--
-- Name: adjust_consultant_commission_v78(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.adjust_consultant_commission_v78(p_billing_adjustment uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_adjustment public.billing_adjustments%rowtype;
  v_reversed public.consultant_commission_adjustments%rowtype;
  v_accrual public.consultant_commission_accruals%rowtype;
  v_consultant public.platform_consultants%rowtype;
  v_prior_basis integer;
  v_prior_commission integer;
  v_basis integer;
  v_commission integer;
  v_id uuid;
  v_inserted uuid;
begin
  select * into v_adjustment
    from public.billing_adjustments
   where id=p_billing_adjustment
     and adjustment_type in ('refund','chargeback','reversal')
   for key share;
  if not found then return null; end if;
  if v_adjustment.adjustment_type='reversal' then
    for v_reversed in
      select commission_adjustment.*
        from public.consultant_commission_adjustments commission_adjustment
        join public.billing_adjustments billing_adjustment
          on billing_adjustment.id=commission_adjustment.billing_adjustment_id
       where commission_adjustment.billing_adjustment_id=v_adjustment.reversal_of
         and commission_adjustment.adjustment_type in ('refund','chargeback')
         and billing_adjustment.business_id=v_adjustment.business_id
         and billing_adjustment.provider_invoice_id
               is not distinct from v_adjustment.provider_invoice_id
       order by commission_adjustment.id
       for key share of commission_adjustment
    loop
      select * into strict v_accrual
        from public.consultant_commission_accruals
       where id=v_reversed.accrual_id;
      select * into strict v_consultant
        from public.platform_consultants where id=v_accrual.consultant_id;
      v_inserted:=null;
      insert into public.consultant_commission_adjustments(
        accrual_id,consultant_id,billing_adjustment_id,reversal_of,
        adjustment_type,basis_adjustment_cents,rate_bps,
        commission_adjustment_cents,settlement_status,occurred_at
      ) values (
        v_accrual.id,v_accrual.consultant_id,v_adjustment.id,v_reversed.id,
        'reversal',-v_reversed.basis_adjustment_cents,v_accrual.rate_bps,
        -v_reversed.commission_adjustment_cents,
        case when v_consultant.active and v_consultant.departed_at is null
             then 'payable' else 'forfeited_to_nestly' end,
        v_adjustment.occurred_at
      )
      on conflict(billing_adjustment_id,accrual_id) do nothing
      returning id into v_inserted;
      v_id:=coalesce(v_id,v_inserted);
    end loop;
    return v_id;
  end if;
  for v_accrual in
    select accrual.*
      from public.consultant_commission_accruals accrual
     where accrual.provider_invoice_id=v_adjustment.provider_invoice_id
     order by accrual.commission_phase
  loop
    select * into strict v_consultant
      from public.platform_consultants where id=v_accrual.consultant_id;
    select coalesce(sum(-basis_adjustment_cents),0),
           coalesce(sum(-commission_adjustment_cents),0)
      into v_prior_basis,v_prior_commission
      from public.consultant_commission_adjustments
     where accrual_id=v_accrual.id;
    v_basis := least(
      greatest(-v_adjustment.subtotal_ex_tax_cents,0),
      greatest(v_accrual.basis_cents-v_prior_basis,0)
    );
    v_commission := least(
      floor(v_basis::numeric*v_accrual.rate_bps::numeric/10000)::integer,
      greatest(v_accrual.commission_cents-v_prior_commission,0)
    );
    if v_basis>0 then
      v_inserted:=null;
      insert into public.consultant_commission_adjustments(
        accrual_id,consultant_id,billing_adjustment_id,adjustment_type,
        basis_adjustment_cents,rate_bps,commission_adjustment_cents,
        settlement_status,occurred_at
      ) values (
        v_accrual.id,v_accrual.consultant_id,v_adjustment.id,
        v_adjustment.adjustment_type,-v_basis,v_accrual.rate_bps,-v_commission,
        case when v_consultant.active and v_consultant.departed_at is null
             then 'payable' else 'forfeited_to_nestly' end,
        v_adjustment.occurred_at
      )
      on conflict(billing_adjustment_id,accrual_id) do nothing
      returning id into v_inserted;
      v_id:=coalesce(v_id,v_inserted);
    end if;
  end loop;
  return v_id;
end
$$;

--
-- Name: append_server_adoption_event_v100(text, uuid, uuid, uuid, text, uuid, text, timestamp with time zone); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.append_server_adoption_event_v100(p_event_name text, p_business uuid, p_branch uuid, p_actor_user uuid, p_source_table text, p_source_id uuid, p_source_operation text, p_occurred_at timestamp with time zone) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_taxonomy public.product_adoption_event_taxonomy_v100%rowtype;
  v_id uuid:=gen_random_uuid();
begin
  select taxonomy.* into v_taxonomy
  from public.product_adoption_event_taxonomy_v100 taxonomy
  where taxonomy.event_name=p_event_name
    and taxonomy.source_authority='server';
  if not found then
    raise exception 'event is not server-authoritative: %',p_event_name
      using errcode='22023';
  end if;
  if p_source_table is null
     or p_source_id is null
     or p_source_operation not in ('INSERT','UPDATE')
     or p_occurred_at is null then
    raise exception 'complete canonical source evidence is required'
      using errcode='22023';
  end if;
  if v_taxonomy.business_scope_required and p_business is null then
    raise exception 'business-scoped event is missing its tenant'
      using errcode='22023';
  end if;
  insert into public.product_adoption_events_v100(
    id,event_name,source_authority,actor_scope,actor_user_id,
    business_id,branch_id,source_table,source_id,source_operation,
    event_context,occurred_at
  ) values(
    v_id,p_event_name,'server',v_taxonomy.actor_scope,p_actor_user,
    p_business,p_branch,p_source_table,p_source_id,p_source_operation,
    '{}'::jsonb,p_occurred_at
  )
  on conflict (source_table,source_id,event_name) do nothing
  returning id into v_id;
  if v_id is null then
    select event_row.id into v_id
    from public.product_adoption_events_v100 event_row
    where event_row.source_table=p_source_table
      and event_row.source_id=p_source_id
      and event_row.event_name=p_event_name;
  end if;
  return v_id;
end
$$;

--
-- Name: apply_booking_consent(uuid, uuid, boolean); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.apply_booking_consent(p_biz uuid, p_client uuid, p_consent boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  -- An unchecked box is not a withdrawal, and an existing identity is not mutable
  -- through an unauthenticated booking submission.
  if p_client is null or coalesce(p_consent, false) is false then
    return;
  end if;
  if current_setting('app.portal_client_created', true) is distinct from p_client::text then
    return;
  end if;

  update public.clients
     set marketing_consent = true
   where id = p_client and business_id = p_biz and marketing_consent is false;
  if found then
    insert into public.consents (business_id, client_id, channel, action, source, actor)
    values (p_biz, p_client, 'marketing', 'granted', 'public_booking_v19_new_client', null);
  end if;
  perform set_config('app.portal_client_created', '', true);
end;
$$;

--
-- Name: apply_bound_booking_consent_v72(uuid, uuid, uuid, boolean); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.apply_bound_booking_consent_v72(p_business uuid, p_client uuid, p_authenticated_user uuid, p_consent boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if coalesce(p_consent, false) is false then
    return;
  end if;
  if p_authenticated_user is null or not exists (
    select 1
      from public.customer_links link
      join public.customer_identities identity
        on identity.id = link.identity_id
       and identity.auth_user_id = link.auth_user_id
     where link.business_id = p_business
       and link.client_id = p_client
       and link.auth_user_id = p_authenticated_user
       and link.state = 'verified'
       and identity.status = 'active'
  ) then
    raise exception 'verified customer link required' using errcode = '42501';
  end if;

  update public.clients
     set marketing_consent = true
   where business_id = p_business
     and id = p_client
     and marketing_consent is false;

  insert into public.consents(
    business_id, client_id, channel, action, source, actor
  ) values (
    p_business, p_client, 'marketing', 'granted',
    'authenticated_public_booking_v72', p_authenticated_user
  );
end
$$;

--
-- Name: assert_billing_json_no_gst_v125(jsonb); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.assert_billing_json_no_gst_v125(p_payload jsonb) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_row jsonb;
begin
  if coalesce((p_payload->>'period_tax_cents')::integer,0)<>0 then
    raise exception 'V125 GST not charged: subscription projection contains tax'
      using errcode='23514';
  end if;
  for v_row in select value from jsonb_array_elements(
    coalesce(p_payload->'invoices','[]'::jsonb)
  ) loop
    if coalesce((v_row->>'tax_cents')::integer,0)<>0 then
      raise exception 'V125 GST not charged: invoice projection contains tax'
        using errcode='23514';
    end if;
  end loop;
  for v_row in select value from jsonb_array_elements(
    coalesce(p_payload->'payment_attempts','[]'::jsonb)
  ) loop
    if coalesce((v_row->>'tax_cents')::integer,0)<>0 then
      raise exception 'V125 GST not charged: payment projection contains tax'
        using errcode='23514';
    end if;
  end loop;
  for v_row in select value from jsonb_array_elements(
    coalesce(p_payload->'adjustments','[]'::jsonb)
  ) loop
    if coalesce((v_row->>'tax_cents')::integer,0)<>0 then
      raise exception 'V125 GST not charged: adjustment projection contains tax'
        using errcode='23514';
    end if;
  end loop;
end
$$;

--
-- Name: assert_no_platform_billing_tax_v125(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.assert_no_platform_billing_tax_v125() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if exists(select 1 from public.subscriptions where coalesce(period_tax_cents,0)<>0)
     or exists(select 1 from public.billing_provider_invoices where tax_cents<>0)
     or exists(select 1 from public.billing_payment_attempts where tax_cents<>0)
     or exists(select 1 from public.billing_adjustments where tax_cents<>0) then
    raise exception 'V125 preflight failed: existing platform billing tax must be reconciled to zero'
      using errcode='23514';
  end if;
end
$$;

--
-- Name: assigned_consultant_v94(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.assigned_consultant_v94(p_business uuid) RETURNS TABLE(consultant_id uuid, user_id uuid, display_name text, hotline_phone text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  select consultant.id,consultant.user_id,consultant.display_name,
    hotline.hotline_phone
  from public.platform_consultants consultant
  left join public.platform_consultant_hotlines_v94 hotline
    on hotline.consultant_id=consultant.id
  where consultant.active
    and exists(
      select 1
      from public.sme_prospects prospect
      where prospect.converted_business_id=p_business
        and prospect.assigned_consultant_id=consultant.id
    )
  order by consultant.created_at,consultant.id
  limit 1
$$;

--
-- Name: attribute_consultant_core_v78(uuid, uuid, uuid, timestamp with time zone, text, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.attribute_consultant_core_v78(p_consultant uuid, p_prospect uuid, p_business uuid, p_onboarding_started_at timestamp with time zone, p_reason text, p_actor uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_existing public.consultant_commission_attributions%rowtype;
  v_result public.consultant_commission_attributions%rowtype;
begin
  if p_consultant is null or p_prospect is null or p_business is null
     or p_onboarding_started_at is null
     or nullif(btrim(p_reason),'') is null or length(p_reason)>1000 then
    raise exception 'complete consultant attribution is required'
      using errcode='22023';
  end if;
  if not exists(
    select 1 from public.platform_consultants consultant
     where consultant.id=p_consultant
       and consultant.active
       and consultant.departed_at is null
  ) then
    raise exception 'active platform consultant was not found'
      using errcode='22023';
  end if;
  if not exists(
    select 1 from public.sme_prospects prospect
     where prospect.id=p_prospect
       and prospect.assigned_consultant_id=p_consultant
       and prospect.converted_business_id=p_business
  ) then
    raise exception 'converted prospect, business and consultant do not agree'
      using errcode='22023';
  end if;
  select * into v_existing
    from public.consultant_commission_attributions
   where prospect_id=p_prospect or business_id=p_business
   for update;
  if found then
    if v_existing.consultant_id<>p_consultant
       or v_existing.prospect_id<>p_prospect
       or v_existing.business_id<>p_business
       or v_existing.onboarding_started_at<>p_onboarding_started_at then
      raise exception 'consultant attribution conflicts with immutable history'
        using errcode='22023';
    end if;
    return to_jsonb(v_existing);
  end if;
  insert into public.consultant_commission_attributions(
    consultant_id,prospect_id,business_id,onboarding_started_at,reason,attributed_by
  ) values (
    p_consultant,p_prospect,p_business,p_onboarding_started_at,btrim(p_reason),p_actor
  ) returning * into v_result;
  insert into public.audit_log(
    business_id,actor,action,entity,entity_id,detail
  ) values (
    p_business,p_actor,'CONSULTANT_COMMISSION_ATTRIBUTED_V78',
    'consultant_commission_attributions',v_result.id,
    jsonb_build_object(
      'consultant_id',p_consultant,'prospect_id',p_prospect,
      'onboarding_started_at',p_onboarding_started_at,'reason',btrim(p_reason)
    )
  );
  return to_jsonb(v_result);
end
$$;

--
-- Name: FUNCTION attribute_consultant_core_v78(p_consultant uuid, p_prospect uuid, p_business uuid, p_onboarding_started_at timestamp with time zone, p_reason text, p_actor uuid); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.attribute_consultant_core_v78(p_consultant uuid, p_prospect uuid, p_business uuid, p_onboarding_started_at timestamp with time zone, p_reason text, p_actor uuid) IS 'Revoked internal attribution core for atomic v79 conversion after the prospect row is locked and converted.';

--
-- Name: audit(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.audit() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  insert into audit_log (business_id, actor, action, entity, entity_id, detail)
  values (coalesce(new.business_id, old.business_id), auth.uid(), tg_op, tg_table_name,
          coalesce(new.id, old.id), to_jsonb(coalesce(new, old)));
  return coalesce(new, old);
end $$;

--
-- Name: backfill_money_back_window_v124(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.backfill_money_back_window_v124() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_invoice public.billing_provider_invoices%rowtype;
  v_legal_version text;
begin
  select onboarding.legal_document_version into v_legal_version
    from public.self_serve_business_onboarding_v130 onboarding
   where onboarding.business_id=new.business_id;
  select invoice.* into v_invoice
    from public.billing_provider_invoices invoice
   where invoice.business_id=new.business_id
     and invoice.provider_subscription_id=new.provider_subscription_id
     and invoice.paid_normalized and invoice.paid_at is not null
   order by invoice.paid_at,invoice.provider_event_created_at,
            invoice.provider_invoice_id
   limit 1;
  if found and v_legal_version>='2026-08-03' then
    insert into public.billing_first_paid_evidence_v144(
      business_id,first_paid_invoice_id,first_paid_at,source_event_id
    ) values(
      new.business_id,v_invoice.provider_invoice_id,v_invoice.paid_at,
      v_invoice.last_event_id
    )
    on conflict(business_id) do update
      set first_paid_invoice_id=excluded.first_paid_invoice_id,
          first_paid_at=excluded.first_paid_at,
          source_event_id=excluded.source_event_id,
          updated_at=now()
      where excluded.first_paid_at
            < billing_first_paid_evidence_v144.first_paid_at;
  elsif found then
    insert into public.billing_money_back_windows_v124(
      business_id,first_paid_invoice_id,first_paid_at,
      money_back_request_until,source_event_id
    ) values(
      new.business_id,v_invoice.provider_invoice_id,v_invoice.paid_at,
      v_invoice.paid_at+interval '30 days',v_invoice.last_event_id
    )
    on conflict(business_id) do update
      set first_paid_invoice_id=excluded.first_paid_invoice_id,
          first_paid_at=excluded.first_paid_at,
          money_back_request_until=excluded.money_back_request_until,
          source_event_id=excluded.source_event_id,
          updated_at=now()
      where excluded.first_paid_at
            < billing_money_back_windows_v124.first_paid_at;
  end if;
  return null;
end
$$;

--
-- Name: bar_bottle_expiry_v278(uuid, uuid, text, date); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.bar_bottle_expiry_v278(p_business uuid, p_client uuid, p_mode text, p_date date) RETURNS timestamp with time zone
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_mode text := lower(btrim(coalesce(p_mode, '')));
  v_next timestamptz;
begin
  if v_mode = 'none' then
    return null;
  end if;
  if v_mode = 'custom' then
    if p_date is null then
      raise exception 'choose the date the bottle is kept until' using errcode = '22023';
    end if;
    v_next := ((p_date + 1)::timestamp) at time zone 'Asia/Singapore';
    if v_next <= now() then
      raise exception 'the keep date must be in the future' using errcode = '22023';
    end if;
    if v_next > now() + make_interval(days => 730) then
      raise exception 'a bottle cannot be kept more than two years' using errcode = '22023';
    end if;
    return v_next;
  end if;
  if v_mode <> 'auto' then
    raise exception 'expiry is automatic, a chosen date, or none' using errcode = '22023';
  end if;
  return now() + make_interval(days => app.bar_keep_days_for_client_v278(p_business, p_client));
end;
$$;

SET default_tablespace = '';

SET default_table_access_method = heap;

--
-- Name: bar_bottles; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.bar_bottles (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    business_id uuid NOT NULL,
    branch_id uuid,
    client_id uuid NOT NULL,
    serial_year integer NOT NULL,
    serial_seq integer NOT NULL,
    serial_code text GENERATED ALWAYS AS (((('PK-'::text || (serial_year)::text) || '-'::text) || lpad((serial_seq)::text, 4, '0'::text))) STORED,
    label text,
    product_id uuid,
    size_ml integer,
    fill_percent integer DEFAULT 100 NOT NULL,
    storage_location_id uuid,
    reentry_limit integer,
    status text DEFAULT 'stored'::text NOT NULL,
    parked_at timestamp with time zone DEFAULT now() NOT NULL,
    expires_at timestamp with time zone,
    sale_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    expiry_mode text DEFAULT 'auto'::text NOT NULL,
    notify_channel text,
    purchased_on date,
    CONSTRAINT bar_bottles_expiry_mode_check CHECK ((expiry_mode = ANY (ARRAY['auto'::text, 'custom'::text, 'none'::text]))),
    CONSTRAINT bar_bottles_expiry_shape_check CHECK (((expiry_mode = 'none'::text) = (expires_at IS NULL))),
    CONSTRAINT bar_bottles_fill_percent_check CHECK (((fill_percent >= 0) AND (fill_percent <= 100))),
    CONSTRAINT bar_bottles_label_check CHECK (((label IS NULL) OR ((length(btrim(label)) >= 1) AND (length(btrim(label)) <= 120)))),
    CONSTRAINT bar_bottles_named CHECK (((product_id IS NOT NULL) OR (NULLIF(btrim(COALESCE(label, ''::text)), ''::text) IS NOT NULL))),
    CONSTRAINT bar_bottles_notify_channel_check CHECK (((notify_channel IS NULL) OR (notify_channel = ANY (ARRAY['whatsapp'::text, 'email'::text, 'none'::text])))),
    CONSTRAINT bar_bottles_reentry_limit_check CHECK (((reentry_limit IS NULL) OR ((reentry_limit >= 1) AND (reentry_limit <= 50)))),
    CONSTRAINT bar_bottles_serial_seq_check CHECK ((serial_seq > 0)),
    CONSTRAINT bar_bottles_serial_year_check CHECK (((serial_year >= 2000) AND (serial_year <= 2999))),
    CONSTRAINT bar_bottles_size_ml_check CHECK (((size_ml IS NULL) OR ((size_ml >= 1) AND (size_ml <= 20000)))),
    CONSTRAINT bar_bottles_status_check CHECK ((status = ANY (ARRAY['stored'::text, 'called'::text, 'at_table'::text, 'retrieved'::text, 'finished'::text, 'expired'::text, 'transferred'::text, 'removed'::text])))
);

--
-- Name: TABLE bar_bottles; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.bar_bottles IS 'One physical parked bottle. Property, not stored value: nothing here touches the credit or points ledgers - only the purchase sale does, through the ordinary v10 policy engine.';

--
-- Name: COLUMN bar_bottles.reentry_limit; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.bar_bottles.reentry_limit IS 'RETIRED at V279 (owner: "what is the purpose of re-entry? please remove it"). The column is kept because bottles parked before V279 carry real values and a custody record is not edited to tidy a form. Nothing reads it and nothing writes it any more: both park functions accept their p_reentry_limit argument and store null.';

--
-- Name: COLUMN bar_bottles.expiry_mode; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.bar_bottles.expiry_mode IS 'V278: auto = the customer''s tier keep-days (else the business default) at park time; custom = an agreed date; none = kept indefinitely, expires_at null.';

--
-- Name: COLUMN bar_bottles.notify_channel; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.bar_bottles.notify_channel IS 'V278 stored per-park reminder preference. WhatsApp and email SENDING are deferred platform-wide; this records what the customer asked for so the later sweep has an answer.';

--
-- Name: COLUMN bar_bottles.purchased_on; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.bar_bottles.purchased_on IS 'V278 the date the bottle was bought, when it differs from the date it was parked.';

--
-- Name: bar_bottle_json_v275(public.bar_bottles); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.bar_bottle_json_v275(p_bottle public.bar_bottles) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $_$
  select jsonb_build_object(
    'id', ($1).id,
    'serial_code', ($1).serial_code,
    'label', coalesce(
      nullif(btrim(coalesce(($1).label, '')), ''),
      (select product.name from public.products product where product.id = ($1).product_id)),
    'product_id', ($1).product_id,
    'size_ml', ($1).size_ml,
    'fill_percent', ($1).fill_percent,
    'status', ($1).status,
    'storage_location_id', ($1).storage_location_id,
    'storage_location_name', (
      select location.name from public.bar_storage_locations location
       where location.id = ($1).storage_location_id),
    'parked_at', ($1).parked_at,
    'expires_at', ($1).expires_at,
    'expiry_mode', ($1).expiry_mode,
    'notify_channel', ($1).notify_channel,
    'purchased_on', ($1).purchased_on,
    'tier_name', app.bar_tier_name_v278(($1).business_id, ($1).client_id),
    'days_left', case when ($1).expires_at is null then null else (
      (($1).expires_at at time zone 'Asia/Singapore')::date
      - (now() at time zone 'Asia/Singapore')::date
    ) end,
    'branch_id', ($1).branch_id,
    'client_id', ($1).client_id,
    'sale_id', ($1).sale_id
  )
$_$;

--
-- Name: bar_bottle_replayed_v275(uuid, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.bar_bottle_replayed_v275(p_business uuid, p_idempotency_key text) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  select event.bottle_id
    from public.bar_bottle_events event
   where event.business_id = p_business
     and event.idem_key = nullif(btrim(coalesce(p_idempotency_key, '')), '')
   limit 1
$$;

--
-- Name: bar_capacity_guard_v279(uuid, integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.bar_capacity_guard_v279(p_business uuid, p_wanted integer) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_capacity integer;
  v_used integer;
  v_wanted integer := greatest(coalesce(p_wanted, 1), 1);
begin
  v_capacity := app.bar_storage_capacity_v279(p_business);
  v_used := app.bar_in_storage_count_v279(p_business);
  if v_used + v_wanted > v_capacity then
    raise exception 'Storage is full — % of % in use', v_used, v_capacity using errcode = '22023';
  end if;
end;
$$;

--
-- Name: bar_expiry_reminder_days_v282(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.bar_expiry_reminder_days_v282(p_business uuid) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  select coalesce(
    (select setting.expiry_reminder_days
       from public.bar_bottle_settings setting
      where setting.business_id = p_business),
    7)
$$;

--
-- Name: bar_in_storage_count_v279(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.bar_in_storage_count_v279(p_business uuid) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  select count(*)::integer from public.bar_bottles bottle
   where bottle.business_id = p_business
     and bottle.status in ('stored', 'called', 'at_table')
$$;

--
-- Name: bar_keep_days_for_client_v278(uuid, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.bar_keep_days_for_client_v278(p_business uuid, p_client uuid) RETURNS integer
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_tier_id uuid;
  v_days integer;
begin
  -- Only the tier IDENTITY is needed, and taking it as a scalar keeps this resolver out of the
  -- business of holding a whole loyalty_tiers row it would then have to null out on failure.
  begin
    select tier.id into v_tier_id from app.loyalty_tier_for(p_business, p_client) tier;
  exception when others then
    v_tier_id := null;
  end;
  if v_tier_id is not null then
    select keep.keep_days into v_days
      from public.bar_tier_keep_days_v278 keep
     where keep.business_id = p_business and keep.tier_id = v_tier_id;
  end if;
  return coalesce(v_days, app.bar_keep_days_v275(p_business));
end;
$$;

--
-- Name: bar_keep_days_v275(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.bar_keep_days_v275(p_business uuid) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  select coalesce(
    (select setting.keep_days from public.bar_bottle_settings setting
      where setting.business_id = p_business),
    30)
$$;

--
-- Name: bar_status_transition_allowed_v278(text, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.bar_status_transition_allowed_v278(p_from text, p_to text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $_$
  select case
    when $1 = $2 then true
    when $1 in ('stored', 'called', 'at_table')
      and $2 in ('stored', 'called', 'at_table', 'retrieved') then true
    when $1 = 'retrieved' and $2 = 'stored' then true
    else false
  end
$_$;

--
-- Name: bar_status_transition_allowed_v279(text, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.bar_status_transition_allowed_v279(p_from text, p_to text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $_$
  select case
    when $1 in ('stored', 'called', 'at_table')
      and $2 in ('stored', 'called', 'at_table', 'retrieved') then true
    else false
  end
$_$;

--
-- Name: bar_storage_capacity_v279(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.bar_storage_capacity_v279(p_business uuid) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  select coalesce(
    (select setting.storage_capacity from public.bar_bottle_settings setting
      where setting.business_id = p_business),
    500)
$$;

--
-- Name: bar_tier_name_v278(uuid, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.bar_tier_name_v278(p_business uuid, p_client uuid) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_tier public.loyalty_tiers%rowtype;
begin
  if p_business is null or p_client is null then
    return null;
  end if;
  if not exists (select 1 from public.loyalty_tiers tier where tier.business_id = p_business) then
    return null;
  end if;
  select * into v_tier from app.loyalty_tier_for(p_business, p_client);
  return nullif(btrim(coalesce(v_tier.name, '')), '');
exception when others then
  return null;
end;
$$;

--
-- Name: begin_sales_backfill(text, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.begin_sales_backfill(p_migration text, p_reason text) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if p_migration is null or length(btrim(p_migration)) < 3 then
    raise exception 'begin_sales_backfill requires the migration name that is opening the window';
  end if;
  if p_reason is null or length(btrim(p_reason)) < 10 then
    raise exception 'begin_sales_backfill requires a reason of at least 10 characters';
  end if;
  insert into audit_log (business_id, actor, action, entity, entity_id, detail)
  values (null, auth.uid(), 'SALES_BACKFILL_WINDOW_OPEN', 'sales', null,
          jsonb_build_object('migration', btrim(p_migration),
                             'reason',    btrim(p_reason),
                             'db_user',   current_user,
                             'opened_at', now(),
                             'scope', 'columns added after v10.1 only; all v10.1-era columns '
                                      'incl. the policy snapshot remain frozen'));
  perform set_config('app.sales_backfill', btrim(p_migration), true);   -- true = txn-local
end $$;

