--
-- Name: billing_provider_invoices; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.billing_provider_invoices (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    business_id uuid NOT NULL,
    provider_customer_id text NOT NULL,
    provider_subscription_id text,
    provider_invoice_id text NOT NULL,
    provider_payment_intent_id text,
    number text,
    currency text NOT NULL,
    collection_method text,
    status text NOT NULL,
    paid_normalized boolean DEFAULT false NOT NULL,
    subtotal_ex_tax_cents integer NOT NULL,
    tax_cents integer NOT NULL,
    total_cents integer NOT NULL,
    amount_due_cents integer NOT NULL,
    amount_paid_cents integer NOT NULL,
    amount_remaining_cents integer NOT NULL,
    net_cash_ex_tax_cents integer DEFAULT 0 NOT NULL,
    period_start timestamp with time zone,
    period_end timestamp with time zone,
    due_at timestamp with time zone,
    next_payment_attempt_at timestamp with time zone,
    paid_at timestamp with time zone,
    finalized_at timestamp with time zone,
    voided_at timestamp with time zone,
    marked_uncollectible_at timestamp with time zone,
    livemode boolean NOT NULL,
    provider_event_created_at timestamp with time zone NOT NULL,
    provider_event_rank smallint NOT NULL,
    last_event_id text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    hosted_invoice_url text,
    invoice_pdf_url text,
    provider_receipt_url text,
    CONSTRAINT billing_provider_invoices_amount_due_cents_check CHECK ((amount_due_cents >= 0)),
    CONSTRAINT billing_provider_invoices_amount_paid_cents_check CHECK ((amount_paid_cents >= 0)),
    CONSTRAINT billing_provider_invoices_amount_remaining_cents_check CHECK ((amount_remaining_cents >= 0)),
    CONSTRAINT billing_provider_invoices_currency_check CHECK ((currency ~ '^[A-Z]{3}$'::text)),
    CONSTRAINT billing_provider_invoices_hosted_url_v146_check CHECK (((hosted_invoice_url IS NULL) OR (hosted_invoice_url ~ '^https://([a-z0-9-]+\.)*stripe\.com/[^[:space:]]+$'::text))),
    CONSTRAINT billing_provider_invoices_net_cash_ex_tax_cents_check CHECK ((net_cash_ex_tax_cents >= 0)),
    CONSTRAINT billing_provider_invoices_no_gst_v125_check CHECK ((tax_cents = 0)),
    CONSTRAINT billing_provider_invoices_paid_truth_check CHECK (((paid_normalized AND (status = 'paid'::text) AND (paid_at IS NOT NULL)) OR (NOT paid_normalized))),
    CONSTRAINT billing_provider_invoices_pdf_url_v146_check CHECK (((invoice_pdf_url IS NULL) OR (invoice_pdf_url ~ '^https://([a-z0-9-]+\.)*stripe\.com/[^[:space:]]+$'::text))),
    CONSTRAINT billing_provider_invoices_receipt_url_v146_check CHECK (((provider_receipt_url IS NULL) OR (provider_receipt_url ~ '^https://([a-z0-9-]+\.)*stripe\.com/[^[:space:]]+$'::text))),
    CONSTRAINT billing_provider_invoices_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'open'::text, 'paid'::text, 'void'::text, 'uncollectible'::text]))),
    CONSTRAINT billing_provider_invoices_subtotal_ex_tax_cents_check CHECK ((subtotal_ex_tax_cents >= 0)),
    CONSTRAINT billing_provider_invoices_tax_cents_check CHECK ((tax_cents >= 0)),
    CONSTRAINT billing_provider_invoices_total_cents_check CHECK ((total_cents >= 0)),
    CONSTRAINT billing_provider_invoices_total_check CHECK ((total_cents = (subtotal_ex_tax_cents + tax_cents)))
);

