--
-- Name: billing_price_confirmation_v77(text, text, text, text, integer, integer, integer, text, timestamp with time zone); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.billing_price_confirmation_v77(p_currency text, p_cadence text, p_provider_base_price_id text, p_provider_seat_price_id text, p_base_amount_cents integer, p_per_seat_amount_cents integer, p_included_seats integer, p_tax_behavior text, p_effective_from timestamp with time zone) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
  select encode(extensions.digest(convert_to(
    upper(p_currency)||E'\n'||p_cadence||E'\n'
    ||p_provider_base_price_id||E'\n'||p_provider_seat_price_id||E'\n'
    ||p_base_amount_cents::text||E'\n'||p_per_seat_amount_cents::text||E'\n'
    ||p_included_seats::text||E'\n'||p_tax_behavior||E'\n'
    ||to_char(p_effective_from at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US'),
    'utf8'
  ),'sha256'),'hex')
$$;

--
-- Name: booking_decision_result_v73(uuid, uuid, text, text, boolean); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.booking_decision_result_v73(p_business uuid, p_request uuid, p_decision text, p_outcome text, p_replayed boolean) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  select jsonb_build_object(
    'request_id', request.id,
    'requested_decision', p_decision,
    'outcome', p_outcome,
    'actual_status', request.status,
    'replayed', p_replayed
  ) || jsonb_strip_nulls(jsonb_build_object(
    'appointment_id', appointment.id,
    'branch_id', appointment.branch_id,
    'starts_at', appointment.starts_at,
    'ends_at', appointment.ends_at,
    'waitlist_id', waitlist_row.id,
    'waitlist_status', waitlist_row.status
  ))
    from public.booking_requests request
    left join public.appointments appointment
      on appointment.id = request.appointment_id
     and appointment.business_id = request.business_id
    left join public.waitlist waitlist_row
      on waitlist_row.booking_request_id = request.id
     and waitlist_row.business_id = request.business_id
   where request.id = p_request
     and request.business_id = p_business
$$;

