--
-- Name: business_module_enabled_at_v117(uuid, text, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.business_module_enabled_at_v117(p_business uuid, p_module text, p_branch uuid DEFAULT NULL::uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  select app.business_workspace_open_v94(p_business)
    and case
      when p_branch is not null then
        exists(
          select 1
          from public.branches branch
          cross join lateral app.effective_platform_module_mode_v94(
            p_business,branch.id,p_module
          ) resolved
          where branch.id=p_branch
            and branch.business_id=p_business
            and branch.active
            and resolved.mode in ('r','rw')
        )
      else
        case when exists(
          select 1
          from public.branches branch
          where branch.business_id=p_business
            and branch.active
        ) then exists(
          select 1
          from public.branches branch
          cross join lateral app.effective_platform_module_mode_v94(
            p_business,branch.id,p_module
          ) resolved
          where branch.business_id=p_business
            and branch.active
            and resolved.mode in ('r','rw')
        ) else exists(
          select 1
          from app.effective_platform_module_mode_v94(
            p_business,null,p_module
          ) resolved
          where resolved.mode in ('r','rw')
        )
        end
    end
$$;

