--
-- Name: business_programmes_active_v314(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.business_programmes_active_v314(p_business uuid) RETURNS TABLE(kind text, running boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  select programme.programme_kind,
         coalesce((select spine.active
                     from public.business_programmes spine
                    where spine.business_id = p_business
                      and spine.kind = programme.programme_kind), false)
    from (values (1,'points'),(2,'tiers'),(3,'stamps'),(4,'referral'))
           as programme(sort_order, programme_kind)
   order by programme.sort_order
$$;

--
-- Name: FUNCTION business_programmes_active_v314(p_business uuid); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.business_programmes_active_v314(p_business uuid) IS 'v314 W6i1: the four programme flags read from the SPINE — the post-inversion successor to app.business_programmes_v307. Always four rows in the pinned order, all false for an unknown business. SECURITY DEFINER so a definer caller gets tenant truth rather than an RLS-shaped answer; browsers read public.business_programmes directly under their own SELECT policy.';

--
-- Name: business_programmes_sync_trigger_v308(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.business_programmes_sync_trigger_v308() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_column text := coalesce(tg_argv[0], 'business_id');
  v_row jsonb;
  v_new uuid;
  v_old uuid;
begin
  -- OLD and NEW are read only inside the branch that owns them: an unassigned record variable
  -- (OLD on INSERT, NEW on DELETE) cannot be passed to to_jsonb without raising. Each branch also
  -- fails loudly rather than silently syncing nothing if this trigger is ever attached to a table
  -- whose tenant key is spelled differently.
  if tg_op in ('INSERT','UPDATE') then
    v_row := to_jsonb(new);
    if not (v_row ? v_column) then
      raise exception 'v308 sync trigger on %.% has no column %',
        tg_table_schema, tg_table_name, v_column using errcode = '42703';
    end if;
    v_new := (v_row ->> v_column)::uuid;
  end if;
  if tg_op in ('UPDATE','DELETE') then
    v_row := to_jsonb(old);
    if not (v_row ? v_column) then
      raise exception 'v308 sync trigger on %.% has no column %',
        tg_table_schema, tg_table_name, v_column using errcode = '42703';
    end if;
    v_old := (v_row ->> v_column)::uuid;
  end if;

  if v_new is not null then
    perform app.sync_business_programmes_v308(v_new);
  end if;
  -- An UPDATE that moves a config row between tenants has to leave BOTH spines correct.
  if v_old is not null and v_old is distinct from v_new then
    perform app.sync_business_programmes_v308(v_old);
  end if;

  return null;
end
$$;

--
-- Name: FUNCTION business_programmes_sync_trigger_v308(); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.business_programmes_sync_trigger_v308() IS 'v308 W2 trigger shim, RETIRED AT v314 with the four triggers that called it. Kept installed so the rollback is `create trigger`, not `create function`.';

--
-- Name: business_programmes_v307(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.business_programmes_v307(p_business uuid) RETURNS TABLE(kind text, running boolean)
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  with business_mode as (
    select (
      select business.points_mode
        from public.businesses business
       where business.id = p_business
    ) as points_mode
  ),
  programme_state as (
    select
      exists(
        select 1
          from public.loyalty_programs program
         where program.business_id = p_business
           and program.active
           and program.loyalty_model in ('classic','points_tiers')
      )
      and coalesce(business_mode.points_mode,'redeem') <> 'tiers'
        as points_running,
      exists(
        select 1
          from public.loyalty_programs program
         where program.business_id = p_business
           and program.active
      )
      and coalesce(business_mode.points_mode,'tiers') in ('tiers','both')
      and exists(
        select 1
          from public.loyalty_tiers tier
         where tier.business_id = p_business
           and tier.deleted_at is null
      )
        as tiers_running,
      exists(
        select 1
          from public.loyalty_programs program
         where program.business_id = p_business
           and program.active
           and program.loyalty_model = 'stamps'
      ) as stamps_running,
      exists(
        select 1
          from public.referral_programs referral_program
         where referral_program.business_id = p_business
           and referral_program.enabled
      ) as referral_running
    from business_mode
  )
  select
    programme.programme_kind,
    case programme.programme_kind
      when 'points' then programme_state.points_running
      when 'tiers' then programme_state.tiers_running
      when 'stamps' then programme_state.stamps_running
      when 'referral' then programme_state.referral_running
    end
  from programme_state
  cross join (values
    (1,'points'),
    (2,'tiers'),
    (3,'stamps'),
    (4,'referral')
  ) as programme(sort_order, programme_kind)
  order by programme.sort_order
$$;

--
-- Name: FUNCTION business_programmes_v307(p_business uuid); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.business_programmes_v307(p_business uuid) IS 'v307 W1 read model — THE PRE-INVERSION ORACLE. It derives the four flags from the legacy columns and was the spine''s backfill source and mirror through W1-W5. As of v314 it is NO LONGER TRUTH: the spine is, and a firm running points and stamps together has no loyalty_model representation for this function to produce. It keeps exactly one live job — SEEDING a brand-new tenant''s four rows (app.seed_business_programmes_v314) and self-healing a firm that lacks them — plus its role as the reference every W1-W5 acceptance document was measured against. app.detect_spine_legacy_divergence_v314 reports where the two now differ; that report is expected to be non-empty and is never an assertion.';

--
-- Name: business_sector_modules_guard_v75(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.business_sector_modules_guard_v75() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if (
       new.enabled_modules is distinct from old.enabled_modules
       or new.industry is distinct from old.industry
     )
     and exists (
       select 1 from public.business_sector_assignments assignment
        where assignment.business_id = new.id
     )
     and nullif(current_setting('app.sector_entitlement_sync', true), '') is distinct from new.id::text
  then
    raise exception 'business modules are fixed by the assigned sector entitlement'
      using errcode = '42501';
  end if;
  return new;
end
$$;

--
-- Name: business_workspace_open_v94(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.business_workspace_open_v94(p_business uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  select coalesce((
    select control.approval_status='approved'
      and not lifecycle.workspace_paused
    from public.business_workspace_controls_v94 control
    join public.business_subscription_lifecycle_v94 lifecycle
      on lifecycle.business_id=control.business_id
    where control.business_id=p_business
  ),false)
$$;

--
-- Name: c42_evidence_immutable_guard(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.c42_evidence_immutable_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  raise exception '% is append-only evidence', tg_table_name using errcode = '23000';
end;
$$;

--
-- Name: c42_profile_guard(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.c42_profile_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_identity text := nullif(current_setting('app.c42_profile_identity', true), '');
begin
  if tg_op = 'DELETE' then
    raise exception 'customer profiles are retained for controlled recovery' using errcode = '23000';
  end if;
  if v_identity is distinct from new.identity_id::text then
    raise exception 'customer profiles may only be written through a self-derived C42 RPC' using errcode = '42501';
  end if;
  if new.birth_date > (timezone('Asia/Singapore', now()))::date then
    raise exception 'birth date cannot be in the future' using errcode = '22023';
  end if;
  if tg_op = 'UPDATE' then
    if (new.identity_id, new.auth_user_id, new.birth_date, new.created_at)
        is distinct from (old.identity_id, old.auth_user_id, old.birth_date, old.created_at) then
      raise exception 'customer identity mapping and birth date require controlled recovery' using errcode = '23000';
    end if;
    new.updated_at := now();
  end if;
  return new;
end;
$$;

--
-- Name: c44_actionable_wallet_card(uuid, uuid, text, text, text, text, text[], timestamp with time zone); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.c44_actionable_wallet_card(p_business_id uuid, p_client_id uuid, p_business_slug text, p_business_name text, p_business_industry text, p_business_currency text, p_enabled_modules text[], p_as_of timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_base jsonb; v_context record; v_birthday jsonb; v_base_band integer; v_birthday_band integer;
  v_base_deadline timestamptz; v_birthday_deadline timestamptz; v_base_units integer;
begin
  select app.c45_base_actionable_wallet_card(p_business_id,p_client_id,p_business_slug,p_business_name,p_business_industry,p_business_currency,p_enabled_modules,p_as_of) into v_base;
  if not app.platform_feature_enabled('customer_birthday_benefits') then return v_base || jsonb_build_object('birthday_benefit',null); end if;
  select ci.id,cp.birth_date into v_context
    from public.customer_identities ci
    join public.customer_links cl on cl.identity_id=ci.id and cl.business_id=p_business_id and cl.client_id=p_client_id and cl.auth_user_id=auth.uid() and cl.state='verified'
    join public.customer_profiles cp on cp.identity_id=ci.id and cp.auth_user_id=auth.uid()
   where ci.auth_user_id=auth.uid() and ci.status='active' limit 1;
  if not found then return v_base || jsonb_build_object('birthday_benefit',null); end if;
  select app.c45_customer_birthday_benefit_for_context(p_business_id,p_client_id,v_context.id,v_context.birth_date,p_as_of) into v_birthday;
  if v_birthday is null then return v_base || jsonb_build_object('birthday_benefit',null); end if;
  -- Redeemed/expired entries remain visible as history, but never outrank an
  -- actionable wallet card. Only the customer-safe CTA states can rank.
  if v_birthday->>'status' not in ('ready_to_activate','available')
     or coalesce(v_birthday->>'cta','') not in ('activate','show_at_counter')
     or nullif(v_birthday#>>'{validity,available_until}','') is null
     or (v_birthday#>>'{validity,available_until}')::timestamptz <= p_as_of then
    return v_base || jsonb_build_object('birthday_benefit',v_birthday);
  end if;
  v_base_band:=coalesce((v_base#>>'{action,sort_band}')::integer,6);
  v_base_deadline:=nullif(v_base#>>'{action,deadline_at}','')::timestamptz;
  v_base_units:=coalesce((v_base#>>'{action,sort_units}')::integer,0);
  v_birthday_deadline:=(v_birthday#>>'{validity,available_until}')::timestamptz;
  v_birthday_band:=case when (v_birthday#>>'{validity,available_until}')::timestamptz<=p_as_of+interval '7 days' then 1 else 2 end;
  if v_birthday_band < v_base_band
     or (v_birthday_band = v_base_band and (v_base_deadline is null or v_birthday_deadline < v_base_deadline))
     or (v_birthday_band = v_base_band and v_birthday_deadline = v_base_deadline and 0 < v_base_units) then
    v_base:=v_base || jsonb_build_object('action',jsonb_build_object(
      'reason',case when v_birthday_band=1 then 'birthday_benefit_expiring_within_7_days' else 'birthday_benefit_available' end,
      'deadline_at',v_birthday#>>'{validity,available_until}',
      'sort_band',v_birthday_band,'sort_units',0
    ));
  end if;
  return v_base || jsonb_build_object('birthday_benefit',v_birthday);
end $$;

--
-- Name: c45_append_only_guard(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.c45_append_only_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  raise exception '% is append-only evidence', tg_table_name using errcode='23000';
end $$;

--
-- Name: c45_base_actionable_wallet_card(uuid, uuid, text, text, text, text, text[], timestamp with time zone); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.c45_base_actionable_wallet_card(p_business_id uuid, p_client_id uuid, p_business_slug text, p_business_name text, p_business_industry text, p_business_currency text, p_enabled_modules text[], p_as_of timestamp with time zone) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  with program as (
    select
      'loyalty' = any(p_enabled_modules) and (coalesce(lp.active, false) and engine.running) as enabled,
      case when 'loyalty' = any(p_enabled_modules) and (coalesce(lp.active, false) and engine.running)
        then case when lp.loyalty_model = 'stamps' then 'stamps' else 'points' end
      end as unit,
      case when 'loyalty' = any(p_enabled_modules) and (coalesce(lp.active, false) and engine.running)
        then lp.loyalty_model
      end as model,
      case when 'loyalty' = any(p_enabled_modules) and (coalesce(lp.active, false) and engine.running)
        then coalesce(lp.expiry_mode, 'none')
        else 'none'
      end as expiry_mode
    from (select 1) scope
    left join public.loyalty_programs lp on lp.business_id = p_business_id
    -- V371: `lp.active` alone is not "is this programme running". The owner's on/off control
    -- (set_programmes_v314) moves the business_programmes spine and never touches lp.active, so a
    -- switched-off programme kept answering enabled=true here while the business page said "not
    -- running". The spine is the authority; app.programme_running_v371 is the single reader of it.
    cross join lateral (
      select app.programme_running_v371(p_business_id, 'points')
          or app.programme_running_v371(p_business_id, 'stamps') as running
    ) engine
  ), ledger_balance as (
    select greatest(coalesce(sum(pl.points), 0), 0)::integer as units
      from public.points_ledger pl
     where pl.business_id = p_business_id
       and pl.client_id = p_client_id
       and pl.programme_id is not distinct from app.live_balance_programme_v381(p_business_id) /* v384_live_customer_programmes_actionable */
  -- A ledger balance can lag or lead batch rows during a repair or reversal.
  -- The customer projection therefore allocates only the proven balance over
  -- unexpired batches in the same FEFO order used for redemption. Expiry
  -- bands and next_expiry_at are derived from that capped allocation, never
  -- from raw batches that the customer cannot currently spend.
  ), unexpired_batches as (
    select
      pb.id,
      pb.remaining,
      pb.earned_at,
      pb.expires_at,
      sum(pb.remaining) over (
        order by pb.expires_at nulls last, pb.earned_at, pb.id
        rows between unbounded preceding and current row
      )::bigint as cumulative_remaining
      from public.points_batches pb
     where pb.business_id = p_business_id
       and pb.client_id = p_client_id
       and pb.remaining > 0
       and pb.programme_id is not distinct from app.live_balance_programme_v381(p_business_id)
       and (pb.expires_at is null or pb.expires_at > p_as_of)
  ), batch_balance as (
    select coalesce(sum(remaining), 0)::integer as unexpired_units
      from unexpired_batches
  ), loyalty_balance as (
    select
      program.enabled,
      program.model,
      program.unit,
      program.expiry_mode,
      case when program.enabled
        then greatest(least(ledger_balance.units, batch_balance.unexpired_units), 0)
        else 0 end as balance
      from program cross join ledger_balance cross join batch_balance
  ), actionable_batches as (
    select
      ub.expires_at,
      least(
        ub.remaining::bigint,
        greatest(
          loyalty_balance.balance::bigint
            - (ub.cumulative_remaining - ub.remaining::bigint),
          0
        )
      )::integer as actionable_remaining
      from unexpired_batches ub
      cross join loyalty_balance
     where loyalty_balance.enabled
       and loyalty_balance.balance > 0
       and ub.cumulative_remaining - ub.remaining::bigint < loyalty_balance.balance::bigint
  ), expiry_balance as (
    select
      coalesce(sum(actionable_remaining) filter (
        where expires_at > p_as_of
          and expires_at <= p_as_of + interval '7 days'
      ), 0)::integer as expiring_7_units,
      coalesce(sum(actionable_remaining) filter (
        where expires_at > p_as_of
          and expires_at <= p_as_of + interval '30 days'
      ), 0)::integer as expiring_30_units,
      min(expires_at) filter (
        where actionable_remaining > 0
          and expires_at > p_as_of
          and expires_at <= p_as_of + interval '30 days'
      ) as next_expiry_at
      from actionable_batches
  ), loyalty as (
    select
      loyalty_balance.enabled,
      loyalty_balance.model,
      loyalty_balance.unit,
      loyalty_balance.expiry_mode,
      loyalty_balance.balance,
      case when loyalty_balance.enabled and loyalty_balance.expiry_mode <> 'none'
        then expiry_balance.expiring_7_units else 0 end as expiring_7_units,
      case when loyalty_balance.enabled and loyalty_balance.expiry_mode <> 'none'
        then expiry_balance.expiring_30_units else 0 end as expiring_units,
      case when loyalty_balance.enabled and loyalty_balance.expiry_mode <> 'none'
             and expiry_balance.expiring_30_units > 0
        then expiry_balance.next_expiry_at else null end as next_expiry_at
      from loyalty_balance cross join expiry_balance
  ), credit as (
    select greatest(coalesce(sum(cl.amount_cents), 0), 0)::integer as balance_cents
      from public.credit_ledger cl
     where cl.business_id = p_business_id
       and cl.client_id = p_client_id
  ), packages as (
    select coalesce(sum(cp.remaining), 0)::integer as sessions_remaining
      from public.client_packages cp
     where cp.business_id = p_business_id
       and cp.client_id = p_client_id
       and cp.status = 'active'
       and cp.remaining > 0
  ), reward_candidate as (
    select
      rv.customer_name as name,
      rv.cost_points::integer as cost_units,
      greatest(rv.cost_points - loyalty.balance, 0)::integer as remaining_units,
      loyalty.balance >= rv.cost_points as available_now
      from public.businesses b
      join public.loyalty_reward_versions rv
        on rv.business_id = b.id
       and rv.config_version_id = b.active_config_version_id
       and rv.active
       -- V371: a gift the owner paused stays in the published version snapshot, so the wallet
       -- advertised it as `available_now` while redeem_reward_core refused the claim. The pause
       -- lives on the live row; honour it here so the promise matches what can actually be given.
       and not exists (
         select 1 from public.loyalty_rewards live_reward
          where live_reward.id = rv.reward_id
            and live_reward.business_id = rv.business_id
            and (
              live_reward.paused
              -- V372: a gift belongs to ONE programme and is priced in that programme's unit, so it
              -- must not be offered while that programme is switched off. Cubbly was the live case:
              -- stamps off and points on, with a 2-STAMP gift still catalogued and reported
              -- `available_now` against a 50-POINT balance — two different units, for a programme
              -- that is not running. A reward with no programme is left alone: fail open, never
              -- hide a gift because a link is missing.
              or exists (
                select 1 from public.business_programmes spine
                 where spine.id = live_reward.programme_id
                   and not spine.active
              )
            )
       )
      cross join loyalty
      left join lateral (
        select count(*)::integer as used_count
          from public.loyalty_redemptions lr
         where lr.business_id = p_business_id
           and lr.client_id = p_client_id
           and lr.reward_id = rv.reward_id
      ) usage on true
     where b.id = p_business_id
       and loyalty.enabled
       and (rv.claim_available_from is null or rv.claim_available_from <= p_as_of)
       and (rv.claim_available_until is null or rv.claim_available_until > p_as_of)
       and (rv.usage_limit is null or usage.used_count < rv.usage_limit)
     order by greatest(rv.cost_points - loyalty.balance, 0), rv.sort,
              lower(rv.customer_name), rv.reward_id
     limit 1
  ), retention_windows as (
    select
      rv.program_id,
      rv.goal_visits,
      rv.sort,
      rv.name,
      rv.customer_description,
      rv.starts_on::timestamptz
        + make_interval(days => (
          floor(extract(epoch from (p_as_of - rv.starts_on::timestamptz))
            / (rv.period_days * 86400))::integer * rv.period_days
        )) as period_start,
      rv.starts_on::timestamptz
        + make_interval(days => (
          (floor(extract(epoch from (p_as_of - rv.starts_on::timestamptz))
            / (rv.period_days * 86400))::integer + 1) * rv.period_days
        )) as period_end
      from public.businesses b
      join public.retention_program_versions rv
        on rv.business_id = b.id
       and rv.config_version_id = b.active_config_version_id
       and rv.active
      join public.retention_programs prog
        on prog.id = rv.program_id
       and prog.business_id = rv.business_id
       and prog.deleted_at is null
       -- V371: same class as the paused gift above — the live row could be switched off while its
       -- published version stayed active, leaving the visit goal on the customer's card.
       and prog.active
     where b.id = p_business_id
       and p_as_of >= rv.starts_on::timestamptz
  ), visit_candidate as (
    select
      w.program_id,
      w.period_end,
      w.goal_visits,
      w.customer_description,
      greatest(w.goal_visits - count(s.id)::integer, 0)::integer as visits_remaining
      from retention_windows w
      left join public.sales s
        on s.business_id = p_business_id
       and s.client_id = p_client_id
       and s.counts_as_visit
       and s.reversal_of is null
       and s.occurred_at >= w.period_start
       and s.occurred_at < w.period_end
       and not exists (
         select 1 from public.sales reversal
          where reversal.business_id = s.business_id and reversal.reversal_of = s.id
       )
     group by w.program_id, w.goal_visits, w.period_end, w.sort, w.name, w.customer_description
     order by greatest(w.goal_visits - count(s.id)::integer, 0),
              w.period_end, w.sort, lower(w.name), w.program_id
     limit 1
  ), action as (
    select
      case
        when loyalty.expiring_7_units > 0 then 'expiring_within_7_days'
        when coalesce(reward_candidate.available_now, false) then 'reward_available'
        when loyalty.expiring_units > 0 then 'expiring_within_30_days'
        when visit_candidate.visits_remaining = 1 then 'one_qualifying_visit_remaining'
        when reward_candidate.name is not null then 'reward_progress'
        else 'none'
      end as reason,
      case
        when loyalty.expiring_7_units > 0 then loyalty.next_expiry_at
        when loyalty.expiring_units > 0 then loyalty.next_expiry_at
        when visit_candidate.visits_remaining = 1 then visit_candidate.period_end
        else null
      end as deadline_at,
      case
        when loyalty.expiring_7_units > 0 then 1
        when coalesce(reward_candidate.available_now, false) then 2
        when loyalty.expiring_units > 0 then 3
        when visit_candidate.visits_remaining = 1 then 4
        when reward_candidate.name is not null then 5
        else 6
      end as sort_band,
      case when reward_candidate.name is not null
        then reward_candidate.remaining_units else 0 end as sort_units
      from loyalty
      left join reward_candidate on true
      left join visit_candidate on true
  )
  select jsonb_build_object(
    'business', jsonb_build_object(
      'slug', p_business_slug,
      'name', p_business_name,
      'industry', p_business_industry,
      'currency', p_business_currency
    ),
    'loyalty', jsonb_build_object(
      'enabled', loyalty.enabled,
      'model', loyalty.model,
      'unit', loyalty.unit,
      'balance', loyalty.balance
    ),
    'credit', jsonb_build_object(
      'balance_cents', credit.balance_cents
    ),
    'packages', jsonb_build_object(
      'sessions_remaining', case when 'packages' = any(p_enabled_modules)
        then packages.sessions_remaining else 0 end
    ),
    'expiry', jsonb_build_object(
      'mode', loyalty.expiry_mode,
      'expiring_within_7_days', loyalty.expiring_7_units,
      'expiring_units', loyalty.expiring_units,
      'next_expiry_at', loyalty.next_expiry_at
    ),
    'next_eligible_reward', case when reward_candidate.name is null then null else
      jsonb_build_object(
        'name', reward_candidate.name,
        'cost_units', reward_candidate.cost_units,
        'remaining_units', reward_candidate.remaining_units,
        'available_now', reward_candidate.available_now
      ) end,
    'visits_remaining', visit_candidate.visits_remaining,
    'visit_progress', case when visit_candidate.visits_remaining is null then null else
      jsonb_build_object(
        'remaining', visit_candidate.visits_remaining,
        'goal_visits', visit_candidate.goal_visits,
        'period_ends_at', visit_candidate.period_end,
        'customer_description', visit_candidate.customer_description
      ) end,
    'action', jsonb_build_object(
      'reason', action.reason,
      'deadline_at', action.deadline_at,
      'sort_band', action.sort_band,
      'sort_units', action.sort_units
    )
  )
    from loyalty
    cross join credit
    cross join packages
    left join reward_candidate on true
    left join visit_candidate on true
    cross join action;
$$;

--
-- Name: birthday_program_versions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.birthday_program_versions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    program_id uuid NOT NULL,
    config_version_id uuid NOT NULL,
    business_id uuid NOT NULL,
    active boolean DEFAULT true NOT NULL,
    customer_label text NOT NULL,
    customer_description text NOT NULL,
    customer_terms text NOT NULL,
    fulfillment_kind text NOT NULL,
    discount_percent numeric(5,2),
    manual_item text,
    window_days_before integer DEFAULT 0 NOT NULL,
    window_days_after integer DEFAULT 0 NOT NULL,
    sort integer DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    window_mode text DEFAULT 'days'::text NOT NULL,
    CONSTRAINT birthday_program_versions_customer_description_check CHECK (((length(btrim(customer_description)) >= 1) AND (length(btrim(customer_description)) <= 1000))),
    CONSTRAINT birthday_program_versions_customer_label_check CHECK (((length(btrim(customer_label)) >= 1) AND (length(btrim(customer_label)) <= 120))),
    CONSTRAINT birthday_program_versions_customer_terms_check CHECK (((length(btrim(customer_terms)) >= 1) AND (length(btrim(customer_terms)) <= 2000))),
    CONSTRAINT birthday_program_versions_fulfillment_check CHECK ((((fulfillment_kind = 'discount_pct'::text) AND (discount_percent IS NOT NULL) AND (discount_percent > (0)::numeric) AND (discount_percent <= (100)::numeric) AND (manual_item IS NULL)) OR ((fulfillment_kind = 'free_item'::text) AND (discount_percent IS NULL) AND ((length(btrim(COALESCE(manual_item, ''::text))) >= 1) AND (length(btrim(COALESCE(manual_item, ''::text))) <= 240))))),
    CONSTRAINT birthday_program_versions_fulfillment_kind_check CHECK ((fulfillment_kind = ANY (ARRAY['discount_pct'::text, 'free_item'::text]))),
    CONSTRAINT birthday_program_versions_sort_check CHECK (((sort >= 0) AND (sort <= 10000))),
    CONSTRAINT birthday_program_versions_window_days_after_check CHECK (((window_days_after >= 0) AND (window_days_after <= 182))),
    CONSTRAINT birthday_program_versions_window_days_before_check CHECK (((window_days_before >= 0) AND (window_days_before <= 182))),
    CONSTRAINT birthday_program_versions_window_mode_check CHECK ((window_mode = ANY (ARRAY['days'::text, 'month'::text]))),
    CONSTRAINT birthday_program_versions_window_no_annual_overlap_check CHECK ((((window_days_before + window_days_after) + 1) <= 365))
);

--
-- Name: TABLE birthday_program_versions; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.birthday_program_versions IS 'One typed birthday rule per stable programme/configuration version. Published rows are immutable.';

--
-- Name: COLUMN birthday_program_versions.window_mode; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.birthday_program_versions.window_mode IS 'V182 ''days'' = the +/-window_days_before/after window around the observed birthday (original
   behaviour, default). ''month'' = the customer''s whole birth month in Singapore time.';

--
-- Name: c45_benefit_snapshot(public.birthday_program_versions); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.c45_benefit_snapshot(p_program public.birthday_program_versions) RETURNS jsonb
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
  select jsonb_strip_nulls(jsonb_build_object(
    'label', p_program.customer_label,
    'description', p_program.customer_description,
    'terms', p_program.customer_terms,
    'kind', p_program.fulfillment_kind,
    'display', case when p_program.fulfillment_kind = 'discount_pct'
      then trim(to_char(p_program.discount_percent, 'FM990D00')) || '% off'
      else p_program.manual_item end
  ))
$$;

--
-- Name: c45_birthday_program_version_guard(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.c45_birthday_program_version_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_status text;
begin
  select status into v_status from public.firm_config_versions
   where id = case when tg_op = 'DELETE' then old.config_version_id else new.config_version_id end;
  if tg_op = 'UPDATE' then
    if (new.program_id, new.config_version_id, new.business_id, new.created_at)
        is distinct from (old.program_id, old.config_version_id, old.business_id, old.created_at) then
      raise exception 'birthday program identity is immutable; edit the draft row in place' using errcode = '23001';
    end if;
  end if;
  if v_status is distinct from 'draft' then
    raise exception 'published birthday configuration is immutable; edit a draft' using errcode = '23001';
  end if;
  if tg_op = 'DELETE' then return old; end if;
  return new;
end $$;

--
-- Name: c45_birthday_snapshot_trigger(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.c45_birthday_snapshot_trigger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  perform app.refresh_loyalty_config_snapshot(case when tg_op = 'DELETE' then old.config_version_id else new.config_version_id end);
  if tg_op = 'DELETE' then return old; end if;
  return new;
end $$;

--
-- Name: c45_birthday_window(date, integer, integer, timestamp with time zone); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.c45_birthday_window(p_birth_date date, p_window_days_before integer, p_window_days_after integer, p_as_of timestamp with time zone) RETURNS TABLE(birthday_year integer, valid_from timestamp with time zone, valid_until timestamp with time zone)
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
  with sg_now as (
    select timezone('Asia/Singapore', p_as_of) as local_now
  ), candidates as (
    select y as birthday_year, app.c45_observed_birthday(p_birth_date, y) as observed_date
      from sg_now,
      lateral generate_series(
        extract(year from local_now)::integer - 1,
        extract(year from local_now)::integer + 1
      ) as y
  )
  select birthday_year,
    ((observed_date - p_window_days_before)::timestamp at time zone 'Asia/Singapore') as valid_from,
    ((observed_date + p_window_days_after + 1)::timestamp at time zone 'Asia/Singapore') as valid_until
    from candidates
   where p_as_of >= ((observed_date - p_window_days_before)::timestamp at time zone 'Asia/Singapore')
     and p_as_of < ((observed_date + p_window_days_after + 1)::timestamp at time zone 'Asia/Singapore')
   order by birthday_year desc
   limit 1
$$;

--
-- Name: c45_birthday_window(date, integer, integer, timestamp with time zone, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.c45_birthday_window(p_birth_date date, p_window_days_before integer, p_window_days_after integer, p_as_of timestamp with time zone, p_mode text) RETURNS TABLE(birthday_year integer, valid_from timestamp with time zone, valid_until timestamp with time zone)
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
  select birthday_year, valid_from, valid_until from (
    with sg_now as (select timezone('Asia/Singapore', p_as_of) as local_now),
    candidates as (
      select y as birthday_year, app.c45_observed_birthday(p_birth_date, y) as observed_date
        from sg_now, lateral generate_series(
          extract(year from local_now)::integer - 1,
          extract(year from local_now)::integer + 1) as y
    )
    select birthday_year,
      (date_trunc('month', observed_date::timestamp) at time zone 'Asia/Singapore') as valid_from,
      ((date_trunc('month', observed_date::timestamp) + interval '1 month') at time zone 'Asia/Singapore') as valid_until
      from candidates where coalesce(p_mode,'days') = 'month'
    union all
    select birthday_year,
      ((observed_date - p_window_days_before)::timestamp at time zone 'Asia/Singapore'),
      ((observed_date + p_window_days_after + 1)::timestamp at time zone 'Asia/Singapore')
      from candidates where coalesce(p_mode,'days') <> 'month'
  ) w
   where p_as_of >= valid_from and p_as_of < valid_until
   order by birthday_year desc limit 1
$$;

--
-- Name: c45_clone_birthday_programs_on_draft(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.c45_clone_birthday_programs_on_draft() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if new.status = 'draft' and new.based_on_version_id is not null then
    insert into public.birthday_program_versions (
      program_id, config_version_id, business_id, active, customer_label,
      customer_description, customer_terms, fulfillment_kind, discount_percent,
      manual_item, window_days_before, window_days_after, sort
    )
    select program_id, new.id, new.business_id, active, customer_label,
           customer_description, customer_terms, fulfillment_kind, discount_percent,
           manual_item, window_days_before, window_days_after, sort
      from public.birthday_program_versions
     where config_version_id = new.based_on_version_id and business_id = new.business_id;
  end if;
  return new;
end $$;

--
-- Name: c45_customer_birthday_benefit_for_context(uuid, uuid, uuid, date, timestamp with time zone); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.c45_customer_birthday_benefit_for_context(p_business_id uuid, p_client_id uuid, p_identity_id uuid, p_birth_date date, p_as_of timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_entitlement public.customer_birthday_entitlements%rowtype;
  v_program public.birthday_program_versions%rowtype;
  v_window record;
  v_opted_in boolean := false;
begin
  -- A current immutable promise wins even if the active programme has since
  -- changed. Its effective state is derived from the half-open validity range.
  select * into v_entitlement
    from public.customer_birthday_entitlements e
   where e.business_id = p_business_id and e.client_id = p_client_id
     and e.identity_id = p_identity_id and e.valid_until > p_as_of
   order by e.valid_until desc, e.activated_at desc
   limit 1;
  if found then
    -- An existing promise remains visible after opt-out until it expires or is
    -- reversed; participation only gates NEW activation.
    return app.c45_safe_birthday_entitlement(v_entitlement, p_as_of);
  end if;
  select coalesce(p.opted_in, false) into v_opted_in
    from (select 1) one
    left join public.customer_birthday_participation p on p.identity_id = p_identity_id;
  select bpv.* into v_program
    from public.businesses b
    join public.loyalty_program_versions lpv
      on lpv.config_version_id = b.active_config_version_id
     and lpv.business_id = b.id and lpv.active
    join public.birthday_program_versions bpv
      on bpv.config_version_id = b.active_config_version_id
     and bpv.business_id = b.id and bpv.active
   where b.id = p_business_id
     and 'loyalty' = any(coalesce(b.enabled_modules, '{}'::text[]))
   order by bpv.sort, bpv.program_id
   limit 1;
  if found then
    select * into v_window
      from app.c45_birthday_window(p_birth_date, v_program.window_days_before,
        v_program.window_days_after, p_as_of);
    if found then
      -- Once the current SG birthday window is known, the matching immutable
      -- promise must be projected even when its end instant has elapsed. This
      -- produces effective `expired` without a write inside a failing action.
      select * into v_entitlement
        from public.customer_birthday_entitlements e
       where e.business_id = p_business_id and e.client_id = p_client_id
         and e.identity_id = p_identity_id and e.birthday_year = v_window.birthday_year
       order by e.activated_at desc
       limit 1;
      if found then return app.c45_safe_birthday_entitlement(v_entitlement, p_as_of); end if;
      if coalesce(v_opted_in, false) then
        return jsonb_build_object(
          'label', v_program.customer_label,
          'description', v_program.customer_description,
          'terms', v_program.customer_terms,
          'kind', v_program.fulfillment_kind,
          'display', case when v_program.fulfillment_kind = 'discount_pct'
            then trim(to_char(v_program.discount_percent, 'FM990D00')) || '% off'
            else v_program.manual_item end,
          'status', 'ready_to_activate',
          'validity', jsonb_build_object('available_from', v_window.valid_from, 'available_until', v_window.valid_until),
          'cta', 'activate'
        );
      end if;
    end if;
  end if;
  -- Outside the current birthday window, retain the most recent immutable
  -- promise as customer history. `c45_safe_birthday_entitlement` derives an
  -- effective expired state from valid_until; no failed redemption writes it.
  select * into v_entitlement
    from public.customer_birthday_entitlements e
   where e.business_id = p_business_id and e.client_id = p_client_id
     and e.identity_id = p_identity_id
   order by e.birthday_year desc, e.valid_until desc, e.activated_at desc
   limit 1;
  if found then return app.c45_safe_birthday_entitlement(v_entitlement, p_as_of); end if;
  return null;
end $$;

--
-- Name: c45_customer_birthday_context(text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.c45_customer_birthday_context(p_business_slug text) RETURNS TABLE(identity_id uuid, business_id uuid, client_id uuid, birth_date date, business_slug text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_context record;
begin
  if auth.uid() is null then
    raise exception 'authenticated customer session required' using errcode = '28000';
  end if;
  if not app.platform_feature_enabled('customer_birthday_benefits') then
    raise exception 'birthday benefits are unavailable' using errcode = '0A000';
  end if;
  select * into v_context from app.v32_customer_wallet_context(p_business_slug) limit 1;
  if not found then
    raise exception 'birthday benefits are unavailable' using errcode = '42501';
  end if;
  return query
    select v_context.identity_id, v_context.business_id, v_context.client_id,
           cp.birth_date, v_context.business_slug
      from public.customer_profiles cp
     where cp.identity_id = v_context.identity_id
       and cp.auth_user_id = auth.uid();
  if not found then
    raise exception 'birthday benefits are unavailable' using errcode = '42501';
  end if;
end $$;

--
-- Name: c45_entitlement_guard(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.c45_entitlement_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if tg_op='INSERT' then return new; end if;
  if tg_op='DELETE' or current_setting('app.c45_entitlement_id',true) is distinct from old.id::text
     or (new.business_id,new.client_id,new.identity_id,new.config_version_id,new.birthday_program_version_id,
         new.birthday_year,new.valid_from,new.valid_until,new.benefit_snapshot,new.activated_at)
       is distinct from
        (old.business_id,old.client_id,old.identity_id,old.config_version_id,old.birthday_program_version_id,
         old.birthday_year,old.valid_from,old.valid_until,old.benefit_snapshot,old.activated_at)
     or new.status not in ('available','redeemed','expired') then
    raise exception 'birthday entitlement provenance is immutable' using errcode='23001';
  end if;
  new.updated_at:=now(); return new;
end $$;

--
-- Name: c45_hash(text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.c45_hash(p_value text) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog', 'extensions', 'pg_temp'
    AS $$ select encode(extensions.digest(convert_to(p_value, 'UTF8'), 'sha256'), 'hex') $$;

--
-- Name: c45_loyalty_program_version_write_guard(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.c45_loyalty_program_version_write_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_business uuid:=case when tg_op='DELETE' then old.business_id else new.business_id end;
  v_config uuid:=case when tg_op='DELETE' then old.config_version_id else new.config_version_id end;
  v_status text;
  v_shared_clone boolean:=false;
begin
  select status into v_status from public.firm_config_versions where id=v_config;
  v_shared_clone:=
    nullif(current_setting('app.v138_grow_draft_id',true),'')=v_config::text
    and nullif(current_setting('app.v138_grow_draft_actor',true),'')=coalesce(auth.uid()::text,'')
    and app.is_salon_owner(v_business)
    and app.can_module_write(v_business,'retention');
  if v_status='draft' and not app.c45_owner_loyalty_write(v_business)
     and not v_shared_clone then
    raise exception 'owner loyalty configuration access required' using errcode='42501';
  end if;
  if tg_op='DELETE' then return old; end if;
  return new;
end $$;

--
-- Name: c45_observed_birthday(date, integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.c45_observed_birthday(p_birth_date date, p_year integer) RETURNS date
    LANGUAGE plpgsql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
begin
  if extract(month from p_birth_date) = 2 and extract(day from p_birth_date) = 29
     and not (p_year % 4 = 0 and (p_year % 100 <> 0 or p_year % 400 = 0)) then
    return make_date(p_year, 2, 28);
  end if;
  return make_date(p_year, extract(month from p_birth_date)::integer,
                   extract(day from p_birth_date)::integer);
end $$;

--
-- Name: c45_owner_loyalty_write(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.c45_owner_loyalty_write(p_business_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  select auth.uid() is not null
     and app.is_salon_owner(p_business_id)
     and app.can_module_write(p_business_id, 'loyalty')
     and exists (
       select 1 from public.businesses b
        where b.id = p_business_id and 'loyalty' = any(coalesce(b.enabled_modules, '{}'::text[]))
     )
$$;

--
-- Name: c45_redemption_guard(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.c45_redemption_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if tg_op='INSERT' then return new; end if;
  if tg_op='DELETE' or current_setting('app.c45_redemption_id',true) is distinct from old.id::text
     or (new.id,new.entitlement_id,new.business_id,new.client_id,new.branch_id,new.actor,new.operation_kind,
         new.original_redemption_id,new.idempotency_key,new.request_hash,new.reason,new.created_at)
       is distinct from
        (old.id,old.entitlement_id,old.business_id,old.client_id,old.branch_id,old.actor,old.operation_kind,
         old.original_redemption_id,old.idempotency_key,old.request_hash,old.reason,old.created_at) then
    raise exception 'birthday redemption provenance is immutable' using errcode='23001';
  end if;
  return new;
end $$;

--
-- Name: customer_birthday_entitlements; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.customer_birthday_entitlements (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    business_id uuid NOT NULL,
    client_id uuid NOT NULL,
    identity_id uuid NOT NULL,
    config_version_id uuid NOT NULL,
    birthday_program_version_id uuid NOT NULL,
    birthday_year integer NOT NULL,
    status text NOT NULL,
    valid_from timestamp with time zone NOT NULL,
    valid_until timestamp with time zone NOT NULL,
    benefit_snapshot jsonb NOT NULL,
    activated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT customer_birthday_entitlements_benefit_snapshot_check CHECK ((jsonb_typeof(benefit_snapshot) = 'object'::text)),
    CONSTRAINT customer_birthday_entitlements_birthday_year_check CHECK (((birthday_year >= 1900) AND (birthday_year <= 9999))),
    CONSTRAINT customer_birthday_entitlements_status_check CHECK ((status = ANY (ARRAY['available'::text, 'redeemed'::text, 'expired'::text]))),
    CONSTRAINT customer_birthday_entitlements_window_check CHECK ((valid_until > valid_from))
);

--
-- Name: TABLE customer_birthday_entitlements; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.customer_birthday_entitlements IS 'Customer-specific immutable benefit promise. It stores no DOB, observed date, age, or birthday month/day.';

--
-- Name: c45_safe_birthday_entitlement(public.customer_birthday_entitlements, timestamp with time zone, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.c45_safe_birthday_entitlement(p_entitlement public.customer_birthday_entitlements, p_as_of timestamp with time zone, p_cta text DEFAULT 'show_at_counter'::text) RETURNS jsonb
    LANGUAGE sql STABLE STRICT
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
  select jsonb_strip_nulls(jsonb_build_object(
    'label', p_entitlement.benefit_snapshot->>'label',
    'description', p_entitlement.benefit_snapshot->>'description',
    'terms', p_entitlement.benefit_snapshot->>'terms',
    'kind', p_entitlement.benefit_snapshot->>'kind',
    'display', p_entitlement.benefit_snapshot->>'display',
    'status', case
      when p_entitlement.status = 'available' and p_entitlement.valid_until <= p_as_of then 'expired'
      else p_entitlement.status end,
    'validity', jsonb_build_object(
      'available_from', p_entitlement.valid_from,
      'available_until', p_entitlement.valid_until
    ),
    'redemption', case when p_entitlement.status = 'redeemed' then 'redeemed' else null end,
    'cta', case
      when p_entitlement.status = 'available'
       and p_entitlement.valid_from <= p_as_of
       and p_entitlement.valid_until > p_as_of then p_cta
      else null end
  ))
$$;

--
-- Name: c45_staff_safe_birthday_entitlement(public.customer_birthday_entitlements, timestamp with time zone, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.c45_staff_safe_birthday_entitlement(p_entitlement public.customer_birthday_entitlements, p_as_of timestamp with time zone, p_cta text DEFAULT 'show_at_counter'::text) RETURNS jsonb
    LANGUAGE sql STABLE STRICT
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
  select jsonb_strip_nulls(jsonb_build_object(
    'label', p_entitlement.benefit_snapshot->>'label',
    'kind', p_entitlement.benefit_snapshot->>'kind',
    'display', p_entitlement.benefit_snapshot->>'display',
    'status', case
      when p_entitlement.status = 'available' and p_entitlement.valid_until <= p_as_of then 'expired'
      else p_entitlement.status end,
    'redemption', case when p_entitlement.status = 'redeemed' then 'redeemed' else null end,
    'cta', case
      when p_entitlement.status = 'available'
       and p_entitlement.valid_from <= p_as_of
       and p_entitlement.valid_until > p_as_of then p_cta
      else null end
  ))
$$;

--
-- Name: c46_append_only_guard(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.c46_append_only_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if tg_op <> 'INSERT' then
    raise exception '% is immutable', tg_table_name using errcode = '23000';
  end if;
  return new;
end;
$$;

--
-- Name: c46_customer_inbox_context(text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.c46_customer_inbox_context(p_business_slug text) RETURNS TABLE(identity_id uuid, auth_user_id uuid, link_id uuid, business_id uuid, client_id uuid, business_slug text, business_name text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_actor uuid := auth.uid(); v_slug text := lower(btrim(coalesce(p_business_slug, '')));
begin
  if v_actor is null then
    raise exception 'authenticated customer session required' using errcode = '28000';
  end if;
  if not app.platform_feature_enabled('customer_in_app_inbox') then
    raise exception 'customer in-app inbox is not enabled' using errcode = '0A000';
  end if;
  if length(v_slug) not between 2 and 160 then
    raise exception 'invalid business link' using errcode = '22023';
  end if;
  return query
    select ci.id, v_actor, cl.id, cl.business_id, cl.client_id, b.slug, b.name
      from public.customer_identities ci
      join public.customer_links cl
        on cl.identity_id = ci.id and cl.auth_user_id = v_actor and cl.state = 'verified'
      join public.businesses b on b.id = cl.business_id
     where ci.auth_user_id = v_actor and ci.status = 'active' and b.slug = v_slug
     order by cl.id
     limit 1;
  if not found then
    raise exception 'verified customer link required' using errcode = '42501';
  end if;
end;
$$;

--
-- Name: c46_customer_inbox_global_context(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.c46_customer_inbox_global_context() RETURNS TABLE(identity_id uuid, auth_user_id uuid)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_actor uuid := auth.uid();
begin
  if v_actor is null then
    raise exception 'authenticated customer session required' using errcode = '28000';
  end if;
  if not app.platform_feature_enabled('customer_in_app_inbox') then
    raise exception 'customer in-app inbox is not enabled' using errcode = '0A000';
  end if;
  return query select ci.id, v_actor from public.customer_identities ci
   where ci.auth_user_id=v_actor and ci.status='active';
  if not found then raise exception 'active customer identity required' using errcode='42501'; end if;
end;
$$;

--
-- Name: c46_customer_safe_booking_candidates(uuid, uuid, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.c46_customer_safe_booking_candidates(p_business_id uuid, p_identity_id uuid, p_link_id uuid) RETURNS TABLE(source_kind text, topic text, title text, body text, source_fingerprint text, deadline_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $_$
  select 'v33_booking_action', 'booking_updates', 'Appointment request received',
         'Open this business wallet to review your appointment request.',
         app.c46_sha256_hex(jsonb_build_object(
           'source','v33-booking-action','request_id',r.id,'action',r.action,
           'proposed_at',r.proposed_at,'created_at',r.created_at
         )::text), r.proposed_at
    from public.customer_appointment_action_requests r
   where r.business_id=$1 and r.identity_id=$2 and r.link_id=$3 and r.status='pending'
$_$;

--
-- Name: c46_customer_safe_inbox_candidates(jsonb); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.c46_customer_safe_inbox_candidates(p_card jsonb) RETURNS TABLE(source_kind text, topic text, title text, body text, source_fingerprint text, deadline_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  select 'c44_actionable_wallet', 'value_expiry',
         case
           when (nullif(p_card#>>'{expiry,next_expiry_at}','')::timestamptz-now())<=interval '1 day'
             then case when p_card#>>'{loyalty,unit}'='stamps' then 'Stamps expire tomorrow' else 'Points expire tomorrow' end
           else case when p_card#>>'{loyalty,unit}'='stamps' then 'Stamps expire within 3 days' else 'Points expire within 3 days' end
         end,
         case when p_card#>>'{loyalty,unit}'='stamps'
           then 'Open this programme now to review your expiring stamps.'
           else 'Open this programme now to review your expiring points.' end,
         app.c46_sha256_hex(jsonb_build_object(
           'source','c44-expiry-urgent',
           'window',case when (nullif(p_card#>>'{expiry,next_expiry_at}','')::timestamptz-now())<=interval '1 day' then 'one_day' else 'three_days' end,
           'deadline',p_card#>>'{expiry,next_expiry_at}',
           'unit',p_card#>>'{loyalty,unit}'
         )::text),
         nullif(p_card#>>'{expiry,next_expiry_at}','')::timestamptz
   where p_card#>>'{loyalty,unit}' in ('points','stamps')
     and coalesce((p_card#>>'{expiry,expiring_units}')::integer, 0)>0
     and nullif(p_card#>>'{expiry,next_expiry_at}','') is not null
     and nullif(p_card#>>'{expiry,next_expiry_at}','')::timestamptz>now()
     and nullif(p_card#>>'{expiry,next_expiry_at}','')::timestamptz<=now()+interval '3 days'
  union all
  select 'c44_actionable_wallet', 'reward_ready', 'Reward unlocked!',
         'Open this programme to view and redeem your reward.',
         app.c46_sha256_hex(jsonb_build_object(
           'source','c44-reward','name',p_card#>>'{next_eligible_reward,name}',
           'cost',p_card#>>'{next_eligible_reward,cost_units}'
         )::text), null
   where coalesce((p_card#>>'{next_eligible_reward,available_now}')::boolean, false)
  union all
  select 'c44_actionable_wallet', 'visit_progress', 'Quest almost complete',
         'One qualifying visit remains before your next reward.',
         app.c46_sha256_hex(jsonb_build_object(
           'source','c44-visit','period_end',p_card#>>'{visit_progress,period_ends_at}',
           'goal',p_card#>>'{visit_progress,goal_visits}'
         )::text), nullif(p_card#>>'{visit_progress,period_ends_at}','')::timestamptz
   where coalesce((p_card#>>'{visits_remaining}')::integer, -1)=1
  union all
  select 'c45_birthday_benefit', 'birthday_benefit', 'Birthday surprise unlocked',
         'Open this programme to view your birthday benefit.',
         app.c46_sha256_hex(jsonb_build_object(
           'source','c45-birthday','status',p_card#>>'{birthday_benefit,status}',
           'until',p_card#>>'{birthday_benefit,validity,available_until}'
         )::text), nullif(p_card#>>'{birthday_benefit,validity,available_until}','')::timestamptz
   where p_card#>>'{birthday_benefit,status}' in ('ready_to_activate','available')
$$;

--
