--

CREATE FUNCTION app.c46_iana_timezone_allowed(p_timezone text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $_$
  select exists (
    select 1 from pg_timezone_names where name = nullif(btrim($1), '')
  )
$_$;

--
-- Name: c46_in_app_preference_for_context(uuid, uuid, uuid, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.c46_in_app_preference_for_context(p_business_id uuid, p_identity_id uuid, p_link_id uuid, p_topic text) RETURNS TABLE(opted_in boolean, quiet_hours_timezone text, quiet_hours_start time without time zone, quiet_hours_end time without time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $_$
  select coalesce(p.opted_in, false), p.quiet_hours_timezone,
         p.quiet_hours_start, p.quiet_hours_end
    from (values (1)) as fallback(one)
    left join public.customer_notification_preferences p
      on p.business_id = $1 and p.identity_id = $2 and p.link_id = $3
     and p.channel = 'in_app' and p.topic = $4
$_$;

--
-- Name: c46_in_app_topic_allowed(text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.c46_in_app_topic_allowed(p_topic text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $_$
  select $1 = any(array[
    'value_expiry','reward_ready','visit_progress','birthday_benefit',
    'booking_updates','promotion_alerts'
  ]::text[])
$_$;

--
-- Name: c46_in_quiet_hours(text, time without time zone, time without time zone, timestamp with time zone); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.c46_in_quiet_hours(p_timezone text, p_start time without time zone, p_end time without time zone, p_as_of timestamp with time zone DEFAULT statement_timestamp()) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
declare v_local_time time without time zone;
begin
  if p_timezone is null or p_start is null or p_end is null then return false; end if;
  if not app.c46_iana_timezone_allowed(p_timezone) then return false; end if;
  v_local_time := timezone(p_timezone, p_as_of)::time;
  if p_start < p_end then
    return v_local_time >= p_start and v_local_time < p_end;
  end if;
  -- A half-open window spanning midnight, for example 22:00–08:00.
  return v_local_time >= p_start or v_local_time < p_end;
end;
$$;

--
-- Name: c46_inbox_source_available(text, boolean); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.c46_inbox_source_available(p_source_kind text, p_actionable_wallet_enabled boolean) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $_$
  select $1 in (
    'v33_booking_action','v48_appointment_reschedule',
    'v122_promotion_new','v122_promotion_expiry','v278_bottle_reminder',
    'v282_bottle_expiry'
  ) or (
    coalesce($2,false)
    and $1 in ('c44_actionable_wallet','c45_birthday_benefit')
  )
$_$;

--
-- Name: c46_inbox_state_guard(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.c46_inbox_state_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_write_event text := nullif(current_setting('app.c46_inbox_state_event', true), '');
begin
  if tg_op = 'DELETE' then
    raise exception 'customer inbox state is retained as operation evidence' using errcode = '23000';
  end if;
  if v_write_event is distinct from new.event_id::text then
    raise exception 'customer inbox state may only be changed through its operation RPC' using errcode = '42501';
  end if;
  if tg_op = 'UPDATE' and (
    (new.event_id, new.business_id, new.identity_id, new.auth_user_id, new.link_id, new.client_id, new.created_at)
      is distinct from
    (old.event_id, old.business_id, old.identity_id, old.auth_user_id, old.link_id, old.client_id, old.created_at)
  ) then
    raise exception 'customer inbox state provenance is immutable' using errcode = '23000';
  end if;
  new.updated_at := now();
  return new;
end;
$$;

--
-- Name: c46_sha256_hex(text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.c46_sha256_hex(p_value text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'extensions', 'pg_temp'
    AS $_$
  select encode(extensions.digest(convert_to($1, 'UTF8'), 'sha256'), 'hex')
$_$;

