--
-- Name: can_see_branch(uuid, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.can_see_branch(p_business uuid, p_branch uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  select case
    when auth.uid() is null then false
    when app.is_super_admin() then true
    when not app.business_workspace_open_v94(p_business) then false
    else exists(
      select 1 from public.staff staff_row
      where staff_row.business_id=p_business
        and staff_row.user_id=auth.uid() and staff_row.active
        and (
          app.role_class(staff_row.role) in ('owner','admin')
          or (p_branch is not null and exists(
            select 1 from public.staff_branches assignment
            where assignment.business_id=p_business
              and assignment.staff_id=staff_row.id
              and assignment.branch_id=p_branch
          ))
        )
    )
  end
$$;

--
-- Name: FUNCTION can_see_branch(p_business uuid, p_branch uuid); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.can_see_branch(p_business uuid, p_branch uuid) IS 'v17 branch visibility. super-admin/owner/admin -> all branches (incl NULL). employee -> only staff_branches-assigned; NULL branch owner/admin only. Fail-closed for anon.';

