    AS $$
  select app.is_salon_owner(p_business)
    or (app.business_workspace_open_v94(p_business)
        and exists (select 1 from public.staff s
            where s.business_id = p_business and s.user_id = auth.uid() and s.active
              and (s.role = 'manager' or coalesce((s.module_perms->>'sell_topups')::boolean, false))))
$$;

--
-- Name: capture_billing_paid_adoption_v100(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.capture_billing_paid_adoption_v100() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if tg_op='INSERT' and new.paid_normalized then
    perform app.append_server_adoption_event_v100(
      'billing.invoice_paid',new.business_id,null,null,
      'billing_provider_invoices',new.id,tg_op,
      coalesce(new.paid_at,new.updated_at)
    );
  elsif tg_op='UPDATE'
        and new.paid_normalized
        and not coalesce(old.paid_normalized,false) then
    perform app.append_server_adoption_event_v100(
      'billing.invoice_paid',new.business_id,null,null,
      'billing_provider_invoices',new.id,tg_op,
      coalesce(new.paid_at,new.updated_at)
    );
  end if;
  return new;
end
$$;

