--
-- Name: checkout_evaluations_guard(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.checkout_evaluations_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_reserved_attempt uuid;
begin
  if tg_op = 'DELETE' then
    raise exception 'checkout_evaluations rows are permanent' using errcode = 'restrict_violation';
  end if;
  if new.id is not distinct from old.id and new.business_id is not distinct from old.business_id
     and new.branch_id is not distinct from old.branch_id and new.client_id is not distinct from old.client_id
     and new.server_lines is not distinct from old.server_lines and new.cart_hash is not distinct from old.cart_hash
     and new.config_version_id is not distinct from old.config_version_id
     and new.applied_effects is not distinct from old.applied_effects
     and new.subtotal_cents is not distinct from old.subtotal_cents
     and new.discount_total_cents is not distinct from old.discount_total_cents
     and new.total_cents is not distinct from old.total_cents and new.gst_cents is not distinct from old.gst_cents
     and new.gst_rate_bps is not distinct from old.gst_rate_bps
     and new.created_at is not distinct from old.created_at
     and new.consumed_at is not distinct from old.consumed_at
     and new.consumed_sale_id is not distinct from old.consumed_sale_id
     and new.expires_at is distinct from old.expires_at then
    if coalesce(auth.role(),'')='service_role'
       and current_setting('app.v142_extend_checkout',true)='on'
       and old.consumed_at is null and new.expires_at>old.expires_at
       and new.expires_at<=clock_timestamp()+interval '61 minutes 5 seconds' then
      return new;
    end if;
    raise exception 'checkout evaluation expiry is immutable outside provider reservation'
      using errcode = 'restrict_violation';
  end if;
  if new.id is distinct from old.id or new.business_id is distinct from old.business_id
     or new.branch_id is distinct from old.branch_id or new.client_id is distinct from old.client_id
     or new.server_lines is distinct from old.server_lines or new.cart_hash is distinct from old.cart_hash
     or new.config_version_id is distinct from old.config_version_id
     or new.applied_effects is distinct from old.applied_effects
     or new.subtotal_cents is distinct from old.subtotal_cents
     or new.discount_total_cents is distinct from old.discount_total_cents
     or new.total_cents is distinct from old.total_cents or new.gst_cents is distinct from old.gst_cents
     or new.gst_rate_bps is distinct from old.gst_rate_bps or new.expires_at is distinct from old.expires_at
     or new.created_at is distinct from old.created_at then
    raise exception 'checkout evaluation identity and economics are immutable' using errcode = 'restrict_violation';
  end if;
  if old.consumed_at is null and new.consumed_at is not null then
    select a.id into v_reserved_attempt
      from public.pos_payment_attempts_v142 a
     where a.evaluation_id=old.id
       and a.status in ('prepared','awaiting_payment','processing','fulfilment_failed',
                        'refund_required','refund_pending','refund_failed')
     limit 1;
    if v_reserved_attempt is not null and not (
      coalesce(auth.role(),'')='service_role'
      and current_setting('app.v142_provider_finalize',true)=v_reserved_attempt::text
    ) then
      raise exception 'checkout evaluation is reserved for provider payment'
        using errcode = 'restrict_violation';
    end if;
  end if;
  if old.consumed_at is not null and new.consumed_at is distinct from old.consumed_at then
    raise exception 'checkout evaluation is already consumed (single-use)' using errcode = 'restrict_violation';
  end if;
  if old.consumed_sale_id is not null and new.consumed_sale_id is distinct from old.consumed_sale_id then
    raise exception 'checkout evaluation consumed_sale_id is write-once' using errcode = 'restrict_violation';
  end if;
  return new;
end $$;

--
-- Name: checkout_sv_tenders_guard(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.checkout_sv_tenders_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if tg_op = 'DELETE' then
    raise exception 'checkout_sv_tenders is append-only (bindings are permanent)' using errcode = 'restrict_violation';
  end if;
  if new.id is distinct from old.id or new.business_id is distinct from old.business_id
     or new.evaluation_id is distinct from old.evaluation_id or new.account_id is distinct from old.account_id
     or new.reservation_id is distinct from old.reservation_id
     or new.reserve_operation_id is distinct from old.reserve_operation_id
     or new.idempotency_key is distinct from old.idempotency_key
     or new.requested_cents is distinct from old.requested_cents
     or new.reserved_cents is distinct from old.reserved_cents
     or new.currency is distinct from old.currency or new.created_at is distinct from old.created_at then
    raise exception 'checkout_sv_tenders identity and economics are immutable' using errcode = 'restrict_violation';
  end if;
  if new.status not in ('reserved', 'consumed', 'released') then
    raise exception 'checkout_sv_tenders status must be reserved/consumed/released' using errcode = 'restrict_violation';
  end if;
  if old.status <> 'reserved' and new.status is distinct from old.status then
    raise exception 'checkout_sv_tenders is already % (single-transition)', old.status using errcode = 'restrict_violation';
  end if;
  if old.status <> 'reserved' then
    -- Terminal: the settlement bindings §10/§11 read are frozen with the status.
    if new.sale_id is distinct from old.sale_id
       or new.spend_operation_id is distinct from old.spend_operation_id then
      raise exception 'checkout_sv_tenders is already % (settlement bindings are frozen)', old.status
        using errcode = 'restrict_violation';
    end if;
  elsif new.status = 'consumed' then
    -- The ONE transition that may write them, and it must write BOTH.
    if old.sale_id is not null or old.spend_operation_id is not null then
      raise exception 'checkout_sv_tenders sale/spend bindings are write-once' using errcode = 'restrict_violation';
    end if;
    if new.sale_id is null or new.spend_operation_id is null then
      raise exception 'a consumed checkout_sv_tender must record both its sale and its spend operation'
        using errcode = 'restrict_violation';
    end if;
  else
    -- Still reserved, or reserved -> released: nothing settled, so nothing binds.
    if new.sale_id is not null or new.spend_operation_id is not null then
      raise exception 'only a consumed checkout_sv_tender may bind a sale and a spend operation'
        using errcode = 'restrict_violation';
    end if;
  end if;
  return new;
end $$;

--
-- Name: classify_billing_item_v124(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.classify_billing_item_v124() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_role text;
begin
  select case
    when catalog.provider_base_price_id = new.provider_price_id then 'base'
    when catalog.provider_capacity_price_id = new.provider_price_id then 'capacity'
  end into v_role
    from public.billing_plan_catalog_v124 catalog
   where new.provider_price_id in (
     catalog.provider_base_price_id,catalog.provider_capacity_price_id
   )
   order by catalog.effective_from desc limit 1;
  if v_role is not null then new.item_role := v_role; end if;
  return new;
end
$$;

--
-- Name: client_points_balance_v409(uuid, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.client_points_balance_v409(p_business uuid, p_client uuid) RETURNS integer
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_scope text := app.programme_balance_scope_v312(p_business);
  v_live  uuid := app.live_balance_programme_v381(p_business);
  v_total integer;
begin
  -- The two resolvers are read into locals ON PURPOSE. Inlined into the WHERE
  -- clause they would be re-evaluated per row, and programme_balance_scope_v312
  -- aggregates the whole tenant's ledger and batches -- the v370 finding that slow
  -- RPCs were re-evaluated functions rather than missing indexes.
  select coalesce(sum(l.points),0)::integer into v_total
    from public.points_ledger l
   where l.business_id = p_business
     and l.client_id   = p_client
     and (v_scope <> 'programme_pot'
          or l.programme_id is not distinct from v_live);
  return coalesce(v_total,0);
end
$$;

--
-- Name: FUNCTION client_points_balance_v409(p_business uuid, p_client uuid); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.client_points_balance_v409(p_business uuid, p_client uuid) IS 'v409: THE canonical customer points balance. Honours the v312 pot-safety switch and the v381 live-programme resolver. Every live current-balance reader delegates here; do not hand-write another sum over points_ledger for a customer balance.';

--
-- Name: clone_loyalty_branch_overrides_on_draft(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.clone_loyalty_branch_overrides_on_draft() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if new.status = 'draft' and new.based_on_version_id is not null then
    insert into public.loyalty_branch_overrides (
      config_version_id, business_id, branch_id, active,
      earn_points_per_dollar, stamp_per_cents, expiry_mode, expiry_days
    )
    select new.id, new.business_id, branch_id, active,
           earn_points_per_dollar, stamp_per_cents, expiry_mode, expiry_days
      from public.loyalty_branch_overrides
     where config_version_id = new.based_on_version_id
       and business_id = new.business_id;
  end if;
  return new;
end
$$;

--
-- Name: clone_program_rules_on_draft(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.clone_program_rules_on_draft() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if new.status = 'draft' and new.based_on_version_id is not null then
    insert into public.program_rules(
      rule_id, config_version_id, business_id, schema_version, name, active,
      when_event, if_conditions, then_effects, with_params, during_schedule, using_stacking,
      source_engine, rule_hash, sort, notes)
    select pr.rule_id, new.id, new.business_id, pr.schema_version, pr.name, pr.active,
           pr.when_event, pr.if_conditions, pr.then_effects, pr.with_params, pr.during_schedule, pr.using_stacking,
           pr.source_engine, pr.rule_hash, pr.sort, pr.notes
      from public.program_rules pr
     where pr.config_version_id = new.based_on_version_id
       and pr.business_id = new.business_id;
  end if;
  return new;
end $$;

--
-- Name: clone_retention_program_versions_on_draft(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.clone_retention_program_versions_on_draft() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if new.status='draft' and new.based_on_version_id is not null then
    insert into public.retention_program_versions(
      program_id,config_version_id,business_id,name,active,goal_visits,
      period_days,starts_on,reward_taxonomy_id,fulfillment_kind,
      discount_percent,credit_cents,manual_item,sort,
      customer_description,staff_description
    )
    select rv.program_id,new.id,new.business_id,rv.name,rv.active,rv.goal_visits,
           rv.period_days,rv.starts_on,rv.reward_taxonomy_id,t.fulfillment_kind,
           rv.discount_percent,rv.credit_cents,rv.manual_item,rv.sort,
           rv.customer_description,rv.staff_description
      from public.retention_program_versions rv
      join public.firm_reward_taxonomy t
        on t.id=rv.reward_taxonomy_id and t.business_id=rv.business_id
      join public.retention_programs prog
        on prog.id=rv.program_id and prog.business_id=rv.business_id
       and prog.deleted_at is null
     where rv.config_version_id=new.based_on_version_id
       and rv.business_id=new.business_id;
  end if;
  return new;
end $$;

--
-- Name: clone_reward_versions_for_config(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.clone_reward_versions_for_config() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if new.based_on_version_id is null then return new; end if;
  insert into public.loyalty_reward_versions (
    reward_id, business_id, config_version_id, internal_name, customer_name,
    description, fulfillment_kind, taxonomy_label, cost_points, credit_cents,
    estimated_cost_cents, active, sort, claim_available_from, claim_available_until,
    entitlement_expiry_days, instructions, terms, image_ref, requires_purchase, usage_limit,
    min_tier_id, min_tier_threshold
  )
  select source.reward_id, source.business_id, new.id, source.internal_name, source.customer_name,
         source.description, source.fulfillment_kind, source.taxonomy_label, source.cost_points,
         source.credit_cents, source.estimated_cost_cents,
         coalesce(live.active, source.active),
         source.sort, source.claim_available_from, source.claim_available_until,
         source.entitlement_expiry_days, source.instructions, source.terms, source.image_ref, source.requires_purchase,
         source.usage_limit, source.min_tier_id, source.min_tier_threshold
    from public.loyalty_reward_versions source
    left join public.loyalty_rewards live
      on live.id = source.reward_id and live.business_id = source.business_id
   where source.config_version_id = new.based_on_version_id
     and source.business_id = new.business_id;

  insert into public.loyalty_reward_branches (reward_version_id, reward_id, business_id, branch_id)
  select next_rv.id, next_rv.reward_id, old_e.business_id, old_e.branch_id
    from public.loyalty_reward_versions old_rv
    join public.loyalty_reward_branches old_e on old_e.reward_version_id = old_rv.id
    join public.loyalty_reward_versions next_rv
      on next_rv.config_version_id = new.id and next_rv.reward_id = old_rv.reward_id
   where old_rv.config_version_id = new.based_on_version_id;

  insert into public.loyalty_reward_services (reward_version_id, reward_id, business_id, service_id)
  select next_rv.id, next_rv.reward_id, old_e.business_id, old_e.service_id
    from public.loyalty_reward_versions old_rv
    join public.loyalty_reward_services old_e on old_e.reward_version_id = old_rv.id
    join public.loyalty_reward_versions next_rv
      on next_rv.config_version_id = new.id and next_rv.reward_id = old_rv.reward_id
   where old_rv.config_version_id = new.based_on_version_id;

  insert into public.loyalty_reward_products (reward_version_id, reward_id, business_id, product_id)
  select next_rv.id, next_rv.reward_id, old_e.business_id, old_e.product_id
    from public.loyalty_reward_versions old_rv
    join public.loyalty_reward_products old_e on old_e.reward_version_id = old_rv.id
    join public.loyalty_reward_versions next_rv
      on next_rv.config_version_id = new.id and next_rv.reward_id = old_rv.reward_id
   where old_rv.config_version_id = new.based_on_version_id;
  return new;
end $$;

--
-- Name: commission_flat_cents(uuid, text, uuid, uuid, timestamp with time zone, integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.commission_flat_cents(p_business uuid, p_kind text, p_staff uuid, p_appointment uuid, p_occurred_at timestamp with time zone, p_amount_cents integer) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  select case
           when st.id is null then null
           when st.commission_starts_on is not null
                and (p_occurred_at at time zone 'Asia/Singapore')::date < st.commission_starts_on
                then null
           when coalesce(p_amount_cents, 0) <= 0 then null
           when p_kind = 'service' then svc.commission_flat_cents
           else null
         end
  from (select 1) _
  left join public.staff st       on st.id  = p_staff and st.business_id = p_business
  left join public.appointments a on a.id   = p_appointment
  left join public.services svc   on svc.id = a.service_id
$$;

--
-- Name: FUNCTION commission_flat_cents(p_business uuid, p_kind text, p_staff uuid, p_appointment uuid, p_occurred_at timestamp with time zone, p_amount_cents integer); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.commission_flat_cents(p_business uuid, p_kind text, p_staff uuid, p_appointment uuid, p_occurred_at timestamp with time zone, p_amount_cents integer) IS 'Flat-commission resolver (v13 rebased; formally reconciled by v22). Owner-only ACL — the sole caller is app.on_sale_commission_snapshot() (SECURITY DEFINER trigger). v22 supersedes v20''s "v13 flat commission is tombstoned" statement: flat commission is the approved model per the owner''s %-or-flat-per-service ruling, with v20-compatible reversal semantics (a reversal row copies the original''s flat snapshot and public.sale_commission nets it negative in full).';

--
-- Name: commission_rate_bps(uuid, text, uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.commission_rate_bps(p_business uuid, p_kind text, p_staff uuid, p_appointment uuid, p_occurred_at timestamp with time zone) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  select case
           when st.id is null then 0
           when st.commission_starts_on is not null
                and (p_occurred_at at time zone 'Asia/Singapore')::date < st.commission_starts_on
                then 0
           else coalesce(
                  case when p_kind = 'service'
                       then coalesce(svc.commission_bps, st.commission_service_bps)
                       else st.commission_product_bps
                  end, 0)
         end
  from (select 1) _
  left join public.staff st       on st.id  = p_staff and st.business_id = p_business
  left join public.appointments a on a.id   = p_appointment
  left join public.services svc   on svc.id = a.service_id
$$;

