--
-- Name: compare_shadow_vs_live(uuid, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.compare_shadow_vs_live(p_business uuid, p_engine text DEFAULT 'referral'::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_shadow_only integer; v_live_only integer; v_mismatch integer; v_matched integer;
begin
  select count(*) into v_shadow_only from public.benefit_shadow_evaluations s
   where s.business_id = p_business and s.source_engine = p_engine
     and not exists(select 1 from public.benefit_fulfilments f
                     where f.business_id = s.business_id and f.canonical_benefit_key = s.would_be_canonical_key);
  select count(*) into v_live_only from public.benefit_fulfilments f
   where f.business_id = p_business and f.source_engine = p_engine
     and not exists(select 1 from public.benefit_shadow_evaluations s
                     where s.business_id = f.business_id and s.would_be_canonical_key = f.canonical_benefit_key);
  select count(*) filter (where s.fulfilment_kind <> f.fulfilment_kind or s.face_value_cents <> f.face_value_cents
                               or s.estimated_cost_cents <> f.estimated_cost_cents),
         count(*)
    into v_mismatch, v_matched
    from public.benefit_shadow_evaluations s
    join public.benefit_fulfilments f
      on f.business_id = s.business_id and f.canonical_benefit_key = s.would_be_canonical_key
   where s.business_id = p_business and s.source_engine = p_engine;
  return jsonb_build_object('engine', p_engine, 'matched', coalesce(v_matched,0),
    'shadow_only', v_shadow_only, 'live_only', v_live_only, 'mismatches', coalesce(v_mismatch,0),
    'clean', (v_shadow_only = 0 and v_live_only = 0 and coalesce(v_mismatch,0) = 0));
end $$;

--
-- Name: compile_program_rules(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.compile_program_rules(p_version uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  delete from public.program_rules_compiled where config_version_id = p_version;
  insert into public.program_rules_compiled(
    rule_id, program_rule_id, config_version_id, business_id, schema_version, when_event, active, compiled, rule_hash)
  select pr.rule_id, pr.id, pr.config_version_id, pr.business_id, pr.schema_version, pr.when_event, pr.active,
         app.program_rule_canonical(jsonb_build_object(
           'schema_version', pr.schema_version, 'when_event', pr.when_event,
           'if_conditions', pr.if_conditions, 'then_effects', pr.then_effects,
           'with_params', pr.with_params, 'during_schedule', pr.during_schedule, 'using_stacking', pr.using_stacking)),
         pr.rule_hash
    from public.program_rules pr
   where pr.config_version_id = p_version;
end $$;

--
-- Name: consultant_accrual_guard_v78(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.consultant_accrual_guard_v78() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if tg_op='DELETE' then
    raise exception 'consultant commission accruals are not deleted'
      using errcode='restrict_violation';
  end if;
  if (
    new.id,new.attribution_id,new.consultant_id,new.business_id,new.invoice_id,
    new.provider_invoice_id,new.policy_id,new.tier_snapshot,new.commission_phase,
    new.onboarding_started_at,new.invoice_paid_at,new.eligible_at,
    new.basis_cents,new.rate_bps,new.commission_cents,new.currency,new.created_at
  ) is distinct from (
    old.id,old.attribution_id,old.consultant_id,old.business_id,old.invoice_id,
    old.provider_invoice_id,old.policy_id,old.tier_snapshot,old.commission_phase,
    old.onboarding_started_at,old.invoice_paid_at,old.eligible_at,
    old.basis_cents,old.rate_bps,old.commission_cents,old.currency,old.created_at
  ) then
    raise exception 'consultant accrual snapshot is immutable'
      using errcode='restrict_violation';
  end if;
  if not (
    (old.status='accrued' and new.status in ('approved','forfeited'))
    or (old.status='approved' and new.status in ('paid','forfeited'))
    or (old.status=new.status)
  ) then
    raise exception 'invalid consultant accrual lifecycle transition'
      using errcode='restrict_violation';
  end if;
  return new;
end
$$;

--
-- Name: consultant_anniversary_qualified_v78(uuid, timestamp with time zone); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.consultant_anniversary_qualified_v78(p_business uuid, p_anniversary timestamp with time zone) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  select coalesce((
    select case
      when subscription.billing_provider='stripe' then exists(
        select 1
          from public.billing_provider_invoices invoice
         where invoice.business_id=p_business
           and invoice.paid_normalized
           and invoice.paid_at>=p_anniversary
      )
      else subscription.status='active'
    end
      from public.subscriptions subscription
     where subscription.business_id=p_business
  ),false)
$$;

