--
-- Name: customer_communication_identity_v263(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.customer_communication_identity_v263() RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_identity uuid;
begin
  if v_actor is null then
    raise exception 'authenticated customer session required' using errcode = '28000';
  end if;
  select identity.id into v_identity
    from public.customer_identities identity
   where identity.auth_user_id = v_actor
     and identity.status = 'active'
   limit 1;
  if v_identity is null then
    raise exception 'active customer account required' using errcode = '42501';
  end if;
  return v_identity;
end;
$$;

