--
-- Name: detect_double_earn_v309(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.detect_double_earn_v309() RETURNS TABLE(sale_id uuid, programme_id uuid, earns bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  -- Two shapes of the same defect, deduplicated by UNION (a group that is both duplicated and
  -- untagged produces the identical tuple from both arms).
  --
  -- 1. More than one earn row for the same (sale, programme). Impossible today — the v2
  --    points_earn_once_per_sale index refuses a second earn for a sale at all — and the whole
  --    reason this query exists is that W5 drops that index and replaces it with the
  --    per-programme one, at which point this is the only thing watching.
  select ledger.sale_id, ledger.programme_id, count(*)::bigint
    from public.points_ledger ledger
   where ledger.entry_type = 'earn'
     and ledger.sale_id is not null
   group by ledger.sale_id, ledger.programme_id
  having count(*) > 1
  union
  -- 2. A sale-linked row that arrived UNTAGGED. programme_id is nullable through W4, so a writer
  --    the tag trigger does not cover fails open by one row instead of erroring — and shows up
  --    here. (The v20 write guard admits sale_id only on 'earn' rows, v20:698-707, so this arm
  --    reports earn rows today; it is deliberately not filtered on entry_type so that a future
  --    sale-linked entry type cannot slip past it.)
  select ledger.sale_id, ledger.programme_id, count(*)::bigint
    from public.points_ledger ledger
   where ledger.sale_id is not null
     and ledger.programme_id is null
   group by ledger.sale_id, ledger.programme_id
$$;

--
-- Name: FUNCTION detect_double_earn_v309(); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.detect_double_earn_v309() IS 'v309 W3 standing detector (plan §6 control 5): sale-linked points_ledger earn rows that are either duplicated within one (sale, programme) or untagged. SELECT-only, no writes, no side effects. Must return ZERO rows on a healthy database; it is asserted empty by this migration, by db/tests/v309_ledger_programme_tag.sql and by every later wave. It exists because W5 drops the v2 points_earn_once_per_sale index — until then it is a tripwire on a condition the database already makes impossible, which is exactly when a detector should be installed.';

--
-- Name: detect_programme_pot_split_v310(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.detect_programme_pot_split_v310() RETURNS TABLE(business_id uuid, business_name text, distinct_tags integer, rows_off_current bigint, negative_tag_pots integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  select b.id, b.name,
         count(distinct pl.programme_id)::int,
         count(*) filter (
           where pl.programme_id is distinct from
                 app.resolve_ledger_programme_v309(pl.business_id)),
         (select count(*)::int from (
            select pl2.client_id, pl2.programme_id, sum(pl2.points) s
              from public.points_ledger pl2
             where pl2.business_id = b.id
             group by 1,2) g where g.s < 0)
    from public.points_ledger pl
    join public.businesses b on b.id = pl.business_id
   group by b.id, b.name
  having count(distinct pl.programme_id) > 1
      or count(*) filter (
           where pl.programme_id is distinct from
                 app.resolve_ledger_programme_v309(pl.business_id)) > 0;
$$;

--
-- Name: FUNCTION detect_programme_pot_split_v310(); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.detect_programme_pot_split_v310() IS 'v310 W4a standing detector — SUPERSEDED BY app.detect_programme_pot_split_v312() at W5b. Kept installed so V310''s acceptance evidence stays reproducible. Its count(distinct programme_id) > 1 arm reports a FACT, not a defect, once a pot migration has run: history keeps the old tag by design, because points_ledger is append-only.';

--
-- Name: detect_programme_pot_split_v312(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.detect_programme_pot_split_v312() RETURNS TABLE(business_id uuid, business_name text, client_id uuid, programme_id uuid, ledger_points bigint, batch_remaining bigint, defect text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  with led as (
    select pl.business_id, pl.client_id, pl.programme_id, sum(pl.points)::bigint as points
      from public.points_ledger pl
     group by 1,2,3
  ), bat as (
    select pb.business_id, pb.client_id, pb.programme_id, sum(pb.remaining)::bigint as remaining
      from public.points_batches pb
     group by 1,2,3
  ), joined as (
    select coalesce(led.business_id, bat.business_id)   as business_id,
           coalesce(led.client_id, bat.client_id)       as client_id,
           coalesce(led.programme_id, bat.programme_id) as programme_id,
           coalesce(led.points, 0)                      as points,
           coalesce(bat.remaining, 0)                   as remaining
      from led
      full join bat
        on bat.business_id = led.business_id
       and bat.client_id = led.client_id
       and bat.programme_id = led.programme_id
  )
  select j.business_id, b.name, j.client_id, j.programme_id, j.points, j.remaining,
         case when j.points < 0 and j.points <> j.remaining then 'negative_pot_and_parity'
              when j.points < 0 then 'negative_pot'
              else 'parity' end
    from joined j
    join public.businesses b on b.id = j.business_id
   where j.points < 0
      or j.points <> j.remaining;
$$;

--
-- Name: FUNCTION detect_programme_pot_split_v312(); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.detect_programme_pot_split_v312() IS 'v312 W5b standing detector, superseding app.detect_programme_pot_split_v310(). For every (business, client, programme): the ledger pot must not be negative and must equal sum(points_batches.remaining) — the programme-scoped form of the v34:685-688 invariant. count(distinct programme_id) > 1 is deliberately NOT a defect here: after a legitimate pot migration a firm permanently carries history under the old programme and its pot under the new one, and the W4a detector would alarm forever on exactly the firms W5 fixed (V309 standing invariant 4). Must return ZERO rows on a healthy database. It has NO "exclude firms with an open migration" arm, and that is the pinned contract, not an omission: app.migrate_programme_pot_v312 retags each client''s batches inside the same loop iteration as that client''s transfer pair, so a half-finished migration is coherent at every commit boundary. Zero rows is therefore the correct answer DURING a migration too, and an exclusion would have blinded the standing detector for as long as a row stayed open — including one wedged ''running'' by a crashed worker. The conservative answer for READERS lives in app.programme_balance_scope_v312 instead.';

--
-- Name: detect_spine_legacy_divergence_v314(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.detect_spine_legacy_divergence_v314() RETURNS TABLE(business_id uuid, business_name text, kind text, spine_active boolean, legacy_running boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  select business.id, business.name, model.kind, spine.active, model.running
    from public.businesses business
    cross join lateral app.business_programmes_v307(business.id) model
    join public.business_programmes spine
      on spine.business_id = business.id and spine.kind = model.kind
   where spine.active is distinct from model.running
   order by business.id, spine.kind
$$;

--
-- Name: FUNCTION detect_spine_legacy_divergence_v314(); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.detect_spine_legacy_divergence_v314() IS 'v314 W6i1: every (business, programme) where the SPINE and the pre-inversion legacy derivation disagree. Asserted EMPTY once, at apply, as proof that the inversion changed no firm''s behaviour on the day it landed. A REPORT AND NEVER AN ASSERTION thereafter: the first owner who switches a programme independently of loyalty_model makes it non-empty by design, and that is the product working.';

--
-- Name: domain_events_guard(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.domain_events_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  raise exception 'domain_events is immutable and append-only' using errcode = 'restrict_violation';
  return null;
end $$;

--
-- Name: effective_platform_module_mode_v94(uuid, uuid, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.effective_platform_module_mode_v94(p_business uuid, p_branch uuid, p_module text) RETURNS TABLE(mode text, source text, version bigint)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_row public.platform_module_overrides_v94%rowtype;
  v_inherit_version bigint;
begin
  -- v219: the blanket inventory disable is gone. Products now follow the business's own
  -- enabled_modules like every other module, via the sector_entitlement branch below.
  if p_module='customerintel' then
    return query select 'disabled'::text,'global_platform_only_policy'::text,null::bigint;
    return;
  end if;
  if p_branch is not null then
    select * into v_row
    from public.platform_module_overrides_v94 override_row
    where override_row.business_id=p_business
      and override_row.branch_scope=p_branch
      and override_row.module_key=p_module;
    if found and v_row.mode<>'inherit' then
      return query select v_row.mode,'branch_override'::text,v_row.version;
      return;
    elsif found then
      v_inherit_version:=v_row.version;
    end if;
  end if;
  select * into v_row
  from public.platform_module_overrides_v94 override_row
  where override_row.business_id=p_business
    and override_row.branch_scope is null
    and override_row.module_key=p_module;
  if found and v_row.mode<>'inherit' then
    return query select v_row.mode,'firm_override'::text,v_row.version;
    return;
  elsif found then
    v_inherit_version:=greatest(
      coalesce(v_inherit_version,0),v_row.version
    );
  end if;
  return query
  select case when p_module=any(business.enabled_modules)
      then 'rw' else 'disabled' end,
    'sector_entitlement'::text,
    v_inherit_version
  from public.businesses business
  where business.id=p_business;
end
$$;

--
-- Name: effective_tax_bps(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.effective_tax_bps(p_branch uuid) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  select coalesce(br.tax_rate_bps, b.tax_rate_bps)
  from public.branches br
  join public.businesses b on b.id = br.business_id
  where br.id = p_branch
$$;

--
-- Name: emit_domain_event(uuid, text, text, uuid, uuid, timestamp with time zone, uuid, jsonb); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.emit_domain_event(p_business uuid, p_event_type text, p_source_operation_id text, p_subject_client uuid, p_subject_identity uuid, p_occurred timestamp with time zone, p_config_version uuid, p_payload jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_id uuid; v_payload jsonb := coalesce(p_payload, '{}'::jsonb);
begin
  insert into public.domain_events(
    business_id, event_type, schema_version, source_operation_id, subject_client_id,
    subject_identity_id, occurred_at, config_version_id, payload, payload_hash)
  values(p_business, p_event_type, 1, p_source_operation_id, p_subject_client,
    p_subject_identity, coalesce(p_occurred, now()), p_config_version, v_payload,
    app.ps1b_sha256(v_payload::text))
  on conflict (business_id, event_type, source_operation_id, schema_version) do nothing
  returning event_id into v_id;
  return v_id;
end $$;

--
-- Name: emit_referral_qualified_v322(uuid, uuid, uuid, uuid, integer, uuid, timestamp with time zone, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.emit_referral_qualified_v322(p_business uuid, p_referral uuid, p_referrer uuid, p_referred uuid, p_points integer, p_ledger uuid, p_occurred_at timestamp with time zone, p_config_version uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_cut text;
  v_value integer := 0;
  v_confidence text := 'low';
  v_config uuid;
begin
  -- public.sales.config_version_id is NULLABLE while benefit_fulfilments.config_version_id is NOT
  -- NULL, so the fulfilment row needs a version and the sale may not carry one. The old credit-side
  -- trigger never met this: app.stamp_config_version fills the column on every credit_ledger row
  -- before the emitter reads it. Fall back to the business's active version, and when there is not
  -- one, record NO fulfilment rather than abort a customer's sale over an accounting row. The
  -- domain event has a nullable version and is emitted either way.
  select coalesce(p_config_version, b.active_config_version_id) into v_config
    from public.businesses b where b.id = p_business;

  select case when coalesce(lp.reward_credit_cents,0) > 0 and coalesce(lp.redeem_points,0) > 0
              then round(p_points::numeric * lp.reward_credit_cents / lp.redeem_points)::integer
              else 0 end
    into v_value
    from public.loyalty_programs lp
   where lp.business_id = p_business
   limit 1;
  v_value := coalesce(v_value, 0);
  if v_value > 0 then v_confidence := 'high'; end if;

  perform app.emit_domain_event(p_business, 'referral.qualified',
    'referral_qualify:' || p_referral::text,
    p_referred, null, p_occurred_at, p_config_version,
    jsonb_build_object('referral_id', p_referral, 'referrer_client_id', p_referrer,
      'referred_client_id', p_referred, 'reward_points', p_points,
      'points_ledger_id', p_ledger));

  select cutover_status into v_cut from public.benefit_registry
   where business_id = p_business and source_engine = 'referral';
  if v_cut in ('shadow','studio') and v_config is not null then
    insert into public.benefit_fulfilments(
      business_id, canonical_benefit_key, source_engine, fulfilment_kind, client_id, detail_ref,
      face_value_cents, estimated_cost_cents, cost_basis, cost_confidence, config_version_id,
      occurred_at)
    values(p_business, 'referral:' || p_referral::text, 'referral', 'referral_reward',
      p_referrer, p_ledger, v_value, v_value, 'bonus_face', v_confidence, v_config,
      p_occurred_at)
    on conflict (business_id, canonical_benefit_key) do nothing;
  end if;
end
$$;

--
-- Name: FUNCTION emit_referral_qualified_v322(p_business uuid, p_referral uuid, p_referrer uuid, p_referred uuid, p_points integer, p_ledger uuid, p_occurred_at timestamp with time zone, p_config_version uuid); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.emit_referral_qualified_v322(p_business uuid, p_referral uuid, p_referrer uuid, p_referred uuid, p_points integer, p_ledger uuid, p_occurred_at timestamp with time zone, p_config_version uuid) IS 'v322: the referral.qualified domain event and the shadow benefit_fulfilments row that app.trg_emit_referral_qualified used to write off a credit_ledger insert. The payout is points now, so the trigger no longer fires and the referral block calls this instead.';

--
-- Name: end_sales_backfill(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.end_sales_backfill() RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  insert into audit_log (business_id, actor, action, entity, entity_id, detail)
  values (null, auth.uid(), 'SALES_BACKFILL_WINDOW_CLOSE', 'sales', null,
          jsonb_build_object('migration', nullif(current_setting('app.sales_backfill', true), ''),
                             'db_user', current_user, 'closed_at', now()));
  perform set_config('app.sales_backfill', '', true);
end $$;

--
-- Name: enforce_branch_module_row_v94(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.enforce_branch_module_row_v94() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if auth.uid() is null or app.is_super_admin() then
    return new;
  end if;
  perform app.require_branch_module_v94(
    new.business_id,new.branch_id,tg_argv[0],tg_argv[1]
  );
  if tg_nargs>=4 and (
    tg_nargs=4
    or to_jsonb(new)->>'kind'=tg_argv[4]
  ) then
    perform app.require_branch_module_v94(
      new.business_id,new.branch_id,tg_argv[2],tg_argv[3]
    );
  end if;
  return new;
end
$$;

--
-- Name: enforce_customer_capacity_v124(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.enforce_customer_capacity_v124() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_capacity integer;
  v_current_customer_count integer;
begin
  perform pg_advisory_xact_lock(hashtextextended('nestly:v124:capacity:'||new.business_id::text,0));
  select terms.customer_capacity into v_capacity
    from public.billing_subscription_terms_v124 terms
    join public.subscriptions subscription using(business_id)
   where terms.business_id=new.business_id
     and terms.pricing_model='v124_customer_capacity'
     and subscription.status in ('trialing','active','past_due','unpaid','paused');
  if v_capacity is null then return new; end if;
  select count(*)::integer into v_current_customer_count
    from public.clients client where client.business_id=new.business_id;
  if v_current_customer_count >= v_capacity then
    raise exception 'customer capacity reached; increase the subscription capacity before adding another customer'
      using errcode='check_violation';
  end if;
  return new;
end
$$;

--
-- Name: enforce_loyalty_redemption_branch_v94(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.enforce_loyalty_redemption_branch_v94() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_branch uuid;
begin
  if auth.uid() is null or app.is_super_admin() then
    return new;
  end if;
  v_branch:=nullif(
    new.eligibility_snapshot#>>'{selected,branch_id}',''
  )::uuid;
  if v_branch is null then
    raise exception 'active_branch_required' using errcode='42501';
  end if;
  perform app.require_branch_module_v94(
    new.business_id,v_branch,'loyalty','rw'
  );
  return new;
end
$$;

--
-- Name: enforce_redemption_completion_branch_v94(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.enforce_redemption_completion_branch_v94() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_branch uuid;
begin
  if auth.uid() is null or app.is_super_admin()
     or old.status<>'pending' or new.status<>'completed' then
    return new;
  end if;
  v_branch:=nullif(new.completion_result->>'branch_id','')::uuid;
