end
$$;

--
-- Name: enforce_sale_reversal_bounds(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.enforce_sale_reversal_bounds() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare o public.sales%rowtype; v_reversed integer;
begin
  if new.reversal_of is null then return new; end if;
  select * into o from public.sales
   where id = new.reversal_of and business_id = new.business_id;
  if not found then raise exception 'original sale not found for reversal %', new.id; end if;
  if o.reversal_of is not null then raise exception 'cannot reverse a reversal sale %', o.id; end if;
  if -new.amount_cents <> o.amount_cents then
    raise exception 'full reversal required: expected %, got %', o.amount_cents, -new.amount_cents;
  end if;
  if new.amount_cents = 0 and not exists (
    select 1 from public.package_session_reversals pr
     join public.package_session_consumptions pc on pc.id = pr.consumption_id
     where pr.business_id = new.business_id and pr.original_sale_id = o.id
       and pr.reversal_sale_id = new.id and pc.sale_id = o.id
  ) then
    raise exception 'zero-dollar reversal requires exact package session provenance' using errcode = '42501';
  end if;
  select coalesce(-sum(r.amount_cents),0)::integer into v_reversed
    from public.sales r where r.business_id=o.business_id and r.reversal_of=o.id;
  if v_reversed > o.amount_cents then raise exception 'reversal exceeds original sale'; end if;
  return new;
end $$;

--
-- Name: enforce_self_serve_loyalty_bundle_v132(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.enforce_self_serve_loyalty_bundle_v132() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if not exists(
    select 1 from public.sector_bundle_versions bundle
     where bundle.id=new.bundle_version_id
       and bundle.sector_key=new.sector_key
       and bundle.status='published'
       and 'loyalty'=any(bundle.modules)
  ) then
    raise exception 'self-service launch requires a published Loyalty-capable sector'
      using errcode='23514';
  end if;
  return new;
end
$$;

--
-- Name: enforce_subscription_no_gst_v125(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.enforce_subscription_no_gst_v125() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if tg_table_name='subscriptions'
       and coalesce((to_jsonb(new)->>'period_tax_cents')::integer,0)<>0 then
      raise exception 'V125 GST not charged: subscription tax must be zero'
        using errcode='23514';
    elsif tg_table_name='billing_provider_invoices'
       and coalesce((to_jsonb(new)->>'tax_cents')::integer,0)<>0 then
      raise exception 'V125 GST not charged: invoice tax must be zero'
        using errcode='23514';
    elsif tg_table_name='billing_payment_attempts'
       and coalesce((to_jsonb(new)->>'tax_cents')::integer,0)<>0 then
      raise exception 'V125 GST not charged: payment-attempt tax must be zero'
        using errcode='23514';
    elsif tg_table_name='billing_adjustments'
       and coalesce((to_jsonb(new)->>'tax_cents')::integer,0)<>0 then
      raise exception 'V125 GST not charged: adjustment tax must be zero'
        using errcode='23514';
  end if;
  return new;
end
$$;

--
-- Name: enqueue_due_promotion_alerts_v122(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.enqueue_due_promotion_alerts_v122() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_item record;v_total integer:=0;
begin
  for v_item in
    select content.id,'v122_promotion_new'::text source_kind
    from public.business_customer_content_v95 content
    where content.content_type='offer'
      and content.metadata->>'schema'='nestly.promotion.v104'
      and content.active
      and content.branch_id is null
      and (content.starts_at is null or content.starts_at<=now())
      and content.ends_at>now()
      and exists(
        select 1 from public.business_media_assets_v95 asset
        where asset.business_id=content.business_id
          and asset.asset_kind='offer'
          and asset.entity_id=content.id
          and asset.customer_visible
          and asset.branch_id is null
      )
      and not exists(
        select 1 from public.promotion_alert_runs_v122 run
        where run.promotion_id=content.id
          and run.source_kind='v122_promotion_new'
          and run.source_version=coalesce(
            content.metadata->>'published_once_at','missing'
          )
      )
    union all
    select content.id,'v122_promotion_expiry'::text source_kind
    from public.business_customer_content_v95 content
    where content.content_type='offer'
      and content.metadata->>'schema'='nestly.promotion.v104'
      and content.active
      and content.branch_id is null
      and (content.starts_at is null or content.starts_at<=now())
      and content.ends_at>now()
      and content.ends_at<=now()+interval '3 days'
      and exists(
        select 1 from public.business_media_assets_v95 asset
        where asset.business_id=content.business_id
          and asset.asset_kind='offer'
          and asset.entity_id=content.id
          and asset.customer_visible
          and asset.branch_id is null
      )
      and not exists(
        select 1 from public.promotion_alert_runs_v122 run
        where run.promotion_id=content.id
          and run.source_kind='v122_promotion_expiry'
          and run.source_version=coalesce(
            content.metadata->>'published_once_at','missing'
          )||':'||content.ends_at::text
      )
  loop
    v_total:=v_total+app.enqueue_promotion_alert_v122(
      v_item.id,v_item.source_kind
    );
  end loop;
  return v_total;
end
$$;

--
-- Name: enqueue_programme_pot_migration_v312(uuid, uuid, uuid, integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.enqueue_programme_pot_migration_v312(p_business uuid, p_from uuid, p_to uuid, p_inline_limit integer DEFAULT 500) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_id uuid;
  v_clients integer;
  v_done integer;
begin
  if p_business is null or p_from is null or p_to is null or p_from = p_to then
    return null;
  end if;

  -- Counted over the SAME set app.migrate_programme_pot_v312 processes (ledger pot OR open
  -- batch), or the inline/async decision would be made on a smaller population than the
  -- work actually done and a firm just over the bound would run inline anyway.
  select count(*) into v_clients
    from (select pl.client_id
            from public.points_ledger pl
           where pl.business_id = p_business and pl.programme_id = p_from
           group by pl.client_id
          having sum(pl.points) <> 0
          union
          select pb.client_id
            from public.points_batches pb
           where pb.business_id = p_business and pb.programme_id = p_from
             and pb.remaining > 0) affected;

  if v_clients = 0 then
    return null;                                  -- nothing to move
  end if;

  -- THE ARBITER IS NAMED (the same doctrine v311 §2 applies to the earn loop's ON CONFLICT).
  -- Arbiter-less DO NOTHING absorbs a conflict from ANY constraint on the table, so a future
  -- index — or the primary key, reachable the day a caller supplies an id — would silently
  -- return NULL here and be read as "one already open; the worker owns it", skipping a
  -- migration that was never enqueued. Naming the partial unique index means this statement
  -- can only ever absorb the intended conflict, and fails at plan time if
  -- programme_pot_migrations_one_open is absent.
  insert into public.programme_pot_migrations(business_id, from_programme_id, to_programme_id, status)
  values (p_business, p_from, p_to, 'running')
  on conflict (business_id) where status in ('pending','running') do nothing
  returning id into v_id;
  if v_id is null then
    return null;                                  -- one already open; the worker owns it
  end if;

  if v_clients <= greatest(coalesce(p_inline_limit, 500), 1) then
    -- Small enough to be coherent instantly, with no window at all. Every production firm
    -- today is far under this bound (max 25 ledger rows).
    v_done := app.migrate_programme_pot_v312(p_business, p_from, p_to, p_inline_limit);
    update public.programme_pot_migrations
       set status = 'complete', completed_at = now(), clients_done = v_done
     where id = v_id;
    if exists (select 1 from app.detect_programme_pot_split_v312() d
                where d.business_id = p_business) then
      raise exception 'v312: pot migration left business % incoherent', p_business
        using errcode = 'XX001';
    end if;
  else
    update public.programme_pot_migrations set status = 'pending' where id = v_id;
  end if;
  return v_id;
end
$$;

--
-- Name: FUNCTION enqueue_programme_pot_migration_v312(p_business uuid, p_from uuid, p_to uuid, p_inline_limit integer); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.enqueue_programme_pot_migration_v312(p_business uuid, p_from uuid, p_to uuid, p_inline_limit integer) IS 'v312 W5b: the ONE entry point for "this business''s accruing programme changed identity". Runs the transfer inline when the affected-client count is within the bound (instant coherence, no window) and otherwise leaves a pending row for the bounded cron worker. W6 calls this directly when per-programme active flags replace loyalty_model, so a switchboard flip routes through the same coherence machinery as a model switch.';

--
-- Name: enqueue_promotion_alert_v122(uuid, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.enqueue_promotion_alert_v122(p_promotion uuid, p_source_kind text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_content public.business_customer_content_v95%rowtype;
  v_source_version text;
  v_label text;
  v_inserted integer:=0;
begin
  if p_source_kind not in ('v122_promotion_new','v122_promotion_expiry') then
    raise exception 'unsupported promotion alert kind' using errcode='22023';
  end if;
  select * into v_content
  from public.business_customer_content_v95 content
  where content.id=p_promotion
    and content.content_type='offer'
    and content.metadata->>'schema'='nestly.promotion.v104'
    and content.active
    and content.branch_id is null
    and (content.starts_at is null or content.starts_at<=now())
    and content.ends_at>now();
  if not found then return 0; end if;
  if not exists(
    select 1 from public.business_media_assets_v95 asset
    where asset.business_id=v_content.business_id
      and asset.asset_kind='offer'
      and asset.entity_id=v_content.id
      and asset.customer_visible
      and asset.branch_id is null
  ) then
    return 0;
  end if;
  v_source_version:=case when p_source_kind='v122_promotion_new'
    then coalesce(v_content.metadata->>'published_once_at','missing')
    else coalesce(v_content.metadata->>'published_once_at','missing')
      ||':'||v_content.ends_at::text end;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'v122:promotion-alert:'||v_content.id::text||':'||p_source_kind,0
    )
  );
  if exists(
    select 1 from public.promotion_alert_runs_v122 run
    where run.promotion_id=v_content.id
      and run.source_kind=p_source_kind
      and run.source_version=v_source_version
  ) then
    return 0;
  end if;

  select coalesce(
    (
      select nullif(btrim(left(copy_row.name,200)),'')
      from public.business_localized_copy_v95 copy_row
      where copy_row.business_id=v_content.business_id
        and copy_row.entity_type='offer'
        and copy_row.entity_id=v_content.id
      order by (copy_row.locale='en') desc,copy_row.locale
      limit 1
    ),
    'Promotion'
  ) into v_label;

  with recipients as(
    select
      link.business_id,link.identity_id,link.auth_user_id,
      link.id as link_id,link.client_id
    from public.customer_links link
    left join public.customer_notification_preferences preference
      on preference.business_id=link.business_id
     and preference.identity_id=link.identity_id
     and preference.auth_user_id=link.auth_user_id
     and preference.link_id=link.id
     and preference.channel='in_app'
     and preference.topic='promotion_alerts'
    where link.business_id=v_content.business_id
      and link.state='verified'
      and coalesce(preference.opted_in,true)
      and app.customer_communication_allows_v263(
        link.identity_id,'business_offers','in_app'
      )
  ),
  enqueued as(
    insert into public.customer_in_app_inbox_events(
      business_id,identity_id,auth_user_id,link_id,client_id,
      source_kind,topic,route_key,source_fingerprint,dedupe_key,
      title,body,deadline_at
    )
    select
      recipient.business_id,recipient.identity_id,recipient.auth_user_id,
      recipient.link_id,recipient.client_id,
      p_source_kind,'promotion_alerts','wallet_business',
      app.c46_sha256_hex((jsonb_build_object(
        'promotion_id',v_content.id,'source_kind',p_source_kind,
        'published_once_at',v_content.metadata->>'published_once_at'
      ) || case when p_source_kind='v122_promotion_expiry'
        then jsonb_build_object('ends_at',v_content.ends_at)
        else '{}'::jsonb end)::text),
      app.c46_sha256_hex((jsonb_build_object(
        'business_id',recipient.business_id,'identity_id',recipient.identity_id,
        'promotion_id',v_content.id,'source_kind',p_source_kind,
        'published_once_at',v_content.metadata->>'published_once_at'
      ) || case when p_source_kind='v122_promotion_expiry'
        then jsonb_build_object('ends_at',v_content.ends_at)
        else '{}'::jsonb end)::text),
      case when p_source_kind='v122_promotion_new'
        then 'New promotion available' else 'Promotion ending soon' end,
      case when p_source_kind='v122_promotion_new'
        then 'Open this programme to view the latest promotion.'
        else 'Open this programme before the current promotion ends.' end,
      v_content.ends_at
    from recipients recipient
    on conflict(identity_id,dedupe_key) do nothing
    returning id,business_id,identity_id,link_id,client_id
  ),
  recorded as(
    insert into public.campaign_send_records_v255(
      business_id,campaign_kind,campaign_ref_id,send_kind,campaign_label,
      channel,inbox_event_id,identity_id,link_id,client_id
    )
    select
      enqueued.business_id,'promotion',v_content.id,p_source_kind,v_label,
      'in_app',enqueued.id,enqueued.identity_id,enqueued.link_id,
      enqueued.client_id
    from enqueued
    on conflict do nothing
    returning 1
  )
  select count(*)::integer into v_inserted from enqueued;

  if v_inserted>0 then
    insert into public.promotion_alert_runs_v122(
      promotion_id,source_kind,source_version
    ) values(
      v_content.id,p_source_kind,v_source_version
    ) on conflict do nothing;
  end if;
  return v_inserted;
end
$$;

--
-- Name: FUNCTION enqueue_promotion_alert_v122(p_promotion uuid, p_source_kind text); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.enqueue_promotion_alert_v122(p_promotion uuid, p_source_kind text) IS 'Fans out promotion alerts and only then burns the watermark, so a run against zero opted-in recipients stays repeatable.';

--
-- Name: ensure_platform_firm_snapshot_v88(uuid, timestamp with time zone, boolean); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.ensure_platform_firm_snapshot_v88(p_actor uuid, p_snapshot_at timestamp with time zone, p_allow_create boolean) RETURNS timestamp with time zone
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_expires_at timestamptz;
  v_created boolean:=false;
begin
  if p_actor is null or p_snapshot_at is null then
    raise exception 'actor and snapshot token are required' using errcode='22023';
  end if;

  select snapshot.expires_at into v_expires_at
  from app.platform_firm_snapshots_v88 snapshot
  where snapshot.actor_id=p_actor and snapshot.snapshot_at=p_snapshot_at;
  if found then
    if v_expires_at<=clock_timestamp() then
      raise exception 'firm snapshot token has expired' using errcode='22023';
    end if;
    return v_expires_at;
  end if;
  if not p_allow_create then
    raise exception 'firm snapshot token was not found' using errcode='22023';
  end if;

  delete from app.platform_firm_snapshots_v88 snapshot
  where snapshot.actor_id=p_actor and snapshot.expires_at<=clock_timestamp();

  insert into app.platform_firm_snapshots_v88(actor_id,snapshot_at)
  values(p_actor,p_snapshot_at)
  on conflict(actor_id,snapshot_at) do nothing
  returning expires_at into v_expires_at;
  v_created:=found;

  if v_created then
    insert into app.platform_firm_snapshot_rows_v88(
      actor_id,snapshot_at,row_id,updated_at,days_unattended,
      attention_due,attention_severity,lane_key,sector_key,industry,
      onboarding_status,subscription_status,search_text,payload
    )
    select
      p_actor,p_snapshot_at,firm.row_id,firm.updated_at,firm.days_unattended,
      coalesce(firm.attention_due,false),firm.attention_severity,firm.lane_key,
      firm.sector_key,firm.industry,firm.onboarding_status,
      firm.subscription_status,
      lower(concat_ws(' ',firm.name,firm.legal_name,firm.registration_number,
        firm.sector_key,firm.industry,firm.boss_name,firm.boss_email,firm.boss_phone)),
      to_jsonb(firm)||jsonb_build_object(
        'attention_due',coalesce(firm.attention_due,false)
      )
    from app.platform_firm_rows_v88(p_snapshot_at) firm;
  else
    select snapshot.expires_at into v_expires_at
    from app.platform_firm_snapshots_v88 snapshot
    where snapshot.actor_id=p_actor and snapshot.snapshot_at=p_snapshot_at;
  end if;

  if v_expires_at is null or v_expires_at<=clock_timestamp() then
    raise exception 'firm snapshot token is unavailable' using errcode='22023';
  end if;
  return v_expires_at;
end
$$;

--
-- Name: FUNCTION ensure_platform_firm_snapshot_v88(p_actor uuid, p_snapshot_at timestamp with time zone, p_allow_create boolean); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.ensure_platform_firm_snapshot_v88(p_actor uuid, p_snapshot_at timestamp with time zone, p_allow_create boolean) IS 'v94 forward repair: v88 firm snapshots fail-close nullable attention predicates to false in both indexed columns and frozen JSON payloads.';

--
-- Name: expire_stale_bookings(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.expire_stale_bookings() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare r record; n int := 0;
begin
  for r in
    update public.booking_requests
       set status = 'expired'
     where status in ('new','pending')
       and expires_at is not null
       and expires_at < now()
    returning id, business_id, name, table_type_id
  loop
    n := n + 1;
    insert into public.notifications(business_id, kind, title, body, ref_table, ref_id)
    values (r.business_id, 'booking_expired', 'Booking hold expired',
            coalesce(r.name,'A guest') || ' — held table released.',
            'booking_requests', r.id);
    if exists (
      select 1 from public.waitlist w
       where w.business_id = r.business_id and w.status = 'waiting'
         and (r.table_type_id is null or w.table_type_id is null or w.table_type_id = r.table_type_id)
    ) then
      insert into public.notifications(business_id, kind, title, body, ref_table, ref_id)
      values (r.business_id, 'waitlist_ready', 'A table opened up',
              'A held table was released — contact your waitlist.',
              'booking_requests', r.id);
    end if;
  end loop;
  return n;
end $$;

--
-- Name: financial_operation_write_guard(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.financial_operation_write_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_token text;
begin
  if tg_op = 'INSERT' then
    v_token := nullif(current_setting('app.financial_operation_insert_id', true), '');
    if v_token is distinct from new.id::text then
      raise exception 'financial operations may only be reserved by a financial RPC'
        using errcode = '42501';
    end if;
    if (new.operation_type = 'quick_sale' and new.sale_id is not null)
       or (new.operation_type <> 'quick_sale' and new.sale_id is null) then
      raise exception 'financial operation reservation has an invalid sale lifecycle'
        using errcode = 'check_violation';
    end if;
    return new;
  end if;

  if tg_op = 'DELETE' then
    raise exception 'financial_operations is append-only: DELETE is not permitted'
      using errcode = 'restrict_violation';
  end if;

  v_token := nullif(current_setting('app.financial_operation_complete_id', true), '');
  if v_token is distinct from old.id::text
     or old.status <> 'reserved'
     or new.status <> 'completed'
     or (new.id, new.business_id, new.branch_id, new.operation_type,
         new.actor, new.idempotency_key, new.request_payload, new.request_hash, new.created_at)
        is distinct from
        (old.id, old.business_id, old.branch_id, old.operation_type,
         old.actor, old.idempotency_key, old.request_payload, old.request_hash, old.created_at)
     or (
       old.operation_type = 'quick_sale'
       and (old.sale_id is not null or new.sale_id is null)
     )
     or (
       old.operation_type <> 'quick_sale'
       and new.sale_id is distinct from old.sale_id
     )
     or new.result is null
     or new.completed_at is null then
    raise exception 'financial operation % may only transition reserved -> completed', old.id
      using errcode = 'restrict_violation';
  end if;

  return new;
end $$;

--
-- Name: forbid_mutation(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.forbid_mutation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  raise exception '% is an append-only ledger: % is not permitted. Post a reversing row instead.',
    tg_table_name, tg_op;
end $$;

--
-- Name: forfeit_consultant_core_v78(uuid, timestamp with time zone, text, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.forfeit_consultant_core_v78(p_consultant uuid, p_departed_at timestamp with time zone, p_reason text, p_actor uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_count integer;
  v_row public.platform_consultants%rowtype;
begin
  if p_departed_at is null or p_departed_at>now()+interval '5 minutes'
     or nullif(btrim(p_reason),'') is null or length(p_reason)>1000 then
    raise exception 'valid consultant departure evidence is required'
      using errcode='22023';
  end if;
  select * into v_row from public.platform_consultants
   where id=p_consultant for update;
  if not found then
    raise exception 'platform consultant was not found' using errcode='22023';
  end if;
  update public.platform_consultants
     set active=false,
         departed_at=coalesce(departed_at,p_departed_at),
         updated_at=now()
   where id=p_consultant
   returning * into v_row;
  update public.consultant_commission_accruals
     set status='forfeited',forfeited_at=p_departed_at,
         forfeiture_reason=btrim(p_reason)
   where consultant_id=p_consultant and status in ('accrued','approved');
  get diagnostics v_count=row_count;
  insert into public.audit_log(
    business_id,actor,action,entity,entity_id,detail
  ) values (
    null,p_actor,'CONSULTANT_COMMISSION_FORFEITED_V78',
    'platform_consultants',p_consultant,
    jsonb_build_object(
      'departed_at',v_row.departed_at,'forfeited_accruals',v_count,
      'reason',btrim(p_reason),'previously_paid_final',true
    )
  );
  return jsonb_build_object(
    'consultant',to_jsonb(v_row)-'user_id','forfeited_accruals',v_count
  );
end
$$;

--
-- Name: gen_ref_code(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.gen_ref_code() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if new.referral_code is null then
    loop
      new.referral_code := upper(substr(md5(random()::text || clock_timestamp()::text),1,6));
      exit when not exists (select 1 from clients where referral_code = new.referral_code);
    end loop;
  end if;
  return new;
end $$;

--
-- Name: get_growth_execution_result_at_v108(uuid, timestamp with time zone); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.get_growth_execution_result_at_v108(p_execution uuid, p_as_of timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_execution public.growth_executions_v108%rowtype;
  v_t_members integer:=0;
  v_h_members integer:=0;
  v_t_buyers integer:=0;
  v_h_buyers integer:=0;
  v_t_revenue bigint:=0;
  v_h_revenue bigint:=0;
  v_t_rate numeric:=0;
  v_h_rate numeric:=0;
  v_lift numeric:=0;
  v_se numeric:=0;
  v_aov numeric:=0;
  v_estimate bigint:=0;
  v_low bigint:=0;
  v_high bigint:=0;
  v_overlap integer:=0;
  v_identity_overlap integer:=0;
  v_measurement text;
begin
  if p_as_of is null then
    raise exception 'reporting cutoff is required' using errcode='22004';
  end if;
  select * into v_execution
    from public.growth_executions_v108 execution
   where execution.id=p_execution;
  if not found then raise exception 'execution not found'; end if;
  if auth.uid() is null or (
    not app.is_super_admin()
    and (
      not app.has_perm(v_execution.business_id,'view_finance')
      or not app.can_module_read(v_execution.business_id,'retention')
    )
  ) then
    raise exception 'finance and retention access required' using errcode='42501';
  end if;
  if not app.can_see_branch(v_execution.business_id,v_execution.branch_id) then
    raise exception 'execution branch is outside actor scope' using errcode='42501';
  end if;

  with effective_members as (
    select member.*,
      app.v113_effective_client_id(member.business_id,member.client_id)
        as effective_client_id,
      row_number() over (
        partition by app.v113_effective_client_id(
          member.business_id,member.client_id
        )
        order by member.assignment_rank,member.id
      ) as identity_rank,
      count(*) over (
        partition by app.v113_effective_client_id(
          member.business_id,member.client_id
        )
      ) as identity_count
    from public.growth_execution_members_v108 member
    where member.execution_id=p_execution
  ),
  member_result as (
    select member.assignment,member.client_id,member.effective_client_id,
      member.identity_count,
      exists (
        select 1 from public.sales sale
         where sale.business_id=v_execution.business_id
           and sale.client_id is not null
           and app.v113_effective_client_id(sale.business_id,sale.client_id)
               =member.effective_client_id
           and sale.counts_as_visit
           and sale.counts_as_revenue
           and sale.reversal_of is null
           and sale.created_at<=p_as_of
           and sale.occurred_at<=p_as_of
           and (
             v_execution.branch_id is null
             or sale.branch_id=v_execution.branch_id
           )
           and sale.occurred_at>=v_execution.started_at
           and sale.occurred_at<v_execution.ends_at
           and app.v106_sale_residual_minor(sale.id,p_as_of)>0
      ) as purchased,
      coalesce((
        select sum(app.v106_sale_residual_minor(sale.id,p_as_of))
          from public.sales sale
         where sale.business_id=v_execution.business_id
           and sale.client_id is not null
           and app.v113_effective_client_id(sale.business_id,sale.client_id)
               =member.effective_client_id
           and sale.counts_as_revenue
           and sale.reversal_of is null
           and sale.created_at<=p_as_of
           and sale.occurred_at<=p_as_of
           and (
             v_execution.branch_id is null
             or sale.branch_id=v_execution.branch_id
           )
           and sale.occurred_at>=v_execution.started_at
           and sale.occurred_at<v_execution.ends_at
           and app.v106_sale_residual_minor(sale.id,p_as_of)>0
      ),0)::bigint as revenue_cents
    from effective_members member
    where member.identity_rank=1
  )
  select
    count(*) filter(where assignment='treatment'),
    count(*) filter(where assignment='holdout'),
    count(*) filter(where assignment='treatment' and purchased),
    count(*) filter(where assignment='holdout' and purchased),
    coalesce(sum(revenue_cents) filter(where assignment='treatment'),0),
    coalesce(sum(revenue_cents) filter(where assignment='holdout'),0),
    count(*) filter(where identity_count>1)
  into v_t_members,v_h_members,v_t_buyers,v_h_buyers,
       v_t_revenue,v_h_revenue,v_identity_overlap
  from member_result;

  select count(*) into v_overlap
    from public.growth_outcomes_v108 outcome
    join public.growth_execution_members_v108 member
      on member.id=outcome.execution_member_id
     and member.business_id=outcome.business_id
    join public.sales sale
      on sale.id=outcome.sale_id
     and sale.business_id=outcome.business_id
   where outcome.execution_id=p_execution
     and not outcome.causal_eligible
     and outcome.occurred_at<=p_as_of
     and app.v106_sale_residual_minor(outcome.sale_id,p_as_of)>0
     and sale.client_id is not null
     and app.v113_effective_client_id(sale.business_id,sale.client_id)
         =app.v113_effective_client_id(member.business_id,member.client_id);
  v_t_rate:=case when v_t_members>0
    then v_t_buyers::numeric/v_t_members else 0 end;
  v_h_rate:=case when v_h_members>0
    then v_h_buyers::numeric/v_h_members else 0 end;
  v_lift:=v_t_rate-v_h_rate;
  v_se:=case when v_t_members>0 and v_h_members>0 then sqrt(
    greatest(0,v_t_rate*(1-v_t_rate)/v_t_members)
    +greatest(0,v_h_rate*(1-v_h_rate)/v_h_members)
  ) else 0 end;
  v_aov:=case when v_t_buyers+v_h_buyers>0
    then (v_t_revenue+v_h_revenue)::numeric/(v_t_buyers+v_h_buyers)
    else 0 end;
  v_estimate:=round(v_lift*v_t_members*v_aov);
  v_low:=round((v_lift-1.96*v_se)*v_t_members*v_aov);
  v_high:=round((v_lift+1.96*v_se)*v_t_members*v_aov);
  v_measurement:=case
    when v_identity_overlap>0 then 'invalid_overlap'
    when v_overlap>0 then 'invalid_overlap'
    when v_t_members<v_execution.minimum_arm_size
      or v_h_members<v_execution.minimum_arm_size
      then 'inconclusive_small_sample'
    when p_as_of<v_execution.ends_at then 'provisional'
    else 'final'
  end;
  return jsonb_build_object(
    'execution_id',p_execution,'business_id',v_execution.business_id,
    'as_of',p_as_of,'status',v_execution.status,
    'window',jsonb_build_object(
      'start',v_execution.started_at,'end',v_execution.ends_at
    ),
    'method','randomized_intent_to_treat_holdout',
    'identity_attribution','v111_current_effective_identity',
    'measurement_status',v_measurement,
    'arms',jsonb_build_object(
      'treatment',jsonb_build_object(
        'members',v_t_members,'buyers',v_t_buyers,
        'conversion_rate_bps',round(v_t_rate*10000),
        'associated_revenue_cents',v_t_revenue
      ),
      'holdout',jsonb_build_object(
        'members',v_h_members,'buyers',v_h_buyers,
        'conversion_rate_bps',round(v_h_rate*10000),
        'associated_revenue_cents',v_h_revenue
      )
    ),
    'incremental_conversion_lift_bps',round(v_lift*10000),
    'estimated_incremental_revenue',case
      when v_measurement in ('invalid_overlap','inconclusive_small_sample')
        then null
      else jsonb_build_object(
        'currency',v_execution.currency,'point_estimate_cents',v_estimate,
        'low_cents',least(v_low,v_high),
        'high_cents',greatest(v_low,v_high),
        'confidence_level','approximate_95_percent'
      )
    end,
    'incremental_gross_profit',null,
    'cost',jsonb_build_object(
      'estimated_offer_cost_cents',coalesce((
        select sum(delivery.estimated_cost_cents)
          from public.growth_deliveries_v108 delivery
         where delivery.execution_id=p_execution
           and delivery.delivery_status='delivered'
      ),0),
      'actual_redeemed_cost_cents',coalesce((
        select sum(entitlement.estimated_cost_cents)
          from public.growth_entitlements_v108 entitlement
         where entitlement.execution_id=p_execution
           and entitlement.status='redeemed'
      ),0),
      'reversed_offer_cost_cents',coalesce((
        select sum(entitlement.estimated_cost_cents)
          from public.growth_entitlements_v108 entitlement
         where entitlement.execution_id=p_execution
           and entitlement.status='reversed'
      ),0)
    ),
    'overlap_outcomes',v_overlap,
    'identity_overlap_members',v_identity_overlap,
    'limitations',jsonb_build_array(
      'revenue result is not gross profit',
      'confidence interval uses a transparent normal approximation',
      'small, overlapping or identity-ambiguous experiments are suppressed'
    )
  );
end
$$;

--
-- Name: get_onboarding_core_v79(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.get_onboarding_core_v79(p_business uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  select jsonb_build_object(
    'checklist',to_jsonb(checklist),
    'business',(select jsonb_build_object('id',business.id,'name',business.name,
      'legal_name',business.legal_name,'registration_number',business.registration_number,
      'industry',business.industry,'onboarding_started_at',business.onboarding_started_at,
      'activated_at',business.activated_at,'source_prospect_id',business.source_prospect_id)
      from public.businesses business where business.id=p_business),
    'subscription',(select jsonb_build_object('status',subscription.status,
      'plan_code',subscription.plan_code,'product_code',subscription.product_code,
      'billing_cadence',subscription.billing_cadence,'seat_limit',subscription.seat_limit,
      'commercial_terms_id',subscription.commercial_terms_id)
      from public.subscriptions subscription where subscription.business_id=p_business),
    'items',coalesce((select jsonb_agg(to_jsonb(item) order by item.category,item.item_key)
      from public.business_onboarding_items item where item.business_id=p_business),'[]'::jsonb),
    'events',coalesce((select jsonb_agg(to_jsonb(event) order by event.created_at,event.id)
      from public.business_onboarding_events event where event.business_id=p_business),'[]'::jsonb),
    'owner_invitations',coalesce((select jsonb_agg(jsonb_build_object(
      'id',invitation.id,'version',invitation.version,'owner_email',invitation.owner_email,
      'status',invitation.status,'expires_at',invitation.expires_at,
      'token_last_four',invitation.token_last_four,'accepted_at',invitation.accepted_at)
      order by invitation.version desc) from public.workspace_owner_invitations invitation
      where invitation.business_id=p_business),'[]'::jsonb)
  ) from public.business_onboarding_checklists checklist where checklist.business_id=p_business
$$;

--
-- Name: growth_v108_effective_parameters(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.growth_v108_effective_parameters(p_business uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_sector text;
  v_base public.sector_policy_versions_v109%rowtype;
  v_override public.business_sector_policy_overrides_v109%rowtype;
  v_suppressions jsonb:='[]'::jsonb;
  v_availability jsonb;
  v_as_of timestamptz:=statement_timestamp();
begin
  select lower(industry) into strict v_sector
  from public.businesses where id=p_business;
  select * into v_base
  from public.sector_policy_versions_v109
  where sector_key=v_sector and policy_key='lapse_detection'
    and status='published' and effective_from<=v_as_of
    and (effective_to is null or effective_to>v_as_of)
  order by version_no desc limit 1;
  if not found then
    select * into strict v_base
    from public.sector_policy_versions_v109
    where sector_key='other' and policy_key='lapse_detection'
      and status='published' and effective_from<=v_as_of
      and (effective_to is null or effective_to>v_as_of)
    order by version_no desc limit 1;
  end if;
  select * into v_override
  from public.business_sector_policy_overrides_v109
    where business_id=p_business and policy_key='lapse_detection'
    and base_policy_id=v_base.id
    and effective_from<=v_as_of
    and (effective_to is null or effective_to>v_as_of)
  order by version_no desc limit 1;
  v_availability:=app.v109_sector_source_availability(
    p_business,v_base.sector_key,
    (v_base.parameters->>'minimum_prior_visits')::integer,v_as_of
  );
  if v_base.sector_key in ('facial','salon','massage')
     and not coalesce((v_availability->>'service_cadence')::boolean,false) then
    v_suppressions:=jsonb_build_array('unknown_service_cadence');
  elsif v_base.sector_key='fitness'
     and not coalesce((v_availability->>'membership_state')::boolean,false) then
    v_suppressions:=jsonb_build_array('membership_state_unknown');
  elsif v_base.sector_key='retail'
     and not coalesce((v_availability->>'product_cycle')::boolean,false) then
    v_suppressions:=jsonb_build_array('product_cycle_unknown');
  elsif v_base.sector_key='other' then
    v_suppressions:=jsonb_build_array('sector_not_specialized');
  end if;
  return jsonb_build_object(
    'source','sector_policy_v109',
    'lineage',jsonb_build_object(
      'requested_sector',v_sector,
      'resolved_sector',v_base.sector_key,
      'base_policy_id',v_base.id,
      'base_version_no',v_base.version_no,
      'override_id',v_override.id,
      'override_version_no',v_override.version_no
    ),
    'parameters',v_base.parameters
      ||coalesce(v_override.override_parameters,'{}'::jsonb),
    'suppression_reasons',v_suppressions,
    'source_availability',v_availability
  );
end $$;

--
-- Name: growth_v108_guard_outcome_residual(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.growth_v108_guard_outcome_residual() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if tg_op = 'DELETE'
     or pg_trigger_depth() < 2
     or (to_jsonb(new) - 'revenue_cents')
          is distinct from (to_jsonb(old) - 'revenue_cents')
     or new.revenue_cents is distinct from
          app.v106_sale_residual_minor(old.sale_id, clock_timestamp()) then
    raise exception 'growth evidence is append-only' using errcode = '23000';
  end if;
  return new;
end $$;

--
-- Name: growth_v108_guard_status(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.growth_v108_guard_status() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if tg_op = 'DELETE' then
    raise exception 'growth lifecycle rows cannot be deleted' using errcode = '23000';
  end if;
  if new.id is distinct from old.id
     or new.business_id is distinct from old.business_id
     or new.created_at is distinct from old.created_at then
    raise exception 'growth row identity is immutable' using errcode = '23000';
  end if;
  return new;
end $$;

--
-- Name: growth_v108_immutable(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.growth_v108_immutable() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  raise exception 'growth evidence is append-only' using errcode = '23000';
end $$;

--
-- Name: growth_v108_token(uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.growth_v108_token(p_identity uuid, p_business uuid, p_entitlement uuid, p_idempotency uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  select encode(extensions.hmac(
    convert_to(concat_ws(':', p_identity, p_business, p_entitlement, p_idempotency), 'UTF8'),
    secret.secret_value, 'sha256'), 'hex')
  from app.v89_token_secrets secret
  where secret.secret_key = 'growth_redemption_v108'
$$;

--
-- Name: guard_booking_customer_binding_v72(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.guard_booking_customer_binding_v72() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if old.customer_client_id is distinct from new.customer_client_id then
    raise exception 'booking customer binding is immutable' using errcode = '23514';
  end if;
  return new;
end
$$;

--
-- Name: guard_client_field_definition(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.guard_client_field_definition() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  new.field_key := lower(btrim(new.field_key));
  new.label := btrim(new.label);
  if tg_op = 'UPDATE' and new.business_id is distinct from old.business_id then
    raise exception 'client field tenant is immutable'
      using errcode = 'restrict_violation';
  end if;
  if tg_op = 'UPDATE' and new.field_key is distinct from old.field_key then
    raise exception 'client field key is immutable; create a new field'
      using errcode = 'restrict_violation';
  end if;
  if tg_op = 'UPDATE'
     and new.value_type is distinct from old.value_type
     and (exists (
       select 1 from public.client_field_values v
        where v.business_id = old.business_id
          and v.field_definition_id = old.id
     ) or exists (
       select 1 from public.client_field_options o
        where o.business_id = old.business_id
          and o.field_definition_id = old.id
     )) then
    raise exception 'client field value type is immutable after values or options exist'
      using errcode = 'restrict_violation';
  end if;
  if tg_op = 'UPDATE'
     and new.classification is distinct from old.classification
     and exists (
       select 1 from public.client_field_values v
        where v.business_id = old.business_id
          and v.field_definition_id = old.id
     ) then
    raise exception 'client field classification is immutable after values exist'
      using errcode = 'restrict_violation';
  end if;
  new.updated_at := now();
  return new;
end
$$;

--
-- Name: guard_converted_commercial_terms_v79(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.guard_converted_commercial_terms_v79() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if exists(
    select 1 from public.sme_prospects
    where id=new.prospect_id and converted_business_id is not null
  ) then
    raise exception 'commercial terms are frozen after prospect conversion' using errcode='42501';
  end if;
  return new;
end
$$;

--
-- Name: guard_converted_prospect_v79(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.guard_converted_prospect_v79() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if old.converted_business_id is not null and (
    new.current_stage_key is distinct from old.current_stage_key
    or new.assigned_consultant_id is distinct from old.assigned_consultant_id
    or new.company_id is distinct from old.company_id
  ) and coalesce(current_setting('app.v79_system_transition',true),'')<>'on' then
    raise exception 'converted prospect lifecycle is controlled by v79 onboarding' using errcode='42501';
  end if;
  return new;
end
$$;

--
-- Name: guard_converted_workspace_activation_v79(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.guard_converted_workspace_activation_v79() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if coalesce(current_setting('app.v79_system_transition', true), '') = 'on' then
    return new;
  end if;

  if tg_table_name = 'businesses' then
    if old.source_prospect_id is not null and (
      new.source_prospect_id is distinct from old.source_prospect_id
      or new.onboarding_started_at is distinct from old.onboarding_started_at
      or new.activated_at is distinct from old.activated_at
      or new.legal_name is distinct from old.legal_name
      or new.registration_number is distinct from old.registration_number
    ) then
      raise exception 'converted workspace identity and activation are controlled by v79'
        using errcode = '42501';
    end if;
  elsif tg_table_name = 'branches' then
    if old.active = false
       and new.active = true
       and exists (
         select 1
           from public.businesses business
          where business.id = new.business_id
            and business.source_prospect_id is not null
       ) then
      raise exception 'converted workspace branch activation is controlled by v79'
        using errcode = '42501';
    end if;
  else
    raise exception 'v79 conversion guard is attached to an unexpected relation'
      using errcode = '55000';
  end if;

  return new;
end
$$;

--
-- Name: guard_first_paid_evidence_v144(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.guard_first_paid_evidence_v144() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if tg_op='DELETE' or new.business_id<>old.business_id
     or new.first_paid_at>=old.first_paid_at then
    raise exception 'first-paid subscription evidence is immutable'
      using errcode='restrict_violation';
  end if;
  return new;
end
$$;

--
-- Name: guard_loyalty_branch_override_draft(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.guard_loyalty_branch_override_draft() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_version_id uuid := case when tg_op = 'DELETE' then old.config_version_id else new.config_version_id end;
  v_status text;
  v_old_status text;
begin
  select status into v_status from public.firm_config_versions where id = v_version_id;
  if tg_op = 'UPDATE' then
    select status into v_old_status
      from public.firm_config_versions
     where id = old.config_version_id;
    if old.config_version_id is distinct from new.config_version_id
       or old.business_id is distinct from new.business_id
       or old.branch_id is distinct from new.branch_id then
      raise exception 'branch override identity is immutable; edit the draft row in place'
        using errcode = 'restrict_violation';
    end if;
  end if;
  if v_status is distinct from 'draft'
     or (tg_op = 'UPDATE' and v_old_status is distinct from 'draft') then
    raise exception 'published configuration overrides are immutable; edit a draft'
      using errcode = 'restrict_violation';
  end if;
  if tg_op = 'DELETE' then
    return old;
  end if;
  new.updated_at := now();
  return new;
end
$$;

--
-- Name: guard_money_back_window_v124(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.guard_money_back_window_v124() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if tg_op = 'DELETE' then
    raise exception 'money-back request evidence is immutable'
      using errcode='restrict_violation';
  end if;
  if new.first_paid_at >= old.first_paid_at
     or new.money_back_request_until <> new.first_paid_at + interval '30 days'
     or new.business_id <> old.business_id then
    raise exception 'money-back request evidence may only move to an earlier paid invoice'
      using errcode='restrict_violation';
  end if;
  return new;
end
$$;

--
-- Name: guard_retention_program_version(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.guard_retention_program_version() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_version uuid:=case when tg_op='DELETE' then old.config_version_id else new.config_version_id end;
        v_status text; v_tax public.firm_reward_taxonomy%rowtype;
begin
  select status into v_status from public.firm_config_versions where id=v_version;
  if v_status is distinct from 'draft' then
    raise exception 'published retention configuration is immutable'
      using errcode='restrict_violation';
  end if;
  if tg_op='DELETE' then return old; end if;
  if tg_op='UPDATE' and (
       new.program_id is distinct from old.program_id
       or new.config_version_id is distinct from old.config_version_id
       or new.business_id is distinct from old.business_id
     ) then
    raise exception 'retention version identity is immutable'
      using errcode='restrict_violation';
  end if;
  select * into v_tax from public.firm_reward_taxonomy
   where id=new.reward_taxonomy_id and business_id=new.business_id;
  if not found or (not v_tax.active and new.active) then
    raise exception 'retired reward types cannot be selected by new drafts'
      using errcode='check_violation';
  end if;
  new.fulfillment_kind:=v_tax.fulfillment_kind;
  return new;
end $$;

--
-- Name: guard_reward_taxonomy_kind(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.guard_reward_taxonomy_kind() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  new.label := btrim(new.label);
  if tg_op = 'UPDATE' and new.fulfillment_kind is distinct from old.fulfillment_kind then
    raise exception 'reward fulfillment behavior is immutable; create a new reward type'
      using errcode = 'restrict_violation';
  end if;
  new.updated_at := now();
  return new;
end $$;

--
-- Name: guard_self_serve_manual_decision_v130(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.guard_self_serve_manual_decision_v130() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if new.approval_status is distinct from old.approval_status
     and exists(
       select 1 from public.self_serve_business_onboarding_v130 onboarding
        where onboarding.business_id=old.business_id
          and onboarding.status='payment_pending'
     ) then
    raise exception 'self-service approval is controlled by provider-confirmed payment'
      using errcode='42501';
  end if;
  return new;
end
$$;

--
-- Name: guard_staff_blocked_time_v120(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.guard_staff_blocked_time_v120() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if new.status<>'booked' or new.staff_id is null then return new; end if;

  perform app.lock_staff_calendar_v120(
    new.business_id,new.branch_id,new.staff_id
  );
  if not app.staff_free_for_appointment_v47(
    new.business_id,new.staff_id,new.branch_id,new.service_id,
    new.starts_at,new.ends_at,new.id
  ) then
    raise exception 'staff is not available for this appointment'
      using errcode='23P01';
  end if;
  return new;
end
$$;

--
-- Name: has_perm(uuid, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.has_perm(p_business uuid, p_perm text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  select app.business_workspace_open_v94(p_business) and exists(
    select 1 from public.staff staff_row
    where staff_row.business_id=p_business
      and staff_row.user_id=auth.uid() and staff_row.active
      and p_perm=any(app.role_perms(staff_row.role))
  )
$$;

--
-- Name: is_platform_operator_v75(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.is_platform_operator_v75() RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_context text;v_module text;v_mode text;
begin
  if app.is_super_admin() then return true;end if;
  if app.v89_platform_role()<>'admin' then return false;end if;
  get diagnostics v_context=pg_context;
  v_context:=lower(v_context);

  if v_context~E'\\npl/pgsql function platform_list_consultants_v75\\(' then
    v_module:='sectors';v_mode:='r';
  elsif v_context~E'\\npl/pgsql function (platform_get_sme_board_v76|platform_list_prospects_v76|platform_get_prospect_detail_v76|get_business_onboarding_v79|platform_get_import_errors_v86|platform_get_import_batch_v86|platform_list_prospects_v86|platform_get_prospect_workspace_v86|platform_get_prospect_detail_v86|platform_get_sme_analytics_v86)\\(' then
    v_module:='onboarding';v_mode:='r';
  elsif v_context~E'\\npl/pgsql function (platform_create_prospect_v76|platform_update_prospect_v76|platform_assign_prospect_v76|platform_add_prospect_activity_v76|platform_create_prospect_task_v76|platform_complete_prospect_task_v76|platform_move_prospect_stage_v76|platform_stage_prospect_import_v76|platform_commit_prospect_import_v76|convert_sme_prospect_v79|reissue_workspace_owner_invite_v79|start_business_onboarding_v79|refresh_business_onboarding_v79|record_onboarding_manual_evidence_v79|platform_record_company_profile_v86|platform_record_contact_profile_v86|platform_record_qualification_v86|platform_record_activity_detail_v86|platform_record_commercial_detail_v86|platform_record_conversion_configuration_v86|platform_upsert_prospect_contact_v86|platform_move_prospect_stage_v86|platform_analyse_prospect_import_v86|platform_stage_prospect_import_v86|platform_decide_import_row_v86|platform_commit_prospect_import_v86|platform_refresh_prospect_quality_v86)\\(' then
    v_module:='onboarding';v_mode:='rw';
  else
    return false;
  end if;
  return app.v89_platform_can(v_module,v_mode);
end
$$;

