--
-- Name: is_synthetic_guard(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.is_synthetic_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_priv boolean := app.is_super_admin() or session_user in ('postgres','service_role','supabase_admin');
  v_biz uuid; v_cli uuid;
begin
  if tg_op = 'INSERT' then
    if new.is_synthetic and not v_priv then
      raise exception 'only a super-admin may create a synthetic entity' using errcode = '42501';
    end if;
    return new;
  end if;
  if new.is_synthetic is distinct from old.is_synthetic then
    if not v_priv then raise exception 'only a super-admin may change the synthetic marker' using errcode = '42501'; end if;
    if old.is_synthetic and not new.is_synthetic then
      if tg_table_name = 'clients' then v_biz := new.business_id; v_cli := new.id;
      else v_biz := new.id; v_cli := null; end if;
      if app.sv_has_synthetic_evidence(v_biz, v_cli) then
        raise exception 'cannot clear the synthetic marker while synthetic stored-value evidence remains' using errcode = '22023';
      end if;
    end if;
  end if;
  return new;
end $$;

--
-- Name: issue_bringback_for_business_v361(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.issue_bringback_for_business_v361(p_business uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_campaign public.bringback_campaigns_v361%rowtype;
  v_issued integer := 0;
  v_rows integer;
begin
  for v_campaign in
    select * from public.bringback_campaigns_v361
     where business_id=p_business and active and deleted_at is null
  loop
    -- "Away for the stated period" uses the SAME definition as the Gone-quiet report the owner
    -- already reads: last completed, non-reversed sale older than away_days. Anyone with no sale
    -- at all is excluded — they never came, so there is nothing to bring them back from.
    insert into public.bringback_grants_v361(
      business_id,campaign_id,client_id,reward_label,away_days,cycle_key,expires_at)
    select p_business, v_campaign.id, last_seen.client_id, v_campaign.reward_label,
           v_campaign.away_days, last_seen.last_day,
           case when v_campaign.expiry_days is null then null
                else now() + make_interval(days => v_campaign.expiry_days) end
      from (
        select s.client_id, max(s.created_at)::date as last_day
          from public.sales s
         where s.business_id=p_business and s.client_id is not null and s.reversal_of is null
           and not exists(select 1 from public.sales r where r.reversal_of=s.id)
         group by s.client_id
        having max(s.created_at) < now() - make_interval(days => v_campaign.away_days)
      ) last_seen
    on conflict (campaign_id, client_id, cycle_key) do nothing;
    get diagnostics v_rows = row_count;
    v_issued := v_issued + v_rows;
  end loop;
  return v_issued;
end $$;

--
-- Name: issue_welcome_offer_v215(uuid, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.issue_welcome_offer_v215(p_business uuid, p_client uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_offer public.business_welcome_offers_v215%rowtype;
  v_ok boolean;
  v_grant uuid;
begin
  if p_business is null or p_client is null then return null; end if;

  select * into v_offer
  from public.business_welcome_offers_v215
  where business_id = p_business;
  if not found or not v_offer.active then return null; end if;

  if v_offer.reward_catalog_kind = 'custom' then
    v_ok := true;
  elsif v_offer.reward_catalog_kind = 'service' then
    select true into v_ok from public.services
    where id = v_offer.reward_catalog_id and business_id = p_business and active;
  else
    select true into v_ok from public.products
    where id = v_offer.reward_catalog_id and business_id = p_business and active;
  end if;
  if not coalesce(v_ok, false) then return null; end if;

  if exists(
    select 1 from public.sales
    where business_id = p_business and client_id = p_client and reversal_of is null
  ) then
    return null;
  end if;

  insert into public.welcome_offer_grants_v215(
    business_id, client_id, min_spend_cents,
    reward_catalog_kind, reward_catalog_id, reward_label, expires_at
  ) values (
    p_business, p_client, v_offer.min_spend_cents,
    v_offer.reward_catalog_kind, v_offer.reward_catalog_id, v_offer.reward_label,
    case when v_offer.expiry_days is null then null
         else now() + make_interval(days => v_offer.expiry_days) end
  )
  on conflict (business_id, client_id) do nothing
  returning id into v_grant;

  return v_grant;
end
$$;

--
-- Name: issue_workspace_owner_invite_core_v79(uuid, uuid, text, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.issue_workspace_owner_invite_core_v79(p_business uuid, p_prospect uuid, p_email text, p_actor uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_token text;v_hash text;v_version integer;v_row public.workspace_owner_invitations%rowtype;
begin
  if p_business is null or p_prospect is null or position('@' in coalesce(p_email,''))<=1 then
    raise exception 'complete workspace owner invitation input is required' using errcode='22023';
  end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(p_business::text,79));
  update public.workspace_owner_invitations set status='revoked',revoked_at=now()
   where business_id=p_business and status='pending';
  select coalesce(max(version),0)+1 into v_version
    from public.workspace_owner_invitations where business_id=p_business;
  v_token:=encode(extensions.gen_random_bytes(32),'hex');
  v_hash:=app.v76_sha256_hex(v_token);
  insert into public.workspace_owner_invitations(
    business_id,prospect_id,version,owner_email,token_hash,token_last_four,
    expires_at,issued_by
  ) values(p_business,p_prospect,v_version,lower(btrim(p_email)),v_hash,right(v_token,4),
    now()+interval '14 days',p_actor) returning * into v_row;
  return jsonb_build_object('id',v_row.id,'business_id',p_business,'version',v_version,
    'owner_email',v_row.owner_email,'status',v_row.status,'expires_at',v_row.expires_at,
    'token_last_four',v_row.token_last_four,'raw_token',v_token);
end
$$;

