    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  select pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'v120:staff-calendar:'||p_business::text||':'||p_staff::text,
      120
    )
  )
$$;

--
-- Name: loyalty_ledger_write_guard(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.loyalty_ledger_write_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_token text;
  v_scope text;
begin
  if tg_table_name='points_ledger' then
    v_token:=nullif(current_setting('app.points_ledger_insert_id',true),'');
    v_scope:=nullif(current_setting('app.points_ledger_write_scope',true),'');
    if v_token is distinct from new.id::text or v_scope not in
       ('sale_trigger','redeem_points','adjust_points','points_expiry',
        'redemption_reversal','sale_amount_correction_v84','programme_pot_transfer',
        'referral_reward_points') then
      raise exception 'points_ledger may only be appended by approved loyalty routes'
        using errcode='42501';
    end if;
    if (v_scope='sale_trigger'
          and (new.entry_type<>'earn' or new.points<=0 or new.sale_id is null))
       or (v_scope='redeem_points'
          and (new.entry_type<>'redeem' or new.points>=0 or new.sale_id is not null))
       or (v_scope='adjust_points'
          and (new.entry_type<>'adjust' or new.points=0 or new.sale_id is not null
               or new.actor is distinct from auth.uid()))
       or (v_scope='points_expiry'
          and (new.entry_type<>'expire' or new.points>=0 or new.sale_id is not null
               or new.actor is not null))
       or (v_scope='redemption_reversal'
          and (new.entry_type<>'adjust' or new.points<=0 or new.sale_id is not null
               or new.actor is distinct from auth.uid()))
       or (v_scope='sale_amount_correction_v84'
          and (new.entry_type<>'adjust' or new.points>=0 or new.sale_id is null
               or new.actor is distinct from auth.uid()))
       or (v_scope='programme_pot_transfer'
          and (new.entry_type<>'adjust' or new.points=0 or new.sale_id is not null
               or new.actor is not null or new.programme_id is null))
       or (v_scope='referral_reward_points'
          and (new.entry_type<>'earn' or new.points<=0 or new.sale_id is not null
               or new.programme_id is null)) then
      raise exception 'points ledger entry does not match its internal route'
        using errcode='check_violation';
    end if;
    if new.programme_id is null then
      raise exception 'points ledger entry has no programme'
        using errcode='check_violation';
    end if;
    if not exists (
      select 1 from public.business_programmes bp
       where bp.id=new.programme_id and bp.business_id=new.business_id
    ) then
      raise exception 'points ledger entry is tagged with another tenant''s programme'
        using errcode='42501';
    end if;
  elsif tg_table_name='credit_ledger' then
    v_token:=nullif(current_setting('app.credit_ledger_insert_id',true),'');
    v_scope:=nullif(current_setting('app.credit_ledger_write_scope',true),'');
    if v_token is distinct from new.id::text or v_scope not in
       ('sale_trigger','redeem_points','redeem_gift_card','enroll_membership',
        'membership_renewal','credit_tender','sale_reversal','redemption_reversal') then
      raise exception 'credit_ledger may only be appended by approved routes'
        using errcode='42501';
    end if;
    if (v_scope='sale_trigger'
          and (new.entry_type not in ('loyalty_earn','referral_reward')
               or new.amount_cents<=0 or new.sale_id is null))
       or (v_scope='redeem_points'
          and (new.entry_type<>'loyalty_earn' or new.amount_cents<=0
               or new.sale_id is not null or new.payment_id is not null
               or new.actor is distinct from auth.uid()))
       or (v_scope='redeem_gift_card'
          and (new.entry_type<>'gift_card_load' or new.amount_cents<=0
               or new.sale_id is not null or new.payment_id is not null
               or new.actor is distinct from auth.uid()))
       or (v_scope='enroll_membership'
          and (new.entry_type<>'membership_credit' or new.amount_cents<=0
               or new.sale_id is null or new.payment_id is not null
               or new.actor is distinct from auth.uid()))
       or (v_scope='membership_renewal'
          and (new.entry_type<>'membership_credit' or new.amount_cents<=0
               or new.sale_id is null or new.actor is not null))
       or (v_scope='credit_tender'
          and (new.entry_type<>'spend' or new.amount_cents>=0
               or new.sale_id is null or new.payment_id is null
               or new.actor is distinct from auth.uid()))
       or (v_scope='sale_reversal'
          and (new.entry_type<>'manual_adjust' or new.amount_cents=0
               or new.sale_id is null or new.actor is distinct from auth.uid()))
       or (v_scope='redemption_reversal'
          and (new.entry_type<>'manual_adjust' or new.amount_cents>=0
               or new.sale_id is not null or new.payment_id is not null
               or new.actor is distinct from auth.uid())) then
      raise exception 'credit ledger entry does not match its internal route'
        using errcode='check_violation';
    end if;
  else
    raise exception 'unexpected loyalty ledger table';
  end if;
  return new;
end
$$;

--
-- Name: loyalty_operation_write_guard(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.loyalty_operation_write_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_token text;
begin
  if tg_op = 'INSERT' then
    v_token := nullif(current_setting('app.loyalty_operation_insert_id', true), '');
    if v_token is distinct from new.id::text then
      raise exception 'loyalty operations may only be reserved by a loyalty RPC'
        using errcode = '42501';
    end if;
    return new;
  end if;

  if tg_op = 'DELETE' then
    raise exception 'loyalty_operations is append-only: DELETE is not permitted'
      using errcode = 'restrict_violation';
  end if;

  v_token := nullif(current_setting('app.loyalty_operation_complete_id', true), '');
  if v_token is distinct from old.id::text
     or old.status <> 'reserved'
     or new.status <> 'completed'
     or (new.id, new.business_id, new.client_id, new.reward_id, new.operation_type,
         new.actor, new.idempotency_key, new.request_payload, new.request_hash, new.created_at)
        is distinct from
        (old.id, old.business_id, old.client_id, old.reward_id, old.operation_type,
         old.actor, old.idempotency_key, old.request_payload, old.request_hash, old.created_at)
     or new.result is null
     or new.completed_at is null then
    raise exception 'loyalty operation % may only transition reserved -> completed', old.id
      using errcode = 'restrict_violation';
  end if;
  return new;
end $$;

--
-- Name: loyalty_redemption_immutable_guard(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.loyalty_redemption_immutable_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  raise exception 'loyalty redemptions are append-only' using errcode = 'restrict_violation';
end $$;

--
-- Name: loyalty_tiers; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.loyalty_tiers (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    business_id uuid NOT NULL,
    name text NOT NULL,
    threshold integer NOT NULL,
    points_multiplier numeric DEFAULT 1 NOT NULL,
    perk_note text,
    sort integer DEFAULT 0 NOT NULL,
    effective_from timestamp with time zone,
    expires_at timestamp with time zone,
    paused boolean DEFAULT false NOT NULL,
    deleted_at timestamp with time zone,
    CONSTRAINT loyalty_tiers_effective_window_check CHECK (((expires_at IS NULL) OR (effective_from IS NULL) OR (expires_at > effective_from))),
    CONSTRAINT loyalty_tiers_points_multiplier_check CHECK ((points_multiplier >= (1)::numeric)),
    CONSTRAINT loyalty_tiers_threshold_check CHECK ((threshold >= 0))
);

--
-- Name: COLUMN loyalty_tiers.paused; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.loyalty_tiers.paused IS 'v331: immediate-write off switch, set by business_set_tier_paused_v331. A paused tier is excluded from every live customer-facing tier computation (loyalty_tier_for, the customer tier/ladder RPCs, the reward tier-gate) but keeps its row -- turning it back on restores it exactly as it was. Survives publish_loyalty_config''s tier delete+reinsert via an explicit capture/restore in that function (see its own comment).';

--
-- Name: COLUMN loyalty_tiers.deleted_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.loyalty_tiers.deleted_at IS 'v331: set once, by business_delete_tier_v331, when an owner deletes a tier from the Tiers page. NULL = not deleted. Also implies paused=true. Survives publish_loyalty_config''s tier delete+reinsert the same way `paused` does.';

--
-- Name: loyalty_tier_for(uuid, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.loyalty_tier_for(p_business uuid, p_client uuid) RETURNS public.loyalty_tiers
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_basis text;
  v_metric numeric;
  v_row public.loyalty_tiers%rowtype;
  v_points_programme uuid;
begin
  select tier_basis into v_basis
  from public.loyalty_programs
  where business_id=p_business;
  v_basis:=coalesce(v_basis,'visits');
  if v_basis='visits' then
    select count(*) into v_metric from public.sales
    where business_id=p_business and client_id=p_client and counts_as_visit;
  elsif v_basis='spend' then
    select coalesce(sum(amount_cents),0)/100.0 into v_metric from public.sales
    where business_id=p_business and client_id=p_client and counts_as_revenue;
  else
    select spine.id into v_points_programme
      from public.business_programmes spine
     where spine.business_id=p_business and spine.kind='points';
    if v_points_programme is null then
      select coalesce(sum(points),0) into v_metric from public.points_ledger
      where business_id=p_business and client_id=p_client and entry_type='earn';
    else
      select coalesce(sum(pl.points),0) into v_metric from public.points_ledger pl
      where pl.business_id=p_business and pl.client_id=p_client
        and pl.entry_type='earn' and pl.programme_id=v_points_programme;
    end if;
  end if;
  select * into v_row from public.loyalty_tiers
  where business_id=p_business
    and threshold<=v_metric
    and deleted_at is null and not paused
    and (effective_from is null or effective_from<=statement_timestamp())
    and (expires_at is null or expires_at>statement_timestamp())
  order by threshold desc,sort desc,id
  limit 1;
  return v_row;
end
$$;

--
-- Name: FUNCTION loyalty_tier_for(p_business uuid, p_client uuid); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.loyalty_tier_for(p_business uuid, p_client uuid) IS 'v148 tier resolver, v311 W5a: the points_earned basis is now fuelled by the POINTS programme''s earn rows only (owner decision D1 — points fuel tiers, stamps never do), joining the three read twins v310 moved. The spine row is resolved INTO A VARIABLE with an explicit unfiltered fallback: written inline as `programme_id = (subselect)` a NULL would make the predicate never true, zeroing every tier and therefore every earn multiplier — a silent change to what every sale earns. Recorded behaviour change: a tier_basis=''points_earned'' firm on loyalty_model=''stamps'' used to climb on stamps and now climbs on 0; zero live tenants are on that shape (all 10 live programmes are visits-basis) and W6 closes it with a silent points programme for tiers-only firms.';

--
-- Name: loyalty_tier_version_guard(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.loyalty_tier_version_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_status text;
begin
  if tg_op='DELETE' then
    select status into v_status from public.firm_config_versions where id=old.config_version_id;
  else
    select status into v_status from public.firm_config_versions where id=new.config_version_id;
  end if;
  if v_status<>'draft' then
    raise exception 'published tier versions are immutable' using errcode='restrict_violation';
  end if;
  if tg_op='DELETE' then return old; end if;
  return new;
end $$;

--
-- Name: loyalty_version_immutable_guard(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.loyalty_version_immutable_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_status text;
begin
  if tg_op = 'DELETE' then
    raise exception 'configuration versions are append-only' using errcode='restrict_violation';
  end if;
  select status into v_status from public.firm_config_versions
   where id = old.config_version_id;
  if v_status <> 'draft' then
    raise exception 'published configuration rows are immutable' using errcode='restrict_violation';
  end if;
  return new;
end $$;

--
-- Name: map_sme_stage_v76(text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.map_sme_stage_v76(p_raw text) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  select stage.stage_key
    from public.sme_pipeline_stages stage
   where stage.stage_key=lower(regexp_replace(btrim(coalesce(p_raw,'')),'[^a-zA-Z0-9]+','_','g'))
      or lower(stage.label)=lower(btrim(coalesce(p_raw,'')))
   order by stage.sort_order limit 1
$$;

--
-- Name: metric_module_scope_available_v145(uuid, uuid, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.metric_module_scope_available_v145(p_business uuid, p_branch uuid, p_module text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if auth.uid() is null
     or p_module is null
     or not app.can_see_branch(p_business, p_branch) then
    return false;
  end if;
  if p_branch is not null and not exists (
    select 1
    from public.branches branch
    where branch.id = p_branch
      and branch.business_id = p_business
  ) then
    return false;
  end if;
  if app.is_super_admin() then
    return true;
  end if;
  if p_branch is not null then
    -- Inactive branches are historical read scopes: their operational module resolver
    -- correctly disables new work, so metric reads inherit the firm read boundary while
    -- can_see_branch above still enforces the caller's branch visibility.
    if exists (
      select 1 from public.branches branch
       where branch.id = p_branch
         and branch.business_id = p_business
         and not branch.active
    ) then
      return app.can_module_read_at_v94(p_business, null, p_module);
    end if;
    return app.can_module_read_at_v94(p_business, p_branch, p_module);
  end if;
  if not app.can_module_read_at_v94(p_business, null, p_module) then
    return false;
  end if;
  return not exists (
    select 1
    from public.branches branch
    where branch.business_id = p_business
      and (
        not app.can_see_branch(p_business, branch.id)
        or not case when branch.active
          then app.can_module_read_at_v94(p_business, branch.id, p_module)
          else app.can_module_read_at_v94(p_business, null, p_module)
        end
      )
  );
end;
$$;

--
-- Name: migrate_programme_pot_v312(uuid, uuid, uuid, integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.migrate_programme_pot_v312(p_business uuid, p_from uuid, p_to uuid, p_limit integer DEFAULT 500) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_client record;
  v_row_id uuid;
  v_done integer := 0;
  v_reference text;
  v_dated integer;
  v_dated_into_no_expiry integer := 0;
begin
  if p_business is null or p_from is null or p_to is null or p_from = p_to then
    raise exception 'v312: a pot migration needs a business and two different programmes'
      using errcode = '22023';
  end if;
  if not exists (select 1 from public.business_programmes bp
                  where bp.id = p_from and bp.business_id = p_business)
     or not exists (select 1 from public.business_programmes bp
                     where bp.id = p_to and bp.business_id = p_business) then
    raise exception 'v312: both programmes must belong to this business'
      using errcode = '42501';
  end if;

  -- V308 standing invariant 1: businesses row first, then money.
  perform 1 from public.businesses b where b.id = p_business for update;

  v_reference := 'programme pot transfer';

  for v_client in
    select candidate.client_id, coalesce(source.pot, 0)::integer as pot
      from (
        select pl.client_id
          from public.points_ledger pl
         where pl.business_id = p_business
           and pl.programme_id = p_from
         group by pl.client_id
        having sum(pl.points) <> 0
        union
        select pb.client_id
          from public.points_batches pb
         where pb.business_id = p_business
           and pb.programme_id = p_from
           and pb.remaining > 0
      ) candidate
      left join lateral (
        select sum(pl.points) as pot
          from public.points_ledger pl
         where pl.business_id = p_business
           and pl.programme_id = p_from
           and pl.client_id = candidate.client_id
      ) source on true
     order by candidate.client_id
     limit greatest(coalesce(p_limit, 500), 1)
  loop
    perform 1 from public.clients c
     where c.id = v_client.client_id and c.business_id = p_business
     for update;

    if v_client.pot <> 0 then
      v_row_id := gen_random_uuid();
      perform set_config('app.points_ledger_insert_id', v_row_id::text, true);
      perform set_config('app.points_ledger_write_scope', 'programme_pot_transfer', true);
      insert into public.points_ledger (
        id, business_id, client_id, entry_type, points, reference, actor, programme_id
      ) values (
        v_row_id, p_business, v_client.client_id, 'adjust', -v_client.pot,
        v_reference || ' out: ' || p_from, null, p_from
      );
      perform set_config('app.points_ledger_insert_id', '', true);
      perform set_config('app.points_ledger_write_scope', '', true);

      v_row_id := gen_random_uuid();
      perform set_config('app.points_ledger_insert_id', v_row_id::text, true);
      perform set_config('app.points_ledger_write_scope', 'programme_pot_transfer', true);
      insert into public.points_ledger (
        id, business_id, client_id, entry_type, points, reference, actor, programme_id
      ) values (
        v_row_id, p_business, v_client.client_id, 'adjust', v_client.pot,
        v_reference || ' in: ' || p_to, null, p_to
      );
      perform set_config('app.points_ledger_insert_id', '', true);
      perform set_config('app.points_ledger_write_scope', '', true);
    end if;

    -- THIS CLIENT'S open batches, under THIS client's lock, in the same iteration as
    -- their transfer pair. OPEN only: a drained batch keeps its tag, contributes 0 to
    -- either side's sum(remaining), and keeps its reversal provenance intact.
    select count(*) into v_dated
      from public.points_batches pb
     where pb.business_id = p_business
       and pb.programme_id = p_from
       and pb.client_id = v_client.client_id
       and pb.remaining > 0
       and pb.expires_at is not null;
    v_dated_into_no_expiry := v_dated_into_no_expiry + v_dated;

    update public.points_batches
       set programme_id = p_to
     where business_id = p_business
       and programme_id = p_from
       and client_id = v_client.client_id
       and remaining > 0;

    v_done := v_done + 1;
  end loop;

  if v_dated_into_no_expiry > 0 then
    -- A dated batch moved into a programme whose policy has no expiry becomes immortal.
    -- That is not a bug — a switch IS a policy change — but it is never silent, and the
    -- promised date is never re-written.
    raise notice 'v312: % dated open batches moved from % to % at business %',
      v_dated_into_no_expiry, p_from, p_to, p_business;
    insert into public.audit_log(business_id, actor, action, entity, entity_id, detail)
    values (p_business, null, 'PROGRAMME_POT_TRANSFER_V312', 'points_batches', p_to,
            jsonb_build_object('from_programme_id', p_from, 'to_programme_id', p_to,
                               'dated_open_batches_moved', v_dated_into_no_expiry,
                               'clients_transferred', v_done));
  end if;

  return v_done;
end
$$;

--
-- Name: FUNCTION migrate_programme_pot_v312(p_business uuid, p_from uuid, p_to uuid, p_limit integer); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.migrate_programme_pot_v312(p_business uuid, p_from uuid, p_to uuid, p_limit integer) IS 'v312 W5b: move a business''s live points pot from one programme to another, coherently. Per client, inside ONE loop iteration under that client''s row lock: an append-only transfer PAIR (adjust -S on the source, adjust +S on the destination, both actor NULL under the programme_pot_transfer write scope) and the retag of that client''s OPEN batches. p_limit bounds the CLIENTS processed, and because the retag is inside the loop every committed invocation leaves each processed client wholly in the destination and every unprocessed client wholly in the source — both coherent, so app.detect_programme_pot_split_v312() reads zero rows at every commit boundary, including mid-migration. The processed set is the union of "nonzero source ledger pot" and "open source batch", so the batch side can never be left behind by the ledger side; a zero-pot client is retagged with no transfer pair. Idempotent and resumable: a finished client matches neither arm, so a second run over a finished business returns 0. Never UPDATEs a points_ledger row and never touches trg_points_ledger_append_only.';

--
-- Name: norm_phone(text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.norm_phone(p text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
  select case
           when length(d) = 8  and left(d,1) in ('3','6','8','9') then d
           when length(d) = 10 and left(d,2) = '65'
                and substr(d,3,1) in ('3','6','8','9')            then substr(d,3,8)
           when length(d) = 11 and left(d,3) = '065'
                and substr(d,4,1) in ('3','6','8','9')            then substr(d,4,8)
           else null
         end
  from (select regexp_replace(coalesce(p,''), '[^0-9]', '', 'g') as d) _;
$$;

--
-- Name: normalized_business_identity_v79(text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.normalized_business_identity_v79(p_value text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$ select nullif(regexp_replace(lower(btrim(coalesce(p_value,''))),'[^a-z0-9]','','g'),'') $$;

--
-- Name: notify_on_booking_request(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.notify_on_booking_request() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_when text;
begin
  -- bulk CSV import sets this GUC to avoid one toast per imported row
  if coalesce(current_setting('app.suppress_booking_notify', true), '') = 'on' then
    return new;
  end if;
  v_when := case when new.preferred_at is not null
                 then to_char(new.preferred_at at time zone 'Asia/Singapore', 'Dy DD Mon HH24:MI')
                 else 'no time given' end;
  if new.status in ('new','pending','confirmed') then
    insert into public.notifications(business_id, kind, title, body, ref_table, ref_id)
    values (new.business_id, 'booking_new',
            case when new.status = 'confirmed' then 'New booking (confirmed)'
                 else 'New booking request' end,
            coalesce(new.name,'A guest')
              || case when new.party_size is not null then ', party ' || new.party_size else '' end
              || ' — ' || v_when,
            'booking_requests', new.id);
  elsif new.status = 'waitlisted' then
    insert into public.notifications(business_id, kind, title, body, ref_table, ref_id)
    values (new.business_id, 'booking_waitlisted', 'Added to waitlist',
            coalesce(new.name,'A guest')
              || case when new.party_size is not null then ', party ' || new.party_size else '' end
              || ' — no tables free',
            'booking_requests', new.id);
  end if;
  return new;
end $$;

--
-- Name: notify_on_change_request(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.notify_on_change_request() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_when text; v_name text;
begin
  select c.full_name into v_name
    from public.appointments a join public.clients c on c.id = a.client_id
   where a.id = new.appointment_id;
  v_when := case when new.proposed_at is not null
                 then to_char(new.proposed_at at time zone 'Asia/Singapore', 'Dy DD Mon HH24:MI')
                 else null end;
  insert into public.notifications(business_id, kind, title, body, ref_table, ref_id)
  values (new.business_id, 'change_request',
          case when new.kind = 'cancel' then 'Cancellation request' else 'Reschedule request' end,
          coalesce(v_name,'A guest')
            || case when new.kind = 'reschedule' and v_when is not null then ' -> ' || v_when else '' end,
          'change_requests', new.id);
  return new;
end $$;

--
-- Name: on_appointment_completed(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.on_appointment_completed() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_amount integer;
  v_component record;
  v_batch record;
  v_need integer;
  v_take integer;
  v_staff uuid;
begin
  if new.status='completed' and old.status is distinct from 'completed' then
    v_amount:=coalesce(nullif(new.total_cents,0),
      (select service.price_cents from public.services service where service.id=new.service_id),0);
    if new.staff_id is not null then
      select staff.id into v_staff from public.staff staff
       where staff.id=new.staff_id and staff.business_id=new.business_id;
      if not found then
        raise exception 'appointment staff does not belong to this business' using errcode='23503';
      end if;
    end if;
    insert into public.sales(
      business_id,client_id,kind,amount_cents,appointment_id,staff_id,branch_id,note
    ) values (
      new.business_id,new.client_id,'service',v_amount,new.id,v_staff,new.branch_id,
      'appointment completed'
    ) on conflict do nothing;
    if new.service_id is not null then
      for v_component in select product_id,qty from public.service_products
        where service_id=new.service_id loop
        v_need:=v_component.qty;
        for v_batch in select id,qty from public.stock_batches
          where product_id=v_component.product_id and qty>0
          order by expires_on nulls last,received_on,id loop
          exit when v_need<=0;
          v_take:=least(v_batch.qty,v_need);
          update public.stock_batches set qty=qty-v_take where id=v_batch.id;
          v_need:=v_need-v_take;
        end loop;
      end loop;
    end if;
  end if;
  return new;
end
$$;

