--
-- Name: platform_accounting_policies_v147; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.platform_accounting_policies_v147 (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    version integer NOT NULL,
    effective_from date NOT NULL,
    legal_name text NOT NULL,
    registration_number text NOT NULL,
    registered_address text NOT NULL,
    functional_currency text DEFAULT 'SGD'::text NOT NULL,
    gst_status text NOT NULL,
    gst_registration_number text,
    gst_rate_bps integer DEFAULT 0 NOT NULL,
    financial_year_end_month integer NOT NULL,
    financial_year_end_day integer NOT NULL,
    document_prefix text NOT NULL,
    operation_key uuid NOT NULL,
    request_hash text NOT NULL,
    supersedes uuid,
    evidence_reference text NOT NULL,
    created_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT platform_accounting_policies_v147_check CHECK ((financial_year_end_day <=
CASE
    WHEN (financial_year_end_month = 2) THEN 29
    WHEN (financial_year_end_month = ANY (ARRAY[4, 6, 9, 11])) THEN 30
    ELSE 31
END)),
    CONSTRAINT platform_accounting_policies_v147_check1 CHECK ((((gst_status = 'registered'::text) AND ((length(btrim(gst_registration_number)) >= 4) AND (length(btrim(gst_registration_number)) <= 40)) AND (gst_rate_bps > 0)) OR ((gst_status <> 'registered'::text) AND (gst_registration_number IS NULL) AND (gst_rate_bps = 0)))),
    CONSTRAINT platform_accounting_policies_v147_document_prefix_check CHECK ((document_prefix ~ '^[A-Z0-9]{2,10}$'::text)),
    CONSTRAINT platform_accounting_policies_v147_evidence_reference_check CHECK (((length(btrim(evidence_reference)) >= 8) AND (length(btrim(evidence_reference)) <= 300))),
    CONSTRAINT platform_accounting_policies_v147_financial_year_end_day_check CHECK (((financial_year_end_day >= 1) AND (financial_year_end_day <= 31))),
    CONSTRAINT platform_accounting_policies_v147_functional_currency_check CHECK ((functional_currency = 'SGD'::text)),
    CONSTRAINT platform_accounting_policies_v147_gst_rate_bps_check CHECK (((gst_rate_bps >= 0) AND (gst_rate_bps <= 2000))),
    CONSTRAINT platform_accounting_policies_v147_gst_status_check CHECK ((gst_status = ANY (ARRAY['not_registered'::text, 'registered'::text, 'pending_review'::text]))),
    CONSTRAINT platform_accounting_policies_v147_legal_name_check CHECK (((length(btrim(legal_name)) >= 2) AND (length(btrim(legal_name)) <= 200))),
    CONSTRAINT platform_accounting_policies_v147_registered_address_check CHECK (((length(btrim(registered_address)) >= 5) AND (length(btrim(registered_address)) <= 500))),
    CONSTRAINT platform_accounting_policies_v147_registration_number_check CHECK (((length(btrim(registration_number)) >= 4) AND (length(btrim(registration_number)) <= 40))),
    CONSTRAINT platform_accounting_policies_v147_request_hash_check CHECK ((request_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT platform_accounting_policies_v147_version_check CHECK ((version > 0)),
    CONSTRAINT platform_accounting_policies_v14_financial_year_end_month_check CHECK (((financial_year_end_month >= 1) AND (financial_year_end_month <= 12)))
);

