--
-- Name: platform_firm_rows_v88(timestamp with time zone); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.platform_firm_rows_v88(p_snapshot_at timestamp with time zone) RETURNS TABLE(row_id uuid, business_id uuid, prospect_id uuid, company_id uuid, name text, legal_name text, registration_number text, sector_key text, industry text, sector_assignment_version bigint, sector_bundle_version_id uuid, boss_name text, boss_email text, boss_phone text, source_type text, source_stage_key text, lane_key text, lane_label text, lane_sort_order smallint, onboarding_status text, onboarding_started_at timestamp with time zone, activated_at timestamp with time zone, last_activity_at timestamp with time zone, days_unattended integer, attention_severity text, attention_due boolean, attention_reason text, next_action_at timestamp with time zone, assigned_consultant_id uuid, updated_at timestamp with time zone, branch_count integer, staff_count integer, customer_count integer, subscription_status text, is_demo boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  with prospect_anchors as (
    select
      prospect.id as row_id,
      business.id as business_id,
      prospect.id as prospect_id,
      company.id as company_id,
      coalesce(business.name,company.trading_name,company.legal_name) as name,
      coalesce(business.legal_name,company.legal_name) as legal_name,
      coalesce(business.registration_number,company.registration_number) as registration_number,
      coalesce(company.sector_key,business.industry,company.industry,'other') as industry,
      company.email as company_email,
      company.phone as company_phone,
      prospect.current_stage_key as source_stage_key,
      prospect.next_action_at,
      prospect.assigned_consultant_id,
      prospect.created_at as anchor_created_at,
      prospect.updated_at as anchor_updated_at,
      business.onboarding_started_at,
      business.activated_at,
      coalesce(business.is_demo,false) as is_demo
    from public.sme_prospects prospect
    join public.sme_companies company on company.id=prospect.company_id
    left join lateral (
      select candidate.*
      from public.businesses candidate
      where candidate.id=prospect.converted_business_id
         or candidate.source_prospect_id=prospect.id
      order by case when candidate.id=prospect.converted_business_id then 0 else 1 end,
        candidate.created_at,candidate.id
      limit 1
    ) business on true
    where prospect.archived_at is null and prospect.created_at <= p_snapshot_at
      and (business.id is null or business.is_synthetic = false)
  ), business_anchors as (
    select
      business.id as row_id,
      business.id as business_id,
      null::uuid as prospect_id,
      null::uuid as company_id,
      business.name,
      business.legal_name,
      business.registration_number,
      coalesce(business.industry,'other') as industry,
      null::text as company_email,
      null::text as company_phone,
      null::text as source_stage_key,
      null::timestamptz as next_action_at,
      null::uuid as assigned_consultant_id,
      business.created_at as anchor_created_at,
      business.created_at as anchor_updated_at,
      business.onboarding_started_at,
      business.activated_at,
      business.is_demo
    from public.businesses business
    where business.is_synthetic=false and business.created_at<=p_snapshot_at
      and not exists(
        select 1
        from public.sme_prospects prospect
        where prospect.converted_business_id=business.id
           or prospect.id=business.source_prospect_id
      )
  ), anchors as (
    select * from prospect_anchors
    union all
    select * from business_anchors
  ), enriched as (
    select
      anchor.*,
      coalesce(bundle.sector_key,anchor.industry,'other') as resolved_sector_key,
      assignment.version as resolved_sector_assignment_version,
      assignment.bundle_version_id as resolved_sector_bundle_version_id,
      coalesce(owner_staff.full_name,configured_owner.full_name,primary_contact.full_name) as resolved_boss_name,
      coalesce(owner_staff.account_email,configuration.owner_email,configured_owner.email,
        primary_contact.email,latest_invitation.owner_email,latest_terms.owner_email,
        anchor.company_email) as resolved_boss_email,
      coalesce(owner_staff.account_phone,configuration.owner_phone,configured_owner.phone,
        primary_contact.phone,anchor.company_phone) as resolved_boss_phone,
      coalesce(source.source_type,case when anchor.prospect_id is null then
        case when exists(
          select 1 from public.audit_log audit
          where audit.business_id=anchor.business_id and audit.action='ONBOARD'
        ) then 'website' else 'existing_business' end
        else 'manual' end) as resolved_source_type,
      case
        when anchor.business_id is not null then 'case_won'
        when anchor.source_stage_key is null or anchor.source_stage_key='new_lead' then 'inbox'
        when anchor.source_stage_key in (
          'appt_set','npu_1','npu_2','npu_3','npu_4','npu_5','npu_6',
          'call_back','reschedule','meeting_sent','site_visit'
        ) then 'contacting'
        when anchor.source_stage_key in ('quotation_sent','pending_decision') then 'decision'
        when anchor.source_stage_key in ('client','account_created','onboarding','activated')
          then 'case_won'
        when anchor.source_stage_key='lost' then 'closed'
        else 'inbox'
      end as resolved_lane_key,
      checklist.status as checklist_status,
      subscription.status as resolved_subscription_status,
      activity.last_activity_at as resolved_last_activity_at,
      least(anchor.anchor_updated_at,p_snapshot_at) as resolved_updated_at,
      (select count(*)::integer from public.branches branch
        where branch.business_id=anchor.business_id) as resolved_branch_count,
      (select count(*)::integer from public.staff staff_row
        where staff_row.business_id=anchor.business_id) as resolved_staff_count,
      (select count(*)::integer from public.clients customer
        where customer.business_id=anchor.business_id) as resolved_customer_count
    from anchors anchor
    left join public.business_sector_assignments assignment
      on assignment.business_id=anchor.business_id
    left join public.sector_bundle_versions bundle
      on bundle.id=assignment.bundle_version_id
    left join public.business_onboarding_checklists checklist
      on checklist.business_id=anchor.business_id
    left join lateral (
      select subscription_row.status
      from public.subscriptions subscription_row
      where subscription_row.business_id=anchor.business_id
      order by subscription_row.next_payment_at desc nulls last,
        subscription_row.last_paid_at desc nulls last
      limit 1
    ) subscription on true
    left join lateral (
      select staff_row.full_name,
        nullif(account.email,'') as account_email,
        nullif(account.phone,'') as account_phone
      from public.staff staff_row
      left join auth.users account on account.id=staff_row.user_id
      where staff_row.business_id=anchor.business_id and staff_row.role='owner'
      order by staff_row.active desc,(staff_row.user_id is not null) desc,
        staff_row.created_at,staff_row.id
      limit 1
    ) owner_staff on true
    left join lateral (
      select config.*
      from public.sme_conversion_configuration_versions config
      where config.prospect_id=anchor.prospect_id and config.created_at<=p_snapshot_at
      order by config.version desc limit 1
    ) configuration on true
    left join public.sme_prospect_contacts configured_owner
      on configured_owner.id=configuration.primary_owner_contact_id
    left join lateral (
      select contact.*
      from public.sme_prospect_contacts contact
      where contact.prospect_id=anchor.prospect_id and contact.active
      order by contact.is_primary desc,contact.created_at,contact.id
      limit 1
    ) primary_contact on true
    left join lateral (
      select invitation.owner_email
      from public.workspace_owner_invitations invitation
      where invitation.business_id=anchor.business_id
      order by invitation.version desc limit 1
    ) latest_invitation on true
    left join lateral (
      select terms.owner_email
      from public.sme_commercial_terms terms
      where terms.prospect_id=anchor.prospect_id
      order by terms.version desc limit 1
    ) latest_terms on true
    left join lateral (
      select lineage.source_type
      from public.sme_prospect_source_lineage lineage
      where lineage.prospect_id=anchor.prospect_id and lineage.created_at<=p_snapshot_at
      order by lineage.created_at,lineage.id limit 1
    ) source on true
    left join lateral (
      select max(moment) as last_activity_at
      from (
        select anchor.anchor_created_at as moment
        union all select anchor.anchor_updated_at
        union all select prospect_activity.occurred_at
          from public.sme_prospect_activities prospect_activity
          where prospect_activity.prospect_id=anchor.prospect_id
        union all select history.occurred_at
          from public.sme_prospect_stage_history history
          where history.prospect_id=anchor.prospect_id
        union all select onboarding_event.created_at
          from public.business_onboarding_events onboarding_event
          where onboarding_event.business_id=anchor.business_id
        union all select audit.created_at
          from public.audit_log audit
          where audit.business_id=anchor.business_id
      ) moments
      where moment<=p_snapshot_at
    ) activity on true
  ), aged as (
    select enriched.*,
      greatest(0,floor(extract(epoch from
        (p_snapshot_at-enriched.resolved_last_activity_at))/86400))::integer
        as resolved_days_unattended
    from enriched
  )
  select
    aged.row_id,
    aged.business_id,
    aged.prospect_id,
    aged.company_id,
    aged.name,
    aged.legal_name,
    aged.registration_number,
    aged.resolved_sector_key as sector_key,
    aged.industry,
    aged.resolved_sector_assignment_version as sector_assignment_version,
    aged.resolved_sector_bundle_version_id as sector_bundle_version_id,
    aged.resolved_boss_name as boss_name,
    aged.resolved_boss_email as boss_email,
    aged.resolved_boss_phone as boss_phone,
    aged.resolved_source_type as source_type,
    aged.source_stage_key,
    aged.resolved_lane_key as lane_key,
    case aged.resolved_lane_key
      when 'inbox' then 'Inbox'
      when 'contacting' then 'Contacting'
      when 'decision' then 'Decision'
      when 'case_won' then 'Case won'
      else 'Closed'
    end as lane_label,
    case aged.resolved_lane_key
      when 'inbox' then 1 when 'contacting' then 2 when 'decision' then 3
      when 'case_won' then 4 else 5
    end::smallint as lane_sort_order,
    coalesce(aged.checklist_status,
      case
        when aged.activated_at is not null then 'activated'
        when aged.onboarding_started_at is not null then 'in_progress'
        when aged.business_id is not null then 'not_started'
      end) as onboarding_status,
    aged.onboarding_started_at,
    aged.activated_at,
    aged.resolved_last_activity_at as last_activity_at,
    aged.resolved_days_unattended as days_unattended,
    case
      when aged.resolved_lane_key in ('case_won','closed') then 'none'
      when aged.next_action_at<p_snapshot_at-interval '7 days' then 'critical'
      when aged.resolved_days_unattended>=14 then 'critical'
      when aged.next_action_at<p_snapshot_at then 'warning'
      when aged.resolved_days_unattended>=7 then 'warning'
      when aged.resolved_days_unattended>=3 then 'info'
      else 'none'
    end as attention_severity,
    coalesce(aged.resolved_lane_key not in ('case_won','closed') and (
      aged.next_action_at<p_snapshot_at or aged.resolved_days_unattended>=7
    ),false) as attention_due,
    case
      when aged.resolved_lane_key in ('case_won','closed') then null
      when aged.next_action_at<p_snapshot_at and aged.resolved_days_unattended>=7
        then 'next_action_overdue_and_stale'
      when aged.next_action_at<p_snapshot_at then 'next_action_overdue'
      when aged.resolved_days_unattended>=7 then 'stale_activity'
      when aged.resolved_days_unattended>=3 then 'approaching_stale'
      else null
    end as attention_reason,
    aged.next_action_at,
    aged.assigned_consultant_id,
    aged.resolved_updated_at as updated_at,
    coalesce(aged.resolved_branch_count,0) as branch_count,
    coalesce(aged.resolved_staff_count,0) as staff_count,
    coalesce(aged.resolved_customer_count,0) as customer_count,
    coalesce(aged.resolved_subscription_status,'none') as subscription_status,
    coalesce(aged.is_demo,false) as is_demo
  from aged
$$;

--
-- Name: FUNCTION platform_firm_rows_v88(p_snapshot_at timestamp with time zone); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.platform_firm_rows_v88(p_snapshot_at timestamp with time zone) IS 'v174: real-firm-only platform onboarding source; attention_due is always boolean; site_visit/quotation_sent lanes; is_demo output column.';

--
-- Name: platform_metric_source_scope_available_v145(uuid, uuid, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.platform_metric_source_scope_available_v145(p_business uuid, p_branch uuid, p_module text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_active boolean;
  v_mode text;
begin
  if auth.uid() is null
     or p_module is null
     or not app.can_see_branch(p_business, p_branch) then
    return false;
  end if;
  if p_branch is not null then
    select branch.active into v_active
      from public.branches branch
     where branch.id=p_branch and branch.business_id=p_business;
    if not found then return false;end if;
    select resolved.mode into v_mode
      from app.effective_platform_module_mode_v94(
        p_business,case when v_active then p_branch else null end,p_module
      ) resolved;
    return coalesce(v_mode,'disabled')<>'disabled';
  end if;
  select resolved.mode into v_mode
    from app.effective_platform_module_mode_v94(p_business,null,p_module) resolved;
  if coalesce(v_mode,'disabled')='disabled' then return false;end if;
  return not exists (
    select 1
      from public.branches branch
     where branch.business_id=p_business
       and branch.active
       and coalesce((
         select resolved.mode
           from app.effective_platform_module_mode_v94(
             p_business,branch.id,p_module
           ) resolved
       ),'disabled')='disabled'
  );
end;
$$;

--
-- Name: platform_next_document_number_v147(text, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.platform_next_document_number_v147(p_type text, p_prefix text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$ declare v_number bigint;v_code text;begin
  update public.platform_financial_document_sequences_v147 set next_value=next_value+1 where document_type=p_type returning next_value-1 into v_number;
  if v_number is null then raise exception 'unsupported financial document type' using errcode='22023';end if;
  v_code:=case p_type when 'invoice' then 'INV' when 'receipt' then 'RCT' when 'credit_note' then 'CN' when 'debit_note' then 'DN' when 'payment_voucher' then 'PV' else 'JV' end;
  return p_prefix||'-'||v_code||'-'||lpad(v_number::text,6,'0');
end $$;

--
-- Name: platform_post_journal_v147(text, text, date, text, jsonb, uuid, text, uuid, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.platform_post_journal_v147(p_source_type text, p_source_id text, p_date date, p_description text, p_lines jsonb, p_operation_key uuid DEFAULT NULL::uuid, p_request_hash text DEFAULT NULL::text, p_actor uuid DEFAULT NULL::uuid, p_reversal_of uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $_$
declare v_existing public.platform_accounting_journal_entries_v147%rowtype;v_entry public.platform_accounting_journal_entries_v147%rowtype;
  v_hash text;v_debits bigint;v_credits bigint;v_count integer;
begin
  v_hash:=coalesce(p_request_hash,encode(extensions.digest(jsonb_build_object('source_type',p_source_type,'source_id',p_source_id,'date',p_date,'description',btrim(p_description),'lines',p_lines)::text,'sha256'),'hex'));
  perform pg_advisory_xact_lock(hashtextextended(p_source_type||':'||p_source_id,147));
  select * into v_existing from public.platform_accounting_journal_entries_v147 where source_type=p_source_type and source_id=p_source_id;
  if found then
    if v_existing.request_hash<>v_hash then raise exception 'accounting source was reused with different input' using errcode='22023';end if;
    return jsonb_build_object('entry',to_jsonb(v_existing),'replayed',true);
  end if;
  perform pg_advisory_xact_lock(hashtextextended('platform_accounting_period_gate',147));
  if p_date is null or app.platform_accounting_date_locked_v147(p_date) then raise exception 'accounting period is locked or invalid' using errcode='55000';end if;
  if jsonb_typeof(p_lines)<>'array' then raise exception 'journal lines must be an array' using errcode='22023';end if;
  select count(*),coalesce(sum((line->>'debit_cents')::bigint),0),coalesce(sum((line->>'credit_cents')::bigint),0)
    into v_count,v_debits,v_credits from jsonb_array_elements(p_lines) line
   where (line->>'account_code')~'^[0-9]{4}$'
     and coalesce((line->>'debit_cents')::bigint,0)>=0 and coalesce((line->>'credit_cents')::bigint,0)>=0
     and ((coalesce((line->>'debit_cents')::bigint,0)>0 and coalesce((line->>'credit_cents')::bigint,0)=0)
       or (coalesce((line->>'credit_cents')::bigint,0)>0 and coalesce((line->>'debit_cents')::bigint,0)=0));
  if v_count<>jsonb_array_length(p_lines) or v_count<2 or v_debits<=0 or v_debits<>v_credits
     or exists(select 1 from jsonb_array_elements(p_lines) line left join public.platform_accounting_accounts_v147 account on account.code=line->>'account_code' where account.code is null or not account.active) then
    raise exception 'journal must contain valid active accounts and balanced one-sided lines' using errcode='22023';
  end if;
  insert into public.platform_accounting_journal_entries_v147(journal_date,description,source_type,source_id,operation_key,request_hash,reversal_of,created_by)
  values(p_date,btrim(p_description),p_source_type,p_source_id,p_operation_key,v_hash,p_reversal_of,p_actor) returning * into v_entry;
  insert into public.platform_accounting_journal_lines_v147(entry_id,line_number,account_code,debit_cents,credit_cents,memo,counterparty)
  select v_entry.id,ordinality,(line->>'account_code'),coalesce((line->>'debit_cents')::bigint,0),coalesce((line->>'credit_cents')::bigint,0),nullif(btrim(line->>'memo'),''),nullif(btrim(line->>'counterparty'),'')
    from jsonb_array_elements(p_lines) with ordinality rows(line,ordinality);
  insert into public.audit_log(business_id,actor,action,entity,entity_id,detail)
  values(null,p_actor,'PLATFORM_JOURNAL_POSTED_V147','platform_accounting_journal_entries_v147',v_entry.id,jsonb_build_object('journal_number',v_entry.journal_number,'source_type',p_source_type,'source_id',p_source_id,'debits_cents',v_debits));
  return jsonb_build_object('entry',to_jsonb(v_entry),'replayed',false);
end
$_$;

--
-- Name: platform_provider_invoice_trigger_v147(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.platform_provider_invoice_trigger_v147() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$ begin perform app.platform_sync_provider_invoice_v147(new);return new;end $$;

--
-- Name: platform_reverse_journal_v147(uuid, text, text, date, text, uuid, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.platform_reverse_journal_v147(p_original uuid, p_source_type text, p_source_id text, p_date date, p_description text, p_operation_key uuid, p_actor uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_lines jsonb;v_hash text;
begin
  if not exists(select 1 from public.platform_accounting_journal_entries_v147 where id=p_original) then raise exception 'original journal was not found' using errcode='22023';end if;
  select jsonb_agg(jsonb_build_object('account_code',account_code,'debit_cents',credit_cents,'credit_cents',debit_cents,'memo','Reversal: '||coalesce(memo,''),'counterparty',counterparty) order by line_number)
    into v_lines from public.platform_accounting_journal_lines_v147 where entry_id=p_original;
  v_hash:=encode(extensions.digest(jsonb_build_object('original',p_original,'date',p_date,'description',btrim(p_description))::text,'sha256'),'hex');
  return app.platform_post_journal_v147(p_source_type,p_source_id,p_date,p_description,v_lines,p_operation_key,v_hash,p_actor,p_original);
end
$$;

--
-- Name: billing_adjustments; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.billing_adjustments (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    business_id uuid NOT NULL,
    provider_invoice_id text,
    adjustment_type text NOT NULL,
    subtotal_ex_tax_cents integer NOT NULL,
    tax_cents integer NOT NULL,
    total_cents integer NOT NULL,
    currency text NOT NULL,
    source_event_id text,
    provider_object_id text,
    reversal_of uuid,
    reason text NOT NULL,
    evidence_sha256 text NOT NULL,
    recorded_by uuid,
    occurred_at timestamp with time zone NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT billing_adjustments_adjustment_type_check CHECK ((adjustment_type = ANY (ARRAY['credit'::text, 'debit'::text, 'refund'::text, 'chargeback'::text, 'external_payment'::text, 'writeoff'::text, 'reversal'::text]))),
    CONSTRAINT billing_adjustments_amount_check CHECK (((total_cents <> 0) AND (total_cents = (subtotal_ex_tax_cents + tax_cents)) AND
CASE
    WHEN (adjustment_type = ANY (ARRAY['debit'::text, 'external_payment'::text])) THEN ((total_cents > 0) AND (reversal_of IS NULL))
    WHEN (adjustment_type = ANY (ARRAY['credit'::text, 'refund'::text, 'chargeback'::text, 'writeoff'::text])) THEN ((total_cents < 0) AND (reversal_of IS NULL))
    WHEN (adjustment_type = 'reversal'::text) THEN (reversal_of IS NOT NULL)
    ELSE false
END)),
    CONSTRAINT billing_adjustments_currency_check CHECK ((currency ~ '^[A-Z]{3}$'::text)),
    CONSTRAINT billing_adjustments_evidence_sha256_check CHECK ((evidence_sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT billing_adjustments_no_gst_v125_check CHECK ((tax_cents = 0)),
    CONSTRAINT billing_adjustments_reason_check CHECK (((length(btrim(reason)) >= 3) AND (length(btrim(reason)) <= 1000)))
);

--
-- Name: platform_sync_billing_adjustment_v147(public.billing_adjustments); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.platform_sync_billing_adjustment_v147(p_adjustment public.billing_adjustments) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_amount bigint:=abs(p_adjustment.total_cents);v_date date:=(p_adjustment.occurred_at at time zone 'Asia/Singapore')::date;v_result jsonb;v_original uuid;v_lines jsonb;
begin
  if p_adjustment.currency<>'SGD' then return;end if;
  if p_adjustment.adjustment_type='reversal' then
    select id into v_original from public.platform_accounting_journal_entries_v147 where source_type='billing_adjustment' and source_id=p_adjustment.reversal_of::text;
    if v_original is not null then v_result:=app.platform_reverse_journal_v147(v_original,'billing_adjustment',p_adjustment.id::text,v_date,p_adjustment.reason,null,p_adjustment.recorded_by);end if;
    return;
  end if;
  v_lines:=case p_adjustment.adjustment_type
    when 'refund' then jsonb_build_array(jsonb_build_object('account_code','4010','debit_cents',v_amount,'credit_cents',0),jsonb_build_object('account_code','1010','debit_cents',0,'credit_cents',v_amount))
    when 'chargeback' then jsonb_build_array(jsonb_build_object('account_code','6200','debit_cents',v_amount,'credit_cents',0),jsonb_build_object('account_code','1010','debit_cents',0,'credit_cents',v_amount))
    when 'external_payment' then jsonb_build_array(jsonb_build_object('account_code','1000','debit_cents',v_amount,'credit_cents',0),jsonb_build_object('account_code','1100','debit_cents',0,'credit_cents',v_amount))
    when 'credit' then jsonb_build_array(jsonb_build_object('account_code','4010','debit_cents',v_amount,'credit_cents',0),jsonb_build_object('account_code','1100','debit_cents',0,'credit_cents',v_amount))
    when 'debit' then jsonb_build_array(jsonb_build_object('account_code','1100','debit_cents',v_amount,'credit_cents',0),jsonb_build_object('account_code','4090','debit_cents',0,'credit_cents',v_amount))
    when 'writeoff' then jsonb_build_array(jsonb_build_object('account_code','6300','debit_cents',v_amount,'credit_cents',0),jsonb_build_object('account_code','1100','debit_cents',0,'credit_cents',v_amount)) end;
  if v_lines is not null then v_result:=app.platform_post_journal_v147('billing_adjustment',p_adjustment.id::text,v_date,p_adjustment.reason,v_lines,null,null,p_adjustment.recorded_by,null);end if;
end
$$;

--
-- Name: platform_operating_expense_entries_v146; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.platform_operating_expense_entries_v146 (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    entry_type text NOT NULL,
    reversal_of uuid,
    expense_date date NOT NULL,
    category text NOT NULL,
    description text NOT NULL,
    amount_cents integer NOT NULL,
    currency text DEFAULT 'SGD'::text NOT NULL,
    recorded_by uuid NOT NULL,
    idempotency_key uuid NOT NULL,
    request_hash text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    counterparty_name text,
    counterparty_registration_number text,
    payment_reference text,
    evidence_reference text,
    CONSTRAINT platform_expense_counterparty_v147_check CHECK (((counterparty_name IS NULL) OR ((length(btrim(counterparty_name)) >= 2) AND (length(btrim(counterparty_name)) <= 200)))),
    CONSTRAINT platform_expense_evidence_v147_check CHECK (((evidence_reference IS NULL) OR ((length(btrim(evidence_reference)) >= 8) AND (length(btrim(evidence_reference)) <= 300)))),
    CONSTRAINT platform_expense_payment_reference_v147_check CHECK (((payment_reference IS NULL) OR ((length(btrim(payment_reference)) >= 3) AND (length(btrim(payment_reference)) <= 200)))),
    CONSTRAINT platform_operating_expense_entries_v146_amount_cents_check CHECK ((amount_cents > 0)),
    CONSTRAINT platform_operating_expense_entries_v146_category_check CHECK ((category = ANY (ARRAY['software'::text, 'marketing'::text, 'professional_services'::text, 'banking'::text, 'operations'::text, 'other'::text]))),
    CONSTRAINT platform_operating_expense_entries_v146_currency_check CHECK ((currency = 'SGD'::text)),
    CONSTRAINT platform_operating_expense_entries_v146_description_check CHECK (((length(btrim(description)) >= 3) AND (length(btrim(description)) <= 240))),
    CONSTRAINT platform_operating_expense_entries_v146_entry_type_check CHECK ((entry_type = ANY (ARRAY['expense'::text, 'reversal'::text]))),
    CONSTRAINT platform_operating_expense_entries_v146_request_hash_check CHECK ((request_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT platform_operating_expense_entry_shape_v146_check CHECK ((((entry_type = 'expense'::text) AND (reversal_of IS NULL)) OR ((entry_type = 'reversal'::text) AND (reversal_of IS NOT NULL))))
);

--
-- Name: platform_sync_expense_document_v147(public.platform_operating_expense_entries_v146); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.platform_sync_expense_document_v147(p_expense public.platform_operating_expense_entries_v146) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_policy public.platform_accounting_policies_v147%rowtype;v_journal uuid;v_original public.platform_financial_documents_v147%rowtype;v_id uuid:=(md5('platform-expense-document:'||p_expense.id::text))::uuid;v_operation uuid:=(md5('platform-expense-operation:'||p_expense.id::text))::uuid;v_number text;v_snapshot jsonb;v_type text;v_source text;v_original_id uuid;
begin
  perform pg_advisory_xact_lock(hashtextextended('platform-expense-document:'||p_expense.id::text,147));
  if exists(select 1 from public.platform_financial_documents_v147 where source_type in ('platform_expense_voucher','platform_expense_reversal_voucher') and source_id=p_expense.id::text) then return;end if;
  select * into v_policy from public.platform_accounting_policies_v147 where effective_from<=p_expense.expense_date order by effective_from desc,version desc limit 1;
  if v_policy.id is null then return;end if;
  select id into v_journal from public.platform_accounting_journal_entries_v147 where source_type='platform_expense' and source_id=p_expense.id::text;
  if not found or v_journal is null then return;end if;
  if p_expense.entry_type='expense' then
    if p_expense.counterparty_name is null or p_expense.payment_reference is null or p_expense.evidence_reference is null then return;end if;
    v_type:='payment_voucher';v_source:='platform_expense_voucher';v_number:=app.platform_next_document_number_v147(v_type,v_policy.document_prefix);
    v_snapshot:=jsonb_build_object('issuer',app.platform_document_issuer_v147(v_policy),'number',v_number,'expense_date',p_expense.expense_date,'counterparty',jsonb_build_object('legal_name',p_expense.counterparty_name,'registration_number',p_expense.counterparty_registration_number),'description',p_expense.description,'category',p_expense.category,'amount_cents',p_expense.amount_cents,'payment_reference',p_expense.payment_reference,'evidence_reference',p_expense.evidence_reference,'currency','SGD');
  else
    select * into v_original from public.platform_financial_documents_v147 where source_type='platform_expense_voucher' and source_id=p_expense.reversal_of::text;
    if not found then return;end if;
    v_type:='journal_voucher';v_source:='platform_expense_reversal_voucher';v_original_id:=v_original.id;v_number:=app.platform_next_document_number_v147(v_type,v_policy.document_prefix);
    v_snapshot:=jsonb_build_object('issuer',v_original.snapshot->'issuer','number',v_number,'original_number',v_original.document_number,'reversal_date',p_expense.expense_date,'reason',p_expense.description,'amount_cents',p_expense.amount_cents,'currency','SGD');
  end if;
  insert into public.platform_financial_documents_v147(id,document_type,document_number,issue_date,counterparty,line_items,subtotal_cents,tax_cents,total_cents,source_type,source_id,original_document,journal_entry,snapshot,snapshot_sha256,operation_key,request_hash,created_by)
  values(v_id,v_type,v_number,p_expense.expense_date,coalesce(v_original.counterparty,jsonb_build_object('legal_name',p_expense.counterparty_name,'registration_number',p_expense.counterparty_registration_number)),jsonb_build_array(jsonb_build_object('description',p_expense.description,'quantity',1,'unit_amount_cents',p_expense.amount_cents)),p_expense.amount_cents,0,p_expense.amount_cents,v_source,p_expense.id::text,v_original_id,v_journal,v_snapshot,encode(extensions.digest(v_snapshot::text,'sha256'),'hex'),v_operation,p_expense.request_hash,p_expense.recorded_by);
end
$$;

--
-- Name: platform_sync_expense_v147(public.platform_operating_expense_entries_v146); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.platform_sync_expense_v147(p_expense public.platform_operating_expense_entries_v146) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_result jsonb;v_original uuid;v_lines jsonb;
begin
  if p_expense.currency<>'SGD' then return;end if;
  if p_expense.entry_type='reversal' then
    select id into v_original from public.platform_accounting_journal_entries_v147 where source_type='platform_expense' and source_id=p_expense.reversal_of::text;
    if v_original is not null then v_result:=app.platform_reverse_journal_v147(v_original,'platform_expense',p_expense.id::text,p_expense.expense_date,p_expense.description,null,p_expense.recorded_by);end if;
  else
    v_lines:=jsonb_build_array(jsonb_build_object('account_code',app.platform_expense_account_v147(p_expense.category),'debit_cents',p_expense.amount_cents,'credit_cents',0),jsonb_build_object('account_code','1000','debit_cents',0,'credit_cents',p_expense.amount_cents));
    v_result:=app.platform_post_journal_v147('platform_expense',p_expense.id::text,p_expense.expense_date,p_expense.description,v_lines,null,null,p_expense.recorded_by,null);
  end if;
end
$$;

--
-- Name: billing_provider_events; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.billing_provider_events (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    provider text DEFAULT 'stripe'::text NOT NULL,
    event_id text NOT NULL,
    event_type text NOT NULL,
    object_id text NOT NULL,
    event_created_at timestamp with time zone NOT NULL,
    livemode boolean NOT NULL,
    api_version text,
    payload jsonb NOT NULL,
    payload_sha256 text NOT NULL,
    processing_status text DEFAULT 'pending'::text NOT NULL,
    processing_attempts integer DEFAULT 0 NOT NULL,
    business_id uuid,
    processed_at timestamp with time zone,
    last_error text,
    received_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT billing_provider_events_payload_sha256_check CHECK ((payload_sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT billing_provider_events_processing_attempts_check CHECK ((processing_attempts >= 0)),
    CONSTRAINT billing_provider_events_processing_status_check CHECK ((processing_status = ANY (ARRAY['pending'::text, 'processing'::text, 'processed'::text, 'ignored'::text, 'failed'::text]))),
    CONSTRAINT billing_provider_events_provider_check CHECK ((provider = 'stripe'::text))
);

--
-- Name: platform_sync_provider_invoice_event_v147(public.billing_provider_events); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.platform_sync_provider_invoice_event_v147(p_event public.billing_provider_events) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_object jsonb:=p_event.payload#>'{data,object}';v_invoice public.billing_provider_invoices%rowtype;v_subtotal integer;v_total integer;
begin
  if p_event.processing_status<>'processed' or p_event.event_type not like 'invoice.%' or jsonb_typeof(v_object)<>'object' then return;end if;
  select * into v_invoice from public.billing_provider_invoices where provider_invoice_id=coalesce(v_object->>'id',p_event.object_id);
  if not found then return;end if;
  v_subtotal:=greatest(coalesce(nullif(v_object->>'total_excluding_tax','')::integer,nullif(v_object->>'subtotal_excluding_tax','')::integer,nullif(v_object->>'subtotal','')::integer,v_invoice.subtotal_ex_tax_cents),0);
  v_total:=greatest(coalesce(nullif(v_object->>'total','')::integer,v_subtotal),0);
  v_invoice.business_id:=coalesce(p_event.business_id,v_invoice.business_id);
  v_invoice.provider_invoice_id:=coalesce(v_object->>'id',p_event.object_id);
  v_invoice.currency:=upper(coalesce(nullif(v_object->>'currency',''),v_invoice.currency));
  v_invoice.status:=case when p_event.event_type='invoice.paid' then 'paid' when p_event.event_type='invoice.voided' then 'void' when p_event.event_type='invoice.marked_uncollectible' then 'uncollectible' when v_object->>'status' in ('draft','open','void','uncollectible') then v_object->>'status' else 'open' end;
  v_invoice.paid_normalized:=p_event.event_type='invoice.paid';
  v_invoice.subtotal_ex_tax_cents:=v_subtotal;v_invoice.total_cents:=v_total;v_invoice.tax_cents:=greatest(v_total-v_subtotal,0);
  v_invoice.amount_paid_cents:=greatest(coalesce(nullif(v_object->>'amount_paid','')::integer,0),0);
  v_invoice.amount_remaining_cents:=greatest(coalesce(nullif(v_object->>'amount_remaining','')::integer,v_total-v_invoice.amount_paid_cents,0),0);
  v_invoice.provider_event_created_at:=p_event.event_created_at;
  v_invoice.paid_at:=case when p_event.event_type='invoice.paid' then coalesce(app.stripe_epoch_v77(v_object#>'{status_transitions,paid_at}'),p_event.event_created_at) end;
  v_invoice.voided_at:=case when p_event.event_type='invoice.voided' then coalesce(app.stripe_epoch_v77(v_object#>'{status_transitions,voided_at}'),p_event.event_created_at) end;
  v_invoice.marked_uncollectible_at:=case when p_event.event_type='invoice.marked_uncollectible' then coalesce(app.stripe_epoch_v77(v_object#>'{status_transitions,marked_uncollectible_at}'),p_event.event_created_at) end;
  perform app.platform_sync_provider_invoice_v147(v_invoice);
end
$$;

--
-- Name: platform_sync_provider_invoice_v147(public.billing_provider_invoices); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.platform_sync_provider_invoice_v147(p_invoice public.billing_provider_invoices) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_date date;v_result jsonb;v_counterparty text:=p_invoice.business_id::text;v_issued uuid;v_terminal uuid;
  v_target_paid bigint:=least(p_invoice.total_cents,p_invoice.amount_paid_cents);v_posted_paid bigint;v_payment_delta bigint;
  v_remaining bigint;v_remaining_tax bigint;v_remaining_subtotal bigint;v_lines jsonb;
  v_terminal_total bigint;v_recovered_total bigint;v_recovery_delta bigint;v_recovered_tax bigint;v_prior_recovered_tax bigint;v_recovery_tax bigint;v_recovery_subtotal bigint;
begin
  if p_invoice.currency<>'SGD' or p_invoice.status='draft' or p_invoice.total_cents<=0 then return;end if;
  perform pg_advisory_xact_lock(hashtextextended('platform_provider_invoice_state:'||p_invoice.provider_invoice_id,147));
  v_date:=(coalesce(p_invoice.created_at,clock_timestamp()) at time zone 'Asia/Singapore')::date;
  select id into v_issued from public.platform_accounting_journal_entries_v147 where source_type='provider_invoice_issued' and source_id=p_invoice.provider_invoice_id;
  if v_issued is null then
    v_result:=app.platform_post_journal_v147('provider_invoice_issued',p_invoice.provider_invoice_id,v_date,'Provider invoice '||p_invoice.provider_invoice_id||' issued',jsonb_build_array(
      jsonb_build_object('account_code','1100','debit_cents',p_invoice.total_cents,'credit_cents',0,'counterparty',v_counterparty),
      jsonb_build_object('account_code','4000','debit_cents',0,'credit_cents',p_invoice.subtotal_ex_tax_cents,'counterparty',v_counterparty)
    )||case when p_invoice.tax_cents>0 then jsonb_build_array(jsonb_build_object('account_code','2200','debit_cents',0,'credit_cents',p_invoice.tax_cents,'counterparty',v_counterparty)) else '[]'::jsonb end,null,null,null,null);
    v_issued:=(v_result#>>'{entry,id}')::uuid;
  end if;

  select coalesce(sum(line.debit_cents),0) into v_posted_paid
    from public.platform_accounting_journal_entries_v147 entry join public.platform_accounting_journal_lines_v147 line on line.entry_id=entry.id and line.account_code='1010'
   where entry.source_type='provider_invoice_payment' and left(entry.source_id,length(p_invoice.provider_invoice_id)+1)=p_invoice.provider_invoice_id||':';
  v_payment_delta:=greatest(0,v_target_paid-v_posted_paid);
  if v_payment_delta>0 then
    v_date:=(coalesce(p_invoice.paid_at,p_invoice.provider_event_created_at,p_invoice.created_at) at time zone 'Asia/Singapore')::date;
    select id into v_terminal from public.platform_accounting_journal_entries_v147 where source_type='provider_invoice_uncollectible' and source_id=p_invoice.provider_invoice_id;
    if v_terminal is not null and not exists(select 1 from public.platform_accounting_journal_entries_v147 where source_type='provider_invoice_uncollectible_to_void' and source_id=p_invoice.provider_invoice_id) then
      select coalesce(sum(debit_cents),0) into v_terminal_total from public.platform_accounting_journal_lines_v147 where entry_id=v_terminal and account_code='6300';
      select coalesce(sum(line.credit_cents),0) into v_recovered_total from public.platform_accounting_journal_entries_v147 entry join public.platform_accounting_journal_lines_v147 line on line.entry_id=entry.id and line.account_code='6300' where entry.source_type='provider_invoice_uncollectible_recovery' and left(entry.source_id,length(p_invoice.provider_invoice_id)+1)=p_invoice.provider_invoice_id||':';
      v_recovery_delta:=least(v_payment_delta,greatest(0,v_terminal_total-v_recovered_total));
      if v_recovery_delta>0 then
        v_result:=app.platform_post_journal_v147('provider_invoice_uncollectible_recovery',p_invoice.provider_invoice_id||':'||v_target_paid,v_date,'Recovery of uncollectible provider invoice '||p_invoice.provider_invoice_id,jsonb_build_array(
          jsonb_build_object('account_code','1100','debit_cents',v_recovery_delta,'credit_cents',0,'counterparty',v_counterparty),
          jsonb_build_object('account_code','6300','debit_cents',0,'credit_cents',v_recovery_delta,'counterparty',v_counterparty)
        ),null,null,null,v_terminal);
      end if;
    end if;
    select id into v_terminal from public.platform_accounting_journal_entries_v147 where source_type='provider_invoice_void' and source_id=p_invoice.provider_invoice_id;
    if v_terminal is not null then
      select coalesce(sum(credit_cents),0) into v_terminal_total from public.platform_accounting_journal_lines_v147 where entry_id=v_terminal and account_code='1100';
      select coalesce(sum(line.debit_cents),0),coalesce(sum(line.credit_cents) filter(where line.account_code='2200'),0)
        into v_recovered_total,v_prior_recovered_tax from public.platform_accounting_journal_entries_v147 entry join public.platform_accounting_journal_lines_v147 line on line.entry_id=entry.id where entry.source_type='provider_invoice_void_recovery' and left(entry.source_id,length(p_invoice.provider_invoice_id)+1)=p_invoice.provider_invoice_id||':' and line.account_code in ('1100','2200');
      v_recovery_delta:=least(v_payment_delta,greatest(0,v_terminal_total-v_recovered_total));
      if v_recovery_delta>0 then
        v_recovered_tax:=round((v_recovered_total+v_recovery_delta)*p_invoice.tax_cents::numeric/p_invoice.total_cents);
        v_recovery_tax:=v_recovered_tax-v_prior_recovered_tax;v_recovery_subtotal:=v_recovery_delta-v_recovery_tax;
        v_lines:=jsonb_build_array(jsonb_build_object('account_code','1100','debit_cents',v_recovery_delta,'credit_cents',0,'counterparty',v_counterparty),jsonb_build_object('account_code','4000','debit_cents',0,'credit_cents',v_recovery_subtotal,'counterparty',v_counterparty))||case when v_recovery_tax>0 then jsonb_build_array(jsonb_build_object('account_code','2200','debit_cents',0,'credit_cents',v_recovery_tax,'counterparty',v_counterparty)) else '[]'::jsonb end;
        v_result:=app.platform_post_journal_v147('provider_invoice_void_recovery',p_invoice.provider_invoice_id||':'||v_target_paid,v_date,'Recovery of void provider invoice '||p_invoice.provider_invoice_id,v_lines,null,null,null,v_terminal);
      end if;
    end if;
    v_result:=app.platform_post_journal_v147('provider_invoice_payment',p_invoice.provider_invoice_id||':'||v_target_paid,v_date,'Provider invoice payment '||p_invoice.provider_invoice_id,jsonb_build_array(
      jsonb_build_object('account_code','1010','debit_cents',v_payment_delta,'credit_cents',0,'counterparty',v_counterparty),
      jsonb_build_object('account_code','1100','debit_cents',0,'credit_cents',v_payment_delta,'counterparty',v_counterparty)
    ),null,null,null,null);
  end if;

  if p_invoice.status='void' then
    select id into v_terminal from public.platform_accounting_journal_entries_v147 where source_type='provider_invoice_uncollectible' and source_id=p_invoice.provider_invoice_id;
    if v_terminal is not null and not exists(select 1 from public.platform_accounting_journal_entries_v147 where source_type='provider_invoice_uncollectible_to_void' and source_id=p_invoice.provider_invoice_id) then
      select coalesce(sum(debit_cents),0) into v_terminal_total from public.platform_accounting_journal_lines_v147 where entry_id=v_terminal and account_code='6300';
      select coalesce(sum(line.credit_cents),0) into v_recovered_total from public.platform_accounting_journal_entries_v147 entry join public.platform_accounting_journal_lines_v147 line on line.entry_id=entry.id and line.account_code='6300' where entry.source_type='provider_invoice_uncollectible_recovery' and left(entry.source_id,length(p_invoice.provider_invoice_id)+1)=p_invoice.provider_invoice_id||':';
      v_recovery_delta:=greatest(0,v_terminal_total-v_recovered_total);
      if v_recovery_delta>0 then
        v_date:=(coalesce(p_invoice.voided_at,p_invoice.provider_event_created_at,p_invoice.created_at) at time zone 'Asia/Singapore')::date;
        v_result:=app.platform_post_journal_v147('provider_invoice_uncollectible_to_void',p_invoice.provider_invoice_id,v_date,'Reclassify uncollectible provider invoice before void '||p_invoice.provider_invoice_id,jsonb_build_array(
          jsonb_build_object('account_code','1100','debit_cents',v_recovery_delta,'credit_cents',0,'counterparty',v_counterparty),
          jsonb_build_object('account_code','6300','debit_cents',0,'credit_cents',v_recovery_delta,'counterparty',v_counterparty)
        ),null,null,null,v_terminal);
      end if;
    end if;
  end if;

  if p_invoice.status in ('void','uncollectible') then
    select id into v_terminal from public.platform_accounting_journal_entries_v147 where source_type=case when p_invoice.status='void' then 'provider_invoice_void' else 'provider_invoice_uncollectible' end and source_id=p_invoice.provider_invoice_id;
    v_remaining:=greatest(0,p_invoice.total_cents-v_target_paid);
    if v_terminal is null and v_remaining>0 then
      v_date:=(coalesce(case when p_invoice.status='void' then p_invoice.voided_at else p_invoice.marked_uncollectible_at end,p_invoice.provider_event_created_at,p_invoice.created_at) at time zone 'Asia/Singapore')::date;
      if p_invoice.status='void' then
        v_remaining_tax:=round(v_remaining*p_invoice.tax_cents::numeric/p_invoice.total_cents);
        v_remaining_subtotal:=v_remaining-v_remaining_tax;
        v_lines:=jsonb_build_array(
          jsonb_build_object('account_code','4000','debit_cents',v_remaining_subtotal,'credit_cents',0,'counterparty',v_counterparty),
          jsonb_build_object('account_code','1100','debit_cents',0,'credit_cents',v_remaining,'counterparty',v_counterparty)
        )||case when v_remaining_tax>0 then jsonb_build_array(jsonb_build_object('account_code','2200','debit_cents',v_remaining_tax,'credit_cents',0,'counterparty',v_counterparty)) else '[]'::jsonb end;
        v_result:=app.platform_post_journal_v147('provider_invoice_void',p_invoice.provider_invoice_id,v_date,'Void provider invoice '||p_invoice.provider_invoice_id,v_lines,null,null,null,v_issued);
      else
        v_result:=app.platform_post_journal_v147('provider_invoice_uncollectible',p_invoice.provider_invoice_id,v_date,'Provider invoice marked uncollectible '||p_invoice.provider_invoice_id,jsonb_build_array(
          jsonb_build_object('account_code','6300','debit_cents',v_remaining,'credit_cents',0,'counterparty',v_counterparty),
          jsonb_build_object('account_code','1100','debit_cents',0,'credit_cents',v_remaining,'counterparty',v_counterparty)
        ),null,null,null,v_issued);
      end if;
    end if;
  end if;
end
$$;

--
-- Name: points_mode_frozen_v314(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.points_mode_frozen_v314() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if new.points_mode is distinct from old.points_mode then
    -- The named escape, for migrations and for a deliberate platform repair. Transaction-local
    -- (set_config(..., true)); nothing in the product sets it.
    if coalesce(nullif(current_setting('app.points_mode_write_ok', true), ''), '') = 'v314' then
      return new;
    end if;
    insert into public.audit_log (business_id, actor, action, entity, entity_id, detail)
    values (new.id, auth.uid(), 'POINTS_MODE_WRITE_SUPPRESSED_V314', 'businesses', new.id,
            jsonb_build_object('attempted', new.points_mode, 'kept', old.points_mode));
    new.points_mode := old.points_mode;
  end if;
  return new;
end
$$;

--
-- Name: FUNCTION points_mode_frozen_v314(); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.points_mode_frozen_v314() IS 'v314 W6i1 tripwire on businesses.points_mode. SWALLOWS the write (pins the column to its old value) and records one audit_log row POINTS_MODE_WRITE_SUPPRESSED_V314 rather than raising — deliberate weakening of the design contract (brief R4). /app-*.js is CDN-pinned for about four hours, so the OLD bundle keeps PATCHing this column after every wizard publish for that long, and a raise would surface as a publish error to every owner in the window. Increment 9 upgrades it to a raise once the audit table proves zero writers remain. Escape GUC: set_config(''app.points_mode_write_ok'',''v314'',true).';

--
-- Name: preserve_current_promotion_event_v122(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.preserve_current_promotion_event_v122() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if exists(
    select 1
    from public.customer_in_app_inbox_events event
    join public.business_customer_content_v95 content
      on content.business_id=event.business_id
     and content.content_type='offer'
     and content.metadata->>'schema'='nestly.promotion.v104'
     and content.active
     and content.branch_id is null
     and (content.starts_at is null or content.starts_at<=now())
     and content.ends_at>now()
     and event.source_fingerprint=app.c46_sha256_hex((jsonb_build_object(
       'promotion_id',content.id,'source_kind',event.source_kind,
       'published_once_at',content.metadata->>'published_once_at'
     ) || case when event.source_kind='v122_promotion_expiry'
       then jsonb_build_object('ends_at',content.ends_at)
       else '{}'::jsonb end)::text)
    where event.id=new.event_id
      and event.source_kind in('v122_promotion_new','v122_promotion_expiry')
      and exists(
        select 1 from public.business_media_assets_v95 asset
        where asset.business_id=content.business_id
          and asset.asset_kind='offer'
          and asset.entity_id=content.id
          and asset.customer_visible
          and asset.branch_id is null
      )
  ) then
    return null;
  end if;
  return new;
end
$$;

--
-- Name: program_entitlement_guard(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.program_entitlement_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if tg_op = 'DELETE' then raise exception 'program_entitlements is append-only' using errcode = 'restrict_violation'; end if;
  if tg_op = 'UPDATE' then
    if new.id is distinct from old.id or new.business_id is distinct from old.business_id
       or new.client_id is distinct from old.client_id or new.rule_id is distinct from old.rule_id
       or new.config_version_id is distinct from old.config_version_id or new.period_key is distinct from old.period_key
       or new.benefit_snapshot is distinct from old.benefit_snapshot or new.valid_from is distinct from old.valid_from
       or new.fulfilment_kind is distinct from old.fulfilment_kind
       -- budget_reservation_id is write-once: the reservation row is created after
       -- the entitlement (they reference each other), so null -> value is the
       -- sanctioned linking step; once linked it is immutable.
       or (new.budget_reservation_id is distinct from old.budget_reservation_id
           and old.budget_reservation_id is not null) then
      raise exception 'program entitlement identity and economics are immutable' using errcode = 'restrict_violation';
    end if;
    -- available -> redeemed | expired | reversed, plus the one sanctioned
    -- post-terminal move: redeemed -> reversed (owner correction of a
    -- mistaken redemption, c45 pattern — the RPC enforces owner-only).
    if old.status <> 'available' and new.status <> old.status
       and not (old.status = 'redeemed' and new.status = 'reversed') then
      raise exception 'program entitlement is terminal' using errcode = 'restrict_violation';
    end if;
  end if;
  return new;
end $$;

--
-- Name: program_rule_canonical(jsonb); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.program_rule_canonical(p_rule jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  select jsonb_build_object(
    'schema_version', coalesce(nullif(p_rule->>'schema_version', '')::smallint, 1),
    'when',   p_rule->>'when_event',
    'if',     coalesce((select jsonb_agg(c order by c->>'field', c->>'op', c::text)
                          from jsonb_array_elements(coalesce(p_rule->'if_conditions', '[]'::jsonb)) c), '[]'::jsonb),
    'then',   coalesce((select jsonb_agg(e order by e->>'effect_type', e::text)
                          from jsonb_array_elements(coalesce(p_rule->'then_effects', '[]'::jsonb)) e), '[]'::jsonb),
    'with',   coalesce(p_rule->'with_params', '{}'::jsonb),
    'during', coalesce(p_rule->'during_schedule', '{}'::jsonb),
    'using',  coalesce(p_rule->'using_stacking', '{}'::jsonb)
  )
$$;

--
-- Name: program_rule_errors(uuid, jsonb); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.program_rule_errors(p_business uuid, p_rule jsonb) RETURNS text[]
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_err text[] := array[]::text[];
  v_schema smallint;
  v_event text;
  v_if jsonb; v_then jsonb; v_with jsonb; v_during jsonb; v_using jsonb;
  v_events text[];
  c jsonb; e jsonb; d jsonb;
  v_field text; v_op text; v_val jsonb;
  v_ops text[]; v_vtype text; v_kind text;
  v_tz text;
  v_max_cond constant integer := 10;
  v_max_eff  constant integer := 8;
begin
  if p_rule is null or jsonb_typeof(p_rule) <> 'object' then
    return array['rule_not_object'];
  end if;
  if exists(select 1 from jsonb_object_keys(p_rule) k where k not in
      ('name','active','schema_version','when_event','if_conditions','then_effects',
       'with_params','during_schedule','using_stacking','sort','notes')) then
    v_err := v_err || 'unsupported_rule_field'::text;
  end if;

  v_schema := coalesce(nullif(p_rule->>'schema_version', '')::smallint, 1);
  if not exists(select 1 from public.rule_schema_versions where schema_version = v_schema and status = 'active') then
    v_err := v_err || 'invalid_schema_version'::text;
  end if;

  v_event := p_rule->>'when_event';
  select array_agg(distinct ev) into v_events from (
    select event_type ev from public.rule_condition_allowlist where schema_version = v_schema
    union
    select event_type    from public.rule_effect_allowlist    where schema_version = v_schema
  ) s;
  if v_event is null or not (v_event = any(coalesce(v_events, array[]::text[]))) then
    v_err := v_err || 'invalid_event'::text;
    return v_err;  -- fields cannot be judged without a known event
  end if;

  v_if     := coalesce(p_rule->'if_conditions',  '[]'::jsonb);
  v_then   := coalesce(p_rule->'then_effects',   '[]'::jsonb);
  v_with   := coalesce(p_rule->'with_params',    '{}'::jsonb);
  v_during := coalesce(p_rule->'during_schedule','{}'::jsonb);
  v_using  := coalesce(p_rule->'using_stacking', '{}'::jsonb);

  if jsonb_typeof(v_if) <> 'array' then v_err := v_err || 'if_not_array'::text;
  elsif jsonb_array_length(v_if) > v_max_cond then v_err := v_err || 'too_many_conditions'::text;
  end if;
  if jsonb_typeof(v_then) <> 'array' then v_err := v_err || 'then_not_array'::text;
  elsif jsonb_array_length(v_then) > v_max_eff then v_err := v_err || 'too_many_effects'::text;
  end if;

  -- conditions
  if jsonb_typeof(v_if) = 'array' then
    for c in select * from jsonb_array_elements(v_if) loop
      if jsonb_typeof(c) <> 'object' then v_err := v_err || 'condition_not_object'::text; continue; end if;
      if exists(select 1 from jsonb_object_keys(c) k where k not in ('field','op','value')) then
        v_err := v_err || 'condition_unsupported_key'::text;
      end if;
      v_field := c->>'field'; v_op := c->>'op'; v_val := c->'value';
      select operators, value_type, catalog_kind into v_ops, v_vtype, v_kind
        from public.rule_condition_allowlist
       where schema_version = v_schema and event_type = v_event and field = v_field;
      if not found then v_err := v_err || ('unknown_condition_field:' || coalesce(v_field, '?')); continue; end if;
      if v_op is null or not (v_op = any(v_ops)) then v_err := v_err || ('invalid_operator:' || coalesce(v_op, '?')); end if;
      if v_op in ('in','not_in') and jsonb_typeof(v_val) <> 'array' then v_err := v_err || 'in_requires_array'::text; end if;
      if v_op = 'between' and (jsonb_typeof(v_val) <> 'array' or jsonb_array_length(v_val) <> 2) then v_err := v_err || 'between_requires_pair'::text; end if;
      if v_vtype = 'catalog_ref' then
        if jsonb_typeof(v_val) = 'array' then
          for d in select * from jsonb_array_elements(v_val) loop
            if not app.ps1a_catalog_ref_valid(p_business, v_kind, nullif(d#>>'{}', '')::uuid) then v_err := v_err || ('catalog_ref_not_found:' || v_kind); end if;
          end loop;
        else
          if not app.ps1a_catalog_ref_valid(p_business, v_kind, nullif(v_val#>>'{}', '')::uuid) then v_err := v_err || ('catalog_ref_not_found:' || v_kind); end if;
        end if;
      end if;
    end loop;
  end if;

  -- effects
  if jsonb_typeof(v_then) = 'array' then
    for e in select * from jsonb_array_elements(v_then) loop
      if jsonb_typeof(e) <> 'object' then v_err := v_err || 'effect_not_object'::text; continue; end if;
      if exists(select 1 from jsonb_object_keys(e) k where k not in
          ('effect_type','amount_cents','discount_pct','points','stamps','multiplier','catalog_kind','catalog_id','note')) then
        v_err := v_err || 'effect_unsupported_key'::text;
      end if;
      -- structural bars: no client-supplied price, no SQL fragment surface
      if e ? 'price_cents' or e ? 'unit_price_cents' or e ? 'catalog_price' then v_err := v_err || 'client_supplied_price'::text; end if;
      if e ? 'sql' or e ? 'expr' or e ? 'expression' or e ? 'raw' then v_err := v_err || 'sql_fragment_forbidden'::text; end if;
      if not exists(select 1 from public.rule_effect_allowlist
          where schema_version = v_schema and event_type = v_event and effect_type = e->>'effect_type') then
        v_err := v_err || ('invalid_effect:' || coalesce(e->>'effect_type', '?')); continue;
      end if;
      case e->>'effect_type'
        when 'grant_credit' then
          if coalesce(nullif(e->>'amount_cents', '')::integer, 0) <= 0 then v_err := v_err || 'effect_amount_required'::text; end if;
        when 'apply_discount_amount' then
          if coalesce(nullif(e->>'amount_cents', '')::integer, 0) <= 0 then v_err := v_err || 'effect_amount_required'::text; end if;
        when 'apply_discount_pct' then
          if not (coalesce(nullif(e->>'discount_pct', '')::numeric, 0) > 0 and (e->>'discount_pct')::numeric <= 100) then v_err := v_err || 'effect_discount_pct_range'::text; end if;
        when 'earn_bonus_points' then
          if coalesce(nullif(e->>'points', '')::integer, 0) <= 0 then v_err := v_err || 'effect_points_required'::text; end if;
        when 'earn_bonus_stamps' then
          if coalesce(nullif(e->>'stamps', '')::integer, 0) <= 0 then v_err := v_err || 'effect_stamps_required'::text; end if;
        when 'tier_multiplier' then
          if coalesce(nullif(e->>'multiplier', '')::numeric, 0) < 1 then v_err := v_err || 'effect_multiplier_range'::text; end if;
        when 'grant_free_item' then
          if not app.ps1a_catalog_ref_valid(p_business, e->>'catalog_kind', nullif(e->>'catalog_id', '')::uuid) then v_err := v_err || 'effect_catalog_ref_not_found'::text; end if;
        else null;
      end case;
    end loop;
  end if;

  -- schedule sanity (SGT only)
  if v_during <> '{}'::jsonb then
    if jsonb_typeof(v_during) <> 'object' then v_err := v_err || 'schedule_not_object'::text;
    else
      if exists(select 1 from jsonb_object_keys(v_during) k where k not in
          ('timezone','start_date','end_date','days_of_week','start_time','end_time')) then
        v_err := v_err || 'schedule_unsupported_key'::text;
      end if;
      v_tz := v_during->>'timezone';
      if v_tz is not null and v_tz <> 'Asia/Singapore' then v_err := v_err || 'schedule_non_sgt'::text; end if;
      begin
        if (v_during ? 'start_date') and (v_during ? 'end_date')
           and (v_during->>'end_date')::date < (v_during->>'start_date')::date then
          v_err := v_err || 'schedule_end_before_start'::text;
        end if;
      exception when others then v_err := v_err || 'schedule_bad_date'::text; end;
      if v_during ? 'days_of_week' then
        if jsonb_typeof(v_during->'days_of_week') <> 'array' then v_err := v_err || 'schedule_dow_not_array'::text;
        else
          for d in select * from jsonb_array_elements(v_during->'days_of_week') loop
            if jsonb_typeof(d) <> 'number' or (d#>>'{}')::integer not between 0 and 6 then v_err := v_err || 'schedule_dow_range'::text; end if;
          end loop;
        end if;
      end if;
      begin
        if v_during ? 'start_time' then perform (v_during->>'start_time')::time; end if;
        if v_during ? 'end_time'   then perform (v_during->>'end_time')::time; end if;
      exception when others then v_err := v_err || 'schedule_bad_time'::text; end;
    end if;
  end if;

  -- stacking sanity
  if v_using <> '{}'::jsonb then
    if jsonb_typeof(v_using) <> 'object' then v_err := v_err || 'stacking_not_object'::text;
    else
      if exists(select 1 from jsonb_object_keys(v_using) k where k not in
          ('stackable','priority','max_stack','exclusive_group')) then
        v_err := v_err || 'stacking_unsupported_key'::text;
      end if;
      if (v_using ? 'stackable') and jsonb_typeof(v_using->'stackable') <> 'boolean' then v_err := v_err || 'stacking_stackable_type'::text; end if;
      begin
        if v_using ? 'priority'  then perform (v_using->>'priority')::integer; end if;
        if (v_using ? 'max_stack') and (v_using->>'max_stack')::integer < 1 then v_err := v_err || 'stacking_max_stack_range'::text; end if;
      exception when others then v_err := v_err || 'stacking_bad_number'::text; end;
    end if;
  end if;

  return v_err;
end $$;

--
-- Name: program_rule_hash(jsonb); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.program_rule_hash(p_rule jsonb) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$ select app.ps1a_sha256(app.program_rule_canonical(p_rule)::text) $$;

--
-- Name: program_rule_version_guard(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.program_rule_version_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_version uuid := case when tg_op = 'DELETE' then old.config_version_id else new.config_version_id end;
        v_status text;
begin
  select status into v_status from public.firm_config_versions where id = v_version;
  if v_status is distinct from 'draft' then
    raise exception 'published program rule configuration is immutable'
      using errcode = 'restrict_violation';
  end if;
  if tg_op = 'DELETE' then return old; end if;
  if tg_op = 'UPDATE' and (
       new.rule_id is distinct from old.rule_id
       or new.config_version_id is distinct from old.config_version_id
       or new.business_id is distinct from old.business_id) then
    raise exception 'program rule identity is immutable'
      using errcode = 'restrict_violation';
  end if;
  return new;
end $$;

--
-- Name: programme_balance_scope_v312(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.programme_balance_scope_v312(p_business uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  select case
    when p_business is null then 'business_pot'
    -- The window. While the pot is being made coherent, nothing may claim it already is.
    when exists (
      select 1 from public.programme_pot_migrations m
       where m.business_id = p_business and m.status in ('pending','running')
    ) then 'business_pot'
    -- The real condition, not a proxy: a firm is programme-pot exactly when every one of
    -- its (client, programme) pots is non-negative and matches its batches. Spanning two
    -- programmes is NOT a defect — it is the point of W5, and it is also the permanent
    -- shape of a firm whose pot has already been migrated (history keeps the old tag,
    -- because points_ledger is append-only). count(distinct programme_id) would call both
    -- of those a split, which is the W4a detector's flaw this wave exists to correct.
    when exists (
      select 1
        from (select pl.client_id, pl.programme_id, sum(pl.points) as points
                from public.points_ledger pl
               where pl.business_id = p_business
               group by 1,2) led
        full join (select pb.client_id, pb.programme_id, sum(pb.remaining) as remaining
                     from public.points_batches pb
                    where pb.business_id = p_business
                    group by 1,2) bat
          on bat.client_id = led.client_id
         and bat.programme_id = led.programme_id
       where coalesce(led.points,0) < 0
          or coalesce(led.points,0) <> coalesce(bat.remaining,0)
    ) then 'business_pot'
    else 'programme_pot'
  end
$$;

--
-- Name: FUNCTION programme_balance_scope_v312(p_business uuid); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.programme_balance_scope_v312(p_business uuid) IS 'v312 W5b: what a per-programme number MEANS for this business right now. ''business_pot'' — the pre-W5 promise: one pot, the per-programme object is identity only. ''programme_pot'' — the programme''s own spendable balance. The answer is ''business_pot'' for any firm with an open pot migration and for any firm whose (client, programme) pots are negative or disagree with their batches — the per-business form of app.detect_programme_pot_split_v312()''s invariant, NOT a distinct-tag proxy: a firm running points AND stamps together spans two programmes by design, and so does every firm whose pot has already been migrated. Read by the five W4a customer readers in place of the literal they shipped, so the flip is a VALUE change on a key the client already reads — no second client wave. Scaling note: it aggregates one business''s points_ledger and points_batches per call, served by points_ledger_business_programme_v312; at a scale where that is a per-request cost the answer becomes a materialised column on businesses maintained by the same two writers.';

--
-- Name: programme_pot_is_split_v310(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.programme_pot_is_split_v310(p_business uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $_$
  -- NULL-blind hardening (W4a verifier risk 2): count(distinct) ignores NULLs, so an
  -- untagged row would read as "not split" while the per-tag INNER JOIN aggregations
  -- silently dropped it. Unreachable barring a v309 tag-trigger bug — treated as split
  -- anyway so liability can never under-report silently.
  select (select count(distinct programme_id) > 1
                 or count(*) filter (where programme_id is null) > 0
            from public.points_ledger
           where business_id = $1)
$_$;

--
-- Name: FUNCTION programme_pot_is_split_v310(p_business uuid); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.programme_pot_is_split_v310(p_business uuid) IS 'v310 W4a: true when this business''s points_ledger rows span more than one programme. Under the W4 currentness policy a split pot means per-programme sums are provenance, not spendable money, so app.v179_business_insights and app.v177_overview suppress their per-tag breakdown to NULL — never a partial array — while this answers true.';

--
-- Name: programme_pot_switch_v312(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.programme_pot_switch_v312() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_from uuid;
  v_to uuid;
begin
  -- The EXACT and ONLY condition under which app.resolve_ledger_programme_v309's answer
  -- moves (v309:258-276). classic <-> points_tiers is not a switch.
  select bp.id into v_from from public.business_programmes bp
   where bp.business_id = new.business_id
     and bp.kind = case when old.loyalty_model = 'stamps' then 'stamps' else 'points' end;
  select bp.id into v_to from public.business_programmes bp
   where bp.business_id = new.business_id
     and bp.kind = case when new.loyalty_model = 'stamps' then 'stamps' else 'points' end;
  if v_from is null or v_to is null or v_from = v_to then
    return null;
  end if;
  perform app.enqueue_programme_pot_migration_v312(new.business_id, v_from, v_to);
  return null;
end
$$;

--
-- Name: FUNCTION programme_pot_switch_v312(); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.programme_pot_switch_v312() IS 'v312 W5b model-switch router, RETIRED AT v314. loyalty_model is a SETTING after the inversion, so firing on it would move a live pot on an ordinary settings republish. public.set_programmes_v314 carries the routing now, keyed on the spine flip that actually changes identity. Kept installed and revoked so the rollback is `create trigger`.';

--
-- Name: programme_running_v371(uuid, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.programme_running_v371(p_business uuid, p_kind text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  -- The spine row is the owner's switch and wins whenever it exists. When one is genuinely missing
  -- we fall back to app.business_programmes_v307, which derives the same answer from the underlying
  -- configuration — a data gap must never silently hide a programme that is actually running.
  select coalesce(
    (select spine.active
       from public.business_programmes spine
      where spine.business_id = p_business
        and spine.kind = p_kind),
    (select model.running
       from app.business_programmes_v307(p_business) model
      where model.kind = p_kind),
    false)
$$;

--
-- Name: FUNCTION programme_running_v371(p_business uuid, p_kind text); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.programme_running_v371(p_business uuid, p_kind text) IS 'V371: single source of truth for "is this programme running" — the business_programmes spine, falling back to the derived state only when a spine row is missing.';

--
-- Name: project_billing_terms_v124(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.project_billing_terms_v124() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_subscription_id text := coalesce(new.provider_subscription_id,old.provider_subscription_id);
  v_business uuid;
  v_cadence text;
  v_base public.billing_provider_subscription_items%rowtype;
  v_capacity public.billing_provider_subscription_items%rowtype;
  v_catalog public.billing_plan_catalog_v124%rowtype;
  v_blocks integer;
begin
  select subscription.business_id,subscription.cadence
    into v_business,v_cadence
    from public.billing_provider_subscriptions subscription
   where subscription.provider_subscription_id=v_subscription_id;
  if v_business is null or v_cadence not in ('monthly','annual') then return null; end if;

  select * into v_base from public.billing_provider_subscription_items item
   where item.provider_subscription_id=v_subscription_id and item.item_role='base'
   order by item.updated_at desc limit 1;
  if not found then return null; end if;
  select * into v_catalog from public.billing_plan_catalog_v124 catalog
   where catalog.provider_base_price_id=v_base.provider_price_id
     and catalog.cadence=v_cadence
   order by catalog.effective_from desc limit 1;
  if not found then return null; end if;
  select * into v_capacity from public.billing_provider_subscription_items item
   where item.provider_subscription_id=v_subscription_id and item.item_role='capacity'
   order by item.updated_at desc limit 1;
  v_blocks := 1 + case when found then greatest(v_capacity.quantity,0) else 0 end;

  insert into public.billing_subscription_terms_v124(
    business_id,provider_subscription_id,cadence,customer_capacity,capacity_blocks,
    provider_base_price_id,provider_capacity_item_id,
    provider_capacity_price_id,provider_event_created_at,last_event_id
  ) values (
    v_business,v_subscription_id,v_cadence,v_blocks*1000,v_blocks,
    v_base.provider_price_id,v_capacity.provider_item_id,
    v_capacity.provider_price_id,
    greatest(v_base.provider_event_created_at,
      coalesce(v_capacity.provider_event_created_at,v_base.provider_event_created_at)),
    coalesce(v_capacity.last_event_id,v_base.last_event_id)
  )
  on conflict(business_id) do update
    set provider_subscription_id=excluded.provider_subscription_id,
        cadence=excluded.cadence,
        customer_capacity=excluded.customer_capacity,
        capacity_blocks=excluded.capacity_blocks,
        provider_base_price_id=excluded.provider_base_price_id,
        provider_capacity_item_id=excluded.provider_capacity_item_id,
        provider_capacity_price_id=excluded.provider_capacity_price_id,
        provider_event_created_at=excluded.provider_event_created_at,
        last_event_id=excluded.last_event_id,updated_at=now()
    where excluded.provider_event_created_at
          >= billing_subscription_terms_v124.provider_event_created_at;
  return null;
end
$$;

--
-- Name: project_invoice_documents_v146(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.project_invoice_documents_v146() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_object jsonb;
begin
  select payload#>'{data,object}' into v_object
    from public.billing_provider_events
   where provider='stripe' and event_id=new.last_event_id;
  if v_object is null then return new; end if;
  new.hosted_invoice_url:=coalesce(
    nullif(v_object->>'hosted_invoice_url',''),new.hosted_invoice_url
  );
  new.invoice_pdf_url:=coalesce(
    nullif(v_object->>'invoice_pdf',''),new.invoice_pdf_url
  );
  new.provider_receipt_url:=coalesce(
    nullif(v_object->>'receipt_url',''),
    nullif(v_object#>>'{charge,receipt_url}',''),
    new.provider_receipt_url
  );
  return new;
end
$$;

--
-- Name: promotion_available_at_branch_v155(uuid, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.promotion_available_at_branch_v155(p_promotion uuid, p_branch uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  select coalesce((
    select case
      when p_branch is null then true
      when content.branch_id is not null then content.branch_id = p_branch
      when exists(
        select 1 from public.promotion_branch_scopes_v155 mapped
        where mapped.promotion_id = content.id
      ) then exists(
        select 1 from public.promotion_branch_scopes_v155 mapped
        where mapped.promotion_id = content.id
          and mapped.branch_id = p_branch
      )
      else true
    end
    from public.business_customer_content_v95 content
    where content.id = p_promotion
      and content.content_type = 'offer'
  ),false)
$$;

--
-- Name: promotion_publication_v122_alert(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.promotion_publication_v122_alert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if new.content_type='offer'
     and new.metadata->>'schema'='nestly.promotion.v104'
     and new.active
     and not old.active
  then
    perform app.enqueue_promotion_alert_v122(new.id,'v122_promotion_new');
  end if;
  return new;
end
$$;

--
-- Name: promotion_version_sync_v280(uuid, uuid, uuid, jsonb); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.promotion_version_sync_v280(p_business uuid, p_promotion uuid, p_attempt_key uuid, p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_version bigint;
  v_payload jsonb := coalesce(p_payload,'{}'::jsonb);
begin
  select content.version into v_version
    from public.business_customer_content_v95 content
   where content.id = p_promotion and content.business_id = p_business;
  if v_version is null then
    return v_payload;
  end if;
  v_payload := v_payload || jsonb_build_object('content_version',v_version);
  if v_payload ? 'item' then
    v_payload := jsonb_set(v_payload,'{item,content_version}',to_jsonb(v_version),true);
  end if;
  -- A replay reads the receipt, not this return value. Leaving the pre-scope version in the
  -- receipt would hand the same stale number straight back to the client that is retrying.
  update public.business_promotion_attempt_receipts_v104 receipt
     set response_payload = case
           when receipt.response_payload ? 'item'
             then jsonb_set(
                    receipt.response_payload||jsonb_build_object('content_version',v_version),
                    '{item,content_version}',to_jsonb(v_version),true)
           else receipt.response_payload||jsonb_build_object('content_version',v_version)
         end
   where receipt.business_id = p_business
     and receipt.attempt_key = p_attempt_key;
  return v_payload;
end
$$;

--
-- Name: prune_billing_provider_items_v124(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.prune_billing_provider_items_v124() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_object jsonb;
  v_subscription_id text;
  v_rank smallint;
begin
  if new.processing_status='processed'
     and old.processing_status is distinct from new.processing_status
     and new.event_type like 'customer.subscription.%' then
    v_object:=new.payload#>'{data,object}';
    v_subscription_id:=v_object->>'id';
    v_rank:=app.stripe_event_rank_v77(new.event_type);
    if v_subscription_id is not null
       and jsonb_typeof(v_object#>'{items,data}')='array'
       and not coalesce((v_object#>>'{items,has_more}')::boolean,false) then
      delete from public.billing_provider_subscription_items item
       where item.provider_subscription_id=v_subscription_id
         and item.provider_item_id not in (
           select value->>'id'
             from jsonb_array_elements(v_object#>'{items,data}')
            where nullif(value->>'id','') is not null
         )
         and (item.provider_event_created_at,item.provider_event_rank)
             <= (new.event_created_at,v_rank);
    end if;
  end if;
  return new;
end
$$;

--
-- Name: ps1a_catalog_ref_valid(uuid, text, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.ps1a_catalog_ref_valid(p_business uuid, p_kind text, p_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if p_id is null or p_kind is null then return false; end if;
  return case p_kind
    when 'service'         then exists(select 1 from public.services         where id = p_id and business_id = p_business)
    when 'product'         then exists(select 1 from public.products         where id = p_id and business_id = p_business)
    when 'branch'          then exists(select 1 from public.branches         where id = p_id and business_id = p_business)
    when 'staff'           then exists(select 1 from public.staff            where id = p_id and business_id = p_business)
    when 'reward'          then exists(select 1 from public.loyalty_rewards  where id = p_id and business_id = p_business)
    when 'tier'            then exists(select 1 from public.loyalty_tiers    where id = p_id and business_id = p_business)
    when 'membership_plan' then exists(select 1 from public.membership_plans where id = p_id and business_id = p_business)
    else false
  end;
end $$;

--
-- Name: ps1a_sha256(text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.ps1a_sha256(p_value text) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog', 'extensions', 'pg_temp'
    AS $$ select encode(extensions.digest(convert_to(p_value, 'UTF8'), 'sha256'), 'hex') $$;

--
-- Name: ps1a_studio_rule_state(uuid, uuid, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.ps1a_studio_rule_state(p_business uuid, p_rule_id uuid, p_config_status text) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v public.program_rules%rowtype; v_err text[];
begin
  select * into v from public.program_rules where id = p_rule_id;
  if not found then return 'validation_failed'; end if;
  -- A published-version rule was validated at publish. PS-1A has NO executor, so
  -- it is 'ready_for_activation' - never 'live'/'active' (owner hard requirement).
  if p_config_status = 'published' then return 'ready_for_activation'; end if;
  v_err := app.program_rule_errors(p_business, jsonb_build_object(
    'schema_version',v.schema_version,'when_event',v.when_event,'if_conditions',v.if_conditions,
    'then_effects',v.then_effects,'with_params',v.with_params,'during_schedule',v.during_schedule,'using_stacking',v.using_stacking));
  if coalesce(array_length(v_err,1),0) > 0 then return 'validation_failed'; end if;
  if jsonb_array_length(coalesce(v.then_effects,'[]'::jsonb)) = 0 then return 'draft'; end if;
  return 'validated';
end $$;

--
-- Name: ps1b_catalog_price(uuid, text, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.ps1b_catalog_price(p_business uuid, p_kind text, p_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_price integer; v_found boolean := false;
begin
  -- A missing catalog reference must NEVER become an economically meaningful 0.
  if p_id is null then
    return jsonb_build_object('status', 'not_applicable', 'price_cents', null,
      'reason', 'no catalog reference');
  end if;
  if p_kind is null or p_kind not in ('service', 'product') then
    return jsonb_build_object('status', 'invalid_kind', 'price_cents', null,
      'reason', 'unsupported catalog kind: ' || coalesce(p_kind, '<null>'));
  end if;
  -- One statement per branch: a planning/column defect in one catalog must not
  -- poison the other (plpgsql plans a whole statement at once). NOTE the column
  -- asymmetry: services carry price_cents, products carry retail_price_cents.
  if p_kind = 'service' then
    select s.price_cents into v_price from public.services s
     where s.id = p_id and s.business_id = p_business;
    v_found := found;
  else
    select pr.retail_price_cents into v_price from public.products pr
     where pr.id = p_id and pr.business_id = p_business;
    v_found := found;
  end if;
  if not v_found then
    return jsonb_build_object('status', 'not_found', 'price_cents', null,
      'reason', 'catalog row not found for this business');
  end if;
  -- A genuine, configured catalog price of 0 is still 'ok' (that IS a price).
  return jsonb_build_object('status', 'ok', 'price_cents', v_price, 'reason', null);
exception when others then
  -- Fail CLOSED with structured evidence, NEVER a silent 0. No secrets / raw SQL
  -- in the detail: only the sqlstate, a truncated message, and the inputs.
  insert into public.audit_log(business_id, actor, action, entity, entity_id, detail)
  values(p_business, null, 'PS1B_PRICING_ERROR', 'ps1b_catalog_price', p_id,
    jsonb_build_object('sqlstate', sqlstate, 'reason', left(sqlerrm, 200),
      'kind', p_kind, 'catalog_id', p_id));
  return jsonb_build_object('status', 'error', 'price_cents', null, 'reason', sqlstate);
end $$;

--
-- Name: ps1b_effect_family(text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.ps1b_effect_family(p_effect_type text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
  select case p_effect_type
    when 'grant_free_item'       then 'recurring'
    when 'display_perk'          then 'recurring'
    when 'tier_multiplier'       then 'tier'
    when 'apply_discount_pct'    then 'checkout'
    when 'apply_discount_amount' then 'checkout'
    when 'grant_credit'          then 'points_loyalty'
    when 'earn_bonus_points'     then 'points_loyalty'
    when 'earn_bonus_stamps'     then 'points_loyalty'
    else 'points_loyalty' end
$$;

--
-- Name: ps1b_eval_conditions(jsonb, jsonb); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.ps1b_eval_conditions(p_payload jsonb, p_conds jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare c jsonb; v_op text; v_val jsonb; v_lhs jsonb;
begin
  if p_conds is null or jsonb_typeof(p_conds) <> 'array' or jsonb_array_length(p_conds) = 0 then return true; end if;
  for c in select * from jsonb_array_elements(p_conds) loop
    v_op := c->>'op'; v_val := c->'value'; v_lhs := p_payload->(c->>'field');
    if v_lhs is null then return false; end if;
    case v_op
      when 'eq'      then if v_lhs is distinct from v_val then return false; end if;
      when 'neq'     then if v_lhs is not distinct from v_val then return false; end if;
      when 'gt'      then if not ((v_lhs#>>'{}')::numeric >  (v_val#>>'{}')::numeric) then return false; end if;
      when 'gte'     then if not ((v_lhs#>>'{}')::numeric >= (v_val#>>'{}')::numeric) then return false; end if;
      when 'lt'      then if not ((v_lhs#>>'{}')::numeric <  (v_val#>>'{}')::numeric) then return false; end if;
      when 'lte'     then if not ((v_lhs#>>'{}')::numeric <= (v_val#>>'{}')::numeric) then return false; end if;
      when 'between' then if not ((v_lhs#>>'{}')::numeric between (v_val->>0)::numeric and (v_val->>1)::numeric) then return false; end if;
      when 'in'      then if not (v_val @> jsonb_build_array(v_lhs)) then return false; end if;
      when 'not_in'  then if (v_val @> jsonb_build_array(v_lhs)) then return false; end if;
      else return false;
    end case;
  end loop;
  return true;
exception when others then return false;
end $$;

--
-- Name: ps1b_execute_event(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.ps1b_execute_event(p_event uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  ev public.domain_events%rowtype; v_active uuid; r record; v_effect jsonb;
  v_idx integer; v_type text; v_family text; v_auth text; v_cut text;
  v_period text; v_pkey text; v_period_start timestamptz; v_period_end timestamptz;
  v_face integer; v_cap integer; v_valid_until timestamptz; v_ent uuid; v_outcome text;
  v_ful uuid; v_key text; v_count integer := 0; v_has_notify boolean := false;
  -- v57: typed catalog pricing (fail-closed) inputs.
  v_price jsonb; v_pstatus text; v_preason text; v_amt integer;
begin
  select * into ev from public.domain_events where event_id = p_event;
  if not found then return 0; end if;
  if exists(select 1 from public.domain_event_execution where event_id = p_event) then return 0; end if;
  select active_config_version_id into v_active from public.businesses where id = ev.business_id;

  for r in select * from public.program_rules_compiled c
            where c.business_id = ev.business_id and c.config_version_id = v_active
              and c.when_event = ev.event_type and c.active
              -- PS-1C.2 teeth: an active emergency pause removes the rule (stops NEW
              -- effects; deletes no historical fulfilment/entitlement/shadow/log row).
              and not exists (select 1 from public.studio_rule_emergency_pauses ep
                               where ep.business_id = ev.business_id and ep.rule_id = c.rule_id
                                 and ep.lifted_at is null) loop
    if not app.ps1b_eval_conditions(ev.payload, r.compiled->'if') then continue; end if;
    v_idx := 0;
    for v_effect in select * from jsonb_array_elements(coalesce(r.compiled->'then', '[]'::jsonb)) loop
      -- v57: process each effect in its own subtransaction. WHEN OTHERS records a
      -- structured 'failed' outcome (fail CLOSED) and continues to the next effect;
      -- the event still receives its execution marker below, so a poisoned rule can
      -- never wedge the sweep.
      begin
        v_type := v_effect->>'effect_type';
        v_family := app.ps1b_effect_family(v_type);
        select execution_authority, cutover_status into v_auth, v_cut
          from public.benefit_registry where business_id = ev.business_id and source_engine = v_family;

        if v_type = 'send_notification' then
          insert into public.event_outbox(business_id, event_id, consumer)
          values(ev.business_id, p_event, 'comms') on conflict (event_id, consumer) do nothing;
          v_has_notify := true;
          insert into public.rule_effect_log(business_id, event_id, rule_id, effect_index, effect_type, outcome, config_version_id)
          values(ev.business_id, p_event, r.rule_id, v_idx, v_type, 'notified', v_active)
          on conflict (event_id, rule_id, effect_index) do nothing;

        elsif v_type = 'display_perk' then
          insert into public.rule_effect_log(business_id, event_id, rule_id, effect_index, effect_type, outcome, config_version_id)
          values(ev.business_id, p_event, r.rule_id, v_idx, v_type, 'display_perk', v_active)
          on conflict (event_id, rule_id, effect_index) do nothing;

        elsif v_type = 'grant_free_item' and v_auth = 'studio_executor' and v_cut = 'studio' then
          -- The ONE value-PROMISING path the PS-1B executor fulfils. The face value
          -- comes from the TYPED catalog price (v57): a missing / renamed / mis-typed
          -- catalog NEVER silently becomes an economically meaningful 0.
          v_price := app.ps1b_catalog_price(ev.business_id, v_effect->>'catalog_kind', nullif(v_effect->>'catalog_id','')::uuid);
          v_pstatus := v_price->>'status';
          v_preason := v_price->>'reason';
          v_amt := nullif(v_effect->>'amount_cents','')::integer;
          v_face := null;
          if v_pstatus = 'ok' then
            v_face := nullif(v_price->>'price_cents','')::integer;
          elsif v_pstatus = 'not_applicable' and v_amt is not null then
            -- Documented fallback: no catalog reference, but the effect carries an
            -- explicit owner-authored face value.
            v_face := v_amt;
          end if;
          if v_face is null then
            -- Fail CLOSED: invalid_kind / not_found / error, or not_applicable with no
            -- amount_cents. No entitlement, no fulfilment, no reservation.
            insert into public.rule_effect_log(business_id, event_id, rule_id, effect_index, effect_type, outcome, failure_reason, config_version_id)
            values(ev.business_id, p_event, r.rule_id, v_idx, v_type, 'failed',
              'price:' || coalesce(v_pstatus, 'null') || ':' || coalesce(v_preason, ''), v_active)
            on conflict (event_id, rule_id, effect_index) do nothing;
          else
            v_period := coalesce(r.compiled->'with'->>'budget_period', r.compiled->'during'->>'period', 'monthly');
            v_pkey := app.ps1b_period_key(ev.occurred_at, v_period);
            v_period_start := (app.ps1b_period_key(ev.occurred_at, v_period) || case v_period when 'daily' then '' when 'annual' then '-01-01' else '-01' end)::timestamptz;
            v_period_end := v_period_start + case v_period when 'daily' then interval '1 day' when 'annual' then interval '1 year' else interval '1 month' end;
            v_cap := nullif(r.compiled->'with'->>'budget_cap_cents','')::integer;
            v_valid_until := ev.occurred_at + (coalesce(nullif(r.compiled->'with'->>'entitlement_expiry_days','')::integer, 30) || ' days')::interval;
            select entitlement_id, outcome into v_ent, v_outcome from app.ps1b_materialise_entitlement(
              ev.business_id, ev.subject_client_id, r.rule_id, v_active, v_pkey, 'free_item',
              jsonb_build_object('rule_id', r.rule_id, 'effect', v_effect, 'source_engine', 'recurring'),
              ev.occurred_at, v_valid_until, v_face, v_cap, v_period_start, v_period_end);
            if v_outcome = 'budget_exhausted' then
              insert into public.rule_effect_log(business_id, event_id, rule_id, effect_index, effect_type, outcome, config_version_id)
              values(ev.business_id, p_event, r.rule_id, v_idx, v_type, 'budget_exhausted', v_active)
              on conflict (event_id, rule_id, effect_index) do nothing;
            else
              v_key := 'recurring:' || r.rule_id::text || ':' || ev.subject_client_id::text || ':' || v_pkey;
              insert into public.benefit_fulfilments(
                business_id, canonical_benefit_key, source_engine, fulfilment_kind, client_id, detail_ref,
                face_value_cents, estimated_cost_cents, cost_basis, cost_confidence, config_version_id, occurred_at)
              values(ev.business_id, v_key, 'recurring', 'recurring_perk', ev.subject_client_id, v_ent,
                v_face, v_face, 'catalog_cost', 'medium', v_active, ev.occurred_at)
              on conflict (business_id, canonical_benefit_key) do nothing
              returning id into v_ful;
              if v_ful is null then select id into v_ful from public.benefit_fulfilments
                 where business_id = ev.business_id and canonical_benefit_key = v_key; end if;
              insert into public.rule_effect_log(business_id, event_id, rule_id, effect_index, effect_type, outcome, benefit_fulfilment_id, config_version_id)
              values(ev.business_id, p_event, r.rule_id, v_idx, v_type, 'fulfilled', v_ful, v_active)
              on conflict (event_id, rule_id, effect_index) do nothing;
            end if;
          end if;

        else
          -- Everything else (value-moving effects, tier, checkout, or a legacy
          -- family) is SHADOW-LOGGED in PS-1B. No value moves.
          insert into public.benefit_shadow_evaluations(
            business_id, event_id, source_engine, rule_id, would_be_canonical_key, client_id,
            fulfilment_kind, face_value_cents, estimated_cost_cents, cost_basis, cost_confidence, config_version_id)
          values(ev.business_id, p_event, v_family, r.rule_id,
            v_family || ':' || r.rule_id::text || ':' || coalesce(ev.subject_client_id::text,'-') || ':' || v_idx::text,
            ev.subject_client_id, v_type,
            coalesce(nullif(v_effect->>'amount_cents','')::integer, 0),
            coalesce(nullif(v_effect->>'amount_cents','')::integer, 0), 'margin_band', 'low', v_active)
          on conflict (business_id, would_be_canonical_key, event_id) do nothing;
          insert into public.rule_effect_log(business_id, event_id, rule_id, effect_index, effect_type, outcome, config_version_id)
          values(ev.business_id, p_event, r.rule_id, v_idx, v_type, 'shadow', v_active)
          on conflict (event_id, rule_id, effect_index) do nothing;
        end if;
      exception when others then
        -- A poisoned effect (e.g. a malformed compiled payload). The subtransaction
        -- rollback undoes any partial write from THIS effect only; record a
        -- structured 'failed' outcome so the failure is evidence, not a silent gap.
        insert into public.rule_effect_log(business_id, event_id, rule_id, effect_index, effect_type, outcome, failure_reason, config_version_id)
        values(ev.business_id, p_event, r.rule_id, v_idx, coalesce(v_type, 'unknown'), 'failed',
          sqlstate || ':' || left(sqlerrm, 180), v_active)
        on conflict (event_id, rule_id, effect_index) do nothing;
      end;
      v_idx := v_idx + 1;
      v_count := v_count + 1;
    end loop;
  end loop;

  insert into public.domain_event_execution(event_id, business_id, effect_count)
  values(p_event, ev.business_id, v_count) on conflict (event_id) do nothing;
  return v_count;
end $$;

--
-- Name: ps1b_materialise_entitlement(uuid, uuid, uuid, uuid, text, text, jsonb, timestamp with time zone, timestamp with time zone, integer, integer, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.ps1b_materialise_entitlement(p_business uuid, p_client uuid, p_rule uuid, p_config uuid, p_period_key text, p_kind text, p_snapshot jsonb, p_valid_from timestamp with time zone, p_valid_until timestamp with time zone, p_face_cents integer, p_cap_cents integer, p_period_start timestamp with time zone, p_period_end timestamp with time zone) RETURNS TABLE(entitlement_id uuid, outcome text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_ent uuid; v_bp public.budget_periods%rowtype; v_res uuid; v_new boolean := false;
begin
  -- Budget check under a single-row lock (deterministic order trivially met).
  if p_cap_cents is not null then
    insert into public.budget_periods(business_id, rule_id, period_start, period_end, cap_cents)
    values(p_business, p_rule, p_period_start, p_period_end, p_cap_cents)
    on conflict (business_id, rule_id, period_start) do nothing;
    select * into v_bp from public.budget_periods
     where business_id = p_business and rule_id = p_rule and period_start = p_period_start for update;
    -- If the entitlement already exists it keeps its reservation (promise preserved);
    -- only a genuinely NEW grant is subject to the cap.
    if not exists(select 1 from public.program_entitlements
        where business_id = p_business and client_id = p_client and rule_id = p_rule and period_key = p_period_key)
       and v_bp.committed_cents + p_face_cents > coalesce(v_bp.cap_cents, 2147483647) then
      return query select null::uuid, 'budget_exhausted'::text; return;
    end if;
  end if;

  insert into public.program_entitlements(
    business_id, client_id, rule_id, config_version_id, period_key, fulfilment_kind, status,
    benefit_snapshot, valid_from, valid_until)
  values(p_business, p_client, p_rule, p_config, p_period_key, p_kind, 'available',
    coalesce(p_snapshot, '{}'::jsonb), p_valid_from, p_valid_until)
  on conflict (business_id, client_id, rule_id, period_key) do nothing
  returning id into v_ent;
  if v_ent is null then
    select id into v_ent from public.program_entitlements
     where business_id = p_business and client_id = p_client and rule_id = p_rule and period_key = p_period_key;
  else
    v_new := true;
  end if;

  if p_cap_cents is not null then
    insert into public.budget_reservations(business_id, budget_period_id, entitlement_id, amount_cents)
    values(p_business, v_bp.id, v_ent, p_face_cents)
    -- by constraint NAME: the (budget_period_id, entitlement_id) column form is
    -- captured by plpgsql substitution of the entitlement_id OUT parameter.
    on conflict on constraint budget_reservations_period_entitlement_uk do nothing
    returning id into v_res;
    if v_res is not null then
      update public.budget_periods set committed_cents = committed_cents + p_face_cents, updated_at = now()
       where id = v_bp.id;
      update public.program_entitlements set budget_reservation_id = v_res, updated_at = now()
       where id = v_ent and budget_reservation_id is null;
    end if;
  end if;
  return query select v_ent, case when v_new then 'materialised' else 'replayed' end;
end $$;

--
-- Name: ps1b_period_key(timestamp with time zone, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.ps1b_period_key(p_occurred timestamp with time zone, p_period text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  select case coalesce(nullif(p_period,''),'monthly')
    when 'daily'  then to_char((p_occurred at time zone 'Asia/Singapore')::date, 'YYYY-MM-DD')
    when 'annual' then to_char(p_occurred at time zone 'Asia/Singapore', 'YYYY')
    else               to_char(p_occurred at time zone 'Asia/Singapore', 'YYYY-MM')
  end
$$;

--
-- Name: ps1b_sha256(text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.ps1b_sha256(p_value text) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog', 'extensions', 'pg_temp'
    AS $$ select encode(extensions.digest(convert_to(p_value, 'UTF8'), 'sha256'), 'hex') $$;

--
-- Name: ps1c2_effect_family(text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.ps1c2_effect_family(p_effect_type text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
  select case p_effect_type
    when 'apply_discount_pct'    then 'checkout'
    when 'apply_discount_amount' then 'checkout'
    when 'grant_free_item'       then 'recurring'
    when 'display_perk'          then 'recurring'
    when 'tier_multiplier'       then 'tier'
    when 'grant_credit'          then 'points_loyalty'
    when 'earn_bonus_points'     then 'points_loyalty'
    when 'earn_bonus_stamps'     then 'points_loyalty'
    when 'send_notification'     then 'comms'
    else 'unknown'
  end
$$;

--
-- Name: ps1c2_effect_state(uuid, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.ps1c2_effect_state(p_business uuid, p_effect_type text) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_family text; v_cut text;
begin
  v_family := app.ps1c2_effect_family(p_effect_type);
  if v_family = 'points_loyalty' then
    return 'shadow';
  elsif v_family in ('comms', 'unknown') then
    return 'unbuilt';
  end if;
  -- checkout / recurring / tier: registry-driven cutover.
  select cutover_status into v_cut from public.benefit_registry
   where business_id = p_business and source_engine = v_family;
  if not found then return 'unbuilt'; end if;   -- fail closed
  return case v_cut
    when 'studio' then 'live'
    when 'shadow' then 'shadow'
    else 'unbuilt'                                -- legacy / unbuilt / rolled_back
  end;
end $$;

--
-- Name: ps1c2_rule_effect_states(uuid, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.ps1c2_rule_effect_states(p_business uuid, p_rule_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v public.program_rules%rowtype; v_out jsonb;
begin
  select * into v from public.program_rules where id = p_rule_id;
  if not found then return '[]'::jsonb; end if;
  select coalesce(jsonb_agg(jsonb_build_object(
      'effect_index', (t.idx - 1),
      'effect_type', t.e->>'effect_type',
      'family', app.ps1c2_effect_family(t.e->>'effect_type'),
      'state', app.ps1c2_effect_state(p_business, t.e->>'effect_type')
    ) order by t.idx), '[]'::jsonb)
    into v_out
    from jsonb_array_elements(coalesce(v.then_effects, '[]'::jsonb)) with ordinality as t(e, idx);
  return v_out;
end $$;

--
-- Name: ps1c2_rule_state(uuid, uuid, text, boolean); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.ps1c2_rule_state(p_business uuid, p_rule_id uuid, p_config_status text, p_active boolean) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v public.program_rules%rowtype; v_err text[];
  e jsonb; v_state text; v_n int := 0; v_live int := 0; v_shadow int := 0;
begin
  select * into v from public.program_rules where id = p_rule_id;
  if not found then return 'validation_failed'; end if;

  if p_config_status = 'draft' then
    -- Authoring context: validate the draft rule.
    v_err := app.program_rule_errors(p_business, jsonb_build_object(
      'schema_version', v.schema_version, 'when_event', v.when_event, 'if_conditions', v.if_conditions,
      'then_effects', v.then_effects, 'with_params', v.with_params,
      'during_schedule', v.during_schedule, 'using_stacking', v.using_stacking));
    if coalesce(array_length(v_err, 1), 0) > 0 then return 'validation_failed'; end if;
    if jsonb_array_length(coalesce(v.then_effects, '[]'::jsonb)) = 0 then return 'draft'; end if;
    return 'validated';
  elsif p_config_status = 'abandoned' then
    return 'draft';        -- a thrown-away draft; never activated
  elsif p_config_status = 'superseded' then
    return 'retired';      -- was published, now replaced by a newer published version
  elsif p_config_status = 'published' then
    -- (a) an ACTIVE emergency pause on the logical rule_id wins over everything.
    if exists (select 1 from public.studio_rule_emergency_pauses ep
                where ep.business_id = p_business and ep.rule_id = v.rule_id and ep.lifted_at is null) then
      return 'paused';
    end if;
    -- (b) a normal (versioned) pause.
    if not coalesce(p_active, v.active) then return 'paused'; end if;
    -- (c) derive over the per-effect states.
    for e in select * from jsonb_array_elements(coalesce(v.then_effects, '[]'::jsonb)) loop
      v_n := v_n + 1;
      v_state := app.ps1c2_effect_state(p_business, e->>'effect_type');
      if v_state = 'live' then v_live := v_live + 1;
      elsif v_state = 'shadow' then v_shadow := v_shadow + 1;
      end if;
    end loop;
    if v_n = 0 then return 'validated'; end if;               -- defensive
    if v_live = v_n then return 'live'; end if;
    if v_live > 0 then return 'partially_live'; end if;
    if v_shadow > 0 then return 'shadow_testing'; end if;
    return 'ready_for_activation';                            -- all unbuilt
  end if;
  return 'validated';                                         -- defensive
end $$;

--
-- Name: ps1c_bundle_lines_v204(uuid, uuid, integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.ps1c_bundle_lines_v204(p_business uuid, p_bundle uuid, p_qty integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_price int; v_name text; v_active boolean;
  v_rows int; v_list bigint := 0; v_alloc bigint := 0; v_share int;
  v_out jsonb := '[]'::jsonb; r record; v_i int := 0; v_total bigint;
begin
  select b.price_cents, b.name, b.active into v_price, v_name, v_active
    from public.bundles b where b.id = p_bundle and b.business_id = p_business;
  if not found then
    return jsonb_build_object('status','unknown_bundle',
      'reason','this bundle does not belong to this business');
  end if;
  if not coalesce(v_active,false) then
    return jsonb_build_object('status','inactive_bundle',
      'reason','this bundle is not available for sale');
  end if;
  if coalesce(v_price,0) < 1 then
    return jsonb_build_object('status','unpriced_bundle',
      'reason','this bundle has no price set');
  end if;

  -- Only services that are themselves still sellable. A bundle must not become a side door
  -- that sells a service the firm has retired.
  select count(*), coalesce(sum(greatest(s.price_cents,0)),0)
    into v_rows, v_list
    from public.bundle_items bi
    join public.services s on s.id = bi.service_id and s.business_id = p_business
   where bi.bundle_id = p_bundle and s.active;
  if coalesce(v_rows,0) < 1 then
    return jsonb_build_object('status','empty_bundle',
      'reason','this bundle has no sellable services in it');
  end if;

  v_total := v_price::bigint * p_qty;

  -- Allocate the BUNDLE price across the services in proportion to their list prices, so a
  -- 100 bundle of a 30 and a 70 service reports 30/70 of the revenue, not 50/50. The last
  -- row takes whatever is left, which is what makes the parts sum to the whole exactly.
  for r in
    select s.id, s.name, greatest(s.price_cents,0) as list
      from public.bundle_items bi
      join public.services s on s.id = bi.service_id and s.business_id = p_business
     where bi.bundle_id = p_bundle and s.active
     order by s.name, s.id
  loop
    v_i := v_i + 1;
    if v_i = v_rows then
      v_share := (v_total - v_alloc)::int;
    elsif v_list > 0 then
      v_share := floor(v_total * r.list / v_list)::int;
    else
      v_share := floor(v_total / v_rows)::int;
    end if;
    v_alloc := v_alloc + v_share;
    v_out := v_out || jsonb_build_object(
      'service_id', r.id,
      'name', r.name || ' · ' || v_name,
      'line_cents', greatest(v_share,0));
  end loop;

  return jsonb_build_object('status','ok','bundle_name',v_name,
    'total_cents', v_total, 'lines', v_out);
end
$$;

--
-- Name: ps1c_cart_hash(jsonb); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.ps1c_cart_hash(p_server_lines jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  select app.ps1b_sha256(coalesce((
    select jsonb_agg(jsonb_build_array(
             ord, e->>'catalog_kind', e->>'catalog_id',
             e->>'qty', e->>'unit_price_cents', e->>'line_total_cents') order by ord)
      from jsonb_array_elements(p_server_lines) with ordinality as t(e, ord)
  ), '[]'::jsonb)::text)
$$;

--
-- Name: ps1c_period_bounds(timestamp with time zone, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.ps1c_period_bounds(p_occurred timestamp with time zone, p_period text, OUT period_start timestamp with time zone, OUT period_end timestamp with time zone) RETURNS record
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_key text := app.ps1b_period_key(p_occurred, coalesce(nullif(p_period, ''), 'monthly'));
begin
  period_start := (v_key || case coalesce(nullif(p_period, ''), 'monthly')
                     when 'daily' then '' when 'annual' then '-01-01' else '-01' end)::timestamptz;
  period_end := period_start + case coalesce(nullif(p_period, ''), 'monthly')
                  when 'daily' then interval '1 day' when 'annual' then interval '1 year' else interval '1 month' end;
end $$;

--
-- Name: ps1c_plan_checkout(uuid, uuid, uuid, jsonb, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.ps1c_plan_checkout(p_business uuid, p_branch uuid, p_client uuid, p_lines jsonb, p_config uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_line jsonb; v_ord int := 0; v_n int;
  v_kind text[]; v_id uuid[]; v_name text[]; v_unit int[]; v_qty int[]; v_ltot int[]; v_rem int[];
  v_entered_by uuid[]; v_lreason text[];
  v_subtotal bigint := 0; v_price jsonb; v_pstatus text; v_nm text;
  v_server jsonb := '[]'::jsonb; v_entry jsonb;
  v_payload jsonb; v_active_rules boolean := (p_config is not null);
  r record; v_eff jsonb; v_idx int; v_etype text; v_ckind text; v_cid uuid; v_level text;
  v_stackable boolean; v_cap int; v_period text;
  v_cand jsonb := '[]'::jsonb;
  v_applied jsonb := '[]'::jsonb;
  v_total_discount bigint := 0; v_any_line boolean := false; v_any_bill boolean := false;
  c jsonb; v_target int; v_base int; v_d int; v_reason text; v_suppressed boolean;
  -- V370: the automatic tier discount.
  v_nonstack_applied boolean := false;
  v_tier_benefit record; v_tier_base int; v_tier_d int;
  v_ps timestamptz; v_pe timestamptz; v_committed int; v_projected int;
  v_rule_proj jsonb := '{}'::jsonb; v_gst_reg boolean; v_gst_bps int; v_total int; v_gst int;
  j int;
  v_desc text; v_camt numeric; v_creason text; v_limit int; v_may_custom boolean;
  v_bundle jsonb; v_bline jsonb; v_bsrc uuid[]; v_bsrcqty int[];
  v_key text;
begin
  if jsonb_typeof(p_lines) <> 'array' then
    return jsonb_build_object('status', 'invalid', 'reason', 'lines must be a JSON array');
  end if;
  v_n := jsonb_array_length(p_lines);
  if v_n < 1 or v_n > 50 then
    return jsonb_build_object('status', 'invalid', 'reason', 'a cart must have between 1 and 50 lines');
  end if;

  select coalesce(custom_line_limit_cents, 50000) into v_limit from public.businesses where id = p_business;
  v_limit := coalesce(v_limit, 50000);
  v_may_custom := app.is_salon_owner(p_business) or app.has_perm(p_business, 'custom_price_lines');

  for v_line in select * from jsonb_array_elements(p_lines) loop
    v_ord := v_ord + 1;
    v_ckind := v_line->>'catalog_kind';
    if v_ckind is null or v_ckind not in ('service', 'product', 'custom', 'bundle') then
      return jsonb_build_object('status', 'bad_kind', 'line', v_ord,
        'reason', 'catalog_kind must be service, product, bundle or custom');
    end if;

    if v_ckind = 'custom' then
      for v_key in select jsonb_object_keys(v_line) loop
        if v_key not in ('catalog_kind', 'description', 'amount_cents', 'reason', 'qty') then
          return jsonb_build_object('status', 'custom_line_invalid', 'line', v_ord,
            'reason', 'custom_line_invalid: a custom line carries only catalog_kind, description, amount_cents and reason');
        end if;
      end loop;
      if not v_may_custom then
        return jsonb_build_object('status', 'custom_line_denied', 'line', v_ord,
          'reason', 'custom_line_denied: you do not have permission to enter a manual price (custom_price_lines)');
      end if;
      if v_line ? 'qty' then
        if jsonb_typeof(v_line->'qty') is distinct from 'number'
           or (v_line->>'qty')::numeric <> 1 then
          return jsonb_build_object('status', 'custom_line_invalid', 'line', v_ord,
            'reason', 'custom_line_invalid: a custom line quantity is always 1');
        end if;
      end if;
      if jsonb_typeof(v_line->'amount_cents') is distinct from 'number' then
        return jsonb_build_object('status', 'custom_line_invalid', 'line', v_ord,
          'reason', 'custom_line_invalid: a custom line requires a numeric amount_cents');
      end if;
      v_camt := (v_line->>'amount_cents')::numeric;
      if v_camt <> trunc(v_camt) or v_camt = 0 then
        return jsonb_build_object('status', 'custom_line_invalid', 'line', v_ord,
          'reason', 'custom_line_invalid: amount_cents must be a whole number of cents and cannot be zero');
      end if;
      if abs(v_camt) > v_limit then
        return jsonb_build_object('status', 'custom_line_limit', 'line', v_ord,
          'reason', 'custom_line_limit: amount_cents exceeds this business''s manual-price limit of '
                    || v_limit || ' cents');
      end if;
      v_desc := btrim(coalesce(v_line->>'description', ''));
      v_creason := btrim(coalesce(v_line->>'reason', ''));
      if length(v_desc) < 3 or length(v_desc) > 200 then
        return jsonb_build_object('status', 'custom_line_invalid', 'line', v_ord,
          'reason', 'custom_line_invalid: a custom line needs a description of 3 to 200 characters');
      end if;
      if length(v_creason) > 200 then
        return jsonb_build_object('status', 'custom_line_invalid', 'line', v_ord,
          'reason', 'custom_line_invalid: a custom line reason cannot exceed 200 characters');
      end if;
      v_kind := array_append(v_kind, 'custom');
      v_id := array_append(v_id, null::uuid);
      v_name := array_append(v_name, v_desc);
      v_unit := array_append(v_unit, v_camt::int);
      v_qty := array_append(v_qty, 1);
      v_ltot := array_append(v_ltot, v_camt::int);
      v_rem := array_append(v_rem, v_camt::int);
      v_entered_by := array_append(v_entered_by, auth.uid());
      v_lreason := array_append(v_lreason, v_creason);
      v_bsrc := array_append(v_bsrc, null::uuid);
      v_bsrcqty := array_append(v_bsrcqty, null::int);
      v_subtotal := v_subtotal + v_camt::int;
      continue;
    end if;

    if v_line ? 'unit_price_cents' or v_line ? 'price_cents' or v_line ? 'amount_cents'
       or v_line ? 'line_total_cents' or v_line ? 'unit_cents' or v_line ? 'discount' then
      return jsonb_build_object('status', 'client_priced', 'line', v_ord,
        'reason', 'checkout lines carry catalog_kind + catalog_id + qty ONLY; nothing is client-priceable');
    end if;
    if jsonb_typeof(v_line->'qty') is distinct from 'number' then
      return jsonb_build_object('status', 'bad_qty', 'line', v_ord, 'reason', 'qty must be a number');
    end if;
    if (v_line->>'qty')::numeric <> trunc((v_line->>'qty')::numeric)
       or (v_line->>'qty')::numeric < 1 or (v_line->>'qty')::numeric > 1000000 then
      return jsonb_build_object('status', 'bad_qty', 'line', v_ord, 'reason', 'qty must be a whole number 1..1000000');
    end if;
    v_cid := nullif(v_line->>'catalog_id', '')::uuid;
    if v_ckind = 'bundle' then
      v_bundle := app.ps1c_bundle_lines_v204(p_business, v_cid, (v_line->>'qty')::int);
      if v_bundle->>'status' <> 'ok' then
        return jsonb_build_object('status', 'price_error', 'line', v_ord,
          'catalog_kind', 'bundle', 'catalog_id', v_cid,
          'reason', (v_bundle->>'status') || ':' || coalesce(v_bundle->>'reason', ''));
      end if;
      for v_bline in select * from jsonb_array_elements(v_bundle->'lines') loop
        v_kind := array_append(v_kind, 'service');
        v_id := array_append(v_id, (v_bline->>'service_id')::uuid);
        v_name := array_append(v_name, v_bline->>'name');
        v_unit := array_append(v_unit, (v_bline->>'line_cents')::int);
        v_qty := array_append(v_qty, 1);
        v_ltot := array_append(v_ltot, (v_bline->>'line_cents')::int);
        v_rem := array_append(v_rem, (v_bline->>'line_cents')::int);
        v_entered_by := array_append(v_entered_by, null::uuid);
        v_lreason := array_append(v_lreason, null::text);
        v_bsrc := array_append(v_bsrc, v_cid);
        v_bsrcqty := array_append(v_bsrcqty, (v_line->>'qty')::int);
        v_subtotal := v_subtotal + (v_bline->>'line_cents')::int;
      end loop;
      continue;
    end if;
    v_price := app.ps1b_catalog_price(p_business, v_ckind, v_cid);
    v_pstatus := v_price->>'status';
    if v_pstatus <> 'ok' then
      return jsonb_build_object('status', 'price_error', 'line', v_ord, 'catalog_kind', v_ckind,
        'catalog_id', v_cid, 'reason', v_pstatus || ':' || coalesce(v_price->>'reason', ''));
    end if;
    if v_ckind = 'service' then
      select name into v_nm from public.services where id = v_cid and business_id = p_business;
    else
      select name into v_nm from public.products where id = v_cid and business_id = p_business;
    end if;
    v_kind := array_append(v_kind, v_ckind);
    v_id := array_append(v_id, v_cid);
    v_name := array_append(v_name, coalesce(v_nm, v_ckind));
    v_unit := array_append(v_unit, (v_price->>'price_cents')::int);
    v_qty := array_append(v_qty, (v_line->>'qty')::int);
    v_ltot := array_append(v_ltot, (v_price->>'price_cents')::int * (v_line->>'qty')::int);
    v_rem := array_append(v_rem, (v_price->>'price_cents')::int * (v_line->>'qty')::int);
    v_entered_by := array_append(v_entered_by, null::uuid);
    v_lreason := array_append(v_lreason, null::text);
    v_bsrc := array_append(v_bsrc, null::uuid);
    v_bsrcqty := array_append(v_bsrcqty, null::int);
    v_subtotal := v_subtotal + ((v_price->>'price_cents')::int * (v_line->>'qty')::int);
  end loop;

  if v_subtotal <= 0 then
    return jsonb_build_object('status', 'invalid', 'reason', 'a checkout must total more than zero');
  end if;
  if v_subtotal > 2147483647 then
    return jsonb_build_object('status', 'invalid', 'reason', 'checkout subtotal exceeds the supported maximum');
  end if;

  for j in 1 .. array_length(v_kind, 1) loop
    v_entry := jsonb_build_object(
      'catalog_kind', v_kind[j], 'catalog_id', v_id[j], 'name', v_name[j],
      'unit_price_cents', v_unit[j], 'qty', v_qty[j], 'line_total_cents', v_ltot[j]);
    if v_kind[j] = 'custom' then
      v_entry := v_entry || jsonb_build_object('entered_by', v_entered_by[j], 'reason', v_lreason[j]);
    end if;
    if v_bsrc[j] is not null then
      v_entry := v_entry || jsonb_build_object('bundle_id', v_bsrc[j], 'bundle_qty', v_bsrcqty[j]);
    end if;
    v_server := v_server || jsonb_build_array(v_entry);
  end loop;

  v_payload := jsonb_build_object('amount_cents', v_subtotal, 'kind', 'cart_sale',
    'branch_id', to_jsonb(p_branch::text), 'client_id', to_jsonb(coalesce(p_client::text, '')),
    'counts_as_visit', true, 'earns_points', true);
  if v_active_rules then
    for r in select c2.rule_id, c2.compiled from public.program_rules_compiled c2
              where c2.business_id = p_business and c2.config_version_id = p_config
                and c2.when_event = 'sale.completed' and c2.active
                and not exists (select 1 from public.studio_rule_emergency_pauses ep
                                 where ep.business_id = p_business and ep.rule_id = c2.rule_id
                                   and ep.lifted_at is null)
              order by c2.rule_id loop
      if not app.ps1b_eval_conditions(v_payload, r.compiled->'if') then continue; end if;
      v_stackable := coalesce((r.compiled->'using'->>'stackable')::boolean, true);
      v_cap := nullif(r.compiled->'with'->>'budget_cap_cents', '')::int;
      v_period := coalesce(r.compiled->'with'->>'budget_period', 'monthly');
      v_idx := 0;
      for v_eff in select * from jsonb_array_elements(coalesce(r.compiled->'then', '[]'::jsonb)) loop
        v_etype := v_eff->>'effect_type';
        if v_etype in ('apply_discount_pct', 'apply_discount_amount') then
          v_ckind := nullif(v_eff->>'catalog_kind', '');
          v_cid := nullif(v_eff->>'catalog_id', '')::uuid;
          v_level := case when v_ckind is not null and v_cid is not null then 'line' else 'bill' end;
          v_cand := v_cand || jsonb_build_array(jsonb_build_object(
            'rule_id', r.rule_id, 'effect_index', v_idx, 'effect_type', v_etype, 'level', v_level,
            'catalog_kind', v_ckind, 'catalog_id', v_cid,
            'discount_pct', v_eff->>'discount_pct', 'amount_cents', v_eff->>'amount_cents',
            'stackable', v_stackable, 'cap_cents', v_cap, 'period', v_period));
        end if;
        v_idx := v_idx + 1;
      end loop;
    end loop;
  end if;

  for c in
    select e from jsonb_array_elements(v_cand) e
     order by (e->>'level') desc,
              (e->>'rule_id'), (e->>'effect_index')::int
  loop
    v_suppressed := false; v_reason := null; v_d := 0; v_target := null;
    v_stackable := (c->>'stackable')::boolean;
    v_cap := nullif(c->>'cap_cents', '')::int;
    v_period := c->>'period';

    if not v_stackable and ((c->>'level' = 'line' and v_any_line) or (c->>'level' = 'bill' and v_any_bill)) then
      v_suppressed := true; v_reason := 'stacking';
    end if;

    if not v_suppressed then
      if c->>'level' = 'line' then
        v_target := null;
        for j in 1 .. array_length(v_kind, 1) loop
          if v_kind[j] = (c->>'catalog_kind') and v_id[j] = nullif(c->>'catalog_id', '')::uuid and v_rem[j] > 0 then
            v_target := j; exit;
          end if;
        end loop;
        if v_target is null then
          v_suppressed := true; v_reason := 'no_target';
        else
          v_base := v_rem[v_target];
        end if;
      else
        v_base := (v_subtotal - v_total_discount)::int;
        if v_base <= 0 then v_suppressed := true; v_reason := 'no_target'; end if;
      end if;
    end if;

    if not v_suppressed then
      if c->>'effect_type' = 'apply_discount_pct' then
        v_d := round(v_base::numeric * (c->>'discount_pct')::numeric / 100.0)::int;
      else
        v_d := least((c->>'amount_cents')::int, v_base);
      end if;
      if v_d > v_base then v_d := v_base; end if;
      if v_d < 0 then v_d := 0; end if;
      if v_d = 0 then v_suppressed := true; v_reason := 'no_target'; end if;
    end if;

    v_ps := null; v_pe := null;
    if v_cap is not null then
      select period_start, period_end into v_ps, v_pe from app.ps1c_period_bounds(now(), v_period);
    end if;
    if not v_suppressed and v_cap is not null then
      select coalesce(committed_cents, 0) into v_committed from public.budget_periods
       where business_id = p_business and rule_id = (c->>'rule_id')::uuid and period_start = v_ps;
      v_committed := coalesce(v_committed, 0);
      v_projected := coalesce((v_rule_proj->>(c->>'rule_id'))::int, 0);
      if v_committed + v_projected + v_d > v_cap then
        v_suppressed := true; v_reason := 'budget_exhausted';
      else
        v_rule_proj := v_rule_proj || jsonb_build_object(c->>'rule_id', v_projected + v_d);
      end if;
    end if;

    if v_suppressed then
      v_applied := v_applied || jsonb_build_array(jsonb_build_object(
        'rule_id', c->>'rule_id', 'effect_index', (c->>'effect_index')::int, 'effect_type', c->>'effect_type',
        'level', c->>'level', 'target_line_index', v_target, 'amount_cents', 0,
        'suppressed', true, 'suppression_reason', v_reason,
        'capped', v_cap is not null, 'cap_cents', v_cap,
        'period_start', v_ps, 'period_end', v_pe));
    else
      if c->>'level' = 'line' then
        v_rem[v_target] := v_rem[v_target] - v_d; v_any_line := true;
      else
        v_any_bill := true;
      end if;
      v_total_discount := v_total_discount + v_d;
      if not v_stackable then v_nonstack_applied := true; end if;
      v_applied := v_applied || jsonb_build_array(jsonb_build_object(
        'rule_id', c->>'rule_id', 'effect_index', (c->>'effect_index')::int, 'effect_type', c->>'effect_type',
        'level', c->>'level', 'target_line_index', v_target, 'amount_cents', v_d,
        'suppressed', false, 'suppression_reason', null,
        'capped', v_cap is not null, 'cap_cents', v_cap,
        'period_start', v_ps, 'period_end', v_pe));
    end if;
  end loop;

  -- ===========================================================================================
  -- V370 — THE AUTOMATIC TIER DISCOUNT (owner: "for tiers it will be automatic if there is a
  -- discount % allocated to it").
  -- It is applied HERE, inside the single pricing authority, rather than by the till: a discount
  -- the browser subtracted for itself would make the sale total and this engine disagree, which
  -- is the two-sources-of-truth failure this codebase keeps paying for.
  -- Four rules, each a decision worth stating:
  --   * ONE discount, never stacked. The best (highest) percentage the customer's rung entitles
  --     them to, inherited down the ladder like every other tier benefit. Stacking Gold's 10%
  --     under Diamond's 30% would compound into a number no owner chose.
  --   * UNLIMITED benefits only. A discount carrying a per-period limit has to be COUNTED when it
  --     is used, and counting belongs to the staff-pressed Give button that already does it
  --     (staff_issue_tier_benefit_v365). Applying a limited one here would spend it silently on
  --     every bill and never record the spend.
  --   * Suppressed when a NON-STACKABLE rule effect has already applied. That rule said it does
  --     not stack; a tier discount landing on top would break the promise the owner authored.
  --   * V394: the tier lifecycle is honoured — a paused or soft-deleted tier neither sets the
  --     customer's rung (app.v365_client_tier filters both since v394) nor donates its benefit
  --     down the ladder (this SELECT filters t.paused/t.deleted_at). Owner ruling 2026-08-20:
  --     paused and deleted tiers grant nothing, matching what customers see (v393 display).
  --   * It carries rule_id null and source 'tier_benefit'. public.checkout_discount_lines is keyed
  --     on a real rule and its rule_id is NOT NULL, so record_cart_sale skips that provenance row
  --     for this effect and records the fulfilment and the signed sale_items line instead.
  -- ===========================================================================================
  if p_client is not null then
    select b.id, b.tier_id, b.label, b.discount_percent
      into v_tier_benefit
      from public.tier_benefits_v365 b
      join public.loyalty_tiers t on t.id = b.tier_id and t.business_id = b.business_id
     where b.business_id = p_business
       and b.deleted_at is null and b.active
       and b.benefit_kind = 'discount_pct'
       and b.limit_count is null
       and coalesce(t.paused, false) = false and t.deleted_at is null
       and t.threshold <= coalesce((app.v365_client_tier(p_business, p_client)).threshold, -1)
       and (t.effective_from is null or t.effective_from <= statement_timestamp())
       and (t.expires_at is null or t.expires_at > statement_timestamp())
     order by b.discount_percent desc, t.threshold desc, b.id
     limit 1;

    if v_tier_benefit.id is not null and not v_nonstack_applied then
      v_tier_base := (v_subtotal - v_total_discount)::int;
      if v_tier_base > 0 then
        v_tier_d := round(v_tier_base::numeric * v_tier_benefit.discount_percent / 100.0)::int;
        if v_tier_d > 0 then
          v_total_discount := v_total_discount + v_tier_d;
          v_applied := v_applied || jsonb_build_array(jsonb_build_object(
            'rule_id', null, 'effect_index', 0, 'effect_type', 'apply_discount_pct',
            'level', 'bill', 'target_line_index', null, 'amount_cents', v_tier_d,
            'suppressed', false, 'suppression_reason', null,
            'capped', false, 'cap_cents', null,
            'period_start', null, 'period_end', null,
            'source', 'tier_benefit', 'tier_benefit_id', v_tier_benefit.id,
            'tier_id', v_tier_benefit.tier_id, 'label', v_tier_benefit.label,
            'discount_pct', v_tier_benefit.discount_percent));
        end if;
      end if;
    end if;
  end if;

  v_total := (v_subtotal - v_total_discount)::int;

  if v_total = 0 then
    return jsonb_build_object('status', 'total_zero_not_supported',
      'reason', 'total_zero_not_supported: this checkout is fully discounted to zero and a zero-value sale is not supported; adjust the cart or the discount');
  end if;

  select gst_registered, gst_rate_bps into v_gst_reg, v_gst_bps from public.businesses where id = p_business;
  if coalesce(v_gst_reg, false) and coalesce(v_gst_bps, 0) > 0 then
    v_gst := round(v_total::numeric * v_gst_bps / (10000 + v_gst_bps))::int;
  else
    v_gst_bps := 0; v_gst := 0;
  end if;

  return jsonb_build_object(
    'status', 'ok',
    'server_lines', v_server,
    'subtotal_cents', v_subtotal::int,
    'applied_effects', v_applied,
    'discount_total_cents', v_total_discount::int,
    'total_cents', v_total,
    'gst_cents', v_gst,
    'gst_rate_bps', coalesce(v_gst_bps, 0),
    'cart_hash', app.ps1c_cart_hash(v_server));
end $$;

--
-- Name: recompute_onboarding_status_v79(uuid, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.recompute_onboarding_status_v79(p_business uuid, p_actor uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_row public.business_onboarding_checklists%rowtype;v_status text;
begin
  select * into v_row from public.business_onboarding_checklists
   where business_id=p_business for update;
  if not found then raise exception 'onboarding checklist was not found' using errcode='22023';end if;
  if v_row.status='activated' then return 'activated';end if;
  if v_row.blocked_at is not null or exists(
    select 1 from public.business_onboarding_items where business_id=p_business and status='blocked'
  ) then v_status:='blocked';
  elsif v_row.started_at is not null and not exists(
    select 1 from public.business_onboarding_items
     where business_id=p_business and mandatory and status not in ('satisfied','waived')
  ) then v_status:='ready';
  elsif v_row.started_at is not null then v_status:='in_progress';
  else v_status:='not_started';end if;
  update public.business_onboarding_checklists set status=v_status,version=version+1,
    updated_at=now() where id=v_row.id;
  return v_status;
end
$$;

--
-- Name: reconcile_subscription_payment_v94(uuid, text, text, uuid, boolean); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.reconcile_subscription_payment_v94(p_business uuid, p_idempotency_key text, p_reason text, p_actor uuid, p_fail_if_unpaid boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_prior public.business_subscription_lifecycle_v94%rowtype;v_result jsonb;
begin
  if length(btrim(coalesce(p_idempotency_key,'')))<8
     or length(btrim(coalesce(p_reason,''))) not between 3 and 1000 then
    raise exception 'valid recovery idempotency and reason are required'
      using errcode='22023';
  end if;
  select * into v_prior from public.business_subscription_lifecycle_v94
  where business_id=p_business for update;
  if not found then raise exception 'business_not_found' using errcode='22023';end if;
  select jsonb_build_object(
    'business_id',p_business,'outcome','replayed','replayed',true,
    'state',audit.new_state,'workspace_paused',audit.new_state='paused',
    'recovered_at',audit.created_at
  ) into v_result
  from public.business_subscription_lifecycle_audit_v94 audit
  where audit.business_id=p_business
    and audit.idempotency_key=btrim(p_idempotency_key);
  if v_result is not null then return v_result;end if;
  if exists(
    select 1 from public.billing_provider_invoices invoice
    where invoice.business_id=p_business and invoice.paid_normalized=false
      and invoice.status in ('open','uncollectible')
      and invoice.amount_remaining_cents>0 and app.billing_due_anchor_v281(invoice) is not null
      and app.billing_due_anchor_v281(invoice)<=now()
  ) then
    if p_fail_if_unpaid then
      raise exception 'provider_invoice_still_unpaid' using errcode='23514';
    end if;
    return jsonb_build_object(
      'business_id',p_business,'outcome','still_overdue','replayed',false,
      'state',v_prior.state,'workspace_paused',v_prior.workspace_paused
    );
  end if;
  if v_prior.state='current' then
    return jsonb_build_object(
      'business_id',p_business,'outcome','already_current','replayed',false,
      'state','current','workspace_paused',false,'recovered_at',v_prior.recovered_at
    );
  end if;
  update public.business_subscription_lifecycle_v94
  set state='current',provider_invoice_id=null,due_date=null,overdue_day=null,
    workspace_paused=false,paused_at=null,recovered_at=now(),
    version=version+1,updated_at=now()
  where business_id=p_business;
  insert into public.business_subscription_lifecycle_audit_v94(
    business_id,event_type,provider_invoice_id,prior_state,new_state,
    actor,reason,idempotency_key
  ) values(
    p_business,'payment_recovered',v_prior.provider_invoice_id,
    v_prior.state,'current',p_actor,btrim(p_reason),btrim(p_idempotency_key)
  );
  return jsonb_build_object(
    'business_id',p_business,'outcome','recovered','replayed',false,
    'state','current','workspace_paused',false,'recovered_at',now()
  );
end
$$;

--
-- Name: reconcile_v145_incomplete_program_rule_pauses(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.reconcile_v145_incomplete_program_rule_pauses() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_inserted integer;
begin
  with inserted as (
    insert into public.studio_rule_emergency_pauses(
      business_id, rule_id, actor, reason
    )
    select rule.business_id,
           rule.rule_id,
           '00000000-0000-0000-0000-000000000000'::uuid,
           'Launch freeze: advanced rule contains an action that is not fully live.'
      from public.businesses business
      join public.program_rules rule
        on rule.business_id = business.id
       and rule.config_version_id = business.active_config_version_id
       and rule.active
     where exists (
       select 1
         from jsonb_array_elements(coalesce(rule.then_effects, '[]'::jsonb)) effect
        where app.ps1c2_effect_state(rule.business_id, effect->>'effect_type') <> 'live'
     )
    on conflict (business_id, rule_id) where lifted_at is null do nothing
    returning id,business_id,rule_id,actor
  ), audited as (
    insert into public.audit_log(business_id,actor,action,entity,entity_id,detail)
    select inserted.business_id,inserted.actor,
           'STUDIO_RULE_EMERGENCY_PAUSE','program_rules',inserted.rule_id,
           jsonb_build_object(
             'rule_id',inserted.rule_id,
             'pause_id',inserted.id,
             'reason','Launch freeze: advanced rule contains an action that is not fully live.',
             'source','v145_launch_reconciliation'
           )
      from inserted
    returning 1
  )
  select count(*)::integer into v_inserted from audited;
  return v_inserted;
end;
$$;

--
-- Name: record_customer_account_open_v175(uuid, uuid, uuid, text, timestamp with time zone); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.record_customer_account_open_v175(p_business uuid, p_auth_user uuid, p_client uuid, p_channel text, p_occurred_at timestamp with time zone DEFAULT now()) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_client uuid:=p_client;
  v_when timestamptz:=coalesce(p_occurred_at,clock_timestamp());
  v_date date;
  v_id uuid;
  v_recorded boolean:=false;
begin
  if p_business is null then
    raise exception 'account-open evidence requires a tenant'
      using errcode='22023';
  end if;
  if p_channel is null or p_channel not in ('wallet','booking','join') then
    raise exception 'unsupported account-open channel: %',p_channel
      using errcode='22023';
  end if;
  -- Clock skew or a stale retry must never fail the customer request; clamp
  -- instead of raising so callers stay fire-and-forget.
  if v_when<clock_timestamp()-interval '24 hours'
     or v_when>clock_timestamp()+interval '5 minutes' then
    v_when:=clock_timestamp();
  end if;
  -- Anchor the subject on the firm-scoped client row whenever the platform
  -- login already has a verified relationship, so one human is not counted as
  -- two subjects across channels.
  if v_client is null and p_auth_user is not null then
    select customer_link.client_id into v_client
    from public.customer_links customer_link
    where customer_link.business_id=p_business
      and customer_link.auth_user_id=p_auth_user
      and customer_link.state='verified'
    limit 1;
  end if;
  if v_client is null and p_auth_user is null then
    return pg_catalog.jsonb_build_object(
      'recorded',false,'reason','no_identity'
    );
  end if;
  v_date:=(v_when at time zone 'Asia/Singapore')::date;

  insert into public.customer_account_open_days_v175(
    business_id,client_id,auth_user_id,channel,open_date,first_opened_at
  ) values(
    p_business,v_client,p_auth_user,p_channel,v_date,v_when
  )
  on conflict (business_id,subject_key,channel,open_date) do nothing
  returning id into v_id;

  if v_id is not null then
    v_recorded:=true;
  else
    select day_row.id into v_id
    from public.customer_account_open_days_v175 day_row
    where day_row.business_id=p_business
      and day_row.channel=p_channel
      and day_row.open_date=v_date
      and day_row.subject_key=coalesce(
        'client:'||v_client::text,'auth:'||p_auth_user::text
      );
  end if;

  return pg_catalog.jsonb_build_object(
    'recorded',v_recorded,'day_id',v_id,'business_id',p_business,
    'channel',p_channel,'open_date',v_date
  );
end
$$;

--
-- Name: redeem_points_v40_internal(uuid, uuid, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.redeem_points_v40_internal(p_business uuid, p_client uuid, p_idempotency_key text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  lp public.loyalty_programs%rowtype;
  bal integer;
  v_batch_balance integer;
  v_remaining integer;
  v_take integer;
  v_batch record;
  v_actor uuid := auth.uid();
  v_staff uuid;
  v_points_id uuid := gen_random_uuid();
  v_credit_id uuid := gen_random_uuid();
  v_operation_id uuid := gen_random_uuid();
  v_payload jsonb;
  v_operation public.loyalty_operations%rowtype;
  v_rows integer;
  v_result json;
  v_points_programme uuid;
begin
  -- v375: points are points, never store credit. This is the only route that ever converted a
  -- points balance into credit_ledger, and it is refused outright rather than left reachable.
  raise exception 'points are redeemed for gifts, not for store credit'
    using errcode = '22023';
  if p_idempotency_key is null or length(btrim(p_idempotency_key)) < 8 then
    raise exception 'idempotency key must contain at least 8 characters' using errcode = '22023';
  end if;
  p_idempotency_key := btrim(p_idempotency_key);
  if not app.has_perm(p_business, 'create_sales') then
    raise exception 'you do not have permission to redeem points in this business (create_sales)'
      using errcode = '42501';
  end if;
  perform 1 from public.businesses where id = p_business for share;

  select s.id into v_staff
    from public.staff s
   where s.business_id = p_business and s.user_id = v_actor and s.active
     and 'create_sales' = any (app.role_perms(s.role))
   order by case s.role when 'owner' then 0 when 'manager' then 1 else 2 end, s.created_at
   limit 1 for update;
  if not found or not app.has_perm(p_business, 'create_sales') then
    raise exception 'active staff authorization changed while redeeming points'
      using errcode = '42501';
  end if;

  perform 1 from public.clients c
   where c.id = p_client and c.business_id = p_business for update;
  if not found then raise exception 'client does not belong to this business'; end if;

  v_payload := jsonb_build_object('business_id', p_business, 'client_id', p_client);
  perform set_config('app.loyalty_operation_insert_id', v_operation_id::text, true);
  insert into public.loyalty_operations
    (id, business_id, client_id, operation_type, actor, idempotency_key,
     request_payload, request_hash)
  values
    (v_operation_id, p_business, p_client, 'redeem_points', v_actor,
     p_idempotency_key, v_payload, md5(v_payload::text))
  on conflict (business_id, operation_type, idempotency_key) do nothing;
  get diagnostics v_rows = row_count;
  perform set_config('app.loyalty_operation_insert_id', '', true);

  if v_rows = 0 then
    select * into v_operation from public.loyalty_operations
     where business_id = p_business and operation_type = 'redeem_points'
       and idempotency_key = p_idempotency_key
     for update;
    if v_operation.actor is distinct from v_actor
       or v_operation.request_payload is distinct from v_payload then
      raise exception 'idempotency key was already used for another redemption request'
        using errcode = '22023';
    end if;
    if v_operation.status = 'completed' then return v_operation.result::json; end if;
    raise exception 'matching redemption is still reserved; retry shortly' using errcode = '40001';
  end if;

  select * into lp from public.loyalty_programs
   where business_id = p_business and active and kind = 'points'
     and redeem_points > 0 and reward_credit_cents > 0 limit 1;
  if not found then
    raise exception 'no active redeemable points program with positive points and credit values';
  end if;
  if lp.loyalty_model is distinct from 'classic' then
    raise exception 'this business redeems points through its reward catalog; use redeem_reward';
  end if;

  select coalesce(sum(pl.points), 0)::integer into bal from public.points_ledger pl
   where pl.business_id = p_business and pl.client_id = p_client;
  if bal < lp.redeem_points then
    raise exception 'insufficient points: % < %', bal, lp.redeem_points;
  end if;
  v_points_programme := app.resolve_ledger_programme_v309(p_business);
  if v_points_programme is null then
    raise exception 'redemption programme is not resolvable for this business'
      using errcode = 'XX001';
  end if;
  select coalesce(sum(pb.remaining), 0)::integer into v_batch_balance
    from public.points_batches pb
   where pb.business_id = p_business and pb.client_id = p_client and pb.remaining > 0
     and pb.programme_id = v_points_programme;
  if v_batch_balance < lp.redeem_points then
    raise exception 'points batches % cannot prove redemption %', v_batch_balance, lp.redeem_points
      using errcode = 'check_violation';
  end if;

  v_remaining := lp.redeem_points;
  for v_batch in
    select pb.id, pb.remaining from public.points_batches pb
     where pb.business_id = p_business and pb.client_id = p_client and pb.remaining > 0
       and pb.programme_id = v_points_programme
     order by pb.expires_at nulls last, pb.earned_at, pb.id for update
  loop
    exit when v_remaining = 0;
    v_take := least(v_batch.remaining, v_remaining);
    update public.points_batches set remaining = remaining - v_take where id = v_batch.id;
    v_remaining := v_remaining - v_take;
  end loop;

  perform set_config('app.points_ledger_insert_id', v_points_id::text, true);
  perform set_config('app.points_ledger_write_scope', 'redeem_points', true);
  insert into public.points_ledger
    (id, business_id, client_id, entry_type, points, reference, actor, programme_id)
  values
    (v_points_id, p_business, p_client, 'redeem', -lp.redeem_points,
     'redeemed to credit', v_actor, v_points_programme);
  perform set_config('app.points_ledger_insert_id', '', true);
  perform set_config('app.points_ledger_write_scope', '', true);

  perform set_config('app.credit_ledger_insert_id', v_credit_id::text, true);
  perform set_config('app.credit_ledger_write_scope', 'redeem_points', true);
  insert into public.credit_ledger
    (id, business_id, client_id, entry_type, amount_cents, reference, actor)
  values
    (v_credit_id, p_business, p_client, 'loyalty_earn', lp.reward_credit_cents,
     'points redemption', v_actor);
  perform set_config('app.credit_ledger_insert_id', '', true);
  perform set_config('app.credit_ledger_write_scope', '', true);

  v_result := json_build_object(
    'points_spent', lp.redeem_points,
    'credit_cents', lp.reward_credit_cents
  );
  perform set_config('app.loyalty_operation_complete_id', v_operation_id::text, true);
  update public.loyalty_operations
     set status = 'completed', result = v_result::jsonb, completed_at = now()
   where id = v_operation_id;
  perform set_config('app.loyalty_operation_complete_id', '', true);
  return v_result;
end $$;

--
-- Name: redeem_reward_core(uuid, uuid, uuid, text, uuid, uuid, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.redeem_reward_core(p_business uuid, p_client uuid, p_reward uuid, p_idempotency_key text, p_branch uuid DEFAULT NULL::uuid, p_service uuid DEFAULT NULL::uuid, p_product uuid DEFAULT NULL::uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  lp public.loyalty_programs%rowtype; v_reward public.loyalty_rewards%rowtype;
  v_version public.loyalty_reward_versions%rowtype; v_balance integer; v_batch_balance integer;
  v_remaining integer; v_take integer; v_batch record; v_actor uuid:=auth.uid(); v_staff uuid;
  v_points_id uuid:=gen_random_uuid(); v_credit_id uuid; v_operation_id uuid:=gen_random_uuid();
  v_redemption_id uuid:=gen_random_uuid(); v_provenance_id uuid:=gen_random_uuid();
  v_payload jsonb; v_operation public.loyalty_operations%rowtype; v_rows integer;
  v_usage integer; v_eligibility jsonb; v_result json; v_reward_programme uuid;
  v_programme_kind text; v_stamp_slots integer; v_stamp_filled integer; v_cycle_index integer;
  v_consumes boolean:=true; v_points_spent integer; v_cycle_id uuid; v_config_version uuid;
begin
  if p_idempotency_key is null or length(btrim(p_idempotency_key))<8 then raise exception 'idempotency key must contain at least 8 characters' using errcode='22023'; end if;
  p_idempotency_key:=btrim(p_idempotency_key);
  if not app.has_perm(p_business,'create_sales') then raise exception 'not authorized' using errcode='42501'; end if;
  perform 1 from public.businesses where id=p_business for share;
  select s.id into v_staff from public.staff s where s.business_id=p_business and s.user_id=v_actor and s.active and 'create_sales'=any(app.role_perms(s.role)) limit 1 for update;
  if not found then raise exception 'active staff authorization required' using errcode='42501'; end if;
  perform 1 from public.clients c where c.id=p_client and c.business_id=p_business for update;
  if not found then raise exception 'client does not belong to this business'; end if;
  if p_branch is not null and not exists(select 1 from public.branches where id=p_branch and business_id=p_business) then raise exception 'branch does not belong to business'; end if;
  if not app.can_see_branch(p_business,p_branch) then
    raise exception 'redemption branch scope is not permitted' using errcode='42501';
  end if;
  if p_service is not null and not exists(select 1 from public.services where id=p_service and business_id=p_business) then raise exception 'service does not belong to business'; end if;
  if p_product is not null and not exists(select 1 from public.products where id=p_product and business_id=p_business) then raise exception 'product does not belong to business'; end if;
  v_payload:=jsonb_build_object('business_id',p_business,'client_id',p_client,'reward_id',p_reward,'branch_id',p_branch,'service_id',p_service,'product_id',p_product);
  perform set_config('app.loyalty_operation_insert_id',v_operation_id::text,true);
  insert into public.loyalty_operations(id,business_id,client_id,reward_id,operation_type,actor,idempotency_key,request_payload,request_hash)
  values(v_operation_id,p_business,p_client,p_reward,'redeem_reward',v_actor,p_idempotency_key,v_payload,md5(v_payload::text))
  on conflict(business_id,operation_type,idempotency_key) do nothing;
  get diagnostics v_rows=row_count; perform set_config('app.loyalty_operation_insert_id','',true);
  if v_rows=0 then
    select * into v_operation from public.loyalty_operations where business_id=p_business and operation_type='redeem_reward' and idempotency_key=p_idempotency_key for update;
    if v_operation.actor is distinct from v_actor or v_operation.request_hash is distinct from md5(v_payload::text) then raise exception 'idempotency conflict' using errcode='23505'; end if;
    if v_operation.status='completed' then return v_operation.result::json; end if;
    raise exception 'redemption already in progress' using errcode='55P03';
  end if;
  select * into lp from public.loyalty_programs where business_id=p_business limit 1;
  if not found then raise exception 'catalog redemption is inactive'; end if;
  select * into v_reward from public.loyalty_rewards where id=p_reward and business_id=p_business;
  if not found then raise exception 'reward not found in this business'; end if;
  -- V326: the live row is mutable and is what pause/delete actually write. The version row below
  -- is an immutable published snapshot that pause/delete cannot touch (trg_loyalty_reward_versions_immutable)
  -- — so this check, not that one, is what makes an immediate pause or delete actually block redemption here.
  if not v_reward.active then raise exception 'reward not found or inactive'; end if;
  if v_reward.paused then raise exception 'reward is currently paused' using errcode='22023'; end if;
  -- nestly_v416: WHICH published configuration this redemption is judged against. For a stamp
  -- card it is the one the customer's OPEN card was started under, so the counter and the card in
  -- their hand cannot disagree; for points there are no cycles and it stays the active version.
  -- The kind is read off the LIVE reward row because v_version is what we are about to select.
  select spine.kind into v_programme_kind from public.business_programmes spine
   where spine.id = v_reward.programme_id and spine.business_id = p_business;
  v_config_version := case when v_programme_kind = 'stamps'
    then app.stamp_cycle_version_v416(p_business, p_client, v_reward.programme_id)
    else (select b.active_config_version_id from public.businesses b where b.id = p_business) end;
  select rv.* into v_version from public.loyalty_reward_versions rv where rv.reward_id=p_reward and rv.business_id=p_business and rv.config_version_id=v_config_version;
  if not found or not v_version.active then raise exception 'reward not found or inactive'; end if;
  if v_version.claim_available_from is not null and v_version.claim_available_from>now() then raise exception 'reward unavailable'; end if;
  if v_version.claim_available_until is not null and v_version.claim_available_until<=now() then raise exception 'reward expired'; end if;
  select jsonb_build_object(
    'branch_ids',coalesce((select jsonb_agg(branch_id order by branch_id) from public.loyalty_reward_branches where reward_version_id=v_version.id),'[]'::jsonb),
    'service_ids',coalesce((select jsonb_agg(service_id order by service_id) from public.loyalty_reward_services where reward_version_id=v_version.id),'[]'::jsonb),
    'product_ids',coalesce((select jsonb_agg(product_id order by product_id) from public.loyalty_reward_products where reward_version_id=v_version.id),'[]'::jsonb),
    'selected',jsonb_build_object('branch_id',p_branch,'service_id',p_service,'product_id',p_product)) into v_eligibility;
  if exists(select 1 from public.loyalty_reward_branches where reward_version_id=v_version.id) and not exists(select 1 from public.loyalty_reward_branches where reward_version_id=v_version.id and branch_id=p_branch) then raise exception 'reward not eligible at branch'; end if;
  if exists(select 1 from public.loyalty_reward_services where reward_version_id=v_version.id) and not exists(select 1 from public.loyalty_reward_services where reward_version_id=v_version.id and service_id=p_service) then raise exception 'reward not eligible for service'; end if;
  if exists(select 1 from public.loyalty_reward_products where reward_version_id=v_version.id) and not exists(select 1 from public.loyalty_reward_products where reward_version_id=v_version.id and product_id=p_product) then raise exception 'reward not eligible for product'; end if;
  select count(*)::integer into v_usage from public.loyalty_redemptions where business_id=p_business and client_id=p_client and reward_id=p_reward;
  if v_version.usage_limit is not null and v_usage>=v_version.usage_limit then
    raise exception 'reward usage limit reached' using errcode='check_violation';
  end if;
  if app.v176_reward_gate_threshold(p_business, v_version.min_tier_id, v_version.min_tier_threshold) is not null and app.v176_tier_gate_metric(p_business, p_client) < app.v176_reward_gate_threshold(p_business, v_version.min_tier_id, v_version.min_tier_threshold) then
    raise exception 'reward requires a higher membership tier' using errcode='check_violation';
  end if;
  select coalesce(sum(points),0)::integer into v_balance from public.points_ledger where business_id=p_business and client_id=p_client;
  v_reward_programme:=v_version.programme_id;
  if v_reward_programme is null then raise exception 'reward programme is not resolvable for this business' using errcode='XX001'; end if;
  if not exists(select 1 from public.business_programmes spine where spine.id=v_reward_programme and spine.business_id=p_business) then raise exception 'reward programme does not belong to this business' using errcode='42501'; end if;
  if not exists(select 1 from public.business_programmes spine where spine.id=v_reward_programme and spine.active) then raise exception 'catalog redemption is inactive'; end if;
  select spine.kind into v_programme_kind from public.business_programmes spine where spine.id=v_reward_programme;
  if v_programme_kind='stamps' then
    v_consumes:=false; v_points_spent:=0;
    select sp.slots,sp.filled,sp.cycle_index into v_stamp_slots,v_stamp_filled,v_cycle_index from app.stamp_progress_v323(p_business,p_client) sp;
    if not found then raise exception 'this business is not running a stamp card' using errcode='XX001'; end if;
    if coalesce(v_stamp_slots,0)<=0 then raise exception 'this stamp card has no length set' using errcode='23514'; end if;
    if v_version.cost_points>v_stamp_slots then raise exception 'this gift sits past the end of the stamp card' using errcode='23514'; end if;
    if v_stamp_filled<v_version.cost_points then raise exception 'not enough stamps yet' using errcode='check_violation'; end if;
  else
    v_points_spent:=v_version.cost_points;
    select coalesce(sum(remaining),0)::integer into v_batch_balance from public.points_batches where business_id=p_business and client_id=p_client and programme_id=v_reward_programme;
    if v_balance<v_version.cost_points or v_batch_balance<v_version.cost_points then raise exception 'insufficient proven points' using errcode='check_violation'; end if;
  end if;
  insert into public.loyalty_redemptions(id,business_id,client_id,reward_id,reward_name,points_spent,credit_cents,actor,reward_version_id,reward_snapshot,eligibility_snapshot,fulfillment_kind,entitlement_expires_at,usage_number,consumes_balance)
  values(v_redemption_id,p_business,p_client,p_reward,v_version.customer_name,v_points_spent,v_version.credit_cents,v_actor,v_version.id,
    to_jsonb(v_version)-'id'-'config_version_id'-'business_id'-'created_at',v_eligibility,v_version.fulfillment_kind,
    case when v_version.entitlement_expiry_days is null then null else now()+make_interval(days=>v_version.entitlement_expiry_days) end,v_usage+1,v_consumes);
  insert into public.loyalty_redemption_provenance
    (id,business_id,client_id,operation_id,redemption_id,points_ledger_id,credit_ledger_id,config_version_id,consumes_balance)
  values(v_provenance_id,p_business,p_client,v_operation_id,v_redemption_id,case when v_consumes then v_points_id end,
    case when v_version.credit_cents>0 then gen_random_uuid() end,v_version.config_version_id,v_consumes)
  returning credit_ledger_id into v_credit_id;
  if v_consumes then
  v_remaining:=v_version.cost_points;
  for v_batch in select id,remaining from public.points_batches where business_id=p_business and client_id=p_client and remaining>0 and programme_id=v_reward_programme order by expires_at nulls last,earned_at,id for update loop
    exit when v_remaining=0; v_take:=least(v_batch.remaining,v_remaining);
    update public.points_batches set remaining=remaining-v_take where id=v_batch.id;
    insert into public.loyalty_redemption_batch_drains
      (provenance_id,business_id,client_id,redemption_id,points_batch_id,drained_points)
    values(v_provenance_id,p_business,p_client,v_redemption_id,v_batch.id,v_take);
    v_remaining:=v_remaining-v_take;
  end loop;
  perform set_config('app.points_ledger_insert_id',v_points_id::text,true); perform set_config('app.points_ledger_write_scope','redeem_points',true);
  insert into public.points_ledger(id,business_id,client_id,entry_type,points,reference,actor,programme_id) values(v_points_id,p_business,p_client,'redeem',-v_version.cost_points,'reward: '||v_version.customer_name,v_actor,v_reward_programme);
  perform set_config('app.points_ledger_insert_id','',true); perform set_config('app.points_ledger_write_scope','',true);
  else
    begin
      insert into public.stamp_milestone_claims(
        business_id,programme_id,client_id,cycle_index,slot_position,reward_id,reward_version_id,
        redemption_id,config_version_id,is_final,actor)
      values(p_business,v_reward_programme,p_client,v_cycle_index,v_version.cost_points,p_reward,
        v_version.id,v_redemption_id,v_version.config_version_id,v_version.cost_points>=v_stamp_slots,v_actor);
      if v_version.cost_points>=v_stamp_slots then
        v_cycle_id:=gen_random_uuid();
        insert into public.stamp_cycles(
          id,business_id,programme_id,client_id,cycle_index,slots,origin,redemption_id,reward_id,
          config_version_id,actor)
        values(v_cycle_id,p_business,v_reward_programme,p_client,v_cycle_index,v_stamp_slots,'claimed',
          v_redemption_id,p_reward,v_version.config_version_id,v_actor);
      end if;
    exception when unique_violation then
      raise exception 'this stamp gift has already been claimed on this card' using errcode='23505';
    end;
  end if;
  if v_credit_id is not null then
    perform set_config('app.credit_ledger_insert_id',v_credit_id::text,true); perform set_config('app.credit_ledger_write_scope','redeem_points',true);
    insert into public.credit_ledger(id,business_id,client_id,entry_type,amount_cents,reference,actor) values(v_credit_id,p_business,p_client,'loyalty_earn',v_version.credit_cents,'loyalty reward: '||v_version.customer_name,v_actor);
    perform set_config('app.credit_ledger_insert_id','',true); perform set_config('app.credit_ledger_write_scope','',true);
  end if;
  v_result:=json_build_object('ok',true,'redemption_id',v_redemption_id,
    'reward_version_id',v_version.id,'reward',v_version.customer_name,
    'points_spent',v_points_spent,'credit_cents',v_version.credit_cents,
    'consumes_balance',v_consumes,
    'stamp_slot',case when v_programme_kind='stamps' then v_version.cost_points end,
    'stamp_cycle_index',v_cycle_index,'stamp_card_closed',v_cycle_id is not null);
  perform set_config('app.loyalty_operation_complete_id',v_operation_id::text,true);
  update public.loyalty_operations set status='completed',result=v_result::jsonb,completed_at=now() where id=v_operation_id;
  perform set_config('app.loyalty_operation_complete_id','',true); return v_result;
end $$;

--
-- Name: FUNCTION redeem_reward_core(p_business uuid, p_client uuid, p_reward uuid, p_idempotency_key text, p_branch uuid, p_service uuid, p_product uuid); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.redeem_reward_core(p_business uuid, p_client uuid, p_reward uuid, p_idempotency_key text, p_branch uuid, p_service uuid, p_product uuid) IS 'v34 catalogue redemption, v176b tier gate, v311 W5a programme-scoped, v313 W6i1 REWARD-scoped. The pot proved and drained is the one named on the reward VERSION (loyalty_reward_versions.programme_id), not the one the business''s loyalty_model implies. That is what makes a stamp gift unpayable out of a customer''s points once a firm runs both programmes at the same time. The business-scoped ledger sum at v34:570 stays as the solvency check it always was; the batch proof and the FEFO drain are the programme-scoped half.';

--
-- Name: referral_payout_programme_v322(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.referral_payout_programme_v322(p_business uuid) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  select accruing.id
    from (select spine.id, spine.kind, count(*) over () as active_accruing
            from public.business_programmes spine
           where spine.business_id = p_business
             and spine.active
             and spine.kind in ('points','stamps')) accruing
   where accruing.active_accruing = 1
$$;

--
-- Name: FUNCTION referral_payout_programme_v322(p_business uuid); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.referral_payout_programme_v322(p_business uuid) IS 'v322 (R1/R4): the business''s ONE active accruing programme, or null. The pot a qualifying referral pays its points into. Null means the referral is left pending and nothing is written.';

--
-- Name: refresh_growth_outcome_residual_v108(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.refresh_growth_outcome_residual_v108() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_now timestamptz := clock_timestamp();
begin
  update public.growth_outcomes_v108
  set revenue_cents = app.v106_sale_residual_minor(new.sale_id, v_now)
  where business_id = new.business_id and sale_id = new.sale_id;
  return new;
end $$;

--
-- Name: refresh_loyalty_config_snapshot(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.refresh_loyalty_config_snapshot(p_version uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_snapshot jsonb;
begin
  select jsonb_build_object(
    'program',(select to_jsonb(lp)-'config_version_id' from public.loyalty_program_versions lp where lp.config_version_id=p_version),
    'tiers',coalesce((select jsonb_agg(to_jsonb(tv)-'id'-'config_version_id'-'business_id'-'created_at' order by tv.threshold,tv.sort,tv.tier_id) from public.loyalty_tier_versions tv where tv.config_version_id=p_version),'[]'::jsonb),
    'rewards',coalesce((select jsonb_agg(jsonb_build_object(
      'reward',to_jsonb(rv)-'id'-'config_version_id'-'business_id'-'created_at',
      'branches',coalesce((select jsonb_agg(e.branch_id order by e.branch_id) from public.loyalty_reward_branches e where e.reward_version_id=rv.id),'[]'::jsonb),
      'services',coalesce((select jsonb_agg(e.service_id order by e.service_id) from public.loyalty_reward_services e where e.reward_version_id=rv.id),'[]'::jsonb),
      'products',coalesce((select jsonb_agg(e.product_id order by e.product_id) from public.loyalty_reward_products e where e.reward_version_id=rv.id),'[]'::jsonb)
    ) order by rv.reward_id) from public.loyalty_reward_versions rv where rv.config_version_id=p_version),'[]'::jsonb),
    'branch_overrides',coalesce((select jsonb_agg(to_jsonb(o)-'config_version_id'-'business_id'-'created_at'-'updated_at' order by o.branch_id) from public.loyalty_branch_overrides o where o.config_version_id=p_version),'[]'::jsonb),
    'retention_programs',coalesce((select jsonb_agg(to_jsonb(r)-'id'-'config_version_id'-'business_id'-'created_at' order by r.sort,r.program_id) from public.retention_program_versions r where r.config_version_id=p_version),'[]'::jsonb),
    'birthday_programs',coalesce((select jsonb_agg(to_jsonb(bp)-'id'-'config_version_id'-'business_id'-'created_at' order by bp.sort,bp.program_id) from public.birthday_program_versions bp where bp.config_version_id=p_version),'[]'::jsonb),
    'program_rules',coalesce((select jsonb_agg(jsonb_build_object(
      'rule_id',pr.rule_id,'schema_version',pr.schema_version,'name',pr.name,'active',pr.active,
      'when',pr.when_event,'sort',pr.sort,'hash',pr.rule_hash
    ) order by pr.sort,pr.rule_id) from public.program_rules pr where pr.config_version_id=p_version),'[]'::jsonb)
  ) into v_snapshot;
  update public.firm_config_versions set snapshot_hash=md5(v_snapshot::text) where id=p_version;
end $$;

--
-- Name: refresh_loyalty_config_snapshot_trigger(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.refresh_loyalty_config_snapshot_trigger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_row jsonb;
  v_reward_version uuid;
  v_config uuid;
begin
  v_row := case when tg_op = 'DELETE' then to_jsonb(old) else to_jsonb(new) end;
  if tg_table_name = 'loyalty_reward_versions' then
    v_config := nullif(v_row ->> 'config_version_id', '')::uuid;
  else
    v_reward_version := nullif(v_row ->> 'reward_version_id', '')::uuid;
    select config_version_id into v_config from public.loyalty_reward_versions where id = v_reward_version;
  end if;
  if v_config is not null then perform app.refresh_loyalty_config_snapshot(v_config); end if;
  if tg_op = 'DELETE' then return old; end if;
  return new;
end $$;

--
-- Name: refresh_loyalty_tier_snapshot_trigger(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.refresh_loyalty_tier_snapshot_trigger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  perform app.refresh_loyalty_config_snapshot(
    case when tg_op='DELETE' then old.config_version_id else new.config_version_id end
  );
  if tg_op='DELETE' then return old; end if;
  return new;
end $$;

--
-- Name: refresh_onboarding_core_v79(uuid, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.refresh_onboarding_core_v79(p_business uuid, p_actor uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_item record;v_ok boolean;v_evidence jsonb;v_status text;
begin
  for v_item in select item_key from public.business_onboarding_items
    where business_id=p_business and verification_mode='derived' and status not in ('blocked','waived')
  loop
    case v_item.item_key
      when 'legal_identity' then
        select app.normalized_business_identity_v79(legal_name) is not null
          and app.normalized_business_identity_v79(registration_number) is not null,
          jsonb_build_object('legal_name',legal_name,'registration_number',registration_number)
          into v_ok,v_evidence from public.businesses where id=p_business;
      when 'owner_access' then
        select exists(select 1 from public.workspace_owner_invitations invitation
          join public.staff staff on staff.business_id=invitation.business_id
            and staff.user_id=invitation.accepted_by and staff.role='owner' and staff.active
          where invitation.business_id=p_business and invitation.status='accepted'),
          jsonb_build_object('accepted_owner_count',(select count(*) from public.staff
            where business_id=p_business and role='owner' and active and user_id is not null))
          into v_ok,v_evidence;
      when 'billing_terms' then
        select subscription.commercial_terms_id=terms.id
          and subscription.plan_code=terms.plan_code
          and subscription.product_code=terms.product_code
          and subscription.billing_cadence=terms.billing_cycle
          and subscription.seat_limit=terms.seats
          and terms.contract_status in ('accepted','signed'),
          jsonb_build_object('commercial_terms_id',subscription.commercial_terms_id,
            'plan_code',subscription.plan_code,'product_code',subscription.product_code,
            'billing_cadence',subscription.billing_cadence,'seat_limit',subscription.seat_limit)
          into v_ok,v_evidence
          from public.subscriptions subscription
          join public.sme_commercial_terms terms on terms.id=subscription.commercial_terms_id
          where subscription.business_id=p_business;
      when 'core_workspace' then
        select exists(select 1 from public.business_sector_assignments where business_id=p_business)
          and exists(select 1 from public.branches where business_id=p_business and is_default and not active)
          and exists(select 1 from public.loyalty_programs where business_id=p_business
            and configuration_status='draft' and not active),
          jsonb_build_object('sector_assigned',exists(select 1 from public.business_sector_assignments where business_id=p_business),
            'inactive_default_branch',exists(select 1 from public.branches where business_id=p_business and is_default and not active),
            'draft_loyalty',exists(select 1 from public.loyalty_programs where business_id=p_business
              and configuration_status='draft' and not active))
          into v_ok,v_evidence;
      when 'users_ready' then
        select exists(select 1 from public.staff where business_id=p_business and role='owner' and active and user_id is not null)
          and app.billable_seats(p_business)<=coalesce((select seat_limit from public.subscriptions where business_id=p_business),0),
          jsonb_build_object('billable_seats',app.billable_seats(p_business),
            'seat_limit',(select seat_limit from public.subscriptions where business_id=p_business))
          into v_ok,v_evidence;
      when 'first_value_configured' then
        select exists(select 1 from public.loyalty_programs where business_id=p_business and active and configuration_status='published')
          or exists(select 1 from public.services where business_id=p_business and active)
          or exists(select 1 from public.products where business_id=p_business and active),
          jsonb_build_object(
            'published_loyalty',exists(select 1 from public.loyalty_programs where business_id=p_business and active and configuration_status='published'),
            'active_services',(select count(*) from public.services where business_id=p_business and active),
            'active_products',(select count(*) from public.products where business_id=p_business and active))
          into v_ok,v_evidence;
      else v_ok:=false;v_evidence:='{}';end case;
    update public.business_onboarding_items set status=case when v_ok then 'satisfied' else 'pending' end,
      evidence=v_evidence,satisfied_by=case when v_ok then p_actor end,
      satisfied_at=case when v_ok then coalesce(satisfied_at,now()) end,updated_at=now()
     where business_id=p_business and item_key=v_item.item_key;
  end loop;
  v_status:=app.recompute_onboarding_status_v79(p_business,p_actor);
  return jsonb_build_object('business_id',p_business,'status',v_status);
end
$$;

