--
-- Name: reporting_scope_label_v155(uuid, text, uuid[], uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.reporting_scope_label_v155(p_business uuid, p_scope_mode text, p_branch_ids uuid[] DEFAULT ARRAY[]::uuid[], p_operational_branch uuid DEFAULT NULL::uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  with resolved as (
    select * from app.resolve_reporting_branch_scope_v155(
      p_business,p_scope_mode,p_branch_ids,p_operational_branch
    )
  )
  select case
    when coalesce(nullif(btrim(p_scope_mode),''),'current') = 'all'
      then case when count(*) = 1 then max(branch_name)
        else 'All accessible branches' end
    when count(*) = 1 then max(branch_name)
    else string_agg(branch_name,' + ' order by branch_name)
  end
  from resolved
$$;

--
-- Name: reports_gift_card_liability_v49b(uuid, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.reports_gift_card_liability_v49b(p_business uuid, p_branch uuid DEFAULT NULL::uuid) RETURNS bigint
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_liability bigint;
begin
  if auth.uid() is null
     or not app.has_perm(p_business, 'view_sales')
     or not app.metric_module_scope_available_v145(p_business, p_branch, 'reports')
     or not app.metric_module_scope_available_v145(p_business, null, 'giftcards') then
    raise exception 'active Reports read authorization is required'
      using errcode = '42501';
  end if;

  -- Gift cards have no branch attribution. The scalar is intentionally business-wide
  -- after complete branch-effective Reports authorization has been proven above.
  select coalesce(sum(card.balance_cents) filter (where card.status = 'active'), 0)::bigint
    into v_liability
    from public.gift_cards card
   where card.business_id = p_business;
  return coalesce(v_liability, 0);
end
$$;

--
-- Name: request_bound_booking_v72(uuid, uuid, uuid, text, text, text, uuid, integer, timestamp with time zone, text, uuid, boolean); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.request_bound_booking_v72(p_business uuid, p_client uuid, p_authenticated_user uuid, p_name text, p_email text, p_phone text, p_service uuid, p_party integer, p_preferred timestamp with time zone, p_notes text, p_table_type uuid, p_consent boolean) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_business public.businesses%rowtype;
  v_available integer;
  v_request uuid;
  v_appointment public.appointments%rowtype;
  v_table_type uuid;
  v_duration integer;
begin
  select business.* into v_business
    from public.businesses business
   where business.id = p_business;
  if not found or not exists (
    select 1 from public.clients client
     where client.business_id = p_business and client.id = p_client
  ) then
    raise exception 'invalid request' using errcode = '22023';
  end if;

  perform app.apply_bound_booking_consent_v72(
    p_business, p_client, p_authenticated_user, p_consent
  );

  if p_table_type is null then
    insert into public.booking_requests (
      business_id, customer_client_id, name, email, phone, service_id,
      party_size, preferred_at, notes, status, marketing_consent
    ) values (
      p_business, p_client, btrim(p_name), p_email, p_phone, p_service,
      p_party, p_preferred, p_notes, 'new', coalesce(p_consent, false)
    ) returning id into v_request;
    return json_build_object('status', 'pending', 'request_id', v_request);
  end if;

  select table_type.id into v_table_type
    from public.booking_tables table_type
   where table_type.id = p_table_type
     and table_type.business_id = p_business
     and table_type.active
   for update;
  if v_table_type is null then
    raise exception 'invalid table type' using errcode = '22023';
  end if;

  select availability.available into v_available
    from public.v_table_availability availability
   where availability.table_type_id = p_table_type;
  v_available := coalesce(v_available, 0);

  if v_available > 0 then
    if v_business.booking_auto_confirm then
      v_duration := coalesce((
        select service.duration_min
          from public.services service
         where service.id = p_service and service.business_id = p_business
      ), 60);
      insert into public.appointments (
        business_id, client_id, service_id, starts_at, ends_at,
        status, party_size, source, note, table_type_id
      ) values (
        p_business, p_client, p_service,
        coalesce(p_preferred, clock_timestamp() + interval '1 day'),
        coalesce(p_preferred, clock_timestamp() + interval '1 day')
          + make_interval(mins => greatest(v_duration, 1)),
        'booked', p_party, 'portal', p_notes, p_table_type
      ) returning * into v_appointment;

      insert into public.booking_requests (
        business_id, customer_client_id, name, email, phone, service_id,
        party_size, preferred_at, notes, status, table_type_id,
        appointment_id, marketing_consent
      ) values (
        p_business, p_client, btrim(p_name), p_email, p_phone, p_service,
        p_party, p_preferred, p_notes, 'confirmed', p_table_type,
        v_appointment.id, coalesce(p_consent, false)
      ) returning id into v_request;
      return json_build_object(
        'status', 'confirmed',
        'request_id', v_request,
        'appointment_id', v_appointment.id
      );
    end if;

    insert into public.booking_requests (
      business_id, customer_client_id, name, email, phone, service_id,
      party_size, preferred_at, notes, status, table_type_id,
      expires_at, marketing_consent
    ) values (
      p_business, p_client, btrim(p_name), p_email, p_phone, p_service,
      p_party, p_preferred, p_notes, 'pending', p_table_type,
      case when v_business.booking_hold_minutes > 0
        then clock_timestamp() + make_interval(mins => v_business.booking_hold_minutes)
        else null end,
      coalesce(p_consent, false)
    ) returning id into v_request;
    return json_build_object('status', 'pending', 'request_id', v_request);
  end if;

  if v_business.booking_overflow = 'reject' then
    insert into public.booking_requests (
      business_id, customer_client_id, name, email, phone, service_id,
      party_size, preferred_at, notes, status, table_type_id, marketing_consent
    ) values (
      p_business, p_client, btrim(p_name), p_email, p_phone, p_service,
      p_party, p_preferred,
      btrim(coalesce(p_notes, '') || ' [auto-declined: no capacity]'),
      'declined', p_table_type, coalesce(p_consent, false)
    ) returning id into v_request;
    return json_build_object('status', 'rejected', 'request_id', v_request);
  end if;

  insert into public.booking_requests (
    business_id, customer_client_id, name, email, phone, service_id,
    party_size, preferred_at, notes, status, table_type_id, marketing_consent
  ) values (
    p_business, p_client, btrim(p_name), p_email, p_phone, p_service,
    p_party, p_preferred, p_notes, 'waitlisted', p_table_type,
    coalesce(p_consent, false)
  ) returning id into v_request;

  insert into public.waitlist (
    business_id, client_id, name, phone, service_id, preferred, notes,
    status, booking_request_id, table_type_id
  ) values (
    p_business, p_client, btrim(p_name), p_phone, p_service,
    to_char(coalesce(p_preferred, clock_timestamp()) at time zone 'Asia/Singapore',
      'YYYY-MM-DD HH24:MI'),
    p_notes, 'waiting', v_request, p_table_type
  );
  return json_build_object('status', 'waitlisted', 'request_id', v_request);
end
$$;

--
-- Name: require_bar_business_v275(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.require_bar_business_v275(p_business uuid) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_industry text;
begin
  if p_business is null then
    raise exception 'business required' using errcode = '22023';
  end if;
  select lower(btrim(coalesce(business.industry, ''))) into v_industry
    from public.businesses business
   where business.id = p_business;
  if coalesce(v_industry, '') <> 'bar' then
    raise exception 'Bottle keep is only available for bar businesses.' using errcode = '42501';
  end if;
end;
$$;

--
-- Name: require_bar_staff_v275(uuid, boolean); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.require_bar_staff_v275(p_business uuid, p_write boolean) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if auth.uid() is null then
    raise exception 'authenticated staff required' using errcode = '28000';
  end if;
  if app.is_salon_owner(p_business) then
    return;
  end if;
  if p_write then
    if app.can_module_write(p_business, 'bottles') then
      return;
    end if;
  elsif app.can_module_read(p_business, 'bottles') then
    return;
  end if;
  raise exception 'bottle keep authorization required' using errcode = '42501';
end;
$$;

--
-- Name: require_branch_module_v94(uuid, uuid, text, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.require_branch_module_v94(p_business uuid, p_branch uuid, p_module text, p_mode text) RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_branch uuid:=p_branch;
begin
  if v_branch is null then
    select branch.id into v_branch
    from public.branches branch
    where branch.business_id=p_business and branch.active
    order by branch.is_default desc,branch.created_at,branch.id
    limit 1;
  end if;
  if v_branch is null or not exists(
    select 1 from public.branches branch
    where branch.id=v_branch and branch.business_id=p_business and branch.active
  ) then
    raise exception 'active_branch_required' using errcode='22023';
  end if;
  if not app.is_super_admin() and (
    (p_mode='r' and not app.can_module_read_at_v94(
      p_business,v_branch,p_module
    ))
    or
    (p_mode='rw' and not app.can_module_write_at_v94(
      p_business,v_branch,p_module
    ))
  ) then
    raise exception 'branch_module_access_required:%:%',p_module,p_mode
      using errcode='42501';
  end if;
  return v_branch;
end
$$;

--
-- Name: require_idempotency_key_v79(text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.require_idempotency_key_v79(p_key text) RETURNS void
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
begin
  if length(btrim(coalesce(p_key,''))) not between 8 and 200 then
    raise exception 'idempotency key must contain 8 to 200 characters' using errcode='22023';
  end if;
end
$$;

--
-- Name: require_metric_module_scope_v145(uuid, uuid, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.require_metric_module_scope_v145(p_business uuid, p_branch uuid, p_module text) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if not app.metric_module_scope_available_v145(p_business, p_branch, p_module) then
    raise exception 'complete_metric_scope_required:%', p_module
      using errcode = '42501';
  end if;
end;
$$;

--
-- Name: require_workspace_open_v173(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.require_workspace_open_v173(p_business uuid) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if not app.business_workspace_open_v94(p_business) then
    raise exception 'workspace_paused' using errcode='42501',
      hint='The workspace is paused until billing is settled.';
  end if;
end
$$;

--
-- Name: resolve_ledger_programme_v309(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.resolve_ledger_programme_v309(p_business uuid) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  select spine.id
    from public.business_programmes spine
   where spine.business_id = p_business
     and spine.kind = case
           when exists (
             select 1
               from public.loyalty_programs program
              where program.business_id = p_business
                and program.loyalty_model = 'stamps'
           ) then 'stamps'
           else 'points'
         end
$$;

--
-- Name: FUNCTION resolve_ledger_programme_v309(p_business uuid); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.resolve_ledger_programme_v309(p_business uuid) IS 'v309 W3 single-pot resolver — THE PRE-INVERSION ORACLE, no longer consulted by any money path as of v313. It answers from loyalty_programs.loyalty_model, which v314 demotes from switch to setting; from that moment its answer is a historical fact about a firm''s settings row and not a statement about which programmes are running. Kept installed and revoked because the v313 backfill''s provenance is "this function, on this date", and because re-attaching the v309 tag triggers is part of the documented rollback.';

--
-- Name: resolve_loyalty_branch_config(uuid, uuid, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.resolve_loyalty_branch_config(p_business_id uuid, p_branch_id uuid, p_config_version_id uuid DEFAULT NULL::uuid) RETURNS TABLE(business_id uuid, config_version_id uuid, branch_id uuid, source text, kind text, loyalty_model text, active boolean, earn_points_per_dollar numeric, redeem_points integer, reward_credit_cents integer, stamp_target integer, stamp_per_cents integer, tier_basis text, expiry_mode text, expiry_days integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_config_version_id uuid;
begin
  if p_branch_id is not null
     and not exists (
       select 1 from public.branches b
        where b.id = p_branch_id and b.business_id = p_business_id
     ) then
    raise exception 'branch does not belong to business' using errcode = 'foreign_key_violation';
  end if;

  v_config_version_id := coalesce(
    p_config_version_id,
    app.active_config_version(p_business_id)
  );

  -- A newly onboarded firm may still have only its inactive draft. In that
  -- case there is no earn configuration and recording a sale remains valid.
  if v_config_version_id is null then
    return;
  end if;

  if not exists (
    select 1 from public.firm_config_versions v
     where v.id = v_config_version_id and v.business_id = p_business_id
  ) then
    raise exception 'configuration version does not belong to business'
      using errcode = 'foreign_key_violation';
  end if;

  return query
  select d.business_id,
         d.config_version_id,
         p_branch_id,
         case when o.branch_id is null then 'firm_default' else 'branch_override' end,
         d.kind,
         d.loyalty_model,
         coalesce(o.active, d.active),
         coalesce(o.earn_points_per_dollar, d.earn_points_per_dollar),
         d.redeem_points,
         d.reward_credit_cents,
         d.stamp_target,
         coalesce(o.stamp_per_cents, d.stamp_per_cents),
         d.tier_basis,
         coalesce(o.expiry_mode, d.expiry_mode),
         coalesce(o.expiry_days, d.expiry_days)
    from public.loyalty_program_versions d
    left join public.loyalty_branch_overrides o
      on o.config_version_id = d.config_version_id
     and o.business_id = d.business_id
     and o.branch_id is not distinct from p_branch_id
   where d.business_id = p_business_id
     and d.config_version_id = v_config_version_id;
end
$$;

--
-- Name: resolve_module_dependencies(text[]); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.resolve_module_dependencies(p_modules text[]) RETURNS text[]
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_unknown text[];
  v_resolved text[];
begin
  select array_agg(distinct requested order by requested)
    into v_unknown
    from unnest(coalesce(p_modules, '{}'::text[])) requested
    left join public.module_registry mr on mr.module_key = requested
   where mr.module_key is null;
  if coalesce(cardinality(v_unknown), 0) > 0 then
    raise exception 'unknown modules: %', array_to_string(v_unknown, ', ')
      using errcode = '22023';
  end if;

  with recursive closure(module_key) as (
    select unnest(array_append(coalesce(p_modules, '{}'::text[]), 'dashboard'))
    union
    select dependency
      from closure c
      join public.module_registry mr on mr.module_key = c.module_key
      cross join lateral unnest(mr.requires_modules) dependency
  )
  select array_agg(c.module_key order by mr.sort_order, c.module_key)
    into v_resolved
    from closure c
    join public.module_registry mr using (module_key);

  return coalesce(v_resolved, array['dashboard']::text[]);
end $$;

--
-- Name: resolve_reporting_branch_scope_v155(uuid, text, uuid[], uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.resolve_reporting_branch_scope_v155(p_business uuid, p_scope_mode text, p_branch_ids uuid[] DEFAULT ARRAY[]::uuid[], p_operational_branch uuid DEFAULT NULL::uuid) RETURNS TABLE(branch_id uuid, branch_name text, active boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_mode text := coalesce(nullif(btrim(p_scope_mode),''),'current');
  v_count integer;
begin
  if auth.uid() is null then
    raise exception 'authenticated_session_required' using errcode='28000';
  end if;
  if p_business is null or not exists(
    select 1 from public.businesses business where business.id = p_business
  ) then
    raise exception 'business_not_found' using errcode='22023';
  end if;
  if v_mode not in ('current','selected','all') then
    raise exception 'unsupported_reporting_branch_scope' using errcode='22023';
  end if;

  if v_mode = 'current' then
    if p_operational_branch is null then
      raise exception 'operational_branch_required_for_current_scope'
        using errcode='22023';
    end if;
    if not exists(
      select 1
      from public.branches branch
      where branch.id = p_operational_branch
        and branch.business_id = p_business
        and coalesce(branch.active,true)
    ) then
      raise exception 'foreign_or_inactive_branch_scope' using errcode='42501';
    end if;
    if not app.can_see_branch(p_business,p_operational_branch) then
      raise exception 'unauthorised_branch_scope' using errcode='42501';
    end if;
    return query
      select branch.id, branch.name, branch.active
      from public.branches branch
      where branch.id = p_operational_branch
        and branch.business_id = p_business
        and coalesce(branch.active,true);
    return;
  end if;

  if v_mode = 'selected' then
    with requested as (
      select distinct unnest(coalesce(p_branch_ids,array[]::uuid[])) as requested_branch_id
    )
    select count(*) into v_count from requested;
    if v_count = 0 then
      raise exception 'empty_selected_branch_scope' using errcode='22023';
    end if;
    if exists(
      with requested as (
        select distinct unnest(coalesce(p_branch_ids,array[]::uuid[])) as requested_branch_id
      )
      select 1
      from requested
      left join public.branches branch
        on branch.id = requested.requested_branch_id
       and branch.business_id = p_business
       and coalesce(branch.active,true)
      where branch.id is null
    ) then
      raise exception 'foreign_or_inactive_branch_scope' using errcode='42501';
    end if;
    if exists(
      with requested as (
        select distinct unnest(coalesce(p_branch_ids,array[]::uuid[])) as requested_branch_id
      )
      select 1
      from requested
      join public.branches branch
        on branch.id = requested.requested_branch_id
       and branch.business_id = p_business
      where not app.can_see_branch(p_business,branch.id)
    ) then
      raise exception 'unauthorised_branch_scope' using errcode='42501';
    end if;
    return query
      with requested as (
        select distinct unnest(coalesce(p_branch_ids,array[]::uuid[])) as requested_branch_id
      )
      select branch.id, branch.name, branch.active
      from requested
      join public.branches branch
        on branch.id = requested.requested_branch_id
       and branch.business_id = p_business
       and coalesce(branch.active,true)
      order by branch.name, branch.id;
    return;
  end if;

  return query
    select branch.id, branch.name, branch.active
    from public.branches branch
    where branch.business_id = p_business
      and coalesce(branch.active,true)
      and app.can_see_branch(p_business,branch.id)
    order by branch.name, branch.id;
end
$$;

--
-- Name: FUNCTION resolve_reporting_branch_scope_v155(p_business uuid, p_scope_mode text, p_branch_ids uuid[], p_operational_branch uuid); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.resolve_reporting_branch_scope_v155(p_business uuid, p_scope_mode text, p_branch_ids uuid[], p_operational_branch uuid) IS 'V155 canonical reporting branch-scope resolver. Current resolves exactly one operational branch; selected resolves a deduplicated non-empty authorised branch set; all resolves only active branches the current membership may see.';

--
-- Name: resolve_retention_reward_taxonomy(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.resolve_retention_reward_taxonomy() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_tax public.firm_reward_taxonomy%rowtype;
begin
  select * into v_tax
    from public.firm_reward_taxonomy
   where id = new.reward_taxonomy_id
     and business_id = new.business_id;
  if not found then
    raise exception 'reward type does not belong to this business'
      using errcode = 'foreign_key_violation';
  end if;
  if (tg_op = 'INSERT' or new.reward_taxonomy_id is distinct from old.reward_taxonomy_id)
     and not v_tax.active then
    raise exception 'retired reward types cannot be selected';
  end if;
  new.reward_type := v_tax.fulfillment_kind;
  if new.reward_type = 'discount_pct'
     and (new.reward_value <= 0 or new.reward_value > 100) then
    raise exception 'discount percentage must be greater than 0 and at most 100'
      using errcode = 'check_violation';
  elsif new.reward_type = 'credit'
     and (new.reward_value <= 0 or new.reward_value <> trunc(new.reward_value)) then
    raise exception 'store credit must be a positive whole number of cents'
      using errcode = 'check_violation';
  elsif new.reward_type = 'free_item'
     and char_length(btrim(coalesce(new.reward_item,''))) < 2 then
    raise exception 'free item or service description is required'
      using errcode = 'check_violation';
  end if;
  return new;
end $$;

--
-- Name: resolve_sector_entitlement_v75(uuid, text[], text[]); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.resolve_sector_entitlement_v75(p_bundle_version uuid, p_add_modules text[] DEFAULT '{}'::text[], p_remove_modules text[] DEFAULT '{}'::text[]) RETURNS text[]
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_base text[];
  v_requested text[];
  v_unknown text[];
begin
  select bundle.modules into v_base
    from public.sector_bundle_versions bundle
   where bundle.id = p_bundle_version;
  if not found then
    raise exception 'sector bundle version was not found' using errcode = '22023';
  end if;
  if coalesce(p_add_modules, '{}'::text[]) && coalesce(p_remove_modules, '{}'::text[]) then
    raise exception 'a module cannot be both added and removed' using errcode = '22023';
  end if;
  select array_agg(module_key order by module_key) into v_unknown
    from (
      select distinct requested module_key
        from unnest(
          coalesce(p_add_modules, '{}'::text[])
          || coalesce(p_remove_modules, '{}'::text[])
        ) requested
      except
      select registry.module_key from public.module_registry registry
    ) unknown;
  if coalesce(cardinality(v_unknown), 0) > 0 then
    raise exception 'unknown modules: %', array_to_string(v_unknown, ', ')
      using errcode = '22023';
  end if;
  select coalesce(array_agg(module_key order by module_key), '{}'::text[])
    into v_requested
    from (
      select unnest(v_base) module_key
      except
      select unnest(coalesce(p_remove_modules, '{}'::text[]))
      union
      select unnest(coalesce(p_add_modules, '{}'::text[]))
    ) requested;
  return app.resolve_module_dependencies(v_requested);
end
$$;

--
-- Name: resolve_verified_booking_client_v72(uuid, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.resolve_verified_booking_client_v72(p_business uuid, p_authenticated_user uuid) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  select link.client_id
    from public.customer_links link
    join public.customer_identities identity
      on identity.id = link.identity_id
     and identity.auth_user_id = link.auth_user_id
   where link.business_id = p_business
     and link.auth_user_id = p_authenticated_user
     and link.state = 'verified'
     and identity.status = 'active'
   order by link.verified_at desc, link.id
   limit 1
$$;

--
-- Name: retention_campaign_child_immutable_guard(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.retention_campaign_child_immutable_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $_$
begin
  if tg_table_name='retention_campaign_grants'
     and tg_op='UPDATE'
     and old.request_hash is null
     and new.request_hash is not null
     and new.request_hash~'^[0-9a-f]{64}$'
     and new.reward_grant_id is not null
     and (
       pg_catalog.to_jsonb(new)-'reward_grant_id'-'request_hash'
     )=(
       pg_catalog.to_jsonb(old)-'reward_grant_id'-'request_hash'
     ) then
    return new;
  end if;
  raise exception
    'campaign membership, offer, and return evidence is append-only'
    using errcode='restrict_violation';
end
$_$;

--
-- Name: retention_campaign_guard(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.retention_campaign_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if tg_op = 'DELETE' then
    raise exception 'retention campaigns are append-only' using errcode = 'restrict_violation';
  end if;
  if new.id is distinct from old.id
     or new.business_id is distinct from old.business_id
     or new.retention_program_version_id is distinct from old.retention_program_version_id
     or new.program_id is distinct from old.program_id
     or new.config_version_id is distinct from old.config_version_id
     or new.name is distinct from old.name
     or new.audience_criteria is distinct from old.audience_criteria
     or new.holdout_percent is distinct from old.holdout_percent
     or new.budget_cap_cents is distinct from old.budget_cap_cents
     or new.attribution_window_days is distinct from old.attribution_window_days
     or new.created_by is distinct from old.created_by
     or new.created_at is distinct from old.created_at then
    raise exception 'retention campaign identity and terms are immutable'
      using errcode = 'restrict_violation';
  end if;
  if (old.activated_at is not null and new.activated_at is distinct from old.activated_at)
     or (old.audience_size is not null and new.audience_size is distinct from old.audience_size) then
    raise exception 'a frozen campaign audience and activation are immutable'
      using errcode = 'restrict_violation';
  end if;
  if not (
       (old.status = 'draft' and new.status in ('draft', 'active', 'cancelled'))
    or (old.status = 'active' and new.status in ('active', 'completed', 'cancelled'))
    or (old.status = new.status)
  ) then
    raise exception 'illegal retention campaign status transition % -> %', old.status, new.status
      using errcode = 'restrict_violation';
  end if;
  return new;
end $$;

--
-- Name: retention_recommendation_run_guard(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.retention_recommendation_run_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if tg_op='DELETE' then
    raise exception 'recommendation runs are immutable evidence' using errcode='restrict_violation';
  end if;
  if old.status='draft_ready' or new.business_id is distinct from old.business_id
     or new.idempotency_key is distinct from old.idempotency_key
     or new.request_hash is distinct from old.request_hash
     or new.input_metrics is distinct from old.input_metrics
     or new.created_by is distinct from old.created_by then
    raise exception 'completed recommendation runs are immutable' using errcode='restrict_violation';
  end if;
  return new;
end $$;

--
-- Name: reverse_customer_birthday_benefit_redemption(uuid, text, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.reverse_customer_birthday_benefit_redemption(p_redemption_id uuid, p_reason text, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_original public.customer_birthday_redemptions%rowtype; v_entitlement public.customer_birthday_entitlements%rowtype;
  v_existing public.customer_birthday_redemptions%rowtype; v_reversal public.customer_birthday_redemptions%rowtype;
  v_reason text:=nullif(btrim(p_reason),''); v_hash text; v_as_of timestamptz:=statement_timestamp();
begin
  if not app.platform_feature_enabled('customer_birthday_benefits') then
    raise exception 'birthday benefit unavailable' using errcode='0A000';
  end if;
  select * into v_original from public.customer_birthday_redemptions where id=p_redemption_id for update;
  if not found or v_original.operation_kind<>'redemption' then raise exception 'birthday benefit unavailable' using errcode='42501'; end if;
  if auth.uid() is null or not app.c45_owner_loyalty_write(v_original.business_id) then raise exception 'owner loyalty reversal authorization is required' using errcode='42501'; end if;
  if p_idempotency_key is null or v_reason is null or length(v_reason)<3 or length(v_reason)>500 then raise exception 'a reversal reason is required' using errcode='22023'; end if;
  v_hash:=app.c45_hash(jsonb_build_object('redemption_id',p_redemption_id,'reason',v_reason)::text);
  select * into v_existing from public.customer_birthday_redemptions
   where original_redemption_id=p_redemption_id and actor=auth.uid() and operation_kind='reversal' and idempotency_key=p_idempotency_key for share;
  if found then
    if v_existing.request_hash is distinct from v_hash then raise exception 'birthday reversal conflicts with an existing operation' using errcode='40001'; end if;
    return jsonb_build_object('status','reversed','replayed',true);
  end if;
  if not v_original.active then raise exception 'birthday benefit unavailable' using errcode='42501'; end if;
  select * into v_entitlement from public.customer_birthday_entitlements where id=v_original.entitlement_id for update;
  perform set_config('app.c45_redemption_id',v_original.id::text,true);
  update public.customer_birthday_redemptions set active=false where id=v_original.id;
  insert into public.customer_birthday_redemptions(entitlement_id,business_id,client_id,branch_id,actor,operation_kind,original_redemption_id,idempotency_key,request_hash,reason)
  values(v_entitlement.id,v_entitlement.business_id,v_entitlement.client_id,v_original.branch_id,auth.uid(),'reversal',v_original.id,p_idempotency_key,v_hash,v_reason)
  returning * into v_reversal;
  perform set_config('app.c45_entitlement_id',v_entitlement.id::text,true);
  -- Expiry is an effective projection of the immutable end instant, never a
  -- state write hidden inside a failed redemption. A successful reversal only
  -- restores the underlying available state; readers derive expired if needed.
  update public.customer_birthday_entitlements set status='available' where id=v_entitlement.id;
  insert into public.audit_log(business_id,actor,action,entity,entity_id,detail)
  values(v_original.business_id,auth.uid(),'REVERSE_BIRTHDAY_BENEFIT_REDEMPTION','customer_birthday_redemptions',v_reversal.id,jsonb_build_object('reason',v_reason,'compensates_redemption_id',v_original.id));
  return jsonb_build_object('status','reversed','replayed',false);
end $$;

--
-- Name: reward_default_programme_v313(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.reward_default_programme_v313(p_business uuid) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  select coalesce(
    (select accruing.id
       from (select spine.id, count(*) over () as active_accruing
               from public.business_programmes spine
              where spine.business_id = p_business
                and spine.active
                and spine.kind in ('points','stamps')) accruing
      where accruing.active_accruing = 1),
    (select spine.id from public.business_programmes spine
      where spine.business_id = p_business and spine.kind = 'points')
  )
$$;

--
-- Name: FUNCTION reward_default_programme_v313(p_business uuid); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.reward_default_programme_v313(p_business uuid) IS 'v313 W6i1 authoring default, REBODIED BY v314. The programme a NEW reward belongs to when the author did not say: the business''s ONE active accruing programme when there is exactly one, and the points spine row otherwise (including when both run — a two-programme firm must choose, and increment 2''s authoring UI is where it does). No longer consults app.resolve_ledger_programme_v309, which the inversion turned into a statement about a settings column.';

--
-- Name: reward_grant_snapshot_guard(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.reward_grant_snapshot_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if tg_op='INSERT' then
    if new.reward_snapshot is null then
      raise exception 'retention grant snapshot is required'
        using errcode='23514';
    end if;
    return new;
  end if;
  if new.id is distinct from old.id
     or new.business_id is distinct from old.business_id
     or new.program_id is distinct from old.program_id
     or new.client_id is distinct from old.client_id
     or new.period_index is distinct from old.period_index
     or new.period_start is distinct from old.period_start
     or new.period_end is distinct from old.period_end
     or new.reward_type is distinct from old.reward_type
     or new.reward_value is distinct from old.reward_value
     or new.reward_item is distinct from old.reward_item
     or new.granted_at is distinct from old.granted_at
     or new.config_version_id is distinct from old.config_version_id
     or new.retention_program_version_id
        is distinct from old.retention_program_version_id
     or new.reward_taxonomy_id is distinct from old.reward_taxonomy_id
     or new.reward_label is distinct from old.reward_label
     or new.fulfillment_kind is distinct from old.fulfillment_kind
     or new.reward_snapshot is distinct from old.reward_snapshot
     or new.campaign_id is distinct from old.campaign_id
     or new.campaign_assignment is distinct from old.campaign_assignment then
    raise exception
      'reward grant identity, economics, window and provenance are immutable'
      using errcode='restrict_violation';
  end if;
  return new;
end
$$;

--
-- Name: reward_programme_default_v313(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.reward_programme_default_v313() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if new.programme_id is null then
    if tg_table_name = 'loyalty_reward_versions' then
      -- A version belongs to the pot its LIVE reward is priced in. That is what makes the draft
      -- clone (v197), the v138 restore and a fresh draft of an existing reward all carry the
      -- reward's programme forward instead of re-deriving it, so a draft can never silently
      -- re-price a reward customers are already holding points for.
      select live.programme_id into new.programme_id
        from public.loyalty_rewards live
       where live.id = new.reward_id and live.business_id = new.business_id;
    end if;
    if new.programme_id is null then
      new.programme_id := app.reward_default_programme_v313(new.business_id);
    end if;
    if new.programme_id is null then
      raise exception 'reward programme is not resolvable for business %', new.business_id
        using errcode = '23514';
    end if;
  end if;
  return new;
end
$$;

--
-- Name: FUNCTION reward_programme_default_v313(); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.reward_programme_default_v313() IS 'v313 W6i1: BEFORE INSERT default for loyalty_rewards / loyalty_reward_versions.programme_id. A version inherits its LIVE reward''s programme; anything else falls back to app.reward_default_programme_v313(business_id). NEVER overrides a supplied value, and raises 23514 rather than writing NULL when no programme can be determined. This covers the three INSERT writers (save_loyalty_reward_draft, clone_reward_versions_for_config, ensure_published_reward_in_draft_v138) without needing a column-list needle against two publish-kernel bodies whose live shape carries an un-repo''d V176 Stage A patch.';

--
-- Name: reward_programme_tenant_guard_v313(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.reward_programme_tenant_guard_v313() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if new.programme_id is not null and not exists (
    select 1 from public.business_programmes spine
     where spine.id = new.programme_id and spine.business_id = new.business_id
  ) then
    raise exception 'reward is tagged with another tenant''s programme'
      using errcode = '42501';
  end if;
  return new;
end
$$;

--
-- Name: FUNCTION reward_programme_tenant_guard_v313(); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.reward_programme_tenant_guard_v313() IS 'v313 W6i1: refuses a loyalty_rewards / loyalty_reward_versions row whose programme_id belongs to another business. The FK references business_programmes(id) only, so without this a cross-tenant tag is a legal row and redeem_reward_core would drain a pot in the wrong firm''s namespace. Mirrors the guard v311:424-433 put on points_ledger.';

--
-- Name: reward_version_immutable_guard(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.reward_version_immutable_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_config uuid; v_reward_version uuid; v_status text;
begin
  if tg_table_name = 'loyalty_reward_versions' then
    v_config := coalesce(new.config_version_id, old.config_version_id);
  else
    v_reward_version := coalesce(new.reward_version_id, old.reward_version_id);
    select config_version_id into v_config from public.loyalty_reward_versions where id = v_reward_version;
  end if;
  select status into v_status from public.firm_config_versions where id = v_config;
  if v_status is distinct from 'draft' then
    raise exception 'published reward configuration is immutable' using errcode = 'restrict_violation';
  end if;
  if tg_op = 'DELETE' then return old; end if;
  return new;
end $$;

--
-- Name: role_class(text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.role_class(p_role text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  select case
    when p_role = 'owner'                             then 'owner'
    when p_role = 'manager'                           then 'admin'
    when p_role in ('staff','frontdesk','bookkeeper') then 'employee'
    else 'employee'
  end;
$$;

--
-- Name: FUNCTION role_class(p_role text); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.role_class(p_role text) IS 'v17: owner->owner, manager->admin, staff/frontdesk/bookkeeper->employee (unknown->employee).';

--
-- Name: role_perms(text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.role_perms(p_role text) RETURNS text[]
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
  select case p_role
    when 'owner'      then array['view_sales','create_sales','refund_sales',
                                 'reclassify_sales','view_finance','manage_sale_policy',
                                 'manage_team','manage_billing','custom_price_lines']
    when 'manager'    then array['view_sales','create_sales','refund_sales','view_finance',
                                 'custom_price_lines']
    when 'staff'      then array['view_sales','create_sales']
    when 'frontdesk'  then array['view_sales','create_sales']
    when 'bookkeeper' then array['view_sales','view_finance']
    when 'stylist'      then array['view_sales','create_sales']
    when 'receptionist' then array['view_sales','create_sales']
    else array[]::text[]
  end
$$;

