--
-- Name: run_bringback_issue_v361(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.run_bringback_issue_v361() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_business uuid; v_total integer := 0;
begin
  -- Expire first, so a lapsed voucher never counts as outstanding.
  update public.bringback_grants_v361 set status='expired'
   where status='granted' and expires_at is not null and expires_at <= now();
  for v_business in
    select distinct business_id from public.bringback_campaigns_v361 where active and deleted_at is null
  loop
    v_total := v_total + app.issue_bringback_for_business_v361(v_business);
  end loop;
  return v_total;
end $$;

--
-- Name: run_expense_recurrences(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.run_expense_recurrences() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare r record; guard integer; v_next date;
begin
  for r in select * from expense_recurrences
      where active and next_run_on <= (timezone('Asia/Singapore', now()))::date loop
    guard := 0;
    v_next := r.next_run_on;
    while v_next <= (timezone('Asia/Singapore', now()))::date and guard < 60 loop
      exit when r.ends_on is not null and v_next > r.ends_on;
      insert into expenses (business_id, branch_id, category, supplier, description,
                            amount_cents, currency, fx_rate_to_base, occurred_on,
                            recurrence_id, period_on, note)
      values (r.business_id, r.branch_id, r.category, r.supplier, r.name,
              r.amount_cents, r.currency, r.fx_rate_to_base, v_next,
              r.id, v_next, 'auto: recurring expense')
      on conflict do nothing;
      v_next := case r.cadence
                  when 'weekly' then v_next + 7
                  when 'annual' then (v_next + interval '1 year')::date
                  else (v_next + interval '1 month')::date
                end;
      guard := guard + 1;
    end loop;
    update expense_recurrences
       set next_run_on = v_next,
           active = case when r.ends_on is not null and v_next > r.ends_on then false else active end
     where id = r.id;
  end loop;
end $$;

--
-- Name: run_membership_renewals(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.run_membership_renewals() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  due record;
  v_sale public.sales%rowtype;
  v_credit_id uuid;
  v_period_start timestamptz;
  v_period_end timestamptz;
  v_catchup integer;
begin
  for due in
    select m.id, m.business_id, m.client_id, m.status,
           m.current_period_start, m.current_period_end,
           p.id as plan_id, p.name as plan_name, p.price_cents,
           p.credit_cents, p.cadence, p.active as plan_active
      from public.memberships m
      join public.membership_plans p
        on p.id = m.plan_id and p.business_id = m.business_id
     where m.status in ('active', 'cancel_at_period_end')
       and m.current_period_end <= now()
     order by m.current_period_end, m.id
     for update of m skip locked
  loop
    if due.status = 'cancel_at_period_end' or not due.plan_active then
      update public.memberships set status = 'cancelled' where id = due.id;
      continue;
    end if;

    v_period_start := due.current_period_end;
    v_catchup := 0;
    while v_period_start <= now() and v_catchup < 12 loop
      v_period_end := v_period_start + case due.cadence
        when 'monthly' then interval '1 month'
        when 'annual' then interval '1 year'
        else null
      end;
      if v_period_end is null then
        raise exception 'unsupported membership cadence %', due.cadence;
      end if;

      insert into public.sales (
        business_id, client_id, kind, amount_cents, occurred_at, note, staff_id
      ) values (
        due.business_id, due.client_id, 'membership', due.price_cents,
        now(), 'membership renewal: ' || due.plan_name, null
      ) returning * into v_sale;

      if due.credit_cents > 0 then
        v_credit_id := gen_random_uuid();
        perform set_config('app.credit_ledger_insert_id', v_credit_id::text, true);
        perform set_config('app.credit_ledger_write_scope', 'membership_renewal', true);
        insert into public.credit_ledger (
          id, business_id, client_id, entry_type, amount_cents, reference,
          sale_id, actor, idempotency_key
        ) values (
          v_credit_id, due.business_id, due.client_id, 'membership_credit',
          due.credit_cents, 'membership renewal credit: ' || due.plan_name,
          v_sale.id, null,
          'v20:membership:' || due.id || ':' || v_period_start
        );
        perform set_config('app.credit_ledger_insert_id', '', true);
        perform set_config('app.credit_ledger_write_scope', '', true);
      end if;

      v_period_start := v_period_end;
      v_catchup := v_catchup + 1;
    end loop;

    update public.memberships
       set current_period_start = v_period_start - case due.cadence
             when 'monthly' then interval '1 month'
             when 'annual' then interval '1 year'
           end,
           current_period_end = v_period_start
     where id = due.id;
  end loop;
end $$;

--
-- Name: run_outbox_sweep(integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.run_outbox_sweep(p_limit integer DEFAULT 200) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare o record; ev public.domain_events%rowtype; v_recipient text; v_done integer := 0; v_fail boolean;
begin
  for o in select * from public.event_outbox
            where delivery_status in ('pending','failed') and next_attempt_at <= now()
            order by next_attempt_at for update skip locked limit greatest(p_limit, 1) loop
    update public.event_outbox set delivery_status = 'delivering', updated_at = now() where id = o.id;
    v_fail := nullif(current_setting('app.ps1b_capture_fail', true), '') = '1';
    begin
      if v_fail then raise exception 'simulated comms provider outage'; end if;
      select * into ev from public.domain_events where event_id = o.event_id;
      -- Synthetic-only recipient. A real address/number is structurally uninsertable.
      v_recipient := 'synthetic:' || coalesce(ev.subject_client_id::text, ev.subject_identity_id::text, o.event_id::text) || '@example.test';
      insert into public.captured_messages(business_id, event_id, outbox_id, channel, recipient, template_key, rendered)
      values(o.business_id, o.event_id, o.id, 'in_app', v_recipient, ev.event_type,
        jsonb_build_object('event_type', ev.event_type, 'subject_client_id', ev.subject_client_id))
      on conflict (outbox_id) do nothing;
      update public.event_outbox set delivery_status = 'delivered', attempts = attempts + 1, updated_at = now(), last_error = null
       where id = o.id;
      v_done := v_done + 1;
    exception when others then
      update public.event_outbox
         set attempts = attempts + 1,
             delivery_status = case when attempts + 1 >= max_attempts then 'dead_letter' else 'failed' end,
             next_attempt_at = now() + (least(power(2, attempts + 1), 3600) || ' seconds')::interval,
             last_error = sqlerrm, updated_at = now()
       where id = o.id;
    end;
  end loop;
  return v_done;
end $$;

--
-- Name: run_points_expiry(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.run_points_expiry() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_business uuid;
begin
  for v_business in
    select distinct lp.business_id
      from public.loyalty_programs lp
     where lp.active
       and lp.kind = 'points'
       and coalesce(lp.expiry_days, 0) > 0
       and exists (                                        -- v311
         select 1 from public.business_programmes spine
          where spine.business_id = lp.business_id
            and spine.kind = 'points'
            and spine.active
       )
  loop
    perform app.run_points_expiry_for_business(v_business);
  end loop;
end $$;

--
-- Name: run_points_expiry_for_business(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.run_points_expiry_for_business(p_business uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_client record;
  v_batch record;
  v_points_id uuid;
  v_expired integer := 0;
  v_points_programme uuid;
begin
  select spine.id into v_points_programme
    from public.business_programmes spine
   where spine.business_id = p_business and spine.kind = 'points';
  if v_points_programme is null then
    return 0;
  end if;

  for v_client in
    select distinct pb.business_id, pb.client_id
      from public.points_batches pb
      join public.loyalty_programs lp on lp.business_id = pb.business_id
     where pb.business_id = p_business
       and pb.remaining > 0
       and pb.programme_id = v_points_programme
       and lp.active
       and lp.kind = 'points'
       and coalesce(lp.expiry_days, 0) > 0
       and (
         (lp.expiry_mode = 'fixed' and pb.expires_at <= now())
         or (
           lp.expiry_mode = 'inactivity'
           and not exists (
             select 1
               from public.points_ledger pl
              where pl.business_id = pb.business_id
                and pl.client_id = pb.client_id
                and pl.points > 0
                and (
                  pl.programme_id = pb.programme_id
                  -- v312: activity the pot INHERITED counts. A completed migration is the
                  -- only thing that moves a customer's money between programmes, and the
                  -- history it left behind is still that customer being active.
                  or exists (
                    select 1 from public.programme_pot_migrations m
                     where m.business_id = pb.business_id
                       and m.to_programme_id = pb.programme_id
                       and m.from_programme_id = pl.programme_id
                       and m.status = 'complete')
                )
                -- The transfer row itself is NOT activity: it would postpone every
                -- switched customer's expiry by N days, silently changing liability the
                -- owner did not choose. actor IS NULL on an 'adjust' row is provably
                -- unique to the programme_pot_transfer scope (v84:143-154).
                and not (pl.entry_type = 'adjust' and pl.actor is null)
                and pl.created_at > now() - make_interval(days => lp.expiry_days)
           )
         )
       )
  loop
    perform 1 from public.clients c
     where c.id = v_client.client_id
       and c.business_id = v_client.business_id
       for update;

    for v_batch in
      select pb.id, pb.remaining, pb.programme_id
        from public.points_batches pb
        join public.loyalty_programs lp on lp.business_id = pb.business_id
       where pb.business_id = v_client.business_id
         and pb.client_id = v_client.client_id
         and pb.remaining > 0
         and pb.programme_id = v_points_programme
         and lp.active
         and lp.kind = 'points'
         and coalesce(lp.expiry_days, 0) > 0
         and (
           (lp.expiry_mode = 'fixed' and pb.expires_at <= now())
           or lp.expiry_mode = 'inactivity'
         )
       order by pb.expires_at nulls last, pb.earned_at, pb.id
       for update of pb skip locked
    loop
      v_points_id := gen_random_uuid();
      perform set_config('app.points_ledger_insert_id', v_points_id::text, true);
      perform set_config('app.points_ledger_write_scope', 'points_expiry', true);
      insert into public.points_ledger (
        id, business_id, client_id, entry_type, points, reference, actor, programme_id
      ) values (
        v_points_id, v_client.business_id, v_client.client_id,
        'expire', -v_batch.remaining, 'points expiry batch ' || v_batch.id, null,
        v_batch.programme_id
      );
      perform set_config('app.points_ledger_insert_id', '', true);
      perform set_config('app.points_ledger_write_scope', '', true);

      update public.points_batches set remaining = 0 where id = v_batch.id;
      v_expired := v_expired + v_batch.remaining;
    end loop;
  end loop;
  return v_expired;
end $$;

--
-- Name: FUNCTION run_points_expiry_for_business(p_business uuid); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.run_points_expiry_for_business(p_business uuid) IS 'v20 points expiry sweep, v311 W5a programme-scoped. Both the client selection and the inner batch loop are filtered to the POINTS programme''s batches, the inactivity clock is read per programme (excluding the W5b pot-transfer row, which would otherwise postpone every switched customer''s expiry), and the expire row is tagged with the batch''s programme. Fails CLOSED: no points spine row means expire nothing.';

--
-- Name: run_programme_pot_migrations_v312(integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.run_programme_pot_migrations_v312(p_batch integer DEFAULT 5) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_job record;
  v_done integer;
  v_ran integer := 0;
begin
  for v_job in
    select m.id, m.business_id, m.from_programme_id, m.to_programme_id
      from public.programme_pot_migrations m
     where m.status in ('pending','running')
     order by m.requested_at
     limit greatest(coalesce(p_batch, 5), 1)
     for update skip locked
  loop
    update public.programme_pot_migrations set status = 'running' where id = v_job.id;
    v_done := app.migrate_programme_pot_v312(
      v_job.business_id, v_job.from_programme_id, v_job.to_programme_id, 500);
    if v_done = 0 then
      update public.programme_pot_migrations
         set status = 'complete', completed_at = now(),
             clients_done = clients_done
       where id = v_job.id;
    else
      update public.programme_pot_migrations
         set clients_done = clients_done + v_done
       where id = v_job.id;
    end if;
    v_ran := v_ran + 1;
  end loop;
  return v_ran;
end
$$;

--
-- Name: run_referral_shadow(integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.run_referral_shadow(p_limit integer DEFAULT 500) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare e record; v_active uuid; v_count integer := 0;
begin
  for e in select d.* from public.domain_events d
            where d.event_type = 'referral.qualified'
              and not exists(select 1 from public.benefit_shadow_evaluations s
                              where s.event_id = d.event_id and s.source_engine = 'referral')
            order by d.recorded_at limit greatest(p_limit, 1) loop
    select active_config_version_id into v_active from public.businesses where id = e.business_id;
    insert into public.benefit_shadow_evaluations(
      business_id, event_id, source_engine, rule_id, would_be_canonical_key, client_id,
      fulfilment_kind, face_value_cents, estimated_cost_cents, cost_basis, cost_confidence, config_version_id)
    values(e.business_id, e.event_id, 'referral', null,
      'referral:' || (e.payload->>'referral_id'), (e.payload->>'referrer_client_id')::uuid, 'referral_reward',
      coalesce((e.payload->>'reward_cents')::integer, 0), coalesce((e.payload->>'reward_cents')::integer, 0),
      'credit_face', 'high', v_active)
    on conflict (business_id, would_be_canonical_key, event_id) do nothing;
    v_count := v_count + 1;
  end loop;
  return v_count;
end $$;

--
-- Name: run_studio_executor(integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.run_studio_executor(p_limit integer DEFAULT 500) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare e record; v_total integer := 0;
begin
  for e in select d.event_id from public.domain_events d
            where d.event_type in ('sale.completed','birthday.activated','membership.renewed')
              and not exists(select 1 from public.domain_event_execution x where x.event_id = d.event_id)
            order by d.recorded_at limit greatest(p_limit, 1) loop
    v_total := v_total + app.ps1b_execute_event(e.event_id);
  end loop;
  return v_total;
end $$;

--
-- Name: run_subscription_lifecycle_v94(date); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.run_subscription_lifecycle_v94(p_as_of date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_run public.subscription_lifecycle_runs_v94%rowtype;
  v_business record;v_day integer;v_notice_day integer;v_created integer:=0;
  v_paused integer:=0;v_recovered integer:=0;v_evaluated integer:=0;
  v_prior public.business_subscription_lifecycle_v94%rowtype;
  v_rep record;v_summary jsonb;v_notice_id uuid;
begin
  if p_as_of is null then raise exception 'run_date_required' using errcode='22023';end if;
  perform pg_advisory_xact_lock(hashtextextended('v94:subscription:'||p_as_of::text,0));
  select * into v_run from public.subscription_lifecycle_runs_v94
  where run_date=p_as_of;
  if found and v_run.status='succeeded' then
    return v_run.summary||jsonb_build_object('replayed',true);
  elsif found then
    delete from public.subscription_lifecycle_runs_v94 where run_date=p_as_of;
  end if;
  insert into public.subscription_lifecycle_runs_v94(run_date,status)
  values(p_as_of,'running');

  for v_business in
    with overdue as (
      select distinct on(invoice.business_id)
        invoice.business_id,invoice.provider_invoice_id,
        (app.billing_due_anchor_v281(invoice) at time zone 'Asia/Singapore')::date due_date
      from public.billing_provider_invoices invoice
      where invoice.paid_normalized=false
        and invoice.status in ('open','uncollectible')
        and invoice.amount_remaining_cents>0
        and app.billing_due_anchor_v281(invoice) is not null
        and (app.billing_due_anchor_v281(invoice) at time zone 'Asia/Singapore')::date<=p_as_of
      order by invoice.business_id,app.billing_due_anchor_v281(invoice),invoice.id
    )
    select business.id business_id,overdue.provider_invoice_id,overdue.due_date
    from public.businesses business
    left join overdue on overdue.business_id=business.id
    where business.is_demo=false
    order by business.id
  loop
    v_evaluated:=v_evaluated+1;
    select * into v_prior
    from public.business_subscription_lifecycle_v94 lifecycle
    where lifecycle.business_id=v_business.business_id for update;
    if v_business.provider_invoice_id is null then
      if v_prior.state<>'current' then
        update public.business_subscription_lifecycle_v94
        set state='current',provider_invoice_id=null,due_date=null,
          overdue_day=null,workspace_paused=false,paused_at=null,
          recovered_at=now(),last_evaluated_on=p_as_of,
          version=version+1,updated_at=now()
        where business_id=v_business.business_id;
        insert into public.business_subscription_lifecycle_audit_v94(
          business_id,event_type,prior_state,new_state,actor,reason
        ) values(
          v_business.business_id,'payment_recovered',v_prior.state,'current',
          auth.uid(),'provider invoice no longer overdue'
        );
        v_recovered:=v_recovered+1;
      else
        update public.business_subscription_lifecycle_v94
        set last_evaluated_on=p_as_of,updated_at=now()
        where business_id=v_business.business_id;
      end if;
      continue;
    end if;
    v_day:=p_as_of-v_business.due_date;
    select * into v_rep from app.assigned_consultant_v94(v_business.business_id);
    -- One run creates only the currently actionable notice. A missed cron does
    -- not flood the bell with every historic day; normal daily runs still
    -- produce one notice per day, and 14 is the distinct pause notice.
    v_notice_day:=least(v_day,14);
    if v_notice_day>=0 then
      v_notice_id:=null;
      insert into public.business_billing_due_notices_v94(
        business_id,provider_invoice_id,due_date,due_day,
        notice_title,notice_body,consultant_id,representative_name,hotline_phone
      ) values(
        v_business.business_id,v_business.provider_invoice_id,
        v_business.due_date,v_notice_day,
        case when v_notice_day=0 then 'Subscription payment is due'
          when v_notice_day=14 then 'Workspace paused — payment overdue'
          else 'Subscription payment is overdue' end,
        case when v_rep.hotline_phone is null
          then case when v_notice_day=14
            then 'Your workspace is paused. Update billing to restore access.'
            else format('Payment is %s day(s) overdue. Update billing to avoid a day-14 workspace pause.',v_notice_day)
          end
          else format('Payment is %s day(s) overdue. Update billing or contact %s at %s.',v_notice_day,coalesce(v_rep.display_name,'your Nestly representative'),v_rep.hotline_phone)
        end,
        v_rep.consultant_id,v_rep.display_name,v_rep.hotline_phone
      ) on conflict(provider_invoice_id,due_day) do nothing
      returning id into v_notice_id;
      if v_notice_id is not null then
        v_created:=v_created+1;
        insert into public.notifications(
          business_id,kind,title,body,ref_table,ref_id
        ) values(
          v_business.business_id,'subscription_payment_due',
          case when v_notice_day=0 then 'Subscription payment is due'
            when v_notice_day=14 then 'Workspace paused — payment overdue'
            else 'Subscription payment is overdue' end,
          case when v_rep.hotline_phone is null
            then case when v_notice_day=14
              then 'Your workspace is paused. Update billing to restore access.'
              else format('Payment is %s day(s) overdue. Update billing to avoid a day-14 workspace pause.',v_notice_day)
            end
            else format('Payment is %s day(s) overdue. Update billing or contact %s at %s.',v_notice_day,coalesce(v_rep.display_name,'your Nestly representative'),v_rep.hotline_phone)
          end,
          'business_billing_due_notices_v94',v_notice_id
        );
      end if;
    end if;
    if v_day>=14 then
      update public.business_subscription_lifecycle_v94
      set state='paused',provider_invoice_id=v_business.provider_invoice_id,
        due_date=v_business.due_date,overdue_day=v_day,workspace_paused=true,
        paused_at=coalesce(paused_at,now()),last_evaluated_on=p_as_of,
        version=version+1,updated_at=now()
      where business_id=v_business.business_id
        and (state<>'paused' or provider_invoice_id is distinct from v_business.provider_invoice_id
          or overdue_day is distinct from v_day);
      if v_prior.state<>'paused' then
        insert into public.business_subscription_lifecycle_audit_v94(
          business_id,event_type,provider_invoice_id,prior_state,new_state,
          overdue_day,reason
        ) values(
          v_business.business_id,'workspace_paused',
          v_business.provider_invoice_id,v_prior.state,'paused',v_day,
          'automatic day-14 overdue subscription pause'
        );
        v_paused:=v_paused+1;
      end if;
    else
      update public.business_subscription_lifecycle_v94
      set state='grace',provider_invoice_id=v_business.provider_invoice_id,
        due_date=v_business.due_date,overdue_day=v_day,
        workspace_paused=false,paused_at=null,last_evaluated_on=p_as_of,
        version=case when state is distinct from 'grace'
          or provider_invoice_id is distinct from v_business.provider_invoice_id
          then version+1 else version end,
        updated_at=now()
      where business_id=v_business.business_id;
      if v_prior.state='current' then
        insert into public.business_subscription_lifecycle_audit_v94(
          business_id,event_type,provider_invoice_id,prior_state,new_state,
          overdue_day,reason
        ) values(
          v_business.business_id,'grace_started',
          v_business.provider_invoice_id,'current','grace',v_day,
          'subscription invoice reached its due date'
        );
      end if;
    end if;
  end loop;
  v_summary:=jsonb_build_object(
    'run_date',p_as_of,'businesses_evaluated',v_evaluated,
    'notices_created',v_created,'paused',v_paused,'recovered',v_recovered,
    'replayed',false
  );
  update public.subscription_lifecycle_runs_v94
  set status='succeeded',finished_at=now(),summary=v_summary
  where run_date=p_as_of;
  return v_summary;
exception when others then
  update public.subscription_lifecycle_runs_v94
  set status='failed',finished_at=now(),
    summary=jsonb_build_object('run_date',p_as_of,'error',sqlerrm)
  where run_date=p_as_of;
  raise;
end
$$;

--
-- Name: run_sv_expiry_sweep(integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.run_sv_expiry_sweep(p_limit integer DEFAULT 1000) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_run uuid; v_b uuid; v_done integer := 0; v_failed integer := 0;
begin
  v_run := app.sv_automation_begin('sv_expiry_sweep');
  for v_b in
    select a.business_id from public.sv_authority a
     where a.asset = 'stored_value' and a.state = 'live'
     order by a.business_id
  loop
    begin
      perform public.sv_expire_due(v_b, p_limit);
      v_done := v_done + 1;
    exception when others then
      v_failed := v_failed + 1;
      insert into public.audit_log(business_id, actor, action, entity, entity_id, detail)
      values (v_b, null, 'SV_AUTOMATION_ERROR', 'sv_automation_runs', v_run, jsonb_build_object(
        'job', 'sv_expiry_sweep', 'sqlstate', sqlstate, 'message', sqlerrm));
    end;
  end loop;
  perform app.sv_automation_finish(v_run, jsonb_build_object('succeeded', v_done, 'failed', v_failed));
  return v_done;
end $$;

--
-- Name: run_sv_reconciliation_sweep(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.run_sv_reconciliation_sweep() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_run uuid; v_b uuid; v_done integer := 0; v_failed integer := 0;
begin
  v_run := app.sv_automation_begin('sv_reconciliation_sweep');
  -- Every business that has begun stored value: pre-cutover evidence has to stay fresh (the
  -- cutover requires a clean run) and a live business has to stay monitored.
  for v_b in
    select a.business_id from public.sv_authority a
     where a.asset = 'stored_value' and a.state <> 'unbuilt'
     order by a.business_id
  loop
    begin
      perform public.run_sv_reconciliation(v_b);
      v_done := v_done + 1;
    exception when others then
      v_failed := v_failed + 1;
      insert into public.audit_log(business_id, actor, action, entity, entity_id, detail)
      values (v_b, null, 'SV_AUTOMATION_ERROR', 'sv_automation_runs', v_run, jsonb_build_object(
        'job', 'sv_reconciliation_sweep', 'sqlstate', sqlstate, 'message', sqlerrm));
    end;
  end loop;
  perform app.sv_automation_finish(v_run, jsonb_build_object('succeeded', v_done, 'failed', v_failed));
  return v_done;
end $$;

--
-- Name: run_sv_tender_release(integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.run_sv_tender_release(p_limit integer DEFAULT 1000) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_run uuid; v_b uuid; v_done integer := 0; v_failed integer := 0;
begin
  v_run := app.sv_automation_begin('sv_tender_release');
  -- Scoped by outstanding work, not by authority: an abandoned hold must be released even if the
  -- business was paused after the hold was taken, or its balance stays stranded.
  for v_b in
    select distinct t.business_id from public.checkout_sv_tenders t
     where t.status = 'reserved'
     order by t.business_id
  loop
    begin
      perform public.sv_release_expired_checkout_tenders(v_b, p_limit);
      v_done := v_done + 1;
    exception when others then
      v_failed := v_failed + 1;
      insert into public.audit_log(business_id, actor, action, entity, entity_id, detail)
      values (v_b, null, 'SV_AUTOMATION_ERROR', 'sv_automation_runs', v_run, jsonb_build_object(
        'job', 'sv_tender_release', 'sqlstate', sqlstate, 'message', sqlerrm));
    end;
  end loop;
  perform app.sv_automation_finish(v_run, jsonb_build_object('succeeded', v_done, 'failed', v_failed));
  return v_done;
end $$;

--
-- Name: sale_items_immutable_guard(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.sale_items_immutable_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  raise exception 'sale_items is append-only: % is not permitted', tg_op
    using errcode = 'restrict_violation';
end $$;

--
-- Name: sale_items_kind_guard(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.sale_items_kind_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_parent_kind text;
begin
  if new.item_type in ('package', 'membership', 'gift_card') then
    select s.kind into v_parent_kind
      from public.sales s
     where s.id = new.sale_id and s.business_id = new.business_id;
    if v_parent_kind in ('quick_sale', 'cart_sale') then
      raise exception
        'sale_items_kind_guard: a % line cannot ride under a % sale; use its dedicated engine',
        new.item_type, v_parent_kind
        using errcode = '23514';
    end if;
  end if;
  return new;
end $$;

--
-- Name: sale_policy(uuid, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.sale_policy(p_business uuid, p_kind text) RETURNS TABLE(kind text, counts_as_revenue boolean, counts_as_visit boolean, earns_points boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  select s.kind, s.counts_as_revenue, s.counts_as_visit, s.earns_points
  from app.sale_policy_set(p_business) s where s.kind = p_kind
$$;

--
-- Name: sale_policy_defaults(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.sale_policy_defaults() RETURNS TABLE(kind text, counts_as_revenue boolean, counts_as_visit boolean, earns_points boolean)
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  select * from (values
    ('service'::text,    true,  true,  true),
    ('retail'::text,     true,  true,  true),
    ('quick_sale'::text, true,  true,  true),
    ('membership'::text, true,  false, false),
    ('gift_card'::text,  false, false, false),
    ('package'::text,    true,  false, true),
    ('bottle_keep'::text, true,  true,  true)
  ) as t(kind, counts_as_revenue, counts_as_visit, earns_points)
$$;

--
-- Name: sale_policy_set(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.sale_policy_set(p_business uuid) RETURNS TABLE(kind text, counts_as_revenue boolean, counts_as_visit boolean, earns_points boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  select d.kind,
         coalesce(o.counts_as_revenue, d.counts_as_revenue),
         coalesce(o.counts_as_visit,   d.counts_as_visit),
         coalesce(o.earns_points,      d.earns_points)
  from app.sale_policy_defaults() d
  left join public.sale_policies o
    on o.business_id = p_business and o.kind = d.kind
$$;

--
-- Name: sales_immutable_guard(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.sales_immutable_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_reclassify text;
  v_backfill text;
begin
  if tg_op = 'DELETE' then
    raise exception 'sales is append-only: DELETE is not permitted (sale %). Use append-only reversal rows.',
      old.id
      using errcode = 'restrict_violation';
  end if;

  v_reclassify := nullif(current_setting('app.reclassify_sale', true), '');
  v_backfill := nullif(current_setting('app.sales_backfill', true), '');

  if v_reclassify is not null and v_reclassify = old.id::text then
    if (new.id, new.business_id, new.client_id, new.kind, new.amount_cents, new.occurred_at,
        new.created_at, new.note, new.appointment_id, new.product_id, new.qty,
        new.counts_as_visit, new.earns_points, new.policy_resolved_at,
        new.commission_rate_bps, new.commission_resolved_at,
        new.idem_key,
        new.branch_id, new.staff_id, new.reversal_of, new.reversal_reason,
        new.reversal_actor, new.reversal_idempotency_key, new.commission_flat_cents)
       is distinct from
       (old.id, old.business_id, old.client_id, old.kind, old.amount_cents, old.occurred_at,
        old.created_at, old.note, old.appointment_id, old.product_id, old.qty,
        old.counts_as_visit, old.earns_points, old.policy_resolved_at,
        old.commission_rate_bps, old.commission_resolved_at,
        old.idem_key,
        old.branch_id, old.staff_id, old.reversal_of, old.reversal_reason,
        old.reversal_actor, old.reversal_idempotency_key, old.commission_flat_cents)
    then
      raise exception 'reclassification of sale % may change counts_as_revenue and nothing else',
        old.id
        using errcode = 'restrict_violation';
    end if;
    return new;
  end if;

  if v_backfill is not null then
    if (new.id, new.business_id, new.client_id, new.kind, new.amount_cents, new.occurred_at,
        new.created_at, new.note, new.appointment_id, new.product_id, new.qty,
        new.counts_as_revenue, new.counts_as_visit, new.earns_points, new.policy_resolved_at,
        new.commission_rate_bps, new.commission_resolved_at,
        new.idem_key,
        new.branch_id, new.staff_id, new.reversal_of, new.reversal_reason,
        new.reversal_actor, new.reversal_idempotency_key, new.commission_flat_cents)
       is distinct from
       (old.id, old.business_id, old.client_id, old.kind, old.amount_cents, old.occurred_at,
        old.created_at, old.note, old.appointment_id, old.product_id, old.qty,
        old.counts_as_revenue, old.counts_as_visit, old.earns_points, old.policy_resolved_at,
        old.commission_rate_bps, old.commission_resolved_at,
        old.idem_key,
        old.branch_id, old.staff_id, old.reversal_of, old.reversal_reason,
        old.reversal_actor, old.reversal_idempotency_key, old.commission_flat_cents)
    then
      raise exception 'backfill window "%" may not change economic facts, attribution, snapshots, or reversal metadata of sale %',
        v_backfill, old.id
        using errcode = 'restrict_violation';
    end if;
    return new;
  end if;

  raise exception 'sales is append-only: UPDATE is not permitted (sale %)', old.id
    using errcode = 'restrict_violation';
end $$;

--
-- Name: sales_reversal_insert_guard(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.sales_reversal_insert_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_sale_token text;
  v_original_token text;
begin
  if new.reversal_of is null then
    return new;
  end if;

  v_sale_token := nullif(current_setting('app.sale_reversal_insert_id', true), '');
  v_original_token := nullif(current_setting('app.sale_reversal_original_id', true), '');

  if v_sale_token is distinct from new.id::text
     or v_original_token is distinct from new.reversal_of::text then
    raise exception 'sale reversal rows must be created through public.reverse_sale()'
      using errcode = '42501';
  end if;

  return new;
end $$;

--
-- Name: save_promotion_scope_v155(uuid, uuid, text, uuid[], uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.save_promotion_scope_v155(p_business uuid, p_promotion uuid, p_scope_mode text, p_branch_ids uuid[] DEFAULT ARRAY[]::uuid[], p_operational_branch uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_mode text := coalesce(nullif(btrim(p_scope_mode),''),'all');
  v_ids uuid[];
  v_actor uuid := auth.uid();
begin
  if v_actor is null then
    raise exception 'authenticated_session_required' using errcode='28000';
  end if;
  if not app.is_salon_owner(p_business) and not app.is_super_admin() then
    raise exception 'owner_required' using errcode='42501';
  end if;
  if v_mode not in ('all','current','selected') then
    raise exception 'unsupported_promotion_scope' using errcode='22023';
  end if;
  if not exists(
    select 1 from public.business_customer_content_v95 content
    where content.id = p_promotion
      and content.business_id = p_business
      and content.content_type = 'offer'
  ) then
    raise exception 'promotion_not_found' using errcode='22023';
  end if;

  if v_mode = 'all' then
    delete from public.promotion_branch_scopes_v155 scope
    where scope.business_id = p_business
      and scope.promotion_id = p_promotion;
    perform set_config('app.v104_promotion_write','on',true);
    update public.business_customer_content_v95
    set branch_id = null,
        metadata = coalesce(metadata,'{}'::jsonb) || jsonb_build_object(
          'branch_scope',jsonb_build_object('mode','all_branches')
        ),
        version = version + 1,
        updated_by = v_actor,
        updated_at = now()
    where id = p_promotion and business_id = p_business;
    perform set_config('app.v104_promotion_write','',true);
    return jsonb_build_object('mode','all','branch_ids','[]'::jsonb);
  end if;

  select coalesce(array_agg(scope.branch_id order by scope.branch_name),array[]::uuid[])
    into v_ids
  from app.resolve_reporting_branch_scope_v155(
    p_business,
    case when v_mode='current' then 'current' else 'selected' end,
    p_branch_ids,
    p_operational_branch
  ) scope;
  if cardinality(v_ids) = 0 then
    raise exception 'empty_selected_branch_scope' using errcode='22023';
  end if;

  delete from public.promotion_branch_scopes_v155 scope
  where scope.business_id = p_business
    and scope.promotion_id = p_promotion
    and not (scope.branch_id = any(v_ids));

  insert into public.promotion_branch_scopes_v155(
    promotion_id,business_id,branch_id,created_by
  )
  select p_promotion,p_business,branch_id,v_actor
  from unnest(v_ids) branch_id
  on conflict (promotion_id,branch_id) do nothing;

  perform set_config('app.v104_promotion_write','on',true);
  update public.business_customer_content_v95
  set branch_id = null,
      metadata = coalesce(metadata,'{}'::jsonb) || jsonb_build_object(
        'branch_scope',jsonb_build_object(
          'mode','selected_branches',
          'branch_ids',to_jsonb(v_ids)
        )
      ),
      version = version + 1,
      updated_by = v_actor,
      updated_at = now()
  where id = p_promotion and business_id = p_business;
  perform set_config('app.v104_promotion_write','',true);

  return jsonb_build_object('mode','selected','branch_ids',to_jsonb(v_ids));
end
$$;

--
-- Name: seed_benefit_registry(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.seed_benefit_registry(p_business uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  insert into public.benefit_registry(business_id, source_engine, execution_authority, cutover_status,
    shadow_started_at, cutover_at, canonical_benefit_key_template)
  values
    (p_business, 'points_loyalty', 'legacy_trigger',  'legacy', null, null, 'points_redeem:{loyalty_operation_id}'),
    (p_business, 'retention',      'legacy_trigger',  'legacy', null, null, 'retention:{program_id}:{client_id}:{period_index}'),
    (p_business, 'referral',       'legacy_trigger',  'shadow', now(), null, 'referral:{referral_id}'),
    (p_business, 'birthday',       'legacy_trigger',  'legacy', null, null, 'birthday:{client_id}:{birthday_year}'),
    (p_business, 'membership',     'legacy_trigger',  'legacy', null, null, 'membership_credit:{membership_id}:{period_key}'),
    (p_business, 'campaign',       'legacy_trigger',  'legacy', null, null, 'campaign_offer:{campaign_id}:{client_id}'),
    (p_business, 'tier',           'studio_executor', 'unbuilt', null, null, 'tier_entry:{client_id}:{tier}'),
    (p_business, 'recurring',      'studio_executor', 'studio', null, now(), 'recurring:{rule_id}:{client_id}:{period_key}'),
    (p_business, 'checkout',       'studio_executor', 'studio', null, now(), 'discount:{sale_id}:{rule_id}:{effect_index}'),
    (p_business, 'stored_value',   'studio_executor', 'unbuilt', null, null, 'sv_spend:{operation_id}:{movement_id}')
  on conflict (business_id, source_engine) do nothing;
end $$;

--
-- Name: seed_business_platform_intelligence_v94(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.seed_business_platform_intelligence_v94() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
