--
-- Name: billing_plan_catalog_v124; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.billing_plan_catalog_v124 (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    currency text DEFAULT 'SGD'::text NOT NULL,
    cadence text NOT NULL,
    cadence_months smallint NOT NULL,
    provider text DEFAULT 'stripe'::text NOT NULL,
    provider_base_price_id text NOT NULL,
    provider_capacity_price_id text NOT NULL,
    base_amount_cents integer NOT NULL,
    included_customer_capacity integer DEFAULT 1000 NOT NULL,
    capacity_block_size integer DEFAULT 1000 NOT NULL,
    capacity_block_amount_cents integer NOT NULL,
    compare_at_monthly_cents integer DEFAULT 16800 NOT NULL,
    tax_behavior text DEFAULT 'exclusive'::text NOT NULL,
    active boolean DEFAULT true NOT NULL,
    effective_from timestamp with time zone DEFAULT now() NOT NULL,
    effective_to timestamp with time zone,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT billing_plan_catalog_v124_cadence_check CHECK ((cadence = ANY (ARRAY['monthly'::text, 'annual'::text]))),
    CONSTRAINT billing_plan_catalog_v124_cadence_months_check CHECK ((cadence_months = ANY (ARRAY[1, 12]))),
    CONSTRAINT billing_plan_catalog_v124_cadence_pair CHECK ((((cadence = 'monthly'::text) AND (cadence_months = 1) AND (capacity_block_amount_cents = 1000) AND ((base_amount_cents = 14800) OR ((base_amount_cents = 14900) AND (active = false) AND (effective_to IS NOT NULL)))) OR ((cadence = 'annual'::text) AND (cadence_months = 12) AND (base_amount_cents = 118800) AND (capacity_block_amount_cents = 12000)))),
    CONSTRAINT billing_plan_catalog_v124_capacity_block_size_check CHECK ((capacity_block_size = 1000)),
    CONSTRAINT billing_plan_catalog_v124_compare_at_monthly_cents_check CHECK ((compare_at_monthly_cents = 16800)),
    CONSTRAINT billing_plan_catalog_v124_currency_check CHECK ((currency = 'SGD'::text)),
    CONSTRAINT billing_plan_catalog_v124_distinct_prices CHECK ((provider_base_price_id <> provider_capacity_price_id)),
    CONSTRAINT billing_plan_catalog_v124_included_customer_capacity_check CHECK ((included_customer_capacity = 1000)),
    CONSTRAINT billing_plan_catalog_v124_provider_base_price_id_check CHECK ((provider_base_price_id ~ '^price_[A-Za-z0-9_]+$'::text)),
    CONSTRAINT billing_plan_catalog_v124_provider_capacity_price_id_check CHECK ((provider_capacity_price_id ~ '^price_[A-Za-z0-9_]+$'::text)),
    CONSTRAINT billing_plan_catalog_v124_provider_check CHECK ((provider = 'stripe'::text)),
    CONSTRAINT billing_plan_catalog_v124_tax_behavior_check CHECK ((tax_behavior = ANY (ARRAY['inclusive'::text, 'exclusive'::text, 'unspecified'::text]))),
    CONSTRAINT billing_plan_catalog_v124_window CHECK (((effective_to IS NULL) OR (effective_to > effective_from))),
    CONSTRAINT billing_plan_catalog_v125_no_gst_tax_behavior CHECK ((tax_behavior = 'exclusive'::text))
);

--
-- Name: TABLE billing_plan_catalog_v124; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.billing_plan_catalog_v124 IS 'V124 launch pricing; SGD 168 is comparison metadata only and never a charge.';

--
-- Name: self_serve_plan_total_v130(public.billing_plan_catalog_v124, integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.self_serve_plan_total_v130(p_catalog public.billing_plan_catalog_v124, p_customer_capacity integer) RETURNS integer
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  select (p_catalog).base_amount_cents
    + greatest(p_customer_capacity/(p_catalog).capacity_block_size-1,0)
      * (p_catalog).capacity_block_amount_cents
$$;

