--
-- Name: sme_prospect_card_v76(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.sme_prospect_card_v76(p_prospect uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  select jsonb_build_object(
    'id',prospect.id,'company_id',company.id,'legal_name',company.legal_name,
    'trading_name',company.trading_name,'registration_number',company.registration_number,
    'industry',company.industry,'sector_key',company.sector_key,
    'current_stage_key',prospect.current_stage_key,'legacy_stage_raw',prospect.legacy_stage_raw,
    'assigned_consultant_id',prospect.assigned_consultant_id,
    'consultant_name',consultant.display_name,'next_action_at',prospect.next_action_at,
    'next_action_overdue',prospect.next_action_at is not null and prospect.next_action_at<now(),
    'priority',prospect.priority,'region',prospect.region,'fit_score',qualification.score,
    'primary_contact',case when contact.id is null then null else jsonb_build_object(
      'id',contact.id,'full_name',contact.full_name,'title',contact.title,
      'phone',contact.phone,'email',contact.email) end,
    'source',case when source.id is null then null else jsonb_build_object(
      'source_system',source.source_system,'source_type',source.source_type,
      'external_id',source.external_id) end,
    'tags',coalesce(tags.items,'[]'::jsonb),
    'last_activity',case when activity.id is null then null else jsonb_build_object(
      'id',activity.id,'activity_type',activity.activity_type,'summary',activity.summary,
      'detail',activity.detail,'occurred_at',activity.occurred_at) end,
    'stage_entered_at',prospect.stage_entered_at,
    'stage_age_days',greatest(0,current_date-(prospect.stage_entered_at at time zone 'Asia/Singapore')::date),
    'data_completeness_percent',
      (case when coalesce(company.legal_name,company.trading_name) is not null then 20 else 0 end)
      +(case when company.registration_number is not null then 15 else 0 end)
      +(case when coalesce(company.sector_key,company.industry) is not null then 10 else 0 end)
      +(case when contact.id is not null then 10 else 0 end)
      +(case when contact.email is not null then 10 else 0 end)
      +(case when contact.phone is not null then 10 else 0 end)
      +(case when source.id is not null then 5 else 0 end)
      +(case when prospect.assigned_consultant_id is not null then 5 else 0 end)
      +(case when qualification.score is not null then 5 else 0 end)
      +(case when prospect.next_action_at is not null then 5 else 0 end)
      +(case when prospect.current_stage_key is not null then 5 else 0 end),
    'open_data_quality_warnings',coalesce(quality.open_count,0),
    'version',prospect.version,'updated_at',prospect.updated_at,
    'converted_business_id',prospect.converted_business_id,'converted_at',prospect.converted_at
  )
  from public.sme_prospects prospect
  join public.sme_companies company on company.id=prospect.company_id
  left join public.platform_consultants consultant on consultant.id=prospect.assigned_consultant_id
  left join lateral (
    select c.* from public.sme_prospect_contacts c
     where c.prospect_id=prospect.id and c.active
     order by c.is_primary desc,c.created_at limit 1
  ) contact on true
  left join lateral (
    select s.* from public.sme_prospect_source_lineage s
     where s.prospect_id=prospect.id order by s.created_at,s.id limit 1
  ) source on true
  left join lateral (
    select q.* from public.sme_prospect_qualification_versions q
     where q.prospect_id=prospect.id order by q.version desc limit 1
  ) qualification on true
  left join lateral (
    select a.* from public.sme_prospect_activities a
     where a.prospect_id=prospect.id order by a.occurred_at desc,a.created_at desc limit 1
  ) activity on true
  left join lateral (
    select jsonb_agg(jsonb_build_object('tag_key',tag.tag_key,'label',tag.label)
      order by tag.label) items
      from public.sme_prospect_tags link join public.sme_tags tag on tag.id=link.tag_id
     where link.prospect_id=prospect.id
  ) tags on true
  left join lateral (
    select count(*)::integer open_count from public.sme_prospect_data_quality_flags flag
     where flag.prospect_id=prospect.id and flag.resolved_at is null
       and flag.severity in ('warning','blocking')
  ) quality on true
  where prospect.id=p_prospect
$$;

--
-- Name: sme_prospect_search_match_v76(uuid, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.sme_prospect_search_match_v76(p_prospect uuid, p_search text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  select p_search is null or exists(
    select 1 from public.sme_prospects prospect
    join public.sme_companies company on company.id=prospect.company_id
    where prospect.id=p_prospect and (
      concat_ws(' ',company.legal_name,company.trading_name,company.registration_number,
        company.email,company.phone,company.industry,company.sector_key) ilike '%'||p_search||'%'
      or exists(select 1 from public.sme_prospect_contacts contact
        where contact.prospect_id=prospect.id and concat_ws(' ',contact.full_name,
          contact.title,contact.email,contact.phone) ilike '%'||p_search||'%')
      or exists(select 1 from public.sme_prospect_activities activity
        where activity.prospect_id=prospect.id and concat_ws(' ',activity.summary,
          activity.detail) ilike '%'||p_search||'%')
      or exists(select 1 from public.sme_prospect_qualification_versions qualification
        where qualification.prospect_id=prospect.id
          and qualification.notes ilike '%'||p_search||'%')
    )
  )
$$;

--
-- Name: snapshot_reward_grant_taxonomy(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.snapshot_reward_grant_taxonomy() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_rule public.retention_program_versions%rowtype;
  v_tax public.firm_reward_taxonomy%rowtype;
  v_campaign public.retention_campaigns%rowtype;
  v_period_start timestamptz;
  v_period_end timestamptz;
begin
  perform 1
  from public.businesses
  where id=new.business_id
  for share;

  if new.campaign_id is not null then
    select campaign.* into v_campaign
    from public.retention_campaigns campaign
    where campaign.id=new.campaign_id
      and campaign.business_id=new.business_id;
    if not found then
      raise exception 'campaign reward grant campaign was not found'
        using errcode='foreign_key_violation';
    end if;
    if v_campaign.status<>'active' then
      raise exception 'campaign reward entitlements require an active campaign'
        using errcode='object_not_in_prerequisite_state';
    end if;
    if not exists(
      select 1
      from public.retention_campaign_members member
      where member.campaign_id=v_campaign.id
        and member.business_id=v_campaign.business_id
        and member.client_id=new.client_id
        and member.assignment='treatment'
    ) then
      raise exception 'campaign reward entitlements are treatment-only'
        using errcode='42501';
    end if;
    select rule.* into v_rule
    from public.retention_program_versions rule
    where rule.id=v_campaign.retention_program_version_id
      and rule.program_id=v_campaign.program_id
      and rule.business_id=v_campaign.business_id
      and rule.config_version_id=v_campaign.config_version_id;
    if not found then
      raise exception 'campaign published retention reward is unavailable'
        using errcode='object_not_in_prerequisite_state';
    end if;
    if not exists(
      select 1
      from public.firm_config_versions config
      join public.businesses business
        on business.id=config.business_id
       and business.active_config_version_id=config.id
      where config.id=v_campaign.config_version_id
        and config.business_id=v_campaign.business_id
        and config.status='published'
    ) then
      raise exception
        'campaign reward version is no longer the active published configuration'
        using errcode='object_not_in_prerequisite_state';
    end if;
    select taxonomy.* into v_tax
    from public.firm_reward_taxonomy taxonomy
    where taxonomy.id=v_rule.reward_taxonomy_id
      and taxonomy.business_id=v_rule.business_id;
    if not found then
      raise exception 'campaign reward taxonomy was not found'
        using errcode='foreign_key_violation';
    end if;
    if new.program_id is distinct from v_campaign.program_id
       or new.config_version_id is distinct from v_campaign.config_version_id
       or (
         new.retention_program_version_id is not null
         and new.retention_program_version_id<>v_rule.id
       )
       or (
         new.campaign_assignment is not null
         and new.campaign_assignment<>'treatment'
       ) then
      raise exception 'campaign reward provenance does not match the campaign'
        using errcode='check_violation';
    end if;
    v_period_start:=v_campaign.activated_at;
    v_period_end:=v_period_start
      + pg_catalog.make_interval(
          days=>v_campaign.attribution_window_days
        );
    if new.period_index<>0
       or (
         new.period_start is not null
         and new.period_start is distinct from v_period_start
       )
       or (
         new.period_end is not null
         and new.period_end is distinct from v_period_end
       ) then
      raise exception 'campaign reward window must match campaign activation'
        using errcode='check_violation';
    end if;
    new.campaign_assignment:='treatment';
    new.retention_program_version_id:=v_rule.id;
    new.period_start:=v_period_start;
    new.period_end:=v_period_end;
    new.reward_taxonomy_id:=v_rule.reward_taxonomy_id;
    new.reward_label:=v_tax.label;
    new.fulfillment_kind:=v_rule.fulfillment_kind;
    new.reward_type:=v_rule.fulfillment_kind;
    new.reward_value:=coalesce(
      v_rule.discount_percent,v_rule.credit_cents,0
    );
    new.reward_item:=v_rule.manual_item;
    new.reward_snapshot:=pg_catalog.jsonb_build_object(
      'legacy',false,
      'entitlement_source','retention_campaign_offer',
      'campaign_id',v_campaign.id,
      'program_id',v_rule.program_id,
      'retention_program_version_id',v_rule.id,
      'config_version_id',v_rule.config_version_id,
      'name',v_rule.name,
      'reward_taxonomy_id',v_rule.reward_taxonomy_id,
      'reward_label',v_tax.label,
      'fulfillment_kind',v_rule.fulfillment_kind,
      'discount_percent',v_rule.discount_percent,
      'credit_cents',v_rule.credit_cents,
      'manual_item',v_rule.manual_item,
      'period_start',v_period_start,
      'period_end',v_period_end
    );
    return new;
  end if;

  select rule.* into v_rule
  from public.retention_program_versions rule
  where rule.program_id=new.program_id
    and rule.business_id=new.business_id
    and rule.config_version_id=new.config_version_id;
  if not found then
    raise exception
      'retention program version not found for stamped configuration';
  end if;
  select taxonomy.* into v_tax
  from public.firm_reward_taxonomy taxonomy
  where taxonomy.id=v_rule.reward_taxonomy_id
    and taxonomy.business_id=v_rule.business_id;
  if not found then
    raise exception 'retention reward taxonomy not found';
  end if;
  if new.retention_program_version_id is not null
     and new.retention_program_version_id<>v_rule.id then
    raise exception
      'reward grant retention version does not match its stamped configuration'
      using errcode='23514';
  end if;
  if new.period_index<0 then
    raise exception 'retention grant period index cannot be negative'
      using errcode='23514';
  end if;
  v_period_start:=v_rule.starts_on::timestamptz
    + pg_catalog.make_interval(days=>new.period_index*v_rule.period_days);
  v_period_end:=v_period_start
    + pg_catalog.make_interval(days=>v_rule.period_days);
  if (
       new.period_start is not null
       and new.period_start is distinct from v_period_start
     )
     or (
       new.period_end is not null
       and new.period_end is distinct from v_period_end
     ) then
    raise exception
      'reward grant period does not match its immutable retention version'
      using errcode='23514';
  end if;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      new.business_id::text||':'||new.program_id::text
        ||':'||new.client_id::text,
      0
    )
  );
  if exists(
    select 1
    from public.reward_grants grant_row
    where grant_row.business_id=new.business_id
      and grant_row.program_id=new.program_id
      and grant_row.client_id=new.client_id
      and grant_row.campaign_id is null
      and grant_row.id<>new.id
      and grant_row.period_start<v_period_end
      and v_period_start<grant_row.period_end
  ) then
    raise exception
      'retention reward already granted for an overlapping programme window'
      using errcode='23505';
  end if;
  new.retention_program_version_id:=v_rule.id;
  new.period_start:=v_period_start;
  new.period_end:=v_period_end;
  new.reward_taxonomy_id:=v_rule.reward_taxonomy_id;
  new.reward_label:=v_tax.label;
  new.fulfillment_kind:=v_rule.fulfillment_kind;
  new.reward_type:=v_rule.fulfillment_kind;
  new.reward_value:=coalesce(
    v_rule.discount_percent,v_rule.credit_cents,0
  );
  new.reward_item:=v_rule.manual_item;
  new.reward_snapshot:=pg_catalog.jsonb_build_object(
    'legacy',false,
    'program_id',v_rule.program_id,
    'retention_program_version_id',v_rule.id,
    'config_version_id',v_rule.config_version_id,
    'name',v_rule.name,
    'goal_visits',v_rule.goal_visits,
    'period_days',v_rule.period_days,
    'starts_on',v_rule.starts_on,
    'period_start',v_period_start,
    'period_end',v_period_end,
    'reward_taxonomy_id',v_rule.reward_taxonomy_id,
    'reward_label',v_tax.label,
    'fulfillment_kind',v_rule.fulfillment_kind,
    'discount_percent',v_rule.discount_percent,
    'credit_cents',v_rule.credit_cents,
    'manual_item',v_rule.manual_item
  );
  return new;
end
$$;

--
-- Name: staff_can_see_branch(uuid, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.staff_can_see_branch(p_business uuid, p_branch uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$select app.can_see_branch(p_business,p_branch)$$;

--
-- Name: staff_free_for_appointment_v120_base(uuid, uuid, uuid, uuid, timestamp with time zone, timestamp with time zone, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.staff_free_for_appointment_v120_base(p_business uuid, p_staff uuid, p_branch uuid, p_service uuid, p_starts timestamp with time zone, p_ends timestamp with time zone, p_exclude_appointment uuid DEFAULT NULL::uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_timezone text;
  v_buffer_before integer := 0;
  v_buffer_after integer := 0;
  v_block_start timestamptz;
  v_block_end timestamptz;
  v_local_start timestamp;
  v_local_end timestamp;
  v_weekday smallint;
begin
  if p_business is null or p_staff is null or p_branch is null
     or p_starts is null or p_ends is null or p_ends <= p_starts then
    return false;
  end if;

  select b.timezone into v_timezone
    from public.branches b
   where b.id = p_branch and b.business_id = p_business and b.active;
  if not found then return false; end if;

  if p_service is not null then
    select service.buffer_before_min, service.buffer_after_min
      into v_buffer_before, v_buffer_after
      from public.services service
     where service.id = p_service and service.business_id = p_business and service.active;
    if not found then return false; end if;
  end if;

  v_block_start := p_starts - make_interval(mins => v_buffer_before);
  v_block_end := p_ends + make_interval(mins => v_buffer_after);
  v_local_start := v_block_start at time zone v_timezone;
  v_local_end := v_block_end at time zone v_timezone;
  v_weekday := extract(dow from v_local_start)::smallint;

  if v_local_end::date <> v_local_start::date then return false; end if;

  if not exists (
    select 1
      from public.staff s
      join public.staff_branches sb
        on sb.business_id = s.business_id and sb.staff_id = s.id
       and sb.branch_id = p_branch
     where s.id = p_staff and s.business_id = p_business and s.active
  ) then return false; end if;

  if p_service is not null
     and exists (
       select 1 from public.staff_services configured
        where configured.business_id = p_business
          and configured.service_id = p_service
     )
     and not exists (
       select 1 from public.staff_services qualified
        where qualified.business_id = p_business
          and qualified.staff_id = p_staff
          and qualified.service_id = p_service
     ) then return false; end if;

  if exists (
    select 1 from public.staff_off_days off_day
     where off_day.business_id = p_business and off_day.staff_id = p_staff
       and v_local_start::date between off_day.starts_on and off_day.ends_on
  ) then return false; end if;

  -- v383: a recurring weekly off day. Same refusal as a one-off, keyed on the SAME weekday
  -- expression (extract(dow ...), 0 = Sunday) the branch and staff hour rules above already use.
  if exists (
    select 1 from public.staff_recurring_off_days recurring
     where recurring.business_id = p_business and recurring.staff_id = p_staff
       and recurring.weekday = v_weekday
  ) then return false; end if;

  -- Legacy workspaces may not have configured opening hours. Once any row exists
  -- for this weekday, the service plus its buffers must fit inside an opening row.
  if exists (
    select 1 from public.branch_hours configured
     where configured.business_id = p_business and configured.branch_id = p_branch
       and configured.weekday = v_weekday
  ) and not exists (
    select 1 from public.branch_hours hours
     where hours.business_id = p_business and hours.branch_id = p_branch
       and hours.weekday = v_weekday
       and v_local_start::time >= hours.opens_at
       and v_local_end::time <= hours.closes_at
  ) then return false; end if;

  if exists (
    select 1 from public.branch_breaks pause
     where pause.business_id = p_business and pause.branch_id = p_branch
       and pause.weekday = v_weekday
       and pause.starts_at < v_local_end::time
       and pause.ends_at > v_local_start::time
  ) then return false; end if;

  -- Existing firms did not always configure staff hours. Preserve availability in that
  -- case, but once a weekday row exists the complete appointment must fit inside it.
  if exists (
    select 1 from public.staff_hours configured
     where configured.business_id = p_business and configured.staff_id = p_staff
       and configured.weekday = v_weekday
  ) and not exists (
    select 1 from public.staff_hours hours
     where hours.business_id = p_business and hours.staff_id = p_staff
       and hours.weekday = v_weekday
       and v_local_start::time >= hours.starts_at
       and v_local_end::time <= hours.ends_at
  ) then return false; end if;

  if exists (
    select 1
      from public.appointments existing
      left join public.services existing_service
        on existing_service.id = existing.service_id
       and existing_service.business_id = existing.business_id
     where existing.business_id = p_business
       and existing.staff_id = p_staff
       and existing.status = 'booked'
       and existing.id is distinct from p_exclude_appointment
       and (
         existing.starts_at - make_interval(mins => coalesce(existing_service.buffer_before_min,0))
       ) < v_block_end
       and (
         existing.ends_at + make_interval(mins => coalesce(existing_service.buffer_after_min,0))
       ) > v_block_start
  ) then return false; end if;

  return true;
end
$$;

--
-- Name: staff_free_for_appointment_v47(uuid, uuid, uuid, uuid, timestamp with time zone, timestamp with time zone, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.staff_free_for_appointment_v47(p_business uuid, p_staff uuid, p_branch uuid, p_service uuid, p_starts timestamp with time zone, p_ends timestamp with time zone, p_exclude_appointment uuid DEFAULT NULL::uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_buffer_before integer:=0;
  v_buffer_after integer:=0;
  v_timezone text;
  v_block_start timestamptz;
  v_block_end timestamptz;
  v_local_start timestamp;
  v_local_end timestamp;
  v_weekday smallint;
begin
  if not app.staff_free_for_appointment_v120_base(
    p_business,p_staff,p_branch,p_service,p_starts,p_ends,p_exclude_appointment
  ) then
    return false;
  end if;

  if p_service is not null then
    select service.buffer_before_min,service.buffer_after_min
      into v_buffer_before,v_buffer_after
      from public.services service
     where service.business_id=p_business and service.id=p_service
       and service.active;
    if not found then return false; end if;
  end if;

  select branch.timezone into v_timezone
    from public.branches branch
   where branch.business_id=p_business and branch.id=p_branch and branch.active;
  if not found then return false; end if;
  v_block_start:=p_starts-make_interval(mins=>coalesce(v_buffer_before,0));
  v_block_end:=p_ends+make_interval(mins=>coalesce(v_buffer_after,0));
  v_local_start:=v_block_start at time zone v_timezone;
  v_local_end:=v_block_end at time zone v_timezone;
  v_weekday:=extract(dow from v_local_start)::smallint;

  -- V118/V119 expose recorded hours as truth. Missing hours are closed, not
  -- legacy-available, and the complete service-plus-buffer interval must fit.
  if v_local_end::date<>v_local_start::date
     or not exists (
       select 1 from public.branch_hours hours
        where hours.business_id=p_business and hours.branch_id=p_branch
          and hours.weekday=v_weekday
          and v_local_start::time>=hours.opens_at
          and v_local_end::time<=hours.closes_at
     )
     or not exists (
       select 1 from public.staff_hours hours
        where hours.business_id=p_business and hours.staff_id=p_staff
          and hours.weekday=v_weekday
          and v_local_start::time>=hours.starts_at
          and v_local_end::time<=hours.ends_at
     ) then
    return false;
  end if;

  return not exists (
    select 1 from public.staff_blocked_times blocked
     where blocked.business_id=p_business and blocked.staff_id=p_staff
       and blocked.starts_at < v_block_end
       and blocked.ends_at > v_block_start
  );
end
$$;

--
-- Name: staff_module_mode_at_or_any_v117(uuid, uuid, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.staff_module_mode_at_or_any_v117(p_business uuid, p_branch uuid, p_module text) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  with candidate_modes as (
    select app.staff_module_mode_v94(
      p_business,p_branch,p_module
    ) access_mode
    where p_branch is not null
    union all
    select app.staff_module_mode_v94(
      p_business,null,p_module
    )
    where p_branch is null
      and not exists(
        select 1
        from public.branches branch
        where branch.business_id=p_business
          and branch.active
      )
    union all
    select app.staff_module_mode_v94(
      p_business,branch.id,p_module
    )
    from public.branches branch
    where p_branch is null
      and branch.business_id=p_business
      and branch.active
      and app.can_see_branch(p_business,branch.id)
  )
  select case
    when bool_or(access_mode='rw') then 'rw'
    when bool_or(access_mode='r') then 'r'
    else 'disabled'
  end
  from candidate_modes
$$;

--
-- Name: staff_module_mode_v94(uuid, uuid, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.staff_module_mode_v94(p_business uuid, p_branch uuid, p_module text) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_staff public.staff%rowtype;v_platform text;v_staff_mode text;
begin
  if not app.business_workspace_open_v94(p_business) then
    return 'disabled';
  end if;
  select * into v_staff from public.staff staff_row
   where staff_row.business_id=p_business and staff_row.user_id=auth.uid() and staff_row.active
   order by case when staff_row.role='owner' then 0 else 1 end, staff_row.created_at, staff_row.id
   limit 1;
  if not found then return 'disabled';end if;
  if p_branch is not null and not app.can_see_branch(p_business,p_branch) then
    return 'disabled';
  end if;
  select resolved.mode into v_platform
    from app.effective_platform_module_mode_v94(p_business,p_branch,p_module) resolved;
  if coalesce(v_platform,'disabled')='disabled' then return 'disabled';end if;
  if v_staff.role='owner' then return v_platform;
  elsif v_staff.module_perms is not null then
    v_staff_mode:=coalesce(v_staff.module_perms->>p_module,'disabled');
  elsif v_staff.modules is null or p_module=any(v_staff.modules) then v_staff_mode:='rw';
  else v_staff_mode:='disabled';
  end if;
  if v_staff_mode='disabled' then return 'disabled';end if;
  if v_platform='r' or v_staff_mode='r' then return 'r';end if;
  return 'rw';
end
$$;

--
-- Name: staff_module_perms(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.staff_module_perms(p_business uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  select app.staff_module_perms_at_v115(p_business,null)
$$;

--
-- Name: staff_module_perms_at_v115(uuid, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.staff_module_perms_at_v115(p_business uuid, p_branch uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  /* v246: body unchanged from v233 — only the language wrapper differs, so the
     plan is cached per connection instead of rebuilt on every call. */
  return (
  with actor_staff as (
    select staff_row.*
    from public.staff staff_row
    where staff_row.business_id=p_business
      and staff_row.user_id=auth.uid()
      and staff_row.active
    order by case when staff_row.role='owner' then 0 else 1 end,
      staff_row.created_at,staff_row.id
    limit 1
  ),
  workspace as (
    select app.business_workspace_open_v94(p_business) as is_open
  ),
  module_keys as (
    select unnest(coalesce(business.enabled_modules,'{}'::text[])) module_key
    from public.businesses business
    where business.id=p_business
    union
    select override_row.module_key
    from public.platform_module_overrides_v94 override_row
    where override_row.business_id=p_business
  ),
  branch_scopes as (
    select p_branch as branch_id,
      app.can_see_branch(p_business,p_branch) as visible
    where p_branch is not null
    union all
    select branch.id, app.can_see_branch(p_business,branch.id)
    from public.branches branch
    where p_branch is null
      and branch.business_id=p_business
      and branch.active
    union all
    select null::uuid, true
    where p_branch is null
      and not exists(
        select 1 from public.branches branch
        where branch.business_id=p_business
          and branch.active
      )
  ),
  scoped as (
    select module_keys.module_key, branch_scopes.branch_id, branch_scopes.visible,
      case when module_keys.module_key='customerintel' then 'disabled'
      else coalesce(
        (select override_row.mode
           from public.platform_module_overrides_v94 override_row
          where override_row.business_id=p_business
            and override_row.branch_scope=branch_scopes.branch_id
            and override_row.module_key=module_keys.module_key
            and override_row.mode<>'inherit'),
        (select override_row.mode
           from public.platform_module_overrides_v94 override_row
          where override_row.business_id=p_business
            and override_row.branch_scope is null
            and override_row.module_key=module_keys.module_key
            and override_row.mode<>'inherit'),
        (select case when module_keys.module_key=any(business.enabled_modules)
                  then 'rw' else 'disabled' end
           from public.businesses business
          where business.id=p_business)
      ) end as platform_mode
    from module_keys
    cross join branch_scopes
  ),
  scoped_modes as (
    select scoped.module_key,
      case
        when not coalesce(workspace.is_open,false) then 'disabled'
        when scoped.branch_id is not null
             and not coalesce(scoped.visible,false) then 'disabled'
        when coalesce(scoped.platform_mode,'disabled')='disabled' then 'disabled'
        when actor_staff.role='owner' then scoped.platform_mode
        when staff_mode.mode='disabled' then 'disabled'
        when scoped.platform_mode='r' or staff_mode.mode='r' then 'r'
        else 'rw'
      end as access_mode,
      actor_staff.role
    from scoped
    cross join workspace
    cross join actor_staff
    cross join lateral (
      select case
        when actor_staff.module_perms is not null
          then coalesce(actor_staff.module_perms->>scoped.module_key,'disabled')
        when actor_staff.modules is null
          or scoped.module_key=any(actor_staff.modules) then 'rw'
        else 'disabled'
      end as mode
    ) staff_mode
  ),
  resolved as (
    select scoped_modes.module_key,
      case
        when bool_or(scoped_modes.access_mode='rw') then 'rw'
        when bool_or(scoped_modes.access_mode='r') then 'r'
        else 'disabled'
      end as access_mode,
      min(scoped_modes.role) as role
    from scoped_modes
    group by scoped_modes.module_key
  )
  select coalesce(
    jsonb_object_agg(resolved.module_key,resolved.access_mode)
      filter(where resolved.access_mode in ('r','rw')
        and (
          resolved.role='owner'
          or resolved.module_key not in ('branches','settings','setup')
        )
        and (
          resolved.module_key not in ('expenses','pnl')
          or 'view_finance'=any(app.role_perms(resolved.role))
        )
      ),
    '{}'::jsonb
  )
  from resolved
  );
end
$$;

--
-- Name: FUNCTION staff_module_perms_at_v115(p_business uuid, p_branch uuid); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.staff_module_perms_at_v115(p_business uuid, p_branch uuid) IS 'v233 set-based module resolver; v246 wraps the identical SELECT in plpgsql so the plan is cached per connection instead of being rebuilt on every call (language sql bodies replan each invocation, 5-14ms on this instance). Decision rules unchanged since the v233 differential verification.';

--
-- Name: staff_modules(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.staff_modules(p_business uuid) RETURNS text[]
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  select coalesce(array_agg(k order by k), array[]::text[])
    from jsonb_object_keys(app.staff_module_perms(p_business)) as keys(k)
$$;

--
-- Name: stamp_config_version(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.stamp_config_version() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_business uuid;
  v_version uuid;
  v_scope text;
  v_reversal_of uuid;
  v_sale_id uuid;
begin
  v_business:=new.business_id;
  perform 1 from public.businesses where id=v_business for share;
  -- NEW has a different composite type for every table using this trigger.
  -- Read table-specific keys through jsonb so missing fields remain NULL.
  if tg_table_name='sales' then
    v_reversal_of:=nullif(to_jsonb(new)->>'reversal_of','')::uuid;
  elsif tg_table_name in ('points_ledger','points_batches','credit_ledger') then
    v_sale_id:=nullif(to_jsonb(new)->>'sale_id','')::uuid;
  end if;
  if v_reversal_of is not null then
    select config_version_id into v_version from public.sales
     where id=v_reversal_of and business_id=v_business;
    if not found then raise exception 'reversal source sale not found'; end if;
  elsif v_sale_id is not null then
    select config_version_id into v_version from public.sales
     where id=v_sale_id and business_id=v_business;
    if not found then raise exception 'linked sale not found for config version'; end if;
  elsif tg_table_name in ('points_ledger','credit_ledger') then
    v_scope:=case when tg_table_name='points_ledger'
      then nullif(current_setting('app.points_ledger_write_scope',true),'')
      else nullif(current_setting('app.credit_ledger_write_scope',true),'') end;
    if v_scope='redemption_reversal' then
      v_version:=nullif(current_setting('app.redemption_reversal_config_version_id',true),'')::uuid;
      if v_version is null then raise exception 'redemption reversal config provenance is missing'; end if;
    else v_version:=app.active_config_version(v_business);
    end if;
  else v_version:=app.active_config_version(v_business);
  end if;
  if new.config_version_id is null then new.config_version_id:=v_version; end if;
  if new.config_version_id is distinct from v_version then
    raise exception 'event config version does not match its immutable source' using errcode='check_violation';
  end if;
  return new;
end $$;

--
-- Name: stamp_cycle_version_v416(uuid, uuid, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.stamp_cycle_version_v416(p_business uuid, p_client uuid, p_programme uuid) RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_last_close timestamptz;
  v_started timestamptz;
  v_version uuid;
begin
  if p_business is null or p_client is null or p_programme is null then
    return (select b.active_config_version_id from public.businesses b where b.id = p_business);
  end if;

  select max(sc.closed_at) into v_last_close
    from public.stamp_cycles sc
   where sc.business_id = p_business and sc.client_id = p_client
     and sc.programme_id = p_programme;

  /* The first stamp of the CURRENT card: the earliest positive ledger row for this programme
     since the last card closed. Only positive rows count — a correction that removes stamps must
     not be mistaken for the moment a card was started. */
  select min(pl.created_at) into v_started
    from public.points_ledger pl
   where pl.business_id = p_business and pl.client_id = p_client
     and pl.programme_id = p_programme and pl.points > 0
     and (v_last_close is null or pl.created_at > v_last_close);

  if v_started is null then
    -- Nothing collected on this card yet: no promise has been made, so the newest setup applies.
    return (select b.active_config_version_id from public.businesses b where b.id = p_business);
  end if;

  select fcv.id into v_version
    from public.firm_config_versions fcv
   where fcv.business_id = p_business
     and fcv.published_at is not null
     and fcv.published_at <= v_started
   order by fcv.published_at desc
   limit 1;

  /* A card started before this firm ever published one falls back to the active version rather
     than to nothing — a customer must never be left with no card at all. */
  return coalesce(v_version,
    (select b.active_config_version_id from public.businesses b where b.id = p_business));
end $$;

--
-- Name: FUNCTION stamp_cycle_version_v416(p_business uuid, p_client uuid, p_programme uuid); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.stamp_cycle_version_v416(p_business uuid, p_client uuid, p_programme uuid) IS 'v416: the published configuration governing a client''s OPEN stamp card - the version in force when its first stamp landed, or the active version when the card is empty. Read by app.stamp_progress_v323, public.customer_get_stamp_card_v323 and app.redeem_reward_core so all three agree about which card a customer is actually filling.';

--
-- Name: stamp_progress_v323(uuid, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.stamp_progress_v323(p_business uuid, p_client uuid) RETURNS TABLE(programme_id uuid, programme_active boolean, running_since timestamp with time zone, paused_since timestamp with time zone, slots integer, net_stamps integer, closed_slots integer, filled integer, cycle_index integer, ready boolean, pot_migrated boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  select spine.id,
         spine.active,
         spine.activated_at,
         spine.deactivated_at,
         target.stamp_target,
         coalesce(led.net, 0)::integer,
         coalesce(cyc.closed, 0)::integer,
         greatest(coalesce(led.net, 0) - coalesce(cyc.closed, 0), 0)::integer,
         coalesce(cyc.cycles, 0)::integer,
         target.stamp_target is not null
           and target.stamp_target > 0
           and greatest(coalesce(led.net, 0) - coalesce(cyc.closed, 0), 0) >= target.stamp_target,
         exists (select 1 from public.programme_pot_migrations m
                  where m.business_id = p_business and m.from_programme_id = spine.id)
    from public.business_programmes spine
    cross join lateral (
      select coalesce(
        (select lpv.stamp_target from public.loyalty_program_versions lpv
          where lpv.config_version_id
                = app.stamp_cycle_version_v416(p_business, p_client, spine.id)),
        (select prog.stamp_target from public.loyalty_programs prog
          where prog.business_id = p_business order by prog.id limit 1)
      ) as stamp_target
    ) target
    left join lateral (
      select coalesce(sum(pl.points), 0) as net
        from public.points_ledger pl
       where pl.business_id = p_business and pl.client_id = p_client
         and pl.programme_id = spine.id
    ) led on true
    left join lateral (
      select coalesce(sum(sc.slots), 0) as closed, count(*)::integer as cycles
        from public.stamp_cycles sc
       where sc.business_id = p_business and sc.client_id = p_client
         and sc.programme_id = spine.id
    ) cyc on true
   where spine.business_id = p_business and spine.kind = 'stamps'
$$;

--
-- Name: FUNCTION stamp_progress_v323(p_business uuid, p_client uuid); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.stamp_progress_v323(p_business uuid, p_client uuid) IS 'v323 (R5): the stamp CARD, computed rather than stored. filled = lifetime stamps on the stamps programme minus the slots of every CLOSED cycle, clamped at zero. Zero rows when the firm has no stamps programme. Internal: nothing browser-reachable may call it directly.';

--
-- Name: stripe_business_v77(jsonb); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.stripe_business_v77(p_payload jsonb) RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $_$
declare
  v_object jsonb := p_payload #> '{data,object}';
  v_candidate text;
  v_customer text;
  v_subscription text;
  v_invoice text;
  v_payment_intent text;
  v_charge text;
  v_business uuid;
begin
  v_candidate := coalesce(
    v_object #>> '{metadata,business_id}',
    v_object #>> '{subscription_details,metadata,business_id}',
    v_object #>> '{parent,subscription_details,metadata,business_id}',
    v_object ->> 'client_reference_id'
  );
  if v_candidate ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
     and exists (select 1 from public.businesses where id = v_candidate::uuid) then
    return v_candidate::uuid;
  end if;

  v_customer := case
    when jsonb_typeof(v_object->'customer') = 'string' then v_object->>'customer'
    else v_object#>>'{customer,id}'
  end;
  select business_id into v_business
    from public.billing_provider_customers
   where provider_customer_id = v_customer;
  if found then return v_business; end if;

  v_subscription := coalesce(
    case when jsonb_typeof(v_object->'subscription') = 'string'
         then v_object->>'subscription' else v_object#>>'{subscription,id}' end,
    v_object#>>'{parent,subscription_details,subscription}'
  );
  select business_id into v_business
    from public.billing_provider_subscriptions
   where provider_subscription_id = v_subscription;
  if found then return v_business; end if;

  v_invoice := case
    when jsonb_typeof(v_object->'invoice') = 'string' then v_object->>'invoice'
    else v_object#>>'{invoice,id}'
  end;
  select business_id into v_business
    from public.billing_provider_invoices
   where provider_invoice_id = v_invoice;
  if found then return v_business; end if;

  v_payment_intent := case
    when jsonb_typeof(v_object->'payment_intent') = 'string'
      then v_object->>'payment_intent'
    else v_object#>>'{payment_intent,id}'
  end;
  select business_id into v_business
    from public.billing_provider_invoices
   where provider_payment_intent_id = v_payment_intent
   order by paid_at desc nulls last
   limit 1;
  if found then return v_business; end if;

  v_charge := case
    when jsonb_typeof(v_object->'charge') = 'string' then v_object->>'charge'
    else v_object#>>'{charge,id}'
  end;
  select business_id into v_business
    from public.billing_payment_attempts
   where provider_charge_id = v_charge
   order by occurred_at desc
   limit 1;
  if found then return v_business; end if;

  return null;
end
$_$;

--
-- Name: stripe_cadence_v77(text, integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.stripe_cadence_v77(p_interval text, p_count integer) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
  select case
    when p_interval = 'month' and p_count = 1 then 'monthly'
    when p_interval = 'month' and p_count = 3 then 'quarterly'
    when p_interval = 'month' and p_count = 6 then 'half_yearly'
    when (p_interval = 'year' and p_count = 1)
      or (p_interval = 'month' and p_count = 12) then 'annual'
    else null
  end
$$;

--
-- Name: stripe_epoch_v77(jsonb); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.stripe_epoch_v77(p_value jsonb) RETURNS timestamp with time zone
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
  select case
    when p_value is null or jsonb_typeof(p_value) <> 'number' then null
    when (p_value #>> '{}')::numeric < 0 then null
    else to_timestamp((p_value #>> '{}')::double precision)
  end
$$;

--
-- Name: stripe_event_rank_v77(text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.stripe_event_rank_v77(p_type text) RETURNS smallint
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
  select case p_type
    when 'checkout.session.completed' then 10
    when 'customer.subscription.created' then 20
    when 'customer.subscription.updated' then 30
    when 'customer.subscription.deleted' then 90
    when 'invoice.finalized' then 20
    when 'invoice.payment_action_required' then 35
    when 'invoice.payment_failed' then 40
    when 'invoice.marked_uncollectible' then 70
    when 'invoice.voided' then 80
    when 'invoice.paid' then 100
    when 'refund.created' then 110
    when 'charge.dispute.created' then 120
    else 0
  end::smallint
$$;

--
-- Name: studio_rule_emergency_pauses_guard(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.studio_rule_emergency_pauses_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if tg_op = 'DELETE' then
    raise exception 'studio_rule_emergency_pauses is append-only' using errcode = 'restrict_violation';
  end if;
  if old.lifted_at is not null then
    raise exception 'emergency pause is already lifted (write-once)' using errcode = 'restrict_violation';
  end if;
  if new.business_id is distinct from old.business_id
     or new.rule_id is distinct from old.rule_id
     or new.actor is distinct from old.actor
     or new.reason is distinct from old.reason
     or new.paused_at is distinct from old.paused_at
     or new.created_at is distinct from old.created_at then
    raise exception 'emergency pause identity is immutable' using errcode = 'restrict_violation';
  end if;
  if new.lifted_at is null or new.lifted_by is null then
    raise exception 'lifting an emergency pause requires lifted_at and lifted_by' using errcode = 'restrict_violation';
  end if;
  return new;
end $$;

--
-- Name: suggest_appointment_reschedule_v48(uuid, uuid, uuid, uuid, timestamp with time zone, integer, integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.suggest_appointment_reschedule_v48(p_business uuid, p_appointment uuid, p_branch uuid, p_service uuid, p_starts timestamp with time zone, p_duration_minutes integer, p_limit integer DEFAULT 5) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_now timestamptz := statement_timestamp();
  v_ends timestamptz := p_starts + make_interval(mins=>p_duration_minutes);
  v_timezone text;
  v_day_end timestamptz;
  v_candidate timestamptz;
  v_available jsonb := '[]'::jsonb;
  v_next jsonb := '[]'::jsonb;
  v_staff record;
begin
  select branch.timezone into v_timezone from public.branches branch
   where branch.id=p_branch and branch.business_id=p_business and branch.active;
  if not found then raise exception 'active branch not found' using errcode='22023'; end if;
  v_day_end:=(((p_starts at time zone v_timezone)::date+1)::timestamp at time zone v_timezone);

  select coalesce(jsonb_agg(jsonb_build_object(
           'staff_id',ranked.id,'staff_name',ranked.full_name,
           'calendar_color',ranked.calendar_color,'recent_appointments',ranked.recent_appointments
         ) order by ranked.recent_appointments,ranked.last_assigned nulls first,
                    ranked.full_name,ranked.id),'[]'::jsonb)
    into v_available
    from (
      select staff.id,staff.full_name,staff.calendar_color,
             (select count(*)::integer from public.appointments recent
               where recent.business_id=p_business and recent.staff_id=staff.id
                 and recent.status in ('booked','completed')
                 and recent.starts_at>=v_now-interval '30 days') recent_appointments,
             (select max(recent.created_at) from public.appointments recent
               where recent.business_id=p_business and recent.staff_id=staff.id
                 and recent.status in ('booked','completed')) last_assigned
        from public.staff staff
        join public.staff_branches staff_branch
          on staff_branch.business_id=staff.business_id and staff_branch.staff_id=staff.id
         and staff_branch.branch_id=p_branch
       where staff.business_id=p_business and staff.active
         and app.staff_free_for_appointment_v47(
           p_business,staff.id,p_branch,p_service,p_starts,v_ends,p_appointment)
       order by recent_appointments,last_assigned nulls first,staff.full_name,staff.id
       limit p_limit
    ) ranked;

  v_candidate:=p_starts+interval '15 minutes';
  while v_candidate+make_interval(mins=>p_duration_minutes)<=v_day_end
        and jsonb_array_length(v_next)<2 loop
    select staff.id,staff.full_name,staff.calendar_color into v_staff
      from public.staff staff
      join public.staff_branches staff_branch
        on staff_branch.business_id=staff.business_id and staff_branch.staff_id=staff.id
       and staff_branch.branch_id=p_branch
     where staff.business_id=p_business and staff.active
       and app.staff_free_for_appointment_v47(
         p_business,staff.id,p_branch,p_service,v_candidate,
         v_candidate+make_interval(mins=>p_duration_minutes),p_appointment)
     order by
       (select count(*) from public.appointments recent
         where recent.business_id=p_business and recent.staff_id=staff.id
           and recent.status in ('booked','completed')
           and recent.starts_at>=v_now-interval '30 days'),
       (select max(recent.created_at) from public.appointments recent
         where recent.business_id=p_business and recent.staff_id=staff.id
           and recent.status in ('booked','completed')) nulls first,
       staff.full_name,staff.id
     limit 1;
    if found then
      v_next:=v_next||jsonb_build_array(jsonb_build_object(
        'starts_at',v_candidate,
        'ends_at',v_candidate+make_interval(mins=>p_duration_minutes),
        'staff_id',v_staff.id,'staff_name',v_staff.full_name,
        'calendar_color',v_staff.calendar_color
      ));
    end if;
    v_candidate:=v_candidate+interval '15 minutes';
  end loop;
  return jsonb_build_object(
    'requested_starts_at',p_starts,'requested_ends_at',v_ends,
    'available_staff',v_available,'recommended_staff_id',v_available#>>'{0,staff_id}',
    'next_best_slots',v_next
  );
end
$$;

--
-- Name: sv_allocate_spend(uuid, uuid, integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.sv_allocate_spend(p_business uuid, p_account uuid, p_spend_cents integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_total_paid bigint;
  v_total_bonus bigint;
  v_total bigint;
  v_bonus_draw bigint;
  v_paid_draw bigint;
  v_plan jsonb := '[]'::jsonb;
  v_left bigint;
  v_take bigint;
  r record;
begin
  if p_spend_cents is null or p_spend_cents < 1 then
    return jsonb_build_object('ok', false, 'reason', 'spend must be a whole number of at least 1 cent');
  end if;

  select coalesce(sum(case when l.class = 'paid'  then m.cents else 0 end), 0),
         coalesce(sum(case when l.class = 'bonus' then m.cents else 0 end), 0)
    into v_total_paid, v_total_bonus
    from public.sv_lot_movements m
    join public.sv_lots l on l.id = m.lot_id and l.business_id = m.business_id
   where m.business_id = p_business and m.account_id = p_account;
  v_total := v_total_paid + v_total_bonus;

  if p_spend_cents > v_total then
    return jsonb_build_object('ok', false, 'reason', 'insufficient stored value',
      'total_paid_cents', v_total_paid, 'total_bonus_cents', v_total_bonus, 'total_cents', v_total);
  end if;

  -- PS-0 §3: floor on bonus; paid keeps the remainder cent. total > 0 here (spend >= 1 <= total).
  v_bonus_draw := (p_spend_cents::bigint * v_total_bonus) / v_total;
  v_paid_draw := p_spend_cents - v_bonus_draw;

  -- paid class FEFO
  v_left := v_paid_draw;
  for r in
    select l.id as lot_id, app.sv_lot_remaining(l.id) as remaining
      from public.sv_lots l
     where l.business_id = p_business and l.account_id = p_account and l.class = 'paid'
     order by l.expiry_key asc nulls last, l.earned_seq asc, l.id asc
  loop
    exit when v_left <= 0;
    if r.remaining <= 0 then continue; end if;
    v_take := least(v_left, r.remaining);
    v_plan := v_plan || jsonb_build_array(jsonb_build_object(
      'lot_id', r.lot_id, 'class', 'paid', 'kind', 'spend', 'cents', (-v_take)::int));
    v_left := v_left - v_take;
  end loop;
  if v_left <> 0 then
    return jsonb_build_object('ok', false, 'reason', 'could not fully allocate the paid class');
  end if;

  -- bonus class FEFO
  v_left := v_bonus_draw;
  for r in
    select l.id as lot_id, app.sv_lot_remaining(l.id) as remaining
      from public.sv_lots l
     where l.business_id = p_business and l.account_id = p_account and l.class = 'bonus'
     order by l.expiry_key asc nulls last, l.earned_seq asc, l.id asc
  loop
    exit when v_left <= 0;
    if r.remaining <= 0 then continue; end if;
    v_take := least(v_left, r.remaining);
    v_plan := v_plan || jsonb_build_array(jsonb_build_object(
      'lot_id', r.lot_id, 'class', 'bonus', 'kind', 'spend', 'cents', (-v_take)::int));
    v_left := v_left - v_take;
  end loop;
  if v_left <> 0 then
    return jsonb_build_object('ok', false, 'reason', 'could not fully allocate the bonus class');
  end if;

  return jsonb_build_object(
    'ok', true,
    'paid_draw', v_paid_draw::int,
    'bonus_draw', v_bonus_draw::int,
    'total_paid_cents', v_total_paid::int,
    'total_bonus_cents', v_total_bonus::int,
    'total_cents', v_total::int,
    'plan', v_plan);
end $$;

--
-- Name: sv_apply_authority_state(uuid, text, text, text, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.sv_apply_authority_state(p_business uuid, p_asset text, p_state text, p_reason text, p_actor uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_asset text := coalesce(p_asset, 'stored_value');
  v_reason text := btrim(coalesce(p_reason, ''));
  v_current text;
begin
  if p_state is null or p_state not in ('unbuilt', 'shadow_testing', 'reconciliation_blocked') then
    raise exception 'stored-value authority state % is not settable in PS-2A (cutover states are unreachable)', p_state
      using errcode = '22023';
  end if;
  if char_length(v_reason) < 3 then
    raise exception 'a stored-value authority transition requires a reason of at least 3 characters' using errcode = '22023';
  end if;

  select state into v_current from public.sv_authority
   where business_id = p_business and asset = v_asset
   for update;
  if v_current is null then
    raise exception 'stored-value authority is not initialised for this business' using errcode = '22023';
  end if;

  -- Idempotent no-op: same state -> no write, no audit.
  if v_current = p_state then
    return v_current;
  end if;

  -- v69 §5 (ADDED): 'live' is TERMINAL on this path. Cutover is deliberately NOT reversible by
  -- RPC; the emergency control is public.sv_pause, which keeps working on a live business. This
  -- is also what stops the newly-scheduled daily reconciliation from silently driving a LIVE
  -- tenant to 'reconciliation_blocked' and stranding issued customer value.
  if v_current = 'live' then
    raise exception 'sv_live_not_reversible: stored value is live for this business and cannot be moved out of live (pause is the emergency control)'
      using errcode = '22023';
  end if;

  -- Blocked-lock (contract §1): a business with open discrepancies cannot leave
  -- 'reconciliation_blocked' except back to 'shadow_testing' (never forward). Forward states
  -- do not exist in PS-2A, so this concretely forbids blocked -> unbuilt.
  if v_current = 'reconciliation_blocked' and p_state <> 'shadow_testing' then
    raise exception 'stored-value authority is reconciliation_blocked; it may only return to shadow_testing' using errcode = '22023';
  end if;

  update public.sv_authority
     set state = p_state, updated_at = now(), updated_by = p_actor
   where business_id = p_business and asset = v_asset;

  insert into public.audit_log(business_id, actor, action, entity, entity_id, detail)
  values (p_business, p_actor, 'SV_AUTHORITY_STATE_SET', 'sv_authority', p_business, jsonb_build_object(
    'asset', v_asset, 'from', v_current, 'to', p_state, 'reason', v_reason));

  return p_state;
end $$;

--
-- Name: sv_authority_guard(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.sv_authority_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if tg_op = 'DELETE' then
    raise exception 'sv_authority is not deletable (history survives)' using errcode = 'restrict_violation';
  end if;
  -- 'ready_for_cutover' remains unreachable: readiness is DERIVED evidence (see
  -- app.sv_cutover_readiness), never a stored state, so nothing needs to set it.
  if new.state = 'ready_for_cutover' then
    raise exception 'sv_authority cannot transition to % in PS-2A (cutover is unreachable until a future authorized phase)', new.state
      using errcode = 'restrict_violation';
  end if;
  -- v69 TRIPWIRE: 'live' is reachable only for an UPDATE authorized in THIS transaction by a
  -- public.sv_cutover_events row (written solely by public.sv_cutover_business). A business is
  -- never born live, and ordinary state-setting can still never reach live.
  if new.state = 'live' then
    if tg_op <> 'UPDATE' then
      raise exception 'sv_authority cannot be created live; cutover is an explicit, evidence-gated transition'
        using errcode = 'restrict_violation';
    end if;
    if not exists (
      select 1 from public.sv_cutover_events e
       where e.business_id = new.business_id
         and e.asset = new.asset
         and e.new_state = 'live'
         and e.authorized_txid = pg_catalog.pg_current_xact_id_if_assigned()::text::bigint)
    then
      raise exception 'sv_authority can only reach live through public.sv_cutover_business (v69 cutover tripwire)'
        using errcode = 'restrict_violation';
    end if;
  end if;
  return new;
end $$;

--
-- Name: sv_automation_begin(text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.sv_automation_begin(p_job text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_id uuid;
begin
  insert into public.sv_automation_runs(job_name, run_txid)
  values (p_job, pg_catalog.pg_current_xact_id()::text::bigint)
  returning id into v_id;
  return v_id;
end $$;

--
-- Name: sv_automation_context(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.sv_automation_context() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  select exists (
    select 1 from public.sv_automation_runs r
     where r.run_txid = pg_catalog.pg_current_xact_id_if_assigned()::text::bigint
       and r.finished_at is null);
$$;

--
-- Name: sv_automation_finish(uuid, jsonb); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.sv_automation_finish(p_run uuid, p_summary jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  update public.sv_automation_runs
     set finished_at = now(), summary = coalesce(p_summary, '{}'::jsonb)
   where id = p_run;
end $$;

--
-- Name: sv_automation_runs_guard(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.sv_automation_runs_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if tg_op = 'DELETE' then
    raise exception 'sv_automation_runs is append-only' using errcode = 'restrict_violation';
  end if;
  if old.finished_at is not null then
    raise exception 'this stored-value automation run is already finished (write-once)' using errcode = 'restrict_violation';
  end if;
  if new.id is distinct from old.id
     or new.job_name is distinct from old.job_name
     or new.run_txid is distinct from old.run_txid
     or new.started_at is distinct from old.started_at then
    raise exception 'stored-value automation run identity is immutable' using errcode = 'restrict_violation';
  end if;
  if new.finished_at is null or new.summary is null then
    raise exception 'finishing a stored-value automation run requires finished_at and summary' using errcode = 'restrict_violation';
  end if;
  return new;
end $$;

--
-- Name: sv_automation_status(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.sv_automation_status() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $_$
declare
  v_required text[] := array['frenly-sv-expiry', 'frenly-sv-tender-release', 'frenly-sv-reconciliation'];
  v_found text[] := '{}'::text[];
  v_missing text[];
  v_has_active boolean;
begin
  if to_regclass('cron.job') is null then
    return jsonb_build_object(
      'required', to_jsonb(v_required), 'scheduled', '[]'::jsonb,
      'missing', to_jsonb(v_required), 'ok', false, 'basis', 'cron.job is absent');
  end if;
  select exists (
    select 1 from pg_attribute a
     where a.attrelid = 'cron.job'::regclass and a.attname = 'active'
       and a.attnum > 0 and not a.attisdropped)
    into v_has_active;
  execute format(
    'select coalesce(array_agg(distinct j.jobname), ''{}''::text[]) from cron.job j where j.jobname = any($1)%s',
    case when v_has_active then ' and j.active' else '' end)
    into v_found using v_required;
  select coalesce(array_agg(m order by m), '{}'::text[]) into v_missing
    from (select unnest(v_required) except select unnest(v_found)) s(m);
  return jsonb_build_object(
    'required', to_jsonb(v_required),
    'scheduled', to_jsonb((select coalesce(array_agg(f order by f), '{}'::text[]) from unnest(v_found) s(f))),
    'missing', to_jsonb(v_missing),
    'ok', (coalesce(array_length(v_missing, 1), 0) = 0),
    'basis', case when v_has_active then 'cron.job.active' else 'cron.job presence (no active column)' end);
end $_$;

--
-- Name: sv_available_balance(uuid, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.sv_available_balance(p_business uuid, p_account uuid) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  select (
    coalesce((select sum(m.cents) from public.sv_lot_movements m
               where m.business_id = p_business and m.account_id = p_account), 0)
    - coalesce((select sum(r.amount_cents) from public.sv_reservations r
                 where r.business_id = p_business and r.account_id = p_account and r.status = 'active'), 0)
  )::integer
$$;

--
-- Name: sv_canon_text_array(jsonb); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.sv_canon_text_array(v jsonb) RETURNS text[]
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare r text[];
begin
  if v is null or jsonb_typeof(v) = 'null' then return null; end if;
  if jsonb_typeof(v) <> 'array' then raise exception 'expected a JSON array of text' using errcode = '22023'; end if;
  select array(select distinct btrim(e) from jsonb_array_elements_text(v) e where btrim(e) <> '' order by btrim(e)) into r;
  return r;
end $$;

--
-- Name: sv_canon_uuid_array(jsonb); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.sv_canon_uuid_array(v jsonb) RETURNS uuid[]
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare r uuid[];
begin
  if v is null or jsonb_typeof(v) = 'null' then return null; end if;
  if jsonb_typeof(v) <> 'array' then raise exception 'expected a JSON array of ids' using errcode = '22023'; end if;
  begin
    select array(select distinct e::uuid from jsonb_array_elements_text(v) e order by e::uuid) into r;
  exception when others then raise exception 'eligibility ids must be valid UUIDs' using errcode = '22023'; end;
  return r;
end $$;

--
-- Name: sv_cash_collected_cents(uuid, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.sv_cash_collected_cents(p_business uuid, p_topup_operation uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_amount integer;
begin
  select amount_cents into v_amount from public.sv_topup_payments
   where business_id = p_business and operation_id = p_topup_operation;
  if v_amount is null then
    return jsonb_build_object('collected_cents', null, 'basis', 'none');
  end if;
  return jsonb_build_object('collected_cents', v_amount, 'basis', 'payment_evidence');
end $$;

--
-- Name: sv_cash_refunded_cents(uuid, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.sv_cash_refunded_cents(p_business uuid, p_topup_operation uuid) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  select coalesce(-sum(m.cents), 0)::integer
    from public.sv_lot_movements m
    join public.sv_lots l on l.id = m.lot_id and l.business_id = m.business_id
   where m.business_id = p_business and l.operation_id = p_topup_operation
     and l.class = 'paid' and m.kind = 'refund'
$$;

--
-- Name: sv_chargeback_plan(uuid, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.sv_chargeback_plan(p_business uuid, p_topup_operation uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_paid_lot uuid;
  v_bonus_lot uuid;
  v_account uuid;
  v_paid_rem bigint;
  v_bonus_rem bigint;
  v_spent bigint;
  v_reversed bigint;
  v_refunded bigint;
  v_bad_debt bigint;
  v_plan jsonb := '[]'::jsonb;
begin
  select id, account_id into v_paid_lot, v_account from public.sv_lots
   where business_id = p_business and operation_id = p_topup_operation and class = 'paid'
   order by earned_seq asc, id asc limit 1;
  if v_paid_lot is null then
    return jsonb_build_object('ok', false, 'reason', 'operation has no paid lot to charge back');
  end if;
  select id into v_bonus_lot from public.sv_lots
   where business_id = p_business and operation_id = p_topup_operation and class = 'bonus'
   order by earned_seq asc, id asc limit 1;

  v_paid_rem := app.sv_lot_remaining(v_paid_lot);
  v_bonus_rem := coalesce(app.sv_lot_remaining(v_bonus_lot), 0);

  -- PS-0 §6: bad debt is the net PAID value already delivered as goods; the refund total is the
  -- contract §3 double-loss figure and is reported ALONGSIDE, never netted into, the bad debt.
  select coalesce(sum(case when m.kind = 'spend' then -m.cents else 0 end), 0),
         coalesce(sum(case when m.kind = 'reversal' then m.cents else 0 end), 0),
         coalesce(sum(case when m.kind = 'refund' then -m.cents else 0 end), 0)
    into v_spent, v_reversed, v_refunded
    from public.sv_lot_movements m
   where m.business_id = p_business and m.lot_id = v_paid_lot;
  v_bad_debt := greatest(v_spent - v_reversed, 0);

  if v_paid_rem > 0 then
    v_plan := v_plan || jsonb_build_array(jsonb_build_object(
      'lot_id', v_paid_lot, 'class', 'paid', 'kind', 'correction', 'cents', (-v_paid_rem)::int));
  end if;
  if v_bonus_rem > 0 and v_bonus_lot is not null then
    v_plan := v_plan || jsonb_build_array(jsonb_build_object(
      'lot_id', v_bonus_lot, 'class', 'bonus', 'kind', 'correction', 'cents', (-v_bonus_rem)::int));
  end if;
  -- The zero-balance-effect loss record (PS-0 §2 footnote; v61 CHECK forces cents = 0).
  v_plan := v_plan || jsonb_build_array(jsonb_build_object(
    'lot_id', v_paid_lot, 'class', 'paid', 'kind', 'bad_debt', 'cents', 0));

  return jsonb_build_object(
    'ok', true,
    'account_id', v_account,
    'paid_lot', v_paid_lot,
    'bonus_lot', v_bonus_lot,
    'paid_remaining_cents', v_paid_rem::int,
    'bonus_remaining_cents', v_bonus_rem::int,
    'void_paid_cents', v_paid_rem::int,
    'void_bonus_cents', v_bonus_rem::int,
    'bad_debt_cents', v_bad_debt::int,
    'cash_already_refunded_cents', v_refunded::int,
    'plan', v_plan);
end $$;

--
-- Name: sv_checkout_quote(uuid, uuid, integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.sv_checkout_quote(p_business uuid, p_account uuid, p_cart_total_cents integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_state text;
  v_available integer;
  v_cover integer;
begin
  select coalesce(state, 'unbuilt') into v_state from public.sv_authority
   where business_id = p_business and asset = 'stored_value';
  v_state := coalesce(v_state, 'unbuilt');
  v_available := coalesce(app.sv_available_balance(p_business, p_account), 0);
  if p_cart_total_cents is null or p_cart_total_cents < 0 then
    return jsonb_build_object('ok', false, 'reason', 'cart total must be a non-negative integer');
  end if;
  v_cover := least(v_available, p_cart_total_cents);
  return jsonb_build_object(
    'ok', true,
    'authority_state', v_state,
    'spendable', (v_state = 'live'),
    'available_cents', v_available,
    'would_cover_cents', v_cover,
    'remaining_due_cents', greatest(p_cart_total_cents - v_cover, 0),
    'note', 'shadow quote only - no checkout path consumes stored-value tender while authority is not live');
end $$;

--
-- Name: sv_checkout_tender_gate(uuid, uuid, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.sv_checkout_tender_gate(p_business uuid, p_client uuid, p_currency text) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_state text;
  v_biz_synth boolean;
  v_client_synth boolean;
  v_biz_currency text;
begin
  select coalesce(state, 'unbuilt') into v_state from public.sv_authority
   where business_id = p_business and asset = 'stored_value';
  v_state := coalesce(v_state, 'unbuilt');
  if v_state <> 'live' then
    raise exception 'sv_not_live: stored value is not spendable for this business' using errcode = '22023';
  end if;
  -- Redeem pause gate (mirrors the spend engine; a clear typed message at the tender boundary).
  if app.sv_pause_active(p_business, 'stored_value', 'redeem') then
    raise exception 'sv_paused: stored-value redemptions are paused' using errcode = '22023';
  end if;
  select is_synthetic, currency into v_biz_synth, v_biz_currency from public.businesses where id = p_business;
  select is_synthetic into v_client_synth from public.clients where id = p_client and business_id = p_business;
  -- On a live business a synthetic entity may never transact (v66 rule).
  if coalesce(v_biz_synth, false) or coalesce(v_client_synth, false) then
    raise exception 'a synthetic entity cannot spend stored value on a live business' using errcode = '22023';
  end if;
  if p_currency is not null and upper(btrim(p_currency)) <> upper(coalesce(v_biz_currency, 'SGD')) then
    raise exception 'currency_mismatch: stored value must be spent in %', upper(coalesce(v_biz_currency, 'SGD')) using errcode = '22023';
  end if;
  return upper(coalesce(v_biz_currency, 'SGD'));
end $$;

--
-- Name: sv_class_balance(uuid, uuid, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.sv_class_balance(p_business uuid, p_account uuid, p_class text) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  select coalesce(sum(m.cents), 0)::integer
    from public.sv_lot_movements m
    join public.sv_lots l on l.id = m.lot_id and l.business_id = m.business_id
   where m.business_id = p_business and m.account_id = p_account and l.class = p_class
$$;

--
-- Name: sv_cutover_designations_guard(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.sv_cutover_designations_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if tg_op = 'DELETE' then
    raise exception 'sv_cutover_designations is append-only' using errcode = 'restrict_violation';
  end if;
  if old.revoked_at is not null then
    raise exception 'this stored-value cutover designation is already revoked (write-once)' using errcode = 'restrict_violation';
  end if;
  if new.id is distinct from old.id
     or new.business_id is distinct from old.business_id
     or new.asset is distinct from old.asset
     or new.designated_by is distinct from old.designated_by
     or new.reason is distinct from old.reason
     or new.designated_at is distinct from old.designated_at
     or new.created_at is distinct from old.created_at then
    raise exception 'stored-value cutover designation identity is immutable' using errcode = 'restrict_violation';
  end if;
  if new.revoked_at is null or new.revoked_by is null then
    raise exception 'revoking a stored-value cutover designation requires revoked_at and revoked_by' using errcode = 'restrict_violation';
  end if;
  return new;
end $$;

--
-- Name: sv_cutover_events_guard(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.sv_cutover_events_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  raise exception 'sv_cutover_events is immutable (a cutover is a fact, not a setting)'
    using errcode = 'restrict_violation';
end $$;

--
-- Name: sv_cutover_raise(jsonb); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.sv_cutover_raise(p_readiness jsonb) RETURNS void
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_code text; v_reason text;
begin
  if (p_readiness->>'ready')::boolean is true then
    return;
  end if;
  v_code := p_readiness->'blocking_codes'->>0;
  v_reason := coalesce(p_readiness->'blocking_reasons'->>0, 'cutover conditions are not met');
  if v_code is null then
    raise exception 'sv_not_ready: cutover conditions are not met' using errcode = '22023';
  end if;
  raise exception '%: %', v_code, v_reason using errcode = '22023';
end $$;

--
-- Name: sv_cutover_readiness(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.sv_cutover_readiness(p_business uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_asset text := 'stored_value';
  v_state text;
  v_snapshot public.sv_reconciliation_snapshots%rowtype;
  v_has_run boolean;
  v_rec_status text;
  v_disc int;
  v_paused boolean;
  v_synth boolean;
  v_designation uuid;
  v_pilot_live boolean;
  v_automation jsonb;
  v_reasons jsonb := '[]'::jsonb;
  v_codes jsonb := '[]'::jsonb;
begin
  select coalesce(state, 'unbuilt') into v_state from public.sv_authority
   where business_id = p_business and asset = v_asset;
  v_state := coalesce(v_state, 'unbuilt');   -- fail closed if no authority row

  select * into v_snapshot from public.sv_reconciliation_snapshots
   where business_id = p_business and asset = v_asset
   order by captured_at desc, id desc limit 1;
  v_has_run := found;
  v_rec_status := case when v_has_run then v_snapshot.status else null end;
  v_disc := case when v_has_run then v_snapshot.discrepancy_count else 0 end;

  v_paused := app.sv_pause_active(p_business, v_asset, 'all_only');
  select coalesce(b.is_synthetic, false) into v_synth from public.businesses b where b.id = p_business;
  v_synth := coalesce(v_synth, true);   -- unknown business fails closed
  select d.id into v_designation from public.sv_cutover_designations d
   where d.business_id = p_business and d.asset = v_asset and d.revoked_at is null;
  -- rev-2, review D1: is a DIFFERENT business already live on this asset platform-wide? The pilot is
  -- one business at a time, and 'live' is irreversible, so this must block cutover of anyone else.
  select exists (
    select 1 from public.sv_authority a2
     where a2.asset = v_asset and a2.state = 'live' and a2.business_id <> p_business)
    into v_pilot_live;
  v_pilot_live := coalesce(v_pilot_live, false);
  v_automation := app.sv_automation_status();

  -- PRECEDENCE ORDER. The three PS-2A reason strings that still hold are byte-identical.
  if v_synth then
    v_codes := v_codes || jsonb_build_array('sv_synthetic_business');
    v_reasons := v_reasons || jsonb_build_array(
      'this business is synthetic; a synthetic business may never go live');
  end if;
  if v_state = 'live' then
    v_codes := v_codes || jsonb_build_array('sv_already_live');
    v_reasons := v_reasons || jsonb_build_array(
      'authority is live (this business has already been cut over)');
  end if;
  -- rev-2, review D1: at-most-one-live-per-asset platform-wide. Placed just after this business's own
  -- already-live check: a business that is not itself live but faces an existing platform pilot is
  -- blocked here, so preview and act agree on sv_pilot_already_live via the precedence->raise path.
  if v_pilot_live then
    v_codes := v_codes || jsonb_build_array('sv_pilot_already_live');
    v_reasons := v_reasons || jsonb_build_array(
      'another business is already live on stored value; the pilot is one business at a time platform-wide');
  end if;
  if v_designation is null then
    v_codes := v_codes || jsonb_build_array('sv_not_designated');
    v_reasons := v_reasons || jsonb_build_array(
      'this business has not been designated for stored-value cutover by a super admin');
  end if;
  if v_state <> 'live' and v_state <> 'shadow_testing' then
    v_codes := v_codes || jsonb_build_array('sv_not_ready');
    v_reasons := v_reasons || jsonb_build_array(
      'authority is ' || v_state || ' (it must be shadow_testing to cut over to live)');
  end if;
  if not v_has_run then
    v_codes := v_codes || jsonb_build_array('sv_reconciliation_unclean');
    v_reasons := v_reasons || jsonb_build_array('reconciliation has not been run');
  elsif v_disc > 0 then
    v_codes := v_codes || jsonb_build_array('sv_reconciliation_unclean');
    v_reasons := v_reasons || jsonb_build_array(
      'reconciliation has ' || v_disc || ' open discrepancy(ies); it must be clean');
  elsif coalesce(v_rec_status, '') <> 'clean' then
    v_codes := v_codes || jsonb_build_array('sv_reconciliation_unclean');
    v_reasons := v_reasons || jsonb_build_array(
      'the latest reconciliation snapshot is ' || coalesce(v_rec_status, 'unknown') || '; it must be clean');
  end if;
  if v_paused then
    v_codes := v_codes || jsonb_build_array('sv_paused');
    v_reasons := v_reasons || jsonb_build_array('an all-scope stored-value pause is active');
  end if;
  if (v_automation->>'ok')::boolean is not true then
    v_codes := v_codes || jsonb_build_array('sv_automation_missing');
    v_reasons := v_reasons || jsonb_build_array(
      'stored-value automation is not scheduled and active: '
      || coalesce(nullif(array_to_string(array(
           select jsonb_array_elements_text(v_automation->'missing')), ', '), ''), 'unknown')
      || ' (value that can expire with no scheduled sweep must not go live)');
  end if;

  return jsonb_build_object(
    'business_id', p_business,
    'asset', v_asset,
    'authority_state', v_state,
    'reconciliation_status', v_rec_status,
    'discrepancy_count', v_disc,
    'designation_id', v_designation,
    'is_synthetic', v_synth,
    'pilot_already_live', v_pilot_live,
    'all_scope_pause_active', v_paused,
    'automation', v_automation,
    'blocking_reasons', v_reasons,
    'blocking_codes', v_codes,
    'ready', (jsonb_array_length(v_codes) = 0),
    'evidence_hash', app.ps1b_sha256(jsonb_build_object(
      'business_id', p_business, 'asset', v_asset, 'authority_state', v_state,
      'reconciliation_snapshot_id', case when v_has_run then v_snapshot.id else null end,
      'reconciliation_status', v_rec_status, 'discrepancy_count', v_disc,
      'designation_id', v_designation, 'is_synthetic', v_synth,
      'pilot_already_live', v_pilot_live,
      'all_scope_pause_active', v_paused,
      'automation_scheduled', v_automation->'scheduled',
      'blocking_codes', v_codes)::text));
end $$;

--
-- Name: sv_ensure_account(uuid, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.sv_ensure_account(p_business uuid, p_client uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_id uuid;
begin
  insert into public.sv_accounts(business_id, client_id, asset)
  values (p_business, p_client, 'stored_value')
  on conflict (business_id, client_id, asset) do nothing
  returning id into v_id;
  if v_id is null then
    select id into v_id from public.sv_accounts
     where business_id = p_business and client_id = p_client and asset = 'stored_value';
  end if;
  return v_id;
end $$;

--
-- Name: sv_evaluate_quote(uuid, uuid, integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.sv_evaluate_quote(p_business uuid, p_client uuid, p_total_cents integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_account uuid;
  v_quote jsonb;
begin
  if p_client is not null then
    select id into v_account from public.sv_accounts
     where business_id = p_business and client_id = p_client and asset = 'stored_value';
  end if;
  v_quote := app.sv_checkout_quote(p_business, v_account, greatest(coalesce(p_total_cents, 0), 0));
  return jsonb_build_object(
    'authority_state', v_quote->>'authority_state',
    'spendable', (v_quote->>'spendable')::boolean,
    'available_cents', coalesce((v_quote->>'available_cents')::int, 0),
    'would_cover_cents', coalesce((v_quote->>'would_cover_cents')::int, 0),
    'remaining_due_cents', coalesce((v_quote->>'remaining_due_cents')::int, greatest(coalesce(p_total_cents, 0), 0)));
end $$;

--
-- Name: sv_has_synthetic_evidence(uuid, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.sv_has_synthetic_evidence(p_business uuid, p_client uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  return exists (select 1 from public.sv_operations o where o.business_id = p_business)
      or exists (select 1 from public.sv_lots l where l.business_id = p_business
                  and (p_client is null or l.account_id in (select id from public.sv_accounts a where a.business_id = p_business and a.client_id = p_client)))
      or exists (select 1 from public.sv_topup_payments pm where pm.business_id = p_business and (p_client is null or pm.client_id = p_client));
end $$;

--
-- Name: sv_immutable_guard(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.sv_immutable_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  raise exception '% is append-only and immutable', tg_table_name using errcode = 'restrict_violation';
end $$;

--
-- Name: sv_jsonb_is_int(jsonb); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.sv_jsonb_is_int(v jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $_$ select v is not null and jsonb_typeof(v) = 'number' and (v#>>'{}') ~ '^-?[0-9]+$' $_$;

--
-- Name: sv_legacy_issue_guard(uuid, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.sv_legacy_issue_guard(p_business uuid, p_kind text DEFAULT 'gift_card'::text) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if exists (
    select 1 from public.sv_authority a
     where a.business_id = p_business
       and a.asset = 'stored_value'
       and a.state = 'live')
  then
    raise exception 'sv_live_legacy_issue_blocked: this business is live on stored value; issuing new legacy % value is blocked (one live value authority per asset - existing value is honoured to extinction and stays redeemable)', p_kind
      using errcode = '22023';
  end if;
end $$;

--
-- Name: sv_lot_remaining(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.sv_lot_remaining(p_lot uuid) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  select coalesce(sum(m.cents), 0)::integer
    from public.sv_lot_movements m
   where m.lot_id = p_lot
$$;

--
-- Name: sv_operation_net_spent(uuid, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.sv_operation_net_spent(p_business uuid, p_topup_operation uuid) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  select greatest(coalesce(sum(
           case when m.kind = 'spend' then -m.cents
                when m.kind = 'reversal' then -m.cents
                else 0 end), 0), 0)::integer
    from public.sv_lot_movements m
    join public.sv_lots l on l.id = m.lot_id and l.business_id = m.business_id
   where m.business_id = p_business and l.operation_id = p_topup_operation
$$;

--
-- Name: sv_operation_refund_policy(uuid, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.sv_operation_refund_policy(p_business uuid, p_topup_operation uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  select coalesce((select pv.refund_policy
                     from public.sv_lots l
                     join public.sv_plan_versions pv
                       on pv.id = l.plan_version_id and pv.business_id = l.business_id
                    where l.business_id = p_business and l.operation_id = p_topup_operation
                      and l.class = 'paid'
                    order by l.earned_seq asc, l.id asc limit 1), 'proportional')
$$;

--
-- Name: sv_pause_active(uuid, text, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.sv_pause_active(p_business uuid, p_asset text, p_family text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  select exists (
    select 1 from public.sv_pauses p
     where p.business_id = p_business
       and p.asset = coalesce(p_asset, 'stored_value')
       and p.lifted_at is null
       and (
         p.scope = 'all'
         or (p_family = 'earn' and p.scope = 'earn')
         or (p_family = 'redeem' and p.scope = 'redeem')
       )
  )
$$;

--
-- Name: sv_pauses_guard(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.sv_pauses_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if tg_op = 'DELETE' then
    raise exception 'sv_pauses is append-only' using errcode = 'restrict_violation';
  end if;
  if old.lifted_at is not null then
    raise exception 'stored-value pause is already lifted (write-once)' using errcode = 'restrict_violation';
  end if;
  if new.business_id is distinct from old.business_id
     or new.asset is distinct from old.asset
     or new.scope is distinct from old.scope
     or new.actor is distinct from old.actor
     or new.reason is distinct from old.reason
     or new.paused_at is distinct from old.paused_at
     or new.created_at is distinct from old.created_at then
    raise exception 'stored-value pause identity is immutable' using errcode = 'restrict_violation';
  end if;
  if new.lifted_at is null or new.lifted_by is null then
    raise exception 'lifting a stored-value pause requires lifted_at and lifted_by' using errcode = 'restrict_violation';
  end if;
  return new;
end $$;

--
-- Name: sv_plan_apply_config(uuid, uuid, jsonb); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.sv_plan_apply_config(p_business uuid, p_draft uuid, p_config jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v jsonb := coalesce(p_config, '{}'::jsonb);
begin
  perform app.sv_plan_assert_config(v, false);
  update public.sv_plan_drafts d set
    customer_facing_name = case when v ? 'customer_facing_name' then btrim(v->>'customer_facing_name') else d.customer_facing_name end,
    price_cents          = case when v ? 'price_cents' then (v->>'price_cents')::integer else d.price_cents end,
    bonus_cents          = case when v ? 'bonus_cents' then (v->>'bonus_cents')::integer else d.bonus_cents end,
    paid_expiry_days     = case when not (v ? 'paid_expiry_days') then d.paid_expiry_days when jsonb_typeof(v->'paid_expiry_days')='null' then null else (v->>'paid_expiry_days')::integer end,
    bonus_expiry_days    = case when not (v ? 'bonus_expiry_days') then d.bonus_expiry_days when jsonb_typeof(v->'bonus_expiry_days')='null' then null else (v->>'bonus_expiry_days')::integer end,
    eligible_branch_ids  = case when not (v ? 'eligible_branch_ids') then d.eligible_branch_ids else app.sv_canon_uuid_array(v->'eligible_branch_ids') end,
    eligible_service_ids = case when not (v ? 'eligible_service_ids') then d.eligible_service_ids else app.sv_canon_uuid_array(v->'eligible_service_ids') end,
    eligible_product_ids = case when not (v ? 'eligible_product_ids') then d.eligible_product_ids else app.sv_canon_uuid_array(v->'eligible_product_ids') end,
    eligible_service_categories = case when not (v ? 'eligible_service_categories') then d.eligible_service_categories else app.sv_canon_text_array(v->'eligible_service_categories') end,
    min_spend_cents      = case when not (v ? 'min_spend_cents') then d.min_spend_cents when jsonb_typeof(v->'min_spend_cents')='null' then null else (v->>'min_spend_cents')::integer end,
    stacking_policy      = case when v ? 'stacking_policy' then v->>'stacking_policy' else d.stacking_policy end,
    max_balance_cents    = case when not (v ? 'max_balance_cents') then d.max_balance_cents when jsonb_typeof(v->'max_balance_cents')='null' then null else (v->>'max_balance_cents')::integer end,
    purchase_window_days = case when not (v ? 'purchase_window_days') then d.purchase_window_days when jsonb_typeof(v->'purchase_window_days')='null' then null else (v->>'purchase_window_days')::integer end,
    purchase_max_in_window = case when not (v ? 'purchase_max_in_window') then d.purchase_max_in_window when jsonb_typeof(v->'purchase_max_in_window')='null' then null else (v->>'purchase_max_in_window')::integer end,
    purchase_lifetime_cap = case when not (v ? 'purchase_lifetime_cap') then d.purchase_lifetime_cap when jsonb_typeof(v->'purchase_lifetime_cap')='null' then null else (v->>'purchase_lifetime_cap')::integer end,
    refund_policy        = case when v ? 'refund_policy' then v->>'refund_policy' else d.refund_policy end,
    spend_order          = case when v ? 'spend_order' then v->>'spend_order' else d.spend_order end,
    topup_purchase_earns_points     = case when v ? 'topup_purchase_earns_points' then (v->>'topup_purchase_earns_points')::boolean else d.topup_purchase_earns_points end,
    stored_value_spend_earns_points = case when v ? 'stored_value_spend_earns_points' then (v->>'stored_value_spend_earns_points')::boolean else d.stored_value_spend_earns_points end,
    customer_terms       = case when not (v ? 'customer_terms') then d.customer_terms when jsonb_typeof(v->'customer_terms')='null' then null else btrim(v->>'customer_terms') end,
    accounting_inputs    = case when v ? 'accounting_inputs' then v->'accounting_inputs' else d.accounting_inputs end,
    effective_at         = case when not (v ? 'effective_at') then d.effective_at when jsonb_typeof(v->'effective_at')='null' then null else (v->>'effective_at')::timestamptz end
  where d.id = p_draft and d.business_id = p_business;
end $$;

--
-- Name: sv_plan_assert_config(jsonb, boolean); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.sv_plan_assert_config(p_config jsonb, p_allow_plan_id boolean) RETURNS void
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  k text;
  v jsonb;
  allowed text[] := array['customer_facing_name','price_cents','bonus_cents','paid_expiry_days',
    'bonus_expiry_days','eligible_branch_ids','eligible_service_ids','eligible_product_ids',
    'eligible_service_categories','min_spend_cents','stacking_policy','max_balance_cents',
    'purchase_window_days','purchase_max_in_window','purchase_lifetime_cap','refund_policy',
    'spend_order','topup_purchase_earns_points','stored_value_spend_earns_points','customer_terms',
    'accounting_inputs','effective_at'];
  nullable_int text[] := array['paid_expiry_days','bonus_expiry_days','min_spend_cents','max_balance_cents',
    'purchase_window_days','purchase_max_in_window','purchase_lifetime_cap'];
  arr_uuid text[] := array['eligible_branch_ids','eligible_service_ids','eligible_product_ids'];
  int4_max constant bigint := 2147483647;
begin
  if p_config is null or jsonb_typeof(p_config) <> 'object' then
    raise exception 'plan configuration must be a JSON object' using errcode = '22023';
  end if;
  if p_allow_plan_id then allowed := array_append(allowed, 'plan_id'); end if;

  for k, v in select key, value from jsonb_each(p_config) loop
    if not (k = any(allowed)) then
      raise exception 'unknown plan configuration key: %', k using errcode = '22023';
    end if;

    if k = 'plan_id' then
      if jsonb_typeof(v) <> 'string' then raise exception 'plan_id must be a UUID string' using errcode = '22023'; end if;
      begin perform (v#>>'{}')::uuid; exception when others then raise exception 'plan_id is not a valid UUID' using errcode = '22023'; end;
    elsif k in ('price_cents','bonus_cents') then
      if not app.sv_jsonb_is_int(v) then raise exception '% must be a whole number', k using errcode = '22023'; end if;
      if (v#>>'{}')::numeric < 0 then raise exception '% cannot be negative', k using errcode = '22023'; end if;
      if (v#>>'{}')::numeric > int4_max then raise exception '% is too large (max 2147483647)', k using errcode = '22023'; end if;
    elsif k = any(nullable_int) then
      if jsonb_typeof(v) <> 'null' then
        if not app.sv_jsonb_is_int(v) then raise exception '% must be a whole number or null', k using errcode = '22023'; end if;
        if k in ('paid_expiry_days','bonus_expiry_days','purchase_window_days','purchase_max_in_window','purchase_lifetime_cap')
           and (v#>>'{}')::numeric <= 0 then raise exception '% must be a positive whole number', k using errcode = '22023'; end if;
        if k in ('min_spend_cents','max_balance_cents') and (v#>>'{}')::numeric < 0 then
          raise exception '% cannot be negative', k using errcode = '22023'; end if;
        if (v#>>'{}')::numeric > int4_max then raise exception '% is too large (max 2147483647)', k using errcode = '22023'; end if;
      end if;
    elsif k = any(arr_uuid) then
      if jsonb_typeof(v) not in ('array','null') then raise exception '% must be a JSON array of ids or null', k using errcode = '22023'; end if;
      if jsonb_typeof(v) = 'array' and jsonb_array_length(v) = 0 then
        raise exception '% cannot be an empty list (use null to mean all, or list at least one)', k using errcode = '22023'; end if;
    elsif k = 'eligible_service_categories' then
      if jsonb_typeof(v) not in ('array','null') then raise exception 'eligible_service_categories must be a JSON array or null' using errcode = '22023'; end if;
      if jsonb_typeof(v) = 'array' and jsonb_array_length(v) = 0 then
        raise exception 'eligible_service_categories cannot be an empty list (use null to mean all)' using errcode = '22023'; end if;
      if jsonb_typeof(v) = 'array' and not exists (select 1 from jsonb_array_elements_text(v) e where btrim(e) <> '') then
        raise exception 'eligible_service_categories has no non-blank values (use null to mean all)' using errcode = '22023'; end if;
    elsif k = 'stacking_policy' then
      if jsonb_typeof(v) <> 'string' or (v#>>'{}') not in ('stackable','not_with_other_discounts','exclusive') then
        raise exception 'stacking_policy must be stackable/not_with_other_discounts/exclusive' using errcode = '22023'; end if;
    elsif k = 'refund_policy' then
      if jsonb_typeof(v) <> 'string' or (v#>>'{}') not in ('full_unused','proportional','unused_only','no_refund') then
        raise exception 'refund_policy must be full_unused/proportional/unused_only/no_refund' using errcode = '22023'; end if;
    elsif k = 'spend_order' then
      if jsonb_typeof(v) <> 'string' or (v#>>'{}') not in ('bonus_first','paid_first','earliest_expiry_first','proportional') then
        raise exception 'spend_order must be bonus_first/paid_first/earliest_expiry_first/proportional' using errcode = '22023'; end if;
    elsif k in ('topup_purchase_earns_points','stored_value_spend_earns_points') then
      if jsonb_typeof(v) <> 'boolean' then raise exception '% must be true or false', k using errcode = '22023'; end if;
    elsif k = 'customer_facing_name' then
      if jsonb_typeof(v) <> 'string' then raise exception 'customer_facing_name must be text' using errcode = '22023'; end if;
      if char_length(btrim(v#>>'{}')) > 200 then raise exception 'customer_facing_name is too long (max 200 chars)' using errcode = '22023'; end if;
    elsif k = 'customer_terms' then
      if jsonb_typeof(v) not in ('string','null') then raise exception 'customer_terms must be text or null' using errcode = '22023'; end if;
      if jsonb_typeof(v) = 'string' and char_length(v#>>'{}') > 5000 then raise exception 'customer_terms is too long (max 5000 chars)' using errcode = '22023'; end if;
    elsif k = 'accounting_inputs' then
      if jsonb_typeof(v) <> 'object' then raise exception 'accounting_inputs must be a JSON object' using errcode = '22023'; end if;
    elsif k = 'effective_at' then
      if jsonb_typeof(v) not in ('string','null') then raise exception 'effective_at must be a timestamp string or null' using errcode = '22023'; end if;
      if jsonb_typeof(v) = 'string' then
        begin perform (v#>>'{}')::timestamptz; exception when others then raise exception 'effective_at is not a valid timestamp' using errcode = '22023'; end;
      end if;
    end if;
  end loop;
end $$;

--
-- Name: sv_plan_drafts; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.sv_plan_drafts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    business_id uuid NOT NULL,
    plan_id uuid,
    status text DEFAULT 'draft'::text NOT NULL,
    revision integer DEFAULT 0 NOT NULL,
    actor uuid,
    customer_facing_name text DEFAULT ''::text NOT NULL,
    price_cents integer DEFAULT 0 NOT NULL,
    bonus_cents integer DEFAULT 0 NOT NULL,
    paid_expiry_days integer,
    bonus_expiry_days integer,
    eligible_branch_ids uuid[],
    eligible_service_ids uuid[],
    eligible_product_ids uuid[],
    eligible_service_categories text[],
    min_spend_cents integer,
    stacking_policy text DEFAULT 'stackable'::text NOT NULL,
    max_balance_cents integer,
    purchase_window_days integer,
    purchase_max_in_window integer,
    purchase_lifetime_cap integer,
    refund_policy text DEFAULT 'proportional'::text NOT NULL,
    spend_order text DEFAULT 'proportional'::text NOT NULL,
    topup_purchase_earns_points boolean DEFAULT false NOT NULL,
    stored_value_spend_earns_points boolean DEFAULT false NOT NULL,
    customer_terms text,
    accounting_inputs jsonb DEFAULT '{}'::jsonb NOT NULL,
    effective_at timestamp with time zone,
    published_version_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT sv_plan_drafts_bonus_cents_check CHECK ((bonus_cents >= 0)),
    CONSTRAINT sv_plan_drafts_bonus_expiry_days_check CHECK (((bonus_expiry_days IS NULL) OR (bonus_expiry_days > 0))),
    CONSTRAINT sv_plan_drafts_max_balance_cents_check CHECK (((max_balance_cents IS NULL) OR (max_balance_cents >= 0))),
    CONSTRAINT sv_plan_drafts_min_spend_cents_check CHECK (((min_spend_cents IS NULL) OR (min_spend_cents >= 0))),
    CONSTRAINT sv_plan_drafts_paid_expiry_days_check CHECK (((paid_expiry_days IS NULL) OR (paid_expiry_days > 0))),
    CONSTRAINT sv_plan_drafts_price_cents_check CHECK ((price_cents >= 0)),
    CONSTRAINT sv_plan_drafts_purchase_lifetime_cap_check CHECK (((purchase_lifetime_cap IS NULL) OR (purchase_lifetime_cap > 0))),
    CONSTRAINT sv_plan_drafts_purchase_max_in_window_check CHECK (((purchase_max_in_window IS NULL) OR (purchase_max_in_window > 0))),
    CONSTRAINT sv_plan_drafts_purchase_window_days_check CHECK (((purchase_window_days IS NULL) OR (purchase_window_days > 0))),
    CONSTRAINT sv_plan_drafts_refund_policy_check CHECK ((refund_policy = ANY (ARRAY['full_unused'::text, 'proportional'::text, 'unused_only'::text, 'no_refund'::text]))),
    CONSTRAINT sv_plan_drafts_spend_order_check CHECK ((spend_order = ANY (ARRAY['bonus_first'::text, 'paid_first'::text, 'earliest_expiry_first'::text, 'proportional'::text]))),
    CONSTRAINT sv_plan_drafts_stacking_policy_check CHECK ((stacking_policy = ANY (ARRAY['stackable'::text, 'not_with_other_discounts'::text, 'exclusive'::text]))),
    CONSTRAINT sv_plan_drafts_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'published'::text, 'discarded'::text])))
);

--
-- Name: sv_plan_draft_json(public.sv_plan_drafts); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.sv_plan_draft_json(p public.sv_plan_drafts) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  select jsonb_build_object(
    'draft_id', p.id, 'business_id', p.business_id, 'plan_id', p.plan_id, 'status', p.status,
    'revision', p.revision, 'customer_facing_name', p.customer_facing_name,
    'price_cents', p.price_cents, 'bonus_cents', p.bonus_cents,
    'total_usable_cents', p.price_cents + p.bonus_cents,
    'effective_discount_bps', app.sv_plan_effective_discount_bps(p.price_cents, p.bonus_cents),
    'paid_expiry_days', p.paid_expiry_days, 'bonus_expiry_days', p.bonus_expiry_days,
    'eligible_branch_ids', to_jsonb(p.eligible_branch_ids), 'eligible_service_ids', to_jsonb(p.eligible_service_ids),
    'eligible_product_ids', to_jsonb(p.eligible_product_ids), 'eligible_service_categories', to_jsonb(p.eligible_service_categories),
    'min_spend_cents', p.min_spend_cents, 'stacking_policy', p.stacking_policy, 'max_balance_cents', p.max_balance_cents,
    'purchase_window_days', p.purchase_window_days, 'purchase_max_in_window', p.purchase_max_in_window,
    'purchase_lifetime_cap', p.purchase_lifetime_cap, 'refund_policy', p.refund_policy, 'spend_order', p.spend_order,
    'topup_purchase_earns_points', p.topup_purchase_earns_points, 'stored_value_spend_earns_points', p.stored_value_spend_earns_points,
    'customer_terms', p.customer_terms, 'accounting_inputs', p.accounting_inputs, 'effective_at', p.effective_at,
    'published_version_id', p.published_version_id)
$$;

--
-- Name: sv_plan_drafts_guard(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.sv_plan_drafts_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if tg_op = 'DELETE' then
    raise exception 'sv_plan_drafts is append-only (discard, never delete)' using errcode = 'restrict_violation';
  end if;
  if old.status <> 'draft' then
    raise exception 'stored-value plan draft is % and can no longer be edited', old.status using errcode = 'restrict_violation';
  end if;
  if new.business_id is distinct from old.business_id or new.created_at is distinct from old.created_at then
    raise exception 'stored-value plan draft identity is immutable' using errcode = 'restrict_violation';
  end if;
  if new.status not in ('draft','published','discarded') then
    raise exception 'stored-value plan draft status must be draft/published/discarded' using errcode = 'restrict_violation';
  end if;
  new.updated_at := now();
  return new;
end $$;

--
-- Name: sv_plan_effective_discount_bps(integer, integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.sv_plan_effective_discount_bps(p_price integer, p_bonus integer) RETURNS integer
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  select case when coalesce(p_price,0) + coalesce(p_bonus,0) = 0 then 0
              else round(coalesce(p_bonus,0)::numeric * 10000 / (coalesce(p_price,0) + coalesce(p_bonus,0)))::integer end
$$;

--
-- Name: sv_plan_idem_lookup(uuid, text, uuid, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.sv_plan_idem_lookup(p_business uuid, p_op text, p_key uuid, p_hash text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v public.sv_plan_operations%rowtype;
begin
  if p_key is null then raise exception 'an idempotency key is required' using errcode = '22023'; end if;
  perform pg_advisory_xact_lock(hashtextextended('v65:'||p_op||':'||p_business::text||':'||p_key::text, 0));
  select * into v from public.sv_plan_operations
   where business_id = p_business and op_type = p_op and idempotency_key = p_key for update;
  if found then
    if v.request_hash <> p_hash then
      raise exception 'idempotency key conflicts with a different % request', p_op using errcode = '22023';
    end if;
    return v.result;
  end if;
  return null;
end $$;

--
-- Name: sv_plan_refund(uuid, uuid, integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.sv_plan_refund(p_business uuid, p_topup_operation uuid, p_cash_cents integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_paid_lot uuid;
  v_bonus_lot uuid;
  v_paid_rem bigint;
  v_bonus_rem bigint;
  v_x bigint;
  v_clawback bigint;
  v_final boolean;
  v_plan jsonb := '[]'::jsonb;
begin
  if p_cash_cents is not null and p_cash_cents < 0 then
    return jsonb_build_object('ok', false, 'reason', 'a refund amount cannot be negative');
  end if;

  select id into v_paid_lot from public.sv_lots
   where business_id = p_business and operation_id = p_topup_operation and class = 'paid'
   order by earned_seq asc, id asc limit 1;
  if v_paid_lot is null then
    return jsonb_build_object('ok', false, 'reason', 'operation has no paid lot to refund');
  end if;
  select id into v_bonus_lot from public.sv_lots
   where business_id = p_business and operation_id = p_topup_operation and class = 'bonus'
   order by earned_seq asc, id asc limit 1;

  v_paid_rem := app.sv_lot_remaining(v_paid_lot);
  v_bonus_rem := coalesce(app.sv_lot_remaining(v_bonus_lot), 0);

  -- Whole-op when cash is unspecified or >= paid remaining (contract: null/>=paid_rem = whole-op).
  v_final := (p_cash_cents is null) or (p_cash_cents >= v_paid_rem);
  v_x := case when v_final then v_paid_rem else p_cash_cents end;

  -- PS-0 §4: X <= paid_rem always holds (partial branch has X < paid_rem; final branch X = paid_rem).
  if v_x > v_paid_rem then
    return jsonb_build_object('ok', false, 'reason', 'refund exceeds the operation paid remaining');
  end if;

  if v_final then
    v_clawback := v_bonus_rem;                                          -- terminal sweep (requirement 2)
  elsif v_paid_rem = 0 then
    v_clawback := v_bonus_rem;                                          -- defensive (final would have fired)
  else
    v_clawback := (v_bonus_rem * v_x) / v_paid_rem;                     -- floor on bonus (non-final)
  end if;

  if v_x > 0 then
    v_plan := v_plan || jsonb_build_array(jsonb_build_object(
      'lot_id', v_paid_lot, 'class', 'paid', 'kind', 'refund', 'cents', (-v_x)::int));
  end if;
  if v_clawback > 0 and v_bonus_lot is not null then
    v_plan := v_plan || jsonb_build_array(jsonb_build_object(
      'lot_id', v_bonus_lot, 'class', 'bonus', 'kind', 'clawback', 'cents', (-v_clawback)::int));
  end if;

  return jsonb_build_object(
    'ok', true,
    'cash_cents', v_x::int,
    'clawback_cents', v_clawback::int,
    'final', v_final,
    'paid_lot', v_paid_lot,
    'bonus_lot', v_bonus_lot,
    'paid_remaining_cents', v_paid_rem::int,
    'bonus_remaining_cents', v_bonus_rem::int,
    'plan', v_plan);
end $$;

--
-- Name: sv_plan_validate(uuid, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.sv_plan_validate(p_business uuid, p_draft uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  d public.sv_plan_drafts%rowtype;
  v_errors text[] := '{}';
  v_warnings text[] := '{}';
  v_warn integer; v_hard integer; v_disc integer;
  v_total integer;
begin
  select * into d from public.sv_plan_drafts where id = p_draft and business_id = p_business;
  if not found then raise exception 'stored-value plan draft not found in this business' using errcode = '22023'; end if;
  v_total := d.price_cents + d.bonus_cents;
  v_disc := app.sv_plan_effective_discount_bps(d.price_cents, d.bonus_cents);
  select coalesce(warn_discount_bps,3000), coalesce(hard_discount_bps,7000) into v_warn, v_hard
    from public.sv_plan_guardrails where business_id = p_business;
  v_warn := coalesce(v_warn,3000); v_hard := coalesce(v_hard,7000);

  -- structural errors
  if d.price_cents <= 0 then v_errors := array_append(v_errors, 'a top-up plan must have a positive paid amount (a zero-paid promo is a grant, not a top-up)'); end if;
  if btrim(d.customer_facing_name) = '' then v_errors := array_append(v_errors, 'a customer-facing name is required'); end if;
  if d.customer_terms is null or btrim(d.customer_terms) = '' then v_errors := array_append(v_errors, 'customer-facing terms are required for a live-pilot plan'); end if;
  if (d.purchase_window_days is null) <> (d.purchase_max_in_window is null) then
    v_errors := array_append(v_errors, 'purchase window days and max-in-window must be set together or both left empty'); end if;
  if d.max_balance_cents is not null and d.max_balance_cents < v_total then
    v_errors := array_append(v_errors, 'maximum balance is smaller than one purchase total - no customer could ever buy this plan'); end if;

  -- eligibility integrity (cross-tenant / inactive)
  if d.eligible_branch_ids is not null then
    if exists (select 1 from unnest(d.eligible_branch_ids) x where not exists (select 1 from public.branches b where b.id = x and b.business_id = p_business)) then
      v_errors := array_append(v_errors, 'one or more eligible branches do not belong to this business');
    elsif exists (select 1 from unnest(d.eligible_branch_ids) x join public.branches b on b.id = x and b.business_id = p_business where not b.active) then
      v_errors := array_append(v_errors, 'one or more eligible branches are inactive'); end if;
  end if;
  if d.eligible_service_ids is not null then
    if exists (select 1 from unnest(d.eligible_service_ids) x where not exists (select 1 from public.services s where s.id = x and s.business_id = p_business)) then
      v_errors := array_append(v_errors, 'one or more eligible services do not belong to this business');
    elsif exists (select 1 from unnest(d.eligible_service_ids) x join public.services s on s.id = x and s.business_id = p_business where not s.active) then
      v_errors := array_append(v_errors, 'one or more eligible services are inactive'); end if;
  end if;
  if d.eligible_product_ids is not null then
    if exists (select 1 from unnest(d.eligible_product_ids) x where not exists (select 1 from public.products p where p.id = x and p.business_id = p_business)) then
      v_errors := array_append(v_errors, 'one or more eligible products do not belong to this business');
    elsif exists (select 1 from unnest(d.eligible_product_ids) x join public.products p on p.id = x and p.business_id = p_business where not p.active) then
      v_errors := array_append(v_errors, 'one or more eligible products are inactive'); end if;
  end if;

  -- warnings (overridable)
  if d.bonus_cents > d.price_cents and d.price_cents > 0 then v_warnings := array_append(v_warnings, 'the bonus exceeds the amount paid'); end if;
  if d.max_balance_cents is null then v_warnings := array_append(v_warnings, 'no maximum customer balance is set'); end if;
  if d.paid_expiry_days is null and d.bonus_expiry_days is null then v_warnings := array_append(v_warnings, 'neither paid nor bonus value expires'); end if;
  if d.eligible_service_categories is not null and not exists (
       select 1 from public.services s where s.business_id = p_business and s.category = any(d.eligible_service_categories)) then
    v_warnings := array_append(v_warnings, 'no active service currently matches the chosen service categories'); end if;
  if v_disc >= v_hard then v_warnings := array_append(v_warnings, 'effective discount is at or above the firm hard limit ('||(v_hard/100.0)||'%) - an override reason is required to publish');
  elsif v_disc >= v_warn then v_warnings := array_append(v_warnings, 'effective discount is at or above the firm warning limit ('||(v_warn/100.0)||'%)'); end if;

  return jsonb_build_object(
    'effective_discount_bps', v_disc, 'warn_threshold_bps', v_warn, 'hard_threshold_bps', v_hard,
    'override_required', (v_disc >= v_hard),
    'validation_errors', to_jsonb(v_errors), 'warnings', to_jsonb(v_warnings),
    'publishable', (array_length(v_errors,1) is null));
end $$;

--
-- Name: sv_plan_versions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.sv_plan_versions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    business_id uuid NOT NULL,
    plan_id uuid NOT NULL,
    version_no integer NOT NULL,
    price_cents integer NOT NULL,
    bonus_cents integer DEFAULT 0 NOT NULL,
    expiry_days integer,
    terms_snapshot jsonb NOT NULL,
    published_at timestamp with time zone DEFAULT now() NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    customer_facing_name text,
    paid_expiry_days integer,
    bonus_expiry_days integer,
    eligible_branch_ids uuid[],
    eligible_service_ids uuid[],
    eligible_product_ids uuid[],
    eligible_service_categories text[],
    min_spend_cents integer,
    stacking_policy text,
    max_balance_cents integer,
    purchase_window_days integer,
    purchase_max_in_window integer,
    purchase_lifetime_cap integer,
    refund_policy text,
    spend_order text,
    topup_purchase_earns_points boolean,
    stored_value_spend_earns_points boolean,
    customer_terms text,
    accounting_inputs jsonb,
    effective_at timestamp with time zone,
    source_draft_id uuid,
    CONSTRAINT sv_plan_versions_bonus_cents_check CHECK ((bonus_cents >= 0)),
    CONSTRAINT sv_plan_versions_bonus_expiry_days_check CHECK (((bonus_expiry_days IS NULL) OR (bonus_expiry_days > 0))),
    CONSTRAINT sv_plan_versions_expiry_days_check CHECK (((expiry_days IS NULL) OR (expiry_days > 0))),
    CONSTRAINT sv_plan_versions_max_balance_cents_check CHECK (((max_balance_cents IS NULL) OR (max_balance_cents >= 0))),
    CONSTRAINT sv_plan_versions_min_spend_cents_check CHECK (((min_spend_cents IS NULL) OR (min_spend_cents >= 0))),
    CONSTRAINT sv_plan_versions_paid_expiry_days_check CHECK (((paid_expiry_days IS NULL) OR (paid_expiry_days > 0))),
    CONSTRAINT sv_plan_versions_price_cents_check CHECK ((price_cents > 0)),
    CONSTRAINT sv_plan_versions_purchase_lifetime_cap_check CHECK (((purchase_lifetime_cap IS NULL) OR (purchase_lifetime_cap > 0))),
    CONSTRAINT sv_plan_versions_purchase_max_in_window_check CHECK (((purchase_max_in_window IS NULL) OR (purchase_max_in_window > 0))),
    CONSTRAINT sv_plan_versions_purchase_window_days_check CHECK (((purchase_window_days IS NULL) OR (purchase_window_days > 0))),
    CONSTRAINT sv_plan_versions_refund_policy_check CHECK (((refund_policy IS NULL) OR (refund_policy = ANY (ARRAY['full_unused'::text, 'proportional'::text, 'unused_only'::text, 'no_refund'::text])))),
    CONSTRAINT sv_plan_versions_spend_order_check CHECK (((spend_order IS NULL) OR (spend_order = ANY (ARRAY['bonus_first'::text, 'paid_first'::text, 'earliest_expiry_first'::text, 'proportional'::text])))),
    CONSTRAINT sv_plan_versions_stacking_policy_check CHECK (((stacking_policy IS NULL) OR (stacking_policy = ANY (ARRAY['stackable'::text, 'not_with_other_discounts'::text, 'exclusive'::text]))))
);

--
-- Name: sv_plan_version_json(public.sv_plan_versions); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.sv_plan_version_json(p public.sv_plan_versions) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  select jsonb_build_object(
    'version_id', p.id, 'version_no', p.version_no, 'customer_facing_name', p.customer_facing_name,
    'price_cents', p.price_cents, 'bonus_cents', p.bonus_cents, 'total_usable_cents', p.price_cents + p.bonus_cents,
    'effective_discount_bps', app.sv_plan_effective_discount_bps(p.price_cents, p.bonus_cents),
    'paid_expiry_days', p.paid_expiry_days, 'bonus_expiry_days', p.bonus_expiry_days,
    'eligible_branch_ids', to_jsonb(p.eligible_branch_ids), 'eligible_service_ids', to_jsonb(p.eligible_service_ids),
    'eligible_product_ids', to_jsonb(p.eligible_product_ids), 'eligible_service_categories', to_jsonb(p.eligible_service_categories),
    'min_spend_cents', p.min_spend_cents, 'stacking_policy', p.stacking_policy, 'max_balance_cents', p.max_balance_cents,
    'purchase_window_days', p.purchase_window_days, 'purchase_max_in_window', p.purchase_max_in_window,
    'purchase_lifetime_cap', p.purchase_lifetime_cap, 'refund_policy', p.refund_policy, 'spend_order', p.spend_order,
    'topup_purchase_earns_points', p.topup_purchase_earns_points, 'stored_value_spend_earns_points', p.stored_value_spend_earns_points,
    'customer_terms', p.customer_terms, 'accounting_inputs', p.accounting_inputs, 'effective_at', p.effective_at,
    'source_draft_id', p.source_draft_id, 'published_at', p.published_at)
$$;

--
-- Name: sv_record_settlement_reversal(uuid, uuid, jsonb, text, uuid, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.sv_record_settlement_reversal(p_business uuid, p_spend_operation uuid, p_reverse_result jsonb, p_reversed_via text, p_reversal_sale_id uuid, p_reason text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_tender public.checkout_sv_tenders%rowtype;
  v_marker uuid;
begin
  select * into v_tender from public.checkout_sv_tenders
   where business_id = p_business and spend_operation_id = p_spend_operation and status = 'consumed';
  if not found then
    return false;   -- a plain spend reversal (no checkout settlement) writes no marker
  end if;

  insert into public.checkout_sv_tender_reversals(
    business_id, tender_id, sale_id, spend_operation_id, reverse_operation_id, account_id,
    restored_cents, restored_paid_cents, restored_bonus_cents, reversed_via, reversal_sale_id, actor, reason)
  values (
    p_business, v_tender.id, v_tender.sale_id, p_spend_operation,
    (p_reverse_result->>'operation_id')::uuid, v_tender.account_id,
    coalesce((p_reverse_result->>'net_restored_cents')::int, 0),
    coalesce(v_tender.sv_paid_cents, 0), coalesce(v_tender.sv_bonus_cents, 0),
    p_reversed_via, p_reversal_sale_id, v_actor, p_reason)
  on conflict on constraint checkout_sv_tender_reversals_tender_uk do nothing
  returning id into v_marker;

  if v_marker is not null then
    insert into public.audit_log(business_id, actor, action, entity, entity_id, detail)
    values (p_business, v_actor, 'SV_SETTLEMENT_REVERSED', 'checkout_sv_tenders', v_tender.id,
      jsonb_build_object('tender_id', v_tender.id, 'sale_id', v_tender.sale_id,
        'spend_operation_id', p_spend_operation, 'reverse_operation_id', (p_reverse_result->>'operation_id')::uuid,
        'reversed_via', p_reversed_via, 'restored_paid_cents', coalesce(v_tender.sv_paid_cents, 0),
        'restored_bonus_cents', coalesce(v_tender.sv_bonus_cents, 0)));
  end if;
  return true;
end $$;

--
-- Name: sv_release_core(uuid, uuid, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.sv_release_core(p_business uuid, p_reservation uuid, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_hash text;
  v_existing public.sv_operations%rowtype;
  v_op uuid := gen_random_uuid();
  v_row public.sv_reservations%rowtype;
  v_result jsonb;
begin
  if coalesce((select state from public.sv_authority
                where business_id = p_business and asset = 'stored_value'), 'unbuilt') <> 'live' then
    raise exception 'sv_not_live: stored value is not the authority for this business' using errcode = '22023';
  end if;
  if p_idempotency_key is null then
    raise exception 'a stored-value release idempotency key is required' using errcode = '22023';
  end if;

  select * into v_row from public.sv_reservations
   where id = p_reservation and business_id = p_business for update;
  if not found then
    raise exception 'stored-value reservation not found in this business' using errcode = '22023';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('v63:sv_acct:' || p_business::text || ':' || v_row.account_id::text, 0));
  perform pg_advisory_xact_lock(hashtextextended('v63:sv_release:' || p_business::text || ':' || p_idempotency_key::text, 0));

  select * into v_existing from public.sv_operations o
   where o.business_id = p_business and o.operation_type = 'release' and o.idempotency_key = p_idempotency_key
   for update;
  v_hash := app.ps1b_sha256(jsonb_build_object(
    'op', 'release', 'business_id', p_business, 'reservation_id', p_reservation)::text);
  if found then
    if v_existing.request_hash <> v_hash then
      raise exception 'idempotency key conflicts with a different stored-value release' using errcode = '22023';
    end if;
    return v_existing.result;
  end if;

  if v_row.status = 'released' then
    -- idempotent: already released, nothing to move.
    return jsonb_build_object('status', 'ok', 'reservation_id', p_reservation,
      'reservation_status', 'released', 'already_released', true);
  end if;
  if v_row.status = 'consumed' then
    raise exception 'stored-value reservation is already consumed and cannot be released' using errcode = '22023';
  end if;

  v_result := jsonb_build_object('status', 'ok', 'operation_id', v_op, 'reservation_id', p_reservation,
    'reservation_status', 'released', 'amount_cents', v_row.amount_cents, 'already_released', false);

  insert into public.sv_operations(id, business_id, operation_type, idempotency_key, request_hash, actor, result)
  values (v_op, p_business, 'release', p_idempotency_key, v_hash, v_actor, v_result);
  update public.sv_reservations
     set status = 'released', released_by_operation_id = v_op, updated_at = now()
   where id = p_reservation and business_id = p_business and status = 'active';
  insert into public.audit_log(business_id, actor, action, entity, entity_id, detail)
  values (p_business, v_actor, 'SV_RELEASE', 'sv_reservations', p_reservation, jsonb_build_object(
    'operation_id', v_op, 'amount_cents', v_row.amount_cents));

  return v_result;
end $$;

--
-- Name: sv_reservations_guard(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.sv_reservations_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if tg_op = 'DELETE' then
    raise exception 'sv_reservations rows are permanent (append-only holds)' using errcode = 'restrict_violation';
  end if;
  if new.id is distinct from old.id or new.business_id is distinct from old.business_id
     or new.account_id is distinct from old.account_id or new.operation_id is distinct from old.operation_id
     or new.amount_cents is distinct from old.amount_cents or new.created_at is distinct from old.created_at then
    raise exception 'sv_reservations identity and economics are immutable' using errcode = 'restrict_violation';
  end if;
  if new.status not in ('active', 'consumed', 'released') then
    raise exception 'sv_reservations status must be active/consumed/released' using errcode = 'restrict_violation';
  end if;
  -- terminal is terminal: a non-active reservation can never change status again.
  if old.status <> 'active' and new.status is distinct from old.status then
    raise exception 'sv_reservations is already % (holds are single-transition)', old.status using errcode = 'restrict_violation';
  end if;
  return new;
end $$;

--
-- Name: sv_reserve_core(uuid, uuid, integer, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.sv_reserve_core(p_business uuid, p_account uuid, p_cents integer, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_hash text;
  v_existing public.sv_operations%rowtype;
  v_op uuid := gen_random_uuid();
  v_res uuid := gen_random_uuid();
  v_available integer;
  v_result jsonb;
begin
  -- HARD SAFETY GATE: value only moves when stored value is the authority (unreachable in prod).
  if coalesce((select state from public.sv_authority
                where business_id = p_business and asset = 'stored_value'), 'unbuilt') <> 'live' then
    raise exception 'sv_not_live: stored value is not the authority for this business' using errcode = '22023';
  end if;

  -- Redeem pause gate (an active 'all' or 'redeem' sv_pause blocks spends/reservations).
  if app.sv_pause_active(p_business, 'stored_value', 'redeem') then
    raise exception 'sv_paused: stored-value redemptions are paused' using errcode = '22023';
  end if;
  if p_idempotency_key is null then
    raise exception 'a stored-value reserve idempotency key is required' using errcode = '22023';
  end if;
  if p_cents is null or p_cents < 1 then
    raise exception 'a stored-value reserve must be a whole number of at least 1 cent' using errcode = '22023';
  end if;
  if not exists (select 1 from public.sv_accounts a where a.id = p_account and a.business_id = p_business) then
    raise exception 'stored-value account does not belong to this business' using errcode = '22023';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('v63:sv_acct:' || p_business::text || ':' || p_account::text, 0));
  perform pg_advisory_xact_lock(hashtextextended('v63:sv_reserve:' || p_business::text || ':' || p_idempotency_key::text, 0));

  select * into v_existing from public.sv_operations o
   where o.business_id = p_business and o.operation_type = 'reserve' and o.idempotency_key = p_idempotency_key
   for update;
  v_hash := app.ps1b_sha256(jsonb_build_object(
    'op', 'reserve', 'business_id', p_business, 'account_id', p_account, 'cents', p_cents)::text);
  if found then
    if v_existing.request_hash <> v_hash then
      raise exception 'idempotency key conflicts with a different stored-value reserve' using errcode = '22023';
    end if;
    return v_existing.result;
  end if;

  v_available := app.sv_available_balance(p_business, p_account);
  if p_cents > v_available then
    raise exception 'insufficient stored value to reserve (% requested, % available)', p_cents, v_available
      using errcode = '22023';
  end if;

  v_result := jsonb_build_object(
    'status', 'ok', 'operation_id', v_op, 'reservation_id', v_res, 'account_id', p_account,
    'amount_cents', p_cents, 'reservation_status', 'active',
    'available_after_cents', v_available - p_cents);

  insert into public.sv_operations(id, business_id, operation_type, idempotency_key, request_hash, actor, result)
  values (v_op, p_business, 'reserve', p_idempotency_key, v_hash, v_actor, v_result);
  insert into public.sv_reservations(id, business_id, account_id, operation_id, amount_cents, status)
  values (v_res, p_business, p_account, v_op, p_cents, 'active');
  insert into public.audit_log(business_id, actor, action, entity, entity_id, detail)
  values (p_business, v_actor, 'SV_RESERVE', 'sv_reservations', v_res, jsonb_build_object(
    'operation_id', v_op, 'account_id', p_account, 'amount_cents', p_cents));

  return v_result;
end $$;

--
-- Name: sv_reverse_settlement_for_sale(uuid, uuid, uuid, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.sv_reverse_settlement_for_sale(p_business uuid, p_sale uuid, p_reversal_sale_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_tender public.checkout_sv_tenders%rowtype;
  v_res jsonb;
  v_key uuid;
begin
  select * into v_tender from public.checkout_sv_tenders
   where business_id = p_business and sale_id = p_sale and status = 'consumed';
  if not found then
    return null;   -- non-sv sale: nothing to restore (the ONLY reachable path in production)
  end if;

  -- Serialize on the account (re-entrant with the core's own lock) so a concurrent Door-B settlement
  -- reversal of the same spend is one-winner: marker-check + restore + marker-write is atomic here.
  perform pg_advisory_xact_lock(hashtextextended('v63:sv_acct:' || p_business::text || ':' || v_tender.account_id::text, 0));

  if exists (select 1 from public.checkout_sv_tender_reversals rv
              where rv.business_id = p_business and rv.tender_id = v_tender.id) then
    -- already reversed via the settlement door: SV restored + §10 nets it; do not double-restore.
    return jsonb_build_object('status', 'already_reversed', 'tender_id', v_tender.id,
      'spend_operation_id', v_tender.spend_operation_id);
  end if;

  v_key := md5('v68b:sale_settlement_reversal:' || v_tender.id::text)::uuid;
  v_res := app.sv_reverse_spend_core(p_business, v_tender.spend_operation_id, v_key);
  perform app.sv_record_settlement_reversal(
    p_business, v_tender.spend_operation_id, v_res, 'sale_reversal', p_reversal_sale_id, p_reason);
  return v_res;
end $$;

--
-- Name: sv_reverse_spend_core(uuid, uuid, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.sv_reverse_spend_core(p_business uuid, p_spend_operation uuid, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_hash text;
  v_existing public.sv_operations%rowtype;
  v_op uuid := gen_random_uuid();
  v_account uuid;
  v_client uuid;
  v_spend_type text;
  v_state text;
  v_biz_synth boolean;
  v_client_synth boolean;
  v_biz_currency text;
  v_restored jsonb := '[]'::jsonb;
  v_restored_total bigint := 0;
  v_reexpired_total bigint := 0;
  m record;
  v_amt bigint;
  v_expiry timestamptz;
  v_reexpired boolean;
  v_result jsonb;
begin
  -- HARD SAFETY GATE (v63): value only moves when stored value is the authority for this business.
  if coalesce((select state from public.sv_authority
                where business_id = p_business and asset = 'stored_value'), 'unbuilt') <> 'live' then
    raise exception 'sv_not_live: stored value is not the authority for this business' using errcode = '22023';
  end if;

  -- PAUSE GATE (v64 family mapping): a reversal of a spend is a redeem-side correction, so an active
  -- 'all' or 'redeem' sv_pause blocks it.
  if app.sv_pause_active(p_business, 'stored_value', 'redeem') then
    raise exception 'sv_paused: stored-value redemptions are paused' using errcode = '22023';
  end if;
  if p_idempotency_key is null then
    raise exception 'a stored-value reverse idempotency key is required' using errcode = '22023';
  end if;

  -- The spend operation must exist, be a 'spend', and belong to this business.
  select o.operation_type into v_spend_type from public.sv_operations o
   where o.id = p_spend_operation and o.business_id = p_business;
  if v_spend_type is null then
    raise exception 'stored-value spend operation not found in this business' using errcode = '22023';
  end if;
  if v_spend_type <> 'spend' then
    raise exception 'stored-value reverse target is not a spend operation' using errcode = '22023';
  end if;

  select account_id into v_account from public.sv_lot_movements
   where business_id = p_business and operation_id = p_spend_operation and kind = 'spend'
   order by id limit 1;
  if v_account is null then
    raise exception 'stored-value spend operation wrote no spend movements to reverse' using errcode = '22023';
  end if;

  -- SYNTHETIC/LIVE COHERENCE (v66): a synthetic entity may never transact on a live business.
  select a.client_id into v_client from public.sv_accounts a
   where a.id = v_account and a.business_id = p_business;
  select b.is_synthetic, b.currency into v_biz_synth, v_biz_currency
    from public.businesses b where b.id = p_business;
  select c.is_synthetic into v_client_synth from public.clients c
   where c.id = v_client and c.business_id = p_business;
  if coalesce(v_biz_synth, false) or coalesce(v_client_synth, false) then
    raise exception 'a synthetic entity cannot transact on a live business' using errcode = '22023';
  end if;
  -- CURRENCY: the business must carry a valid three-letter currency (restitution restores the exact
  -- lots, which are denominated in the business currency; there is no cross-currency conversion).
  if btrim(coalesce(v_biz_currency, '')) !~ '^[A-Za-z]{3}$' then
    raise exception 'currency_missing: this business has no valid three-letter currency configured'
      using errcode = '22023';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('v63:sv_acct:' || p_business::text || ':' || v_account::text, 0));
  perform pg_advisory_xact_lock(hashtextextended('v63:sv_reverse:' || p_business::text || ':' || p_idempotency_key::text, 0));

  select * into v_existing from public.sv_operations o
   where o.business_id = p_business and o.operation_type = 'reverse' and o.idempotency_key = p_idempotency_key
   for update;
  v_hash := app.ps1b_sha256(jsonb_build_object(
    'op', 'reverse', 'business_id', p_business, 'spend_operation_id', p_spend_operation)::text);
  if found then
    if v_existing.request_hash <> v_hash then
      raise exception 'idempotency key conflicts with a different stored-value reverse' using errcode = '22023';
    end if;
    return v_existing.result;   -- same key -> idempotent replay
  end if;

  -- BOUND: a spend op is reversed at most once. Any prior reverse of THIS spend op (under a
  -- different key) is over-reversal -> fail.
  if exists (
    select 1 from public.sv_operations o
     where o.business_id = p_business and o.operation_type = 'reverse'
       and o.result->>'spend_operation_id' = p_spend_operation::text) then
    raise exception 'stored-value spend operation is already reversed (over-reversal refused)' using errcode = '22023';
  end if;

  -- CHARGEBACK INTERACTION (contract §4): if ANY source lot of this spend belongs to a charged-back
  -- top-up, the funding was clawed back by the bank; restoring it would resurrect voided value.
  -- Fail CLOSED (the same choice v68a's sv_correct_lot makes for a charged-back lot).
  if exists (
    select 1
      from public.sv_lot_movements mv
      join public.sv_lots l on l.id = mv.lot_id and l.business_id = mv.business_id
      join public.sv_chargebacks c on c.business_id = l.business_id and c.topup_operation_id = l.operation_id
     where mv.business_id = p_business and mv.operation_id = p_spend_operation and mv.kind = 'spend') then
    raise exception 'sv_settlement_charged_back: a source top-up of this spend has been charged back; reversing would resurrect clawed-back value'
      using errcode = '22023';
  end if;

  -- TOCTOU RE-VALIDATION (v66/v67/v68a): re-read authority + pause under the locks so a concurrent
  -- transition or pause committed since the early checks cannot slip a restitution through.
  select coalesce(state, 'unbuilt') into v_state from public.sv_authority
   where business_id = p_business and asset = 'stored_value';
  if coalesce(v_state, 'unbuilt') <> 'live' then
    raise exception 'sv_not_live: stored value is not the authority for this business' using errcode = '22023';
  end if;
  if app.sv_pause_active(p_business, 'stored_value', 'redeem') then
    raise exception 'sv_paused: stored-value redemptions are paused' using errcode = '22023';
  end if;

  -- Compute the restore-then-expire plan FIRST (sv_operations is append-only/immutable, so the op
  -- row must be inserted ONCE with its final result before the movements it anchors).
  for m in
    select mv.lot_id, mv.cents
      from public.sv_lot_movements mv
     where mv.business_id = p_business and mv.operation_id = p_spend_operation and mv.kind = 'spend'
     order by mv.id
  loop
    v_amt := -m.cents;   -- positive restore amount
    if v_amt <= 0 then continue; end if;
    v_restored_total := v_restored_total + v_amt;
    select expiry_key into v_expiry from public.sv_lots where id = m.lot_id and business_id = p_business;
    v_reexpired := (v_expiry is not null and v_expiry <= now());
    if v_reexpired then
      v_reexpired_total := v_reexpired_total + v_amt;
    end if;
    v_restored := v_restored || jsonb_build_array(jsonb_build_object(
      'lot_id', m.lot_id, 'restored_cents', v_amt::int, 're_expired', v_reexpired));
  end loop;

  v_result := jsonb_build_object(
    'status', 'ok', 'operation_id', v_op, 'spend_operation_id', p_spend_operation, 'account_id', v_account,
    'restored_cents', v_restored_total::int, 're_expired_cents', v_reexpired_total::int,
    'net_restored_cents', (v_restored_total - v_reexpired_total)::int, 'restored', v_restored);

  insert into public.sv_operations(id, business_id, operation_type, idempotency_key, request_hash, actor, result)
  values (v_op, p_business, 'reverse', p_idempotency_key, v_hash, v_actor, v_result);

  -- Apply: a 'reversal' (+) per lot, immediately followed by a '-expiry' when the restored lot is now
  -- past its expiry_key (restore-then-expire; an expired lot is never silently resurrected).
  for m in
    select mv.lot_id, mv.cents
      from public.sv_lot_movements mv
     where mv.business_id = p_business and mv.operation_id = p_spend_operation and mv.kind = 'spend'
     order by mv.id
  loop
    v_amt := -m.cents;
    if v_amt <= 0 then continue; end if;
    insert into public.sv_lot_movements(business_id, account_id, lot_id, operation_id, kind, cents)
    values (p_business, v_account, m.lot_id, v_op, 'reversal', v_amt::int);
    select expiry_key into v_expiry from public.sv_lots where id = m.lot_id and business_id = p_business;
    if v_expiry is not null and v_expiry <= now() then
      insert into public.sv_lot_movements(business_id, account_id, lot_id, operation_id, kind, cents)
      values (p_business, v_account, m.lot_id, v_op, 'expiry', (-v_amt)::int);
    end if;
  end loop;

  insert into public.audit_log(business_id, actor, action, entity, entity_id, detail)
  values (p_business, v_actor, 'SV_REVERSE_SPEND', 'sv_accounts', v_account, jsonb_build_object(
    'operation_id', v_op, 'spend_operation_id', p_spend_operation,
    'restored_cents', v_restored_total::int, 're_expired_cents', v_reexpired_total::int));

  return v_result;
end $_$;

--
-- Name: sv_spend_core(uuid, uuid, integer, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.sv_spend_core(p_business uuid, p_account uuid, p_cents integer, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_hash text;
  v_existing public.sv_operations%rowtype;
  v_op uuid := gen_random_uuid();
  v_available integer;
  v_plan jsonb;
  v_entry jsonb;
  v_result jsonb;
begin
  if coalesce((select state from public.sv_authority
                where business_id = p_business and asset = 'stored_value'), 'unbuilt') <> 'live' then
    raise exception 'sv_not_live: stored value is not the authority for this business' using errcode = '22023';
  end if;

  -- Redeem pause gate (an active 'all' or 'redeem' sv_pause blocks spends/reservations).
  if app.sv_pause_active(p_business, 'stored_value', 'redeem') then
    raise exception 'sv_paused: stored-value redemptions are paused' using errcode = '22023';
  end if;
  if p_idempotency_key is null then
    raise exception 'a stored-value spend idempotency key is required' using errcode = '22023';
  end if;
  if p_cents is null or p_cents < 1 then
    raise exception 'a stored-value spend must be a whole number of at least 1 cent' using errcode = '22023';
  end if;
  if not exists (select 1 from public.sv_accounts a where a.id = p_account and a.business_id = p_business) then
    raise exception 'stored-value account does not belong to this business' using errcode = '22023';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('v63:sv_acct:' || p_business::text || ':' || p_account::text, 0));
  perform pg_advisory_xact_lock(hashtextextended('v63:sv_spend:' || p_business::text || ':' || p_idempotency_key::text, 0));

  select * into v_existing from public.sv_operations o
   where o.business_id = p_business and o.operation_type = 'spend' and o.idempotency_key = p_idempotency_key
   for update;
  v_hash := app.ps1b_sha256(jsonb_build_object(
    'op', 'spend', 'business_id', p_business, 'account_id', p_account, 'cents', p_cents)::text);
  if found then
    if v_existing.request_hash <> v_hash then
      raise exception 'idempotency key conflicts with a different stored-value spend' using errcode = '22023';
    end if;
    return v_existing.result;   -- duplicate spend, same key -> ONE effect, replayed result
  end if;

  -- Deterministic FEFO row locks over the accounts lot set (one-winner; the fresh READ COMMITTED
  -- snapshot after the advisory lock + these locks sees a concurrent winning transaction committed movements).
  perform 1 from public.sv_lots l
   where l.business_id = p_business and l.account_id = p_account
   order by l.expiry_key asc nulls last, l.earned_seq asc, l.id asc
   for update;

  v_available := app.sv_available_balance(p_business, p_account);
  if p_cents > v_available then
    raise exception 'insufficient stored value to spend (% requested, % available)', p_cents, v_available
      using errcode = '22023';   -- refuse BEFORE any write: no partial movement
  end if;

  v_plan := app.sv_allocate_spend(p_business, p_account, p_cents);
  if (v_plan->>'ok')::boolean is not true then
    raise exception 'stored-value allocation failed: %', coalesce(v_plan->>'reason', 'unknown') using errcode = '22023';
  end if;

  v_result := jsonb_build_object(
    'status', 'ok', 'operation_id', v_op, 'account_id', p_account, 'spend_cents', p_cents,
    'paid_draw_cents', (v_plan->>'paid_draw')::int, 'bonus_draw_cents', (v_plan->>'bonus_draw')::int,
    'plan', v_plan->'plan', 'available_after_cents', v_available - p_cents);

  insert into public.sv_operations(id, business_id, operation_type, idempotency_key, request_hash, actor, result)
  values (v_op, p_business, 'spend', p_idempotency_key, v_hash, v_actor, v_result);
  for v_entry in select * from jsonb_array_elements(v_plan->'plan') loop
    insert into public.sv_lot_movements(business_id, account_id, lot_id, operation_id, kind, cents)
    values (p_business, p_account, (v_entry->>'lot_id')::uuid, v_op, 'spend', (v_entry->>'cents')::int);
  end loop;
  insert into public.audit_log(business_id, actor, action, entity, entity_id, detail)
  values (p_business, v_actor, 'SV_SPEND', 'sv_accounts', p_account, jsonb_build_object(
    'operation_id', v_op, 'spend_cents', p_cents,
    'paid_draw_cents', (v_plan->>'paid_draw')::int, 'bonus_draw_cents', (v_plan->>'bonus_draw')::int));

  return v_result;
end $$;

--
-- Name: sv_topup_count(uuid, uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.sv_topup_count(p_business uuid, p_account uuid, p_plan uuid, p_since timestamp with time zone) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  select count(distinct o.id)::integer
    from public.sv_operations o
    join public.sv_lots l on l.operation_id = o.id and l.business_id = o.business_id
   where o.business_id = p_business and o.operation_type = 'topup' and l.account_id = p_account
     and l.plan_version_id in (select id from public.sv_plan_versions where plan_id = p_plan and business_id = p_business)
     and (p_since is null or o.created_at >= p_since)
$$;

--
-- Name: sv_topup_projection(uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.sv_topup_projection(p_business uuid, p_branch uuid, p_client uuid, p_plan_version uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  pv public.sv_plan_versions%rowtype; v_plan_active boolean; v_state text; v_biz_synth boolean; v_client_synth boolean;
  v_account uuid; v_outstanding integer := 0; v_blockers text[] := '{}'; v_window_used integer := 0; v_lifetime_used integer := 0;
  v_currency text; v_total integer;
begin
  select * into pv from public.sv_plan_versions where id = p_plan_version and business_id = p_business;
  if not found then return jsonb_build_object('ok', false, 'blockers', to_jsonb(array['plan version not in this business'])); end if;
  select active into v_plan_active from public.sv_plans where id = pv.plan_id and business_id = p_business;
  v_total := pv.price_cents + pv.bonus_cents;
  select coalesce(state,'unbuilt') into v_state from public.sv_authority where business_id = p_business and asset = 'stored_value';
  v_state := coalesce(v_state,'unbuilt');
  select b.is_synthetic, b.currency into v_biz_synth, v_currency from public.businesses b where b.id = p_business;
  select c.is_synthetic into v_client_synth from public.clients c where c.id = p_client and c.business_id = p_business;

  if not coalesce(v_plan_active,false) then v_blockers := array_append(v_blockers,'plan is retired'); end if;
  if pv.effective_at is not null and pv.effective_at > now() then v_blockers := array_append(v_blockers,'plan version is not yet effective'); end if;
  if p_plan_version is distinct from app.current_sellable_sv_version(p_business, pv.plan_id) then v_blockers := array_append(v_blockers,'not the current sellable version'); end if;
  if pv.eligible_branch_ids is not null and not (p_branch = any(pv.eligible_branch_ids)) then v_blockers := array_append(v_blockers,'branch not eligible for this plan'); end if;
  if pv.topup_purchase_earns_points then v_blockers := array_append(v_blockers,'points-on-topup is not yet supported'); end if;
  if v_state = 'unbuilt' then v_blockers := array_append(v_blockers,'stored value is not ready for top-ups');
  elsif v_state in ('shadow_testing','ready_for_cutover') then
    if not (coalesce(v_biz_synth,false) and coalesce(v_client_synth,false)) then v_blockers := array_append(v_blockers,'only synthetic test top-ups are permitted in this authority state'); end if;
  elsif v_state = 'live' then
    if coalesce(v_biz_synth,false) or coalesce(v_client_synth,false) then v_blockers := array_append(v_blockers,'a synthetic entity cannot transact on a live business'); end if;
  else v_blockers := array_append(v_blockers,'stored value is '||v_state); end if;

  select id into v_account from public.sv_accounts where business_id = p_business and client_id = p_client and asset = 'stored_value';
  if v_account is not null then
    v_outstanding := app.sv_total_outstanding(p_business, v_account);
    if pv.purchase_window_days is not null then
      v_window_used := app.sv_topup_count(p_business, v_account, pv.plan_id, now() - (pv.purchase_window_days||' days')::interval);
    end if;
    v_lifetime_used := app.sv_topup_count(p_business, v_account, pv.plan_id, null);
  end if;
  if pv.max_balance_cents is not null and v_outstanding + v_total > pv.max_balance_cents then v_blockers := array_append(v_blockers,'maximum balance would be exceeded'); end if;
  if pv.purchase_window_days is not null and pv.purchase_max_in_window is not null and v_window_used >= pv.purchase_max_in_window then v_blockers := array_append(v_blockers,'purchase frequency limit reached'); end if;
  if pv.purchase_lifetime_cap is not null and v_lifetime_used >= pv.purchase_lifetime_cap then v_blockers := array_append(v_blockers,'lifetime purchase cap reached'); end if;

  return jsonb_build_object(
    'ok', (array_length(v_blockers,1) is null),
    'plan_id', pv.plan_id, 'version_id', pv.id, 'version_no', pv.version_no, 'plan_name', pv.customer_facing_name,
    'price_cents', pv.price_cents, 'bonus_cents', pv.bonus_cents, 'total_usable_cents', v_total,
    'effective_discount_bps', app.sv_plan_effective_discount_bps(pv.price_cents, pv.bonus_cents),
    'paid_expiry_days', pv.paid_expiry_days, 'bonus_expiry_days', pv.bonus_expiry_days,
    'min_spend_cents', pv.min_spend_cents, 'stacking_policy', pv.stacking_policy, 'max_balance_cents', pv.max_balance_cents,
    'purchase_window_days', pv.purchase_window_days, 'purchase_max_in_window', pv.purchase_max_in_window,
    'purchase_lifetime_cap', pv.purchase_lifetime_cap, 'refund_policy', pv.refund_policy, 'spend_order', pv.spend_order,
    'topup_purchase_earns_points', pv.topup_purchase_earns_points, 'customer_terms', pv.customer_terms,
    'eligible_branch_ids', to_jsonb(pv.eligible_branch_ids), 'eligible_service_ids', to_jsonb(pv.eligible_service_ids),
    'currency', coalesce(v_currency,'SGD'),
    'account_outstanding_cents', v_outstanding, 'projected_account_total_cents', v_outstanding + v_total,
    'window_used', v_window_used, 'window_remaining', case when pv.purchase_max_in_window is null then null else greatest(pv.purchase_max_in_window - v_window_used, 0) end,
    'lifetime_used', v_lifetime_used, 'lifetime_remaining', case when pv.purchase_lifetime_cap is null then null else greatest(pv.purchase_lifetime_cap - v_lifetime_used, 0) end,
    'authority_state', v_state, 'spendable', (v_state = 'live'),
    'reference_required', true, 'blockers', to_jsonb(v_blockers));
end $$;

--
-- Name: sv_total_outstanding(uuid, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.sv_total_outstanding(p_business uuid, p_account uuid) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  select coalesce((select sum(m.cents) from public.sv_lot_movements m
                    where m.business_id = p_business and m.account_id = p_account), 0)::integer
$$;

--
-- Name: sv_write_shadow_evaluation(uuid, uuid, text, text, jsonb, integer, text, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.sv_write_shadow_evaluation(p_business uuid, p_account uuid, p_asset text, p_operation_type text, p_proposed_movements jsonb, p_proposed_total_cents integer, p_legacy_ref text, p_note text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_id uuid := gen_random_uuid();
begin
  insert into public.sv_shadow_evaluations(
    id, business_id, account_id, asset, operation_type,
    proposed_movements, proposed_total_cents, legacy_ref, note)
  values (v_id, p_business, p_account, coalesce(p_asset, 'stored_value'), p_operation_type,
    coalesce(p_proposed_movements, '[]'::jsonb), coalesce(p_proposed_total_cents, 0), p_legacy_ref, p_note);
  return v_id;
end $$;

--
-- Name: sync_business_programmes_v308(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.sync_business_programmes_v308(p_business uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if p_business is null then
    return;
  end if;

  -- LOCK, THEN PROBE — one statement doing two jobs.
  --
  -- (a) Existence. A cascade delete of a business removes its legacy rows AFTER the parent row is
  --     gone, so the DELETE triggers below can call this for a business that no longer exists. There
  --     is nothing to project onto (the spine rows cascaded away too) and the insert would violate
  --     the FK, so a missing business is a silent return.
  --
  -- (b) Serialization. FOR UPDATE makes this a per-business mutex around the whole recompute. Two
  --     watched writes to the same business really can run concurrently on different legacy tables:
  --     public.save_referral_program (v41) locks only a staff row, and an owner PATCHing
  --     businesses.points_mode over PostgREST locks only that businesses row — neither excludes the
  --     other. Without this lock the interleaving is:
  --       B updates points_mode and holds; A enables referral, computes BOTH flags from a snapshot
  --       that predates B, then blocks on B's spine row; B commits; A wakes, and its
  --       `where spine.active is distinct from excluded.active` guard now compares A's STALE points
  --       value against B's FRESH row — they differ, so the guard PASSES and A overwrites B's answer
  --       with a pre-B one. The spine stays wrong until the next watched write touches that business.
  --     Taking the lock here moves the wait in front of the computation. Under READ COMMITTED each
  --     statement takes a fresh snapshot, so the recompute below runs after B's commit is visible and
  --     projects the combined state.
  --
  -- Lock order established globally: public.businesses row -> public.business_programmes rows in
  -- kind order. Nothing inverts it — publish_loyalty_config (v55:683) already takes the businesses
  -- row FOR UPDATE before touching loyalty_programs/loyalty_tiers, so the sync its writes trigger
  -- simply re-takes a lock the transaction already holds.
  perform 1 from public.businesses target where target.id = p_business for update;
  if not found then
    return;
  end if;

  insert into public.business_programmes as spine
    (business_id, kind, active, sort, activated_at, deactivated_at)
  select
    p_business,
    model.kind,
    model.running,
    (case model.kind
       when 'points' then 1
       when 'tiers' then 2
       when 'stamps' then 3
       when 'referral' then 4
     end)::smallint,
    case when model.running then now() end,
    null::timestamptz
    from app.business_programmes_v307(p_business) model
  on conflict (business_id, kind) do update
     set active = excluded.active,
         activated_at = case
           when excluded.active and not spine.active then now()
           else spine.activated_at
         end,
         deactivated_at = case
           when spine.active and not excluded.active then now()
           else spine.deactivated_at
         end
   -- A recompute that changes nothing writes nothing: no dead tuple, no timestamp churn, and
   -- calling the sync twice is byte-stable.
   where spine.active is distinct from excluded.active;
end
$$;

--
-- Name: FUNCTION sync_business_programmes_v308(p_business uuid); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.sync_business_programmes_v308(p_business uuid) IS 'v308 W2 legacy->spine recompute, RETIRED AT v314. Its four triggers are dropped and its EXECUTE privilege is revoked from every role including service_role: after the inversion the spine is the AUTHORITY and running this would overwrite an owner''s switches with a value derived from settings. Kept installed, and only installed, because the documented rollback is "re-attach the four triggers and run this once per business" — which discards every post-inversion switch, deliberately and knowingly.';

--
-- Name: tag_ledger_programme_v309(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.tag_ledger_programme_v309() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  -- NEVER override. W5's earn loop supplies programme_id explicitly, once per accruing
  -- programme per sale; recomputing the single-pot answer here would silently collapse that
  -- loop onto one programme.
  if new.programme_id is null then
    new.programme_id := app.resolve_ledger_programme_v309(new.business_id);
  end if;
  return new;
end
$$;

--
-- Name: FUNCTION tag_ledger_programme_v309(); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.tag_ledger_programme_v309() IS 'v309 W3 BEFORE INSERT default, RETIRED AT v313 (W6 increment 1). The triggers that called it on points_ledger and points_batches are dropped. It filled programme_id from a resolver that v314 turns into a lie, so keeping it attached would let a writer that forgot to be explicit be silently tagged into the WRONG pot instead of failing on NOT NULL. The function stays installed and revoked so the rollback is `create trigger`, not `create function`. Every money writer is explicit — V311 suite steps 29-36 are the standing proof.';

