CREATE FUNCTION app.v104_lock_promotion_business(p_business uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    SET lock_timeout TO '5s'
    AS $$
begin
  perform pg_advisory_xact_lock(
    hashtextextended('nestly.v104.promotion:'||p_business::text,0)
  );
exception when lock_not_available then
  raise exception 'Another promotion change for this business is still saving. Wait a moment and try again.'
    using errcode='55P03';
end
$$;

--
-- Name: v104_promotion_copy_write_guard(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v104_promotion_copy_write_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_touches_offer boolean;
begin
  if tg_op='DELETE' then
    v_touches_offer:=old.entity_type='offer';
  else
    v_touches_offer:=new.entity_type='offer'
      or (tg_op='UPDATE' and old.entity_type='offer');
  end if;
  if v_touches_offer
     and coalesce(
       current_setting('app.v104_promotion_copy_write',true),''
     )<>'on'
  then
    raise exception 'promotion_copy_v104_rpc_required'
      using errcode='42501';
  end if;
  if tg_op='DELETE' then return old;end if;
  return new;
end
$$;

