--
-- Name: v109_require_finance(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v109_require_finance(p_business uuid) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if auth.uid() is null or (
    not app.is_super_admin()
    and not app.has_perm(p_business,'view_finance')
  ) then
    raise exception 'finance access required' using errcode='42501';
  end if;
end $$;

--
-- Name: v109_require_finance_scope(uuid, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v109_require_finance_scope(p_business uuid, p_branch uuid) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  perform app.v109_require_finance(p_business);
  if not app.can_see_branch(p_business,p_branch) then
    raise exception 'finance branch is outside actor scope' using errcode='42501';
  end if;
end $$;

--
-- Name: v109_sector_source_availability(uuid, text, integer, timestamp with time zone); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v109_sector_source_availability(p_business uuid, p_sector text, p_minimum_history integer, p_as_of timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_service_history integer:=0;
  v_product_history integer:=0;
  v_membership_history integer:=0;
  v_required integer:=greatest(coalesce(p_minimum_history,1),1);
begin
  if p_as_of is null then
    raise exception 'as-of is required' using errcode='22023';
  end if;

  if p_sector in ('facial','salon','massage') then
    select count(*) into v_service_history
    from (
      select appointment.id
      from public.appointments appointment
      where appointment.business_id=p_business
        and appointment.status='completed'
        and appointment.service_id is not null
        and appointment.created_at<=p_as_of
      union
      select item.sale_id
      from public.sale_items item
      join public.sales sale
        on sale.id=item.sale_id and sale.business_id=item.business_id
      where item.business_id=p_business
        and item.item_type='service' and item.ref_id is not null
        and sale.reversal_of is null and sale.created_at<=p_as_of
        and app.v106_sale_residual_minor(sale.id,p_as_of)>0
    ) observed;
  end if;

  if p_sector='retail' then
    select count(distinct item.sale_id) into v_product_history
    from public.sale_items item
    join public.sales sale
      on sale.id=item.sale_id and sale.business_id=item.business_id
    where item.business_id=p_business
      and item.item_type='retail' and item.product_id is not null
      and sale.reversal_of is null and sale.created_at<=p_as_of
      and app.v106_sale_residual_minor(sale.id,p_as_of)>0;
  end if;

  if p_sector='fitness' then
    select count(*) into v_membership_history
    from public.memberships membership
    where membership.business_id=p_business
      and membership.created_at<=p_as_of
      and membership.status in (
        'active','paused','cancel_at_period_end','cancelled'
      );
  end if;

  return jsonb_build_object(
    'as_of',p_as_of,
    'minimum_history_required',v_required,
    'service_cadence',case
      when p_sector in ('facial','salon','massage')
        then v_service_history>=v_required else null end,
    'service_linked_history_count',case
      when p_sector in ('facial','salon','massage')
        then v_service_history else null end,
    'product_cycle',case
      when p_sector='retail' then v_product_history>=v_required else null end,
    'product_linked_history_count',case
      when p_sector='retail' then v_product_history else null end,
    'membership_state',case
      when p_sector='fitness' then v_membership_history>0 else null end,
    'membership_history_count',case
      when p_sector='fitness' then v_membership_history else null end,
    'specialized_sector_policy',p_sector<>'other'
  );
end $$;

--
-- Name: v110_guard_delivery_update(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v110_guard_delivery_update() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if tg_op = 'DELETE' then
    raise exception 'growth deliveries cannot be deleted' using errcode = '23000';
  end if;
  if current_setting('app.growth_delivery_v110_transition', true)
       is distinct from 'on' then
    raise exception 'growth delivery transitions require the lifecycle service'
      using errcode = '42501';
  end if;
  if new.id is distinct from old.id
     or new.execution_id is distinct from old.execution_id
     or new.execution_member_id is distinct from old.execution_member_id
     or new.business_id is distinct from old.business_id
     or new.client_id is distinct from old.client_id
     or new.identity_id is distinct from old.identity_id
     or new.link_id is distinct from old.link_id
     or new.assignment is distinct from old.assignment
     or new.channel is distinct from old.channel
     or new.title is distinct from old.title
     or new.body is distinct from old.body
     or new.estimated_cost_cents is distinct from old.estimated_cost_cents
     or new.created_at is distinct from old.created_at then
    raise exception 'growth delivery identity and governed content are immutable'
      using errcode = '23000';
  end if;
  if not (
    (old.delivery_status in ('queued', 'scheduled')
      and new.delivery_status in (
        'queued', 'scheduled', 'delivering', 'cancelled'
      ))
    or (old.delivery_status = 'delivering'
      and new.delivery_status in ('delivering', 'delivered', 'failed', 'cancelled'))
    or (old.delivery_status = 'failed'
      and new.delivery_status in ('failed', 'queued', 'cancelled'))
    or old.delivery_status = new.delivery_status
  ) then
    raise exception 'invalid growth delivery transition: % -> %',
      old.delivery_status, new.delivery_status using errcode = '22023';
  end if;
  return new;
end $$;

--
-- Name: v110_guard_dispatch_update(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v110_guard_dispatch_update() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if tg_op = 'DELETE' then
    raise exception 'growth dispatches cannot be deleted' using errcode = '23000';
  end if;
  if current_setting('app.growth_delivery_v110_transition', true)
       is distinct from 'on' then
    raise exception 'growth dispatch transitions require the lifecycle service'
      using errcode = '42501';
  end if;
  if new.id is distinct from old.id
     or new.delivery_id is distinct from old.delivery_id
     or new.execution_id is distinct from old.execution_id
     or new.business_id is distinct from old.business_id
     or new.branch_id is distinct from old.branch_id
     or new.provider is distinct from old.provider
     or new.created_at is distinct from old.created_at then
    raise exception 'growth dispatch identity is immutable' using errcode = '23000';
  end if;
  return new;
end $$;

--
-- Name: v110_next_allowed_at(text, time without time zone, time without time zone, timestamp with time zone); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v110_next_allowed_at(p_timezone text, p_quiet_start time without time zone, p_quiet_end time without time zone, p_from timestamp with time zone DEFAULT statement_timestamp()) RETURNS timestamp with time zone
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_candidate timestamptz := p_from;
  v_step integer;
begin
  if not app.c46_in_quiet_hours(
    p_timezone, p_quiet_start, p_quiet_end, p_from
  ) then
    return p_from;
  end if;
  for v_step in 1..288 loop
    v_candidate := p_from + make_interval(mins => v_step * 5);
    if not app.c46_in_quiet_hours(
      p_timezone, p_quiet_start, p_quiet_end, v_candidate
    ) then
      return v_candidate;
    end if;
  end loop;
  return p_from + interval '24 hours';
end $$;

--
-- Name: v110_prepare_delivery_insert(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v110_prepare_delivery_insert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_execution public.growth_executions_v108%rowtype;
begin
  if new.assignment = 'treatment'
     and (
       new.delivery_status = 'delivered'
       or (
         new.delivery_status = 'suppressed'
         and new.suppression_reason = 'quiet_hours'
       )
     ) then
    select * into strict v_execution
    from public.growth_executions_v108
    where id = new.execution_id and business_id = new.business_id;
    new.delivery_status := case
      when new.suppression_reason = 'quiet_hours' then 'scheduled'
      else 'queued'
    end;
    new.suppression_reason := null;
    new.title := v_execution.governed_copy ->> 'title';
    new.body := v_execution.governed_copy ->> 'body';
    new.estimated_cost_cents := v_execution.offer_value_cents;
    new.delivered_at := null;
  end if;
  return new;
end $$;

--
-- Name: v110_register_delivery(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v110_register_delivery() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_dispatch uuid;
  v_execution public.growth_executions_v108%rowtype;
  v_preference public.customer_notification_preferences%rowtype;
  v_scheduled_for timestamptz := statement_timestamp();
  v_event_key uuid;
  v_hash text;
begin
  select * into strict v_execution
  from public.growth_executions_v108
  where id = new.execution_id and business_id = new.business_id;
  if new.delivery_status = 'scheduled' then
    select * into v_preference
    from public.customer_notification_preferences preference
    where preference.business_id = new.business_id
      and preference.client_id = new.client_id
      and preference.link_id = new.link_id
      and preference.channel = 'in_app'
      and preference.topic = 'marketing'
    order by preference.updated_at desc, preference.id
    limit 1;
    v_scheduled_for := app.v110_next_allowed_at(
      v_preference.quiet_hours_timezone,
      v_preference.quiet_hours_start,
      v_preference.quiet_hours_end,
      statement_timestamp()
    );
  end if;
  insert into public.growth_delivery_dispatches_v110(
    delivery_id, execution_id, business_id, branch_id,
    lifecycle_status, scheduled_for, next_attempt_at
  ) values (
    new.id, new.execution_id, new.business_id, v_execution.branch_id,
    new.delivery_status, v_scheduled_for, v_scheduled_for
  ) returning id into v_dispatch;
  v_event_key := extensions.uuid_generate_v5(new.id, 'v110-created');
  v_hash := app.v110_request_hash(jsonb_build_object(
    'delivery_id', new.id, 'to_status', new.delivery_status,
    'scheduled_for', v_scheduled_for
  ));
  insert into public.growth_delivery_state_events_v110(
    dispatch_id, delivery_id, execution_id, business_id,
    from_status, to_status, reason_code, idempotency_key,
    request_hash, detail
  ) values (
    v_dispatch, new.id, new.execution_id, new.business_id,
    null, new.delivery_status, new.suppression_reason, v_event_key,
    v_hash, jsonb_build_object('scheduled_for', v_scheduled_for)
  );
  return new;
end $$;

--
-- Name: v110_request_hash(jsonb); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v110_request_hash(p_value jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  select encode(
    extensions.digest(convert_to(p_value::text, 'UTF8'), 'sha256'),
    'hex'
  )
$$;

--
-- Name: growth_delivery_dispatches_v110; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.growth_delivery_dispatches_v110 (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    delivery_id uuid NOT NULL,
    execution_id uuid NOT NULL,
    business_id uuid NOT NULL,
    branch_id uuid,
    provider text DEFAULT 'in_app'::text NOT NULL,
    lifecycle_status text NOT NULL,
    scheduled_for timestamp with time zone DEFAULT statement_timestamp() NOT NULL,
    next_attempt_at timestamp with time zone DEFAULT statement_timestamp() NOT NULL,
    attempt_count integer DEFAULT 0 NOT NULL,
    claimed_by text,
    claimed_at timestamp with time zone,
    provider_message_id text,
    delivered_at timestamp with time zone,
    failure_code text,
    cancelled_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT growth_delivery_dispatches_v110_attempt_count_check CHECK (((attempt_count >= 0) AND (attempt_count <= 5))),
    CONSTRAINT growth_delivery_dispatches_v110_lifecycle_status_check CHECK ((lifecycle_status = ANY (ARRAY['queued'::text, 'scheduled'::text, 'delivering'::text, 'delivered'::text, 'held_out'::text, 'suppressed'::text, 'failed'::text, 'cancelled'::text]))),
    CONSTRAINT growth_delivery_dispatches_v110_provider_check CHECK ((provider ~ '^[a-z][a-z0-9_]{1,39}$'::text)),
    CONSTRAINT growth_delivery_dispatches_v110_shape_check CHECK ((((lifecycle_status = ANY (ARRAY['queued'::text, 'scheduled'::text])) AND (claimed_by IS NULL) AND (claimed_at IS NULL) AND (delivered_at IS NULL) AND (cancelled_at IS NULL)) OR ((lifecycle_status = 'delivering'::text) AND (claimed_by IS NOT NULL) AND (claimed_at IS NOT NULL) AND (delivered_at IS NULL) AND (cancelled_at IS NULL)) OR ((lifecycle_status = 'delivered'::text) AND (claimed_by IS NOT NULL) AND (claimed_at IS NOT NULL) AND (delivered_at IS NOT NULL) AND (provider_message_id IS NOT NULL) AND (cancelled_at IS NULL)) OR ((lifecycle_status = 'failed'::text) AND (claimed_by IS NOT NULL) AND (claimed_at IS NOT NULL) AND (delivered_at IS NULL) AND (failure_code IS NOT NULL) AND (cancelled_at IS NULL)) OR ((lifecycle_status = 'cancelled'::text) AND (delivered_at IS NULL) AND (failure_code IS NOT NULL) AND (cancelled_at IS NOT NULL)) OR ((lifecycle_status = ANY (ARRAY['held_out'::text, 'suppressed'::text])) AND (claimed_by IS NULL) AND (claimed_at IS NULL) AND (delivered_at IS NULL) AND (cancelled_at IS NULL)))),
    CONSTRAINT growth_delivery_dispatches_v112_retry_bound_check CHECK (((lifecycle_status <> ALL (ARRAY['queued'::text, 'scheduled'::text])) OR (attempt_count < 5)))
);

--
-- Name: TABLE growth_delivery_dispatches_v110; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.growth_delivery_dispatches_v110 IS 'Provider-neutral queued delivery lifecycle. Entitlements issue only after a verified delivered callback.';

--
-- Name: v110_transition_delivery(uuid, text, text, text, uuid, jsonb); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v110_transition_delivery(p_dispatch uuid, p_to_status text, p_reason_code text, p_provider_message_id text, p_idempotency_key uuid, p_detail jsonb DEFAULT '{}'::jsonb) RETURNS public.growth_delivery_dispatches_v110
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_identity text;
  v_hash text;
  v_receipt jsonb;
  v_dispatch public.growth_delivery_dispatches_v110%rowtype;
  v_backoff jsonb;
  v_detail jsonb := coalesce(p_detail, '{}'::jsonb);
  v_now timestamptz;
  v_next_attempt_at timestamptz;
begin
  if p_idempotency_key is null
     or jsonb_typeof(v_detail) <> 'object' then
    raise exception 'valid transition idempotency and detail are required'
      using errcode = '22023';
  end if;
  v_identity := app.v112_hash(jsonb_build_object(
    'operation', 'v110_transition_delivery',
    'dispatch_id', p_dispatch, 'idempotency_key', p_idempotency_key
  ));
  v_hash := app.v112_hash(jsonb_build_object(
    'dispatch_id', p_dispatch, 'to_status', p_to_status,
    'reason_code', p_reason_code,
    'provider_message_id', p_provider_message_id,
    'detail', v_detail
  ));
  perform app.v112_lock_dispatch(p_dispatch);
  perform app.v112_lock_pair(
    'v112-v110-transition-request:' || v_identity,
    'v112-v110-transition-request:' || v_identity
  );
  v_receipt := app.v112_get_receipt(v_identity, v_hash);
  if v_receipt is not null then
    return jsonb_populate_record(
      null::public.growth_delivery_dispatches_v110, v_receipt
    );
  end if;
  select * into strict v_dispatch
  from public.growth_delivery_dispatches_v110
  where id = p_dispatch;
  if v_dispatch.lifecycle_status = 'failed' and p_to_status = 'queued' then
    v_now := clock_timestamp();
    v_backoff := app.v112_delivery_backoff(v_dispatch.attempt_count, v_now);
    v_next_attempt_at := v_now
      + make_interval(secs => (v_backoff ->> 'delay_seconds')::integer);
    v_detail := v_detail || jsonb_build_object(
      'v112_backoff', v_backoff || jsonb_build_object(
        'computed_at', v_now,
        'next_attempt_at', v_next_attempt_at
      )
    );
  end if;
  v_dispatch := app.v110_transition_delivery_v112_inner(
    p_dispatch, p_to_status, p_reason_code, p_provider_message_id,
    p_idempotency_key, v_detail
  );
  if v_next_attempt_at is not null then
    perform set_config('app.growth_delivery_v110_transition', 'on', true);
    update public.growth_delivery_dispatches_v110
    set next_attempt_at = v_next_attempt_at,
        updated_at = v_now
    where id = p_dispatch
    returning * into v_dispatch;
  end if;
  v_receipt := to_jsonb(v_dispatch);
  perform app.v112_put_receipt(
    v_identity, 'v110_transition_delivery', v_hash,
    jsonb_build_object(
      'dispatch_id', p_dispatch, 'idempotency_key', p_idempotency_key,
      'to_status', p_to_status
    ),
    v_receipt
  );
  return v_dispatch;
end $$;

--
-- Name: v110_transition_delivery_v112_inner(uuid, text, text, text, uuid, jsonb); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v110_transition_delivery_v112_inner(p_dispatch uuid, p_to_status text, p_reason_code text, p_provider_message_id text, p_idempotency_key uuid, p_detail jsonb DEFAULT '{}'::jsonb) RETURNS public.growth_delivery_dispatches_v110
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  perform app.v112_lock_dispatch(p_dispatch);
  return app.v110_transition_delivery_v112_unsafe_row_inner(
    p_dispatch, p_to_status, p_reason_code, p_provider_message_id,
    p_idempotency_key, p_detail
  );
end $$;

--
-- Name: v110_transition_delivery_v112_unsafe_row_inner(uuid, text, text, text, uuid, jsonb); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v110_transition_delivery_v112_unsafe_row_inner(p_dispatch uuid, p_to_status text, p_reason_code text, p_provider_message_id text, p_idempotency_key uuid, p_detail jsonb DEFAULT '{}'::jsonb) RETURNS public.growth_delivery_dispatches_v110
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_dispatch public.growth_delivery_dispatches_v110%rowtype;
  v_existing public.growth_delivery_state_events_v110%rowtype;
  v_hash text;
  v_from_status text;
  v_now timestamptz := statement_timestamp();
begin
  if p_idempotency_key is null
     or jsonb_typeof(coalesce(p_detail, '{}'::jsonb)) <> 'object' then
    raise exception 'valid transition idempotency and detail are required'
      using errcode = '22023';
  end if;
  v_hash := app.v110_request_hash(jsonb_build_object(
    'dispatch_id', p_dispatch, 'to_status', p_to_status,
    'reason_code', p_reason_code,
    'provider_message_id', p_provider_message_id,
    'detail', coalesce(p_detail, '{}'::jsonb)
  ));
  select * into v_existing
  from public.growth_delivery_state_events_v110
  where dispatch_id = p_dispatch and idempotency_key = p_idempotency_key;
  if found then
    if v_existing.request_hash <> v_hash then
      raise exception 'idempotency key reused with a different delivery transition'
        using errcode = '23505';
    end if;
    select * into strict v_dispatch
    from public.growth_delivery_dispatches_v110 where id = p_dispatch;
    return v_dispatch;
  end if;
  select * into strict v_dispatch
  from public.growth_delivery_dispatches_v110
  where id = p_dispatch for update;
  v_from_status := v_dispatch.lifecycle_status;
  if not (
    (v_from_status in ('queued', 'scheduled')
      and p_to_status in ('queued', 'scheduled', 'delivering', 'cancelled'))
    or (v_from_status = 'delivering'
      and p_to_status in ('delivering', 'delivered', 'failed', 'cancelled'))
    or (v_from_status = 'failed'
      and p_to_status in ('failed', 'queued', 'cancelled'))
    or v_from_status = p_to_status
  ) then
    raise exception 'invalid growth dispatch transition: % -> %',
      v_from_status, p_to_status using errcode = '22023';
  end if;
  perform set_config('app.growth_delivery_v110_transition', 'on', true);
  update public.growth_delivery_dispatches_v110
  set lifecycle_status = p_to_status,
      claimed_by = case
        when p_to_status in ('queued', 'scheduled') then null
        else coalesce(claimed_by, p_detail ->> 'worker_id')
      end,
      claimed_at = case
        when p_to_status in ('queued', 'scheduled') then null
        else coalesce(claimed_at, v_now)
      end,
      provider_message_id = case when p_to_status = 'delivered'
        then p_provider_message_id else provider_message_id end,
      delivered_at = case when p_to_status = 'delivered' then v_now else null end,
      failure_code = case
        when p_to_status in ('failed', 'cancelled') then p_reason_code
        when p_to_status in ('queued', 'scheduled', 'delivering', 'delivered')
          then null
        else failure_code
      end,
      cancelled_at = case when p_to_status = 'cancelled' then v_now else null end,
      attempt_count = case when p_to_status = 'delivering'
        and lifecycle_status <> 'delivering' then attempt_count + 1
        else attempt_count end,
      next_attempt_at = case when p_to_status = 'queued'
        then v_now else next_attempt_at end,
      updated_at = v_now
  where id = p_dispatch
  returning * into v_dispatch;
  update public.growth_deliveries_v108
  set delivery_status = p_to_status,
      suppression_reason = case
        when p_to_status = 'failed' then 'provider_failure'
        when p_to_status = 'cancelled' then coalesce(p_reason_code, 'owner_cancelled')
        else null
      end,
      provider_message_id = case when p_to_status = 'delivered'
        then p_provider_message_id else provider_message_id end,
      delivered_at = case when p_to_status = 'delivered' then v_now else null end,
      retry_count = v_dispatch.attempt_count
  where id = v_dispatch.delivery_id;
  insert into public.growth_delivery_state_events_v110(
    dispatch_id, delivery_id, execution_id, business_id,
    from_status, to_status, reason_code, provider_message_id,
    actor, idempotency_key, request_hash, detail
  ) values (
    v_dispatch.id, v_dispatch.delivery_id, v_dispatch.execution_id,
    v_dispatch.business_id, v_from_status, p_to_status,
    p_reason_code, p_provider_message_id, auth.uid(),
    p_idempotency_key, v_hash, coalesce(p_detail, '{}'::jsonb)
  );
  return v_dispatch;
end $$;

