-- Name: v111_can_decide(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v111_can_decide(p_business uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $_$
  select auth.uid() is not null
     and (app.is_super_admin() or app.is_salon_owner($1))
$_$;

--
-- Name: v111_can_propose(uuid, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v111_can_propose(p_business uuid, p_branch uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
