--
-- Name: v111_effective_client_id(uuid, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v111_effective_client_id(p_business uuid, p_client uuid) RETURNS uuid
    LANGUAGE sql STABLE STRICT SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  select coalesce((
    select current.effective_client_id
      from public.customer_identity_current_attribution_v111 current
     where current.business_id=p_business
       and current.source_client_id=p_client
  ),p_client)
$$;

--
-- Name: v111_guard_verified_customer_link(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v111_guard_verified_customer_link() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if new.state<>'verified' then
    return new;
  end if;
  perform pg_advisory_xact_lock(hashtextextended(
    'v111:client:'||new.business_id||':'||new.client_id::text,0
  ));
  if exists (
    select 1
      from public.customer_identity_current_attribution_v111 current
     where current.business_id=new.business_id
       and current.source_client_id=new.client_id
       and current.effective_client_id<>current.source_client_id
  ) then
    raise exception
      'verified link cannot be created for a customer with an active identity correction'
      using errcode='55000';
  end if;
  return new;
end
$$;

--
-- Name: v111_normalize_contact(text, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v111_normalize_contact(p_type text, p_value text) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_result text;
begin
  if p_type='email' then
    v_result:=lower(nullif(btrim(p_value),''));
    if v_result is null or position('@' in v_result)<=1 then
      raise exception 'a valid email evidence subject is required'
        using errcode='22023';
    end if;
  elsif p_type='phone' then
    v_result:=app.norm_phone(p_value);
    if v_result is null then
      raise exception 'a valid Singapore phone evidence subject is required'
        using errcode='22023';
    end if;
  else
    raise exception 'unsupported proof contact type' using errcode='22023';
  end if;
  return v_result;
end
$$;

--
-- Name: v111_proposal_guard(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v111_proposal_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if tg_op='DELETE' then
    raise exception 'identity proposals are retained as audit evidence'
      using errcode='23000';
  end if;
  if (new.id,new.business_id,new.branch_id,new.source_client_id,new.target_client_id,
      new.source_identity_id,new.target_identity_id,new.target_link_id,new.reason,
      new.proposed_by,new.proposed_at)
     is distinct from
     (old.id,old.business_id,old.branch_id,old.source_client_id,old.target_client_id,
      old.source_identity_id,old.target_identity_id,old.target_link_id,old.reason,
      old.proposed_by,old.proposed_at) then
    raise exception 'identity proposal scope and evidence are immutable'
      using errcode='23000';
  end if;
  return new;
end
$$;

--
-- Name: v111_request_hash(jsonb); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v111_request_hash(p_payload jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $_$
  select app.v31_sha256_hex($1::text)
$_$;

--
-- Name: v111_validate_contact_pair(uuid, text, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v111_validate_contact_pair(p_proposal uuid, p_type text, p_subject text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_proposal public.customer_identity_proposals_v111%rowtype;
  v_subject text:=app.v111_normalize_contact(p_type,p_subject);
  v_target_user uuid;
  v_target_identity uuid;
  v_candidate_count integer;
  v_candidate uuid;
  v_target_contact text;
begin
  select * into strict v_proposal
    from public.customer_identity_proposals_v111
   where id=p_proposal;

  select link.auth_user_id,link.identity_id
    into v_target_user,v_target_identity
    from public.customer_links link
   where link.id=v_proposal.target_link_id
     and link.business_id=v_proposal.business_id
     and link.client_id=v_proposal.target_client_id
     and link.identity_id=v_proposal.target_identity_id
     and link.state='verified'
     and exists (
       select 1
         from public.customer_identities identity_row
        where identity_row.id=link.identity_id
          and identity_row.status='active'
     );
  if not found then
    raise exception 'target no longer has an active verified business identity'
      using errcode='42501';
  end if;

  if p_type='email' then
    select lower(nullif(btrim(u.email),'')) into v_target_contact
      from auth.users u
     where u.id=v_target_user and u.email_confirmed_at is not null;
  else
    select app.norm_phone(u.phone) into v_target_contact
      from auth.users u
     where u.id=v_target_user and u.phone_confirmed_at is not null;
  end if;
  if v_target_contact is distinct from v_subject then
    raise exception 'evidence does not match the target verified identity'
      using errcode='42501';
  end if;

  select count(*)::integer,(array_agg(c.id order by c.id))[1]
    into v_candidate_count,v_candidate
    from public.clients c
   where c.business_id=v_proposal.business_id
     and c.id<>v_proposal.target_client_id
     and (
       (p_type='email' and lower(nullif(btrim(c.email),''))=v_subject)
       or (p_type='phone' and c.phone_norm=v_subject)
     )
     and not exists (
       select 1 from public.customer_links linked
        where linked.business_id=c.business_id
          and linked.client_id=c.id
          and linked.state='verified'
     );
  if v_candidate_count<>1 or v_candidate is distinct from v_proposal.source_client_id then
    raise exception 'proof is ambiguous or matches multiple candidate customer records'
      using errcode='P0003';
  end if;

  return jsonb_build_object(
    'proof_kind','verified_contact_pair',
    'contact_type',p_type,
    'target_identity_id',v_target_identity,
    'candidate_count',v_candidate_count,
    'source_client_id',v_proposal.source_client_id,
    'target_client_id',v_proposal.target_client_id
  );
end
$$;

--
-- Name: v111_validate_invitation(uuid, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v111_validate_invitation(p_proposal uuid, p_invitation uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_proposal public.customer_identity_proposals_v111%rowtype;
  v_invite public.customer_link_invitations%rowtype;
  v_email text;
  v_target_user uuid;
begin
  select * into strict v_proposal
    from public.customer_identity_proposals_v111 where id=p_proposal;
  if exists (
    select 1
      from public.customer_links source_link
     where source_link.business_id=v_proposal.business_id
       and source_link.client_id=v_proposal.source_client_id
       and source_link.state='verified'
  ) then
    raise exception 'source customer already has a verified identity; invitation proof is no longer unambiguous'
      using errcode='42501';
  end if;
  select * into v_invite
    from public.customer_link_invitations invitation
   where invitation.id=p_invitation
     and invitation.business_id=v_proposal.business_id
     and invitation.client_id=v_proposal.source_client_id
     and invitation.state='issued'
     and invitation.expires_at>statement_timestamp();
  if not found then
    raise exception 'firm invitation evidence is invalid, expired, or cross-business'
      using errcode='42501';
  end if;
  select link.auth_user_id into v_target_user
    from public.customer_links link
   where link.id=v_proposal.target_link_id
     and link.business_id=v_proposal.business_id
     and link.client_id=v_proposal.target_client_id
     and link.identity_id=v_proposal.target_identity_id
     and link.state='verified'
     and exists (
       select 1
         from public.customer_identities identity_row
        where identity_row.id=link.identity_id
          and identity_row.status='active'
     );
  select lower(nullif(btrim(u.email),'')) into v_email
    from auth.users u
   where u.id=v_target_user and u.email_confirmed_at is not null;
  if v_email is null
     or v_invite.recipient_email_hash is distinct from
        app.v31_sha256_hex('v31.invitation-email:'||v_email) then
    raise exception 'invitation recipient does not match the target verified identity'
      using errcode='42501';
  end if;
  return jsonb_build_object(
    'proof_kind','firm_invitation',
    'invitation_id',v_invite.id,
    'source_client_id',v_proposal.source_client_id,
    'target_client_id',v_proposal.target_client_id
  );
end
$$;

--
-- Name: v112_delivery_backoff(integer, timestamp with time zone); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v112_delivery_backoff(p_completed_attempts integer, p_at timestamp with time zone DEFAULT clock_timestamp()) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_policy public.growth_delivery_backoff_policies_v112%rowtype;
  v_slot integer;
begin
  select * into strict v_policy
  from public.growth_delivery_backoff_policies_v112
  where effective_from <= p_at
  order by effective_from desc, version_no desc
  limit 1;
  if p_completed_attempts is null
     or p_completed_attempts < 0
     or p_completed_attempts >= v_policy.max_attempts then
    raise exception 'delivery retry limit reached'
      using errcode = '22023';
  end if;
  v_slot := greatest(1, p_completed_attempts);
  return jsonb_build_object(
    'policy_version', v_policy.version_no,
    'policy_hash', v_policy.policy_hash,
    'max_attempts', v_policy.max_attempts,
    'completed_attempts', p_completed_attempts,
    'backoff_slot', v_slot,
    'delay_seconds', v_policy.delays_seconds[v_slot]
  );
end $$;

--
-- Name: FUNCTION v112_delivery_backoff(p_completed_attempts integer, p_at timestamp with time zone); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.v112_delivery_backoff(p_completed_attempts integer, p_at timestamp with time zone) IS 'Returns the versioned deterministic delay for the persisted completed-attempt count; exhausted attempts are rejected.';

--
-- Name: v112_get_receipt(text, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v112_get_receipt(p_request_identity text, p_request_hash text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_row public.concurrent_operation_receipts_v112%rowtype;
begin
  select * into v_row
  from public.concurrent_operation_receipts_v112
  where request_identity = p_request_identity;
  if not found then
    return null;
  end if;
  if v_row.request_hash <> p_request_hash then
    raise exception 'idempotency key reused with a different request'
      using errcode = '23505';
  end if;
  return v_row.receipt;
end $$;

--
-- Name: v112_hash(jsonb); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v112_hash(p_value jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  select encode(
    extensions.digest(convert_to(p_value::text, 'UTF8'), 'sha256'),
    'hex'
  )
$$;

--
-- Name: v112_immutable(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v112_immutable() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  raise exception '% is append-only', tg_table_name using errcode = '23000';
end $$;

--
-- Name: v112_lock_dispatch(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v112_lock_dispatch(p_dispatch uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if p_dispatch is null then
    raise exception 'dispatch identity is required' using errcode = '22023';
  end if;
  perform pg_advisory_xact_lock(
    hashtextextended('v112-v110-dispatch:' || p_dispatch::text, 112)
  );
end $$;

--
-- Name: v112_lock_pair(text, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v112_lock_pair(p_first text, p_second text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_first text := least(p_first, p_second);
  v_second text := greatest(p_first, p_second);
begin
  if nullif(v_first, '') is null or nullif(v_second, '') is null then
    raise exception 'two non-empty lock identities are required'
      using errcode = '22023';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(v_first, 112));
  if v_second <> v_first then
    perform pg_advisory_xact_lock(hashtextextended(v_second, 112));
  end if;
end $$;

--
-- Name: v112_put_receipt(text, text, text, jsonb, jsonb); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v112_put_receipt(p_request_identity text, p_operation text, p_request_hash text, p_scope jsonb, p_receipt jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $_$
begin
  if p_request_identity !~ '^[0-9a-f]{64}$'
     or p_request_hash !~ '^[0-9a-f]{64}$'
     or p_operation !~ '^[a-z][a-z0-9_]{2,79}$'
     or jsonb_typeof(coalesce(p_scope, '{}'::jsonb)) <> 'object'
     or jsonb_typeof(p_receipt) <> 'object' then
    raise exception 'valid immutable operation receipt is required'
      using errcode = '22023';
  end if;
  insert into public.concurrent_operation_receipts_v112(
    request_identity, operation, request_hash, scope, receipt
  ) values (
    p_request_identity, p_operation, p_request_hash,
    coalesce(p_scope, '{}'::jsonb), p_receipt
  );
  return p_receipt;
end $_$;

--
-- Name: v113_canonicalize_execution_member(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v113_canonicalize_execution_member() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  new.client_id:=app.v113_effective_client_id(new.business_id,new.client_id);
  return new;
end
$$;

--
-- Name: v113_customer_effective_client_id(uuid, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v113_customer_effective_client_id(p_business uuid, p_identity uuid) RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_count integer;
  v_client uuid;
begin
  select count(*),(array_agg(effective.effective_client_id))[1]
    into v_count,v_client
    from (
      select distinct
        app.v113_effective_client_id(link.business_id,link.client_id)
          as effective_client_id
      from public.customer_links link
      join public.customer_identities identity_row
        on identity_row.id=link.identity_id
       and identity_row.auth_user_id=link.auth_user_id
      where link.business_id=p_business
        and link.identity_id=p_identity
        and link.state='verified'
        and identity_row.status='active'
    ) effective;
  if v_count<>1 then
    raise exception 'one unambiguous active verified customer link is required'
      using errcode='42501';
  end if;
  return v_client;
end
$$;

--
-- Name: v113_effective_client_id(uuid, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v113_effective_client_id(p_business uuid, p_client uuid) RETURNS uuid
    LANGUAGE sql STABLE STRICT SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  select app.v111_effective_client_id(p_business,p_client)
$$;

--
-- Name: v113_guard_growth_execution_identity(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v113_guard_growth_execution_identity() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_eligible integer;
  v_effective integer;
begin
  select count(*),
         count(distinct app.v113_effective_client_id(member.business_id,member.client_id))
    into v_eligible,v_effective
    from public.growth_recommendation_members_v108 member
   where member.recommendation_id=new.recommendation_id
     and member.business_id=new.business_id
     and member.eligible;
  if v_eligible<>v_effective then
    raise exception 'recommendation identity snapshot is stale; refresh before approval'
      using errcode='55000';
  end if;
  if exists (
    select 1
      from public.growth_recommendation_members_v108 candidate
      join public.growth_execution_members_v108 active_member
        on active_member.business_id=candidate.business_id
       and app.v113_effective_client_id(
             active_member.business_id,active_member.client_id
           )=app.v113_effective_client_id(
             candidate.business_id,candidate.client_id
           )
      join public.growth_executions_v108 active_execution
        on active_execution.id=active_member.execution_id
       and active_execution.business_id=active_member.business_id
     where candidate.recommendation_id=new.recommendation_id
       and candidate.business_id=new.business_id
       and candidate.eligible
       and active_execution.status='running'
       and active_execution.ends_at>statement_timestamp()
  ) then
    raise exception 'recommendation overlaps an active effective-customer experiment'
      using errcode='23P01';
  end if;
  return new;
end
$$;

--
-- Name: v134_peekaa_billing_notice_brand(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v134_peekaa_billing_notice_brand() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if tg_table_schema='public' and tg_table_name='business_billing_due_notices_v94' then
    new.notice_body:=replace(new.notice_body,'your Nestly representative','your Peekaa representative');
  elsif tg_table_schema='public' and tg_table_name='notifications'
        and new.kind='subscription_payment_due' then
    new.body:=replace(new.body,'your Nestly representative','your Peekaa representative');
  end if;
  return new;
end
$$;

