--
-- Name: v143_project_tier_window(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v143_project_tier_window() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  select version.effective_from,version.expires_at
    into new.effective_from,new.expires_at
  from public.businesses business
  join public.loyalty_tier_versions version
    on version.business_id=business.id
   and version.config_version_id=business.active_config_version_id
   and version.tier_id=new.id
  where business.id=new.business_id;
  return new;
end
$$;

--
-- Name: v145_config_publish_guard(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v145_config_publish_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if new.status = 'published'
     and old.status is distinct from 'published'
     and exists (
       select 1
         from public.program_rules rule
         cross join lateral jsonb_array_elements(
           coalesce(rule.then_effects, '[]'::jsonb)
         ) effect
        where rule.config_version_id = new.id
          and rule.business_id = new.business_id
          and rule.active
          and app.ps1c2_effect_state(
            rule.business_id, effect->>'effect_type'
          ) <> 'live'
     ) then
    raise exception 'this draft contains an active advanced action that is unavailable for launch; pause that rule before publishing'
      using errcode = '55000';
  end if;
  return new;
end;
$$;

--
-- Name: v145_program_rule_activation_guard(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v145_program_rule_activation_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if old.active is false and new.active is true and exists (
    select 1
      from jsonb_array_elements(coalesce(new.then_effects, '[]'::jsonb)) effect
     where app.ps1c2_effect_state(new.business_id, effect->>'effect_type') <> 'live'
  ) then
    raise exception 'incomplete advanced rule cannot be resumed for launch'
      using errcode = '55000';
  end if;
  return new;
end;
$$;

--
-- Name: v145_program_rule_pause_lift_guard(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v145_program_rule_pause_lift_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if old.lifted_at is null and new.lifted_at is not null and exists (
    select 1
      from public.businesses business
      join public.program_rules rule
        on rule.business_id = business.id
       and rule.config_version_id = business.active_config_version_id
       and rule.active
      cross join lateral jsonb_array_elements(coalesce(rule.then_effects, '[]'::jsonb)) effect
     where business.id = old.business_id
       and rule.rule_id = old.rule_id
       and app.ps1c2_effect_state(rule.business_id, effect->>'effect_type') <> 'live'
  ) then
    raise exception 'incomplete advanced rule pause cannot be lifted for launch'
      using errcode = '55000';
  end if;
  return new;
end;
$$;

--
-- Name: v156_billing_event_trigger(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v156_billing_event_trigger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_result jsonb;v_status text;
begin
  if new.processing_status='processed' and old.processing_status is distinct from new.processing_status then
    begin
      v_result:=app.v156_prepare_billing_event(new.event_id);
      v_status:=case when v_result->>'status'='blocked' then 'blocked' when v_result->>'status' like 'ignored%' then 'ignored' else 'prepared' end;
      insert into public.platform_billing_event_preparations_v156(event_pk,event_id,status,reason,last_result,prepared_at)
      values(new.id,new.event_id,v_status,v_result->>'reason',v_result,case when v_status='prepared' then clock_timestamp() end)
      on conflict(event_id) do update set status=excluded.status,reason=excluded.reason,last_result=excluded.last_result,
        attempt_count=platform_billing_event_preparations_v156.attempt_count+1,last_attempt_at=clock_timestamp(),prepared_at=excluded.prepared_at;
    exception when others then
      insert into public.platform_billing_event_preparations_v156(event_pk,event_id,status,reason,last_result)
      values(new.id,new.event_id,'failed',sqlstate,jsonb_build_object('status','failed','sqlstate',sqlstate))
      on conflict(event_id) do update set status='failed',reason=sqlstate,last_result=excluded.last_result,
        attempt_count=platform_billing_event_preparations_v156.attempt_count+1,last_attempt_at=clock_timestamp();
      insert into public.platform_subscription_dispatch_audit_v156(action,entity_type,detail)
      values('billing_event_prepare_failed','stripe_event',jsonb_build_object('event_id',new.event_id,'sqlstate',sqlstate));
    end;
  end if;return new;
end $$;

--
-- Name: v156_can(text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v156_can(p_mode text DEFAULT 'r'::text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  select coalesce(app.is_super_admin() or app.v89_platform_can('billing',p_mode),false)
$$;

--
-- Name: v156_can_prospect(uuid, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v156_can_prospect(p_prospect uuid, p_mode text DEFAULT 'r'::text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  select coalesce(
    app.is_super_admin()
    or (app.v89_platform_role()='admin'
        and app.v89_platform_can('onboarding',p_mode))
    or (app.v89_platform_role()='sales_staff'
        and app.v89_platform_can('onboarding',p_mode)
        and exists(
          select 1 from public.sme_prospects prospect
          join public.platform_consultants consultant
            on consultant.id=prospect.assigned_consultant_id
          where prospect.id=p_prospect
            and consultant.user_id=auth.uid()
            and consultant.active))
  ,false)
$$;

--
-- Name: v156_customer_snapshot(uuid, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v156_customer_snapshot(p_business uuid, p_prospect uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  select coalesce((select jsonb_build_object('business_display_name',c.business_display_name,
    'legal_entity_name',c.legal_entity_name,'registration_number',c.registration_number,
    'billing_address',c.billing_address,'country',c.country,'contact_name',c.contact_name,
    'primary_email',c.email,'telephone',c.telephone,'purchase_order_number',c.purchase_order_number,
    'customer_reference',c.customer_reference,'recipients',(select jsonb_agg(jsonb_build_object(
      'name',r.contact_name,'email',r.email,'role',r.recipient_role) order by r.recipient_role,r.email)
      from public.platform_billing_contacts_v156 r where r.active and (r.business_id=p_business or r.prospect_id=p_prospect)))
    from public.platform_billing_contacts_v156 c where c.active and c.recipient_role='primary'
      and (c.business_id=p_business or c.prospect_id=p_prospect) limit 1),null)
$$;

--
-- Name: v156_document_guard(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v156_document_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if tg_op='DELETE' or old.finalized_at is not null then raise exception 'finalized subscription documents are immutable; void or reissue instead' using errcode='55000';end if;
  if new.id<>old.id or new.document_type<>old.document_type or new.business_id is distinct from old.business_id
    or new.prospect_id is distinct from old.prospect_id or new.operation_key<>old.operation_key
    or new.created_by is distinct from old.created_by then raise exception 'document identity is immutable' using errcode='55000';end if;
  return new;
end $$;

--
-- Name: v156_immutable_guard(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v156_immutable_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin raise exception 'V156 audit evidence is immutable' using errcode='55000';end $$;

--
-- Name: v156_next_document_number(text, date); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v156_next_document_number(p_type text, p_date date) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_year integer:=extract(year from p_date);v_value bigint;v_prefix text;
begin
  if p_type not in ('quotation','invoice','receipt','subscription_summary') then raise exception 'unsupported document type' using errcode='22023';end if;
  insert into public.platform_subscription_document_sequences_v156(document_type,document_year,next_value)
  values(p_type,v_year,2) on conflict(document_type,document_year) do update
    set next_value=platform_subscription_document_sequences_v156.next_value+1
  returning next_value-1 into v_value;
  v_prefix:=case p_type when 'quotation' then 'QTN' when 'invoice' then 'INV' when 'receipt' then 'REC' else 'SUB' end;
  return v_prefix||'-'||v_year||'-'||lpad(v_value::text,6,'0');
end $$;

--
-- Name: v156_operation_replay(uuid, text, uuid, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v156_operation_replay(p_key uuid, p_type text, p_actor uuid, p_hash text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_receipt public.platform_v156_operation_receipts%rowtype;
begin
  select * into v_receipt from public.platform_v156_operation_receipts where operation_key=p_key;
  if not found then return null;end if;
  if v_receipt.operation_type<>p_type or v_receipt.actor<>p_actor or v_receipt.request_hash<>p_hash then
    raise exception 'idempotency key conflict' using errcode='22023';
  end if;
  return v_receipt.response||jsonb_build_object('replayed',true);
end $$;

--
-- Name: v156_prepare_billing_event(text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v156_prepare_billing_event(p_event_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'extensions', 'pg_temp'
    AS $$
declare v_event public.billing_provider_events%rowtype;v_invoice public.billing_provider_invoices%rowtype;v_subscription public.billing_provider_subscriptions%rowtype;v_profile public.platform_billing_profiles_v156%rowtype;v_customer jsonb;v_prospect uuid;v_invoice_doc public.platform_subscription_documents_v156%rowtype;v_receipt_doc public.platform_subscription_documents_v156%rowtype;v_summary_doc public.platform_subscription_documents_v156%rowtype;v_quote uuid;v_number text;v_snapshot jsonb;v_id uuid;v_status text;v_period_start date;v_period_end date;v_recipient text[];v_cc text[];v_docs uuid[];v_first boolean;v_previous_stage text;
begin
  select * into v_event from public.billing_provider_events where event_id=p_event_id and processing_status='processed';if not found or v_event.business_id is null then return jsonb_build_object('status','ignored');end if;
  select id into v_prospect from public.sme_prospects where converted_business_id=v_event.business_id order by converted_at desc nulls last limit 1;
  if v_event.event_type in ('invoice.payment_failed','invoice.payment_action_required') then
    select * into v_invoice from public.billing_provider_invoices where provider_invoice_id=v_event.object_id;if not found then return jsonb_build_object('status','ignored');end if;
    if v_invoice.paid_normalized then
      return jsonb_build_object('status','ignored_stale','reason','invoice_already_paid');
    elsif v_event.event_type='invoice.payment_failed' then
      perform app.v156_upsert_task('payment-failed:'||v_invoice.provider_invoice_id,'payment_failed',v_event.business_id,v_prospect,v_invoice.provider_subscription_id,v_invoice.provider_invoice_id,'urgent',clock_timestamp(),'Follow up failed subscription payment',p_event_id);
    else
      perform app.v156_upsert_task('payment-action:'||v_invoice.provider_invoice_id,'payment_action_required',v_event.business_id,v_prospect,v_invoice.provider_subscription_id,v_invoice.provider_invoice_id,'urgent',clock_timestamp(),'Customer payment action is required',p_event_id);
    end if;
    insert into public.platform_subscription_lifecycle_events_v156(business_id,provider_subscription_id,lifecycle_status,snapshot,source_type,source_id,occurred_at)
    values(v_event.business_id,v_invoice.provider_subscription_id,case when v_event.event_type='invoice.payment_failed' then 'past_due' else 'payment_action_required' end,jsonb_build_object('invoice_id',v_invoice.provider_invoice_id,'invoice_status',v_invoice.status),'stripe_event',p_event_id,v_event.event_created_at) on conflict do nothing;
    return jsonb_build_object('status','processed','follow_up_created',true);
  end if;
  if v_event.event_type in ('invoice.voided','invoice.marked_uncollectible') then
    select * into v_invoice from public.billing_provider_invoices where provider_invoice_id=v_event.object_id;if not found then return jsonb_build_object('status','ignored');end if;
    select * into v_invoice_doc from public.platform_subscription_documents_v156 where provider_invoice_id=v_invoice.provider_invoice_id and document_type='invoice';
    if found then insert into public.platform_subscription_document_events_v156(document_id,status,source_type,source_id)
      values(v_invoice_doc.id,case when v_event.event_type='invoice.voided' then 'void' else 'uncollectible' end,'stripe_event',p_event_id) on conflict do nothing;end if;
    return jsonb_build_object('status','processed','document_state',case when v_event.event_type='invoice.voided' then 'void' else 'uncollectible' end);
  end if;
  if v_event.event_type in ('refund.created','charge.dispute.created') then
    select invoice.* into v_invoice from public.billing_adjustments adjustment join public.billing_provider_invoices invoice on invoice.provider_invoice_id=adjustment.provider_invoice_id where adjustment.source_event_id=p_event_id;
    if not found then return jsonb_build_object('status','ignored');end if;
    select * into v_invoice_doc from public.platform_subscription_documents_v156 where provider_invoice_id=v_invoice.provider_invoice_id and document_type='invoice';
    if found then
      select case when abs(coalesce(sum(total_cents),0))>=v_invoice.amount_paid_cents then 'refunded' else 'partially_refunded' end into v_status from public.billing_adjustments where provider_invoice_id=v_invoice.provider_invoice_id and adjustment_type in ('refund','chargeback');
      insert into public.platform_subscription_document_events_v156(document_id,status,source_type,source_id) values(v_invoice_doc.id,v_status,'stripe_event',p_event_id) on conflict do nothing;
    end if;
    if v_prospect is not null and not exists(select 1 from public.sme_prospect_activities where prospect_id=v_prospect and detail='event:'||p_event_id) then insert into public.sme_prospect_activities(prospect_id,activity_type,summary,detail) values(v_prospect,'payment',case when v_event.event_type='refund.created' then 'Verified Stripe refund recorded' else 'Stripe payment dispute recorded' end,'event:'||p_event_id);end if;
    return jsonb_build_object('status','processed','document_state',v_status);
  end if;
  if v_event.event_type like 'customer.subscription.%' then
    select * into v_subscription from public.billing_provider_subscriptions where provider_subscription_id=v_event.object_id;if not found then return jsonb_build_object('status','ignored');end if;
    v_status:=case when v_subscription.cancel_at_period_end then 'cancel_at_period_end' when v_subscription.status='trialing' then 'trial' when v_subscription.status='active' then 'active' when v_subscription.status='incomplete' then 'payment_incomplete' when v_subscription.status='past_due' then 'past_due' when v_subscription.status='paused' then 'paused' when v_subscription.status='canceled' then 'cancelled' else 'payment_incomplete' end;
    insert into public.platform_subscription_lifecycle_events_v156(business_id,provider_subscription_id,lifecycle_status,snapshot,source_type,source_id,occurred_at)
    values(v_event.business_id,v_subscription.provider_subscription_id,v_status,jsonb_build_object('canonical_status',v_subscription.status,'start_date',v_subscription.created_at,'trial_end',v_subscription.trial_end,'paid_period_start',v_subscription.current_period_start,'paid_period_end',v_subscription.current_period_end,'billing_cycle_anchor',v_subscription.billing_cycle_anchor,'cancel_at_period_end',v_subscription.cancel_at_period_end,'scheduled_end',case when v_subscription.cancel_at_period_end then v_subscription.current_period_end end,'actual_end',v_subscription.ended_at,'no_scheduled_end',not v_subscription.cancel_at_period_end and v_subscription.ended_at is null),'stripe_event',p_event_id,v_event.event_created_at) on conflict do nothing;
    if v_subscription.cancel_at_period_end then perform app.v156_upsert_task('cancel-at-end:'||v_subscription.provider_subscription_id,'cancel_at_period_end',v_event.business_id,v_prospect,v_subscription.provider_subscription_id,null,'high',coalesce(v_subscription.current_period_end,clock_timestamp()),'Subscription is scheduled to end',p_event_id);end if;
    return jsonb_build_object('status','processed');
  end if;
  select * into v_profile from public.platform_billing_profiles_v156 order by version desc limit 1;
  if not app.v156_profile_ready(v_profile) then perform app.v156_upsert_task('billing-profile:'||v_event.business_id,'billing_profile_missing',v_event.business_id,v_prospect,null,null,'urgent',clock_timestamp(),'Complete seller legal and billing settings',p_event_id);return jsonb_build_object('status','blocked','reason','billing_profile_incomplete');end if;
  v_customer:=app.v156_customer_snapshot(v_event.business_id,v_prospect);
  if v_customer is null then perform app.v156_upsert_task('billing-contact:'||v_event.business_id,'billing_contact_missing',v_event.business_id,v_prospect,null,null,'high',clock_timestamp(),'Add a primary billing contact',p_event_id);return jsonb_build_object('status','blocked','reason','billing_contact_missing');end if;

  if v_event.event_type like 'invoice.%' then
    select * into v_invoice from public.billing_provider_invoices where provider_invoice_id=v_event.object_id;if not found then return jsonb_build_object('status','ignored');end if;
    select * into v_subscription from public.billing_provider_subscriptions where provider_subscription_id=v_invoice.provider_subscription_id;
    v_period_start:=(v_invoice.period_start at time zone 'Asia/Singapore')::date;v_period_end:=((v_invoice.period_end at time zone 'Asia/Singapore')::date-1);
    select * into v_invoice_doc from public.platform_subscription_documents_v156 where provider_invoice_id=v_invoice.provider_invoice_id and document_type='invoice';
    -- Stripe's finalised/open invoice is itself the pre-payment obligation.  The
    -- Peekaa mirror is issued only from verified invoice.paid so its immutable
    -- snapshot can never be frozen with an unpaid balance and later mislabelled.
    if not found and v_event.event_type='invoice.paid' then
      v_number:=app.v156_next_document_number('invoice',(coalesce(v_invoice.finalized_at,v_event.event_created_at) at time zone 'Asia/Singapore')::date);
      v_snapshot:=jsonb_build_object('document_type','invoice','number',v_number,'stripe_invoice_id',v_invoice.provider_invoice_id,
        'stripe_invoice_number',v_invoice.number,'canonical_provider','Stripe','no_second_payment_obligation',true,
        'issue_date',(coalesce(v_invoice.finalized_at,v_event.event_created_at) at time zone 'Asia/Singapore')::date,'due_date',(v_invoice.due_at at time zone 'Asia/Singapore')::date,
        'service_period_start',v_period_start,'service_period_end',v_period_end,'seller',app.v156_seller_snapshot(v_profile),
        'customer',v_customer,'subtotal_cents',v_invoice.subtotal_ex_tax_cents,'tax_cents',v_invoice.tax_cents,
        'total_cents',v_invoice.total_cents,'amount_paid_cents',v_invoice.amount_paid_cents,'balance_due_cents',v_invoice.amount_remaining_cents,
        'currency',v_invoice.currency,'payment_status',v_invoice.status,
        'line_items',jsonb_build_array(jsonb_build_object('description','Peekaa '||coalesce(v_subscription.cadence,'subscription')||' subscription','quantity',1,'unit_amount_cents',v_invoice.subtotal_ex_tax_cents)),
        'bank_transfer_reference',v_number||' – '||(v_customer->>'legal_entity_name'));
      insert into public.platform_subscription_documents_v156(document_type,document_number,business_id,prospect_id,seller_profile_id,
        provider_invoice_id,provider_subscription_id,issue_date,due_date,service_period_start,service_period_end,currency,
        subtotal_cents,tax_cents,total_cents,amount_paid_cents,balance_due_cents,snapshot,snapshot_sha256,finalized_at,
        operation_key,request_hash,source_event_id)
      values('invoice',v_number,v_event.business_id,v_prospect,v_profile.id,v_invoice.provider_invoice_id,v_invoice.provider_subscription_id,
        (coalesce(v_invoice.finalized_at,v_event.event_created_at) at time zone 'Asia/Singapore')::date,(v_invoice.due_at at time zone 'Asia/Singapore')::date,
        v_period_start,v_period_end,v_invoice.currency,v_invoice.subtotal_ex_tax_cents,v_invoice.tax_cents,v_invoice.total_cents,
        v_invoice.amount_paid_cents,v_invoice.amount_remaining_cents,v_snapshot,encode(extensions.digest(v_snapshot::text,'sha256'),'hex'),clock_timestamp(),
        (md5('v156-invoice:'||v_invoice.provider_invoice_id))::uuid,encode(extensions.digest(v_snapshot::text,'sha256'),'hex'),p_event_id) returning * into v_invoice_doc;
      insert into public.platform_subscription_document_events_v156(document_id,status,source_type,source_id)
      values(v_invoice_doc.id,case when v_invoice.paid_normalized then 'paid' else 'open' end,'stripe_event',p_event_id);
    end if;
    if v_event.event_type='invoice.payment_failed' then
      perform app.v156_upsert_task('payment-failed:'||v_invoice.provider_invoice_id,'payment_failed',v_event.business_id,v_prospect,v_invoice.provider_subscription_id,v_invoice.provider_invoice_id,'urgent',clock_timestamp(),'Follow up failed subscription payment',p_event_id);
    elsif v_event.event_type='invoice.payment_action_required' then
      perform app.v156_upsert_task('payment-action:'||v_invoice.provider_invoice_id,'payment_action_required',v_event.business_id,v_prospect,v_invoice.provider_subscription_id,v_invoice.provider_invoice_id,'urgent',clock_timestamp(),'Customer payment action is required',p_event_id);
    elsif v_event.event_type='invoice.paid' then
      update public.platform_subscription_tasks_v156 set status='completed',completed_at=clock_timestamp(),resolution='Payment recovered',updated_at=clock_timestamp()
      where business_id=v_event.business_id and provider_invoice_id=v_invoice.provider_invoice_id and status='open' and task_type in ('payment_failed','payment_action_required','past_due');
      insert into public.platform_subscription_document_events_v156(document_id,status,source_type,source_id)
      values(v_invoice_doc.id,'paid','stripe_event',p_event_id) on conflict do nothing;
      select * into v_receipt_doc from public.platform_subscription_documents_v156 where provider_invoice_id=v_invoice.provider_invoice_id and document_type='receipt';
      if not found then
        v_number:=app.v156_next_document_number('receipt',(v_invoice.paid_at at time zone 'Asia/Singapore')::date);
        v_snapshot:=jsonb_build_object('document_type','receipt','number',v_number,'related_invoice_number',v_invoice_doc.document_number,
          'stripe_invoice_id',v_invoice.provider_invoice_id,'stripe_payment_reference',v_invoice.provider_payment_intent_id,
          'seller',app.v156_seller_snapshot(v_profile),'customer',v_customer,'payment_date',v_invoice.paid_at,
          'payment_method','stripe','payment_method_label','Payment received via Stripe','amount_received_cents',v_invoice.amount_paid_cents,'currency',v_invoice.currency,
          'service_period_start',v_period_start,'service_period_end',v_period_end,'remaining_balance_cents',v_invoice.amount_remaining_cents);
        insert into public.platform_subscription_documents_v156(document_type,document_number,business_id,prospect_id,seller_profile_id,
          provider_invoice_id,provider_subscription_id,original_document_id,issue_date,service_period_start,service_period_end,currency,
          subtotal_cents,tax_cents,total_cents,amount_paid_cents,balance_due_cents,snapshot,snapshot_sha256,finalized_at,operation_key,request_hash,source_event_id)
        values('receipt',v_number,v_event.business_id,v_prospect,v_profile.id,v_invoice.provider_invoice_id,v_invoice.provider_subscription_id,
          v_invoice_doc.id,(v_invoice.paid_at at time zone 'Asia/Singapore')::date,v_period_start,v_period_end,v_invoice.currency,
          v_invoice.amount_paid_cents,0,v_invoice.amount_paid_cents,v_invoice.amount_paid_cents,0,v_snapshot,
          encode(extensions.digest(v_snapshot::text,'sha256'),'hex'),clock_timestamp(),(md5('v156-receipt:'||v_invoice.provider_invoice_id))::uuid,
          encode(extensions.digest(v_snapshot::text,'sha256'),'hex'),p_event_id) returning * into v_receipt_doc;
        insert into public.platform_subscription_document_events_v156(document_id,status,source_type,source_id) values(v_receipt_doc.id,'issued','stripe_event',p_event_id);
      end if;
      select * into v_summary_doc from public.platform_subscription_documents_v156 where provider_invoice_id=v_invoice.provider_invoice_id and document_type='subscription_summary';
      if not found then
        v_number:=app.v156_next_document_number('subscription_summary',(v_invoice.paid_at at time zone 'Asia/Singapore')::date);
        v_snapshot:=jsonb_build_object('document_type','subscription_summary','number',v_number,'business',v_customer,
          'plan',coalesce(v_subscription.cadence,'subscription'),'billing_interval',v_subscription.cadence,
          'active_since',v_subscription.created_at,'paid_period_start',v_period_start,'paid_period_end',v_period_end,
          'next_renewal',case when not v_subscription.cancel_at_period_end then (v_subscription.current_period_end at time zone 'Asia/Singapore')::date end,
          'scheduled_end',case when v_subscription.cancel_at_period_end then (v_subscription.current_period_end at time zone 'Asia/Singapore')::date end,
          'no_scheduled_end',not v_subscription.cancel_at_period_end,'seller',app.v156_seller_snapshot(v_profile));
        insert into public.platform_subscription_documents_v156(document_type,document_number,business_id,prospect_id,seller_profile_id,
          provider_invoice_id,provider_subscription_id,original_document_id,issue_date,service_period_start,service_period_end,currency,
          subtotal_cents,total_cents,amount_paid_cents,balance_due_cents,snapshot,snapshot_sha256,finalized_at,operation_key,request_hash,source_event_id)
        values('subscription_summary',v_number,v_event.business_id,v_prospect,v_profile.id,v_invoice.provider_invoice_id,v_invoice.provider_subscription_id,
          v_invoice_doc.id,(v_invoice.paid_at at time zone 'Asia/Singapore')::date,v_period_start,v_period_end,v_invoice.currency,0,0,0,0,v_snapshot,
          encode(extensions.digest(v_snapshot::text,'sha256'),'hex'),clock_timestamp(),(md5('v156-summary:'||v_invoice.provider_invoice_id))::uuid,
          encode(extensions.digest(v_snapshot::text,'sha256'),'hex'),p_event_id) returning * into v_summary_doc;
        insert into public.platform_subscription_document_events_v156(document_id,status,source_type,source_id) values(v_summary_doc.id,'finalized','stripe_event',p_event_id);
      end if;
      insert into public.platform_subscription_lifecycle_events_v156(business_id,provider_subscription_id,lifecycle_status,snapshot,source_type,source_id,occurred_at)
      values(v_event.business_id,v_invoice.provider_subscription_id,'payment_received',jsonb_build_object('paid_through',v_period_end,'next_renewal',(v_subscription.current_period_end at time zone 'Asia/Singapore')::date,'invoice_id',v_invoice.provider_invoice_id),'stripe_event',p_event_id,v_invoice.paid_at) on conflict do nothing;
      if v_prospect is not null then
        select current_stage_key into v_previous_stage from public.sme_prospects where id=v_prospect for update;
        if v_previous_stage not in ('client','account_created','onboarding','activated') then
          insert into public.sme_prospect_stage_history(prospect_id,from_stage_key,to_stage_key,reason_code,reason_detail,occurred_at)
          values(v_prospect,v_previous_stage,'client','verified_payment','Stripe invoice.paid event '||p_event_id,v_invoice.paid_at);
          update public.sme_prospects set current_stage_key='client',stage_entered_at=clock_timestamp(),version=version+1,updated_at=clock_timestamp() where id=v_prospect;
        end if;
        if not exists(select 1 from public.sme_prospect_activities where prospect_id=v_prospect and activity_type='payment' and detail='event:'||p_event_id) then
          insert into public.sme_prospect_activities(prospect_id,consultant_id,activity_type,summary,detail,occurred_at)
          select v_prospect,assigned_consultant_id,'payment','Verified subscription payment received','event:'||p_event_id,v_invoice.paid_at from public.sme_prospects where id=v_prospect;
        end if;
      end if;
      perform app.v156_upsert_task('onboarding:'||v_event.business_id||':'||v_invoice.provider_subscription_id,'onboarding',v_event.business_id,v_prospect,v_invoice.provider_subscription_id,v_invoice.provider_invoice_id,'high',clock_timestamp()+interval '1 day','Schedule subscription onboarding',p_event_id);
      select array_agg(email order by recipient_role,email) filter(where recipient_role='primary'),array_agg(email order by recipient_role,email) filter(where recipient_role<>'primary') into v_recipient,v_cc from public.platform_billing_contacts_v156 where active and (business_id=v_event.business_id or prospect_id=v_prospect);
      if v_profile.internal_copy_email is not null then select array_agg(distinct address) into v_cc from unnest(coalesce(v_cc,'{}'::text[])||array[v_profile.internal_copy_email]) address where not(address=any(v_recipient));end if;
      select count(*)=1 into v_first from public.billing_provider_invoices where business_id=v_event.business_id and paid_normalized and paid_at<=v_invoice.paid_at;
      v_docs:=array[v_invoice_doc.id,v_receipt_doc.id,v_summary_doc.id];
      if v_first then select q.id into v_quote from public.platform_subscription_documents_v156 q where q.prospect_id=v_prospect and q.document_type='quotation' and q.finalized_at is not null and q.expiry_date>=(v_invoice.paid_at at time zone 'Asia/Singapore')::date
        and (select e.status from public.platform_subscription_document_events_v156 e where e.document_id=q.id order by e.occurred_at desc,e.id desc limit 1) in ('sent','accepted') order by q.finalized_at desc limit 1;if v_quote is not null then v_docs:=array_append(v_docs,v_quote);end if;end if;
      insert into public.platform_subscription_deliveries_v156(delivery_key,business_id,provider_invoice_id,delivery_type,document_ids,recipients,cc_recipients,subject)
      values('stripe-paid:'||v_invoice.provider_invoice_id,v_event.business_id,v_invoice.provider_invoice_id,case when v_first then 'first_payment_pack' else 'renewal_payment_pack' end,v_docs,v_recipient,coalesce(v_cc,'{}'),'Payment received – Peekaa subscription for '||(v_customer->>'business_display_name')) on conflict(delivery_key) do nothing;
    end if;
  elsif v_event.event_type like 'customer.subscription.%' then
    select * into v_subscription from public.billing_provider_subscriptions where provider_subscription_id=v_event.object_id;if not found then return jsonb_build_object('status','ignored');end if;
    v_status:=case when v_subscription.cancel_at_period_end then 'cancel_at_period_end' when v_subscription.status='trialing' then 'trial' when v_subscription.status='active' then 'active' when v_subscription.status='incomplete' then 'payment_incomplete' when v_subscription.status='past_due' then 'past_due' when v_subscription.status='paused' then 'paused' when v_subscription.status='canceled' then 'cancelled' else 'payment_incomplete' end;
    insert into public.platform_subscription_lifecycle_events_v156(business_id,provider_subscription_id,lifecycle_status,snapshot,source_type,source_id,occurred_at)
    values(v_event.business_id,v_subscription.provider_subscription_id,v_status,jsonb_build_object('canonical_status',v_subscription.status,
      'start_date',v_subscription.created_at,'trial_end',v_subscription.trial_end,'paid_period_start',v_subscription.current_period_start,
      'paid_period_end',v_subscription.current_period_end,'billing_cycle_anchor',v_subscription.billing_cycle_anchor,
      'cancel_at_period_end',v_subscription.cancel_at_period_end,'scheduled_end',case when v_subscription.cancel_at_period_end then v_subscription.current_period_end end,
      'actual_end',v_subscription.ended_at,'no_scheduled_end',not v_subscription.cancel_at_period_end and v_subscription.ended_at is null),
      'stripe_event',p_event_id,v_event.event_created_at) on conflict do nothing;
    if v_subscription.cancel_at_period_end then perform app.v156_upsert_task('cancel-at-end:'||v_subscription.provider_subscription_id,'cancel_at_period_end',v_event.business_id,v_prospect,v_subscription.provider_subscription_id,null,'high',coalesce(v_subscription.current_period_end,clock_timestamp()),'Subscription is scheduled to end',p_event_id);end if;
  end if;
  return jsonb_build_object('status','processed');
end $$;

--
-- Name: platform_billing_profiles_v156; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.platform_billing_profiles_v156 (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    version integer NOT NULL,
    effective_from timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    brand_name text NOT NULL,
    legal_name text NOT NULL,
    uen text,
    registered_address text,
    billing_email text,
    currency text DEFAULT 'SGD'::text NOT NULL,
    gst_status text NOT NULL,
    gst_registration_number text,
    gst_rate_bps integer DEFAULT 0 NOT NULL,
    default_payment_terms text,
    logo_object_path text,
    authorised_signature_object_path text,
    bank_account_name text NOT NULL,
    bank_name text NOT NULL,
    bank_code text NOT NULL,
    branch_code text NOT NULL,
    swift_code text NOT NULL,
    bank_account_number text NOT NULL,
    bank_account_location text NOT NULL,
    billing_contact_name text NOT NULL,
    billing_contact_mobile text NOT NULL,
    internal_copy_email text,
    customer_reminders_enabled boolean DEFAULT false NOT NULL,
    annual_reminder_days integer[] DEFAULT ARRAY[30, 14, 7] NOT NULL,
    created_by uuid,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    operation_key uuid,
    request_hash text,
    CONSTRAINT platform_billing_profiles_v156_annual_reminder_days_check CHECK (((cardinality(annual_reminder_days) <= 3) AND (annual_reminder_days <@ ARRAY[30, 14, 7]))),
    CONSTRAINT platform_billing_profiles_v156_billing_email_check CHECK (((billing_email IS NULL) OR (billing_email ~* '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$'::text))),
    CONSTRAINT platform_billing_profiles_v156_brand_name_check CHECK (((length(btrim(brand_name)) >= 2) AND (length(btrim(brand_name)) <= 80))),
    CONSTRAINT platform_billing_profiles_v156_check CHECK ((((gst_status = 'registered'::text) AND (length(btrim(gst_registration_number)) >= 4) AND (gst_rate_bps > 0)) OR ((gst_status <> 'registered'::text) AND (gst_registration_number IS NULL) AND (gst_rate_bps = 0)))),
    CONSTRAINT platform_billing_profiles_v156_check1 CHECK (((operation_key IS NULL) = (request_hash IS NULL))),
    CONSTRAINT platform_billing_profiles_v156_currency_check CHECK ((currency = 'SGD'::text)),
    CONSTRAINT platform_billing_profiles_v156_gst_rate_bps_check CHECK (((gst_rate_bps >= 0) AND (gst_rate_bps <= 2000))),
    CONSTRAINT platform_billing_profiles_v156_gst_status_check CHECK ((gst_status = ANY (ARRAY['unconfigured'::text, 'not_registered'::text, 'registered'::text]))),
    CONSTRAINT platform_billing_profiles_v156_internal_copy_email_check CHECK (((internal_copy_email IS NULL) OR (internal_copy_email ~* '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$'::text))),
    CONSTRAINT platform_billing_profiles_v156_legal_name_check CHECK (((length(btrim(legal_name)) >= 2) AND (length(btrim(legal_name)) <= 200))),
    CONSTRAINT platform_billing_profiles_v156_registered_address_check CHECK (((registered_address IS NULL) OR ((length(btrim(registered_address)) >= 5) AND (length(btrim(registered_address)) <= 500)))),
    CONSTRAINT platform_billing_profiles_v156_request_hash_check CHECK (((request_hash IS NULL) OR (request_hash ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT platform_billing_profiles_v156_uen_check CHECK (((uen IS NULL) OR ((length(btrim(uen)) >= 4) AND (length(btrim(uen)) <= 40)))),
    CONSTRAINT platform_billing_profiles_v156_version_check CHECK ((version > 0))
);

--
-- Name: v156_profile_ready(public.platform_billing_profiles_v156); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v156_profile_ready(p_profile public.platform_billing_profiles_v156) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  select p_profile.uen is not null and p_profile.registered_address is not null
    and p_profile.billing_email is not null and p_profile.default_payment_terms is not null
    and p_profile.gst_status in ('not_registered','registered')
$$;

--
-- Name: v156_replay_blocked_billing_events(integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v156_replay_blocked_billing_events(p_limit integer DEFAULT 100) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare r record;v_result jsonb;v_status text;v_prepared integer:=0;v_blocked integer:=0;v_failed integer:=0;
begin
  for r in select p.event_id from public.platform_billing_event_preparations_v156 p
    where p.status in ('blocked','failed') and p.last_attempt_at<=clock_timestamp()-interval '1 minute'
    order by p.last_attempt_at,p.event_id for update skip locked limit least(greatest(p_limit,1),500)
  loop
    begin
      v_result:=app.v156_prepare_billing_event(r.event_id);
      v_status:=case when v_result->>'status'='blocked' then 'blocked' when v_result->>'status' like 'ignored%' then 'ignored' else 'prepared' end;
      update public.platform_billing_event_preparations_v156 set status=v_status,reason=v_result->>'reason',last_result=v_result,
        attempt_count=attempt_count+1,last_attempt_at=clock_timestamp(),prepared_at=case when v_status='prepared' then clock_timestamp() end where event_id=r.event_id;
      if v_status='prepared' then v_prepared:=v_prepared+1;else v_blocked:=v_blocked+1;end if;
    exception when others then
      update public.platform_billing_event_preparations_v156 set status='failed',reason=sqlstate,last_result=jsonb_build_object('status','failed','sqlstate',sqlstate),attempt_count=attempt_count+1,last_attempt_at=clock_timestamp() where event_id=r.event_id;
      v_failed:=v_failed+1;
    end;
  end loop;
  return jsonb_build_object('prepared',v_prepared,'blocked_or_ignored',v_blocked,'failed',v_failed);
end $$;

--
-- Name: v156_run_subscription_automation(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v156_run_subscription_automation() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $_$
declare v_url text;v_secret text;v_request bigint;v_replay jsonb;v_reminders jsonb;
begin
  v_replay:=app.v156_replay_blocked_billing_events(100);
  v_reminders:=public.platform_generate_subscription_reminders_v156((clock_timestamp() at time zone 'Asia/Singapore')::date);
  if to_regnamespace('vault') is null or to_regnamespace('net') is null then
    return jsonb_build_object('replay',v_replay,'reminders',v_reminders,'dispatch','extensions_unavailable');
  end if;
  begin
    execute 'select decrypted_secret from vault.decrypted_secrets where name=$1 order by created_at desc limit 1' into v_url using 'v156_supabase_url';
    execute 'select decrypted_secret from vault.decrypted_secrets where name=$1 order by created_at desc limit 1' into v_secret using 'v156_dispatch_secret';
  exception when others then
    return jsonb_build_object('replay',v_replay,'reminders',v_reminders,'dispatch','vault_unavailable');
  end;
  if coalesce(v_url,'')='' or coalesce(v_secret,'')='' then
    return jsonb_build_object('replay',v_replay,'reminders',v_reminders,'dispatch','secret_unconfigured');
  end if;
  execute 'select net.http_post(url := $1, body := ''{}''::jsonb, headers := jsonb_build_object(''content-type'',''application/json'',''x-v156-dispatch-secret'',$2), timeout_milliseconds := 15000)'
    into v_request using rtrim(v_url,'/')||'/functions/v1/subscription-document-dispatch',v_secret;
  return jsonb_build_object('replay',v_replay,'reminders',v_reminders,'dispatch_request_id',v_request);
end $_$;

--
-- Name: v156_seller_snapshot(public.platform_billing_profiles_v156); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v156_seller_snapshot(p_profile public.platform_billing_profiles_v156) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  select jsonb_build_object('brand_name',p_profile.brand_name,'legal_name',p_profile.legal_name,
    'display_name',p_profile.brand_name||' by '||p_profile.legal_name,'uen',p_profile.uen,
    'registered_address',p_profile.registered_address,'billing_email',p_profile.billing_email,
    'currency',p_profile.currency,'gst_status',p_profile.gst_status,
    'gst_registration_number',case when p_profile.gst_status='registered' then p_profile.gst_registration_number end,
    'gst_rate_bps',case when p_profile.gst_status='registered' then p_profile.gst_rate_bps else 0 end,
    'payment_terms',p_profile.default_payment_terms,'logo_object_path',p_profile.logo_object_path,
    'bank',jsonb_build_object('currency','SGD','account_name',p_profile.bank_account_name,
      'bank_name',p_profile.bank_name,'bank_code',p_profile.bank_code,'branch_code',p_profile.branch_code,
      'swift_code',p_profile.swift_code,'account_number',p_profile.bank_account_number,
      'account_location',p_profile.bank_account_location),
    'contact',jsonb_build_object('name',p_profile.billing_contact_name,'mobile',p_profile.billing_contact_mobile))
$$;

--
-- Name: v156_store_operation(uuid, text, uuid, text, jsonb); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v156_store_operation(p_key uuid, p_type text, p_actor uuid, p_hash text, p_response jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  insert into public.platform_v156_operation_receipts(operation_key,operation_type,actor,request_hash,response)
  values(p_key,p_type,p_actor,p_hash,p_response);
  return p_response||jsonb_build_object('replayed',false);
end $$;

--
-- Name: v156_upsert_task(text, text, uuid, uuid, text, text, text, timestamp with time zone, text, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v156_upsert_task(p_key text, p_type text, p_business uuid, p_prospect uuid, p_subscription text, p_invoice text, p_priority text, p_due timestamp with time zone, p_title text, p_event text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_id uuid;v_owner uuid;
begin
  select assigned_consultant_id into v_owner from public.sme_prospects where id=p_prospect;
  insert into public.platform_subscription_tasks_v156(task_key,task_type,business_id,prospect_id,
    provider_subscription_id,provider_invoice_id,assigned_consultant_id,priority,due_at,title,source_event_id)
  values(p_key,p_type,p_business,p_prospect,p_subscription,p_invoice,v_owner,p_priority,p_due,p_title,p_event)
  on conflict(task_key) do update set due_at=excluded.due_at,priority=excluded.priority,
    title=excluded.title,updated_at=clock_timestamp()
  where platform_subscription_tasks_v156.status='open' returning id into v_id;
  return coalesce(v_id,(select id from public.platform_subscription_tasks_v156 where task_key=p_key));
end $$;

--
-- Name: v175_account_open_immutable_guard(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v175_account_open_immutable_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if tg_op='DELETE'
     and coalesce(
       pg_catalog.current_setting('app.v175_retention_purge',true),''
     )='on'
     and old.retention_until<clock_timestamp() then
    return old;
  end if;
  raise exception 'v175 account-open evidence is append-only'
    using errcode='restrict_violation';
end
$$;

--
-- Name: v176_account_opens_window(uuid, date, date); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v176_account_opens_window(p_business uuid, p_from date, p_to date) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  with window_rows as (
    select day_row.subject_key, day_row.open_date
    from public.customer_account_open_days_v175 day_row
    where day_row.business_id = p_business
      and day_row.open_date between p_from and p_to
  ), subject_first as (
    select day_row.subject_key, min(day_row.open_date) as first_open_date
    from public.customer_account_open_days_v175 day_row
    where day_row.business_id = p_business
    group by day_row.subject_key
  )
  select pg_catalog.jsonb_build_object(
    'from', p_from,
    'to', p_to,
    'opens', (select count(*) from window_rows),
    'distinct_customers', (
      select count(distinct subject_key) from window_rows
    ),
    'first_time_customers', (
      select count(*) from subject_first
      where subject_first.first_open_date between p_from and p_to
    )
  )
$$;

--
-- Name: v176_assert_period(text, date); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v176_assert_period(p_period_kind text, p_period_start date) RETURNS date
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_today date := (clock_timestamp() at time zone 'Asia/Singapore')::date;
  v_end date;
begin
  if p_period_kind is null
     or p_period_kind not in ('monthly','quarterly','yearly') then
    raise exception 'period_kind must be monthly, quarterly or yearly'
      using errcode = '22023';
  end if;
  if p_period_start is null then
    raise exception 'period_start is required' using errcode = '22023';
  end if;
  if p_period_kind = 'monthly'
     and p_period_start <> date_trunc('month', p_period_start)::date then
    raise exception 'monthly period_start must be the first day of a month'
      using errcode = '22023';
  end if;
  if p_period_kind = 'quarterly'
     and p_period_start <> date_trunc('quarter', p_period_start)::date then
    raise exception 'quarterly period_start must be 1 Jan, 1 Apr, 1 Jul or 1 Oct'
      using errcode = '22023';
  end if;
  if p_period_kind = 'yearly'
     and p_period_start <> date_trunc('year', p_period_start)::date then
    raise exception 'yearly period_start must be 1 January'
      using errcode = '22023';
  end if;
  v_end := app.v176_period_end(p_period_kind, p_period_start);
  if v_end >= v_today then
    raise exception 'the requested period has not closed yet'
      using errcode = '22023';
  end if;
  if p_period_start < v_today - interval '5 years' then
    raise exception 'period_start is outside the supported reporting range'
      using errcode = '22023';
  end if;
  return v_end;
end
$$;

--
-- Name: v176_can_read_firm_report(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v176_can_read_firm_report(p_business uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  select auth.uid() is not null
    and (
      app.is_super_admin()
      or app.platform_firm_report_access_v94(p_business)
    )
$$;

--
-- Name: v176_enqueue_ai_firm_reports(text, date); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v176_enqueue_ai_firm_reports(p_period_kind text, p_period_start date) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_end date := app.v176_period_end(p_period_kind, p_period_start);
  v_queued integer := 0;
begin
  if v_end is null then
    raise exception 'period_kind must be monthly, quarterly or yearly'
      using errcode = '22023';
  end if;

  insert into public.ai_firm_reports_v176(
    business_id, period_kind, period_start, period_end, status, model
  )
  select business.id, p_period_kind, p_period_start, v_end,
    'pending', app.v176_model_for_period(p_period_kind)
  from public.businesses business
  join public.business_workspace_controls_v94 control
    on control.business_id = business.id
  where control.approval_status = 'approved'
    and business.is_demo = false
    and business.is_synthetic = false
  on conflict (business_id, period_kind, period_start) do nothing;

  get diagnostics v_queued = row_count;
  return v_queued;
end
$$;

--
-- Name: v176_evidence_pack(uuid, text, date, date); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v176_evidence_pack(p_business uuid, p_period_kind text, p_period_start date, p_period_end date) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_business record;
  v_prior_start date := app.v176_period_prior_start(p_period_kind, p_period_start);
  v_prior_end date := p_period_start - 1;
  v_current jsonb;
  v_prior jsonb;
  v_opens_current jsonb;
  v_opens_prior jsonb;
  v_gated jsonb;
begin
  select business.id, business.name, business.industry, business.is_demo
  into v_business
  from public.businesses business
  where business.id = p_business;
  if not found then
    raise exception 'business_not_found' using errcode = '22023';
  end if;

  v_current := app.v176_sales_window(p_business, p_period_start, p_period_end);
  v_prior := app.v176_sales_window(p_business, v_prior_start, v_prior_end);
  v_opens_current := app.v176_account_opens_window(
    p_business, p_period_start, p_period_end
  );
  v_opens_prior := app.v176_account_opens_window(
    p_business, v_prior_start, v_prior_end
  );
  v_gated := app.v176_gated_evidence(p_business, p_period_start, p_period_end);

  return pg_catalog.jsonb_build_object(
    'contract_version', 'v176',
    'generated_at', now(),
    'timezone', 'Asia/Singapore',
    'currency', 'SGD',
    'scope', pg_catalog.jsonb_build_object(
      'business_id', v_business.id,
      'business_name', v_business.name,
      'industry', v_business.industry,
      'period_kind', p_period_kind,
      'period_start', p_period_start,
      'period_end', p_period_end,
      'prior_period_start', v_prior_start,
      'prior_period_end', v_prior_end
    ),
    'sales', pg_catalog.jsonb_build_object(
      'current', v_current,
      'prior', v_prior,
      'growth', pg_catalog.jsonb_build_object(
        'net_revenue_cents_delta',
          (v_current->>'net_revenue_cents')::bigint
            - (v_prior->>'net_revenue_cents')::bigint,
        'net_revenue_pct',
          case when (v_prior->>'net_revenue_cents')::bigint > 0
            then round(
              ((v_current->>'net_revenue_cents')::numeric
                - (v_prior->>'net_revenue_cents')::numeric)
              * 100 / (v_prior->>'net_revenue_cents')::numeric, 1)
            else null end,
        'revenue_transactions_delta',
          (v_current->>'revenue_transactions')::bigint
            - (v_prior->>'revenue_transactions')::bigint,
        'customers_served_delta',
          (v_current->>'customers_served')::bigint
            - (v_prior->>'customers_served')::bigint,
        'new_customers_delta',
          (v_current->>'new_customers')::bigint
            - (v_prior->>'new_customers')::bigint
      )
    ),
    'insights', app.v179_business_insights(
      p_business, p_period_start, p_period_end, v_prior_start, v_prior_end
    ),
    'account_opens', pg_catalog.jsonb_build_object(
      'current', v_opens_current,
      'prior', v_opens_prior,
      'report', v_gated->'account_opens_report'
    ),
    'consultant_brief', v_gated->'consultant_brief',
    'catalogue_affinity', v_gated->'catalogue_affinity',
    'recommendations', v_gated->'recommendations',
    'evidence_completeness', pg_catalog.jsonb_build_object(
      'gated_rpcs_available',
        coalesce((v_gated->>'available')::boolean, false),
      'gated_rpcs_reason', v_gated->>'reason',
      'synthetic_customers_excluded', true,
      'reversed_sales_excluded', true,
      'revenue_definition',
        'per-sale v10.1 policy snapshot (counts_as_revenue)',
      'insights_version', 'v179'
    )
  );
end
$$;

--
-- Name: v176_gated_evidence(uuid, date, date); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v176_gated_evidence(p_business uuid, p_from date, p_to date) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_reader uuid;
  v_prior_sub text;
  v_prior_claims text;
  v_impersonated boolean := false;
  v_result jsonb;
begin
  if auth.uid() is null then
    select super_admin.user_id into v_reader
    from public.super_admins super_admin
    order by super_admin.user_id
    limit 1;
    if v_reader is null then
      return pg_catalog.jsonb_build_object(
        'available', false, 'reason', 'no_platform_reader'
      );
    end if;
    v_prior_sub := coalesce(
      pg_catalog.current_setting('request.jwt.claim.sub', true), ''
    );
    v_prior_claims := coalesce(
      pg_catalog.current_setting('request.jwt.claims', true), ''
    );
    perform pg_catalog.set_config(
      'request.jwt.claim.sub', v_reader::text, true
    );
    perform pg_catalog.set_config(
      'request.jwt.claims',
      pg_catalog.json_build_object(
        'sub', v_reader, 'role', 'authenticated', 'aud', 'authenticated'
      )::text,
      true
    );
    v_impersonated := true;
  end if;

  begin
    v_result := pg_catalog.jsonb_build_object(
      'available', true,
      'consultant_brief',
        public.platform_get_assigned_firm_report_v94(
          p_business, null, p_from, p_to
        ),
      'catalogue_affinity',
        public.platform_get_catalogue_affinity_v94(
          p_business, null, p_from, p_to, 25
        ),
      'recommendations',
        public.platform_get_consultative_recommendations_v94(
          p_business, null, p_from, p_to, 25
        ),
      'account_opens_report',
        public.platform_customer_account_opens_v175(p_business, p_from, p_to)
    );
  exception when others then
    v_result := pg_catalog.jsonb_build_object(
      'available', false, 'reason', 'evidence_rpc_unavailable'
    );
  end;

  if v_impersonated then
    perform pg_catalog.set_config(
      'request.jwt.claim.sub', v_prior_sub, true
    );
    perform pg_catalog.set_config(
      'request.jwt.claims', v_prior_claims, true
    );
  end if;
  return v_result;
end
$$;

--
-- Name: v176_is_assigned_consultant(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v176_is_assigned_consultant(p_business uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  select auth.uid() is not null
    and exists(
      select 1
      from app.assigned_consultant_v94(p_business) consultant
      where consultant.user_id = auth.uid()
    )
$$;

--
-- Name: v176_model_for_period(text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v176_model_for_period(p_period_kind text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  select case p_period_kind
    when 'monthly' then 'claude-sonnet-5'
    else 'claude-opus-4-8'
  end
$$;

--
-- Name: v176_period_end(text, date); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v176_period_end(p_period_kind text, p_period_start date) RETURNS date
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  select case p_period_kind
    when 'monthly' then (p_period_start + interval '1 month' - interval '1 day')::date
    when 'quarterly' then (p_period_start + interval '3 months' - interval '1 day')::date
    when 'yearly' then (p_period_start + interval '1 year' - interval '1 day')::date
  end
$$;

--
-- Name: v176_period_prior_start(text, date); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v176_period_prior_start(p_period_kind text, p_period_start date) RETURNS date
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  select case p_period_kind
    when 'monthly' then (p_period_start - interval '1 month')::date
    when 'quarterly' then (p_period_start - interval '3 months')::date
    when 'yearly' then (p_period_start - interval '1 year')::date
  end
$$;

--
-- Name: v176_reward_gate_label(uuid, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v176_reward_gate_label(p_business uuid, p_min_tier_id uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  select t.name from public.loyalty_tiers t
   where t.business_id = p_business and t.id = p_min_tier_id
     and t.deleted_at is null and not t.paused
   limit 1;
$$;

--
-- Name: v176_reward_gate_threshold(uuid, uuid, integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v176_reward_gate_threshold(p_business uuid, p_min_tier_id uuid, p_min_tier_threshold integer) RETURNS integer
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_live integer;
begin
  if p_min_tier_id is null and p_min_tier_threshold is null then
    return null;
  end if;
  if p_min_tier_id is not null then
    select threshold into v_live
      from public.loyalty_tiers
     where business_id = p_business and id = p_min_tier_id
       and deleted_at is null and not paused
     limit 1;
    if v_live is not null then
      return v_live;
    end if;
  end if;
  return p_min_tier_threshold;
end $$;

--
-- Name: v176_run_scheduled_ai_firm_reports(date); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v176_run_scheduled_ai_firm_reports(p_today date DEFAULT NULL::date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $_$
declare
  v_today date := coalesce(
    p_today, (clock_timestamp() at time zone 'Asia/Singapore')::date
  );
  v_yesterday date := v_today - 1;
  v_monthly integer := 0;
  v_quarterly integer := 0;
  v_yearly integer := 0;
  v_url text;
  v_secret text;
  v_request bigint;
begin
  if extract(day from v_today) = 1 then
    v_monthly := app.v176_enqueue_ai_firm_reports(
      'monthly', date_trunc('month', v_yesterday)::date
    );
    if extract(month from v_today) in (1, 4, 7, 10) then
      v_quarterly := app.v176_enqueue_ai_firm_reports(
        'quarterly', date_trunc('quarter', v_yesterday)::date
      );
    end if;
    if extract(month from v_today) = 1 then
      v_yearly := app.v176_enqueue_ai_firm_reports(
        'yearly', date_trunc('year', v_yesterday)::date
      );
    end if;
  end if;

  if v_monthly + v_quarterly + v_yearly = 0
     and not exists(
       select 1 from public.ai_firm_reports_v176 where status = 'pending'
     ) then
    return pg_catalog.jsonb_build_object(
      'today', v_today, 'queued', 0, 'dispatch', 'nothing_pending'
    );
  end if;

  -- Dispatch mirrors app.v156_run_subscription_automation: pg_net + Vault.
  if to_regnamespace('vault') is null or to_regnamespace('net') is null then
    return pg_catalog.jsonb_build_object(
      'today', v_today, 'monthly', v_monthly, 'quarterly', v_quarterly,
      'yearly', v_yearly, 'dispatch', 'extensions_unavailable'
    );
  end if;
  begin
    execute 'select decrypted_secret from vault.decrypted_secrets where name=$1 order by created_at desc limit 1'
      into v_url using 'v176_supabase_url';
    if coalesce(v_url, '') = '' then
      execute 'select decrypted_secret from vault.decrypted_secrets where name=$1 order by created_at desc limit 1'
        into v_url using 'v156_supabase_url';
    end if;
    execute 'select decrypted_secret from vault.decrypted_secrets where name=$1 order by created_at desc limit 1'
      into v_secret using 'v176_dispatch_secret';
  exception when others then
    return pg_catalog.jsonb_build_object(
      'today', v_today, 'monthly', v_monthly, 'quarterly', v_quarterly,
      'yearly', v_yearly, 'dispatch', 'vault_unavailable'
    );
  end;
  if coalesce(v_url, '') = '' or coalesce(v_secret, '') = '' then
    return pg_catalog.jsonb_build_object(
      'today', v_today, 'monthly', v_monthly, 'quarterly', v_quarterly,
      'yearly', v_yearly, 'dispatch', 'secret_unconfigured'
    );
  end if;

  execute 'select net.http_post(url := $1, body := ''{}''::jsonb, headers := jsonb_build_object(''content-type'',''application/json'',''x-v176-dispatch-secret'',$2), timeout_milliseconds := 20000)'
    into v_request
    using rtrim(v_url, '/') || '/functions/v1/ai-firm-reports', v_secret;

  return pg_catalog.jsonb_build_object(
    'today', v_today, 'monthly', v_monthly, 'quarterly', v_quarterly,
    'yearly', v_yearly, 'dispatch_request_id', v_request
  );
end
$_$;

--
-- Name: v176_sales_window(uuid, date, date); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v176_sales_window(p_business uuid, p_from date, p_to date) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  with bounds as (
    select
      p_from::timestamp at time zone 'Asia/Singapore' as from_ts,
      (p_to + 1)::timestamp at time zone 'Asia/Singapore' as to_ts
  ), valid_sales as (
    select sale.id, sale.client_id, sale.amount_cents,
      coalesce(sale.counts_as_revenue, true) as counts_as_revenue,
      coalesce(sale.counts_as_visit, true) as counts_as_visit
    from public.sales sale, bounds
    where sale.business_id = p_business
      and sale.reversal_of is null
      and sale.occurred_at >= bounds.from_ts
      and sale.occurred_at < bounds.to_ts
      and not exists(
        select 1 from public.sales reversal
        where reversal.business_id = sale.business_id
          and reversal.reversal_of = sale.id
      )
  ), first_purchase as (
    select sale.client_id,
      min((sale.occurred_at at time zone 'Asia/Singapore')::date) as first_date
    from public.sales sale
    join public.clients client
      on client.id = sale.client_id
     and client.business_id = sale.business_id
     and client.is_synthetic = false
    where sale.business_id = p_business
      and sale.reversal_of is null
      and sale.client_id is not null
      and coalesce(sale.counts_as_visit, true)
      and not exists(
        select 1 from public.sales reversal
        where reversal.business_id = sale.business_id
          and reversal.reversal_of = sale.id
      )
    group by sale.client_id
  )
  select pg_catalog.jsonb_build_object(
    'from', p_from,
    'to', p_to,
    'currency', 'SGD',
    'net_revenue_cents', coalesce(
      (select sum(amount_cents) from valid_sales where counts_as_revenue), 0
    ),
    'revenue_transactions', (
      select count(*) from valid_sales where counts_as_revenue
    ),
    'visits', (select count(*) from valid_sales where counts_as_visit),
    'customers_served', (
      select count(distinct client_id)
      from valid_sales where client_id is not null
    ),
    'average_order_cents', coalesce(
      (select round(avg(amount_cents))::bigint
       from valid_sales where counts_as_revenue), 0
    ),
    'new_customers', (
      select count(*) from first_purchase
      where first_purchase.first_date between p_from and p_to
    )
  )
$$;

--
-- Name: v176_tier_gate_metric(uuid, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v176_tier_gate_metric(p_business uuid, p_client uuid) RETURNS numeric
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_basis text;
  v_metric numeric := 0;
  v_points_programme uuid;
begin
  select coalesce(tier_basis,'visits') into v_basis
    from public.loyalty_programs
   where business_id = p_business and active
   limit 1;

  if v_basis = 'spend' then
    select coalesce(sum(amount_cents),0)/100.0 into v_metric
      from public.sales
     where business_id = p_business and client_id = p_client and counts_as_revenue;
  elsif v_basis = 'points_earned' then
    -- v310 D1, identical to public.customer_get_effective_tier_v143. Fail OPEN on a missing
    -- spine row: the reward gate must never tighten because a projection row went absent.
    select spine.id into v_points_programme
      from public.business_programmes spine
     where spine.business_id = p_business and spine.kind = 'points';
    if v_points_programme is null then
      select coalesce(sum(points),0) into v_metric
        from public.points_ledger
       where business_id = p_business and client_id = p_client and entry_type = 'earn';
    else
      select coalesce(sum(ledger.points),0) into v_metric
        from public.points_ledger ledger
       where ledger.business_id = p_business and ledger.client_id = p_client
         and ledger.entry_type = 'earn' and ledger.programme_id = v_points_programme;
    end if;
  else
    select count(*) into v_metric
      from public.sales
     where business_id = p_business and client_id = p_client and counts_as_visit;
  end if;
  return coalesce(v_metric,0);
end $$;

--
-- Name: FUNCTION v176_tier_gate_metric(p_business uuid, p_client uuid); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.v176_tier_gate_metric(p_business uuid, p_client uuid) IS 'v310 D1 twin of public.customer_get_effective_tier_v143: points_earned fuel is scoped to the v308 points spine row, fail-OPEN when that row is missing. Changed in the SAME transaction as the ladder so the reward gate and the ladder can never disagree.';

--
-- Name: v176_touch_updated_at(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v176_touch_updated_at() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  new.updated_at := now();
  return new;
end
$$;

--
-- Name: v177_appointments(uuid, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v177_appointments(p_business uuid, p_branch uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  with bounds as (
    select
      (clock_timestamp() at time zone 'Asia/Singapore')::date as today
  ), window_bounds as (
    select
      bounds.today as from_date,
      bounds.today + 7 as to_date,
      bounds.today::timestamp at time zone 'Asia/Singapore' as from_ts,
      (bounds.today + 8)::timestamp at time zone 'Asia/Singapore' as to_ts
    from bounds
  ), matched as (
    select appointment.id, appointment.starts_at, appointment.ends_at,
      appointment.status, appointment.party_size, appointment.branch_id,
      appointment.service_id, appointment.staff_id, appointment.client_id
    from public.appointments appointment, window_bounds
    where appointment.business_id = p_business
      and appointment.starts_at >= window_bounds.from_ts
      and appointment.starts_at < window_bounds.to_ts
      and (p_branch is null or appointment.branch_id = p_branch)
  ), capped as (
    select * from matched order by starts_at asc, id asc limit 50
  )
  select pg_catalog.jsonb_build_object(
    'from', (select from_date from window_bounds),
    'to', (select to_date from window_bounds),
    'row_cap', 50,
    'total', (select count(*) from matched),
    'truncated', (select count(*) from matched) > 50,
    'ordering', 'soonest_first',
    'rows', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', capped.id,
        'starts_at', capped.starts_at,
        'ends_at', capped.ends_at,
        'status', capped.status,
        'party_size', capped.party_size,
        'branch_id', capped.branch_id,
        'branch_name', branch.name,
        'service_name', service.name,
        'staff_name', member.full_name,
        -- Abbreviated on purpose: the mirror shows the operations shape, and
        -- must never become a customer-contact export.
        'guest_label', app.v177_person_label(client.full_name, capped.client_id)
      ) order by capped.starts_at asc, capped.id asc)
      from capped
      left join public.branches branch
        on branch.id = capped.branch_id and branch.business_id = p_business
      left join public.services service
        on service.id = capped.service_id and service.business_id = p_business
      left join public.staff member
        on member.id = capped.staff_id and member.business_id = p_business
      left join public.clients client
        on client.id = capped.client_id and client.business_id = p_business
    ), '[]'::jsonb)
  )
$$;

--
-- Name: v177_can_view_workspace(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v177_can_view_workspace(p_business uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  select auth.uid() is not null
    and (
      app.is_super_admin()
      or app.v176_is_assigned_consultant(p_business)
    )
$$;

--
-- Name: FUNCTION v177_can_view_workspace(p_business uuid); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.v177_can_view_workspace(p_business uuid) IS 'v177 workspace-mirror gate: super admin, or the consultant assigned to this firm. Reading is allowed for paused and demo firms.';

--
-- Name: v177_customers(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v177_customers(p_business uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  with bounds as (
    select (clock_timestamp() at time zone 'Asia/Singapore')::date as today
  ), real_clients as (
    select client.id, client.full_name, client.created_at
    from public.clients client
    where client.business_id = p_business
      and coalesce(client.is_synthetic, false) = false
  ), recent as (
    select * from real_clients order by created_at desc, id desc limit 10
  )
  select pg_catalog.jsonb_build_object(
    'total', (select count(*) from real_clients),
    'joined_last_30_days', (
      select count(*) from real_clients, bounds
      where (real_clients.created_at at time zone 'Asia/Singapore')::date
        between bounds.today - 29 and bounds.today
    ),
    'joined_prior_30_days', (
      select count(*) from real_clients, bounds
      where (real_clients.created_at at time zone 'Asia/Singapore')::date
        between bounds.today - 59 and bounds.today - 30
    ),
    'row_cap', 10,
    -- Counts plus an abbreviated ten-row sample. No contact detail is
    -- selected at all, so none can leak through the mirror.
    'recent', coalesce((
      select jsonb_agg(jsonb_build_object(
        'label', app.v177_person_label(recent.full_name, recent.id),
        'joined_on', (recent.created_at at time zone 'Asia/Singapore')::date,
        'visit_count', (
          select count(*) from public.sales sale
          where sale.business_id = p_business
            and sale.client_id = recent.id
            and coalesce(sale.counts_as_visit, true)
            and sale.reversal_of is null
        )
      ) order by recent.created_at desc, recent.id desc)
      from recent
    ), '[]'::jsonb)
  )
$$;

--
-- Name: v177_overview(uuid, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v177_overview(p_business uuid, p_branch uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_today date := (clock_timestamp() at time zone 'Asia/Singapore')::date;
  v_current_from date;
  v_prior_from date;
  v_prior_to date;
  v_current jsonb;
  v_prior jsonb;
  v_growth jsonb;
begin
  v_current_from := v_today - 29;
  v_prior_to := v_today - 30;
  v_prior_from := v_today - 59;

  if p_branch is null then
    v_current := app.v176_sales_window(p_business, v_current_from, v_today);
    v_prior := app.v176_sales_window(p_business, v_prior_from, v_prior_to);
  else
    v_current := app.v177_sales_window(p_business, p_branch, v_current_from, v_today);
    v_prior := app.v177_sales_window(p_business, p_branch, v_prior_from, v_prior_to);
  end if;

  v_growth := jsonb_build_object(
    'net_revenue_pct', case
      when coalesce((v_prior->>'net_revenue_cents')::numeric, 0) = 0 then null
      else round(
        ((v_current->>'net_revenue_cents')::numeric
          - (v_prior->>'net_revenue_cents')::numeric)
        * 100 / (v_prior->>'net_revenue_cents')::numeric, 1)
    end,
    'visits_delta',
      coalesce((v_current->>'visits')::bigint, 0)
      - coalesce((v_prior->>'visits')::bigint, 0),
    'new_customers_delta',
      coalesce((v_current->>'new_customers')::bigint, 0)
      - coalesce((v_prior->>'new_customers')::bigint, 0)
  );

  return jsonb_build_object(
    'window', jsonb_build_object(
      'current', jsonb_build_object('from', v_current_from, 'to', v_today),
      'prior', jsonb_build_object('from', v_prior_from, 'to', v_prior_to)
    ),
    'sales', jsonb_build_object(
      'current', v_current, 'prior', v_prior, 'growth', v_growth
    ),
    -- v175 account-open days carry no branch, so this block is always the
    -- whole firm. It is labelled as such rather than silently branch-filtered.
    'account_opens', jsonb_build_object(
      'scope', 'whole_firm',
      'current', app.v176_account_opens_window(p_business, v_current_from, v_today),
      'prior', app.v176_account_opens_window(p_business, v_prior_from, v_prior_to)
    ),
    'outstanding', jsonb_build_object(
      'scope', 'whole_firm',
      'points', coalesce(
        (select sum(entry.points) from public.points_ledger entry
         where entry.business_id = p_business), 0
      ),
      'pot_is_split', app.programme_pot_is_split_v310(p_business),
      'by_programme_note',
        'ledger tag provenance, not a spendable pot (V309 currentness gap)',
      'points_outstanding_by_programme_tag', case
        when app.programme_pot_is_split_v310(p_business) then null
        else coalesce((
          select jsonb_agg(jsonb_build_object('kind', spine.kind, 'points', tag.points)
                   order by spine.sort)
            from (
              select entry.programme_id, sum(entry.points) as points
                from public.points_ledger entry
               where entry.business_id = p_business
               group by entry.programme_id
            ) tag
            join public.business_programmes spine on spine.id = tag.programme_id
        ), '[]'::jsonb) end,
      'credit_cents', coalesce(
        (select sum(entry.amount_cents) from public.credit_ledger entry
         where entry.business_id = p_business), 0
      )
    ),
    'counts', jsonb_build_object(
      'customers', (
        select count(*) from public.clients client
        where client.business_id = p_business
          and coalesce(client.is_synthetic, false) = false
      ),
      'active_staff', (
        select count(*) from public.staff member
        where member.business_id = p_business and member.active
      ),
      'active_branches', (
        select count(*) from public.branches branch
        where branch.business_id = p_business and branch.active
      )
    )
  );
end
$$;

--
-- Name: v177_person_label(text, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v177_person_label(p_full_name text, p_id uuid) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_parts text[];
  v_count integer;
begin
  v_parts := regexp_split_to_array(btrim(coalesce(p_full_name, '')), '\s+');
  v_parts := array_remove(v_parts, '');
  v_count := coalesce(array_length(v_parts, 1), 0);

  if v_count = 0 then
    return 'Guest ' || upper(right(coalesce(p_id::text, '0000'), 4));
  end if;
  if v_count = 1 then
    return v_parts[1];
  end if;
  return v_parts[1] || ' ' || upper(left(v_parts[v_count], 1)) || '.';
end
$$;

--
-- Name: FUNCTION v177_person_label(p_full_name text, p_id uuid); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.v177_person_label(p_full_name text, p_id uuid) IS 'v177 privacy helper: renders a person as "First L." for the read-only workspace mirror. Never returns a phone number or an email address.';

--
-- Name: v177_programmes(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v177_programmes(p_business uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  select pg_catalog.jsonb_build_object(
    'loyalty', coalesce((
      select jsonb_build_object(
        'configured', true,
        'active', program.active,
        'loyalty_model', program.loyalty_model,
        'configuration_status', program.configuration_status,
        'earn_points_per_dollar', program.earn_points_per_dollar,
        'redeem_points', program.redeem_points,
        'reward_credit_cents', program.reward_credit_cents,
        'stamp_target', program.stamp_target,
        'stamp_per_cents', program.stamp_per_cents,
        'expiry_mode', program.expiry_mode,
        'expiry_days', program.expiry_days
      )
      from public.loyalty_programs program
      where program.business_id = p_business
      order by program.active desc, program.id
      limit 1
    ), jsonb_build_object('configured', false)),
    'rewards', jsonb_build_object(
      'active', (
        select count(*) from public.loyalty_rewards reward
        where reward.business_id = p_business and reward.active
      ),
      'total', (
        select count(*) from public.loyalty_rewards reward
        where reward.business_id = p_business
      )
    ),
    'tiers', (
      select count(*) from public.loyalty_tiers tier
      where tier.business_id = p_business
    ),
    'promotions', jsonb_build_object(
      'active_retention_programmes', (
        select count(*) from public.retention_programs program
        where program.business_id = p_business and program.active and program.deleted_at is null
      ),
      'total_retention_programmes', (
        select count(*) from public.retention_programs program
        where program.business_id = p_business and program.deleted_at is null
      ),
      'active_campaigns', (
        select count(*) from public.retention_campaigns campaign
        where campaign.business_id = p_business
          and campaign.status = 'active'
      )
    ),
    'referral', coalesce((
      select jsonb_build_object(
        'configured', true,
        'enabled', program.enabled,
        'reward_cents', program.reward_cents,
        'min_spend_cents', program.min_spend_cents
      )
      from public.referral_programs program
      where program.business_id = p_business
      order by program.created_at desc, program.id
      limit 1
    ), jsonb_build_object('configured', false))
  )
$$;

--
-- Name: v177_sales_window(uuid, uuid, date, date); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v177_sales_window(p_business uuid, p_branch uuid, p_from date, p_to date) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  with bounds as (
    select
      p_from::timestamp at time zone 'Asia/Singapore' as from_ts,
      (p_to + 1)::timestamp at time zone 'Asia/Singapore' as to_ts
  ), valid_sales as (
    select sale.id, sale.client_id, sale.amount_cents,
      coalesce(sale.counts_as_revenue, true) as counts_as_revenue,
      coalesce(sale.counts_as_visit, true) as counts_as_visit
    from public.sales sale, bounds
    where sale.business_id = p_business
      and sale.branch_id = p_branch
      and sale.reversal_of is null
      and sale.occurred_at >= bounds.from_ts
      and sale.occurred_at < bounds.to_ts
      and not exists(
        select 1 from public.sales reversal
        where reversal.business_id = sale.business_id
          and reversal.reversal_of = sale.id
      )
  ), first_purchase as (
    select sale.client_id,
      min((sale.occurred_at at time zone 'Asia/Singapore')::date) as first_date
    from public.sales sale
    join public.clients client
      on client.id = sale.client_id
     and client.business_id = sale.business_id
     and client.is_synthetic = false
    where sale.business_id = p_business
      and sale.branch_id = p_branch
      and sale.reversal_of is null
      and sale.client_id is not null
      and coalesce(sale.counts_as_visit, true)
      and not exists(
        select 1 from public.sales reversal
        where reversal.business_id = sale.business_id
          and reversal.reversal_of = sale.id
      )
    group by sale.client_id
  )
  select pg_catalog.jsonb_build_object(
    'from', p_from,
    'to', p_to,
    'currency', 'SGD',
    'net_revenue_cents', coalesce(
      (select sum(amount_cents) from valid_sales where counts_as_revenue), 0
    ),
    'revenue_transactions', (
      select count(*) from valid_sales where counts_as_revenue
    ),
    'visits', (select count(*) from valid_sales where counts_as_visit),
    'customers_served', (
      select count(distinct client_id)
      from valid_sales where client_id is not null
    ),
    'average_order_cents', coalesce(
      (select round(avg(amount_cents))::bigint
       from valid_sales where counts_as_revenue), 0
    ),
    'new_customers', (
      select count(*) from first_purchase
      where first_purchase.first_date between p_from and p_to
    )
  )
$$;

--
-- Name: FUNCTION v177_sales_window(p_business uuid, p_branch uuid, p_from date, p_to date); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.v177_sales_window(p_business uuid, p_branch uuid, p_from date, p_to date) IS 'v177 branch-scoped twin of app.v176_sales_window. Same revenue and visit definition, one extra branch predicate. NULL p_branch is not meaningful here - the caller uses v176_sales_window for the whole firm.';

--
-- Name: v177_staff(uuid, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v177_staff(p_business uuid, p_branch uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  with roster as (
    select member.id, member.full_name, member.role, member.title,
      member.active, member.user_id,
      (select count(*) from public.staff_branches assignment
       where assignment.staff_id = member.id
         and assignment.business_id = p_business) as branch_count
    from public.staff member
    where member.business_id = p_business
      and (
        p_branch is null
        or exists(
          select 1 from public.staff_branches assignment
          where assignment.staff_id = member.id
            and assignment.business_id = p_business
            and assignment.branch_id = p_branch
        )
        or not exists(
          select 1 from public.staff_branches assignment
          where assignment.staff_id = member.id
            and assignment.business_id = p_business
        )
      )
  ), capped as (
    select * from roster order by active desc, full_name asc, id asc limit 100
  )
  select pg_catalog.jsonb_build_object(
    'total', (select count(*) from roster),
    'active', (select count(*) from roster where active),
    'with_login', (select count(*) from roster where user_id is not null and active),
    'row_cap', 100,
    'truncated', (select count(*) from roster) > 100,
    -- Staff are business-internal records; full names are intentional here.
    -- Contact columns are still not selected.
    'rows', coalesce((
      select jsonb_agg(jsonb_build_object(
        'full_name', capped.full_name,
        'role', capped.role,
        'title', capped.title,
        'active', capped.active,
        'has_login', capped.user_id is not null,
        'branch_count', capped.branch_count
      ) order by capped.active desc, capped.full_name asc, capped.id asc)
      from capped
    ), '[]'::jsonb)
  )
$$;

--
-- Name: v179_business_insights(uuid, date, date, date, date); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v179_business_insights(p_business uuid, p_from date, p_to date, p_prior_from date, p_prior_to date) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  with bounds as (
    select
      p_from::timestamp at time zone 'Asia/Singapore' as from_ts,
      (p_to + 1)::timestamp at time zone 'Asia/Singapore' as to_ts,
      p_prior_from::timestamp at time zone 'Asia/Singapore' as prior_from_ts,
      (p_prior_to + 1)::timestamp at time zone 'Asia/Singapore' as prior_to_ts,
      (p_to + 1)::timestamp at time zone 'Asia/Singapore' - interval '45 days' as at_risk_before_ts,
      (p_to + 1)::timestamp at time zone 'Asia/Singapore' - interval '180 days' as at_risk_after_ts
  ), lifetime_sales as (
    -- All unreversed visit/revenue-bearing sales for real clients of this firm.
    select sale.id, sale.client_id, sale.amount_cents, sale.occurred_at,
      coalesce(sale.counts_as_revenue, true) as counts_as_revenue,
      coalesce(sale.counts_as_visit, true) as counts_as_visit
    from public.sales sale
    join public.clients client
      on client.id = sale.client_id
     and client.business_id = sale.business_id
     and coalesce(client.is_synthetic, false) = false
    where sale.business_id = p_business
      and sale.reversal_of is null
      and sale.client_id is not null
      and not exists(
        select 1 from public.sales reversal
        where reversal.business_id = sale.business_id
          and reversal.reversal_of = sale.id
      )
  ), client_lifetime as (
    select client_id,
      min(occurred_at) filter (where counts_as_visit) as first_visit_at,
      max(occurred_at) filter (where counts_as_visit) as last_visit_at,
      count(*) filter (where counts_as_visit) as lifetime_visits,
      coalesce(sum(amount_cents) filter (where counts_as_revenue), 0) as lifetime_revenue_cents
    from lifetime_sales
    group by client_id
  ), window_sales as (
    select lifetime_sales.*
    from lifetime_sales, bounds
    where occurred_at >= bounds.from_ts and occurred_at < bounds.to_ts
  ), window_clients as (
    select ws.client_id,
      coalesce(sum(ws.amount_cents) filter (where ws.counts_as_revenue), 0) as revenue_cents,
      count(*) filter (where ws.counts_as_visit) as visits,
      bool_and(cl.first_visit_at >= bounds.from_ts) as is_new
    from window_sales ws
    join client_lifetime cl on cl.client_id = ws.client_id
    cross join bounds
    group by ws.client_id
  ), window_revenue as (
    select coalesce(sum(revenue_cents), 0) as total_cents from window_clients
  ), prior_new_clients as (
    -- Clients whose first-ever visit fell in the PRIOR window.
    select cl.client_id
    from client_lifetime cl, bounds
    where cl.first_visit_at >= bounds.prior_from_ts
      and cl.first_visit_at < bounds.prior_to_ts
  ), prior_new_returned as (
    select count(*) as returned
    from prior_new_clients pnc
    where exists(select 1 from window_clients wc
                 where wc.client_id = pnc.client_id and wc.visits > 0)
  ), at_risk as (
    -- Regulars (2+ lifetime visits) whose last visit is 45-180 days old at
    -- period end. Recovery value = one visit each at their own average ticket.
    select cl.client_id,
      cl.lifetime_visits,
      cl.lifetime_revenue_cents,
      case when cl.lifetime_visits > 0
        then (cl.lifetime_revenue_cents / cl.lifetime_visits)::bigint
        else 0 end as avg_ticket_cents
    from client_lifetime cl, bounds
    where cl.lifetime_visits >= 2
      and cl.last_visit_at < bounds.at_risk_before_ts
      and cl.last_visit_at >= bounds.at_risk_after_ts
  ), weekday as (
    select extract(isodow from (occurred_at at time zone 'Asia/Singapore'))::int as isodow,
      coalesce(sum(amount_cents) filter (where counts_as_revenue), 0) as revenue_cents,
      count(*) filter (where counts_as_visit) as visits
    from window_sales
    group by 1
  ), items as (
    select si.description,
      sum(si.qty)::bigint as qty,
      coalesce(sum(si.line_cents), 0)::bigint as revenue_cents
    from public.sale_items si
    join window_sales ws on ws.id = si.sale_id
    where si.business_id = p_business
    group by si.description
  ), points_window as (
    select
      coalesce(sum(points) filter (where entry_type = 'earn'), 0)::bigint as earned,
      coalesce(-sum(points) filter (where entry_type = 'redeem'), 0)::bigint as redeemed
    from public.points_ledger, bounds
    where business_id = p_business
      and created_at >= bounds.from_ts and created_at < bounds.to_ts
  )
  select pg_catalog.jsonb_build_object(
    'contract_version', 'v179',
    'retention', pg_catalog.jsonb_build_object(
      'customers_served', (select count(*) from window_clients where visits > 0),
      'new_customers', (select count(*) from window_clients where is_new and visits > 0),
      'returning_customers', (select count(*) from window_clients where not is_new and visits > 0),
      'repeat_rate_pct', (
        select case when count(*) filter (where visits > 0) = 0 then null
          else round(100.0 * count(*) filter (where not is_new and visits > 0)
                     / count(*) filter (where visits > 0), 1) end
        from window_clients
      ),
      'prior_period_new_customers', (select count(*) from prior_new_clients),
      'prior_new_who_returned_this_period', (select returned from prior_new_returned),
      'prior_new_return_rate_pct', (
        select case when (select count(*) from prior_new_clients) = 0 then null
          else round(100.0 * (select returned from prior_new_returned)
                     / (select count(*) from prior_new_clients), 1) end
      )
    ),
    'at_risk', pg_catalog.jsonb_build_object(
      'definition', 'customers with 2+ lifetime visits whose last visit is 45-180 days before period end',
      'customers', (select count(*) from at_risk),
      'their_lifetime_revenue_cents', (select coalesce(sum(lifetime_revenue_cents), 0) from at_risk),
      'recovery_value_one_visit_each_cents', (select coalesce(sum(avg_ticket_cents), 0) from at_risk)
    ),
    'top_customers', pg_catalog.jsonb_build_object(
      'rows', coalesce((
        select jsonb_agg(jsonb_build_object(
          'label', app.v177_person_label(client.full_name, wc.client_id),
          'revenue_cents', wc.revenue_cents,
          'visits', wc.visits,
          'is_new_this_period', wc.is_new
        ) order by wc.revenue_cents desc, wc.client_id)
        from (select * from window_clients order by revenue_cents desc limit 5) wc
        join public.clients client on client.id = wc.client_id
        where wc.revenue_cents > 0
      ), '[]'::jsonb),
      'top1_share_pct', (
        select case when wr.total_cents = 0 then null
          else round(100.0 * (select max(revenue_cents) from window_clients) / wr.total_cents, 1) end
        from window_revenue wr
      ),
      'top5_share_pct', (
        select case when wr.total_cents = 0 then null
          else round(100.0 * (
            select coalesce(sum(revenue_cents), 0)
            from (select revenue_cents from window_clients
                  order by revenue_cents desc limit 5) top5
          ) / wr.total_cents, 1) end
        from window_revenue wr
      )
    ),
    'weekday_pattern', pg_catalog.jsonb_build_object(
      'note', 'isodow: 1=Monday .. 7=Sunday, Singapore time',
      'rows', coalesce((
        select jsonb_agg(jsonb_build_object(
          'isodow', isodow, 'revenue_cents', revenue_cents, 'visits', visits
        ) order by isodow) from weekday
      ), '[]'::jsonb),
      'best_isodow', (select isodow from weekday order by revenue_cents desc, isodow limit 1),
      'quietest_isodow', (select isodow from weekday order by revenue_cents asc, isodow limit 1)
    ),
    'items', pg_catalog.jsonb_build_object(
      'note', 'line-item data may cover only part of revenue; see coverage_pct before generalising',
      'coverage_pct', (
        select case when wr.total_cents = 0 then null
          else round(100.0 * (select coalesce(sum(revenue_cents), 0) from items) / wr.total_cents, 1) end
        from window_revenue wr
      ),
      'top_items', coalesce((
        select jsonb_agg(jsonb_build_object(
          'description', description, 'qty', qty, 'revenue_cents', revenue_cents
        ) order by revenue_cents desc)
        from (select * from items order by revenue_cents desc limit 5) top_items
      ), '[]'::jsonb)
    ),
    'loyalty', pg_catalog.jsonb_build_object(
      'points_earned_this_period', (select earned from points_window),
      'points_redeemed_this_period', (select redeemed from points_window),
      'redemption_rate_pct', (
        select case when earned = 0 then null
          else round(100.0 * redeemed / earned, 1) end from points_window
      ),
      'points_outstanding_total', coalesce((
        select sum(points) from public.points_ledger where business_id = p_business
      ), 0),
      'pot_is_split', app.programme_pot_is_split_v310(p_business),
      'by_programme_note',
        'ledger tag provenance, not a spendable pot (V309 currentness gap)',
      'points_outstanding_by_programme_tag', case
        when app.programme_pot_is_split_v310(p_business) then null
        else coalesce((
          select pg_catalog.jsonb_agg(
                   pg_catalog.jsonb_build_object('kind', spine.kind, 'points', tag.points)
                   order by spine.sort)
            from (
              select entry.programme_id, sum(entry.points) as points
                from public.points_ledger entry
               where entry.business_id = p_business
               group by entry.programme_id
            ) tag
            join public.business_programmes spine on spine.id = tag.programme_id
        ), '[]'::jsonb) end
    )
  )
$$;

--
-- Name: FUNCTION v179_business_insights(p_business uuid, p_from date, p_to date, p_prior_from date, p_prior_to date); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.v179_business_insights(p_business uuid, p_from date, p_to date, p_prior_from date, p_prior_to date) IS 'Deterministic owner-grade insight evidence for AI firm reports: retention and new-customer return rates, at-risk regulars with a quantified recovery value, top-customer concentration (labels abbreviated, never contact details), weekday revenue pattern, item mix with coverage honesty, and loyalty points economics. Reversal-aware, policy-snapshot revenue, synthetic clients excluded.';

--
-- Name: v183_bookable_staff(uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v183_bookable_staff(p_business uuid, p_service uuid, p_staff uuid, p_branch uuid DEFAULT NULL::uuid) RETURNS TABLE(staff_id uuid, full_name text, title text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  select member.id,
         coalesce(nullif(btrim(member.full_name), ''), 'Team member'),
         nullif(btrim(member.title), '')
    from public.staff member
   where member.business_id = p_business
     and coalesce(member.active, true)
     and coalesce(member.customer_bookable, true)
     and (p_staff is null or member.id = p_staff)
     and (
       p_branch is null
       or exists (
         select 1 from public.staff_branches assignment
          where assignment.business_id = p_business
            and assignment.staff_id = member.id
            and assignment.branch_id = p_branch
       )
     )
     -- A service with no explicit assignments is offered by everyone; once the business
     -- assigns anyone, only the assigned people are offered.
     and (
       p_service is null
       or not exists (
         select 1 from public.staff_services mapped
          where mapped.business_id = p_business and mapped.service_id = p_service
       )
       or exists (
         select 1 from public.staff_services mapped
          where mapped.business_id = p_business
            and mapped.service_id = p_service
            and mapped.staff_id = member.id
       )
     );
$$;

--
-- Name: v184_assert_archivable(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v184_assert_archivable(p_prospect uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_row public.sme_prospects%rowtype; v_business uuid;
begin
  select * into v_row from public.sme_prospects where id=p_prospect;
  if not found then
    raise exception 'firm record not found' using errcode='22023';
  end if;
  if v_row.converted_business_id is not null then
    raise exception 'this firm already has a workspace and cannot be archived'
      using errcode='42501';
  end if;
  select id into v_business from public.businesses
   where source_prospect_id=p_prospect limit 1;
  if v_business is not null then
    raise exception 'a workspace was created from this record and cannot be archived'
      using errcode='42501';
  end if;
end $$;

--
-- Name: v184_assert_prospect_active(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v184_assert_prospect_active(p_prospect uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_archived timestamptz;
begin
  select archived_at into v_archived from public.sme_prospects where id=p_prospect;
  if v_archived is not null then
    raise exception 'this firm record is archived; restore it before making changes'
      using errcode='42501';
  end if;
end $$;

--
-- Name: v197_join_qr_secret(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v197_join_qr_secret() RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_secret text;
begin
  select decrypted_secret into v_secret
  from vault.decrypted_secrets where name='v197_join_qr_secret' limit 1;
  if v_secret is null or length(v_secret)<32 then
    raise exception 'join QR secret is not configured' using errcode='55000';
  end if;
  return v_secret;
end $$;

--
-- Name: v197_join_token(uuid, integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v197_join_token(p_business uuid, p_version integer) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'extensions', 'pg_temp'
    AS $$
begin
  if p_business is null or p_version is null or p_version < 1 then
    raise exception 'business and rotation version are required' using errcode='22023';
  end if;
  return encode(extensions.hmac(
    p_business::text||':'||p_version::text,
    app.v197_join_qr_secret(),
    'sha256'
  ),'hex');
end $$;

--
-- Name: v198_assert_qr_unlocked(uuid, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v198_assert_qr_unlocked(p_business uuid, p_action text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_locked timestamptz;
begin
  select print_locked_at into v_locked
  from public.business_customer_join_qr_v89
  where business_id=p_business and status='active' and print_locked_at is not null
  limit 1;
  if v_locked is not null then
    raise exception
      'This QR is locked for printing, so it cannot be %. Unlock it first if the printed copy is no longer in use.',
      p_action
      using errcode='42501';
  end if;
end $$;

--
-- Name: v200_capture_paid_periods(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v200_capture_paid_periods() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_sub record; v_period public.platform_subscription_revenue_periods_v200%rowtype;
  v_months integer; v_base bigint; v_remainder bigint; v_index integer;
  v_cash text; v_result jsonb; v_captured integer := 0; v_post_date date;
begin
  for v_sub in
    select s.business_id, s.current_period_start, s.current_period_end,
           s.period_total_cents, s.last_paid_at, s.last_paid_invoice_id,
           s.provider_subscription_id, s.cadence_months
      from public.subscriptions s
     where s.payment_status = 'paid'
       and s.last_paid_at is not null
       and coalesce(s.period_total_cents,0) > 0
       and s.current_period_start is not null
       and s.current_period_end is not null
       and s.current_period_end > s.current_period_start
       and not exists (
         select 1 from public.platform_subscription_revenue_periods_v200 p
          where p.business_id = s.business_id
            and p.period_start = (s.current_period_start at time zone 'Asia/Singapore')::date
            and p.period_end = (s.current_period_end at time zone 'Asia/Singapore')::date)
  loop
    v_post_date := (v_sub.last_paid_at at time zone 'Asia/Singapore')::date;

    -- Nothing posts before the company legally existed.
    if not exists (select 1 from public.platform_accounting_policies_v147
                    where effective_from <= v_post_date) then
      continue;
    end if;

    -- Prefer the subscription's own cadence; fall back to the period's length.
    v_months := greatest(1, coalesce(v_sub.cadence_months,
      (extract(year from age(v_sub.current_period_end, v_sub.current_period_start))*12
       + extract(month from age(v_sub.current_period_end, v_sub.current_period_start)))::integer));
    if v_months > 60 then v_months := 60; end if;

    v_cash := case when v_sub.provider_subscription_id is not null then '1010' else '1000' end;

    insert into public.platform_subscription_revenue_periods_v200(
      business_id, period_start, period_end, total_cents, month_count,
      paid_at, invoice_reference, cash_account_code)
    values (v_sub.business_id,
      (v_sub.current_period_start at time zone 'Asia/Singapore')::date,
      (v_sub.current_period_end at time zone 'Asia/Singapore')::date,
      v_sub.period_total_cents, v_months, v_sub.last_paid_at,
      nullif(btrim(coalesce(v_sub.last_paid_invoice_id,'')),''), v_cash)
    returning * into v_period;

    -- Whole cents only; the remainder rides on the final month so the slices
    -- always add back to the cash received.
    v_base := v_period.total_cents / v_months;
    v_remainder := v_period.total_cents - (v_base * v_months);
    for v_index in 1..v_months loop
      insert into public.platform_subscription_revenue_months_v200(
        period_id, month_index, month_start, amount_cents)
      values (v_period.id, v_index,
        (v_period.period_start + make_interval(months => v_index - 1)),
        v_base + case when v_index = v_months then v_remainder else 0 end);
    end loop;

    begin
      v_result := app.platform_post_journal_v147(
        'platform_subscription_cash_v200',
        v_period.id::text,
        v_post_date,
        'Subscription payment received (deferred until earned)',
        jsonb_build_array(
          jsonb_build_object('account_code', v_cash,
            'debit_cents', v_period.total_cents, 'credit_cents', 0),
          jsonb_build_object('account_code', '2300',
            'debit_cents', 0, 'credit_cents', v_period.total_cents)));
      update public.platform_subscription_revenue_periods_v200
         set cash_journal_entry_id = ((v_result->'entry')->>'id')::uuid
       where id = v_period.id;
      v_captured := v_captured + 1;
    exception when sqlstate '55000' then
      -- Period locked: leave the capture recorded but unposted; the next run
      -- retries rather than silently dropping the payment.
      null;
    end;
  end loop;
  return v_captured;
end $$;

--
-- Name: v200_recognize_due_months(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v200_recognize_due_months() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_row record; v_result jsonb; v_recognized integer := 0; v_today date;
begin
  v_today := (clock_timestamp() at time zone 'Asia/Singapore')::date;
  for v_row in
    select m.id, m.month_index, m.month_start, m.amount_cents,
           p.business_id, p.cash_journal_entry_id
      from public.platform_subscription_revenue_months_v200 m
      join public.platform_subscription_revenue_periods_v200 p on p.id = m.period_id
     where m.journal_entry_id is null
       and m.month_start <= v_today
       -- Only recognise what the cash entry already backs.
       and p.cash_journal_entry_id is not null
     order by m.month_start
  loop
    if not exists (select 1 from public.platform_accounting_policies_v147
                    where effective_from <= v_row.month_start) then
      continue;
    end if;
    begin
      v_result := app.platform_post_journal_v147(
        'platform_subscription_revenue_v200',
        v_row.id::text,
        v_row.month_start,
        'Subscription revenue earned',
        jsonb_build_array(
          jsonb_build_object('account_code', '2300',
            'debit_cents', v_row.amount_cents, 'credit_cents', 0),
          jsonb_build_object('account_code', '4000',
            'debit_cents', 0, 'credit_cents', v_row.amount_cents)));
      update public.platform_subscription_revenue_months_v200
         set journal_entry_id = ((v_result->'entry')->>'id')::uuid,
             recognized_at = now()
       where id = v_row.id;
      v_recognized := v_recognized + 1;
    exception when sqlstate '55000' then
      -- Locked period: skip this slice, retry next run.
      null;
    end;
  end loop;
  return v_recognized;
end $$;

--
-- Name: v226_self_consultant(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v226_self_consultant() RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  select consultant.id
    from public.platform_consultants consultant
   where consultant.user_id = auth.uid()
     and consultant.active
   order by consultant.created_at, consultant.id
   limit 1
$$;

--
-- Name: v247_distance_km(numeric, numeric, numeric, numeric); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v247_distance_km(p_lat1 numeric, p_lng1 numeric, p_lat2 numeric, p_lng2 numeric) RETURNS numeric
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  select case
    when p_lat1 is null or p_lng1 is null or p_lat2 is null or p_lng2 is null then null
    else round((
      6371 * 2 * asin(least(1, sqrt(
        power(sin(radians(p_lat2 - p_lat1) / 2), 2)
        + cos(radians(p_lat1)) * cos(radians(p_lat2))
        * power(sin(radians(p_lng2 - p_lng1) / 2), 2)
      )))
    )::numeric, 2)
  end;
$$;

--
-- Name: FUNCTION v247_distance_km(p_lat1 numeric, p_lng1 numeric, p_lat2 numeric, p_lng2 numeric); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.v247_distance_km(p_lat1 numeric, p_lng1 numeric, p_lat2 numeric, p_lng2 numeric) IS 'v247: great-circle distance in km between two WGS84 points (haversine, 6371 km sphere).';

--
-- Name: v255_campaign_send_immutable_guard(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v255_campaign_send_immutable_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if tg_op='DELETE'
     and coalesce(
       pg_catalog.current_setting('app.v255_retention_purge',true),''
     )='on'
     and old.retention_until<clock_timestamp() then
    return old;
  end if;
  raise exception 'v255 campaign send records are append-only'
    using errcode='restrict_violation';
end
$$;

--
-- Name: v267_business_logo_url(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v267_business_logo_url(p_business uuid) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  select app.v95_public_media_url(logo.object_path)
    from public.business_brand_presentation_v95 brand
    join public.business_media_assets_v95 logo
      on logo.id = brand.logo_asset_id
     and logo.business_id = brand.business_id
     and logo.asset_kind = 'logo'
     and logo.customer_visible
   where brand.business_id = p_business
   limit 1;
$$;

--
-- Name: v281_capture_first_paid_from_terms(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v281_capture_first_paid_from_terms() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_invoice public.billing_provider_invoices%rowtype;
  v_legal_version text;
begin
  select invoice.* into v_invoice
    from public.billing_provider_invoices invoice
   where invoice.business_id=new.business_id
     and invoice.provider_subscription_id=new.provider_subscription_id
     and invoice.paid_normalized
     and invoice.paid_at is not null
   order by invoice.paid_at asc, invoice.provider_invoice_id asc
   limit 1;
  if not found then return null; end if;

  -- Branch copied verbatim from app.capture_money_back_window_v124, including its behaviour when
  -- there is no self-service onboarding row (v_legal_version null, comparison null, else branch).
  select onboarding.legal_document_version into v_legal_version
    from public.self_serve_business_onboarding_v130 onboarding
   where onboarding.business_id=new.business_id;

  if v_legal_version>='2026-08-03' then
    insert into public.billing_first_paid_evidence_v144(
      business_id,first_paid_invoice_id,first_paid_at,source_event_id
    ) values(
      new.business_id,v_invoice.provider_invoice_id,v_invoice.paid_at,
      v_invoice.last_event_id
    )
    on conflict(business_id) do update
      set first_paid_invoice_id=excluded.first_paid_invoice_id,
          first_paid_at=excluded.first_paid_at,
          source_event_id=excluded.source_event_id,
          updated_at=now()
      where excluded.first_paid_at
            < billing_first_paid_evidence_v144.first_paid_at;
  else
    insert into public.billing_money_back_windows_v124(
      business_id,first_paid_invoice_id,first_paid_at,
      money_back_request_until,source_event_id
    ) values(
      new.business_id,v_invoice.provider_invoice_id,v_invoice.paid_at,
      v_invoice.paid_at+interval '30 days',v_invoice.last_event_id
    )
    on conflict(business_id) do update
      set first_paid_invoice_id=excluded.first_paid_invoice_id,
          first_paid_at=excluded.first_paid_at,
          money_back_request_until=excluded.money_back_request_until,
          source_event_id=excluded.source_event_id,
          updated_at=now()
      where excluded.first_paid_at
            < billing_money_back_windows_v124.first_paid_at;
  end if;
  return null;
end
$$;

--
-- Name: FUNCTION v281_capture_first_paid_from_terms(); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.v281_capture_first_paid_from_terms() IS 'Replays the first-paid capture when the subscription terms arrive after the paid invoice. Stripe does not order webhooks, and the invoice-side capture is evaluated only once.';

--
-- Name: v281_redrive_failed_billing_events(integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v281_redrive_failed_billing_events(p_limit integer DEFAULT 200) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_event record;
  v_result jsonb;
  v_attempted integer := 0;
  v_processed integer := 0;
  v_still_failed integer := 0;
begin
  if p_limit is null or p_limit < 1 or p_limit > 1000 then
    raise exception 'redrive limit must be between 1 and 1000' using errcode='22023';
  end if;
  for v_event in
    select event_row.event_id
      from public.billing_provider_events event_row
     where event_row.provider='stripe'
       and (
         event_row.processing_status='failed'
         or (event_row.processing_status='processing'
             and event_row.received_at < now()-interval '10 minutes')
       )
     order by event_row.event_created_at asc, event_row.id asc
     limit p_limit
  loop
    v_attempted := v_attempted + 1;
    v_result := public.apply_stripe_billing_event_v77(v_event.event_id);
    if coalesce(v_result->>'status','') in ('processed','ignored') then
      v_processed := v_processed + 1;
    else
      v_still_failed := v_still_failed + 1;
    end if;
  end loop;
  return jsonb_build_object(
    'attempted',v_attempted,'processed',v_processed,'still_failed',v_still_failed
  );
end
$$;

--
-- Name: FUNCTION v281_redrive_failed_billing_events(p_limit integer); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.v281_redrive_failed_billing_events(p_limit integer) IS 'Re-applies durable-inbox Stripe events left failed or stuck processing. Stripe stops retrying after roughly three days; after that a stranded event is permanent and the money has still moved.';

--
-- Name: v282_partner_suppression_guard(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v282_partner_suppression_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if tg_op = 'DELETE' then
    raise exception 'a suppression instruction is append-only' using errcode = '23000';
  end if;
  if old.acknowledged_at is not null then
    raise exception 'this suppression instruction is already acknowledged' using errcode = '23000';
  end if;
  if new.acknowledged_at is null then
    raise exception 'only an acknowledgement may amend a suppression instruction'
      using errcode = '23000';
  end if;
  if new.id is distinct from old.id
     or new.partner_id is distinct from old.partner_id
     or new.identity_id is distinct from old.identity_id
     or new.auth_user_id is distinct from old.auth_user_id
     or new.reason is distinct from old.reason
     or new.issued_at is distinct from old.issued_at
     or new.issued_by is distinct from old.issued_by
     or new.idempotency_key is distinct from old.idempotency_key then
    raise exception 'a suppression instruction is append-only' using errcode = '23000';
  end if;
  return new;
end;
$$;

--
-- Name: v282_run_customer_push_dispatch(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v282_run_customer_push_dispatch() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $_$
declare
  v_url text;
  v_secret text;
  v_request bigint;
  v_pending integer;
begin
  select count(*)::integer into v_pending
    from public.customer_push_deliveries_v95 delivery
   where delivery.status in ('queued', 'retry')
     and delivery.attempt_count < 5;

  if to_regnamespace('vault') is null or to_regnamespace('net') is null then
    return jsonb_build_object('pending', v_pending, 'dispatch', 'extensions_unavailable');
  end if;
  begin
    execute 'select decrypted_secret from vault.decrypted_secrets where name=$1 order by created_at desc limit 1'
      into v_url using 'v282_supabase_url';
    if coalesce(v_url, '') = '' then
      execute 'select decrypted_secret from vault.decrypted_secrets where name=$1 order by created_at desc limit 1'
        into v_url using 'v156_supabase_url';
    end if;
    execute 'select decrypted_secret from vault.decrypted_secrets where name=$1 order by created_at desc limit 1'
      into v_secret using 'v282_push_dispatch_secret';
  exception when others then
    return jsonb_build_object('pending', v_pending, 'dispatch', 'vault_unavailable');
  end;
  if coalesce(v_url, '') = '' or coalesce(v_secret, '') = '' then
    return jsonb_build_object('pending', v_pending, 'dispatch', 'secret_unconfigured');
  end if;

  -- The header name is the one supabase/functions/_shared/customer-push.ts
  -- compares in constant time; changing either side alone locks the dispatcher
  -- out with a 401 that looks like a healthy deployment.
  execute 'select net.http_post(url := $1, body := ''{}''::jsonb, headers := jsonb_build_object(''content-type'',''application/json'',''x-nestly-push-dispatch-secret'',$2), timeout_milliseconds := 20000)'
    into v_request
    using rtrim(v_url, '/') || '/functions/v1/customer-push-dispatch', v_secret;

  return jsonb_build_object('pending', v_pending, 'dispatch_request_id', v_request);
end
$_$;

--
-- Name: FUNCTION v282_run_customer_push_dispatch(); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.v282_run_customer_push_dispatch() IS 'Ticks the customer-push-dispatch edge function. Returns a named reason instead of raising when pg_net, Vault or the secret is absent.';

--
-- Name: v282_sweep_bottle_expiry(timestamp with time zone); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v282_sweep_bottle_expiry(p_now timestamp with time zone DEFAULT now()) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_now timestamptz := coalesce(p_now, now());
  v_expired integer := 0;
  v_reminded integer := 0;
begin
  with lapsed as (
    update public.bar_bottles bottle
       set status = 'expired', updated_at = v_now
     where bottle.status = 'stored'
       and bottle.expires_at <= v_now
    returning bottle.id, bottle.business_id, bottle.expires_at
  ), evidenced as (
    insert into public.bar_bottle_events (
      business_id, bottle_id, kind, actor, idem_key, detail
    )
    select
      lapsed.business_id, lapsed.id, 'expire', null::uuid,
      'v282-expire:' || lapsed.id::text,
      jsonb_build_object('swept_at', v_now, 'expires_at', lapsed.expires_at)
    from lapsed
    on conflict do nothing
    returning 1
  )
  select count(*)::integer into v_expired from lapsed;

  with due as (
    select
      bottle.id as bottle_id,
      bottle.business_id,
      bottle.expires_at,
      link.id as link_id,
      link.identity_id,
      link.auth_user_id,
      link.client_id
    from public.bar_bottles bottle
    join public.customer_links link
      on link.business_id = bottle.business_id
     and link.client_id = bottle.client_id
     and link.state = 'verified'
     and link.unlinked_at is null
    left join public.customer_notification_preferences preference
      on preference.business_id = link.business_id
     and preference.identity_id = link.identity_id
     and preference.auth_user_id = link.auth_user_id
     and preference.link_id = link.id
     and preference.channel = 'in_app'
     and preference.topic = 'value_expiry'
    where bottle.status = 'stored'
      and bottle.expires_at > v_now
      and bottle.expires_at <= v_now
        + make_interval(days => app.bar_expiry_reminder_days_v282(bottle.business_id))
      and coalesce(preference.opted_in, true)
      and app.customer_communication_allows_v263(
        link.identity_id, 'rewards_and_points', 'in_app'
      )
  ), enqueued as (
    insert into public.customer_in_app_inbox_events (
      business_id, identity_id, auth_user_id, link_id, client_id,
      source_kind, topic, route_key, source_fingerprint, dedupe_key,
      title, body, deadline_at
    )
    select
      due.business_id, due.identity_id, due.auth_user_id, due.link_id, due.client_id,
      'v282_bottle_expiry', 'value_expiry', 'wallet_business',
      app.c46_sha256_hex(jsonb_build_object(
        'bottle_id', due.bottle_id, 'expires_at', due.expires_at)::text),
      app.c46_sha256_hex(jsonb_build_object(
        'identity_id', due.identity_id, 'bottle_id', due.bottle_id,
        'expires_at', due.expires_at)::text),
      'Your bottle expires soon',
      'Open this business wallet before the bottle kept for you is collected.',
      due.expires_at
    from due
    on conflict (identity_id, dedupe_key) do nothing
    returning id, business_id
  ), noted as (
    insert into public.bar_bottle_events (
      business_id, bottle_id, kind, actor, idem_key, detail
    )
    select
      due.business_id, due.bottle_id, 'reminder', null::uuid,
      'v282-remind:' || due.bottle_id::text || ':' || due.expires_at::text,
      jsonb_build_object('delivery', 'in_app', 'automated', true,
        'expires_at', due.expires_at)
    from due
    on conflict do nothing
    returning 1
  )
  select count(*)::integer into v_reminded from enqueued;

  return jsonb_build_object(
    'swept_at', v_now, 'expired', v_expired, 'reminded', v_reminded);
end
$$;

--
-- Name: FUNCTION v282_sweep_bottle_expiry(p_now timestamp with time zone); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.v282_sweep_bottle_expiry(p_now timestamp with time zone) IS 'Daily SGT sweep: expires lapsed in-storage bottles (one ''expire'' event each) and enqueues expiry reminders N days ahead. Both halves are idempotent - running twice writes nothing the second time.';

--
-- Name: v297_assert_prospecting(text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v297_assert_prospecting(p_mode text DEFAULT 'r'::text) RETURNS void
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if auth.uid() is null then
    raise exception 'authenticated_session_required' using errcode='28000';
  end if;
  if not app.v297_can_prospecting(p_mode) then
    raise exception 'prospecting_access_required' using errcode='42501';
  end if;
end $$;

--
-- Name: v297_can_prospecting(text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v297_can_prospecting(p_mode text DEFAULT 'r'::text) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  select coalesce(
    app.is_super_admin()
    or (app.v89_platform_role() in ('admin','sales_staff')
        and app.v89_platform_can('onboarding', p_mode)),
  false)
$$;

--
-- Name: v297_haversine_km(double precision, double precision, double precision, double precision); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v297_haversine_km(p_lat1 double precision, p_lng1 double precision, p_lat2 double precision, p_lng2 double precision) RETURNS double precision
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
  select 2 * 6371 * asin(sqrt(
    power(sin(radians(p_lat2 - p_lat1) / 2), 2)
    + cos(radians(p_lat1)) * cos(radians(p_lat2))
      * power(sin(radians(p_lng2 - p_lng1) / 2), 2)
  ))
$$;

--
-- Name: v310_purge_expired_google_content(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v310_purge_expired_google_content() RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_geo integer := 0; v_facts integer := 0; v_prospect uuid;
begin
  -- §14.3: google-sourced coordinates older than 30 days are deleted. The
  -- address/postal that came from Google go with them (no storage allowance).
  with expired as (
    update public.sme_company_locations l
       set latitude=null, longitude=null, address=null, postal_code=null
     where l.geo_source='google_places'
       and l.geo_synced_at < now() - interval '30 days'
       and (l.latitude is not null or l.address is not null or l.postal_code is not null)
    returning l.company_id
  ) select count(*) into v_geo from expired;

  -- Provider market facts (rating/reviews/status/price/phone/website) have no
  -- storage allowance in the current terms; 30 days is this system's OUTER
  -- transient bound, enforced by deletion. A refresh re-fetch restarts the window.
  with expired as (
    delete from public.sme_company_market_facts f
     where f.last_synced_at < now() - interval '30 days'
    returning f.company_id
  ) select count(*) into v_facts from expired;

  -- Scores that leaned on purged facts must drop honestly.
  for v_prospect in
    select p.id from public.sme_prospects p
     where p.archived_at is null
       and not exists (select 1 from public.sme_company_market_facts f
                        where f.company_id=p.company_id)
       and exists (select 1 from public.sme_lead_scores sc
                    where sc.prospect_id=p.id
                      and sc.score_breakdown::text like '%rating%')
  loop
    perform app.v297_refresh_lead_score(v_prospect);
  end loop;

  if v_geo > 0 or v_facts > 0 then
    insert into public.audit_log(business_id, actor, action, entity, entity_id, detail)
    values (null, null, 'GOOGLE_CONTENT_PURGED_V310', 'sme_company_market_facts', null,
            jsonb_build_object('expired_geo_rows', v_geo, 'expired_fact_rows', v_facts,
                               'policy', 'GMP SST §14.3 + no-storage posture'));
  end if;
  return jsonb_build_object('expired_geo_rows', v_geo, 'expired_fact_rows', v_facts);
end $$;

--
-- Name: v311_match_merchants(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v311_match_merchants(p_company uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_linked integer := 0; v_queued integer := 0; r record;
begin
  for r in
    select c.id as company_id,
           c.legal_name, c.trading_name,
           src.source_id as place_id,
           l.postal_code
      from public.sme_companies c
      left join public.sme_company_sources src
             on src.company_id=c.id and src.source='google_places'
      left join public.sme_company_locations l
             on l.company_id=c.id and l.is_primary
     where c.peekaa_business_id is null
       and (p_company is null or c.id = p_company)
  loop
    -- (a) Place ID is exact identity — link without asking.
    update public.sme_companies c
       set peekaa_business_id = b.id, merchant_linked_at = now(), merchant_link_basis = 'place_id'
      from public.businesses b
     where c.id = r.company_id and r.place_id is not null and b.place_id = r.place_id;
    if found then v_linked := v_linked + 1; continue; end if;

    -- (b) Same normalized name AND same postal code — two independent
    --     agreements, treated as confident.
    update public.sme_companies c
       set peekaa_business_id = b.id, merchant_linked_at = now(), merchant_link_basis = 'name_postal'
      from public.businesses b
     where c.id = r.company_id
       and r.postal_code is not null and b.postal_code is not null
       and btrim(r.postal_code) = btrim(b.postal_code)
       and app.normalized_business_identity_v79(coalesce(b.legal_name, b.name))
         = app.normalized_business_identity_v79(coalesce(r.legal_name, r.trading_name));
    if found then v_linked := v_linked + 1; continue; end if;

    -- (c) Name agrees but nothing corroborates it. Queue, do not apply:
    --     "Kim's Kitchen" in Bedok is not "Kim's Kitchen" in Jurong.
    insert into public.sme_merchant_match_candidates(company_id, business_id, match_basis)
    select r.company_id, b.id, 'name_only'
      from public.businesses b
     where app.normalized_business_identity_v79(coalesce(b.legal_name, b.name))
         = app.normalized_business_identity_v79(coalesce(r.legal_name, r.trading_name))
       and coalesce(b.is_demo,false) = false
     on conflict (company_id, business_id) do nothing;
    if found then v_queued := v_queued + 1; end if;
  end loop;

  return jsonb_build_object('linked', v_linked, 'queued_for_review', v_queued);
end $$;

--
-- Name: v311_on_business_merchant_link(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v311_on_business_merchant_link() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  perform app.v311_match_merchants(null);
  return null;
end $$;

--
-- Name: FUNCTION v311_on_business_merchant_link(); Type: COMMENT; Schema: app; Owner: -
--

COMMENT ON FUNCTION app.v311_on_business_merchant_link() IS 'v385: SECURITY DEFINER so the prospect matcher it calls runs as the definer. Without it every
   owner UPDATE of businesses.name or legal_name raised 42501 and the Business Profile could not
   be saved by anyone.';

--
-- Name: v31_current_identity(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v31_current_identity() RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_identity_id uuid;
begin
  if v_actor is null then
    raise exception 'authenticated customer session required' using errcode = '28000';
  end if;
  select ci.id into v_identity_id
    from public.customer_identities ci
   where ci.auth_user_id = v_actor and ci.status = 'active';
  if v_identity_id is null then
    raise exception 'an independent active customer identity is required' using errcode = '42501';
  end if;
  return v_identity_id;
end;
$$;

--
-- Name: v31_evidence_immutable_guard(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v31_evidence_immutable_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  raise exception '% is append-only evidence', tg_table_name using errcode = '23000';
end;
$$;

--
-- Name: v31_invitation_guard(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v31_invitation_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_claim_id text := nullif(current_setting('app.customer_link_invitation_claim_id', true), '');
begin
  if tg_op = 'DELETE' then
    raise exception 'customer link invitations are retained as audit evidence' using errcode = '23000';
  end if;
  if old.state <> 'issued' or new.state <> 'claimed' or v_claim_id is distinct from old.id::text
     or (new.id, new.business_id, new.client_id, new.issued_by_auth_user_id, new.token_hash,
         new.recipient_email_hash, new.expires_at, new.created_at)
        is distinct from
        (old.id, old.business_id, old.client_id, old.issued_by_auth_user_id, old.token_hash,
         old.recipient_email_hash, old.expires_at, old.created_at)
     or new.claimed_at is null or new.claimed_by_identity_id is null or new.claimed_link_id is null then
    raise exception 'an invitation may only transition issued -> claimed through its token route'
      using errcode = '23000';
  end if;
  return new;
end;
$$;

--
-- Name: v31_link_immutable_guard(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v31_link_immutable_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_insert_id text := nullif(current_setting('app.customer_link_insert_id', true), '');
  v_transition_id text := nullif(current_setting('app.customer_link_transition_id', true), '');
begin
  if tg_op = 'INSERT' then
    if v_insert_id is distinct from new.id::text or new.state <> 'verified' or new.verified_at is null then
      raise exception 'customer links may only be created by a verified claim route' using errcode = '42501';
    end if;
    return new;
  end if;
  if tg_op = 'DELETE' then
    raise exception 'customer links are retained as relationship evidence' using errcode = '23000';
  end if;
  if v_transition_id is distinct from old.id::text
     or old.state <> 'verified' or new.state <> 'unlinked'
     or (new.id, new.business_id, new.identity_id, new.auth_user_id, new.client_id,
         new.verification_method, new.verified_at, new.created_at)
        is distinct from
        (old.id, old.business_id, old.identity_id, old.auth_user_id, old.client_id,
         old.verification_method, old.verified_at, old.created_at)
     or new.unlinked_at is null or new.unlinked_by_auth_user_id is null then
    raise exception 'customer links may only transition verified -> unlinked through the self-service route'
      using errcode = '23000';
  end if;
  return new;
end;
$$;

--
-- Name: v31_sha256_hex(text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v31_sha256_hex(p_value text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'extensions', 'pg_temp'
    AS $_$
  select encode(extensions.digest(convert_to($1, 'UTF8'), 'sha256'), 'hex')
$_$;

--
-- Name: v327_member_qr_secret(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v327_member_qr_secret() RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_secret text;
begin
  select decrypted_secret into v_secret
  from vault.decrypted_secrets where name='v327_member_qr_secret' limit 1;
  if v_secret is null or length(v_secret)<32 then
    raise exception 'member QR secret is not configured' using errcode='55000';
  end if;
  return v_secret;
end $$;

--
-- Name: v327_member_qr_token(uuid, integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v327_member_qr_token(p_identity uuid, p_version integer) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'extensions', 'pg_temp'
    AS $$
begin
  if p_identity is null or p_version is null or p_version < 1 then
    raise exception 'identity and rotation version are required' using errcode='22023';
  end if;
  return encode(extensions.hmac(
    p_identity::text||':'||p_version::text,
    app.v327_member_qr_secret(),
    'sha256'
  ),'hex');
end $$;

--
-- Name: v32_customer_wallet_context(text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v32_customer_wallet_context(p_business_slug text DEFAULT NULL::text) RETURNS TABLE(identity_id uuid, business_id uuid, client_id uuid, business_name text, business_slug text, business_industry text, business_currency text, enabled_modules text[])
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid:=auth.uid();
  v_slug text:=nullif(lower(btrim(coalesce(p_business_slug,''))),'');
begin
  if v_actor is null then
    raise exception 'authenticated customer session required'
      using errcode='28000';
  end if;
  if not app.platform_feature_enabled('customer_wallet') then
    raise exception 'customer wallet is not enabled' using errcode='0A000';
  end if;
  perform 1
  from public.customer_identities identity
  where identity.auth_user_id=v_actor and identity.status='active';
  if not found then
    raise exception 'active customer identity required' using errcode='42501';
  end if;

  return query
  select identity.id,link.business_id,link.client_id,
    business.name,business.slug,business.industry,business.currency,
    coalesce(array(
      select key.module_key
      from (
        select unnest(coalesce(business.enabled_modules,'{}'::text[])) module_key
        union
        select override_row.module_key
        from public.platform_module_overrides_v94 override_row
        where override_row.business_id=business.id
      ) key
      where app.business_module_enabled_at_v117(
        business.id,key.module_key,null
      )
      order by key.module_key
    ),'{}'::text[])
  from public.customer_identities identity
  join public.customer_links link
    on link.identity_id=identity.id
   and link.auth_user_id=v_actor
   and link.state='verified'
  join public.businesses business on business.id=link.business_id
  where identity.auth_user_id=v_actor
    and identity.status='active'
    and (v_slug is null or business.slug=v_slug)
  order by business.slug,link.id;
end
$$;

