--
-- Name: v365_apply_perk_note(uuid, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v365_apply_perk_note(p_business uuid, p_tier uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  update public.loyalty_tiers t
     set perk_note = nullif((
       select string_agg(app.v365_benefit_sentence(b.label,b.limit_count,b.limit_period), E'\n' order by b.sort, b.created_at, b.id)
         from public.tier_benefits_v365 b
        where b.business_id=p_business and b.tier_id=p_tier and b.deleted_at is null and b.active),'')
   where t.id=p_tier and t.business_id=p_business;
end $$;

--
-- Name: v365_benefit_sentence(text, integer, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v365_benefit_sentence(p_label text, p_limit integer, p_period text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
  select btrim(p_label) || case
    when p_limit is null and coalesce(p_period,'month')='birthday_month' then ' — during their birthday month'
    when p_limit is null then ''
    when coalesce(p_period,'month')='birthday_month' then ' — '||p_limit||' during their birthday month'
    when coalesce(p_period,'month')='ever' then ' — '||p_limit||' in total'
    else ' — '||p_limit||' per '||coalesce(p_period,'month')
  end
$$;

--
-- Name: v365_client_tier(uuid, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v365_client_tier(p_business uuid, p_client uuid) RETURNS public.loyalty_tiers
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_basis text;
  v_metric numeric := 0;
  v_tier public.loyalty_tiers%rowtype;
begin
  select coalesce(tier_basis,'visits') into v_basis
    from public.loyalty_programs where business_id=p_business and active limit 1;
  if v_basis='spend' then
    select coalesce(sum(amount_cents),0)/100.0 into v_metric from public.sales
     where business_id=p_business and client_id=p_client and counts_as_revenue;
  elsif v_basis='points_earned' then
    select coalesce(sum(points),0) into v_metric from public.points_ledger
     where business_id=p_business and client_id=p_client and entry_type='earn';
  else
    select count(*) into v_metric from public.sales
     where business_id=p_business and client_id=p_client and counts_as_visit;
  end if;
  select * into v_tier from public.loyalty_tiers
   where business_id=p_business and threshold<=v_metric
     and coalesce(paused,false)=false and deleted_at is null
     and (effective_from is null or effective_from<=statement_timestamp())
     and (expires_at is null or expires_at>statement_timestamp())
   order by threshold desc, sort desc, id limit 1;
  return v_tier;
end $$;

--
-- Name: v365_period_key(text, timestamp with time zone); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v365_period_key(p_period text, p_at timestamp with time zone) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
  select case coalesce(p_period,'month')
    when 'ever' then 'ever'
    when 'day' then to_char(timezone('Asia/Singapore',p_at),'YYYY-MM-DD')
    when 'week' then to_char(timezone('Asia/Singapore',p_at),'IYYY-"W"IW')
    when 'year' then to_char(timezone('Asia/Singapore',p_at),'YYYY')
    else to_char(timezone('Asia/Singapore',p_at),'YYYY-MM')
  end
$$;

--
-- Name: v367_in_birthday_month(uuid, timestamp with time zone); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v367_in_birthday_month(p_client uuid, p_at timestamp with time zone) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
  select c.birth_date is not null
     and extract(month from c.birth_date) = extract(month from timezone('Asia/Singapore',p_at))
    from public.clients c where c.id = p_client
$$;

--
-- Name: v369_benefit_label(text, numeric, uuid, text, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v369_benefit_label(p_kind text, p_discount numeric, p_product uuid, p_item text, p_fallback text) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
  select case coalesce(p_kind,'custom')
    /* FM999990.99 leaves a bare trailing '.' on a whole number (30.00 -> "30."), which the
       rehearsal caught as "30.% off". Strip it so 30 reads "30% off" and 12.5 still reads
       "12.5% off". */
    when 'discount_pct' then regexp_replace(trim(to_char(p_discount,'FM999990.99')),'\.$','')||'% off'
    when 'free_item' then 'Free '||coalesce(
      (select p.name from public.products p where p.id = p_product),
      nullif(btrim(coalesce(p_item,'')),''), 'item')
    else btrim(coalesce(p_fallback,''))
  end
$_$;

