--
-- Name: v53_customer_feedback_context(text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v53_customer_feedback_context(p_business_slug text) RETURNS TABLE(identity_id uuid, auth_user_id uuid, link_id uuid, business_id uuid, client_id uuid, business_slug text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_slug text := lower(btrim(coalesce(p_business_slug, '')));
begin
  if v_actor is null then
    raise exception 'authenticated customer session required' using errcode = '28000';
  end if;
  if length(v_slug) not between 2 and 160 then
    raise exception 'invalid business link' using errcode = '22023';
  end if;
  return query
    select ci.id, v_actor, cl.id, cl.business_id, cl.client_id, b.slug
      from public.customer_identities ci
      join public.customer_links cl
        on cl.identity_id = ci.id and cl.auth_user_id = v_actor and cl.state = 'verified'
      join public.businesses b on b.id = cl.business_id
     where ci.auth_user_id = v_actor and ci.status = 'active' and b.slug = v_slug
     order by cl.id
     limit 1;
  if not found then
    raise exception 'verified customer link required' using errcode = '42501';
  end if;
end;
$$;

--
-- Name: visit_feedback; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.visit_feedback (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    business_id uuid NOT NULL,
    identity_id uuid NOT NULL,
    link_id uuid NOT NULL,
    client_id uuid NOT NULL,
    auth_user_id uuid NOT NULL,
    sale_id uuid,
    rating smallint NOT NULL,
    comment text,
    idempotency_key uuid NOT NULL,
    recovery_status text NOT NULL,
    resolved_by uuid,
    resolved_at timestamp with time zone,
    resolution_note text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT visit_feedback_comment_check CHECK (((comment IS NULL) OR (length(comment) <= 2000))),
    CONSTRAINT visit_feedback_rating_check CHECK (((rating >= 1) AND (rating <= 5))),
    CONSTRAINT visit_feedback_recovery_gate_check CHECK ((((rating <= 3) AND (recovery_status = ANY (ARRAY['open'::text, 'acknowledged'::text, 'resolved'::text]))) OR ((rating >= 4) AND (recovery_status = 'closed'::text)))),
    CONSTRAINT visit_feedback_recovery_status_check CHECK ((recovery_status = ANY (ARRAY['open'::text, 'acknowledged'::text, 'resolved'::text, 'closed'::text]))),
    CONSTRAINT visit_feedback_resolution_check CHECK ((((recovery_status = 'resolved'::text) AND (resolved_by IS NOT NULL) AND (resolved_at IS NOT NULL)) OR (recovery_status <> 'resolved'::text))),
    CONSTRAINT visit_feedback_resolution_note_check CHECK (((resolution_note IS NULL) OR (length(resolution_note) <= 2000)))
);

