-- Name: v76_sha256_hex(text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v76_sha256_hex(p_value text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'extensions', 'pg_temp'
