--
-- Name: v89_can_access_business(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v89_can_access_business(p_business uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  select case app.v89_platform_role()
    when 'super_admin' then true
    when 'admin' then app.v89_platform_can('firms','r')
    when 'sales_staff' then app.v89_business_in_role_scope(p_business)
    else false end
$$;

--
-- Name: v89_can_access_prospect(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v89_can_access_prospect(p_prospect uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  select case app.v89_platform_role()
    when 'super_admin' then true
    when 'admin' then app.v89_platform_can('onboarding','r')
    when 'sales_staff' then app.v89_platform_can('onboarding','r')
      and app.v89_prospect_in_role_scope(p_prospect)
    else false end
$$;

--
-- Name: v89_customer_appointment_change_gate(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v89_customer_appointment_change_gate() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if not app.v89_business_module_enabled(new.business_id,'appointments')
     or not coalesce((
    select capability.appointment_changes_enabled
    from public.business_customer_capabilities_v89 capability
    where capability.business_id=new.business_id
  ),false) then
    raise exception 'customer appointment changes are disabled for this business'
      using errcode='42501';
  end if;
  return new;
end
$$;

--
-- Name: v89_customer_booking_gate(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v89_customer_booking_gate() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if new.customer_client_id is not null and not coalesce((
    select capability.booking_enabled
    from public.business_customer_capabilities_v89 capability
    where capability.business_id=new.business_id
  ),false)
  or (new.customer_client_id is not null
    and not app.v89_business_module_enabled(new.business_id,'bookings')) then
    raise exception 'customer app booking is disabled for this business'
      using errcode='42501';
  end if;
  return new;
end
$$;

--
-- Name: v89_platform_billing_reconciliation(uuid, integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v89_platform_billing_reconciliation(p_run uuid, p_limit integer) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  select jsonb_build_object(
    'runs',coalesce((
      select jsonb_agg(to_jsonb(runs) order by runs.started_at desc)
      from (
        select id,run_mode,status,cursor_start,cursor_end,started_at,finished_at,summary
        from public.billing_reconciliation_runs
        where p_run is null or id=p_run
        order by started_at desc limit p_limit
      ) runs
    ),'[]'::jsonb),
    'items',coalesce((
      select jsonb_agg(to_jsonb(items) order by items.created_at desc)
      from (
        select run_id,business_id,object_type,provider_object_id,result,
          expected_digest,actual_digest,detail,created_at
        from public.billing_reconciliation_items
        where p_run is not null and run_id=p_run
        order by created_at desc limit 500
      ) items
    ),'[]'::jsonb)
  )
$$;

--
-- Name: v89_platform_billing_rows(uuid, integer); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v89_platform_billing_rows(p_business uuid, p_limit integer) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  select coalesce(jsonb_agg(to_jsonb(rows) order by rows.updated_at desc),'[]'::jsonb)
  from (
    select subscription.business_id,business.name business_name,
      subscription.status,subscription.payment_status,subscription.currency,
      subscription.billing_cadence cadence,subscription.cadence_months,
      subscription.billing_provider provider,subscription.provider_customer_id,
      subscription.provider_subscription_id,
      app.billable_seats(subscription.business_id) billable_seats,
      subscription.period_subtotal_cents,subscription.period_tax_cents,
      subscription.period_total_cents,subscription.next_payment_at,
      subscription.last_paid_at,subscription.last_paid_invoice_id,
      subscription.cancel_at_period_end,subscription.updated_at,
      (select count(*) from public.billing_provider_events event
        where event.business_id=subscription.business_id
          and event.processing_status='failed') failed_event_count
    from public.subscriptions subscription
    join public.businesses business on business.id=subscription.business_id
    where (p_business is null or subscription.business_id=p_business) and business.is_demo=false
    order by subscription.updated_at desc limit p_limit
  ) rows
$$;

--
-- Name: v89_platform_can(text, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v89_platform_can(p_module text, p_mode text DEFAULT 'r'::text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  select case
    when app.is_super_admin() then true
    when p_mode not in ('r','rw') then false
    else coalesce((
      select case
        when grant_row.role='sales_staff'
             and p_module not in ('onboarding','firms','reports') then false
        when p_mode='r' then coalesce(
          grant_row.module_perms->>p_module,
          case when grant_row.role='admin' then grant_row.module_perms->>'*' end
        ) in ('r','rw')
        else coalesce(
          grant_row.module_perms->>p_module,
          case when grant_row.role='admin' then grant_row.module_perms->>'*' end
        )='rw'
      end
      from public.platform_access_grants_v89 grant_row
      where grant_row.user_id=auth.uid() and grant_row.active
    ),false)
  end
$$;

--
-- Name: v89_platform_role(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v89_platform_role() RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  select case
    when app.is_super_admin() then 'super_admin'
    else (select grant_row.role from public.platform_access_grants_v89 grant_row
      where grant_row.user_id=auth.uid() and grant_row.active)
  end
$$;

--
-- Name: v89_prospect_in_role_scope(uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v89_prospect_in_role_scope(p_prospect uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  select case app.v89_platform_role()
    when 'super_admin' then true
    when 'admin' then true
    when 'sales_staff' then exists(
      select 1 from public.sme_prospects prospect
      where prospect.id=p_prospect and (
        prospect.created_by=auth.uid()
        or prospect.assigned_consultant_id=app.v89_sales_consultant_id()
      )
    )
    else false end
$$;

--
-- Name: v89_redemption_intent_guard(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v89_redemption_intent_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if tg_op='DELETE' or nullif(current_setting(
    'app.v89_redemption_intent_id',true),'') is distinct from old.id::text then
    raise exception 'redemption intent evidence is protected' using errcode='23001';
  end if;
  if (new.id,new.business_id,new.identity_id,new.auth_user_id,new.client_id,
      new.redemption_kind,new.reward_id,new.quoted_program_id,
      new.quoted_config_version_id,new.quoted_reward_version_id,
      new.quoted_points_spent,new.quoted_credit_cents,new.quoted_terms,
      new.token_hash,new.idempotency_key,new.request_hash,new.expires_at,
      new.created_at)
     is distinct from
    (old.id,old.business_id,old.identity_id,old.auth_user_id,old.client_id,
      old.redemption_kind,old.reward_id,old.quoted_program_id,
      old.quoted_config_version_id,old.quoted_reward_version_id,
      old.quoted_points_spent,old.quoted_credit_cents,old.quoted_terms,
      old.token_hash,old.idempotency_key,old.request_hash,old.expires_at,
      old.created_at) then
    raise exception 'redemption intent provenance is immutable' using errcode='23001';
  end if;
  return new;
end
$$;

--
-- Name: v89_redemption_token(uuid, uuid, text, uuid, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v89_redemption_token(p_identity uuid, p_business uuid, p_redemption_kind text, p_reward uuid, p_idempotency_key uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'extensions', 'pg_temp'
    AS $$
  select encode(extensions.hmac(
    convert_to(concat_ws(':',p_identity,p_business,p_redemption_kind,
      coalesce(p_reward::text,'classic'),p_idempotency_key),'UTF8'),
    secret.secret_value,'sha256'),'hex')
  from app.v89_token_secrets secret
  where secret.secret_key='customer_redemption'
$$;

--
-- Name: v89_sales_consultant_id(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v89_sales_consultant_id() RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  select consultant.id from public.platform_consultants consultant
  where consultant.user_id=auth.uid() and consultant.active
  order by consultant.created_at,consultant.id limit 1
$$;

--
-- Name: v89_sha256(text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v89_sha256(p_value text) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog', 'extensions', 'pg_temp'
    AS $$select encode(extensions.digest(convert_to(p_value,'UTF8'),'sha256'),'hex')$$;

--
-- Name: v92_capture_platform_marketing_consent(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v92_capture_platform_marketing_consent() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_source text := coalesce(nullif(current_setting('app.v92_marketing_source',true),''),'signup');
  v_idempotency_key text := nullif(current_setting('app.v92_marketing_idempotency_key',true),'');
  v_privacy app.customer_legal_documents%rowtype;
begin
  if tg_op='UPDATE' and new.platform_marketing_opted_in is not distinct from old.platform_marketing_opted_in
     and v_idempotency_key is null then return new; end if;
  if v_source not in ('signup','customer_profile') then
    raise exception 'invalid platform marketing consent source' using errcode='22023';
  end if;
  select * into v_privacy from app.customer_legal_documents d
   where d.document_key='privacy' and d.active for share;
  if not found or v_privacy.document_version<>'2026-08-10'
     or v_privacy.document_sha256<>'960434af7919e5401b3587111eb746fbba41f739edacd74cb5aeeca0402c224f' then
    raise exception 'platform marketing consent document is unavailable' using errcode='0A000';
  end if;
  insert into public.customer_platform_marketing_consent_events(
    identity_id,auth_user_id,opted_in,scope_version,privacy_version,
    privacy_sha256,source,idempotency_key,request_hash
  ) values (
    new.identity_id,new.auth_user_id,new.platform_marketing_opted_in,
    '2026-08-10-partner-sharing-v3',v_privacy.document_version,
    v_privacy.document_sha256,v_source,v_idempotency_key,
    -- The scope string joins the hash so the same customer, the same answer and
    -- the same idempotency key still produce a DISTINCT request hash under a new
    -- scope. Without it a v3 re-grant could collide with its v2 predecessor.
    app.v31_sha256_hex('v92.platform-marketing:'||new.auth_user_id::text||':'
      ||new.platform_marketing_opted_in::text||':'||v_privacy.document_sha256||':'
      ||'2026-08-10-partner-sharing-v3'||':'||coalesce(v_idempotency_key,'signup'))
  );
  return new;
end;
$$;

--
-- Name: v92_platform_marketing_consent_immutable(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v92_platform_marketing_consent_immutable() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  raise exception 'platform marketing consent evidence is append-only' using errcode = '23000';
end;
$$;

--
-- Name: v92_prepare_platform_marketing_preference(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v92_prepare_platform_marketing_preference() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if new.platform_marketing_opted_in then
    new.marketing_scope_version := '2026-08-10-partner-sharing-v3';
    new.marketing_privacy_sha256 := '960434af7919e5401b3587111eb746fbba41f739edacd74cb5aeeca0402c224f';
  else
    new.marketing_scope_version := null;
    new.marketing_privacy_sha256 := null;
  end if;
  return new;
end;
$$;

--
-- Name: v95_entity_in_business(uuid, text, uuid); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v95_entity_in_business(p_business uuid, p_entity_type text, p_entity uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  select case p_entity_type
    when 'programme' then exists(select 1 from public.loyalty_programs
      where id=p_entity and business_id=p_business)
    when 'reward' then exists(select 1 from public.loyalty_rewards
      where id=p_entity and business_id=p_business)
    when 'product' then exists(select 1 from public.products
      where id=p_entity and business_id=p_business)
    when 'service' then exists(select 1 from public.services
      where id=p_entity and business_id=p_business)
    when 'tier' then exists(select 1 from public.loyalty_tiers
      where id=p_entity and business_id=p_business and deleted_at is null)
    when 'benefit' then exists(select 1 from public.business_customer_content_v95
      where id=p_entity and business_id=p_business and content_type='benefit')
    when 'offer' then exists(select 1 from public.business_customer_content_v95
      where id=p_entity and business_id=p_business and content_type='offer')
    else false end
$$;

--
-- Name: v95_public_media_url(text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v95_public_media_url(p_object_path text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
  select case when p_object_path is null then null
    else '/storage/v1/object/public/business-public/'||p_object_path end
$$;

--
-- Name: v95_sha256(text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v95_sha256(p_value text) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog', 'extensions', 'pg_temp'
    AS $$
  select encode(extensions.digest(convert_to(p_value,'UTF8'),'sha256'),'hex')
$$;

--
-- Name: v95_storage_object_is_publishable(uuid, text, text, text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v95_storage_object_is_publishable(p_business uuid, p_asset_kind text, p_object_path text, p_mime_type text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $_$
  select
    p_asset_kind in (
      'logo','hero','programme','reward','product','service','benefit','offer'
    )
    and p_mime_type in ('image/png','image/jpeg','image/webp','image/gif')
    and p_object_path~(
      '^'||p_business::text||'/'||p_asset_kind||
      '/[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}\.(png|jpg|jpeg|webp|gif)$'
    )
    and case p_mime_type
      when 'image/png' then p_object_path~'\.png$'
      when 'image/jpeg' then p_object_path~'\.(jpg|jpeg)$'
      when 'image/webp' then p_object_path~'\.webp$'
      when 'image/gif' then p_object_path~'\.gif$'
      else false
    end
    and exists(
      select 1 from storage.objects object
      where object.bucket_id='business-public'
        and object.name=p_object_path
        and lower(coalesce(object.metadata->>'mimetype',''))=p_mime_type
        and coalesce(object.metadata->>'size','')~'^[0-9]+$'
        and (object.metadata->>'size')::bigint between 1 and 10485760
    )
$_$;

--
-- Name: v95_storage_path_owned(text); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v95_storage_path_owned(p_name text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $_$
begin
  if coalesce(p_name,'')!~(
    '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}'||
    '/(logo|hero|programme|reward|product|service|benefit|offer|gallery)'||
    '/[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}\.(png|jpg|jpeg|webp|gif)$'
  )
  then return false;end if;
  return app.is_salon_owner(split_part(p_name,'/',1)::uuid);
end $_$;

