-- Name: v99_immutable_evidence_guard(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.v99_immutable_evidence_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  raise exception 'v99 campaign evidence is append-only'
    using errcode='restrict_violation';
end
$$;

--
-- Name: validate_client_field_option(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.validate_client_field_option() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_type text;
begin
  select value_type into v_type
    from public.client_field_definitions
   where id = new.field_definition_id and business_id = new.business_id;
  if v_type is null then
    raise exception 'client field definition does not belong to business'
      using errcode = 'foreign_key_violation';
  end if;
  if v_type <> 'select' then
    raise exception 'options are allowed only for select fields'
      using errcode = 'check_violation';
  end if;
  new.option_key := lower(btrim(new.option_key));
  new.option_label := btrim(new.option_label);
  if tg_op = 'UPDATE'
     and (new.business_id is distinct from old.business_id
          or new.field_definition_id is distinct from old.field_definition_id
          or new.option_key is distinct from old.option_key)
     and exists (
       select 1 from public.client_field_values v
        where v.business_id = old.business_id
          and v.field_definition_id = old.field_definition_id
          and v.select_value = old.option_key
     ) then
    raise exception 'select option identity is immutable after values exist'
      using errcode = 'restrict_violation';
  end if;
  return new;
end
$$;

--
-- Name: validate_client_field_value(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.validate_client_field_value() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_definition public.client_field_definitions%rowtype;
begin
  select * into v_definition
    from public.client_field_definitions
   where id = new.field_definition_id and business_id = new.business_id;
  if not found then
    raise exception 'client field definition does not belong to business'
      using errcode = 'foreign_key_violation';
  end if;
  if not v_definition.active then
    raise exception 'retired client fields cannot receive new values'
      using errcode = 'check_violation';
  end if;
  if ((new.text_value is not null)::integer
      + (new.number_value is not null)::integer
      + (new.date_value is not null)::integer
      + (new.boolean_value is not null)::integer
      + (new.select_value is not null)::integer) <> 1 then
    raise exception 'exactly one typed client field value is required'
      using errcode = 'check_violation';
  end if;

  case v_definition.value_type
    when 'text' then
      if new.text_value is null then raise exception 'text value is required' using errcode = 'check_violation'; end if;
    when 'number' then
      if new.number_value is null then raise exception 'number value is required' using errcode = 'check_violation'; end if;
    when 'date' then
      if new.date_value is null then raise exception 'date value is required' using errcode = 'check_violation'; end if;
    when 'boolean' then
      if new.boolean_value is null then raise exception 'boolean value is required' using errcode = 'check_violation'; end if;
    when 'select' then
      new.select_value := lower(btrim(new.select_value));
      if new.select_value is null
         or not exists (
           select 1 from public.client_field_options o
            where o.option_key = new.select_value
              and o.business_id = new.business_id
              and o.field_definition_id = new.field_definition_id
              and o.active
         ) then
        raise exception 'select value is not an active option for this field'
          using errcode = 'check_violation';
      end if;
    else
      raise exception 'unsupported client field type' using errcode = 'check_violation';
  end case;
  return new;
end
$$;

--
-- Name: validate_stage_entry_v86(uuid, text, jsonb, jsonb); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.validate_stage_entry_v86(p_prospect uuid, p_stage text, p_evidence jsonb, p_commercial_terms jsonb) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $_$
declare v_rule public.sme_stage_entry_requirements%rowtype;v_missing text[];
begin
  select * into v_rule from public.sme_stage_entry_requirements where stage_key=p_stage;
  if not found then raise exception 'unknown SME stage requirement' using errcode='22023';end if;
  if v_rule.system_managed then
    raise exception 'this SME stage is system-managed and requires conversion evidence' using errcode='42501';
  end if;
  if p_evidence is null or jsonb_typeof(p_evidence)<>'object' then
    raise exception 'stage entry evidence must be an object' using errcode='22023';
  end if;
  select array_agg(key order by key) into v_missing
    from unnest(v_rule.required_keys) key
   where not (p_evidence?key) or p_evidence->>key is null or btrim(p_evidence->>key)='';
  if cardinality(v_missing)>0 then
    raise exception 'stage % is missing evidence: %',p_stage,array_to_string(v_missing,', ')
      using errcode='22023';
  end if;
  if p_stage='new_lead' and not exists(
    select 1 from public.sme_prospects prospect join public.sme_companies company on company.id=prospect.company_id
     where prospect.id=p_prospect and coalesce(company.legal_name,company.trading_name,company.registration_number) is not null
       and exists(select 1 from public.sme_prospect_source_lineage source where source.prospect_id=p_prospect)
  ) then raise exception 'New Lead requires company identity and source' using errcode='22023';
  elsif p_stage='appt_set' and not exists(
    select 1 from public.sme_prospect_contacts contact where contact.prospect_id=p_prospect and contact.active
      and (contact.email is not null or contact.phone is not null)
  ) then raise exception 'Appointment Set requires a primary contact with a valid channel' using errcode='22023';
  elsif p_stage like 'npu_%' and not (p_evidence?'next_attempt_at' or p_evidence?'terminal_disposition') then
    raise exception 'NPU requires next attempt or terminal disposition' using errcode='22023';
  elsif p_stage='meeting_sent' and not (p_evidence?'meeting_url' or p_evidence?'physical_location') then
    raise exception 'Meeting Link Sent requires a meeting URL or physical location' using errcode='22023';
  elsif p_stage='pending_decision' and not (p_evidence?'decision_at' or p_evidence?'next_follow_up_at') then
    raise exception 'Pending Decision requires decision date or next follow-up' using errcode='22023';
  elsif p_stage='client' and (
    coalesce((p_evidence->>'explicit_confirmation')::boolean,false)=false
    or p_commercial_terms is null or jsonb_typeof(p_commercial_terms)<>'object'
    or coalesce(p_commercial_terms->>'plan_code','')=''
    or coalesce(p_commercial_terms->>'product_code','')=''
    or coalesce((p_commercial_terms->>'seats')::integer,0)<=0
    or coalesce((p_commercial_terms->>'accepted_value_cents')::bigint,-1)<0
    or coalesce(p_commercial_terms->>'currency','')!~'^[A-Z]{3}$'
    or coalesce(p_commercial_terms->>'contract_status','') not in ('accepted','signed')
    or coalesce(p_commercial_terms->>'owner_email','') not like '%@%'
    or nullif(p_commercial_terms->>'onboarding_owner_consultant_id','') is null
    or nullif(p_commercial_terms->>'target_go_live','') is null
  ) then raise exception 'Client requires explicit confirmation and complete commercial evidence' using errcode='22023';
  elsif p_stage='lost' and (
    coalesce(p_evidence->>'reason_code','') not in
      ('no_response','not_interested','no_budget','timing','chose_competitor',
       'missing_required_feature','procurement_security_blocker','price',
       'internal_priority_changed','business_ceased','duplicate','bad_fit','other')
    or (coalesce((p_evidence->>'recontact_permission')::boolean,false)
      and not p_evidence?'recontact_at')
  ) then raise exception 'Lost requires a valid reason and conditional recontact date' using errcode='22023';
  end if;
end
$_$;

--
-- Name: visit_feedback_guard(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.visit_feedback_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_token text;
begin
  if tg_op = 'DELETE' then
    raise exception 'visit_feedback is append-only: DELETE is not permitted'
      using errcode = 'restrict_violation';
  end if;
  if tg_op = 'INSERT' then
    return new;
  end if;
  -- UPDATE: only staff_resolve_feedback may move the recovery lifecycle, and only that.
  v_token := nullif(current_setting('app.visit_feedback_resolve_id', true), '');
  if v_token is distinct from old.id::text then
    raise exception 'visit feedback recovery may only be updated by staff_resolve_feedback'
      using errcode = '42501';
  end if;
  if (new.id, new.business_id, new.identity_id, new.link_id, new.client_id, new.auth_user_id,
      new.sale_id, new.rating, new.comment, new.idempotency_key, new.created_at)
     is distinct from
     (old.id, old.business_id, old.identity_id, old.link_id, old.client_id, old.auth_user_id,
      old.sale_id, old.rating, old.comment, old.idempotency_key, old.created_at) then
    raise exception 'only the service-recovery lifecycle of a feedback row may change'
      using errcode = 'restrict_violation';
  end if;
  if not (
       (old.recovery_status = 'open' and new.recovery_status in ('acknowledged', 'resolved'))
    or (old.recovery_status = 'acknowledged' and new.recovery_status = 'resolved')
    or (old.recovery_status = new.recovery_status)
  ) then
    raise exception 'illegal service-recovery transition % -> %',
      old.recovery_status, new.recovery_status
      using errcode = 'restrict_violation';
  end if;
  return new;
end $$;

--
-- Name: visit_feedback_v122_notify_staff(); Type: FUNCTION; Schema: app; Owner: -
--

CREATE FUNCTION app.visit_feedback_v122_notify_staff() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  insert into public.notifications(
    business_id,kind,title,body,ref_table,ref_id
  ) values (
    new.business_id,'feedback_new','New customer feedback',
    case when new.recovery_status='open'
      then 'A customer response needs follow-up.'
      else 'A customer shared visit feedback.'
    end,
    'visit_feedback',new.id
  );
  return new;
end
$$;

--
-- Name: accept_invite(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accept_invite(p_code text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $_$
declare
  inv public.staff_invites%rowtype;
  b public.businesses%rowtype;
  v_email text; v_code text; v_staff uuid;
begin
  if auth.uid() is null then raise exception 'sign in required'; end if;
  v_code := upper(regexp_replace(btrim(coalesce(p_code, '')), '[\s-]+', '', 'g'));
  if v_code !~ '^[A-Z0-9]{4,32}$' then raise exception 'company invite code is invalid'; end if;
  select * into inv from public.staff_invites where code = v_code for update;
  if not found then raise exception 'company invite code is invalid'; end if;
  if inv.status = 'accepted' or inv.status = 'awaiting_approval' then
    raise exception 'company invite has already been used';
  elsif inv.status = 'revoked' then
    raise exception 'company invite has been revoked';
  elsif inv.status = 'expired' or inv.expires_at <= now() then
    update public.staff_invites set status='expired' where id=inv.id and status='pending';
    raise exception 'company invite has expired';
  elsif inv.status <> 'pending' then
    raise exception 'company invite is no longer active';
  end if;
  select * into b from public.businesses where id = inv.business_id;
  if not found then raise exception 'business unavailable'; end if;
  v_email := lower(btrim(coalesce(auth.jwt()->>'email', '')));
  if nullif(btrim(coalesce(inv.email, '')), '') is not null
     and lower(btrim(inv.email)) <> v_email then
    raise exception 'company invite is restricted to another email';
  end if;
  if exists (select 1 from public.staff
              where business_id = inv.business_id and user_id = auth.uid()) then
    raise exception 'you are already on this team';
  end if;
  if inv.staff_id is not null then
    -- Upgrade the EXISTING roster record: their name, job title, commission, hours, rota and
    -- every past sale stay attached to the same person rather than splitting across two rows.
    update public.staff
       set user_id = auth.uid(),
           access_state = 'pending',
           email = coalesce(nullif(btrim(email,''),''), nullif(v_email,''))
     where id = inv.staff_id and business_id = inv.business_id and user_id is null
     returning id into v_staff;
    if v_staff is null then raise exception 'that teammate already has a login'; end if;
  else
    insert into public.staff (business_id, user_id, role, full_name, access_state)
    values (inv.business_id, auth.uid(), inv.role,
            coalesce(auth.jwt()->>'email', 'Team member'), 'pending')
    returning id into v_staff;
  end if;
  update public.staff_invites
     set status = 'awaiting_approval', accepted_at = now(), accepted_user_id = auth.uid()
   where id = inv.id and status = 'pending';
  insert into public.audit_log (business_id, actor, action, entity, entity_id, detail)
  values (inv.business_id, auth.uid(), 'INVITE_ACCEPTED', 'staff_invites', inv.id,
          jsonb_build_object('role', inv.role, 'accepted_user_id', auth.uid(),
                             'staff_id', v_staff, 'awaiting_owner_approval', true));
  return json_build_object('status','awaiting_approval','business_name', b.name,
    'message','Your request has been sent. You can sign in once the owner approves it.');
end;
$_$;

--
-- Name: accept_workspace_owner_invite_v79(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accept_workspace_owner_invite_v79(p_token text, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid:=auth.uid();v_email text;v_hash text;v_request_hash text;v_replay jsonb;
  v_invite public.workspace_owner_invitations%rowtype;v_staff uuid;v_branch uuid;v_response jsonb;
  v_checklist uuid;
begin
  if v_actor is null then raise exception 'authenticated owner access is required' using errcode='42501';end if;
  perform app.require_idempotency_key_v79(p_idempotency_key);
  select lower(btrim(email)) into v_email from auth.users
   where id=v_actor and email_confirmed_at is not null;
  if v_email is null then raise exception 'authenticated email is required' using errcode='42501';end if;
  v_hash:=app.v76_sha256_hex(coalesce(p_token,''));
  v_request_hash:=app.v76_sha256_hex(jsonb_build_object('token_hash',v_hash)::text);
  v_replay:=app.v76_replay(v_actor,'accept_owner_invite_v79',p_idempotency_key,v_request_hash);
  if v_replay is not null then return v_replay;end if;
  select * into v_invite from public.workspace_owner_invitations
   where token_hash=v_hash for update;
  if not found then raise exception 'workspace owner invitation is invalid' using errcode='22023';end if;
  if v_invite.status='accepted' and v_invite.accepted_by=v_actor then
    return jsonb_build_object('replayed',false,'outcome','already_accepted',
      'business_id',v_invite.business_id,'invitation_id',v_invite.id);
  end if;
  if v_invite.status<>'pending' then raise exception 'workspace owner invitation is no longer active' using errcode='22023';end if;
  if v_invite.expires_at<=now() then
    update public.workspace_owner_invitations set status='expired',revoked_at=now() where id=v_invite.id;
    v_response:=jsonb_build_object('replayed',false,'outcome','expired',
      'business_id',v_invite.business_id,'invitation_id',v_invite.id);
    perform app.v76_store_receipt(v_actor,'accept_owner_invite_v79',p_idempotency_key,
      v_request_hash,v_response);
    return v_response;
  end if;
  if lower(btrim(v_invite.owner_email))<>v_email then
    raise exception 'workspace owner invitation email does not match the authenticated user'
      using errcode='42501';
  end if;
  if exists(
    select 1 from public.staff
    where business_id=v_invite.business_id and user_id=v_actor and role<>'owner'
  ) then
    raise exception 'existing non-owner membership requires an explicit platform role decision'
      using errcode='42501';
  end if;
  insert into public.staff(business_id,user_id,role,full_name,active)
  values(v_invite.business_id,v_actor,'owner',coalesce((select raw_user_meta_data->>'full_name'
    from auth.users where id=v_actor),split_part(v_email,'@',1)),true)
  on conflict(business_id,user_id) do update set role='owner',active=true
  returning id into v_staff;
  select id into v_branch from public.branches
   where business_id=v_invite.business_id and is_default limit 1;
  insert into public.staff_branches(business_id,staff_id,branch_id)
  values(v_invite.business_id,v_staff,v_branch) on conflict do nothing;
  update public.workspace_owner_invitations set status='accepted',accepted_by=v_actor,
    accepted_at=now() where id=v_invite.id;
  select id into v_checklist from public.business_onboarding_checklists
   where business_id=v_invite.business_id;
  insert into public.business_onboarding_events(
    checklist_id,business_id,event_type,to_status,evidence,actor
  ) values(v_checklist,v_invite.business_id,'owner_invite_accepted','satisfied',
    jsonb_build_object('invitation_id',v_invite.id,'staff_id',v_staff),v_actor);
  perform app.refresh_onboarding_core_v79(v_invite.business_id,v_actor);
  insert into public.audit_log(business_id,actor,action,entity,entity_id,detail)
  values(v_invite.business_id,v_actor,'WORKSPACE_OWNER_INVITE_ACCEPTED_V79',
    'workspace_owner_invitations',v_invite.id,jsonb_build_object('staff_id',v_staff));
  v_response:=jsonb_build_object('replayed',false,'outcome','accepted',
    'business_id',v_invite.business_id,'invitation_id',v_invite.id,'staff_id',v_staff);
  perform app.v76_store_receipt(v_actor,'accept_owner_invite_v79',p_idempotency_key,
    v_request_hash,v_response);
  return v_response;
end
$$;

--
-- Name: acknowledge_legacy_value(uuid, text, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.acknowledge_legacy_value(p_business uuid, p_asset text, p_acknowledged_cents bigint, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_asset text := coalesce(p_asset, 'stored_value');
  v_reason text := btrim(coalesce(p_reason, ''));
  v_id uuid := gen_random_uuid();
begin
  if not (app.is_salon_owner(p_business) or app.is_super_admin()) then
    raise exception 'owner or super-admin only' using errcode = '42501';
  end if;
  if v_asset <> 'stored_value' then
    raise exception 'only the stored_value asset is supported for legacy acknowledgement' using errcode = '22023';
  end if;
  if p_acknowledged_cents is null or p_acknowledged_cents < 0 then
    raise exception 'a legacy acknowledgement requires an amount of zero or more cents' using errcode = '22023';
  end if;
  if char_length(v_reason) < 10 then
    raise exception 'a legacy-value acknowledgement requires a reason of at least 10 characters' using errcode = '22023';
  end if;
  if not exists (select 1 from public.businesses b where b.id = p_business) then
    raise exception 'business not found' using errcode = '22023';
  end if;
  insert into public.sv_legacy_acknowledgements(id, business_id, asset, acknowledged_cents, reason, actor)
  values (v_id, p_business, v_asset, p_acknowledged_cents, v_reason, v_actor);
  insert into public.audit_log(business_id, actor, action, entity, entity_id, detail)
  values (p_business, v_actor, 'SV_LEGACY_VALUE_ACKNOWLEDGED', 'sv_legacy_acknowledgements', v_id,
    jsonb_build_object('asset', v_asset, 'acknowledged_cents', p_acknowledged_cents, 'reason', v_reason));
  return jsonb_build_object('status', 'ok', 'business_id', p_business, 'asset', v_asset,
    'acknowledgement_id', v_id, 'acknowledged_cents', p_acknowledged_cents);
end $$;

--
-- Name: activate_approved_business_application_v95(text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.activate_approved_business_application_v95(p_invitation_token text, p_business_slug text, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $_$
declare
  v_actor uuid:=auth.uid();
  v_email text;
  v_invitation public.business_application_invitations_v95%rowtype;
  v_application public.business_applications_v95%rowtype;
  v_bundle public.sector_bundle_versions%rowtype;
  v_business public.businesses%rowtype;
  v_staff uuid;v_branch uuid;v_response jsonb;
begin
  if v_actor is null or p_idempotency_key is null
     or coalesce(p_invitation_token,'')!~'^[0-9a-f]{64}$'
     or coalesce(p_business_slug,'')!~'^[a-z0-9]+(?:-[a-z0-9]+)*$'
     or length(p_business_slug) not between 3 and 80
  then raise exception 'valid authenticated activation is required'
    using errcode='22023';end if;
  select lower(email) into v_email from auth.users
  where id=v_actor and coalesce(email_confirmed_at,confirmed_at) is not null;
  if v_email is null then
    raise exception 'confirmed_invited_email_required' using errcode='42501';
  end if;
  select * into v_invitation
  from public.business_application_invitations_v95 invitation
  where invitation.token_hash=app.v95_sha256(p_invitation_token)
  for update;
  if not found then raise exception 'approved_invitation_not_found'
    using errcode='42501';end if;
  if v_invitation.consumed_at is not null then
    if v_invitation.consumed_by=v_actor
       and v_invitation.idempotency_key=p_idempotency_key then
      return v_invitation.response||jsonb_build_object('replayed',true);
    end if;
    raise exception 'approved_invitation_already_consumed' using errcode='42501';
  end if;
  select * into v_application from public.business_applications_v95
  where id=v_invitation.application_id for update;
  if v_invitation.revoked_at is not null or v_application.status<>'approved' then
    raise exception 'approved_invitation_inactive' using errcode='42501';
  end if;
  if v_invitation.expires_at<=now() then
    update public.business_applications_v95
    set status='expired',version=version+1,updated_at=now(),
      decision_reason=decision_reason||'; approved invitation expired'
    where id=v_application.id;
    insert into public.business_application_audit_v95(
      application_id,event_type,actor,prior_status,new_status,reason
    ) values(
      v_application.id,'invitation_expired',v_actor,'approved','expired',
      'approved owner invitation expired before consumption'
    );
    return jsonb_build_object(
      'application_id',v_application.id,'status','expired',
      'workspace_created',false,'replayed',false
    );
  end if;
  if v_email<>v_application.contact_email then
    insert into public.business_application_audit_v95(
      application_id,event_type,actor,prior_status,new_status,reason,detail
    ) values(
      v_application.id,'activation_refused',v_actor,'approved','approved',
      'authenticated email did not match approved application',
      jsonb_build_object('email_match',false)
    );
    return jsonb_build_object(
      'application_id',v_application.id,'status','refused',
      'reason','approved_invitation_email_mismatch',
      'workspace_created',false,'replayed',false
    );
  end if;
  select * into v_bundle from public.sector_bundle_versions
  where sector_key=v_application.sector_key and status='published';
  if not found then raise exception 'published_sector_required'
    using errcode='23514';end if;
  insert into public.businesses(name,slug,industry,enabled_modules)
  values(
    v_application.business_name,p_business_slug,
    v_application.sector_key,v_bundle.modules
  ) returning * into v_business;
  insert into public.staff(business_id,user_id,role,full_name,active)
  values(v_business.id,v_actor,'owner',v_application.contact_name,true)
  returning id into v_staff;
  insert into public.branches(business_id,name,is_default,active)
  values(v_business.id,v_application.business_name,true,true)
  returning id into v_branch;
  insert into public.staff_branches(business_id,staff_id,branch_id)
  values(v_business.id,v_staff,v_branch);
  -- v94 seeds every direct business insert as pending. This workspace was
  -- already approved at the application boundary, so open it before owner-
  -- guarded configuration triggers (loyalty/config versioning) execute.
  update public.business_workspace_controls_v94
  set approval_status='approved',version=version+1,
    decided_by=v_application.decided_by,
    decided_at=v_application.decided_at,
    decision_reason='approved business application '||v_application.id,
    updated_at=now()
  where business_id=v_business.id;
  insert into public.business_workspace_control_audit_v94(
    business_id,actor,event_type,prior_status,new_status,reason,control_version
  ) values(
    v_business.id,v_application.decided_by,'application_activated',
    'pending','approved','approved pre-auth application consumed',2
  );
  insert into public.loyalty_programs(
    business_id,kind,earn_points_per_dollar,redeem_points,
    reward_credit_cents,active,loyalty_model,configuration_status,
    recommendation_source
  ) values(
    v_business.id,'points',1,800,2000,false,'classic','draft',
    'onboarding_preset'
  );
  insert into public.subscriptions(business_id) values(v_business.id)
  on conflict(business_id) do nothing;
  insert into public.business_sector_assignments(
    business_id,bundle_version_id,version,assigned_by
  ) values(v_business.id,v_bundle.id,1,v_actor);
  update public.business_applications_v95
  set status='consumed',version=version+1,consumed_business_id=v_business.id,
    consumed_by=v_actor,consumed_at=now(),updated_at=now()
  where id=v_application.id;
  v_response:=jsonb_build_object(
    'application_id',v_application.id,'status','consumed',
    'business_id',v_business.id,'business_slug',v_business.slug,
    'owner_staff_id',v_staff,'default_branch_id',v_branch,
    'workspace_created',true,'workspace_access',true,'replayed',false
  );
  update public.business_application_invitations_v95
  set consumed_at=now(),consumed_by=v_actor,business_id=v_business.id,
    idempotency_key=p_idempotency_key,response=v_response
  where id=v_invitation.id;
  insert into public.business_application_audit_v95(
    application_id,event_type,actor,prior_status,new_status,reason,detail
  ) values(
    v_application.id,'invitation_consumed',v_actor,'approved','consumed',
    'approved invitation consumed once',
    jsonb_build_object('business_id',v_business.id)
  );
  insert into public.audit_log(
    business_id,actor,action,entity,entity_id,detail
  ) values(
    v_business.id,v_actor,'APPROVED_APPLICATION_ACTIVATED_V95',
    'businesses',v_business.id,jsonb_build_object(
      'application_id',v_application.id,'sector_bundle_version_id',v_bundle.id
    )
  );
  return v_response;
end
$_$;

--
-- Name: activate_business_v79(uuid, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.activate_business_v79(p_business uuid, p_expected_version bigint, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_checklist public.business_onboarding_checklists%rowtype;
  v_prospect public.sme_prospects%rowtype;
  v_request jsonb;
  v_replay jsonb;
  v_response jsonb;
  v_now timestamptz := now();
begin
  if not app.is_super_admin() then
    raise exception 'super_admin_required';
  end if;
  perform app.require_idempotency_key_v79(p_idempotency_key);
  if nullif(btrim(p_idempotency_key), '') is null then
    raise exception 'idempotency_key_required';
  end if;

  v_request := jsonb_build_object(
    'business_id', p_business,
    'expected_version', p_expected_version
  );
  v_replay := app.v76_replay(
    v_actor, 'activate_business_v79', p_idempotency_key,
    app.v76_sha256_hex(v_request::text)
  );
  if v_replay is not null then return v_replay; end if;

  select * into v_checklist
  from public.business_onboarding_checklists
  where business_id = p_business
  for update;
  if not found then raise exception 'onboarding_checklist_not_found'; end if;
  if v_checklist.version <> p_expected_version then raise exception 'version_conflict'; end if;
  if v_checklist.status = 'activated' then raise exception 'business_already_activated'; end if;
  if v_checklist.blocked_at is not null
     or exists (
       select 1 from public.business_onboarding_items
       where checklist_id = v_checklist.id and status = 'blocked'
     ) then
    raise exception 'onboarding_blocked';
  end if;

  perform app.refresh_onboarding_core_v79(p_business, v_actor);
  select * into v_checklist
  from public.business_onboarding_checklists
  where business_id = p_business
  for update;

  if v_checklist.status <> 'ready'
     or exists (
       select 1 from public.business_onboarding_items
       where checklist_id = v_checklist.id
         and mandatory
         and status not in ('satisfied', 'waived')
     ) then
    raise exception 'mandatory_onboarding_items_incomplete';
  end if;
  if not exists (
    select 1 from public.business_onboarding_items
    where checklist_id = v_checklist.id
      and item_key = 'go_live_approved'
      and status = 'satisfied'
      and verification_mode = 'sa_approval'
      and not waivable
  ) then
    raise exception 'go_live_approval_required';
  end if;

  select * into v_prospect
  from public.sme_prospects
  where id = v_checklist.prospect_id
  for update;
  if not found or v_prospect.converted_business_id is distinct from p_business then
    raise exception 'prospect_business_link_invalid';
  end if;
  if v_prospect.current_stage_key <> 'onboarding' then
    raise exception 'prospect_must_be_in_onboarding';
  end if;

  perform set_config('app.v79_system_transition','on',true);
  update public.businesses
  set activated_at = coalesce(activated_at, v_now),
      updated_at = v_now
  where id = p_business;

  update public.branches
  set active = true,
      updated_at = v_now
  where business_id = p_business
    and is_default;

  update public.business_onboarding_checklists
  set status = 'activated',
      activated_at = v_now,
      version = version + 1,
      updated_at = v_now
  where id = v_checklist.id;

  update public.sme_prospects
  set current_stage_key = 'activated',
      version = version + 1,
      stage_entered_at = v_now,
      updated_by = v_actor,
      updated_at = v_now
  where id = v_prospect.id;

  insert into public.sme_prospect_stage_history(
    prospect_id, from_stage_key, to_stage_key, reason_code, reason_detail, actor
  ) values (
    v_prospect.id, 'onboarding', 'activated', 'activation_completed',
    'v79 activation gate satisfied', v_actor
  );
  insert into public.sme_prospect_activities(
    prospect_id, consultant_id, activity_type, summary, detail, created_by
  ) values (
    v_prospect.id, v_prospect.assigned_consultant_id, 'system',
    'Business activated', 'v79 onboarding gates satisfied', v_actor
  );
  insert into public.business_onboarding_events(
    checklist_id, business_id, event_type, actor, evidence
  ) values (
    v_checklist.id, p_business, 'activated', v_actor,
    jsonb_build_object('activated_at', v_now)
  );

  v_response := jsonb_build_object(
    'replayed',false,
    'onboarding',app.get_onboarding_core_v79(p_business),
    'activated_at',v_now
  );
  perform app.v76_store_receipt(
    v_actor, 'activate_business_v79', p_idempotency_key,
    app.v76_sha256_hex(v_request::text), v_response
  );
  insert into public.audit_log(business_id,actor,action,entity,entity_id,detail)
  values(p_business,v_actor,'BUSINESS_ACTIVATED_V79','businesses',p_business,
    jsonb_build_object('prospect_id',v_prospect.id,'checklist_id',v_checklist.id));
  return v_response;
end
$$;

--
-- Name: FUNCTION activate_business_v79(p_business uuid, p_expected_version bigint, p_idempotency_key text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.activate_business_v79(p_business uuid, p_expected_version bigint, p_idempotency_key text) IS 'Super-admin-only activation after refreshed derived evidence and every mandatory onboarding gate is fulfilled.';

--
-- Name: activate_pos_paynow_qr_v142(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.activate_pos_paynow_qr_v142(p_attempt uuid, p_account_id text, p_payment_intent_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_attempt public.pos_payment_attempts_v142%rowtype;
        v_qr_expires_at timestamptz;
begin
  perform app.v142_service_guard();
  select * into v_attempt from public.pos_payment_attempts_v142 where id=p_attempt for update;
  if not found or v_attempt.provider_account_id is distinct from p_account_id
     or v_attempt.provider_payment_intent_id is distinct from p_payment_intent_id then
    raise exception 'PayNow QR activation authority mismatch' using errcode='42501';
  end if;
  if v_attempt.status not in ('awaiting_payment','processing') then
    raise exception 'PayNow attempt cannot activate a QR in this state' using errcode='22023';
  end if;
  if v_attempt.qr_activated_at is null then
    v_qr_expires_at:=clock_timestamp()+interval '61 minutes';
    perform set_config('app.v142_extend_checkout','on',true);
    update public.checkout_evaluations set expires_at=v_qr_expires_at
     where id=v_attempt.evaluation_id and consumed_at is null;
    if not found then
      perform set_config('app.v142_extend_checkout','off',true);
      raise exception 'PayNow checkout is no longer available' using errcode='restrict_violation';
    end if;
    perform set_config('app.v142_extend_checkout','off',true);
    update public.pos_payment_attempts_v142 set qr_activated_at=clock_timestamp(),
      expires_at=v_qr_expires_at,updated_at=now() where id=v_attempt.id
      returning * into v_attempt;
  end if;
  return jsonb_build_object('attempt_id',v_attempt.id,'status',v_attempt.status,
    'qr_activated_at',v_attempt.qr_activated_at,'expires_at',v_attempt.expires_at);
end $$;

--
-- Name: activate_retention_campaign(uuid, uuid, uuid[], text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.activate_retention_campaign(p_business uuid, p_campaign uuid, p_client_ids uuid[], p_idempotency_key text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_campaign public.retention_campaigns%rowtype;
  v_requested integer;
  v_inserted integer;
  v_treatment integer;
  v_holdout integer;
begin
  if not app.is_salon_owner(p_business) then
    raise exception 'owner only' using errcode = '42501';
  end if;
  if p_idempotency_key is null or length(btrim(p_idempotency_key)) < 8 then
    raise exception 'idempotency key must contain at least 8 characters' using errcode = '22023';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('v50:activate:' || p_campaign::text, 0));
  select * into v_campaign from public.retention_campaigns
   where id = p_campaign and business_id = p_business for update;
  if not found then raise exception 'campaign not found in this business'; end if;

  if v_campaign.status = 'active' then
    select count(*) filter (where assignment = 'treatment'),
           count(*) filter (where assignment = 'holdout')
      into v_treatment, v_holdout
      from public.retention_campaign_members
     where campaign_id = p_campaign and business_id = p_business;
    return json_build_object('campaign_id', p_campaign, 'status', 'active',
      'audience_size', v_campaign.audience_size, 'treatment', v_treatment, 'holdout', v_holdout,
      'replayed', true);
  end if;
  if v_campaign.status <> 'draft' then
    raise exception 'only a draft campaign can be activated' using errcode = '42501';
  end if;
  if p_client_ids is null or array_length(p_client_ids, 1) is null then
    raise exception 'a non-empty audience is required to activate a campaign' using errcode = '22023';
  end if;
  select count(*) into v_requested from (select distinct unnest(p_client_ids) cid) u where u.cid is not null;
  if v_requested = 0 then
    raise exception 'a non-empty audience is required to activate a campaign' using errcode = '22023';
  end if;
  if v_requested > 50000 then
    raise exception 'campaign audience is limited to 50000 members' using errcode = '22023';
  end if;

  -- The membership fan-out and its immutable send record are one statement.
  -- channel='none' is the honest value: activation freezes an audience and no
  -- delivery channel exists for retention campaigns (audit finding 1.14).
  with members as(
    insert into public.retention_campaign_members(
      campaign_id, business_id, client_id, assignment, assignment_bucket
    )
    select p_campaign, p_business, c.id,
           case when app.campaign_holdout_bucket(p_campaign, c.id) < v_campaign.holdout_percent
                then 'holdout' else 'treatment' end,
           app.campaign_holdout_bucket(p_campaign, c.id)
      from (select distinct unnest(p_client_ids) cid) u
      join public.clients c on c.id = u.cid and c.business_id = p_business
    returning business_id, client_id, assignment
  ),
  recorded as(
    insert into public.campaign_send_records_v255(
      business_id,campaign_kind,campaign_ref_id,send_kind,campaign_label,
      channel,client_id
    )
    select
      member.business_id,'retention',p_campaign,'v50_campaign_activated',
      coalesce(nullif(btrim(left(v_campaign.name,200)),''),'Bring-back campaign'),
      'none',member.client_id
    from members member
    where member.assignment='treatment'
    on conflict do nothing
    returning 1
  )
  select count(*)::integer into v_inserted from members;
  if v_inserted <> v_requested then
    raise exception 'some audience clients do not belong to this business' using errcode = '42501';
  end if;

  select count(*) filter (where assignment = 'treatment'),
         count(*) filter (where assignment = 'holdout')
    into v_treatment, v_holdout
    from public.retention_campaign_members
   where campaign_id = p_campaign and business_id = p_business;

  update public.retention_campaigns
     set status = 'active', activated_at = now(), audience_size = v_inserted
   where id = p_campaign and business_id = p_business;

  insert into public.audit_log(business_id, actor, action, entity, entity_id, detail)
  values (p_business, v_actor, 'ACTIVATE_RETENTION_CAMPAIGN', 'retention_campaigns', p_campaign,
    jsonb_build_object('audience_size', v_inserted, 'treatment', v_treatment, 'holdout', v_holdout));
  return json_build_object('campaign_id', p_campaign, 'status', 'active',
    'audience_size', v_inserted, 'treatment', v_treatment, 'holdout', v_holdout, 'replayed', false);
end
$$;

--
-- Name: add_bottle_note_v278(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.add_bottle_note_v278(p_business uuid, p_bottle uuid, p_note text, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_key text := nullif(btrim(coalesce(p_idempotency_key, '')), '');
  v_note text := nullif(btrim(coalesce(p_note, '')), '');
  v_existing uuid;
  v_bottle public.bar_bottles%rowtype;
begin
  perform app.require_bar_business_v275(p_business);
  perform app.require_bar_staff_v275(p_business, true);
  if v_key is null then
    raise exception 'idempotency key required' using errcode = '22023';
  end if;
  if v_note is null then
    raise exception 'type the note first' using errcode = '22023';
  end if;
  if length(v_note) > 500 then
    raise exception 'a note is limited to 500 characters' using errcode = '22023';
  end if;

  v_existing := app.bar_bottle_replayed_v275(p_business, v_key);
  if v_existing is not null then
    select * into v_bottle from public.bar_bottles bottle where bottle.id = v_existing;
    return jsonb_build_object('status', 'duplicate_ignored',
      'bottle', app.bar_bottle_json_v275(v_bottle));
  end if;

  select * into v_bottle from public.bar_bottles bottle
   where bottle.id = p_bottle and bottle.business_id = p_business for update;
  if not found then
    raise exception 'bottle not found' using errcode = '22023';
  end if;

  -- A note changes no state; it is pure evidence, which is why the bottle row is only touched to
  -- move its updated_at. The note itself lives in the append-only log where it cannot be edited.
  update public.bar_bottles bottle set updated_at = now() where bottle.id = v_bottle.id
  returning * into v_bottle;

  insert into public.bar_bottle_events (business_id, bottle_id, kind, actor, idem_key, detail)
  values (p_business, v_bottle.id, 'note', v_actor, v_key,
    jsonb_build_object('note', v_note));

  return jsonb_build_object('status', 'ok', 'bottle', app.bar_bottle_json_v275(v_bottle));
end;
$$;

--
-- Name: add_consultant_payout_line_v78(uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.add_consultant_payout_line_v78(p_batch uuid, p_accrual uuid, p_amount_cents integer) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_batch public.consultant_payout_batches%rowtype;
  v_accrual public.consultant_commission_accruals%rowtype;
  v_net integer;
  v_allocated integer;
  v_id uuid;
begin
  if auth.uid() is null or not app.v89_platform_can('commissions','rw') then
    raise exception 'super-admin access is required' using errcode='42501';
  end if;
  select * into v_batch from public.consultant_payout_batches
   where id=p_batch and status='draft' for update;
  if not found then raise exception 'draft payout batch was not found' using errcode='22023'; end if;
  select accrual.* into v_accrual
    from public.consultant_commission_accruals accrual
    join public.platform_consultants consultant on consultant.id=accrual.consultant_id
   where accrual.id=p_accrual and accrual.status in ('approved','paid')
     and consultant.active and consultant.departed_at is null
   for update of accrual;
  if not found or v_accrual.currency<>v_batch.currency then
    raise exception 'approved or reopened paid accrual in batch currency was not found'
      using errcode='22023';
  end if;
  select v_accrual.commission_cents+coalesce(sum(
    case when settlement_status='payable' then commission_adjustment_cents else 0 end
  ),0) into v_net
    from public.consultant_commission_adjustments
   where accrual_id=v_accrual.id;
  select coalesce(sum(amount_cents),0) into v_allocated
    from public.consultant_payout_lines where accrual_id=v_accrual.id;
  if p_amount_cents<=0 or p_amount_cents>greatest(v_net-v_allocated,0) then
    raise exception 'payout line exceeds unallocated consultant commission'
      using errcode='22023';
  end if;
  insert into public.consultant_payout_lines(
    batch_id,accrual_id,consultant_id,amount_cents
  ) values (
    p_batch,p_accrual,v_accrual.consultant_id,p_amount_cents
  ) returning id into v_id;
  return v_id;
end
$$;

--
-- Name: add_recommended_loyalty_tiers_v143(uuid, uuid, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.add_recommended_loyalty_tiers_v143(p_business uuid, p_version uuid, p_basis text, p_expected_snapshot_hash text, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid:=auth.uid();
  v_request_hash text;
  v_operation app.loyalty_tier_default_operations_v143%rowtype;
  v_header public.firm_config_versions%rowtype;
  v_version uuid:=p_version;
  v_created_draft boolean:=false;
  v_draft jsonb;
  v_snapshot_hash text;
  v_tier_ids jsonb:='[]'::jsonb;
  v_result jsonb;
begin
  if v_actor is null then
    raise exception 'authenticated owner required' using errcode='28000';
  end if;
  if p_idempotency_key is null then
    raise exception 'idempotency key is required' using errcode='22023';
  end if;
  p_basis:=lower(btrim(coalesce(p_basis,'')));
  if p_basis not in ('visits','spend','points_earned') then
    raise exception 'tier basis must be visits, spend or points earned' using errcode='22023';
  end if;
  if not app.c45_owner_loyalty_write(p_business) then
    raise exception 'owner loyalty configuration access required' using errcode='42501';
  end if;

  v_request_hash:=md5(jsonb_build_object(
    'business_id',p_business,
    'version_id',p_version,
    'basis',p_basis,
    'expected_snapshot_hash',p_expected_snapshot_hash
  )::text);
  perform pg_advisory_xact_lock(hashtextextended(
    'v148-tier-defaults:'||p_business::text||':'||v_actor::text||':'||p_idempotency_key::text,0
  ));
  perform 1 from public.businesses where id=p_business for update;
  if not found then raise exception 'business not found' using errcode='22023'; end if;

  select * into v_operation
  from app.loyalty_tier_default_operations_v143
  where business_id=p_business and actor_id=v_actor and idempotency_key=p_idempotency_key
  for update;
  if found then
    if v_operation.request_hash<>v_request_hash then
      raise exception 'idempotency key conflicts with changed tier defaults'
        using errcode='22023';
    end if;
    return v_operation.result_snapshot;
  end if;

  if v_version is null then
    select version.id into v_version
    from public.firm_config_versions version
    where version.business_id=p_business and version.status='draft'
    order by version.version_no desc,version.id
    limit 1;
    if v_version is null then
      v_draft:=public.create_loyalty_config_draft(
        p_business,
        (select active_config_version_id from public.businesses where id=p_business),
        'recommended_tiers_v148'
      )::jsonb;
      v_version:=(v_draft->>'version_id')::uuid;
      v_created_draft:=true;
    end if;
  end if;

  select * into v_header from public.firm_config_versions
  where id=v_version for update;
  if not found or v_header.business_id<>p_business
     or not app.c45_owner_loyalty_write(v_header.business_id) then
    raise exception 'owner loyalty configuration access required' using errcode='42501';
  end if;
  if v_header.status<>'draft' then
    raise exception 'only a draft may receive recommended tiers' using errcode='55000';
  end if;
  if p_expected_snapshot_hash is not null
     and v_header.snapshot_hash is distinct from p_expected_snapshot_hash then
    raise exception 'draft configuration changed; reload before adding tiers'
      using errcode='40001';
  end if;

  if exists(
    select 1 from public.loyalty_tier_versions
    where business_id=p_business and config_version_id=v_version
  ) then
    select coalesce(jsonb_agg(tier_id order by threshold,sort,tier_id),'[]'::jsonb)
      into v_tier_ids
    from public.loyalty_tier_versions
    where business_id=p_business and config_version_id=v_version;
    v_result:=jsonb_build_object(
      'version_id',v_version,'tier_ids',v_tier_ids,'status','existing_tiers',
      'snapshot_hash',v_header.snapshot_hash,'created_draft',v_created_draft,
      'published',false,'replayed',false
    );
  else
    with templates(name,threshold,points_multiplier,perk_note,sort) as (
      values
        ('Gold',0::integer,1::numeric,'Standard points earning',0),
        ('Platinum',case when p_basis='visits' then 5 else 500 end::integer,
          1.25::numeric,'25% more points',1),
        ('Diamond',case when p_basis='visits' then 12 else 1500 end::integer,
          1.5::numeric,'50% more points',2)
    ), inserted as (
      insert into public.loyalty_tier_versions(
        tier_id,config_version_id,business_id,name,threshold,points_multiplier,
        perk_note,sort,active,effective_from,expires_at
      )
      select gen_random_uuid(),v_version,p_business,name,threshold,
        points_multiplier,perk_note,sort,true,null,null
      from templates
      returning tier_id,threshold,sort
    )
    select coalesce(jsonb_agg(tier_id order by threshold,sort,tier_id),'[]'::jsonb)
      into v_tier_ids from inserted;
    perform app.refresh_loyalty_config_snapshot(v_version);
    select snapshot_hash into v_snapshot_hash
    from public.firm_config_versions where id=v_version;
    v_result:=jsonb_build_object(
      'version_id',v_version,'tier_ids',v_tier_ids,'status','draft_ready',
      'snapshot_hash',v_snapshot_hash,'created_draft',v_created_draft,
      'published',false,'replayed',false
    );
  end if;

  insert into app.loyalty_tier_default_operations_v143(
    business_id,actor_id,idempotency_key,request_hash,config_version_id,result_snapshot
  ) values(
    p_business,v_actor,p_idempotency_key,v_request_hash,v_version,v_result
  );
  return v_result;
end
$$;

--
-- Name: adjust_points(uuid, uuid, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.adjust_points(p_business uuid, p_client uuid, p_points integer, p_reason text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_staff uuid;
  v_balance integer;
  v_batch_balance integer;
  v_remaining integer;
  v_take integer;
  v_points_id uuid := gen_random_uuid();
  v_expiry timestamptz;
  v_batch record;
  lp public.loyalty_programs%rowtype;
  v_points_programme uuid;
begin
  if coalesce(p_points, 0) = 0 then
    raise exception 'points adjustment must be non-zero';
  end if;
  if p_reason is null or length(btrim(p_reason)) < 3 then
    raise exception 'points adjustment reason must be at least 3 characters';
  end if;

  select s.id into v_staff
    from public.staff s
   where s.business_id = p_business
     and s.user_id = v_actor
     and s.active
     and s.role = 'owner'
   order by s.created_at
   limit 1
   for update;
  if not found then
    raise exception 'only an active owner may adjust points'
      using errcode = '42501';
  end if;

  perform app.require_workspace_open_v173(p_business);

  perform 1 from public.clients c
   where c.id = p_client and c.business_id = p_business
   for update;
  if not found then
    raise exception 'client does not belong to this business';
  end if;

  -- v311 W5a: an owner points adjustment is a POINTS-programme fact. Fail closed.
  select spine.id into v_points_programme
    from public.business_programmes spine
   where spine.business_id = p_business and spine.kind = 'points';
  if v_points_programme is null then
    raise exception 'this business has no points programme to adjust'
      using errcode = 'check_violation';
  end if;

  select coalesce(sum(pl.points), 0)::integer into v_balance
    from public.points_ledger pl
   where pl.business_id = p_business and pl.client_id = p_client
     and pl.programme_id = v_points_programme;
  if p_points < 0 and v_balance + p_points < 0 then
    raise exception 'points adjustment would overdraw balance % by %', v_balance, -p_points;
  end if;

  if p_points < 0 then
    select coalesce(sum(pb.remaining), 0)::integer into v_batch_balance
      from public.points_batches pb
     where pb.business_id = p_business
       and pb.client_id = p_client
       and pb.programme_id = v_points_programme
       and pb.remaining > 0;
    if v_batch_balance < -p_points then
      raise exception 'points batches % cannot prove negative adjustment %',
        v_batch_balance, -p_points
        using errcode = 'check_violation';
    end if;

    v_remaining := -p_points;
    for v_batch in
      select pb.id, pb.remaining
        from public.points_batches pb
       where pb.business_id = p_business
         and pb.client_id = p_client
         and pb.programme_id = v_points_programme
         and pb.remaining > 0
       order by pb.expires_at nulls last, pb.earned_at, pb.id
       for update
    loop
      exit when v_remaining = 0;
      v_take := least(v_batch.remaining, v_remaining);
      update public.points_batches
         set remaining = remaining - v_take
       where id = v_batch.id;
      v_remaining := v_remaining - v_take;
    end loop;
  else
    select * into lp
      from public.loyalty_programs
     where business_id = p_business
       and active
       and kind = 'points'
     limit 1;
    v_expiry := case
      when found and lp.expiry_mode = 'fixed' and coalesce(lp.expiry_days, 0) > 0
        then now() + make_interval(days => lp.expiry_days)
      else null
    end;
    insert into public.points_batches (
      business_id, client_id, earned, remaining, earned_at, expires_at, programme_id
    ) values (
      p_business, p_client, p_points, p_points, now(), v_expiry, v_points_programme
    );
  end if;

  perform set_config('app.points_ledger_insert_id', v_points_id::text, true);
  perform set_config('app.points_ledger_write_scope', 'adjust_points', true);
  insert into public.points_ledger (
    id, business_id, client_id, entry_type, points, reference, actor, programme_id
  ) values (
    v_points_id, p_business, p_client, 'adjust', p_points, btrim(p_reason), v_actor,
    v_points_programme
  );
  perform set_config('app.points_ledger_insert_id', '', true);
  perform set_config('app.points_ledger_write_scope', '', true);

  return v_balance + p_points;
end $$;

--
-- Name: FUNCTION adjust_points(p_business uuid, p_client uuid, p_points integer, p_reason text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.adjust_points(p_business uuid, p_client uuid, p_points integer, p_reason text) IS 'v20/v173 owner points adjustment, v311 W5a programme-scoped. Balance, overdraw check, batch proof and FEFO drain are all restricted to the POINTS programme, and both the new batch and the ledger row are tagged with it — without this an owner granting 100 points would drain a customer''s STAMP batches to pay for a negative adjustment. The returned balance is now the points programme''s, identical to the business pot for every firm running one accruing programme.';

--
-- Name: append_billing_adjustment_v77(uuid, text, text, integer, integer, text, text, uuid, text, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.append_billing_adjustment_v77(p_business uuid, p_provider_invoice_id text, p_adjustment_type text, p_subtotal_ex_tax_cents integer, p_tax_cents integer, p_currency text, p_provider_object_id text, p_reversal_of uuid, p_reason text, p_evidence_sha256 text, p_occurred_at timestamp with time zone) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $_$
declare
  v_id uuid;
  v_total integer;
begin
  v_total := p_subtotal_ex_tax_cents + p_tax_cents;
  if p_adjustment_type not in (
    'credit','debit','refund','chargeback','external_payment','writeoff','reversal'
  ) or p_currency !~ '^[A-Z]{3}$'
     or p_evidence_sha256 !~ '^[0-9a-f]{64}$'
     or p_occurred_at is null then
    raise exception 'invalid billing adjustment' using errcode='22023';
  end if;
  if p_adjustment_type='reversal' and p_reversal_of is null then
    raise exception 'reversal reference is required' using errcode='22023';
  elsif p_adjustment_type<>'reversal' and p_reversal_of is not null then
    raise exception 'only a reversal may carry a reversal reference'
      using errcode='22023';
  end if;
  insert into public.billing_adjustments(
    business_id,provider_invoice_id,adjustment_type,subtotal_ex_tax_cents,
    tax_cents,total_cents,currency,provider_object_id,reversal_of,reason,
    evidence_sha256,occurred_at
  ) values (
    p_business,p_provider_invoice_id,p_adjustment_type,p_subtotal_ex_tax_cents,
    p_tax_cents,v_total,p_currency,p_provider_object_id,p_reversal_of,p_reason,
    p_evidence_sha256,p_occurred_at
  ) returning id into v_id;
  insert into public.billing_evidence(
    business_id,evidence_type,entity_type,entity_id,content_sha256,external_reference
  ) values (
    p_business,'adjustment','billing_adjustment',v_id::text,
    p_evidence_sha256,p_provider_object_id
  );
  return v_id;
end
$_$;

--
-- Name: apply_module_template(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_module_template(p_staff uuid, p_template uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare t public.module_templates; v_biz uuid;
begin
  select business_id into v_biz from public.staff where id = p_staff;
  if v_biz is null then raise exception 'staff not found'; end if;
  if not app.is_salon_owner(v_biz) then raise exception 'owner role required'; end if;
  select * into t from public.module_templates where id = p_template and business_id = v_biz;
  if not found then raise exception 'template not found for this business'; end if;
  return public.set_staff_modules(p_staff, t.modules);
end $$;

--
-- Name: apply_stripe_billing_event_v77(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_stripe_billing_event_v77(p_event_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_result jsonb;
  v_event public.billing_provider_events%rowtype;
  v_recovery jsonb;
begin
  v_result:=public.apply_stripe_billing_event_v94_base(p_event_id);
  select * into v_event
  from public.billing_provider_events event_row
  where event_row.provider='stripe' and event_row.event_id=p_event_id;
  if v_event.event_type='invoice.paid'
     and coalesce(v_result->>'status','')='processed'
     and v_event.business_id is not null
  then
    v_recovery:=app.reconcile_subscription_payment_v94(
      v_event.business_id,
      'stripe-paid:'||p_event_id,
      'Stripe invoice.paid recovered the subscription workspace',
      null,false
    );
    v_result:=v_result||jsonb_build_object(
      'subscription_lifecycle',v_recovery
    );
  elsif v_event.event_type='invoice.paid'
        and coalesce(v_result->>'duplicate','false')='true'
        and v_event.business_id is not null
  then
    v_recovery:=app.reconcile_subscription_payment_v94(
      v_event.business_id,
      'stripe-paid:'||p_event_id,
      'Stripe invoice.paid recovered the subscription workspace',
      null,false
    );
    v_result:=v_result||jsonb_build_object(
      'subscription_lifecycle',v_recovery
    );
  end if;
  return v_result;
end
$$;

--
-- Name: apply_stripe_billing_event_v94_base(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_stripe_billing_event_v94_base(p_event_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_event public.billing_provider_events%rowtype;
  v_object jsonb;
  v_business uuid;
  v_rank smallint;
  v_customer text;
  v_subscription text;
  v_invoice text;
  v_status text;
  v_interval text;
  v_interval_count integer;
  v_cadence_months integer;
  v_cadence text;
  v_period_start timestamptz;
  v_period_end timestamptz;
  v_next_attempt timestamptz;
  v_paid_at timestamptz;
  v_subtotal integer;
  v_tax integer;
  v_total integer;
  v_due integer;
  v_paid integer;
  v_remaining integer;
  v_item jsonb;
  v_item_role text;
  v_price text;
  v_attempt_state text;
  v_adjustment_total integer;
  v_adjustment_tax integer;
  v_adjustment_net integer;
  v_adjustment_invoice public.billing_provider_invoices%rowtype;
begin
  select * into v_event
    from public.billing_provider_events
   where provider = 'stripe' and event_id = p_event_id
   for update;
  if not found then
    raise exception 'Stripe event is not in the durable inbox' using errcode = '22023';
  end if;
  if v_event.processing_status in ('processed','ignored') then
    return jsonb_build_object(
      'event_id',p_event_id,'status',v_event.processing_status,'duplicate',true
    );
  end if;

  update public.billing_provider_events
     set processing_status = 'processing',
         processing_attempts = processing_attempts + 1,
         last_error = null
   where id = v_event.id;

  begin
    v_object := v_event.payload #> '{data,object}';
    v_rank := app.stripe_event_rank_v77(v_event.event_type);
    if v_rank = 0 or jsonb_typeof(v_object) <> 'object' then
      update public.billing_provider_events
         set processing_status='ignored',processed_at=now()
       where id=v_event.id;
      return jsonb_build_object('event_id',p_event_id,'status','ignored');
    end if;

    v_business := app.stripe_business_v77(v_event.payload);
    if v_business is null then
      raise exception 'Stripe event cannot be mapped to a business';
    end if;
    v_customer := case
      when jsonb_typeof(v_object->'customer') = 'string' then v_object->>'customer'
      else v_object#>>'{customer,id}'
    end;
    v_subscription := coalesce(
      case when jsonb_typeof(v_object->'subscription') = 'string'
           then v_object->>'subscription' else v_object#>>'{subscription,id}' end,
      v_object#>>'{parent,subscription_details,subscription}'
    );

    if v_customer is not null then
      if exists(
        select 1 from public.billing_provider_customers customer
         where (
           customer.provider_customer_id=v_customer
           and customer.business_id<>v_business
         ) or (
           customer.business_id=v_business
           and customer.provider_customer_id<>v_customer
         )
      ) then
        raise exception 'Stripe customer is already linked to another business';
      end if;
      insert into public.billing_provider_customers(
        business_id,provider_customer_id,currency,livemode,provider_created_at,
        provider_event_created_at,provider_event_rank,last_event_id
      ) values (
        v_business,v_customer,upper(nullif(v_object->>'currency','')),
        v_event.livemode,app.stripe_epoch_v77(v_object->'created'),
        v_event.event_created_at,v_rank,v_event.event_id
      )
      on conflict(provider_customer_id) do update
        set currency=coalesce(excluded.currency,billing_provider_customers.currency),
            provider_event_created_at=excluded.provider_event_created_at,
            provider_event_rank=excluded.provider_event_rank,
            last_event_id=excluded.last_event_id,updated_at=now()
      where (excluded.provider_event_created_at,excluded.provider_event_rank)
            >= (billing_provider_customers.provider_event_created_at,
                billing_provider_customers.provider_event_rank);
    end if;

    if v_event.event_type like 'customer.subscription.%' then
      v_subscription := v_object->>'id';
      if exists(
        select 1 from public.billing_provider_subscriptions subscription
         where subscription.provider_subscription_id=v_subscription
           and subscription.business_id<>v_business
      ) then
        raise exception 'Stripe subscription is already linked to another business';
      end if;
      v_status := case
        when v_event.event_type = 'customer.subscription.deleted' then 'canceled'
        when v_object->>'status' in (
          'trialing','active','incomplete','incomplete_expired','past_due',
          'unpaid','paused','canceled'
        ) then v_object->>'status'
        else 'incomplete'
      end;
      select item into v_item
        from jsonb_array_elements(coalesce(v_object#>'{items,data}','[]'::jsonb)) item
       order by coalesce((item->>'quantity')::integer,0) desc
       limit 1;
      v_interval := v_item#>>'{price,recurring,interval}';
      v_interval_count := nullif(v_item#>>'{price,recurring,interval_count}','')::integer;
      v_cadence := app.stripe_cadence_v77(v_interval,v_interval_count);
      v_cadence_months := case v_cadence
        when 'quarterly' then 3
        when 'half_yearly' then 6
        when 'annual' then 12
        else null
      end;
      v_period_start := coalesce(
        app.stripe_epoch_v77(v_item->'current_period_start'),
        app.stripe_epoch_v77(v_object->'current_period_start')
      );
      v_period_end := coalesce(
        app.stripe_epoch_v77(v_item->'current_period_end'),
        app.stripe_epoch_v77(v_object->'current_period_end')
      );

      insert into public.billing_provider_subscriptions(
        business_id,provider_customer_id,provider_subscription_id,status,
        cadence,cadence_months,currency,current_period_start,current_period_end,
        billing_cycle_anchor,trial_end,cancel_at_period_end,canceled_at,ended_at,
        livemode,provider_event_created_at,provider_event_rank,last_event_id
      ) values (
        v_business,v_customer,v_subscription,v_status,v_cadence,v_cadence_months,
        upper(nullif(v_object->>'currency','')),v_period_start,v_period_end,
        app.stripe_epoch_v77(v_object->'billing_cycle_anchor'),
        app.stripe_epoch_v77(v_object->'trial_end'),
        coalesce((v_object->>'cancel_at_period_end')::boolean,false),
        app.stripe_epoch_v77(v_object->'canceled_at'),
        app.stripe_epoch_v77(v_object->'ended_at'),
        v_event.livemode,v_event.event_created_at,v_rank,v_event.event_id
      )
      on conflict(provider_subscription_id) do update
        set status=excluded.status,cadence=excluded.cadence,
            cadence_months=excluded.cadence_months,currency=excluded.currency,
            current_period_start=excluded.current_period_start,
            current_period_end=excluded.current_period_end,
            billing_cycle_anchor=excluded.billing_cycle_anchor,
            trial_end=excluded.trial_end,
            cancel_at_period_end=excluded.cancel_at_period_end,
            canceled_at=excluded.canceled_at,ended_at=excluded.ended_at,
            provider_event_created_at=excluded.provider_event_created_at,
            provider_event_rank=excluded.provider_event_rank,
            last_event_id=excluded.last_event_id,updated_at=now()
      where (excluded.provider_event_created_at,excluded.provider_event_rank)
            >= (billing_provider_subscriptions.provider_event_created_at,
                billing_provider_subscriptions.provider_event_rank);

      for v_item in
        select value from jsonb_array_elements(coalesce(v_object#>'{items,data}','[]'::jsonb))
      loop
        v_price := coalesce(v_item#>>'{price,id}',v_item->>'price');
        select case
          when catalog.provider_base_price_id = v_price then 'base'
          when catalog.provider_seat_price_id = v_price then 'seat'
          else 'other'
        end into v_item_role
          from public.billing_price_catalog catalog
         where v_price in (catalog.provider_base_price_id,catalog.provider_seat_price_id)
         order by catalog.effective_from desc
         limit 1;
        v_item_role := coalesce(v_item_role,'other');
        insert into public.billing_provider_subscription_items(
          provider_subscription_id,provider_item_id,item_role,provider_price_id,
          quantity,unit_amount_cents,currency,interval_name,interval_count,
          current_period_start,current_period_end,provider_event_created_at,
          provider_event_rank,last_event_id
        ) values (
          v_subscription,v_item->>'id',v_item_role,v_price,
          coalesce((v_item->>'quantity')::integer,0),
          nullif(v_item#>>'{price,unit_amount}','')::integer,
          upper(nullif(v_item#>>'{price,currency}','')),
          v_item#>>'{price,recurring,interval}',
          nullif(v_item#>>'{price,recurring,interval_count}','')::integer,
          app.stripe_epoch_v77(v_item->'current_period_start'),
          app.stripe_epoch_v77(v_item->'current_period_end'),
          v_event.event_created_at,v_rank,v_event.event_id
        )
        on conflict(provider_item_id) do update
          set item_role=excluded.item_role,provider_price_id=excluded.provider_price_id,
              quantity=excluded.quantity,unit_amount_cents=excluded.unit_amount_cents,
              currency=excluded.currency,interval_name=excluded.interval_name,
              interval_count=excluded.interval_count,
              current_period_start=excluded.current_period_start,
              current_period_end=excluded.current_period_end,
              provider_event_created_at=excluded.provider_event_created_at,
              provider_event_rank=excluded.provider_event_rank,
              last_event_id=excluded.last_event_id,updated_at=now()
        where (excluded.provider_event_created_at,excluded.provider_event_rank)
              >= (billing_provider_subscription_items.provider_event_created_at,
                  billing_provider_subscription_items.provider_event_rank);
      end loop;

      update public.subscriptions tenant_subscription
         set billing_provider='stripe',provider_customer_id=v_customer,
             provider_subscription_id=v_subscription,status=v_status,
             billing_cadence=v_cadence,cadence_months=v_cadence_months,
             current_period_start=coalesce(v_period_start,current_period_start),
             current_period_end=coalesce(v_period_end,current_period_end),
             next_payment_at=v_period_end,
             cancel_at_period_end=coalesce((v_object->>'cancel_at_period_end')::boolean,false),
             canceled_at=app.stripe_epoch_v77(v_object->'canceled_at'),
             provider_base_item_id=(
               select item.provider_item_id
                 from public.billing_provider_subscription_items item
                where item.provider_subscription_id=v_subscription
                  and item.item_role='base'
                order by item.updated_at desc limit 1
             ),
             provider_seat_item_id=(
               select item.provider_item_id
                 from public.billing_provider_subscription_items item
                where item.provider_subscription_id=v_subscription
                  and item.item_role='seat'
                order by item.updated_at desc limit 1
             ),
             provider_base_price_id=(
               select item.provider_price_id
                 from public.billing_provider_subscription_items item
                where item.provider_subscription_id=v_subscription
                  and item.item_role='base'
                order by item.updated_at desc limit 1
             ),
             provider_seat_price_id=(
               select item.provider_price_id
                 from public.billing_provider_subscription_items item
                where item.provider_subscription_id=v_subscription
                  and item.item_role='seat'
                order by item.updated_at desc limit 1
             ),
             provider_seat_quantity=coalesce((
               select item.quantity
                 from public.billing_provider_subscription_items item
                where item.provider_subscription_id=v_subscription
                  and item.item_role='seat'
                order by item.updated_at desc limit 1
             ),0),
             provider_event_created_at=v_event.event_created_at,
             provider_event_rank=v_rank,updated_at=now()
       where tenant_subscription.business_id=v_business
         and (tenant_subscription.provider_event_created_at is null
              or (v_event.event_created_at,v_rank)
                 >= (tenant_subscription.provider_event_created_at,
                     tenant_subscription.provider_event_rank));
    end if;

    if v_event.event_type like 'invoice.%' then
      v_invoice := v_object->>'id';
      if exists(
        select 1 from public.billing_provider_invoices invoice
         where invoice.provider_invoice_id=v_invoice
           and invoice.business_id<>v_business
      ) then
        raise exception 'Stripe invoice is already linked to another business';
      end if;
      if v_subscription is not null and exists(
        select 1 from public.billing_provider_subscriptions subscription
         where subscription.provider_subscription_id=v_subscription
           and subscription.business_id<>v_business
      ) then
        raise exception 'Stripe invoice references another business subscription';
      end if;
      v_status := case
        when v_event.event_type = 'invoice.paid' then 'paid'
        when v_event.event_type = 'invoice.voided' then 'void'
        when v_event.event_type = 'invoice.marked_uncollectible' then 'uncollectible'
        when v_object->>'status' in ('draft','open','void','uncollectible')
          then v_object->>'status'
        else 'open'
      end;
      v_subtotal := greatest(coalesce(
        nullif(v_object->>'total_excluding_tax','')::integer,
        nullif(v_object->>'subtotal_excluding_tax','')::integer,
        nullif(v_object->>'subtotal','')::integer,0
      ),0);
      v_total := greatest(coalesce(nullif(v_object->>'total','')::integer,v_subtotal),0);
      v_tax := greatest(v_total-v_subtotal,0);
      v_due := greatest(coalesce(nullif(v_object->>'amount_due','')::integer,v_total),0);
      v_paid := greatest(coalesce(nullif(v_object->>'amount_paid','')::integer,0),0);
      v_remaining := greatest(coalesce(
        nullif(v_object->>'amount_remaining','')::integer,v_due-v_paid,0
      ),0);
      v_next_attempt := app.stripe_epoch_v77(v_object->'next_payment_attempt');
      v_paid_at := case when v_event.event_type='invoice.paid' then coalesce(
        app.stripe_epoch_v77(v_object#>'{status_transitions,paid_at}'),
        v_event.event_created_at
      ) end;

      insert into public.billing_provider_invoices(
        business_id,provider_customer_id,provider_subscription_id,
        provider_invoice_id,provider_payment_intent_id,number,currency,
        collection_method,status,paid_normalized,subtotal_ex_tax_cents,tax_cents,
        total_cents,amount_due_cents,amount_paid_cents,amount_remaining_cents,
        net_cash_ex_tax_cents,period_start,period_end,due_at,
        next_payment_attempt_at,paid_at,finalized_at,voided_at,
        marked_uncollectible_at,livemode,provider_event_created_at,
        provider_event_rank,last_event_id
      ) values (
        v_business,v_customer,v_subscription,v_invoice,
        case when jsonb_typeof(v_object->'payment_intent')='string'
             then v_object->>'payment_intent'
             else v_object#>>'{payment_intent,id}' end,
        v_object->>'number',upper(coalesce(nullif(v_object->>'currency',''),'SGD')),
        v_object->>'collection_method',v_status,
        v_event.event_type='invoice.paid',v_subtotal,v_tax,v_total,v_due,v_paid,
        v_remaining,
        case when v_event.event_type='invoice.paid'
             then greatest(least(v_paid,v_total)-least(v_tax,least(v_paid,v_total)),0)
             else 0 end,
        app.stripe_epoch_v77(v_object->'period_start'),
        app.stripe_epoch_v77(v_object->'period_end'),
        app.stripe_epoch_v77(v_object->'due_date'),v_next_attempt,v_paid_at,
        app.stripe_epoch_v77(v_object#>'{status_transitions,finalized_at}'),
        app.stripe_epoch_v77(v_object#>'{status_transitions,voided_at}'),
        app.stripe_epoch_v77(v_object#>'{status_transitions,marked_uncollectible_at}'),
        v_event.livemode,v_event.event_created_at,v_rank,v_event.event_id
      )
      on conflict(provider_invoice_id) do update
        set provider_payment_intent_id=coalesce(
              excluded.provider_payment_intent_id,
              billing_provider_invoices.provider_payment_intent_id
            ),
            number=coalesce(excluded.number,billing_provider_invoices.number),
            collection_method=excluded.collection_method,status=excluded.status,
            paid_normalized=excluded.paid_normalized,
            subtotal_ex_tax_cents=excluded.subtotal_ex_tax_cents,
            tax_cents=excluded.tax_cents,total_cents=excluded.total_cents,
            amount_due_cents=excluded.amount_due_cents,
            amount_paid_cents=excluded.amount_paid_cents,
            amount_remaining_cents=excluded.amount_remaining_cents,
            net_cash_ex_tax_cents=excluded.net_cash_ex_tax_cents,
            period_start=excluded.period_start,period_end=excluded.period_end,
            due_at=excluded.due_at,
            next_payment_attempt_at=excluded.next_payment_attempt_at,
            paid_at=excluded.paid_at,finalized_at=excluded.finalized_at,
            voided_at=excluded.voided_at,
            marked_uncollectible_at=excluded.marked_uncollectible_at,
            provider_event_created_at=excluded.provider_event_created_at,
            provider_event_rank=excluded.provider_event_rank,
            last_event_id=excluded.last_event_id,updated_at=now()
      where (excluded.provider_event_created_at,excluded.provider_event_rank)
            >= (billing_provider_invoices.provider_event_created_at,
                billing_provider_invoices.provider_event_rank);

      if v_event.event_type in (
        'invoice.paid','invoice.payment_failed','invoice.payment_action_required'
      ) then
        v_attempt_state := case v_event.event_type
          when 'invoice.paid' then 'paid'
          when 'invoice.payment_failed' then 'failed'
          else 'action_required'
        end;
        insert into public.billing_payment_attempts(
          business_id,provider_invoice_id,source_event_id,
          provider_payment_intent_id,provider_charge_id,attempt_state,
          amount_cents,tax_cents,failure_code,failure_message,next_attempt_at,
          occurred_at,collection_method
        ) values (
          v_business,v_invoice,v_event.event_id,
          case when jsonb_typeof(v_object->'payment_intent')='string'
               then v_object->>'payment_intent'
               else v_object#>>'{payment_intent,id}' end,
          v_object#>>'{charge,id}',v_attempt_state,
          case when v_attempt_state='paid' then v_paid else v_due end,
          v_tax,v_object#>>'{last_finalization_error,code}',
          left(v_object#>>'{last_finalization_error,message}',1000),
          v_next_attempt,v_event.event_created_at,v_object->>'collection_method'
        ) on conflict(source_event_id) do nothing;
      end if;

      update public.subscriptions tenant_subscription
         set payment_status=case
               when v_event.event_type='invoice.payment_failed' then 'failed'
               when v_event.event_type='invoice.payment_action_required'
                 then 'action_required'
               when v_event.event_type='invoice.paid' then 'paid'
               else payment_status
             end,
             period_subtotal_cents=v_subtotal,period_tax_cents=v_tax,
             period_total_cents=v_total,
             next_payment_at=case
               when v_event.event_type in (
                 'invoice.payment_failed','invoice.payment_action_required'
               ) then v_next_attempt
               else next_payment_at
             end,
             last_paid_at=case when v_event.event_type='invoice.paid'
                               then v_paid_at else last_paid_at end,
             last_paid_invoice_id=case when v_event.event_type='invoice.paid'
                                       then v_invoice else last_paid_invoice_id end,
             payment_event_created_at=v_event.event_created_at,
             payment_event_rank=v_rank,updated_at=now()
       where tenant_subscription.business_id=v_business
         and (tenant_subscription.payment_event_created_at is null
              or (v_event.event_created_at,v_rank)
                 >= (tenant_subscription.payment_event_created_at,
                     tenant_subscription.payment_event_rank));
    end if;

    if v_event.event_type in ('refund.created','charge.dispute.created') then
      if v_event.event_type='refund.created' then
        select invoice_row.* into v_adjustment_invoice
          from public.billing_provider_invoices invoice_row
         where invoice_row.provider_payment_intent_id =
               coalesce(
                 case when jsonb_typeof(v_object->'payment_intent')='string'
                      then v_object->>'payment_intent'
                      else v_object#>>'{payment_intent,id}' end,
                 (
                   select attempt.provider_payment_intent_id
                     from public.billing_payment_attempts attempt
                    where attempt.provider_charge_id = v_object->>'charge'
                    order by attempt.occurred_at desc limit 1
                 )
               )
         order by invoice_row.paid_at desc nulls last
         limit 1;
        v_adjustment_total := -greatest(coalesce((v_object->>'amount')::integer,0),0);
      else
        select invoice_row.* into v_adjustment_invoice
          from public.billing_payment_attempts attempt
          join public.billing_provider_invoices invoice_row
            on invoice_row.provider_invoice_id=attempt.provider_invoice_id
         where attempt.provider_charge_id = coalesce(
           case when jsonb_typeof(v_object->'charge')='string'
                then v_object->>'charge' else v_object#>>'{charge,id}' end,
           v_object->>'charge'
         )
         order by attempt.occurred_at desc limit 1;
        v_adjustment_total := -greatest(coalesce((v_object->>'amount')::integer,0),0);
      end if;
      if v_adjustment_invoice.id is null or v_adjustment_total = 0 then
        raise exception 'refund or chargeback cannot be mapped to a paid invoice';
      end if;
      v_adjustment_tax := case when v_adjustment_invoice.total_cents > 0 then
        -floor(
          abs(v_adjustment_total)::numeric
          * v_adjustment_invoice.tax_cents::numeric
          / v_adjustment_invoice.total_cents::numeric
        )::integer
      else 0 end;
      v_adjustment_net := v_adjustment_total-v_adjustment_tax;
      insert into public.billing_adjustments(
        business_id,provider_invoice_id,adjustment_type,
        subtotal_ex_tax_cents,tax_cents,total_cents,currency,source_event_id,
        provider_object_id,reason,evidence_sha256,occurred_at
      ) values (
        v_adjustment_invoice.business_id,
        v_adjustment_invoice.provider_invoice_id,
        case when v_event.event_type='refund.created' then 'refund' else 'chargeback' end,
        v_adjustment_net,v_adjustment_tax,v_adjustment_total,
        v_adjustment_invoice.currency,v_event.event_id,v_object->>'id',
        case when v_event.event_type='refund.created'
             then 'Stripe refund event' else 'Stripe chargeback event' end,
        v_event.payload_sha256,v_event.event_created_at
      ) on conflict(source_event_id) do nothing;
    end if;

    insert into public.billing_evidence(
      business_id,evidence_type,entity_type,entity_id,content_sha256,external_reference
    ) values (
      v_business,'provider_event','stripe_event',v_event.event_id,
      v_event.payload_sha256,v_event.object_id
    ) on conflict do nothing;

    update public.billing_provider_events
       set processing_status='processed',business_id=v_business,
           processed_at=now(),last_error=null
     where id=v_event.id;
    return jsonb_build_object(
      'event_id',p_event_id,'status','processed','business_id',v_business
    );
  exception when others then
    update public.billing_provider_events
       set processing_status='failed',last_error=left(sqlerrm,2000)
     where id=v_event.id;
    return jsonb_build_object(
      'event_id',p_event_id,'status','failed','error',left(sqlerrm,500)
    );
  end;
end
$$;

--
-- Name: FUNCTION apply_stripe_billing_event_v94_base(p_event_id text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.apply_stripe_billing_event_v94_base(p_event_id text) IS 'Service-role-only normalizer. invoice.paid is the sole event that sets normalized paid truth; provider timestamps and event ranks reject stale regressions.';

--
-- Name: apply_stripe_connect_payment_event_v142(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_stripe_connect_payment_event_v142(p_event_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_event public.stripe_connect_event_inbox_v142%rowtype;
        v_attempt public.pos_payment_attempts_v142%rowtype;
        v_object jsonb; v_result jsonb; v_sale uuid; v_previous_sub text;
        v_previous_finalize text;
        v_amount int; v_currency text; v_provider_status text;
begin
  perform app.v142_service_guard();
  select * into v_event from public.stripe_connect_event_inbox_v142 where event_id=p_event_id for update;
  if not found then raise exception 'Connect event not found' using errcode='22023'; end if;
  if v_event.processing_status in ('processed','ignored','refund_required','refund_pending','refund_failed','refunded') then
    return coalesce(v_event.processing_result,jsonb_build_object('status',v_event.processing_status));
  end if;
  if v_event.event_type='account.updated' then
    update public.stripe_connect_event_inbox_v142 set processing_status='ignored',processed_at=now(),
      processing_result=jsonb_build_object('status','account_event_requires_provider_refresh')
      where event_id=p_event_id;
    return jsonb_build_object('status','account_event_requires_provider_refresh');
  end if;
  if v_event.event_type not in ('payment_intent.processing','payment_intent.succeeded',
      'payment_intent.payment_failed','payment_intent.canceled') then
    update public.stripe_connect_event_inbox_v142 set processing_status='ignored',processed_at=now(),
      processing_result=jsonb_build_object('status','ignored_event_type') where event_id=p_event_id;
    return jsonb_build_object('status','ignored_event_type');
  end if;
  v_object:=v_event.payload#>'{data,object}';
  v_amount:=coalesce((v_object->>'amount')::int,0);
  v_currency:=upper(coalesce(v_object->>'currency',''));
  v_provider_status:=coalesce(v_object->>'status','');
  select * into v_attempt from public.pos_payment_attempts_v142
   where provider_account_id=v_event.connected_account_id
     and provider_payment_intent_id=v_event.object_id for update;
  if not found then
    update public.stripe_connect_event_inbox_v142 set processing_status='ignored',processed_at=now(),
      processing_result=jsonb_build_object('status','unknown_payment_intent') where event_id=p_event_id;
    return jsonb_build_object('status','unknown_payment_intent');
  end if;
  if v_attempt.livemode is distinct from v_event.livemode
     or v_amount is distinct from v_attempt.amount_cents or v_currency is distinct from v_attempt.currency
     or coalesce(v_object#>>'{metadata,peekaa_pos_attempt_id}','') is distinct from v_attempt.id::text
     or coalesce(v_object#>>'{metadata,peekaa_business_id}','') is distinct from v_attempt.business_id::text then
    v_result:=case when v_event.event_type='payment_intent.succeeded' and v_provider_status='succeeded'
      then jsonb_build_object('status','refund_required','attempt_id',v_attempt.id,
        'provider_account_id',v_attempt.provider_account_id,'payment_intent_id',v_attempt.provider_payment_intent_id)
      else jsonb_build_object('status','provider_envelope_mismatch','attempt_id',v_attempt.id) end;
    update public.pos_payment_attempts_v142 set
      status=case when v_event.event_type='payment_intent.succeeded' and v_provider_status='succeeded'
        then 'refund_required' else 'fulfilment_failed' end,
      failure_code='provider_envelope_mismatch',
      paid_at=case when v_event.event_type='payment_intent.succeeded' then v_event.event_created_at else paid_at end,
      provider_event_created_at=v_event.event_created_at,provider_event_id=v_event.event_id,updated_at=now()
     where id=v_attempt.id;
    update public.stripe_connect_event_inbox_v142 set
      processing_status=case when v_event.event_type='payment_intent.succeeded' and v_provider_status='succeeded'
        then 'refund_required' else 'failed' end,processed_at=now(),
      processing_result=v_result
     where event_id=p_event_id;
    return v_result;
  end if;
  if v_attempt.status in ('succeeded','refund_required','refund_pending','refund_failed','refunded') then
    v_result:=jsonb_build_object('status',case when v_attempt.status='succeeded' then 'duplicate_ignored'
      else v_attempt.status end,'attempt_id',v_attempt.id,'sale_id',v_attempt.sale_id,
      'refund_id',v_attempt.provider_refund_id);
    update public.stripe_connect_event_inbox_v142 set processing_status='processed',processed_at=now(),processing_result=v_result
     where event_id=p_event_id;
    return v_result;
  end if;
  if v_attempt.provider_event_created_at is not null
     and v_event.event_created_at<v_attempt.provider_event_created_at then
    v_result:=jsonb_build_object('status','stale_event_ignored','attempt_id',v_attempt.id);
    update public.stripe_connect_event_inbox_v142 set processing_status='ignored',processed_at=now(),processing_result=v_result
     where event_id=p_event_id;
    return v_result;
  end if;
  if v_event.event_type='payment_intent.succeeded' and v_provider_status='succeeded' then
    if v_event.event_created_at>v_attempt.expires_at then
      update public.pos_payment_attempts_v142 set status='refund_required',paid_at=v_event.event_created_at,
        failure_code='checkout_evaluation_expired',provider_event_created_at=v_event.event_created_at,
        provider_event_id=v_event.event_id,updated_at=now() where id=v_attempt.id;
      v_result:=jsonb_build_object('status','refund_required','attempt_id',v_attempt.id,
        'provider_account_id',v_attempt.provider_account_id,'payment_intent_id',v_attempt.provider_payment_intent_id);
      update public.stripe_connect_event_inbox_v142 set processing_status='refund_required',processed_at=now(),processing_result=v_result
       where event_id=p_event_id;
      return v_result;
    end if;
    v_previous_sub:=current_setting('request.jwt.claim.sub',true);
    v_previous_finalize:=current_setting('app.v142_provider_finalize',true);
    perform set_config('request.jwt.claim.sub',v_attempt.created_by::text,true);
    perform set_config('app.v142_provider_finalize',v_attempt.id::text,true);
    begin
      v_result:=public.record_cart_sale(v_attempt.business_id,v_attempt.client_id,v_attempt.branch_id,
        v_attempt.staff_id,'paynow','v142-pos-'||v_attempt.id::text,null,v_attempt.evaluation_id,true)::jsonb;
    exception when others then
      perform set_config('request.jwt.claim.sub',coalesce(v_previous_sub,''),true);
      perform set_config('app.v142_provider_finalize',coalesce(v_previous_finalize,''),true);
      update public.pos_payment_attempts_v142 set status='refund_required',paid_at=v_event.event_created_at,
        failure_code=left('sale_finalise:'||sqlstate,160),provider_event_created_at=v_event.event_created_at,
        provider_event_id=v_event.event_id,updated_at=now() where id=v_attempt.id;
      v_result:=jsonb_build_object('status','refund_required','attempt_id',v_attempt.id,
        'provider_account_id',v_attempt.provider_account_id,'payment_intent_id',v_attempt.provider_payment_intent_id);
      update public.stripe_connect_event_inbox_v142 set processing_status='refund_required',processed_at=now(),processing_result=v_result
       where event_id=p_event_id;
      return v_result;
    end;
    perform set_config('request.jwt.claim.sub',coalesce(v_previous_sub,''),true);
    perform set_config('app.v142_provider_finalize',coalesce(v_previous_finalize,''),true);
    v_sale:=nullif(v_result->>'sale_id','')::uuid;
    update public.pos_payment_attempts_v142 set status='succeeded',sale_id=v_sale,
      payment_reference=left(v_attempt.provider_payment_intent_id,120),paid_at=v_event.event_created_at,
      failure_code=null,provider_event_created_at=v_event.event_created_at,provider_event_id=v_event.event_id,updated_at=now()
     where id=v_attempt.id;
    v_result:=jsonb_build_object('status','succeeded','attempt_id',v_attempt.id,'sale_id',v_sale,
      'payment_reference',v_attempt.provider_payment_intent_id);
    update public.stripe_connect_event_inbox_v142 set processing_status='processed',processed_at=now(),processing_result=v_result
     where event_id=p_event_id;
    return v_result;
  end if;
  update public.pos_payment_attempts_v142 set status=case v_event.event_type
      when 'payment_intent.processing' then 'processing'
      when 'payment_intent.canceled' then 'canceled' else 'failed' end,
    failure_code=case when v_event.event_type='payment_intent.payment_failed'
      then left(coalesce(v_object#>>'{last_payment_error,code}','payment_failed'),160) else null end,
    provider_event_created_at=v_event.event_created_at,provider_event_id=v_event.event_id,updated_at=now()
   where id=v_attempt.id;
  v_result:=jsonb_build_object('status',case v_event.event_type
      when 'payment_intent.processing' then 'processing'
      when 'payment_intent.canceled' then 'canceled' else 'failed' end,'attempt_id',v_attempt.id);
  update public.stripe_connect_event_inbox_v142 set processing_status='processed',processed_at=now(),processing_result=v_result
   where event_id=p_event_id;
  return v_result;
end $$;

--
-- Name: apply_stripe_connect_refund_event_v142(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_stripe_connect_refund_event_v142(p_event_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_event public.stripe_connect_event_inbox_v142%rowtype;
        v_attempt public.pos_payment_attempts_v142%rowtype;
        v_object jsonb; v_status text; v_failure text; v_result jsonb;
        v_amount int; v_currency text; v_attempt_id uuid; v_payment_intent text;
        v_previous_signed_event text;
begin
  perform app.v142_service_guard();
  select * into v_event from public.stripe_connect_event_inbox_v142 where event_id=p_event_id for update;
  if not found then raise exception 'Connect event not found' using errcode='22023'; end if;
  if v_event.processing_status in ('refunded','refund_failed') then
    return coalesce(v_event.processing_result,jsonb_build_object('status',v_event.processing_status));
  end if;
  if v_event.event_type not in ('refund.updated','refund.failed') then
    raise exception 'event is not a refund state event' using errcode='22023';
  end if;
  v_object:=v_event.payload#>'{data,object}';
  begin v_attempt_id:=nullif(v_object#>>'{metadata,peekaa_pos_attempt_id}','')::uuid;
  exception when others then v_attempt_id:=null; end;
  v_payment_intent:=coalesce(v_object->>'payment_intent','');
  v_amount:=coalesce((v_object->>'amount')::int,0);
  v_currency:=upper(coalesce(v_object->>'currency',''));
  v_status:=case when v_event.event_type='refund.failed' then 'failed'
                 else coalesce(v_object->>'status','') end;
  v_failure:=coalesce(v_object#>>'{failure_reason}',v_object#>>'{failure_balance_transaction}');
  select * into v_attempt from public.pos_payment_attempts_v142
   where id=v_attempt_id and provider_account_id=v_event.connected_account_id
     and provider_payment_intent_id=v_payment_intent for update;
  if not found or v_attempt.livemode is distinct from v_event.livemode
     or v_amount is distinct from v_attempt.amount_cents
     or v_currency is distinct from v_attempt.currency
     or (v_attempt.provider_refund_id is not null
         and v_attempt.provider_refund_id is distinct from v_event.object_id) then
    update public.stripe_connect_event_inbox_v142 set processing_status='failed',processed_at=now(),
      processing_result=jsonb_build_object('status','refund_envelope_mismatch') where event_id=p_event_id;
    return jsonb_build_object('status','refund_envelope_mismatch');
  end if;
  if v_attempt.refund_event_created_at is not null
     and v_event.event_created_at<v_attempt.refund_event_created_at then
    update public.stripe_connect_event_inbox_v142 set processing_status='ignored',processed_at=now(),
      processing_result=jsonb_build_object('status','stale_refund_event_ignored','attempt_id',v_attempt.id)
     where event_id=p_event_id;
    return jsonb_build_object('status','stale_refund_event_ignored','attempt_id',v_attempt.id);
  end if;
  v_previous_signed_event:=current_setting('app.v142_signed_refund_event',true);
  perform set_config('app.v142_signed_refund_event',p_event_id,true);
  begin
    v_result:=public.mark_pos_paynow_refund_state_v142(v_attempt.id,p_event_id,v_event.object_id,
      v_status,v_failure);
  exception when others then
    perform set_config('app.v142_signed_refund_event',coalesce(v_previous_signed_event,''),true);
    raise;
  end;
  perform set_config('app.v142_signed_refund_event',coalesce(v_previous_signed_event,''),true);
  update public.pos_payment_attempts_v142 set refund_event_created_at=v_event.event_created_at,
    refund_event_id=v_event.event_id where id=v_attempt.id;
  return v_result;
end $$;

--
-- Name: approve_consultant_accrual_v78(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_consultant_accrual_v78(p_accrual uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid:=auth.uid();
  v_row public.consultant_commission_accruals%rowtype;
begin
  if v_actor is null or not app.v89_platform_can('commissions','rw') then
    raise exception 'super-admin access is required' using errcode='42501';
  end if;
  if nullif(btrim(p_reason),'') is null then
    raise exception 'approval reason is required' using errcode='22023';
  end if;
  select accrual.* into v_row
    from public.consultant_commission_accruals accrual
    join public.platform_consultants consultant
      on consultant.id=accrual.consultant_id
   where accrual.id=p_accrual and accrual.status='accrued'
     and consultant.active and consultant.departed_at is null
     and now()>=accrual.eligible_at
     and (
       accrual.commission_phase<>'anniversary_bonus'
       or app.consultant_anniversary_qualified_v78(
         accrual.business_id,accrual.eligible_at
       )
     )
   for update of accrual;
  if not found then
    raise exception 'active and payable accrued commission was not found'
      using errcode='22023';
  end if;
  update public.consultant_commission_accruals
     set status='approved',approved_by=v_actor,approved_at=now()
   where id=p_accrual returning * into v_row;
  insert into public.audit_log(
    business_id,actor,action,entity,entity_id,detail
  ) values (
    v_row.business_id,v_actor,'CONSULTANT_COMMISSION_APPROVED_V78',
    'consultant_commission_accruals',v_row.id,
    jsonb_build_object('commission_cents',v_row.commission_cents,'reason',btrim(p_reason))
  );
  return to_jsonb(v_row);
end
$$;

--
-- Name: approve_consultant_payout_batch_v78(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_consultant_payout_batch_v78(p_batch uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_row public.consultant_payout_batches%rowtype;
begin
  if auth.uid() is null or not app.v89_platform_can('commissions','rw') then
    raise exception 'super-admin access is required' using errcode='42501';
  end if;
  select * into v_row from public.consultant_payout_batches
   where id=p_batch and status='draft' for update;
  if not found or not exists(
    select 1 from public.consultant_payout_lines where batch_id=p_batch
  ) then
    raise exception 'non-empty draft payout batch was not found' using errcode='22023';
  end if;
  if exists(
    select 1
      from public.consultant_payout_lines line
      join public.platform_consultants consultant on consultant.id=line.consultant_id
     where line.batch_id=p_batch
       and (not consultant.active or consultant.departed_at is not null)
  ) then
    raise exception 'departed consultant cannot enter an approved payout'
      using errcode='22023';
  end if;
  update public.consultant_payout_batches
     set status='approved',approved_by=auth.uid(),approved_at=now()
   where id=p_batch returning * into v_row;
  return to_jsonb(v_row);
end
$$;

--
-- Name: approve_customer_identity_correction_v111(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_customer_identity_correction_v111(p_proposal uuid, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid:=auth.uid();
  v_proposal public.customer_identity_proposals_v111%rowtype;
  v_active_members integer:=0;
begin
  if v_actor is null then
    raise exception 'authentication required' using errcode='42501';
  end if;
  select * into v_proposal
    from public.customer_identity_proposals_v111 proposal
   where proposal.id=p_proposal;
  if not found then
    raise exception 'identity proposal not found' using errcode='23503';
  end if;
  if not app.v111_can_decide(v_proposal.business_id) then
    raise exception 'owner or global business authority is required to approve'
      using errcode='42501';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(
    'growth-v108-membership:'||v_proposal.business_id::text,0
  ));
  if v_proposal.status<>'approved' then
    select count(*) into v_active_members
      from public.growth_execution_members_v108 member
      join public.growth_executions_v108 execution
        on execution.id=member.execution_id
       and execution.business_id=member.business_id
     where member.business_id=v_proposal.business_id
       and execution.status='running'
       and execution.ends_at>statement_timestamp()
       and app.v113_effective_client_id(
             member.business_id,member.client_id
           ) in (
             app.v113_effective_client_id(
               v_proposal.business_id,v_proposal.source_client_id
             ),
             app.v113_effective_client_id(
               v_proposal.business_id,v_proposal.target_client_id
             )
           );
    if v_active_members>1 then
      raise exception
        'identity correction would overlap active customer experiments'
        using errcode='23P01';
    end if;
  end if;
  return public.approve_customer_identity_correction_v111_v113_inner(
    p_proposal,p_idempotency_key
  );
end
$$;

--
-- Name: approve_customer_identity_correction_v111_v113_inner(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_customer_identity_correction_v111_v113_inner(p_proposal uuid, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid:=auth.uid();
  v_proposal public.customer_identity_proposals_v111%rowtype;
  v_proof public.customer_identity_proofs_v111%rowtype;
  v_payload jsonb:=jsonb_build_object('operation','approve','proposal_id',p_proposal);
  v_hash text:=app.v111_request_hash(v_payload);
  v_existing public.customer_identity_request_ledger_v111%rowtype;
  v_decision uuid;
  v_event uuid;
  v_before jsonb;
  v_after jsonb;
  v_receipt jsonb;
begin
  if v_actor is null then raise exception 'authentication required' using errcode='42501'; end if;
  if p_idempotency_key is null then
    raise exception 'idempotency key is required' using errcode='22023';
  end if;
  select * into v_proposal from public.customer_identity_proposals_v111
   where id=p_proposal;
  if not found then raise exception 'identity proposal not found' using errcode='23503'; end if;
  if not app.v111_can_decide(v_proposal.business_id) then
    raise exception 'owner or global business authority is required to approve'
      using errcode='42501';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(
    'v111:request:'||v_actor||':'||p_idempotency_key,0
  ));
  select * into v_existing from public.customer_identity_request_ledger_v111
   where actor_auth_user_id=v_actor and idempotency_key=p_idempotency_key;
  if found then
    if v_existing.operation<>'approve' or v_existing.request_hash<>v_hash then
      raise exception 'idempotency key was already used for a different identity mutation'
        using errcode='23505';
    end if;
    return v_existing.receipt;
  end if;
  select * into v_proposal from public.customer_identity_proposals_v111
   where id=p_proposal for update;
  if not found then raise exception 'identity proposal not found' using errcode='23503'; end if;
  perform pg_advisory_xact_lock(hashtextextended(
    'v111:client:'||v_proposal.business_id||':'||
    least(v_proposal.source_client_id::text,v_proposal.target_client_id::text),0
  ));
  perform pg_advisory_xact_lock(hashtextextended(
    'v111:client:'||v_proposal.business_id||':'||
    greatest(v_proposal.source_client_id::text,v_proposal.target_client_id::text),0
  ));
  if v_proposal.status='approved' then
    select id into v_decision from public.customer_identity_decisions_v111
     where proposal_id=p_proposal and decision_type='approve';
    v_receipt:=jsonb_build_object('status','approved','proposal_id',p_proposal,'decision_id',v_decision);
  elsif v_proposal.status in ('rejected','reversed') then
    raise exception 'identity proposal already has a conflicting terminal decision'
      using errcode='55000';
  else
    select * into v_proof from public.customer_identity_proofs_v111 proof
     where proof.proposal_id=p_proposal and proof.business_id=v_proposal.business_id
     order by proof.validated_at desc,proof.id desc limit 1;
    if not found then raise exception 'validated proof is required before approval' using errcode='42501'; end if;
    if exists (
      select 1
        from public.customer_links source_link
       where source_link.business_id=v_proposal.business_id
         and source_link.client_id=v_proposal.source_client_id
         and source_link.state='verified'
    ) then
      raise exception 'source customer gained a verified identity after proof; approval requires fresh unambiguous evidence'
        using errcode='42501';
    end if;
    if v_proof.proof_kind='verified_contact_pair' then
      perform app.v111_validate_contact_pair(
        p_proposal,v_proof.evidence_metadata->>'contact_type',v_proof.evidence_subject
      );
    else
      perform app.v111_validate_invitation(p_proposal,(v_proof.evidence_metadata->>'invitation_id')::uuid);
    end if;
    if exists (
      select 1 from public.customer_identity_current_attribution_v111 current
       where current.business_id=v_proposal.business_id
         and current.effective_client_id<>current.source_client_id
         and (
           current.source_client_id in (
             v_proposal.source_client_id,v_proposal.target_client_id
           )
           or current.effective_client_id in (
             v_proposal.source_client_id,v_proposal.target_client_id
           )
         )
    ) then
      raise exception 'source or target already participates in an active identity correction'
        using errcode='55000';
    end if;
    v_before:=app.v111_attribution_snapshot(
      v_proposal.business_id,v_proposal.source_client_id,
      v_proposal.target_client_id,v_proposal.source_client_id
    );
    v_after:=app.v111_attribution_snapshot(
      v_proposal.business_id,v_proposal.source_client_id,
      v_proposal.target_client_id,v_proposal.target_client_id
    );
    v_decision:=gen_random_uuid();
    insert into public.customer_identity_decisions_v111(
      id,proposal_id,business_id,decision_type,proof_id,
      before_client_id,after_client_id,before_attribution,after_attribution,
      decided_by
    ) values (
      v_decision,p_proposal,v_proposal.business_id,'approve',v_proof.id,
      v_proposal.source_client_id,v_proposal.target_client_id,v_before,v_after,
      v_actor
    );
    v_event:=gen_random_uuid();
    insert into public.customer_identity_attribution_events_v111(
      id,proposal_id,decision_id,business_id,source_client_id,
      before_client_id,after_client_id,event_type,actor_auth_user_id
    ) values (
      v_event,p_proposal,v_decision,v_proposal.business_id,
      v_proposal.source_client_id,v_proposal.source_client_id,
      v_proposal.target_client_id,'correction_approved',v_actor
    );
    update public.customer_identity_proposals_v111
       set status='approved',decided_at=statement_timestamp(),
           updated_at=statement_timestamp()
     where id=p_proposal;
    v_receipt:=jsonb_build_object(
      'status','approved','proposal_id',p_proposal,'decision_id',v_decision,
      'attribution_event_id',v_event,'source_client_id',v_proposal.source_client_id,
      'effective_client_id',v_proposal.target_client_id
    );
  end if;
  insert into public.customer_identity_request_ledger_v111(
    actor_auth_user_id,business_id,operation,idempotency_key,request_hash,receipt
  ) values(v_actor,v_proposal.business_id,'approve',p_idempotency_key,v_hash,v_receipt);
  return v_receipt;
end
$$;

--
-- Name: approve_growth_recommendation_v108(uuid, uuid, integer, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_growth_recommendation_v108(p_business uuid, p_recommendation uuid, p_offer_value_cents integer, p_offer_label text, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_identity text;
  v_hash text;
  v_receipt jsonb;
  v_branch uuid;
begin
  if not app.is_salon_owner(p_business) then
    raise exception 'owner only' using errcode = '42501';
  end if;
  select r.branch_id into v_branch
  from public.growth_recommendations_v108 r
  where r.id = p_recommendation and r.business_id = p_business;
  if not found then
    raise exception 'recommendation not found';
  end if;
  if not app.can_see_branch(p_business, v_branch) then
    raise exception 'recommendation branch is outside actor scope'
      using errcode = '42501';
  end if;
  if not app.platform_feature_enabled('growth_closed_loop_v108')
     or not app.can_module_read(p_business, 'retention') then
    raise exception 'growth feature or retention entitlement is no longer enabled'
      using errcode = '42501';
  end if;
  v_identity := app.v112_hash(jsonb_build_object(
    'operation', 'approve_growth_recommendation_v108',
    'business_id', p_business, 'actor', v_actor,
    'idempotency_key', p_idempotency_key
  ));
  v_hash := app.v112_hash(jsonb_build_object(
    'business_id', p_business,
    'recommendation_id', p_recommendation,
    'offer_value_cents', p_offer_value_cents,
    'offer_label', btrim(p_offer_label)
  ));
  perform app.v112_lock_pair(
    'v112-v108-approve-request:' || v_identity,
    'v112-v108-recommendation:' || p_recommendation::text
  );
  v_receipt := app.v112_get_receipt(v_identity, v_hash);
  if v_receipt is not null then
    return v_receipt;
  end if;
  v_receipt := public.approve_growth_recommendation_v108_v112_inner(
    p_business, p_recommendation, p_offer_value_cents, p_offer_label,
    p_idempotency_key
  );
  return app.v112_put_receipt(
    v_identity, 'approve_growth_recommendation_v108', v_hash,
    jsonb_build_object(
      'business_id', p_business, 'recommendation_id', p_recommendation,
      'actor', v_actor
    ),
    v_receipt
  );
end $$;

--
-- Name: approve_growth_recommendation_v108_v112_inner(uuid, uuid, integer, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_growth_recommendation_v108_v112_inner(p_business uuid, p_recommendation uuid, p_offer_value_cents integer, p_offer_label text, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_rec public.growth_recommendations_v108%rowtype;
  v_policy public.growth_policies_v108%rowtype;
  v_execution uuid := gen_random_uuid();
  v_existing public.growth_executions_v108%rowtype;
  v_holdout integer;
  v_queued integer := 0;
  v_scheduled integer := 0;
  v_heldout integer := 0;
  v_suppressed integer := 0;
  v_spend bigint := 0;
  v_request_hash text;
  v_currency text;
  v_offer_timezone text;
  v_offer_expires_at timestamptz;
  v_template_title text;
  v_template_lead text;
  v_governed_copy jsonb;
  v_ends_at timestamptz;
  v_effective_policy jsonb;
begin
  if not app.is_salon_owner(p_business) then
    raise exception 'owner only' using errcode = '42501';
  end if;
  if p_offer_value_cents is null then
    raise exception 'offer value is required' using errcode = '22023';
  end if;
  if p_offer_label is null
     or p_offer_label not in (
       'welcome_back', 'member_thank_you', 'simple_saving'
     ) then
    raise exception 'offer template must be welcome_back, member_thank_you, or simple_saving'
      using errcode = '22023';
  end if;
  v_request_hash := encode(extensions.digest(convert_to(jsonb_build_object(
    'business_id', p_business,
    'recommendation_id', p_recommendation,
    'offer_value_cents', p_offer_value_cents,
    'offer_label', btrim(p_offer_label)
  )::text, 'UTF8'), 'sha256'), 'hex');

  select * into v_existing from public.growth_executions_v108
  where business_id = p_business and approved_by = v_actor
    and idempotency_key = p_idempotency_key;
  if found then
    if v_existing.request_hash <> v_request_hash then
      raise exception 'idempotency key reused with a different approval request'
        using errcode = '23505';
    end if;
    return jsonb_build_object('execution_id', v_existing.id, 'replayed', true);
  end if;

  perform pg_advisory_xact_lock(hashtextextended(
    'growth-v108-membership:' || p_business::text, 0
  ));
  perform pg_advisory_xact_lock(hashtextextended(
    'growth-v108-approve:' || p_recommendation::text, 0
  ));
  select * into v_rec from public.growth_recommendations_v108
  where id = p_recommendation and business_id = p_business for update;
  if not found then raise exception 'recommendation not found'; end if;
  select * into v_policy from public.growth_policies_v108 where business_id = p_business;
  v_effective_policy := app.growth_v108_effective_parameters(p_business);
  if not app.can_see_branch(v_rec.business_id, v_rec.branch_id) then
    raise exception 'recommendation branch is outside actor scope' using errcode = '42501';
  end if;
  if not app.platform_feature_enabled('growth_closed_loop_v108')
     or not app.can_module_read(p_business, 'retention') then
    raise exception 'growth feature or retention entitlement is no longer enabled'
      using errcode = '42501';
  end if;
  if v_policy.enabled is distinct from true
     or v_rec.policy_version <> v_policy.policy_version
     -- Source availability is timestamped observation evidence.  It is kept on
     -- the recommendation for audit, but its moving `as_of` value is not policy
     -- configuration and must not make the next approval statement stale.
     or (
       (v_rec.data_coverage -> 'effective_policy') - 'source_availability'
     ) is distinct from (
       v_effective_policy - 'source_availability'
     ) then
    raise exception 'recommendation policy is disabled or stale'
      using errcode = '42501';
  end if;
  if v_rec.status <> 'presented' or v_rec.valid_until <= statement_timestamp() then
    raise exception 'recommendation is no longer executable' using errcode = '42501';
  end if;
  if p_offer_value_cents not between 100 and v_policy.maximum_credit_cents then
    raise exception 'offer exceeds configured economic guardrail' using errcode = '22023';
  end if;

  v_holdout := greatest(v_policy.minimum_arm_size,
    floor(v_rec.audience_size * v_rec.holdout_percent / 100.0)::integer);
  if v_rec.audience_size - v_holdout < v_policy.minimum_arm_size then
    raise exception 'audience is too small for a valid measured execution'
      using errcode = '22023';
  end if;
  if exists (
    select 1
    from public.growth_recommendation_members_v108 candidate
    join public.growth_execution_members_v108 active_member
      on active_member.business_id = candidate.business_id
     and active_member.client_id = candidate.client_id
    join public.growth_executions_v108 active_execution
      on active_execution.id = active_member.execution_id
     and active_execution.business_id = active_member.business_id
    where candidate.recommendation_id = v_rec.id
      and candidate.business_id = p_business
      and candidate.eligible
      and active_execution.status = 'running'
      and active_execution.ends_at > statement_timestamp()
  ) then
    raise exception 'recommendation overlaps an active customer experiment'
      using errcode = '23P01';
  end if;
  select upper(currency) into strict v_currency
  from public.businesses where id = p_business;
  select reporting.timezone into strict v_offer_timezone
  from app.v106_reporting_contract(
    -- Reporting-contract rows are appended with clock_timestamp().  Use the
    -- same clock here so a newly onboarded firm can approve its first
    -- recommendation in the transaction that creates its branch.
    p_business, v_rec.branch_id, clock_timestamp()
  ) reporting;
  v_ends_at := statement_timestamp()
    + make_interval(days => v_rec.attribution_window_days);
  v_offer_expires_at := least(
    statement_timestamp() + interval '7 days', v_ends_at
  );
  select template.title, template.lead
  into strict v_template_title, v_template_lead
  from (values
    (
      'welcome_back'::text,
      'A welcome-back thank-you is waiting'::text,
      'We would love to welcome you back.'::text
    ),
    (
      'member_thank_you',
      'A member thank-you is waiting',
      'Thank you for being part of our community.'
    ),
    (
      'simple_saving',
      'A saving is ready for you',
      'Enjoy a little saving on your next eligible visit.'
    )
  ) template(template_id, title, lead)
  where template.template_id = p_offer_label;
  v_governed_copy := jsonb_build_object(
    'schema', 'nestly.growth_offer_copy',
    'version', 1,
    'title', v_template_title,
    'body', concat(
      v_template_lead, ' Enjoy ', v_currency, ' ',
      to_char(p_offer_value_cents / 100.0, 'FM999999990.00'),
      ' in credit before ',
      to_char(v_offer_expires_at at time zone v_offer_timezone, 'DD Mon YYYY'),
      ' (', v_offer_timezone, ').'
    ),
    'cta_label', 'Redeem now',
    'cta_destination', 'customer_growth_offer_qr',
    'eligibility', jsonb_build_object(
      'business_id', p_business,
      'branch_id', v_rec.branch_id,
      'recommendation_id', v_rec.id,
      'eligible_member_snapshot', true,
      'verified_customer_link_required', true,
      'marketing_consent_required', true,
      'one_active_experiment_per_customer', true
    ),
    'conditions', jsonb_build_object(
      'single_use', true,
      'qualifying_completed_sale_required', true,
      'sale_after_issuance_required', true,
      'exact_branch_when_scoped', true,
      'expires_at', v_offer_expires_at,
      'timezone', v_offer_timezone
    ),
    'locked_facts', jsonb_build_object(
      'template_id', p_offer_label,
      'offer_value_cents', p_offer_value_cents,
      'currency', v_currency,
      'expires_at', v_offer_expires_at,
      'timezone', v_offer_timezone,
      'branch_id', v_rec.branch_id,
      'recommendation_id', v_rec.id,
      'cta_label', 'Redeem now',
      'cta_destination', 'customer_growth_offer_qr'
    )
  );

  insert into public.growth_executions_v108(
    id, recommendation_id, business_id, branch_id, channel, offer_type,
    offer_value_cents, offer_label, currency, offer_timezone,
    offer_expires_at, governed_copy,
    budget_cap_cents, holdout_percent,
    attribution_window_days, minimum_arm_size, approved_by, ends_at, idempotency_key,
    request_hash
  ) values (
    v_execution, v_rec.id, p_business, v_rec.branch_id, 'in_app', 'credit_cents',
    p_offer_value_cents, p_offer_label, v_currency, v_offer_timezone,
    v_offer_expires_at, v_governed_copy,
    (v_rec.audience_size - v_holdout) * p_offer_value_cents,
    v_rec.holdout_percent, v_rec.attribution_window_days,
    v_policy.minimum_arm_size, v_actor,
    v_ends_at, p_idempotency_key, v_request_hash
  );

  insert into public.growth_execution_members_v108(
    execution_id, business_id, recommendation_member_id, client_id,
    assignment, assignment_rank, assignment_score
  )
  select v_execution, p_business, ranked.id, ranked.client_id,
    case when ranked.assignment_rank <= v_holdout then 'holdout' else 'treatment' end,
    ranked.assignment_rank, ranked.assignment_score
  from (
    select m.id, m.client_id,
      encode(extensions.digest(convert_to(
        v_execution::text || ':' || m.client_id::text, 'UTF8'
      ), 'sha256'), 'hex') as assignment_score,
      row_number() over (order by
        encode(extensions.digest(convert_to(
          v_execution::text || ':' || m.client_id::text, 'UTF8'
        ), 'sha256'), 'hex'),
        m.client_id
      )::integer as assignment_rank
    from public.growth_recommendation_members_v108 m
    where m.recommendation_id = v_rec.id and m.business_id = p_business and m.eligible
  ) ranked;

  insert into public.growth_deliveries_v108(
    execution_id, execution_member_id, business_id, client_id,
    identity_id, link_id, assignment, channel, delivery_status,
    suppression_reason, title, body, estimated_cost_cents, delivered_at
  )
  select v_execution, em.id, p_business, em.client_id,
    link.identity_id, link.id, em.assignment, 'in_app',
    case
      when em.assignment = 'holdout' then 'held_out'
      when link.id is null then 'suppressed'
      when pref.opted_in is distinct from true then 'suppressed'
      when delivery_gate.in_quiet_hours then 'suppressed'
      when delivery_gate.frequency_capped then 'suppressed'
      else 'delivered'
    end,
    case
      when em.assignment = 'holdout' then 'holdout'
      when link.id is null then 'link_unavailable'
      when pref.opted_in is distinct from true then 'consent_withdrawn'
      when delivery_gate.in_quiet_hours then 'quiet_hours'
      when delivery_gate.frequency_capped then 'frequency_cap'
      else null
    end,
    case when delivery_gate.can_deliver
      then v_governed_copy ->> 'title' else null end,
    case when delivery_gate.can_deliver
      then v_governed_copy ->> 'body' else null end,
    case when delivery_gate.can_deliver
      then p_offer_value_cents else 0 end,
    case when delivery_gate.can_deliver
      then statement_timestamp() else null end
  from public.growth_execution_members_v108 em
  left join lateral (
    select l.* from public.customer_links l
    where l.business_id = p_business and l.client_id = em.client_id and l.state = 'verified'
    order by l.verified_at desc, l.id limit 1
  ) link on true
  left join lateral (
    select p.* from public.customer_notification_preferences p
    where p.business_id = p_business and p.client_id = em.client_id
      and p.link_id = link.id and p.channel = 'in_app' and p.topic = 'marketing'
    order by p.updated_at desc, p.id limit 1
  ) pref on true
  cross join lateral (
    select
      app.c46_in_quiet_hours(
        pref.quiet_hours_timezone, pref.quiet_hours_start,
        pref.quiet_hours_end, statement_timestamp()
      ) as in_quiet_hours,
      exists (
        select 1 from public.growth_deliveries_v108 prior
        where prior.business_id = p_business and prior.client_id = em.client_id
          and prior.delivery_status = 'delivered'
          and prior.delivered_at >= statement_timestamp()
            - make_interval(days => v_policy.frequency_cap_days)
      ) as frequency_capped
  ) delivery_state
  cross join lateral (
    select (
      em.assignment = 'treatment'
      and link.id is not null
      and pref.opted_in is true
      and not delivery_state.in_quiet_hours
      and not delivery_state.frequency_capped
    ) as can_deliver,
    delivery_state.in_quiet_hours,
    delivery_state.frequency_capped
  ) delivery_gate
  where em.execution_id = v_execution;

  insert into public.growth_entitlements_v108(
    delivery_id, execution_id, business_id, client_id, identity_id,
    entitlement_type, value_cents, estimated_cost_cents, expires_at
  )
  select d.id, v_execution, p_business, d.client_id, d.identity_id,
    'credit_cents', p_offer_value_cents, p_offer_value_cents,
    v_offer_expires_at
  from public.growth_deliveries_v108 d
  where d.execution_id = v_execution and d.delivery_status = 'delivered';

  insert into public.growth_entitlement_events_v108(
    entitlement_id, business_id, event_type, actor, idempotency_key, detail
  )
  select e.id, p_business, 'issued', v_actor,
    extensions.uuid_generate_v5(p_idempotency_key, e.id::text),
    jsonb_build_object('execution_id', v_execution, 'value_cents', e.value_cents)
  from public.growth_entitlements_v108 e where e.execution_id = v_execution;

  select
    count(*) filter (where delivery_status = 'queued'),
    count(*) filter (where delivery_status = 'scheduled'),
    count(*) filter (where delivery_status = 'held_out'),
    count(*) filter (where delivery_status = 'suppressed'),
    coalesce(sum(estimated_cost_cents) filter (
      where delivery_status in ('queued', 'scheduled')
    ), 0)
  into v_queued, v_scheduled, v_heldout, v_suppressed, v_spend
  from public.growth_deliveries_v108 where execution_id = v_execution;

  update public.growth_recommendations_v108 set status = 'executed'
  where id = v_rec.id and business_id = p_business;
  insert into public.growth_recommendation_decisions_v108(
    recommendation_id, business_id, decision, actor, idempotency_key, request_hash
  ) values (
    v_rec.id, p_business, 'accepted', v_actor, p_idempotency_key, v_request_hash
  );
  insert into public.audit_log(business_id, actor, action, entity, entity_id, detail)
  values (p_business, v_actor, 'APPROVE_GROWTH_RECOMMENDATION_V108',
    'growth_executions_v108', v_execution,
    jsonb_build_object(
      'queued', v_queued,
      'scheduled', v_scheduled,
      'held_out', v_heldout,
      'suppressed', v_suppressed,
      'estimated_cost_cents', v_spend
    ));

  return jsonb_build_object(
    'execution_id', v_execution,
    'recommendation_id', v_rec.id,
    'delivery', jsonb_build_object(
      'queued', v_queued,
      'scheduled', v_scheduled,
      'held_out', v_heldout,
      'suppressed', v_suppressed
    ),
    'estimated_cost_cents', v_spend,
    'currency', v_currency,
    'governed_copy', v_governed_copy,
    'measurement', jsonb_build_object(
      'method', 'randomized_intent_to_treat_holdout',
      'status', 'running',
      'ends_at', statement_timestamp() + make_interval(days => v_rec.attribution_window_days)
    ),
    'replayed', false
  );
end $$;

--
-- Name: assert_promotion_redeemable_at_branch_v155(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assert_promotion_redeemable_at_branch_v155(p_business uuid, p_promotion uuid, p_branch uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_content public.business_customer_content_v95%rowtype;
begin
  if auth.uid() is null or not app.has_perm(p_business,'create_sales') then
    raise exception 'sales access required' using errcode='42501';
  end if;
  if p_branch is null or not app.can_see_branch(p_business,p_branch) then
    raise exception 'unauthorised_branch_scope' using errcode='42501';
  end if;
  select * into v_content
  from public.business_customer_content_v95 content
  where content.id = p_promotion
    and content.business_id = p_business
    and content.content_type = 'offer'
  for share;
  if not found
     or not v_content.active
     or (v_content.starts_at is not null and v_content.starts_at > now())
     or v_content.ends_at <= now() then
    raise exception 'promotion_not_available' using errcode='22023';
  end if;
  if not app.promotion_available_at_branch_v155(p_promotion,p_branch) then
    raise exception 'This promotion is not available at the selected branch.'
      using errcode='42501';
  end if;
  return jsonb_build_object(
    'status','ok',
    'promotion_id',p_promotion,
    'business_id',p_business,
    'branch_id',p_branch
  );
end
$$;

--
-- Name: attach_customer_identity_proof_v111(uuid, text, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.attach_customer_identity_proof_v111(p_proposal uuid, p_proof_kind text, p_evidence jsonb, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid:=auth.uid();
  v_proposal public.customer_identity_proposals_v111%rowtype;
  v_payload jsonb;
  v_hash text;
  v_existing public.customer_identity_request_ledger_v111%rowtype;
  v_metadata jsonb;
  v_subject text;
  v_contact_type text;
  v_fingerprint text;
  v_proof uuid;
  v_receipt jsonb;
begin
  if v_actor is null then raise exception 'authentication required' using errcode='42501'; end if;
  if p_idempotency_key is null then
    raise exception 'idempotency key is required' using errcode='22023';
  end if;
  select * into v_proposal from public.customer_identity_proposals_v111
   where id=p_proposal;
  if not found then raise exception 'identity proposal not found' using errcode='23503'; end if;
  if not app.v111_can_propose(v_proposal.business_id,v_proposal.branch_id) then
    raise exception 'proof is outside actor business or branch scope' using errcode='42501';
  end if;
  p_proof_kind:=lower(nullif(btrim(p_proof_kind),''));
  if p_proof_kind='verified_contact_pair' then
    v_contact_type:=lower(nullif(btrim(p_evidence->>'contact_type'),''));
    v_subject:=app.v111_normalize_contact(
      v_contact_type,p_evidence->>'contact_value'
    );
    v_payload:=jsonb_build_object(
      'operation','attach_proof','proposal_id',p_proposal,
      'proof_kind',p_proof_kind,'contact_type',v_contact_type,
      'contact_value',v_subject
    );
  elsif p_proof_kind='firm_invitation' then
    v_subject:=nullif(p_evidence->>'invitation_id','');
    if v_subject is null then raise exception 'invitation_id is required' using errcode='22023'; end if;
    v_payload:=jsonb_build_object(
      'operation','attach_proof','proposal_id',p_proposal,
      'proof_kind',p_proof_kind,'invitation_id',v_subject
    );
  else
    raise exception 'unsupported proof kind' using errcode='22023';
  end if;
  v_hash:=app.v111_request_hash(v_payload);
  perform pg_advisory_xact_lock(hashtextextended(
    'v111:request:'||v_actor||':'||p_idempotency_key,0
  ));
  select * into v_existing from public.customer_identity_request_ledger_v111
   where actor_auth_user_id=v_actor and idempotency_key=p_idempotency_key;
  if found then
    if v_existing.operation<>'attach_proof' or v_existing.request_hash<>v_hash then
      raise exception 'idempotency key was already used for a different identity mutation'
        using errcode='23505';
    end if;
    return v_existing.receipt;
  end if;
  select * into v_proposal from public.customer_identity_proposals_v111
   where id=p_proposal for update;
  if not found then raise exception 'identity proposal not found' using errcode='23503'; end if;
  if v_proposal.status not in ('proposed','proof_attached') then
    raise exception 'proof cannot be attached after a terminal decision' using errcode='55000';
  end if;
  if p_proof_kind='verified_contact_pair' then
    v_metadata:=app.v111_validate_contact_pair(
      p_proposal,v_contact_type,v_subject
    );
  else
    v_metadata:=app.v111_validate_invitation(p_proposal,v_subject::uuid);
  end if;
  v_fingerprint:=app.v111_request_hash(jsonb_build_object(
    'proposal_id',p_proposal,'proof_kind',p_proof_kind,'subject',v_subject
  ));
  select proof.id into v_proof from public.customer_identity_proofs_v111 proof
   where proof.proposal_id=p_proposal and proof.business_id=v_proposal.business_id
     and proof.proof_fingerprint=v_fingerprint;
  if v_proof is null then
    v_proof:=gen_random_uuid();
    insert into public.customer_identity_proofs_v111(
      id,proposal_id,business_id,proof_kind,evidence_subject,
      evidence_subject_hash,evidence_metadata,proof_fingerprint,validated_by
    ) values (
      v_proof,p_proposal,v_proposal.business_id,p_proof_kind,v_subject,
      app.v111_request_hash(jsonb_build_object('subject',v_subject)),
      v_metadata,v_fingerprint,v_actor
    );
  end if;
  if v_proposal.status='proposed' then
    update public.customer_identity_proposals_v111
       set status='proof_attached',proof_attached_at=statement_timestamp(),
           updated_at=statement_timestamp()
     where id=p_proposal;
  end if;
  v_receipt:=jsonb_build_object(
    'status','proof_attached','proposal_id',p_proposal,'proof_id',v_proof,
    'proof_kind',p_proof_kind
  );
  insert into public.customer_identity_request_ledger_v111(
    actor_auth_user_id,business_id,operation,idempotency_key,request_hash,receipt
  ) values(v_actor,v_proposal.business_id,'attach_proof',p_idempotency_key,v_hash,v_receipt);
  return v_receipt;
end
$$;

--
-- Name: attach_pos_paynow_intent_v142(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.attach_pos_paynow_intent_v142(p_attempt uuid, p_account_id text, p_payment_intent_id text, p_provider_status text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_attempt public.pos_payment_attempts_v142%rowtype;
begin
  perform app.v142_service_guard();
  select * into v_attempt from public.pos_payment_attempts_v142 where id=p_attempt for update;
  if not found or v_attempt.provider_account_id is distinct from p_account_id then
    raise exception 'payment attempt account mismatch' using errcode='42501';
  end if;
  if v_attempt.provider_payment_intent_id is not null
     and v_attempt.provider_payment_intent_id is distinct from p_payment_intent_id then
    raise exception 'payment attempt is already bound to another provider intent' using errcode='23505';
  end if;
  update public.pos_payment_attempts_v142 set
    provider_payment_intent_id=p_payment_intent_id,
    status=case p_provider_status when 'processing' then 'processing'
      when 'succeeded' then status when 'canceled' then 'canceled'
      when 'requires_payment_method' then 'prepared'
      when 'requires_confirmation' then 'prepared' else 'awaiting_payment' end,
    updated_at=now()
  where id=p_attempt;
  return jsonb_build_object('status','bound','attempt_id',p_attempt);
end $$;

--
-- Name: attest_campaign_exposure_v99(uuid, uuid, uuid, text, boolean, text, timestamp with time zone, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.attest_campaign_exposure_v99(p_business uuid, p_campaign uuid, p_campaign_grant uuid, p_channel text, p_confirmed boolean, p_idempotency_key text, p_exposed_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_evidence_context jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid:=auth.uid();
  v_existing public.retention_campaign_exposures_v99%rowtype;
  v_result jsonb;
  v_exposed_at timestamptz;
begin
  if v_actor is null
     or not app.is_salon_owner(p_business)
     or not app.can_module_write(p_business,'retention') then
    raise exception 'active owner retention write authorization is required'
      using errcode='42501';
  end if;
  if p_confirmed is distinct from true then
    raise exception
      'manual exposure must be explicitly confirmed after the offer is shown or sent'
      using errcode='22023';
  end if;

  -- A transport replay may omit the original server-stamped timestamp. Every
  -- caller-authored evidence field, including the privacy-safe context, must
  -- still match the immutable first attestation exactly.
  select exposure.* into v_existing
  from public.retention_campaign_exposures_v99 exposure
  where exposure.business_id=p_business
    and exposure.idempotency_key=btrim(coalesce(p_idempotency_key,''));
  if found then
    if v_existing.campaign_id<>p_campaign
       or v_existing.campaign_grant_id<>p_campaign_grant
       or v_existing.channel<>p_channel
       or (
         p_exposed_at is not null
         and v_existing.exposed_at is distinct from p_exposed_at
       )
       or v_existing.evidence_context
            is distinct from coalesce(p_evidence_context,'{}'::jsonb) then
      raise exception
        'idempotency key conflicts with another manual exposure attestation'
        using errcode='23505';
    end if;
    return pg_catalog.jsonb_build_object(
      'exposure_id',v_existing.id,
      'campaign_id',v_existing.campaign_id,
      'campaign_grant_id',v_existing.campaign_grant_id,
      'client_id',v_existing.client_id,
      'exposure_status','verified',
      'attestation_kind','merchant_manual_confirmation',
      'attested',true,
      'delivery_provider_status','not_configured',
      'replayed',true
    );
  end if;

  -- The immutable campaign-grant identity is also a replay anchor. This makes
  -- modal/page reload recovery safe even when the browser did not persist the
  -- first attestation key or timestamp.
  select exposure.* into v_existing
  from public.retention_campaign_exposures_v99 exposure
  where exposure.business_id=p_business
    and exposure.campaign_id=p_campaign
    and exposure.campaign_grant_id=p_campaign_grant;
  if found then
    if v_existing.channel<>p_channel
       or (
         p_exposed_at is not null
         and v_existing.exposed_at is distinct from p_exposed_at
       )
       or v_existing.evidence_context
            is distinct from coalesce(p_evidence_context,'{}'::jsonb) then
      raise exception
        'campaign grant already has different manual exposure evidence'
        using errcode='23505';
    end if;
    return pg_catalog.jsonb_build_object(
      'exposure_id',v_existing.id,
      'campaign_id',v_existing.campaign_id,
      'campaign_grant_id',v_existing.campaign_grant_id,
      'client_id',v_existing.client_id,
      'exposure_status','verified',
      'attestation_kind','merchant_manual_confirmation',
      'attested',true,
      'delivery_provider_status','not_configured',
      'replayed',true
    );
  end if;

  v_exposed_at:=coalesce(p_exposed_at,clock_timestamp());
  v_result:=public.record_campaign_exposure_v99(
    p_business,
    p_campaign,
    p_campaign_grant,
    p_channel,
    p_idempotency_key,
    v_exposed_at,
    null,
    p_evidence_context
  );
  return v_result||pg_catalog.jsonb_build_object(
    'campaign_grant_id',p_campaign_grant,
    'attestation_kind','merchant_manual_confirmation',
    'attested',true
  );
end
$$;

--
-- Name: attribute_consultant_v78(uuid, uuid, uuid, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.attribute_consultant_v78(p_consultant uuid, p_prospect uuid, p_business uuid, p_onboarding_started_at timestamp with time zone, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if auth.uid() is null or not app.v89_platform_can('commissions','rw') then
    raise exception 'super-admin access is required' using errcode='42501';
  end if;
  return app.attribute_consultant_core_v78(
    p_consultant,p_prospect,p_business,p_onboarding_started_at,p_reason,auth.uid()
  );
end
$$;

--
-- Name: bar_client_keep_days_v278(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bar_client_keep_days_v278(p_business uuid, p_client uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  perform app.require_bar_business_v275(p_business);
  perform app.require_bar_staff_v275(p_business, false);
  if p_client is null then
    raise exception 'choose a customer' using errcode = '22023';
  end if;
  if not exists (select 1 from public.clients client
                  where client.id = p_client and client.business_id = p_business) then
    raise exception 'customer not found' using errcode = '22023';
  end if;
  return jsonb_build_object(
    'status', 'ok',
    'keep_days', app.bar_keep_days_for_client_v278(p_business, p_client),
    'default_keep_days', app.bar_keep_days_v275(p_business),
    'tier_name', app.bar_tier_name_v278(p_business, p_client));
end;
$$;

--
-- Name: bar_get_bottle_setup_v278(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bar_get_bottle_setup_v278(p_business uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_tiers jsonb;
  v_products jsonb;
begin
  perform app.require_bar_business_v275(p_business);
  perform app.require_bar_staff_v275(p_business, false);

  select coalesce(jsonb_agg(jsonb_build_object(
           'tier_id', tier.id,
           'name', tier.name,
           'threshold', tier.threshold,
           'keep_days', keep.keep_days
         ) order by tier.threshold, tier.sort, tier.id), '[]'::jsonb)
    into v_tiers
    from public.loyalty_tiers tier
    left join public.bar_tier_keep_days_v278 keep
      on keep.business_id = tier.business_id and keep.tier_id = tier.id
   where tier.business_id = p_business and tier.deleted_at is null;

  select coalesce(jsonb_agg(jsonb_build_object(
           'id', product.id,
           'name', product.name,
           'size_ml', product.size_ml,
           'price_cents', product.retail_price_cents,
           'is_bottle', product.size_ml is not null
         ) order by (product.size_ml is null), product.name, product.id), '[]'::jsonb)
    into v_products
    from public.products product
   where product.business_id = p_business and product.active;

  return jsonb_build_object(
    'status', 'ok',
    'keep_days', app.bar_keep_days_v275(p_business),
    'reminder_days', app.bar_expiry_reminder_days_v282(p_business),
    'can_edit', app.is_salon_owner(p_business),
    'tiers', v_tiers,
    'products', v_products);
end;
$$;

--
-- Name: bar_get_setup_v275(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bar_get_setup_v275(p_business uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_locations jsonb;
begin
  perform app.require_bar_business_v275(p_business);
  perform app.require_bar_staff_v275(p_business, false);

  select coalesce(jsonb_agg(jsonb_build_object(
           'id', location.id,
           'name', location.name,
           'active', location.active,
           'sort', location.sort,
           'in_use', exists (
             select 1 from public.bar_bottles bottle
              where bottle.storage_location_id = location.id
                and bottle.status in ('stored', 'called', 'at_table')
           )
         ) order by location.sort, location.name), '[]'::jsonb)
    into v_locations
    from public.bar_storage_locations location
   where location.business_id = p_business;

  return jsonb_build_object(
    'status', 'ok',
    'keep_days', app.bar_keep_days_v275(p_business),
    'storage_capacity', app.bar_storage_capacity_v279(p_business),
    'in_storage', app.bar_in_storage_count_v279(p_business),
    'can_edit', app.is_salon_owner(p_business),
    'locations', v_locations);
end;
$$;

--
-- Name: bar_save_bottle_product_v278(uuid, uuid, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bar_save_bottle_product_v278(p_business uuid, p_product uuid, p_name text, p_size_ml integer, p_price_cents integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_name text := nullif(btrim(coalesce(p_name, '')), '');
  v_updated uuid;
begin
  perform app.require_bar_business_v275(p_business);
  if v_actor is null then
    raise exception 'authenticated staff required' using errcode = '28000';
  end if;
  if not app.is_salon_owner(p_business) then
    raise exception 'only the owner can change the bottle catalogue' using errcode = '42501';
  end if;
  if p_size_ml is not null and (p_size_ml < 100 or p_size_ml > 5000) then
    raise exception 'a bottle is between 100ml and 5000ml' using errcode = '22023';
  end if;
  if v_name is not null and length(v_name) > 120 then
    raise exception 'a bottle name is limited to 120 characters' using errcode = '22023';
  end if;
  if p_price_cents is not null and (p_price_cents < 0 or p_price_cents > 2147483647) then
    raise exception 'the price is not a valid amount' using errcode = '22023';
  end if;

  if p_product is null then
    if v_name is null then
      raise exception 'name the bottle' using errcode = '22023';
    end if;
    if p_size_ml is null then
      raise exception 'a new bottle needs its size in millilitres' using errcode = '22023';
    end if;
    insert into public.products (business_id, name, retail_price_cents, size_ml, active)
    values (p_business, v_name, coalesce(p_price_cents, 0), p_size_ml, true);
  else
    -- size_ml is still written unconditionally: clearing the box is how the owner
    -- says "this is no longer a bottle", so null there is a VALUE, not an omission.
    -- Name and price keep the opposite contract — null leaves them alone.
    update public.products product
       set size_ml = p_size_ml,
           name = coalesce(v_name, product.name),
           retail_price_cents = coalesce(p_price_cents, product.retail_price_cents)
     where product.id = p_product and product.business_id = p_business
    returning product.id into v_updated;
    if v_updated is null then
      raise exception 'product not found' using errcode = '22023';
    end if;
  end if;

  return public.bar_get_bottle_setup_v278(p_business);
end;
$$;

--
-- Name: bar_save_bottle_product_v288(uuid, uuid, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bar_save_bottle_product_v288(p_business uuid, p_product uuid, p_name text, p_size_ml integer, p_price_cents integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_name text := nullif(btrim(coalesce(p_name, '')), '');
  v_updated uuid;
begin
  perform app.require_bar_business_v275(p_business);
  if v_actor is null then
    raise exception 'authenticated staff required' using errcode = '28000';
  end if;
  if not app.is_salon_owner(p_business) then
    raise exception 'only the owner can change the bottle catalogue' using errcode = '42501';
  end if;
  if p_size_ml is not null and (p_size_ml < 100 or p_size_ml > 5000) then
    raise exception 'a bottle is between 100ml and 5000ml' using errcode = '22023';
  end if;
  if v_name is not null and length(v_name) > 120 then
    raise exception 'a bottle name is limited to 120 characters' using errcode = '22023';
  end if;
  if p_price_cents is not null and (p_price_cents < 0 or p_price_cents > 2147483647) then
    raise exception 'the price is not a valid amount' using errcode = '22023';
  end if;

  if p_product is null then
    if v_name is null then
      raise exception 'name the bottle' using errcode = '22023';
    end if;
    if p_size_ml is null then
      raise exception 'a new bottle needs its size in millilitres' using errcode = '22023';
    end if;
    insert into public.products (business_id, name, retail_price_cents, size_ml, active)
    values (p_business, v_name, coalesce(p_price_cents, 0), p_size_ml, true);
  else
    -- A null name or price still means "leave it alone", so this cannot blank a name by
    -- omission; the size is genuinely nullable (clearing it means "not a bottle") and is
    -- therefore written unconditionally, exactly as v278 wrote it.
    update public.products product
       set size_ml = p_size_ml,
           name = coalesce(v_name, product.name),
           retail_price_cents = coalesce(p_price_cents, product.retail_price_cents)
     where product.id = p_product and product.business_id = p_business
    returning product.id into v_updated;
    if v_updated is null then
      raise exception 'product not found' using errcode = '22023';
    end if;
  end if;

  return public.bar_get_bottle_setup_v278(p_business);
end;
$$;

--
-- Name: bar_save_expiry_reminder_days_v282(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bar_save_expiry_reminder_days_v282(p_business uuid, p_days integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
begin
  perform app.require_bar_business_v275(p_business);
  perform app.require_bar_staff_v275(p_business, true);
  if not app.is_salon_owner(p_business) then
    raise exception 'only an owner may change the reminder window' using errcode = '42501';
  end if;
  if p_days is null or p_days not between 1 and 90 then
    raise exception 'the reminder window must be 1 to 90 days' using errcode = '22023';
  end if;

  insert into public.bar_bottle_settings (business_id, expiry_reminder_days, updated_at, updated_by)
  values (p_business, p_days, now(), v_actor)
  on conflict (business_id) do update
    set expiry_reminder_days = excluded.expiry_reminder_days,
        updated_at = now(),
        updated_by = excluded.updated_by;

  return jsonb_build_object('status', 'ok', 'reminder_days', p_days);
end;
$$;

--
-- Name: bar_save_setup_v275(uuid, integer, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bar_save_setup_v275(p_business uuid, p_keep_days integer, p_locations jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_keep integer := p_keep_days;
  v_kept uuid[] := '{}'::uuid[];
  v_entry jsonb;
  v_name text;
  v_id uuid;
  v_found uuid;
  v_sort integer := 0;
begin
  perform app.require_bar_business_v275(p_business);
  if v_actor is null then
    raise exception 'authenticated staff required' using errcode = '28000';
  end if;
  if not app.is_salon_owner(p_business) then
    raise exception 'only the owner can change bottle keep setup' using errcode = '42501';
  end if;
  if v_keep is null or v_keep < 1 or v_keep > 365 then
    raise exception 'keep window must be between 1 and 365 days' using errcode = '22023';
  end if;
  if p_locations is not null and jsonb_typeof(p_locations) <> 'array' then
    raise exception 'storage locations must be a list' using errcode = '22023';
  end if;

  insert into public.bar_bottle_settings (business_id, keep_days, updated_at, updated_by)
  values (p_business, v_keep, now(), v_actor)
  on conflict (business_id) do update
    set keep_days = excluded.keep_days,
        updated_at = excluded.updated_at,
        updated_by = excluded.updated_by;

  for v_entry in select value from jsonb_array_elements(coalesce(p_locations, '[]'::jsonb)) loop
    v_name := nullif(btrim(coalesce(v_entry->>'name', '')), '');
    if v_name is null then
      raise exception 'a storage location needs a name' using errcode = '22023';
    end if;
    if length(v_name) > 60 then
      raise exception 'a storage location name is limited to 60 characters' using errcode = '22023';
    end if;
    v_sort := v_sort + 1;
    v_id := nullif(v_entry->>'id', '')::uuid;
    v_found := null;
    if v_id is not null then
      update public.bar_storage_locations location
         set name = v_name, active = true, sort = v_sort, updated_at = now()
       where location.id = v_id and location.business_id = p_business
       returning location.id into v_found;
    end if;
    if v_found is null then
      insert into public.bar_storage_locations (business_id, name, active, sort)
      values (p_business, v_name, true, v_sort)
      on conflict (business_id, name) do update
        set active = true, sort = excluded.sort, updated_at = now()
      returning id into v_found;
    end if;
    v_kept := array_append(v_kept, v_found);
  end loop;

  update public.bar_storage_locations location
     set active = false, updated_at = now()
   where location.business_id = p_business
     and location.active
     and not (location.id = any (v_kept));

  return public.bar_get_setup_v275(p_business);
end;
$$;

--
-- Name: bar_save_setup_v279(uuid, integer, integer, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bar_save_setup_v279(p_business uuid, p_keep_days integer, p_storage_capacity integer, p_locations jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_keep integer := p_keep_days;
  v_capacity integer := p_storage_capacity;
  v_kept uuid[] := '{}'::uuid[];
  v_entry jsonb;
  v_name text;
  v_id uuid;
  v_found uuid;
  v_sort integer := 0;
begin
  perform app.require_bar_business_v275(p_business);
  if v_actor is null then
    raise exception 'authenticated staff required' using errcode = '28000';
  end if;
  if not app.is_salon_owner(p_business) then
    raise exception 'only the owner can change bottle keep setup' using errcode = '42501';
  end if;
  if v_keep is null or v_keep < 1 or v_keep > 365 then
    raise exception 'keep window must be between 1 and 365 days' using errcode = '22023';
  end if;
  if v_capacity is null or v_capacity < 1 or v_capacity > 10000 then
    raise exception 'storage capacity must be between 1 and 10000 bottles' using errcode = '22023';
  end if;
  if p_locations is not null and jsonb_typeof(p_locations) <> 'array' then
    raise exception 'storage locations must be a list' using errcode = '22023';
  end if;

  insert into public.bar_bottle_settings (business_id, keep_days, storage_capacity, updated_at, updated_by)
  values (p_business, v_keep, v_capacity, now(), v_actor)
  on conflict (business_id) do update
    set keep_days = excluded.keep_days,
        storage_capacity = excluded.storage_capacity,
        updated_at = excluded.updated_at,
        updated_by = excluded.updated_by;

  for v_entry in select value from jsonb_array_elements(coalesce(p_locations, '[]'::jsonb)) loop
    v_name := nullif(btrim(coalesce(v_entry->>'name', '')), '');
    if v_name is null then
      raise exception 'a storage location needs a name' using errcode = '22023';
    end if;
    if length(v_name) > 60 then
      raise exception 'a storage location name is limited to 60 characters' using errcode = '22023';
    end if;
    v_sort := v_sort + 1;
    v_id := nullif(v_entry->>'id', '')::uuid;
    v_found := null;
    if v_id is not null then
      update public.bar_storage_locations location
         set name = v_name, active = true, sort = v_sort, updated_at = now()
       where location.id = v_id and location.business_id = p_business
       returning location.id into v_found;
    end if;
    if v_found is null then
      insert into public.bar_storage_locations (business_id, name, active, sort)
      values (p_business, v_name, true, v_sort)
      on conflict (business_id, name) do update
        set active = true, sort = excluded.sort, updated_at = now()
      returning id into v_found;
    end if;
    v_kept := array_append(v_kept, v_found);
  end loop;

  -- A name that disappears from the list is DEACTIVATED, never deleted: bottles still point at it
  -- and must keep a nameable answer to "where is it".
  update public.bar_storage_locations location
     set active = false, updated_at = now()
   where location.business_id = p_business
     and location.active
     and not (location.id = any (v_kept));

  return public.bar_get_setup_v275(p_business);
end;
$$;

--
-- Name: bar_save_tier_keep_days_v278(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bar_save_tier_keep_days_v278(p_business uuid, p_tiers jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_entry jsonb;
  v_tier uuid;
  v_days integer;
  v_kept uuid[] := '{}'::uuid[];
begin
  perform app.require_bar_business_v275(p_business);
  if v_actor is null then
    raise exception 'authenticated staff required' using errcode = '28000';
  end if;
  if not app.is_salon_owner(p_business) then
    raise exception 'only the owner can change bottle keep setup' using errcode = '42501';
  end if;
  if p_tiers is not null and jsonb_typeof(p_tiers) <> 'array' then
    raise exception 'tier keep windows must be a list' using errcode = '22023';
  end if;

  for v_entry in select value from jsonb_array_elements(coalesce(p_tiers, '[]'::jsonb)) loop
    v_tier := nullif(v_entry->>'tier_id', '')::uuid;
    if v_tier is null then
      raise exception 'a tier keep window needs a tier' using errcode = '22023';
    end if;
    if not exists (select 1 from public.loyalty_tiers tier
                    where tier.id = v_tier and tier.business_id = p_business
                      and tier.deleted_at is null) then
      raise exception 'that tier does not belong to this business' using errcode = '22023';
    end if;
    v_days := nullif(v_entry->>'keep_days', '')::integer;
    if v_days is null then
      delete from public.bar_tier_keep_days_v278 keep
       where keep.business_id = p_business and keep.tier_id = v_tier;
    else
      if v_days < 1 or v_days > 365 then
        raise exception 'a tier keep window must be between 1 and 365 days' using errcode = '22023';
      end if;
      insert into public.bar_tier_keep_days_v278 (business_id, tier_id, keep_days, updated_at, updated_by)
      values (p_business, v_tier, v_days, now(), v_actor)
      on conflict (business_id, tier_id) do update
        set keep_days = excluded.keep_days,
            updated_at = excluded.updated_at,
            updated_by = excluded.updated_by;
    end if;
    v_kept := array_append(v_kept, v_tier);
  end loop;

  delete from public.bar_tier_keep_days_v278 keep
   where keep.business_id = p_business
     and not (keep.tier_id = any (v_kept));

  return public.bar_get_bottle_setup_v278(p_business);
end;
$$;

--
-- Name: begin_business_google_oauth_signup_v138(text, uuid, text, text, text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.begin_business_google_oauth_signup_v138(p_attempt_token text, p_idempotency_key uuid, p_terms_version text, p_terms_sha256 text, p_privacy_version text, p_privacy_sha256 text, p_accepted boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $_$
declare
  v_token text:=lower(btrim(coalesce(p_attempt_token,'')));
  v_token_hash text;
  v_request_hash text;
  v_existing app.business_google_oauth_attempts_v138%rowtype;
  v_terms app.customer_legal_documents%rowtype;
  v_privacy app.customer_legal_documents%rowtype;
begin
  if auth.uid() is not null or p_accepted is distinct from true
     or p_idempotency_key is null
     or v_token!~'^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then
    raise exception 'valid consented Google signup attempt required' using errcode='22023';
  end if;
  select * into v_terms from app.customer_legal_documents
   where document_key='terms' and active for share;
  select * into v_privacy from app.customer_legal_documents
   where document_key='privacy' and active for share;
  if v_terms.document_version is distinct from p_terms_version
     or v_terms.document_sha256 is distinct from lower(p_terms_sha256)
     or v_privacy.document_version is distinct from p_privacy_version
     or v_privacy.document_sha256 is distinct from lower(p_privacy_sha256) then
    raise exception 'current Terms and Privacy Policy must be accepted' using errcode='22023';
  end if;
  v_token_hash:=app.v31_sha256_hex(v_token);
  v_request_hash:=app.v31_sha256_hex(
    'v138.google-oauth-signup:'||v_token_hash||':'||p_terms_version||':'
    ||lower(p_terms_sha256)||':'||p_privacy_version||':'||lower(p_privacy_sha256)
  );
  perform pg_advisory_xact_lock(hashtextextended(p_idempotency_key::text,138));
  select * into v_existing from app.business_google_oauth_attempts_v138
   where idempotency_key=p_idempotency_key for update;
  if found then
    if v_existing.request_sha256<>v_request_hash then
      raise exception 'Google signup attempt key was reused for different consent'
        using errcode='22023';
    end if;
    return jsonb_build_object('accepted',true,'expires_at',v_existing.expires_at,
      'replayed',true,'published',false);
  end if;
  if exists(select 1 from app.business_google_oauth_attempts_v138
      where token_sha256=v_token_hash) then
    raise exception 'Google signup attempt token is already in use' using errcode='23505';
  end if;
  insert into app.business_google_oauth_attempts_v138(
    token_sha256,idempotency_key,request_sha256,
    terms_version,terms_sha256,privacy_version,privacy_sha256
  ) values(
    v_token_hash,p_idempotency_key,v_request_hash,
    v_terms.document_version,v_terms.document_sha256,
    v_privacy.document_version,v_privacy.document_sha256
  ) returning * into v_existing;
  return jsonb_build_object('accepted',true,'expires_at',v_existing.expires_at,
    'replayed',false,'published',false);
end
$_$;

--
-- Name: FUNCTION begin_business_google_oauth_signup_v138(p_attempt_token text, p_idempotency_key uuid, p_terms_version text, p_terms_sha256 text, p_privacy_version text, p_privacy_sha256 text, p_accepted boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.begin_business_google_oauth_signup_v138(p_attempt_token text, p_idempotency_key uuid, p_terms_version text, p_terms_sha256 text, p_privacy_version text, p_privacy_sha256 text, p_accepted boolean) IS 'Anonymous no-PII V138 pre-OAuth consent attempt pinned to the active Terms and Privacy hashes; expires after 30 minutes.';

--
-- Name: begin_merchant_connect_command_v142(uuid, uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.begin_merchant_connect_command_v142(p_business uuid, p_actor uuid, p_idempotency_key uuid, p_livemode boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_command public.merchant_payment_commands_v142%rowtype;
        v_account public.merchant_payment_accounts_v142%rowtype;
        v_bound public.merchant_payment_accounts_v142%rowtype;
begin
  perform app.v142_service_guard();
  if not app.v142_actor_is_owner(p_business,p_actor) then
    raise exception 'only the active business owner can set up customer payments' using errcode = '42501';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('v142-connect:'||p_business::text,0));
  select * into v_bound from public.merchant_payment_accounts_v142
   where business_id=p_business;
  if found and v_bound.livemode and not p_livemode then
    raise exception 'live merchant payment binding cannot be downgraded to test mode'
      using errcode='23505';
  end if;
  -- Stripe objects are isolated by mode. A test account must never be retrieved
  -- with a live key; a live setup starts a new, explicitly promoted binding.
  select * into v_account from public.merchant_payment_accounts_v142
   where business_id=p_business and livemode=p_livemode;
  insert into public.merchant_payment_commands_v142(
    business_id,actor,action,livemode,idempotency_key,provider_idempotency_key,status,provider_account_id,started_at)
  values(p_business,p_actor,'create_onboarding_link',p_livemode,p_idempotency_key,
    'peekaa-connect-'||case when p_livemode then 'live-' else 'test-' end||p_business::text,
    'running',v_account.provider_account_id,now())
  on conflict (business_id,actor,action,livemode,idempotency_key) do update
    set status=case when merchant_payment_commands_v142.status='completed' then 'completed' else 'running' end,
        started_at=coalesce(merchant_payment_commands_v142.started_at,now()),updated_at=now()
  returning * into v_command;
  return jsonb_build_object('command_id',v_command.id,'business_id',p_business,
    'status',v_command.status,'provider_idempotency_key',v_command.provider_idempotency_key,
    'provider_account_id',coalesce(v_account.provider_account_id,v_command.provider_account_id),
    'livemode',p_livemode);
end $$;

--
-- Name: begin_pos_paynow_attempt_v142(uuid, uuid, uuid, uuid, uuid, uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.begin_pos_paynow_attempt_v142(p_business uuid, p_branch uuid, p_client uuid, p_staff uuid, p_evaluation uuid, p_actor uuid, p_idempotency_key uuid, p_livemode boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_eval public.checkout_evaluations%rowtype;
        v_account public.merchant_payment_accounts_v142%rowtype;
        v_attempt public.pos_payment_attempts_v142%rowtype;
        v_paynow_expires_at timestamptz;
begin
  perform app.v142_service_guard();
  if not exists (select 1 from public.staff s where s.id=p_staff and s.business_id=p_business
    and s.user_id=p_actor and s.active) then
    raise exception 'active staff identity required' using errcode='42501';
  end if;
  perform set_config('request.jwt.claim.sub',p_actor::text,true);
  if not app.has_perm(p_business,'create_sales')
     or not app.can_module_write_at_v94(p_business,p_branch,'till')
     or not app.can_module_read_at_v94(p_business,p_branch,'clients') then
    raise exception 'Record sale access denied at this branch' using errcode='42501';
  end if;
  select * into v_attempt from public.pos_payment_attempts_v142
   where business_id=p_business and idempotency_key=p_idempotency_key;
  if found then
    if v_attempt.branch_id is distinct from p_branch or v_attempt.client_id is distinct from p_client
       or v_attempt.staff_id is distinct from p_staff
       or v_attempt.evaluation_id is distinct from p_evaluation
       or v_attempt.livemode is distinct from p_livemode then
      raise exception 'PayNow attempt key conflicts with another checkout' using errcode='22023';
    end if;
    return jsonb_build_object('attempt_id',v_attempt.id,'business_id',v_attempt.business_id,
      'provider_account_id',v_attempt.provider_account_id,'provider_payment_intent_id',v_attempt.provider_payment_intent_id,
      'provider_idempotency_key',v_attempt.provider_idempotency_key,'amount_cents',v_attempt.amount_cents,
      'currency',v_attempt.currency,'status',v_attempt.status,'expires_at',v_attempt.expires_at,
      'livemode',v_attempt.livemode);
  end if;
  -- If the browser lost its local retry key, the immutable checkout evaluation
  -- still identifies the one existing payment attempt. Recover it instead of
  -- minting another provider charge for the same cart.
  select * into v_attempt from public.pos_payment_attempts_v142
   where business_id=p_business and evaluation_id=p_evaluation;
  if found then
    if v_attempt.branch_id is distinct from p_branch or v_attempt.client_id is distinct from p_client
       or v_attempt.staff_id is distinct from p_staff or v_attempt.created_by is distinct from p_actor
       or v_attempt.livemode is distinct from p_livemode then
      raise exception 'checkout evaluation is already bound to another PayNow authority'
        using errcode='22023';
    end if;
    return jsonb_build_object('attempt_id',v_attempt.id,'business_id',v_attempt.business_id,
      'provider_account_id',v_attempt.provider_account_id,'provider_payment_intent_id',v_attempt.provider_payment_intent_id,
      'provider_idempotency_key',v_attempt.provider_idempotency_key,'amount_cents',v_attempt.amount_cents,
      'currency',v_attempt.currency,'status',v_attempt.status,'expires_at',v_attempt.expires_at,
      'livemode',v_attempt.livemode);
  end if;
  select * into v_eval from public.checkout_evaluations
   where id=p_evaluation and business_id=p_business for update;
  if not found or v_eval.branch_id is distinct from p_branch
     or v_eval.client_id is distinct from p_client or v_eval.consumed_at is not null
     or not exists (select 1 from public.checkout_evaluation_operations o
       where o.business_id=p_business and o.evaluation_id=p_evaluation and o.actor=p_actor) then
    raise exception 'checkout evaluation does not match this sale' using errcode='42501';
  end if;
  if v_eval.expires_at<=now() then
    raise exception 'checkout evaluation expired; check the total again' using errcode='P0001';
  end if;
  if v_eval.total_cents<=0 then
    raise exception 'PayNow requires a positive total' using errcode='22023';
  end if;
  if exists(select 1 from public.checkout_sv_tenders t where t.evaluation_id=v_eval.id and t.status='reserved') then
    raise exception 'remove stored value before creating a PayNow QR' using errcode='22023';
  end if;
  select * into v_account from public.merchant_payment_accounts_v142
   where business_id=p_business and livemode=p_livemode for share;
  if not found or not (v_account.details_submitted and v_account.charges_enabled
      and v_account.payouts_enabled and v_account.paynow_capability='active') then
    raise exception 'business PayNow setup is not ready' using errcode='P0001';
  end if;
  -- A Stripe PayNow QR remains payable for one hour. Reserve the original
  -- immutable evaluation and extend only its expiry to cover that provider
  -- window. There is never a second consumable checkout for the same cart.
  v_paynow_expires_at:=now()+interval '61 minutes';
  perform set_config('app.v142_extend_checkout','on',true);
  update public.checkout_evaluations set expires_at=v_paynow_expires_at where id=p_evaluation;
  perform set_config('app.v142_extend_checkout','off',true);
  insert into public.pos_payment_attempts_v142(
    business_id,branch_id,client_id,staff_id,created_by,evaluation_id,provider_account_id,
    livemode,amount_cents,currency,idempotency_key,provider_idempotency_key,expires_at)
  values(p_business,p_branch,p_client,p_staff,p_actor,p_evaluation,v_account.provider_account_id,
    v_account.livemode,v_eval.total_cents,'SGD',p_idempotency_key,
    'peekaa-pos-'||case when p_livemode then 'live-' else 'test-' end||p_business::text||'-'||p_idempotency_key::text,
    v_paynow_expires_at)
  on conflict (business_id,idempotency_key) do nothing returning * into v_attempt;
  if v_attempt.id is null then
    select * into v_attempt from public.pos_payment_attempts_v142
     where business_id=p_business and idempotency_key=p_idempotency_key;
    if v_attempt.branch_id is distinct from p_branch or v_attempt.client_id is distinct from p_client
       or v_attempt.staff_id is distinct from p_staff
       or v_attempt.evaluation_id is distinct from p_evaluation
       or v_attempt.livemode is distinct from p_livemode then
      raise exception 'PayNow attempt key conflicts with another checkout' using errcode='22023';
    end if;
  end if;
  return jsonb_build_object('attempt_id',v_attempt.id,'business_id',v_attempt.business_id,
    'provider_account_id',v_attempt.provider_account_id,'provider_payment_intent_id',v_attempt.provider_payment_intent_id,
    'provider_idempotency_key',v_attempt.provider_idempotency_key,'amount_cents',v_attempt.amount_cents,
    'currency',v_attempt.currency,'status',v_attempt.status,'expires_at',v_attempt.expires_at,
    'livemode',v_attempt.livemode);
end $$;

--
-- Name: block_business_onboarding_v79(uuid, text, text, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.block_business_onboarding_v79(p_business uuid, p_item_key text, p_reason text, p_expected_version bigint, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_checklist public.business_onboarding_checklists%rowtype;
  v_item public.business_onboarding_items%rowtype;
  v_request jsonb;
  v_replay jsonb;
  v_response jsonb;
begin
  if not app.is_super_admin() then
    raise exception 'super_admin_required';
  end if;
  perform app.require_idempotency_key_v79(p_idempotency_key);
  if length(btrim(coalesce(p_reason,'')))<3 then
    raise exception 'block_reason_required';
  end if;
  if nullif(btrim(p_idempotency_key), '') is null then
    raise exception 'idempotency_key_required';
  end if;

  v_request := jsonb_build_object(
    'business_id', p_business,
    'item_key', p_item_key,
    'reason', btrim(p_reason),
    'expected_version', p_expected_version
  );
  v_replay := app.v76_replay(
    v_actor, 'block_business_onboarding_v79', p_idempotency_key,
    app.v76_sha256_hex(v_request::text)
  );
  if v_replay is not null then return v_replay; end if;

  select * into v_checklist
  from public.business_onboarding_checklists
  where business_id = p_business
  for update;
  if not found then raise exception 'onboarding_checklist_not_found'; end if;
  if v_checklist.version <> p_expected_version then raise exception 'version_conflict'; end if;
  if v_checklist.status = 'activated' then raise exception 'business_already_activated'; end if;

  if nullif(btrim(p_item_key), '') is null then
    update public.business_onboarding_checklists
    set status = 'blocked',
        blocked_reason = btrim(p_reason),
        blocked_by = v_actor,
        blocked_at = now(),
        version = version + 1,
        updated_at = now()
    where id = v_checklist.id;
  else
    select * into v_item
    from public.business_onboarding_items
    where checklist_id = v_checklist.id
      and item_key = btrim(p_item_key)
    for update;
    if not found then raise exception 'onboarding_item_not_found'; end if;

    update public.business_onboarding_items
    set status_before_block = case when status = 'blocked' then status_before_block else status end,
        status = 'blocked',
        block_reason = btrim(p_reason),
        blocked_by = v_actor,
        blocked_at = now(),
        updated_at = now()
    where id = v_item.id;
    perform app.recompute_onboarding_status_v79(p_business, v_actor);
  end if;

  insert into public.business_onboarding_events(
    checklist_id, business_id, item_id, event_type, actor, evidence
  ) values (
    v_checklist.id, p_business, v_item.id, 'blocked', v_actor,
    jsonb_build_object('item_key', nullif(btrim(p_item_key), ''), 'reason', btrim(p_reason))
  );

  v_response := jsonb_build_object(
    'replayed',false,'onboarding',app.get_onboarding_core_v79(p_business)
  );
  perform app.v76_store_receipt(
    v_actor, 'block_business_onboarding_v79', p_idempotency_key,
    app.v76_sha256_hex(v_request::text), v_response
  );
  insert into public.audit_log(business_id,actor,action,entity,entity_id,detail)
  values(p_business,v_actor,'BUSINESS_ONBOARDING_BLOCKED_V79','businesses',p_business,
    jsonb_build_object('item_key',nullif(btrim(p_item_key),''),'reason',btrim(p_reason)));
  return v_response;
end
$$;

--
-- Name: book_appointment_smart_v47(uuid, uuid, uuid, uuid, timestamp with time zone, integer, uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.book_appointment_smart_v47(p_business uuid, p_client uuid, p_branch uuid, p_service uuid, p_starts timestamp with time zone, p_duration_minutes integer, p_requested_staff uuid, p_assignment_mode text, p_note text, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if app.business_has_appointments_module_v288(p_business,p_branch) then
    perform app.require_branch_module_v94(
      p_business,p_branch,'appointments','rw'
    );
  else
    perform app.require_branch_module_v94(
      p_business,p_branch,'bookings','rw'
    );
  end if;
  return public.book_appointment_smart_v47_v94_base(
    p_business,p_client,p_branch,p_service,p_starts,p_duration_minutes,
    p_requested_staff,p_assignment_mode,p_note,p_idempotency_key
  );
end
$$;

--
-- Name: book_appointment_smart_v47_v94_base(uuid, uuid, uuid, uuid, timestamp with time zone, integer, uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.book_appointment_smart_v47_v94_base(p_business uuid, p_client uuid, p_branch uuid, p_service uuid, p_starts timestamp with time zone, p_duration_minutes integer, p_requested_staff uuid, p_assignment_mode text, p_note text, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_request_hash text;
  v_existing app.appointment_booking_operations%rowtype;
  v_appointment public.appointments%rowtype;
  v_service public.services%rowtype;
  v_staff public.staff%rowtype;
  v_duration integer;
  v_ends timestamptz;
  v_suggestions jsonb;
begin
  if auth.uid() is null
     or (case
       when app.business_has_appointments_module_v288(p_business, p_branch)
         then not app.can_module_write(p_business, 'appointments')
         else not app.can_module_write(p_business, 'bookings')
     end)
     or not app.can_see_branch(p_business, p_branch) then
    raise exception 'appointment write access for this branch is required'
      using errcode = '42501';
  end if;
  if p_assignment_mode not in ('manual','round_robin') then
    raise exception 'assignment mode must be manual or round_robin'
      using errcode = '22023';
  end if;
  if p_assignment_mode = 'manual' and p_requested_staff is null then
    raise exception 'manual assignment requires a staff member'
      using errcode = '22023';
  end if;
  if p_starts is null or p_starts < clock_timestamp() - interval '5 minutes' then
    raise exception 'appointment start must be in the future'
      using errcode = '22023';
  end if;
  if p_idempotency_key is null or char_length(btrim(p_idempotency_key)) not between 8 and 200 then
    raise exception 'an idempotency key of 8 to 200 characters is required'
      using errcode = '22023';
  end if;
  if p_note is not null and char_length(p_note) > 1000 then
    raise exception 'appointment note is too long' using errcode = '22023';
  end if;
  if not exists(select 1 from public.clients c
                 where c.id=p_client and c.business_id=p_business) then
    raise exception 'customer not found' using errcode = '22023';
  end if;
  if not exists(select 1 from public.branches b
                 where b.id=p_branch and b.business_id=p_business and b.active) then
    raise exception 'active branch not found' using errcode = '22023';
  end if;

  if p_service is not null then
    select * into v_service from public.services s
     where s.id=p_service and s.business_id=p_business and s.active;
    if not found then raise exception 'active service not found' using errcode='22023'; end if;
    if exists(select 1 from public.service_branches configured
               where configured.business_id=p_business and configured.service_id=p_service)
       and not exists(select 1 from public.service_branches allowed
                       where allowed.business_id=p_business and allowed.service_id=p_service
                         and allowed.branch_id=p_branch) then
      raise exception 'service is not bookable at this branch' using errcode='22023';
    end if;
    v_duration := v_service.duration_min;
  else
    v_duration := p_duration_minutes;
  end if;
  if v_duration not between 15 and 720 then
    raise exception 'appointment duration must be between 15 and 720 minutes'
      using errcode = '22023';
  end if;
  v_ends := p_starts + make_interval(mins => v_duration);

  v_request_hash := app.v41_request_hash(concat_ws('|',
    p_business::text,p_client::text,p_branch::text,coalesce(p_service::text,''),
    p_starts::text,v_duration::text,coalesce(p_requested_staff::text,''),
    p_assignment_mode,coalesce(p_note,'')));

  perform pg_advisory_xact_lock(hashtextextended(p_business::text, 47));
  select * into v_existing from app.appointment_booking_operations op
   where op.business_id=p_business and op.idempotency_key=btrim(p_idempotency_key);
  if found then
    if v_existing.request_hash <> v_request_hash then
      raise exception 'idempotency key was already used for a different appointment request'
        using errcode = '22023';
    end if;
    select * into v_appointment from public.appointments a
     where a.id=v_existing.appointment_id and a.business_id=p_business;
    return jsonb_build_object('status','booked','replayed',true,
      'appointment_id',v_appointment.id,'staff_id',v_appointment.staff_id,
      'starts_at',v_appointment.starts_at,'ends_at',v_appointment.ends_at);
  end if;

  if p_assignment_mode = 'manual' then
    select * into v_staff from public.staff s
     where s.id=p_requested_staff and s.business_id=p_business and s.active;
    if not found then raise exception 'active staff member not found' using errcode='22023'; end if;
    if not app.staff_free_for_appointment_v47(
      p_business,v_staff.id,p_branch,p_service,p_starts,v_ends,null) then
      v_suggestions := public.suggest_appointment_staff_v47(
        p_business,p_branch,p_service,p_starts,v_duration,5);
      return jsonb_build_object('status','conflict','reason','staff_unavailable',
        'suggestions',v_suggestions);
    end if;
  else
    select s.* into v_staff
      from public.staff s
      join public.staff_branches sb
        on sb.business_id=s.business_id and sb.staff_id=s.id and sb.branch_id=p_branch
     where s.business_id=p_business and s.active
       and app.staff_free_for_appointment_v47(
         p_business,s.id,p_branch,p_service,p_starts,v_ends,null)
     order by
       (select count(*) from public.appointments a
         where a.business_id=p_business and a.staff_id=s.id
           and a.status in ('booked','completed')
           and a.starts_at >= clock_timestamp() - interval '30 days'),
       (select max(a.created_at) from public.appointments a
         where a.business_id=p_business and a.staff_id=s.id
           and a.status in ('booked','completed')) nulls first,
       s.full_name, s.id
     limit 1;
    if not found then
      v_suggestions := public.suggest_appointment_staff_v47(
        p_business,p_branch,p_service,p_starts,v_duration,5);
      return jsonb_build_object('status','conflict','reason','no_staff_available',
        'suggestions',v_suggestions);
    end if;
  end if;

  insert into public.appointments (
    business_id,client_id,branch_id,service_id,staff_id,starts_at,ends_at,
    note,total_cents,source,status
  ) values (
    p_business,p_client,p_branch,p_service,v_staff.id,p_starts,v_ends,
    nullif(btrim(coalesce(p_note,'')),''),coalesce(v_service.price_cents,0),
    'smart_staff','booked'
  ) returning * into v_appointment;

  insert into app.appointment_booking_operations (
    business_id,idempotency_key,request_hash,appointment_id
  ) values (
    p_business,btrim(p_idempotency_key),v_request_hash,v_appointment.id
  );

  insert into public.audit_log (business_id,actor,action,entity,entity_id,detail)
  values (p_business,auth.uid(),'APPOINTMENT_SMART_BOOK','appointments',v_appointment.id,
    jsonb_build_object('branch_id',p_branch,'staff_id',v_staff.id,
      'assignment_mode',p_assignment_mode,'starts_at',p_starts,'ends_at',v_ends));

  return jsonb_build_object('status','booked','replayed',false,
    'appointment_id',v_appointment.id,'staff_id',v_staff.id,
    'staff_name',v_staff.full_name,'assignment_mode',p_assignment_mode,
    'starts_at',v_appointment.starts_at,'ends_at',v_appointment.ends_at);
end
$$;

--
-- Name: business_activate_paid_branches_v202(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.business_activate_paid_branches_v202(p_business uuid, p_command uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_branch uuid; v_activated integer := 0;
begin
  if not app.is_super_admin() and auth.uid() is not null then
    raise exception 'payment confirmation is server-side only' using errcode='42501';
  end if;
  select requested_branch_id into v_branch from public.billing_commands
   where id=p_command and business_id=p_business;
  if v_branch is null then
    return jsonb_build_object('status','no_branch','activated',0);
  end if;
  update public.branches
     set billing_state='active', active=true, updated_at=now()
   where id=v_branch and business_id=p_business and billing_state='pending_payment';
  get diagnostics v_activated = row_count;
  return jsonb_build_object('status','ok','branch_id',v_branch,'activated',v_activated);
end
$$;

--
-- Name: business_add_branch_v202(uuid, text, text, text, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.business_add_branch_v202(p_business uuid, p_name text, p_address text DEFAULT NULL::text, p_phone text DEFAULT NULL::text, p_email text DEFAULT NULL::text, p_copy_from uuid DEFAULT NULL::uuid, p_idempotency_key uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_branch public.branches%rowtype;
  v_existing public.billing_commands%rowtype;
  v_cadence text;
  v_capacity integer;
  v_subscription text;
  v_command_type text;
  v_command jsonb;
  v_copied jsonb := null;
  v_name text := nullif(btrim(coalesce(p_name,'')),'');
begin
  if v_actor is null or not (app.is_salon_owner(p_business) or app.is_super_admin()) then
    raise exception 'owner access is required' using errcode='42501';
  end if;
  if v_name is null then
    raise exception 'a branch name is required' using errcode='22023';
  end if;
  if p_idempotency_key is null then
    raise exception 'an idempotency key is required' using errcode='22023';
  end if;

  select * into v_existing from public.billing_commands
   where business_id=p_business and idempotency_key=p_idempotency_key;
  if found then
    select * into v_branch from public.branches where id=v_existing.requested_branch_id;
    return jsonb_build_object(
      'status','replayed','branch_id',v_existing.requested_branch_id,
      'branch_name',v_branch.name,'billing_state',v_branch.billing_state,
      'command_id',v_existing.id,'command_status',v_existing.status,
      'redirect_url',v_existing.redirect_url);
  end if;

  select s.billing_cadence, s.provider_subscription_id, t.customer_capacity
    into v_cadence, v_subscription, v_capacity
    from public.subscriptions s
    left join public.billing_subscription_terms_v124 t on t.business_id=s.business_id
   where s.business_id=p_business;

  v_cadence := coalesce(nullif(v_cadence,''),'annual');
  if v_capacity is null then
    select greatest(1000, ceil(count(*)::numeric/1000)::integer*1000)
      into v_capacity from public.clients where business_id=p_business;
  end if;
  v_command_type := case when nullif(v_subscription,'') is not null
                         then 'change_branches' else 'create_checkout' end;

  insert into public.branches(business_id,name,address,phone,email,active,is_default,billing_state)
  values (p_business,v_name,nullif(btrim(coalesce(p_address,'')),''),
          nullif(btrim(coalesce(p_phone,'')),''),nullif(btrim(coalesce(p_email,'')),''),
          false,false,'pending_payment')
  returning * into v_branch;

  if p_copy_from is not null then
    v_copied := public.business_copy_branch_settings_v202(p_business,p_copy_from,v_branch.id);
  end if;

  -- V280: this branch of the code runs only when the firm has NO Stripe subscription, so the
  -- checkout being minted here is being minted to pay for a BRANCH. Whatever is collecting the
  -- firm's own base plan today — a manual invoice, or nothing yet because the trial is running —
  -- it is not this subscription, and charging the base a second time inside a branch purchase is
  -- what the owner saw as "pay for 2 branch". Recorded before the command is handed out, so the
  -- edge function reads a decision rather than guessing one.
  if v_command_type = 'create_checkout' then
    update public.subscriptions
       set provider_covers_base_unit = false, updated_at = now()
     where business_id = p_business;
  end if;

  v_command := public.request_billing_command_v124(
    p_business,v_command_type,v_cadence,v_capacity,p_idempotency_key);

  update public.billing_commands
     set requested_branch_id=v_branch.id
   where id=(v_command->>'command_id')::uuid;

  return jsonb_build_object(
    'status','ok','branch_id',v_branch.id,'branch_name',v_branch.name,
    'billing_state',v_branch.billing_state,'copied',v_copied,
    'command_type',v_command_type,'cadence',v_cadence,
    'covers_base_unit',v_command_type<>'create_checkout',
    'command_id',v_command->>'command_id','command_status',v_command->>'status');
end
$$;

--
-- Name: business_branch_billing_units_v280(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.business_branch_billing_units_v280(p_business uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_total integer; v_included integer; v_billable integer; v_lapsed integer;
  v_covers boolean;
begin
  if auth.uid() is null or not (app.is_salon_owner(p_business) or app.is_super_admin()) then
    raise exception 'owner access is required' using errcode='42501';
  end if;
  select count(*)::integer,
         count(*) filter (where billing_state='included')::integer,
         count(*) filter (where billing_state in ('pending_payment','active'))::integer,
         count(*) filter (where billing_state='suspended')::integer
    into v_total, v_included, v_billable, v_lapsed
    from public.branches where business_id=p_business;
  select coalesce(provider_covers_base_unit,true) into v_covers
    from public.subscriptions where business_id=p_business;
  return jsonb_build_object(
    'status','ok','total_branches',v_total,'included_branches',v_included,
    'billable_branches',v_billable,'lapsed_branches',v_lapsed,
    'base_unit_billed_by_provider',coalesce(v_covers,true),
    'plan_units',greatest(1,(case when coalesce(v_covers,true) then 1 else 0 end)+v_billable));
end
$$;

--
-- Name: business_copy_branch_settings_v202(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.business_copy_branch_settings_v202(p_business uuid, p_from uuid, p_to uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_hours integer := 0; v_breaks integer := 0; v_services integer := 0;
  v_staff integer := 0; v_loyalty integer := 0; v_live uuid;
begin
  if auth.uid() is null or not (app.is_salon_owner(p_business) or app.is_super_admin()) then
    raise exception 'owner access is required' using errcode='42501';
  end if;
  if p_from is null or p_to is null or p_from = p_to then
    raise exception 'a source and a different destination branch are required' using errcode='22023';
  end if;
  if not exists (select 1 from public.branches where id=p_from and business_id=p_business)
     or not exists (select 1 from public.branches where id=p_to and business_id=p_business) then
    raise exception 'both branches must belong to this business' using errcode='42501';
  end if;

  insert into public.branch_hours(business_id,branch_id,weekday,opens_at,closes_at)
  select p_business,p_to,h.weekday,h.opens_at,h.closes_at
    from public.branch_hours h
   where h.business_id=p_business and h.branch_id=p_from
     and not exists (
       select 1 from public.branch_hours e
        where e.business_id=p_business and e.branch_id=p_to and e.weekday=h.weekday
          and e.opens_at=h.opens_at and e.closes_at=h.closes_at);
  get diagnostics v_hours = row_count;

  insert into public.branch_breaks(business_id,branch_id,weekday,starts_at,ends_at)
  select p_business,p_to,b.weekday,b.starts_at,b.ends_at
    from public.branch_breaks b
   where b.business_id=p_business and b.branch_id=p_from
     and not exists (
       select 1 from public.branch_breaks e
        where e.business_id=p_business and e.branch_id=p_to and e.weekday=b.weekday
          and e.starts_at=b.starts_at and e.ends_at=b.ends_at);
  get diagnostics v_breaks = row_count;

  insert into public.service_branches(business_id,service_id,branch_id)
  select p_business,s.service_id,p_to from public.service_branches s
   where s.business_id=p_business and s.branch_id=p_from
  on conflict do nothing;
  get diagnostics v_services = row_count;

  -- Staff carry the module permissions that decide who can do what at a branch, and a
  -- branch with nobody assigned cannot take a single booking (v118/v119: missing hours and
  -- missing staff are closed, not open). Copying them is what makes the new branch work on
  -- day one; the owner removes whoever does not belong there.
  insert into public.staff_branches(business_id,staff_id,branch_id)
  select p_business,s.staff_id,p_to from public.staff_branches s
   where s.business_id=p_business and s.branch_id=p_from
  on conflict do nothing;
  get diagnostics v_staff = row_count;

  -- Only the LIVE configuration version. Copying an override into a historical published
  -- version would rewrite what a customer was already promised.
  select fcv.id into v_live from public.firm_config_versions fcv
   where fcv.business_id=p_business and fcv.status='published'
   order by fcv.published_at desc nulls last limit 1;
  if v_live is not null then
    insert into public.loyalty_branch_overrides(
      config_version_id,business_id,branch_id,active,earn_points_per_dollar,
      stamp_per_cents,expiry_mode,expiry_days)
    select o.config_version_id,p_business,p_to,o.active,o.earn_points_per_dollar,
           o.stamp_per_cents,o.expiry_mode,o.expiry_days
      from public.loyalty_branch_overrides o
     where o.business_id=p_business and o.branch_id=p_from
       and o.config_version_id=v_live
    on conflict do nothing;
    get diagnostics v_loyalty = row_count;
  end if;

  return jsonb_build_object(
    'status','ok','from_branch',p_from,'to_branch',p_to,
    'opening_hours',v_hours,'breaks',v_breaks,'services',v_services,
    'staff_assignments',v_staff,'loyalty_overrides',v_loyalty,
    'products_note','products are firm-wide and need no copy');
end
$$;

--
-- Name: business_create_customer_join_qr_v89(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.business_create_customer_join_qr_v89(p_business uuid, p_expires_at timestamp with time zone DEFAULT (now() + '365 days'::interval)) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'extensions', 'pg_temp'
    AS $$
declare
  v_token text; v_version integer; v_expires timestamptz;
  v_qr public.business_customer_join_qr_v89%rowtype;
begin
  if not (app.is_salon_owner(p_business) or app.is_super_admin()) then
    raise exception 'business owner access is required' using errcode='42501';
  end if;
  if p_expires_at is not null and p_expires_at <= now()+interval '5 minutes' then
    raise exception 'join QR expiry must be at least 5 minutes away' using errcode='22023';
  end if;
  v_expires := greatest(coalesce(p_expires_at, now()), now()+interval '50 years');

  select coalesce(max(token_version),0)+1 into v_version
  from public.business_customer_join_qr_v89 where business_id=p_business;
  v_token := app.v197_join_token(p_business, v_version);

  insert into public.business_customer_join_qr_v89(
    business_id,token_hash,expires_at,issued_by,token_version
  ) values(p_business,app.v89_sha256(v_token),v_expires,auth.uid(),v_version)
  returning * into v_qr;

  insert into public.audit_log(business_id,actor,action,entity,entity_id,detail)
  values(p_business,auth.uid(),'CREATE_CUSTOMER_JOIN_QR_V89',
    'business_customer_join_qr_v89',v_qr.id,
    jsonb_build_object('expires_at',v_qr.expires_at,'token_version',v_version));
  return jsonb_build_object('qr_id',v_qr.id,'join_token',v_token,
    'expires_at',v_qr.expires_at,'token_version',v_version);
end $$;

--
-- Name: business_create_promotion_draft_v104(uuid, uuid, uuid, uuid, text, text, text, text, timestamp with time zone, timestamp with time zone, integer, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.business_create_promotion_draft_v104(p_business uuid, p_promotion_id uuid, p_attempt_key uuid, p_branch uuid, p_name text, p_tagline text, p_description text, p_terms text, p_starts_at timestamp with time zone, p_ends_at timestamp with time zone, p_display_order integer, p_cta_kind text, p_cta_label text, p_offer_facts text, p_occasion text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid:=auth.uid();
  v_content public.business_customer_content_v95%rowtype;
  v_copy public.business_localized_copy_v95%rowtype;
  v_receipt public.business_promotion_attempt_receipts_v104%rowtype;
  v_entitlement record;
  v_request jsonb;
  v_response jsonb;
  v_quota_used integer:=0;
begin
  if v_actor is null then
    raise exception 'authenticated_session_required' using errcode='28000';
  end if;
  if p_business is null or p_promotion_id is null or p_attempt_key is null then
    raise exception 'valid_promotion_attempt_identity_required'
      using errcode='22023';
  end if;

  perform app.v104_lock_promotion_business(p_business);
  v_request:=jsonb_build_object(
    'action','create_draft',
    'promotion_id',p_promotion_id,
    'branch_id',p_branch,
    'name',p_name,
    'tagline',p_tagline,
    'description',p_description,
    'terms',p_terms,
    'starts_at',p_starts_at,
    'ends_at',p_ends_at,
    'display_order',p_display_order,
    'cta_kind',p_cta_kind,
    'cta_label',p_cta_label,
    'offer_facts',p_offer_facts,
    'occasion',p_occasion
  );
  select * into v_receipt
  from public.business_promotion_attempt_receipts_v104 receipt
  where receipt.business_id=p_business
    and receipt.attempt_key=p_attempt_key
  for update;
  if found then
    if v_receipt.created_by is distinct from v_actor
       and not app.is_salon_owner(p_business)
       and not app.is_super_admin()
    then
      raise exception 'promotion_receipt_replay_forbidden'
        using errcode='42501';
    end if;
    if v_receipt.request_payload<>v_request then
      raise exception 'promotion_attempt_key_reused'
        using errcode='23505';
    end if;
    return v_receipt.response_payload||jsonb_build_object(
      'attempt_key',p_attempt_key,
      'replayed',true
    );
  end if;

  if not app.is_salon_owner(p_business) then
    raise exception 'owner_required' using errcode='42501';
  end if;
  if p_branch is not null
     or p_display_order is null
     or p_display_order not between 0 and 10000
     or p_cta_kind is null
     or p_cta_kind not in ('book','programme','counter')
     or length(btrim(coalesce(p_cta_label,''))) not between 2 and 40
     or length(btrim(coalesce(p_name,''))) not between 2 and 70
     or (
       nullif(btrim(coalesce(p_tagline,'')),'') is not null
       and length(btrim(p_tagline)) not between 2 and 120
     )
     or length(btrim(coalesce(p_description,''))) not between 10 and 600
     or (
       nullif(btrim(coalesce(p_terms,'')),'') is not null
       and length(btrim(p_terms))>1000
     )
     or length(btrim(coalesce(p_offer_facts,''))) not between 2 and 500
     or (
       nullif(btrim(coalesce(p_occasion,'')),'') is not null
       and length(btrim(p_occasion)) not between 2 and 80
     )
     or p_ends_at is null
     or (p_starts_at is not null and p_ends_at<=p_starts_at)
     or not exists(
       select 1 from public.businesses business where business.id=p_business
     )
  then
    raise exception 'valid_promotion_draft_fields_required'
      using errcode='22023';
  end if;

  select * into v_entitlement
  from app.v104_effective_promotion_entitlement(p_business);
  if exists(
    select 1 from public.business_customer_content_v95 content
    where content.id=p_promotion_id
  ) then
    raise exception 'promotion_id_already_exists' using errcode='23505';
  end if;

  perform set_config('app.v104_promotion_write','on',true);
  insert into public.business_customer_content_v95(
    id,business_id,content_type,branch_id,active,display_order,
    starts_at,ends_at,metadata,updated_by
  ) values(
    p_promotion_id,p_business,'offer',p_branch,false,p_display_order,
    p_starts_at,p_ends_at,
    jsonb_strip_nulls(jsonb_build_object(
      'schema','nestly.promotion.v104',
      'cta',jsonb_build_object(
        'kind',p_cta_kind,
        'label',btrim(p_cta_label)
      ),
      'offer_facts',btrim(p_offer_facts),
      'occasion',nullif(btrim(coalesce(p_occasion,'')),'')
    )),
    v_actor
  )
  returning * into v_content;
  perform set_config('app.v104_promotion_write','',true);

  perform set_config('app.v104_promotion_copy_write','on',true);
  insert into public.business_localized_copy_v95(
    business_id,entity_type,entity_id,locale,name,tagline,description,
    terms,updated_by
  ) values(
    p_business,'offer',p_promotion_id,'en',btrim(p_name),
    nullif(btrim(coalesce(p_tagline,'')),''),
    btrim(p_description),nullif(btrim(coalesce(p_terms,'')),''),
    v_actor
  )
  returning * into v_copy;
  perform set_config('app.v104_promotion_copy_write','',true);

  select count(*)::integer into v_quota_used
  from public.business_customer_content_v95 content
  where content.business_id=p_business
    and content.content_type='offer'
    and content.metadata->>'schema'='nestly.promotion.v104'
    and content.metadata ? 'published_once_at';
  v_response:=jsonb_build_object(
    'id',v_content.id,
    'promotion_id',v_content.id,
    'business_id',v_content.business_id,
    'branch_id',v_content.branch_id,
    'status','draft',
    'publish_state','draft',
    'active',false,
    'display_order',v_content.display_order,
    'starts_at',v_content.starts_at,
    'ends_at',v_content.ends_at,
    'metadata',v_content.metadata,
    'content_version',v_content.version,
    'copy_version',v_copy.version,
    'name',v_copy.name,
    'tagline',v_copy.tagline,
    'description',v_copy.description,
    'terms',v_copy.terms,
    'media_version',0,
    'target_media_version',0,
    'quota_used',v_quota_used,
    'quota_limit',v_entitlement.max_published_offers,
    'item',jsonb_build_object(
      'id',v_content.id,
      'branch_id',v_content.branch_id,
      'active',false,
      'publish_state','draft',
      'starts_at',v_content.starts_at,
      'ends_at',v_content.ends_at,
      'display_order',v_content.display_order,
      'content_version',v_content.version,
      'copy_version',v_copy.version,
      'name',v_copy.name,
      'tagline',v_copy.tagline,
      'description',v_copy.description,
      'terms',v_copy.terms,
      'metadata',v_content.metadata,
      'media_version',0,
      'target_media_version',0
    )
  );
  insert into public.business_promotion_attempt_receipts_v104(
    business_id,attempt_key,promotion_id,request_payload,response_payload,
    created_by
  ) values(
    p_business,p_attempt_key,p_promotion_id,v_request,v_response,v_actor
  );
  return v_response||jsonb_build_object(
    'attempt_key',p_attempt_key,
    'replayed',false
  );
end
$$;

--
-- Name: business_create_promotion_draft_v155(uuid, uuid, uuid, text, uuid[], uuid, text, text, text, text, timestamp with time zone, timestamp with time zone, integer, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.business_create_promotion_draft_v155(p_business uuid, p_promotion_id uuid, p_attempt_key uuid, p_scope_mode text, p_branch_ids uuid[], p_operational_branch uuid, p_name text, p_tagline text, p_description text, p_terms text, p_starts_at timestamp with time zone, p_ends_at timestamp with time zone, p_display_order integer, p_cta_kind text, p_cta_label text, p_offer_facts text, p_occasion text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_result jsonb;
  v_scope jsonb;
begin
  v_result := public.business_create_promotion_draft_v104(
    p_business,p_promotion_id,p_attempt_key,null,p_name,p_tagline,
    p_description,p_terms,p_starts_at,p_ends_at,p_display_order,p_cta_kind,
    p_cta_label,p_offer_facts,p_occasion
  );
  v_scope := app.save_promotion_scope_v155(
    p_business,p_promotion_id,p_scope_mode,p_branch_ids,p_operational_branch
  );
  -- V280: save_promotion_scope_v155 bumped the row's version AFTER v104 built this payload, so
  -- what was returned here described a row that no longer existed. The client then finalized
  -- with a version one behind and was refused, every time, for every new promotion.
  v_result := app.promotion_version_sync_v280(p_business,p_promotion_id,p_attempt_key,v_result);
  return v_result || jsonb_build_object('branch_scope',v_scope);
end
$$;

--
-- Name: business_create_reward_v326(uuid, uuid, text, integer, integer, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.business_create_reward_v326(p_business uuid, p_programme uuid, p_name text, p_points integer, p_credit_cents integer DEFAULT 0, p_description text DEFAULT NULL::text, p_image_ref text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_reward_id uuid:=gen_random_uuid();
  v_name text:=nullif(btrim(coalesce(p_name,'')),'');
  v_description text:=nullif(btrim(coalesce(p_description,'')),'');
  v_kind text:=case when coalesce(p_credit_cents,0)>0 then 'credit' else 'manual_item' end;
  v_active_version uuid;
  v_sort integer;
begin
  if not app.c45_owner_loyalty_write(p_business) then
    raise exception 'owner loyalty configuration access required' using errcode='42501';
  end if;
  if v_name is null then
    raise exception 'gift name is required' using errcode='22023';
  end if;
  if p_points is null or p_points<=0 then
    raise exception 'points must be a positive number' using errcode='22023';
  end if;
  if p_credit_cents is not null and p_credit_cents<0 then
    raise exception 'credit_cents cannot be negative' using errcode='22023';
  end if;
  if not exists(select 1 from public.business_programmes spine
                 where spine.id=p_programme and spine.business_id=p_business) then
    raise exception 'programme does not belong to this business' using errcode='42501';
  end if;
  select active_config_version_id into v_active_version
    from public.businesses where id=p_business;
  if v_active_version is null then
    raise exception 'this business has no published loyalty configuration yet' using errcode='XX001';
  end if;

  select coalesce(max(sort),0)+1 into v_sort from public.loyalty_rewards where business_id=p_business;

  insert into public.loyalty_rewards(
    id,business_id,name,internal_name,customer_name,description,image_ref,fulfillment_kind,cost_points,credit_cents,
    estimated_cost_cents,active,paused,sort,programme_id,current_config_version_id
  ) values(
    v_reward_id,p_business,v_name,v_name,v_name,v_description,p_image_ref,v_kind,p_points,coalesce(p_credit_cents,0),
    coalesce(p_credit_cents,0),true,false,v_sort,p_programme,v_active_version
  );

  insert into public.loyalty_reward_versions(
    reward_id,business_id,config_version_id,internal_name,customer_name,description,image_ref,fulfillment_kind,
    cost_points,credit_cents,estimated_cost_cents,active,sort,programme_id
  ) values(
    v_reward_id,p_business,v_active_version,v_name,v_name,v_description,p_image_ref,v_kind,
    p_points,coalesce(p_credit_cents,0),coalesce(p_credit_cents,0),true,v_sort,p_programme
  );

  insert into public.audit_log(business_id,actor,action,entity,entity_id,detail)
  values(p_business,auth.uid(),'reward.created','loyalty_rewards',v_reward_id,
    jsonb_build_object('name',v_name,'cost_points',p_points,'credit_cents',coalesce(p_credit_cents,0)));

  return jsonb_build_object('status','ok','reward_id',v_reward_id,'name',v_name,
    'description',v_description,'cost_points',p_points,'credit_cents',coalesce(p_credit_cents,0));
end
$$;

--
-- Name: business_create_tier_v331(uuid, text, integer, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.business_create_tier_v331(p_business uuid, p_name text, p_threshold integer, p_multiplier numeric DEFAULT 1, p_perk_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_tier public.loyalty_tiers%rowtype;
  v_name text := nullif(btrim(coalesce(p_name,'')),'');
  v_perk_note text := nullif(btrim(coalesce(p_perk_note,'')),'');
  v_published uuid;
  v_open_draft uuid;
  v_sort integer;
begin
  if not app.c45_owner_loyalty_write(p_business) then
    raise exception 'owner loyalty configuration access required' using errcode='42501';
  end if;
  if v_name is null or char_length(v_name)>120 then
    raise exception 'invalid tier name' using errcode='22023';
  end if;
  if p_threshold is null or p_threshold<0 then
    raise exception 'invalid tier threshold' using errcode='22023';
  end if;
  if p_multiplier is null or p_multiplier<1 then
    raise exception 'invalid tier multiplier' using errcode='22023';
  end if;

  select coalesce(max(sort),0)+1 into v_sort from public.loyalty_tiers where business_id=p_business;
  insert into public.loyalty_tiers(business_id,name,threshold,points_multiplier,perk_note,sort)
  values (p_business,v_name,p_threshold,p_multiplier,v_perk_note,v_sort)
  returning * into v_tier;

  select active_config_version_id into v_published from public.businesses where id=p_business;
  if v_published is not null then
    insert into public.loyalty_tier_versions(tier_id,config_version_id,business_id,name,threshold,points_multiplier,perk_note,sort,active)
    values (v_tier.id,v_published,p_business,v_tier.name,v_tier.threshold,v_tier.points_multiplier,v_tier.perk_note,v_tier.sort,true)
    on conflict (tier_id,config_version_id) do nothing;
  end if;

  select id into v_open_draft from public.firm_config_versions
   where business_id=p_business and status='draft' limit 1;
  if v_open_draft is not null and v_open_draft is distinct from v_published then
    insert into public.loyalty_tier_versions(tier_id,config_version_id,business_id,name,threshold,points_multiplier,perk_note,sort,active)
    values (v_tier.id,v_open_draft,p_business,v_tier.name,v_tier.threshold,v_tier.points_multiplier,v_tier.perk_note,v_tier.sort,true)
    on conflict (tier_id,config_version_id) do nothing;
  end if;

  insert into public.audit_log(business_id,actor,action,entity,entity_id,detail)
  values(p_business,auth.uid(),'tier.created','loyalty_tiers',v_tier.id,
    jsonb_build_object('name',v_name,'threshold',p_threshold,'points_multiplier',p_multiplier));

  return jsonb_build_object('status','ok','tier_id',v_tier.id,'name',v_tier.name,'threshold',v_tier.threshold,'perk_note',v_tier.perk_note);
end
$$;

--
-- Name: business_delete_bringback_v361(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.business_delete_bringback_v361(p_business uuid, p_campaign uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_row public.bringback_campaigns_v361%rowtype;
begin
  if not app.c45_owner_loyalty_write(p_business) then
    raise exception 'owner loyalty configuration access required' using errcode='42501';
  end if;
  -- Soft delete only. Vouchers already issued from this campaign stay valid and redeemable:
  -- withdrawing a gift a customer has already been promised is not a UI action.
  update public.bringback_campaigns_v361 set active=false, deleted_at=now(), updated_at=now(), updated_by=auth.uid()
   where id=p_campaign and business_id=p_business and deleted_at is null
   returning * into v_row;
  if not found then raise exception 'bring-back campaign not found in this business' using errcode='42704'; end if;
  insert into public.audit_log(business_id,actor,action,entity,entity_id,detail)
  values(p_business,auth.uid(),'bringback.deleted','bringback_campaigns_v361',p_campaign,
    jsonb_build_object('name',v_row.name));
  return jsonb_build_object('status','ok','campaign_id',p_campaign,'mode','deleted');
end $$;

--
-- Name: business_delete_membership_plan_v329(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.business_delete_membership_plan_v329(p_business uuid, p_plan uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_staff uuid;
  v_plan public.membership_plans%rowtype;
begin
  if v_actor is null or not app.can_module_write(p_business, 'memberships') then
    raise exception 'active memberships-module write authorization is required'
      using errcode = '42501';
  end if;
  select s.id into v_staff from public.staff s
   where s.business_id=p_business and s.user_id=v_actor and s.active
   order by case when s.role='owner' then 0 else 1 end,s.created_at limit 1 for update;
  if not found then raise exception 'active staff authorization is required' using errcode='42501'; end if;
  update public.membership_plans
     set active=false, deleted_at=now()
   where id=p_plan and business_id=p_business and deleted_at is null
  returning * into v_plan;
  if not found then
    raise exception 'membership plan does not belong to this business, or is already deleted' using errcode='22023';
  end if;
  return jsonb_build_object('status','completed','plan_id',v_plan.id,'name',v_plan.name,
    'active',v_plan.active,'deleted_at',v_plan.deleted_at);
end
$$;

--
-- Name: business_delete_promotion_v183(uuid, uuid, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.business_delete_promotion_v183(p_business uuid, p_promotion_id uuid, p_expected_version bigint DEFAULT NULL::bigint) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_row public.business_customer_content_v95%rowtype;
  v_mode text;
begin
  if not app.can_module_write_at_v94(p_business, null, 'loyalty') then
    raise exception 'promotion write access required' using errcode='42501';
  end if;
  select * into v_row from public.business_customer_content_v95
   where business_id = p_business and id = p_promotion_id and content_type = 'offer'
   for update;
  if not found then
    raise exception 'promotion not found in this business' using errcode='42704';
  end if;
  if p_expected_version is not null and v_row.version is distinct from p_expected_version then
    raise exception 'this promotion changed in another tab; reopen it and try again'
      using errcode='40001';
  end if;

  perform set_config('app.v104_promotion_write','on',true);
  perform set_config('app.v104_promotion_copy_write','on',true);

  if coalesce(v_row.active,false) then
    v_mode := 'retired';
    update public.business_customer_content_v95
       set active=false, ends_at=least(coalesce(ends_at,now()),now()),
           version=version+1, updated_by=auth.uid(), updated_at=now()
     where id=p_promotion_id and business_id=p_business;
  else
    v_mode := 'deleted';
    delete from public.promotion_branch_scopes_v155
     where promotion_id=p_promotion_id and business_id=p_business;
    delete from public.promotion_branch_scopes_v154
     where promotion_id=p_promotion_id and business_id=p_business;
    delete from public.business_localized_copy_v95
     where business_id=p_business and entity_type='offer' and entity_id=p_promotion_id;
    delete from public.business_customer_content_v95
     where id=p_promotion_id and business_id=p_business;
  end if;

  perform set_config('app.v104_promotion_write','',true);
  perform set_config('app.v104_promotion_copy_write','',true);

  insert into public.audit_log(business_id, actor, action, entity, entity_id, meta)
  values (p_business, auth.uid(), 'promotion.'||v_mode, 'promotion', p_promotion_id,
          jsonb_build_object('was_published', coalesce(v_row.active,false)));
  return json_build_object('status','ok','mode',v_mode,'promotion_id',p_promotion_id);
end $$;

--
-- Name: FUNCTION business_delete_promotion_v183(p_business uuid, p_promotion_id uuid, p_expected_version bigint); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.business_delete_promotion_v183(p_business uuid, p_promotion_id uuid, p_expected_version bigint) IS 'v412: retire a published promotion or hard-delete a draft. Gated on the loyalty module - v183 gated on ''promotions'', which is not a registered module, so every caller including the owner was refused.';

--
-- Name: business_delete_retention_program_v332(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.business_delete_retention_program_v332(p_business uuid, p_program uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_row public.retention_programs%rowtype;
begin
  if not app.is_salon_owner(p_business) then
    raise exception 'owner only' using errcode='42501';
  end if;

  update public.retention_programs
     set active=false, deleted_at=now()
   where id=p_program and business_id=p_business and deleted_at is null
  returning * into v_row;
  if not found then
    raise exception 'retention program does not belong to this business, or is already deleted' using errcode='22023';
  end if;

  -- app.on_sale_recorded / public.issue_campaign_offer both now check retention_programs.deleted_at
  -- directly (see migration header) -- the update above is ALREADY sufficient to stop new reward
  -- grants immediately, because retention_program_versions rows on an already-published config
  -- version are immutable (trg_guard_retention_program_version) and can never be forced false
  -- directly. This second write is a UI-consistency nicety, not the resurrection guard itself:
  -- every currently-open draft (there is normally at most one, but this updates all of them, not
  -- just one) gets its OWN editable retention_program_versions row set to active=false too, so the
  -- Bring-back editor immediately shows the rule as off if the owner has a draft open right now.
  -- publish_loyalty_config is separately, durably patched to force active=false at every future
  -- publish regardless of what any draft's row says (see its own comment) -- that is what actually
  -- makes this delete permanent.
  update public.retention_program_versions rpv
     set active=false
    from public.firm_config_versions fcv
   where fcv.id=rpv.config_version_id
     and fcv.business_id=p_business
     and fcv.status='draft'
     and rpv.program_id=p_program
     and rpv.business_id=p_business
     and rpv.active;

  insert into public.audit_log(business_id,actor,action,entity,entity_id,detail)
  values(p_business,auth.uid(),'DELETE_RETENTION_PROGRAM','retention_programs',p_program,
    jsonb_build_object('name',v_row.name,'goal_visits',v_row.goal_visits,'period_days',v_row.period_days));

  return jsonb_build_object('status','ok','program_id',p_program,'mode','deleted');
end
$$;

--
-- Name: business_delete_reward_v326(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.business_delete_reward_v326(p_business uuid, p_reward uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_row public.loyalty_rewards%rowtype;
  v_draft_version uuid;
begin
  if not app.c45_owner_loyalty_write(p_business) then
    raise exception 'owner loyalty configuration access required' using errcode='42501';
  end if;
  select * into v_row from public.loyalty_rewards
   where id=p_reward and business_id=p_business and active
   for update;
  if not found then
    raise exception 'gift not found in this business' using errcode='42704';
  end if;

  update public.loyalty_rewards set active=false, paused=false
   where id=p_reward and business_id=p_business;

  -- V326: keep any currently OPEN draft's own version row in sync so that publishing an
  -- unrelated draft later cannot resurrect this delete. A *published* version row cannot be
  -- touched here (trg_loyalty_reward_versions_immutable) and does not need to be — nothing reads
  -- loyalty_reward_versions.active off a published row as a delete gate outside of the redeem
  -- paths, which now check loyalty_rewards.active/paused directly (see app.redeem_reward_core).
  select id into v_draft_version from public.firm_config_versions
   where business_id=p_business and status='draft' limit 1;
  if v_draft_version is not null then
    update public.loyalty_reward_versions set active=false
     where reward_id=p_reward and business_id=p_business
       and config_version_id=v_draft_version and active;
  end if;

  insert into public.audit_log(business_id,actor,action,entity,entity_id,detail)
  values(p_business,auth.uid(),'reward.deleted','loyalty_rewards',p_reward,
    jsonb_build_object('name',coalesce(v_row.customer_name,v_row.name)));

  return jsonb_build_object('status','ok','reward_id',p_reward,'mode','deleted');
end
$$;

--
-- Name: business_delete_tier_v331(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.business_delete_tier_v331(p_business uuid, p_tier uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_row public.loyalty_tiers%rowtype;
  v_remaining integer;
begin
  if not app.c45_owner_loyalty_write(p_business) then
    raise exception 'owner loyalty configuration access required' using errcode='42501';
  end if;
  select * into v_row from public.loyalty_tiers
   where id=p_tier and business_id=p_business and deleted_at is null
   for update;
  if not found then
    raise exception 'tier not found in this business' using errcode='42704';
  end if;

  -- Mirrors the wizard's own existing "keep at least one tier" guard (app/app.js tiersStepHtml)
  -- for a live tier programme, now enforced server-side for the immediate-write path too.
  select count(*) into v_remaining from public.loyalty_tiers
   where business_id=p_business and deleted_at is null and not paused and id<>p_tier;
  if v_remaining=0 and exists(
    select 1 from public.business_programmes spine
     where spine.business_id=p_business and spine.kind='tiers' and spine.active
  ) then
    raise exception 'at least one tier must stay on for a live tier programme' using errcode='23514';
  end if;

  update public.loyalty_tiers set paused=true, deleted_at=now()
   where id=p_tier and business_id=p_business;

  insert into public.audit_log(business_id,actor,action,entity,entity_id,detail)
  values(p_business,auth.uid(),'tier.deleted','loyalty_tiers',p_tier,
    jsonb_build_object('name',v_row.name,'threshold',v_row.threshold));

  return jsonb_build_object('status','ok','tier_id',p_tier,'mode','deleted');
end
$$;

--
-- Name: business_ensure_customer_join_qr_v91(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.business_ensure_customer_join_qr_v91(p_business uuid, p_expires_at timestamp with time zone DEFAULT (now() + '365 days'::interval)) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'extensions', 'pg_temp'
    AS $$
declare v_existing record; v_created jsonb;
begin
  if not (app.is_salon_owner(p_business) or app.is_super_admin()) then
    raise exception 'business owner access is required' using errcode='42501';
  end if;
  if p_expires_at is not null and p_expires_at <= now()+interval '5 minutes' then
    raise exception 'join QR expiry must be at least 5 minutes away' using errcode='22023';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('v90:join-qr:'||p_business::text,0));

  select q.id,q.expires_at,q.token_version into v_existing
  from public.business_customer_join_qr_v89 q
  where q.business_id=p_business and q.status='active' and q.expires_at>now()
  order by q.expires_at desc,q.id desc
  limit 1;

  if found and v_existing.token_version is not null then
    -- Keep a printed poster alive: an active derived QR never ages out.
    if v_existing.expires_at < now()+interval '50 years' then
      update public.business_customer_join_qr_v89
         set expires_at=created_at+interval '100 years'
       where id=v_existing.id
      returning expires_at into v_existing.expires_at;
    end if;
    return jsonb_build_object(
      'business_id',p_business,'created',false,'qr_id',v_existing.id,
      'expires_at',v_existing.expires_at,
      'token_version',v_existing.token_version,
      'join_token',app.v197_join_token(p_business,v_existing.token_version)
    );
  end if;

  -- Either nothing active, or a pre-v197 random token that cannot be shown
  -- again. Both resolve to issuing one derived QR — the last change there will
  -- ever be for this firm.
  if found then
    update public.business_customer_join_qr_v89
       set status='revoked',revoked_at=now()
     where business_id=p_business and status='active';
  end if;
  v_created := public.business_create_customer_join_qr_v89(p_business,p_expires_at);
  return v_created||jsonb_build_object(
    'business_id',p_business,'created',true,
    'replaced_legacy_token',found
  );
end $$;

--
-- Name: business_finalize_promotion_v104(uuid, uuid, uuid, text, text, text, text, timestamp with time zone, timestamp with time zone, integer, text, text, text, text, boolean, text, text, integer, integer, text, bigint, bigint, bigint, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.business_finalize_promotion_v104(p_business uuid, p_promotion_id uuid, p_branch uuid, p_name text, p_tagline text, p_description text, p_terms text, p_starts_at timestamp with time zone, p_ends_at timestamp with time zone, p_display_order integer, p_cta_kind text, p_cta_label text, p_offer_facts text, p_occasion text, p_publish boolean, p_object_path text, p_mime_type text, p_width_px integer, p_height_px integer, p_alt_en text, p_expected_content_version bigint, p_expected_copy_version bigint, p_expected_target_media_version bigint, p_attempt_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid:=auth.uid();
  v_content public.business_customer_content_v95%rowtype;
  v_copy public.business_localized_copy_v95%rowtype;
  v_target_media public.business_media_assets_v95%rowtype;
  v_applicable_media public.business_media_assets_v95%rowtype;
  v_receipt public.business_promotion_attempt_receipts_v104%rowtype;
  v_entitlement record;
  v_request jsonb;
  v_response jsonb;
  v_metadata jsonb;
  v_previous_object_path text;
  v_media_url text;
  v_media_alt text;
  v_quota_used integer:=0;
  v_published_count integer:=0;
  v_first_adoption boolean;
begin
  if v_actor is null then
    raise exception 'authenticated_session_required' using errcode='28000';
  end if;
  if p_business is null or p_promotion_id is null or p_attempt_key is null then
    raise exception 'valid_promotion_attempt_identity_required'
      using errcode='22023';
  end if;

  -- V281 fast-fail: reject a stale-version retry before the advisory lock and the
  -- 8 table reads. Two indexed existence checks only. Same 40001 as the
  -- authoritative check below; a real replay (receipt present) skips this.
  if p_expected_content_version is not null
     and not exists(
       select 1 from public.business_promotion_attempt_receipts_v104 receipt
       where receipt.business_id=p_business and receipt.attempt_key=p_attempt_key)
     and exists(
       select 1 from public.business_customer_content_v95 content
       where content.id=p_promotion_id and content.business_id=p_business
         and content.content_type='offer'
         and content.version <> p_expected_content_version)
  then
    raise exception 'promotion_version_conflict' using errcode='40001';
  end if;

  perform app.v104_lock_promotion_business(p_business);
  v_request:=jsonb_build_object(
    'promotion_id',p_promotion_id,
    'branch_id',p_branch,
    'name',p_name,
    'tagline',p_tagline,
    'description',p_description,
    'terms',p_terms,
    'starts_at',p_starts_at,
    'ends_at',p_ends_at,
    'display_order',p_display_order,
    'cta_kind',p_cta_kind,
    'cta_label',p_cta_label,
    'offer_facts',p_offer_facts,
    'occasion',p_occasion,
    'publish',p_publish,
    'object_path',p_object_path,
    'mime_type',p_mime_type,
    'width_px',p_width_px,
    'height_px',p_height_px,
    'alt_en',p_alt_en,
    'expected_content_version',p_expected_content_version,
    'expected_copy_version',p_expected_copy_version,
    'expected_target_media_version',p_expected_target_media_version
  );
  select * into v_receipt
  from public.business_promotion_attempt_receipts_v104 receipt
  where receipt.business_id=p_business
    and receipt.attempt_key=p_attempt_key
  for update;
  if found then
    if v_receipt.created_by is distinct from v_actor
       and not app.is_salon_owner(p_business)
       and not app.is_super_admin()
    then
      raise exception 'promotion_receipt_replay_forbidden'
        using errcode='42501';
    end if;
    if v_receipt.request_payload<>v_request then
      raise exception 'promotion_attempt_key_reused'
        using errcode='23505';
    end if;
    return v_receipt.response_payload||jsonb_build_object(
      'attempt_key',p_attempt_key,
      'replayed',true
    );
  end if;

  if not app.is_salon_owner(p_business) then
    raise exception 'owner_required' using errcode='42501';
  end if;
  if p_branch is not null
     or p_publish is null
     or p_expected_content_version is null
     or p_expected_copy_version is null
     or p_expected_target_media_version is null
     or p_display_order is null
     or p_display_order not between 0 and 10000
     or p_cta_kind is null
     or p_cta_kind not in ('book','programme','counter')
     or length(btrim(coalesce(p_cta_label,''))) not between 2 and 40
     or length(btrim(coalesce(p_name,''))) not between 2 and 70
     or (
       nullif(btrim(coalesce(p_tagline,'')),'') is not null
       and length(btrim(p_tagline)) not between 2 and 120
     )
     or length(btrim(coalesce(p_description,''))) not between 10 and 600
     or (
       nullif(btrim(coalesce(p_terms,'')),'') is not null
       and length(btrim(p_terms))>1000
     )
     or length(btrim(coalesce(p_offer_facts,''))) not between 2 and 500
     or (
       nullif(btrim(coalesce(p_occasion,'')),'') is not null
       and length(btrim(p_occasion)) not between 2 and 80
     )
     or p_ends_at is null
     or (p_publish and p_ends_at<=now())
     or (p_starts_at is not null and p_ends_at<=p_starts_at)
     or not exists(
       select 1 from public.businesses business where business.id=p_business
     )
     or (
       p_object_path is null
       and (
         p_mime_type is not null
         or p_width_px is not null
         or p_height_px is not null
         or p_alt_en is not null
       )
     )
     or (
       p_object_path is not null
       and (
         p_mime_type is null
         or length(btrim(coalesce(p_alt_en,''))) not between 1 and 240
       )
     )
  then
    raise exception 'valid_promotion_finalize_fields_required'
      using errcode='22023';
  end if;

  if p_object_path is not null
     and not app.v95_storage_object_is_publishable(
       p_business,'offer',p_object_path,p_mime_type
     )
  then
    raise exception 'verified_storage_object_required' using errcode='22023';
  end if;

  select * into v_content
  from public.business_customer_content_v95 content
  where content.id=p_promotion_id
    and content.business_id=p_business
    and content.content_type='offer'
  for update;
  if not found then
    raise exception 'promotion_not_found' using errcode='22023';
  end if;
  if v_content.version<>p_expected_content_version then
    raise exception 'promotion_version_conflict' using errcode='40001';
  end if;

  select * into v_copy
  from public.business_localized_copy_v95 copy
  where copy.business_id=p_business
    and copy.entity_type='offer'
    and copy.entity_id=p_promotion_id
    and copy.locale='en'
  for update;
  if not found or v_copy.version<>p_expected_copy_version then
    raise exception 'promotion_copy_version_conflict' using errcode='40001';
  end if;

  select * into v_entitlement
  from app.v104_effective_promotion_entitlement(p_business);
  v_first_adoption:=p_publish
    and not(v_content.metadata ? 'published_once_at');
  if v_first_adoption then
    if now()>=v_entitlement.complimentary_until then
      raise exception 'promotion_publishing_window_closed' using errcode='42501';
    end if;
    select count(*)::integer into v_quota_used
    from public.business_customer_content_v95 content
    where content.business_id=p_business
      and content.content_type='offer'
      and content.metadata->>'schema'='nestly.promotion.v104'
      and content.metadata ? 'published_once_at';
    if v_quota_used>=v_entitlement.max_published_offers then
      raise exception 'promotion_publish_limit_reached' using errcode='23514';
    end if;
  end if;

  select * into v_target_media
  from public.business_media_assets_v95 asset
  where asset.business_id=p_business
    and asset.asset_kind='offer'
    and asset.entity_id=p_promotion_id
    and asset.branch_id is not distinct from p_branch
  for update;

  if found then
    if v_target_media.version<>p_expected_target_media_version then
      raise exception 'promotion_target_media_version_conflict'
        using errcode='40001';
    end if;
    v_previous_object_path:=v_target_media.object_path;
  elsif p_expected_target_media_version<>0 then
    raise exception 'promotion_target_media_version_conflict'
      using errcode='40001';
  end if;

  if p_object_path is not null then
    perform set_config('app.v104_promotion_media_write','on',true);
    perform public.business_upsert_media_asset_v95(
      p_business,'offer',p_promotion_id,p_branch,p_object_path,p_mime_type,
      p_width_px,p_height_px,btrim(p_alt_en),null,false,
      coalesce(v_target_media.version,0)
    );
    update public.business_media_assets_v95 asset
    set customer_visible=p_publish
    where asset.business_id=p_business
      and asset.asset_kind='offer'
      and asset.entity_id=p_promotion_id
      and asset.branch_id is not distinct from p_branch
    returning * into v_applicable_media;
    perform set_config('app.v104_promotion_media_write','',true);
  else
    select * into v_applicable_media
    from public.business_media_assets_v95 asset
    where asset.business_id=p_business
      and asset.asset_kind='offer'
      and asset.entity_id=p_promotion_id
      and (
        asset.branch_id is not distinct from p_branch
        or (p_branch is not null and asset.branch_id is null)
      )
    order by (asset.branch_id is not distinct from p_branch) desc,
      asset.updated_at desc,asset.id
    limit 1
    for update;
    if not found and p_publish then
      raise exception 'promotion_image_required' using errcode='23514';
    end if;
    if found and p_publish and not v_applicable_media.customer_visible then
      perform set_config('app.v104_promotion_media_write','on',true);
      update public.business_media_assets_v95
      set customer_visible=true,
          version=version+1,
          updated_by=v_actor,
          updated_at=now()
      where id=v_applicable_media.id
      returning * into v_applicable_media;
      perform set_config('app.v104_promotion_media_write','',true);
    end if;
  end if;

  v_metadata:=jsonb_strip_nulls(jsonb_build_object(
    'schema','nestly.promotion.v104',
    'cta',jsonb_build_object(
      'kind',p_cta_kind,
      'label',btrim(p_cta_label)
    ),
    'offer_facts',btrim(p_offer_facts),
    'occasion',nullif(btrim(coalesce(p_occasion,'')),''),
    'published_once_at',case when p_publish then coalesce(
      v_content.metadata->'published_once_at',to_jsonb(now())
    ) else v_content.metadata->'published_once_at' end
  ));

  perform set_config('app.v104_promotion_write','on',true);
  update public.business_customer_content_v95
  set branch_id=p_branch,
      active=p_publish,
      display_order=p_display_order,
      starts_at=p_starts_at,
      ends_at=p_ends_at,
      metadata=v_metadata,
      version=version+1,
      updated_by=v_actor,
      updated_at=now()
  where id=p_promotion_id
  returning * into v_content;
  perform set_config('app.v104_promotion_write','',true);

  perform set_config('app.v104_promotion_copy_write','on',true);
  update public.business_localized_copy_v95
  set name=btrim(p_name),
      tagline=nullif(btrim(coalesce(p_tagline,'')),''),
      description=btrim(p_description),
      terms=nullif(btrim(coalesce(p_terms,'')),''),
      version=version+1,
      updated_by=v_actor,
      updated_at=now()
  where business_id=p_business
    and entity_type='offer'
    and entity_id=p_promotion_id
    and locale='en'
  returning * into v_copy;
  perform set_config('app.v104_promotion_copy_write','',true);

  select count(*)::integer into v_quota_used
  from public.business_customer_content_v95 content
  where content.business_id=p_business
    and content.content_type='offer'
    and content.metadata->>'schema'='nestly.promotion.v104'
    and content.metadata ? 'published_once_at';
  select count(*)::integer into v_published_count
  from public.business_customer_content_v95 content
  where content.business_id=p_business
    and content.content_type='offer'
    and content.active
    and content.ends_at>now();

  v_media_url:=app.v95_public_media_url(v_applicable_media.object_path);
  v_media_alt:=v_applicable_media.alt_en;
  v_response:=jsonb_build_object(
    'id',v_content.id,
    'promotion_id',v_content.id,
    'business_id',v_content.business_id,
    'branch_id',v_content.branch_id,
    'status',case when p_publish then 'published' else 'draft' end,
    'publish_state',case when p_publish then 'published' else 'draft' end,
    'active',p_publish,
    'display_order',v_content.display_order,
    'starts_at',v_content.starts_at,
    'ends_at',v_content.ends_at,
    'metadata',v_content.metadata,
    'content_version',v_content.version,
    'copy_version',v_copy.version,
    'name',v_copy.name,
    'tagline',v_copy.tagline,
    'description',v_copy.description,
    'terms',v_copy.terms,
    'image_url',v_media_url,
    'image_alt',v_media_alt,
    'media_asset_id',v_applicable_media.id,
    'media_version',v_applicable_media.version,
    'target_media_version',v_applicable_media.version,
    'quota_used',v_quota_used,
    'quota_limit',v_entitlement.max_published_offers,
    'published_count',v_published_count,
    'previous_object_path',case
      when v_previous_object_path is distinct from v_applicable_media.object_path
      then v_previous_object_path else null end,
    'item',jsonb_build_object(
      'id',v_content.id,
      'branch_id',v_content.branch_id,
      'active',p_publish,
      'publish_state',case when p_publish then 'published' else 'draft' end,
      'starts_at',v_content.starts_at,
      'ends_at',v_content.ends_at,
      'display_order',v_content.display_order,
      'content_version',v_content.version,
      'copy_version',v_copy.version,
      'name',v_copy.name,
      'tagline',v_copy.tagline,
      'description',v_copy.description,
      'terms',v_copy.terms,
      'metadata',v_content.metadata,
      'image_url',v_media_url,
      'image_alt',v_media_alt,
      'media_asset_id',v_applicable_media.id,
      'media_version',v_applicable_media.version,
      'target_media_version',v_applicable_media.version
    )
  );

  insert into public.business_promotion_attempt_receipts_v104(
    business_id,attempt_key,promotion_id,request_payload,response_payload,
    created_by
  ) values(
    p_business,p_attempt_key,p_promotion_id,v_request,v_response,v_actor
  );

  return v_response||jsonb_build_object(
    'attempt_key',p_attempt_key,
    'replayed',false
  );
end
$$;

--
-- Name: business_finalize_promotion_v154(uuid, uuid, text, uuid[], uuid, text, text, text, text, timestamp with time zone, timestamp with time zone, integer, text, text, text, text, boolean, text, text, integer, integer, text, bigint, bigint, bigint, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.business_finalize_promotion_v154(p_business uuid, p_promotion_id uuid, p_scope_mode text, p_branch_ids uuid[], p_operational_branch uuid, p_name text, p_tagline text, p_description text, p_terms text, p_starts_at timestamp with time zone, p_ends_at timestamp with time zone, p_display_order integer, p_cta_kind text, p_cta_label text, p_offer_facts text, p_occasion text, p_publish boolean, p_object_path text, p_mime_type text, p_width_px integer, p_height_px integer, p_alt_en text, p_expected_content_version bigint, p_expected_copy_version bigint, p_expected_target_media_version bigint, p_attempt_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_result   jsonb;
  v_scope    jsonb;
  v_failures integer;
  v_reason   text;
  v_state    text;
  v_actor    uuid := auth.uid();
  /* Three sends of one receipt, matching the client-side ceiling in v373. */
  c_max constant integer := 3;
  /* Every refusal business_finalize_promotion_v104 raises by name. Anything not in this list is
     not ours and must keep raising. */
  c_definitive constant text[] := array[
    'promotion_version_conflict',
    'promotion_copy_version_conflict',
    'promotion_target_media_version_conflict',
    'valid_promotion_attempt_identity_required',
    'valid_promotion_finalize_fields_required',
    'verified_storage_object_required',
    'promotion_not_found',
    'promotion_image_required',
    'promotion_publish_limit_reached',
    'promotion_publishing_window_closed',
    'owner_required',
    'promotion_receipt_replay_forbidden',
    'promotion_attempt_key_reused',
    'authenticated_session_required'
  ];
begin
  select refusal.failures, refusal.last_reason
    into v_failures, v_reason
    from public.promotion_finalize_refusals_v378 refusal
   where refusal.business_id  = p_business
     and refusal.promotion_id = p_promotion_id
     and refusal.attempt_key  = p_attempt_key;

  /* Past the ceiling nothing is executed: one indexed lookup answers, and the finalize pipeline —
     the version reads, the storage verification, the scope write — never runs. */
  if coalesce(v_failures, 0) >= c_max then
    return jsonb_build_object(
      'ok', false, 'blocked', true,
      'code', 'promotion_finalize_rejected',
      'reason', v_reason,
      'attempt_key', p_attempt_key,
      'promotion_id', p_promotion_id,
      'failures', v_failures);
  end if;

  begin
    v_result := public.business_finalize_promotion_v104(
      p_business,p_promotion_id,null,p_name,p_tagline,p_description,p_terms,
      p_starts_at,p_ends_at,p_display_order,p_cta_kind,p_cta_label,
      p_offer_facts,p_occasion,p_publish,p_object_path,p_mime_type,
      p_width_px,p_height_px,p_alt_en,p_expected_content_version,
      p_expected_copy_version,p_expected_target_media_version,p_attempt_key
    );
    v_scope := app.save_promotion_scope_v154(
      p_business,p_promotion_id,p_scope_mode,p_branch_ids,p_operational_branch
    );
  exception when others then
    get stacked diagnostics v_reason = message_text, v_state = returned_sqlstate;
    /* Not one of ours: re-raise unchanged. A deadlock, a real serialization failure or a bug must
       never be reported to a caller as a handled refusal. */
    if not (v_reason = any(c_definitive)) then
      raise;
    end if;
    /* The subtransaction above has rolled back; this write is in the OUTER transaction and so it
       commits with the refusal we return. That is the whole point — the abort used to erase both
       the evidence and any chance of counting the attempt. */
    insert into public.promotion_finalize_refusals_v378 as refusal
      (business_id, promotion_id, attempt_key, actor, failures, last_reason, last_sqlstate)
    values
      (p_business, p_promotion_id, p_attempt_key, v_actor, 1, v_reason, v_state)
    on conflict (business_id, promotion_id, attempt_key) do update
      set failures       = refusal.failures + 1,
          last_reason    = excluded.last_reason,
          last_sqlstate  = excluded.last_sqlstate,
          last_failed_at = now(),
          actor          = coalesce(refusal.actor, excluded.actor);
    return jsonb_build_object(
      'ok', false, 'blocked', true,
      'code', 'promotion_finalize_rejected',
      'reason', v_reason,
      'attempt_key', p_attempt_key,
      'promotion_id', p_promotion_id);
  end;

  /* A success releases the key: the same promotion may be edited and published again afterwards
     without inheriting a count from an earlier failed attempt. */
  delete from public.promotion_finalize_refusals_v378
   where business_id  = p_business
     and promotion_id = p_promotion_id
     and attempt_key  = p_attempt_key;

  return v_result || jsonb_build_object('branch_scope', v_scope);
end
$$;

--
-- Name: business_finalize_promotion_v155(uuid, uuid, text, uuid[], uuid, text, text, text, text, timestamp with time zone, timestamp with time zone, integer, text, text, text, text, boolean, text, text, integer, integer, text, bigint, bigint, bigint, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.business_finalize_promotion_v155(p_business uuid, p_promotion_id uuid, p_scope_mode text, p_branch_ids uuid[], p_operational_branch uuid, p_name text, p_tagline text, p_description text, p_terms text, p_starts_at timestamp with time zone, p_ends_at timestamp with time zone, p_display_order integer, p_cta_kind text, p_cta_label text, p_offer_facts text, p_occasion text, p_publish boolean, p_object_path text, p_mime_type text, p_width_px integer, p_height_px integer, p_alt_en text, p_expected_content_version bigint, p_expected_copy_version bigint, p_expected_target_media_version bigint, p_attempt_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_result   jsonb;
  v_scope    jsonb;
  v_failures integer;
  v_reason   text;
  v_state    text;
  v_actor    uuid := auth.uid();
  /* Three sends of one receipt, matching the client-side ceiling in v373. */
  c_max constant integer := 3;
  /* Every refusal business_finalize_promotion_v104 raises by name. Anything not in this list is
     not ours and must keep raising. */
  c_definitive constant text[] := array[
    'promotion_version_conflict',
    'promotion_copy_version_conflict',
    'promotion_target_media_version_conflict',
    'valid_promotion_attempt_identity_required',
    'valid_promotion_finalize_fields_required',
    'verified_storage_object_required',
    'promotion_not_found',
    'promotion_image_required',
    'promotion_publish_limit_reached',
    'promotion_publishing_window_closed',
    'owner_required',
    'promotion_receipt_replay_forbidden',
    'promotion_attempt_key_reused',
    'authenticated_session_required'
  ];
begin
  select refusal.failures, refusal.last_reason
    into v_failures, v_reason
    from public.promotion_finalize_refusals_v378 refusal
   where refusal.business_id  = p_business
     and refusal.promotion_id = p_promotion_id
     and refusal.attempt_key  = p_attempt_key;

  /* Past the ceiling nothing is executed: one indexed lookup answers, and the finalize pipeline —
     the version reads, the storage verification, the scope write — never runs. */
  if coalesce(v_failures, 0) >= c_max then
    return jsonb_build_object(
      'ok', false, 'blocked', true,
      'code', 'promotion_finalize_rejected',
      'reason', v_reason,
      'attempt_key', p_attempt_key,
      'promotion_id', p_promotion_id,
      'failures', v_failures);
  end if;

  begin
    v_result := public.business_finalize_promotion_v104(
      p_business,p_promotion_id,null,p_name,p_tagline,p_description,p_terms,
      p_starts_at,p_ends_at,p_display_order,p_cta_kind,p_cta_label,
      p_offer_facts,p_occasion,p_publish,p_object_path,p_mime_type,
      p_width_px,p_height_px,p_alt_en,p_expected_content_version,
      p_expected_copy_version,p_expected_target_media_version,p_attempt_key
    );
    v_scope := app.save_promotion_scope_v155(
      p_business,p_promotion_id,p_scope_mode,p_branch_ids,p_operational_branch
    );
    -- V280: same correction on the finalize path. Publishing twice in a row without leaving the
    -- editor used to hit the identical stale-version refusal.
    v_result := app.promotion_version_sync_v280(p_business,p_promotion_id,p_attempt_key,v_result);
  exception when others then
    get stacked diagnostics v_reason = message_text, v_state = returned_sqlstate;
    /* Not one of ours: re-raise unchanged. A deadlock, a real serialization failure or a bug must
       never be reported to a caller as a handled refusal. */
    if not (v_reason = any(c_definitive)) then
      raise;
    end if;
    /* The subtransaction above has rolled back; this write is in the OUTER transaction and so it
       commits with the refusal we return. That is the whole point — the abort used to erase both
       the evidence and any chance of counting the attempt. */
    insert into public.promotion_finalize_refusals_v378 as refusal
      (business_id, promotion_id, attempt_key, actor, failures, last_reason, last_sqlstate)
    values
      (p_business, p_promotion_id, p_attempt_key, v_actor, 1, v_reason, v_state)
    on conflict (business_id, promotion_id, attempt_key) do update
      set failures       = refusal.failures + 1,
          last_reason    = excluded.last_reason,
          last_sqlstate  = excluded.last_sqlstate,
          last_failed_at = now(),
          actor          = coalesce(refusal.actor, excluded.actor);
    return jsonb_build_object(
      'ok', false, 'blocked', true,
      'code', 'promotion_finalize_rejected',
      'reason', v_reason,
      'attempt_key', p_attempt_key,
      'promotion_id', p_promotion_id);
  end;

  /* A success releases the key: the same promotion may be edited and published again afterwards
     without inheriting a count from an earlier failed attempt. */
  delete from public.promotion_finalize_refusals_v378
   where business_id  = p_business
     and promotion_id = p_promotion_id
     and attempt_key  = p_attempt_key;

  return v_result || jsonb_build_object('branch_scope', v_scope);
end
$$;

--
-- Name: business_get_catalogue_media_versions_v158(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.business_get_catalogue_media_versions_v158(p_business uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_items jsonb;
begin
  if p_business is null then
    raise exception 'business_required' using errcode='22023';
  end if;
  if not (
    app.is_super_admin()
    or app.is_salon_owner(p_business)
  ) then
    raise exception 'owner_required' using errcode='42501';
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
    'asset_kind',asset.asset_kind,
    'entity_id',asset.entity_id,
    'version',asset.version,
    'url',app.v95_public_media_url(asset.object_path)
  ) order by asset.asset_kind,asset.entity_id),'[]'::jsonb)
  into v_items
  from public.business_media_assets_v95 asset
  where asset.business_id=p_business
    and asset.asset_kind in ('service','product')
    and asset.branch_id is null
    and asset.customer_visible;

  return jsonb_build_object('items',v_items);
end
$$;

--
-- Name: business_get_checkout_catalogue_v94(uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.business_get_checkout_catalogue_v94(p_business uuid, p_branch uuid, p_include_inactive boolean) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_branch uuid:=p_branch;
  v_setting public.business_checkout_catalogue_settings_v94%rowtype;
  v_branches jsonb;
  v_items jsonb;
begin
  if p_include_inactive is null then
    raise exception 'include_inactive_required' using errcode='22023';
  end if;
  if v_branch is null then
    select branch.id into v_branch
    from public.branches branch
    where branch.business_id=p_business and branch.active
    order by branch.is_default desc,branch.created_at,branch.id
    limit 1;
  end if;
  if v_branch is null or not exists(
    select 1 from public.branches branch
    where branch.id=v_branch and branch.business_id=p_business and branch.active
  ) then
    raise exception 'active_branch_required' using errcode='22023';
  end if;
  if not (
    app.is_super_admin()
    or app.can_module_read_at_v94(p_business,v_branch,'sales')
    or app.can_module_read_at_v94(p_business,v_branch,'till')
  ) then
    raise exception 'checkout_catalogue_access_required' using errcode='42501';
  end if;
  if p_include_inactive and not (
    app.is_super_admin() or app.is_salon_owner(p_business)
  ) then
    raise exception 'owner_required_for_inactive_catalogue' using errcode='42501';
  end if;

  select * into v_setting
  from public.business_checkout_catalogue_settings_v94
  where business_id=p_business;
  if not found then
    raise exception 'business_not_found' using errcode='22023';
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
    'id',branch.id,'name',branch.name,'is_default',branch.is_default
  ) order by branch.is_default desc,branch.name,branch.id),'[]'::jsonb)
  into v_branches
  from public.branches branch
  where branch.business_id=p_business and branch.active
    and (
      app.is_super_admin()
      or app.can_see_branch(p_business,branch.id)
    );

  with catalogue as (
    select
      'service'::text item_type,service.id item_id,service.name,
      service.price_cents unit_cents,service.active source_active,
      coalesce(item.checkout_active,true) checkout_active,
      (
        not exists(
          select 1 from public.service_branches configured
          where configured.business_id=p_business
            and configured.service_id=service.id
        )
        or exists(
          select 1 from public.service_branches available
          where available.business_id=p_business
            and available.service_id=service.id
            and available.branch_id=v_branch
        )
      ) branch_available,
      coalesce(item.version,0) version,
      app.v95_public_media_url(service_asset.object_path) image_url
    from public.services service
    left join public.business_checkout_catalogue_items_v94 item
      on item.business_id=p_business and item.item_type='service'
      and item.item_id=service.id
    left join public.business_media_assets_v95 service_asset
      on service_asset.business_id=p_business
      and service_asset.asset_kind='service'
      and service_asset.entity_id=service.id
      and service_asset.branch_id is null
      and service_asset.customer_visible
    where service.business_id=p_business
    union all
    select
      'product'::text,product.id,product.name,
      product.retail_price_cents,product.active,
      coalesce(item.checkout_active,true),true,
      coalesce(item.version,0),
      app.v95_public_media_url(product_asset.object_path)
    from public.products product
    left join public.business_checkout_catalogue_items_v94 item
      on item.business_id=p_business and item.item_type='product'
      and item.item_id=product.id
    left join public.business_media_assets_v95 product_asset
      on product_asset.business_id=p_business
      and product_asset.asset_kind='product'
      and product_asset.entity_id=product.id
      and product_asset.branch_id is null
      and product_asset.customer_visible
    where product.business_id=p_business
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'item_type',item_type,'item_id',item_id,'name',name,
    'unit_cents',unit_cents,'checkout_active',checkout_active,
    'branch_available',branch_available,'version',version,
    'image_url',image_url
  ) order by item_type,name,item_id),'[]'::jsonb)
  into v_items
  from catalogue
  where p_include_inactive
     or (source_active and checkout_active and branch_available);

  return jsonb_build_object(
    'platform_allowed',v_setting.platform_allowed,
    'enabled',v_setting.platform_allowed and v_setting.owner_enabled,
    'settings_version',v_setting.version,
    'selected_branch_id',v_branch,
    'branches',v_branches,
    'items',v_items
  );
end
$$;

--
-- Name: business_get_checkout_preferences_v102(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.business_get_checkout_preferences_v102(p_business uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_gift boolean;
  v_package_points boolean;
begin
  if not (
    app.is_super_admin()
    or app.can_module_read(p_business,'till')
    or app.can_module_read(p_business,'sales')
    or app.can_module_read(p_business,'packages')
    or app.can_module_read(p_business,'giftcards')
  ) then
    raise exception 'checkout_preferences_access_required' using errcode='42501';
  end if;
  select business.gift_card_sales_enabled
  into v_gift
  from public.businesses business
  where business.id=p_business;
  if not found then
    raise exception 'business_not_found' using errcode='22023';
  end if;
  select policy.earns_points into v_package_points
  from app.sale_policy(p_business,'package') policy;
  return jsonb_build_object(
    'status','available',
    'gift_card_sales_enabled',coalesce(v_gift,false),
    'package_earns_points',coalesce(v_package_points,true)
  );
end
$$;

--
-- Name: business_get_customer_capabilities_v89(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.business_get_customer_capabilities_v89(p_business uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_result jsonb;
begin
  if not (app.is_salon_member(p_business) or app.is_super_admin()) then
    raise exception 'business staff access is required' using errcode='42501';
  end if;
  select jsonb_build_object(
    'business_id',p_business,
    'booking_enabled',coalesce(capability.booking_enabled,false)
      and app.v89_business_module_enabled(p_business,'bookings'),
    'redemption_enabled',coalesce(capability.redemption_enabled,false)
      and app.v89_business_module_enabled(p_business,'loyalty'),
    'appointment_changes_enabled',
      coalesce(capability.appointment_changes_enabled,false)
      and app.v89_business_module_enabled(p_business,'appointments'),
    'configured',jsonb_build_object(
      'booking_enabled',coalesce(capability.booking_enabled,false),
      'redemption_enabled',coalesce(capability.redemption_enabled,false),
      'appointment_changes_enabled',
        coalesce(capability.appointment_changes_enabled,false))
  ) into v_result
  from (select p_business business_id) requested
  left join public.business_customer_capabilities_v89 capability
    on capability.business_id=requested.business_id;
  return v_result;
end
$$;

--
-- Name: business_get_customer_join_qr_status_v91(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.business_get_customer_join_qr_status_v91(p_business uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_count integer; v_expires_at timestamptz; v_version integer; v_id uuid;
begin
  if not (app.is_salon_owner(p_business) or app.is_super_admin()) then
    raise exception 'business owner access is required' using errcode='42501';
  end if;
  select count(*)::integer, max(q.expires_at) into v_count, v_expires_at
    from public.business_customer_join_qr_v89 q
   where q.business_id=p_business and q.status='active' and q.expires_at>now();
  select q.id, q.token_version into v_id, v_version
    from public.business_customer_join_qr_v89 q
   where q.business_id=p_business and q.status='active' and q.expires_at>now()
   order by q.expires_at desc, q.id desc limit 1;
  return jsonb_build_object(
    'active_count', v_count,
    'latest_expires_at', v_expires_at,
    'qr_id', v_id,
    'token_version', v_version,
    'join_token', case when v_version is not null
                      then app.v197_join_token(p_business, v_version) end
  );
end
$$;

--
-- Name: business_get_loyalty_tiers_v143(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.business_get_loyalty_tiers_v143(p_business uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if not app.c45_owner_loyalty_write(p_business) then
    raise exception 'owner loyalty configuration access required' using errcode='42501';
  end if;
  return coalesce((
    select jsonb_agg(to_jsonb(version)-'id'-'config_version_id'-'business_id'-'created_at'
      order by version.threshold,version.sort,version.tier_id)
    from public.businesses business
    join public.loyalty_tier_versions version
      on version.business_id=business.id
     and version.config_version_id=business.active_config_version_id
    where business.id=p_business
  ),'[]'::jsonb);
end
$$;

--
-- Name: business_get_presentation_editor_v95(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.business_get_presentation_editor_v95(p_business uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_result jsonb;
begin
  if not app.is_salon_owner(p_business) and not app.is_super_admin() then
    raise exception 'owner_required' using errcode='42501';
  end if;
  if not exists(select 1 from public.businesses where id=p_business) then
    raise exception 'business_not_found' using errcode='22023';
  end if;

  select jsonb_build_object(
    'business_id',p_business,
    'available_locales',jsonb_build_array('en','zh-CN'),
    'brand',jsonb_build_object(
      'version',brand.version,
      'hero_color',brand.hero_color,
      'logo_asset',case when logo.id is null then null else
        (to_jsonb(logo)-'business_id'-'updated_by')
        ||jsonb_build_object('url',app.v95_public_media_url(logo.object_path))
      end,
      'hero_asset',case when hero.id is null then null else
        (to_jsonb(hero)-'business_id'-'updated_by')
        ||jsonb_build_object('url',app.v95_public_media_url(hero.object_path))
      end
    ),
    'programmes',coalesce((
      select jsonb_agg(
        (to_jsonb(programme)-'business_id')
        ||jsonb_build_object(
          'copies',coalesce((
            select jsonb_agg(
              to_jsonb(copy)-'business_id'-'entity_type'-'entity_id'
                -'updated_by'
              order by copy.locale
            )
            from public.business_localized_copy_v95 copy
            where copy.business_id=p_business
              and copy.entity_type='programme'
              and copy.entity_id=programme.id
          ),'[]'::jsonb),
          'media',coalesce((
            select jsonb_agg(
              (to_jsonb(asset)-'business_id'-'updated_by')
                ||jsonb_build_object(
                  'url',app.v95_public_media_url(asset.object_path)
                )
              order by asset.branch_id nulls first,asset.id
            )
            from public.business_media_assets_v95 asset
            where asset.business_id=p_business
              and asset.asset_kind='programme'
              and asset.entity_id=programme.id
          ),'[]'::jsonb)
        )
        order by programme.id
      )
      from public.loyalty_programs programme
      where programme.business_id=p_business
    ),'[]'::jsonb),
    'rewards',coalesce((
      select jsonb_agg(
        (to_jsonb(reward)-'business_id')
        ||jsonb_build_object(
          'copies',coalesce((
            select jsonb_agg(
              to_jsonb(copy)-'business_id'-'entity_type'-'entity_id'
                -'updated_by'
              order by copy.locale
            )
            from public.business_localized_copy_v95 copy
            where copy.business_id=p_business
              and copy.entity_type='reward'
              and copy.entity_id=reward.id
          ),'[]'::jsonb),
          'media',coalesce((
            select jsonb_agg(
              (to_jsonb(asset)-'business_id'-'updated_by')
                ||jsonb_build_object(
                  'url',app.v95_public_media_url(asset.object_path)
                )
              order by asset.branch_id nulls first,asset.id
            )
            from public.business_media_assets_v95 asset
            where asset.business_id=p_business
              and asset.asset_kind='reward'
              and asset.entity_id=reward.id
          ),'[]'::jsonb)
        )
        order by reward.sort,reward.id
      )
      from public.loyalty_rewards reward
      where reward.business_id=p_business
    ),'[]'::jsonb),
    'products',coalesce((
      select jsonb_agg(
        (to_jsonb(product)-'business_id')
        ||jsonb_build_object(
          'copies',coalesce((
            select jsonb_agg(
              to_jsonb(copy)-'business_id'-'entity_type'-'entity_id'
                -'updated_by'
              order by copy.locale
            )
            from public.business_localized_copy_v95 copy
            where copy.business_id=p_business
              and copy.entity_type='product'
              and copy.entity_id=product.id
          ),'[]'::jsonb),
          'media',coalesce((
            select jsonb_agg(
              (to_jsonb(asset)-'business_id'-'updated_by')
                ||jsonb_build_object(
                  'url',app.v95_public_media_url(asset.object_path)
                )
              order by asset.branch_id nulls first,asset.id
            )
            from public.business_media_assets_v95 asset
            where asset.business_id=p_business
              and asset.asset_kind='product'
              and asset.entity_id=product.id
          ),'[]'::jsonb)
        )
        order by product.name,product.id
      )
      from public.products product
      where product.business_id=p_business
    ),'[]'::jsonb),
    'services',coalesce((
      select jsonb_agg(
        (to_jsonb(service)-'business_id')
        ||jsonb_build_object(
          'copies',coalesce((
            select jsonb_agg(
              to_jsonb(copy)-'business_id'-'entity_type'-'entity_id'
                -'updated_by'
              order by copy.locale
            )
            from public.business_localized_copy_v95 copy
            where copy.business_id=p_business
              and copy.entity_type='service'
              and copy.entity_id=service.id
          ),'[]'::jsonb),
          'media',coalesce((
            select jsonb_agg(
              (to_jsonb(asset)-'business_id'-'updated_by')
                ||jsonb_build_object(
                  'url',app.v95_public_media_url(asset.object_path)
                )
              order by asset.branch_id nulls first,asset.id
            )
            from public.business_media_assets_v95 asset
            where asset.business_id=p_business
              and asset.asset_kind='service'
              and asset.entity_id=service.id
          ),'[]'::jsonb)
        )
        order by service.name,service.id
      )
      from public.services service
      where service.business_id=p_business
    ),'[]'::jsonb)
  ) into v_result
  from public.business_brand_presentation_v95 brand
  left join public.business_media_assets_v95 logo
    on logo.id=brand.logo_asset_id and logo.business_id=brand.business_id
  left join public.business_media_assets_v95 hero
    on hero.id=brand.hero_asset_id and hero.business_id=brand.business_id
  where brand.business_id=p_business;
  return v_result;
end
$$;

--
-- Name: business_get_profile_extras_v418(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.business_get_profile_extras_v418(p_business uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if not (app.is_salon_owner(p_business) or app.can_module_read(p_business,'dashboard')) then
    raise exception 'business profile access required' using errcode='42501';
  end if;
  return jsonb_build_object(
    'status','ok',
    'gallery', coalesce((select jsonb_agg(jsonb_build_object(
        'id', g.id, 'image_ref', g.image_ref, 'caption', g.caption, 'sort', g.sort)
        order by g.sort, g.created_at)
      from public.business_gallery_v418 g where g.business_id = p_business),'[]'::jsonb),
    'social_links', coalesce((select jsonb_agg(jsonb_build_object(
        'platform', l.platform, 'url', l.url, 'sort', l.sort) order by l.sort, l.platform)
      from public.business_social_links_v418 l where l.business_id = p_business),'[]'::jsonb));
end $$;

--
-- Name: business_get_promotion_editor_v104(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.business_get_promotion_editor_v104(p_business uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_entitlement record;
  v_published_count integer;
  v_quota_used integer;
  v_items jsonb;
begin
  if auth.uid() is null then
    raise exception 'authenticated_session_required' using errcode='28000';
  end if;
  if not app.is_salon_owner(p_business) and not app.is_super_admin() then
    raise exception 'owner_required' using errcode='42501';
  end if;
  if p_business is null or not exists(
    select 1 from public.businesses business where business.id=p_business
  ) then
    raise exception 'business_not_found' using errcode='22023';
  end if;

  select * into v_entitlement
  from app.v104_effective_promotion_entitlement(p_business);
  select count(*)::integer into v_published_count
  from public.business_customer_content_v95 content
  where content.business_id=p_business
    and content.content_type='offer'
    and content.active
    and (content.ends_at is null or content.ends_at>now());
  select count(*)::integer into v_quota_used
  from public.business_customer_content_v95 content
  where content.business_id=p_business
    and content.content_type='offer'
    and content.metadata->>'schema'='nestly.promotion.v104'
    and content.metadata ? 'published_once_at';

  with bounded as (
    select content.*
    from public.business_customer_content_v95 content
    where content.business_id=p_business
      and content.content_type='offer'
    order by content.active desc,content.display_order,
      content.updated_at desc,content.id
    limit 100
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'id',content.id,
    'business_id',content.business_id,
    'branch_id',content.branch_id,
    'status',case when content.active then 'published' else 'draft' end,
    'publish_state',case when content.active then 'published' else 'draft' end,
    'active',content.active,
    'display_order',content.display_order,
    'starts_at',content.starts_at,
    'ends_at',content.ends_at,
    'metadata',content.metadata,
    'content_version',content.version,
    'copy_version',coalesce(copy.version,0),
    'name',copy.name,
    'tagline',copy.tagline,
    'description',copy.description,
    'terms',copy.terms,
    'image_url',media.url,
    'image_alt',media.alt_en,
    'media_asset_id',media.id,
    'media_version',coalesce(media.version,0),
    'image_asset_version',coalesce(media.version,0),
    'image_customer_visible',coalesce(media.customer_visible,false),
    'media_versions_by_scope',coalesce(
      media_scopes.items,'{}'::jsonb
    )
  ) order by content.active desc,content.display_order,
      content.updated_at desc,content.id),'[]'::jsonb)
  into v_items
  from bounded content
  left join public.business_localized_copy_v95 copy
    on copy.business_id=p_business
    and copy.entity_type='offer'
    and copy.entity_id=content.id
    and copy.locale='en'
  left join lateral(
    select asset.id,app.v95_public_media_url(asset.object_path) url,
      asset.version,asset.alt_en,asset.customer_visible
    from public.business_media_assets_v95 asset
    where asset.business_id=p_business
      and asset.asset_kind='offer'
      and asset.entity_id=content.id
      and (
        asset.branch_id is not distinct from content.branch_id
        or (content.branch_id is not null and asset.branch_id is null)
      )
    order by (asset.branch_id is not distinct from content.branch_id) desc,
      asset.updated_at desc,asset.id
    limit 1
  ) media on true
  left join lateral(
    select jsonb_object_agg(
      coalesce(asset.branch_id::text,'global'),
      jsonb_build_object(
        'branch_id',asset.branch_id,
        'media_asset_id',asset.id,
        'media_version',asset.version,
        'customer_visible',asset.customer_visible,
        'image_url',app.v95_public_media_url(asset.object_path),
        'image_alt',asset.alt_en
      )
    ) items
    from public.business_media_assets_v95 asset
    where asset.business_id=p_business
      and asset.asset_kind='offer'
      and asset.entity_id=content.id
  ) media_scopes on true;

  return jsonb_build_object(
    'items',v_items,
    'entitlement',jsonb_build_object(
      'max_published_offers',v_entitlement.max_published_offers,
      'complimentary_until',v_entitlement.complimentary_until,
      'version',v_entitlement.version,
      'published_count',v_published_count,
      'quota_used',v_quota_used,
      'quota_limit',v_entitlement.max_published_offers,
      'quota_remaining',greatest(
        v_entitlement.max_published_offers-v_quota_used,0
      ),
      'can_publish_new',
        now()<v_entitlement.complimentary_until
        and v_quota_used<v_entitlement.max_published_offers
    )
  );
end
$$;

--
-- Name: business_get_promotion_editor_v155(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.business_get_promotion_editor_v155(p_business uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_base jsonb;
  v_items jsonb;
begin
  v_base := public.business_get_promotion_editor_v104(p_business);
  with items as (
    select value item
    from jsonb_array_elements(coalesce(v_base->'items','[]'::jsonb))
  )
  select coalesce(jsonb_agg(
    item || jsonb_build_object(
      'branch_scope',case
        when exists(
          select 1 from public.promotion_branch_scopes_v155 mapped
          where mapped.promotion_id = (item->>'id')::uuid
        ) then jsonb_build_object(
          'mode','selected_branches',
          'branch_ids',(
            select coalesce(jsonb_agg(mapped.branch_id order by branch.name),'[]'::jsonb)
            from public.promotion_branch_scopes_v155 mapped
            join public.branches branch on branch.id = mapped.branch_id
            where mapped.promotion_id = (item->>'id')::uuid
          ),
          'branch_names',(
            select coalesce(jsonb_agg(branch.name order by branch.name),'[]'::jsonb)
            from public.promotion_branch_scopes_v155 mapped
            join public.branches branch on branch.id = mapped.branch_id
            where mapped.promotion_id = (item->>'id')::uuid
          )
        )
        else jsonb_build_object('mode','all_branches','branch_ids','[]'::jsonb,'branch_names','[]'::jsonb)
      end
    )
  ),'[]'::jsonb)
  into v_items
  from items;
  return jsonb_set(v_base,'{items}',v_items,true);
end
$$;

--
-- Name: business_get_visible_promotion_count_v167(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.business_get_visible_promotion_count_v167(p_business uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_count integer;
begin
  if auth.uid() is null or p_business is null then
    raise exception 'authenticated_business_context_required' using errcode='28000';
  end if;
  if not app.is_salon_owner(p_business) then
    raise exception 'owner_required' using errcode='42501';
  end if;

  -- v173: media is optional for customer visibility (customer readers render a
  -- branded fallback), so the owner-facing count no longer requires an image.
  select count(*)::integer into v_count
  from public.business_customer_content_v95 content
  where content.business_id=p_business
    and content.content_type='offer'
    and content.active
    and content.branch_id is null
    and (content.starts_at is null or content.starts_at<=statement_timestamp())
    and content.ends_at>statement_timestamp()
    and (
      not exists(select 1 from public.promotion_branch_scopes_v155 mapped where mapped.promotion_id=content.id)
      or exists(
        select 1
        from public.promotion_branch_scopes_v155 mapped
        join public.branches active_branch
          on active_branch.id=mapped.branch_id
         and active_branch.business_id=p_business
         and coalesce(active_branch.active,true)
        where mapped.promotion_id=content.id
          and mapped.business_id=p_business
      )
    );

  return jsonb_build_object(
    'business_id',p_business,
    'visible_count',v_count,
    'as_of',statement_timestamp()
  );
end
$$;

--
-- Name: FUNCTION business_get_visible_promotion_count_v167(p_business uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.business_get_visible_promotion_count_v167(p_business uuid) IS 'Owner-only canonical count of currently customer-visible published promotions.';

--
-- Name: business_get_welcome_offer_v215(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.business_get_welcome_offer_v215(p_business uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_row public.business_welcome_offers_v215%rowtype;
  v_granted int; v_redeemed int; v_item_ok boolean;
begin
  if auth.uid() is null then
    raise exception 'authenticated staff required' using errcode='42501';
  end if;
  if not (app.is_salon_owner(p_business)
          or app.can_module_read(p_business,'loyalty')
          or app.can_module_read(p_business,'till')) then
    raise exception 'welcome offer authorization required' using errcode='42501';
  end if;

  select count(*) filter (where status='granted'), count(*) filter (where status='redeemed')
    into v_granted, v_redeemed
  from public.welcome_offer_grants_v215 where business_id = p_business;

  select * into v_row from public.business_welcome_offers_v215 where business_id = p_business;
  if v_row.business_id is null then
    return jsonb_build_object('status','ok','configured',false,'active',false,
      'granted_count',coalesce(v_granted,0),'redeemed_count',coalesce(v_redeemed,0));
  end if;

  if v_row.reward_catalog_kind = 'custom' then
    v_item_ok := true;
  elsif v_row.reward_catalog_kind = 'service' then
    select true into v_item_ok from public.services
    where id = v_row.reward_catalog_id and business_id = p_business and active;
  else
    select true into v_item_ok from public.products
    where id = v_row.reward_catalog_id and business_id = p_business and active;
  end if;

  return jsonb_build_object(
    'status','ok','configured',true,'active',v_row.active,
    'min_spend_cents',v_row.min_spend_cents,
    'reward_catalog_kind',v_row.reward_catalog_kind,
    'reward_catalog_id',v_row.reward_catalog_id,
    'custom_label',v_row.custom_label,
    'reward_label',v_row.reward_label,'expiry_days',v_row.expiry_days,
    'version',v_row.version,
    'item_available',coalesce(v_item_ok,false),
    'granted_count',coalesce(v_granted,0),'redeemed_count',coalesce(v_redeemed,0));
end
$$;

--
-- Name: business_has_active_gift_liability_v117(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.business_has_active_gift_liability_v117(p_business uuid, p_branch uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if auth.uid() is null
     or not app.can_module_write_at_v94(p_business,p_branch,'till')
     or not app.can_module_read_at_v94(p_business,p_branch,'clients')
     or not app.has_perm(p_business,'create_sales') then
    raise exception 'branch-effective Till, Clients and create-sales authorization is required'
      using errcode='42501';
  end if;
  return exists(
    select 1
    from public.gift_cards card
    where card.business_id=p_business
      and card.status='active'
      and card.balance_cents>0
  );
end
$$;

--
-- Name: business_list_branches_v202(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.business_list_branches_v202(p_business uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_rows jsonb;
begin
  if auth.uid() is null or not (app.is_salon_owner(p_business) or app.is_super_admin()) then
    raise exception 'owner access is required' using errcode='42501';
  end if;
  select coalesce(jsonb_agg(jsonb_build_object(
           'id',b.id,'name',b.name,'address',b.address,'phone',b.phone,
           'active',b.active,'is_default',b.is_default,
           'billing_state',b.billing_state,
           'operational',app.branch_is_operational_v202(b.id)
         ) order by b.is_default desc, b.name), '[]'::jsonb)
    into v_rows from public.branches b where b.business_id=p_business;
  return jsonb_build_object('status','ok','branches',v_rows);
end
$$;

--
-- Name: business_list_media_cleanup_queue_v95(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.business_list_media_cleanup_queue_v95(p_business uuid, p_limit integer DEFAULT 20) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if not app.is_salon_owner(p_business) and not app.is_super_admin() then
    raise exception 'owner_required' using errcode='42501';
  end if;
  if p_limit not between 1 and 100 then
    raise exception 'cleanup_limit_out_of_range' using errcode='22023';
  end if;
  return jsonb_build_object(
    'pending',coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'id',queue.id,'object_path',queue.object_path,
          'reason',queue.reason,'attempts',queue.attempts,
          'last_error',queue.last_error,'requested_at',queue.requested_at,
          'last_attempt_at',queue.last_attempt_at
        ) order by queue.requested_at,queue.id
      )
      from (
        select * from public.business_media_cleanup_queue_v95
        where business_id=p_business and status='pending'
        order by requested_at,id limit p_limit
      ) queue
    ),'[]'::jsonb)
  );
end
$$;

--
-- Name: business_manage_package_plan_v193(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.business_manage_package_plan_v193(p_business uuid, p_plan uuid, p_action text, p_name text DEFAULT NULL::text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_plan public.package_plans%rowtype; v_sold integer; v_name text;
begin
  if p_action not in ('rename','delete') then
    raise exception 'unsupported package action' using errcode='22023';
  end if;
  if not app.can_module_write(p_business,'packages') then
    raise exception 'packages write access is required' using errcode='42501';
  end if;
  select * into v_plan from public.package_plans
   where id=p_plan and business_id=p_business for update;
  if not found then
    raise exception 'package not found in this business' using errcode='42704';
  end if;
  select count(*) into v_sold from public.client_packages
   where business_id=p_business and plan_id=p_plan;
  if v_sold > 0 then
    raise exception 'this package has been sold to % customer(s); create a new version instead', v_sold
      using errcode='42501';
  end if;
  if p_action='rename' then
    v_name := btrim(coalesce(p_name,''));
    if length(v_name) < 2 then
      raise exception 'give the package a name' using errcode='22023';
    end if;
    update public.package_plans set name=v_name where id=p_plan and business_id=p_business;
  else
    delete from public.package_plans where id=p_plan and business_id=p_business;
  end if;
  insert into public.audit_log(business_id, actor, action, entity, entity_id, meta)
  values (p_business, auth.uid(), 'package_plan.'||p_action, 'package_plans', p_plan,
          jsonb_build_object('was_sold', v_sold, 'name', coalesce(v_name, v_plan.name)));
  return json_build_object('status','ok','action',p_action,'plan_id',p_plan);
end $$;

--
-- Name: business_mark_media_cleanup_result_v95(uuid, uuid, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.business_mark_media_cleanup_result_v95(p_business uuid, p_cleanup uuid, p_succeeded boolean, p_error text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_row public.business_media_cleanup_queue_v95%rowtype;
begin
  if not app.is_salon_owner(p_business) and not app.is_super_admin() then
    raise exception 'owner_required' using errcode='42501';
  end if;
  select * into v_row from public.business_media_cleanup_queue_v95
  where id=p_cleanup and business_id=p_business for update;
  if not found then raise exception 'cleanup_item_not_found'
    using errcode='22023';end if;
  if p_succeeded is null
     or (not p_succeeded and length(btrim(coalesce(p_error,'')))
       not between 1 and 1000)
     or (p_succeeded and exists(
       select 1 from storage.objects
       where bucket_id='business-public' and name=v_row.object_path
     )) then
    raise exception 'truthful_cleanup_result_required' using errcode='22023';
  end if;
  update public.business_media_cleanup_queue_v95
  set status=case when p_succeeded then 'completed' else 'pending' end,
    attempts=attempts+1,last_attempt_at=now(),
    last_error=case when p_succeeded then null else btrim(p_error) end,
    completed_at=case when p_succeeded then now() else null end,
    updated_at=now()
  where id=p_cleanup returning * into v_row;
  return to_jsonb(v_row)-'requested_by';
end
$$;

--
-- Name: business_preview_stamp_conversion_v384(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.business_preview_stamp_conversion_v384(p_business uuid, p_points_per_stamp integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_points_programme uuid;
  v_stamps_programme uuid;
  v_rate integer := coalesce(p_points_per_stamp, 0);
  v_result jsonb;
begin
  if not app.c45_owner_loyalty_write(p_business) then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  if v_rate <= 0 then
    raise exception 'points per stamp must be greater than zero' using errcode = '22023';
  end if;

  select id into v_points_programme
    from public.business_programmes
   where business_id = p_business and kind = 'points'
   order by sort, id
   limit 1;
  select id into v_stamps_programme
    from public.business_programmes
   where business_id = p_business and kind = 'stamps'
   order by sort, id
   limit 1;
  if v_points_programme is null or v_stamps_programme is null then
    raise exception 'points and stamp programmes are required' using errcode = '23514';
  end if;

  with balances as (
    select coalesce(l.client_id, b.client_id) as client_id,
           greatest(least(coalesce(l.points_balance, 0), coalesce(b.batch_balance, 0)), 0)::integer as spendable_points
      from (
        select client_id, sum(points)::integer as points_balance
          from public.points_ledger
         where business_id = p_business and programme_id = v_points_programme
         group by client_id
      ) l
      full join (
        select client_id, sum(remaining)::integer as batch_balance
          from public.points_batches
         where business_id = p_business
           and programme_id = v_points_programme
           and remaining > 0
         group by client_id
      ) b using (client_id)
  ), converted as (
    select client_id,
           spendable_points,
           (spendable_points / v_rate)::integer as stamps_to_issue,
           ((spendable_points / v_rate) * v_rate)::integer as points_to_convert,
           (spendable_points - ((spendable_points / v_rate) * v_rate))::integer as leftover_points
      from balances
     where spendable_points > 0
  )
  select jsonb_build_object(
    'points_per_stamp', v_rate,
    'customers', coalesce(count(*) filter (where stamps_to_issue > 0), 0),
    'points_convertible', coalesce(sum(points_to_convert), 0),
    'stamps_to_issue', coalesce(sum(stamps_to_issue), 0),
    'leftover_points', coalesce(sum(leftover_points), 0),
    'already_converted', exists (
      select 1 from public.programme_stamp_conversions_v384 done
       where done.business_id = p_business
         and done.points_programme_id = v_points_programme
         and done.stamps_programme_id = v_stamps_programme
    )
  ) into v_result
  from converted;

  return coalesce(v_result, jsonb_build_object(
    'points_per_stamp', v_rate,
    'customers', 0,
    'points_convertible', 0,
    'stamps_to_issue', 0,
    'leftover_points', 0,
    'already_converted', false
  ));
end;
$$;

--
-- Name: business_programme_usage_v271(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.business_programme_usage_v271(p_business uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_point_customers int;
  v_points_programme_v310 uuid;
  v_stamps_programme_v310 uuid;
  v_stamp_customers_v310 int;
  v_rewards jsonb;
  v_retention jsonb;
  v_birthday_started timestamptz;
  v_birthday_customers int;
  v_welcome_customers int;
  v_referral_customers int;
  v_memberships jsonb;
begin
  if auth.uid() is null then
    raise exception 'authenticated staff required' using errcode = '42501';
  end if;
  if p_business is null then
    raise exception 'business required' using errcode = '22023';
  end if;
  if not (app.is_salon_owner(p_business) or app.can_module_read(p_business, 'loyalty')) then
    raise exception 'programme overview authorization required' using errcode = '42501';
  end if;

  -- The point system is "used" by a customer the moment they earn from it. Redemption is a
  -- separate programme (the rewards below), so it is deliberately not folded in here.
  select spine.id into v_points_programme_v310
    from public.business_programmes spine
   where spine.business_id = p_business and spine.kind = 'points';
  if v_points_programme_v310 is null then
    select count(distinct client_id)::int into v_point_customers
      from public.points_ledger
     where business_id = p_business
       and entry_type = 'earn'
       and client_id is not null;
  else
    select count(distinct ledger.client_id)::int into v_point_customers
      from public.points_ledger ledger
     where ledger.business_id = p_business
       and ledger.entry_type = 'earn'
       and ledger.client_id is not null
       and ledger.programme_id = v_points_programme_v310;
  end if;

  select spine.id into v_stamps_programme_v310
    from public.business_programmes spine
   where spine.business_id = p_business and spine.kind = 'stamps';
  if v_stamps_programme_v310 is not null then
    select count(distinct ledger.client_id)::int into v_stamp_customers_v310
      from public.points_ledger ledger
     where ledger.business_id = p_business
       and ledger.entry_type = 'earn'
       and ledger.client_id is not null
       and ledger.programme_id = v_stamps_programme_v310;
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
           'reward_id', reward.id,
           'customers', coalesce(used.customers, 0))), '[]'::jsonb)
    into v_rewards
    from public.loyalty_rewards reward
    left join lateral (
      select count(distinct redemption.client_id)::int customers
        from public.loyalty_redemptions redemption
       where redemption.business_id = p_business
         and redemption.reward_id = reward.id
         and redemption.client_id is not null
    ) used on true
   where reward.business_id = p_business;

  -- A bring-back reward reaches a customer as a reward_grant; the grant is the only durable
  -- evidence that the programme did anything for that person.
  select coalesce(jsonb_agg(jsonb_build_object(
           'program_id', program.id,
           'customers', coalesce(used.customers, 0))), '[]'::jsonb)
    into v_retention
    from public.retention_programs program
    left join lateral (
      select count(distinct grant_row.client_id)::int customers
        from public.reward_grants grant_row
       where grant_row.business_id = p_business
         and grant_row.program_id = program.id
         and grant_row.client_id is not null
    ) used on true
   where program.business_id = p_business;

  select min(created_at) into v_birthday_started
    from public.birthday_programs where business_id = p_business;

  -- Reversal rows share this table with the original redemption; `active` is what distinguishes a
  -- redemption that still stands from one that was undone. Counting both would report a customer
  -- as having used a benefit that was taken back.
  select count(distinct client_id)::int into v_birthday_customers
    from public.customer_birthday_redemptions
   where business_id = p_business and active and client_id is not null;

  -- Granted is not used. Only a redeemed welcome offer means the customer actually received it.
  select count(distinct client_id)::int into v_welcome_customers
    from public.welcome_offer_grants_v215
   where business_id = p_business and status = 'redeemed' and client_id is not null;

  -- The referrer is the customer the programme rewarded, and only a qualified referral pays out.
  select count(distinct referrer_client_id)::int into v_referral_customers
    from public.referrals
   where business_id = p_business
     and qualified_at is not null
     and referrer_client_id is not null;

  select coalesce(jsonb_agg(jsonb_build_object(
           'plan_id', plan.id,
           'customers', coalesce(used.customers, 0))), '[]'::jsonb)
    into v_memberships
    from public.membership_plans plan
    left join lateral (
      select count(distinct member.client_id)::int customers
        from public.memberships member
       where member.business_id = p_business
         and member.plan_id = plan.id
         and member.client_id is not null
    ) used on true
   where plan.business_id = p_business;

  return jsonb_build_object(
    'status', 'ok',
    'as_of', now(),
    'point_system', jsonb_build_object('customers', coalesce(v_point_customers, 0)),
    'stamp_card', jsonb_build_object('customers', case when exists(
                                       select 1 from public.loyalty_programs programme_v310
                                        where programme_v310.business_id = p_business
                                          and programme_v310.loyalty_model = 'stamps')
                                     then coalesce(v_stamp_customers_v310, 0) else null end),
    'rewards', v_rewards,
    'retention', v_retention,
    'birthday', jsonb_build_object('started_at', v_birthday_started,
                                   'customers', case when exists(
                                     select 1 from public.birthday_programs v273_exists
                                      where v273_exists.business_id = p_business)
                                     then coalesce(v_birthday_customers, 0) else null end),
    'welcome', jsonb_build_object('customers', case when exists(
                                     select 1 from public.business_welcome_offers_v215 v273_exists
                                      where v273_exists.business_id = p_business)
                                     then coalesce(v_welcome_customers, 0) else null end),
    'referrals', jsonb_build_object('customers', case when exists(
                                     select 1 from public.referral_programs v273_exists
                                      where v273_exists.business_id = p_business)
                                     then coalesce(v_referral_customers, 0) else null end),
    'memberships', v_memberships,
    -- null, not 0: nothing in this schema records a customer using a promotion or a gift card
    -- programme, and a zero would read as "measured, and nobody used it".
    'promotions', jsonb_build_object('customers', null),
    'gift_cards', jsonb_build_object('customers', null));
end
$$;

--
-- Name: business_programme_usage_v386(uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.business_programme_usage_v386(p_business uuid, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  -- The window, resolved once. Singapore day boundaries, half-open [from, to+1day): the same
  -- convention every other dated read in this product uses, so "17 Aug" means the whole of the
  -- 17th in Singapore and never a slice of it in the browser's zone.
  v_from timestamptz := case when p_from is null then null
                             else (p_from::text || ' 00:00:00+08')::timestamptz end;
  v_to   timestamptz := case when p_to is null then null
                             else ((p_to + 1)::text || ' 00:00:00+08')::timestamptz end;
  v_point_customers int;
  v_points_programme_v310 uuid;
  v_stamps_programme_v310 uuid;
  v_stamp_customers_v310 int;
  v_rewards jsonb;
  v_retention jsonb;
  v_birthday_started timestamptz;
  v_birthday_customers int;
  v_welcome_customers int;
  v_referral_customers int;
  v_memberships jsonb;
begin
  if auth.uid() is null then
    raise exception 'authenticated staff required' using errcode = '42501';
  end if;
  if p_business is null then
    raise exception 'business required' using errcode = '22023';
  end if;
  if not (app.is_salon_owner(p_business) or app.can_module_read(p_business, 'loyalty')) then
    raise exception 'programme overview authorization required' using errcode = '42501';
  end if;
  -- A backwards window is a mistake, not an empty result: answering 0 for it would let the page
  -- report "nobody used this" when nobody was ever asked.
  if p_from is not null and p_to is not null and p_from > p_to then
    raise exception 'the From date is after the To date' using errcode = '22023';
  end if;

  -- The point system is "used" by a customer the moment they earn from it. Redemption is a
  -- separate programme (the rewards below), so it is deliberately not folded in here.
  select spine.id into v_points_programme_v310
    from public.business_programmes spine
   where spine.business_id = p_business and spine.kind = 'points';
  if v_points_programme_v310 is null then
    select count(distinct client_id)::int into v_point_customers
      from public.points_ledger
     where business_id = p_business
       and entry_type = 'earn'
       and client_id is not null
       and (v_from is null or created_at >= v_from)
       and (v_to is null or created_at < v_to);
  else
    select count(distinct ledger.client_id)::int into v_point_customers
      from public.points_ledger ledger
     where ledger.business_id = p_business
       and ledger.entry_type = 'earn'
       and ledger.client_id is not null
       and ledger.programme_id = v_points_programme_v310
       and (v_from is null or ledger.created_at >= v_from)
       and (v_to is null or ledger.created_at < v_to);
  end if;

  select spine.id into v_stamps_programme_v310
    from public.business_programmes spine
   where spine.business_id = p_business and spine.kind = 'stamps';
  if v_stamps_programme_v310 is not null then
    select count(distinct ledger.client_id)::int into v_stamp_customers_v310
      from public.points_ledger ledger
     where ledger.business_id = p_business
       and ledger.entry_type = 'earn'
       and ledger.client_id is not null
       and ledger.programme_id = v_stamps_programme_v310
       and (v_from is null or ledger.created_at >= v_from)
       and (v_to is null or ledger.created_at < v_to);
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
           'reward_id', reward.id,
           'customers', coalesce(used.customers, 0))), '[]'::jsonb)
    into v_rewards
    from public.loyalty_rewards reward
    left join lateral (
      select count(distinct redemption.client_id)::int customers
        from public.loyalty_redemptions redemption
       where redemption.business_id = p_business
         and redemption.reward_id = reward.id
         and redemption.client_id is not null
       and (v_from is null or redemption.redeemed_at >= v_from)
       and (v_to is null or redemption.redeemed_at < v_to)
    ) used on true
   where reward.business_id = p_business;

  -- A bring-back reward reaches a customer as a reward_grant; the grant is the only durable
  -- evidence that the programme did anything for that person.
  select coalesce(jsonb_agg(jsonb_build_object(
           'program_id', program.id,
           'customers', coalesce(used.customers, 0))), '[]'::jsonb)
    into v_retention
    from public.retention_programs program
    left join lateral (
      select count(distinct grant_row.client_id)::int customers
        from public.reward_grants grant_row
       where grant_row.business_id = p_business
         and grant_row.program_id = program.id
         and grant_row.client_id is not null
       and (v_from is null or grant_row.granted_at >= v_from)
       and (v_to is null or grant_row.granted_at < v_to)
    ) used on true
   where program.business_id = p_business;

  select min(created_at) into v_birthday_started
    from public.birthday_programs where business_id = p_business;

  -- Reversal rows share this table with the original redemption; `active` is what distinguishes a
  -- redemption that still stands from one that was undone. Counting both would report a customer
  -- as having used a benefit that was taken back.
  select count(distinct client_id)::int into v_birthday_customers
    from public.customer_birthday_redemptions
   where business_id = p_business and active and client_id is not null
       and (v_from is null or created_at >= v_from)
       and (v_to is null or created_at < v_to);

  -- Granted is not used. Only a redeemed welcome offer means the customer actually received it.
  select count(distinct client_id)::int into v_welcome_customers
    from public.welcome_offer_grants_v215
   where business_id = p_business and status = 'redeemed' and client_id is not null
       and (v_from is null or redeemed_at >= v_from)
       and (v_to is null or redeemed_at < v_to);

  -- The referrer is the customer the programme rewarded, and only a qualified referral pays out.
  select count(distinct referrer_client_id)::int into v_referral_customers
    from public.referrals
   where business_id = p_business
     and qualified_at is not null
     and referrer_client_id is not null
       and (v_from is null or qualified_at >= v_from)
       and (v_to is null or qualified_at < v_to);

  select coalesce(jsonb_agg(jsonb_build_object(
           'plan_id', plan.id,
           'customers', coalesce(used.customers, 0))), '[]'::jsonb)
    into v_memberships
    from public.membership_plans plan
    left join lateral (
      select count(distinct member.client_id)::int customers
        from public.memberships member
       where member.business_id = p_business
         and member.plan_id = plan.id
         and member.client_id is not null
       and (v_from is null or member.started_at >= v_from)
       and (v_to is null or member.started_at < v_to)
    ) used on true
   where plan.business_id = p_business;

  return jsonb_build_object(
    'status', 'ok',
    'as_of', now(),
    -- Echoed so the card labels its figures with the window the SERVER used, not the one the
    -- inputs happen to be showing after an edit the owner has not applied yet.
    'window', jsonb_build_object('from', p_from, 'to', p_to),
    'point_system', jsonb_build_object('customers', coalesce(v_point_customers, 0)),
    'stamp_card', jsonb_build_object('customers', case when exists(
                                       select 1 from public.loyalty_programs programme_v310
                                        where programme_v310.business_id = p_business
                                          and programme_v310.loyalty_model = 'stamps')
                                     then coalesce(v_stamp_customers_v310, 0) else null end),
    'rewards', v_rewards,
    'retention', v_retention,
    'birthday', jsonb_build_object('started_at', v_birthday_started,
                                   'customers', case when exists(
                                     select 1 from public.birthday_programs v273_exists
                                      where v273_exists.business_id = p_business)
                                     then coalesce(v_birthday_customers, 0) else null end),
    'welcome', jsonb_build_object('customers', case when exists(
                                     select 1 from public.business_welcome_offers_v215 v273_exists
                                      where v273_exists.business_id = p_business)
                                     then coalesce(v_welcome_customers, 0) else null end),
    'referrals', jsonb_build_object('customers', case when exists(
                                     select 1 from public.referral_programs v273_exists
                                      where v273_exists.business_id = p_business)
                                     then coalesce(v_referral_customers, 0) else null end),
    'memberships', v_memberships,
    -- null, not 0: nothing in this schema records a customer using a promotion or a gift card
    -- programme, and a zero would read as "measured, and nobody used it".
    'promotions', jsonb_build_object('customers', null),
    'gift_cards', jsonb_build_object('customers', null));
end
$$;

--
-- Name: FUNCTION business_programme_usage_v386(p_business uuid, p_from date, p_to date); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.business_programme_usage_v386(p_business uuid, p_from date, p_to date) IS 'v386: business_programme_usage_v271 with an optional Singapore-day window. NULL bounds mean
   unbounded, so a call with neither argument is identical to v271.';

--
-- Name: business_publish_media_replacement_v95(uuid, text, uuid, uuid, text, text, integer, integer, text, text, text, bigint, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.business_publish_media_replacement_v95(p_business uuid, p_asset_kind text, p_entity_id uuid, p_branch uuid, p_object_path text, p_mime_type text, p_width_px integer, p_height_px integer, p_alt_en text, p_alt_zh_cn text, p_hero_color text, p_expected_asset_version bigint, p_expected_brand_version bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $_$
declare
  v_existing public.business_media_assets_v95%rowtype;
  v_asset public.business_media_assets_v95%rowtype;
  v_brand public.business_brand_presentation_v95%rowtype;
  v_previous_object_path text;
begin
  if not app.is_salon_owner(p_business) and not app.is_super_admin() then
    raise exception 'owner_required' using errcode='42501';
  end if;
  if p_expected_asset_version is null
     or not app.v95_storage_object_is_publishable(
       p_business,p_asset_kind,p_object_path,p_mime_type
     ) then
    raise exception 'verified_storage_object_required' using errcode='22023';
  end if;
  if p_asset_kind in ('logo','hero') then
    if p_expected_brand_version is null or p_entity_id is not null
       or p_branch is not null
       or coalesce(p_hero_color,'')!~'^#[0-9A-Fa-f]{6}$' then
      raise exception 'brand_version_required' using errcode='22023';
    end if;
    select * into v_brand from public.business_brand_presentation_v95
    where business_id=p_business for update;
    if not found or v_brand.version<>p_expected_brand_version then
      raise exception 'brand_version_conflict' using errcode='40001';
    end if;
  elsif p_expected_brand_version is not null or p_hero_color is not null then
    raise exception 'brand_version_not_applicable' using errcode='22023';
  end if;

  select * into v_existing from public.business_media_assets_v95 asset
  where asset.business_id=p_business and asset.asset_kind=p_asset_kind
    and asset.entity_id is not distinct from p_entity_id
    and asset.branch_id is not distinct from p_branch
  for update;
  if found then v_previous_object_path:=v_existing.object_path;end if;

  perform public.business_upsert_media_asset_v95(
    p_business,p_asset_kind,p_entity_id,p_branch,p_object_path,p_mime_type,
    p_width_px,p_height_px,p_alt_en,p_alt_zh_cn,false,
    p_expected_asset_version
  );
  update public.business_media_assets_v95 asset
  set customer_visible=true
  where asset.business_id=p_business and asset.asset_kind=p_asset_kind
    and asset.entity_id is not distinct from p_entity_id
    and asset.branch_id is not distinct from p_branch
  returning * into v_asset;

  if p_asset_kind in ('logo','hero') then
    update public.business_brand_presentation_v95
    set logo_asset_id=case
          when p_asset_kind='logo' then v_asset.id else logo_asset_id end,
        hero_asset_id=case
          when p_asset_kind='hero' then v_asset.id else hero_asset_id end,
        hero_color=upper(p_hero_color),
        version=version+1,updated_by=auth.uid(),updated_at=now()
    where business_id=p_business returning * into v_brand;
  end if;

  return jsonb_build_object(
    'id',v_asset.id,'asset_kind',v_asset.asset_kind,
    'entity_id',v_asset.entity_id,'branch_id',v_asset.branch_id,
    'object_path',v_asset.object_path,
    'url',app.v95_public_media_url(v_asset.object_path),
    'mime_type',v_asset.mime_type,'width_px',v_asset.width_px,
    'height_px',v_asset.height_px,'alt_en',v_asset.alt_en,
    'alt_zh_cn',v_asset.alt_zh_cn,'customer_visible',true,
    'version',v_asset.version,
    'brand_version',case when p_asset_kind in ('logo','hero')
      then v_brand.version else null end,
    'previous_object_path',case
      when v_previous_object_path is distinct from v_asset.object_path
      then v_previous_object_path else null end
  );
end
$_$;

--
-- Name: business_queue_media_cleanup_v95(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.business_queue_media_cleanup_v95(p_business uuid, p_object_path text, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $_$
declare v_row public.business_media_cleanup_queue_v95%rowtype;
begin
  if not app.is_salon_owner(p_business) and not app.is_super_admin() then
    raise exception 'owner_required' using errcode='42501';
  end if;
  if coalesce(p_object_path,'')!~(
       '^'||p_business::text||
       '/(logo|hero|programme|reward|product|service|benefit|offer)'||
       '/[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}\.(png|jpg|jpeg|webp|gif)$'
     )
     or length(btrim(coalesce(p_reason,''))) not between 1 and 240 then
    raise exception 'valid cleanup target required' using errcode='22023';
  end if;
  if exists(
    select 1 from public.business_media_assets_v95
    where business_id=p_business and object_path=p_object_path
  ) then
    raise exception 'published_media_cannot_be_queued' using errcode='23514';
  end if;
  insert into public.business_media_cleanup_queue_v95(
    business_id,object_path,reason,status,requested_by,completed_at
  ) values(
    p_business,p_object_path,btrim(p_reason),
    case when exists(
      select 1 from storage.objects
      where bucket_id='business-public' and name=p_object_path
    ) then 'pending' else 'completed' end,
    auth.uid(),
    case when exists(
      select 1 from storage.objects
      where bucket_id='business-public' and name=p_object_path
    ) then null else now() end
  )
  on conflict(business_id,object_path) do update set
    reason=excluded.reason,status=excluded.status,
    requested_by=excluded.requested_by,requested_at=now(),
    completed_at=excluded.completed_at,updated_at=now()
  returning * into v_row;
  return to_jsonb(v_row)-'requested_by';
end
$_$;

--
-- Name: business_revoke_customer_join_qrs_v90(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.business_revoke_customer_join_qrs_v90(p_business uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_count integer;
begin
  if not (app.is_salon_owner(p_business) or app.is_super_admin()) then
    raise exception 'business owner access is required' using errcode='42501';
  end if;
  perform app.v198_assert_qr_unlocked(p_business,'revoked');
  perform pg_advisory_xact_lock(hashtextextended(
    'v90:join-qr:'||p_business::text,0
  ));
  update public.business_customer_join_qr_v89
  set status='revoked',revoked_at=now()
  where business_id=p_business and status='active';
  get diagnostics v_count=row_count;
  insert into public.audit_log(
    business_id,actor,action,entity,entity_id,detail
  ) values(
    p_business,auth.uid(),'REVOKE_CUSTOMER_JOIN_QRS_V90',
    'businesses',p_business,jsonb_build_object('revoked_count',v_count)
  );
  return jsonb_build_object('business_id',p_business,'revoked_count',v_count);
end
$$;

--
-- Name: business_reward_redemption_counts_v300(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.business_reward_redemption_counts_v300(p_business uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_by_reward jsonb;
  v_classic integer;
  v_total integer;
begin
  perform public.require_module_scope_v145(p_business, null, 'loyalty');

  select coalesce(jsonb_object_agg(t.reward_id::text, t.cnt), '{}'::jsonb)
    into v_by_reward
    from (
      select lr.reward_id, count(*)::integer as cnt
      from public.loyalty_redemptions lr
      where lr.business_id = p_business
        and lr.reward_id is not null
      group by lr.reward_id
    ) t;

  select count(*) filter (where lr.reward_id is null)::integer,
         count(*)::integer
    into v_classic, v_total
    from public.loyalty_redemptions lr
   where lr.business_id = p_business;

  return jsonb_build_object(
    'rewards', v_by_reward,
    'classic', coalesce(v_classic, 0),
    'total', coalesce(v_total, 0)
  );
end
$$;

--
-- Name: business_rotate_customer_join_qr_v90(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.business_rotate_customer_join_qr_v90(p_business uuid, p_expires_at timestamp with time zone DEFAULT (now() + '365 days'::interval)) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_revoked jsonb;v_created jsonb;
begin
  if not (app.is_salon_owner(p_business) or app.is_super_admin()) then
    raise exception 'business owner access is required' using errcode='42501';
  end if;
  perform app.v198_assert_qr_unlocked(p_business,'replaced');
  v_revoked:=public.business_revoke_customer_join_qrs_v90(p_business);
  v_created:=public.business_create_customer_join_qr_v89(
    p_business,p_expires_at
  );
  return v_created||jsonb_build_object(
    'replaced_count',coalesce((v_revoked->>'revoked_count')::integer,0)
  );
end
$$;

--
-- Name: business_save_promotion_v104(uuid, uuid, uuid, text, text, text, text, timestamp with time zone, timestamp with time zone, integer, text, text, text, text, boolean, bigint, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.business_save_promotion_v104(p_business uuid, p_promotion_id uuid, p_branch uuid, p_name text, p_tagline text, p_description text, p_terms text, p_starts_at timestamp with time zone, p_ends_at timestamp with time zone, p_display_order integer, p_cta_kind text, p_cta_label text, p_offer_facts text, p_occasion text, p_publish boolean, p_expected_content_version bigint, p_expected_copy_version bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid:=auth.uid();
  v_content public.business_customer_content_v95%rowtype;
  v_copy public.business_localized_copy_v95%rowtype;
  v_is_new boolean:=p_promotion_id is null;
  v_entitlement record;
  v_media_id uuid;
  v_media_version bigint;
  v_media_url text;
  v_media_alt text;
  v_published_count integer:=0;
  v_quota_used integer:=0;
  v_metadata jsonb;
begin
  if v_actor is null then
    raise exception 'authenticated_session_required' using errcode='28000';
  end if;
  if not app.is_salon_owner(p_business) then
    raise exception 'owner_required' using errcode='42501';
  end if;
  if p_business is null
     or p_publish is null
     or p_expected_content_version is null
     or p_expected_copy_version is null
     or p_display_order is null
     or p_display_order not between 0 and 10000
     or p_cta_kind is null
     or p_cta_kind not in ('book','programme','counter')
     or length(btrim(coalesce(p_cta_label,''))) not between 2 and 40
     or length(btrim(coalesce(p_name,''))) not between 2 and 70
     or (
       nullif(btrim(coalesce(p_tagline,'')),'') is not null
       and length(btrim(p_tagline)) not between 2 and 120
     )
     or length(btrim(coalesce(p_description,''))) not between 10 and 600
     or (
       nullif(btrim(coalesce(p_terms,'')),'') is not null
       and length(btrim(p_terms))>1000
     )
     or length(btrim(coalesce(p_offer_facts,''))) not between 2 and 500
     or (
       nullif(btrim(coalesce(p_occasion,'')),'') is not null
       and length(btrim(p_occasion)) not between 2 and 80
     )
     or p_ends_at is null
     or (p_starts_at is not null and p_ends_at<=p_starts_at)
     or (
       p_branch is not null
       and not exists(
         select 1 from public.branches branch
         where branch.id=p_branch
           and branch.business_id=p_business
           and branch.active
       )
     )
     or not exists(
       select 1 from public.businesses business where business.id=p_business
     )
  then
    raise exception 'valid_promotion_fields_required' using errcode='22023';
  end if;

  perform app.v104_lock_promotion_business(p_business);
  -- Retained only as an explicit compatibility failure for cached clients.
  -- Every mutable save now requires a stable attempt key and therefore goes
  -- through business_finalize_promotion_v104, even when the result is a draft
  -- or an unpublish.
  raise exception 'promotion_finalize_rpc_required' using errcode='42501';

  if p_promotion_id is null then
    raise exception 'promotion_create_draft_rpc_required' using errcode='42501';
  end if;
  if p_publish then
    raise exception 'promotion_finalize_rpc_required' using errcode='42501';
  end if;

  select * into v_entitlement
  from app.v104_effective_promotion_entitlement(p_business);

  if v_is_new then
    if p_expected_content_version<>0 or p_expected_copy_version<>0 then
      raise exception 'promotion_version_conflict' using errcode='40001';
    end if;
    if now()>=v_entitlement.complimentary_until then
      raise exception 'promotion_creation_window_closed' using errcode='42501';
    end if;
  else
    select * into v_content
    from public.business_customer_content_v95 content
    where content.id=p_promotion_id
      and content.business_id=p_business
      and content.content_type='offer'
    for update;
    if not found then
      raise exception 'promotion_not_found' using errcode='22023';
    end if;
    if v_content.version<>p_expected_content_version then
      raise exception 'promotion_version_conflict' using errcode='40001';
    end if;
    select * into v_copy
    from public.business_localized_copy_v95 copy
    where copy.business_id=p_business
      and copy.entity_type='offer'
      and copy.entity_id=p_promotion_id
      and copy.locale='en'
    for update;
    if found then
      if v_copy.version<>p_expected_copy_version then
        raise exception 'promotion_copy_version_conflict' using errcode='40001';
      end if;
    elsif p_expected_copy_version<>0 then
      raise exception 'promotion_copy_version_conflict' using errcode='40001';
    end if;
  end if;

  v_metadata:=jsonb_strip_nulls(jsonb_build_object(
    'schema','nestly.promotion.v104',
    'cta',jsonb_build_object(
      'kind',p_cta_kind,
      'label',btrim(p_cta_label)
    ),
    'offer_facts',btrim(p_offer_facts),
    'occasion',nullif(btrim(coalesce(p_occasion,'')),''),
    'published_once_at',v_content.metadata->'published_once_at'
  ));
  perform set_config('app.v104_promotion_write','on',true);
  perform set_config('app.v104_promotion_copy_write','on',true);

  if v_is_new then
    insert into public.business_customer_content_v95(
      business_id,content_type,branch_id,active,display_order,
      starts_at,ends_at,metadata,updated_by
    ) values(
      p_business,'offer',p_branch,false,p_display_order,
      p_starts_at,p_ends_at,v_metadata,v_actor
    )
    returning * into v_content;
    insert into public.business_localized_copy_v95(
      business_id,entity_type,entity_id,locale,name,tagline,description,
      terms,updated_by
    ) values(
      p_business,'offer',v_content.id,'en',btrim(p_name),
      nullif(btrim(coalesce(p_tagline,'')),''),
      btrim(p_description),nullif(btrim(coalesce(p_terms,'')),''),
      v_actor
    )
    returning * into v_copy;
  else
    update public.business_customer_content_v95
    set branch_id=p_branch,
        active=p_publish,
        display_order=p_display_order,
        starts_at=p_starts_at,
        ends_at=p_ends_at,
        metadata=v_metadata,
        version=version+1,
        updated_by=v_actor,
        updated_at=now()
    where id=p_promotion_id
    returning * into v_content;

    if v_copy.business_id is null then
      insert into public.business_localized_copy_v95(
        business_id,entity_type,entity_id,locale,name,tagline,description,
        terms,updated_by
      ) values(
        p_business,'offer',v_content.id,'en',btrim(p_name),
        nullif(btrim(coalesce(p_tagline,'')),''),
        btrim(p_description),nullif(btrim(coalesce(p_terms,'')),''),
        v_actor
      )
      returning * into v_copy;
    else
      update public.business_localized_copy_v95
      set name=btrim(p_name),
          tagline=nullif(btrim(coalesce(p_tagline,'')),''),
          description=btrim(p_description),
          terms=nullif(btrim(coalesce(p_terms,'')),''),
          version=version+1,
          updated_by=v_actor,
          updated_at=now()
      where business_id=p_business
        and entity_type='offer'
        and entity_id=v_content.id
        and locale='en'
      returning * into v_copy;
    end if;
  end if;
  perform set_config('app.v104_promotion_write','',true);
  perform set_config('app.v104_promotion_copy_write','',true);

  select asset.id,asset.version,
    app.v95_public_media_url(asset.object_path) url,asset.alt_en
  into v_media_id,v_media_version,v_media_url,v_media_alt
  from public.business_media_assets_v95 asset
  where asset.business_id=p_business
    and asset.asset_kind='offer'
    and asset.entity_id=v_content.id
    and asset.customer_visible
    and (
      asset.branch_id is not distinct from v_content.branch_id
      or (v_content.branch_id is not null and asset.branch_id is null)
    )
  order by (asset.branch_id is not distinct from v_content.branch_id) desc,
    asset.updated_at desc,asset.id
  limit 1;

  select count(*)::integer into v_quota_used
  from public.business_customer_content_v95 content
  where content.business_id=p_business
    and content.content_type='offer'
    and content.metadata->>'schema'='nestly.promotion.v104'
    and content.metadata ? 'published_once_at';
  select count(*)::integer into v_published_count
  from public.business_customer_content_v95 content
  where content.business_id=p_business
    and content.content_type='offer'
    and content.active
    and (content.ends_at is null or content.ends_at>now());

  return jsonb_build_object(
    'id',v_content.id,
    'promotion_id',v_content.id,
    'business_id',v_content.business_id,
    'branch_id',v_content.branch_id,
    'status',case when v_content.active then 'published' else 'draft' end,
    'publish_state',case when v_content.active then 'published' else 'draft' end,
    'active',v_content.active,
    'display_order',v_content.display_order,
    'starts_at',v_content.starts_at,
    'ends_at',v_content.ends_at,
    'metadata',v_content.metadata,
    'content_version',v_content.version,
    'copy_version',v_copy.version,
    'name',v_copy.name,
    'tagline',v_copy.tagline,
    'description',v_copy.description,
    'terms',v_copy.terms,
    'image_url',v_media_url,
    'image_alt',v_media_alt,
    'media_asset_id',v_media_id,
    'media_version',coalesce(v_media_version,0),
    'quota_used',v_quota_used,
    'quota_limit',v_entitlement.max_published_offers,
    'published_count',v_published_count,
    'item',jsonb_build_object(
      'id',v_content.id,
      'branch_id',v_content.branch_id,
      'active',v_content.active,
      'publish_state',case
        when v_content.active then 'published' else 'draft' end,
      'starts_at',v_content.starts_at,
      'ends_at',v_content.ends_at,
      'display_order',v_content.display_order,
      'content_version',v_content.version,
      'copy_version',v_copy.version,
      'name',v_copy.name,
      'tagline',v_copy.tagline,
      'description',v_copy.description,
      'terms',v_copy.terms,
      'metadata',v_content.metadata,
      'image_url',v_media_url,
      'image_alt',v_media_alt,
      'media_asset_id',v_media_id,
      'media_version',coalesce(v_media_version,0)
    )
  );
end
$$;

--
-- Name: business_set_brand_presentation_v95(uuid, uuid, uuid, text, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.business_set_brand_presentation_v95(p_business uuid, p_logo_asset uuid, p_hero_asset uuid, p_hero_color text, p_expected_version bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $_$
declare v_row public.business_brand_presentation_v95%rowtype;
begin
  if not app.is_salon_owner(p_business) and not app.is_super_admin() then
    raise exception 'owner_required' using errcode='42501';end if;
  if coalesce(p_hero_color,'')!~'^#[0-9A-Fa-f]{6}$'
     or p_expected_version is null
     or (p_logo_asset is not null and not exists(
       select 1 from public.business_media_assets_v95
       where id=p_logo_asset and business_id=p_business
         and asset_kind='logo' and customer_visible
     ))
     or (p_hero_asset is not null and not exists(
       select 1 from public.business_media_assets_v95
       where id=p_hero_asset and business_id=p_business
         and asset_kind='hero' and customer_visible
     ))
  then raise exception 'valid visible brand assets and version are required'
    using errcode='22023';end if;
  select * into v_row from public.business_brand_presentation_v95
  where business_id=p_business for update;
  if v_row.version<>p_expected_version then raise exception 'brand_version_conflict'
    using errcode='40001';end if;
  update public.business_brand_presentation_v95
  set logo_asset_id=p_logo_asset,hero_asset_id=p_hero_asset,
    hero_color=upper(p_hero_color),version=version+1,
    updated_by=auth.uid(),updated_at=now()
  where business_id=p_business returning * into v_row;
  return jsonb_build_object(
    'business_id',p_business,'logo_asset_id',v_row.logo_asset_id,
    'hero_asset_id',v_row.hero_asset_id,'hero_color',v_row.hero_color,
    'version',v_row.version
  );
end
$_$;

--
-- Name: business_set_bringback_paused_v361(uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.business_set_bringback_paused_v361(p_business uuid, p_campaign uuid, p_paused boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_row public.bringback_campaigns_v361%rowtype;
begin
  if not app.c45_owner_loyalty_write(p_business) then
    raise exception 'owner loyalty configuration access required' using errcode='42501';
  end if;
  if p_paused is null then raise exception 'paused flag is required' using errcode='22023'; end if;
  update public.bringback_campaigns_v361 set active=not p_paused, updated_at=now(), updated_by=auth.uid()
   where id=p_campaign and business_id=p_business and deleted_at is null
   returning * into v_row;
  if not found then raise exception 'bring-back campaign not found in this business' using errcode='42704'; end if;
  insert into public.audit_log(business_id,actor,action,entity,entity_id,detail)
  values(p_business,auth.uid(),case when p_paused then 'bringback.paused' else 'bringback.unpaused' end,
    'bringback_campaigns_v361',p_campaign,jsonb_build_object('name',v_row.name));
  return jsonb_build_object('status','ok','campaign_id',p_campaign,'active',v_row.active);
end $$;

--
-- Name: business_set_checkout_catalogue_enabled_v94(uuid, boolean, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.business_set_checkout_catalogue_enabled_v94(p_business uuid, p_enabled boolean, p_expected_version bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_setting public.business_checkout_catalogue_settings_v94%rowtype;
begin
  if not app.is_salon_owner(p_business) and not app.is_super_admin() then
    raise exception 'owner_required' using errcode='42501';
  end if;
  if p_enabled is null or p_expected_version is null then
    raise exception 'enabled_and_expected_version_required' using errcode='22023';
  end if;
  select * into v_setting
  from public.business_checkout_catalogue_settings_v94
  where business_id=p_business for update;
  if not found then raise exception 'business_not_found' using errcode='22023';end if;
  if v_setting.version<>p_expected_version then
    raise exception 'checkout_catalogue_version_conflict' using errcode='40001';
  end if;
  update public.business_checkout_catalogue_settings_v94
  set owner_enabled=p_enabled,version=version+1,
    updated_by=auth.uid(),updated_at=now()
  where business_id=p_business returning * into v_setting;
  update public.businesses
  set quick_earn_catalogue_enabled=(
    v_setting.platform_allowed and v_setting.owner_enabled
  ) where id=p_business;
  insert into public.audit_log(
    business_id,actor,action,entity,entity_id,detail
  ) values(
    p_business,auth.uid(),'CHECKOUT_CATALOGUE_ENABLED_SET_V94',
    'businesses',p_business,jsonb_build_object(
      'owner_enabled',v_setting.owner_enabled,
      'platform_allowed',v_setting.platform_allowed,
      'effective_enabled',
        v_setting.platform_allowed and v_setting.owner_enabled,
      'version',v_setting.version
    )
  );
  return jsonb_build_object(
    'business_id',p_business,
    'platform_allowed',v_setting.platform_allowed,
    'enabled',v_setting.platform_allowed and v_setting.owner_enabled,
    'settings_version',v_setting.version
  );
end
$$;

--
-- Name: business_set_checkout_catalogue_item_v94(uuid, text, uuid, boolean, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.business_set_checkout_catalogue_item_v94(p_business uuid, p_item_type text, p_item uuid, p_active boolean, p_expected_version bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_item public.business_checkout_catalogue_items_v94%rowtype;
begin
  if not app.is_salon_owner(p_business) and not app.is_super_admin() then
    raise exception 'owner_required' using errcode='42501';
  end if;
  if p_item_type not in ('service','product') or p_item is null
     or p_active is null or p_expected_version is null
  then
    raise exception 'valid_item_type_item_active_and_version_required'
      using errcode='22023';
  end if;
  if (
    p_item_type='service' and not exists(
      select 1 from public.services service
      where service.id=p_item and service.business_id=p_business
    )
  ) or (
    p_item_type='product' and not exists(
      select 1 from public.products product
      where product.id=p_item and product.business_id=p_business
    )
  ) then
    raise exception 'catalogue_item_not_in_business' using errcode='22023';
  end if;
  select * into v_item
  from public.business_checkout_catalogue_items_v94 item
  where item.business_id=p_business and item.item_type=p_item_type
    and item.item_id=p_item
  for update;
  if found then
    if v_item.version<>p_expected_version then
      raise exception 'checkout_catalogue_item_version_conflict'
        using errcode='40001';
    end if;
    update public.business_checkout_catalogue_items_v94
    set checkout_active=p_active,version=version+1,
      updated_by=auth.uid(),updated_at=now()
    where business_id=p_business and item_type=p_item_type and item_id=p_item
    returning * into v_item;
  else
    if p_expected_version<>0 then
      raise exception 'checkout_catalogue_item_version_conflict'
        using errcode='40001';
    end if;
    insert into public.business_checkout_catalogue_items_v94(
      business_id,item_type,item_id,checkout_active,updated_by
    ) values(p_business,p_item_type,p_item,p_active,auth.uid())
    returning * into v_item;
  end if;
  insert into public.audit_log(
    business_id,actor,action,entity,entity_id,detail
  ) values(
    p_business,auth.uid(),'CHECKOUT_CATALOGUE_ITEM_SET_V94',
    p_item_type,p_item,jsonb_build_object(
      'checkout_active',v_item.checkout_active,'version',v_item.version
    )
  );
  return jsonb_build_object(
    'business_id',p_business,'item_type',v_item.item_type,
    'item_id',v_item.item_id,'checkout_active',v_item.checkout_active,
    'version',v_item.version
  );
end
$$;

--
-- Name: business_set_customer_capabilities_v89(uuid, boolean, boolean, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.business_set_customer_capabilities_v89(p_business uuid, p_booking_enabled boolean, p_redemption_enabled boolean, p_appointment_changes_enabled boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_row public.business_customer_capabilities_v89%rowtype;
begin
  if not (app.is_salon_owner(p_business) or app.is_super_admin()) then
    raise exception 'business owner access is required' using errcode='42501';
  end if;
  insert into public.business_customer_capabilities_v89(
    business_id,booking_enabled,redemption_enabled,
    appointment_changes_enabled,updated_by
  ) values(
    p_business,coalesce(p_booking_enabled,false),
    coalesce(p_redemption_enabled,false),
    coalesce(p_appointment_changes_enabled,false),auth.uid()
  )
  on conflict(business_id) do update set
    booking_enabled=excluded.booking_enabled,
    redemption_enabled=excluded.redemption_enabled,
    appointment_changes_enabled=excluded.appointment_changes_enabled,
    updated_by=auth.uid(),updated_at=now()
  returning * into v_row;
  insert into public.audit_log(business_id,actor,action,entity,entity_id,detail)
  values(p_business,auth.uid(),'SET_CUSTOMER_CAPABILITIES_V89',
    'business_customer_capabilities_v89',p_business,
    jsonb_build_object('booking_enabled',v_row.booking_enabled,
      'redemption_enabled',v_row.redemption_enabled,
      'appointment_changes_enabled',v_row.appointment_changes_enabled));
  return jsonb_build_object(
    'business_id',p_business,
    'booking_enabled',v_row.booking_enabled
      and app.v89_business_module_enabled(p_business,'bookings'),
    'redemption_enabled',v_row.redemption_enabled
      and app.v89_business_module_enabled(p_business,'loyalty'),
    'appointment_changes_enabled',v_row.appointment_changes_enabled
      and app.v89_business_module_enabled(p_business,'appointments'),
    'configured',jsonb_build_object(
      'booking_enabled',v_row.booking_enabled,
      'redemption_enabled',v_row.redemption_enabled,
      'appointment_changes_enabled',v_row.appointment_changes_enabled),
    'updated_at',v_row.updated_at
  );
end
$$;

--
-- Name: business_set_earning_rule_v359(uuid, numeric, integer, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.business_set_earning_rule_v359(p_business uuid, p_earn_points_per_dollar numeric DEFAULT NULL::numeric, p_stamp_per_cents integer DEFAULT NULL::integer, p_expiry_mode text DEFAULT NULL::text, p_expiry_days integer DEFAULT NULL::integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_mode text := nullif(btrim(coalesce(p_expiry_mode,'')),'');
  v_days integer;
  v_row public.loyalty_programs%rowtype;
begin
  if not app.c45_owner_loyalty_write(p_business) then
    raise exception 'owner loyalty configuration access required' using errcode='42501';
  end if;

  if p_earn_points_per_dollar is not null and p_earn_points_per_dollar <= 0 then
    raise exception 'points per dollar must be greater than zero' using errcode='22023';
  end if;
  if p_stamp_per_cents is not null and p_stamp_per_cents <= 0 then
    raise exception 'spend per stamp must be greater than zero' using errcode='22023';
  end if;

  if v_mode is not null then
    if v_mode not in ('none','fixed','inactivity') then
      raise exception 'invalid expiry mode' using errcode='22023';
    end if;
    if v_mode = 'none' then
      v_days := null;
    else
      v_days := p_expiry_days;
      if v_days is null or v_days < 1 or v_days > 3650 then
        raise exception 'expiry days must be between 1 and 3650' using errcode='22023';
      end if;
    end if;
  end if;

  insert into public.loyalty_programs(business_id, active, configuration_status,
    earn_points_per_dollar, stamp_per_cents, expiry_mode, expiry_days)
  values (p_business, false, 'draft',
    coalesce(p_earn_points_per_dollar, 1), p_stamp_per_cents,
    coalesce(v_mode, 'none'), v_days)
  on conflict (business_id) do update set
    -- NB: must test the PARAMETER, not `excluded`. The INSERT arm defaults an omitted rate to 1,
    -- so `excluded.earn_points_per_dollar` is never null and a coalesce here would silently reset
    -- a firm's real rate to 1 on any call that only meant to change the stamp rate or expiry.
    -- (Caught by the rolled-back verification below before this ever reached production.)
    earn_points_per_dollar = case when p_earn_points_per_dollar is null then public.loyalty_programs.earn_points_per_dollar else excluded.earn_points_per_dollar end,
    stamp_per_cents        = case when p_stamp_per_cents is null then public.loyalty_programs.stamp_per_cents else excluded.stamp_per_cents end,
    expiry_mode            = case when v_mode is null then public.loyalty_programs.expiry_mode else excluded.expiry_mode end,
    expiry_days            = case when v_mode is null then public.loyalty_programs.expiry_days else excluded.expiry_days end
  returning * into v_row;

  insert into public.audit_log(business_id, actor, action, entity, entity_id, detail)
  values (p_business, auth.uid(), 'earning_rule.updated', 'loyalty_programs', p_business,
    jsonb_build_object('earn_points_per_dollar', v_row.earn_points_per_dollar,
                       'stamp_per_cents', v_row.stamp_per_cents,
                       'expiry_mode', v_row.expiry_mode, 'expiry_days', v_row.expiry_days));

  return jsonb_build_object('status','ok',
    'earn_points_per_dollar', v_row.earn_points_per_dollar,
    'stamp_per_cents', v_row.stamp_per_cents,
    'expiry_mode', v_row.expiry_mode, 'expiry_days', v_row.expiry_days);
end
$$;

--
-- Name: business_set_gallery_v418(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.business_set_gallery_v418(p_business uuid, p_items jsonb DEFAULT '[]'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $_$
declare
  v_count integer;
begin
  if not app.is_salon_owner(p_business) then
    raise exception 'owner access required to edit the business profile' using errcode='42501';
  end if;
  if jsonb_typeof(coalesce(p_items,'[]'::jsonb)) <> 'array' then
    raise exception 'gallery must be a list of photos' using errcode='22023';
  end if;
  select count(*) into v_count from jsonb_array_elements(coalesce(p_items,'[]'::jsonb));
  if v_count > 12 then
    raise exception 'a profile gallery holds up to 12 photos' using errcode='23514';
  end if;

  /* Every image must be one THIS business owns, in the gallery folder. The check is here and not
     only in the browser because the browser is not a place a rule can live: without it an owner
     could point a row at another firm's storage object and the customer app would render it. */
  if exists(
    select 1 from jsonb_array_elements(coalesce(p_items,'[]'::jsonb)) item
     where coalesce(item->>'image_ref','') !~ (
       '/storage/v1/object/public/business-public/'||p_business::text||'/gallery/'||
       '[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}\.(png|jpg|jpeg|webp|gif)$')
  ) then
    raise exception 'a gallery photo must be an image uploaded to this business' using errcode='22023';
  end if;

  delete from public.business_gallery_v418 where business_id = p_business;
  insert into public.business_gallery_v418(business_id, image_ref, caption, sort, created_by)
  select p_business,
         item->>'image_ref',
         nullif(btrim(coalesce(item->>'caption','')),''),
         (ordinality - 1)::integer,
         auth.uid()
    from jsonb_array_elements(coalesce(p_items,'[]'::jsonb)) with ordinality as t(item, ordinality);

  insert into public.audit_log(business_id, actor, action, entity, entity_id, detail)
  values (p_business, auth.uid(), 'business_profile.gallery_set', 'businesses', p_business,
    jsonb_build_object('photos', v_count));

  return jsonb_build_object('status','ok','photos', v_count);
end $_$;

--
-- Name: business_set_join_qr_print_lock_v198(uuid, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.business_set_join_qr_print_lock_v198(p_business uuid, p_locked boolean, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_actor uuid:=auth.uid(); v_id uuid; v_was timestamptz;
begin
  if not (app.is_salon_owner(p_business) or app.is_super_admin()) then
    raise exception 'business owner access is required' using errcode='42501';
  end if;
  if p_locked is null then
    raise exception 'lock state is required' using errcode='22023';
  end if;

  select id,print_locked_at into v_id,v_was
  from public.business_customer_join_qr_v89
  where business_id=p_business and status='active'
  order by expires_at desc,id desc limit 1;
  if v_id is null then
    raise exception 'there is no active QR to lock' using errcode='22023';
  end if;

  update public.business_customer_join_qr_v89
     set print_locked_at=case when p_locked then coalesce(print_locked_at,now()) end,
         print_locked_by=case when p_locked then coalesce(print_locked_by,v_actor) end
   where id=v_id;

  insert into public.audit_log(business_id,actor,action,entity,entity_id,detail)
  values(p_business,v_actor,
    case when p_locked then 'LOCK_JOIN_QR_FOR_PRINT_V198' else 'UNLOCK_JOIN_QR_V198' end,
    'business_customer_join_qr_v89',v_id,
    jsonb_build_object('reason',nullif(btrim(coalesce(p_reason,'')),''),
      'was_locked',v_was is not null));
  return jsonb_build_object('business_id',p_business,'qr_id',v_id,
    'print_locked',p_locked,'changed',(v_was is not null)<>p_locked);
end $$;

--
-- Name: business_set_loyalty_model_v353(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.business_set_loyalty_model_v353(p_business uuid, p_model text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_kind text;
begin
  if not app.c45_owner_loyalty_write(p_business) then
    raise exception 'owner loyalty configuration access required' using errcode='42501';
  end if;
  if p_model is null or p_model not in ('classic','points_tiers','stamps') then
    raise exception 'invalid loyalty model' using errcode='22023';
  end if;
  v_kind := case when p_model='stamps' then 'stamps' else 'points' end;

  -- active must be false while configuration_status stays at its table default 'draft' --
  -- loyalty_programs_configuration_status_check requires configuration_status='draft' => not
  -- active (same insert-path constraint v347 already worked around for tier_basis).
  insert into public.loyalty_programs(business_id, loyalty_model, kind, active, configuration_status)
  values (p_business, p_model, v_kind, false, 'draft')
  on conflict (business_id) do update set loyalty_model=excluded.loyalty_model, kind=excluded.kind;

  insert into public.audit_log(business_id,actor,action,entity,entity_id,detail)
  values(p_business,auth.uid(),'loyalty_model.updated','loyalty_programs',p_business,
    jsonb_build_object('loyalty_model',p_model,'kind',v_kind));

  return jsonb_build_object('status','ok','loyalty_model',p_model,'kind',v_kind);
end
$$;

--
-- Name: business_set_reward_paused_v326(uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.business_set_reward_paused_v326(p_business uuid, p_reward uuid, p_paused boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_row public.loyalty_rewards%rowtype;
begin
  if not app.c45_owner_loyalty_write(p_business) then
    raise exception 'owner loyalty configuration access required' using errcode='42501';
  end if;
  select * into v_row from public.loyalty_rewards
   where id=p_reward and business_id=p_business and active
   for update;
  if not found then
    raise exception 'gift not found in this business' using errcode='42704';
  end if;
  if v_row.paused is distinct from p_paused then
    update public.loyalty_rewards set paused=p_paused
     where id=p_reward and business_id=p_business;
    insert into public.audit_log(business_id,actor,action,entity,entity_id,detail)
    values(p_business,auth.uid(),case when p_paused then 'reward.paused' else 'reward.unpaused' end,
      'loyalty_rewards',p_reward,jsonb_build_object('name',coalesce(v_row.customer_name,v_row.name)));
  end if;
  return jsonb_build_object('status','ok','reward_id',p_reward,'paused',p_paused);
end
$$;

--
-- Name: business_set_sales_mix_v184(uuid, boolean, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.business_set_sales_mix_v184(p_business uuid, p_sells_services boolean, p_sells_products boolean) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_role text; v_modules text[]; v_removed text[] := '{}'; v_dependent text;
begin
  select s.role into v_role from public.staff s
   where s.business_id=p_business and s.user_id=auth.uid() and s.active
   order by case when s.role='owner' then 0 else 1 end, s.created_at limit 1;
  if v_role is distinct from 'owner' then
    raise exception 'only an owner can change what this business sells' using errcode='42501';
  end if;
  if not coalesce(p_sells_services,false) and not coalesce(p_sells_products,false) then
    raise exception 'a business must sell services, products, or both' using errcode='22023';
  end if;
  select coalesce(enabled_modules,'{}'::text[]) into v_modules
    from public.businesses where id=p_business for update;
  if not found then raise exception 'business not found' using errcode='42704'; end if;

  if p_sells_services then
    if not ('services'=any(v_modules)) then v_modules := v_modules || array['services']; end if;
  else
    for v_dependent in select r.module_key from public.module_registry r
      where 'services'=any(r.requires_modules) and r.module_key=any(v_modules)
    loop v_modules := array_remove(v_modules,v_dependent); v_removed := v_removed || v_dependent; end loop;
    v_modules := array_remove(v_modules,'services');
  end if;
  if p_sells_products then
    if not ('inventory'=any(v_modules)) then v_modules := v_modules || array['inventory']; end if;
  else
    for v_dependent in select r.module_key from public.module_registry r
      where 'inventory'=any(r.requires_modules) and r.module_key=any(v_modules)
    loop v_modules := array_remove(v_modules,v_dependent); v_removed := v_removed || v_dependent; end loop;
    v_modules := array_remove(v_modules,'inventory');
  end if;

  perform set_config('app.sector_entitlement_sync', p_business::text, true);
  update public.businesses set enabled_modules=v_modules where id=p_business;
  perform set_config('app.sector_entitlement_sync','',true);

  select coalesce(enabled_modules,'{}'::text[]) into v_modules
    from public.businesses where id=p_business;

  insert into public.audit_log(business_id, actor, action, entity, entity_id, detail)
  values (p_business, auth.uid(), 'business.sales_mix_changed', 'business', p_business,
          jsonb_build_object('sells_services',p_sells_services,'sells_products',p_sells_products,
                             'also_disabled',to_jsonb(v_removed)));

  return json_build_object('status','ok',
    'sells_services',('services'=any(v_modules)),
    'sells_products',('inventory'=any(v_modules)),
    'also_disabled',to_json(v_removed));
end $$;

--
-- Name: business_set_social_links_v418(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.business_set_social_links_v418(p_business uuid, p_links jsonb DEFAULT '[]'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_count integer;
begin
  if not app.is_salon_owner(p_business) then
    raise exception 'owner access required to edit the business profile' using errcode='42501';
  end if;
  if jsonb_typeof(coalesce(p_links,'[]'::jsonb)) <> 'array' then
    raise exception 'links must be a list' using errcode='22023';
  end if;

  delete from public.business_social_links_v418 where business_id = p_business;
  /* The platform and https CHECKs on the table do the validating, so a bad row raises with the
     constraint's own message rather than a second, hand-written copy of the same rule that could
     drift from it. Blank urls are dropped rather than refused: an owner clearing one field should
     not have to delete the row to save the others. */
  insert into public.business_social_links_v418(business_id, platform, url, sort)
  select p_business,
         lower(btrim(link->>'platform')),
         btrim(link->>'url'),
         (ordinality - 1)::integer
    from jsonb_array_elements(coalesce(p_links,'[]'::jsonb)) with ordinality as t(link, ordinality)
   where btrim(coalesce(link->>'url','')) <> '';
  get diagnostics v_count = row_count;

  insert into public.audit_log(business_id, actor, action, entity, entity_id, detail)
  values (p_business, auth.uid(), 'business_profile.links_set', 'businesses', p_business,
    jsonb_build_object('links', v_count));

  return jsonb_build_object('status','ok','links', v_count);
end $$;

--
-- Name: business_set_stamp_card_length_v414(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.business_set_stamp_card_length_v414(p_business uuid, p_stamps integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_spine uuid;
  v_blocker record;
  v_row public.loyalty_programs%rowtype;
begin
  if not app.c45_owner_loyalty_write(p_business) then
    raise exception 'owner loyalty configuration access required' using errcode='42501';
  end if;
  if p_stamps is null or p_stamps < 1 or p_stamps > 100 then
    raise exception 'a stamp card must be between 1 and 100 stamps long' using errcode='22023';
  end if;

  select id into v_spine from public.business_programmes
   where business_id = p_business and kind = 'stamps';
  if v_spine is null then
    raise exception 'this business is not running a stamp card' using errcode='XX001';
  end if;

  /* The redeemability test app.redeem_reward_core itself applies, asked BEFORE the write rather
     than after a customer is standing at the counter. It reads the VERSION row joined to the
     firm's active config version — the same row the claim path resolves — because that, and not
     loyalty_rewards.cost_points, is the number the refusal compares against. */
  select rv.customer_name as name, rv.cost_points as stamps into v_blocker
    from public.loyalty_reward_versions rv
    join public.businesses b on b.active_config_version_id = rv.config_version_id
    join public.loyalty_rewards r on r.id = rv.reward_id
   where rv.business_id = p_business
     and rv.programme_id = v_spine
     and coalesce(rv.active, true)
     and coalesce(r.active, true)
     and not coalesce(r.paused, false)
     and rv.cost_points > p_stamps
   order by rv.cost_points desc
   limit 1;
  if found then
    raise exception '% needs % stamps, so a % stamp card would put it out of reach. Move or remove that gift first.',
      coalesce(v_blocker.name,'A gift'), v_blocker.stamps, p_stamps
      using errcode='23514';
  end if;

  update public.loyalty_programs
     set stamp_target = p_stamps
   where business_id = p_business
  returning * into v_row;
  if not found then
    raise exception 'this business has no loyalty programme row' using errcode='XX001';
  end if;

  insert into public.audit_log(business_id, actor, action, entity, entity_id, detail)
  values (p_business, auth.uid(), 'stamp_card.length_set', 'loyalty_programs', p_business,
    jsonb_build_object('stamp_target', v_row.stamp_target));

  return jsonb_build_object('status','ok','stamp_target', v_row.stamp_target);
end $$;

--
-- Name: FUNCTION business_set_stamp_card_length_v414(p_business uuid, p_stamps integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.business_set_stamp_card_length_v414(p_business uuid, p_stamps integer) IS 'v414: set the stamp card length (loyalty_programs.stamp_target) from the Stamp Card page. Refuses a length that would put a live gift past the end of the card, which app.redeem_reward_core rejects at claim time.';

--
-- Name: business_set_tier_basis_v347(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.business_set_tier_basis_v347(p_business uuid, p_basis text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_basis text := nullif(btrim(coalesce(p_basis,'')),'');
begin
  if not app.c45_owner_loyalty_write(p_business) then
    raise exception 'owner loyalty configuration access required' using errcode='42501';
  end if;
  if v_basis is null or v_basis not in ('visits','spend','points_earned') then
    raise exception 'invalid tier basis' using errcode='22023';
  end if;

  -- active must be false while configuration_status stays at its table default 'draft' --
  -- loyalty_programs_configuration_status_check requires configuration_status='draft' => not
  -- active (confirmed live: the executor validates row constraints against the proposed INSERT
  -- row, defaults included, before ON CONFLICT ever resolves — a bare default-column insert here
  -- throws 23514 even though the actual outcome for an existing row is always the UPDATE branch).
  -- Mirrors create_business's own insert shape (business_id,kind,active,loyalty_model,
  -- configuration_status) for the only-ever-hit-on-a-missing-row path.
  insert into public.loyalty_programs(business_id, tier_basis, active, configuration_status)
  values (p_business, v_basis, false, 'draft')
  on conflict (business_id) do update set tier_basis=excluded.tier_basis;

  insert into public.audit_log(business_id,actor,action,entity,entity_id,detail)
  values(p_business,auth.uid(),'tier_basis.updated','loyalty_programs',p_business,
    jsonb_build_object('tier_basis',v_basis));

  return jsonb_build_object('status','ok','tier_basis',v_basis);
end
$$;

--
-- Name: business_set_tier_benefits_v365(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.business_set_tier_benefits_v365(p_business uuid, p_tier uuid, p_benefits jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_item jsonb;
  v_index integer := 0;
  v_keep uuid[] := array[]::uuid[];
  v_id uuid;
  v_label text;
  v_limit integer;
  v_period text;
  v_kind text;
  v_discount numeric;
  v_product uuid;
  v_item_label text;
begin
  if not app.c45_owner_loyalty_write(p_business) then
    raise exception 'owner loyalty configuration access required' using errcode='42501';
  end if;
  perform 1 from public.loyalty_tiers where id=p_tier and business_id=p_business;
  if not found then
    raise exception 'tier not found in this business' using errcode='42704';
  end if;
  if p_benefits is not null and jsonb_typeof(p_benefits) <> 'array' then
    raise exception 'benefits must be an array' using errcode='22023';
  end if;

  for v_item in select * from jsonb_array_elements(coalesce(p_benefits,'[]'::jsonb)) loop
    v_kind := coalesce(nullif(btrim(coalesce(v_item->>'benefit_kind','')),''),'custom');
    if v_kind not in ('discount_pct','free_item','custom') then
      raise exception 'benefit kind must be a discount, a free item, or your own wording' using errcode='22023';
    end if;
    v_discount := nullif(v_item->>'discount_percent','')::numeric;
    v_product := nullif(v_item->>'product_id','')::uuid;
    v_item_label := nullif(btrim(coalesce(v_item->>'item_label','')),'');

    if v_kind='discount_pct' then
      if v_discount is null or v_discount <= 0 or v_discount > 100 then
        raise exception 'a discount must be between 0.01 and 100 percent' using errcode='22023';
      end if;
      v_product := null; v_item_label := null;
    elsif v_kind='free_item' then
      if v_product is not null then
        perform 1 from public.products where id=v_product and business_id=p_business;
        if not found then
          raise exception 'that product does not belong to this business' using errcode='42704';
        end if;
        v_item_label := null;
      elsif v_item_label is null then
        raise exception 'say which item is free, or pick one from your products' using errcode='22023';
      end if;
      v_discount := null;
    else
      v_discount := null; v_product := null; v_item_label := null;
    end if;

    -- Derived for the structured kinds; the owner's own words for 'custom'.
    v_label := app.v369_benefit_label(v_kind, v_discount, v_product, v_item_label,
                 nullif(btrim(coalesce(v_item->>'label','')),''));
    if v_label is null or btrim(v_label)='' then
      raise exception 'every benefit needs a description' using errcode='22023';
    end if;

    v_limit := nullif(v_item->>'limit_count','')::integer;
    v_period := coalesce(nullif(btrim(coalesce(v_item->>'limit_period','')),''),'month');
    if v_period not in ('day','week','month','year','ever','birthday_month') then
      raise exception 'benefit period is not one of day/week/month/year/ever/birthday_month' using errcode='22023';
    end if;
    if v_limit is not null and (v_limit < 1 or v_limit > 10000) then
      raise exception 'a benefit limit must be between 1 and 10000' using errcode='22023';
    end if;

    v_id := nullif(v_item->>'id','')::uuid;
    if v_id is not null then
      update public.tier_benefits_v365
         set label=v_label, limit_count=v_limit, limit_period=v_period, sort=v_index,
             benefit_kind=v_kind, discount_percent=v_discount, product_id=v_product, item_label=v_item_label,
             active=true, deleted_at=null, updated_at=now(), updated_by=auth.uid()
       where id=v_id and business_id=p_business and tier_id=p_tier;
      if not found then
        raise exception 'benefit not found on this tier' using errcode='42704';
      end if;
    else
      insert into public.tier_benefits_v365(business_id,tier_id,label,limit_count,limit_period,sort,
        benefit_kind,discount_percent,product_id,item_label,updated_by)
      values(p_business,p_tier,v_label,v_limit,v_period,v_index,
        v_kind,v_discount,v_product,v_item_label,auth.uid())
      returning id into v_id;
    end if;
    v_keep := v_keep || v_id;
    v_index := v_index + 1;
  end loop;

  update public.tier_benefits_v365
     set deleted_at=now(), active=false, updated_at=now(), updated_by=auth.uid()
   where business_id=p_business and tier_id=p_tier and deleted_at is null
     and not (id = any(v_keep));

  perform app.v365_apply_perk_note(p_business,p_tier);

  insert into public.audit_log(business_id,actor,action,entity,entity_id,detail)
  values(p_business,auth.uid(),'tier_benefits.set','loyalty_tiers',p_tier,
    jsonb_build_object('count',v_index));

  return jsonb_build_object('status','ok','tier_id',p_tier,'count',v_index,
    'perk_note',(select perk_note from public.loyalty_tiers where id=p_tier and business_id=p_business));
end $$;

--
-- Name: business_set_tier_paused_v331(uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.business_set_tier_paused_v331(p_business uuid, p_tier uuid, p_paused boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_row public.loyalty_tiers%rowtype;
begin
  if not app.c45_owner_loyalty_write(p_business) then
    raise exception 'owner loyalty configuration access required' using errcode='42501';
  end if;
  if p_paused is null then
    raise exception 'paused flag is required' using errcode='22023';
  end if;
  select * into v_row from public.loyalty_tiers
   where id=p_tier and business_id=p_business and deleted_at is null
   for update;
  if not found then
    raise exception 'tier not found in this business' using errcode='42704';
  end if;
  if v_row.paused is distinct from p_paused then
    update public.loyalty_tiers set paused=p_paused
     where id=p_tier and business_id=p_business;
    insert into public.audit_log(business_id,actor,action,entity,entity_id,detail)
    values(p_business,auth.uid(),case when p_paused then 'tier.paused' else 'tier.unpaused' end,
      'loyalty_tiers',p_tier,jsonb_build_object('name',v_row.name,'threshold',v_row.threshold));
  end if;
  return jsonb_build_object('status','ok','tier_id',p_tier,'paused',p_paused);
end
$$;

--
-- Name: business_set_welcome_offer_v215(uuid, boolean, integer, text, uuid, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.business_set_welcome_offer_v215(p_business uuid, p_active boolean, p_min_spend_cents integer, p_reward_catalog_kind text, p_reward_catalog_id uuid, p_expiry_days integer DEFAULT NULL::integer, p_custom_label text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_label text;
  v_custom text := nullif(btrim(coalesce(p_custom_label,'')),'');
  v_row public.business_welcome_offers_v215%rowtype;
begin
  if v_actor is null then
    raise exception 'authenticated staff required' using errcode='42501';
  end if;
  if not (app.is_salon_owner(p_business) or app.can_module_write(p_business,'loyalty')) then
    raise exception 'welcome offer authorization required' using errcode='42501';
  end if;
  if p_reward_catalog_kind is null or p_reward_catalog_kind not in ('service','product','custom') then
    raise exception 'reward_catalog_kind must be service, product or custom' using errcode='22023';
  end if;
  if coalesce(p_min_spend_cents,0) < 0 or coalesce(p_min_spend_cents,0) > 100000000 then
    raise exception 'min_spend_cents out of range' using errcode='22023';
  end if;
  if p_expiry_days is not null and (p_expiry_days < 1 or p_expiry_days > 3650) then
    raise exception 'expiry_days must be between 1 and 3650' using errcode='22023';
  end if;

  if p_reward_catalog_kind = 'custom' then
    if v_custom is null or char_length(v_custom) > 120 then
      raise exception 'welcome_offer_custom_label_required' using errcode='22023';
    end if;
    v_label := v_custom;
  else
    if p_reward_catalog_kind = 'service' then
      select name into v_label from public.services
      where id = p_reward_catalog_id and business_id = p_business and active;
    else
      select name into v_label from public.products
      where id = p_reward_catalog_id and business_id = p_business and active;
    end if;
    if v_label is null then
      raise exception 'welcome_offer_item_unavailable' using errcode='22023';
    end if;
  end if;

  insert into public.business_welcome_offers_v215 as offer(
    business_id, active, min_spend_cents, reward_catalog_kind,
    reward_catalog_id, custom_label, reward_label, expiry_days, updated_by, updated_at
  ) values (
    p_business, coalesce(p_active,false), coalesce(p_min_spend_cents,0),
    p_reward_catalog_kind, case when p_reward_catalog_kind='custom' then null else p_reward_catalog_id end,
    v_custom, v_label, p_expiry_days, v_actor, now()
  )
  on conflict (business_id) do update set
    active = excluded.active,
    min_spend_cents = excluded.min_spend_cents,
    reward_catalog_kind = excluded.reward_catalog_kind,
    reward_catalog_id = excluded.reward_catalog_id,
    custom_label = excluded.custom_label,
    reward_label = excluded.reward_label,
    expiry_days = excluded.expiry_days,
    version = offer.version + 1,
    updated_by = excluded.updated_by,
    updated_at = now()
  returning * into v_row;

  insert into public.audit_log(business_id, actor, action, entity, entity_id, detail)
  values (p_business, v_actor, 'WELCOME_OFFER_SET_V215',
          'business_welcome_offers_v215', p_business, jsonb_build_object(
    'active', v_row.active, 'min_spend_cents', v_row.min_spend_cents,
    'reward_catalog_kind', v_row.reward_catalog_kind,
    'reward_catalog_id', v_row.reward_catalog_id,
    'reward_label', v_row.reward_label, 'expiry_days', v_row.expiry_days,
    'version', v_row.version));

  return jsonb_build_object(
    'status','ok','active',v_row.active,'min_spend_cents',v_row.min_spend_cents,
    'reward_catalog_kind',v_row.reward_catalog_kind,
    'reward_catalog_id',v_row.reward_catalog_id,
    'custom_label',v_row.custom_label,
    'reward_label',v_row.reward_label,'expiry_days',v_row.expiry_days,
    'version',v_row.version);
end
$$;

--
-- Name: business_switch_to_stamps_v384(uuid, boolean, integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.business_switch_to_stamps_v384(p_business uuid, p_convert_existing_points boolean, p_points_per_stamp integer, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_points_programme uuid;
  v_stamps_programme uuid;
  v_rate integer := coalesce(p_points_per_stamp, 0);
  v_existing jsonb;
  v_switch jsonb;
  v_row record;
  v_batch record;
  v_left integer;
  v_take integer;
  v_customers integer := 0;
  v_points integer := 0;
  v_stamps integer := 0;
  v_leftover integer := 0;
  v_response jsonb;
  v_spend_ledger_id uuid;
  v_issue_ledger_id uuid;
begin
  if p_idempotency_key is null then
    raise exception 'idempotency key is required' using errcode = '22023';
  end if;
  if not app.c45_owner_loyalty_write(p_business) then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  if coalesce(p_convert_existing_points, false) and v_rate <= 0 then
    raise exception 'points per stamp must be greater than zero' using errcode = '22023';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('v384:stamp-switch:'||p_business::text, 0));

  select response into v_existing
    from public.programme_stamp_conversions_v384
   where business_id = p_business and idempotency_key = p_idempotency_key;
  if found then
    return v_existing;
  end if;

  select id into v_points_programme
    from public.business_programmes
   where business_id = p_business and kind = 'points'
   order by sort, id
   limit 1;
  select id into v_stamps_programme
    from public.business_programmes
   where business_id = p_business and kind = 'stamps'
   order by sort, id
   limit 1;
  if v_points_programme is null or v_stamps_programme is null then
    raise exception 'points and stamp programmes are required' using errcode = '23514';
  end if;

  v_switch := public.set_programmes_v314(
    p_business,
    jsonb_build_object('stamps', true, 'points', false, 'tiers', false),
    p_idempotency_key
  );

  if coalesce(p_convert_existing_points, false) then
    if exists (
      select 1 from public.programme_stamp_conversions_v384 done
       where done.business_id = p_business
         and done.points_programme_id = v_points_programme
         and done.stamps_programme_id = v_stamps_programme
    ) then
      raise exception 'points have already been converted to this stamp card'
        using errcode = '23505';
    end if;

    for v_row in
      with balances as (
        select coalesce(l.client_id, b.client_id) as client_id,
               greatest(least(coalesce(l.points_balance, 0), coalesce(b.batch_balance, 0)), 0)::integer as spendable_points
          from (
            select client_id, sum(points)::integer as points_balance
              from public.points_ledger
             where business_id = p_business and programme_id = v_points_programme
             group by client_id
          ) l
          full join (
            select client_id, sum(remaining)::integer as batch_balance
              from public.points_batches
             where business_id = p_business
               and programme_id = v_points_programme
               and remaining > 0
             group by client_id
          ) b using (client_id)
      )
      select client_id,
             ((spendable_points / v_rate) * v_rate)::integer as points_to_convert,
             (spendable_points / v_rate)::integer as stamps_to_issue,
             (spendable_points - ((spendable_points / v_rate) * v_rate))::integer as leftover_points
        from balances
       where (spendable_points / v_rate)::integer > 0
       order by client_id
    loop
      v_left := v_row.points_to_convert;
      for v_batch in
        select id, remaining
          from public.points_batches
         where business_id = p_business
           and client_id = v_row.client_id
           and programme_id = v_points_programme
           and remaining > 0
         order by expires_at nulls last, earned_at, id
         for update
      loop
        exit when v_left = 0;
        v_take := least(v_batch.remaining, v_left);
        update public.points_batches
           set remaining = remaining - v_take
         where id = v_batch.id;
        v_left := v_left - v_take;
      end loop;
      if v_left <> 0 then
        raise exception 'could not prove points batch conversion for customer %', v_row.client_id
          using errcode = '23514';
      end if;

      -- V403 (owner, photo 3: "set up stamp does not work").
      -- The points_ledger guard (v312) admits an insert only when BOTH
      -- app.points_ledger_write_scope names an approved route AND
      -- app.points_ledger_insert_id equals the row's own id. v384 set the scope and never the
      -- token, and generated the ids inline so there was nothing to publish -- so both inserts
      -- below raised 42501 'points_ledger may only be appended by approved loyalty routes'.
      -- Any business holding points could therefore never switch to the stamp card.
      -- Each id is now generated into a variable and published before its own insert, the same
      -- shape every working route uses (see the points_expiry sweep in v312).
      v_spend_ledger_id := gen_random_uuid();
      perform set_config('app.points_ledger_insert_id', v_spend_ledger_id::text, true);
      perform set_config('app.points_ledger_write_scope', 'programme_pot_transfer', true);
      insert into public.points_ledger(
        id,business_id,client_id,entry_type,points,sale_id,reference,actor,programme_id
      ) values (
        v_spend_ledger_id, p_business, v_row.client_id, 'adjust', -v_row.points_to_convert,
        null, 'stamp conversion: points spent', null, v_points_programme
      );
      v_issue_ledger_id := gen_random_uuid();
      perform set_config('app.points_ledger_insert_id', v_issue_ledger_id::text, true);
      insert into public.points_ledger(
        id,business_id,client_id,entry_type,points,sale_id,reference,actor,programme_id
      ) values (
        v_issue_ledger_id, p_business, v_row.client_id, 'adjust', v_row.stamps_to_issue,
        null, 'stamp conversion: stamps issued', null, v_stamps_programme
      );
      perform set_config('app.points_ledger_insert_id', '', true);
      perform set_config('app.points_ledger_write_scope', '', true);

      insert into public.points_batches(
        business_id,client_id,earned,remaining,sale_id,earned_at,expires_at,programme_id
      ) values (
        p_business, v_row.client_id, v_row.stamps_to_issue, v_row.stamps_to_issue,
        null, statement_timestamp(), null, v_stamps_programme
      );

      v_customers := v_customers + 1;
      v_points := v_points + v_row.points_to_convert;
      v_stamps := v_stamps + v_row.stamps_to_issue;
      v_leftover := v_leftover + v_row.leftover_points;
    end loop;
  end if;

  v_response := jsonb_build_object(
    'ok', true,
    'converted', coalesce(p_convert_existing_points, false),
    'points_per_stamp', case when coalesce(p_convert_existing_points, false) then v_rate else null end,
    'customers', v_customers,
    'points_converted', v_points,
    'stamps_issued', v_stamps,
    'leftover_points', v_leftover,
    'programmes', v_switch->'programmes'
  );

  if coalesce(p_convert_existing_points, false) then
    insert into public.programme_stamp_conversions_v384(
      business_id,idempotency_key,points_programme_id,stamps_programme_id,
      points_per_stamp,converted_customers,converted_points,issued_stamps,leftover_points,response
    ) values (
      p_business,p_idempotency_key,v_points_programme,v_stamps_programme,
      v_rate,v_customers,v_points,v_stamps,v_leftover,v_response
    );
  end if;

  return v_response;
exception when others then
  perform set_config('app.points_ledger_insert_id', '', true);
  perform set_config('app.points_ledger_write_scope', '', true);
  raise;
end;
$$;

--
-- Name: FUNCTION business_switch_to_stamps_v384(p_business uuid, p_convert_existing_points boolean, p_points_per_stamp integer, p_idempotency_key uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.business_switch_to_stamps_v384(p_business uuid, p_convert_existing_points boolean, p_points_per_stamp integer, p_idempotency_key uuid) IS 'v403: publishes app.points_ledger_insert_id for each conversion row. v384 set only the write scope, so the v312 ledger guard rejected every insert with 42501 and no business holding points could switch to the stamp card.';

--
-- Name: business_update_reward_v326(uuid, uuid, text, integer, text, integer, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.business_update_reward_v326(p_business uuid, p_reward uuid, p_name text, p_points integer, p_description text DEFAULT NULL::text, p_credit_cents integer DEFAULT 0, p_image_ref text DEFAULT NULL::text, p_clear_image boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_row public.loyalty_rewards%rowtype;
  v_name text := nullif(btrim(coalesce(p_name,'')),'');
  v_description text := nullif(btrim(coalesce(p_description,'')),'');
begin
  if not app.c45_owner_loyalty_write(p_business) then
    raise exception 'owner loyalty configuration access required' using errcode='42501';
  end if;
  if v_name is null then
    raise exception 'gift name is required' using errcode='22023';
  end if;
  if p_points is null or p_points<=0 then
    raise exception 'points must be a positive number' using errcode='22023';
  end if;
  if p_credit_cents is not null and p_credit_cents<0 then
    raise exception 'credit_cents cannot be negative' using errcode='22023';
  end if;
  select * into v_row from public.loyalty_rewards
   where id=p_reward and business_id=p_business and active
   for update;
  if not found then
    raise exception 'gift not found in this business' using errcode='42704';
  end if;
  update public.loyalty_rewards
     set name=v_name, internal_name=v_name, customer_name=v_name,
         description=v_description, cost_points=p_points,
         credit_cents=coalesce(p_credit_cents,0), estimated_cost_cents=coalesce(p_credit_cents,0),
         image_ref=case when p_clear_image then null
                        when p_image_ref is not null then p_image_ref
                        else image_ref end
   where id=p_reward and business_id=p_business;
  insert into public.audit_log(business_id,actor,action,entity,entity_id,detail)
  values(p_business,auth.uid(),'reward.updated','loyalty_rewards',p_reward,
    jsonb_build_object('name',v_name,'cost_points',p_points,'credit_cents',coalesce(p_credit_cents,0)));
  return jsonb_build_object('status','ok','reward_id',p_reward,'name',v_name,
    'description',v_description,'cost_points',p_points,'credit_cents',coalesce(p_credit_cents,0));
end
$$;

--
-- Name: business_update_tier_v331(uuid, uuid, text, integer, text, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.business_update_tier_v331(p_business uuid, p_tier uuid, p_name text, p_threshold integer, p_perk_note text DEFAULT NULL::text, p_multiplier numeric DEFAULT 1) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_row public.loyalty_tiers%rowtype;
  v_name text := nullif(btrim(coalesce(p_name,'')),'');
  v_perk_note text := nullif(btrim(coalesce(p_perk_note,'')),'');
begin
  if not app.c45_owner_loyalty_write(p_business) then
    raise exception 'owner loyalty configuration access required' using errcode='42501';
  end if;
  if v_name is null or char_length(v_name)>120 then
    raise exception 'invalid tier name' using errcode='22023';
  end if;
  if p_threshold is null or p_threshold<0 then
    raise exception 'invalid tier threshold' using errcode='22023';
  end if;
  if p_multiplier is null or p_multiplier<1 then
    raise exception 'invalid tier multiplier' using errcode='22023';
  end if;
  select * into v_row from public.loyalty_tiers
   where id=p_tier and business_id=p_business and deleted_at is null
   for update;
  if not found then
    raise exception 'tier not found in this business' using errcode='42704';
  end if;
  update public.loyalty_tiers
     set name=v_name, threshold=p_threshold, points_multiplier=p_multiplier, perk_note=v_perk_note
   where id=p_tier and business_id=p_business;
  insert into public.audit_log(business_id,actor,action,entity,entity_id,detail)
  values(p_business,auth.uid(),'tier.updated','loyalty_tiers',p_tier,
    jsonb_build_object('name',v_name,'threshold',p_threshold,'points_multiplier',p_multiplier));
  return jsonb_build_object('status','ok','tier_id',p_tier,'name',v_name,'threshold',p_threshold,'perk_note',v_perk_note);
end
$$;

--
-- Name: business_upsert_bringback_v361(uuid, uuid, text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.business_upsert_bringback_v361(p_business uuid, p_campaign uuid, p_name text, p_reward_label text, p_away_days integer, p_expiry_days integer DEFAULT NULL::integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_name text := nullif(btrim(coalesce(p_name,'')),'');
  v_reward text := nullif(btrim(coalesce(p_reward_label,'')),'');
  v_row public.bringback_campaigns_v361%rowtype;
begin
  if not app.c45_owner_loyalty_write(p_business) then
    raise exception 'owner loyalty configuration access required' using errcode='42501';
  end if;
  if v_name is null then raise exception 'campaign name is required' using errcode='22023'; end if;
  if v_reward is null then raise exception 'reward is required' using errcode='22023'; end if;
  if p_away_days is null or p_away_days < 1 or p_away_days > 3650 then
    raise exception 'away days must be between 1 and 3650' using errcode='22023';
  end if;
  if p_expiry_days is not null and (p_expiry_days < 1 or p_expiry_days > 3650) then
    raise exception 'expiry days must be between 1 and 3650' using errcode='22023';
  end if;

  if p_campaign is null then
    insert into public.bringback_campaigns_v361(business_id,name,reward_label,away_days,expiry_days,updated_by)
    values (p_business,v_name,v_reward,p_away_days,p_expiry_days,auth.uid())
    returning * into v_row;
  else
    update public.bringback_campaigns_v361
       set name=v_name, reward_label=v_reward, away_days=p_away_days,
           expiry_days=p_expiry_days, updated_at=now(), updated_by=auth.uid()
     where id=p_campaign and business_id=p_business and deleted_at is null
     returning * into v_row;
    if not found then
      raise exception 'bring-back campaign not found in this business' using errcode='42704';
    end if;
  end if;

  insert into public.audit_log(business_id,actor,action,entity,entity_id,detail)
  values(p_business,auth.uid(),case when p_campaign is null then 'bringback.created' else 'bringback.updated' end,
    'bringback_campaigns_v361',v_row.id,
    jsonb_build_object('name',v_row.name,'reward_label',v_row.reward_label,
                       'away_days',v_row.away_days,'expiry_days',v_row.expiry_days));

  return jsonb_build_object('status','ok','campaign_id',v_row.id,'name',v_row.name,
    'reward_label',v_row.reward_label,'away_days',v_row.away_days,
    'expiry_days',v_row.expiry_days,'active',v_row.active);
end $$;

--
-- Name: business_upsert_customer_content_v95(uuid, text, uuid, uuid, boolean, integer, timestamp with time zone, timestamp with time zone, jsonb, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.business_upsert_customer_content_v95(p_business uuid, p_content_type text, p_content_id uuid, p_branch uuid, p_active boolean, p_display_order integer, p_starts_at timestamp with time zone, p_ends_at timestamp with time zone, p_metadata jsonb, p_expected_version bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_row public.business_customer_content_v95%rowtype;
begin
  if not app.is_salon_owner(p_business) and not app.is_super_admin() then
    raise exception 'owner_required' using errcode='42501';end if;
  if p_content_type not in ('benefit','offer') or p_active is null
     or p_display_order not between 0 and 10000
     or jsonb_typeof(coalesce(p_metadata,'null'::jsonb))<>'object'
     or p_expected_version is null
     or (p_branch is not null and not exists(
       select 1 from public.branches where id=p_branch and business_id=p_business
     ))
  then raise exception 'valid customer content fields are required'
    using errcode='22023';end if;
  if p_content_id is null then
    if p_expected_version<>0 then raise exception 'content_version_conflict'
      using errcode='40001';end if;
    insert into public.business_customer_content_v95(
      business_id,content_type,branch_id,active,display_order,starts_at,
      ends_at,metadata,updated_by
    ) values(
      p_business,p_content_type,p_branch,p_active,p_display_order,p_starts_at,
      p_ends_at,p_metadata,auth.uid()
    ) returning * into v_row;
  else
    select * into v_row from public.business_customer_content_v95
    where id=p_content_id and business_id=p_business for update;
    if not found then raise exception 'content_not_found' using errcode='22023';end if;
    if v_row.version<>p_expected_version then raise exception 'content_version_conflict'
      using errcode='40001';end if;
    update public.business_customer_content_v95
    set content_type=p_content_type,branch_id=p_branch,active=p_active,
      display_order=p_display_order,starts_at=p_starts_at,ends_at=p_ends_at,
      metadata=p_metadata,version=version+1,updated_by=auth.uid(),updated_at=now()
    where id=p_content_id returning * into v_row;
  end if;
  return jsonb_build_object(
    'id',v_row.id,'business_id',v_row.business_id,
    'content_type',v_row.content_type,'branch_id',v_row.branch_id,
    'active',v_row.active,'display_order',v_row.display_order,
    'starts_at',v_row.starts_at,'ends_at',v_row.ends_at,
    'metadata',v_row.metadata,'version',v_row.version
  );
end
$$;

--
-- Name: business_upsert_localized_copy_v95(uuid, text, uuid, text, text, text, text, text, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.business_upsert_localized_copy_v95(p_business uuid, p_entity_type text, p_entity_id uuid, p_locale text, p_name text, p_tagline text, p_description text, p_terms text, p_expected_version bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_row public.business_localized_copy_v95%rowtype;
begin
  if not app.is_salon_owner(p_business) and not app.is_super_admin() then
    raise exception 'owner_required' using errcode='42501';end if;
  if p_locale not in ('en','zh-CN')
     or not app.v95_entity_in_business(p_business,p_entity_type,p_entity_id)
     or length(btrim(coalesce(p_name,''))) not between 1 and 160
     or p_expected_version is null
  then raise exception 'valid localized entity copy is required'
    using errcode='22023';end if;
  select * into v_row from public.business_localized_copy_v95
  where business_id=p_business and entity_type=p_entity_type
    and entity_id=p_entity_id and locale=p_locale for update;
  if found then
    if v_row.version<>p_expected_version then raise exception 'copy_version_conflict'
      using errcode='40001';end if;
    update public.business_localized_copy_v95
    set name=btrim(p_name),tagline=nullif(btrim(coalesce(p_tagline,'')),''),
      description=nullif(btrim(coalesce(p_description,'')),''),
      terms=nullif(btrim(coalesce(p_terms,'')),''),
      version=version+1,updated_by=auth.uid(),updated_at=now()
    where business_id=p_business and entity_type=p_entity_type
      and entity_id=p_entity_id and locale=p_locale returning * into v_row;
  else
    if p_expected_version<>0 then raise exception 'copy_version_conflict'
      using errcode='40001';end if;
    insert into public.business_localized_copy_v95(
      business_id,entity_type,entity_id,locale,name,tagline,description,
      terms,updated_by
    ) values(
      p_business,p_entity_type,p_entity_id,p_locale,btrim(p_name),
      nullif(btrim(coalesce(p_tagline,'')),''),
      nullif(btrim(coalesce(p_description,'')),''),
      nullif(btrim(coalesce(p_terms,'')),''),auth.uid()
    ) returning * into v_row;
  end if;
  return to_jsonb(v_row)-'updated_by';
end
$$;

--
-- Name: business_upsert_media_asset_v95(uuid, text, uuid, uuid, text, text, integer, integer, text, text, boolean, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.business_upsert_media_asset_v95(p_business uuid, p_asset_kind text, p_entity_id uuid, p_branch uuid, p_object_path text, p_mime_type text, p_width_px integer, p_height_px integer, p_alt_en text, p_alt_zh_cn text, p_visible boolean, p_expected_version bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_row public.business_media_assets_v95%rowtype;
begin
  if not app.is_salon_owner(p_business) and not app.is_super_admin() then
    raise exception 'owner_required' using errcode='42501';end if;
  if p_asset_kind not in (
      'logo','hero','programme','reward','product','service','benefit','offer'
    ) or p_visible is distinct from false
     or not app.v95_storage_object_is_publishable(
       p_business,p_asset_kind,p_object_path,p_mime_type
     )
     or p_mime_type not in ('image/png','image/jpeg','image/webp','image/gif')
     or length(btrim(coalesce(p_alt_en,''))) not between 1 and 240
     or p_visible is null or p_expected_version is null
     or (p_asset_kind not in ('logo','hero') and (
       p_entity_id is null or not app.v95_entity_in_business(
         p_business,p_asset_kind,p_entity_id
       )
     ))
     or (p_asset_kind in ('logo','hero') and p_entity_id is not null)
     or (p_asset_kind in ('logo','hero') and p_branch is not null)
     or (p_branch is not null and not exists(
       select 1 from public.branches where id=p_branch and business_id=p_business
     ))
  then raise exception 'valid scoped media asset is required' using errcode='22023';end if;
  select * into v_row from public.business_media_assets_v95 asset
  where asset.business_id=p_business and asset.asset_kind=p_asset_kind
    and asset.entity_id is not distinct from p_entity_id
    and asset.branch_id is not distinct from p_branch for update;
  if found then
    if v_row.version<>p_expected_version then raise exception 'media_version_conflict'
      using errcode='40001';end if;
    update public.business_media_assets_v95
    set object_path=p_object_path,mime_type=p_mime_type,width_px=p_width_px,
      height_px=p_height_px,alt_en=btrim(p_alt_en),
      alt_zh_cn=nullif(btrim(coalesce(p_alt_zh_cn,'')),''),
      customer_visible=p_visible,version=version+1,updated_by=auth.uid(),
      updated_at=now()
    where id=v_row.id returning * into v_row;
  else
    if p_expected_version<>0 then raise exception 'media_version_conflict'
      using errcode='40001';end if;
    insert into public.business_media_assets_v95(
      business_id,asset_kind,entity_id,branch_id,object_path,mime_type,
      width_px,height_px,alt_en,alt_zh_cn,customer_visible,updated_by
    ) values(
      p_business,p_asset_kind,p_entity_id,p_branch,p_object_path,p_mime_type,
      p_width_px,p_height_px,btrim(p_alt_en),
      nullif(btrim(coalesce(p_alt_zh_cn,'')),''),p_visible,auth.uid()
    ) returning * into v_row;
  end if;
  return jsonb_build_object(
    'id',v_row.id,'asset_kind',v_row.asset_kind,'entity_id',v_row.entity_id,
    'branch_id',v_row.branch_id,'object_path',v_row.object_path,
    'url',app.v95_public_media_url(v_row.object_path),
    'mime_type',v_row.mime_type,'width_px',v_row.width_px,
    'height_px',v_row.height_px,'alt_en',v_row.alt_en,
    'alt_zh_cn',v_row.alt_zh_cn,'customer_visible',v_row.customer_visible,
    'version',v_row.version
  );
end
$$;

--
-- Name: cancel_growth_delivery_v110(uuid, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_growth_delivery_v110(p_business uuid, p_dispatch uuid, p_reason text, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_identity text;
  v_hash text;
  v_receipt jsonb;
  v_dispatch_branch uuid;
begin
  if not app.is_salon_owner(p_business)
     or not app.can_module_write(p_business, 'retention') then
    raise exception 'owner retention access required' using errcode = '42501';
  end if;
  select d.branch_id into v_dispatch_branch
  from public.growth_delivery_dispatches_v110 d
  where d.id = p_dispatch and d.business_id = p_business;
  if not found then
    raise exception 'dispatch not found';
  end if;
  if not app.can_see_branch(p_business, v_dispatch_branch) then
    raise exception 'delivery branch is outside actor scope'
      using errcode = '42501';
  end if;
  if length(btrim(coalesce(p_reason, ''))) not between 2 and 500
     or p_idempotency_key is null then
    raise exception 'cancellation reason and idempotency are required'
      using errcode = '22023';
  end if;
  v_identity := app.v112_hash(jsonb_build_object(
    'operation', 'cancel_growth_delivery_v110',
    'business_id', p_business, 'dispatch_id', p_dispatch,
    'actor', v_actor, 'idempotency_key', p_idempotency_key
  ));
  v_hash := app.v112_hash(jsonb_build_object(
    'business_id', p_business, 'dispatch_id', p_dispatch,
    'reason', btrim(p_reason)
  ));
  perform app.v112_lock_dispatch(p_dispatch);
  perform app.v112_lock_pair(
    'v112-v110-cancel-request:' || v_identity,
    'v112-v110-cancel-request:' || v_identity
  );
  v_receipt := app.v112_get_receipt(v_identity, v_hash);
  if v_receipt is not null then return v_receipt; end if;
  v_receipt := public.cancel_growth_delivery_v110_v112_inner(
    p_business, p_dispatch, p_reason, p_idempotency_key
  );
  return app.v112_put_receipt(
    v_identity, 'cancel_growth_delivery_v110', v_hash,
    jsonb_build_object(
      'business_id', p_business, 'dispatch_id', p_dispatch,
      'actor', v_actor
    ),
    v_receipt
  );
end $$;

--
-- Name: cancel_growth_delivery_v110_v112_inner(uuid, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_growth_delivery_v110_v112_inner(p_business uuid, p_dispatch uuid, p_reason text, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  perform app.v112_lock_dispatch(p_dispatch);
  return public.cancel_growth_delivery_v110_v112_unsafe_row_inner(
    p_business, p_dispatch, p_reason, p_idempotency_key
  );
end $$;

--
-- Name: cancel_growth_delivery_v110_v112_unsafe_row_inner(uuid, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_growth_delivery_v110_v112_unsafe_row_inner(p_business uuid, p_dispatch uuid, p_reason text, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_dispatch public.growth_delivery_dispatches_v110%rowtype;
begin
  if not app.is_salon_owner(p_business)
     or not app.can_module_write(p_business, 'retention') then
    raise exception 'owner retention access required' using errcode = '42501';
  end if;
  select * into strict v_dispatch
  from public.growth_delivery_dispatches_v110
  where id = p_dispatch and business_id = p_business for update;
  if not app.can_see_branch(v_dispatch.business_id, v_dispatch.branch_id) then
    raise exception 'delivery branch is outside actor scope' using errcode = '42501';
  end if;
  if length(btrim(coalesce(p_reason, ''))) not between 2 and 500 then
    raise exception 'cancellation reason is required' using errcode = '22023';
  end if;
  v_dispatch := app.v110_transition_delivery(
    p_dispatch, 'cancelled', 'owner_cancelled', null, p_idempotency_key,
    jsonb_build_object('owner_reason', btrim(p_reason))
  );
  return jsonb_build_object(
    'dispatch_id', v_dispatch.id,
    'status', v_dispatch.lifecycle_status
  );
end $$;

--
-- Name: cancel_retention_campaign(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_retention_campaign(p_business uuid, p_campaign uuid, p_reason text DEFAULT NULL::text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_actor uuid := auth.uid(); v_campaign public.retention_campaigns%rowtype;
begin
  if not app.is_salon_owner(p_business) then raise exception 'owner only' using errcode = '42501'; end if;
  select * into v_campaign from public.retention_campaigns
   where id = p_campaign and business_id = p_business for update;
  if not found then raise exception 'campaign not found in this business'; end if;
  if v_campaign.status not in ('draft', 'active') then
    raise exception 'only a draft or active campaign can be cancelled' using errcode = '42501';
  end if;
  update public.retention_campaigns set status = 'cancelled', cancelled_at = now()
   where id = p_campaign and business_id = p_business;
  insert into public.audit_log(business_id, actor, action, entity, entity_id, detail)
  values (p_business, v_actor, 'CANCEL_RETENTION_CAMPAIGN', 'retention_campaigns', p_campaign,
    jsonb_build_object('reason', nullif(btrim(coalesce(p_reason, '')), '')));
  return json_build_object('campaign_id', p_campaign, 'status', 'cancelled');
end $$;

--
-- Name: claim_billing_command_v124(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_billing_command_v124(p_command uuid, p_actor uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_command public.billing_commands%rowtype;
  v_subscription public.subscriptions%rowtype;
  v_terms public.billing_subscription_terms_v124%rowtype;
  v_catalog public.billing_plan_catalog_v124%rowtype;
  v_recovery_required boolean:=false;
  v_current_customer_count integer;
  v_capacity integer;
  v_blocks integer;
begin
  select * into v_command from public.billing_commands
   where id=p_command and requested_by=p_actor for update;
  if not found then
    raise exception 'billing command was not found for this actor'
      using errcode='42501';
  end if;
  if v_command.pricing_model is distinct from 'v124_customer_capacity' then
    return public.claim_billing_command_v77(p_command,p_actor);
  end if;
  if v_command.status in ('completed','failed','canceled') then
    return jsonb_build_object(
      'command_id',v_command.id,'status',v_command.status,
      'command_type',v_command.command_type,
      'provider_object_id',v_command.provider_object_id,
      'redirect_url',v_command.redirect_url,'error_code',v_command.error_code,
      'error_message',v_command.error_message,'pricing_model',v_command.pricing_model
    );
  end if;
  v_recovery_required:=v_command.status in ('processing','uncertain');
  update public.billing_commands set status='processing'
   where id=v_command.id and status in ('pending','uncertain')
   returning * into v_command;
  if not found then
    select * into strict v_command from public.billing_commands where id=p_command;
  end if;
  select * into strict v_subscription from public.subscriptions
   where business_id=v_command.business_id;
  select * into v_terms from public.billing_subscription_terms_v124
   where business_id=v_command.business_id;
  select count(*)::integer into v_current_customer_count
    from public.clients client where client.business_id=v_command.business_id;

  if v_command.requested_cadence is not null then
    select * into v_catalog from public.billing_plan_catalog_v124 catalog
     where catalog.id=v_command.billing_catalog_id_v124
       and catalog.currency='SGD'
       and catalog.cadence=v_command.requested_cadence;
    if not found then
      raise exception 'snapshotted V124 Stripe price catalog entry was not found'
        using errcode='22023';
    end if;
  end if;
  v_capacity:=coalesce(v_command.requested_customer_capacity,v_terms.customer_capacity);
  if v_capacity is not null and (
       v_capacity<greatest(1000,ceil(v_current_customer_count::numeric/1000)::integer*1000)
       or v_capacity%1000<>0
     ) then
    raise exception 'selected capacity is below the current customer count'
      using errcode='22023';
  end if;
  if v_command.command_type in ('change_cadence','change_capacity')
     and v_terms.business_id is not null and (
       v_capacity<v_terms.customer_capacity
       or (v_command.command_type='change_capacity'
           and v_capacity=v_terms.customer_capacity
           and not v_recovery_required)
     ) then
    raise exception 'subscription changes cannot decrease or replay customer capacity'
      using errcode='22023';
  end if;
  v_blocks:=case when v_capacity is null then null else v_capacity/1000 end;

  return jsonb_build_object(
    'command_id',v_command.id,'status',v_command.status,
    'command_type',v_command.command_type,'business_id',v_command.business_id,
    'pricing_model','v124_customer_capacity',
    'requested_cadence',v_command.requested_cadence,
    'requested_customer_capacity',v_capacity,
    'current_customer_count',v_current_customer_count,
    'capacity_blocks',v_blocks,'extra_capacity_blocks',greatest(v_blocks-1,0),
    'provider_idempotency_key','nestly:v124:billing-command:'||v_command.id::text,
    'recovery_required',v_recovery_required,
    'prior_provider_object_id',v_command.provider_object_id,
    'prior_redirect_url',v_command.redirect_url,
    'prior_error_code',v_command.error_code,
    'currency',v_subscription.currency,
    'provider_customer_id',v_subscription.provider_customer_id,
    'provider_subscription_id',v_subscription.provider_subscription_id,
    'provider_base_item_id',v_subscription.provider_base_item_id,
    'provider_capacity_item_id',v_terms.provider_capacity_item_id,
    'provider_base_price_id',v_catalog.provider_base_price_id,
    'provider_capacity_price_id',v_catalog.provider_capacity_price_id,
    'base_amount_cents',v_catalog.base_amount_cents,
    'capacity_block_amount_cents',v_catalog.capacity_block_amount_cents,
    'tax_behavior',v_catalog.tax_behavior
  );
end
$$;

--
-- Name: claim_billing_command_v130(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_billing_command_v130(p_command uuid, p_actor uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_claim jsonb;
  v_self_service boolean;
begin
  v_claim:=public.claim_billing_command_v124(p_command,p_actor);
  select exists(
    select 1 from public.billing_commands command
    join public.self_serve_business_onboarding_v130 onboarding
      on onboarding.business_id=command.business_id
     and onboarding.checkout_command_id=command.id
   where command.id=p_command and command.requested_by=p_actor
  ) into v_self_service;
  return v_claim||jsonb_build_object(
    'self_service_onboarding',v_self_service
  );
end
$$;

--
-- Name: claim_billing_command_v77(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_billing_command_v77(p_command uuid, p_actor uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_command public.billing_commands%rowtype;
  v_subscription public.subscriptions%rowtype;
  v_catalog public.billing_price_catalog%rowtype;
  v_seats integer;
  v_recovery_required boolean:=false;
begin
  if p_command is null or p_actor is null then
    raise exception 'command and actor are required' using errcode='22023';
  end if;
  select * into v_command
    from public.billing_commands
   where id=p_command and requested_by=p_actor
   for update;
  if not found then
    raise exception 'billing command was not found for this actor'
      using errcode='42501';
  end if;
  if v_command.status in ('completed','failed','canceled') then
    return jsonb_build_object(
      'command_id',v_command.id,'status',v_command.status,
      'command_type',v_command.command_type,
      'provider_object_id',v_command.provider_object_id,
      'redirect_url',v_command.redirect_url,
      'error_code',v_command.error_code,
      'error_message',v_command.error_message
    );
  end if;
  v_recovery_required:=v_command.status in ('processing','uncertain');
  update public.billing_commands
     set status='processing'
   where id=v_command.id and status in ('pending','uncertain')
   returning * into v_command;
  if not found then
    select * into strict v_command
      from public.billing_commands where id=p_command;
  end if;

  select * into strict v_subscription
    from public.subscriptions where business_id=v_command.business_id;
  v_seats := app.billable_seats(v_command.business_id);
  if v_command.requested_cadence is not null then
    select * into v_catalog
      from public.billing_price_catalog
     where currency=v_subscription.currency
       and cadence=v_command.requested_cadence
       and active and effective_from <= now()
       and (effective_to is null or effective_to > now())
     order by effective_from desc limit 1;
    if not found then
      raise exception 'active Stripe price catalog entry was not found'
        using errcode='22023';
    end if;
  end if;
  return jsonb_build_object(
    'command_id',v_command.id,'status',v_command.status,
    'command_type',v_command.command_type,
    'business_id',v_command.business_id,
    'requested_cadence',v_command.requested_cadence,
    'provider_idempotency_key','nestly:v77:billing-command:'||v_command.id::text,
    'recovery_required',v_recovery_required,
    'prior_provider_object_id',v_command.provider_object_id,
    'prior_redirect_url',v_command.redirect_url,
    'prior_error_code',v_command.error_code,
    'currency',v_subscription.currency,
    'provider_customer_id',v_subscription.provider_customer_id,
    'provider_subscription_id',v_subscription.provider_subscription_id,
    'provider_base_item_id',coalesce(
      v_subscription.provider_base_item_id,
      (
        select item.provider_item_id
          from public.billing_provider_subscription_items item
         where item.provider_subscription_id=v_subscription.provider_subscription_id
           and item.item_role='base'
         order by item.updated_at desc limit 1
      )
    ),
    'provider_seat_item_id',coalesce(
      v_subscription.provider_seat_item_id,
      (
        select item.provider_item_id
          from public.billing_provider_subscription_items item
         where item.provider_subscription_id=v_subscription.provider_subscription_id
           and item.item_role='seat'
         order by item.updated_at desc limit 1
      )
    ),
    'billable_seats',v_seats,
    'included_seats',coalesce(v_catalog.included_seats,v_subscription.included_seats),
    'extra_seats',greatest(
      v_seats-coalesce(v_catalog.included_seats,v_subscription.included_seats),0
    ),
    'provider_base_price_id',v_catalog.provider_base_price_id,
    'provider_seat_price_id',v_catalog.provider_seat_price_id
  );
end
$$;

--
-- Name: FUNCTION claim_billing_command_v77(p_command uuid, p_actor uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.claim_billing_command_v77(p_command uuid, p_actor uuid) IS 'Service-only command claim for the authenticated Edge executor. Returns a finite provider instruction and a stable Stripe idempotency key.';

--
-- Name: classify_legacy_business(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.classify_legacy_business(p_business uuid, p_classification text, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_reason text := btrim(coalesce(p_reason, ''));
  v_id uuid := gen_random_uuid();
begin
  if not app.is_super_admin() then
    raise exception 'super-admin only: legacy classification is a platform decision' using errcode = '42501';
  end if;
  if p_classification is null or p_classification not in ('pilot', 'qa_reset', 'retain_fixture') then
    raise exception 'classification must be one of pilot / qa_reset / retain_fixture' using errcode = '22023';
  end if;
  if char_length(v_reason) < 10 then
    raise exception 'a legacy classification requires a reason of at least 10 characters' using errcode = '22023';
  end if;
  if not exists (select 1 from public.businesses b where b.id = p_business) then
    raise exception 'business not found' using errcode = '22023';
  end if;
  insert into public.sv_legacy_classifications(id, business_id, classification, reason, actor)
  values (v_id, p_business, p_classification, v_reason, v_actor);
  insert into public.audit_log(business_id, actor, action, entity, entity_id, detail)
  values (p_business, v_actor, 'SV_LEGACY_BUSINESS_CLASSIFIED', 'sv_legacy_classifications', v_id,
    jsonb_build_object('classification', p_classification, 'reason', v_reason));
  return jsonb_build_object('status', 'ok', 'business_id', p_business,
    'classification', p_classification, 'classification_id', v_id);
end $$;

--
-- Name: clone_sv_plan_version_to_draft(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.clone_sv_plan_version_to_draft(p_business uuid, p_version uuid, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid(); pv public.sv_plan_versions%rowtype; v_id uuid := gen_random_uuid();
  v_hash text; v_hit jsonb; v_row public.sv_plan_drafts%rowtype;
begin
  if not app.is_salon_owner(p_business) then raise exception 'owner only' using errcode = '42501'; end if;
  v_hash := app.ps1b_sha256(jsonb_build_object('op','clone','business',p_business,'version',p_version)::text);
  v_hit := app.sv_plan_idem_lookup(p_business, 'clone', p_idempotency_key, v_hash);
  if v_hit is not null then return v_hit; end if;

  select * into pv from public.sv_plan_versions where id = p_version and business_id = p_business;
  if not found then raise exception 'stored-value plan version not found in this business' using errcode = '22023'; end if;

  insert into public.sv_plan_drafts(
    id, business_id, plan_id, actor, customer_facing_name, price_cents, bonus_cents, paid_expiry_days,
    bonus_expiry_days, eligible_branch_ids, eligible_service_ids, eligible_product_ids, eligible_service_categories,
    min_spend_cents, stacking_policy, max_balance_cents, purchase_window_days, purchase_max_in_window,
    purchase_lifetime_cap, refund_policy, spend_order, topup_purchase_earns_points, stored_value_spend_earns_points,
    customer_terms, accounting_inputs, effective_at)
  values (
    v_id, p_business, pv.plan_id, v_actor, pv.customer_facing_name, pv.price_cents, pv.bonus_cents, pv.paid_expiry_days,
    pv.bonus_expiry_days, pv.eligible_branch_ids, pv.eligible_service_ids, pv.eligible_product_ids, pv.eligible_service_categories,
    pv.min_spend_cents, coalesce(pv.stacking_policy,'stackable'), pv.max_balance_cents, pv.purchase_window_days, pv.purchase_max_in_window,
    pv.purchase_lifetime_cap, coalesce(pv.refund_policy,'proportional'), coalesce(pv.spend_order,'proportional'),
    coalesce(pv.topup_purchase_earns_points,false), coalesce(pv.stored_value_spend_earns_points,false),
    pv.customer_terms, coalesce(pv.accounting_inputs,'{}'::jsonb), pv.effective_at);
  select * into v_row from public.sv_plan_drafts where id = v_id and business_id = p_business;

  insert into public.sv_plan_operations(business_id, op_type, idempotency_key, request_hash, actor, result)
  values (p_business, 'clone', p_idempotency_key, v_hash, v_actor, app.sv_plan_draft_json(v_row));
  insert into public.audit_log(business_id, actor, action, entity, entity_id, detail)
  values (p_business, v_actor, 'SV_PLAN_CLONED_TO_DRAFT', 'sv_plan_drafts', v_id, jsonb_build_object('from_version', p_version, 'plan_id', pv.plan_id));
  return app.sv_plan_draft_json(v_row);
end $$;

--
-- Name: close_drawer(uuid, uuid, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.close_drawer(p_business uuid, p_session uuid, p_counted_cents integer, p_note text DEFAULT NULL::text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_s cash_drawer_sessions; v_expected integer; v_variance integer;
begin
  if not app.has_perm(p_business, 'view_finance') then
    raise exception 'you do not have permission to close the cash drawer (view_finance)';
  end if;
  select * into v_s from cash_drawer_sessions
    where id = p_session and business_id = p_business for update;
  if not found then raise exception 'drawer session not found'; end if;
  if v_s.closed_at is not null then raise exception 'drawer session already closed'; end if;
  if p_counted_cents is null or p_counted_cents < 0 then
    raise exception 'counted amount must be zero or positive';
  end if;
  select coalesce(sum(amount_cents), 0) into v_expected
    from cash_drawer_movements where branch_id = v_s.branch_id;
  v_variance := p_counted_cents - v_expected;
  update cash_drawer_sessions
     set closed_at = now(), closed_by = auth.uid(),
         expected_cents = v_expected, counted_cents = p_counted_cents,
         note = coalesce(p_note, note)
   where id = p_session;
  if v_variance <> 0 then
    insert into cash_drawer_movements (business_id, branch_id, session_id, kind,
                                       amount_cents, note)
    values (p_business, v_s.branch_id, p_session, 'close_variance', v_variance,
            'close: counted ' || p_counted_cents || ' vs expected ' || v_expected);
  end if;
  return json_build_object('session_id', p_session, 'expected_cents', v_expected,
                          'counted_cents', p_counted_cents, 'variance_cents', v_variance);
end $$;

--
-- Name: commit_import_job(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commit_import_job(p_job uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_job public.import_jobs%rowtype;
  v_row public.import_rows%rowtype;
  v_id uuid;
  v_imported integer := 0;
  v_result json;
begin
  select * into v_job from public.import_jobs where id = p_job for update;
  if not found then raise exception 'import job not found'; end if;
  if not app.is_salon_owner(v_job.business_id) then
    raise exception 'only the business owner can commit imports' using errcode = '42501';
  end if;
  -- Serialize commits for one business/entity and recheck natural keys below. Staging previews
  -- remain concurrent, but two approved imports cannot both pass a stale duplicate check.
  perform pg_advisory_xact_lock(hashtextextended(
    'v24c:import:'||v_job.business_id::text||':'||v_job.entity_type,0
  ));
  if v_job.status = 'completed' then return v_job.result::json; end if;
  if v_job.invalid_rows > 0 then
    raise exception 'fix all invalid rows before importing' using errcode = 'check_violation';
  end if;

  for v_row in
    select * from public.import_rows
     where job_id = p_job and business_id = v_job.business_id
     order by row_number for update
  loop
    if v_job.entity_type='customers' and nullif(v_row.normalized_data->>'phone','') is not null
       and exists(select 1 from public.clients c where c.business_id=v_job.business_id
         and c.phone_norm=app.norm_phone(v_row.normalized_data->>'phone')) then
      raise exception 'customer now exists; restage the import for a fresh preview';
    elsif v_job.entity_type='services' and exists(
      select 1 from public.services s where s.business_id=v_job.business_id
       and lower(btrim(s.name))=lower(v_row.normalized_data->>'name')
       and s.price_cents=(v_row.normalized_data->>'price_cents')::integer
       and s.duration_min=(v_row.normalized_data->>'duration_min')::integer
    ) then raise exception 'service now exists; restage the import for a fresh preview';
    elsif v_job.entity_type='inventory' and nullif(v_row.normalized_data->>'sku','') is not null
       and exists(select 1 from public.products p where p.business_id=v_job.business_id
         and p.sku=v_row.normalized_data->>'sku') then
      raise exception 'product SKU now exists; restage the import for a fresh preview';
    elsif v_job.entity_type='staff' and exists(
      select 1 from public.staff s where s.business_id=v_job.business_id and (
        (v_row.normalized_data ? 'email' and lower(btrim(s.email))=lower(v_row.normalized_data->>'email'))
        or (v_row.normalized_data ? 'phone' and regexp_replace(coalesce(s.phone,''),'\D','','g')=
            regexp_replace(v_row.normalized_data->>'phone','\D','','g')))
    ) then raise exception 'staff now exists; restage the import for a fresh preview';
    elsif v_job.entity_type='branches' and exists(
      select 1 from public.branches b where b.business_id=v_job.business_id
       and lower(btrim(b.name))=lower(v_row.normalized_data->>'name')
       and lower(btrim(coalesce(b.address,'')))=lower(btrim(coalesce(v_row.normalized_data->>'address','')))
    ) then raise exception 'branch now exists; restage the import for a fresh preview';
    elsif v_job.entity_type='reservations' and exists(
      select 1 from public.booking_tables t where t.business_id=v_job.business_id
       and lower(btrim(t.name))=lower(v_row.normalized_data->>'name')
       and t.pax is not distinct from nullif(v_row.normalized_data->>'pax','')::integer
    ) then raise exception 'reservation table now exists; restage the import for a fresh preview';
    end if;
    if v_job.entity_type = 'customers' then
      insert into public.clients
        (business_id, full_name, phone, email, gender, birth_date, notes)
      values
        (v_job.business_id, v_row.normalized_data->>'full_name',
         v_row.normalized_data->>'phone', v_row.normalized_data->>'email',
         v_row.normalized_data->>'gender',
         (v_row.normalized_data->>'birth_date')::date,
         v_row.normalized_data->>'notes')
      returning id into v_id;
    elsif v_job.entity_type = 'services' then
      insert into public.services
        (business_id, name, price_cents, duration_min, category, description, active)
      values
        (v_job.business_id, v_row.normalized_data->>'name',
         (v_row.normalized_data->>'price_cents')::integer,
         (v_row.normalized_data->>'duration_min')::integer,
         v_row.normalized_data->>'category', v_row.normalized_data->>'description', true)
      returning id into v_id;
    elsif v_job.entity_type = 'inventory' then
      insert into public.products
        (business_id, name, sku, retail_price_cents, active)
      values
        (v_job.business_id, v_row.normalized_data->>'name',
         v_row.normalized_data->>'sku',
         (v_row.normalized_data->>'retail_price_cents')::integer, true)
      returning id into v_id;
      if coalesce((v_row.normalized_data->>'opening_qty')::integer, 0) > 0 then
        insert into public.stock_batches (product_id, qty)
        values (v_id, (v_row.normalized_data->>'opening_qty')::integer);
      end if;
    elsif v_job.entity_type = 'staff' then
      insert into public.staff
        (business_id, full_name, email, phone, title, role, calendar_color, active)
      values
        (v_job.business_id, v_row.normalized_data->>'full_name',
         v_row.normalized_data->>'email', v_row.normalized_data->>'phone',
         v_row.normalized_data->>'title', v_row.normalized_data->>'role',
         v_row.normalized_data->>'calendar_color', true)
      returning id into v_id;
    elsif v_job.entity_type = 'branches' then
      insert into public.branches
        (business_id, name, address, phone, email, timezone, active, is_default)
      values
        (v_job.business_id, v_row.normalized_data->>'name',
         v_row.normalized_data->>'address', v_row.normalized_data->>'phone',
         v_row.normalized_data->>'email', v_row.normalized_data->>'timezone', true, false)
      returning id into v_id;
    else
      insert into public.booking_tables
        (business_id, name, pax, quantity, sort, active)
      values
        (v_job.business_id, v_row.normalized_data->>'name',
         (v_row.normalized_data->>'pax')::integer,
         (v_row.normalized_data->>'quantity')::integer,
         (v_row.normalized_data->>'sort')::integer, true)
      returning id into v_id;
    end if;
    update public.import_rows set committed_id = v_id where id = v_row.id;
    v_imported := v_imported + 1;
  end loop;

  v_result := json_build_object(
    'job_id', p_job, 'entity', v_job.entity_type, 'imported', v_imported
  );
  update public.import_jobs
     set status = 'completed', result = v_result::jsonb, completed_at = now()
   where id = p_job;
  return v_result;
end $$;

--
-- Name: complete_billing_command_v77(uuid, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_billing_command_v77(p_command uuid, p_status text, p_provider_object_id text, p_redirect_url text, p_error_code text, p_error_message text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_command public.billing_commands%rowtype;
begin
  if p_status not in ('processing','uncertain','completed','failed','canceled') then
    raise exception 'invalid command status' using errcode='22023';
  end if;
  select * into v_command from public.billing_commands where id=p_command for update;
  if not found then raise exception 'billing command not found' using errcode='22023'; end if;
  if v_command.status in ('completed','failed','canceled') then
    if v_command.status <> p_status
       or v_command.provider_object_id is distinct from p_provider_object_id
       or v_command.redirect_url is distinct from p_redirect_url
       or v_command.error_code is distinct from p_error_code then
      raise exception 'terminal billing command cannot be rewritten'
        using errcode='restrict_violation';
    end if;
    return to_jsonb(v_command);
  end if;
  update public.billing_commands
     set status=p_status,provider_object_id=p_provider_object_id,
         redirect_url=p_redirect_url,error_code=p_error_code,
         error_message=left(p_error_message,2000),
         completed_at=case when p_status in ('completed','failed','canceled')
                           then now() else null end
   where id=p_command returning * into v_command;
  return to_jsonb(v_command);
end
$$;

--
-- Name: complete_business_google_oauth_v138(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_business_google_oauth_v138(p_intent text, p_attempt_token text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $_$
declare
  v_actor uuid:=auth.uid();
  v_token_hash text;
  v_attempt app.business_google_oauth_attempts_v138%rowtype;
begin
  if v_actor is null or p_intent not in ('signin','signup') then
    raise exception 'authenticated Google OAuth admission required' using errcode='28000';
  end if;
  if not exists(select 1 from auth.identities identity_row
      where identity_row.user_id=v_actor and identity_row.provider='google') then
    raise exception 'Google identity required' using errcode='42501';
  end if;
  if p_intent='signin' then
    if not exists(select 1 from public.staff staff_row
        where staff_row.user_id=v_actor and staff_row.active) then
      raise exception 'existing active business account required; use signup first'
        using errcode='42501';
    end if;
    return jsonb_build_object('admitted',true,'intent','signin',
      'legal_recorded',false,'replayed',false);
  end if;
  if lower(btrim(coalesce(p_attempt_token,'')))
       !~'^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then
    raise exception 'server-recorded Google signup consent required' using errcode='42501';
  end if;
  v_token_hash:=app.v31_sha256_hex(lower(btrim(p_attempt_token)));
  select * into v_attempt from app.business_google_oauth_attempts_v138
   where token_sha256=v_token_hash for update;
  if not found then
    raise exception 'server-recorded Google signup consent required' using errcode='42501';
  end if;
  if v_attempt.consumed_by is not null then
    if v_attempt.consumed_by<>v_actor or not exists(
      select 1 from app.business_account_legal_acceptances_v138 acceptance
       where acceptance.source='google_oauth_signup'
         and acceptance.auth_user_id=v_actor
         and acceptance.idempotency_key=v_attempt.idempotency_key
         and acceptance.request_sha256=v_attempt.request_sha256
    ) then
      raise exception 'Google signup consent attempt was already consumed'
        using errcode='42501';
    end if;
    return jsonb_build_object('admitted',true,'intent','signup',
      'legal_recorded',true,'replayed',true);
  end if;
  if v_attempt.expires_at<=now() then
    raise exception 'Google signup consent attempt expired' using errcode='42501';
  end if;
  if not exists(select 1 from app.customer_legal_documents document
      where document.document_key='terms' and document.active
        and document.document_version=v_attempt.terms_version
        and document.document_sha256=v_attempt.terms_sha256)
     or not exists(select 1 from app.customer_legal_documents document
      where document.document_key='privacy' and document.active
        and document.document_version=v_attempt.privacy_version
        and document.document_sha256=v_attempt.privacy_sha256) then
    raise exception 'accepted legal documents are no longer current' using errcode='42501';
  end if;
  update app.business_google_oauth_attempts_v138
     set consumed_by=v_actor,consumed_at=now()
   where token_sha256=v_token_hash and consumed_by is null;
  if not found then
    raise exception 'Google signup consent attempt could not be consumed'
      using errcode='40001';
  end if;
  insert into app.business_account_legal_acceptances_v138(
    auth_user_id,source,terms_version,terms_sha256,
    privacy_version,privacy_sha256,accepted_at,idempotency_key,request_sha256
  ) values(
    v_actor,'google_oauth_signup',v_attempt.terms_version,v_attempt.terms_sha256,
    v_attempt.privacy_version,v_attempt.privacy_sha256,v_attempt.accepted_at,
    v_attempt.idempotency_key,v_attempt.request_sha256
  );
  return jsonb_build_object('admitted',true,'intent','signup',
    'legal_recorded',true,'replayed',false);
end
$_$;

--
-- Name: FUNCTION complete_business_google_oauth_v138(p_intent text, p_attempt_token text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.complete_business_google_oauth_v138(p_intent text, p_attempt_token text) IS 'Authenticated Google-only V138 admission: existing active staff may sign in without consent; signup consumes one server-recorded legal acceptance.';

--
-- Name: complete_merchant_connect_command_v142(uuid, text, boolean, boolean, boolean, boolean, text, jsonb, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_merchant_connect_command_v142(p_command uuid, p_account_id text, p_livemode boolean, p_details_submitted boolean, p_charges_enabled boolean, p_payouts_enabled boolean, p_paynow_capability text, p_currently_due jsonb, p_eventually_due jsonb, p_disabled_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_command public.merchant_payment_commands_v142%rowtype;
        v_existing public.merchant_payment_accounts_v142%rowtype;
begin
  perform app.v142_service_guard();
  select * into v_command from public.merchant_payment_commands_v142 where id=p_command for update;
  if not found then raise exception 'merchant payment command not found' using errcode='22023'; end if;
  if v_command.livemode is distinct from p_livemode then
    raise exception 'merchant account mode does not match setup command' using errcode='22023';
  end if;
  select * into v_existing from public.merchant_payment_accounts_v142
   where business_id=v_command.business_id;
  if found and (v_existing.provider_account_id is distinct from p_account_id
                or v_existing.livemode is distinct from p_livemode)
     and not (v_existing.livemode=false and p_livemode=true) then
    raise exception 'business payment account is already bound in this mode' using errcode='23505';
  end if;
  insert into public.merchant_payment_accounts_v142(
    business_id,provider_account_id,livemode,details_submitted,charges_enabled,payouts_enabled,
    paynow_capability,requirements_currently_due,requirements_eventually_due,disabled_reason,created_by)
  values(v_command.business_id,p_account_id,p_livemode,coalesce(p_details_submitted,false),
    coalesce(p_charges_enabled,false),coalesce(p_payouts_enabled,false),p_paynow_capability,
    coalesce(p_currently_due,'[]'::jsonb),coalesce(p_eventually_due,'[]'::jsonb),
    nullif(left(coalesce(p_disabled_reason,''),300),''),v_command.actor)
  on conflict (business_id) do update set
    provider_account_id=excluded.provider_account_id,livemode=excluded.livemode,
    details_submitted=excluded.details_submitted,
    charges_enabled=excluded.charges_enabled,payouts_enabled=excluded.payouts_enabled,
    paynow_capability=excluded.paynow_capability,
    requirements_currently_due=excluded.requirements_currently_due,
    requirements_eventually_due=excluded.requirements_eventually_due,
    disabled_reason=excluded.disabled_reason,updated_at=now();
  update public.merchant_payment_commands_v142 set status='completed',provider_account_id=p_account_id,
    completed_at=now(),updated_at=now(),failure_code=null where id=p_command;
  return jsonb_build_object('business_id',v_command.business_id,'status','completed');
end $$;

--
-- Name: complete_retention_campaign(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_retention_campaign(p_business uuid, p_campaign uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_actor uuid := auth.uid(); v_campaign public.retention_campaigns%rowtype;
begin
  if not app.is_salon_owner(p_business) then raise exception 'owner only' using errcode = '42501'; end if;
  select * into v_campaign from public.retention_campaigns
   where id = p_campaign and business_id = p_business for update;
  if not found then raise exception 'campaign not found in this business'; end if;
  if v_campaign.status <> 'active' then
    raise exception 'only an active campaign can be completed' using errcode = '42501';
  end if;
  update public.retention_campaigns set status = 'completed', completed_at = now()
   where id = p_campaign and business_id = p_business;
  insert into public.audit_log(business_id, actor, action, entity, entity_id, detail)
  values (p_business, v_actor, 'COMPLETE_RETENTION_CAMPAIGN', 'retention_campaigns', p_campaign, '{}'::jsonb);
  return json_build_object('campaign_id', p_campaign, 'status', 'completed');
end $$;

--
-- Name: confirm_billing_plan_catalog_v124(text, text, text, text, timestamp with time zone, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.confirm_billing_plan_catalog_v124(p_cadence text, p_provider_base_price_id text, p_provider_capacity_price_id text, p_tax_behavior text, p_effective_from timestamp with time zone, p_confirmation_hash text, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid:=auth.uid();
  v_preview jsonb;
  v_row public.billing_plan_catalog_v124%rowtype;
begin
  if v_actor is null or not app.is_super_admin() then
    raise exception 'super-admin access is required' using errcode='42501';
  end if;
  if length(btrim(coalesce(p_reason,''))) < 8 then
    raise exception 'an audit reason is required' using errcode='22023';
  end if;
  v_preview:=public.preview_billing_plan_catalog_v124(
    p_cadence,p_provider_base_price_id,p_provider_capacity_price_id,
    p_tax_behavior,p_effective_from
  );
  if p_confirmation_hash is distinct from v_preview->>'confirmation_hash' then
    raise exception 'V124 Stripe price confirmation is stale' using errcode='22023';
  end if;
  update public.billing_plan_catalog_v124
     set active=false,effective_to=p_effective_from
   where currency='SGD' and cadence=p_cadence
     and active and effective_to is null;
  insert into public.billing_plan_catalog_v124(
    currency,cadence,cadence_months,provider_base_price_id,
    provider_capacity_price_id,base_amount_cents,
    included_customer_capacity,capacity_block_size,
    capacity_block_amount_cents,compare_at_monthly_cents,
    tax_behavior,effective_from,created_by
  ) values (
    'SGD',p_cadence,case p_cadence when 'monthly' then 1 else 12 end,
    p_provider_base_price_id,p_provider_capacity_price_id,
    case p_cadence when 'monthly' then 14800 else 118800 end,
    1000,1000,case p_cadence when 'monthly' then 1000 else 12000 end,
    16800,p_tax_behavior,p_effective_from,v_actor
  ) returning * into v_row;
  insert into public.audit_log(business_id,actor,action,entity,entity_id,detail)
  values (null,v_actor,'billing.v162_catalog_confirmed','billing_plan_catalog_v124',
    v_row.id,jsonb_build_object('reason',btrim(p_reason),'proposal',v_preview));
  return to_jsonb(v_row);
end
$$;

--
-- Name: confirm_billing_plan_catalog_v125(text, text, text, text, timestamp with time zone, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.confirm_billing_plan_catalog_v125(p_cadence text, p_provider_base_price_id text, p_provider_capacity_price_id text, p_tax_behavior text, p_effective_from timestamp with time zone, p_confirmation_hash text, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if p_tax_behavior is distinct from 'exclusive' then
    raise exception 'NESTLY TECHNOLOGIES PTE. LTD. is not GST-registered; Stripe prices must use exclusive tax behavior'
      using errcode='22023';
  end if;
  return public.confirm_billing_plan_catalog_v124(
    p_cadence,p_provider_base_price_id,p_provider_capacity_price_id,
    'exclusive',p_effective_from,p_confirmation_hash,p_reason
  ) || jsonb_build_object(
    'gst_registered',false,
    'tax_collection_enabled',false,
    'tax_label','GST not charged'
  );
end
$$;

--
-- Name: confirm_billing_price_catalog_v77(text, text, text, text, integer, integer, integer, text, timestamp with time zone, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.confirm_billing_price_catalog_v77(p_currency text, p_cadence text, p_provider_base_price_id text, p_provider_seat_price_id text, p_base_amount_cents integer, p_per_seat_amount_cents integer, p_included_seats integer, p_tax_behavior text, p_effective_from timestamp with time zone, p_confirmation_hash text, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_preview jsonb;
  v_expected text;
  v_months smallint;
  v_prior public.billing_price_catalog%rowtype;
  v_new public.billing_price_catalog%rowtype;
begin
  if v_actor is null or not app.is_super_admin() then
    raise exception 'super-admin access is required' using errcode='42501';
  end if;
  v_preview := public.preview_billing_price_catalog_v77(
    p_currency,p_cadence,p_provider_base_price_id,p_provider_seat_price_id,
    p_base_amount_cents,p_per_seat_amount_cents,p_included_seats,
    p_tax_behavior,p_effective_from
  );
  v_expected := v_preview->>'confirmation_hash';
  if p_confirmation_hash is null or p_confirmation_hash <> v_expected then
    raise exception 'price catalog confirmation hash does not match preview'
      using errcode='22023';
  end if;
  if nullif(btrim(p_reason),'') is null or length(p_reason)>1000 then
    raise exception 'a bounded activation reason is required' using errcode='22023';
  end if;
  if p_effective_from < now()-interval '1 day'
     or p_effective_from > now()+interval '5 minutes' then
    raise exception 'effective_from must activate now, not schedule a hidden gap'
      using errcode='22023';
  end if;
  v_months := case p_cadence
    when 'quarterly' then 3 when 'half_yearly' then 6 when 'annual' then 12
  end;
  perform pg_advisory_xact_lock(hashtextextended(
    'v77:billing-price:'||p_currency||':'||p_cadence,0
  ));
  select * into v_prior
    from public.billing_price_catalog
   where currency=p_currency and cadence=p_cadence
     and active and effective_to is null
   for update;
  if found and v_prior.effective_from >= p_effective_from then
    raise exception 'new price version must begin after the active version'
      using errcode='22023';
  end if;
  if found then
    update public.billing_price_catalog
       set active=false,effective_to=p_effective_from
     where id=v_prior.id;
  end if;
  insert into public.billing_price_catalog(
    currency,cadence,cadence_months,provider_base_price_id,
    provider_seat_price_id,base_amount_cents,per_seat_amount_cents,
    included_seats,tax_behavior,effective_from,created_by
  ) values (
    p_currency,p_cadence,v_months,p_provider_base_price_id,
    p_provider_seat_price_id,p_base_amount_cents,p_per_seat_amount_cents,
    p_included_seats,p_tax_behavior,p_effective_from,v_actor
  ) returning * into v_new;
  insert into public.audit_log(
    business_id,actor,action,entity,entity_id,detail
  ) values (
    null,v_actor,'BILLING_PRICE_CATALOG_ACTIVATED_V77',
    'billing_price_catalog',v_new.id,
    jsonb_build_object(
      'prior_id',v_prior.id,'currency',p_currency,'cadence',p_cadence,
      'cadence_months',v_months,'base_amount_cents',p_base_amount_cents,
      'per_seat_amount_cents',p_per_seat_amount_cents,
      'included_seats',p_included_seats,'tax_behavior',p_tax_behavior,
      'confirmation_hash',p_confirmation_hash,'reason',btrim(p_reason)
    )
  );
  return to_jsonb(v_new);
end
$$;

--
-- Name: convert_booking_request(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.convert_booking_request(p_request uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_business uuid;
  v_result jsonb;
  v_legacy json;
begin
  select request.business_id into v_business
    from public.booking_requests request
   where request.id = p_request;
  if not found then
    raise exception 'booking request not found' using errcode = '22023';
  end if;

  v_result := public.staff_decide_booking_request_v73(
    v_business, p_request, 'confirm', null
  );
  if v_result->>'outcome' in ('applied', 'replayed') then
    select row_to_json(appointment) into v_legacy
      from public.appointments appointment
     where appointment.id = (v_result->>'appointment_id')::uuid
       and appointment.business_id = v_business;
    return v_legacy;
  end if;
  return jsonb_build_object(
    'status', 'conflict',
    'reason', v_result->>'outcome',
    'request_id', p_request
  )::json;
end
$$;

--
-- Name: convert_sme_prospect_v79(uuid, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.convert_sme_prospect_v79(p_prospect uuid, p_expected_version bigint, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid:=auth.uid();v_hash text;v_replay jsonb;v_prospect public.sme_prospects%rowtype;
  v_company public.sme_companies%rowtype;v_terms public.sme_commercial_terms%rowtype;
  v_bundle public.sector_bundle_versions%rowtype;v_business public.businesses%rowtype;
  v_duplicate public.businesses%rowtype;v_branch uuid;v_checklist uuid;v_invite jsonb;
  v_response jsonb;v_sector text;v_slug text;v_months integer;
begin
  if not app.is_platform_operator_v75() then raise exception 'platform operator access is required' using errcode='42501';end if;
  perform app.require_idempotency_key_v79(p_idempotency_key);
  v_hash:=app.v76_sha256_hex(jsonb_build_object('prospect',p_prospect,'version',p_expected_version)::text);
  v_replay:=app.v76_replay(v_actor,'convert_prospect_v79',p_idempotency_key,v_hash);
  if v_replay is not null then return v_replay;end if;
  select * into v_prospect from public.sme_prospects where id=p_prospect for update;
  if not found then raise exception 'prospect was not found' using errcode='22023';end if;
  if v_prospect.converted_business_id is not null then
    return jsonb_build_object('replayed',false,'outcome','already_converted',
      'prospect_id',p_prospect,'business_id',v_prospect.converted_business_id,
      'prospect_version',v_prospect.version);
  end if;
  if v_prospect.version<>p_expected_version then raise exception 'prospect version conflict' using errcode='40001';end if;
  if v_prospect.current_stage_key<>'client' then raise exception 'only a Client / Deal Won prospect can convert' using errcode='22023';end if;
  select * into v_company from public.sme_companies where id=v_prospect.company_id;
  select * into v_terms from public.sme_commercial_terms
   where prospect_id=p_prospect and contract_status in ('accepted','signed')
   order by version desc limit 1;
  if not found then raise exception 'latest accepted or signed commercial terms are required' using errcode='22023';end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    coalesce(app.normalized_business_identity_v79(v_company.registration_number),'registration:none'),79));
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    coalesce(app.normalized_business_identity_v79(coalesce(v_company.legal_name,v_company.trading_name)),'name:none'),79));
  select * into v_duplicate from public.businesses business
   where (v_company.registration_number is not null
      and app.normalized_business_identity_v79(business.registration_number)
        =app.normalized_business_identity_v79(v_company.registration_number))
      or app.normalized_business_identity_v79(coalesce(business.legal_name,business.name))
         =app.normalized_business_identity_v79(coalesce(v_company.legal_name,v_company.trading_name))
   order by business.created_at limit 1;
  if found then
    v_response:=jsonb_build_object('replayed',false,'outcome','duplicate_workspace',
      'prospect_id',p_prospect,'matched_business_id',v_duplicate.id,
      'match_basis',case when v_company.registration_number is not null
        and lower(btrim(v_duplicate.registration_number))=lower(btrim(v_company.registration_number))
        then 'registration_number' else 'normalized_name' end);
    perform app.v76_store_receipt(v_actor,'convert_prospect_v79',p_idempotency_key,v_hash,v_response);
    return v_response;
  end if;
  v_sector:=case when exists(select 1 from public.sector_profiles where sector_key=v_company.sector_key and active)
    then v_company.sector_key when exists(select 1 from public.sector_profiles where sector_key=v_company.industry and active)
    then v_company.industry else 'other' end;
  select * into v_bundle from public.sector_bundle_versions where sector_key=v_sector and status='published';
  if not found then raise exception 'current published sector bundle is required' using errcode='22023';end if;
  v_slug:=trim(both '-' from regexp_replace(lower(coalesce(v_company.trading_name,v_company.legal_name,'business')),'[^a-z0-9]+','-','g'))
    ||'-'||left(replace(p_prospect::text,'-',''),8);
  insert into public.businesses(
    name,slug,industry,enabled_modules,legal_name,registration_number,source_prospect_id
  ) values(coalesce(v_company.trading_name,v_company.legal_name),v_slug,v_sector,v_bundle.modules,
    coalesce(v_company.legal_name,v_company.trading_name),v_company.registration_number,p_prospect)
  returning * into v_business;
  insert into public.branches(business_id,name,is_default,active)
  values(v_business.id,coalesce(v_company.trading_name,v_company.legal_name),true,false)
  returning id into v_branch;
  insert into public.loyalty_programs(
    business_id,kind,earn_points_per_dollar,redeem_points,reward_credit_cents,
    active,loyalty_model,configuration_status,recommendation_source
  ) values(v_business.id,'points',1,800,2000,false,'classic','draft','prospect_conversion_v79');
  v_months:=case v_terms.billing_cycle when 'quarterly' then 3 when 'half_yearly' then 6 else 12 end;
  insert into public.subscriptions(
    business_id,status,currency,billing_provider,billing_cadence,cadence_months,
    plan_code,product_code,commercial_terms_id,seat_limit
  ) values(v_business.id,'trialing',v_terms.currency,'manual',v_terms.billing_cycle,v_months,
    v_terms.plan_code,v_terms.product_code,v_terms.id,v_terms.seats);
  insert into public.business_sector_assignments(
    business_id,bundle_version_id,version,assigned_by
  ) values(v_business.id,v_bundle.id,1,v_actor);
  v_invite:=app.issue_workspace_owner_invite_core_v79(
    v_business.id,p_prospect,v_terms.owner_email,v_actor);
  v_checklist:=app.create_onboarding_checklist_core_v79(v_business.id,p_prospect,v_actor);
  update public.sme_prospects set converted_business_id=v_business.id,converted_at=now(),
    converted_by=v_actor,current_stage_key='account_created',stage_entered_at=now(),
    version=version+1,updated_by=v_actor,updated_at=now() where id=p_prospect
    returning * into v_prospect;
  insert into public.sme_prospect_stage_history(prospect_id,from_stage_key,to_stage_key,reason_code,reason_detail,actor)
  values(p_prospect,'client','account_created','conversion_completed','Workspace and owner invitation created',v_actor);
  insert into public.sme_prospect_activities(prospect_id,consultant_id,activity_type,summary,detail,created_by)
  values(p_prospect,v_prospect.assigned_consultant_id,'system','Account created',
    'v79 transactional workspace conversion completed',v_actor);
  perform app.refresh_onboarding_core_v79(v_business.id,v_actor);
  insert into public.audit_log(business_id,actor,action,entity,entity_id,detail)
  values(v_business.id,v_actor,'SME_PROSPECT_CONVERTED_V79','businesses',v_business.id,
    jsonb_build_object('prospect_id',p_prospect,'commercial_terms_id',v_terms.id,
      'sector_bundle_version_id',v_bundle.id,'branch_id',v_branch,'checklist_id',v_checklist));
  v_response:=jsonb_build_object('replayed',false,'outcome','converted','prospect_id',p_prospect,
    'prospect_version',v_prospect.version,'business_id',v_business.id,'branch_id',v_branch,
    'checklist_id',v_checklist,'owner_invitation',v_invite);
  perform app.v76_store_receipt(v_actor,'convert_prospect_v79',p_idempotency_key,v_hash,
    v_response#-'{owner_invitation,raw_token}');
  return v_response;
end
$$;

--
-- Name: FUNCTION convert_sme_prospect_v79(p_prospect uuid, p_expected_version bigint, p_idempotency_key text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.convert_sme_prospect_v79(p_prospect uuid, p_expected_version bigint, p_idempotency_key text) IS 'Transactional v79 client conversion. Raw invitation token is returned once and omitted from idempotency receipts.';

--
-- Name: correct_quick_sale_amount_v84(uuid, uuid, integer, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.correct_quick_sale_amount_v84(p_business uuid, p_sale uuid, p_corrected_amount_cents integer, p_idempotency_key text, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_key text := nullif(btrim(p_idempotency_key),'');
  v_note text := nullif(btrim(p_note),'');
  v_original public.sales%rowtype;
  v_existing public.sale_amount_corrections_v84%rowtype;
  v_payload jsonb;
  v_hash text;
  v_reverse jsonb;
  v_replacement jsonb;
  v_reversal_sale uuid;
  v_replacement_sale uuid;
  v_method text;
  v_paid boolean;
  v_payment_net_cents integer := 0;
  v_nonzero_payment_methods integer := 0;
  v_positive_payment_methods integer := 0;
  v_original_points integer := 0;
  v_original_batch_earned integer := 0;
  v_original_batch_remaining integer := 0;
  v_points_compensation_id uuid;
  v_earn_programme record;
  v_points_compensation_ids uuid[] := array[]::uuid[];
  v_points_removed_by_programme jsonb := '{}'::jsonb;
  v_points_earned integer := 0;
  v_result jsonb;
begin
  if v_actor is null
     or not app.has_perm(p_business,'refund_sales')
     or not app.has_perm(p_business,'create_sales') then
    raise exception 'sale correction requires active create-sales and refund-sales authorization'
      using errcode='42501';
  end if;
  if v_key is null or length(v_key) not between 8 and 200 then
    raise exception 'idempotency key must contain 8 to 200 characters'
      using errcode='22023';
  end if;
  if coalesce(p_corrected_amount_cents,0) <= 0 then
    raise exception 'corrected sale amount must be positive'
      using errcode='22023';
  end if;

  select * into v_original
    from public.sales
   where id=p_sale and business_id=p_business;
  if not found then
    raise exception 'sale not found in this business' using errcode='42501';
  end if;
  if not app.can_see_branch(p_business,v_original.branch_id) then
    raise exception 'sale branch scope is not permitted' using errcode='42501';
  end if;

  -- Authorization precedes the attacker-selected idempotency lock.
  perform pg_advisory_xact_lock(
    hashtextextended(p_business::text||':sale-correction-v84:'||v_key,0)
  );

  v_payload := jsonb_build_object(
    'business_id',p_business,
    'sale_id',p_sale,
    'branch_id',v_original.branch_id,
    'actor',v_actor,
    'original_amount_cents',v_original.amount_cents,
    'corrected_amount_cents',p_corrected_amount_cents,
    'note',v_note
  );
  v_hash := md5(v_payload::text);

  select * into v_existing
    from public.sale_amount_corrections_v84 correction
   where correction.business_id=p_business
     and correction.idempotency_key=v_key;
  if found then
    if v_existing.original_sale_id is distinct from p_sale
       or v_existing.request_hash is distinct from v_hash
       or v_existing.request_payload is distinct from v_payload then
      raise exception 'sale-correction idempotency key conflicts with a changed request'
        using errcode='23505';
    end if;
    if not exists (
      select 1
        from public.sales original
        join public.sales reversal
          on reversal.id=v_existing.reversal_sale_id
         and reversal.business_id=original.business_id
         and reversal.reversal_of=original.id
        join public.sales replacement
          on replacement.id=v_existing.replacement_sale_id
         and replacement.business_id=original.business_id
       where original.id=v_existing.original_sale_id
         and original.business_id=v_existing.business_id
         and original.amount_cents=v_existing.original_amount_cents
         and reversal.amount_cents=-v_existing.original_amount_cents
         and replacement.amount_cents=v_existing.corrected_amount_cents
    ) then
      raise exception 'completed sale correction is missing exact sale-chain evidence'
        using errcode='XX001';
    end if;
    if (v_existing.points_removed=0
          and v_existing.points_compensation_ledger_id is not null)
       or (v_existing.points_removed>0 and (
         v_existing.points_compensation_ledger_id is null
         or not coalesce(case
              when v_existing.points_compensation_ledger_ids is null
               and v_existing.points_removed_by_programme is null
              then exists (
                select 1
                  from public.points_ledger compensation
                 where compensation.id=v_existing.points_compensation_ledger_id
                   and compensation.business_id=v_existing.business_id
                   and compensation.client_id=(
                     select original.client_id
                       from public.sales original
                      where original.id=v_existing.original_sale_id
                        and original.business_id=v_existing.business_id
                   )
                   and compensation.sale_id=v_existing.reversal_sale_id
                   and compensation.entry_type='adjust'
                   and compensation.points=-v_existing.points_removed
              )
              else (
                select jsonb_typeof(v_existing.points_removed_by_programme)='object'
                   and coalesce(array_length(v_existing.points_compensation_ledger_ids,1),0)>0
                   and count(*)=coalesce(array_length(v_existing.points_compensation_ledger_ids,1),0)
                   and coalesce(sum(compensation.points),0)=-v_existing.points_removed
                   and count(*) filter (
                         where (v_existing.points_removed_by_programme
                                  ->>compensation.programme_id::text)::integer
                               is distinct from -compensation.points)=0
                   and count(distinct compensation.programme_id)=(
                         select count(*)
                           from jsonb_object_keys(v_existing.points_removed_by_programme))
                  from public.points_ledger compensation
                 where compensation.id=any(v_existing.points_compensation_ledger_ids)
                   and compensation.business_id=v_existing.business_id
                   and compensation.client_id=(
                     select original.client_id
                       from public.sales original
                      where original.id=v_existing.original_sale_id
                        and original.business_id=v_existing.business_id
                   )
                   and compensation.sale_id=v_existing.reversal_sale_id
                   and compensation.entry_type='adjust'
              )
            end,false)
         or exists (
           select 1
             from public.points_batches batch
            where batch.business_id=v_existing.business_id
              and batch.sale_id=v_existing.original_sale_id
              and batch.remaining<>0
         )
       )) then
      raise exception 'completed sale correction is missing exact loyalty compensation evidence'
        using errcode='XX001';
    end if;
    return v_existing.result || jsonb_build_object('replayed',true);
  end if;

  select * into v_original
    from public.sales
   where id=p_sale and business_id=p_business
   for update;
  if not found
     or not app.has_perm(p_business,'refund_sales')
     or not app.has_perm(p_business,'create_sales')
     or not app.can_see_branch(p_business,v_original.branch_id) then
    raise exception 'sale correction authorization changed while locking'
      using errcode='42501';
  end if;
  if v_original.reversal_of is not null
     or v_original.amount_cents <= 0
     or v_original.kind <> 'quick_sale' then
    raise exception 'only a positive original quick sale can use fast amount correction'
      using errcode='22023';
  end if;
  if p_corrected_amount_cents=v_original.amount_cents then
    raise exception 'corrected amount is unchanged' using errcode='22023';
  end if;
  if exists (
    select 1 from public.sales reversal
     where reversal.business_id=p_business and reversal.reversal_of=v_original.id
  ) then
    raise exception 'sale is already reversed; correct the active replacement instead'
      using errcode='23505';
  end if;
  if exists (
    select 1 from public.sale_amount_corrections_v84 correction
     where correction.original_sale_id=v_original.id
  ) then
    raise exception 'sale was already corrected; correct the active replacement instead'
      using errcode='23505';
  end if;
  if v_original.staff_id is not null and not exists (
    select 1 from public.staff staff
     where staff.id=v_original.staff_id
       and staff.business_id=p_business
       and staff.active
  ) then
    raise exception 'the originally tagged team member is inactive; use reversal and a new sale'
      using errcode='55000';
  end if;

  -- Lock the customer before inspecting FEFO point batches. A fast correction can remove
  -- only the exact, wholly-unspent earn created by the source sale. If any of that earn was
  -- consumed, the coherent automatic path no longer exists and the whole correction refuses
  -- before reverse_sale writes anything.
  if v_original.client_id is not null then
    perform 1
      from public.clients client
     where client.id=v_original.client_id
       and client.business_id=p_business
     for update;
    if not found then
      raise exception 'sale customer no longer belongs to this business' using errcode='XX001';
    end if;
  end if;
  select coalesce(sum(ledger.points),0)::integer
    into v_original_points
    from public.points_ledger ledger
   where ledger.business_id=p_business
     and ledger.sale_id=v_original.id
     and ledger.entry_type='earn';
  if v_original_points>0 then
    if v_original.client_id is null then
      raise exception 'sale earn has no customer provenance' using errcode='XX001';
    end if;
    perform 1
      from public.points_batches batch
     where batch.business_id=p_business
       and batch.client_id=v_original.client_id
       and batch.sale_id=v_original.id
     order by batch.id
     for update;
    select coalesce(sum(batch.earned),0)::integer,
           coalesce(sum(batch.remaining),0)::integer
      into v_original_batch_earned,v_original_batch_remaining
      from public.points_batches batch
     where batch.business_id=p_business
       and batch.client_id=v_original.client_id
       and batch.sale_id=v_original.id;
    if v_original_batch_earned<>v_original_points
       or v_original_batch_remaining<>v_original_points then
      raise exception 'original loyalty points are not wholly unspent; fast correction requires manual loyalty reconciliation'
        using errcode='55000';
    end if;
  elsif exists (
    select 1
      from public.points_batches batch
     where batch.business_id=p_business
       and batch.sale_id=v_original.id
  ) then
    raise exception 'sale points batch has no matching immutable earn' using errcode='XX001';
  end if;

  -- The creation request is valid only as an unpaid method preference. Paid state is derived
  -- from the CURRENT net payment journal under the locked sale, so later payments are never
  -- silently discarded. Fast correction supports exactly unpaid (net zero) or fully-paid
  -- single-method cash. Partial, mixed, overpaid, credit and provider-settled cases refuse.
  select nullif(operation.request_payload->>'method','')
    into v_method
    from public.financial_operations operation
   where operation.business_id=p_business
     and operation.sale_id=v_original.id
     and operation.operation_type='quick_sale'
     and operation.status='completed'
   order by operation.completed_at desc,operation.id desc
   limit 1;
  if not found then
    raise exception 'quick-sale creation evidence is missing' using errcode='XX001';
  end if;
  if v_method not in ('cash','card','paynow','bank_transfer','other') then
    raise exception 'the original unpaid method preference cannot be reproduced by quick sale'
      using errcode='0A000';
  end if;
  with method_nets as (
    select payment.method,sum(payment.amount_cents)::integer as net_cents
      from public.payments payment
     where payment.business_id=p_business
       and (
         payment.sale_id=v_original.id
         or (
           payment.sale_id is null
           and v_original.appointment_id is not null
           and payment.appointment_id=v_original.appointment_id
         )
       )
     group by payment.method
  )
  select coalesce(sum(net_cents),0)::integer,
         count(*) filter (where net_cents<>0)::integer,
         count(*) filter (where net_cents>0)::integer,
         min(method) filter (where net_cents>0)
    into v_payment_net_cents,v_nonzero_payment_methods,
         v_positive_payment_methods,v_method
    from method_nets;
  if v_payment_net_cents=0 and v_nonzero_payment_methods=0 then
    v_paid:=false;
    select nullif(operation.request_payload->>'method','')
      into v_method
      from public.financial_operations operation
     where operation.business_id=p_business
       and operation.sale_id=v_original.id
       and operation.operation_type='quick_sale'
       and operation.status='completed'
     order by operation.completed_at desc,operation.id desc
     limit 1;
  elsif v_payment_net_cents=v_original.amount_cents
        and v_nonzero_payment_methods=1
        and v_positive_payment_methods=1
        and v_method='cash' then
    v_paid:=true;
  else
    raise exception 'fast correction supports only net-unpaid or fully-paid single-method cash sales; current payment state is % cents across % nonzero methods',
      v_payment_net_cents,v_nonzero_payment_methods
      using errcode='0A000';
  end if;

  -- These two calls execute in this function's transaction. Any refusal or failure in
  -- either call rolls back both operations and the audit link.
  v_reverse := public.reverse_sale(
    p_business,
    v_original.id,
    'Amount corrected from '||v_original.amount_cents::text
      ||' to '||p_corrected_amount_cents::text||' cents'
      ||case when v_note is null then '' else ' · Staff note: '||v_note end,
    'v84:'||md5(v_key)||':reverse',
    'Peekaa amount correction',
    'none'
  )::jsonb;
  v_reversal_sale := nullif(v_reverse->>'reversal_sale_id','')::uuid;
  if v_reversal_sale is null then
    raise exception 'sale correction did not produce reversal evidence' using errcode='XX001';
  end if;

  if v_original_points>0 then
    v_points_compensation_id:=gen_random_uuid();
    perform set_config(
      'app.points_ledger_insert_id',v_points_compensation_id::text,true
    );
    perform set_config(
      'app.points_ledger_write_scope','sale_amount_correction_v84',true
    );
    null;
    for v_earn_programme in
      select ledger.programme_id as programme_id,
             coalesce(sum(ledger.points),0)::integer as points
        from public.points_ledger ledger
       where ledger.business_id=p_business
         and ledger.sale_id=v_original.id
         and ledger.entry_type='earn'
       group by ledger.programme_id
       order by ledger.programme_id
    loop
      if v_earn_programme.points<=0 then continue; end if;
      v_points_compensation_id:=gen_random_uuid();
      perform set_config(
        'app.points_ledger_insert_id',v_points_compensation_id::text,true
      );
      perform set_config(
        'app.points_ledger_write_scope','sale_amount_correction_v84',true
      );
      insert into public.points_ledger(
        id,business_id,client_id,entry_type,points,sale_id,reference,actor,programme_id
      ) values (
        v_points_compensation_id,p_business,v_original.client_id,'adjust',
        -v_earn_programme.points,v_reversal_sale,
        'sale amount correction: remove original earn for sale '||v_original.id,
        v_actor,v_earn_programme.programme_id
      );
      perform set_config('app.points_ledger_insert_id','',true);
      perform set_config('app.points_ledger_write_scope','',true);

      update public.points_batches batch
         set remaining=0
       where batch.business_id=p_business
         and batch.client_id=v_original.client_id
         and batch.sale_id=v_original.id
         and batch.programme_id=v_earn_programme.programme_id
         and batch.remaining=batch.earned;

      v_points_compensation_ids:=v_points_compensation_ids||v_points_compensation_id;
      v_points_removed_by_programme:=v_points_removed_by_programme
        ||jsonb_build_object(v_earn_programme.programme_id::text,v_earn_programme.points);
    end loop;
    v_points_compensation_id:=v_points_compensation_ids[1];
    if (select coalesce(sum(ledger.points),0)::integer
          from public.points_ledger ledger
         where ledger.business_id=p_business
           and ledger.client_id=v_original.client_id)
       <> (select coalesce(sum(batch.remaining),0)::integer
             from public.points_batches batch
            where batch.business_id=p_business
              and batch.client_id=v_original.client_id) then
      raise exception 'points ledger and batch cache diverged during sale correction'
        using errcode='XX001';
    end if;
    if exists (
      select 1
        from (select ledger.programme_id,sum(ledger.points) as total
                from public.points_ledger ledger
               where ledger.business_id=p_business
                 and ledger.client_id=v_original.client_id
               group by ledger.programme_id) led
        full join (select batch.programme_id,sum(batch.remaining) as total
                     from public.points_batches batch
                    where batch.business_id=p_business
                      and batch.client_id=v_original.client_id
                    group by batch.programme_id) bat
          on bat.programme_id=led.programme_id
       where coalesce(led.total,0)<>coalesce(bat.total,0)
    ) then
      raise exception 'per-programme points ledger and batch cache diverged during sale correction'
        using errcode='XX001';
    end if;
  end if;

  v_replacement := public.record_quick_sale(
    p_business=>p_business,
    p_amount_cents=>p_corrected_amount_cents,
    p_method=>v_method,
    p_client=>v_original.client_id,
    p_staff=>v_original.staff_id,
    p_branch=>v_original.branch_id,
    p_note=>v_original.note,
    p_idempotency_key=>'v84:'||md5(v_key)||':replacement',
    p_paid=>v_paid
  )::jsonb;
  v_replacement_sale := nullif(v_replacement #>> '{sale,id}','')::uuid;
  if v_replacement_sale is null then
    raise exception 'sale correction did not produce replacement evidence' using errcode='XX001';
  end if;

  select coalesce(sum(points),0)::integer
    into v_points_earned
    from public.points_ledger
   where business_id=p_business
     and sale_id=v_replacement_sale
     and entry_type='earn';
  if v_original.client_id is not null
     and (select coalesce(sum(ledger.points),0)::integer
            from public.points_ledger ledger
           where ledger.business_id=p_business
             and ledger.client_id=v_original.client_id)
         <> (select coalesce(sum(batch.remaining),0)::integer
               from public.points_batches batch
              where batch.business_id=p_business
                and batch.client_id=v_original.client_id) then
    raise exception 'replacement sale left points ledger and batch cache inconsistent'
      using errcode='XX001';
  end if;

  v_result := jsonb_build_object(
    'status','corrected',
    'original_sale_id',v_original.id,
    'reversal_sale_id',v_reversal_sale,
    'replacement_sale_id',v_replacement_sale,
    'original_amount_cents',v_original.amount_cents,
    'corrected_amount_cents',p_corrected_amount_cents,
    'branch_id',v_original.branch_id,
    'client_id',v_original.client_id,
    'staff_id',v_original.staff_id,
    'payment_method',v_method,
    'paid',v_paid,
    'current_payment_cents',v_payment_net_cents,
    'points_removed',v_original_points,
    'points_compensation_ledger_id',v_points_compensation_id,
    'points_compensation_ledger_ids',to_jsonb(v_points_compensation_ids),
    'points_removed_by_programme',v_points_removed_by_programme,
    'points_earned',v_points_earned,
    'refunded_payment_cents',coalesce((v_reverse->>'refunded_payment_cents')::integer,0),
    'replacement_payment_id',nullif(v_replacement->>'payment_id','')::uuid,
    'replayed',false
  );

  insert into public.sale_amount_corrections_v84(
    business_id,branch_id,original_sale_id,reversal_sale_id,replacement_sale_id,
    actor,original_amount_cents,corrected_amount_cents,points_removed,
    points_compensation_ledger_id,points_compensation_ledger_ids,
    points_removed_by_programme,note,idempotency_key,request_payload,request_hash,result
  ) values (
    p_business,v_original.branch_id,v_original.id,v_reversal_sale,v_replacement_sale,
    v_actor,v_original.amount_cents,p_corrected_amount_cents,v_original_points,
    v_points_compensation_id,v_points_compensation_ids,
    v_points_removed_by_programme,v_note,v_key,v_payload,v_hash,v_result
  );

  insert into public.audit_log(business_id,actor,action,entity,entity_id,detail)
  values (
    p_business,v_actor,'SALE_AMOUNT_CORRECTED_V84','sales',v_original.id,
    jsonb_build_object(
      'original_sale_id',v_original.id,
      'reversal_sale_id',v_reversal_sale,
      'replacement_sale_id',v_replacement_sale,
      'original_amount_cents',v_original.amount_cents,
      'corrected_amount_cents',p_corrected_amount_cents,
      'branch_id',v_original.branch_id,
      'client_id',v_original.client_id,
      'staff_id',v_original.staff_id,
      'current_payment_cents',v_payment_net_cents,
      'points_removed',v_original_points,
      'points_compensation_ledger_id',v_points_compensation_id,
      'note',v_note
    )
  );

  return v_result;
end
$$;

--
-- Name: FUNCTION correct_quick_sale_amount_v84(p_business uuid, p_sale uuid, p_corrected_amount_cents integer, p_idempotency_key text, p_note text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.correct_quick_sale_amount_v84(p_business uuid, p_sale uuid, p_corrected_amount_cents integer, p_idempotency_key text, p_note text) IS 'Atomically reverses a positive quick sale, removes a wholly-unspent original point earn, and records its corrected append-only replacement; partial/mixed/non-cash paid states refuse.';

--
-- Name: create_business(text, text, text, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_business(p_name text, p_slug text, p_industry text, p_modules text[]) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  raise exception 'approved_business_invitation_required' using errcode='42501';
end
$$;

--
-- Name: create_client_field_definition(uuid, text, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_client_field_definition(p_business uuid, p_field_key text, p_label text, p_value_type text, p_classification text, p_options jsonb DEFAULT '[]'::jsonb) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $_$
declare
  v_definition_id uuid;
  v_option jsonb;
  v_option_count integer := 0;
  v_option_key text;
  v_option_label text;
begin
  if not app.is_salon_owner(p_business) then
    raise exception 'owner only' using errcode = '42501';
  end if;
  if p_options is null or jsonb_typeof(p_options) <> 'array' then
    raise exception 'field options must be a JSON array' using errcode = '22023';
  end if;
  if jsonb_array_length(p_options) > 100 then
    raise exception 'a field may have at most 100 options' using errcode = '22023';
  end if;
  if p_value_type <> 'select' and jsonb_array_length(p_options) > 0 then
    raise exception 'only select fields may define options' using errcode = 'check_violation';
  end if;
  if p_value_type = 'select' and jsonb_array_length(p_options) < 2 then
    raise exception 'select fields require at least 2 options' using errcode = 'check_violation';
  end if;

  insert into public.client_field_definitions(
    business_id, field_key, label, value_type, classification
  ) values (
    p_business, p_field_key, p_label, p_value_type, p_classification
  ) returning id into v_definition_id;

  for v_option in select value from jsonb_array_elements(p_options) loop
    if jsonb_typeof(v_option) <> 'object' then
      raise exception 'each field option must be a JSON object' using errcode = '22023';
    end if;
    v_option_key := lower(btrim(v_option->>'option_key'));
    v_option_label := btrim(v_option->>'option_label');
    if v_option_key is null or v_option_key !~ '^[a-z][a-z0-9_\-]{0,63}$' then
      raise exception 'field option key is invalid' using errcode = 'check_violation';
    end if;
    if v_option_label is null or length(v_option_label) not between 1 and 120 then
      raise exception 'field option label must be 1 to 120 characters' using errcode = 'check_violation';
    end if;
    insert into public.client_field_options(
      business_id, field_definition_id, option_key, option_label
    ) values (
      p_business, v_definition_id, v_option_key, v_option_label
    );
    v_option_count := v_option_count + 1;
  end loop;

  return json_build_object(
    'id', v_definition_id,
    'business_id', p_business,
    'field_key', lower(btrim(p_field_key)),
    'value_type', p_value_type,
    'classification', p_classification,
    'options_created', v_option_count
  );
end
$_$;

--
-- Name: create_consultant_commission_policy_v78(text, integer, integer, integer, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_consultant_commission_policy_v78(p_tier text, p_first_year_bps integer, p_anniversary_bonus_bps integer, p_renewal_bps integer, p_effective_from timestamp with time zone, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid:=auth.uid();
  v_prior public.consultant_commission_policies%rowtype;
  v_new public.consultant_commission_policies%rowtype;
begin
  if v_actor is null or not app.v89_platform_can('commissions','rw') then
    raise exception 'super-admin access is required' using errcode='42501';
  end if;
  if p_tier not in ('senior','junior')
     or p_first_year_bps not between 0 and 10000
     or p_anniversary_bonus_bps not between 0 and 10000
     or p_first_year_bps+p_anniversary_bonus_bps>10000
     or p_renewal_bps not between 0 and 10000
     or p_effective_from is null
     or p_effective_from<now()-interval '5 minutes'
     or nullif(btrim(p_reason),'') is null or length(p_reason)>1000 then
    raise exception 'invalid consultant commission policy' using errcode='22023';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(
    'v78:consultant-policy:'||p_tier,0
  ));
  select * into strict v_prior
    from public.consultant_commission_policies
   where tier=p_tier and effective_to is null
   for update;
  if p_effective_from<=v_prior.effective_from then
    raise exception 'new policy must start after the open version'
      using errcode='22023';
  end if;
  update public.consultant_commission_policies
     set effective_to=p_effective_from
   where id=v_prior.id;
  insert into public.consultant_commission_policies(
    tier,version,effective_from,first_year_bps,anniversary_bonus_bps,
    renewal_bps,reason,created_by
  ) values (
    p_tier,v_prior.version+1,p_effective_from,p_first_year_bps,
    p_anniversary_bonus_bps,p_renewal_bps,btrim(p_reason),v_actor
  ) returning * into v_new;
  insert into public.audit_log(
    business_id,actor,action,entity,entity_id,detail
  ) values (
    null,v_actor,'CONSULTANT_COMMISSION_POLICY_VERSIONED_V78',
    'consultant_commission_policies',v_new.id,
    jsonb_build_object(
      'tier',p_tier,'version',v_new.version,
      'first_year_bps',p_first_year_bps,
      'anniversary_bonus_bps',p_anniversary_bonus_bps,
      'renewal_bps',p_renewal_bps,
      'effective_from',p_effective_from,'reason',btrim(p_reason)
    )
  );
  return to_jsonb(v_new);
end
$$;

--
-- Name: create_consultant_payout_batch_v78(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_consultant_payout_batch_v78(p_currency text, p_note text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $_$
declare v_id uuid;
begin
  if auth.uid() is null or not app.v89_platform_can('commissions','rw') then
    raise exception 'super-admin access is required' using errcode='42501';
  end if;
  if p_currency !~ '^[A-Z]{3}$' or length(coalesce(p_note,''))>1000 then
    raise exception 'invalid payout batch' using errcode='22023';
  end if;
  insert into public.consultant_payout_batches(currency,note,created_by)
  values(p_currency,nullif(btrim(p_note),''),auth.uid()) returning id into v_id;
  return v_id;
end
$_$;

--
-- Name: create_customer_intelligence_export_v83(uuid, uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_customer_intelligence_export_v83(p_business uuid, p_branch uuid DEFAULT NULL::uuid, p_from date DEFAULT (((now() AT TIME ZONE 'Asia/Singapore'::text))::date - 365), p_to date DEFAULT ((now() AT TIME ZONE 'Asia/Singapore'::text))::date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid:=auth.uid();
  v_export uuid:=gen_random_uuid();
  v_snapshot timestamptz:=clock_timestamp();
  v_expires timestamptz:=v_snapshot+interval '24 hours';
  v_page jsonb;
  v_cursor jsonb;
  v_customer jsonb;
  v_ordinal integer:=0;
begin
  if v_actor is null then
    raise exception 'authenticated_user_required' using errcode='42501';
  end if;
  if not app.has_perm(p_business,'view_finance') then
    raise exception 'view_finance_required' using errcode='42501';
  end if;
  delete from public.customer_intelligence_exports_v83
  where requested_by=v_actor and expires_at<=clock_timestamp();

  v_page:=public.get_customer_intelligence_v83(
    p_business,p_branch,p_from,p_to,500,v_snapshot,null,null
  );
  insert into public.customer_intelligence_exports_v83(
    id,business_id,branch_id,requested_by,from_date,to_date,snapshot_at,
    expires_at,scope,methodology,data_quality,summary,forecast,total_customers
  ) values (
    v_export,p_business,p_branch,v_actor,p_from,p_to,v_snapshot,v_expires,
    v_page->'scope',v_page->'methodology',v_page->'data_quality',
    v_page->'summary',v_page->'forecast',
    coalesce((v_page#>>'{pagination,total_customers}')::integer,0)
  );

  loop
    for v_customer in select value from jsonb_array_elements(v_page->'customers')
    loop
      v_ordinal:=v_ordinal+1;
      insert into public.customer_intelligence_export_rows_v83(
        export_id,ordinal,client_id,payload
      ) values (
        v_export,v_ordinal,(v_customer->>'client_id')::uuid,v_customer
      );
    end loop;
    v_cursor:=v_page#>'{pagination,next_cursor}';
    exit when v_cursor is null or v_cursor='null'::jsonb;
    v_page:=public.get_customer_intelligence_v83(
      p_business,p_branch,p_from,p_to,500,v_snapshot,
      (v_cursor->>'customer_since')::timestamptz,
      (v_cursor->>'client_id')::uuid
    );
  end loop;

  return jsonb_build_object(
    'export_id',v_export,'snapshot_at',v_snapshot,'expires_at',v_expires,
    'total_customers',v_ordinal
  );
end
$$;

--
-- Name: FUNCTION create_customer_intelligence_export_v83(p_business uuid, p_branch uuid, p_from date, p_to date); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.create_customer_intelligence_export_v83(p_business uuid, p_branch uuid, p_from date, p_to date) IS 'Materialises a 24-hour customer-intelligence export at one immutable generated-at cutoff.';

--
-- Name: create_expense(uuid, uuid, text, integer, date, text, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_expense(p_business uuid, p_branch uuid, p_category text, p_amount_cents integer, p_occurred_on date, p_supplier text, p_description text, p_note text, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_staff uuid;
  v_category text := nullif(btrim(p_category), '');
  v_supplier text := nullif(btrim(p_supplier), '');
  v_description text := nullif(btrim(p_description), '');
  v_note text := nullif(btrim(p_note), '');
  v_sgt_today date := (timezone('Asia/Singapore', now()))::date;
  v_occurred date := coalesce(p_occurred_on, (timezone('Asia/Singapore', now()))::date);
  v_payload jsonb;
  v_hash text;
  v_existing public.f2_write_operations%rowtype;
  v_expense_id uuid;
  v_result jsonb;
begin
  if v_actor is null then
    raise exception 'authenticated staff required' using errcode = '42501';
  end if;
  if p_idempotency_key is null then
    raise exception 'an expense idempotency key is required' using errcode = '22023';
  end if;
  -- Active staff of THIS business, module-write on expenses, and the finance permission.
  select s.id into v_staff
    from public.staff s
   where s.business_id = p_business
     and s.user_id = v_actor
     and s.active
   order by case when s.role = 'owner' then 0 else 1 end, s.created_at
   limit 1
   for update;
  if v_staff is null
     or not app.can_module_write(p_business, 'expenses')
     or not app.has_perm(p_business, 'view_finance') then
    raise exception 'active expenses-module write authorization with view_finance is required'
      using errcode = '42501';
  end if;

  -- Payload validation (fail-closed).
  if v_category is null or char_length(v_category) < 1 or char_length(v_category) > 80 then
    raise exception 'expense category must be 1..80 characters' using errcode = '22023';
  end if;
  if p_amount_cents is null or p_amount_cents < 1 or p_amount_cents > 100000000 then
    raise exception 'expense amount must be between 1 and 100000000 cents' using errcode = '22023';
  end if;
  if v_supplier is not null and char_length(v_supplier) > 160 then
    raise exception 'expense supplier is too long' using errcode = '22023';
  end if;
  if v_description is not null and char_length(v_description) > 500 then
    raise exception 'expense description is too long' using errcode = '22023';
  end if;
  if v_note is not null and char_length(v_note) > 500 then
    raise exception 'expense note is too long' using errcode = '22023';
  end if;
  if v_occurred > v_sgt_today + 1
     or v_occurred < (v_sgt_today - interval '5 years')::date then
    raise exception 'expense date is outside the accepted window' using errcode = '22023';
  end if;
  if p_branch is not null and not exists (
    select 1 from public.branches b
     where b.id = p_branch and b.business_id = p_business and b.active
  ) then
    raise exception 'expense branch does not belong to this business or is inactive'
      using errcode = '22023';
  end if;

  v_payload := jsonb_build_object(
    'amount_cents', p_amount_cents,
    'branch_id', p_branch,
    'business_id', p_business,
    'category', v_category,
    'description', v_description,
    'note', v_note,
    'occurred_on', v_occurred,
    'supplier', v_supplier
  );
  v_hash := app.v41_request_hash(v_payload::text);
  perform pg_advisory_xact_lock(hashtextextended(
    'v54:expense:' || p_business::text || ':' || p_idempotency_key::text, 0));

  select * into v_existing
    from public.f2_write_operations o
   where o.business_id = p_business and o.idempotency_key = p_idempotency_key
   for update;
  if found then
    if v_existing.actor is distinct from v_actor
       or v_existing.operation_type <> 'expense_create'
       or v_existing.request_hash <> v_hash then
      raise exception 'idempotency key conflicts with another expense request'
        using errcode = '23505';
    end if;
    return jsonb_build_object(
      'status', 'duplicate_ignored',
      'expense_id', (v_existing.result->>'expense_id')::uuid,
      'replayed', true
    );
  end if;

  -- Value row + explicit semantic audit row, in this one transaction.
  insert into public.expenses (
    business_id, branch_id, category, supplier, description,
    amount_cents, occurred_on, note, created_by
  ) values (
    p_business, p_branch, v_category, v_supplier, v_description,
    p_amount_cents, v_occurred, v_note, v_actor
  ) returning id into v_expense_id;

  insert into public.audit_log (business_id, actor, action, entity, entity_id, detail)
  values (p_business, v_actor, 'expense_create', 'expenses', v_expense_id,
          jsonb_build_object(
            'idempotency_key', p_idempotency_key,
            'amount_cents', p_amount_cents,
            'category', v_category,
            'branch_id', p_branch,
            'occurred_on', v_occurred));

  v_result := jsonb_build_object('status', 'ok', 'expense_id', v_expense_id, 'replayed', false);
  insert into public.f2_write_operations (
    business_id, actor, operation_type, idempotency_key, request_hash, status, result
  ) values (
    p_business, v_actor, 'expense_create', p_idempotency_key, v_hash, 'completed', v_result);
  return v_result;
end $$;

--
-- Name: create_grow_config_draft_v138(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_grow_config_draft_v138(p_business uuid, p_based_on uuid DEFAULT NULL::uuid, p_source text DEFAULT 'grow_shared_edit'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid:=auth.uid();
  v_base uuid;
  v_existing public.firm_config_versions%rowtype;
  v_typed public.loyalty_program_versions%rowtype;
  v_id uuid;
  v_no integer;
  v_snapshot_hash text;
begin
  if v_actor is null or not app.is_salon_owner(p_business)
     or not (
       app.can_module_write(p_business,'loyalty')
       or app.can_module_write(p_business,'retention')
     ) then
    raise exception 'owner Grow configuration access required' using errcode='42501';
  end if;
  if p_source not in ('grow_shared_edit','grow_retention_edit','grow_reward_edit') then
    raise exception 'invalid Grow draft source' using errcode='22023';
  end if;

  perform 1 from public.businesses where id=p_business for update;
  if not found then
    raise exception 'business is unavailable' using errcode='22023';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('v138:grow-draft:'||p_business::text,0));
  v_base:=coalesce(
    p_based_on,
    app.active_config_version(p_business),
    (select current_config_version_id from public.loyalty_programs where business_id=p_business)
  );
  if v_base is null or not exists(
    select 1 from public.firm_config_versions
     where id=v_base and business_id=p_business and status='published'
  ) then
    raise exception 'published base configuration not found' using errcode='22023';
  end if;

  select * into v_existing from public.firm_config_versions
   where business_id=p_business and based_on_version_id=v_base and status='draft'
   order by version_no desc limit 1 for update;
  if found then
    return jsonb_build_object(
      'version_id',v_existing.id,'version_no',v_existing.version_no,
      'status','draft','snapshot_hash',v_existing.snapshot_hash,
      'replayed',true,'published',false
    );
  end if;

  select * into v_typed from public.loyalty_program_versions
   where config_version_id=v_base and business_id=p_business;
  if not found then
    raise exception 'base Loyalty configuration not found' using errcode='22023';
  end if;
  select coalesce(max(version_no),0)+1 into v_no
    from public.firm_config_versions where business_id=p_business;
  v_id:=gen_random_uuid();
  insert into public.firm_config_versions(
    id,business_id,version_no,status,based_on_version_id,source,snapshot_hash,created_by
  ) values(
    v_id,p_business,v_no,'draft',v_base,p_source,
    md5((to_jsonb(v_typed)-'config_version_id')::text),v_actor
  );
  perform set_config('app.v138_grow_draft_id',v_id::text,true);
  perform set_config('app.v138_grow_draft_actor',v_actor::text,true);
  insert into public.loyalty_program_versions(
    config_version_id,business_id,kind,loyalty_model,active,
    earn_points_per_dollar,redeem_points,reward_credit_cents,
    stamp_target,stamp_per_cents,tier_basis,expiry_mode,expiry_days
  ) select
    v_id,business_id,kind,loyalty_model,active,
    earn_points_per_dollar,redeem_points,reward_credit_cents,
    stamp_target,stamp_per_cents,tier_basis,expiry_mode,expiry_days
  from public.loyalty_program_versions
  where config_version_id=v_base and business_id=p_business;
  perform set_config('app.v138_grow_draft_id','',true);
  perform set_config('app.v138_grow_draft_actor','',true);
  insert into public.loyalty_tier_versions(
    tier_id,config_version_id,business_id,name,threshold,
    points_multiplier,perk_note,sort,active
  ) select
    tier_id,v_id,business_id,name,threshold,
    points_multiplier,perk_note,sort,active
  from public.loyalty_tier_versions
  where config_version_id=v_base and business_id=p_business;
  perform app.refresh_loyalty_config_snapshot(v_id);
  select snapshot_hash into v_snapshot_hash
    from public.firm_config_versions where id=v_id;
  insert into public.audit_log(business_id,actor,action,entity,entity_id,detail)
  values(p_business,v_actor,'CREATE_GROW_DRAFT','firm_config_versions',v_id,
    jsonb_build_object('based_on_version_id',v_base,'source',p_source,'published',false));
  return jsonb_build_object(
    'version_id',v_id,'version_no',v_no,'status','draft',
    'snapshot_hash',v_snapshot_hash,'replayed',false,'published',false
  );
end $$;

--
-- Name: FUNCTION create_grow_config_draft_v138(p_business uuid, p_based_on uuid, p_source text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.create_grow_config_draft_v138(p_business uuid, p_based_on uuid, p_source text) IS 'Owner-only V138 shared Grow draft creation for Loyalty or retention writers; exact replay returns the existing draft and never publishes.';

--
-- Name: create_invite(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_invite(p_business uuid, p_role text, p_email text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_code text; inv staff_invites;
begin
  if not app.is_salon_owner(p_business) then raise exception 'owner role required'; end if;
  loop
    v_code := upper(substr(md5(random()::text || clock_timestamp()::text),1,8));
    exit when not exists (select 1 from staff_invites where code = v_code);
  end loop;
  insert into staff_invites (business_id, role, email, code)
  values (p_business, p_role, p_email, v_code) returning * into inv;
  return row_to_json(inv);
end $$;

--
-- Name: create_loyalty_config_draft(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_loyalty_config_draft(p_business uuid, p_based_on uuid DEFAULT NULL::uuid, p_source text DEFAULT 'manual'::text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid:=auth.uid();
  v_base uuid;
  v_id uuid;
  v_no integer;
  v_typed public.loyalty_program_versions%rowtype;
begin
  if not app.c45_owner_loyalty_write(p_business) then
    raise exception 'owner loyalty configuration access required' using errcode='42501';
  end if;
  perform 1 from public.businesses where id=p_business for update;
  v_base:=coalesce(
    p_based_on,
    app.active_config_version(p_business),
    (select current_config_version_id from public.loyalty_programs where business_id=p_business)
  );
  select * into v_typed from public.loyalty_program_versions
  where config_version_id=v_base and business_id=p_business;
  if not found then raise exception 'base configuration not found'; end if;
  select coalesce(max(version_no),0)+1 into v_no
  from public.firm_config_versions where business_id=p_business;
  v_id:=gen_random_uuid();
  insert into public.firm_config_versions(
    id,business_id,version_no,status,based_on_version_id,source,snapshot_hash,created_by
  ) values(
    v_id,p_business,v_no,'draft',v_base,
    coalesce(nullif(btrim(p_source),''),'manual'),
    md5((to_jsonb(v_typed)-'config_version_id')::text),v_actor
  );
  insert into public.loyalty_program_versions(
    config_version_id,business_id,kind,loyalty_model,active,
    earn_points_per_dollar,redeem_points,reward_credit_cents,stamp_target,
    stamp_per_cents,tier_basis,expiry_mode,expiry_days
  )
  select v_id,business_id,kind,loyalty_model,active,
    earn_points_per_dollar,redeem_points,reward_credit_cents,stamp_target,
    stamp_per_cents,tier_basis,expiry_mode,expiry_days
  from public.loyalty_program_versions where config_version_id=v_base;
  insert into public.loyalty_tier_versions(
    tier_id,config_version_id,business_id,name,threshold,points_multiplier,
    perk_note,sort,active,effective_from,expires_at
  )
  select tier_id,v_id,business_id,name,threshold,points_multiplier,
    perk_note,sort,active,effective_from,expires_at
  from public.loyalty_tier_versions where config_version_id=v_base;
  perform app.refresh_loyalty_config_snapshot(v_id);
  return json_build_object('version_id',v_id,'version_no',v_no,'status','draft');
end
$$;

--
-- Name: create_retention_campaign(uuid, uuid, text, jsonb, integer, bigint, integer, bigint, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_retention_campaign(p_business uuid, p_program_version_id uuid, p_name text, p_audience_criteria jsonb, p_holdout_percent integer DEFAULT 10, p_budget_cap_cents bigint DEFAULT 0, p_attribution_window_days integer DEFAULT 30, p_expected_cost_cents bigint DEFAULT NULL::bigint, p_expected_upside_cents bigint DEFAULT NULL::bigint, p_explanation text DEFAULT NULL::text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_rule public.retention_program_versions%rowtype;
  v_campaign_id uuid := gen_random_uuid();
  v_name text := btrim(coalesce(p_name, ''));
begin
  if not app.is_salon_owner(p_business) then
    raise exception 'owner only' using errcode = '42501';
  end if;
  perform 1 from public.businesses where id = p_business for share;
  if char_length(v_name) not between 1 and 120 then
    raise exception 'campaign name must be 1..120 characters' using errcode = '22023';
  end if;
  if p_audience_criteria is null or jsonb_typeof(p_audience_criteria) <> 'object' then
    raise exception 'audience criteria must be a JSON object' using errcode = '22023';
  end if;
  if coalesce(p_holdout_percent, -1) not between 0 and 90 then
    raise exception 'holdout percent must be between 0 and 90' using errcode = '22023';
  end if;
  if coalesce(p_budget_cap_cents, 0) < 0 then
    raise exception 'budget cap cannot be negative' using errcode = '22023';
  end if;
  if coalesce(p_attribution_window_days, 0) not between 1 and 365 then
    raise exception 'attribution window must be between 1 and 365 days' using errcode = '22023';
  end if;
  if p_explanation is not null and char_length(p_explanation) > 4000 then
    raise exception 'explanation is limited to 4000 characters' using errcode = '22023';
  end if;
  select * into v_rule from public.retention_program_versions
   where id = p_program_version_id and business_id = p_business;
  if not found then
    raise exception 'retention program version does not belong to this business' using errcode = '22023';
  end if;
  if exists(
    select 1 from public.retention_programs prog
     where prog.id = v_rule.program_id and prog.business_id = p_business and prog.deleted_at is not null
  ) then
    raise exception 'cannot create a campaign for a deleted bring-back rule' using errcode = '22023';
  end if;

  insert into public.retention_campaigns(
    id, business_id, retention_program_version_id, program_id, config_version_id,
    name, audience_criteria, holdout_percent, budget_cap_cents,
    expected_cost_cents, expected_upside_cents, attribution_window_days,
    explanation, status, created_by
  ) values (
    v_campaign_id, p_business, v_rule.id, v_rule.program_id, v_rule.config_version_id,
    v_name, p_audience_criteria, coalesce(p_holdout_percent, 10), coalesce(p_budget_cap_cents, 0),
    p_expected_cost_cents, p_expected_upside_cents, coalesce(p_attribution_window_days, 30),
    nullif(btrim(coalesce(p_explanation, '')), ''), 'draft', v_actor
  );
  insert into public.audit_log(business_id, actor, action, entity, entity_id, detail)
  values (p_business, v_actor, 'CREATE_RETENTION_CAMPAIGN', 'retention_campaigns', v_campaign_id,
    jsonb_build_object('retention_program_version_id', v_rule.id, 'holdout_percent', coalesce(p_holdout_percent, 10)));
  return json_build_object(
    'campaign_id', v_campaign_id, 'status', 'draft',
    'retention_program_version_id', v_rule.id, 'holdout_percent', coalesce(p_holdout_percent, 10),
    'attribution_window_days', coalesce(p_attribution_window_days, 30)
  );
end $$;

--
-- Name: create_service_bundle_v123(uuid, text, integer, uuid[], text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_service_bundle_v123(p_business uuid, p_name text, p_price_cents integer, p_service_ids uuid[], p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid:=auth.uid();
  v_name text:=btrim(coalesce(p_name,''));
  v_service_ids uuid[];
  v_request_hash text;
  v_existing app.service_bundle_operations_v123%rowtype;
  v_bundle_id uuid;
  v_response jsonb;
begin
  if v_actor is null or p_business is null
     or not app.can_module_write(p_business,'services') then
    raise exception 'permission denied' using errcode='42501';
  end if;

  select array_agg(service_id order by service_id)
    into v_service_ids
    from (
      select distinct candidate as service_id
        from unnest(coalesce(p_service_ids,array[]::uuid[])) candidate
       where candidate is not null
    ) normalized;

  if char_length(v_name) not between 2 and 120
     or p_price_cents is null or p_price_cents not between 0 and 100000000
     or p_idempotency_key is null
     or char_length(p_idempotency_key) not between 1 and 160
     or cardinality(coalesce(v_service_ids,array[]::uuid[])) not between 2 and 50
     or cardinality(coalesce(p_service_ids,array[]::uuid[]))
        <> cardinality(coalesce(v_service_ids,array[]::uuid[])) then
    raise exception 'invalid service bundle' using errcode='22023';
  end if;

  v_request_hash:=app.v41_request_hash(jsonb_build_object(
    'business_id',p_business,
    'name',v_name,
    'price_cents',p_price_cents,
    'service_ids',to_jsonb(v_service_ids)
  )::text);

  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    'v123:bundle:'||p_business::text||':'||v_actor::text||':'||p_idempotency_key,
    123
  ));

  select * into v_existing
    from app.service_bundle_operations_v123 operation
   where operation.business_id=p_business
     and operation.actor=v_actor
     and operation.idempotency_key=p_idempotency_key;
  if found then
    if v_existing.request_hash<>v_request_hash then
      raise exception 'idempotency key reused with a different bundle'
        using errcode='22023';
    end if;
    return v_existing.response||jsonb_build_object('replayed',true);
  end if;

  -- Mutable catalogue state is checked only for a fresh write. A lost-response
  -- replay must remain observable even if a service was disabled afterward.
  if (
    select count(*)
      from public.services service
     where service.business_id=p_business
       and service.active
       and service.id=any(v_service_ids)
  ) <> cardinality(v_service_ids) then
    raise exception 'bundle services must be active in this business'
      using errcode='22023';
  end if;

  insert into public.bundles (business_id,name,price_cents)
  values (p_business,v_name,p_price_cents)
  returning id into v_bundle_id;

  insert into public.bundle_items (bundle_id,service_id)
  select v_bundle_id,service_id from unnest(v_service_ids) service_id;

  v_response:=jsonb_build_object(
    'status','created','bundle_id',v_bundle_id,'replayed',false
  );

  insert into app.service_bundle_operations_v123 (
    business_id,actor,idempotency_key,request_hash,bundle_id,response
  ) values (
    p_business,v_actor,p_idempotency_key,v_request_hash,v_bundle_id,v_response
  );

  insert into public.audit_log (
    business_id,actor,action,entity,entity_id,detail
  ) values (
    p_business,v_actor,'SERVICE_BUNDLE_CREATE','bundles',v_bundle_id,
    jsonb_build_object(
      'name',v_name,'price_cents',p_price_cents,
      'service_count',cardinality(v_service_ids)
    )
  );

  return v_response;
end
$$;

--
-- Name: create_staff_blocked_time_v120(uuid, uuid, uuid, timestamp with time zone, timestamp with time zone, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_staff_blocked_time_v120(p_business uuid, p_branch uuid, p_staff uuid, p_starts timestamp with time zone, p_ends timestamp with time zone, p_reason text, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid:=auth.uid();
  v_timezone text;
  v_reason text:=nullif(btrim(coalesce(p_reason,'')),'');
  v_request_hash text;
  v_existing app.staff_blocked_time_operations_v120%rowtype;
  v_id uuid;
  v_response jsonb;
begin
  if v_actor is null or p_business is null or p_branch is null or p_staff is null
     or not app.can_module_write_at_v94(p_business,p_branch,'appointments') then
    raise exception 'permission denied' using errcode='42501';
  end if;
  if p_starts is null or p_ends is null or p_ends <= p_starts
     or p_ends > p_starts + interval '24 hours'
     or char_length(btrim(coalesce(p_reason,''))) > 160
     or p_idempotency_key is null
     or char_length(p_idempotency_key) not between 1 and 160 then
    raise exception 'invalid blocked time' using errcode='22023';
  end if;

  select branch.timezone into v_timezone
    from public.branches branch
   where branch.business_id=p_business and branch.id=p_branch and branch.active;
  if not found
     or (p_starts at time zone v_timezone)::date
        <> (p_ends at time zone v_timezone)::date then
    raise exception 'blocked time must stay within one active branch day'
      using errcode='22023';
  end if;

  if not exists (
    select 1
      from public.staff person
      join public.staff_branches assignment
        on assignment.business_id=person.business_id
       and assignment.staff_id=person.id
       and assignment.branch_id=p_branch
     where person.business_id=p_business and person.id=p_staff and person.active
  ) then
    raise exception 'staff is not active at this branch' using errcode='42501';
  end if;

  v_request_hash:=app.v41_request_hash(jsonb_build_object(
    'business_id',p_business,'branch_id',p_branch,'staff_id',p_staff,
    'starts_at',p_starts,'ends_at',p_ends,'reason',v_reason
  )::text);

  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    'v120:create:'||p_business::text||':'||v_actor::text||':'||p_idempotency_key,
    120
  ));

  select * into v_existing
    from app.staff_blocked_time_operations_v120 operation
   where operation.business_id=p_business and operation.actor=v_actor
     and operation.operation_type='create'
     and operation.idempotency_key=p_idempotency_key;
  if found then
    if v_existing.request_hash<>v_request_hash then
      raise exception 'idempotency key reused with different blocked time'
        using errcode='22023';
    end if;
    return v_existing.response||jsonb_build_object('replayed',true);
  end if;

  -- Every appointment mutation added below and every block creation takes this
  -- same lock. Different keys therefore cannot race an overlap check.
  perform app.lock_staff_calendar_v120(p_business,p_branch,p_staff);

  if exists (
    select 1 from public.staff_blocked_times blocked
     where blocked.business_id=p_business and blocked.staff_id=p_staff
       and blocked.starts_at < p_ends and blocked.ends_at > p_starts
  ) then
    raise exception 'this time is already blocked' using errcode='23P01';
  end if;

  if exists (
    select 1
      from public.appointments appointment
      left join public.services service
        on service.id=appointment.service_id
       and service.business_id=appointment.business_id
     where appointment.business_id=p_business
       and appointment.staff_id=p_staff and appointment.status='booked'
       and appointment.starts_at
           - make_interval(mins=>coalesce(service.buffer_before_min,0)) < p_ends
       and appointment.ends_at
           + make_interval(mins=>coalesce(service.buffer_after_min,0)) > p_starts
  ) then
    raise exception 'an appointment or its buffer already uses this time'
      using errcode='23P01';
  end if;

  insert into public.staff_blocked_times (
    business_id,branch_id,staff_id,starts_at,ends_at,reason,created_by
  ) values (
    p_business,p_branch,p_staff,p_starts,p_ends,v_reason,v_actor
  ) returning id into v_id;

  v_response:=jsonb_build_object(
    'status','created','replayed',false,'block_id',v_id
  );
  insert into app.staff_blocked_time_operations_v120 (
    business_id,actor,operation_type,idempotency_key,request_hash,response
  ) values (
    p_business,v_actor,'create',p_idempotency_key,v_request_hash,v_response
  );

  insert into public.audit_log (business_id,actor,action,entity,entity_id,detail)
  values (
    p_business,v_actor,'STAFF_TIME_BLOCK','staff_blocked_times',v_id,
    jsonb_build_object(
      'branch_id',p_branch,'staff_id',p_staff,
      'starts_at',p_starts,'ends_at',p_ends
    )
  );
  return v_response;
end
$$;

--
-- Name: create_staff_invite_v207(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_staff_invite_v207(p_business uuid, p_staff uuid, p_email text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_code text; v_row public.staff%rowtype; inv public.staff_invites%rowtype;
begin
  if not app.is_salon_owner(p_business) then
    raise exception 'owner access is required' using errcode='42501';
  end if;
  select * into v_row from public.staff where id=p_staff and business_id=p_business;
  if not found then
    raise exception 'that teammate is not in this business' using errcode='42501';
  end if;
  if v_row.user_id is not null then
    raise exception 'that teammate already has a login' using errcode='22023';
  end if;
  -- One live code per teammate: reissuing supersedes the old one rather than leaving two valid
  -- codes for the same person floating around.
  update public.staff_invites set status='revoked'
   where business_id=p_business and staff_id=p_staff and status='pending';
  loop
    v_code := upper(substr(md5(random()::text || clock_timestamp()::text),1,8));
    exit when not exists (select 1 from public.staff_invites where code=v_code);
  end loop;
  insert into public.staff_invites(business_id, role, email, code, staff_id)
  values (p_business, v_row.role, nullif(btrim(coalesce(p_email, v_row.email, '')),''), v_code, p_staff)
  returning * into inv;
  return jsonb_build_object('status','ok','code',inv.code,'staff_id',p_staff,
    'staff_name',v_row.full_name,'expires_at',inv.expires_at);
end
$$;

--
-- Name: create_staff_reference_code_v217(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_staff_reference_code_v217(p_business uuid, p_staff uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_staff public.staff%rowtype;
  v_code text;
  v_invite uuid;
  v_expires timestamptz := now() + interval '14 days';
begin
  if v_actor is null then
    raise exception 'authenticated staff required' using errcode='42501';
  end if;
  -- Granting app access is an owner/manager act, exactly like create_invite.
  if not (app.is_salon_owner(p_business) or app.has_perm(p_business,'manage_staff')) then
    raise exception 'staff reference code authorization required' using errcode='42501';
  end if;

  select * into v_staff from public.staff
  where id = p_staff and business_id = p_business
  for update;
  if not found then
    raise exception 'staff_member_not_found' using errcode='22023';
  end if;
  if v_staff.user_id is not null then
    raise exception 'staff_member_already_has_login' using errcode='22023';
  end if;
  if not coalesce(v_staff.active, true) then
    raise exception 'staff_member_inactive' using errcode='22023';
  end if;
  if v_staff.role = 'owner' then
    raise exception 'owner_is_not_invitable' using errcode='22023';
  end if;

  -- One live code per teammate. Re-issuing supersedes the previous one so an old slip of paper
  -- cannot still claim the same person after the owner has re-thought it.
  update public.staff_invites set status='revoked'
  where business_id = p_business and staff_id = p_staff and status = 'pending';

  -- Unambiguous alphabet: no O/0, no I/1, so a handwritten code is readable by someone who may
  -- not read English well. accept_invite upper-cases and strips spaces and dashes already.
  loop
    v_code := (select string_agg(substr('ABCDEFGHJKLMNPQRSTUVWXYZ23456789',
                (floor(random()*32)+1)::int, 1), '')
               from generate_series(1,8));
    exit when not exists(select 1 from public.staff_invites where code = v_code);
  end loop;

  insert into public.staff_invites(business_id, email, role, code, status, expires_at, staff_id)
  values (p_business, nullif(btrim(coalesce(v_staff.email,'')),''), v_staff.role, v_code,
          'pending', v_expires, p_staff)
  returning id into v_invite;

  insert into public.audit_log(business_id, actor, action, entity, entity_id, detail)
  values (p_business, v_actor, 'STAFF_REFERENCE_CODE_CREATED_V217', 'staff_invites', v_invite,
          jsonb_build_object('staff_id', p_staff, 'role', v_staff.role,
                             'staff_name', v_staff.full_name));

  return jsonb_build_object('status','ok','code',v_code,'invite_id',v_invite,
    'staff_id',p_staff,'staff_name',v_staff.full_name,'role',v_staff.role,
    'expires_at',v_expires,
    'restricted_to_email', nullif(btrim(coalesce(v_staff.email,'')),''));
end
$$;

--
-- Name: create_sv_plan_draft(uuid, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_sv_plan_draft(p_business uuid, p_config jsonb, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_id uuid := gen_random_uuid();
  v_plan uuid;
  v_hash text; v_hit jsonb;
  v_row public.sv_plan_drafts%rowtype;
begin
  if not app.is_salon_owner(p_business) then raise exception 'owner only' using errcode = '42501'; end if;
  perform app.sv_plan_assert_config(coalesce(p_config,'{}'::jsonb), true);
  v_hash := app.ps1b_sha256(jsonb_build_object('op','create_draft','business',p_business,'config',coalesce(p_config,'{}'::jsonb))::text);
  v_hit := app.sv_plan_idem_lookup(p_business, 'create_draft', p_idempotency_key, v_hash);
  if v_hit is not null then return v_hit; end if;

  if (p_config ? 'plan_id') and nullif(p_config->>'plan_id','') is not null then
    v_plan := (p_config->>'plan_id')::uuid;
    if not exists (select 1 from public.sv_plans s where s.id = v_plan and s.business_id = p_business) then
      raise exception 'stored-value plan does not belong to this business' using errcode = '22023';
    end if;
  end if;

  insert into public.sv_plan_drafts(id, business_id, plan_id, actor) values (v_id, p_business, v_plan, v_actor);
  perform app.sv_plan_apply_config(p_business, v_id, p_config - 'plan_id');
  select * into v_row from public.sv_plan_drafts where id = v_id and business_id = p_business;

  insert into public.sv_plan_operations(business_id, op_type, idempotency_key, request_hash, actor, result)
  values (p_business, 'create_draft', p_idempotency_key, v_hash, v_actor, app.sv_plan_draft_json(v_row));
  insert into public.audit_log(business_id, actor, action, entity, entity_id, detail)
  values (p_business, v_actor, 'SV_PLAN_DRAFT_CREATED', 'sv_plan_drafts', v_id, jsonb_build_object('plan_id', v_plan));
  return app.sv_plan_draft_json(v_row);
end $$;

--
-- Name: customer_activate_birthday_benefit(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_activate_birthday_benefit(p_business_slug text, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_context record; v_as_of timestamptz:=statement_timestamp(); v_program public.birthday_program_versions%rowtype;
  v_window record; v_entitlement public.customer_birthday_entitlements%rowtype;
  v_op public.customer_birthday_activation_operations%rowtype; v_request_hash text;
begin
  select * into v_context from app.c45_customer_birthday_context(p_business_slug) limit 1;
  if p_idempotency_key is null then raise exception 'birthday benefits are unavailable' using errcode='22023'; end if;
  v_request_hash:=app.c45_hash(jsonb_build_object('business_slug',lower(btrim(p_business_slug)))::text);
  select * into v_op from public.customer_birthday_activation_operations
   where identity_id=v_context.identity_id and business_id=v_context.business_id and idempotency_key=p_idempotency_key for share;
  if found then
    if v_op.request_hash is distinct from v_request_hash then raise exception 'birthday activation conflicts with an existing operation' using errcode='40001'; end if;
    select * into v_entitlement from public.customer_birthday_entitlements where id=v_op.entitlement_id;
    return app.c45_safe_birthday_entitlement(v_entitlement,v_as_of);
  end if;
  if not exists(select 1 from public.customer_birthday_participation p where p.identity_id=v_context.identity_id and p.auth_user_id=auth.uid() and p.opted_in) then
    raise exception 'birthday benefits are unavailable' using errcode='42501';
  end if;
  select bpv.* into v_program from public.businesses b
   join public.loyalty_program_versions lpv on lpv.config_version_id=b.active_config_version_id and lpv.business_id=b.id and lpv.active
   join public.birthday_program_versions bpv on bpv.config_version_id=b.active_config_version_id and bpv.business_id=b.id and bpv.active
   where b.id=v_context.business_id and 'loyalty'=any(coalesce(b.enabled_modules,'{}'::text[]))
   order by bpv.sort,bpv.program_id limit 1 for update of bpv;
  if not found then raise exception 'birthday benefits are unavailable' using errcode='42501'; end if;
  select * into v_window from app.c45_birthday_window(v_context.birth_date,v_program.window_days_before,v_program.window_days_after,v_as_of);
  if not found then raise exception 'birthday benefits are unavailable' using errcode='42501'; end if;
  select * into v_entitlement from public.customer_birthday_entitlements
   where business_id=v_context.business_id and client_id=v_context.client_id and birthday_year=v_window.birthday_year for update;
  if found then
    insert into public.customer_birthday_activation_operations(identity_id,business_id,client_id,idempotency_key,request_hash,entitlement_id)
    values(v_context.identity_id,v_context.business_id,v_context.client_id,p_idempotency_key,v_request_hash,v_entitlement.id);
    return app.c45_safe_birthday_entitlement(v_entitlement,v_as_of);
  end if;
  insert into public.customer_birthday_entitlements(
    business_id,client_id,identity_id,config_version_id,birthday_program_version_id,birthday_year,
    status,valid_from,valid_until,benefit_snapshot
  ) values(
    v_context.business_id,v_context.client_id,v_context.identity_id,v_program.config_version_id,v_program.id,v_window.birthday_year,
    'available',v_window.valid_from,v_window.valid_until,app.c45_benefit_snapshot(v_program)
  ) returning * into v_entitlement;
  insert into public.customer_birthday_activation_operations(identity_id,business_id,client_id,idempotency_key,request_hash,entitlement_id)
  values(v_context.identity_id,v_context.business_id,v_context.client_id,p_idempotency_key,v_request_hash,v_entitlement.id);
  insert into public.audit_log(business_id,actor,action,entity,entity_id,detail)
  values(v_context.business_id,auth.uid(),'ACTIVATE_BIRTHDAY_BENEFIT','customer_birthday_entitlements',v_entitlement.id,jsonb_build_object('status','available'));
  return app.c45_safe_birthday_entitlement(v_entitlement,v_as_of);
exception when unique_violation then
  -- The per-customer/year uniqueness is the re-publish and concurrent-activate
  -- backstop. A caller retries through the same idempotency key for the exact
  -- immutable promise; changed inputs fail through the hash check above.
  select * into v_entitlement from public.customer_birthday_entitlements
   where business_id=v_context.business_id and client_id=v_context.client_id and birthday_year=v_window.birthday_year;
  if v_entitlement.id is null then raise; end if;
  insert into public.customer_birthday_activation_operations(identity_id,business_id,client_id,idempotency_key,request_hash,entitlement_id)
  values(v_context.identity_id,v_context.business_id,v_context.client_id,p_idempotency_key,v_request_hash,v_entitlement.id)
  on conflict (identity_id,business_id,idempotency_key) do nothing;
  return app.c45_safe_birthday_entitlement(v_entitlement,v_as_of);
end $$;

--
-- Name: customer_cancel_redemption_intent_v89(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_cancel_redemption_intent_v89(p_intent uuid, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_identity uuid:=app.v31_current_identity();
  v_intent public.customer_redemption_intents_v89%rowtype;
  v_status text;
begin
  if p_idempotency_key is null then
    raise exception 'idempotency key is required' using errcode='22023';
  end if;
  select * into v_intent from public.customer_redemption_intents_v89 intent
  where intent.id=p_intent and intent.identity_id=v_identity
    and intent.auth_user_id=auth.uid() for update;
  if not found then
    raise exception 'redemption intent was not found' using errcode='42501';
  end if;
  if v_intent.status='completed' then
    raise exception 'completed redemption cannot be cancelled' using errcode='23514';
  end if;
  v_status:=case when v_intent.status='pending' and v_intent.expires_at<=now()
    then 'expired' else v_intent.status end;
  if v_status='expired' and v_intent.status='pending' then
    perform set_config('app.v89_redemption_intent_id',v_intent.id::text,true);
    update public.customer_redemption_intents_v89 set status='expired'
      where id=v_intent.id;
    perform set_config('app.v89_redemption_intent_id','',true);
    insert into public.customer_redemption_events_v89(
      intent_id,business_id,actor,event_type,idempotency_key,detail
    ) values(v_intent.id,v_intent.business_id,auth.uid(),'intent_expired',
      p_idempotency_key,jsonb_build_object('expired_at',v_intent.expires_at))
    on conflict(intent_id,event_type,idempotency_key) do nothing;
  elsif v_status='pending' then
    perform set_config('app.v89_redemption_intent_id',v_intent.id::text,true);
    update public.customer_redemption_intents_v89 set status='cancelled'
      where id=v_intent.id;
    perform set_config('app.v89_redemption_intent_id','',true);
    insert into public.customer_redemption_events_v89(
      intent_id,business_id,actor,event_type,idempotency_key,detail
    ) values(v_intent.id,v_intent.business_id,auth.uid(),'intent_cancelled',
      p_idempotency_key,'{}'::jsonb)
    on conflict(intent_id,event_type,idempotency_key) do nothing;
    v_status:='cancelled';
  end if;
  return jsonb_build_object('intent_id',v_intent.id,'status',v_status,
    'expires_at',v_intent.expires_at);
end
$$;

--
-- Name: customer_claim_link_by_email(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_claim_link_by_email(p_business_slug text, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_identity uuid;
  v_slug text := lower(btrim(coalesce(p_business_slug, '')));
  v_email text;
  v_email_confirmed_at timestamptz;
  v_business uuid;
  v_existing public.customer_link_claim_attempts%rowtype;
  v_link_id uuid;
  v_client_id uuid;
  v_candidate_ids uuid[];
  v_candidate_count integer := 0;
  v_request_hash text;
  v_outcome text;
  v_response jsonb;
  v_event_type text;
begin
  if not app.platform_feature_enabled('customer_claims') then
    raise exception 'customer access is unavailable' using errcode = '0A000';
  end if;
  v_identity := app.v31_current_identity();
  if p_idempotency_key is null or length(btrim(p_idempotency_key)) < 8 then
    raise exception 'idempotency key must contain at least 8 characters' using errcode = '22023';
  end if;
  p_idempotency_key := btrim(p_idempotency_key);
  v_request_hash := app.v31_sha256_hex('v31.email_claim:' || v_slug);
  perform pg_advisory_xact_lock(hashtextextended(
    'v31:email-claim:' || v_identity::text || ':' || p_idempotency_key, 0
  ));

  select * into v_existing
    from public.customer_link_claim_attempts a
   where a.identity_id = v_identity and a.operation = 'email_claim'
     and a.idempotency_key = p_idempotency_key;
  if found then
    if v_existing.request_hash is distinct from v_request_hash then
      raise exception 'idempotency key was already used for another claim request' using errcode = '22023';
    end if;
    return v_existing.response;
  end if;

  -- Exactly one normalized candidate is required. Duplicate or ambiguous legacy
  -- records receive the same generic response as an unavailable relationship.
  if (select count(*) from public.customer_link_claim_attempts a
       where a.identity_id = v_identity and a.operation = 'email_claim'
         and a.created_at >= now() - interval '15 minutes'
         and a.outcome <> 'rate_limited') >= 5 then
    v_outcome := 'rate_limited';
    v_response := jsonb_build_object('outcome', 'try_later', 'retry_after_seconds', 900);
    v_event_type := 'email_claim_rate_limited';
  else
    select u.email, u.email_confirmed_at into v_email, v_email_confirmed_at
      from auth.users u where u.id = v_actor for share;
    select b.id into v_business from public.businesses b where b.slug = v_slug for share;

    if v_email_confirmed_at is null or nullif(btrim(v_email), '') is null or v_business is null then
      v_outcome := 'not_linked';
      v_response := jsonb_build_object('outcome', 'no_link_created');
      v_event_type := 'email_claim_not_linked';
    else
      perform pg_advisory_xact_lock(hashtextextended('v31:business-link:' || v_business::text, 0));
      select l.id, l.client_id into v_link_id, v_client_id from public.customer_links l
       where l.identity_id = v_identity and l.business_id = v_business and l.state = 'verified'
       for update;
      if found then
        v_outcome := 'linked';
        v_response := jsonb_build_object('outcome', 'linked');
        v_event_type := 'email_claim_linked';
      else
        select coalesce(array_agg(c.id order by c.id), '{}'::uuid[]), count(*)::integer
          into v_candidate_ids, v_candidate_count
          from public.clients c
         where c.business_id = v_business
           and lower(btrim(coalesce(c.email, ''))) = lower(btrim(v_email))
           and nullif(btrim(c.email), '') is not null
           and not exists (
             select 1 from public.customer_links linked
              where linked.client_id = c.id and linked.state = 'verified'
           );
        if v_candidate_count = 1 then
          v_link_id := gen_random_uuid();
          v_client_id := v_candidate_ids[1];
          perform set_config('app.customer_link_insert_id', v_link_id::text, true);
          insert into public.customer_links (
            id, business_id, identity_id, auth_user_id, client_id, state,
            verification_method, verified_at
          ) values (
            v_link_id, v_business, v_identity, v_actor, v_candidate_ids[1], 'verified',
            'email_claim', now()
          );
          perform set_config('app.customer_link_insert_id', '', true);
          v_outcome := 'linked';
          v_response := jsonb_build_object('outcome', 'linked');
          v_event_type := 'email_claim_linked';
        else
          v_outcome := 'not_linked';
          v_response := jsonb_build_object('outcome', 'no_link_created');
          v_event_type := 'email_claim_not_linked';
        end if;
      end if;
    end if;
  end if;

  insert into public.customer_link_claim_attempts (
    identity_id, auth_user_id, business_id, link_id, operation, idempotency_key,
    request_hash, outcome, response
  ) values (
    v_identity, v_actor, v_business, v_link_id, 'email_claim', p_idempotency_key,
    v_request_hash, v_outcome, v_response
  );
  insert into public.customer_link_audit_events (
    identity_id, actor_auth_user_id, business_id, client_id, link_id, event_type,
    idempotency_key, request_hash, response
  ) values (
    v_identity, v_actor, v_business, v_client_id, v_link_id, v_event_type,
    p_idempotency_key, v_request_hash, v_response
  );
  return v_response;
end;
$$;

--
-- Name: customer_claim_link_by_verified_phone(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_claim_link_by_verified_phone(p_business_slug text, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_identity uuid;
  v_slug text := lower(btrim(coalesce(p_business_slug, '')));
  v_phone text;
  v_phone_confirmed_at timestamptz;
  v_phone_norm text;
  v_business uuid;
  v_link_id uuid;
  v_client_id uuid;
  v_candidate_ids uuid[];
  v_candidate_count integer := 0;
  v_existing public.customer_link_claim_attempts%rowtype;
  v_request_hash text;
  v_outcome text;
  v_event_type text;
  v_response jsonb;
begin
  if not app.platform_feature_enabled('customer_claims')
     or not app.platform_feature_enabled('customer_phone_claims')
     or not app.platform_feature_enabled('customer_phone_registration') then
    raise exception 'customer access is unavailable' using errcode = '0A000';
  end if;
  v_identity := app.v31_current_identity();
  if p_idempotency_key is null or length(btrim(p_idempotency_key)) < 8
     or length(v_slug) < 2 or length(v_slug) > 160 then
    raise exception 'invalid customer claim request' using errcode = '22023';
  end if;
  p_idempotency_key := btrim(p_idempotency_key);
  v_request_hash := app.v31_sha256_hex('c42.phone-claim:' || v_slug);
  perform pg_advisory_xact_lock(hashtextextended(
    'c42:phone-claim:' || v_identity::text || ':' || p_idempotency_key, 0
  ));
  select * into v_existing from public.customer_link_claim_attempts a
   where a.identity_id = v_identity and a.operation = 'phone_claim'
     and a.idempotency_key = p_idempotency_key for update;
  if found then
    if v_existing.request_hash is distinct from v_request_hash then
      raise exception 'idempotency key was already used for another claim request' using errcode = '23505';
    end if;
    return v_existing.response;
  end if;

  perform pg_advisory_xact_lock(hashtextextended('c42:phone-claim-rate:' || v_identity::text, 0));
  if (select count(*) from public.customer_link_claim_attempts a
       where a.identity_id = v_identity and a.operation = 'phone_claim'
         and a.created_at >= now() - interval '15 minutes'
         and a.outcome <> 'rate_limited') >= 5 then
    v_outcome := 'rate_limited';
    v_response := jsonb_build_object('outcome', 'try_later', 'retry_after_seconds', 900);
    v_event_type := 'phone_claim_rate_limited';
  else
    select u.phone, u.phone_confirmed_at into v_phone, v_phone_confirmed_at
      from auth.users u where u.id = v_actor for share;
    v_phone_norm := app.norm_phone(v_phone);
    select b.id into v_business from public.businesses b where b.slug = v_slug for share;
    if v_phone_confirmed_at is null or v_phone_norm is null or v_business is null then
      v_outcome := 'not_linked';
      v_response := jsonb_build_object('outcome', 'no_link_created');
      v_event_type := 'phone_claim_not_linked';
    else
      perform pg_advisory_xact_lock(hashtextextended('c42:phone-business-link:' || v_business::text, 0));
      select l.id, l.client_id into v_link_id, v_client_id from public.customer_links l
       where l.identity_id = v_identity and l.business_id = v_business and l.state = 'verified'
       for update;
      if found then
        v_outcome := 'linked';
        v_response := jsonb_build_object('outcome', 'linked');
        v_event_type := 'phone_claim_linked';
      else
        -- Exact one unclaimed record only. Any historical link is retained as
        -- evidence and requires controlled recovery rather than reassignment.
        select coalesce(array_agg(c.id order by c.id), '{}'::uuid[]), count(*)::integer
          into v_candidate_ids, v_candidate_count
          from public.clients c
         where c.business_id = v_business and c.phone_norm = v_phone_norm
           and c.phone_norm is not null
           and not exists (select 1 from public.customer_links prior where prior.client_id = c.id);
        if v_candidate_count = 1 then
          v_link_id := gen_random_uuid();
          v_client_id := v_candidate_ids[1];
          perform set_config('app.customer_link_insert_id', v_link_id::text, true);
          insert into public.customer_links (
            id, business_id, identity_id, auth_user_id, client_id, state, verification_method, verified_at
          ) values (
            v_link_id, v_business, v_identity, v_actor, v_client_id, 'verified', 'phone_claim', now()
          );
          perform set_config('app.customer_link_insert_id', '', true);
          v_outcome := 'linked';
          v_response := jsonb_build_object('outcome', 'linked');
          v_event_type := 'phone_claim_linked';
        else
          v_outcome := 'not_linked';
          v_response := jsonb_build_object('outcome', 'no_link_created');
          v_event_type := 'phone_claim_not_linked';
        end if;
      end if;
    end if;
  end if;

  insert into public.customer_link_claim_attempts (
    identity_id, auth_user_id, business_id, link_id, operation, idempotency_key, request_hash, outcome, response
  ) values (
    v_identity, v_actor, v_business, v_link_id, 'phone_claim', p_idempotency_key,
    v_request_hash, v_outcome, v_response
  );
  insert into public.customer_link_audit_events (
    identity_id, actor_auth_user_id, business_id, client_id, link_id, event_type,
    idempotency_key, request_hash, response
  ) values (
    v_identity, v_actor, v_business, v_client_id, v_link_id, v_event_type,
    p_idempotency_key, v_request_hash, v_response
  );
  return v_response;
end;
$$;

--
-- Name: customer_claim_link_invitation(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_claim_link_invitation(p_token text, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_identity uuid;
  v_token_hash text := app.v31_sha256_hex(coalesce(p_token, ''));
  v_request_hash text := app.v31_sha256_hex('v31.invitation_claim:' || coalesce(p_token, ''));
  v_existing public.customer_link_claim_attempts%rowtype;
  v_invite public.customer_link_invitations%rowtype;
  v_link_id uuid;
  v_outcome text;
  v_response jsonb;
  v_event_type text;
  v_auth_email text;
  v_email_confirmed_at timestamptz;
begin
  if not app.platform_feature_enabled('customer_claims') then
    raise exception 'customer access is unavailable' using errcode = '0A000';
  end if;
  v_identity := app.v31_current_identity();
  if p_idempotency_key is null or length(btrim(p_idempotency_key)) < 8 then
    raise exception 'idempotency key must contain at least 8 characters' using errcode = '22023';
  end if;
  p_idempotency_key := btrim(p_idempotency_key);
  perform pg_advisory_xact_lock(hashtextextended(
    'v31:invitation-claim:' || v_identity::text || ':' || p_idempotency_key, 0
  ));
  select * into v_existing from public.customer_link_claim_attempts a
   where a.identity_id = v_identity and a.operation = 'invitation_claim'
     and a.idempotency_key = p_idempotency_key;
  if found then
    if v_existing.request_hash is distinct from v_request_hash then
      raise exception 'idempotency key was already used for another invitation claim' using errcode = '22023';
    end if;
    return v_existing.response;
  end if;

  if (select count(*) from public.customer_link_claim_attempts a
       where a.identity_id = v_identity and a.operation = 'invitation_claim'
         and a.created_at >= now() - interval '15 minutes'
         and a.outcome <> 'rate_limited') >= 5 then
    v_outcome := 'rate_limited';
    v_response := jsonb_build_object('outcome', 'try_later', 'retry_after_seconds', 900);
    v_event_type := 'invitation_claim_rate_limited';
  else
    select lower(btrim(u.email)), u.email_confirmed_at
      into v_auth_email, v_email_confirmed_at
      from auth.users u where u.id = v_actor for share;
    select * into v_invite from public.customer_link_invitations i
     where i.token_hash = v_token_hash for update;
    if found then
      perform pg_advisory_xact_lock(hashtextextended('v31:business-link:' || v_invite.business_id::text, 0));
      if v_invite.state = 'claimed' and v_invite.claimed_by_identity_id = v_identity then
        v_link_id := v_invite.claimed_link_id;
        v_outcome := 'linked';
        v_response := jsonb_build_object('outcome', 'linked');
        v_event_type := 'invitation_claim_linked';
      elsif v_invite.state = 'issued' and v_invite.expires_at > now()
        and v_email_confirmed_at is not null
        and v_invite.recipient_email_hash = app.v31_sha256_hex(
          'v31.invitation-email:' || coalesce(v_auth_email, '')
        )
        and not exists (
          select 1 from public.customer_links l
           where l.identity_id = v_identity and l.business_id = v_invite.business_id and l.state = 'verified'
        )
        and not exists (
          select 1 from public.customer_links l
           where l.client_id = v_invite.client_id and l.state = 'verified'
        ) then
        v_link_id := gen_random_uuid();
        perform set_config('app.customer_link_insert_id', v_link_id::text, true);
        insert into public.customer_links (
          id, business_id, identity_id, auth_user_id, client_id, state,
          verification_method, verified_at
        ) values (
          v_link_id, v_invite.business_id, v_identity, v_actor, v_invite.client_id,
          'verified', 'firm_invitation', now()
        );
        perform set_config('app.customer_link_insert_id', '', true);
        perform set_config('app.customer_link_invitation_claim_id', v_invite.id::text, true);
        update public.customer_link_invitations
           set state = 'claimed', claimed_at = now(), claimed_by_identity_id = v_identity,
               claimed_link_id = v_link_id
         where id = v_invite.id;
        perform set_config('app.customer_link_invitation_claim_id', '', true);
        v_outcome := 'linked';
        v_response := jsonb_build_object('outcome', 'linked');
        v_event_type := 'invitation_claim_linked';
      else
        v_outcome := 'not_linked';
        v_response := jsonb_build_object('outcome', 'no_link_created');
        v_event_type := 'invitation_claim_not_linked';
      end if;
    else
      v_outcome := 'not_linked';
      v_response := jsonb_build_object('outcome', 'no_link_created');
      v_event_type := 'invitation_claim_not_linked';
    end if;
  end if;

  insert into public.customer_link_claim_attempts (
    identity_id, auth_user_id, business_id, link_id, operation, idempotency_key,
    request_hash, outcome, response
  ) values (
    v_identity, v_actor, v_invite.business_id, v_link_id, 'invitation_claim',
    p_idempotency_key, v_request_hash, v_outcome, v_response
  );
  insert into public.customer_link_audit_events (
    identity_id, actor_auth_user_id, business_id, client_id, link_id, invitation_id,
    event_type, idempotency_key, request_hash, response
  ) values (
    v_identity, v_actor, v_invite.business_id, v_invite.client_id, v_link_id, v_invite.id,
    v_event_type, p_idempotency_key, v_request_hash, v_response
  );
  return v_response;
end;
$$;

--
-- Name: customer_create_identity(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_create_identity(p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_identity public.customer_identities%rowtype;
  v_email_confirmed_at timestamptz;
  v_proof_id uuid;
  v_created boolean := false;
  v_existing_hash text;
  v_request_hash text := md5('customer_create_identity:v1');
  v_response jsonb;
begin
  if v_actor is null then
    raise exception 'authenticated customer session required' using errcode = '28000';
  end if;
  if not app.platform_feature_enabled('customer_identity') then
    raise exception 'customer access is unavailable' using errcode = '0A000';
  end if;
  if p_idempotency_key is null or length(btrim(p_idempotency_key)) < 8 then
    raise exception 'idempotency key must contain at least 8 characters' using errcode = '22023';
  end if;
  p_idempotency_key := btrim(p_idempotency_key);

  select u.email_confirmed_at
    into v_email_confirmed_at
    from auth.users u
   where u.id = v_actor
   for share;
  if not found then
    raise exception 'authenticated user no longer exists' using errcode = '28000';
  end if;
  if v_email_confirmed_at is null or not exists (
    select 1 from auth.users u
     where u.id = v_actor and nullif(btrim(u.email), '') is not null
  ) then
    raise exception 'a verified email is required to create a customer identity'
      using errcode = '42501';
  end if;

  insert into public.customer_identities (auth_user_id)
  values (v_actor)
  on conflict (auth_user_id) do nothing
  returning * into v_identity;
  v_created := found;

  if not v_created then
    select * into v_identity
      from public.customer_identities
     where auth_user_id = v_actor;
  end if;

  -- An identity is platform-scoped. This proof is for the authenticated email
  -- only; it creates no client relationship. Phone proof is deferred from v30.
  select a.request_hash, a.response into v_existing_hash, v_response
    from public.customer_identity_audit_events a
   where a.identity_id = v_identity.id
     and a.event_type = 'identity_created'
     and a.idempotency_key = p_idempotency_key;
  if v_existing_hash is not null and v_existing_hash <> v_request_hash then
    raise exception 'idempotency key was already used for another request'
      using errcode = '22023';
  end if;
  if v_response is not null then
    return v_response;
  end if;

  if v_created then
    insert into public.customer_contact_proofs (
      identity_id, auth_user_id, contact_type, proof_method, status,
      issued_at, expires_at, verified_at
    ) values (
      v_identity.id, v_actor, 'email', 'auth_email_confirmation', 'verified',
      now(), now() + interval '15 minutes', now()
    ) returning id into v_proof_id;

    insert into public.customer_verified_contacts (
      identity_id, auth_user_id, contact_type, verification_proof_id
    ) values (v_identity.id, v_actor, 'email', v_proof_id);

    v_response := jsonb_build_object(
      'identity_id', v_identity.id, 'status', v_identity.status,
      'created_at', v_identity.created_at, 'created', true
    );
    insert into public.customer_identity_audit_events (
      identity_id, actor_auth_user_id, event_type, idempotency_key, request_hash, response
    ) values (
      v_identity.id, v_actor, 'identity_created', p_idempotency_key, v_request_hash, v_response
    );
  end if;

  return coalesce(v_response, jsonb_build_object(
    'identity_id', v_identity.id,
    'status', v_identity.status,
    'created_at', v_identity.created_at,
    'created', v_created
  ));
end;
$$;

--
-- Name: customer_create_promotion_intent_v290(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_create_promotion_intent_v290(p_business uuid, p_promotion uuid, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_identity uuid;
  v_client uuid;
  v_promotion public.business_customer_content_v95%rowtype;
  v_existing public.promotion_redemption_intents_v290%rowtype;
  v_open public.promotion_redemption_intents_v290%rowtype;
  v_limit integer;
  v_used integer;
  v_token text;
  v_request_hash text;
  v_expires timestamptz := now() + interval '5 minutes';
  v_intent uuid := gen_random_uuid();
begin
  if p_idempotency_key is null or p_business is null or p_promotion is null then
    raise exception 'business, promotion and idempotency key are required' using errcode = '22023';
  end if;
  v_identity := app.v31_current_identity();
  v_request_hash := app.v89_sha256(p_business::text||':promotion:'||p_promotion::text);

  perform pg_advisory_xact_lock(hashtextextended(
    'v290:promotion-intent:'||v_identity::text||':'||p_idempotency_key::text,0));

  select * into v_existing from public.promotion_redemption_intents_v290 intent
   where intent.identity_id = v_identity and intent.idempotency_key = p_idempotency_key
   for update;
  if found then
    if v_existing.request_hash <> v_request_hash then
      raise exception 'idempotency key conflicts with another promotion intent'
        using errcode = '23505';
    end if;
    return jsonb_build_object('status',v_existing.status,'intent_id',v_existing.id,
      'promotion_id',v_existing.promotion_id,'expires_at',v_existing.expires_at,
      'qr_token',app.v89_redemption_token(v_identity,p_business,'promotion_v290',
        v_existing.promotion_id,p_idempotency_key),
      'replayed',true);
  end if;

  select link.client_id into v_client
    from public.customer_links link
   where link.identity_id = v_identity and link.auth_user_id = auth.uid()
     and link.business_id = p_business and link.state = 'verified'
   for share;
  if not found then
    raise exception 'verified customer link required' using errcode = '42501';
  end if;

  select * into v_promotion from public.business_customer_content_v95 content
   where content.id = p_promotion
     and content.business_id = p_business
     and content.content_type = 'offer'
     and content.active
     and content.branch_id is null
     and (content.starts_at is null or content.starts_at <= now())
     and content.ends_at > now();
  if not found then
    raise exception 'this offer is not available' using errcode = '22023';
  end if;

  -- usage_limit is optional promotion metadata, not a column: the offer editor writes a free
  -- jsonb, so a firm that sets one gets it enforced per customer and one that does not is
  -- unaffected. A non-numeric value is ignored rather than treated as zero.
  v_limit := nullif(regexp_replace(coalesce(v_promotion.metadata->>'usage_limit',''),
    '[^0-9]','','g'),'')::integer;
  if v_limit is not null and v_limit > 0 then
    select count(*)::integer into v_used
      from public.promotion_redemptions_v290 used
     where used.business_id = p_business
       and used.promotion_id = p_promotion
       and used.client_id = v_client;
    if v_used >= v_limit then
      raise exception 'offer usage limit reached' using errcode = '23514';
    end if;
  end if;

  -- One live intent per promotion per customer. An earlier one that has run out of time is
  -- retired here rather than blocking the customer forever.
  update public.promotion_redemption_intents_v290 stale
     set status = 'expired'
   where stale.business_id = p_business
     and stale.promotion_id = p_promotion
     and stale.client_id = v_client
     and stale.status = 'pending'
     and stale.expires_at <= now();
  select * into v_open from public.promotion_redemption_intents_v290 intent
   where intent.business_id = p_business
     and intent.promotion_id = p_promotion
     and intent.client_id = v_client
     and intent.status = 'pending';
  if found then
    return jsonb_build_object('status','pending','intent_id',v_open.id,
      'promotion_id',v_open.promotion_id,'expires_at',v_open.expires_at,
      'qr_token',app.v89_redemption_token(v_identity,p_business,'promotion_v290',
        v_open.promotion_id,v_open.idempotency_key),
      'replayed',true);
  end if;

  v_token := app.v89_redemption_token(
    v_identity,p_business,'promotion_v290',p_promotion,p_idempotency_key);

  insert into public.promotion_redemption_intents_v290(
    id,business_id,promotion_id,identity_id,auth_user_id,client_id,
    token_hash,idempotency_key,request_hash,expires_at
  ) values (
    v_intent,p_business,p_promotion,v_identity,auth.uid(),v_client,
    app.v89_sha256(v_token),p_idempotency_key,v_request_hash,v_expires
  );

  return jsonb_build_object('status','pending','intent_id',v_intent,
    'promotion_id',p_promotion,'expires_at',v_expires,'qr_token',v_token,'replayed',false);
end;
$$;

--
-- Name: customer_create_redemption_intent_v89(uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_create_redemption_intent_v89(p_business uuid, p_reward uuid, p_idempotency_key uuid, p_redemption_kind text DEFAULT 'catalog_reward'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'extensions', 'pg_temp'
    AS $$
declare
  v_identity uuid;v_client uuid;v_reward public.loyalty_rewards%rowtype;
  v_program public.loyalty_programs%rowtype;
  v_reward_version public.loyalty_reward_versions%rowtype;
  v_existing public.customer_redemption_intents_v89%rowtype;
  v_token text;v_hash text;v_request_hash text;
  v_quote jsonb;
  v_balance integer;v_batch_balance integer;v_cost_points integer;
  v_kind text:=lower(btrim(coalesce(p_redemption_kind,'')));
  v_intent uuid:=gen_random_uuid();
  v_expires timestamptz:=now()+interval '5 minutes';v_response jsonb;
  v_intent_programme uuid;
  v_intent_programme_kind text;
  v_stamp_filled integer;
  v_stamp_cycle integer;
begin
  if p_idempotency_key is null then
    raise exception 'idempotency key is required' using errcode='22023';
  end if;
  if v_kind not in ('classic_points','catalog_reward') then
    raise exception 'unsupported redemption kind' using errcode='22023';
  end if;
  if (v_kind='classic_points' and p_reward is not null)
     or (v_kind='catalog_reward' and p_reward is null) then
    raise exception 'redemption kind and reward do not match' using errcode='22023';
  end if;
  if not app.platform_feature_enabled('customer_qr_redemption') then
    raise exception 'customer QR redemption is unavailable' using errcode='0A000';
  end if;
  -- v229: this firm uses points for tier membership, not redemption. Refused here, before
  -- identity resolution, so the rule holds for every caller.
  if not exists(select 1 from public.business_programmes spine
             where spine.business_id=p_business and spine.active
               and spine.kind in ('points','stamps')) then
    raise exception 'this business is not running a programme you can redeem from'
      using errcode='0A000';
  end if;
  v_identity:=app.v31_current_identity();
  v_request_hash:=app.v89_sha256(p_business::text||':'||v_kind||':'||
    coalesce(p_reward::text,'classic'));
  perform pg_advisory_xact_lock(hashtextextended(
    'v89:redemption-intent:'||v_identity::text||':'||p_idempotency_key::text,0));
  select * into v_existing from public.customer_redemption_intents_v89 intent
  where intent.identity_id=v_identity and intent.idempotency_key=p_idempotency_key
  for update;
  if found then
    if v_existing.request_hash<>v_request_hash then
      raise exception 'idempotency key conflicts with another redemption intent'
        using errcode='23505';
    end if;
    return jsonb_build_object('intent_id',v_existing.id,'status',v_existing.status,
      'redemption_kind',v_existing.redemption_kind,
      'qr_token',app.v89_redemption_token(v_identity,p_business,
        v_existing.redemption_kind,v_existing.reward_id,p_idempotency_key),
      'expires_at',v_existing.expires_at,'replayed',true);
  end if;
  if not coalesce((select capability.redemption_enabled
    from public.business_customer_capabilities_v89 capability
    where capability.business_id=p_business),false)
     or not app.v89_business_module_enabled(p_business,'loyalty') then
    raise exception 'customer redemption is disabled for this business'
      using errcode='42501';
  end if;
  select link.client_id into v_client from public.customer_links link
  where link.identity_id=v_identity and link.auth_user_id=auth.uid()
    and link.business_id=p_business and link.state='verified' for share;
  if not found then raise exception 'verified customer link required' using errcode='42501';end if;
  select * into v_program from public.loyalty_programs program
  where program.business_id=p_business and program.active order by program.id limit 1;
  if not found then raise exception 'loyalty redemption is unavailable' using errcode='22023';end if;
  if v_kind='classic_points' then
    if v_program.kind<>'points' or v_program.loyalty_model<>'classic'
       or v_program.redeem_points<=0 or v_program.reward_credit_cents<=0 then
      raise exception 'classic points redemption is unavailable' using errcode='22023';
    end if;
    v_cost_points:=v_program.redeem_points;
    v_quote:=jsonb_build_object(
      'program_id',v_program.id,
      'config_version_id',v_program.current_config_version_id,
      'loyalty_model',v_program.loyalty_model,'kind',v_program.kind,
      'points_spent',v_program.redeem_points,
      'credit_cents',v_program.reward_credit_cents);
  else
    if not exists(select 1 from public.business_programmes spine
                   where spine.business_id=p_business and spine.active
                     and spine.kind in ('points','stamps')) then
      raise exception 'catalog redemption is unavailable' using errcode='22023';
    end if;
    select * into v_reward from public.loyalty_rewards reward
    where reward.id=p_reward and reward.business_id=p_business and reward.active and not reward.paused;
    if not found then
      raise exception 'reward is unavailable' using errcode='22023';
    end if;
    select reward_version.* into v_reward_version
    from public.loyalty_reward_versions reward_version
    join public.businesses business on business.id=reward_version.business_id
    where reward_version.reward_id=p_reward
      and reward_version.business_id=p_business
      and reward_version.config_version_id=business.active_config_version_id
      and reward_version.active;
    if not found
       or (v_reward_version.claim_available_from is not null
         and v_reward_version.claim_available_from>now())
       or (v_reward_version.claim_available_until is not null
         and v_reward_version.claim_available_until<=now()) then
      raise exception 'reward is unavailable' using errcode='22023';
    end if;
    if exists(select 1 from public.loyalty_reward_branches restriction
         where restriction.reward_version_id=v_reward_version.id)
       or exists(select 1 from public.loyalty_reward_services restriction
         where restriction.reward_version_id=v_reward_version.id)
       or exists(select 1 from public.loyalty_reward_products restriction
         where restriction.reward_version_id=v_reward_version.id) then
      raise exception 'context-restricted rewards require staff-assisted redemption'
        using errcode='22023';
    end if;
    if v_reward_version.usage_limit is not null and (
      select count(*) from public.loyalty_redemptions redemption
      where redemption.business_id=p_business
        and redemption.client_id=v_client and redemption.reward_id=p_reward
    )>=v_reward_version.usage_limit then
      raise exception 'reward usage limit reached' using errcode='23514';
    end if;
    v_cost_points:=v_reward_version.cost_points;
    v_quote:=jsonb_build_object(
      'program_id',v_program.id,
      'config_version_id',v_reward_version.config_version_id,
      'reward_version_id',v_reward_version.id,'reward_id',p_reward,
      'points_spent',v_reward_version.cost_points,
      'credit_cents',v_reward_version.credit_cents,
      'fulfillment_kind',v_reward_version.fulfillment_kind,
      'claim_available_from',v_reward_version.claim_available_from,
      'claim_available_until',v_reward_version.claim_available_until,
      'usage_limit',v_reward_version.usage_limit,
      'active',v_reward_version.active);
  end if;
  v_intent_programme:=case when v_kind='catalog_reward' then v_reward_version.programme_id
    else (select spine.id from public.business_programmes spine
           where spine.business_id=p_business and spine.kind='points') end;
  if v_intent_programme is null then
    raise exception 'redemption programme is not resolvable for this business' using errcode='XX001';
  end if;
  if not exists(select 1 from public.business_programmes spine
                 where spine.id=v_intent_programme and spine.active) then
    raise exception 'this reward''s programme is not running right now' using errcode='0A000';
  end if;
  select spine.kind into v_intent_programme_kind from public.business_programmes spine
   where spine.id=v_intent_programme;
  if v_intent_programme_kind='stamps' then
    select sp.filled,sp.cycle_index into v_stamp_filled,v_stamp_cycle
      from app.stamp_progress_v323(p_business,v_client) sp;
    if not found then
      raise exception 'this business is not running a stamp card' using errcode='23514';
    end if;
    if coalesce(v_stamp_filled,0)<v_cost_points then
      raise exception 'not enough stamps yet' using errcode='23514';
    end if;
    if exists(select 1 from public.stamp_milestone_claims claim
               where claim.business_id=p_business and claim.client_id=v_client
                 and claim.programme_id=v_intent_programme
                 and claim.cycle_index=v_stamp_cycle
                 and (claim.slot_position=v_cost_points or claim.reward_id=p_reward)) then
      raise exception 'this stamp gift has already been claimed on this card' using errcode='23514';
    end if;
  else
  v_balance := app.client_points_balance_v409(p_business, v_client);
  select coalesce(sum(remaining),0)::integer into v_batch_balance
    from public.points_batches
    where business_id=p_business and client_id=v_client and remaining>0
      and programme_id=v_intent_programme;
  if least(v_balance,v_batch_balance)<v_cost_points then
    raise exception 'insufficient points' using errcode='23514';
  end if;
  end if;
  v_token:=app.v89_redemption_token(
    v_identity,p_business,v_kind,p_reward,p_idempotency_key);
  v_hash:=app.v89_sha256(v_token);
  insert into public.customer_redemption_intents_v89(
    id,business_id,identity_id,auth_user_id,client_id,redemption_kind,reward_id,
    quoted_program_id,quoted_config_version_id,quoted_reward_version_id,
    quoted_points_spent,quoted_credit_cents,quoted_terms,
    token_hash,idempotency_key,request_hash,expires_at
  ) values(
    v_intent,p_business,v_identity,auth.uid(),v_client,v_kind,p_reward,
    v_program.id,
    case when v_kind='catalog_reward' then v_reward_version.config_version_id
      else v_program.current_config_version_id end,
    case when v_kind='catalog_reward' then v_reward_version.id else null end,
    v_cost_points,
    case when v_kind='catalog_reward' then v_reward_version.credit_cents
      else v_program.reward_credit_cents end,
    v_quote,
    v_hash,p_idempotency_key,v_request_hash,v_expires
  );
  insert into public.customer_redemption_events_v89(
    intent_id,business_id,actor,event_type,idempotency_key,detail
  ) values(
    v_intent,p_business,auth.uid(),'intent_created',p_idempotency_key,
    jsonb_build_object('redemption_kind',v_kind,'reward_id',p_reward,
      'expires_at',v_expires)
  );
  v_response:=jsonb_build_object('intent_id',v_intent,'status','pending',
    'redemption_kind',v_kind,'qr_token',v_token,'expires_at',v_expires,
    'replayed',false);
  return v_response;
end
$$;

--
-- Name: FUNCTION customer_create_redemption_intent_v89(p_business uuid, p_reward uuid, p_idempotency_key uuid, p_redemption_kind text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.customer_create_redemption_intent_v89(p_business uuid, p_reward uuid, p_idempotency_key uuid, p_redemption_kind text) IS 'v89 customer QR redemption intent, v229 mode gate, v311 W5a programme-scoped, v313 W6i1 REWARD-scoped. The affordability quote proves the pot named on the reward version — the same pot app.redeem_reward_core will drain at the counter — so the customer is never handed a QR the counter must refuse. The programme is resolved ONCE into v_intent_programme rather than per candidate batch row.';

--
-- Name: customer_explore_businesses_v244(text, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_explore_businesses_v244(p_query text DEFAULT NULL::text, p_lat numeric DEFAULT NULL::numeric, p_lng numeric DEFAULT NULL::numeric) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_tokens text[];
  v_lat numeric;
  v_lng numeric;
  v_result jsonb;
begin
  if v_actor is null then
    raise exception 'authenticated customer required' using errcode='28000';
  end if;

  -- an out-of-range or half-supplied position is treated as no position at all, never clamped
  if p_lat between -90 and 90 and p_lng between -180 and 180 then
    v_lat := p_lat;
    v_lng := p_lng;
  end if;

  select coalesce(array_agg(word), '{}')
    into v_tokens
  from (
    select lower(word) as word
    from regexp_split_to_table(coalesce(p_query,''), '[^[:alnum:]]+') word
    where length(word) between 2 and 40
      and lower(word) not in ('near','me','nearby','the','shop','shops','store','stores','place','places','in','at','for','a','an')
    limit 6
  ) cleaned;

  select coalesce(jsonb_agg(entry order by
      -- nearest first when the customer shared a position; unlocated businesses last, never gone
      (case when v_lat is null then 0 else 1 end) * coalesce((entry->>'distance_km')::numeric, 999999),
      (entry->>'joined') desc,
      entry->>'name'
    ), '[]'::jsonb)
    into v_result
  from (
    select jsonb_build_object(
      'business_id', b.id,
      'name', b.name,
      'slug', b.slug,
      'brand_color', b.brand_color,
      'industry', b.industry,
      'logo_url', app.v95_public_media_url(logo.object_path),
      'joined', (cl.id is not null),
      'points_balance', case when cl.id is null then null else coalesce((
        select sum(pl.points) from public.points_ledger pl
         where pl.business_id = b.id and pl.client_id = cl.client_id), 0) end,
      'earn_points_per_dollar', lp.earn_points_per_dollar,
      'loyalty_model', lp.loyalty_model,
      'points_mode', b.points_mode,
      'address', branch.address,
      'phone', branch.phone,
      'distance_km', app.v247_distance_km(v_lat, v_lng, branch.latitude, branch.longitude),
      'located', (branch.latitude is not null and branch.longitude is not null),
      'booking_enabled', coalesce(b.booking_policy is not null and exists(
        select 1 from public.services s where s.business_id=b.id and s.active), false),
      'match_note', matched.note
    ) as entry
    from public.businesses b
    left join public.customer_links cl
      on cl.business_id = b.id and cl.auth_user_id = v_actor
     and cl.state = 'verified' and cl.unlinked_at is null
    left join public.loyalty_programs lp
      on lp.business_id = b.id and lp.active
    left join public.business_brand_presentation_v95 brand
      on brand.business_id = b.id
    left join public.business_media_assets_v95 logo
      on logo.id = brand.logo_asset_id and logo.business_id = b.id
     and logo.asset_kind = 'logo' and logo.customer_visible
    left join lateral (
      /* the branch a customer would actually walk into: the nearest LOCATED one when a position
         was shared, otherwise the default. A firm with ten outlets is as far away as its closest
         outlet, not as far away as whichever row happened to sort first. */
      select br.address, br.phone, br.latitude, br.longitude
      from public.branches br
      where br.business_id = b.id and coalesce(br.active,true)
      order by
        case when v_lat is null then null
             else app.v247_distance_km(v_lat, v_lng, br.latitude, br.longitude) end
          nulls last,
        br.is_default desc, br.created_at, br.id
      limit 1
    ) branch on true
    left join lateral (
      select min(item.name) as note
      from (
        select s.name from public.services s where s.business_id=b.id and s.active
        union all
        select p.name from public.products p where p.business_id=b.id and coalesce(p.active,true)
      ) item
      where cardinality(v_tokens) > 0
        and exists(select 1 from unnest(v_tokens) t where item.name ilike '%'||t||'%')
    ) matched on true
    where b.join_enabled
      and (
        cardinality(v_tokens) = 0
        or not exists (
          select 1 from unnest(v_tokens) t
          where not (
            b.name ilike '%'||t||'%'
            or coalesce(b.industry,'') ilike '%'||t||'%'
            or exists(select 1 from public.services s
                       where s.business_id=b.id and s.active and s.name ilike '%'||t||'%')
            or exists(select 1 from public.products p
                       where p.business_id=b.id and coalesce(p.active,true) and p.name ilike '%'||t||'%')
          )
        )
      )
  ) listed;

  return v_result;
end
$$;

--
