--
-- Name: customer_get_actionable_business(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_get_actionable_business(p_business_slug text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_as_of timestamptz := statement_timestamp();
  v_context record;
begin
  if auth.uid() is null then
    raise exception 'authenticated customer session required' using errcode = '28000';
  end if;
  if p_business_slug is null or length(btrim(p_business_slug)) not between 2 and 160 then
    raise exception 'invalid business link' using errcode = '22023';
  end if;
  if not app.platform_feature_enabled('customer_actionable_wallet') then
    raise exception 'actionable customer wallet is not enabled' using errcode = '0A000';
  end if;

  select * into v_context
    from app.v32_customer_wallet_context(p_business_slug)
   limit 1;
  if not found then
    raise exception 'verified customer link required' using errcode = '42501';
  end if;

  return jsonb_build_object(
    'as_of', v_as_of,
    'card', app.c44_actionable_wallet_card(
      v_context.business_id, v_context.client_id, v_context.business_slug,
      v_context.business_name, v_context.business_industry, v_context.business_currency,
      v_context.enabled_modules, v_as_of
    )
  );
end;
$$;

--
-- Name: customer_get_actionable_wallet(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_get_actionable_wallet() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_as_of timestamptz := statement_timestamp();
  v_cards jsonb;
  v_truncated boolean := false;
begin
  if auth.uid() is null then
    raise exception 'authenticated customer session required' using errcode = '28000';
  end if;
  if not app.platform_feature_enabled('customer_actionable_wallet') then
    raise exception 'actionable customer wallet is not enabled' using errcode = '0A000';
  end if;

  -- Rank every verified relationship before the 100-card response bound. Logo
  -- media is joined to that same relationship context, never discovered from
  -- a caller-supplied business id or slug.
  select coalesce(jsonb_agg(card order by
    (card#>>'{action,sort_band}')::integer,
    nullif(card#>>'{action,deadline_at}', '')::timestamptz nulls last,
    (card#>>'{action,sort_units}')::integer,
    lower(card#>>'{business,name}'),
    card#>>'{business,slug}'
  ) filter (where action_rank <= 100), '[]'::jsonb),
  coalesce(bool_or(action_rank > 100), false)
    into v_cards, v_truncated
    from (
      select action_cards.card, row_number() over (order by
        (action_cards.card#>>'{action,sort_band}')::integer,
        nullif(action_cards.card#>>'{action,deadline_at}', '')::timestamptz nulls last,
        (action_cards.card#>>'{action,sort_units}')::integer,
        lower(action_cards.card#>>'{business,name}'),
        action_cards.card#>>'{business,slug}'
      ) as action_rank
        from (
          select base.card || jsonb_build_object(
            'business',
            coalesce(base.card->'business', '{}'::jsonb)
              || jsonb_build_object(
                'logo_url', app.v95_public_media_url(logo.object_path)
              )
          ) as card
            from app.v32_customer_wallet_context(null) context
            cross join lateral (
              select app.c44_actionable_wallet_card(
                context.business_id, context.client_id, context.business_slug,
                context.business_name, context.business_industry,
                context.business_currency, context.enabled_modules, v_as_of
              ) as card
            ) base
            left join public.business_brand_presentation_v95 brand
              on brand.business_id = context.business_id
            left join public.business_media_assets_v95 logo
              on logo.id = brand.logo_asset_id
             and logo.business_id = context.business_id
             and logo.asset_kind = 'logo'
             and logo.customer_visible
        ) action_cards
    ) ranked
   where action_rank <= 101;

  return jsonb_build_object(
    'as_of', v_as_of,
    'cards', v_cards,
    'truncated', v_truncated
  );
end;
$$;

--
-- Name: FUNCTION customer_get_actionable_wallet(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.customer_get_actionable_wallet() IS 'Bounded actionable cards for verified customer links, including the current customer-visible v95 logo URL.';

--
-- Name: customer_get_appointments(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_get_appointments(p_business_slug text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_context record;
  v_appointments jsonb;
begin
  if v_actor is null then
    raise exception 'authenticated customer session required' using errcode = '28000';
  end if;
  if not app.platform_feature_enabled('customer_wallet') then
    raise exception 'customer wallet is not enabled' using errcode = '0A000';
  end if;

  -- The app context resolves auth.uid() through customer_links with link status = 'verified'.
  select identity_id, business_id, client_id, business_name, business_slug,
         business_industry, business_currency, enabled_modules into v_context
    from app.v32_customer_wallet_context(p_business_slug)
   limit 1;
  if not found then
    raise exception 'verified customer link required' using errcode = '42501';
  end if;
  if not ('appointments' = any(v_context.enabled_modules)) then
    raise exception 'appointments module is unavailable for this business' using errcode = '42501';
  end if;

  select coalesce(jsonb_agg(
    jsonb_build_object(
      'appointment_id', listed.id,
      'starts_at', listed.starts_at,
      'ends_at', listed.ends_at,
      'status', listed.status,
      'service_name', listed.service_name,
      'branch_name', listed.branch_name
    ) order by listed.sort_group, listed.starts_at asc, listed.id
  ), '[]'::jsonb)
    into v_appointments
    from (
      select a.id, a.starts_at, a.ends_at, a.status,
             case when a.status = 'booked' and a.starts_at >= now() then 0 else 1 end as sort_group,
             s.name as service_name, br.name as branch_name
        from public.appointments a
        left join public.services s
          on s.id = a.service_id and s.business_id = a.business_id
        left join public.branches br
          on br.id = a.branch_id and br.business_id = a.business_id
       where a.business_id = v_context.business_id
         and a.client_id = v_context.client_id
         and a.status in ('booked', 'completed', 'cancelled', 'no_show')
       order by case when a.status = 'booked' and a.starts_at >= now() then 0 else 1 end,
                a.starts_at asc, a.id
       limit 20
    ) listed;

  return v_appointments;
end;
$$;

--
-- Name: customer_get_appointments_page(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_get_appointments_page(p_business_slug text, p_cursor jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_context record;
  v_cursor jsonb := coalesce(p_cursor, '{}'::jsonb);
  v_limit integer := 20;
  v_as_of timestamptz := statement_timestamp();
  v_cursor_group integer;
  v_cursor_at timestamptz;
  v_cursor_id uuid;
  v_result jsonb;
begin
  if auth.uid() is null then
    raise exception 'authenticated customer session required' using errcode = '28000';
  end if;
  if jsonb_typeof(v_cursor) <> 'object' then
    raise exception 'invalid appointments cursor' using errcode = '22023';
  end if;
  if exists (select 1 from jsonb_object_keys(v_cursor) as keys(key)
              where key not in ('limit','as_of','sort_group','starts_at','id')) then
    raise exception 'invalid appointments cursor' using errcode = '22023';
  end if;
  begin
    v_limit := least(greatest(coalesce((v_cursor->>'limit')::integer, 20), 1), 50);
    v_as_of := coalesce(nullif(v_cursor->>'as_of', '')::timestamptz, v_as_of);
    v_cursor_group := nullif(v_cursor->>'sort_group', '')::integer;
    v_cursor_at := nullif(v_cursor->>'starts_at', '')::timestamptz;
    v_cursor_id := nullif(v_cursor->>'id', '')::uuid;
  exception when others then
    raise exception 'invalid appointments cursor' using errcode = '22023';
  end;
  if v_cursor_group is not null and v_cursor_group not in (0,1) then
    raise exception 'invalid appointments cursor' using errcode = '22023';
  end if;
  if num_nonnulls(v_cursor_group,v_cursor_at,v_cursor_id) not in (0,3) then
    raise exception 'appointments cursor is incomplete' using errcode = '22023';
  end if;

  select * into v_context from app.v32_customer_wallet_context(p_business_slug) limit 1;
  if not found then
    raise exception 'verified customer link required' using errcode = '42501';
  end if;
  if not ('appointments' = any(v_context.enabled_modules)) then
    raise exception 'appointments module is unavailable for this business' using errcode = '42501';
  end if;

  with ordered as (
    select a.id, a.starts_at, a.ends_at, a.status,
           case when a.status = 'booked' and a.starts_at >= v_as_of then 0 else 1 end as sort_group,
           s.name as service_name, br.name as branch_name
      from public.appointments a
      left join public.services s on s.id = a.service_id and s.business_id = a.business_id
      left join public.branches br on br.id = a.branch_id and br.business_id = a.business_id
     where a.business_id = v_context.business_id
       and a.client_id = v_context.client_id
       and a.status in ('booked','completed','cancelled','no_show')
  ), eligible as (
    select * from ordered
     where v_cursor_group is null
        or sort_group > v_cursor_group
        or (
          sort_group = v_cursor_group and (
            (sort_group = 0 and (starts_at,id) > (v_cursor_at,v_cursor_id))
            or (sort_group = 1 and (starts_at,id) < (v_cursor_at,v_cursor_id))
          )
        )
     order by sort_group,
              case when sort_group=0 then starts_at end asc,
              case when sort_group=1 then starts_at end desc,
              case when sort_group=0 then id end asc,
              case when sort_group=1 then id end desc
     limit v_limit + 1
  ), visible as (
    select * from eligible
     order by sort_group,
              case when sort_group=0 then starts_at end asc,
              case when sort_group=1 then starts_at end desc,
              case when sort_group=0 then id end asc,
              case when sort_group=1 then id end desc
     limit v_limit
  )
  select jsonb_build_object(
    'items', coalesce((select jsonb_agg(jsonb_build_object(
      'appointment_id', id, 'starts_at', starts_at, 'ends_at', ends_at,
      'status', status, 'service_name', service_name, 'branch_name', branch_name
    ) order by sort_group,
               case when sort_group=0 then starts_at end asc,
               case when sort_group=1 then starts_at end desc,
               case when sort_group=0 then id end asc,
               case when sort_group=1 then id end desc) from visible), '[]'::jsonb),
    'next_cursor', case when (select count(*) from eligible) > v_limit then (
      select jsonb_build_object(
        'as_of', v_as_of, 'sort_group', sort_group, 'starts_at', starts_at,
        'id', id, 'limit', v_limit
      ) from visible
       order by sort_group,
                case when sort_group=0 then starts_at end asc,
                case when sort_group=1 then starts_at end desc,
                case when sort_group=0 then id end asc,
                case when sort_group=1 then id end desc
       offset v_limit - 1 limit 1
    ) else null end
  ) into v_result;

  return v_result;
end;
$$;

--
-- Name: customer_get_birthday_benefit(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_get_birthday_benefit(p_business_slug text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_context record; v_benefit jsonb;
begin
  select * into v_context from app.c45_customer_birthday_context(p_business_slug) limit 1;
  select app.c45_customer_birthday_benefit_for_context(
    v_context.business_id,v_context.client_id,v_context.identity_id,v_context.birth_date,statement_timestamp()
  ) into v_benefit;
  return coalesce(v_benefit, jsonb_build_object('status','unavailable'));
end $$;

--
-- Name: customer_get_birthday_participation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_get_birthday_participation() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_identity uuid; v_opted_in boolean := false;
begin
  if auth.uid() is null then raise exception 'authenticated customer session required' using errcode='28000'; end if;
  if not app.platform_feature_enabled('customer_birthday_benefits') then
    raise exception 'birthday benefits are unavailable' using errcode='0A000';
  end if;
  select id into v_identity from public.customer_identities
   where auth_user_id=auth.uid() and status='active';
  if not found then raise exception 'birthday benefits are unavailable' using errcode='42501'; end if;
  select coalesce(p.opted_in,false) into v_opted_in
    from (select 1) one left join public.customer_birthday_participation p on p.identity_id=v_identity;
  return jsonb_build_object('opted_in',coalesce(v_opted_in,false));
end $$;

--
-- Name: customer_get_booking_requests(integer, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_get_booking_requests(p_limit integer DEFAULT 20, p_cursor jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_limit integer;
  v_cursor_created timestamptz;
  v_cursor_id uuid;
  v_result jsonb;
begin
  if v_actor is null then
    raise exception 'authenticated customer session required' using errcode = '28000';
  end if;
  if p_limit is null or p_limit not between 1 and 50 then
    raise exception 'invalid booking request limit' using errcode = '22023';
  end if;
  v_limit := p_limit;
  if p_cursor is not null then
    if jsonb_typeof(p_cursor) <> 'object'
       or not (p_cursor ? 'created_at')
       or not (p_cursor ? 'request_id')
       or (select count(*) from jsonb_object_keys(p_cursor)) <> 2
       or jsonb_typeof(p_cursor->'created_at') <> 'string'
       or jsonb_typeof(p_cursor->'request_id') <> 'string'
       or (p_cursor->>'created_at') !~
          '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]{1,6})?(Z|[+-][0-9]{2}:[0-9]{2})$'
       or (p_cursor->>'request_id') !~
          '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then
      raise exception 'invalid booking request cursor' using errcode = '22023';
    end if;
    begin
      v_cursor_created := (p_cursor->>'created_at')::timestamptz;
      v_cursor_id := (p_cursor->>'request_id')::uuid;
    exception when others then
      raise exception 'invalid booking request cursor' using errcode = '22023';
    end;
  end if;

  with visible as (
    select request.id,
           business.slug as business_slug,
           business.name as business_name,
           case when request.status = 'new' then 'pending' else request.status end as status,
           request.preferred_at,
           request.party_size,
           service.name as service_name,
           request.created_at
      from public.customer_identities identity
      join public.customer_links link
        on link.identity_id = identity.id
       and link.auth_user_id = identity.auth_user_id
       and link.state = 'verified'
      join public.booking_requests request
        on request.business_id = link.business_id
       and request.customer_client_id = link.client_id
      join app.booking_management_tokens token
        on token.business_id = request.business_id
       and token.booking_request_id = request.id
       and token.customer_client_id = request.customer_client_id
       and token.authenticated_user_id = v_actor
      join public.businesses business on business.id = request.business_id
      left join public.services service
        on service.id = request.service_id
       and service.business_id = request.business_id
     where identity.auth_user_id = v_actor
       and identity.status = 'active'
       and request.appointment_id is null
       and (
         request.status in ('new', 'pending', 'waitlisted')
         or (
           request.status in ('declined', 'expired', 'cancelled')
           and request.created_at >= current_timestamp - interval '90 days'
         )
       )
       and (
         v_cursor_created is null
         or (request.created_at, request.id) < (v_cursor_created, v_cursor_id)
       )
     order by request.created_at desc, request.id desc
     limit v_limit + 1
  ), listed as (
    select * from visible
     order by created_at desc, id desc
     limit v_limit
  )
  select jsonb_build_object(
    'items', coalesce((
      select jsonb_agg(jsonb_build_object(
        'request_id', listed.id,
        'business_slug', listed.business_slug,
        'business_name', listed.business_name,
        'status', listed.status,
        'preferred_at', listed.preferred_at,
        'party_size', listed.party_size,
        'service_name', listed.service_name,
        'created_at', listed.created_at
      ) order by listed.created_at desc, listed.id desc)
      from listed
    ), '[]'::jsonb),
    'truncated', (select count(*) from visible) > v_limit,
    'next_cursor', case
      when (select count(*) from visible) > v_limit then (
        select jsonb_build_object(
          'created_at', listed.created_at,
          'request_id', listed.id
        )
          from listed
         order by listed.created_at asc, listed.id asc
         limit 1
      )
      else null
    end
  ) into v_result;
  return v_result;
end
$_$;

--
-- Name: customer_get_bottles_v275(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_get_bottles_v275(p_business_slug text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_business uuid;
  v_client uuid;
  v_modules text[];
  v_items jsonb;
begin
  select context.business_id, context.client_id, context.enabled_modules
    into v_business, v_client, v_modules
    from app.v32_customer_wallet_context(p_business_slug) context
   limit 1;
  if v_business is null then
    raise exception 'no verified link to this business' using errcode = '42501';
  end if;
  perform app.require_bar_business_v275(v_business);
  if not ('bottles' = any (coalesce(v_modules, '{}'::text[]))) then
    raise exception 'bottle keep is not enabled for this business' using errcode = '42501';
  end if;

  select coalesce(jsonb_agg(entry order by ordering_expires), '[]'::jsonb)
    into v_items
    from (
      select jsonb_build_object(
               'id', bottle.id,
               'serial_code', bottle.serial_code,
               'label', coalesce(nullif(btrim(coalesce(bottle.label, '')), ''), product.name),
               'size_ml', bottle.size_ml,
               'fill_percent', bottle.fill_percent,
               'status', bottle.status,
               'storage_location_name', location.name,
               'parked_at', bottle.parked_at,
               'expires_at', bottle.expires_at,
               'expiry_mode', bottle.expiry_mode,
               'days_left', case when bottle.expires_at is null then null else (
                 (bottle.expires_at at time zone 'Asia/Singapore')::date
                 - (now() at time zone 'Asia/Singapore')::date
               ) end) as entry,
             bottle.expires_at as ordering_expires
        from public.bar_bottles bottle
        left join public.products product on product.id = bottle.product_id
        left join public.bar_storage_locations location on location.id = bottle.storage_location_id
       where bottle.business_id = v_business
         and bottle.client_id = v_client
         and bottle.status in ('stored', 'called', 'at_table')
       order by bottle.expires_at
       limit 50
    ) page;

  return jsonb_build_object('status', 'ok', 'items', v_items);
end;
$$;

--
-- Name: customer_get_business_actions_v89(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_get_business_actions_v89(p_business uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_identity uuid;v_client uuid;v_result jsonb;
  v_balance integer;v_batch_balance integer;
  v_program public.loyalty_programs%rowtype;
  v_live_points_programme uuid;v_stamps_programme uuid;v_stamp_filled integer;v_stamp_cycle integer;
begin
  v_identity:=app.v31_current_identity();
  select link.client_id into v_client from public.customer_links link
  where link.identity_id=v_identity and link.auth_user_id=auth.uid()
    and link.business_id=p_business and link.state='verified';
  if not found then raise exception 'verified customer link required' using errcode='42501';end if;
  select spine.id into v_live_points_programme from public.business_programmes spine
    where spine.business_id=p_business and spine.kind='points' and spine.active
    order by spine.sort, spine.id limit 1;
  select coalesce(sum(points),0)::integer into v_balance from public.points_ledger
    where business_id=p_business and client_id=v_client and programme_id=v_live_points_programme;
  select coalesce(sum(remaining),0)::integer into v_batch_balance
    from public.points_batches
    where business_id=p_business and client_id=v_client and remaining>0
      and programme_id=v_live_points_programme;
  select spine.id into v_stamps_programme from public.business_programmes spine
    where spine.business_id=p_business and spine.kind='stamps' and spine.active
    order by spine.sort, spine.id limit 1; /* v384_live_customer_programmes_actions */
  select coalesce(sp.filled,0),coalesce(sp.cycle_index,0)
    into v_stamp_filled,v_stamp_cycle
    from app.stamp_progress_v323(p_business,v_client) sp;
  select * into v_program from public.loyalty_programs program
    where program.business_id=p_business and program.active
    order by program.id limit 1;
  select jsonb_build_object(
    'business',jsonb_build_object('id',business.id,'slug',business.slug,
      'name',business.name,'industry',business.industry,'currency',business.currency),
    'booking',jsonb_build_object('enabled',
      coalesce(capability.booking_enabled,false)
      and app.v89_business_module_enabled(p_business,'bookings') and exists(
        select 1 from public.services service where service.business_id=p_business
          and service.active and service.show_on_booking_page),
      'public_slug',case when coalesce(capability.booking_enabled,false)
        and app.v89_business_module_enabled(p_business,'bookings') and exists(
        select 1 from public.services service where service.business_id=p_business
          and service.active and service.show_on_booking_page)
        then business.slug else null end),
    'redemption',jsonb_build_object(
      'enabled',coalesce(capability.redemption_enabled,false)
        and app.v89_business_module_enabled(p_business,'loyalty')
        and v_program.id is not null,
      -- v376: the points-for-store-credit action is never offered. v375 retired the model and made
      -- app.redeem_points_v40_internal refuse, so leaving this in place would have shown a customer
      -- a redemption their own counter could no longer honour.
      'classic',null::jsonb),
    'appointment_changes',jsonb_build_object(
      'enabled',coalesce(capability.appointment_changes_enabled,false)
        and app.v89_business_module_enabled(p_business,'appointments')),
    'rewards',coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',reward.id,'name',coalesce(reward.customer_name,reward.name),
        'redemption_kind','catalog_reward',
        'cost_points',reward_version.cost_points,
        'availability',case
          when not coalesce(capability.redemption_enabled,false)
            or not app.v89_business_module_enabled(p_business,'loyalty')
            then 'disabled'
          when reward_version.claim_available_from is not null
            and reward_version.claim_available_from>now() then 'not_started'
          when reward_version.claim_available_until is not null
            and reward_version.claim_available_until<=now() then 'ended'
          when reward_version.usage_limit is not null and (
            select count(*) from public.loyalty_redemptions redemption
            where redemption.business_id=p_business
              and redemption.client_id=v_client
              and redemption.reward_id=reward.id
          )>=reward_version.usage_limit then 'limit_reached'
          when v_stamps_programme is not null and reward.programme_id=v_stamps_programme
            and exists(select 1 from public.stamp_milestone_claims claim
                        where claim.business_id=p_business and claim.client_id=v_client
                          and claim.programme_id=v_stamps_programme
                          and claim.cycle_index=coalesce(v_stamp_cycle,0)
                          and claim.reward_id=reward.id)
            then 'limit_reached'
          when (case when v_stamps_programme is not null and reward.programme_id=v_stamps_programme
                     then coalesce(v_stamp_filled,0)
                     else least(v_balance,v_batch_balance) end)<reward_version.cost_points
            then 'insufficient_balance'
          else 'available_at_counter' end
      ) order by reward.sort,reward.id)
      from public.loyalty_rewards reward
      join public.loyalty_reward_versions reward_version
        on reward_version.reward_id=reward.id
       and reward_version.business_id=reward.business_id
      where reward.business_id=p_business and reward.active and not reward.paused
        and exists(select 1 from public.business_programmes spine
                    where spine.id=reward.programme_id and spine.active)
        and reward_version.config_version_id=business.active_config_version_id
        and reward_version.active
        -- Customer QR redemption carries no visit context in v89. Restricted
        -- rewards remain visible through the ordinary wallet catalog, but are
        -- truthfully excluded from this actionable scan list.
        and not exists(select 1 from public.loyalty_reward_branches restriction
          where restriction.reward_version_id=reward_version.id)
        and not exists(select 1 from public.loyalty_reward_services restriction
          where restriction.reward_version_id=reward_version.id)
        and not exists(select 1 from public.loyalty_reward_products restriction
          where restriction.reward_version_id=reward_version.id)
    ),'[]'::jsonb)
  ) into v_result
  from public.businesses business
  left join public.business_customer_capabilities_v89 capability
    on capability.business_id=business.id
  where business.id=p_business;
  return v_result;
end
$$;

--
-- Name: customer_get_business_presentation_v95(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_get_business_presentation_v95(p_business uuid, p_branch uuid DEFAULT NULL::uuid, p_locale text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid:=auth.uid();v_identity uuid;v_client uuid;v_branch uuid:=p_branch;
  v_locale text;v_programme uuid;v_balance integer:=0;v_unit text:='points';
  v_metric numeric:=0;v_basis text;v_points_programme uuid;
  v_current public.loyalty_tiers%rowtype;
  v_next public.loyalty_tiers%rowtype;v_progress numeric:=0;v_result jsonb;
begin
  if v_actor is null then raise exception 'authenticated_session_required'
    using errcode='28000';end if;
  if p_locale is not null and p_locale not in ('en','zh-CN') then
    raise exception 'unsupported_locale' using errcode='22023';end if;
  v_identity:=app.v31_current_identity();
  select link.client_id into v_client from public.customer_links link
  where link.identity_id=v_identity and link.auth_user_id=v_actor
    and link.business_id=p_business and link.state='verified';
  if not found then raise exception 'verified_customer_link_required'
    using errcode='42501';end if;
  v_locale:=coalesce(
    p_locale,(select locale from public.customer_locale_preferences_v95
      where auth_user_id=v_actor),'en'
  );
  if v_branch is null then
    select id into v_branch from public.branches
    where business_id=p_business and active
    order by is_default desc,created_at,id limit 1;
  end if;
  if v_branch is null or not exists(
    select 1 from public.branches
    where id=v_branch and business_id=p_business and active
  ) then raise exception 'active_branch_required' using errcode='22023';end if;
  select id,case when loyalty_model='stamps' then 'stamps' else 'points' end,
    coalesce(tier_basis,'visits')
  into v_programme,v_unit,v_basis
  from public.loyalty_programs
  where business_id=p_business and active
  order by (current_config_version_id is not null) desc,id limit 1;
  select coalesce(sum(points),0)::integer into v_balance
  from public.points_ledger
  where business_id=p_business and client_id=v_client;
  if v_basis='spend' then
    select coalesce(sum(amount_cents),0)/100.0 into v_metric from public.sales
    where business_id=p_business and client_id=v_client and counts_as_revenue;
  elsif v_basis='points_earned' then
    select spine.id into v_points_programme
    from public.business_programmes spine
    where spine.business_id=p_business and spine.kind='points';
    if v_points_programme is null then
      select coalesce(sum(points),0) into v_metric from public.points_ledger
      where business_id=p_business and client_id=v_client and entry_type='earn';
    else
      select coalesce(sum(ledger.points),0) into v_metric from public.points_ledger ledger
      where ledger.business_id=p_business and ledger.client_id=v_client
        and ledger.entry_type='earn' and ledger.programme_id=v_points_programme;
    end if;
  else
    select count(*) into v_metric from public.sales
    where business_id=p_business and client_id=v_client and counts_as_visit;
  end if;
  select * into v_current from public.loyalty_tiers
  where business_id=p_business and threshold<=v_metric
    and deleted_at is null and not paused
  order by threshold desc,sort desc,id limit 1;
  select * into v_next from public.loyalty_tiers
  where business_id=p_business and threshold>coalesce(v_current.threshold,-1)
    and deleted_at is null and not paused
  order by threshold,sort,id limit 1;
  if v_next.id is not null then
    v_progress:=greatest(0,least(100,round(
      (v_metric-coalesce(v_current.threshold,0))*100
      /nullif(v_next.threshold-coalesce(v_current.threshold,0),0),2
    )));
  elsif v_current.id is not null then v_progress:=100;end if;

  with programme_copy as (
    select copy.* from public.business_localized_copy_v95 copy
    where copy.business_id=p_business and copy.entity_type='programme'
      and copy.entity_id=v_programme and copy.locale=v_locale
    limit 1
  ), programme_english as (
    select copy.* from public.business_localized_copy_v95 copy
    where copy.business_id=p_business and copy.entity_type='programme'
      and copy.entity_id=v_programme and copy.locale='en'
    limit 1
  ), visible_media as (
    select distinct on(asset.asset_kind,asset.entity_id)
      asset.asset_kind,asset.entity_id,
      app.v95_public_media_url(asset.object_path) url
    from public.business_media_assets_v95 asset
    where asset.business_id=p_business and asset.customer_visible
      and (asset.branch_id is null or asset.branch_id=v_branch)
    order by asset.asset_kind,asset.entity_id,
      (asset.branch_id=v_branch) desc,asset.updated_at desc,asset.id
  ), benefits as (
    select coalesce(jsonb_agg(jsonb_build_object(
      'id',content.id,
      'name',coalesce(copy.name,english.name,'Benefit'),
      'tagline',coalesce(copy.tagline,english.tagline),
      'description',coalesce(copy.description,english.description),
      'image_url',media.url,'metadata',content.metadata
    ) order by content.display_order,content.id),'[]'::jsonb) value
    from public.business_customer_content_v95 content
    left join public.business_localized_copy_v95 copy
      on copy.business_id=p_business and copy.entity_type='benefit'
      and copy.entity_id=content.id and copy.locale=v_locale
    left join public.business_localized_copy_v95 english
      on english.business_id=p_business and english.entity_type='benefit'
      and english.entity_id=content.id and english.locale='en'
    left join visible_media media
      on media.asset_kind='benefit' and media.entity_id=content.id
    where content.business_id=p_business and content.content_type='benefit'
      and content.active and (content.branch_id is null or content.branch_id=v_branch)
      and (content.starts_at is null or content.starts_at<=now())
      and (content.ends_at is null or content.ends_at>now())
  ), offers as (
    select coalesce(jsonb_agg(jsonb_build_object(
      'id',content.id,
      'name',coalesce(copy.name,english.name,'Offer'),
      'tagline',coalesce(copy.tagline,english.tagline),
      'description',coalesce(copy.description,english.description),
      'terms',coalesce(copy.terms,english.terms),
      'image_url',media.url,'starts_at',content.starts_at,
      'ends_at',content.ends_at,'metadata',content.metadata
    ) order by content.display_order,content.id),'[]'::jsonb) value
    from public.business_customer_content_v95 content
    left join public.business_localized_copy_v95 copy
      on copy.business_id=p_business and copy.entity_type='offer'
      and copy.entity_id=content.id and copy.locale=v_locale
    left join public.business_localized_copy_v95 english
      on english.business_id=p_business and english.entity_type='offer'
      and english.entity_id=content.id and english.locale='en'
    left join visible_media media
      on media.asset_kind='offer' and media.entity_id=content.id
    where content.business_id=p_business and content.content_type='offer'
      and content.active and (content.branch_id is null or content.branch_id=v_branch)
      and (content.starts_at is null or content.starts_at<=now())
      and (content.ends_at is null or content.ends_at>now())
  ), services_json as (
    select coalesce(jsonb_agg(jsonb_build_object(
      'id',service.id,'name',coalesce(copy.name,english.name,service.name),
      'description',coalesce(copy.description,english.description),
      'image_url',media.url,'price_cents',service.price_cents,
      'duration_min',service.duration_min
    ) order by service.name,service.id),'[]'::jsonb) value
    from public.services service
    left join public.business_localized_copy_v95 copy
      on copy.business_id=p_business and copy.entity_type='service'
      and copy.entity_id=service.id and copy.locale=v_locale
    left join public.business_localized_copy_v95 english
      on english.business_id=p_business and english.entity_type='service'
      and english.entity_id=service.id and english.locale='en'
    left join visible_media media
      on media.asset_kind='service' and media.entity_id=service.id
    where service.business_id=p_business and service.active
      and service.show_on_booking_page
      and (not exists(select 1 from public.service_branches configured
        where configured.business_id=p_business and configured.service_id=service.id)
        or exists(select 1 from public.service_branches available
          where available.business_id=p_business and available.service_id=service.id
            and available.branch_id=v_branch))
  ), products_json as (
    select coalesce(jsonb_agg(jsonb_build_object(
      'id',product.id,'name',coalesce(copy.name,english.name,product.name),
      'description',coalesce(copy.description,english.description),
      'image_url',media.url,'price_cents',product.retail_price_cents
    ) order by product.name,product.id),'[]'::jsonb) value
    from public.products product
    left join public.business_localized_copy_v95 copy
      on copy.business_id=p_business and copy.entity_type='product'
      and copy.entity_id=product.id and copy.locale=v_locale
    left join public.business_localized_copy_v95 english
      on english.business_id=p_business and english.entity_type='product'
      and english.entity_id=product.id and english.locale='en'
    left join visible_media media
      on media.asset_kind='product' and media.entity_id=product.id
    where product.business_id=p_business and product.active
  ), rewards_json as (
    select coalesce(jsonb_agg(jsonb_build_object(
      'id',reward.id,'name',coalesce(copy.name,english.name,reward.name),
      'description',coalesce(copy.description,english.description),
      'terms',coalesce(copy.terms,english.terms),
      'image_url',media.url,
      'metadata',jsonb_build_object(
        'cost_points',reward.cost_points,'credit_cents',reward.credit_cents
      )
    ) order by reward.sort,reward.id),'[]'::jsonb) value
    from public.loyalty_rewards reward
    left join public.business_localized_copy_v95 copy
      on copy.business_id=p_business and copy.entity_type='reward'
      and copy.entity_id=reward.id and copy.locale=v_locale
    left join public.business_localized_copy_v95 english
      on english.business_id=p_business and english.entity_type='reward'
      and english.entity_id=reward.id and english.locale='en'
    left join visible_media media
      on media.asset_kind='reward' and media.entity_id=reward.id
    where reward.business_id=p_business and reward.active and not reward.paused
  )
  select jsonb_build_object(
    'business_id',business.id,'branch_id',v_branch,'locale',v_locale,
    'available_locales',jsonb_build_array('en','zh-CN'),
    'brand',jsonb_build_object(
      'logo_url',app.v95_public_media_url(logo.object_path),
      'hero_image_url',app.v95_public_media_url(hero.object_path),
      'hero_color',brand.hero_color
    ),
    'programme',jsonb_build_object(
      'id',v_programme,
      'name',coalesce(programme_copy.name,programme_english.name,
        business.name||' Loyalty'),
      'tagline',coalesce(programme_copy.tagline,programme_english.tagline),
      'description',coalesce(
        programme_copy.description,programme_english.description
      ),
      'balance',v_balance,'unit',v_unit,
      'tier',jsonb_build_object(
        'label',coalesce(tier_copy.name,tier_english.name,v_current.name),
        'current',case when v_current.id is null then null else jsonb_build_object(
          'id',v_current.id,'threshold',v_current.threshold,'metric',v_metric
        ) end,
        'next',case when v_next.id is null then null else jsonb_build_object(
          'id',v_next.id,'label',coalesce(next_copy.name,next_english.name,v_next.name),
          'threshold',v_next.threshold
        ) end,
        'progress_percent',v_progress
      ),
      'benefits',benefits.value,'offers',offers.value
    ),
    'catalogue',jsonb_build_object(
      'services',services_json.value,'products',products_json.value,
      'rewards',rewards_json.value
    ),
    'capabilities',jsonb_build_object(
      'booking_enabled',coalesce(capability.booking_enabled,false)
        and app.v89_business_module_enabled(p_business,'bookings')
        and jsonb_array_length(services_json.value)>0,
      'redemption_enabled',coalesce(capability.redemption_enabled,false)
        and app.v89_business_module_enabled(p_business,'loyalty')
        and v_programme is not null,
      'appointment_changes_enabled',
        coalesce(capability.appointment_changes_enabled,false)
        and app.v89_business_module_enabled(p_business,'appointments')
    )
  ) into v_result
  from public.businesses business
  join public.business_brand_presentation_v95 brand
    on brand.business_id=business.id
  left join public.business_media_assets_v95 logo
    on logo.id=brand.logo_asset_id and logo.customer_visible
    and (logo.branch_id is null or logo.branch_id=v_branch)
  left join public.business_media_assets_v95 hero
    on hero.id=brand.hero_asset_id and hero.customer_visible
    and (hero.branch_id is null or hero.branch_id=v_branch)
  left join public.business_customer_capabilities_v89 capability
    on capability.business_id=business.id
  left join programme_copy on true
  left join programme_english on true
  left join public.business_localized_copy_v95 tier_copy
    on tier_copy.business_id=p_business and tier_copy.entity_type='tier'
    and tier_copy.entity_id=v_current.id and tier_copy.locale=v_locale
  left join public.business_localized_copy_v95 tier_english
    on tier_english.business_id=p_business and tier_english.entity_type='tier'
    and tier_english.entity_id=v_current.id and tier_english.locale='en'
  left join public.business_localized_copy_v95 next_copy
    on next_copy.business_id=p_business and next_copy.entity_type='tier'
    and next_copy.entity_id=v_next.id and next_copy.locale=v_locale
  left join public.business_localized_copy_v95 next_english
    on next_english.business_id=p_business and next_english.entity_type='tier'
    and next_english.entity_id=v_next.id and next_english.locale='en'
  cross join benefits cross join offers cross join services_json
  cross join products_json cross join rewards_json
  where business.id=p_business;
  return v_result;
end
$$;

--
-- Name: FUNCTION customer_get_business_presentation_v95(p_business uuid, p_branch uuid, p_locale text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.customer_get_business_presentation_v95(p_business uuid, p_branch uuid, p_locale text) IS 'v310 D1 twin: the points_earned tier metric is scoped to the v308 points spine row, fail-OPEN. The programme BALANCE stays the business pot, byte-identical to v95 — W4 policy rule 1.';

--
-- Name: customer_get_business_summary(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_get_business_summary(p_business_slug text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_context record;
  v_summary jsonb;
begin
  if v_actor is null then
    raise exception 'authenticated customer session required' using errcode = '28000';
  end if;
  if not app.platform_feature_enabled('customer_wallet') then
    raise exception 'customer wallet is not enabled' using errcode = '0A000';
  end if;

  select identity_id, business_id, client_id, business_name, business_slug,
         business_industry, business_currency, enabled_modules into v_context
    from app.v32_customer_wallet_context(p_business_slug)
   limit 1;
  if not found then
    raise exception 'verified customer link required' using errcode = '42501';
  end if;

  select jsonb_build_object(
    'business', jsonb_build_object(
      'id', v_context.business_id,
      'slug', v_context.business_slug,
      'name', v_context.business_name,
      'industry', v_context.business_industry,
      -- V385: the firm's OWN wording for what it does, shown under the business name in the
      -- customer app. Read straight off the row rather than added to the wallet context, so the
      -- context view keeps the shape every other caller of it already depends on.
      'industry_label', (select b.industry_label from public.businesses b where b.id = v_context.business_id),
      -- nestly_v417 (owner, photo 7: an arrow from the workspace's "Company bio" field to the line
      -- under the business name in the customer app, "show here as bio"). The column has existed
      -- since v325 and the workspace has always edited it; no customer read ever returned it, so
      -- everything a firm wrote there was only ever visible to the firm. Same shape as
      -- industry_label above: a scalar subquery off the row, leaving v32_customer_wallet_context
      -- untouched for every other caller.
      'bio', (select b.bio from public.businesses b where b.id = v_context.business_id),
      -- nestly_v418 (owner, photo 10): the profile's own gallery and links, on the read that
      -- already carries the name, logo, industry and bio. No new customer endpoint, so nothing
      -- else about what a customer may fetch changed.
      'gallery', coalesce((select jsonb_agg(jsonb_build_object('image_ref', g.image_ref,
                                                              'caption', g.caption)
                             order by g.sort, g.created_at)
                             from public.business_gallery_v418 g
                            where g.business_id = v_context.business_id),'[]'::jsonb),
      'social_links', coalesce((select jsonb_agg(jsonb_build_object('platform', l.platform,
                                                                   'url', l.url)
                                  order by l.sort, l.platform)
                                  from public.business_social_links_v418 l
                                 where l.business_id = v_context.business_id),'[]'::jsonb),
      'currency', v_context.business_currency,
      'logo_url', app.v267_business_logo_url(v_context.business_id),
      'review_url', (select b.review_url from public.businesses b where b.id = v_context.business_id)
    ),
    'loyalty', app.customer_live_loyalty_v384(
      v_context.business_id, v_context.client_id, v_context.enabled_modules, now()
    ),
    'packages', jsonb_build_object(
      'enabled', 'packages' = any(v_context.enabled_modules),
      'active_count', case when 'packages' = any(v_context.enabled_modules) then coalesce((
        select count(*)::integer
          from public.client_packages cp
         where cp.business_id = v_context.business_id
           and cp.client_id = v_context.client_id
           and cp.status = 'active'
           and cp.remaining > 0
      ), 0) else 0 end,
      'sessions_remaining', case when 'packages' = any(v_context.enabled_modules) then coalesce((
        select sum(cp.remaining)::integer
          from public.client_packages cp
         where cp.business_id = v_context.business_id
           and cp.client_id = v_context.client_id
           and cp.status = 'active'
           and cp.remaining > 0
      ), 0) else 0 end
    ),
    'membership', jsonb_build_object(
      'enabled', 'memberships' = any(v_context.enabled_modules),
      'active', case when 'memberships' = any(v_context.enabled_modules) then exists (
        select 1 from public.memberships m
         where m.business_id = v_context.business_id
           and m.client_id = v_context.client_id
           and m.status in ('active', 'paused', 'cancel_at_period_end')
      ) else false end,
      'current_period_ends_at', case when 'memberships' = any(v_context.enabled_modules) then (
        select min(m.current_period_end)
          from public.memberships m
         where m.business_id = v_context.business_id
           and m.client_id = v_context.client_id
           and m.status in ('active', 'paused', 'cancel_at_period_end')
      ) end
    ),
    'upcoming_appointments', jsonb_build_object(
      'enabled', 'appointments' = any(v_context.enabled_modules),
      'count', case when 'appointments' = any(v_context.enabled_modules) then (
        select count(*)::integer
          from public.appointments a
         where a.business_id = v_context.business_id
           and a.client_id = v_context.client_id
           and a.status = 'booked'
           and a.starts_at >= now()
      ) else 0 end
    )
  ) into v_summary;

  return v_summary;
end;
$$;

--
-- Name: customer_get_communication_preferences_v263(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_get_communication_preferences_v263() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_identity uuid := app.customer_communication_identity_v263();
  v_result jsonb;
begin
  select jsonb_build_object(
    'categories', coalesce(jsonb_agg(category_row.entry order by category_row.ordinality), '[]'::jsonb),
    'all_enabled', not exists (
      select 1
        from public.customer_communication_preferences_v263 preference
       where preference.identity_id = v_identity
         and not preference.enabled
    )
  )
  into v_result
  from (
    select
      catalog.ordinality,
      jsonb_build_object(
        'category', catalog.category,
        'channels', (
          select coalesce(jsonb_agg(
            jsonb_build_object(
              'channel', channels.channel,
              'enabled', coalesce((
                select preference.enabled
                  from public.customer_communication_preferences_v263 preference
                 where preference.identity_id = v_identity
                   and preference.category = catalog.category
                   and preference.channel = channels.channel
              ), true)
            ) order by channels.ordinality
          ), '[]'::jsonb)
          from unnest(app.communication_channels_v263()) with ordinality
            as channels(channel, ordinality)
        )
      ) as entry
    from unnest(app.communication_categories_v263()) with ordinality
      as catalog(category, ordinality)
  ) as category_row;
  return v_result;
end;
$$;

--
-- Name: customer_get_consent_history_v282(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_get_consent_history_v282(p_limit integer DEFAULT 100) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_identity uuid := app.customer_communication_identity_v263();
  v_limit integer := least(greatest(coalesce(p_limit, 100), 1), 200);
  v_entries jsonb;
begin
  select coalesce(jsonb_agg(entry order by occurred_at desc, ordering, entry_id), '[]'::jsonb)
    into v_entries
  from (
    select
      audit.occurred_at,
      1 as ordering,
      audit.id as entry_id,
      jsonb_build_object(
        'entry_kind', case when audit.scope = 'all'
          then 'marketing_all_channels' else 'marketing_channel' end,
        'occurred_at', audit.occurred_at,
        'enabled', audit.enabled,
        'category', audit.category,
        'channel', audit.channel,
        'source', audit.source,
        'scope_version', null
      ) as entry
      from public.customer_communication_preference_audit_v263 audit
     where audit.identity_id = v_identity
       and audit.auth_user_id = v_actor

    union all

    select
      consent.occurred_at,
      2 as ordering,
      consent.id as entry_id,
      jsonb_build_object(
        'entry_kind', 'platform_partner_marketing',
        'occurred_at', consent.occurred_at,
        'enabled', consent.opted_in,
        'category', null,
        'channel', null,
        'source', consent.source,
        'scope_version', consent.scope_version
      ) as entry
      from public.customer_platform_marketing_consent_events consent
     where consent.identity_id = v_identity
       and consent.auth_user_id = v_actor

    order by occurred_at desc, ordering, entry_id
    limit v_limit
  ) as history;

  return jsonb_build_object('entries', v_entries, 'limit', v_limit);
end;
$$;

--
-- Name: FUNCTION customer_get_consent_history_v282(p_limit integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.customer_get_consent_history_v282(p_limit integer) IS 'The caller''s own marketing consent evidence, newest first, from the v263 per-channel audit and the v92 platform/partner consent events. Own rows only; the identity is resolved from the session, never from an argument.';

--
-- Name: customer_get_effective_tier_v143(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_get_effective_tier_v143(p_business uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_identity uuid;
  v_client uuid;
  v_basis text;
  v_metric numeric:=0;
  v_points_programme uuid;
  v_current public.loyalty_tiers%rowtype;
  v_next public.loyalty_tiers%rowtype;
  v_progress numeric:=0;
  v_tiers jsonb:='[]'::jsonb;
  v_tiers_running boolean;
begin
  if auth.uid() is null then
    raise exception 'authenticated customer session required' using errcode='28000';
  end if;
  v_identity:=app.v31_current_identity();
  select link.client_id into v_client
  from public.customer_links link
  where link.identity_id=v_identity
    and link.auth_user_id=auth.uid()
    and link.business_id=p_business
    and link.state='verified';
  if not found then
    raise exception 'verified customer link required' using errcode='42501';
  end if;
  if not app.business_module_enabled_at_v117(p_business,'loyalty',null)
     or not exists(
       select 1 from public.loyalty_programs
       where business_id=p_business and active
     ) then
    raise exception 'loyalty module is unavailable for this business' using errcode='42501';
  end if;

  /* V371: the ladder is only the customer's business while the Tier membership programme is
     running. Turning it off used to change nothing here — this reader filters per-tier `paused`
     and `deleted_at` only, and its one business_programmes lookup below merely picks which points
     pot to count. The guard wraps the whole resolution once, so a query added inside it later
     cannot reintroduce the leak. */
  v_tiers_running:=app.programme_running_v371(p_business,'tiers');

  select coalesce(tier_basis,'visits') into v_basis
  from public.loyalty_programs
  where business_id=p_business and active
  limit 1;
  if v_basis='spend' then
    select coalesce(sum(amount_cents),0)/100.0 into v_metric from public.sales
    where business_id=p_business and client_id=v_client and counts_as_revenue;
  elsif v_basis='points_earned' then
    select spine.id into v_points_programme
    from public.business_programmes spine
    where spine.business_id=p_business and spine.kind='points';
    if v_points_programme is null then
      select coalesce(sum(points),0) into v_metric from public.points_ledger
      where business_id=p_business and client_id=v_client and entry_type='earn';
    else
      select coalesce(sum(ledger.points),0) into v_metric from public.points_ledger ledger
      where ledger.business_id=p_business and ledger.client_id=v_client
        and ledger.entry_type='earn' and ledger.programme_id=v_points_programme;
    end if;
  else
    select count(*) into v_metric from public.sales
    where business_id=p_business and client_id=v_client and counts_as_visit;
  end if;

  if v_tiers_running then
    select * into v_current from public.loyalty_tiers
    where business_id=p_business
      and threshold<=v_metric
      and deleted_at is null and not paused
      and (effective_from is null or effective_from<=statement_timestamp())
      and (expires_at is null or expires_at>statement_timestamp())
    order by threshold desc,sort desc,id limit 1;
    select * into v_next from public.loyalty_tiers
    where business_id=p_business
      and threshold>coalesce(v_current.threshold,-1)
      and deleted_at is null and not paused
      and (effective_from is null or effective_from<=statement_timestamp())
      and (expires_at is null or expires_at>statement_timestamp())
    order by threshold,sort,id limit 1;
    if v_next.id is not null then
      v_progress:=greatest(0,least(100,round(
        (v_metric-coalesce(v_current.threshold,0))*100
        /nullif(v_next.threshold-coalesce(v_current.threshold,0),0),2
      )));
    elsif v_current.id is not null then
      v_progress:=100;
    end if;

    select coalesce(jsonb_agg(jsonb_build_object(
      'id',ladder.id,
      'label',ladder.name,
      'threshold',ladder.threshold,
      'achieved',ladder.threshold<=v_metric,
      'current',ladder.id=v_current.id,
      'benefits',coalesce((
        select jsonb_agg(btrim(benefit) order by ordinal)
        from regexp_split_to_table(coalesce(ladder.perk_note,''),E'\\r?\\n')
          with ordinality as item(benefit,ordinal)
        where btrim(benefit)<>''
      ),'[]'::jsonb)
    ) order by ladder.threshold,ladder.sort,ladder.id),'[]'::jsonb) into v_tiers
    from public.loyalty_tiers ladder
    where ladder.business_id=p_business
      and ladder.deleted_at is null and not ladder.paused
      and (ladder.effective_from is null or ladder.effective_from<=statement_timestamp())
      and (ladder.expires_at is null or ladder.expires_at>statement_timestamp());
  end if;

  return jsonb_build_object('tier',jsonb_build_object(
    'points_mode',(select points_mode from public.businesses where id=p_business),
    'label',v_current.name,
    'current',case when v_current.id is null then null else jsonb_build_object(
      'id',v_current.id,'label',v_current.name,'threshold',v_current.threshold,
      'metric',v_metric,'benefits',coalesce((
        select jsonb_agg(btrim(benefit) order by ordinal)
        from regexp_split_to_table(coalesce(v_current.perk_note,''),E'\\r?\\n')
          with ordinality as item(benefit,ordinal)
        where btrim(benefit)<>''
      ),'[]'::jsonb)
    ) end,
    'next',case when v_next.id is null then null else jsonb_build_object(
      'id',v_next.id,'label',v_next.name,'threshold',v_next.threshold,
      'benefits',coalesce((
        select jsonb_agg(btrim(benefit) order by ordinal)
        from regexp_split_to_table(coalesce(v_next.perk_note,''),E'\\r?\\n')
          with ordinality as item(benefit,ordinal)
        where btrim(benefit)<>''
      ),'[]'::jsonb)
    ) end,
    'tiers',v_tiers,
    'progress_percent',v_progress,'basis',v_basis,'metric',v_metric,
    'tier_fuel','points_programme_earn','balance_scope',app.programme_balance_scope_v312(p_business)
  ));
end
$$;

--
-- Name: FUNCTION customer_get_effective_tier_v143(p_business uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.customer_get_effective_tier_v143(p_business uuid) IS 'v310 D1: on tier_basis=''points_earned'' the metric is the POINTS programme''s lifetime earn (v308 spine row), with an explicit fail-OPEN fallback to the unfiltered sum when that spine row is missing — a missing row must never zero a tier. Adds tier_fuel and balance_scope. v186 ladder, v230 points_mode and every other key unchanged.';

--
-- Name: customer_get_gift_cards(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_get_gift_cards(p_business_slug text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_context record;
  v_cards jsonb;
  v_count integer;
  v_total bigint;
begin
  if auth.uid() is null then
    raise exception 'authenticated customer session required' using errcode = '28000';
  end if;

  -- The app context resolves auth.uid() through customer_links with link status = 'verified'.
  select identity_id, business_id, client_id, business_name, business_slug,
         business_industry, business_currency, enabled_modules into v_context
    from app.v32_customer_wallet_context(p_business_slug)
   limit 1;
  if not found then
    raise exception 'verified customer link required' using errcode = '42501';
  end if;

  -- Totals over the FULL matching set, so a bounded list never understates the balance.
  select count(*)::integer, coalesce(sum(g.balance_cents), 0)::bigint
    into v_count, v_total
    from public.gift_cards g
   where g.business_id = v_context.business_id
     and v_context.client_id is not null
     and g.purchaser_client_id = v_context.client_id;

  -- Explicit customer-safe projection. The bearer code is masked to its last 4 characters, the same
  -- masking the two staff readers of this table already use; recipient_email and purchaser_client_id
  -- are never projected.
  select coalesce(jsonb_agg(jsonb_build_object(
    'gift_card_id', listed.id,
    'code_suffix', right(listed.code, 4),
    'initial_cents', listed.initial_cents,
    'balance_cents', listed.balance_cents,
    'status', listed.status,
    'created_at', listed.created_at
  ) order by listed.created_at desc, listed.id desc), '[]'::jsonb)
    into v_cards
    from (
      select g.id, g.code, g.initial_cents, g.balance_cents, g.status, g.created_at
        from public.gift_cards g
       where g.business_id = v_context.business_id
         and v_context.client_id is not null
         and g.purchaser_client_id = v_context.client_id
       order by g.created_at desc, g.id desc
       limit 100
    ) listed;

  return jsonb_build_object(
    'business', jsonb_build_object(
      'slug', v_context.business_slug,
      'name', v_context.business_name,
      'currency', v_context.business_currency
    ),
    'cards', v_cards,
    'count', v_count,
    'total_balance_cents', v_total,
    'truncated', v_count > jsonb_array_length(v_cards)
  );
end;
$$;

--
-- Name: customer_get_growth_offers_v108(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_get_growth_offers_v108(p_business uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_identity uuid;
  v_client uuid;
begin
  select identity_row.id into v_identity
    from public.customer_identities identity_row
   where identity_row.auth_user_id=auth.uid()
     and identity_row.status='active';
  if v_identity is null then
    raise exception 'active customer identity required' using errcode='42501';
  end if;
  v_client:=app.v113_customer_effective_client_id(p_business,v_identity);

  with expired as (
    update public.growth_entitlements_v108 entitlement
       set status='expired'
     where entitlement.business_id=p_business
       and app.v113_effective_client_id(
             entitlement.business_id,entitlement.client_id
           )=v_client
       and entitlement.status='issued'
       and entitlement.expires_at<=statement_timestamp()
    returning entitlement.id,entitlement.business_id,entitlement.expires_at
  )
  insert into public.growth_entitlement_events_v108(
    entitlement_id,business_id,event_type,actor,idempotency_key,detail
  )
  select expired.id,expired.business_id,'expired',auth.uid(),
    extensions.uuid_generate_v5(expired.id,'expired'),
    jsonb_build_object('expired_at',expired.expires_at)
  from expired
  on conflict do nothing;

  return jsonb_build_object(
    'business_id',p_business,
    'identity_attribution','v111_current_effective_identity',
    'offers',coalesce((
      select jsonb_agg(jsonb_build_object(
        'entitlement_id',entitlement.id,
        'label',execution.offer_label,
        'type',entitlement.entitlement_type,
        'value_cents',entitlement.value_cents,
        'currency',execution.currency,
        'governed_copy',execution.governed_copy,
        'status',entitlement.status,
        'issued_at',entitlement.issued_at,
        'expires_at',entitlement.expires_at,
        'redeemed_at',entitlement.redeemed_at
      ) order by entitlement.issued_at desc,entitlement.id desc)
      from public.growth_entitlements_v108 entitlement
      join public.growth_executions_v108 execution
        on execution.id=entitlement.execution_id
      where entitlement.business_id=p_business
        and app.v113_effective_client_id(
              entitlement.business_id,entitlement.client_id
            )=v_client
    ),'[]'::jsonb)
  );
end
$$;

--
-- Name: customer_get_home_offers_v167(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_get_home_offers_v167(p_locale text DEFAULT 'en'::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_identity uuid;
  v_items jsonb;
  v_pending_redemption jsonb;
  v_truncated boolean := false;
begin
  if v_actor is null then
    raise exception 'authenticated_customer_session_required' using errcode='28000';
  end if;
  if p_locale not in ('en','zh-CN') then
    raise exception 'supported_locale_required' using errcode='22023';
  end if;
  v_identity := app.v31_current_identity();

  select jsonb_build_object(
    'intent_id',intent.id,
    'expires_at',intent.expires_at,
    'business',jsonb_build_object(
      'id',business.id,
      'slug',business.slug,
      'name',business.name
    ),
    'reward_name',coalesce(reward.name,'reward')
  ) into v_pending_redemption
  from public.customer_redemption_intents_v89 intent
  join public.businesses business on business.id=intent.business_id
  left join public.loyalty_rewards reward on reward.id=intent.reward_id
  where intent.identity_id=v_identity
    and intent.auth_user_id=v_actor
    and intent.status='pending'
    and intent.expires_at>statement_timestamp()
  order by intent.created_at desc,intent.id
  limit 1;

  -- v32_customer_wallet_context is the canonical verified-link resolver. The
  -- caller cannot nominate a customer, identity, business, or tenant.
  with ranked as (
    select
      content.id,
      content.version,
      content.updated_at,
      content.display_order,
      content.starts_at,
      content.ends_at,
      content.metadata,
      context.business_id,
      context.business_slug,
      context.business_name,
      coalesce(copy.name,english.name,'Offer') name,
      coalesce(copy.tagline,english.tagline) tagline,
      coalesce(copy.description,english.description) description,
      coalesce(copy.terms,english.terms) terms,
      media.url image_url,
      media.image_alt,
      app.v95_public_media_url(logo.object_path) logo_url,
      branches.names branch_names,
      exists(select 1 from public.promotion_branch_scopes_v155 mapped where mapped.promotion_id=content.id) branch_scoped,
      row_number() over(order by
        content.ends_at asc,
        content.display_order asc,
        content.updated_at desc,
        content.id
      ) item_rank
    from app.v32_customer_wallet_context(null) context
    join public.business_customer_content_v95 content
      on content.business_id=context.business_id
     and content.content_type='offer'
     and content.active
     and content.branch_id is null
     and (content.starts_at is null or content.starts_at<=statement_timestamp())
     and content.ends_at>statement_timestamp()
     and (
       not exists(select 1 from public.promotion_branch_scopes_v155 mapped where mapped.promotion_id=content.id)
       or exists(
         select 1
         from public.promotion_branch_scopes_v155 mapped
         join public.branches active_branch
           on active_branch.id=mapped.branch_id
          and active_branch.business_id=context.business_id
          and coalesce(active_branch.active,true)
         where mapped.promotion_id=content.id
           and mapped.business_id=context.business_id
       )
     )
    left join public.business_localized_copy_v95 copy
      on copy.business_id=context.business_id
     and copy.entity_type='offer'
     and copy.entity_id=content.id
     and copy.locale=p_locale
    left join public.business_localized_copy_v95 english
      on english.business_id=context.business_id
     and english.entity_type='offer'
     and english.entity_id=content.id
     and english.locale='en'
    left join lateral(
      select app.v95_public_media_url(asset.object_path) url,
        case when p_locale='zh-CN'
          then coalesce(asset.alt_zh_cn,asset.alt_en)
          else asset.alt_en
        end image_alt
      from public.business_media_assets_v95 asset
      where asset.business_id=context.business_id
        and asset.asset_kind='offer'
        and asset.entity_id=content.id
        and asset.customer_visible
        and asset.branch_id is null
      order by asset.updated_at desc,asset.id
      limit 1
    ) media on true
    left join public.business_brand_presentation_v95 brand
      on brand.business_id=context.business_id
    left join public.business_media_assets_v95 logo
      on logo.id=brand.logo_asset_id
     and logo.business_id=context.business_id
     and logo.asset_kind='logo'
     and logo.customer_visible
    left join lateral(
      select coalesce(jsonb_agg(branch.name order by branch.name),'[]'::jsonb) names
      from public.promotion_branch_scopes_v155 mapped
      join public.branches branch
        on branch.id=mapped.branch_id
       and branch.business_id=context.business_id
       and coalesce(branch.active,true)
      where mapped.promotion_id=content.id
        and mapped.business_id=context.business_id
    ) branches on true
  ), bounded as (
    select * from ranked where item_rank<=13
  )
  select
    coalesce(jsonb_agg(jsonb_build_object(
      'id',bounded.id,
      'version_id',bounded.id::text||':'||bounded.version::text,
      'name',bounded.name,
      'tagline',bounded.tagline,
      'description',bounded.description,
      'terms',bounded.terms,
      'image_url',bounded.image_url,
      'image_alt',bounded.image_alt,
      'starts_at',bounded.starts_at,
      'ends_at',bounded.ends_at,
      'display_order',bounded.display_order,
      'metadata',bounded.metadata,
      'business',jsonb_build_object(
        'id',bounded.business_id,
        'slug',bounded.business_slug,
        'name',bounded.business_name,
        'logo_url',bounded.logo_url
      ),
      'branch_names',bounded.branch_names,
      'availability_label',case
        when bounded.branch_scoped then 'Available at '||(
          select string_agg(value,' and ' order by value)
          from jsonb_array_elements_text(bounded.branch_names) value
        )
        else 'Available at all branches'
      end
    ) order by bounded.item_rank) filter(where bounded.item_rank<=12),'[]'::jsonb),
    coalesce(bool_or(bounded.item_rank>12),false)
  into v_items,v_truncated
  from bounded;

  return jsonb_build_object(
    'as_of',statement_timestamp(),
    'items',v_items,
    'pending_redemption',v_pending_redemption,
    'limit',12,
    'truncated',v_truncated
  );
end
$$;

--
-- Name: FUNCTION customer_get_home_offers_v167(p_locale text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.customer_get_home_offers_v167(p_locale text) IS 'At most twelve current offers across auth.uid() verified customer links; no caller-supplied ownership identifier.';

--
-- Name: customer_get_identity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_get_identity() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_identity public.customer_identities%rowtype;
  v_contact_types jsonb;
begin
  if v_actor is null then
    raise exception 'authenticated customer session required' using errcode = '28000';
  end if;
  if not app.platform_feature_enabled('customer_identity') then
    raise exception 'customer access is unavailable' using errcode = '0A000';
  end if;

  select * into v_identity
    from public.customer_identities
   where auth_user_id = v_actor;
  if not found then
    return jsonb_build_object('identity', null);
  end if;

  select coalesce(jsonb_agg(c.contact_type order by c.contact_type), '[]'::jsonb)
    into v_contact_types
    from public.customer_verified_contacts c
   where c.identity_id = v_identity.id
     and c.status = 'verified';

  return jsonb_build_object(
    'identity_id', v_identity.id,
    'status', v_identity.status,
    'created_at', v_identity.created_at,
    'verified_contact_types', v_contact_types
  );
end;
$$;

--
-- Name: customer_get_in_app_inbox_count(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_get_in_app_inbox_count(p_business_slug text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_context record; v_unread integer; v_quiet boolean; v_actionable_source_available boolean;
begin
  if not app.platform_feature_enabled('customer_in_app_inbox') then
    raise exception 'customer in-app inbox is not enabled' using errcode='0A000';
  end if;
  select * into v_context from app.c46_customer_inbox_context(p_business_slug);
  v_actionable_source_available:=app.platform_feature_enabled('customer_actionable_wallet');
  select count(*)::integer into v_unread
    from public.customer_in_app_inbox_events e
    left join public.customer_in_app_inbox_state s on s.event_id=e.id
    left join public.customer_in_app_inbox_resolutions r on r.event_id=e.id
   where e.business_id=v_context.business_id and e.identity_id=v_context.identity_id
     and e.link_id=v_context.link_id and r.id is null and s.dismissed_at is null and s.read_at is null
     and app.c46_inbox_source_available(e.source_kind,v_actionable_source_available);
  select exists (
    select 1 from (values ('value_expiry'::text),('reward_ready'::text),('visit_progress'::text),
                         ('birthday_benefit'::text),('booking_updates'::text)) topics(topic)
    join lateral app.c46_in_app_preference_for_context(
      v_context.business_id,v_context.identity_id,v_context.link_id,topics.topic
    ) p on true
    where p.opted_in and (v_actionable_source_available or topics.topic='booking_updates')
      and app.c46_in_quiet_hours(
      p.quiet_hours_timezone,p.quiet_hours_start,p.quiet_hours_end,statement_timestamp()
    )
  ) into v_quiet;
  return jsonb_build_object('unread_count',v_unread,'quiet_hours_active',v_quiet,
    'actionable_source_available',v_actionable_source_available);
end;
$$;

--
-- Name: customer_get_in_app_inbox_global_count(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_get_in_app_inbox_global_count() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_context record; v_unread integer; v_quiet boolean; v_actionable_source_available boolean;
begin
  if not app.platform_feature_enabled('customer_in_app_inbox') then
    raise exception 'customer in-app inbox is not enabled' using errcode='0A000';
  end if;
  select * into v_context from app.c46_customer_inbox_global_context();
  v_actionable_source_available:=app.platform_feature_enabled('customer_actionable_wallet');
  select count(*)::integer into v_unread
    from public.customer_in_app_inbox_events e
    join public.customer_links cl on cl.id=e.link_id and cl.business_id=e.business_id
      and cl.client_id=e.client_id and cl.identity_id=e.identity_id and cl.auth_user_id=v_context.auth_user_id
      and cl.state='verified'
    left join public.customer_in_app_inbox_state s on s.event_id=e.id
    left join public.customer_in_app_inbox_resolutions r on r.event_id=e.id
   where e.identity_id=v_context.identity_id and e.auth_user_id=v_context.auth_user_id
     and r.id is null and s.dismissed_at is null and s.read_at is null
     and app.c46_inbox_source_available(e.source_kind,v_actionable_source_available);
  select exists (
    select 1 from public.customer_links cl
    join public.customer_notification_preferences p
      on p.business_id=cl.business_id and p.identity_id=cl.identity_id and p.link_id=cl.id
     and p.client_id=cl.client_id and p.channel='in_app' and p.opted_in
    where cl.identity_id=v_context.identity_id and cl.auth_user_id=v_context.auth_user_id and cl.state='verified'
      and p.topic in ('value_expiry','reward_ready','visit_progress','birthday_benefit','booking_updates')
      and (v_actionable_source_available or p.topic='booking_updates')
      and app.c46_in_quiet_hours(p.quiet_hours_timezone,p.quiet_hours_start,p.quiet_hours_end,statement_timestamp())
  ) into v_quiet;
  return jsonb_build_object('unread_count',v_unread,'quiet_hours_active',v_quiet,
    'actionable_source_available',v_actionable_source_available);
end;
$$;

--
-- Name: customer_get_in_app_inbox_preferences(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_get_in_app_inbox_preferences(p_business_slug text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_context record;
begin
  if not app.platform_feature_enabled('customer_in_app_inbox') then
    raise exception 'customer in-app inbox is not enabled' using errcode='0A000';
  end if;
  select * into v_context from app.c46_customer_inbox_context(p_business_slug);
  return coalesce((
    select jsonb_agg(jsonb_build_object(
      'topic',topics.topic,'opted_in',coalesce(preference.opted_in,false),
      'quiet_hours_timezone',preference.quiet_hours_timezone,
      'quiet_hours_start',preference.quiet_hours_start,
      'quiet_hours_end',preference.quiet_hours_end
    ) order by topics.ordinal)
    from (values
      (1,'value_expiry'::text),(2,'reward_ready'::text),
      (3,'visit_progress'::text),(4,'birthday_benefit'::text),
      (5,'booking_updates'::text),(6,'promotion_alerts'::text)
    ) topics(ordinal,topic)
    left join public.customer_notification_preferences preference
      on preference.business_id=v_context.business_id
     and preference.identity_id=v_context.identity_id
     and preference.link_id=v_context.link_id
     and preference.channel='in_app'
     and preference.topic=topics.topic
  ),'[]'::jsonb);
end
$$;

--
-- Name: customer_get_locale_preference_v95(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_get_locale_preference_v95() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_actor uuid:=auth.uid();v_row public.customer_locale_preferences_v95%rowtype;
begin
  if v_actor is null then raise exception 'authenticated_session_required'
    using errcode='28000';end if;
  select * into v_row from public.customer_locale_preferences_v95
  where auth_user_id=v_actor;
  return jsonb_build_object(
    'locale',coalesce(v_row.locale,'en'),'version',coalesce(v_row.version,0)
  );
end
$$;

--
-- Name: customer_get_loyalty_details(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_get_loyalty_details(p_business_slug text, p_cursor jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_context record;
  v_program public.loyalty_programs%rowtype;
  v_cursor jsonb:=coalesce(p_cursor,'{}'::jsonb);
  v_limit integer:=20;
  v_before_at timestamptz;
  v_before_id uuid;
  v_result jsonb;
begin
  if auth.uid() is null then
    raise exception 'authenticated customer session required'
      using errcode='28000';
  end if;
  if pg_catalog.jsonb_typeof(v_cursor)<>'object'
     or exists(
       select 1
       from pg_catalog.jsonb_object_keys(v_cursor) as keys(key)
       where keys.key not in ('limit','before_at','before_id')
     ) then
    raise exception 'invalid loyalty activity cursor' using errcode='22023';
  end if;
  begin
    v_limit:=least(
      greatest(coalesce((v_cursor->>'limit')::integer,20),1),50
    );
    v_before_at:=nullif(v_cursor->>'before_at','')::timestamptz;
    v_before_id:=nullif(v_cursor->>'before_id','')::uuid;
  exception when others then
    raise exception 'invalid loyalty activity cursor' using errcode='22023';
  end;
  if (v_before_at is null)<>(v_before_id is null) then
    raise exception 'loyalty activity cursor is incomplete'
      using errcode='22023';
  end if;

  select * into v_context
  from app.v32_customer_wallet_context(p_business_slug)
  limit 1;
  if not found then
    raise exception 'verified customer link required' using errcode='42501';
  end if;
  if not ('loyalty'=any(v_context.enabled_modules)) then
    raise exception 'loyalty module is unavailable for this business'
      using errcode='42501';
  end if;
  select * into v_program
  from public.loyalty_programs program
  where program.business_id=v_context.business_id
    and program.active
  limit 1;
  if not found then
    raise exception 'loyalty module is unavailable for this business'
      using errcode='42501';
  end if;

  with activity as (
    select
      ledger.id,
      ledger.created_at as event_at,
      ledger.entry_type as event_type,
      ledger.points::integer as points_delta,
      case ledger.entry_type
        when 'earn' then 'Points earned'
        when 'expire' then 'Points expired'
        when 'adjust' then 'Balance adjustment'
        else 'Loyalty activity'
      end as title,
      null::text as detail,
      null::text as status,
      null::timestamptz as entitlement_expires_at,
      false as is_campaign_entitlement,
      null::text as entitlement_status,
      null::text as fulfillment_status,
      null::text as redemption_mode,
      null::boolean as economic_value_posted,
      null::text as fulfillment_kind,
      null::text as reward_label,
      false as reward_value_hidden,
      null::text as display_label,
      null::bigint as display_amount_cents
    from public.points_ledger ledger
    where ledger.business_id=v_context.business_id
      and ledger.client_id=v_context.client_id
      and ledger.entry_type in ('earn','expire','adjust')
    union all
    select
      redemption.id,
      redemption.redeemed_at,
      'reward_claimed',
      -redemption.points_spent,
      redemption.reward_name,
      null::text,
      case when reversal.id is null then 'claimed' else 'reversed' end,
      redemption.entitlement_expires_at,
      false,null::text,null::text,null::text,null::boolean,
      null::text,redemption.reward_name,false,redemption.reward_name,
      null::bigint
    from public.loyalty_redemptions redemption
    left join public.loyalty_redemption_reversals reversal
      on reversal.business_id=redemption.business_id
     and reversal.redemption_id=redemption.id
    where redemption.business_id=v_context.business_id
      and redemption.client_id=v_context.client_id
    union all
    select
      reward.id,
      reward.granted_at,
      case when reward.campaign_id is not null
        then 'campaign_offer_entitlement'
        else 'retention_reward'
      end,
      0,
      case when reward.campaign_id is not null
        then 'Offer awaiting merchant fulfilment'
        else coalesce(
          nullif(btrim(reward.reward_label),''),'Reward earned'
        )
      end,
      case when reward.campaign_id is not null
        then 'No wallet value has been posted. Ask the business to fulfil this offer.'
        else null::text
      end,
      case
        when reward.campaign_id is not null and reward.status='expired'
          then 'expired_unfulfilled'
        when reward.campaign_id is not null
          then 'merchant_fulfilment_pending'
        else reward.status
      end,
      null::timestamptz,
      reward.campaign_id is not null,
      reward.status,
      case
        when reward.campaign_id is not null and reward.status='expired'
          then 'expired_unfulfilled'
        when reward.campaign_id is not null
          then 'merchant_fulfilment_pending'
        else reward.status
      end,
      case when reward.campaign_id is not null
        then 'merchant_fulfilment_pending'
        else null::text
      end,
      case when reward.campaign_id is not null then false else null::boolean end,
      reward.fulfillment_kind,
      reward.reward_label,
      reward.campaign_id is not null,
      case when reward.campaign_id is not null
        then 'Offer awaiting merchant fulfilment'
        else coalesce(nullif(btrim(reward.reward_label),''),'Reward')
      end,
      case
        when reward.campaign_id is null
         and reward.fulfillment_kind='credit'
          then reward.reward_value::bigint
        else null::bigint
      end
    from public.reward_grants reward
    where reward.business_id=v_context.business_id
      and reward.client_id=v_context.client_id
  ), eligible as (
    select *
    from activity
    where v_before_at is null
       or (event_at,id)<(v_before_at,v_before_id)
    order by event_at desc,id desc
    limit v_limit+1
  ), visible as (
    select * from eligible order by event_at desc,id desc limit v_limit
  )
  select pg_catalog.jsonb_build_object(
    'model',v_program.loyalty_model,
    'unit',case when v_program.loyalty_model='stamps'
      then 'stamps' else 'points' end,
    'programme',pg_catalog.jsonb_build_object(
      'kind',case when v_program.loyalty_model='stamps' then 'stamps' else 'points' end,
      'active',coalesce((
        select spine.active from public.business_programmes spine
         where spine.business_id=v_context.business_id
           and spine.kind=case when v_program.loyalty_model='stamps'
                               then 'stamps' else 'points' end),false),
      'balance_scope',app.programme_balance_scope_v312(v_context.business_id)),
    'balance',app.client_points_balance_v409(v_context.business_id,v_context.client_id),
    'expiry',pg_catalog.jsonb_build_object(
      'expiring_next_30_days',coalesce((
        select sum(batch.remaining)::integer
        from public.points_batches batch
        where batch.business_id=v_context.business_id
          and batch.client_id=v_context.client_id
          and batch.remaining>0
          and batch.expires_at>now()
          and batch.expires_at<=now()+interval '30 days'
      ),0),
      'next_expiry_at',(
        select min(batch.expires_at)
        from public.points_batches batch
        where batch.business_id=v_context.business_id
          and batch.client_id=v_context.client_id
          and batch.remaining>0
          and batch.expires_at>now()
      )
    ),
    'items',coalesce((
      select pg_catalog.jsonb_agg(
        pg_catalog.jsonb_build_object(
          'event_at',event_at,
          'event_type',event_type,
          'points_delta',points_delta,
          'title',title,
          'detail',detail,
          'status',status,
          'entitlement_expires_at',entitlement_expires_at,
          'is_campaign_entitlement',is_campaign_entitlement,
          'entitlement_status',entitlement_status,
          'fulfillment_status',fulfillment_status,
          'redemption_mode',redemption_mode,
          'economic_value_posted',economic_value_posted,
          'fulfillment_kind',fulfillment_kind,
          'reward_label',reward_label,
          'reward_value_hidden',reward_value_hidden,
          'display_label',display_label,
          'display_amount_cents',display_amount_cents
        )
        order by event_at desc,id desc
      )
      from visible
    ),'[]'::jsonb),
    'next_cursor',case
      when (select count(*) from eligible)>v_limit then (
        select pg_catalog.jsonb_build_object(
          'before_at',event_at,'before_id',id,'limit',v_limit
        )
        from visible order by event_at,id limit 1
      )
      else null
    end
  ) into v_result;
  return v_result;
end
$$;

--
-- Name: customer_get_member_qr_v327(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_get_member_qr_v327() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_identity public.customer_identities%rowtype;
  v_token text;
  v_hash text;
begin
  if v_actor is null then
    raise exception 'authenticated customer session required' using errcode='28000';
  end if;
  if not app.platform_feature_enabled('customer_identity') then
    raise exception 'customer access is unavailable' using errcode='0A000';
  end if;

  select * into v_identity from public.customer_identities
   where auth_user_id=v_actor for update;
  if not found then
    raise exception 'a platform identity is required before a member QR can be issued'
      using errcode='42501';
  end if;
  if v_identity.status <> 'active' then
    raise exception 'this platform identity is not active' using errcode='42501';
  end if;

  v_token := app.v327_member_qr_token(v_identity.id, v_identity.qr_token_version);
  v_hash := app.v89_sha256(v_token);
  if v_identity.qr_token_hash is distinct from v_hash then
    update public.customer_identities
       set qr_token_hash = v_hash, updated_at = now()
     where id = v_identity.id;
  end if;

  return jsonb_build_object(
    'identity_id', v_identity.id,
    'member_qr', 'nestly:member:'||v_token,
    'token_version', v_identity.qr_token_version
  );
end $$;

--
-- Name: customer_get_memberships(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_get_memberships(p_business_slug text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_context record;
  v_result jsonb;
begin
  if auth.uid() is null then
    raise exception 'authenticated customer session required' using errcode = '28000';
  end if;
  select * into v_context from app.v32_customer_wallet_context(p_business_slug) limit 1;
  if not found then
    raise exception 'verified customer link required' using errcode = '42501';
  end if;
  if not ('memberships' = any(v_context.enabled_modules)) then
    raise exception 'memberships module is unavailable for this business' using errcode = '42501';
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
    'plan_name', listed.plan_name,
    'cadence', listed.cadence,
    'status', listed.status,
    'current_period_start', listed.current_period_start,
    'current_period_end', listed.current_period_end
  ) order by listed.current_period_end desc, listed.id desc), '[]'::jsonb)
  into v_result
  from (
    select m.id, mp.name as plan_name, mp.cadence, m.status,
           m.current_period_start, m.current_period_end
      from public.memberships m
      join public.membership_plans mp
        on mp.id = m.plan_id and mp.business_id = m.business_id
     where m.business_id = v_context.business_id
       and m.client_id = v_context.client_id
     order by m.current_period_end desc, m.id desc
     limit 20
  ) listed;

  return v_result;
end;
$$;

--
-- Name: customer_get_notification_preferences(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_get_notification_preferences(p_business_slug text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_identity_id uuid;
  v_link_id uuid;
  v_business_id uuid;
begin
  if v_actor is null then
    raise exception 'authenticated customer session required' using errcode = '28000';
  end if;
  if not app.platform_feature_enabled('customer_notifications') then
    raise exception 'verified customer link required' using errcode = '42501';
  end if;
  select ci.id, l.id, l.business_id
    into v_identity_id, v_link_id, v_business_id
    from public.customer_identities ci
    join public.customer_links l
      on l.identity_id = ci.id and l.auth_user_id = v_actor and l.state = 'verified'
    join public.businesses b on b.id = l.business_id
   where ci.auth_user_id = v_actor and ci.status = 'active'
     and b.slug = lower(btrim(coalesce(p_business_slug, '')))
   limit 1;
  if not found then
    raise exception 'verified customer link required' using errcode = '42501';
  end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object(
      'channel', p.channel,
      'topic', p.topic,
      'opted_in', p.opted_in,
      'consent_at', p.consent_at
    ) order by p.channel, p.topic)
      from public.customer_notification_preferences p
     where p.business_id = v_business_id
       and p.identity_id = v_identity_id
       and p.link_id = v_link_id
  ), '[]'::jsonb);
end;
$$;

--
-- Name: customer_get_offer_business_contact_v173(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_get_offer_business_contact_v173(p_business uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_identity uuid;
  v_result jsonb;
begin
  if v_actor is null then
    raise exception 'authenticated_session_required' using errcode='28000';
  end if;
  if p_business is null then
    raise exception 'business_required' using errcode='22023';
  end if;
  v_identity := app.v31_current_identity();
  if not exists(
    select 1 from public.customer_links link
    where link.identity_id = v_identity
      and link.auth_user_id = v_actor
      and link.business_id = p_business
      and link.state = 'verified'
  ) then
    raise exception 'verified_customer_link_required' using errcode='42501';
  end if;

  select jsonb_build_object(
    'business', jsonb_build_object(
      'id', business.id,
      'slug', business.slug,
      'name', business.name
    ),
    'branch', case when branch.id is null then null else jsonb_build_object(
      'name', branch.name,
      'address', branch.address,
      'phone', branch.phone,
      'email', branch.email
    ) end,
    -- v386: every active branch, default first, then oldest first — the SAME ordering the
    -- default-branch lateral uses, so branches[0] is always the object in `branch`.
    'branches', coalesce(all_branches.items, '[]'::jsonb)
  ) into v_result
  from public.businesses business
  left join lateral (
    select b.id, b.name, b.address, b.phone, b.email
    from public.branches b
    where b.business_id = business.id and coalesce(b.active,true)
    order by b.is_default desc, b.created_at, b.id
    limit 1
  ) branch on true
  left join lateral (
    select jsonb_agg(jsonb_build_object(
      'name', b.name,
      'address', b.address,
      'phone', b.phone,
      'email', b.email
    ) order by b.is_default desc, b.created_at, b.id) as items
    from public.branches b
    where b.business_id = business.id and coalesce(b.active,true)
  ) all_branches on true
  where business.id = p_business;

  return v_result;
end
$$;

--
-- Name: FUNCTION customer_get_offer_business_contact_v173(p_business uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.customer_get_offer_business_contact_v173(p_business uuid) IS 'Default-branch contact plus (v386) every active branch, for the customer offer-detail and company-details sheets; requires an auth.uid() verified customer link to the business.';

--
-- Name: customer_get_packages(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_get_packages(p_business_slug text, p_cursor jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_context record;
  v_cursor jsonb := coalesce(p_cursor, '{}'::jsonb);
  v_limit integer := 20;
  v_before_at timestamptz;
  v_before_id uuid;
  v_result jsonb;
begin
  if auth.uid() is null then
    raise exception 'authenticated customer session required' using errcode = '28000';
  end if;
  if jsonb_typeof(v_cursor) <> 'object' then
    raise exception 'invalid packages cursor' using errcode = '22023';
  end if;
  if exists (select 1 from jsonb_object_keys(v_cursor) as keys(key) where key not in ('limit','before_at','before_id')) then
    raise exception 'invalid packages cursor' using errcode = '22023';
  end if;
  begin
    v_limit := least(greatest(coalesce((v_cursor->>'limit')::integer, 20), 1), 50);
    v_before_at := nullif(v_cursor->>'before_at', '')::timestamptz;
    v_before_id := nullif(v_cursor->>'before_id', '')::uuid;
  exception when others then
    raise exception 'invalid packages cursor' using errcode = '22023';
  end;
  if (v_before_at is null) <> (v_before_id is null) then
    raise exception 'packages cursor is incomplete' using errcode = '22023';
  end if;

  select * into v_context from app.v32_customer_wallet_context(p_business_slug) limit 1;
  if not found then
    raise exception 'verified customer link required' using errcode = '42501';
  end if;
  if not ('packages' = any(v_context.enabled_modules)) then
    raise exception 'packages module is unavailable for this business' using errcode = '42501';
  end if;

  with packages as (
    select cp.id,
           coalesce(nullif(to_jsonb(cp)->>'purchased_at','')::timestamptz,
                    nullif(to_jsonb(cp)->>'created_at','')::timestamptz,
                    'epoch'::timestamptz) as sort_at,
           nullif(to_jsonb(cp)->>'purchased_at','')::timestamptz as purchased_at,
           nullif(to_jsonb(cp)->>'expires_at','')::timestamptz as expires_at,
           pp.name as plan_name, pp.sessions as sessions_purchased,
           cp.remaining as sessions_remaining, cp.status,
           coalesce((
             select jsonb_agg(jsonb_build_object(
               'used_at', history.created_at,
               'remaining_after', history.remaining_after,
               'status', case when history.reversed then 'reversed' else 'used' end
             ) order by history.created_at desc)
             from (
               select use.created_at, use.remaining_after,
                      exists (select 1 from public.package_session_reversals rev
                               where rev.business_id = use.business_id and rev.consumption_id = use.id) as reversed
                 from public.package_session_consumptions use
                where use.business_id = v_context.business_id
                  and use.client_id = v_context.client_id
                  and use.client_package_id = cp.id
                order by use.created_at desc, use.id desc
                limit 10
             ) history
           ), '[]'::jsonb) as usage_history
      from public.client_packages cp
      join public.package_plans pp
        on pp.id = cp.plan_id and pp.business_id = cp.business_id
     where cp.business_id = v_context.business_id
       and cp.client_id = v_context.client_id
  ), eligible as (
    select * from packages
     where v_before_at is null or (sort_at, id) < (v_before_at, v_before_id)
     order by sort_at desc, id desc limit v_limit + 1
  ), visible as (
    select * from eligible order by sort_at desc, id desc limit v_limit
  )
  select jsonb_build_object(
    'items', coalesce((select jsonb_agg(jsonb_build_object(
      'plan_name', plan_name, 'sessions_purchased', sessions_purchased,
      'sessions_remaining', sessions_remaining, 'status', status,
      'purchased_at', purchased_at, 'expires_at', expires_at,
      'usage_history', usage_history
    ) order by sort_at desc, id desc) from visible), '[]'::jsonb),
    'next_cursor', case when (select count(*) from eligible) > v_limit then (
      select jsonb_build_object('before_at', sort_at, 'before_id', id, 'limit', v_limit)
        from visible order by sort_at, id limit 1
    ) else null end
  ) into v_result;

  return v_result;
end;
$$;

--
-- Name: customer_get_pending_promotion_prompt_v122(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_get_pending_promotion_prompt_v122(p_business_slug text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_context record;v_prompt jsonb;
begin
  if not app.platform_feature_enabled('customer_in_app_inbox') then
    raise exception 'customer in-app inbox is not enabled' using errcode='0A000';
  end if;
  select * into v_context from app.c46_customer_inbox_context(p_business_slug);
  select jsonb_build_object(
    'event_id',event.id,'source_kind',event.source_kind,
    'title',event.title,'body',event.body,'deadline_at',event.deadline_at,
    'promotion_id',content.id
  ) into v_prompt
  from public.customer_in_app_inbox_events event
  left join public.customer_in_app_inbox_state state on state.event_id=event.id
  join public.business_customer_content_v95 content
    on content.business_id=event.business_id
   and content.content_type='offer'
   and content.metadata->>'schema'='nestly.promotion.v104'
   and content.active
   and content.branch_id is null
   and (content.starts_at is null or content.starts_at<=now())
   and content.ends_at>now()
   and event.source_fingerprint=app.c46_sha256_hex((jsonb_build_object(
      'promotion_id',content.id,'source_kind',event.source_kind,
      'published_once_at',content.metadata->>'published_once_at'
   ) || case when event.source_kind='v122_promotion_expiry'
      then jsonb_build_object('ends_at',content.ends_at)
      else '{}'::jsonb end)::text)
  where event.business_id=v_context.business_id
    and event.identity_id=v_context.identity_id
    and event.link_id=v_context.link_id
    and event.client_id=v_context.client_id
    and event.topic='promotion_alerts'
    and event.source_kind in('v122_promotion_new','v122_promotion_expiry')
    and state.read_at is null and state.dismissed_at is null
    and exists(
      select 1 from public.customer_notification_preferences preference
      where preference.business_id=event.business_id
        and preference.identity_id=event.identity_id
        and preference.auth_user_id=event.auth_user_id
        and preference.link_id=event.link_id
        and preference.channel='in_app'
        and preference.topic='promotion_alerts'
        and preference.opted_in
    )
    and not exists(
      select 1 from public.customer_in_app_inbox_resolutions resolution
      where resolution.event_id=event.id
    )
    and exists(
      select 1 from public.business_media_assets_v95 asset
      where asset.business_id=content.business_id
        and asset.asset_kind='offer'
        and asset.entity_id=content.id
        and asset.customer_visible
        and asset.branch_id is null
    )
  order by event.created_at desc,event.id desc
  limit 1;
  return v_prompt;
end
$$;

--
-- Name: customer_get_platform_marketing_preference(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_get_platform_marketing_preference() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_actor uuid:=auth.uid();
begin
  if v_actor is null then raise exception 'authenticated customer session required' using errcode='28000'; end if;
  return coalesce((select jsonb_build_object(
    'opted_in',p.platform_marketing_opted_in
      and p.marketing_scope_version='2026-08-10-partner-sharing-v3'
      and p.marketing_privacy_sha256='960434af7919e5401b3587111eb746fbba41f739edacd74cb5aeeca0402c224f'
      and exists (select 1 from public.customer_platform_marketing_consent_events e
        where e.identity_id=p.identity_id and e.auth_user_id=v_actor and e.opted_in
          and e.scope_version=p.marketing_scope_version
          and e.privacy_sha256=p.marketing_privacy_sha256),
    'scope_version','2026-08-10-partner-sharing-v3','updated_at',p.updated_at)
    from public.customer_registration_preferences p where p.auth_user_id=v_actor),
    jsonb_build_object('opted_in',false,'scope_version','2026-08-10-partner-sharing-v3','updated_at',null));
end;
$$;

--
-- Name: customer_get_profile(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_get_profile() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
begin
  if v_actor is null then raise exception 'authenticated customer session required' using errcode = '28000'; end if;
  if not app.platform_feature_enabled('customer_phone_registration') then
    raise exception 'customer profile is unavailable' using errcode = '0A000';
  end if;
  return jsonb_build_object('profile', (
    select jsonb_build_object(
      'full_name', p.full_name, 'birth_date', p.birth_date, 'gender', p.gender, 'preferred_language', p.preferred_language
    ) from public.customer_profiles p where p.auth_user_id = v_actor
  ));
end;
$$;

--
-- Name: customer_get_programme_selector_media_v96(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_get_programme_selector_media_v96() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_items jsonb;
  v_truncated boolean := false;
begin
  if auth.uid() is null then
    raise exception 'authenticated customer session required' using errcode = '28000';
  end if;

  -- This contract is intentionally independent of the optional actionable
  -- ranking flag. Scope still comes solely from the customer wallet's verified
  -- auth.uid() -> identity -> link resolver and remains bounded for large users.
  select
    coalesce(jsonb_agg(jsonb_build_object(
      'business_slug', ranked.business_slug,
      'logo_url', app.v95_public_media_url(ranked.object_path)
    ) order by ranked.business_slug) filter(where ranked.item_rank<=100),'[]'::jsonb),
    coalesce(bool_or(ranked.item_rank>100),false)
  into v_items,v_truncated
  from (
    select
      context.business_slug,
      logo.object_path,
      row_number() over(order by context.business_slug) item_rank
    from app.v32_customer_wallet_context(null) context
    left join public.business_brand_presentation_v95 brand
      on brand.business_id=context.business_id
    left join public.business_media_assets_v95 logo
      on logo.id=brand.logo_asset_id
     and logo.business_id=context.business_id
     and logo.asset_kind='logo'
     and logo.customer_visible
  ) ranked
  where ranked.item_rank<=101;

  return jsonb_build_object('items',v_items,'truncated',v_truncated);
end;
$$;

--
-- Name: FUNCTION customer_get_programme_selector_media_v96(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.customer_get_programme_selector_media_v96() IS 'Bounded customer-visible v95 logo URLs for the current authenticated customer verified links.';

--
-- Name: customer_get_promotions_v104(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_get_promotions_v104(p_business uuid, p_branch uuid DEFAULT NULL::uuid, p_locale text DEFAULT 'en'::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid:=auth.uid();
  v_identity uuid;
  v_items jsonb;
begin
  if v_actor is null then
    raise exception 'authenticated_session_required' using errcode='28000';
  end if;
  if p_business is null
     or p_branch is not null
     or p_locale not in ('en','zh-CN')
  then
    raise exception 'valid_promotion_reader_context_required'
      using errcode='22023';
  end if;

  v_identity:=app.v31_current_identity();
  if not exists(
    select 1
    from public.customer_links link
    where link.identity_id=v_identity
      and link.auth_user_id=v_actor
      and link.business_id=p_business
      and link.state='verified'
  ) then
    raise exception 'verified_customer_link_required' using errcode='42501';
  end if;

  with visible as (
    select
      content.id,content.display_order,content.starts_at,content.ends_at,
      content.metadata,content.updated_at,
      coalesce(copy.name,english.name,'Offer') name,
      coalesce(copy.tagline,english.tagline) tagline,
      coalesce(copy.description,english.description) description,
      coalesce(copy.terms,english.terms) terms,
      media.url image_url,media.image_alt
    from public.business_customer_content_v95 content
    left join public.business_localized_copy_v95 copy
      on copy.business_id=p_business
      and copy.entity_type='offer'
      and copy.entity_id=content.id
      and copy.locale=p_locale
    left join public.business_localized_copy_v95 english
      on english.business_id=p_business
      and english.entity_type='offer'
      and english.entity_id=content.id
      and english.locale='en'
    left join lateral(
      select app.v95_public_media_url(asset.object_path) url,
        case when p_locale='zh-CN'
          then coalesce(asset.alt_zh_cn,asset.alt_en)
          else asset.alt_en
        end image_alt
      from public.business_media_assets_v95 asset
      where asset.business_id=p_business
        and asset.asset_kind='offer'
        and asset.entity_id=content.id
        and asset.customer_visible
        and asset.branch_id is null
      order by asset.updated_at desc,asset.id
      limit 1
    ) media on true
    where content.business_id=p_business
      and content.content_type='offer'
      and content.active
      and content.branch_id is null
      and (content.starts_at is null or content.starts_at<=now())
      and content.ends_at>now()
      and media.url is not null
    order by content.display_order,content.starts_at desc nulls last,
      content.updated_at desc,content.id
    limit 2
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'id',visible.id,
    'name',visible.name,
    'tagline',visible.tagline,
    'description',visible.description,
    'terms',visible.terms,
    'image_url',visible.image_url,
    'image_alt',visible.image_alt,
    'starts_at',visible.starts_at,
    'ends_at',visible.ends_at,
    'display_order',visible.display_order,
    'metadata',visible.metadata
  ) order by visible.display_order,visible.starts_at desc nulls last,
      visible.updated_at desc,visible.id),'[]'::jsonb)
  into v_items
  from visible;

  return jsonb_build_object(
    'business_id',p_business,
    'branch_id',null,
    'locale',p_locale,
    'items',v_items,
    'limit',2
  );
end
$$;

--
-- Name: customer_get_promotions_v155(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_get_promotions_v155(p_business uuid, p_branch uuid DEFAULT NULL::uuid, p_locale text DEFAULT 'en'::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_identity uuid;
  v_items jsonb;
begin
  if v_actor is null then
    raise exception 'authenticated_session_required' using errcode='28000';
  end if;
  if p_business is null or p_locale not in ('en','zh-CN') then
    raise exception 'valid_promotion_reader_context_required' using errcode='22023';
  end if;
  if p_branch is not null and not exists(
    select 1 from public.branches branch
    where branch.id = p_branch
      and branch.business_id = p_business
      and coalesce(branch.active,true)
  ) then
    raise exception 'branch_not_available' using errcode='42501';
  end if;

  v_identity := app.v31_current_identity();
  if not exists(
    select 1
    from public.customer_links link
    where link.identity_id = v_identity
      and link.auth_user_id = v_actor
      and link.business_id = p_business
      and link.state = 'verified'
  ) then
    raise exception 'verified_customer_link_required' using errcode='42501';
  end if;

  with visible as (
    select
      content.id,content.display_order,content.starts_at,content.ends_at,
      content.metadata,content.updated_at,
      coalesce(copy.name,english.name,'Offer') name,
      coalesce(copy.tagline,english.tagline) tagline,
      coalesce(copy.description,english.description) description,
      coalesce(copy.terms,english.terms) terms,
      media.url image_url,media.image_alt,
      branches.names branch_names
    from public.business_customer_content_v95 content
    left join public.business_localized_copy_v95 copy
      on copy.business_id = p_business
     and copy.entity_type = 'offer'
     and copy.entity_id = content.id
     and copy.locale = p_locale
    left join public.business_localized_copy_v95 english
      on english.business_id = p_business
     and english.entity_type = 'offer'
     and english.entity_id = content.id
     and english.locale = 'en'
    left join lateral(
      select app.v95_public_media_url(asset.object_path) url,
        case when p_locale='zh-CN'
          then coalesce(asset.alt_zh_cn,asset.alt_en)
          else asset.alt_en
        end image_alt
      from public.business_media_assets_v95 asset
      where asset.business_id = p_business
        and asset.asset_kind = 'offer'
        and asset.entity_id = content.id
        and asset.customer_visible
        and asset.branch_id is null
      order by asset.updated_at desc,asset.id
      limit 1
    ) media on true
    left join lateral(
      select coalesce(jsonb_agg(branch.name order by branch.name),'[]'::jsonb) names
      from public.promotion_branch_scopes_v155 mapped
      join public.branches branch on branch.id = mapped.branch_id
      where mapped.promotion_id = content.id
    ) branches on true
    where content.business_id = p_business
      and content.content_type = 'offer'
      and content.active
      and content.branch_id is null
      and app.promotion_available_at_branch_v155(content.id,p_branch)
      and (content.starts_at is null or content.starts_at <= now())
      and content.ends_at > now()
    order by content.display_order,content.starts_at desc nulls last,
      content.updated_at desc,content.id
    limit 6
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'id',visible.id,
    'name',visible.name,
    'tagline',visible.tagline,
    'description',visible.description,
    'terms',visible.terms,
    'image_url',visible.image_url,
    'image_alt',visible.image_alt,
    'starts_at',visible.starts_at,
    'ends_at',visible.ends_at,
    'display_order',visible.display_order,
    'metadata',visible.metadata,
    'branch_names',visible.branch_names,
    'availability_label',case when jsonb_array_length(visible.branch_names)>0
      then 'Available at ' || (
        select string_agg(value,' and ' order by value)
        from jsonb_array_elements_text(visible.branch_names) value
      )
      else 'Available at all branches' end
  ) order by visible.display_order,visible.starts_at desc nulls last,
      visible.updated_at desc,visible.id),'[]'::jsonb)
  into v_items
  from visible;

  return jsonb_build_object(
    'business_id',p_business,
    'branch_id',p_branch,
    'locale',p_locale,
    'items',v_items,
    'limit',2
  );
end
$$;

--
-- Name: customer_get_redemption_intent_v89(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_get_redemption_intent_v89(p_intent uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_identity uuid:=app.v31_current_identity();
  v_intent public.customer_redemption_intents_v89%rowtype;
begin
  select * into v_intent from public.customer_redemption_intents_v89 intent
  where intent.id=p_intent and intent.identity_id=v_identity
    and intent.auth_user_id=auth.uid();
  if not found then
    raise exception 'redemption intent was not found' using errcode='42501';
  end if;
  return jsonb_build_object(
    'intent_id',v_intent.id,
    'business_id',v_intent.business_id,
    'reward_id',v_intent.reward_id,
    'status',case when v_intent.status='pending' and v_intent.expires_at<=now()
      then 'expired' else v_intent.status end,
    'expires_at',v_intent.expires_at,
    'completed_at',v_intent.completed_at,
    'result',v_intent.completion_result
  );
end
$$;

--
-- Name: customer_get_referral_card_v300(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_get_referral_card_v300(p_business_slug text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_context record;
  v_program record;
  v_code text;
  v_referred integer := 0;
  v_enabled boolean := false;
begin
  if v_actor is null then
    raise exception 'authenticated customer session required' using errcode = '28000';
  end if;
  if not app.platform_feature_enabled('customer_wallet') then
    raise exception 'customer wallet is not enabled' using errcode = '0A000';
  end if;
  select identity_id, business_id, client_id, business_currency, enabled_modules
    into v_context
    from app.v32_customer_wallet_context(p_business_slug)
   limit 1;
  if not found then
    raise exception 'verified customer link required' using errcode = '42501';
  end if;
  select rp.enabled, rp.reward_cents, rp.reward_points, rp.reward_kind, rp.reward_label,
         rp.min_spend_cents, rp.friend_enabled, rp.friend_reward_points, rp.friend_reward_label
    into v_program
    from public.referral_programs rp
   where rp.business_id = v_context.business_id
   limit 1;
  v_enabled := coalesce(v_program.enabled, false)
    and 'referrals' = any(coalesce(v_context.enabled_modules, '{}'::text[]));
  if not v_enabled then
    return jsonb_build_object('enabled', false);
  end if;
  select c.referral_code into v_code
    from public.clients c
   where c.id = v_context.client_id;
  select count(*)::integer into v_referred
    from public.referrals r
   where r.business_id = v_context.business_id
     and r.referrer_client_id = v_context.client_id
     and r.status in ('qualified','rewarded');
  return jsonb_build_object(
    'enabled', true,
    'code', v_code,
    'reward_cents', coalesce(v_program.reward_cents, 0),
    'reward_points', coalesce(v_program.reward_points, 0),
    'reward_kind', coalesce(v_program.reward_kind, 'points'),
    'reward_label', v_program.reward_label,
    'min_spend_cents', coalesce(v_program.min_spend_cents, 0),
    -- The friend's side is resolved HERE rather than in the browser, so the sentence a customer
    -- reads cannot disagree with what app.on_sale_recorded will actually pay.
    'friend_enabled', coalesce(v_program.friend_enabled, true),
    'friend_reward_points', case when coalesce(v_program.friend_enabled,true)
                                 then coalesce(v_program.friend_reward_points, v_program.reward_points, 0) else 0 end,
    'friend_reward_label', case when coalesce(v_program.friend_enabled,true)
                                then coalesce(v_program.friend_reward_label, v_program.reward_label) end,
    'currency', coalesce(v_context.business_currency, 'SGD'),
    'referred_count', v_referred
  );
end
$$;

--
-- Name: customer_get_repeat_booking_preference_v167(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_get_repeat_booking_preference_v167(p_business_slug text, p_appointment uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_context record;
  v_result jsonb;
begin
  if auth.uid() is null then
    raise exception 'authenticated customer session required' using errcode = '28000';
  end if;
  if p_business_slug is null or p_appointment is null then
    raise exception 'invalid repeat booking request' using errcode = '22023';
  end if;

  select * into v_context
    from app.v32_customer_wallet_context(p_business_slug)
   limit 1;
  if not found then
    raise exception 'verified customer link required' using errcode = '42501';
  end if;

  select jsonb_build_object(
    'business_slug', v_context.business_slug,
    'appointment_id', appointment.id,
    'service_id', service.id,
    'service_name', service.name,
    'staff_id', staff_member.id,
    'staff_name', staff_member.full_name
  ) into v_result
    from public.appointments appointment
    join public.services service
      on service.business_id = appointment.business_id
     and service.id = appointment.service_id
     and service.active
     and service.show_on_booking_page
    left join public.staff staff_member
      on staff_member.business_id = appointment.business_id
     and staff_member.id = appointment.staff_id
     and staff_member.active
     and appointment.branch_id is not null
     and exists (
       select 1
         from public.staff_branches assignment
        where assignment.business_id = appointment.business_id
          and assignment.branch_id = appointment.branch_id
          and assignment.staff_id = staff_member.id
     )
     and (
       not exists (
         select 1
           from public.staff_services configured
          where configured.business_id = appointment.business_id
            and configured.service_id = appointment.service_id
       )
       or exists (
         select 1
           from public.staff_services qualified
          where qualified.business_id = appointment.business_id
            and qualified.service_id = appointment.service_id
            and qualified.staff_id = staff_member.id
       )
     )
   where appointment.business_id = v_context.business_id
     and appointment.client_id = v_context.client_id
     and appointment.id = p_appointment
     and appointment.status = 'completed'
     and appointment.starts_at < statement_timestamp();

  return coalesce(v_result, jsonb_build_object(
    'business_slug', v_context.business_slug,
    'appointment_id', p_appointment,
    'service_id', null,
    'service_name', null,
    'staff_id', null,
    'staff_name', null
  ));
end;
$$;

--
-- Name: customer_get_reward_catalog(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_get_reward_catalog(p_business_slug text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_context record;
  v_balance integer;
  v_metric numeric;
  v_result jsonb;
  v_balance_scope text;
  v_stamps_programme uuid;
  v_live_points_programme uuid;
  v_stamp_filled integer;
  v_stamp_cycle integer;
begin
  if auth.uid() is null then
    raise exception 'authenticated customer session required' using errcode = '28000';
  end if;
  select * into v_context from app.v32_customer_wallet_context(p_business_slug) limit 1;
  if not found then
    raise exception 'verified customer link required' using errcode = '42501';
  end if;
  if not ('loyalty' = any(v_context.enabled_modules)) or not exists (
    select 1 from public.loyalty_programs lp
     where lp.business_id = v_context.business_id and lp.active
  ) then
    raise exception 'loyalty module is unavailable for this business' using errcode = '42501';
  end if;

  select spine.id into v_live_points_programme
    from public.business_programmes spine
   where spine.business_id = v_context.business_id and spine.kind = 'points' and spine.active
   order by spine.sort, spine.id limit 1;
  select coalesce(sum(pl.points), 0)::integer into v_balance
    from public.points_ledger pl
   where pl.business_id = v_context.business_id and pl.client_id = v_context.client_id
     and pl.programme_id = v_live_points_programme; /* v384_live_customer_programmes_catalog */

  v_metric := app.v176_tier_gate_metric(v_context.business_id, v_context.client_id);

  select spine.id into v_stamps_programme
    from public.business_programmes spine
   where spine.business_id = v_context.business_id and spine.kind = 'stamps' and spine.active
   order by spine.sort, spine.id limit 1;
  select coalesce(sp.filled, 0), coalesce(sp.cycle_index, 0)
    into v_stamp_filled, v_stamp_cycle
    from app.stamp_progress_v323(v_context.business_id, v_context.client_id) sp;

  select coalesce(jsonb_agg(jsonb_build_object(
    'customer_name', listed.customer_name,
    'description', listed.description,
    'image_ref', listed.image_ref,
    'terms', listed.terms,
    'instructions', listed.instructions,
    'taxonomy_label', listed.taxonomy_label,
    'fulfillment_kind', listed.fulfillment_kind,
    'cost_points', listed.cost_points,
    'claim_available_from', listed.claim_available_from,
    'claim_available_until', listed.claim_available_until,
    'entitlement_expiry_days', listed.entitlement_expiry_days,
    'availability', listed.availability,
    'claim_method', 'counter',
    'tier_requirement', case when listed.gate_threshold is null then null else jsonb_build_object(
      'tier_label', listed.gate_label,
      'threshold', listed.gate_threshold,
      'met', v_metric >= listed.gate_threshold
    ) end,
    'eligibility', jsonb_build_object(
      'branches', jsonb_build_object('scope', case when listed.branch_count = 0 then 'all' else 'restricted' end, 'count', listed.branch_count),
      'services', jsonb_build_object('scope', case when listed.service_count = 0 then 'all' else 'restricted' end, 'count', listed.service_count),
      'products', jsonb_build_object('scope', case when listed.product_count = 0 then 'all' else 'restricted' end, 'count', listed.product_count)
    )
  ) order by listed.sort, listed.customer_name), '[]'::jsonb)
  into v_result
  from (
    select rv.customer_name, rv.description, rv.image_ref, rv.terms, rv.instructions,
           rv.taxonomy_label, rv.fulfillment_kind, rv.cost_points, rv.claim_available_from,
           rv.claim_available_until, rv.entitlement_expiry_days, rv.sort,
           app.v176_reward_gate_threshold(v_context.business_id, rv.min_tier_id, rv.min_tier_threshold) as gate_threshold,
           app.v176_reward_gate_label(v_context.business_id, rv.min_tier_id) as gate_label,
           (select count(*)::integer from public.loyalty_reward_branches e where e.reward_version_id = rv.id) as branch_count,
           (select count(*)::integer from public.loyalty_reward_services e where e.reward_version_id = rv.id) as service_count,
           (select count(*)::integer from public.loyalty_reward_products e where e.reward_version_id = rv.id) as product_count,
           case
             when rv.claim_available_from is not null and now() < rv.claim_available_from then 'not_started'
             when rv.claim_available_until is not null and now() >= rv.claim_available_until then 'ended'
             when app.v176_reward_gate_threshold(v_context.business_id, rv.min_tier_id, rv.min_tier_threshold) is not null
              and v_metric < app.v176_reward_gate_threshold(v_context.business_id, rv.min_tier_id, rv.min_tier_threshold) then 'tier_locked'
             when rv.usage_limit is not null and coalesce(usage.used_count, 0) >= rv.usage_limit then 'limit_reached'
             when v_stamps_programme is not null and rv.programme_id = v_stamps_programme
              and exists (select 1 from public.stamp_milestone_claims claim
                           where claim.business_id = v_context.business_id
                             and claim.client_id = v_context.client_id
                             and claim.programme_id = v_stamps_programme
                             and claim.cycle_index = coalesce(v_stamp_cycle, 0)
                             and claim.reward_id = rv.reward_id) then 'limit_reached'
             when (case when v_stamps_programme is not null and rv.programme_id = v_stamps_programme
                        then coalesce(v_stamp_filled, 0) else v_balance end) < rv.cost_points then 'insufficient_balance'
             else 'available_at_counter'
           end as availability
      from public.businesses b
      join public.loyalty_reward_versions rv
        on rv.business_id = b.id and rv.config_version_id = b.active_config_version_id and rv.active
       -- V371: see app.c45_base_actionable_wallet_card. `paused` is on the live row and the
       -- customer reads the published snapshot, so a switched-off gift stayed in the catalogue.
       and not exists (
         select 1 from public.loyalty_rewards live_reward
          where live_reward.id = rv.reward_id
            and live_reward.business_id = rv.business_id
            and (
              live_reward.paused
              -- V372: a gift belongs to ONE programme and is priced in that programme's unit, so it
              -- must not be offered while that programme is switched off. Cubbly was the live case:
              -- stamps off and points on, with a 2-STAMP gift still catalogued and reported
              -- `available_now` against a 50-POINT balance — two different units, for a programme
              -- that is not running. A reward with no programme is left alone: fail open, never
              -- hide a gift because a link is missing.
              or exists (
                select 1 from public.business_programmes spine
                 where spine.id = live_reward.programme_id
                   and not spine.active
              )
            )
       )
      left join lateral (
        select count(*)::integer as used_count
          from public.loyalty_redemptions lr
         where lr.business_id = v_context.business_id and lr.client_id = v_context.client_id
           and lr.reward_id = rv.reward_id
      ) usage on true
     where b.id = v_context.business_id
  ) listed;

  -- v230/v241: the one owner choice for what points are FOR, so the wallet tells one
  -- story. As an OBJECT: appending to the rewards array made the mode unreadable (v241).
  v_balance_scope := app.programme_balance_scope_v312(v_context.business_id);
  return jsonb_build_object(
    'rewards', coalesce(v_result, '[]'::jsonb),
    'points_mode', (select points_mode from public.businesses where id = v_context.business_id),
    'programmes_contract', 'v310',
    'balance_scope', v_balance_scope,
    'programmes', jsonb_build_array(jsonb_build_object(
      'kind', case when exists (
                     select 1 from public.loyalty_programs programme_v310
                      where programme_v310.business_id = v_context.business_id
                        and programme_v310.loyalty_model = 'stamps')
                   then 'stamps' else 'points' end,
      'balance_scope', v_balance_scope,
      'rewards', coalesce(v_result, '[]'::jsonb))));
end;
$$;

--
-- Name: FUNCTION customer_get_reward_catalog(p_business_slug text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.customer_get_reward_catalog(p_business_slug text) IS 'v310: adds programmes[] (one derived group in W4 — the firm''s single accruing programme) and balance_scope=business_pot beside the unchanged rewards[] and points_mode. The grouped and flat views are the SAME v_result aggregation, so they cannot drift. v241 shape, v230 mode, v176b tier gate all unchanged.';

--
-- Name: customer_get_reward_history_v422(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_get_reward_history_v422(p_business_slug text, p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_context record;
  v_limit integer := least(greatest(coalesce(p_limit, 50), 1), 100);
  v_items jsonb;
begin
  if auth.uid() is null then
    raise exception 'authenticated customer session required' using errcode = '28000';
  end if;

  -- Identity, business and client all come from here. Nothing about WHO is being asked about is
  -- taken from an argument.
  select * into v_context
    from app.v32_customer_wallet_context(p_business_slug)
   limit 1;
  if not found then
    raise exception 'verified customer link required' using errcode = '42501';
  end if;

  select coalesce(jsonb_agg(item order by redeemed_at desc, id desc), '[]'::jsonb)
    into v_items
    from (
      select redemption.id,
             redemption.redeemed_at,
             jsonb_build_object(
               'id', redemption.id,
               'reward_name', redemption.reward_name,
               'redeemed_at', redemption.redeemed_at,
               -- The cost is printed back to the customer in the unit they paid in. A stamp-card
               -- milestone is claimed without consuming a balance (v323), so points_spent is 0 on
               -- those rows and the client prints no cost line rather than "0 points".
               'points_spent', redemption.points_spent,
               'consumes_balance', redemption.consumes_balance,
               'fulfillment_kind', redemption.fulfillment_kind,
               -- image_ref is read from the snapshot the redemption itself stored, not from the
               -- live reward: a gift whose photo the firm has since changed should appear in
               -- history as the thing the customer actually received.
               'image_ref', nullif(redemption.reward_snapshot->>'image_ref', '')
             ) as item
        from public.loyalty_redemptions redemption
       where redemption.business_id = v_context.business_id
         and redemption.client_id = v_context.client_id
         and not exists (
           select 1
             from public.loyalty_redemption_reversals reversal
            where reversal.business_id = redemption.business_id
              and reversal.redemption_id = redemption.id
         )
       order by redemption.redeemed_at desc, redemption.id desc
       limit v_limit
    ) as recent;

  return jsonb_build_object(
    'contract', 'v422',
    'business_id', v_context.business_id,
    'items', v_items
  );
end
$$;

--
-- Name: customer_get_stamp_card_v323(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_get_stamp_card_v323(p_business_slug text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_context record;
  v_progress record;
  v_milestones jsonb;
  v_metric numeric;
begin
  if auth.uid() is null then
    raise exception 'authenticated customer session required' using errcode = '28000';
  end if;
  select * into v_context from app.v32_customer_wallet_context(p_business_slug) limit 1;
  if not found then
    raise exception 'verified customer link required' using errcode = '42501';
  end if;

  if not ('loyalty' = any(v_context.enabled_modules)) then
    return jsonb_build_object('enabled', false);
  end if;
  select * into v_progress
    from app.stamp_progress_v323(v_context.business_id, v_context.client_id) limit 1;
  if not found then
    return jsonb_build_object('enabled', false);
  end if;

  v_metric := app.v176_tier_gate_metric(v_context.business_id, v_context.client_id);

  select coalesce(jsonb_agg(jsonb_build_object(
    'reward_id', rung.reward_id,
    'name', rung.customer_name,
    'slot', rung.cost_points,
    'is_final', rung.cost_points >= coalesce(v_progress.slots, 0)
                and coalesce(v_progress.slots, 0) > 0,
    'claimed_this_cycle', rung.claimed,
    'description', rung.description,
    'image_ref', rung.image_ref,
    'terms', rung.terms,
    'instructions', rung.instructions,
    'availability', case
      when not v_progress.programme_active then 'paused'
      when rung.claim_available_from is not null and now() < rung.claim_available_from
        then 'not_started'
      when rung.claim_available_until is not null and now() >= rung.claim_available_until
        then 'ended'
      when rung.gate_threshold is not null and v_metric < rung.gate_threshold then 'tier_locked'
      when rung.claimed then 'claimed_this_cycle'
      when rung.usage_limit is not null and rung.used_count >= rung.usage_limit
        then 'limit_reached'
      when v_progress.filled < rung.cost_points then 'insufficient_stamps'
      else 'available_at_counter'
    end,
    'stamps_to_go', greatest(rung.cost_points - v_progress.filled, 0)
  ) order by rung.cost_points, rung.customer_name), '[]'::jsonb)
  into v_milestones
  from (
    select rv.reward_id, rv.customer_name, rv.cost_points, rv.description, rv.image_ref,
           rv.terms, rv.instructions, rv.claim_available_from, rv.claim_available_until,
           rv.usage_limit,
           app.v176_reward_gate_threshold(v_context.business_id, rv.min_tier_id,
             rv.min_tier_threshold) as gate_threshold,
           (select count(*)::integer from public.loyalty_redemptions lr
             where lr.business_id = v_context.business_id
               and lr.client_id = v_context.client_id
               and lr.reward_id = rv.reward_id) as used_count,
           exists (select 1 from public.stamp_milestone_claims claim
                    where claim.business_id = v_context.business_id
                      and claim.client_id = v_context.client_id
                      and claim.programme_id = v_progress.programme_id
                      and claim.cycle_index = v_progress.cycle_index
                      and claim.reward_id = rv.reward_id) as claimed
      from public.businesses b
      join public.loyalty_reward_versions rv
        /* nestly_v416: the customer's OPEN card, not whatever the firm published last. */
        on rv.business_id = b.id and rv.active
       and rv.config_version_id = app.stamp_cycle_version_v416(
             v_context.business_id, v_context.client_id, v_progress.programme_id)
     where b.id = v_context.business_id
       and rv.programme_id = v_progress.programme_id
  ) rung;

  return jsonb_build_object(
    'enabled', true,
    'contract', 'v323',
    'unit', 'stamps',
    'running', v_progress.programme_active,
    'running_since', v_progress.running_since,
    'paused_since', v_progress.paused_since,
    'slots', v_progress.slots,
    'filled', v_progress.filled,
    'shown_filled', case when coalesce(v_progress.slots, 0) > 0
                         then least(v_progress.filled, v_progress.slots)
                         else v_progress.filled end,
    'carried', case when coalesce(v_progress.slots, 0) > 0
                    then greatest(v_progress.filled - v_progress.slots, 0) else 0 end,
    'cycle_index', v_progress.cycle_index,
    'lifetime', v_progress.net_stamps,
    'ready', v_progress.ready,
    'pot_migrated', v_progress.pot_migrated,
    'milestones', v_milestones,
    'next_milestone', (
      select rung.value from jsonb_array_elements(v_milestones) as rung(value)
       where (rung.value ->> 'claimed_this_cycle')::boolean is not true
       order by (rung.value ->> 'slot')::integer
       limit 1)
  );
end
$$;

--
-- Name: FUNCTION customer_get_stamp_card_v323(p_business_slug text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.customer_get_stamp_card_v323(p_business_slug text) IS 'v323 (R5): the customer''s stamp quest — filled/total against the CURRENT cycle, which milestones are claimed on this card, which is next and how far. Stamps only: this payload carries no points figure by construction. Returns exactly {"enabled": false} when the firm runs no stamp card, so the client removes the slot rather than rendering an empty one.';

--
-- Name: customer_get_transaction_history_v167(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_get_transaction_history_v167(p_business_slug text, p_cursor jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_context record;
  v_result jsonb;
  v_items jsonb;
begin
  if auth.uid() is null then
    raise exception 'authenticated customer session required' using errcode = '28000';
  end if;

  select * into v_context
    from app.v32_customer_wallet_context(p_business_slug)
   limit 1;
  if not found then
    raise exception 'verified customer link required' using errcode = '42501';
  end if;

  v_result := public.customer_get_transaction_history_v81(p_business_slug, p_cursor);

  select coalesce(jsonb_agg(
    case
      when item->>'source_kind' = 'sale' and package_use.id is not null then
        item || jsonb_build_object(
          'is_package_session', true,
          'package_name', customer_package.plan_name_snapshot,
          'package_purchased_at', customer_package.purchased_at,
          'package_reference', left(customer_package.id::text, 8)
        )
      else item || jsonb_build_object('is_package_session', false)
    end
    order by ordinal
  ), '[]'::jsonb) into v_items
    from jsonb_array_elements(coalesce(v_result->'items', '[]'::jsonb))
         with ordinality listed(item, ordinal)
    left join public.package_session_consumptions package_use
      on listed.item->>'source_kind' = 'sale'
     and package_use.business_id = v_context.business_id
     and package_use.client_id = v_context.client_id
     and package_use.sale_id = nullif(listed.item->>'source_id', '')::uuid
    left join public.client_packages customer_package
      on customer_package.business_id = package_use.business_id
     and customer_package.client_id = package_use.client_id
     and customer_package.id = package_use.client_package_id;

  return jsonb_set(v_result, '{items}', v_items, true);
end;
$$;

--
-- Name: customer_get_transaction_history_v81(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_get_transaction_history_v81(p_business_slug text, p_cursor jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_context record;
  v_cursor jsonb := coalesce(p_cursor, '{}'::jsonb);
  v_limit integer := 20;
  v_before_at timestamptz;
  v_before_order integer;
  v_before_id uuid;
  v_result jsonb;
begin
  if auth.uid() is null then
    raise exception 'authenticated customer session required' using errcode = '28000';
  end if;
  if jsonb_typeof(v_cursor) <> 'object'
     or exists (
       select 1
         from jsonb_object_keys(v_cursor) as cursor_keys(key)
        where key not in ('limit', 'before_at', 'before_order', 'before_id')
     ) then
    raise exception 'invalid transaction history cursor' using errcode = '22023';
  end if;
  begin
    v_limit := least(greatest(coalesce((v_cursor->>'limit')::integer, 20), 1), 50);
    v_before_at := nullif(v_cursor->>'before_at', '')::timestamptz;
    v_before_order := nullif(v_cursor->>'before_order', '')::integer;
    v_before_id := nullif(v_cursor->>'before_id', '')::uuid;
  exception when others then
    raise exception 'invalid transaction history cursor' using errcode = '22023';
  end;
  if num_nonnulls(v_before_at, v_before_order, v_before_id) not in (0, 3)
     or (v_before_order is not null and v_before_order not in (1, 2)) then
    raise exception 'transaction history cursor is incomplete' using errcode = '22023';
  end if;

  select * into v_context
    from app.v32_customer_wallet_context(p_business_slug)
   limit 1;
  if not found then
    raise exception 'verified customer link required' using errcode = '42501';
  end if;

  with sale_events as (
    select
      sale.id as source_id,
      sale.occurred_at as event_at,
      2 as event_order,
      'sale'::text as source_kind,
      case when sale.reversal_of is null then 'sale' else 'sale_reversal' end
        as event_type,
      case
        when sale.reversal_of is not null then 'reversal'
        when reversal.id is not null then 'reversed'
        else 'completed'
      end as status,
      branch.name as branch_name,
      sale.kind as sale_kind,
      sale.amount_cents::integer as gross_cents,
      case when sale.reversal_of is not null then 0
        else (sale.amount_cents + coalesce(reversal.amount_cents, 0))::integer
      end as net_cents,
      coalesce(points.points_earned, 0)::integer as points_earned,
      coalesce(points.points_redeemed, 0)::integer as points_redeemed,
      coalesce(points.points_removed, 0)::integer as points_removed,
      case when sale.reversal_of is not null then sale.reversal_of else reversal.id end
        as related_source_id,
      case sale.kind
        when 'quick_sale' then 'Purchase'
        when 'service' then 'Service purchase'
        when 'retail' then 'Retail purchase'
        when 'membership' then 'Membership purchase'
        else 'Purchase'
      end as description,
      coalesce((
        select jsonb_agg(jsonb_build_object(
          'item_id', item.id,
          'item_type', item.item_type,
          'description', item.description,
          'qty', item.qty,
          'unit_cents', item.unit_cents,
          'line_cents', item.line_cents
        ) order by item.created_at, item.id)
          from public.sale_items item
         where item.business_id = sale.business_id
           and item.sale_id = sale.id
      ), '[]'::jsonb) as line_items
      from public.sales sale
      left join public.branches branch
        on branch.business_id = sale.business_id
       and branch.id = sale.branch_id
      left join lateral (
        select reversal_sale.id, reversal_sale.amount_cents
          from public.sales reversal_sale
         where reversal_sale.business_id = sale.business_id
           and reversal_sale.reversal_of = sale.id
         order by reversal_sale.occurred_at desc, reversal_sale.id desc
         limit 1
      ) reversal on true
      left join lateral (
        select
          coalesce(sum(ledger.points) filter (where ledger.points > 0), 0)::integer
            as points_earned,
          abs(coalesce(sum(ledger.points) filter (
            where ledger.points < 0 and ledger.entry_type = 'redeem'
          ), 0))::integer as points_redeemed,
          abs(coalesce(sum(ledger.points) filter (
            where ledger.points < 0 and ledger.entry_type <> 'redeem'
          ), 0))::integer as points_removed
          from public.points_ledger ledger
         where ledger.business_id = sale.business_id
           and ledger.client_id = sale.client_id
           and ledger.sale_id = sale.id
      ) points on true
     where sale.business_id = v_context.business_id
       and sale.client_id = v_context.client_id
  ), standalone_point_events as (
    select
      ledger.id as source_id,
      ledger.created_at as event_at,
      1 as event_order,
      'points_ledger'::text as source_kind,
      'points_' || ledger.entry_type as event_type,
      'completed'::text as status,
      null::text as branch_name,
      null::text as sale_kind,
      null::integer as gross_cents,
      null::integer as net_cents,
      greatest(ledger.points, 0)::integer as points_earned,
      case when ledger.entry_type = 'redeem'
        then greatest(-ledger.points, 0) else 0 end::integer as points_redeemed,
      case when ledger.entry_type <> 'redeem'
        then greatest(-ledger.points, 0) else 0 end::integer as points_removed,
      null::uuid as related_source_id,
      case ledger.entry_type
        when 'earn' then 'Points earned'
        when 'redeem' then 'Points redeemed'
        when 'expire' then 'Points expired'
        when 'adjust' then 'Points adjustment'
        else 'Loyalty activity'
      end as description,
      '[]'::jsonb as line_items
      from public.points_ledger ledger
     where ledger.business_id = v_context.business_id
       and ledger.client_id = v_context.client_id
       and ledger.sale_id is null
  ), history as (
    select * from sale_events
    union all
    select * from standalone_point_events
  ), eligible as (
    select *
      from history
     where v_before_at is null
        or (event_at, event_order, source_id)
           < (v_before_at, v_before_order, v_before_id)
     order by event_at desc, event_order desc, source_id desc
     limit v_limit + 1
  ), visible as (
    select *
      from eligible
     order by event_at desc, event_order desc, source_id desc
     limit v_limit
  )
  select jsonb_build_object(
    'business', jsonb_build_object(
      'slug', v_context.business_slug,
      'name', v_context.business_name,
      'currency', v_context.business_currency
    ),
    'items', coalesce((
      select jsonb_agg(jsonb_build_object(
        'source_kind', source_kind,
        'source_id', source_id,
        'event_at', event_at,
        'event_type', event_type,
        'status', status,
        'branch_name', branch_name,
        'sale_kind', sale_kind,
        'gross_cents', gross_cents,
        'net_cents', net_cents,
        'points_earned', points_earned,
        'points_redeemed', points_redeemed,
        'points_removed', points_removed,
        'related_source_id', related_source_id,
        'description', description,
        'line_items', line_items
      ) order by event_at desc, event_order desc, source_id desc)
        from visible
    ), '[]'::jsonb),
    'next_cursor', case when (select count(*) from eligible) > v_limit then (
      select jsonb_build_object(
        'before_at', event_at,
        'before_order', event_order,
        'before_id', source_id,
        'limit', v_limit
      )
        from visible
       order by event_at, event_order, source_id
       limit 1
    ) else null end
  ) into v_result;

  return v_result;
end;
$$;

--
-- Name: customer_get_wallet(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_get_wallet() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_wallet jsonb;
begin
  if v_actor is null then
    raise exception 'authenticated customer session required' using errcode = '28000';
  end if;
  if not app.platform_feature_enabled('customer_wallet') then
    raise exception 'customer wallet is not enabled' using errcode = '0A000';
  end if;

  select coalesce(jsonb_agg(card order by business_slug), '[]'::jsonb)
    into v_wallet
    from (
      select
        ctx.business_slug,
        jsonb_build_object(
          'business', jsonb_build_object(
            'slug', ctx.business_slug,
            'name', ctx.business_name,
            'industry', ctx.business_industry,
            'currency', ctx.business_currency
          ),
          'loyalty', app.customer_live_loyalty_v384(ctx.business_id, ctx.client_id, ctx.enabled_modules, now()),
          'packages', jsonb_build_object(
            'enabled', 'packages' = any(ctx.enabled_modules),
            'active_count', case when 'packages' = any(ctx.enabled_modules)
                                 then coalesce(package_summary.active_count, 0) else 0 end,
            'sessions_remaining', case when 'packages' = any(ctx.enabled_modules)
                                       then coalesce(package_summary.sessions_remaining, 0) else 0 end
          ),
          'membership', jsonb_build_object(
            'enabled', 'memberships' = any(ctx.enabled_modules),
            'active', case when 'memberships' = any(ctx.enabled_modules)
                           then coalesce(membership_summary.active, false) else false end,
            'current_period_ends_at', case when 'memberships' = any(ctx.enabled_modules)
                                           then membership_summary.current_period_end end
          ),
          'upcoming_appointments', jsonb_build_object(
            'enabled', 'appointments' = any(ctx.enabled_modules),
            'count', case when 'appointments' = any(ctx.enabled_modules)
                          then coalesce(appointment_summary.upcoming_count, 0) else 0 end
          )
        ) as card
      from app.v32_customer_wallet_context(null) ctx
      left join lateral (
        select count(*)::integer as active_count,
               coalesce(sum(cp.remaining), 0)::integer as sessions_remaining
          from public.client_packages cp
         where 'packages' = any(ctx.enabled_modules)
           and cp.business_id = ctx.business_id
           and cp.client_id = ctx.client_id
           and cp.status = 'active'
           and cp.remaining > 0
      ) package_summary on true
      left join lateral (
        select (count(*) > 0) as active, min(m.current_period_end) as current_period_end
          from public.memberships m
         where 'memberships' = any(ctx.enabled_modules)
           and m.business_id = ctx.business_id
           and m.client_id = ctx.client_id
           and m.status in ('active', 'paused', 'cancel_at_period_end')
      ) membership_summary on true
      left join lateral (
        select count(*)::integer as upcoming_count
          from public.appointments a
         where 'appointments' = any(ctx.enabled_modules)
           and a.business_id = ctx.business_id
           and a.client_id = ctx.client_id
           and a.status = 'booked'
           and a.starts_at >= now()
      ) appointment_summary on true
    ) per_firm;

  return v_wallet;
end;
$$;

--
-- Name: customer_issue_link_invitation(uuid, uuid, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_issue_link_invitation(p_business uuid, p_client uuid, p_idempotency_key text, p_expires_in_minutes integer DEFAULT 10080) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_request_hash text;
  v_existing public.customer_link_invitation_issues%rowtype;
  v_invitation_id uuid := gen_random_uuid();
  v_token text;
  v_expires_at timestamptz;
  v_recipient_email text;
begin
  if v_actor is null then raise exception 'authenticated staff session required' using errcode = '28000'; end if;
  if not app.platform_feature_enabled('customer_claims') then
    raise exception 'customer access is unavailable' using errcode = '0A000';
  end if;
  if p_idempotency_key is null or length(btrim(p_idempotency_key)) < 8 then
    raise exception 'idempotency key must contain at least 8 characters' using errcode = '22023';
  end if;
  if p_expires_in_minutes is null or p_expires_in_minutes < 5 or p_expires_in_minutes > 43200 then
    raise exception 'invitation expiry must be between 5 minutes and 30 days' using errcode = '22023';
  end if;
  p_idempotency_key := btrim(p_idempotency_key);
  v_request_hash := app.v31_sha256_hex(
    'v31.invitation_issue:' || p_business::text || ':' || p_client::text || ':' || p_expires_in_minutes::text
  );
  perform pg_advisory_xact_lock(hashtextextended(
    'v31:invitation-issue:' || p_business::text || ':' || v_actor::text || ':' || p_idempotency_key, 0
  ));
  if not app.is_salon_owner(p_business) then
    raise exception 'owner only' using errcode = '42501';
  end if;
  perform 1 from public.businesses b where b.id = p_business for share;
  select nullif(lower(btrim(c.email)), '') into v_recipient_email
    from public.clients c
   where c.id = p_client and c.business_id = p_business
   for share;
  if not found then raise exception 'client does not belong to this business' using errcode = '23503'; end if;
  if v_recipient_email is null then
    raise exception 'customer invitation requires an email on the client record' using errcode = '22023';
  end if;

  select * into v_existing from public.customer_link_invitation_issues i
   where i.business_id = p_business and i.issued_by_auth_user_id = v_actor
     and i.idempotency_key = p_idempotency_key;
  if found then
    if v_existing.request_hash is distinct from v_request_hash then
      raise exception 'idempotency key was already used for another invitation request' using errcode = '22023';
    end if;
    -- The raw secret is purposefully unavailable after its initial response.
    return jsonb_build_object(
      'outcome', 'invitation_already_issued', 'invitation_id', v_existing.invitation_id,
      'token', null
    );
  end if;
  perform pg_advisory_xact_lock(hashtextextended(
    'v31:invitation-issue-rate:' || p_business::text || ':' || v_actor::text, 0
  ));
  if (
    select count(*) from public.customer_link_invitation_issues i
     where i.business_id = p_business
       and i.issued_by_auth_user_id = v_actor
       and i.created_at >= now() - interval '15 minutes'
  ) >= 20 then
    raise exception 'try later' using errcode = '54000';
  end if;

  v_expires_at := now() + make_interval(mins => p_expires_in_minutes);
  v_token := encode(extensions.gen_random_bytes(32), 'hex');
  insert into public.customer_link_invitations (
    id, business_id, client_id, issued_by_auth_user_id, token_hash,
    recipient_email_hash, expires_at
  ) values (
    v_invitation_id, p_business, p_client, v_actor, app.v31_sha256_hex(v_token),
    app.v31_sha256_hex('v31.invitation-email:' || v_recipient_email), v_expires_at
  );
  insert into public.customer_link_invitation_issues (
    invitation_id, business_id, client_id, issued_by_auth_user_id, idempotency_key, request_hash
  ) values (
    v_invitation_id, p_business, p_client, v_actor, p_idempotency_key, v_request_hash
  );
  insert into public.customer_link_audit_events (
    actor_auth_user_id, business_id, client_id, invitation_id, event_type,
    idempotency_key, request_hash, response
  ) values (
    v_actor, p_business, p_client, v_invitation_id, 'invitation_issued',
    p_idempotency_key, v_request_hash,
    jsonb_build_object('outcome', 'invitation_issued', 'invitation_id', v_invitation_id, 'expires_at', v_expires_at)
  );
  return jsonb_build_object(
    'outcome', 'invitation_issued', 'invitation_id', v_invitation_id,
    'token', v_token, 'expires_at', v_expires_at
  );
end;
$$;

--
-- Name: customer_join_business_from_qr_v89(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_join_business_from_qr_v89(p_join_token text, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  perform 1
  from public.business_customer_join_qr_v89 qr
  join public.businesses business on business.id=qr.business_id
  where qr.token_hash=app.v89_sha256(p_join_token)
    and qr.status='active' and qr.expires_at>now()
    and business.join_enabled
  for share of qr,business;
  if not found then
    raise exception 'join QR is invalid, expired, or paused' using errcode='22023';
  end if;
  return public.customer_join_business_from_qr_v89_base_v90(
    p_join_token,p_idempotency_key
  );
end
$$;

--
-- Name: customer_join_business_from_qr_v89_base_v90(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_join_business_from_qr_v89_base_v90(p_join_token text, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid:=auth.uid();
  v_identity uuid;
  v_qr public.business_customer_join_qr_v89%rowtype;
  v_auth_phone text;v_phone_confirmed_at timestamptz;v_phone text;
  v_profile public.customer_profiles%rowtype;
  v_client uuid;v_link uuid;v_existing public.customer_link_claim_attempts%rowtype;
  v_hash text;v_response jsonb;v_event text;
begin
  if v_actor is null then
    raise exception 'authenticated customer session required' using errcode='28000';
  end if;
  if not app.platform_feature_enabled('customer_qr_join') then
    raise exception 'customer QR join is unavailable' using errcode='0A000';
  end if;
  if p_idempotency_key is null or length(coalesce(p_join_token,''))<32 then
    raise exception 'invalid QR join request' using errcode='22023';
  end if;
  v_identity:=app.v31_current_identity();
  v_hash:=app.v89_sha256(p_join_token);
  perform pg_advisory_xact_lock(hashtextextended(
    'v89:join:'||v_identity::text||':'||p_idempotency_key::text,0));
  select * into v_existing from public.customer_link_claim_attempts attempt
  where attempt.identity_id=v_identity and attempt.operation='qr_join'
    and attempt.idempotency_key=p_idempotency_key::text for update;
  if found then
    if v_existing.request_hash<>v_hash then
      raise exception 'idempotency key conflicts with another QR join'
        using errcode='23505';
    end if;
    return v_existing.response||jsonb_build_object('replayed',true);
  end if;

  select * into v_qr from public.business_customer_join_qr_v89 qr
  where qr.token_hash=v_hash and qr.status='active' and qr.expires_at>now()
  for share;
  if not found then
    raise exception 'join QR is invalid or expired' using errcode='22023';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(
    'v89:business-customer:'||v_qr.business_id::text||':'||v_identity::text,0));
  select link.id,link.client_id into v_link,v_client
  from public.customer_links link
  where link.business_id=v_qr.business_id and link.identity_id=v_identity
    and link.auth_user_id=v_actor and link.state='verified' for update;
  if found then
    v_response:=jsonb_build_object('outcome','linked','business_id',
      v_qr.business_id,'link_id',v_link,'replayed',true);
    v_event:='qr_join_replayed';
  else
    select auth_user.phone,auth_user.phone_confirmed_at
      into v_auth_phone,v_phone_confirmed_at
      from auth.users auth_user where auth_user.id=v_actor for share;
    v_phone:=app.norm_phone(v_auth_phone);
    if v_phone_confirmed_at is null or v_phone is null then
      raise exception 'verified customer mobile is required' using errcode='42501';
    end if;
    select * into v_profile from public.customer_profiles profile
      where profile.identity_id=v_identity and profile.auth_user_id=v_actor;
    if not found then
      raise exception 'completed customer profile is required' using errcode='42501';
    end if;
    select client.id into v_client from public.clients client
      where client.business_id=v_qr.business_id and client.phone_norm=v_phone
      for update;
    if found and exists(select 1 from public.customer_links prior
      where prior.business_id=v_qr.business_id and prior.client_id=v_client
        and prior.state='verified') then
      raise exception 'this business relationship cannot be joined automatically'
        using errcode='42501';
    end if;
    if v_client is null then
      insert into public.clients(
        business_id,full_name,phone,birth_date,marketing_consent
      ) values(
        v_qr.business_id,v_profile.full_name,v_phone,v_profile.birth_date,false
      ) returning id into v_client;
    end if;
    v_link:=gen_random_uuid();
    perform set_config('app.customer_link_insert_id',v_link::text,true);
    insert into public.customer_links(
      id,business_id,identity_id,auth_user_id,client_id,state,
      verification_method,verified_at
    ) values(
      v_link,v_qr.business_id,v_identity,v_actor,v_client,'verified','qr_join',now()
    );
    perform set_config('app.customer_link_insert_id','',true);
    perform app.issue_welcome_offer_v215(v_qr.business_id,v_client);
    v_response:=jsonb_build_object('outcome','linked','business_id',
      v_qr.business_id,'link_id',v_link,'replayed',false);
    v_event:='qr_join_linked';
  end if;
  insert into public.customer_link_claim_attempts(
    identity_id,auth_user_id,business_id,link_id,operation,idempotency_key,
    request_hash,outcome,response
  ) values(
    v_identity,v_actor,v_qr.business_id,v_link,'qr_join',
    p_idempotency_key::text,v_hash,'linked',v_response
  );
  insert into public.customer_link_audit_events(
    identity_id,actor_auth_user_id,business_id,client_id,link_id,event_type,
    idempotency_key,request_hash,response
  ) values(
    v_identity,v_actor,v_qr.business_id,v_client,v_link,v_event,
    p_idempotency_key::text,v_hash,v_response
  );
  return v_response;
end
$$;

--
-- Name: FUNCTION customer_join_business_from_qr_v89_base_v90(p_join_token text, p_idempotency_key uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.customer_join_business_from_qr_v89_base_v90(p_join_token text, p_idempotency_key uuid) IS 'Authenticated QR-only customer enrolment. Raw merchant token is never stored.';

--
-- Name: customer_list_business_directory_v242(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_list_business_directory_v242() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_result jsonb;
begin
  if v_actor is null then
    raise exception 'authenticated customer required' using errcode='28000';
  end if;
  select coalesce(jsonb_agg(entry order by (entry->>'joined') desc, entry->>'name'), '[]'::jsonb)
    into v_result
  from (
    select jsonb_build_object(
      'business_id', b.id,
      'name', b.name,
      'slug', b.slug,
      'brand_color', b.brand_color,
      'industry', b.industry,
      'joined', (cl.id is not null),
      'points_balance', case when cl.id is null then null else coalesce((
        select sum(pl.points) from public.points_ledger pl
         where pl.business_id = b.id and pl.client_id = cl.client_id), 0) end,
      'earn_points_per_dollar', lp.earn_points_per_dollar,
      'loyalty_model', lp.loyalty_model,
      'points_mode', b.points_mode
    ) as entry
    from public.businesses b
    left join public.customer_links cl
      on cl.business_id = b.id and cl.auth_user_id = v_actor
     and cl.state = 'verified' and cl.unlinked_at is null
    left join public.loyalty_programs lp
      on lp.business_id = b.id and lp.active
    where b.join_enabled
  ) listed;
  return v_result;
end
$$;

--
-- Name: customer_list_in_app_inbox(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_list_in_app_inbox(p_business_slug text, p_cursor jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $_$
declare
  v_context record; v_limit integer := 20; v_cursor_at timestamptz; v_cursor_id uuid;
  v_has_cursor boolean := false; v_count integer := 0; v_has_more boolean := false;
  v_items jsonb := '[]'::jsonb; v_row record; v_last_at timestamptz; v_last_id uuid;
  v_quiet boolean; v_filter text; v_actionable_source_available boolean;
begin
  if not app.platform_feature_enabled('customer_in_app_inbox') then
    raise exception 'customer in-app inbox is not enabled' using errcode='0A000';
  end if;
  select * into v_context from app.c46_customer_inbox_context(p_business_slug);
  v_actionable_source_available:=app.platform_feature_enabled('customer_actionable_wallet');
  if p_cursor is null then p_cursor:='{}'::jsonb; end if;
  if jsonb_typeof(p_cursor) <> 'object' or p_cursor - 'limit' - 'filter' - 'created_at' - 'event_id' <> '{}'::jsonb then
    raise exception 'invalid inbox cursor' using errcode='22023';
  end if;
  v_filter:=lower(coalesce(p_cursor->>'filter','all'));
  if v_filter not in ('all','unread') then raise exception 'invalid inbox filter' using errcode='22023'; end if;
  if p_cursor ? 'limit' then
    if (p_cursor->>'limit') !~ '^[0-9]{1,2}$' then raise exception 'invalid inbox cursor' using errcode='22023'; end if;
    v_limit:=least(greatest((p_cursor->>'limit')::integer,1),50);
  end if;
  if (p_cursor ? 'created_at') <> (p_cursor ? 'event_id') then
    raise exception 'invalid inbox cursor' using errcode='22023';
  end if;
  if p_cursor ? 'created_at' then
    begin
      v_cursor_at:=(p_cursor->>'created_at')::timestamptz;
      v_cursor_id:=(p_cursor->>'event_id')::uuid;
    exception when others then
      raise exception 'invalid inbox cursor' using errcode='22023';
    end;
    v_has_cursor:=true;
  end if;
  for v_row in
    select e.id,e.title,e.body,e.route_key,e.created_at,e.deadline_at,e.topic,e.source_kind,s.read_at,r.id as resolution_id,
           app.c46_inbox_source_available(e.source_kind,v_actionable_source_available) as source_available
      from public.customer_in_app_inbox_events e
      left join public.customer_in_app_inbox_state s on s.event_id=e.id
      left join public.customer_in_app_inbox_resolutions r on r.event_id=e.id
     where e.business_id=v_context.business_id and e.identity_id=v_context.identity_id
       and e.link_id=v_context.link_id and s.dismissed_at is null
       and (v_filter='all' or (
         r.id is null
         and app.c46_inbox_source_available(e.source_kind,v_actionable_source_available)
         and s.read_at is null
       ))
       and (not v_has_cursor or (e.created_at,e.id) < (v_cursor_at,v_cursor_id))
     order by e.created_at desc,e.id desc
     limit v_limit+1
  loop
    v_count:=v_count+1;
    if v_count > v_limit then v_has_more:=true; exit; end if;
    v_items:=v_items || jsonb_build_array(jsonb_build_object(
      'event_id',v_row.id,'title',v_row.title,'body',v_row.body,
      'route_key',case when v_row.resolution_id is null and v_row.source_available then v_row.route_key else null end,
      'action_available',v_row.resolution_id is null and v_row.source_available,
      'created_at',v_row.created_at,'deadline_at',v_row.deadline_at,'topic',v_row.topic,
      'source',v_row.source_kind,'state',case when v_row.resolution_id is not null then 'resolved'
        when not v_row.source_available then 'source_unavailable'
        when v_row.read_at is null then 'unread' else 'read' end
    ));
    v_last_at:=v_row.created_at; v_last_id:=v_row.id;
  end loop;
  select exists (
    select 1 from (values ('value_expiry'::text),('reward_ready'::text),('visit_progress'::text),
                         ('birthday_benefit'::text),('booking_updates'::text)) topics(topic)
    join lateral app.c46_in_app_preference_for_context(
      v_context.business_id,v_context.identity_id,v_context.link_id,topics.topic
    ) p on true
    where p.opted_in and (v_actionable_source_available or topics.topic='booking_updates')
      and app.c46_in_quiet_hours(
      p.quiet_hours_timezone,p.quiet_hours_start,p.quiet_hours_end,statement_timestamp()
    )
  ) into v_quiet;
  return jsonb_build_object('items',v_items,'next_cursor',case when v_has_more then
    jsonb_build_object('limit',v_limit,'filter',v_filter,'created_at',v_last_at,'event_id',v_last_id) else null end,
    'filter',v_filter,'quiet_hours_active',v_quiet,
    'actionable_source_available',v_actionable_source_available);
end;
$_$;

--
-- Name: customer_list_in_app_inbox_global(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_list_in_app_inbox_global(p_cursor jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $_$
declare
  v_context record; v_limit integer:=20; v_filter text; v_cursor_at timestamptz; v_cursor_id uuid;
  v_has_cursor boolean:=false; v_count integer:=0; v_has_more boolean:=false;
  v_items jsonb:='[]'::jsonb; v_row record; v_last_at timestamptz; v_last_id uuid;
  v_actionable_source_available boolean;
begin
  if not app.platform_feature_enabled('customer_in_app_inbox') then
    raise exception 'customer in-app inbox is not enabled' using errcode='0A000';
  end if;
  select * into v_context from app.c46_customer_inbox_global_context();
  v_actionable_source_available:=app.platform_feature_enabled('customer_actionable_wallet');
  if p_cursor is null then p_cursor:='{}'::jsonb; end if;
  if jsonb_typeof(p_cursor)<>'object'
     or p_cursor-'limit'-'filter'-'created_at'-'event_id'<>'{}'::jsonb then
    raise exception 'invalid inbox cursor' using errcode='22023';
  end if;
  v_filter:=lower(coalesce(p_cursor->>'filter','all'));
  if v_filter not in ('all','unread') then raise exception 'invalid inbox filter' using errcode='22023'; end if;
  if p_cursor ? 'limit' then
    if (p_cursor->>'limit') !~ '^[0-9]{1,2}$' then raise exception 'invalid inbox cursor' using errcode='22023'; end if;
    v_limit:=least(greatest((p_cursor->>'limit')::integer,1),50);
  end if;
  if (p_cursor?'created_at')<>(p_cursor?'event_id') then raise exception 'invalid inbox cursor' using errcode='22023'; end if;
  if p_cursor?'created_at' then
    begin
      v_cursor_at:=(p_cursor->>'created_at')::timestamptz; v_cursor_id:=(p_cursor->>'event_id')::uuid;
    exception when others then raise exception 'invalid inbox cursor' using errcode='22023';
    end;
    v_has_cursor:=true;
  end if;
  for v_row in
    select e.id,e.title,e.body,e.route_key,e.created_at,e.deadline_at,e.topic,e.source_kind,
           b.name as business_name,b.slug as business_slug,s.read_at,r.id as resolution_id,
           app.c46_inbox_source_available(e.source_kind,v_actionable_source_available) as source_available
      from public.customer_in_app_inbox_events e
      join public.customer_links cl on cl.id=e.link_id and cl.business_id=e.business_id
        and cl.client_id=e.client_id and cl.identity_id=e.identity_id and cl.auth_user_id=v_context.auth_user_id
        and cl.state='verified'
      join public.businesses b on b.id=e.business_id
      left join public.customer_in_app_inbox_state s on s.event_id=e.id
      left join public.customer_in_app_inbox_resolutions r on r.event_id=e.id
     where e.identity_id=v_context.identity_id and e.auth_user_id=v_context.auth_user_id
       and s.dismissed_at is null and (v_filter='all' or (
         r.id is null
         and app.c46_inbox_source_available(e.source_kind,v_actionable_source_available)
         and s.read_at is null
       ))
       and (not v_has_cursor or (e.created_at,e.id)<(v_cursor_at,v_cursor_id))
     order by e.created_at desc,e.id desc limit v_limit+1
  loop
    v_count:=v_count+1; if v_count>v_limit then v_has_more:=true; exit; end if;
    v_items:=v_items||jsonb_build_array(jsonb_build_object(
      'event_id',v_row.id,'business',jsonb_build_object('name',v_row.business_name,'slug',v_row.business_slug),
      'route_key',case when v_row.resolution_id is null and v_row.source_available then v_row.route_key else null end,
      'action_available',v_row.resolution_id is null and v_row.source_available,
      'title',v_row.title,'body',v_row.body,'topic',v_row.topic,
      'source',v_row.source_kind,'deadline_at',v_row.deadline_at,'created_at',v_row.created_at,
      'state',case when v_row.resolution_id is not null then 'resolved'
        when not v_row.source_available then 'source_unavailable'
        when v_row.read_at is null then 'unread' else 'read' end
    ));
    v_last_at:=v_row.created_at; v_last_id:=v_row.id;
  end loop;
  return jsonb_build_object('items',v_items,'filter',v_filter,
    'actionable_source_available',v_actionable_source_available,'next_cursor',case when v_has_more then
    jsonb_build_object('limit',v_limit,'filter',v_filter,'created_at',v_last_at,'event_id',v_last_id)
    else null end);
end;
$_$;

--
-- Name: customer_list_my_feedback(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_list_my_feedback(p_business_slug text DEFAULT NULL::text, p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_identity uuid;
  v_business uuid;
  v_limit integer := least(greatest(coalesce(p_limit, 50), 1), 200);
  v_result jsonb;
begin
  if v_actor is null then
    raise exception 'authenticated customer session required' using errcode = '28000';
  end if;
  if p_business_slug is not null then
    select identity_id, business_id into v_identity, v_business
      from app.v53_customer_feedback_context(p_business_slug);
  else
    select ci.id into v_identity
      from public.customer_identities ci
     where ci.auth_user_id = v_actor and ci.status = 'active'
     limit 1;
    if v_identity is null or not exists (
      select 1 from public.customer_links cl
       where cl.identity_id = v_identity and cl.auth_user_id = v_actor and cl.state = 'verified'
    ) then
      raise exception 'verified customer link required' using errcode = '42501';
    end if;
  end if;

  select coalesce(jsonb_agg(app.v53_feedback_json(f) order by f.created_at desc, f.id desc), '[]'::jsonb)
    into v_result
    from (
      select * from public.visit_feedback f
       where f.identity_id = v_identity
         and (v_business is null or f.business_id = v_business)
       order by f.created_at desc, f.id desc
       limit v_limit
    ) f;
  return jsonb_build_object('status', 'ok', 'feedback', v_result);
end $$;

--
-- Name: customer_list_programmes_v89(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_list_programmes_v89() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_identity uuid;v_result jsonb;
begin
  v_identity:=app.v31_current_identity();
  select jsonb_build_object(
    'programmes',coalesce(jsonb_agg(jsonb_build_object(
      'business',jsonb_build_object(
        'id',row_data.business_id,'slug',row_data.slug,'name',row_data.name,
        'industry',row_data.industry,'currency',row_data.currency),
      'capabilities',jsonb_build_object(
        'booking_enabled',row_data.booking_enabled,
        'redemption_enabled',row_data.redemption_enabled,
        'appointment_changes_enabled',row_data.appointment_changes_enabled),
      'loyalty',jsonb_build_object(
        'balance',row_data.points_balance,'unit',row_data.unit),
      'upcoming_appointments',jsonb_build_object('count',row_data.upcoming_count)
    ) order by lower(row_data.name),row_data.business_id),'[]'::jsonb),
    'truncated',false
  ) into v_result
  from (
    select business.id business_id,business.slug,business.name,business.industry,
      business.currency,
      coalesce(capability.booking_enabled,false)
      and app.v89_business_module_enabled(business.id,'bookings') and exists(
        select 1 from public.services service
        where service.business_id=business.id and service.active
          and service.show_on_booking_page
      ) booking_enabled,
      coalesce(capability.redemption_enabled,false)
        and app.v89_business_module_enabled(business.id,'loyalty')
        and program.id is not null redemption_enabled,
      coalesce(capability.appointment_changes_enabled,false)
        and app.v89_business_module_enabled(business.id,'appointments')
        appointment_changes_enabled,
      app.client_points_balance_v409(link.business_id,link.client_id) points_balance,
      case when program.loyalty_model='stamps' then 'stamps' else 'points' end unit,
      (select count(*)::integer from public.appointments appointment
        where appointment.business_id=link.business_id
          and appointment.client_id=link.client_id
          and appointment.status='booked' and appointment.starts_at>=now()) upcoming_count
    from public.customer_links link
    join public.customer_identities identity
      on identity.id=link.identity_id and identity.auth_user_id=link.auth_user_id
    join public.businesses business on business.id=link.business_id
    left join public.business_customer_capabilities_v89 capability
      on capability.business_id=business.id
    left join lateral(
      select programme.id,programme.loyalty_model
      from public.loyalty_programs programme
      where programme.business_id=business.id and programme.active
      order by (programme.current_config_version_id is not null) desc,
        programme.id
      limit 1
    ) program on true
    where link.identity_id=v_identity and link.auth_user_id=auth.uid()
      and link.state='verified' and identity.status='active'
  ) row_data;
  return v_result;
end
$$;

--
-- Name: customer_portal_capabilities(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_portal_capabilities(p_business_slug text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_context record;
  v_points_active boolean;
  v_stamps_active boolean;
  v_tiers_active boolean;
  v_referral_active boolean;
  v_points_programme uuid;
  v_stamps_programme uuid;
  v_tiers_programme uuid;
  v_wallet boolean;
  v_rewards boolean;
  v_tiers boolean;
  v_points_mode text;
  v_programmes jsonb;
begin
  if auth.uid() is null then
    raise exception 'authenticated customer session required' using errcode='28000';
  end if;

  select * into v_context
    from app.v32_customer_wallet_context(p_business_slug)
   limit 1;
  if not found then
    raise exception 'verified customer link required' using errcode='42501';
  end if;

  select
    bool_or(kind = 'points' and active),
    bool_or(kind = 'stamps' and active),
    bool_or(kind = 'tiers' and active),
    bool_or(kind = 'referral' and active)
    into v_points_active, v_stamps_active, v_tiers_active, v_referral_active
    from public.business_programmes
   where business_id = v_context.business_id;
  select id into v_points_programme
    from public.business_programmes
   where business_id = v_context.business_id and kind = 'points' and active
   order by sort, id limit 1;
  select id into v_stamps_programme
    from public.business_programmes
   where business_id = v_context.business_id and kind = 'stamps' and active
   order by sort, id limit 1;
  select id into v_tiers_programme
    from public.business_programmes
   where business_id = v_context.business_id and kind = 'tiers' and active
   order by sort, id limit 1;

  v_wallet := 'loyalty'=any(v_context.enabled_modules)
    and (coalesce(v_points_active,false) or coalesce(v_stamps_active,false)
         or coalesce(v_tiers_active,false));
  v_rewards := 'loyalty'=any(v_context.enabled_modules)
    and (coalesce(v_points_active,false) or coalesce(v_stamps_active,false))
    and exists (
      select 1
        from public.loyalty_reward_versions rv
        join public.businesses business
          on business.id = rv.business_id
         and business.active_config_version_id = rv.config_version_id
        join public.business_programmes spine
          on spine.id = rv.programme_id
         and spine.business_id = rv.business_id
         and spine.active
       where rv.business_id = v_context.business_id
         and rv.active
    );
  v_tiers := 'loyalty'=any(v_context.enabled_modules)
    and coalesce(v_tiers_active,false)
    and exists(select 1 from public.loyalty_tiers tier where tier.business_id=v_context.business_id);
  v_points_mode := case
    when coalesce(v_stamps_active,false) then 'stamps'
    when coalesce(v_points_active,false) and coalesce(v_tiers_active,false) then 'both'
    when coalesce(v_points_active,false) then 'redeem'
    when coalesce(v_tiers_active,false) then 'tiers'
    else null end;

  select coalesce(jsonb_agg(jsonb_build_object(
    'id', spine.id,
    'kind', spine.kind,
    'active', spine.active,
    'running_since', spine.activated_at,
    'paused_since', spine.deactivated_at,
    'balance_scope', 'programme_pot',
    'customer_visible', case spine.kind
      when 'points' then v_rewards and spine.active
      when 'stamps' then v_rewards and spine.active
      when 'tiers' then v_tiers and spine.active
      when 'referral' then coalesce(v_referral_active,false) and spine.active
      else false end
  ) order by spine.sort, spine.kind), '[]'::jsonb)
  into v_programmes
  from public.business_programmes spine
  where spine.business_id = v_context.business_id;

  return jsonb_build_object(
    'wallet', v_wallet,
    'rewards', v_rewards,
    'tiers', v_tiers,
    'points_mode', v_points_mode,
    'activity',
      v_wallet and (
        exists(select 1 from public.points_ledger ledger
                where ledger.business_id=v_context.business_id
                  and ledger.client_id=v_context.client_id
                  and ledger.programme_id in (v_points_programme, v_stamps_programme))
        or exists(select 1 from public.loyalty_redemptions redemption
                   where redemption.business_id=v_context.business_id
                     and redemption.client_id=v_context.client_id)
        or exists(select 1 from public.reward_grants grant_row
                   where grant_row.business_id=v_context.business_id
                     and grant_row.client_id=v_context.client_id)
      ),
    'appointments',
      'appointments'=any(v_context.enabled_modules)
      and exists(select 1 from public.appointments appointment
                  where appointment.business_id=v_context.business_id
                    and appointment.client_id=v_context.client_id),
    'booking_request',
      'bookings'=any(v_context.enabled_modules)
      and exists(select 1 from public.services service
                  where service.business_id=v_context.business_id
                    and service.active),
    'packages',
      'packages'=any(v_context.enabled_modules)
      and exists(select 1 from public.client_packages customer_package
                  where customer_package.business_id=v_context.business_id
                    and customer_package.client_id=v_context.client_id),
    'membership',
      'memberships'=any(v_context.enabled_modules)
      and exists(select 1 from public.memberships membership
                  where membership.business_id=v_context.business_id
                    and membership.client_id=v_context.client_id),
    'programmes_contract', 'v391',
    'programmes', v_programmes
  );
end;
$$;

--
-- Name: FUNCTION customer_portal_capabilities(p_business_slug text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.customer_portal_capabilities(p_business_slug text) IS 'v391: v384 programme capabilities, with running_since/paused_since read from their real columns (activated_at/deactivated_at). v384 read them as columns that do not exist, which raised 42703 on every customer wallet load.';

--
-- Name: customer_prepare_growth_offer_qr_v108(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_prepare_growth_offer_qr_v108(p_entitlement uuid, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_identity uuid;
  v_client uuid;
  v_entitlement public.growth_entitlements_v108%rowtype;
  v_intent public.growth_redemption_intents_v108%rowtype;
  v_token text;
  v_request_hash text;
  v_now timestamptz:=statement_timestamp();
begin
  select identity_row.id into v_identity
    from public.customer_identities identity_row
   where identity_row.auth_user_id=auth.uid()
     and identity_row.status='active';
  if v_identity is null then
    raise exception 'active customer identity required' using errcode='42501';
  end if;
  select * into v_entitlement
    from public.growth_entitlements_v108 entitlement
   where entitlement.id=p_entitlement
   for update;
  if not found then raise exception 'offer not found'; end if;
  v_client:=app.v113_customer_effective_client_id(
    v_entitlement.business_id,v_identity
  );
  if app.v113_effective_client_id(
       v_entitlement.business_id,v_entitlement.client_id
     )<>v_client then
    raise exception 'offer not found' using errcode='42501';
  end if;
  if v_entitlement.status<>'issued' or v_entitlement.expires_at<=v_now then
    raise exception 'offer is not redeemable' using errcode='42501';
  end if;
  v_request_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'identity_id',v_identity,
    'effective_client_id',v_client,
    'entitlement_id',p_entitlement
  )::text,'UTF8'),'sha256'),'hex');
  v_token:=app.growth_v108_token(
    v_identity,v_entitlement.business_id,v_entitlement.id,p_idempotency_key
  );
  select * into v_intent
    from public.growth_redemption_intents_v108 intent
   where intent.identity_id=v_identity
     and intent.idempotency_key=p_idempotency_key;
  if found then
    if v_intent.request_hash<>v_request_hash then
      raise exception 'idempotency key reused with a different QR request'
        using errcode='23505';
    end if;
    return jsonb_build_object(
      'intent_id',v_intent.id,'token',v_token,
      'expires_at',v_intent.expires_at,'replayed',true
    );
  end if;
  insert into public.growth_redemption_intents_v108(
    entitlement_id,business_id,identity_id,token_hash,idempotency_key,
    request_hash,expires_at
  ) values (
    v_entitlement.id,v_entitlement.business_id,v_identity,
    encode(extensions.digest(convert_to(v_token,'UTF8'),'sha256'),'hex'),
    p_idempotency_key,v_request_hash,
    least(v_now+interval '5 minutes',v_entitlement.expires_at)
  ) returning * into v_intent;
  insert into public.growth_entitlement_events_v108(
    entitlement_id,business_id,event_type,actor,idempotency_key,detail
  ) values (
    v_entitlement.id,v_entitlement.business_id,'qr_prepared',auth.uid(),
    p_idempotency_key,jsonb_build_object(
      'intent_id',v_intent.id,
      'identity_attribution','v111_current_effective_identity'
    )
  );
  return jsonb_build_object(
    'intent_id',v_intent.id,'token',v_token,
    'expires_at',v_intent.expires_at,'replayed',false
  );
end
$$;

--
-- Name: customer_record_account_open_v175(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_record_account_open_v175(p_business uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid:=auth.uid();
  v_client uuid;
begin
  if v_actor is null then
    raise exception 'authenticated customer session is required'
      using errcode='28000';
  end if;
  select customer_link.client_id into v_client
  from public.customer_links customer_link
  where customer_link.business_id=p_business
    and customer_link.auth_user_id=v_actor
    and customer_link.state='verified'
  limit 1;
  if v_client is null then
    raise exception 'verified customer relationship is required'
      using errcode='42501';
  end if;
  return app.record_customer_account_open_v175(
    p_business,v_actor,v_client,'wallet',clock_timestamp()
  );
end
$$;

--
-- Name: FUNCTION customer_record_account_open_v175(p_business uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.customer_record_account_open_v175(p_business uuid) IS 'Records a wallet-channel account open for the calling verified customer. The relationship is proved server-side; the caller asserts nothing.';

--
-- Name: customer_register_push_subscription_v95(text, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_register_push_subscription_v95(p_endpoint text, p_p256dh text, p_auth_secret text, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $_$
declare
  v_actor uuid:=auth.uid(); v_identity uuid; v_endpoint text:=btrim(coalesce(p_endpoint,''));
  v_endpoint_hash text; v_request_hash text; v_prior record;
  v_subscription uuid; v_response jsonb; v_existing record;
  v_active_count integer; v_evicted uuid;
begin
  if v_actor is null then raise exception 'authentication required' using errcode='42501'; end if;
  if p_idempotency_key is null then raise exception 'idempotency key is required' using errcode='22023'; end if;
  if length(v_endpoint) not between 20 and 2048
     or not app.customer_push_endpoint_supported_v95(v_endpoint)
     or length(coalesce(p_p256dh,''))<>87
     or p_p256dh !~ '^[A-Za-z0-9_-]{87}$'
     or length(coalesce(p_auth_secret,''))<>22
     or p_auth_secret !~ '^[A-Za-z0-9_-]{22}$' then
    raise exception 'invalid push subscription' using errcode='22023';
  end if;
  select id into v_identity from public.customer_identities
   where auth_user_id=v_actor and status='active'
   order by created_at,id limit 1;
  if v_identity is null then raise exception 'active customer identity required' using errcode='42501'; end if;
  v_endpoint_hash:=app.c46_sha256_hex(v_endpoint);
  v_request_hash:=app.c46_sha256_hex(jsonb_build_object(
    'operation','register','endpoint_hash',v_endpoint_hash,
    'p256dh_hash',app.c46_sha256_hex(p_p256dh),
    'auth_hash',app.c46_sha256_hex(p_auth_secret)
  )::text);
  perform pg_advisory_xact_lock(hashtextextended(v_actor::text||':'||p_idempotency_key::text,95));
  select request_hash,response into v_prior
    from public.customer_push_subscription_operations_v95
   where auth_user_id=v_actor and idempotency_key=p_idempotency_key;
  if found then
    if v_prior.request_hash<>v_request_hash then
      raise exception 'idempotency key conflict' using errcode='22000';
    end if;
    return v_prior.response;
  end if;
  perform pg_advisory_xact_lock(hashtextextended('v95-push-identity:'||v_identity::text,95));
  if (
    select count(*)>=20
      from public.customer_push_subscription_operations_v95
     where identity_id=v_identity and created_at>now()-interval '10 minutes'
  ) then
    raise exception 'push subscription operation rate exceeded' using errcode='54000';
  end if;
  select id,auth_user_id,status into v_existing
    from public.customer_push_subscriptions_v95
   where endpoint_hash=v_endpoint_hash for update;
  if found and v_existing.auth_user_id<>v_actor then
    raise exception 'push subscription unavailable' using errcode='23505';
  end if;
  if not found or v_existing.status<>'active' then
    select count(*)::integer into v_active_count
      from public.customer_push_subscriptions_v95
     where identity_id=v_identity and auth_user_id=v_actor and status='active';
    if v_active_count>=5 then
      select id into v_evicted
        from public.customer_push_subscriptions_v95
       where identity_id=v_identity and auth_user_id=v_actor and status='active'
       order by updated_at,created_at,id
       for update limit 1;
      update public.customer_push_subscriptions_v95
         set status='revoked',revoked_at=now(),updated_at=now()
       where id=v_evicted;
    end if;
  end if;
  insert into public.customer_push_subscriptions_v95(
    identity_id,auth_user_id,endpoint,endpoint_hash,p256dh,auth_secret,status,revoked_at
  ) values(
    v_identity,v_actor,v_endpoint,v_endpoint_hash,p_p256dh,p_auth_secret,'active',null
  )
  on conflict(endpoint_hash) do update set
    identity_id=excluded.identity_id,p256dh=excluded.p256dh,
    auth_secret=excluded.auth_secret,status='active',revoked_at=null,updated_at=now()
  where customer_push_subscriptions_v95.auth_user_id=v_actor
  returning id into v_subscription;
  if v_subscription is null then
    raise exception 'push subscription unavailable' using errcode='23505';
  end if;
  v_response:=jsonb_build_object(
    'subscription_id',v_subscription,'status','active',
    'evicted_subscription_id',v_evicted
  );
  insert into public.customer_push_subscription_operations_v95(
    identity_id,auth_user_id,operation,idempotency_key,request_hash,response
  ) values(v_identity,v_actor,'register',p_idempotency_key,v_request_hash,v_response);
  return v_response;
end
$_$;

--
-- Name: customer_register_verified_phone(text, date, text, text, boolean, boolean, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_register_verified_phone(p_full_name text, p_birth_date date, p_gender text, p_preferred_language text, p_accept_terms boolean, p_accept_privacy boolean, p_platform_marketing_opted_in boolean, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_identity public.customer_identities%rowtype;
  v_existing public.customer_registration_operations%rowtype;
  v_phone text;
  v_phone_confirmed_at timestamptz;
  v_name text := nullif(btrim(p_full_name), '');
  v_gender text := lower(nullif(btrim(p_gender), ''));
  v_language text := lower(nullif(btrim(p_preferred_language), ''));
  v_terms app.customer_legal_documents%rowtype;
  v_privacy app.customer_legal_documents%rowtype;
  v_request_hash text;
  v_response jsonb;
  v_profile_exists boolean;
begin
  if v_actor is null then
    raise exception 'authenticated customer session required' using errcode = '28000';
  end if;
  if not app.platform_feature_enabled('customer_phone_registration')
     or not app.platform_feature_enabled('customer_phone_otp') then
    raise exception 'customer registration is unavailable' using errcode = '0A000';
  end if;
  if p_idempotency_key is null or length(btrim(p_idempotency_key)) < 8
     or v_name is null or p_birth_date is null or p_birth_date > (timezone('Asia/Singapore', now()))::date
     or v_gender not in ('female','male')
     or v_language is null or v_language !~ '^[a-z]{2,3}(-[a-z]{2,4})?$'
     or p_accept_terms is not true or p_accept_privacy is not true then
    raise exception 'invalid customer registration request' using errcode = '22023';
  end if;
  p_idempotency_key := btrim(p_idempotency_key);

  select u.phone, u.phone_confirmed_at into v_phone, v_phone_confirmed_at
    from auth.users u where u.id = v_actor for share;
  if not found or v_phone_confirmed_at is null or nullif(btrim(v_phone), '') is null then
    raise exception 'a verified phone is required to register' using errcode = '42501';
  end if;

  select * into v_terms from app.customer_legal_documents d
   where d.document_key = 'terms' and d.active for share;
  select * into v_privacy from app.customer_legal_documents d
   where d.document_key = 'privacy' and d.active for share;
  if not found or v_terms.document_key is null or v_privacy.document_key is null then
    raise exception 'customer registration is unavailable' using errcode = '0A000';
  end if;

  insert into public.customer_identities (auth_user_id, created_via)
  values (v_actor, 'phone_registration')
  on conflict (auth_user_id) do nothing
  returning * into v_identity;
  if not found then
    select * into v_identity from public.customer_identities
     where auth_user_id = v_actor and status = 'active' for share;
  end if;
  if v_identity.id is null then
    raise exception 'customer registration is unavailable' using errcode = '0A000';
  end if;

  v_request_hash := app.v31_sha256_hex(
    'v163.registration:' || v_actor::text || ':'
    || app.v31_sha256_hex(v_name) || ':' || app.v31_sha256_hex(p_birth_date::text) || ':'
    || v_gender || ':' || v_language || ':' || v_terms.document_version || ':' || v_terms.document_sha256 || ':'
    || v_privacy.document_version || ':' || v_privacy.document_sha256 || ':'
    || coalesce(p_platform_marketing_opted_in, false)::text
  );
  perform pg_advisory_xact_lock(hashtextextended(
    'c42:registration:' || v_identity.id::text || ':' || p_idempotency_key, 0
  ));
  select * into v_existing from public.customer_registration_operations o
   where o.identity_id = v_identity.id and o.operation = 'registration'
     and o.idempotency_key = p_idempotency_key for update;
  if found then
    if v_existing.request_hash is distinct from v_request_hash then
      raise exception 'idempotency key was already used for a different registration request' using errcode = '23505';
    end if;
    return v_existing.response;
  end if;

  perform pg_advisory_xact_lock(hashtextextended('c42:registration-rate:' || v_identity.id::text, 0));
  if (select count(*) from public.customer_registration_operations o
       where o.identity_id = v_identity.id and o.operation = 'registration'
         and o.created_at >= now() - interval '15 minutes') >= 5 then
    v_response := jsonb_build_object('outcome', 'try_later', 'retry_after_seconds', 900);
    insert into public.customer_registration_operations (
      identity_id, actor_auth_user_id, operation, idempotency_key, request_hash, outcome, response
    ) values (v_identity.id, v_actor, 'registration', p_idempotency_key, v_request_hash, 'rate_limited', v_response);
    return v_response;
  end if;

  if not exists (
    select 1 from public.customer_verified_contacts c
     where c.identity_id = v_identity.id and c.contact_type = 'phone' and c.status = 'verified'
  ) then
    insert into public.customer_contact_proofs (
      identity_id, auth_user_id, contact_type, proof_method, status, issued_at, expires_at, verified_at
    ) values (
      v_identity.id, v_actor, 'phone', 'auth_phone_otp', 'verified', now(), now() + interval '15 minutes', now()
    );
    insert into public.customer_verified_contacts (
      identity_id, auth_user_id, contact_type, verification_proof_id
    ) select p.identity_id, p.auth_user_id, p.contact_type, p.id
      from public.customer_contact_proofs p
     where p.identity_id = v_identity.id and p.auth_user_id = v_actor
       and p.contact_type = 'phone' and p.proof_method = 'auth_phone_otp'
     order by p.created_at desc limit 1;
  end if;

  select exists(select 1 from public.customer_profiles p where p.identity_id = v_identity.id)
    into v_profile_exists;
  if v_profile_exists and exists (
    select 1 from public.customer_profiles p
     where p.identity_id = v_identity.id and p.birth_date is distinct from p_birth_date
  ) then
    raise exception 'birth date changes require controlled recovery' using errcode = '23000';
  end if;
  perform set_config('app.c42_profile_identity', v_identity.id::text, true);
  insert into public.customer_profiles (
    identity_id, auth_user_id, full_name, birth_date, gender, preferred_language
  ) values (v_identity.id, v_actor, v_name, p_birth_date, v_gender, v_language)
  on conflict (identity_id) do update set
    full_name = excluded.full_name, gender = excluded.gender, preferred_language = excluded.preferred_language;
  perform set_config('app.c42_profile_identity', '', true);

  insert into public.customer_legal_acceptances (
    identity_id, auth_user_id, document_key, document_version, document_sha256, acceptance_hash
  ) values
    (v_identity.id, v_actor, v_terms.document_key, v_terms.document_version, v_terms.document_sha256,
      app.v31_sha256_hex('c42.acceptance:' || v_actor::text || ':terms:' || v_terms.document_sha256)),
    (v_identity.id, v_actor, v_privacy.document_key, v_privacy.document_version, v_privacy.document_sha256,
      app.v31_sha256_hex('c42.acceptance:' || v_actor::text || ':privacy:' || v_privacy.document_sha256))
  on conflict (identity_id, document_key, document_version, document_sha256) do nothing;

  insert into public.customer_registration_preferences (
    identity_id, auth_user_id, platform_marketing_opted_in
  ) values (v_identity.id, v_actor, coalesce(p_platform_marketing_opted_in, false))
  on conflict (identity_id) do update set
    platform_marketing_opted_in = excluded.platform_marketing_opted_in, updated_at = now();

  v_response := jsonb_build_object('outcome', 'registered', 'profile_ready', true);
  insert into public.customer_registration_operations (
    identity_id, actor_auth_user_id, operation, idempotency_key, request_hash, outcome, response
  ) values (v_identity.id, v_actor, 'registration', p_idempotency_key, v_request_hash, 'completed', v_response);
  return v_response;
end;
$_$;

--
-- Name: FUNCTION customer_register_verified_phone(p_full_name text, p_birth_date date, p_gender text, p_preferred_language text, p_accept_terms boolean, p_accept_privacy boolean, p_platform_marketing_opted_in boolean, p_idempotency_key text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.customer_register_verified_phone(p_full_name text, p_birth_date date, p_gender text, p_preferred_language text, p_accept_terms boolean, p_accept_privacy boolean, p_platform_marketing_opted_in boolean, p_idempotency_key text) IS 'V163 phone customer registration: persists required DOB and owner-requested binary gender with one combined legal/privacy/marketing signup consent.';

--
-- Name: customer_request_appointment_action(text, uuid, text, timestamp with time zone, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_request_appointment_action(p_business_slug text, p_appointment uuid, p_action text, p_proposed_at timestamp with time zone, p_note text, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_slug text := lower(btrim(coalesce(p_business_slug, '')));
  v_action text := lower(btrim(coalesce(p_action, '')));
  v_note text := nullif(btrim(coalesce(p_note, '')), '');
  v_identity_id uuid;
  v_link_id uuid;
  v_business_id uuid;
  v_client_id uuid;
  v_enabled_modules text[];
  v_request_id uuid;
  v_existing public.customer_appointment_action_requests%rowtype;
  v_request_hash text;
  v_response jsonb;
begin
  if v_actor is null then
    raise exception 'authenticated customer session required' using errcode = '28000';
  end if;
  if not app.platform_feature_enabled('customer_actions') then
    raise exception 'verified customer link and appointment required' using errcode = '42501';
  end if;
  if p_idempotency_key is null or length(btrim(p_idempotency_key)) < 8 then
    raise exception 'idempotency key must contain at least 8 characters' using errcode = '22023';
  end if;
  if v_action not in ('cancel', 'reschedule') then
    raise exception 'action must be cancel or reschedule' using errcode = '22023';
  end if;
  if v_action = 'cancel' and p_proposed_at is not null then
    raise exception 'cancel requests cannot include a proposed time' using errcode = '22023';
  end if;
  if v_action = 'reschedule' and (p_proposed_at is null or p_proposed_at <= now()) then
    raise exception 'reschedule time must be in the future' using errcode = '22023';
  end if;
  if v_note is not null and length(v_note) > 750 then
    raise exception 'note must not exceed 750 characters' using errcode = '22023';
  end if;

  p_idempotency_key := btrim(p_idempotency_key);
  v_request_hash := app.v33_sha256_hex(jsonb_build_object(
    'business_slug', v_slug,
    'appointment', p_appointment,
    'action', v_action,
    'proposed_at', p_proposed_at,
    'note', v_note
  )::text);
  perform pg_advisory_xact_lock(hashtextextended(
    'v33:appointment-action:' || v_actor::text || ':' || p_idempotency_key, 0
  ));

  select * into v_existing
    from public.customer_appointment_action_requests r
   where r.identity_id = (
           select ci.id from public.customer_identities ci
            where ci.auth_user_id = v_actor and ci.status = 'active'
         )
     and r.idempotency_key = p_idempotency_key;
  if found then
    if v_existing.request_hash is distinct from v_request_hash then
      raise exception 'idempotency key was already used for another action request' using errcode = '22023';
    end if;
    return jsonb_build_object('request_id', v_existing.id, 'status', v_existing.status);
  end if;

  -- The slug merely narrows the verified customer relationship. The actual
  -- business, client, identity, and link are all derived from auth.uid().
  select ci.id, l.id, l.business_id, l.client_id, coalesce(b.enabled_modules, '{}'::text[])
    into v_identity_id, v_link_id, v_business_id, v_client_id, v_enabled_modules
    from public.customer_identities ci
    join public.customer_links l
      on l.identity_id = ci.id
     and l.auth_user_id = v_actor
     and l.state = 'verified'
    join public.businesses b on b.id = l.business_id
   where ci.auth_user_id = v_actor
     and ci.status = 'active'
     and b.slug = v_slug
   limit 1;
  if not found or not ('appointments' = any(v_enabled_modules)) then
    raise exception 'verified customer link and appointment required' using errcode = '42501';
  end if;

  perform 1
    from public.appointments a
   where a.id = p_appointment
     and a.business_id = v_business_id
     and a.client_id = v_client_id
     and a.status = 'booked'
     and a.starts_at > now()
   for share;
  if not found then
    raise exception 'verified customer link and appointment required' using errcode = '42501';
  end if;

  if (select count(*) from public.customer_appointment_action_requests r
       where r.identity_id = v_identity_id
         and r.created_at >= now() - interval '15 minutes') >= 5 then
    raise exception 'too many appointment action requests; try later' using errcode = '42901';
  end if;

  v_request_id := gen_random_uuid();
  insert into public.customer_appointment_action_requests (
    id, business_id, identity_id, auth_user_id, link_id, client_id,
    appointment_id, action, proposed_at, note, idempotency_key, request_hash
  ) values (
    v_request_id, v_business_id, v_identity_id, v_actor, v_link_id, v_client_id,
    p_appointment, v_action, p_proposed_at, v_note, p_idempotency_key, v_request_hash
  );
  insert into public.customer_notification_outbox (
    business_id, identity_id, link_id, client_id, action_request_id,
    event_type, topic, channel, delivery_status
  ) values (
    v_business_id, v_identity_id, v_link_id, v_client_id, v_request_id,
    'appointment_action_requested', 'booking_updates', 'in_app',
    case when not app.platform_feature_enabled('customer_notifications') or exists (
      select 1 from public.customer_notification_preferences p
       where p.business_id = v_business_id
         and p.link_id = v_link_id
         and p.channel = 'in_app'
         and p.topic = 'booking_updates'
         and not p.opted_in
    ) then 'suppressed' else 'pending' end
  );

  v_response := jsonb_build_object('request_id', v_request_id, 'status', 'pending');
  return v_response;
end;
$$;

--
-- Name: customer_rotate_member_qr_v327(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_rotate_member_qr_v327() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_identity public.customer_identities%rowtype;
  v_token text;
begin
  if v_actor is null then
    raise exception 'authenticated customer session required' using errcode='28000';
  end if;
  select * into v_identity from public.customer_identities
   where auth_user_id=v_actor for update;
  if not found then
    raise exception 'a platform identity is required before a member QR can be rotated'
      using errcode='42501';
  end if;

  update public.customer_identities
     set qr_token_version = qr_token_version + 1
   where id = v_identity.id
  returning * into v_identity;

  v_token := app.v327_member_qr_token(v_identity.id, v_identity.qr_token_version);
  update public.customer_identities
     set qr_token_hash = app.v89_sha256(v_token), updated_at = now()
   where id = v_identity.id;

  return jsonb_build_object(
    'identity_id', v_identity.id,
    'member_qr', 'nestly:member:'||v_token,
    'token_version', v_identity.qr_token_version
  );
end $$;

--
-- Name: customer_set_all_communications_v263(boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_set_all_communications_v263(p_enabled boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_identity uuid := app.customer_communication_identity_v263();
  v_now timestamptz := now();
begin
  if p_enabled is null then
    raise exception 'unsupported communication preference' using errcode = '22023';
  end if;

  if p_enabled then
    delete from public.customer_communication_preferences_v263 preference
     where preference.identity_id = v_identity;
  else
    insert into public.customer_communication_preferences_v263 (
      identity_id, auth_user_id, category, channel, enabled, decided_at, updated_at
    )
    select v_identity, v_actor, catalog.category, channels.channel, false, v_now, v_now
      from unnest(app.communication_categories_v263()) as catalog(category)
     cross join unnest(app.communication_channels_v263()) as channels(channel)
    on conflict (identity_id, category, channel) do update
      set enabled = false,
          decided_at = excluded.decided_at,
          updated_at = excluded.updated_at,
          auth_user_id = excluded.auth_user_id;
  end if;

  insert into public.customer_communication_preference_audit_v263 (
    identity_id, auth_user_id, scope, category, channel, enabled, source, request_hash
  ) values (
    v_identity, v_actor, 'all', null, null, p_enabled, 'communications_screen',
    app.v33_sha256_hex(jsonb_build_object(
      'identity_id', v_identity, 'scope', 'all', 'enabled', p_enabled
    )::text)
  );

  return jsonb_build_object('all_enabled', p_enabled, 'decided_at', v_now);
end;
$$;

--
-- Name: customer_set_birthday_participation(boolean, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_set_birthday_participation(p_opted_in boolean, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_identity uuid; v_request_hash text; v_operation public.customer_birthday_participation_operations%rowtype;
begin
  if auth.uid() is null then raise exception 'authenticated customer session required' using errcode='28000'; end if;
  if not app.platform_feature_enabled('customer_birthday_benefits') then raise exception 'birthday benefits are unavailable' using errcode='0A000'; end if;
  if p_opted_in is null then raise exception 'birthday participation request is invalid' using errcode='22023'; end if;
  select id into v_identity from public.customer_identities where auth_user_id=auth.uid() and status='active' for update;
  if not found or p_idempotency_key is null then raise exception 'birthday benefits are unavailable' using errcode='42501'; end if;
  v_request_hash:=app.c45_hash(jsonb_build_object('opted_in',p_opted_in)::text);
  select * into v_operation from public.customer_birthday_participation_operations where identity_id=v_identity and idempotency_key=p_idempotency_key for share;
  if found then
    if v_operation.request_hash is distinct from v_request_hash then raise exception 'birthday participation request conflicts with an existing operation' using errcode='40001'; end if;
    return jsonb_build_object('opted_in',v_operation.opted_in,'replayed',true);
  end if;
  insert into public.customer_birthday_participation(identity_id,auth_user_id,opted_in,updated_at)
  values(v_identity,auth.uid(),p_opted_in,now())
  on conflict(identity_id) do update set opted_in=excluded.opted_in,updated_at=excluded.updated_at;
  insert into public.customer_birthday_participation_operations(identity_id,actor_auth_user_id,idempotency_key,request_hash,opted_in)
  values(v_identity,auth.uid(),p_idempotency_key,v_request_hash,p_opted_in);
  return jsonb_build_object('opted_in',p_opted_in,'replayed',false);
end $$;

--
-- Name: customer_set_communication_preference_v263(text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_set_communication_preference_v263(p_category text, p_channel text, p_enabled boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_identity uuid := app.customer_communication_identity_v263();
  v_category text := lower(btrim(coalesce(p_category, '')));
  v_channel text := lower(btrim(coalesce(p_channel, '')));
  v_now timestamptz := now();
begin
  if p_enabled is null
     or not (v_category = any (app.communication_categories_v263()))
     or not (v_channel = any (app.communication_channels_v263())) then
    raise exception 'unsupported communication preference' using errcode = '22023';
  end if;

  insert into public.customer_communication_preferences_v263 (
    identity_id, auth_user_id, category, channel, enabled, decided_at, updated_at
  ) values (
    v_identity, v_actor, v_category, v_channel, p_enabled, v_now, v_now
  )
  on conflict (identity_id, category, channel) do update
    set enabled = excluded.enabled,
        decided_at = excluded.decided_at,
        updated_at = excluded.updated_at,
        auth_user_id = excluded.auth_user_id;

  insert into public.customer_communication_preference_audit_v263 (
    identity_id, auth_user_id, scope, category, channel, enabled, source, request_hash
  ) values (
    v_identity, v_actor, 'single', v_category, v_channel, p_enabled, 'communications_screen',
    app.v33_sha256_hex(jsonb_build_object(
      'identity_id', v_identity, 'category', v_category,
      'channel', v_channel, 'enabled', p_enabled
    )::text)
  );

  return jsonb_build_object(
    'category', v_category,
    'channel', v_channel,
    'enabled', p_enabled,
    'decided_at', v_now
  );
end;
$$;

--
-- Name: customer_set_in_app_inbox_preferences(text, text, boolean, text, time without time zone, time without time zone, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_set_in_app_inbox_preferences(p_business_slug text, p_topic text, p_opted_in boolean, p_quiet_hours_timezone text, p_quiet_hours_start time without time zone, p_quiet_hours_end time without time zone, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_context record; v_topic text; v_timezone text;
  v_now timestamptz := statement_timestamp(); v_preference_id uuid;
  v_idempotency text; v_request_hash text; v_existing public.customer_preference_audit%rowtype;
begin
  if not app.platform_feature_enabled('customer_in_app_inbox') then
    raise exception 'customer in-app inbox is not enabled' using errcode='0A000';
  end if;
  v_topic:=lower(btrim(coalesce(p_topic, '')));
  v_timezone:=nullif(btrim(coalesce(p_quiet_hours_timezone, '')), '');
  if p_idempotency_key is null or p_opted_in is null or not app.c46_in_app_topic_allowed(v_topic) then
    raise exception 'invalid in-app inbox preference' using errcode = '22023';
  end if;
  if (v_timezone is null and (p_quiet_hours_start is not null or p_quiet_hours_end is not null))
     or (v_timezone is not null and (
       p_quiet_hours_start is null or p_quiet_hours_end is null
       or p_quiet_hours_start = p_quiet_hours_end
       or not app.c46_iana_timezone_allowed(v_timezone)
     )) then
    raise exception 'quiet hours must use a valid IANA timezone and two different times' using errcode = '22023';
  end if;
  select * into v_context from app.c46_customer_inbox_context(p_business_slug);
  -- Linearization point for C46 consent: C45 participation setters already
  -- lock this same active identity row. Taking it before any preference read
  -- or mutation means an opt-out/participation withdrawal and a C46 sync are
  -- ordered as one serial history for this customer.
  perform 1 from public.customer_identities ci
   where ci.id=v_context.identity_id and ci.auth_user_id=v_context.auth_user_id and ci.status='active'
   for update;
  if not found then raise exception 'active customer identity required' using errcode='42501'; end if;
  v_idempotency := 'c46:in-app-preference:' || p_idempotency_key::text;
  v_request_hash := app.c46_sha256_hex(jsonb_build_object(
    'business_slug',v_context.business_slug,'topic',v_topic,'opted_in',p_opted_in,
    'quiet_hours_timezone',v_timezone,'quiet_hours_start',p_quiet_hours_start,
    'quiet_hours_end',p_quiet_hours_end
  )::text);
  perform pg_advisory_xact_lock(hashtextextended(
    'c46:in-app-preference:' || v_context.identity_id::text || ':' || p_idempotency_key::text, 0
  ));
  select * into v_existing from public.customer_preference_audit a
   where a.identity_id = v_context.identity_id and a.idempotency_key = v_idempotency;
  if found then
    if v_existing.request_hash is distinct from v_request_hash then
      raise exception 'idempotency key conflicts with another inbox preference' using errcode = '40001';
    end if;
    return jsonb_build_object('topic',v_existing.topic,'opted_in',v_existing.opted_in,
      'quiet_hours_timezone',v_existing.quiet_hours_timezone,
      'quiet_hours_start',v_existing.quiet_hours_start,'quiet_hours_end',v_existing.quiet_hours_end,
      'consent_at',v_existing.consent_at);
  end if;
  insert into public.customer_notification_preferences(
    business_id,identity_id,auth_user_id,link_id,client_id,channel,topic,opted_in,consent_at,
    quiet_hours_timezone,quiet_hours_start,quiet_hours_end,updated_at
  ) values (
    v_context.business_id,v_context.identity_id,v_context.auth_user_id,v_context.link_id,v_context.client_id,
    'in_app',v_topic,p_opted_in,v_now,v_timezone,p_quiet_hours_start,p_quiet_hours_end,v_now
  ) on conflict (business_id,link_id,channel,topic) do update set
    opted_in=excluded.opted_in,consent_at=excluded.consent_at,
    quiet_hours_timezone=excluded.quiet_hours_timezone,quiet_hours_start=excluded.quiet_hours_start,
    quiet_hours_end=excluded.quiet_hours_end,updated_at=excluded.updated_at
  returning id into v_preference_id;
  insert into public.customer_preference_audit(
    preference_id,business_id,identity_id,auth_user_id,link_id,client_id,channel,topic,opted_in,consent_at,
    quiet_hours_timezone,quiet_hours_start,quiet_hours_end,idempotency_key,request_hash
  ) values (
    v_preference_id,v_context.business_id,v_context.identity_id,v_context.auth_user_id,v_context.link_id,
    v_context.client_id,'in_app',v_topic,p_opted_in,v_now,v_timezone,p_quiet_hours_start,p_quiet_hours_end,
    v_idempotency,v_request_hash
  );
  return jsonb_build_object('topic',v_topic,'opted_in',p_opted_in,
    'quiet_hours_timezone',v_timezone,'quiet_hours_start',p_quiet_hours_start,
    'quiet_hours_end',p_quiet_hours_end,'consent_at',v_now);
end;
$$;

--
-- Name: customer_set_in_app_inbox_state(text, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_set_in_app_inbox_state(p_business_slug text, p_event_id uuid, p_operation text, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_context record; v_event public.customer_in_app_inbox_events%rowtype;
  v_operation text; v_existing public.customer_in_app_inbox_state_operations%rowtype;
  v_request_hash text; v_now timestamptz:=statement_timestamp(); v_response jsonb;
  v_state public.customer_in_app_inbox_state%rowtype;
begin
  if not app.platform_feature_enabled('customer_in_app_inbox') then
    raise exception 'customer in-app inbox is not enabled' using errcode='0A000';
  end if;
  v_operation:=lower(btrim(coalesce(p_operation,'')));
  if p_event_id is null or p_idempotency_key is null or v_operation not in ('read','unread','dismiss') then
    raise exception 'invalid inbox state operation' using errcode='22023';
  end if;
  select * into v_context from app.c46_customer_inbox_context(p_business_slug);
  v_request_hash:=app.c46_sha256_hex(jsonb_build_object(
    'business_slug',v_context.business_slug,'event_id',p_event_id,'operation',v_operation
  )::text);
  perform pg_advisory_xact_lock(hashtextextended(
    'c46:in-app-state:'||v_context.identity_id::text||':'||p_idempotency_key::text,0
  ));
  select * into v_existing from public.customer_in_app_inbox_state_operations o
   where o.identity_id=v_context.identity_id and o.idempotency_key=p_idempotency_key;
  if found then
    if v_existing.request_hash is distinct from v_request_hash then
      raise exception 'idempotency key conflicts with another inbox state operation' using errcode='40001';
    end if;
    return v_existing.response;
  end if;
  select * into v_event from public.customer_in_app_inbox_events e
   where e.id=p_event_id and e.business_id=v_context.business_id and e.identity_id=v_context.identity_id
     and e.link_id=v_context.link_id and e.client_id=v_context.client_id
     and not exists (select 1 from public.customer_in_app_inbox_resolutions r where r.event_id=e.id)
   for update;
  if not found then raise exception 'inbox item is unavailable' using errcode='42501'; end if;
  perform set_config('app.c46_inbox_state_event',p_event_id::text,true);
  insert into public.customer_in_app_inbox_state(
    event_id,business_id,identity_id,auth_user_id,link_id,client_id,read_at,dismissed_at
  ) values (
    v_event.id,v_event.business_id,v_event.identity_id,v_event.auth_user_id,v_event.link_id,v_event.client_id,
    case when v_operation in ('read','dismiss') then v_now else null end,
    case when v_operation='dismiss' then v_now else null end
  ) on conflict (event_id) do update set
    -- Dismissal is terminal. A later read/unread request is still recorded as
    -- immutable operation evidence, but may never clear dismissed_at or
    -- resurrect the card. This also makes unread-vs-dismiss races converge on
    -- dismissed regardless of lock acquisition order.
    read_at=case
      when public.customer_in_app_inbox_state.dismissed_at is not null then public.customer_in_app_inbox_state.read_at
      when v_operation='unread' then null
      else coalesce(public.customer_in_app_inbox_state.read_at,v_now)
    end,
    dismissed_at=case
      when public.customer_in_app_inbox_state.dismissed_at is not null then public.customer_in_app_inbox_state.dismissed_at
      when v_operation='dismiss' then v_now
      else null
    end
  returning * into v_state;
  v_response:=jsonb_build_object('event_id',v_event.id,'state',
    case when v_state.dismissed_at is not null then 'dismissed'
         when v_state.read_at is not null then 'read' else 'unread' end
  );
  insert into public.customer_in_app_inbox_state_operations(
    event_id,business_id,identity_id,auth_user_id,link_id,client_id,operation,idempotency_key,request_hash,response
  ) values (
    v_event.id,v_event.business_id,v_event.identity_id,v_event.auth_user_id,v_event.link_id,v_event.client_id,
    v_operation,p_idempotency_key,v_request_hash,v_response
  );
  return v_response;
end;
$$;

--
-- Name: customer_set_locale_preference_v95(text, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_set_locale_preference_v95(p_locale text, p_expected_version bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_actor uuid:=auth.uid();v_row public.customer_locale_preferences_v95%rowtype;
begin
  if v_actor is null then raise exception 'authenticated_session_required'
    using errcode='28000';end if;
  if p_locale not in ('en','zh-CN') or p_expected_version is null then
    raise exception 'supported_locale_and_version_required' using errcode='22023';
  end if;
  select * into v_row from public.customer_locale_preferences_v95
  where auth_user_id=v_actor for update;
  if found then
    if v_row.version<>p_expected_version then
      raise exception 'locale_version_conflict' using errcode='40001';
    end if;
    update public.customer_locale_preferences_v95
    set locale=p_locale,version=version+1,updated_at=now()
    where auth_user_id=v_actor returning * into v_row;
  else
    if p_expected_version<>0 then
      raise exception 'locale_version_conflict' using errcode='40001';
    end if;
    insert into public.customer_locale_preferences_v95(auth_user_id,locale)
    values(v_actor,p_locale) returning * into v_row;
  end if;
  return jsonb_build_object('locale',v_row.locale,'version',v_row.version);
end
$$;

--
-- Name: customer_set_notification_preference(text, text, text, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_set_notification_preference(p_business_slug text, p_channel text, p_topic text, p_opted_in boolean, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_channel text := lower(btrim(coalesce(p_channel, '')));
  v_topic text := lower(btrim(coalesce(p_topic, '')));
  v_identity_id uuid;
  v_link_id uuid;
  v_business_id uuid;
  v_client_id uuid;
  v_preference_id uuid;
  v_existing public.customer_preference_audit%rowtype;
  v_request_hash text;
  v_now timestamptz := now();
begin
  if v_actor is null then
    raise exception 'authenticated customer session required' using errcode = '28000';
  end if;
  if not app.platform_feature_enabled('customer_notifications') then
    raise exception 'verified customer link required' using errcode = '42501';
  end if;
  if p_idempotency_key is null or length(btrim(p_idempotency_key)) < 8 then
    raise exception 'idempotency key must contain at least 8 characters' using errcode = '22023';
  end if;
  if v_channel not in ('email', 'in_app') or v_topic not in ('marketing', 'booking_updates', 'loyalty_updates')
     or p_opted_in is null then
    raise exception 'unsupported notification preference' using errcode = '22023';
  end if;
  p_idempotency_key := btrim(p_idempotency_key);
  v_request_hash := app.v33_sha256_hex(jsonb_build_object(
    'business_slug', lower(btrim(coalesce(p_business_slug, ''))),
    'channel', v_channel, 'topic', v_topic, 'opted_in', p_opted_in
  )::text);
  perform pg_advisory_xact_lock(hashtextextended(
    'v33:notification-preference:' || v_actor::text || ':' || p_idempotency_key, 0
  ));

  select ci.id, l.id, l.business_id, l.client_id
    into v_identity_id, v_link_id, v_business_id, v_client_id
    from public.customer_identities ci
    join public.customer_links l
      on l.identity_id = ci.id and l.auth_user_id = v_actor and l.state = 'verified'
    join public.businesses b on b.id = l.business_id
   where ci.auth_user_id = v_actor and ci.status = 'active'
     and b.slug = lower(btrim(coalesce(p_business_slug, '')))
   limit 1;
  if not found then
    raise exception 'verified customer link required' using errcode = '42501';
  end if;

  select * into v_existing
    from public.customer_preference_audit a
   where a.identity_id = v_identity_id and a.idempotency_key = p_idempotency_key;
  if found then
    if v_existing.request_hash is distinct from v_request_hash then
      raise exception 'idempotency key was already used for another preference' using errcode = '22023';
    end if;
    return jsonb_build_object(
      'channel', v_existing.channel,
      'topic', v_existing.topic,
      'opted_in', v_existing.opted_in,
      'consent_at', v_existing.consent_at
    );
  end if;

  insert into public.customer_notification_preferences (
    business_id, identity_id, auth_user_id, link_id, client_id,
    channel, topic, opted_in, consent_at, updated_at
  ) values (
    v_business_id, v_identity_id, v_actor, v_link_id, v_client_id,
    v_channel, v_topic, p_opted_in, v_now, v_now
  )
  on conflict (business_id, link_id, channel, topic) do update
    set opted_in = excluded.opted_in,
        consent_at = excluded.consent_at,
        updated_at = excluded.updated_at
  returning id into v_preference_id;

  insert into public.customer_preference_audit (
    preference_id, business_id, identity_id, auth_user_id, link_id, client_id,
    channel, topic, opted_in, consent_at, idempotency_key, request_hash
  ) values (
    v_preference_id, v_business_id, v_identity_id, v_actor, v_link_id, v_client_id,
    v_channel, v_topic, p_opted_in, v_now, p_idempotency_key, v_request_hash
  );
  return jsonb_build_object(
    'channel', v_channel,
    'topic', v_topic,
    'opted_in', p_opted_in,
    'consent_at', v_now
  );
end;
$$;

--
-- Name: customer_set_platform_marketing_preference(boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_set_platform_marketing_preference(p_opted_in boolean, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_identity uuid;
  v_existing public.customer_platform_marketing_consent_events%rowtype;
begin
  if v_actor is null then
    raise exception 'authenticated customer session required' using errcode = '28000';
  end if;
  if p_opted_in is null
     or p_idempotency_key is null
     or length(btrim(p_idempotency_key)) < 8 then
    raise exception 'invalid platform marketing preference request' using errcode = '22023';
  end if;
  p_idempotency_key := btrim(p_idempotency_key);
  v_identity := app.v31_current_identity();
  perform pg_advisory_xact_lock(hashtextextended(
    'v92:platform-marketing:' || v_identity::text || ':' || p_idempotency_key, 0
  ));
  select * into v_existing
    from public.customer_platform_marketing_consent_events e
   where e.identity_id = v_identity and e.idempotency_key = p_idempotency_key
   for update;
  if found then
    if v_existing.opted_in is distinct from p_opted_in then
      raise exception 'idempotency key was already used for a different marketing preference'
        using errcode = '23505';
    end if;
    return jsonb_build_object('outcome', 'updated', 'opted_in', v_existing.opted_in);
  end if;
  perform set_config('app.v92_marketing_source', 'customer_profile', true);
  perform set_config('app.v92_marketing_idempotency_key', p_idempotency_key, true);
  update public.customer_registration_preferences p
     set platform_marketing_opted_in = p_opted_in,
         updated_at = now()
   where p.identity_id = v_identity and p.auth_user_id = v_actor;
  if not found then
    raise exception 'customer marketing preference is unavailable' using errcode = '42501';
  end if;
  perform set_config('app.v92_marketing_source', '', true);
  perform set_config('app.v92_marketing_idempotency_key', '', true);
  return jsonb_build_object('outcome', 'updated', 'opted_in', p_opted_in);
end;
$$;

--
-- Name: customer_submit_visit_feedback(text, uuid, integer, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_submit_visit_feedback(p_business_slug text, p_sale uuid, p_rating integer, p_comment text, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_ctx record;
  v_comment text := nullif(btrim(p_comment), '');
  v_status text;
  v_row public.visit_feedback%rowtype;
  v_existing public.visit_feedback%rowtype;
begin
  select * into v_ctx from app.v53_customer_feedback_context(p_business_slug);
  if p_idempotency_key is null then
    raise exception 'an idempotency key is required' using errcode = '22023';
  end if;
  if p_rating is null or p_rating < 1 or p_rating > 5 then
    raise exception 'rating must be between 1 and 5' using errcode = '22023';
  end if;
  if v_comment is not null and length(v_comment) > 2000 then
    raise exception 'comment is too long' using errcode = '22023';
  end if;
  if p_sale is not null and not exists (
    select 1 from public.sales s
     where s.id = p_sale
       and s.business_id = v_ctx.business_id
       and s.client_id = v_ctx.client_id
       and s.reversal_of is null
  ) then
    raise exception 'that visit is not on your account' using errcode = '42501';
  end if;

  v_status := case when p_rating <= 3 then 'open' else 'closed' end;

  perform pg_advisory_xact_lock(hashtextextended(
    'v53:feedback:' || v_ctx.identity_id::text || ':' || p_idempotency_key::text, 0));

  select * into v_existing from public.visit_feedback f
   where f.identity_id = v_ctx.identity_id and f.idempotency_key = p_idempotency_key;
  if found then
    if v_existing.rating <> p_rating
       or v_existing.comment is distinct from v_comment
       or v_existing.sale_id is distinct from p_sale then
      raise exception 'idempotency key conflicts with a different feedback submission'
        using errcode = '40001';
    end if;
    return app.v53_feedback_json(v_existing);
  end if;

  begin
    insert into public.visit_feedback(
      business_id, identity_id, link_id, client_id, auth_user_id,
      sale_id, rating, comment, idempotency_key, recovery_status)
    values (
      v_ctx.business_id, v_ctx.identity_id, v_ctx.link_id, v_ctx.client_id, v_ctx.auth_user_id,
      p_sale, p_rating::smallint, v_comment, p_idempotency_key, v_status)
    returning * into v_row;
  exception when unique_violation then
    -- A concurrent same-key winner replays; a different key for the same visit/general
    -- slot is a genuine duplicate.
    select * into v_existing from public.visit_feedback f
     where f.identity_id = v_ctx.identity_id and f.idempotency_key = p_idempotency_key;
    if found then
      return app.v53_feedback_json(v_existing);
    end if;
    raise exception 'you have already left feedback for this visit'
      using errcode = '23505';
  end;

  return app.v53_feedback_json(v_row);
end $$;

--
-- Name: customer_sync_in_app_inbox(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_sync_in_app_inbox(p_business_slug text, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_context record; v_existing public.customer_in_app_inbox_sync_operations%rowtype;
  v_request_hash text; v_card jsonb; v_candidate record; v_preference record;
  v_dedupe_key text; v_cycle integer; v_created integer := 0; v_resolved integer := 0; v_rows integer;
  v_response jsonb; v_active_source_keys text[] := '{}'::text[];
  v_actionable_source_available boolean; v_birthday_participating boolean := false;
begin
  if not app.platform_feature_enabled('customer_in_app_inbox') then
    raise exception 'customer in-app inbox is not enabled' using errcode='0A000';
  end if;
  if p_idempotency_key is null then raise exception 'idempotency key is required' using errcode='22023'; end if;
  select * into v_context from app.c46_customer_inbox_context(p_business_slug);
  -- Same linearization point as the C46 preference setter and C45
  -- participation setter. Source, preference, and participation reads below
  -- cannot interleave with an opt-out for this identity.
  perform 1 from public.customer_identities ci
   where ci.id=v_context.identity_id and ci.auth_user_id=v_context.auth_user_id and ci.status='active'
   for update;
  if not found then raise exception 'active customer identity required' using errcode='42501'; end if;
  v_request_hash:=app.c46_sha256_hex(jsonb_build_object('business_slug',v_context.business_slug)::text);
  perform pg_advisory_xact_lock(hashtextextended(
    'c46:in-app-sync:'||v_context.identity_id::text||':'||p_idempotency_key::text,0
  ));
  select * into v_existing from public.customer_in_app_inbox_sync_operations o
   where o.identity_id=v_context.identity_id and o.idempotency_key=p_idempotency_key;
  if found then
    if v_existing.request_hash is distinct from v_request_hash then
      raise exception 'idempotency key conflicts with another inbox sync' using errcode='40001';
    end if;
    return v_existing.response;
  end if;
  v_actionable_source_available:=app.platform_feature_enabled('customer_actionable_wallet');
  if v_actionable_source_available then
    select public.customer_get_actionable_business(v_context.business_slug)->'card' into v_card;
  end if;
  -- C45 participation is a separate platform-wide customer decision. An
  -- entitlement remains visible in C45 after withdrawal, so the C46 inbox
  -- cannot infer eligibility from the wallet card alone. A birthday event
  -- needs both this current participation decision and the precise C46 topic
  -- preference below.
  select coalesce(p.opted_in,false) into v_birthday_participating
    from (select 1) one
    left join public.customer_birthday_participation p on p.identity_id=v_context.identity_id;
  for v_candidate in
    select * from app.c46_customer_safe_booking_candidates(
      v_context.business_id,v_context.identity_id,v_context.link_id
    )
    union all
    select * from app.c46_customer_safe_inbox_candidates(v_card)
     where v_actionable_source_available
  loop
    if v_candidate.topic='birthday_benefit' and not v_birthday_participating then
      -- Do not retain the source key after C45 withdrawal: revalidation below
      -- resolves any old C46 birthday event without changing the entitlement.
      continue;
    end if;
    v_active_source_keys:=array_append(v_active_source_keys,
      v_candidate.source_kind||':'||v_candidate.source_fingerprint);
    select * into v_preference from app.c46_in_app_preference_for_context(
      v_context.business_id,v_context.identity_id,v_context.link_id,v_candidate.topic
    );
    if v_preference.opted_in then
      -- Recurrence is a logical source cycle, not an unstable clock value. A
      -- later identical reward/expiry fact may become true after an immutable
      -- source-no-longer-current resolution; its next resolution ordinal is a
      -- new customer-visible occurrence while concurrent syncs share one key.
      select count(*)::integer into v_cycle
        from public.customer_in_app_inbox_resolutions r
        join public.customer_in_app_inbox_events prior on prior.id=r.event_id
       where prior.business_id=v_context.business_id and prior.identity_id=v_context.identity_id
         and prior.link_id=v_context.link_id and prior.source_kind=v_candidate.source_kind
         and prior.source_fingerprint=v_candidate.source_fingerprint;
      v_dedupe_key:=app.c46_sha256_hex(jsonb_build_object(
        'business_id',v_context.business_id,'identity_id',v_context.identity_id,
        'source_kind',v_candidate.source_kind,'source_fingerprint',v_candidate.source_fingerprint,
        'source_cycle',v_cycle
      )::text);
      insert into public.customer_in_app_inbox_events(
        business_id,identity_id,auth_user_id,link_id,client_id,source_kind,topic,route_key,
        source_fingerprint,dedupe_key,title,body,deadline_at
      ) values (
        v_context.business_id,v_context.identity_id,v_context.auth_user_id,v_context.link_id,
        v_context.client_id,v_candidate.source_kind,v_candidate.topic,'wallet_business',
        v_candidate.source_fingerprint,v_dedupe_key,v_candidate.title,v_candidate.body,v_candidate.deadline_at
      ) on conflict (identity_id,dedupe_key) do nothing;
      get diagnostics v_rows = row_count;
      v_created:=v_created+v_rows;
    end if;
  end loop;
  -- Revalidation evaluates authoritative source independently of C46 topic
  -- consent. Turning a C46 preference off stops future facts but preserves
  -- history; withdrawing the separate C45 birthday participation intentionally
  -- removes only birthday source keys and therefore resolves C46 history.
  insert into public.customer_in_app_inbox_resolutions(
    event_id,business_id,identity_id,auth_user_id,link_id,client_id,resolution_kind,source_fingerprint
  )
  select e.id,e.business_id,e.identity_id,e.auth_user_id,e.link_id,e.client_id,
         'source_no_longer_current',e.source_fingerprint
    from public.customer_in_app_inbox_events e
   where e.business_id=v_context.business_id and e.identity_id=v_context.identity_id
     and e.link_id=v_context.link_id
     and (e.source_kind='v33_booking_action' or v_actionable_source_available)
     and not (e.source_kind||':'||e.source_fingerprint = any(v_active_source_keys))
  on conflict (event_id) do nothing;
  get diagnostics v_resolved = row_count;
  v_response:=jsonb_build_object('created',v_created,'resolved',v_resolved,
    'source_available',v_actionable_source_available);
  insert into public.customer_in_app_inbox_sync_operations(
    business_id,identity_id,auth_user_id,link_id,client_id,idempotency_key,request_hash,response
  ) values (
    v_context.business_id,v_context.identity_id,v_context.auth_user_id,v_context.link_id,
    v_context.client_id,p_idempotency_key,v_request_hash,v_response
  );
  return v_response;
end;
$$;

--
-- Name: customer_sync_in_app_inbox_global(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_sync_in_app_inbox_global(p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_context record; v_existing public.customer_in_app_inbox_global_sync_operations%rowtype;
  v_request_hash text; v_link record; v_count integer:=0; v_created integer:=0; v_resolved integer:=0;
  v_truncated boolean:=false; v_child_key uuid; v_child jsonb; v_response jsonb;
begin
  if not app.platform_feature_enabled('customer_in_app_inbox') then
    raise exception 'customer in-app inbox is not enabled' using errcode='0A000';
  end if;
  if p_idempotency_key is null then raise exception 'idempotency key is required' using errcode='22023'; end if;
  select * into v_context from app.c46_customer_inbox_global_context();
  v_request_hash:=app.c46_sha256_hex(jsonb_build_object('scope','my-frenly-inbox')::text);
  perform pg_advisory_xact_lock(hashtextextended(
    'c46:global-in-app-sync:'||v_context.identity_id::text||':'||p_idempotency_key::text,0
  ));
  select * into v_existing from public.customer_in_app_inbox_global_sync_operations o
   where o.identity_id=v_context.identity_id and o.idempotency_key=p_idempotency_key;
  if found then
    if v_existing.request_hash is distinct from v_request_hash then
      raise exception 'idempotency key conflicts with another global inbox sync' using errcode='40001';
    end if;
    return v_existing.response;
  end if;
  -- Child syncs take the shared identity linearization lock. A lexical,
  -- immutable link order prevents this global refresh from changing lock order
  -- between retries or contending callers.
  for v_link in
    select b.slug
      from public.customer_links cl join public.businesses b on b.id=cl.business_id
     where cl.identity_id=v_context.identity_id and cl.auth_user_id=v_context.auth_user_id and cl.state='verified'
     order by b.slug,cl.id limit 101
  loop
    v_count:=v_count+1;
    if v_count>100 then v_truncated:=true; exit; end if;
    v_child_key:=(substr(md5('c46:global:'||p_idempotency_key::text||':'||v_link.slug),1,8)||'-'||
      substr(md5('c46:global:'||p_idempotency_key::text||':'||v_link.slug),9,4)||'-'||
      substr(md5('c46:global:'||p_idempotency_key::text||':'||v_link.slug),13,4)||'-'||
      substr(md5('c46:global:'||p_idempotency_key::text||':'||v_link.slug),17,4)||'-'||
      substr(md5('c46:global:'||p_idempotency_key::text||':'||v_link.slug),21,12))::uuid;
    select public.customer_sync_in_app_inbox(v_link.slug,v_child_key) into v_child;
    v_created:=v_created+coalesce((v_child->>'created')::integer,0);
    v_resolved:=v_resolved+coalesce((v_child->>'resolved')::integer,0);
  end loop;
  v_response:=jsonb_build_object('synced_businesses',least(v_count,100),'created',v_created,
    'resolved',v_resolved,'truncated',v_truncated);
  insert into public.customer_in_app_inbox_global_sync_operations(
    identity_id,auth_user_id,idempotency_key,request_hash,response
  ) values (v_context.identity_id,v_context.auth_user_id,p_idempotency_key,v_request_hash,v_response);
  return v_response;
end;
$$;

--
-- Name: customer_sync_verified_relationships_v81(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_sync_verified_relationships_v81(p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_identity uuid;
  v_auth_email text;
  v_email_confirmed_at timestamptz;
  v_auth_phone text;
  v_phone_confirmed_at timestamptz;
  v_phone_norm text;
  v_existing public.customer_link_claim_attempts%rowtype;
  v_match record;
  v_candidate_ids uuid[];
  v_candidate_count integer;
  v_client_id uuid;
  v_link_id uuid;
  v_method text;
  v_linked_count integer := 0;
  v_already_linked_count integer := 0;
  v_ambiguous_count integer := 0;
  v_request_hash text := app.v31_sha256_hex('v81.relationship-sync');
  v_response jsonb;
begin
  if v_actor is null then
    raise exception 'authenticated customer session required' using errcode = '28000';
  end if;
  if not app.platform_feature_enabled('customer_claims') then
    raise exception 'customer access is unavailable' using errcode = '0A000';
  end if;
  v_identity := app.v31_current_identity();
  if p_idempotency_key is null
     or length(btrim(p_idempotency_key)) not between 8 and 160 then
    raise exception 'idempotency key must contain between 8 and 160 characters'
      using errcode = '22023';
  end if;
  p_idempotency_key := btrim(p_idempotency_key);

  perform pg_advisory_xact_lock(hashtextextended(
    'v81:relationship-sync:' || v_identity::text || ':' || p_idempotency_key, 0
  ));
  select * into v_existing
    from public.customer_link_claim_attempts attempt
   where attempt.identity_id = v_identity
     and attempt.operation = 'relationship_sync'
     and attempt.idempotency_key = p_idempotency_key
   for update;
  if found then
    if v_existing.request_hash is distinct from v_request_hash then
      raise exception 'idempotency key was already used for another relationship sync'
        using errcode = '23505';
    end if;
    return v_existing.response;
  end if;

  perform pg_advisory_xact_lock(hashtextextended(
    'v81:relationship-sync-rate:' || v_identity::text, 0
  ));
  if (
    select count(*)
      from public.customer_link_claim_attempts attempt
     where attempt.identity_id = v_identity
       and attempt.operation = 'relationship_sync'
       and attempt.outcome <> 'rate_limited'
       and attempt.created_at >= now() - interval '15 minutes'
  ) >= 20 then
    v_response := jsonb_build_object(
      'outcome', 'try_later',
      'linked_count', 0,
      'already_linked_count', 0,
      'ambiguous_count', 0,
      'matched_business_count', 0,
      'retry_after_seconds', 900
    );
    insert into public.customer_link_claim_attempts (
      identity_id, auth_user_id, operation, idempotency_key, request_hash,
      outcome, response
    ) values (
      v_identity, v_actor, 'relationship_sync', p_idempotency_key,
      v_request_hash, 'rate_limited', v_response
    );
    return v_response;
  end if;

  select
    lower(nullif(btrim(auth_user.email), '')),
    auth_user.email_confirmed_at,
    auth_user.phone,
    auth_user.phone_confirmed_at
    into v_auth_email, v_email_confirmed_at, v_auth_phone, v_phone_confirmed_at
    from auth.users auth_user
   where auth_user.id = v_actor
   for share;
  if not found then
    raise exception 'authenticated user no longer exists' using errcode = '28000';
  end if;
  if v_email_confirmed_at is null then
    v_auth_email := null;
  end if;
  if v_phone_confirmed_at is not null
     and app.platform_feature_enabled('customer_phone_claims')
     and app.platform_feature_enabled('customer_phone_registration') then
    v_phone_norm := app.norm_phone(v_auth_phone);
  end if;

  select count(*)::integer into v_already_linked_count
    from public.customer_links link
   where link.identity_id = v_identity
     and link.auth_user_id = v_actor
     and link.state = 'verified';

  for v_match in
    select matched.business_id
      from (
        select client.business_id
          from public.clients client
         where (
           (v_phone_norm is not null and client.phone_norm = v_phone_norm)
           or (
             v_auth_email is not null
             and nullif(btrim(client.email), '') is not null
             and lower(btrim(client.email)) = v_auth_email
           )
         )
           and not exists (
             select 1
               from public.customer_links prior
              where prior.client_id = client.id
           )
         group by client.business_id
      ) matched
     where not exists (
       select 1
         from public.customer_links current_link
        where current_link.business_id = matched.business_id
          and current_link.identity_id = v_identity
          and current_link.auth_user_id = v_actor
          and current_link.state = 'verified'
     )
     order by matched.business_id
  loop
    -- Serialize with both existing exact-email and exact-phone claim routes.
    perform pg_advisory_xact_lock(hashtextextended(
      'v31:business-link:' || v_match.business_id::text, 0
    ));
    perform pg_advisory_xact_lock(hashtextextended(
      'c42:phone-business-link:' || v_match.business_id::text, 0
    ));

    if exists (
      select 1
        from public.customer_links current_link
       where current_link.business_id = v_match.business_id
         and current_link.identity_id = v_identity
         and current_link.auth_user_id = v_actor
         and current_link.state = 'verified'
    ) then
      v_already_linked_count := v_already_linked_count + 1;
      continue;
    end if;

    select
      coalesce(array_agg(client.id order by client.id), '{}'::uuid[]),
      count(*)::integer
      into v_candidate_ids, v_candidate_count
      from public.clients client
     where client.business_id = v_match.business_id
       and (
         (v_phone_norm is not null and client.phone_norm = v_phone_norm)
         or (
           v_auth_email is not null
           and nullif(btrim(client.email), '') is not null
           and lower(btrim(client.email)) = v_auth_email
         )
       )
       and not exists (
         select 1
           from public.customer_links prior
          where prior.client_id = client.id
       );

    if v_candidate_count <> 1 then
      v_ambiguous_count := v_ambiguous_count + 1;
      continue;
    end if;

    v_client_id := v_candidate_ids[1];
    select case
      when v_phone_norm is not null and client.phone_norm = v_phone_norm
        then 'phone_claim'
      else 'email_claim'
    end
      into v_method
      from public.clients client
     where client.business_id = v_match.business_id
       and client.id = v_client_id;
    v_link_id := gen_random_uuid();

    begin
      perform set_config('app.customer_link_insert_id', v_link_id::text, true);
      insert into public.customer_links (
        id, business_id, identity_id, auth_user_id, client_id, state,
        verification_method, verified_at
      ) values (
        v_link_id, v_match.business_id, v_identity, v_actor, v_client_id,
        'verified', v_method, now()
      );
      perform set_config('app.customer_link_insert_id', '', true);

      insert into public.customer_link_audit_events (
        identity_id, actor_auth_user_id, business_id, client_id, link_id,
        event_type, idempotency_key, request_hash, response
      ) values (
        v_identity, v_actor, v_match.business_id, v_client_id, v_link_id,
        'relationship_sync_linked',
        p_idempotency_key || ':' || v_match.business_id::text,
        app.v31_sha256_hex(
          'v81.relationship-sync-link:' || v_match.business_id::text
        ),
        jsonb_build_object('outcome', 'linked')
      );
      v_linked_count := v_linked_count + 1;
    exception when unique_violation then
      perform set_config('app.customer_link_insert_id', '', true);
      if exists (
        select 1
          from public.customer_links current_link
         where current_link.business_id = v_match.business_id
           and current_link.identity_id = v_identity
           and current_link.auth_user_id = v_actor
           and current_link.state = 'verified'
      ) then
        v_already_linked_count := v_already_linked_count + 1;
      else
        v_ambiguous_count := v_ambiguous_count + 1;
      end if;
    end;
  end loop;

  v_response := jsonb_build_object(
    'outcome', 'synchronized',
    'linked_count', v_linked_count,
    'already_linked_count', v_already_linked_count,
    'ambiguous_count', v_ambiguous_count,
    'matched_business_count',
      v_linked_count + v_already_linked_count + v_ambiguous_count
  );
  insert into public.customer_link_claim_attempts (
    identity_id, auth_user_id, operation, idempotency_key, request_hash,
    outcome, response
  ) values (
    v_identity, v_actor, 'relationship_sync', p_idempotency_key, v_request_hash,
    case when v_linked_count + v_already_linked_count > 0
      then 'linked' else 'not_linked' end,
    v_response
  );
  return v_response;
end;
$$;

--
-- Name: customer_unlink_business_link(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_unlink_business_link(p_business_slug text, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_identity uuid;
  v_slug text := lower(btrim(coalesce(p_business_slug, '')));
  v_business uuid;
  v_link public.customer_links%rowtype;
  v_request_hash text;
  v_existing public.customer_link_audit_events%rowtype;
  v_response jsonb;
begin
  if not app.platform_feature_enabled('customer_claims') then
    raise exception 'customer access is unavailable' using errcode = '0A000';
  end if;
  v_identity := app.v31_current_identity();
  if p_idempotency_key is null or length(btrim(p_idempotency_key)) < 8 then
    raise exception 'idempotency key must contain at least 8 characters' using errcode = '22023';
  end if;
  p_idempotency_key := btrim(p_idempotency_key);
  v_request_hash := app.v31_sha256_hex('v31.unlink:' || v_slug);
  perform pg_advisory_xact_lock(hashtextextended(
    'v31:unlink:' || v_identity::text || ':' || p_idempotency_key, 0
  ));
  select * into v_existing from public.customer_link_audit_events a
   where a.identity_id = v_identity and a.actor_auth_user_id = v_actor
     and a.event_type = 'link_unlinked' and a.idempotency_key = p_idempotency_key;
  if found then
    if v_existing.request_hash is distinct from v_request_hash then
      raise exception 'idempotency key was already used for another unlink request' using errcode = '22023';
    end if;
    return v_existing.response;
  end if;
  perform pg_advisory_xact_lock(hashtextextended(
    'v31:unlink-rate:' || v_identity::text, 0
  ));
  if (
    select count(*) from public.customer_link_audit_events a
     where a.identity_id = v_identity
       and a.actor_auth_user_id = v_actor
       and a.event_type = 'link_unlinked'
       and a.created_at >= now() - interval '15 minutes'
  ) >= 10 then
    raise exception 'try later' using errcode = '54000';
  end if;

  select b.id into v_business from public.businesses b where b.slug = v_slug for share;
  if v_business is not null then
    select * into v_link from public.customer_links l
     where l.identity_id = v_identity and l.business_id = v_business and l.state = 'verified'
     for update;
  end if;
  if found then
    perform set_config('app.customer_link_transition_id', v_link.id::text, true);
    update public.customer_links
       set state = 'unlinked', unlinked_at = now(), unlinked_by_auth_user_id = v_actor,
           updated_at = now()
     where id = v_link.id;
    perform set_config('app.customer_link_transition_id', '', true);
    v_response := jsonb_build_object('outcome', 'unlinked');
  else
    v_response := jsonb_build_object('outcome', 'already_unlinked');
  end if;
  insert into public.customer_link_audit_events (
    identity_id, actor_auth_user_id, business_id, client_id, link_id, event_type,
    idempotency_key, request_hash, response
  ) values (
    v_identity, v_actor, v_business, v_link.client_id, v_link.id, 'link_unlinked',
    p_idempotency_key, v_request_hash, v_response
  );
  if v_link.id is not null then
    insert into public.customer_link_unlink_events (
      link_id, identity_id, actor_auth_user_id, business_id, client_id,
      idempotency_key, request_hash, response
    ) values (
      v_link.id, v_identity, v_actor, v_business, v_link.client_id,
      p_idempotency_key, v_request_hash, v_response
    );
  end if;
  return v_response;
end;
$$;

--
-- Name: customer_unregister_push_subscription_v95(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_unregister_push_subscription_v95(p_subscription uuid, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid:=auth.uid(); v_identity uuid; v_request_hash text;
  v_prior record; v_response jsonb; v_changed boolean:=false;
begin
  if v_actor is null then raise exception 'authentication required' using errcode='42501'; end if;
  if p_subscription is null or p_idempotency_key is null then
    raise exception 'subscription and idempotency key are required' using errcode='22023';
  end if;
  select id into v_identity from public.customer_identities
   where auth_user_id=v_actor and status='active'
   order by created_at,id limit 1;
  if v_identity is null then raise exception 'active customer identity required' using errcode='42501'; end if;
  v_request_hash:=app.c46_sha256_hex(jsonb_build_object(
    'operation','unregister','subscription_id',p_subscription
  )::text);
  perform pg_advisory_xact_lock(hashtextextended(v_actor::text||':'||p_idempotency_key::text,95));
  select request_hash,response into v_prior
    from public.customer_push_subscription_operations_v95
   where auth_user_id=v_actor and idempotency_key=p_idempotency_key;
  if found then
    if v_prior.request_hash<>v_request_hash then
      raise exception 'idempotency key conflict' using errcode='22000';
    end if;
    return v_prior.response;
  end if;
  perform pg_advisory_xact_lock(hashtextextended('v95-push-identity:'||v_identity::text,95));
  if (
    select count(*)>=20
      from public.customer_push_subscription_operations_v95
     where identity_id=v_identity and created_at>now()-interval '10 minutes'
  ) then
    raise exception 'push subscription operation rate exceeded' using errcode='54000';
  end if;
  update public.customer_push_subscriptions_v95
     set status='revoked',revoked_at=coalesce(revoked_at,now()),updated_at=now()
   where id=p_subscription and identity_id=v_identity and auth_user_id=v_actor
  returning true into v_changed;
  v_response:=jsonb_build_object(
    'subscription_id',p_subscription,
    'status',case when coalesce(v_changed,false) then 'revoked' else 'not_found' end
  );
  insert into public.customer_push_subscription_operations_v95(
    identity_id,auth_user_id,operation,idempotency_key,request_hash,response
  ) values(v_identity,v_actor,'unregister',p_idempotency_key,v_request_hash,v_response);
  return v_response;
end
$$;

--
-- Name: customer_update_profile(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_update_profile(p_full_name text, p_preferred_language text, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_identity uuid;
  v_name text := nullif(btrim(p_full_name), '');
  v_language text := lower(nullif(btrim(p_preferred_language), ''));
  v_request_hash text;
  v_existing public.customer_registration_operations%rowtype;
  v_response jsonb;
begin
  if v_actor is null then raise exception 'authenticated customer session required' using errcode = '28000'; end if;
  if not app.platform_feature_enabled('customer_phone_registration') then
    raise exception 'customer profile is unavailable' using errcode = '0A000';
  end if;
  if v_name is null or v_language is null or v_language !~ '^[a-z]{2,3}(-[a-z]{2,4})?$'
     or p_idempotency_key is null or length(btrim(p_idempotency_key)) < 8 then
    raise exception 'invalid customer profile request' using errcode = '22023';
  end if;
  v_identity := app.v31_current_identity();
  p_idempotency_key := btrim(p_idempotency_key);
  v_request_hash := app.v31_sha256_hex('c42.profile:' || v_actor::text || ':' || app.v31_sha256_hex(v_name) || ':' || v_language);
  perform pg_advisory_xact_lock(hashtextextended('c42:profile:' || v_identity::text || ':' || p_idempotency_key, 0));
  select * into v_existing from public.customer_registration_operations o
   where o.identity_id = v_identity and o.operation = 'profile_update' and o.idempotency_key = p_idempotency_key for update;
  if found then
    if v_existing.request_hash is distinct from v_request_hash then
      raise exception 'idempotency key was already used for a different profile request' using errcode = '23505';
    end if;
    return v_existing.response;
  end if;
  perform set_config('app.c42_profile_identity', v_identity::text, true);
  update public.customer_profiles set full_name = v_name, preferred_language = v_language
   where identity_id = v_identity and auth_user_id = v_actor;
  if not found then raise exception 'customer profile is unavailable' using errcode = '42501'; end if;
  perform set_config('app.c42_profile_identity', '', true);
  v_response := jsonb_build_object('outcome', 'updated');
  insert into public.customer_registration_operations (
    identity_id, actor_auth_user_id, operation, idempotency_key, request_hash, outcome, response
  ) values (v_identity, v_actor, 'profile_update', p_idempotency_key, v_request_hash, 'completed', v_response);
  return v_response;
end;
$_$;

--
-- Name: customer_withdraw_booking_request_v290(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_withdraw_booking_request_v290(p_request uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_request public.booking_requests%rowtype;
begin
  if v_actor is null then
    raise exception 'authenticated customer session required' using errcode = '28000';
  end if;
  if p_request is null then
    raise exception 'invalid booking request' using errcode = '22023';
  end if;

  select request.* into v_request
    from public.customer_identities identity
    join public.customer_links link
      on link.identity_id = identity.id
     and link.auth_user_id = identity.auth_user_id
     and link.state = 'verified'
    join public.booking_requests request
      on request.business_id = link.business_id
     and request.customer_client_id = link.client_id
    join app.booking_management_tokens token
      on token.business_id = request.business_id
     and token.booking_request_id = request.id
     and token.customer_client_id = request.customer_client_id
     and token.authenticated_user_id = v_actor
   where identity.auth_user_id = v_actor
     and identity.status = 'active'
     and request.id = p_request
   for update of request;
  if not found then
    raise exception 'booking request not found' using errcode = '42501';
  end if;

  if v_request.status = 'cancelled' then
    return jsonb_build_object('status','cancelled','replayed',true);
  end if;
  if v_request.appointment_id is not null
     or v_request.status not in ('new','pending','waitlisted') then
    raise exception 'already_actioned' using errcode = '22023';
  end if;

  update public.booking_requests
     set status = 'cancelled'
   where id = v_request.id and business_id = v_request.business_id;

  return jsonb_build_object('status','cancelled','replayed',false);
end;
$$;

--
-- Name: decide_change(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.decide_change(p_request uuid, p_approve boolean) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_request public.change_requests%rowtype;
  v_appointment public.appointments%rowtype;
  v_duration integer;
  v_suggestions jsonb;
begin
  select request.* into v_request
    from public.change_requests request where request.id=p_request for update;
  if not found then raise exception 'change request not found' using errcode='22023'; end if;
  select appointment.* into v_appointment
    from public.appointments appointment
   where appointment.id=v_request.appointment_id
     and appointment.business_id=v_request.business_id
   for update;
  if not found then raise exception 'appointment not found' using errcode='22023'; end if;
  if auth.uid() is null
     or not app.can_module_write(v_request.business_id,'appointments')
     or not app.can_see_branch(v_request.business_id,v_appointment.branch_id) then
    raise exception 'appointment write access for this branch is required' using errcode='42501';
  end if;
  if v_request.status<>'pending' then
    raise exception 'change request is already %',v_request.status using errcode='22023';
  end if;
  if not p_approve then
    update public.change_requests set status='declined',decided_at=clock_timestamp()
     where id=p_request;
    return json_build_object('id',p_request,'status','declined','kind',v_request.kind);
  end if;
  if v_appointment.status<>'booked' then
    raise exception 'appointment is no longer booked' using errcode='22023';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(v_request.business_id::text,47));
  if v_request.kind='reschedule' then
    v_duration:=greatest(15,ceil(extract(epoch from
      (v_appointment.ends_at-v_appointment.starts_at))/60)::integer);
    if v_request.proposed_at is null
       or not app.staff_free_for_appointment_v47(
         v_request.business_id,v_appointment.staff_id,v_appointment.branch_id,
         v_appointment.service_id,v_request.proposed_at,
         v_request.proposed_at+make_interval(mins=>v_duration),v_appointment.id) then
      v_suggestions:=public.suggest_appointment_staff_v47(
        v_request.business_id,v_appointment.branch_id,v_appointment.service_id,
        coalesce(v_request.proposed_at,clock_timestamp()),v_duration,5);
      return json_build_object('id',p_request,'status','conflict','kind',v_request.kind,
        'suggestions',v_suggestions);
    end if;
    update public.appointments
       set starts_at=v_request.proposed_at,
           ends_at=v_request.proposed_at+make_interval(mins=>v_duration)
     where id=v_appointment.id;
  elsif v_request.kind='cancel' then
    update public.appointments set status='cancelled' where id=v_appointment.id;
  else
    raise exception 'unsupported change request type' using errcode='22023';
  end if;
  update public.change_requests set status='approved',decided_at=clock_timestamp()
   where id=p_request;
  insert into public.audit_log(business_id,actor,action,entity,entity_id,detail)
  values (v_request.business_id,auth.uid(),'APPOINTMENT_CHANGE_APPROVE','appointments',
    v_appointment.id,jsonb_build_object('request_id',p_request,'kind',v_request.kind,
      'proposed_at',v_request.proposed_at));
  return json_build_object('id',p_request,'status','approved','kind',v_request.kind);
end
$$;

--
-- Name: decide_staff_access_v207(uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.decide_staff_access_v207(p_business uuid, p_staff uuid, p_approve boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_row public.staff%rowtype;
begin
  if not app.is_salon_owner(p_business) then
    raise exception 'owner access is required' using errcode='42501';
  end if;
  select * into v_row from public.staff where id=p_staff and business_id=p_business;
  if not found then
    raise exception 'that teammate is not in this business' using errcode='42501';
  end if;
  if v_row.access_state <> 'pending' then
    return jsonb_build_object('status','no_change','access_state',v_row.access_state);
  end if;
  update public.staff
     set access_state = case when p_approve then 'approved' else 'rejected' end,
         -- a refusal detaches the login but KEEPS the person on the rota; refusing app access
         -- is not the same as sacking someone, and their history must not move
         user_id = case when p_approve then user_id else null end
   where id=p_staff and business_id=p_business;
  update public.staff_invites
     set status = case when p_approve then 'accepted' else 'revoked' end
   where business_id=p_business and staff_id=p_staff and status='awaiting_approval';
  insert into public.audit_log(business_id, actor, action, entity, entity_id, detail)
  values (p_business, auth.uid(), case when p_approve then 'STAFF_ACCESS_APPROVED'
                                       else 'STAFF_ACCESS_REJECTED' end,
          'staff', p_staff, jsonb_build_object('approved', p_approve));
  return jsonb_build_object('status','ok','access_state',
    case when p_approve then 'approved' else 'rejected' end);
end
$$;

--
-- Name: delete_program_rule_draft(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_program_rule_draft(p_config_version uuid, p_rule_id uuid, p_expected_snapshot_hash text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_business uuid;
begin
  select version.business_id into v_business
    from public.firm_config_versions version
   where version.id = p_config_version;
  if v_business is null or not app.is_salon_owner(v_business) then
    raise exception 'owner only' using errcode = '42501';
  end if;
  raise exception 'advanced rule authoring is unavailable for launch'
    using errcode = '55000';
end;
$$;

--
-- Name: delete_service_bundle_v285(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_service_bundle_v285(p_business uuid, p_bundle uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_bundle public.bundles%rowtype;
  v_items integer;
begin
  if v_actor is null or p_business is null or p_bundle is null
     or not app.can_module_write(p_business, 'services') then
    raise exception 'permission denied' using errcode = '42501';
  end if;

  select * into v_bundle
    from public.bundles bundle
   where bundle.id = p_bundle and bundle.business_id = p_business
     for update;
  if not found then
    raise exception 'bundle not found' using errcode = '22023';
  end if;

  delete from public.bundle_items item where item.bundle_id = p_bundle;
  get diagnostics v_items = row_count;
  delete from public.bundles bundle
   where bundle.id = p_bundle and bundle.business_id = p_business;

  insert into public.audit_log (business_id, actor, action, entity, entity_id, detail)
  values (
    p_business, v_actor, 'SERVICE_BUNDLE_DELETE', 'bundles', p_bundle,
    jsonb_build_object('name', v_bundle.name, 'price_cents', v_bundle.price_cents,
                       'service_count', v_items)
  );

  return jsonb_build_object('status', 'deleted', 'bundle_id', p_bundle);
end;
$$;

--
-- Name: delete_staff_blocked_time_v120(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_staff_blocked_time_v120(p_business uuid, p_block uuid, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid:=auth.uid();
  v_request_hash text;
  v_existing app.staff_blocked_time_operations_v120%rowtype;
  v_block public.staff_blocked_times%rowtype;
  v_response jsonb;
begin
  if v_actor is null or p_business is null or p_block is null
     or p_idempotency_key is null
     or char_length(p_idempotency_key) not between 1 and 160 then
    raise exception 'permission denied or invalid blocked time'
      using errcode='42501';
  end if;

  v_request_hash:=app.v41_request_hash(jsonb_build_object(
    'business_id',p_business,'block_id',p_block
  )::text);

  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    'v120:delete:'||p_business::text||':'||v_actor::text||':'||p_idempotency_key,
    120
  ));

  select * into v_existing
    from app.staff_blocked_time_operations_v120 operation
   where operation.business_id=p_business and operation.actor=v_actor
     and operation.operation_type='delete'
     and operation.idempotency_key=p_idempotency_key;
  if found then
    if v_existing.request_hash<>v_request_hash then
      raise exception 'idempotency key reused with different blocked time'
        using errcode='22023';
    end if;
    if not app.can_module_write_at_v94(
      p_business,(v_existing.response->>'branch_id')::uuid,'appointments'
    ) then
      raise exception 'permission denied' using errcode='42501';
    end if;
    return (v_existing.response-'branch_id')||jsonb_build_object('replayed',true);
  end if;

  -- Different delete keys for the same block must not both observe and log the
  -- row before either deletion commits.
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    'v120:block-delete:'||p_business::text||':'||p_block::text,
    120
  ));
  select * into v_block
    from public.staff_blocked_times blocked
   where blocked.business_id=p_business and blocked.id=p_block;
  if not found
     or not app.can_module_write_at_v94(
       p_business,v_block.branch_id,'appointments'
     ) then
    raise exception 'permission denied' using errcode='42501';
  end if;

  perform app.lock_staff_calendar_v120(
    p_business,v_block.branch_id,v_block.staff_id
  );
  delete from public.staff_blocked_times
   where business_id=p_business and id=p_block;

  -- branch_id is retained only in the API-invisible receipt so replay can
  -- re-check current branch-effective permission after the source row is gone.
  v_response:=jsonb_build_object(
    'status','deleted','replayed',false,'block_id',p_block,
    'branch_id',v_block.branch_id
  );
  insert into app.staff_blocked_time_operations_v120 (
    business_id,actor,operation_type,idempotency_key,request_hash,response
  ) values (
    p_business,v_actor,'delete',p_idempotency_key,v_request_hash,v_response
  );

  insert into public.audit_log (business_id,actor,action,entity,entity_id,detail)
  values (
    p_business,v_actor,'STAFF_TIME_UNBLOCK','staff_blocked_times',p_block,
    jsonb_build_object(
      'branch_id',v_block.branch_id,'staff_id',v_block.staff_id,
      'starts_at',v_block.starts_at,'ends_at',v_block.ends_at,
      'reason',v_block.reason
    )
  );
  return v_response-'branch_id';
end
$$;

--
-- Name: discard_sv_plan_draft(uuid, uuid, integer, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.discard_sv_plan_draft(p_business uuid, p_draft uuid, p_expected_revision integer, p_idempotency_key uuid, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid(); v_row public.sv_plan_drafts%rowtype; v_hash text; v_hit jsonb; v_result jsonb;
  v_norm_reason text := nullif(btrim(coalesce(p_reason,'')),'');
begin
  if not app.is_salon_owner(p_business) then raise exception 'owner only' using errcode = '42501'; end if;
  v_hash := app.ps1b_sha256(jsonb_build_object('op','discard','business',p_business,'draft',p_draft,
    'expected_revision',p_expected_revision,'reason',v_norm_reason)::text);
  v_hit := app.sv_plan_idem_lookup(p_business, 'discard', p_idempotency_key, v_hash);
  if v_hit is not null then return v_hit; end if;

  select * into v_row from public.sv_plan_drafts where id = p_draft and business_id = p_business for update;
  if not found then raise exception 'stored-value plan draft not found in this business' using errcode = '22023'; end if;
  if v_row.status = 'discarded' then
    v_result := jsonb_build_object('status','ok','draft_id',p_draft,'discarded',true,'replayed',true);
  elsif v_row.status = 'published' then
    raise exception 'a published stored-value plan draft cannot be discarded' using errcode = '22023';
  else
    if p_expected_revision is null or p_expected_revision <> v_row.revision then
      raise exception 'stored-value plan draft was changed in another session (expected revision %, current %)', p_expected_revision, v_row.revision using errcode = '22023';
    end if;
    update public.sv_plan_drafts set status = 'discarded' where id = p_draft and business_id = p_business;
    v_result := jsonb_build_object('status','ok','draft_id',p_draft,'discarded',true,'replayed',false);
    insert into public.audit_log(business_id, actor, action, entity, entity_id, detail)
    values (p_business, v_actor, 'SV_PLAN_DRAFT_DISCARDED', 'sv_plan_drafts', p_draft, jsonb_build_object('reason', v_norm_reason));
  end if;
  insert into public.sv_plan_operations(business_id, op_type, idempotency_key, request_hash, actor, result)
  values (p_business, 'discard', p_idempotency_key, v_hash, v_actor, v_result);
  return v_result;
end $$;

--
-- Name: dismiss_growth_recommendation_v108(uuid, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dismiss_growth_recommendation_v108(p_business uuid, p_recommendation uuid, p_reason text, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_identity text;
  v_hash text;
  v_receipt jsonb;
  v_branch uuid;
begin
  if not app.is_salon_owner(p_business) then
    raise exception 'owner only' using errcode = '42501';
  end if;
  select r.branch_id into v_branch
  from public.growth_recommendations_v108 r
  where r.id = p_recommendation and r.business_id = p_business;
  if not found then
    raise exception 'recommendation not found';
  end if;
  if not app.can_see_branch(p_business, v_branch) then
    raise exception 'recommendation branch is outside actor scope'
      using errcode = '42501';
  end if;
  v_identity := app.v112_hash(jsonb_build_object(
    'operation', 'dismiss_growth_recommendation_v108',
    'business_id', p_business, 'actor', v_actor,
    'idempotency_key', p_idempotency_key
  ));
  v_hash := app.v112_hash(jsonb_build_object(
    'business_id', p_business,
    'recommendation_id', p_recommendation,
    'decision', 'dismissed',
    'reason', nullif(btrim(coalesce(p_reason, '')), '')
  ));
  perform app.v112_lock_pair(
    'v112-v108-dismiss-request:' || v_identity,
    'v112-v108-recommendation:' || p_recommendation::text
  );
  v_receipt := app.v112_get_receipt(v_identity, v_hash);
  if v_receipt is not null then
    return v_receipt;
  end if;
  v_receipt := public.dismiss_growth_recommendation_v108_v112_inner(
    p_business, p_recommendation, p_reason, p_idempotency_key
  );
  return app.v112_put_receipt(
    v_identity, 'dismiss_growth_recommendation_v108', v_hash,
    jsonb_build_object(
      'business_id', p_business, 'recommendation_id', p_recommendation,
      'actor', v_actor
    ),
    v_receipt
  );
end $$;

--
-- Name: dismiss_growth_recommendation_v108_v112_inner(uuid, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dismiss_growth_recommendation_v108_v112_inner(p_business uuid, p_recommendation uuid, p_reason text, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_existing public.growth_recommendation_decisions_v108%rowtype;
  v_rec public.growth_recommendations_v108%rowtype;
  v_request_hash text;
begin
  if not app.is_salon_owner(p_business) then
    raise exception 'owner only' using errcode = '42501';
  end if;
  v_request_hash := encode(extensions.digest(convert_to(jsonb_build_object(
    'business_id', p_business,
    'recommendation_id', p_recommendation,
    'decision', 'dismissed',
    'reason', nullif(btrim(coalesce(p_reason, '')), '')
  )::text, 'UTF8'), 'sha256'), 'hex');
  select * into v_existing from public.growth_recommendation_decisions_v108
  where business_id = p_business and actor = v_actor and idempotency_key = p_idempotency_key;
  if found then
    if v_existing.request_hash <> v_request_hash then
      raise exception 'idempotency key reused with a different dismissal request'
        using errcode = '23505';
    end if;
    return jsonb_build_object('recommendation_id', v_existing.recommendation_id,
      'decision', v_existing.decision, 'replayed', true);
  end if;
  select * into v_rec from public.growth_recommendations_v108
  where id = p_recommendation and business_id = p_business for update;
  if not found then raise exception 'recommendation not found'; end if;
  if not app.can_see_branch(v_rec.business_id, v_rec.branch_id) then
    raise exception 'recommendation branch is outside actor scope' using errcode = '42501';
  end if;
  update public.growth_recommendations_v108
  set status = 'dismissed'
  where id = p_recommendation and business_id = p_business
    and status = 'presented' and valid_until > statement_timestamp();
  if not found then raise exception 'recommendation is not dismissible'; end if;
  insert into public.growth_recommendation_decisions_v108(
    recommendation_id, business_id, decision, reason, actor, idempotency_key,
    request_hash
  ) values (
    p_recommendation, p_business, 'dismissed',
    nullif(btrim(coalesce(p_reason, '')), ''), v_actor, p_idempotency_key,
    v_request_hash
  );
  return jsonb_build_object('recommendation_id', p_recommendation,
    'decision', 'dismissed', 'replayed', false);
end $$;

--
-- Name: emergency_pause_studio_rule(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.emergency_pause_studio_rule(p_business uuid, p_rule_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_reason text := btrim(coalesce(p_reason, '')); v_id uuid;
begin
  if not app.is_salon_owner(p_business) then raise exception 'owner only' using errcode = '42501'; end if;
  if char_length(v_reason) < 3 then
    raise exception 'an emergency pause requires a reason of at least 3 characters' using errcode = '22023';
  end if;
  if not exists (select 1 from public.program_rules where rule_id = p_rule_id and business_id = p_business) then
    raise exception 'program rule not found in this business' using errcode = '42501';
  end if;
  -- Idempotent: an existing active pause is returned unchanged (also wins the race).
  insert into public.studio_rule_emergency_pauses(business_id, rule_id, actor, reason)
  values(p_business, p_rule_id, auth.uid(), v_reason)
  on conflict (business_id, rule_id) where lifted_at is null do nothing
  returning id into v_id;
  if v_id is null then
    select id into v_id from public.studio_rule_emergency_pauses
     where business_id = p_business and rule_id = p_rule_id and lifted_at is null;
    return jsonb_build_object('status', 'ok', 'pause_id', v_id, 'business_id', p_business,
      'rule_id', p_rule_id, 'replayed', true);
  end if;
  insert into public.audit_log(business_id, actor, action, entity, entity_id, detail)
  values(p_business, auth.uid(), 'STUDIO_RULE_EMERGENCY_PAUSE', 'program_rules', p_rule_id,
    jsonb_build_object('rule_id', p_rule_id, 'reason', v_reason, 'pause_id', v_id));
  return jsonb_build_object('status', 'ok', 'pause_id', v_id, 'business_id', p_business,
    'rule_id', p_rule_id, 'replayed', false);
end $$;

--
-- Name: enroll_membership(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enroll_membership(p_business uuid, p_client uuid, p_plan uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  mp public.membership_plans%rowtype;
  ms public.memberships%rowtype;
  v_sale public.sales%rowtype;
  v_actor uuid := auth.uid();
  v_staff uuid;
  v_credit_id uuid;
  v_period_end timestamptz;
begin
  if not app.has_perm(p_business, 'create_sales') then
    raise exception 'you do not have permission to enroll memberships in this business'
      using errcode = '42501';
  end if;
  select s.id into v_staff
    from public.staff s
   where s.business_id = p_business
     and s.user_id = v_actor
     and s.active
     and 'create_sales' = any (app.role_perms(s.role))
   order by case s.role when 'owner' then 0 when 'manager' then 1 else 2 end, s.created_at
   limit 1
   for update;
  if not found then
    raise exception 'active staff authorization is required to enroll a membership'
      using errcode = '42501';
  end if;
  perform 1 from public.clients c
   where c.id = p_client and c.business_id = p_business
   for update;
  if not found then
    raise exception 'client does not belong to this business';
  end if;
  select * into mp from public.membership_plans p
   where p.id = p_plan and p.business_id = p_business and p.active
   for update;
  if not found then
    raise exception 'active membership plan does not belong to this business';
  end if;
  if exists (
    select 1 from public.memberships m
     where m.business_id = p_business
       and m.client_id = p_client
       and m.status in ('active', 'paused', 'cancel_at_period_end')
  ) then
    raise exception 'client already has a live membership';
  end if;

  v_period_end := now() + case mp.cadence
    when 'monthly' then interval '1 month'
    when 'annual' then interval '1 year'
    else null
  end;
  if v_period_end is null then
    raise exception 'unsupported membership cadence %', mp.cadence;
  end if;

  insert into public.memberships (
    business_id, client_id, plan_id, status, current_period_start, current_period_end
  ) values (
    p_business, p_client, mp.id, 'active', now(), v_period_end
  ) returning * into ms;

  insert into public.sales (
    business_id, client_id, kind, amount_cents, note, staff_id
  ) values (
    p_business, p_client, 'membership', mp.price_cents,
    'membership enrollment: ' || mp.name, null
  ) returning * into v_sale;

  if mp.credit_cents > 0 then
    v_credit_id := gen_random_uuid();
    perform set_config('app.credit_ledger_insert_id', v_credit_id::text, true);
    perform set_config('app.credit_ledger_write_scope', 'enroll_membership', true);
    insert into public.credit_ledger (
      id, business_id, client_id, entry_type, amount_cents, reference,
      sale_id, actor, idempotency_key
    ) values (
      v_credit_id, p_business, p_client, 'membership_credit', mp.credit_cents,
      'membership period credit: ' || mp.name, v_sale.id, v_actor,
      'v20:membership:' || ms.id || ':' || ms.current_period_start
    );
    perform set_config('app.credit_ledger_insert_id', '', true);
    perform set_config('app.credit_ledger_write_scope', '', true);
  end if;

  return row_to_json(ms);
end $$;

--
-- Name: enroll_membership_v41(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enroll_membership_v41(p_business uuid, p_client uuid, p_plan uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_actor uuid:=auth.uid(); v_staff uuid; v_result json;
begin
  if v_actor is null or not app.can_module_write(p_business,'memberships')
     or not app.has_perm(p_business,'create_sales') then
    raise exception 'active memberships-module and create-sales authorization is required' using errcode='42501';
  end if;
  select s.id into v_staff from public.staff s
   where s.business_id=p_business and s.user_id=v_actor and s.active
     and 'create_sales'=any(app.role_perms(s.role))
   order by case when s.role='owner' then 0 else 1 end,s.created_at limit 1 for update;
  if not found then raise exception 'active staff authorization is required' using errcode='42501'; end if;
  v_result:=public.enroll_membership(p_business,p_client,p_plan);
  return v_result;
end
$$;

--
-- Name: enroll_membership_v41(uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enroll_membership_v41(p_business uuid, p_client uuid, p_plan uuid, p_idempotency_key uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_payload jsonb;
  v_hash text;
  v_existing public.sale_intent_operations%rowtype;
  v_result json;
begin
  if v_actor is null then
    raise exception 'authenticated staff required' using errcode = '42501';
  end if;
  if p_idempotency_key is null then
    raise exception 'a membership-enrollment idempotency key is required' using errcode = '22023';
  end if;
  if p_client is null or not exists (
    select 1 from public.clients c where c.id = p_client and c.business_id = p_business
  ) then
    raise exception 'membership-enrollment client does not belong to this business'
      using errcode = '22023';
  end if;

  v_payload := jsonb_build_object('business_id', p_business, 'client_id', p_client, 'plan_id', p_plan);
  v_hash := app.v41_request_hash(v_payload::text);
  perform pg_advisory_xact_lock(hashtextextended(
    'v51a:membership:' || p_business::text || ':' || p_idempotency_key::text, 0));

  select * into v_existing
    from public.sale_intent_operations o
   where o.business_id = p_business and o.idempotency_key = p_idempotency_key
   for update;
  if found then
    if v_existing.actor is distinct from v_actor
       or v_existing.operation_type <> 'membership_enroll'
       or v_existing.request_hash <> v_hash then
      raise exception 'idempotency key conflicts with another membership enrollment'
        using errcode = '23505';
    end if;
    return v_existing.result::json;
  end if;

  -- Delegate to the existing 3-arg v41 implementation (its own auth + work).
  v_result := public.enroll_membership_v41(p_business, p_client, p_plan);

  insert into public.sale_intent_operations(
    business_id, actor, operation_type, idempotency_key, request_hash, status, client_id, result)
  values (
    p_business, v_actor, 'membership_enroll', p_idempotency_key, v_hash, 'completed', p_client, v_result::jsonb);
  return v_result;
end $$;

--
-- Name: ensure_published_birthday_in_draft_v138(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_published_birthday_in_draft_v138(p_config_version uuid, p_program uuid, p_expected_snapshot_hash text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_draft public.firm_config_versions%rowtype;
  v_source public.birthday_program_versions%rowtype;
  v_active_config uuid;
  v_new_version uuid;
  v_snapshot_hash text;
begin
  select * into v_draft from public.firm_config_versions
   where id=p_config_version for update;
  if not found or not app.c45_owner_loyalty_write(v_draft.business_id) then
    raise exception 'owner loyalty configuration access required' using errcode='42501';
  end if;
  if v_draft.status<>'draft' then
    raise exception 'only a draft may receive an editable birthday benefit' using errcode='22023';
  end if;
  select id into v_new_version from public.birthday_program_versions
   where config_version_id=p_config_version and business_id=v_draft.business_id
     and program_id=p_program;
  if found then
    return jsonb_build_object('program_id',p_program,
      'birthday_program_version_id',v_new_version,
      'config_version_id',p_config_version,'snapshot_hash',v_draft.snapshot_hash,
      'replayed',true,'published',false);
  end if;
  if p_expected_snapshot_hash is not null
     and v_draft.snapshot_hash is distinct from p_expected_snapshot_hash then
    raise exception 'draft configuration changed; reload before editing this birthday benefit'
      using errcode='40001';
  end if;
  select active_config_version_id into v_active_config
    from public.businesses where id=v_draft.business_id for share;
  select * into v_source from public.birthday_program_versions
   where config_version_id=v_active_config and business_id=v_draft.business_id
     and program_id=p_program;
  if not found then
    raise exception 'published birthday benefit is unavailable' using errcode='22023';
  end if;
  if exists(select 1 from public.birthday_program_versions
      where config_version_id=p_config_version and business_id=v_draft.business_id) then
    raise exception 'the draft already contains another birthday benefit' using errcode='40001';
  end if;
  insert into public.birthday_program_versions(
    program_id,config_version_id,business_id,active,customer_label,
    customer_description,customer_terms,fulfillment_kind,discount_percent,
    manual_item,window_days_before,window_days_after,sort
  ) values(
    v_source.program_id,p_config_version,v_source.business_id,v_source.active,
    v_source.customer_label,v_source.customer_description,v_source.customer_terms,
    v_source.fulfillment_kind,v_source.discount_percent,v_source.manual_item,
    v_source.window_days_before,v_source.window_days_after,v_source.sort
  ) on conflict(program_id,config_version_id) do nothing returning id into v_new_version;
  if v_new_version is null then
    select id into v_new_version from public.birthday_program_versions
     where config_version_id=p_config_version and business_id=v_draft.business_id
       and program_id=p_program;
  end if;
  perform app.refresh_loyalty_config_snapshot(p_config_version);
  select snapshot_hash into v_snapshot_hash from public.firm_config_versions
   where id=p_config_version;
  insert into public.audit_log(business_id,actor,action,entity,entity_id,detail)
  values(v_draft.business_id,auth.uid(),'MATERIALIZE_BIRTHDAY_DRAFT',
    'birthday_program_versions',p_program,jsonb_build_object(
      'draft_config_version_id',p_config_version,
      'source_config_version_id',v_active_config,
      'birthday_program_version_id',v_new_version,'published',false));
  return jsonb_build_object('program_id',p_program,
    'birthday_program_version_id',v_new_version,
    'config_version_id',p_config_version,'snapshot_hash',v_snapshot_hash,
    'replayed',false,'published',false);
end $$;

--
-- Name: FUNCTION ensure_published_birthday_in_draft_v138(p_config_version uuid, p_program uuid, p_expected_snapshot_hash text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.ensure_published_birthday_in_draft_v138(p_config_version uuid, p_program uuid, p_expected_snapshot_hash text) IS 'Owner-only V138 continuity: idempotently copies the currently published birthday benefit into a stale editable draft; never publishes.';

--
-- Name: ensure_published_retention_in_draft_v138(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_published_retention_in_draft_v138(p_config_version uuid, p_program uuid, p_expected_snapshot_hash text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_draft public.firm_config_versions%rowtype;
  v_source public.retention_program_versions%rowtype;
  v_active_config uuid;
  v_new_version uuid;
  v_snapshot_hash text;
begin
  select * into v_draft from public.firm_config_versions
   where id=p_config_version for update;
  if not found or not app.is_salon_owner(v_draft.business_id)
     or not app.can_module_write(v_draft.business_id,'retention') then
    raise exception 'owner retention configuration access required' using errcode='42501';
  end if;
  if v_draft.status<>'draft' then
    raise exception 'only a draft may receive an editable bring-back rule' using errcode='22023';
  end if;
  if not exists(
    select 1 from public.retention_programs prog
     where prog.id=p_program and prog.business_id=v_draft.business_id and prog.deleted_at is null
  ) then
    raise exception 'retention program does not belong to this business, or is already deleted' using errcode='22023';
  end if;
  select id into v_new_version from public.retention_program_versions
   where config_version_id=p_config_version and business_id=v_draft.business_id
     and program_id=p_program;
  if found then
    return jsonb_build_object('program_id',p_program,
      'retention_program_version_id',v_new_version,
      'config_version_id',p_config_version,'snapshot_hash',v_draft.snapshot_hash,
      'replayed',true,'published',false);
  end if;
  if p_expected_snapshot_hash is not null
     and v_draft.snapshot_hash is distinct from p_expected_snapshot_hash then
    raise exception 'draft configuration changed; reload before editing this bring-back rule'
      using errcode='40001';
  end if;
  select active_config_version_id into v_active_config
    from public.businesses where id=v_draft.business_id for share;
  select * into v_source from public.retention_program_versions
   where config_version_id=v_active_config and business_id=v_draft.business_id
     and program_id=p_program;
  if not found then
    raise exception 'published bring-back rule is unavailable' using errcode='22023';
  end if;
  insert into public.retention_program_versions(
    program_id,config_version_id,business_id,name,active,goal_visits,period_days,
    starts_on,reward_taxonomy_id,fulfillment_kind,discount_percent,credit_cents,
    manual_item,sort,customer_description,staff_description
  ) values(
    v_source.program_id,p_config_version,v_source.business_id,v_source.name,
    v_source.active,v_source.goal_visits,v_source.period_days,v_source.starts_on,
    v_source.reward_taxonomy_id,v_source.fulfillment_kind,v_source.discount_percent,
    v_source.credit_cents,v_source.manual_item,v_source.sort,
    v_source.customer_description,v_source.staff_description
  ) on conflict(program_id,config_version_id) do nothing returning id into v_new_version;
  if v_new_version is null then
    select id into v_new_version from public.retention_program_versions
     where config_version_id=p_config_version and business_id=v_draft.business_id
       and program_id=p_program;
  end if;
  perform app.refresh_loyalty_config_snapshot(p_config_version);
  select snapshot_hash into v_snapshot_hash from public.firm_config_versions
   where id=p_config_version;
  insert into public.audit_log(business_id,actor,action,entity,entity_id,detail)
  values(v_draft.business_id,auth.uid(),'MATERIALIZE_RETENTION_DRAFT',
    'retention_program_versions',p_program,jsonb_build_object(
      'draft_config_version_id',p_config_version,
      'source_config_version_id',v_active_config,
      'retention_program_version_id',v_new_version,'published',false));
  return jsonb_build_object('program_id',p_program,
    'retention_program_version_id',v_new_version,
    'config_version_id',p_config_version,'snapshot_hash',v_snapshot_hash,
    'replayed',false,'published',false);
end $$;

--
-- Name: FUNCTION ensure_published_retention_in_draft_v138(p_config_version uuid, p_program uuid, p_expected_snapshot_hash text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.ensure_published_retention_in_draft_v138(p_config_version uuid, p_program uuid, p_expected_snapshot_hash text) IS 'Owner-only V138 continuity: idempotently copies one currently published Bring-back rule into a stale editable draft; never publishes.';

--
-- Name: ensure_published_reward_in_draft_v138(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_published_reward_in_draft_v138(p_config_version uuid, p_reward uuid, p_expected_snapshot_hash text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_draft public.firm_config_versions%rowtype;
  v_source public.loyalty_reward_versions%rowtype;
  v_active_config uuid;
  v_new_reward_version uuid;
  v_snapshot_hash text;
  v_replayed boolean := false;
begin
  select *
    into v_draft
    from public.firm_config_versions
   where id = p_config_version
   for update;

  if not found or not app.c45_owner_loyalty_write(v_draft.business_id) then
    raise exception 'owner loyalty configuration access required' using errcode = '42501';
  end if;
  if v_draft.status <> 'draft' then
    raise exception 'only a draft may receive an editable reward' using errcode = '22023';
  end if;
  select id
    into v_new_reward_version
    from public.loyalty_reward_versions
   where config_version_id = p_config_version
     and business_id = v_draft.business_id
     and reward_id = p_reward;

  if found then
    return jsonb_build_object(
      'reward_id', p_reward,
      'reward_version_id', v_new_reward_version,
      'config_version_id', p_config_version,
      'snapshot_hash', v_draft.snapshot_hash,
      'replayed', true,
      'published', false
    );
  end if;

  -- Replay is resolved before the optimistic-hash check. If the first call
  -- committed but its HTTP response was lost, the browser necessarily retries
  -- with the old hash; the already materialized exact row is the durable proof.
  if p_expected_snapshot_hash is not null
     and v_draft.snapshot_hash is distinct from p_expected_snapshot_hash then
    raise exception 'draft configuration changed; reload before editing this reward'
      using errcode = '40001';
  end if;

  select active_config_version_id
    into v_active_config
    from public.businesses
   where id = v_draft.business_id
   for share;

  select *
    into v_source
    from public.loyalty_reward_versions
   where config_version_id = v_active_config
     and business_id = v_draft.business_id
     and reward_id = p_reward;

  if not found then
    raise exception 'published reward is unavailable' using errcode = '22023';
  end if;

  insert into public.loyalty_reward_versions (
    reward_id, business_id, config_version_id, internal_name, customer_name,
    description, fulfillment_kind, taxonomy_label, cost_points, credit_cents,
    estimated_cost_cents, active, sort, claim_available_from, claim_available_until,
    entitlement_expiry_days, instructions, terms, image_ref, usage_limit
  )
  values (
    v_source.reward_id, v_source.business_id, p_config_version, v_source.internal_name,
    v_source.customer_name, v_source.description, v_source.fulfillment_kind,
    v_source.taxonomy_label, v_source.cost_points, v_source.credit_cents,
    v_source.estimated_cost_cents, v_source.active, v_source.sort,
    v_source.claim_available_from, v_source.claim_available_until,
    v_source.entitlement_expiry_days, v_source.instructions, v_source.terms,
    v_source.image_ref, v_source.usage_limit
  )
  on conflict (reward_id, config_version_id) do nothing
  returning id into v_new_reward_version;

  if v_new_reward_version is null then
    select id
      into v_new_reward_version
      from public.loyalty_reward_versions
     where config_version_id = p_config_version
       and business_id = v_draft.business_id
       and reward_id = p_reward;
    v_replayed := true;
  end if;

  insert into public.loyalty_reward_branches
    (reward_version_id, reward_id, business_id, branch_id)
  select v_new_reward_version, p_reward, v_draft.business_id, source.branch_id
    from public.loyalty_reward_branches source
   where source.reward_version_id = v_source.id
  on conflict do nothing;

  insert into public.loyalty_reward_services
    (reward_version_id, reward_id, business_id, service_id)
  select v_new_reward_version, p_reward, v_draft.business_id, source.service_id
    from public.loyalty_reward_services source
   where source.reward_version_id = v_source.id
  on conflict do nothing;

  insert into public.loyalty_reward_products
    (reward_version_id, reward_id, business_id, product_id)
  select v_new_reward_version, p_reward, v_draft.business_id, source.product_id
    from public.loyalty_reward_products source
   where source.reward_version_id = v_source.id
  on conflict do nothing;

  perform app.refresh_loyalty_config_snapshot(p_config_version);
  select snapshot_hash
    into v_snapshot_hash
    from public.firm_config_versions
   where id = p_config_version;

  insert into public.audit_log
    (business_id, actor, action, entity, entity_id, detail)
  values (
    v_draft.business_id, auth.uid(), 'MATERIALIZE_REWARD_DRAFT',
    'loyalty_reward_versions', p_reward,
    jsonb_build_object(
      'draft_config_version_id', p_config_version,
      'source_config_version_id', v_active_config,
      'reward_version_id', v_new_reward_version,
      'published', false
    )
  );

  return jsonb_build_object(
    'reward_id', p_reward,
    'reward_version_id', v_new_reward_version,
    'config_version_id', p_config_version,
    'snapshot_hash', v_snapshot_hash,
    'replayed', v_replayed,
    'published', false
  );
end $$;

--
-- Name: FUNCTION ensure_published_reward_in_draft_v138(p_config_version uuid, p_reward uuid, p_expected_snapshot_hash text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.ensure_published_reward_in_draft_v138(p_config_version uuid, p_reward uuid, p_expected_snapshot_hash text) IS 'Owner-only V138 continuity: idempotently copies one currently published reward and eligibility into a stale editable draft; never publishes.';

--
-- Name: erase_client_v290(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.erase_client_v290(p_business uuid, p_client uuid, p_reason text, p_idem text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_reason text := nullif(btrim(coalesce(p_reason,'')),'');
  v_key text := nullif(btrim(coalesce(p_idem,'')),'');
  v_client public.clients%rowtype;
  v_existing public.client_erasures_v290%rowtype;
  v_credit bigint := 0;
  v_bottles integer := 0;
  v_sv integer := 0;
  v_fields jsonb;
  v_id uuid;
begin
  if v_actor is null or p_business is null or p_client is null
     or not app.is_salon_owner(p_business) then
    raise exception 'customer erasure requires the workspace owner' using errcode = '42501';
  end if;
  if v_reason is null or char_length(v_reason) not between 4 and 500 then
    raise exception 'an erasure reason of 4 to 500 characters is required' using errcode = '22023';
  end if;
  if v_key is null or char_length(v_key) not between 8 and 200 then
    raise exception 'an idempotency key of 8 to 200 characters is required' using errcode = '22023';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended(p_business::text||':client-erasure-v290:'||v_key,0));

  select * into v_existing from public.client_erasures_v290 record
   where record.business_id = p_business
     and (record.idempotency_key = v_key or record.client_id = p_client);
  if found then
    if v_existing.client_id is distinct from p_client
       or v_existing.idempotency_key is distinct from v_key then
      raise exception 'this customer or key was already used for a different erasure'
        using errcode = '23505';
    end if;
    return jsonb_build_object('status','duplicate_ignored','erasure_id',v_existing.id,
      'client_id',v_existing.client_id,'erased_at',v_existing.created_at);
  end if;

  select * into v_client from public.clients customer
   where customer.id = p_client and customer.business_id = p_business
   for update;
  if not found then
    raise exception 'customer not found in this business' using errcode = '22023';
  end if;

  -- Three refusals. Each is something the business still HOLDS that belongs to this person; the
  -- identity that names the owner of it cannot be removed while it is outstanding.
  select coalesce(sum(ledger.amount_cents),0)::bigint into v_credit
    from public.credit_ledger ledger
   where ledger.business_id = p_business and ledger.client_id = p_client;
  select count(*)::integer into v_bottles
    from public.bar_bottles bottle
   where bottle.business_id = p_business and bottle.client_id = p_client
     and bottle.status in ('stored','called','at_table','expired');
  -- Stored value blocks on PARTICIPATION, not on a computed balance: the lot/movement sign
  -- convention belongs to PS-2 and this function must never guess a balance in order to decide
  -- whether it is safe to erase somebody. It fails closed.
  select count(*)::integer into v_sv
    from public.sv_lots lot
    join public.sv_accounts account on account.id = lot.account_id
   where account.business_id = p_business and account.client_id = p_client;

  if v_credit > 0 or v_bottles > 0 or v_sv > 0 then
    return jsonb_build_object('status','refused','reason','holdings_outstanding',
      'credit_balance_cents',v_credit,'bottles_in_storage',v_bottles,
      'stored_value_lots',v_sv);
  end if;

  v_fields := jsonb_build_object(
    'full_name',v_client.full_name is not null,
    'phone',v_client.phone is not null,
    'email',v_client.email is not null,
    'birth_date',v_client.birth_date is not null,
    'gender',v_client.gender is not null,
    'notes',v_client.notes is not null,
    'tags',coalesce(cardinality(v_client.tags),0) > 0,
    'referral_code',v_client.referral_code is not null);

  -- Anonymised in place. phone_norm is a GENERATED column and clears itself with phone.
  update public.clients customer
     set full_name = 'Erased customer',
         phone = null,
         email = null,
         birth_date = null,
         gender = null,
         notes = null,
         tags = array[]::text[],
         referral_code = null,
         marketing_consent = false
   where customer.id = p_client and customer.business_id = p_business;

  insert into public.client_erasures_v290(
    business_id, client_id, actor, reason, idempotency_key, erased_fields
  ) values (
    p_business, p_client, v_actor, v_reason, v_key, v_fields
  ) returning id into v_id;

  insert into public.audit_log(business_id, actor, action, entity, entity_id, detail)
  values (
    p_business, v_actor, 'CLIENT_ERASED_V290', 'clients', p_client,
    jsonb_build_object('erasure_id',v_id,'reason',v_reason,'erased_fields',v_fields));

  return jsonb_build_object('status','erased','erasure_id',v_id,'client_id',p_client,
    'erased_fields',v_fields);
end;
$$;

--
-- Name: evaluate_checkout(uuid, uuid, uuid, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.evaluate_checkout(p_business uuid, p_branch uuid, p_client uuid, p_lines jsonb, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_branch uuid;
  v_config uuid;
  v_hash text;
  v_existing public.checkout_evaluation_operations%rowtype;
  v_eval public.checkout_evaluations%rowtype;
  v_plan jsonb;
  v_eval_id uuid;
  v_msg text;
begin
  if v_actor is null then
    raise exception 'authenticated staff required to evaluate a checkout' using errcode = '42501';
  end if;
  if not app.has_perm(p_business, 'create_sales') then
    raise exception 'you do not have permission to price a checkout in this business (create_sales)'
      using errcode = '42501';
  end if;
  if p_idempotency_key is null then
    raise exception 'a checkout evaluation idempotency key is required' using errcode = '22023';
  end if;
  v_branch := coalesce(p_branch, app.default_branch(p_business));
  if v_branch is null or not exists (
    select 1 from public.branches b where b.id = v_branch and b.business_id = p_business and b.active) then
    raise exception 'checkout branch is missing, inactive, or belongs to another business' using errcode = '22023';
  end if;
  if not app.can_see_branch(p_business, v_branch) then
    raise exception 'you are not permitted to price a checkout for this branch scope' using errcode = '42501';
  end if;
  if p_client is not null and not exists (
    select 1 from public.clients c where c.id = p_client and c.business_id = p_business) then
    raise exception 'checkout client does not belong to this business' using errcode = '22023';
  end if;

  v_hash := app.ps1b_sha256(jsonb_build_object(
    'business_id', p_business, 'branch_id', v_branch, 'client_id', p_client, 'lines', p_lines)::text);

  perform pg_advisory_xact_lock(hashtextextended(
    'v58:evaluate:' || p_business::text || ':' || p_idempotency_key::text, 0));

  select * into v_existing from public.checkout_evaluation_operations o
   where o.business_id = p_business and o.idempotency_key = p_idempotency_key for update;
  if found then
    if v_existing.actor is distinct from v_actor or v_existing.request_hash <> v_hash then
      raise exception 'idempotency key conflicts with a different checkout evaluation' using errcode = '22023';
    end if;
    select * into v_eval from public.checkout_evaluations where id = v_existing.evaluation_id;
    if v_eval.consumed_at is not null or v_eval.expires_at <= now() then
      raise exception 'stale: this checkout evaluation is already consumed or expired; re-evaluate' using errcode = '22023';
    end if;
    return jsonb_build_object(
      'status', 'ok', 'replayed', true, 'evaluation_id', v_eval.id, 'expires_at', v_eval.expires_at,
      'server_lines', v_eval.server_lines, 'applied_effects', v_eval.applied_effects,
      'subtotal_cents', v_eval.subtotal_cents, 'discount_total_cents', v_eval.discount_total_cents,
      'total_cents', v_eval.total_cents, 'gst_cents', v_eval.gst_cents,
      'stored_value', app.sv_evaluate_quote(p_business, v_eval.client_id, v_eval.total_cents));
  end if;

  select active_config_version_id into v_config from public.businesses where id = p_business;

  v_plan := app.ps1c_plan_checkout(p_business, v_branch, p_client, p_lines, v_config);
  if v_plan->>'status' <> 'ok' then
    -- Surface the typed status as the message prefix. When the plan already provides a
    -- prefixed human sentence in 'reason' (custom_line_*, total_zero_not_supported) use
    -- it as-is; otherwise compose '<status>: <reason> (line N)'.
    if v_plan->>'reason' is not null and position((v_plan->>'status') || ':' in (v_plan->>'reason')) = 1 then
      v_msg := v_plan->>'reason';
    else
      v_msg := (v_plan->>'status') || ': ' || coalesce(v_plan->>'reason', 'checkout could not be priced')
               || case when v_plan->>'line' is not null then ' (line ' || (v_plan->>'line') || ')' else '' end;
    end if;
    raise exception '%', v_msg using errcode = '22023';
  end if;

  insert into public.checkout_evaluations(
    business_id, branch_id, client_id, server_lines, cart_hash, config_version_id, applied_effects,
    subtotal_cents, discount_total_cents, total_cents, gst_cents, gst_rate_bps, expires_at)
  values(
    p_business, v_branch, p_client, v_plan->'server_lines', v_plan->>'cart_hash', v_config,
    v_plan->'applied_effects', (v_plan->>'subtotal_cents')::int, (v_plan->>'discount_total_cents')::int,
    (v_plan->>'total_cents')::int, (v_plan->>'gst_cents')::int, (v_plan->>'gst_rate_bps')::int,
    now() + interval '10 minutes')
  returning id into v_eval_id;

  insert into public.checkout_evaluation_operations(business_id, actor, idempotency_key, request_hash, evaluation_id)
  values(p_business, v_actor, p_idempotency_key, v_hash, v_eval_id);

  return jsonb_build_object(
    'status', 'ok', 'replayed', false, 'evaluation_id', v_eval_id,
    'expires_at', now() + interval '10 minutes',
    'server_lines', v_plan->'server_lines', 'applied_effects', v_plan->'applied_effects',
    'subtotal_cents', (v_plan->>'subtotal_cents')::int, 'discount_total_cents', (v_plan->>'discount_total_cents')::int,
    'total_cents', (v_plan->>'total_cents')::int, 'gst_cents', (v_plan->>'gst_cents')::int,
    'stored_value', app.sv_evaluate_quote(p_business, p_client, (v_plan->>'total_cents')::int));
end $$;

--
-- Name: extend_bottle_v275(uuid, uuid, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.extend_bottle_v275(p_business uuid, p_bottle uuid, p_expires_at timestamp with time zone, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_key text := nullif(btrim(coalesce(p_idempotency_key, '')), '');
  v_existing uuid;
  v_bottle public.bar_bottles%rowtype;
  v_before timestamptz;
  v_next timestamptz;
  v_keep integer;
begin
  perform app.require_bar_business_v275(p_business);
  perform app.require_bar_staff_v275(p_business, true);
  if v_key is null then
    raise exception 'idempotency key required' using errcode = '22023';
  end if;

  v_existing := app.bar_bottle_replayed_v275(p_business, v_key);
  if v_existing is not null then
    select * into v_bottle from public.bar_bottles bottle where bottle.id = v_existing;
    return jsonb_build_object('status', 'duplicate_ignored',
      'bottle', app.bar_bottle_json_v275(v_bottle));
  end if;

  select * into v_bottle from public.bar_bottles bottle
   where bottle.id = p_bottle and bottle.business_id = p_business for update;
  if not found then
    raise exception 'bottle not found' using errcode = '22023';
  end if;
  if v_bottle.status in ('finished', 'transferred', 'removed') then
    raise exception 'this bottle is closed' using errcode = '22023';
  end if;

  v_keep := app.bar_keep_days_v275(p_business);
  v_next := coalesce(p_expires_at, now() + make_interval(days => v_keep));
  if v_next <= now() then
    raise exception 'the new keep date must be in the future' using errcode = '22023';
  end if;
  if v_next > now() + make_interval(days => 730) then
    raise exception 'a bottle cannot be kept more than two years' using errcode = '22023';
  end if;
  v_before := v_bottle.expires_at;

  update public.bar_bottles bottle
     set expires_at = v_next,
         expiry_mode = case when bottle.expiry_mode = 'none' then 'custom' else bottle.expiry_mode end,
         status = case when bottle.status = 'expired' then 'stored' else bottle.status end,
         updated_at = now()
   where bottle.id = v_bottle.id
  returning * into v_bottle;

  insert into public.bar_bottle_events (business_id, bottle_id, kind, actor, idem_key, detail)
  values (p_business, v_bottle.id, 'extend', v_actor, v_key,
    jsonb_build_object('from', v_before, 'to', v_next, 'keep_days', v_keep,
      'explicit_date', p_expires_at is not null));

  return jsonb_build_object('status', 'ok', 'bottle', app.bar_bottle_json_v275(v_bottle));
end;
$$;

--
-- Name: finalize_growth_execution_v108(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finalize_growth_execution_v108(p_business uuid, p_execution uuid, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_identity text;
  v_hash text;
  v_receipt jsonb;
  v_branch uuid;
begin
  if not app.is_salon_owner(p_business) then
    raise exception 'owner only' using errcode = '42501';
  end if;
  if not app.has_perm(p_business, 'view_finance')
     or not app.can_module_read(p_business, 'retention') then
    raise exception 'finance and retention access required'
      using errcode = '42501';
  end if;
  select e.branch_id into v_branch
  from public.growth_executions_v108 e
  where e.id = p_execution and e.business_id = p_business;
  if not found then
    raise exception 'execution not found';
  end if;
  if not app.can_see_branch(p_business, v_branch) then
    raise exception 'execution branch is outside actor scope'
      using errcode = '42501';
  end if;
  v_identity := app.v112_hash(jsonb_build_object(
    'operation', 'finalize_growth_execution_v108',
    'business_id', p_business, 'actor', v_actor,
    'idempotency_key', p_idempotency_key
  ));
  v_hash := app.v112_hash(jsonb_build_object(
    'business_id', p_business, 'execution_id', p_execution
  ));
  perform app.v112_lock_pair(
    'v112-v108-finalize-request:' || v_identity,
    'v112-v108-execution:' || p_execution::text
  );
  v_receipt := app.v112_get_receipt(v_identity, v_hash);
  if v_receipt is not null then return v_receipt; end if;
  v_receipt := public.finalize_growth_execution_v108_v112_inner(
    p_business, p_execution, p_idempotency_key
  );
  return app.v112_put_receipt(
    v_identity, 'finalize_growth_execution_v108', v_hash,
    jsonb_build_object(
      'business_id', p_business, 'execution_id', p_execution,
      'actor', v_actor
    ),
    v_receipt
  );
end $$;

--
-- Name: finalize_growth_execution_v108_v112_inner(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finalize_growth_execution_v108_v112_inner(p_business uuid, p_execution uuid, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_execution public.growth_executions_v108%rowtype;
  v_rec public.growth_recommendations_v108%rowtype;
  v_result jsonb;
  v_status text;
  v_estimate bigint;
  v_low bigint;
  v_high bigint;
  v_request_hash text;
  v_existing public.growth_execution_results_v108%rowtype;
  v_receipt jsonb;
  -- Freeze one finalization cutoff and persist the result derived from it.
  v_now timestamptz := clock_timestamp();
begin
  if not app.is_salon_owner(p_business) then
    raise exception 'owner only' using errcode = '42501';
  end if;
  v_request_hash := encode(extensions.digest(convert_to(jsonb_build_object(
    'business_id', p_business,
    'execution_id', p_execution
  )::text, 'UTF8'), 'sha256'), 'hex');
  select * into v_existing
  from public.growth_execution_results_v108
  where business_id = p_business and finalized_by = v_actor
    and idempotency_key = p_idempotency_key;
  if found then
    if v_existing.request_hash <> v_request_hash then
      raise exception 'idempotency key reused with a different finalization request'
        using errcode = '23505';
    end if;
    return v_existing.result
      || jsonb_build_object('result_status', v_existing.result_status);
  end if;
  select * into v_execution from public.growth_executions_v108
  where id = p_execution and business_id = p_business for update;
  if not found then raise exception 'execution not found'; end if;
  if not app.can_see_branch(v_execution.business_id, v_execution.branch_id) then
    raise exception 'execution branch is outside actor scope' using errcode = '42501';
  end if;
  if v_execution.status = 'completed' then
    raise exception 'execution was finalized with another idempotency key'
      using errcode = '23505';
  end if;
  if v_execution.status <> 'running' or v_execution.ends_at > v_now then
    raise exception 'execution cannot be finalized before its measurement window closes'
      using errcode = '42501';
  end if;
  select * into v_rec from public.growth_recommendations_v108
  where id = v_execution.recommendation_id;
  v_result := app.get_growth_execution_result_at_v108(p_execution, v_now);
  v_estimate := (v_result #>> '{estimated_incremental_revenue,point_estimate_cents}')::bigint;
  v_low := (v_result #>> '{estimated_incremental_revenue,low_cents}')::bigint;
  v_high := (v_result #>> '{estimated_incremental_revenue,high_cents}')::bigint;
  v_status := case
    when v_result ->> 'measurement_status' = 'invalid_overlap' then 'invalid'
    when v_result ->> 'measurement_status' <> 'final' then 'inconclusive'
    when v_low > 0 then 'won'
    when v_high < 0 then 'lost'
    else 'inconclusive'
  end;
  insert into public.growth_execution_results_v108(
    execution_id, business_id, policy_version, result, prediction, calibration,
    result_status, finalized_by, idempotency_key, request_hash
  ) values (
    p_execution, p_business, v_rec.policy_version, v_result,
    v_rec.expected_incremental_revenue,
    jsonb_build_object(
      'prediction_low_cents', (v_rec.expected_incremental_revenue ->> 'low_cents')::bigint,
      'prediction_high_cents', (v_rec.expected_incremental_revenue ->> 'high_cents')::bigint,
      'observed_point_estimate_cents', v_estimate,
      'inside_predicted_range', case when v_estimate is null then null else
        v_estimate between
          (v_rec.expected_incremental_revenue ->> 'low_cents')::bigint
          and (v_rec.expected_incremental_revenue ->> 'high_cents')::bigint
      end,
      'policy_adjusted_automatically', false
    ),
    v_status, v_actor, p_idempotency_key, v_request_hash
  );
  update public.growth_executions_v108
  set status = 'completed', completed_at = v_now
  where id = p_execution;
  update public.growth_recommendations_v108
  set status = 'completed' where id = v_rec.id;
  insert into public.audit_log(business_id, actor, action, entity, entity_id, detail)
  values (p_business, v_actor, 'FINALIZE_GROWTH_EXECUTION_V108',
    'growth_executions_v108', p_execution,
    jsonb_build_object('result_status', v_status, 'idempotency_key', p_idempotency_key));
  return v_result || jsonb_build_object('result_status', v_status);
end $$;

--
-- Name: finish_billing_reconciliation_v77(uuid, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finish_billing_reconciliation_v77(p_run uuid, p_status text, p_cursor_end text, p_summary jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if p_status not in ('partial','clean','mismatch','failed')
     or jsonb_typeof(p_summary) <> 'object' then
    raise exception 'invalid reconciliation result' using errcode='22023';
  end if;
  update public.billing_reconciliation_runs
     set status=p_status,cursor_end=p_cursor_end,summary=p_summary,finished_at=now()
   where id=p_run and status='running';
  if not found then
    raise exception 'running reconciliation was not found'
      using errcode='restrict_violation';
  end if;
end
$$;

--
-- Name: finish_bottle_v275(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finish_bottle_v275(p_business uuid, p_bottle uuid, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_key text := nullif(btrim(coalesce(p_idempotency_key, '')), '');
  v_existing uuid;
  v_bottle public.bar_bottles%rowtype;
  v_before text;
begin
  perform app.require_bar_business_v275(p_business);
  perform app.require_bar_staff_v275(p_business, true);
  if v_key is null then
    raise exception 'idempotency key required' using errcode = '22023';
  end if;

  v_existing := app.bar_bottle_replayed_v275(p_business, v_key);
  if v_existing is not null then
    select * into v_bottle from public.bar_bottles bottle where bottle.id = v_existing;
    return jsonb_build_object('status', 'duplicate_ignored',
      'bottle', app.bar_bottle_json_v275(v_bottle));
  end if;

  select * into v_bottle from public.bar_bottles bottle
   where bottle.id = p_bottle and bottle.business_id = p_business for update;
  if not found then
    raise exception 'bottle not found' using errcode = '22023';
  end if;
  if v_bottle.status = 'finished' then
    return jsonb_build_object('status', 'ok', 'bottle', app.bar_bottle_json_v275(v_bottle));
  end if;
  if v_bottle.status in ('transferred', 'removed') then
    raise exception 'this bottle is closed' using errcode = '22023';
  end if;
  v_before := v_bottle.status;

  update public.bar_bottles bottle
     set status = 'finished', fill_percent = 0, updated_at = now()
   where bottle.id = v_bottle.id
  returning * into v_bottle;

  insert into public.bar_bottle_events (business_id, bottle_id, kind, actor, idem_key, detail)
  values (p_business, v_bottle.id, 'finish', v_actor, v_key,
    jsonb_build_object('from', v_before, 'fill_percent_at_finish', 0));

  return jsonb_build_object('status', 'ok', 'bottle', app.bar_bottle_json_v275(v_bottle));
end;
$$;

--
-- Name: forfeit_consultant_open_commission_v78(uuid, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.forfeit_consultant_open_commission_v78(p_consultant uuid, p_departed_at timestamp with time zone, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if auth.uid() is null or not app.v89_platform_can('commissions','rw') then
    raise exception 'super-admin access is required' using errcode='42501';
  end if;
  return app.forfeit_consultant_core_v78(
    p_consultant,p_departed_at,p_reason,auth.uid()
  );
end
$$;

--
-- Name: generate_retention_recommendation(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_retention_recommendation(p_business uuid, p_idempotency_key text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid:=auth.uid(); v_run public.retention_recommendation_runs%rowtype;
  v_business public.businesses%rowtype; v_base uuid; v_draft json; v_draft_id uuid;
  v_existing_draft uuid; v_service_count integer; v_product_count integer;
  v_branch_count integer; v_avg_service integer; v_avg_product integer;
  v_reference_price integer; v_model text; v_stamp_cents integer;
  v_reward_cost integer; v_metrics jsonb; v_recommendation jsonb;
  v_base_active boolean;
begin
  if not app.c45_owner_loyalty_write(p_business)
     or not app.can_module_write_at_v94(p_business,null,'loyalty') then
    raise exception 'owner loyalty configuration access required'
      using errcode='42501';
  end if;
  if p_idempotency_key is null or length(btrim(p_idempotency_key))<8 then
    raise exception 'idempotency key must contain at least 8 characters'
      using errcode='22023';
  end if;
  p_idempotency_key:=btrim(p_idempotency_key);

  -- The business row serializes different request keys too. A second tab that
  -- began from a stale no-draft snapshot will observe and resume the first
  -- tab's committed draft after acquiring this lock.
  select * into v_business from public.businesses
   where id=p_business for update;
  if not found then raise exception 'business not found'; end if;

  select count(*)::integer,coalesce(round(avg(price_cents)),0)::integer
    into v_service_count,v_avg_service from public.services
   where business_id=p_business and active;
  select count(*)::integer,coalesce(round(avg(retail_price_cents)),0)::integer
    into v_product_count,v_avg_product from public.products
   where business_id=p_business and active;
  select count(*)::integer into v_branch_count from public.branches
   where business_id=p_business and active;
  v_reference_price:=case
    when v_avg_service>0 and v_avg_product>0
      then round((v_avg_service+v_avg_product)/2.0)
    else greatest(v_avg_service,v_avg_product,1000)
  end;
  v_metrics:=jsonb_build_object(
    'industry',coalesce(v_business.industry,'other'),
    'active_services',v_service_count,
    'active_products',v_product_count,
    'active_branches',v_branch_count,
    'average_service_cents',v_avg_service,
    'average_product_cents',v_avg_product,
    'reference_price_cents',v_reference_price
  );

  -- Preserve exact replay before considering any other editable draft.
  select * into v_run from public.retention_recommendation_runs
   where business_id=p_business and idempotency_key=p_idempotency_key
   for update;
  if found then
    if v_run.request_hash<>md5(v_metrics::text) then
      raise exception 'idempotency key conflicts with changed business inputs'
        using errcode='22023';
    end if;
    if v_run.status='draft_ready' then return v_run.recommendation::json; end if;
    raise exception 'recommendation is already being generated'
      using errcode='55P03';
  end if;

  select coalesce(v_business.active_config_version_id,lp.current_config_version_id)
    into v_base from public.loyalty_programs lp
   where lp.business_id=p_business;
  if v_base is null then
    raise exception 'loyalty draft is missing for this business';
  end if;

  select version.id into v_existing_draft
    from public.firm_config_versions version
   where version.business_id=p_business
     and version.status='draft'
     and version.based_on_version_id=v_base
   order by version.version_no desc
   limit 1;
  if v_existing_draft is not null then
    select programme.loyalty_model into v_model
      from public.loyalty_program_versions programme
     where programme.business_id=p_business
       and programme.config_version_id=v_existing_draft;
    return json_build_object(
      'run_id',null,
      'draft_config_version_id',v_existing_draft,
      'status','existing_draft',
      'published',false,
      'resumed_existing',true,
      'model',v_model,
      'rationale','Existing editable draft resumed; no recommendation replaced it.',
      'input_metrics',v_metrics
    );
  end if;

  insert into public.retention_recommendation_runs(
    business_id,idempotency_key,request_hash,status,input_metrics,created_by
  ) values(
    p_business,p_idempotency_key,md5(v_metrics::text),'generating',v_metrics,v_actor
  );

  -- V75 governs these exact current sector keys. Legacy synonyms remain for
  -- already-created businesses that have not yet been normalized.
  v_model:=case
    when lower(coalesce(v_business.industry,'other'))
      in ('fnb','food_beverage','cafe','restaurant') then 'stamps'
    when lower(coalesce(v_business.industry,'other'))
      in ('salon','spa','facial','massage','fitness','retail','bar') then 'points_tiers'
    else 'classic'
  end;
  v_stamp_cents:=greatest(
    100,round((v_reference_price/2.0)/100.0)::integer*100
  );
  v_reward_cost:=greatest(
    5,case when v_model='stamps' then 8
      else ceil((v_reference_price/100.0)*5)::integer end
  );

  -- V258: the recommendation owns the NUMBERS, never the trading status. Read the live
  -- version's own flag and carry it forward, so a live Active programme is never silently
  -- paused by publishing a recommended draft. A firm with no live programme keeps the old
  -- behaviour: its first draft starts Paused.
  select base.active into v_base_active
    from public.loyalty_program_versions base
   where base.config_version_id=v_base
     and base.business_id=p_business;
  v_base_active:=coalesce(v_base_active,false);

  v_draft:=public.create_loyalty_config_draft(
    p_business,v_base,'catalog_recommendation_v128'
  );
  v_draft_id:=(v_draft->>'version_id')::uuid;
  perform public.save_loyalty_config_draft(v_draft_id,jsonb_build_object(
    'kind','points','active',v_base_active,'loyalty_model',v_model,
    'tier_basis',case when lower(coalesce(v_business.industry,''))='bar' then 'spend' else null end,
    'earn_points_per_dollar',1,'redeem_points',greatest(100,v_reward_cost),
    'reward_credit_cents',0,
    'expiry_mode','none','expiry_days',null
  )
  -- nestly_v419: the key is ADDED only when this recommendation is actually setting it.
  -- save_loyalty_config_draft treats stamp_per_cents by KEY PRESENCE
  --     stamp_per_cents = case when p_config ? 'stamp_per_cents' then ... else <keep> end
  -- so sending it as null does not mean "leave it alone", it means "erase it". This function
  -- recommends a POINTS catalogue, so v_model is never 'stamps' here in practice and the branch
  -- always sent null - wiping the inherited spend-per-stamp of any firm running a stamp card.
  || case when v_model='stamps' then jsonb_build_object('stamp_per_cents',v_stamp_cents)
          else '{}'::jsonb end
  );
  -- V197: only seed a starting reward when the draft has none. The draft is cloned from the
  -- live config, so a firm that already published a reward would otherwise gain a duplicate on
  -- every recommend -> publish cycle.
  if v_model in ('stamps','points_tiers')
     and not exists (
       select 1 from public.loyalty_reward_versions existing
        where existing.business_id = p_business
          and existing.config_version_id = v_draft_id
          and existing.active
     ) then
    perform public.save_loyalty_config_draft(v_draft_id,jsonb_build_object(
      'reward',jsonb_build_object(
        'business_id',p_business,
        'name','Recommended return reward',
        'customer_name','A thank-you on your next visits',
        'description','Suggested starting benefit. Replace this with an item or service that fits your margins.',
        'fulfillment_kind','manual_item',
        'cost_points',v_reward_cost,
        'credit_cents',0,
        'estimated_cost_cents',0,
        'active',true,
        'usage_limit',null
      ),
      'reward_branch_ids','[]'::jsonb,
      'reward_service_ids','[]'::jsonb,
      'reward_product_ids','[]'::jsonb
    ));
  end if;

  v_recommendation:=jsonb_build_object(
    'run_id',(
      select id from public.retention_recommendation_runs
       where business_id=p_business and idempotency_key=p_idempotency_key
    ),
    'draft_config_version_id',v_draft_id,
    'status','draft_ready',
    'published',false,
    'resumed_existing',false,
    'model',v_model,
    'reference_price_cents',v_reference_price,
    'suggested_spend_per_stamp_cents',
      case when v_model='stamps' then v_stamp_cents else null end,
    'suggested_reward_cost',
      case when v_model in ('stamps','points_tiers') then v_reward_cost else null end,
    'rationale',case
      when v_model='stamps'
        then 'Frequent-purchase catalog: a visible stamp goal is simple at the counter.'
      when v_model='points_tiers'
        then 'Repeat-service catalog: flexible rewards preserve margin and support progression.'
      else 'Limited catalog signal: start with simple points and review after real sales history.'
    end,
    'input_metrics',v_metrics
  );
  update public.retention_recommendation_runs
     set status='draft_ready',recommendation=v_recommendation,
       draft_config_version_id=v_draft_id,completed_at=now()
   where business_id=p_business and idempotency_key=p_idempotency_key;
  return v_recommendation::json;
end $$;

--
-- Name: FUNCTION generate_retention_recommendation(p_business uuid, p_idempotency_key text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.generate_retention_recommendation(p_business uuid, p_idempotency_key text) IS 'V128 owner-only draft recommender: governed sector mapping, exact replay, concurrent existing-draft resume, never publication.';

--
-- Name: get_account_deletion_request_v131(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_account_deletion_request_v131() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_user uuid:=auth.uid();
  v_row public.account_deletion_requests%rowtype;
begin
  if v_user is null then
    raise exception 'authentication required' using errcode='42501';
  end if;
  select * into v_row from public.account_deletion_requests
   where subject_ref=v_user order by requested_at desc,id desc limit 1;
  if v_row.id is null then return null;end if;
  return jsonb_build_object(
    'request_id',v_row.id,'status',v_row.status,
    'requested_at',v_row.requested_at,'response_due_at',v_row.response_due_at,
    'resolution_code',v_row.resolution_code,'retention_until',v_row.retention_until
  );
end
$$;

--
-- Name: FUNCTION get_account_deletion_request_v131(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_account_deletion_request_v131() IS 'V131 subject-only projection of the caller current deletion request.';

--
-- Name: get_active_birthday_program(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_active_birthday_program(p_business_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_version uuid;
  v_as_of timestamptz:=statement_timestamp();
begin
  if auth.uid() is null
     or not app.can_module_read(p_business_id, 'loyalty') then
    raise exception 'loyalty read access required' using errcode = '42501';
  end if;

  select business.active_config_version_id into v_version
    from public.businesses business
   where business.id = p_business_id;

  if v_version is null then
    return jsonb_build_object(
      'status','unavailable','as_of',v_as_of,'programs','[]'::jsonb
    );
  end if;

  return jsonb_build_object(
    'status','published',
    'as_of',v_as_of,
    'programs',coalesce((
      select jsonb_agg(jsonb_build_object(
        'program_id',program.program_id,
        'active',program.active,
        'customer_label',program.customer_label,
        'customer_description',program.customer_description,
        'customer_terms',program.customer_terms,
        'fulfillment_kind',program.fulfillment_kind,
        'discount_percent',program.discount_percent,
        'manual_item',program.manual_item,
        'window_days_before',program.window_days_before,
        'window_days_after',program.window_days_after,
        'sort',program.sort
      ) order by program.sort,program.program_id)
        from public.birthday_program_versions program
       where program.business_id = p_business_id
         and program.config_version_id = v_version
    ),'[]'::jsonb)
  );
end
$$;

--
-- Name: FUNCTION get_active_birthday_program(p_business_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_active_birthday_program(p_business_id uuid) IS 'Returns non-customer published birthday programme copy to active staff with effective Loyalty read access; the underlying table remains browser-closed.';

--
-- Name: get_billing_plan_catalog_v124(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_billing_plan_catalog_v124() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if auth.uid() is null or not app.is_super_admin() then
    raise exception 'super-admin access is required' using errcode='42501';
  end if;
  return coalesce((
    select jsonb_agg(to_jsonb(rows) order by rows.effective_from desc)
    from (
      select id,currency,cadence,cadence_months,provider_base_price_id,
             provider_capacity_price_id,base_amount_cents,
             included_customer_capacity,capacity_block_size,
             capacity_block_amount_cents,compare_at_monthly_cents,
             tax_behavior,active,effective_from,effective_to,created_at
        from public.billing_plan_catalog_v124
       order by effective_from desc limit 100
    ) rows
  ),'[]'::jsonb);
end
$$;

--
-- Name: get_billing_plan_catalog_v125(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_billing_plan_catalog_v125() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  return public.get_billing_plan_catalog_v124();
end
$$;

--
-- Name: get_billing_price_catalog_v77(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_billing_price_catalog_v77(p_currency text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if auth.uid() is null or not app.is_super_admin() then
    raise exception 'super-admin access is required' using errcode='42501';
  end if;
  return coalesce((
    select jsonb_agg(to_jsonb(rows) order by rows.effective_from desc)
    from (
      select id,currency,cadence,cadence_months,provider_base_price_id,
             provider_seat_price_id,base_amount_cents,per_seat_amount_cents,
             included_seats,tax_behavior,active,effective_from,effective_to,
             created_at
        from public.billing_price_catalog
       where p_currency is null or currency=p_currency
       order by effective_from desc limit 100
    ) rows
  ),'[]'::jsonb);
end
$$;

--
-- Name: get_billing_reconciliation_v77(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_billing_reconciliation_v77(p_run uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if auth.uid() is null or not app.is_super_admin() then
    raise exception 'super-admin access is required' using errcode='42501';
  end if;
  if p_limit not between 1 and 200 then
    raise exception 'limit must be between 1 and 200' using errcode='22023';
  end if;
  return jsonb_build_object(
    'runs',coalesce((
      select jsonb_agg(to_jsonb(runs) order by runs.started_at desc)
      from (
        select id,run_mode,status,cursor_start,cursor_end,started_at,finished_at,summary
          from public.billing_reconciliation_runs
         where p_run is null or id=p_run
         order by started_at desc limit p_limit
      ) runs
    ),'[]'::jsonb),
    'items',coalesce((
      select jsonb_agg(to_jsonb(items) order by items.created_at desc)
      from (
        select run_id,business_id,object_type,provider_object_id,result,
               expected_digest,actual_digest,detail,created_at
          from public.billing_reconciliation_items
         where p_run is not null and run_id=p_run
         order by created_at desc limit 500
      ) items
    ),'[]'::jsonb)
  );
end
$$;

--
-- Name: get_birthday_program_draft(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_birthday_program_draft(p_config_version uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_header public.firm_config_versions%rowtype;
begin
  select * into v_header from public.firm_config_versions where id = p_config_version for share;
  if not found or not app.c45_owner_loyalty_write(v_header.business_id) then
    raise exception 'owner loyalty configuration access required' using errcode = '42501';
  end if;
  if v_header.status <> 'draft' then
    raise exception 'only a draft birthday configuration may be read' using errcode = '42501';
  end if;
  return jsonb_build_object(
    'status', v_header.status,
    'snapshot_hash', v_header.snapshot_hash,
    'programs', coalesce((select jsonb_agg(jsonb_build_object(
      'program_id', p.program_id, 'active', p.active, 'customer_label', p.customer_label,
      'customer_description', p.customer_description, 'customer_terms', p.customer_terms,
      'fulfillment_kind', p.fulfillment_kind, 'discount_percent', p.discount_percent,
      'manual_item', p.manual_item, 'window_days_before', p.window_days_before,
      'window_days_after', p.window_days_after, 'sort', p.sort
    ) order by p.sort, p.program_id) from public.birthday_program_versions p
      where p.config_version_id = p_config_version and p.business_id = v_header.business_id), '[]'::jsonb)
  );
end $$;

--
-- Name: get_booking_availability(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_booking_availability(p_slug text) RETURNS json
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  select coalesce(json_agg(json_build_object(
      'table_type_id', v.table_type_id, 'name', v.name, 'pax', v.pax,
      'quantity', v.quantity, 'held', v.held, 'available', v.available)
      order by v.sort, v.name), '[]'::json)
  from public.v_table_availability v
  join public.businesses b on b.id = v.business_id
  where b.slug = p_slug;
$$;

--
-- Name: get_business_application_status_v95(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_business_application_status_v95(p_public_reference uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_application public.business_applications_v95%rowtype;
begin
  select * into v_application from public.business_applications_v95
  where public_reference=p_public_reference;
  if not found then
    return jsonb_build_object('found',false);
  end if;
  return jsonb_build_object(
    'found',true,'public_reference',v_application.public_reference,
    'status',v_application.status,'version',v_application.version,
    'submitted_at',v_application.created_at,
    'decided_at',v_application.decided_at
  );
end
$$;

--
-- Name: get_business_billing_v124(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_business_billing_v124(p_business uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_base jsonb;
  v_current_customer_count integer;
begin
  if auth.uid() is null
     or not (app.is_salon_owner(p_business) or app.is_super_admin()) then
    raise exception 'active owner or super-admin access is required'
      using errcode = '42501';
  end if;
  v_base := public.get_business_billing_v77(p_business);
  select count(*)::integer into v_current_customer_count
    from public.clients client where client.business_id = p_business;
  return v_base || jsonb_build_object(
    'pricing_model', 'v124_customer_capacity',
    'current_customer_count', v_current_customer_count,
    'staff_billing', false,
    'staff_access_note', 'Staff access is included; use individual logins and roles.',
    'terms', (select to_jsonb(terms) from public.billing_subscription_terms_v124 terms
      where terms.business_id = p_business),
    'money_back_window', (select to_jsonb(window_row)
      from public.billing_money_back_windows_v124 window_row
      where window_row.business_id = p_business),
    'plans', coalesce((
      select jsonb_agg(to_jsonb(plan_rows) order by
        case plan_rows.cadence when 'annual' then 0 else 1 end)
      from (
        select cadence, cadence_months, base_amount_cents,
               included_customer_capacity, capacity_block_size,
               capacity_block_amount_cents, compare_at_monthly_cents,
               tax_behavior
          from public.billing_plan_catalog_v124 catalog
         where currency = 'SGD' and active and effective_from <= now()
           and (effective_to is null or effective_to > now())
      ) plan_rows
    ), '[]'::jsonb),
    'included_modules', jsonb_build_array(
      'Customer CRM and QR signup', 'Loyalty points, stamps and rewards',
      'Birthday benefits and referrals', 'Appointments, team schedule and waitlist',
      'Record sale and sales history', 'Packages, memberships and gift cards',
      'Customer wallet, history and redemption', 'Promotions and template-assisted promotion wording',
      'Feedback and Google review handoff', 'Configured notifications',
      'Profitability and operational reports', 'Branches, roles and permissions',
      'English, Simplified Chinese and Malay business UI'
    ),
    'exclusions', jsonb_build_array(
      'Stripe payment processing fees', 'Usage-priced external messaging',
      'Custom integrations', 'Platform-only administration',
      'Disabled or unconfigured modules'
    )
  );
end;
$$;

