--
-- Name: get_business_billing_v49(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_business_billing_v49(p_business uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_billable_seats integer;
  v_projection jsonb;
begin
  -- Do not rely on the historical app.is_salon_member helper here: its legacy body
  -- predates staff.active and does not enforce the owner-only Settings boundary.
  if v_actor is null or p_business is null or not exists (
    select 1
      from public.staff staff_member
     where staff_member.business_id = p_business
       and staff_member.user_id = v_actor
       and staff_member.active
       and staff_member.role = 'owner'
  ) then
    raise exception 'active business owner access is required' using errcode = '42501';
  end if;

  -- app.billable_seats remains private. This definer executes it only after the
  -- active owner/business check above and returns a finite billing allowlist.
  v_billable_seats := app.billable_seats(p_business);

  select jsonb_build_object(
    'business_id', business.id,
    'status', coalesce(subscription.status, 'trialing'),
    'currency', coalesce(subscription.currency, 'SGD'),
    'base_price_cents', coalesce(subscription.base_price_cents, 2500),
    'included_seats', coalesce(subscription.included_seats, 1),
    'per_seat_price_cents', coalesce(subscription.per_seat_price_cents, 1000),
    'billable_seats', v_billable_seats,
    'extra_seats', greatest(
      v_billable_seats - coalesce(subscription.included_seats, 1), 0
    ),
    'monthly_total_cents',
      coalesce(subscription.base_price_cents, 2500)::bigint
      + greatest(
          v_billable_seats - coalesce(subscription.included_seats, 1), 0
        )::bigint * coalesce(subscription.per_seat_price_cents, 1000)::bigint,
    'trial_ends_at', subscription.trial_ends_at,
    'current_period_start', subscription.current_period_start,
    'current_period_end', subscription.current_period_end
  )
    into v_projection
    from public.businesses business
    left join public.subscriptions subscription
      on subscription.business_id = business.id
   where business.id = p_business;

  -- Keep nonexistent and unauthorized business identifiers indistinguishable.
  if v_projection is null then
    raise exception 'active business owner access is required' using errcode = '42501';
  end if;

  return v_projection;
end
$$;

--
-- Name: FUNCTION get_business_billing_v49(p_business uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_business_billing_v49(p_business uuid) IS 'Finite billing projection for an authenticated active owner of the requested business. The private seat counter remains unexposed.';

--
-- Name: get_business_billing_v77(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_business_billing_v77(p_business uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_result jsonb;
begin
  if auth.uid() is null
     or not (app.is_salon_owner(p_business) or app.is_super_admin()) then
    raise exception 'active owner or super-admin access is required'
      using errcode='42501';
  end if;
  select jsonb_build_object(
    'business_id',s.business_id,'status',s.status,
    'payment_status',s.payment_status,'currency',s.currency,
    'cadence',s.billing_cadence,'cadence_months',s.cadence_months,
    'billable_seats',app.billable_seats(s.business_id),
    'provider_seat_quantity',s.provider_seat_quantity,
    'period_subtotal_cents',s.period_subtotal_cents,
    'period_tax_cents',s.period_tax_cents,
    'period_total_cents',s.period_total_cents,
    'tax_behavior',s.tax_behavior,
    'provider',jsonb_build_object(
      'name',s.billing_provider,'customer_id',s.provider_customer_id,
      'subscription_id',s.provider_subscription_id
    ),
    'current_period_start',s.current_period_start,
    'current_period_end',s.current_period_end,
    'next_payment_at',s.next_payment_at,
    'last_paid_at',s.last_paid_at,
    'last_paid_invoice_id',s.last_paid_invoice_id,
    'cancel_at_period_end',s.cancel_at_period_end,
    'invoices',coalesce((
      select jsonb_agg(to_jsonb(invoice_rows) order by invoice_rows.sort_at desc)
      from (
        select provider_invoice_id,number,status,paid_normalized,currency,
               subtotal_ex_tax_cents,tax_cents,total_cents,amount_paid_cents,
               amount_remaining_cents,collection_method,period_start,period_end,
               paid_at,next_payment_attempt_at,
               coalesce(paid_at,created_at) sort_at
          from public.billing_provider_invoices
         where business_id=p_business
         order by coalesce(paid_at,created_at) desc limit 20
      ) invoice_rows
    ),'[]'::jsonb),
    'payment_attempts',coalesce((
      select jsonb_agg(to_jsonb(attempt_rows) order by attempt_rows.occurred_at desc)
      from (
        select provider_invoice_id,attempt_state,amount_cents,tax_cents,
               failure_code,next_attempt_at,occurred_at,collection_method
          from public.billing_payment_attempts
         where business_id=p_business order by occurred_at desc limit 20
      ) attempt_rows
    ),'[]'::jsonb),
    'adjustments',coalesce((
      select jsonb_agg(to_jsonb(adjustment_rows) order by adjustment_rows.occurred_at desc)
      from (
        select id,provider_invoice_id,adjustment_type,subtotal_ex_tax_cents,
               tax_cents,total_cents,currency,reason,occurred_at,reversal_of
          from public.billing_adjustments
         where business_id=p_business order by occurred_at desc limit 20
      ) adjustment_rows
    ),'[]'::jsonb),
    'commands',coalesce((
      select jsonb_agg(to_jsonb(command_rows) order by command_rows.requested_at desc)
      from (
        select id command_id,command_type,requested_cadence,status,redirect_url,
               error_code,requested_at,completed_at
          from public.billing_commands
         where business_id=p_business order by requested_at desc limit 10
      ) command_rows
    ),'[]'::jsonb)
  ) into v_result
    from public.subscriptions s where s.business_id=p_business;
  if v_result is null then
    raise exception 'billing subscription was not found' using errcode='22023';
  end if;
  return v_result;
end
$$;

--
-- Name: get_business_onboarding_v79(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_business_onboarding_v79(p_business uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if not app.is_platform_operator_v75() and not exists(
    select 1 from public.staff where business_id=p_business and user_id=auth.uid()
      and role='owner' and active
  ) then raise exception 'platform operator or active workspace owner access is required' using errcode='42501';end if;
  if not exists(select 1 from public.business_onboarding_checklists where business_id=p_business) then
    raise exception 'onboarding checklist was not found' using errcode='22023';end if;
  return app.get_onboarding_core_v79(p_business);
end
$$;

