-- Name: get_customer_feature_capabilities(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_customer_feature_capabilities() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if auth.uid() is null then raise exception 'authenticated session required' using errcode='28000'; end if;
