    'customer_identity',app.platform_feature_enabled('customer_identity'),
    'customer_claims',app.platform_feature_enabled('customer_claims'),
    'customer_wallet',app.platform_feature_enabled('customer_wallet'),
    'customer_actions',app.platform_feature_enabled('customer_actions'),
    'customer_notifications',app.platform_feature_enabled('customer_notifications'),
    'customer_email_otp',app.platform_feature_enabled('customer_email_otp'),
    'customer_phone_otp',app.platform_feature_enabled('customer_phone_otp'),
    'customer_whatsapp_otp',app.platform_feature_enabled('customer_whatsapp_otp'),
    'customer_phone_registration',app.platform_feature_enabled('customer_phone_registration'),
    'customer_phone_claims',app.platform_feature_enabled('customer_phone_claims'),
    'customer_actionable_wallet',app.platform_feature_enabled('customer_actionable_wallet'),
    'customer_birthday_benefits',app.platform_feature_enabled('customer_birthday_benefits'),
    'customer_in_app_inbox',app.platform_feature_enabled('customer_in_app_inbox')
  );
end;
$$;

--
-- Name: get_customer_identity_coverage_v111(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_customer_identity_coverage_v111(p_business uuid, p_branch uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_total bigint;
  v_identified bigint;
  v_corrected bigint;
  v_raw_customers bigint;
  v_canonical_customers bigint;
begin
  if auth.uid() is null
     or not app.v111_can_propose(p_business,p_branch) then
    raise exception 'identity coverage is outside actor scope' using errcode='42501';
  end if;
  select
    count(*)::bigint,
    count(*) filter(where s.client_id is not null)::bigint,
    count(*) filter(where current.effective_client_id is distinct from s.client_id)::bigint,
    count(distinct s.client_id) filter(where s.client_id is not null)::bigint,
    count(distinct coalesce(current.effective_client_id,s.client_id))
      filter(where s.client_id is not null)::bigint
  into v_total,v_identified,v_corrected,v_raw_customers,v_canonical_customers
  from public.sales s
  left join public.customer_identity_current_attribution_v111 current
    on current.business_id=s.business_id and current.source_client_id=s.client_id
  where s.business_id=p_business
    and (p_branch is null or s.branch_id=p_branch)
    and s.amount_cents>=0
    and s.counts_as_revenue
    and s.reversal_of is null
    and not exists(
      select 1 from public.sales reversal
      where reversal.business_id=s.business_id
        and reversal.reversal_of=s.id
    );
  return jsonb_build_object(
    'business_id',p_business,'branch_id',p_branch,
    'eligible_transaction_count',v_total,
    'identified_transaction_count',v_identified,
    'corrected_transaction_count',v_corrected,
    'raw_identified_customer_count',v_raw_customers,
    'canonical_identified_customer_count',v_canonical_customers,
    'identified_transaction_coverage',
      case when v_total=0 then null else round(v_identified::numeric/v_total,6) end
  );
end
$$;

--
-- Name: get_customer_identity_proposal_v111(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_customer_identity_proposal_v111(p_proposal uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_proposal public.customer_identity_proposals_v111%rowtype;
begin
  if auth.uid() is null then raise exception 'authentication required' using errcode='42501'; end if;
  select * into v_proposal from public.customer_identity_proposals_v111 where id=p_proposal;
  if not found then raise exception 'identity proposal not found' using errcode='23503'; end if;
  if not app.v111_can_propose(v_proposal.business_id,v_proposal.branch_id) then
    raise exception 'identity proposal is outside actor scope' using errcode='42501';
  end if;
  return jsonb_build_object(
    'proposal',to_jsonb(v_proposal),
    'proofs',coalesce((
      select jsonb_agg(to_jsonb(proof) order by proof.validated_at,proof.id)
      from public.customer_identity_proofs_v111 proof
      where proof.proposal_id=p_proposal
    ),'[]'::jsonb),
    'decisions',coalesce((
      select jsonb_agg(to_jsonb(decision) order by decision.decided_at,decision.id)
      from public.customer_identity_decisions_v111 decision
      where decision.proposal_id=p_proposal
    ),'[]'::jsonb),
    'attribution_history',coalesce((
      select jsonb_agg(to_jsonb(event) order by event.occurred_at,event.id)
      from public.customer_identity_attribution_events_v111 event
      where event.proposal_id=p_proposal
    ),'[]'::jsonb)
  );
end
$$;

--
-- Name: get_customer_intelligence_export_page_v83(uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_customer_intelligence_export_page_v83(p_export uuid, p_after_ordinal integer DEFAULT 0, p_limit integer DEFAULT 500) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid:=auth.uid();
  v_export public.customer_intelligence_exports_v83%rowtype;
  v_result jsonb;
begin
  if p_after_ordinal is null or p_after_ordinal<0 then
    raise exception 'after_ordinal_must_be_nonnegative' using errcode='22023';
  end if;
  if p_limit is null or p_limit<1 or p_limit>500 then
    raise exception 'limit_must_be_between_1_and_500' using errcode='22023';
  end if;
  select * into v_export
  from public.customer_intelligence_exports_v83 export
  where export.id=p_export and export.requested_by=v_actor;
  if not found then
    raise exception 'export_not_found' using errcode='22023';
  end if;
  if v_export.expires_at<=clock_timestamp() then
    raise exception 'export_expired' using errcode='22023';
  end if;
  if not app.has_perm(v_export.business_id,'view_finance')
     or not app.can_see_branch(v_export.business_id,v_export.branch_id) then
    raise exception 'export_scope_no_longer_permitted' using errcode='42501';
  end if;

  with page as materialized (
    select row.ordinal,row.payload
    from public.customer_intelligence_export_rows_v83 row
    where row.export_id=p_export and row.ordinal>p_after_ordinal
    order by row.ordinal limit p_limit
  )
  select jsonb_build_object(
    'export_id',v_export.id,'snapshot_at',v_export.snapshot_at,
    'expires_at',v_export.expires_at,'scope',v_export.scope,
    'methodology',v_export.methodology,'data_quality',v_export.data_quality,
    'summary',v_export.summary,'forecast',v_export.forecast,
    'customers',coalesce((
      select jsonb_agg(payload order by ordinal) from page
    ),'[]'::jsonb),
    'pagination',jsonb_build_object(
      'limit',p_limit,'total_customers',v_export.total_customers,
      'returned_customers',(select count(*) from page),
      'has_more',coalesce((select max(ordinal) from page),p_after_ordinal)
        <v_export.total_customers,
      'next_ordinal',case
        when coalesce((select max(ordinal) from page),p_after_ordinal)
          <v_export.total_customers
        then (select max(ordinal) from page) else null end
    )
  ) into v_result;
  return v_result;
end
$$;

--
-- Name: get_customer_intelligence_v83(uuid, uuid, date, date, integer, timestamp with time zone, timestamp with time zone, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_customer_intelligence_v83(p_business uuid, p_branch uuid DEFAULT NULL::uuid, p_from date DEFAULT (((now() AT TIME ZONE 'Asia/Singapore'::text))::date - 365), p_to date DEFAULT ((now() AT TIME ZONE 'Asia/Singapore'::text))::date, p_limit integer DEFAULT 250, p_snapshot_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_after_created_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_after_client uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_from_ts timestamptz;
  v_to_ts timestamptz;
  v_snapshot_at timestamptz := coalesce(p_snapshot_at,clock_timestamp());
  v_forecast_end_date date;
  v_forecast_start_date date;
  v_result jsonb;
  v_history_days integer := 0;
  v_active_weeks integer := 0;
  v_completed_transactions integer := 0;
  v_cash_observation_weeks integer := 0;
  v_forecast_eligible boolean;
  v_unmet jsonb := '[]'::jsonb;
  v_weekly_average numeric := 0;
  v_weekly_lower numeric := 0;
  v_weekly_upper numeric := 0;
  v_forecast jsonb;
begin
  if p_business is null then
    raise exception 'business_required' using errcode='22023';
  end if;
  if not app.has_perm(p_business,'view_finance') then
    raise exception 'view_finance_required' using errcode='42501';
  end if;
  if p_from is null or p_to is null or p_from>p_to then
    raise exception 'invalid_report_window' using errcode='22023';
  end if;
  if p_to-p_from>1826 then
    raise exception 'report_window_exceeds_five_years' using errcode='22023';
  end if;
  if p_limit is null or p_limit<1 or p_limit>500 then
    raise exception 'limit_must_be_between_1_and_500' using errcode='22023';
  end if;
  if (p_after_created_at is null)<>(p_after_client is null) then
    raise exception 'complete_customer_cursor_required' using errcode='22023';
  end if;
  if p_snapshot_at is not null and p_snapshot_at>clock_timestamp()+interval '1 minute' then
    raise exception 'snapshot_cannot_be_in_the_future' using errcode='22023';
  end if;
  if p_branch is not null and not exists(
    select 1 from public.branches branch
    where branch.id=p_branch and branch.business_id=p_business
  ) then
    raise exception 'branch_not_in_business' using errcode='22023';
  end if;
  if not app.can_see_branch(p_business,p_branch) then
    raise exception 'branch_visibility_required' using errcode='42501';
  end if;

  v_from_ts:=p_from::timestamp at time zone 'Asia/Singapore';
  v_to_ts:=(p_to+1)::timestamp at time zone 'Asia/Singapore';
  -- Sunday is a complete Singapore ISO week; every other p_to excludes its
  -- partial week and anchors on that week's Monday.
  v_forecast_end_date:=case
    when extract(isodow from p_to)::integer=7 then p_to+1
    else p_to-(extract(isodow from p_to)::integer-1)
  end;
  v_forecast_start_date:=v_forecast_end_date-91;

  select coalesce(
    (v_forecast_end_date-1)
      - min((sale.occurred_at at time zone 'Asia/Singapore')::date),0
  )::integer
  into v_history_days
  from public.sales sale
  where sale.business_id=p_business
    and sale.created_at<=v_snapshot_at
    and sale.reversal_of is null
    and sale.amount_cents>0
    and sale.counts_as_revenue
    and sale.occurred_at
      < v_forecast_end_date::timestamp at time zone 'Asia/Singapore'
    and (p_branch is null or sale.branch_id=p_branch)
    and not exists(
      select 1 from public.sales reversal
      where reversal.business_id=sale.business_id
        and reversal.reversal_of=sale.id
        and reversal.created_at<=v_snapshot_at
        and reversal.occurred_at
          < v_forecast_end_date::timestamp at time zone 'Asia/Singapore'
    );

  select count(distinct date_trunc(
           'week',sale.occurred_at at time zone 'Asia/Singapore'
         ))::integer,
         count(*)::integer
  into v_active_weeks,v_completed_transactions
  from public.sales sale
  where sale.business_id=p_business
    and sale.created_at<=v_snapshot_at
    and sale.reversal_of is null
    and sale.amount_cents>0
    and sale.counts_as_revenue
    and sale.occurred_at
      >= v_forecast_start_date::timestamp at time zone 'Asia/Singapore'
    and sale.occurred_at
      < v_forecast_end_date::timestamp at time zone 'Asia/Singapore'
    and (p_branch is null or sale.branch_id=p_branch)
    and not exists(
      select 1 from public.sales reversal
      where reversal.business_id=sale.business_id
        and reversal.reversal_of=sale.id
        and reversal.created_at<=v_snapshot_at
        and reversal.occurred_at
          < v_forecast_end_date::timestamp at time zone 'Asia/Singapore'
    );

  with week_series as (
    select week_start::date
    from generate_series(
      v_forecast_start_date,
      v_forecast_end_date-7,
      interval '1 week'
    ) week_start
  ),weekly as (
    select week.week_start,
           coalesce(sum(payment.amount_cents) filter(
             where payment.method not in ('credit','gift_card')
           ),0)::numeric cash_cents,
           count(payment.id) filter(
             where payment.method not in ('credit','gift_card')
           )::integer payment_count
    from week_series week
    left join public.payments payment
      on payment.business_id=p_business
     and payment.created_at<=v_snapshot_at
     and payment.occurred_at
       >= week.week_start::timestamp at time zone 'Asia/Singapore'
     and payment.occurred_at
       < (week.week_start+7)::timestamp at time zone 'Asia/Singapore'
     and (p_branch is null or payment.branch_id=p_branch)
    group by week.week_start
  )
  select coalesce(avg(cash_cents),0),
         coalesce(percentile_cont(0.20) within group(order by cash_cents),0),
         coalesce(percentile_cont(0.80) within group(order by cash_cents),0),
         count(*) filter(where payment_count>0)::integer
  into v_weekly_average,v_weekly_lower,v_weekly_upper,v_cash_observation_weeks
  from weekly;

  if v_history_days<90 then
    v_unmet:=v_unmet||jsonb_build_array(jsonb_build_object(
      'key','history_days','actual',v_history_days,'required',90
    ));
  end if;
  if v_active_weeks<12 then
    v_unmet:=v_unmet||jsonb_build_array(jsonb_build_object(
      'key','active_weeks','actual',v_active_weeks,'required',12
    ));
  end if;
  if v_completed_transactions<30 then
    v_unmet:=v_unmet||jsonb_build_array(jsonb_build_object(
      'key','completed_transactions','actual',v_completed_transactions,'required',30
    ));
  end if;
  if v_cash_observation_weeks<8 then
    v_unmet:=v_unmet||jsonb_build_array(jsonb_build_object(
      'key','cash_observation_weeks','actual',v_cash_observation_weeks,'required',8
    ));
  end if;
  v_forecast_eligible:=jsonb_array_length(v_unmet)=0;

  if v_forecast_eligible then
    select jsonb_build_object(
      'status','available',
      'method','trailing_13_complete_singapore_calendar_weeks_p20_mean_p80',
      'data_valid_through',p_to,
      'observation_start',v_forecast_start_date,
      'observation_end_exclusive',v_forecast_end_date,
      'complete_weeks',13,
      'partial_report_end_week_excluded',
        extract(isodow from p_to)::integer<>7,
      'weekly_average_cents',round(v_weekly_average)::bigint,
      'weekly_lower_cents',round(v_weekly_lower)::bigint,
      'weekly_upper_cents',round(v_weekly_upper)::bigint,
      'next_90_days',jsonb_build_object(
        'lower_cents',greatest(0,round(v_weekly_lower*90/7))::bigint,
        'expected_cents',greatest(0,round(v_weekly_average*90/7))::bigint,
        'upper_cents',greatest(0,round(v_weekly_upper*90/7))::bigint
      ),
      'months',(
        select jsonb_agg(jsonb_build_object(
          'month_index',month_index,
          'from',month_start,
          'to',month_end,
          'lower_cents',greatest(0,round(
            v_weekly_lower*((month_end-month_start)+1)/7
          ))::bigint,
          'expected_cents',greatest(0,round(
            v_weekly_average*((month_end-month_start)+1)/7
          ))::bigint,
          'upper_cents',greatest(0,round(
            v_weekly_upper*((month_end-month_start)+1)/7
          ))::bigint
        ) order by month_index)
        from (
          select month_index,
                 (p_to+1+make_interval(months=>month_index-1))::date month_start,
                 (p_to+make_interval(months=>month_index))::date month_end
          from generate_series(1,3) month_index
        ) windows
      ),
      'caution','Observed 20th percentile, mean and 80th percentile from 13 complete Singapore calendar weeks; this operating range is not a guarantee.'
    ) into v_forecast;
  else
    v_forecast:=jsonb_build_object(
      'status','insufficient_data',
      'data_valid_through',p_to,
      'observation_start',v_forecast_start_date,
      'observation_end_exclusive',v_forecast_end_date,
      'unmet_thresholds',v_unmet,
      'required_thresholds',jsonb_build_object(
        'history_days',90,'active_weeks',12,
        'completed_transactions',30,'cash_observation_weeks',8
      ),
      'message','A 3-month cash-collection range appears only after enough complete-week evidence exists.'
    );
  end if;

  with period_sales as materialized (
    select sale.*
    from public.sales sale
    where sale.business_id=p_business
      and sale.created_at<=v_snapshot_at
      and sale.occurred_at>=v_from_ts and sale.occurred_at<v_to_ts
      and (p_branch is null or sale.branch_id=p_branch)
  ),valid_period_purchases as materialized (
    select sale.*
    from period_sales sale
    where sale.reversal_of is null and sale.amount_cents>0
      and sale.counts_as_revenue
      and not exists(
        select 1 from public.sales reversal
        where reversal.business_id=sale.business_id
          and reversal.reversal_of=sale.id
          and reversal.created_at<=v_snapshot_at
          and reversal.occurred_at<v_to_ts
      )
  ),valid_period_visits as materialized (
    select sale.*
    from period_sales sale
    where sale.reversal_of is null and sale.amount_cents>0
      and sale.counts_as_visit
      and not exists(
        select 1 from public.sales reversal
        where reversal.business_id=sale.business_id
          and reversal.reversal_of=sale.id
          and reversal.created_at<=v_snapshot_at
          and reversal.occurred_at<v_to_ts
      )
  ),valid_lifetime_purchases as materialized (
    select sale.*
    from public.sales sale
    where sale.business_id=p_business
      and sale.created_at<=v_snapshot_at
      and sale.occurred_at<v_to_ts
      and (p_branch is null or sale.branch_id=p_branch)
      and sale.reversal_of is null and sale.amount_cents>0
      and sale.counts_as_revenue
      and not exists(
        select 1 from public.sales reversal
        where reversal.business_id=sale.business_id
          and reversal.reversal_of=sale.id
          and reversal.created_at<=v_snapshot_at
          and reversal.occurred_at<v_to_ts
      )
  ),period_revenue as (
    select sale.client_id,
           coalesce(sum(sale.amount_cents) filter(
             where sale.counts_as_revenue
           ),0)::bigint net_revenue_cents
    from period_sales sale where sale.client_id is not null
    group by sale.client_id
  ),period_purchases as (
    select sale.client_id,count(*)::integer purchase_count,
           min(sale.occurred_at) period_first_purchase_at,
           max(sale.occurred_at) period_last_purchase_at
    from valid_period_purchases sale where sale.client_id is not null
    group by sale.client_id
  ),period_visits as (
    select sale.client_id,count(*)::integer visit_count
    from valid_period_visits sale where sale.client_id is not null
    group by sale.client_id
  ),period_cash as (
    select coalesce(payment.client_id,sale.client_id) client_id,
           coalesce(sum(payment.amount_cents) filter(
             where payment.method not in ('credit','gift_card')
           ),0)::bigint cash_collected_cents
    from public.payments payment
    left join public.sales sale
      on sale.id=payment.sale_id and sale.business_id=payment.business_id
    where payment.business_id=p_business
      and payment.created_at<=v_snapshot_at
      and payment.occurred_at>=v_from_ts and payment.occurred_at<v_to_ts
      and (p_branch is null or payment.branch_id=p_branch)
      and coalesce(payment.client_id,sale.client_id) is not null
    group by coalesce(payment.client_id,sale.client_id)
  ),lifetime as (
    select sale.client_id,count(*)::integer lifetime_purchase_count,
           min(sale.occurred_at) first_purchase_at,
           max(sale.occurred_at) last_purchase_at,
           count(distinct sale.branch_id)::integer branches_visited,
           case when count(*)<2 then null else round(
             extract(epoch from(max(sale.occurred_at)-min(sale.occurred_at)))
             /86400/(count(*)-1),1
           ) end average_days_between_purchases
    from valid_lifetime_purchases sale where sale.client_id is not null
    group by sale.client_id
  ),client_metrics as materialized (
    select client.id client_id,client.full_name,client.email,client.phone,
           client.created_at customer_since,
           coalesce(revenue.net_revenue_cents,0)::bigint net_revenue_cents,
           coalesce(cash.cash_collected_cents,0)::bigint cash_collected_cents,
           coalesce(purchase.purchase_count,0)::integer purchase_count,
           coalesce(visit.visit_count,0)::integer visit_count,
           purchase.period_first_purchase_at,purchase.period_last_purchase_at,
           lifetime.first_purchase_at,lifetime.last_purchase_at,
           case when lifetime.last_purchase_at is null then null
             else p_to-(lifetime.last_purchase_at at time zone 'Asia/Singapore')::date
           end days_since_last_purchase,
           coalesce(lifetime.branches_visited,0)::integer branches_visited,
           coalesce(lifetime.lifetime_purchase_count,0)::integer lifetime_purchase_count,
           coalesce(purchase.purchase_count,0)>=2 returning_customer,
           case when coalesce(purchase.purchase_count,0)=0 then 0 else round(
             coalesce(revenue.net_revenue_cents,0)::numeric/purchase.purchase_count
           )::bigint end average_revenue_per_purchase_cents,
           lifetime.average_days_between_purchases
    from public.clients client
    left join period_revenue revenue on revenue.client_id=client.id
    left join period_purchases purchase on purchase.client_id=client.id
    left join period_visits visit on visit.client_id=client.id
    left join period_cash cash on cash.client_id=client.id
    left join lifetime on lifetime.client_id=client.id
    where client.business_id=p_business
      and client.created_at<=v_snapshot_at
      and (p_branch is null or lifetime.client_id is not null)
  ),page as materialized (
    select * from client_metrics customer
    where p_after_created_at is null
       or (customer.customer_since,customer.client_id)
          >(p_after_created_at,p_after_client)
    order by customer_since,client_id
    limit p_limit
  ),last_page as (
    select customer_since,client_id
    from page order by customer_since desc,client_id desc limit 1
  ),page_state as (
    select exists(
      select 1 from client_metrics customer,last_page last
      where (customer.customer_since,customer.client_id)
            >(last.customer_since,last.client_id)
    ) has_more
  )
  select jsonb_build_object(
    'generated_at',v_snapshot_at,
    'snapshot_at',v_snapshot_at,
    'scope',jsonb_build_object(
      'business_id',p_business,'business_name',business.name,
      'currency',business.currency,'branch_id',p_branch,'branch_name',branch.name,
      'from',p_from,'to',p_to,'timezone','Asia/Singapore'
    ),
    'methodology',jsonb_build_object(
      'period_metrics','Revenue, cash, active and returning metrics use p_from through p_to.',
      'lifetime_inactivity','Last purchase and inactivity use all valid purchases through p_to.',
      'revenue','Net immutable sales ledger events at the generated-at cutoff.',
      'cash_collected','External payment ledger less refunds; credit and gift-card tenders excluded.',
      'forecast','Thirteen complete Singapore calendar weeks; partial report-end week excluded; p20/mean/p80 range.',
      'returning_customer','At least two completed unreversed revenue transactions in the selected period.',
      'returning_rate_denominator','Active customers with at least one completed period purchase.',
      'pagination','Immutable customer_since/client_id keyset at one generated-at cutoff.'
    ),
    'data_quality',jsonb_build_object(
      'forecast_eligible',v_forecast_eligible,'history_days',v_history_days,
      'active_weeks',v_active_weeks,
      'completed_transactions',v_completed_transactions,
      'cash_observation_weeks',v_cash_observation_weeks,
      'required_thresholds',jsonb_build_object(
        'history_days',90,'active_weeks',12,
        'completed_transactions',30,'cash_observation_weeks',8
      ),'unmet_thresholds',v_unmet
    ),
    'summary',jsonb_build_object(
      'known_customers',(select count(*) from client_metrics),
      'active_customers',(select count(*) from client_metrics where purchase_count>0),
      'returning_customers',(select count(*) from client_metrics where returning_customer),
      'returning_rate_pct',(
        select case when count(*) filter(where purchase_count>0)=0 then 0
          else round(100.0*count(*) filter(where returning_customer)
            /count(*) filter(where purchase_count>0),1) end
        from client_metrics
      ),
      'net_revenue_cents',(select coalesce(sum(net_revenue_cents),0) from client_metrics),
      'cash_collected_cents',(select coalesce(sum(cash_collected_cents),0) from client_metrics),
      'average_revenue_per_active_customer_cents',(
        select case when count(*) filter(where purchase_count>0)=0 then 0
          else round(sum(net_revenue_cents)::numeric
            /count(*) filter(where purchase_count>0))::bigint end
        from client_metrics
      ),
      'average_purchase_frequency_days',(
        select round(avg(average_days_between_purchases),1)
        from client_metrics where average_days_between_purchases is not null
      ),
      'customers_over_90_days_inactive',(
        select count(*) from client_metrics where days_since_last_purchase>90
      )
    ),
    'forecast',v_forecast,
    'customers',coalesce((
      select jsonb_agg(to_jsonb(customer) order by customer_since,client_id)
      from page customer
    ),'[]'::jsonb),
    'pagination',jsonb_build_object(
      'limit',p_limit,'total_customers',(select count(*) from client_metrics),
      'returned_customers',(select count(*) from page),
      'has_more',coalesce((select has_more from page_state),false),
      'next_cursor',case
        when coalesce((select has_more from page_state),false) then (
          select jsonb_build_object(
            'customer_since',customer_since,'client_id',client_id
          ) from last_page
        ) else null end
    )
  ) into v_result
  from public.businesses business
  left join public.branches branch
    on branch.id=p_branch and branch.business_id=business.id
  where business.id=p_business;

  if v_result is null then
    raise exception 'business_not_found' using errcode='22023';
  end if;
  return v_result;
end
$$;

--
-- Name: FUNCTION get_customer_intelligence_v83(p_business uuid, p_branch uuid, p_from date, p_to date, p_limit integer, p_snapshot_at timestamp with time zone, p_after_created_at timestamp with time zone, p_after_client uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_customer_intelligence_v83(p_business uuid, p_branch uuid, p_from date, p_to date, p_limit integer, p_snapshot_at timestamp with time zone, p_after_created_at timestamp with time zone, p_after_client uuid) IS 'Customer intelligence with period metrics, lifetime inactivity, complete-week forecast and snapshot keyset pagination.';

--
-- Name: get_customer_lifecycle_v107(uuid, date, date, uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_customer_lifecycle_v107(p_business uuid, p_from date, p_to date, p_branch uuid DEFAULT NULL::uuid, p_as_of timestamp with time zone DEFAULT clock_timestamp()) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_policy public.customer_lifecycle_policies_v107%rowtype;
  v_timezone text;
  v_currency text;
  v_business_wide_identity boolean;
  v_result jsonb;
begin
  if auth.uid() is null then
    raise exception 'authentication required' using errcode = '42501';
  end if;
  if p_to <= p_from then
    raise exception 'p_to must be after p_from' using errcode = '22023';
  end if;
  if not (app.is_super_admin() or app.has_perm(p_business, 'view_finance')) then
    raise exception 'finance permission required' using errcode = '42501';
  end if;
  if not app.can_see_branch(p_business, p_branch) then
    raise exception 'branch is outside actor scope' using errcode = '42501';
  end if;
  if p_branch is not null and not exists (
    select 1 from public.branches b
     where b.id = p_branch and b.business_id = p_business
  ) then
    raise exception 'branch does not belong to business' using errcode = '23503';
  end if;
  v_business_wide_identity := app.can_see_branch(p_business, null);
  select * into strict v_policy
    from public.customer_lifecycle_policies_v107 p
   where p.business_id = p_business and p.effective_from <= p_as_of
   order by p.effective_from desc, p.version_no desc limit 1;
  select upper(currency) into strict v_currency
    from public.businesses where id = p_business;
  if p_branch is null then
    v_timezone := 'per_outlet';
  else
    select timezone into strict v_timezone
      from public.branches where id = p_branch and business_id = p_business;
  end if;

  with eligible as materialized (
    select s.id,
           app.v111_effective_client_id(s.business_id, s.client_id) as client_id,
           s.branch_id, s.occurred_at, s.created_at,
           s.amount_cents, c.timezone,
           app.v106_sale_residual_minor(s.id, p_to, p_as_of)
             as residual_minor
      from public.sales s
      cross join lateral app.v106_reporting_contract(
        s.business_id, s.branch_id, s.occurred_at
      ) c
     where s.business_id = p_business
       and s.reversal_of is null
       and s.counts_as_visit
       and s.created_at <= p_as_of
       and (
         v_business_wide_identity
         or (p_branch is not null and s.branch_id = p_branch)
       )
  ), sequenced as (
    select e.*,
           min(e.occurred_at) over (partition by e.client_id) as first_ever_at,
           first_value((e.occurred_at at time zone e.timezone)::date) over (
             partition by e.client_id order by e.occurred_at, e.id
           ) as first_ever_business_date,
           lag(e.occurred_at) over (
             partition by e.client_id order by e.occurred_at, e.id
           ) as previous_purchase_at,
           row_number() over (
             partition by e.client_id order by e.occurred_at, e.id
           ) as purchase_sequence,
           ((e.occurred_at at time zone e.timezone)::date >= p_from
             and (e.occurred_at at time zone e.timezone)::date < p_to
             and (p_branch is null or e.branch_id = p_branch)) as in_selected_period
      from eligible e
     where e.residual_minor > 0
  ), interval_evidence as (
    select client_id,
           count(*) filter (where previous_purchase_at is not null)::integer
             as interval_observations,
           percentile_cont(0.5) within group (
             order by extract(epoch from (occurred_at - previous_purchase_at)) / 86400.0
           ) filter (where previous_purchase_at is not null)
             as median_interval_days
      from sequenced
     where client_id is not null
       and (occurred_at at time zone timezone)::date < p_from
     group by client_id
  ), customer_activity as (
    select s.client_id,
           count(*) filter (where s.in_selected_period)::integer as period_purchases,
           min(s.occurred_at) filter (where s.in_selected_period) as first_period_at,
           min(s.first_ever_at) as first_ever_at,
           bool_or(
             (s.occurred_at at time zone s.timezone)::date < p_from
           ) as purchased_before_period
      from sequenced s
     where s.client_id is not null
     group by s.client_id
    having count(*) filter (where s.in_selected_period) > 0
  ), first_period_evidence as (
    select distinct on (s.client_id)
           s.client_id, s.previous_purchase_at, s.timezone,
           s.first_ever_business_date
      from sequenced s
      join customer_activity a
        on a.client_id = s.client_id and a.first_period_at = s.occurred_at
     where s.in_selected_period
     order by s.client_id, s.occurred_at, s.id
  ), classified as (
    select a.*,
           f.previous_purchase_at,
           f.first_ever_business_date,
           coalesce(i.interval_observations, 0) as interval_observations,
           i.median_interval_days,
           case
             when coalesce(i.interval_observations, 0)
                    >= v_policy.customer_interval_min_observations
               then greatest(
                 1.0,
                 i.median_interval_days * v_policy.reactivation_multiplier
               )
             else v_policy.fallback_lapse_days::numeric
           end as effective_lapse_days,
           case
             when coalesce(i.interval_observations, 0)
                    >= v_policy.customer_interval_min_observations
               then 'customer_median_interval'
             else 'business_fallback'
           end as lapse_evidence_source
      from customer_activity a
      join first_period_evidence f using (client_id)
      left join interval_evidence i using (client_id)
  ), totals as (
    select
      count(*)::bigint as transacting_identified_customers,
      count(*) filter (
        where first_ever_business_date >= p_from
          and first_ever_business_date < p_to
      )::bigint as new_customers,
      count(*) filter (where purchased_before_period)::bigint
        as existing_returning_customers,
      count(*) filter (where period_purchases >= 2)::bigint
        as repeat_purchasers_in_period,
      count(*) filter (
        where purchased_before_period
          and previous_purchase_at is not null
          and extract(epoch from (first_period_at - previous_purchase_at)) / 86400.0
                > effective_lapse_days
      )::bigint as reactivated_customers,
      count(*) filter (
        where lapse_evidence_source = 'customer_median_interval'
      )::bigint as customer_cadence_classifications,
      count(*) filter (
        where lapse_evidence_source = 'business_fallback'
      )::bigint as fallback_classifications
    from classified
  ), transaction_coverage as (
    select
      count(*) filter (
        where (occurred_at at time zone timezone)::date >= p_from
          and (occurred_at at time zone timezone)::date < p_to
          and (p_branch is null or branch_id = p_branch)
          and residual_minor > 0
      )::bigint as eligible_transactions,
      count(*) filter (
        where (occurred_at at time zone timezone)::date >= p_from
          and (occurred_at at time zone timezone)::date < p_to
          and (p_branch is null or branch_id = p_branch)
          and residual_minor > 0 and client_id is not null
      )::bigint as identified_transactions,
      max(occurred_at) filter (
        where (occurred_at at time zone timezone)::date >= p_from
          and (occurred_at at time zone timezone)::date < p_to
          and (p_branch is null or branch_id = p_branch)
          and residual_minor > 0
      ) as latest_purchase_occurred_at
    from eligible
  )
  select jsonb_build_object(
    'contract_version', 'v107.1',
    'generated_at', clock_timestamp(),
    'as_of', p_as_of,
    'scope', jsonb_build_object(
      'business_id', p_business,
      'branch_id', p_branch,
      'period', jsonb_build_object(
        'from', p_from, 'to', p_to, 'interval', '[from,to)'
      ),
      'timezone', v_timezone,
      'timezone_contract', case when p_branch is null
        then 'per_outlet_effective_timezone'
        else 'selected_outlet_effective_timezone'
      end,
      'currency', v_currency,
      'identity_scope', case when v_business_wide_identity
        then 'business'
        else 'selected_branch'
      end,
      'period_activity_scope', case when p_branch is null then 'business' else 'branch' end
    ),
    'status', case when x.eligible_transactions = 0 then 'no_data' else 'ok' end,
    'policy', jsonb_build_object(
      'id', v_policy.id,
      'version_no', v_policy.version_no,
      'effective_from', v_policy.effective_from,
      'fallback_lapse_days', v_policy.fallback_lapse_days,
      'customer_interval_min_observations',
        v_policy.customer_interval_min_observations,
      'reactivation_multiplier', v_policy.reactivation_multiplier,
      'legacy_assumption', v_policy.legacy_assumption
    ),
    'metrics', jsonb_build_object(
      'transacting_identified_customers', t.transacting_identified_customers,
      'new_customers', t.new_customers,
      'existing_returning_customers', t.existing_returning_customers,
      'repeat_purchasers_in_period', t.repeat_purchasers_in_period,
      'reactivated_customers', t.reactivated_customers,
      'existing_customer_share_pct',
        case when t.transacting_identified_customers = 0 then null
          else round(
            100 * t.existing_returning_customers::numeric
              / t.transacting_identified_customers, 2
          ) end,
      'repeat_in_period_rate_pct',
        case when t.transacting_identified_customers = 0 then null
          else round(
            100 * t.repeat_purchasers_in_period::numeric
              / t.transacting_identified_customers, 2
          ) end,
      'customer_cadence_classifications', t.customer_cadence_classifications,
      'fallback_classifications', t.fallback_classifications
    ),
    'coverage', jsonb_build_object(
      'eligible_transactions', x.eligible_transactions,
      'identified_transactions', x.identified_transactions,
      'identified_transaction_pct',
        case when x.eligible_transactions = 0 then null
          else round(
            100 * x.identified_transactions::numeric / x.eligible_transactions, 2
          ) end
    ),
    'freshness', jsonb_build_object(
      'latest_purchase_occurred_at', x.latest_purchase_occurred_at
    ),
    'definitions', jsonb_build_object(
      'first_ever_purchase',
        'earliest eligible counts_as_visit purchase in the business',
      'new_customer',
        'first-ever business purchase has a local business date in [from,to)',
      'existing_returning_customer',
        'at least one eligible purchase before from and at least one in [from,to)',
      'repeat_purchaser_in_period',
        'at least two eligible purchases in [from,to); not a synonym for returning',
      'reactivated_customer',
        'existing customer whose first in-period purchase follows a lapse strictly greater than the effective threshold',
      'effective_threshold',
        'customer median interval multiplied by policy multiplier when evidence is sufficient; otherwise policy fallback days'
    ),
    'formula_metadata', jsonb_build_object(
      'version', 'customer_lifecycle_v107_1',
      'eligible_purchase',
        'original sale with counts_as_visit=true, residual amount above zero, and created_at<=as_of',
      'identity_attribution',
        'immutable sales.client_id is resolved through app.v111_effective_client_id for current synchronized reporting',
      'existing_customer_share',
        'existing_returning_customers / transacting_identified_customers',
      'repeat_in_period_rate',
        'repeat_purchasers_in_period / transacting_identified_customers',
      'zero_denominator', 'ratios are null',
      'lapse_comparison', 'gap_days > effective_lapse_days'
    ),
    'limitations', jsonb_build_array(
      'Anonymous purchases contribute to identity coverage but cannot be lifecycle-classified.',
      'Customer-specific cadence uses only pre-period intervals to avoid future leakage.',
      'The migration default is 90 days until an owner or super-admin publishes a business policy.',
      'Lifecycle is aggregate reporting only and does not expose customer PII.'
    )
  ) into v_result
  from totals t cross join transaction_coverage x;
  return v_result;
end $$;

--
-- Name: get_customer_phone_otp_capabilities(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_customer_phone_otp_capabilities() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  return jsonb_build_object(
    'sms',
      app.platform_feature_enabled('customer_phone_registration')
      and app.platform_feature_enabled('customer_phone_otp'),
    'whatsapp',
      app.platform_feature_enabled('customer_phone_registration')
      and app.platform_feature_enabled('customer_phone_otp')
      and app.platform_feature_enabled('customer_whatsapp_otp')
  );
end;
$$;

--
-- Name: get_dashboard_summary(uuid, date, date, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_dashboard_summary(p_business uuid, p_from date, p_to date, p_branch uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_kpis jsonb;
  v_weekdays jsonb;
  v_revenue_by_day jsonb;
  v_gender jsonb;
  v_age jsonb;
  v_sales_available boolean;
  v_clients_available boolean;
  v_loyalty_available boolean;
  v_credit_liability_available boolean;
begin
  if auth.uid() is null
     or not app.has_perm(p_business, 'view_sales') then
    raise exception 'you do not have permission to view this dashboard'
      using errcode = '42501';
  end if;
  if p_from is null or p_to is null or p_from > p_to then
    raise exception 'a valid report date range is required'
      using errcode = '22007';
  end if;
  if p_to - p_from > 1826 then
    raise exception 'report date range cannot exceed 1827 days'
      using errcode = '22023';
  end if;
  if p_branch is not null and not exists (
    select 1 from public.branches b
    where b.id = p_branch and b.business_id = p_business
  ) then
    raise exception 'branch does not belong to this business'
      using errcode = '42501';
  end if;
  if not app.can_see_branch(p_business, p_branch) then
    raise exception 'you are not permitted to view this branch scope'
      using errcode = '42501';
  end if;

  v_sales_available := app.metric_module_scope_available_v145(
    p_business, p_branch, 'sales'
  );
  v_clients_available := app.metric_module_scope_available_v145(
    p_business, null, 'clients'
  );
  v_loyalty_available := app.metric_module_scope_available_v145(
    p_business, p_branch, 'loyalty'
  );
  v_credit_liability_available := app.metric_module_scope_available_v145(
    p_business, null, 'sales'
  );
  if not v_sales_available then
    return jsonb_build_object(
      'availability', jsonb_build_object(
        'sales', false,
        'clients', false,
        'loyalty', false,
        'credit_liability', false
      ),
      'scope', jsonb_build_object(
        'timezone', 'Asia/Singapore',
        'from', p_from,
        'to', p_to,
        'branch_id', p_branch,
        'status', 'unavailable_incomplete_sales_scope'
      )
    );
  end if;

  with scoped_sales as (
    select s.*
    from public.sales s
    where s.business_id = p_business
      and s.occurred_at >= (p_from::timestamp at time zone 'Asia/Singapore')
      and s.occurred_at < ((p_to + 1)::timestamp at time zone 'Asia/Singapore')
      and (p_branch is null or s.branch_id = p_branch)
  ), valid_visits as (
    select s.*
    from scoped_sales s
    where s.counts_as_visit
      and s.reversal_of is null
      and not exists (
        select 1
        from public.sales r
        where r.business_id = s.business_id
          and r.reversal_of = s.id
      )
  )
  select jsonb_build_object(
    'visits', (select count(*) from valid_visits),
    'revenue_cents', coalesce((select sum(s.amount_cents) from scoped_sales s where s.counts_as_revenue), 0),
    'unique_customers', (select count(distinct s.client_id) from valid_visits s where s.client_id is not null)
  )
  into v_kpis;

  v_kpis := v_kpis || jsonb_build_object(
    'new_customers', case when v_clients_available then (
      select count(*) from public.clients c
      where c.business_id = p_business
        and c.created_at >= (p_from::timestamp at time zone 'Asia/Singapore')
        and c.created_at < ((p_to + 1)::timestamp at time zone 'Asia/Singapore')
    ) else null end,
    'points_issued', case when v_loyalty_available then (
      select coalesce(sum(pl.points), 0)
      from public.points_ledger pl
      left join public.sales ps
        on ps.id = pl.sale_id
       and ps.business_id = pl.business_id
      where pl.business_id = p_business
        and pl.entry_type = 'earn'
        and pl.created_at >= (p_from::timestamp at time zone 'Asia/Singapore')
        and pl.created_at < ((p_to + 1)::timestamp at time zone 'Asia/Singapore')
        and (p_branch is null or ps.branch_id = p_branch)
    ) else null end,
    'credit_liability_cents', case when v_credit_liability_available then (
      select coalesce(sum(greatest(cb.balance_cents, 0)), 0)
      from public.client_credit_balance cb
      where cb.business_id = p_business
    ) else null end
  );

  with valid_visits as (
    select s.*
    from public.sales s
    where s.business_id = p_business
      and s.counts_as_visit
      and s.reversal_of is null
      and s.occurred_at >= (p_from::timestamp at time zone 'Asia/Singapore')
      and s.occurred_at < ((p_to + 1)::timestamp at time zone 'Asia/Singapore')
      and (p_branch is null or s.branch_id = p_branch)
      and not exists (
        select 1
        from public.sales r
        where r.business_id = s.business_id
          and r.reversal_of = s.id
      )
  )
  select coalesce(jsonb_agg(coalesce(w.visits, 0) order by d.day_no), '[]'::jsonb)
  into v_weekdays
  from generate_series(1, 7) d(day_no)
  left join (
    select extract(isodow from s.occurred_at at time zone 'Asia/Singapore')::int as day_no,
           count(*) as visits
    from valid_visits s
    group by 1
  ) w using (day_no);

  select coalesce(
    jsonb_agg(jsonb_build_object(
      'day', d.sale_day,
      'amount_cents', coalesce(r.amount_cents, 0)
    ) order by d.sale_day),
    '[]'::jsonb)
  into v_revenue_by_day
  from generate_series(p_from::timestamp, p_to::timestamp, interval '1 day') d0(day_value)
  cross join lateral (select d0.day_value::date as sale_day) d
  left join (
    select (s.occurred_at at time zone 'Asia/Singapore')::date as sale_day,
           sum(s.amount_cents) as amount_cents
    from public.sales s
    where s.business_id = p_business
      and s.counts_as_revenue
      and s.occurred_at >= (p_from::timestamp at time zone 'Asia/Singapore')
      and s.occurred_at < ((p_to + 1)::timestamp at time zone 'Asia/Singapore')
      and (p_branch is null or s.branch_id = p_branch)
    group by 1
  ) r using (sale_day);

  if v_clients_available then
  select jsonb_build_object(
    'female', count(*) filter (where c.gender = 'female'),
    'male', count(*) filter (where c.gender = 'male'),
    'other', count(*) filter (where c.gender = 'other'),
    'unknown', count(*) filter (where c.gender is null)
  )
  into v_gender
  from public.clients c
  where c.business_id = p_business;

  select jsonb_build_object(
    'under_25', count(*) filter (where c.birth_date is not null and extract(year from age((timezone('Asia/Singapore', now()))::date, c.birth_date)) < 25),
    'age_25_34', count(*) filter (where c.birth_date is not null and extract(year from age((timezone('Asia/Singapore', now()))::date, c.birth_date)) between 25 and 34),
    'age_35_44', count(*) filter (where c.birth_date is not null and extract(year from age((timezone('Asia/Singapore', now()))::date, c.birth_date)) between 35 and 44),
    'age_45_54', count(*) filter (where c.birth_date is not null and extract(year from age((timezone('Asia/Singapore', now()))::date, c.birth_date)) between 45 and 54),
    'age_55_plus', count(*) filter (where c.birth_date is not null and extract(year from age((timezone('Asia/Singapore', now()))::date, c.birth_date)) >= 55),
    'unknown', count(*) filter (where c.birth_date is null)
  )
  into v_age
  from public.clients c
  where c.business_id = p_business;
  else
    v_gender := null;
    v_age := null;
  end if;

  return v_kpis || jsonb_build_object(
    'visits_by_weekday', v_weekdays,
    'revenue_by_day', v_revenue_by_day,
    'gender_counts', v_gender,
    'age_counts', v_age,
    'availability', jsonb_build_object(
      'sales', true,
      'clients', v_clients_available,
      'loyalty', v_loyalty_available,
      'credit_liability', v_credit_liability_available
    ),
    'scope', jsonb_build_object(
      'timezone', 'Asia/Singapore',
      'from', p_from,
      'to', p_to,
      'branch_id', p_branch,
      'visits', 'selected_period_and_branch_valid_originals',
      'revenue', 'selected_period_and_branch_signed_ledger',
      'unique_customers', 'selected_period_and_branch_customer_records_with_valid_visits',
      'new_customers', case when v_clients_available then 'business_wide_records_added_in_selected_period' else 'unavailable_without_complete_clients_scope' end,
      'points_issued', case
        when not v_loyalty_available then 'unavailable_without_complete_loyalty_scope'
        when p_branch is null then 'business_wide_gross_earn_in_selected_period'
        else 'selected_branch_sale_linked_gross_earn_in_selected_period'
      end,
      'credit_liability', case when v_credit_liability_available
        then 'business_wide_current_signed_credit_ledger_with_complete_business_sales_read'
        else 'unavailable_without_complete_business_sales_scope' end,
      'age_counts', case when v_clients_available then 'business_wide_current' else 'unavailable_without_complete_clients_scope' end
    )
  );
end;
$$;

--
-- Name: get_dashboard_summary_v155(uuid, date, date, text, uuid[], uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_dashboard_summary_v155(p_business uuid, p_from date, p_to date, p_scope_mode text DEFAULT 'current'::text, p_branch_ids uuid[] DEFAULT ARRAY[]::uuid[], p_operational_branch uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_kpis jsonb;
  v_weekdays jsonb;
  v_revenue_by_day jsonb;
  v_gender jsonb;
  v_age jsonb;
  v_scope_ids uuid[];
  v_scope_label text;
  v_mode text := coalesce(nullif(btrim(p_scope_mode),''),'current');
  v_sales_available boolean;
  v_clients_available boolean;
  v_loyalty_available boolean;
begin
  if auth.uid() is null or not app.has_perm(p_business,'view_sales') then
    raise exception 'you do not have permission to view this dashboard'
      using errcode='42501';
  end if;
  if p_from is null or p_to is null or p_from > p_to then
    raise exception 'a valid report date range is required' using errcode='22007';
  end if;
  if p_to - p_from > 1826 then
    raise exception 'report date range cannot exceed 1827 days'
      using errcode='22023';
  end if;

  select coalesce(array_agg(scope.branch_id order by scope.branch_name),array[]::uuid[])
    into v_scope_ids
  from app.resolve_reporting_branch_scope_v155(
    p_business,v_mode,p_branch_ids,p_operational_branch
  ) scope;
  if cardinality(v_scope_ids) = 0 then
    raise exception 'no_authorised_reporting_branches' using errcode='42501';
  end if;
  v_scope_label := app.reporting_scope_label_v155(
    p_business,v_mode,p_branch_ids,p_operational_branch
  );

  v_sales_available := app.metric_module_scope_available_v145(
    p_business, case when cardinality(v_scope_ids)=1 then v_scope_ids[1] else null end, 'sales'
  );
  v_clients_available := app.metric_module_scope_available_v145(
    p_business, null, 'clients'
  );
  v_loyalty_available := app.metric_module_scope_available_v145(
    p_business, case when cardinality(v_scope_ids)=1 then v_scope_ids[1] else null end, 'loyalty'
  );

  with scoped_sales as (
    select s.*
    from public.sales s
    where s.business_id = p_business
      and s.occurred_at >= (p_from::timestamp at time zone 'Asia/Singapore')
      and s.occurred_at < ((p_to + 1)::timestamp at time zone 'Asia/Singapore')
      and s.branch_id = any(v_scope_ids)
  ), valid_visits as (
    select s.*
    from scoped_sales s
    where s.counts_as_visit
      and s.reversal_of is null
      and not exists (
        select 1 from public.sales r
        where r.business_id = s.business_id
          and r.reversal_of = s.id
      )
  ), repeaters as (
    select s.client_id
    from valid_visits s
    where s.client_id is not null
    group by s.client_id
    having count(*) >= 2
  )
  select jsonb_build_object(
    'visits', (select count(*) from valid_visits),
    'revenue_cents', coalesce((select sum(s.amount_cents) from scoped_sales s where s.counts_as_revenue),0),
    'unique_customers', (select count(distinct s.client_id) from valid_visits s where s.client_id is not null),
    'repeat_customers', (select count(*) from repeaters),
    'repeat_customer_percentage', case when (select count(distinct s.client_id) from valid_visits s where s.client_id is not null) = 0 then null
      else round(((select count(*) from repeaters)::numeric / nullif((select count(distinct s.client_id) from valid_visits s where s.client_id is not null),0)::numeric) * 100, 1) end
  ) into v_kpis;

  v_kpis := v_kpis || jsonb_build_object(
    'new_customers', case when v_clients_available then (
      select count(*) from public.clients c
      where c.business_id = p_business
        and c.created_at >= (p_from::timestamp at time zone 'Asia/Singapore')
        and c.created_at < ((p_to + 1)::timestamp at time zone 'Asia/Singapore')
    ) else null end,
    'points_issued', case when v_loyalty_available then (
      select coalesce(sum(pl.points),0)
      from public.points_ledger pl
      left join public.sales ps
        on ps.id = pl.sale_id
       and ps.business_id = pl.business_id
      where pl.business_id = p_business
        and pl.entry_type = 'earn'
        and pl.created_at >= (p_from::timestamp at time zone 'Asia/Singapore')
        and pl.created_at < ((p_to + 1)::timestamp at time zone 'Asia/Singapore')
        and ps.branch_id = any(v_scope_ids)
    ) else null end
  );

  with valid_visits as (
    select s.*
    from public.sales s
    where s.business_id = p_business
      and s.counts_as_visit
      and s.reversal_of is null
      and s.occurred_at >= (p_from::timestamp at time zone 'Asia/Singapore')
      and s.occurred_at < ((p_to + 1)::timestamp at time zone 'Asia/Singapore')
      and s.branch_id = any(v_scope_ids)
      and not exists (
        select 1 from public.sales r
        where r.business_id = s.business_id
          and r.reversal_of = s.id
      )
  )
  select coalesce(jsonb_agg(coalesce(w.visits,0) order by d.day_no),'[]'::jsonb)
  into v_weekdays
  from generate_series(1,7) d(day_no)
  left join (
    select extract(isodow from s.occurred_at at time zone 'Asia/Singapore')::int as day_no,
           count(*) as visits
    from valid_visits s
    group by 1
  ) w using (day_no);

  select coalesce(jsonb_agg(jsonb_build_object(
    'day',d.sale_day,
    'amount_cents',coalesce(r.amount_cents,0)
  ) order by d.sale_day),'[]'::jsonb)
  into v_revenue_by_day
  from generate_series(p_from::timestamp,p_to::timestamp,interval '1 day') d0(day_value)
  cross join lateral (select d0.day_value::date as sale_day) d
  left join (
    select (s.occurred_at at time zone 'Asia/Singapore')::date as sale_day,
           sum(s.amount_cents) as amount_cents
    from public.sales s
    where s.business_id = p_business
      and s.counts_as_revenue
      and s.occurred_at >= (p_from::timestamp at time zone 'Asia/Singapore')
      and s.occurred_at < ((p_to + 1)::timestamp at time zone 'Asia/Singapore')
      and s.branch_id = any(v_scope_ids)
    group by 1
  ) r using (sale_day);

  if v_clients_available then
    with scoped_customers as (
      select distinct s.client_id
      from public.sales s
      where s.business_id = p_business
        and s.client_id is not null
        and s.counts_as_visit
        and s.reversal_of is null
        and s.branch_id = any(v_scope_ids)
        and not exists(
          select 1 from public.sales reversal
          where reversal.business_id=s.business_id
            and reversal.reversal_of=s.id
        )
    )
    select jsonb_build_object(
      'female', count(*) filter (where c.gender='female'),
      'male', count(*) filter (where c.gender='male'),
      'other', count(*) filter (where c.gender='other'),
      'unknown', count(*) filter (where c.gender is null)
    )
    into v_gender
    from public.clients c
    join scoped_customers scoped on scoped.client_id = c.id
    where c.business_id = p_business;

    with scoped_customers as (
      select distinct s.client_id
      from public.sales s
      where s.business_id = p_business
        and s.client_id is not null
        and s.counts_as_visit
        and s.reversal_of is null
        and s.branch_id = any(v_scope_ids)
        and not exists(
          select 1 from public.sales reversal
          where reversal.business_id=s.business_id
            and reversal.reversal_of=s.id
        )
    )
    select jsonb_build_object(
      'under_25', count(*) filter (where c.birth_date is not null and extract(year from age((timezone('Asia/Singapore',now()))::date,c.birth_date)) < 25),
      'age_25_34', count(*) filter (where c.birth_date is not null and extract(year from age((timezone('Asia/Singapore',now()))::date,c.birth_date)) between 25 and 34),
      'age_35_44', count(*) filter (where c.birth_date is not null and extract(year from age((timezone('Asia/Singapore',now()))::date,c.birth_date)) between 35 and 44),
      'age_45_54', count(*) filter (where c.birth_date is not null and extract(year from age((timezone('Asia/Singapore',now()))::date,c.birth_date)) between 45 and 54),
      'age_55_plus', count(*) filter (where c.birth_date is not null and extract(year from age((timezone('Asia/Singapore',now()))::date,c.birth_date)) >= 55),
      'unknown', count(*) filter (where c.birth_date is null)
    )
    into v_age
    from public.clients c
    join scoped_customers scoped on scoped.client_id = c.id
    where c.business_id = p_business;
  else
    v_gender := null;
    v_age := null;
  end if;

  return v_kpis || jsonb_build_object(
    'visits_by_weekday',v_weekdays,
    'revenue_by_day',v_revenue_by_day,
    'gender_counts',v_gender,
    'age_counts',v_age,
    'availability',jsonb_build_object(
      'sales',v_sales_available,
      'clients',v_clients_available,
      'loyalty',v_loyalty_available
    ),
    'scope',jsonb_build_object(
      'mode',v_mode,
      'label',v_scope_label,
      'branch_ids',to_jsonb(v_scope_ids),
      'operational_branch_id',p_operational_branch,
      'timezone','Asia/Singapore',
      'from',p_from,
      'to',p_to,
      'revenue','selected_reporting_scope_signed_ledger',
      'visits','selected_reporting_scope_valid_originals',
      'unique_customers','deduplicated canonical customer IDs with valid visits in scope',
      'repeat_customer_percentage','recalculated from combined source records; percentages are not summed',
      'new_customers','business_wide_records_added_in_selected_period'
    )
  );
end
$$;

--
-- Name: get_effective_sector_policy_v109(uuid, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_effective_sector_policy_v109(p_business uuid, p_policy_key text DEFAULT 'lapse_detection'::text, p_as_of timestamp with time zone DEFAULT statement_timestamp()) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_sector text;
  v_base public.sector_policy_versions_v109%rowtype;
  v_override public.business_sector_policy_overrides_v109%rowtype;
begin
  perform app.v109_require_feature();
  perform app.v109_require_finance_scope(p_business,null);
  if p_as_of is null then
    raise exception 'as-of is required' using errcode='22023';
  end if;
  select lower(b.industry) into v_sector
  from public.businesses b where b.id=p_business;
  if v_sector is null then raise exception 'business not found';end if;
  select * into v_base
  from public.sector_policy_versions_v109 p
  where p.sector_key=v_sector and p.policy_key=p_policy_key
    and p.status='published' and p.effective_from<=p_as_of
    and (p.effective_to is null or p.effective_to>p_as_of)
  order by p.version_no desc limit 1;
  if not found then
    select * into v_base
    from public.sector_policy_versions_v109 p
    where p.sector_key='other' and p.policy_key=p_policy_key
      and p.status='published' and p.effective_from<=p_as_of
      and (p.effective_to is null or p.effective_to>p_as_of)
    order by p.version_no desc limit 1;
  end if;
  if not found then raise exception 'no effective sector policy';end if;
  select * into v_override
  from public.business_sector_policy_overrides_v109 o
  where o.business_id=p_business and o.policy_key=p_policy_key
    and o.base_policy_id=v_base.id and o.effective_from<=p_as_of
    and (o.effective_to is null or o.effective_to>p_as_of)
  order by o.version_no desc limit 1;
  return jsonb_build_object(
    'contract_version','effective_sector_policy_v109',
    'business_id',p_business,
    'requested_sector',v_sector,
    'resolved_sector',v_base.sector_key,
    'used_fallback_sector',v_base.sector_key<>v_sector,
    'policy_key',v_base.policy_key,
    'base_policy',jsonb_build_object(
      'id',v_base.id,'version_no',v_base.version_no,
      'effective_from',v_base.effective_from,'effective_to',v_base.effective_to,
      'evidence_basis',v_base.evidence_basis,'parameters',v_base.parameters,
      'fallback_policy',v_base.fallback_policy,
      'suppression_rules',v_base.suppression_rules,
      'limitations',v_base.limitations
    ),
    'owner_override',case when v_override.id is null then 'null'::jsonb
      else jsonb_build_object(
        'id',v_override.id,'version_no',v_override.version_no,
        'parameters',v_override.override_parameters,
        'reason',v_override.reason,'effective_from',v_override.effective_from,
        'effective_to',v_override.effective_to,'created_by',v_override.created_by
      ) end,
    'effective_parameters',v_base.parameters
      ||coalesce(v_override.override_parameters,'{}'::jsonb),
    'universal_churn_number',null,
    'requires_local_evidence',true
  );
end $$;

--
-- Name: get_growth_daily_briefing_v108(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_growth_daily_briefing_v108(p_business uuid, p_branch uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_recommendation public.growth_recommendations_v108%rowtype;
  v_result public.growth_execution_results_v108%rowtype;
  v_execution public.growth_executions_v108%rowtype;
  v_live_measurement jsonb;
begin
  if auth.uid() is null or (
     not app.is_super_admin()
     and (
       not app.has_perm(p_business, 'view_finance')
       or not app.can_module_read(p_business, 'retention')
     )
  ) then
    raise exception 'finance and retention access required' using errcode = '42501';
  end if;
  if not app.can_see_branch(p_business, p_branch) then
    raise exception 'branch is outside actor scope' using errcode = '42501';
  end if;

  select * into v_recommendation
  from public.growth_recommendations_v108 r
  where r.business_id = p_business
    and r.branch_id is not distinct from p_branch
  order by r.generated_at desc, r.id desc limit 1;

  select result_row.* into v_result
  from public.growth_execution_results_v108 result_row
  join public.growth_executions_v108 result_execution
    on result_execution.id = result_row.execution_id
   and result_execution.business_id = result_row.business_id
  where result_row.business_id = p_business
    and result_execution.branch_id is not distinct from p_branch
  order by result_row.finalized_at desc, result_row.id desc limit 1;

  select execution_row.* into v_execution
  from public.growth_executions_v108 execution_row
  where execution_row.business_id = p_business
    and execution_row.branch_id is not distinct from p_branch
    and execution_row.status = 'running'
  order by execution_row.started_at desc, execution_row.id desc
  limit 1;

  if v_execution.id is not null then
    v_live_measurement := public.get_growth_execution_result_v108(v_execution.id);
  end if;

  return jsonb_build_object(
    'contract_version', 'growth_daily_briefing_v108',
    'generated_at', coalesce(v_recommendation.generated_at, statement_timestamp()),
    'as_of', v_recommendation.data_freshness_at,
    'data_status', case
      when v_recommendation.id is null then 'not_computed'
      when v_recommendation.status = 'suppressed' then 'insufficient_evidence'
      when v_recommendation.valid_until <= statement_timestamp() then 'stale'
      else 'ready'
    end,
    'coverage', coalesce(v_recommendation.data_coverage, '{}'::jsonb),
    'top_action', case
      when v_recommendation.id is null
        or v_recommendation.status <> 'presented'
        or v_recommendation.valid_until <= statement_timestamp()
      then null
      else jsonb_build_object(
        'recommendation_id', v_recommendation.id,
        'type', v_recommendation.recommendation_type,
        'title', 'Bring back customers whose usual visit is overdue',
        'finding', v_recommendation.finding,
        'evidence', v_recommendation.supporting_evidence,
        'observation_window', jsonb_build_object(
          'start', v_recommendation.observation_start,
          'end', v_recommendation.observation_end
        ),
        'comparison_window', jsonb_build_object(
          'start', v_recommendation.comparison_start,
          'end', v_recommendation.comparison_end
        ),
        'audience', jsonb_build_object(
          'eligible', v_recommendation.audience_size,
          'excluded', v_recommendation.excluded_size,
          'treatment', v_recommendation.audience_size
            - floor(v_recommendation.audience_size * v_recommendation.holdout_percent / 100.0)::integer,
          'holdout', floor(
            v_recommendation.audience_size * v_recommendation.holdout_percent / 100.0
          )::integer
        ),
        'expected_incremental_revenue', v_recommendation.expected_incremental_revenue,
        'estimated_cost_cents', v_recommendation.estimated_cost_cents,
        'confidence', v_recommendation.confidence,
        'action', v_recommendation.recommended_action
          || v_recommendation.recommended_offer
          || jsonb_build_object(
            'offer',
            concat(
              coalesce(v_recommendation.recommended_offer ->> 'currency', 'UNSUPPORTED'),
              ' ',
              to_char(
                coalesce((v_recommendation.recommended_offer ->> 'value_cents')::bigint, 0)
                  / 100.0,
                'FM999999990.00'
              ),
              ' in-store credit on one eligible return visit'
            )
          )
          || jsonb_build_object('expires_at', v_recommendation.valid_until),
        'measurement', jsonb_build_object(
          'method', 'randomized_intent_to_treat_holdout',
          'attribution_days', v_recommendation.attribution_window_days,
          'minimum_sample', (v_recommendation.stop_conditions ->> 'minimum_arm_size')::integer,
          'status', 'not_started'
        ),
        'status', v_recommendation.status
      )
    end,
    'suppressions', coalesce(v_recommendation.suppression_reasons, '[]'::jsonb),
    'active_execution', case when v_execution.id is null then null else
      jsonb_build_object(
        'execution_id', v_execution.id,
        'recommendation_id', v_execution.recommendation_id,
        'branch_id', v_execution.branch_id,
        'currency', v_execution.currency,
        'status', v_execution.status,
        'started_at', v_execution.started_at,
        'ends_at', v_execution.ends_at,
        'governed_copy', v_execution.governed_copy,
        'delivery', jsonb_build_object(
          'queued', (
            select count(*) from public.growth_deliveries_v108 delivery
            where delivery.execution_id = v_execution.id
              and delivery.delivery_status = 'queued'
          ),
          'scheduled', (
            select count(*) from public.growth_deliveries_v108 delivery
            where delivery.execution_id = v_execution.id
              and delivery.delivery_status = 'scheduled'
          ),
          'delivering', (
            select count(*) from public.growth_deliveries_v108 delivery
            where delivery.execution_id = v_execution.id
              and delivery.delivery_status = 'delivering'
          ),
          'delivered', (
            select count(*) from public.growth_deliveries_v108 delivery
            where delivery.execution_id = v_execution.id
              and delivery.delivery_status = 'delivered'
          ),
          'held_out', (
            select count(*) from public.growth_deliveries_v108 delivery
            where delivery.execution_id = v_execution.id
              and delivery.delivery_status = 'held_out'
          ),
          'suppressed', (
            select count(*) from public.growth_deliveries_v108 delivery
            where delivery.execution_id = v_execution.id
              and delivery.delivery_status = 'suppressed'
          ),
          'failed', (
            select count(*) from public.growth_deliveries_v108 delivery
            where delivery.execution_id = v_execution.id
              and delivery.delivery_status = 'failed'
          ),
          'cancelled', (
            select count(*) from public.growth_deliveries_v108 delivery
            where delivery.execution_id = v_execution.id
              and delivery.delivery_status = 'cancelled'
          )
        ),
        'arms', jsonb_build_object(
          'treatment', (
            select count(*) from public.growth_execution_members_v108 member
            where member.execution_id = v_execution.id
              and member.assignment = 'treatment'
          ),
          'holdout', (
            select count(*) from public.growth_execution_members_v108 member
            where member.execution_id = v_execution.id
              and member.assignment = 'holdout'
          )
        ),
        'provisional_measurement', v_live_measurement
      )
    end,
    'latest_completed_action', case when v_result.id is null then null else
      jsonb_build_object(
        'execution_id', v_result.execution_id,
        'status', v_result.result_status,
        'result', v_result.result,
        'prediction', v_result.prediction,
        'calibration', v_result.calibration,
        'finalized_at', v_result.finalized_at
      )
    end
  );
end $$;

--
-- Name: get_growth_delivery_status_v110(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_growth_delivery_status_v110(p_business uuid, p_execution uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_execution public.growth_executions_v108%rowtype;
begin
  if auth.uid() is null or (
    not app.is_super_admin()
    and (
      not app.has_perm(p_business, 'view_finance')
      or not app.can_module_read(p_business, 'retention')
    )
  ) then
    raise exception 'finance and retention access required' using errcode = '42501';
  end if;
  select * into strict v_execution
  from public.growth_executions_v108
  where id = p_execution and business_id = p_business;
  if not app.can_see_branch(v_execution.business_id, v_execution.branch_id) then
    raise exception 'execution branch is outside actor scope' using errcode = '42501';
  end if;
  return jsonb_build_object(
    'contract_version', 'growth_delivery_lifecycle_v112',
    'execution_id', v_execution.id,
    'business_id', v_execution.business_id,
    'branch_id', v_execution.branch_id,
    'counts', (
      select coalesce(
        jsonb_object_agg(status_rows.lifecycle_status, status_rows.n),
        '{}'::jsonb
      )
      from (
        select dispatch.lifecycle_status, count(*) as n
        from public.growth_delivery_dispatches_v110 dispatch
        where dispatch.execution_id = p_execution
        group by dispatch.lifecycle_status
      ) status_rows
    ),
    'deliveries', coalesce((
      select jsonb_agg(jsonb_build_object(
        'dispatch_id', dispatch.id,
        'delivery_id', dispatch.delivery_id,
        'status', dispatch.lifecycle_status,
        'provider', dispatch.provider,
        'scheduled_for', dispatch.scheduled_for,
        'attempt_count', dispatch.attempt_count,
        'delivered_at', dispatch.delivered_at,
        'failure_code', dispatch.failure_code,
        'cancelled_at', dispatch.cancelled_at,
        'updated_at', dispatch.updated_at,
        'entitlement_status', case
          when latest_event.detail ->> 'entitlement_suppressed' = 'true'
            then 'suppressed'
          when entitlement.id is not null then entitlement.status
          else null
        end,
        'entitlement_suppressed',
          latest_event.detail ->> 'entitlement_suppressed' = 'true',
        'suppression_reason', case
          when latest_event.detail ->> 'entitlement_suppressed' = 'true'
           and latest_event.reason_code in (
             'feature_disabled', 'module_disabled', 'execution_cancelled',
             'execution_expired', 'branch_unavailable', 'link_unavailable',
             'consent_withdrawn'
           )
            then latest_event.reason_code
          else null
        end
      ) order by dispatch.created_at, dispatch.id)
      from public.growth_delivery_dispatches_v110 dispatch
      left join public.growth_entitlements_v108 entitlement
        on entitlement.delivery_id = dispatch.delivery_id
      left join lateral (
        select event.reason_code, event.detail
        from public.growth_delivery_state_events_v110 event
        where event.dispatch_id = dispatch.id
          and event.to_status = dispatch.lifecycle_status
        order by event.occurred_at desc, event.id desc
        limit 1
      ) latest_event on true
      where dispatch.execution_id = p_execution
    ), '[]'::jsonb)
  );
end $$;

--
-- Name: FUNCTION get_growth_delivery_status_v110(p_business uuid, p_execution uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_growth_delivery_status_v110(p_business uuid, p_execution uuid) IS 'Owner-scoped delivery truth including whether a delivered message produced an entitlement or was safely suppressed after eligibility changed.';

--
-- Name: get_growth_execution_result_v108(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_growth_execution_result_v108(p_execution uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  -- Freeze one live reporting cutoff for the entire projection.
  v_as_of timestamptz := clock_timestamp();
begin
  return app.get_growth_execution_result_at_v108(p_execution, v_as_of);
end $$;

--
-- Name: get_join_page(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_join_page(p_slug text) RETURNS json
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  select json_build_object('name', b.name, 'brand_color', b.brand_color, 'slug', b.slug)
  from public.businesses b where b.slug = p_slug and b.join_enabled;
$$;

--
-- Name: get_legacy_acknowledgements(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_legacy_acknowledgements(p_business uuid, p_asset text DEFAULT 'stored_value'::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_asset text := coalesce(p_asset, 'stored_value');
  v_current bigint;
  v_history jsonb;
begin
  if not (app.is_salon_owner(p_business) or app.is_super_admin()) then
    raise exception 'not permitted to view legacy acknowledgements for this business' using errcode = '42501';
  end if;
  select acknowledged_cents into v_current from public.sv_legacy_acknowledgements
   where business_id = p_business and asset = v_asset
   order by seq desc limit 1;
  select coalesce(jsonb_agg(jsonb_build_object(
      'acknowledgement_id', a.id, 'acknowledged_cents', a.acknowledged_cents,
      'reason', a.reason, 'actor', a.actor, 'created_at', a.created_at)
      order by a.seq desc), '[]'::jsonb)
    into v_history
    from public.sv_legacy_acknowledgements a
   where a.business_id = p_business and a.asset = v_asset;
  return jsonb_build_object(
    'business_id', p_business, 'asset', v_asset,
    'current_acknowledged_cents', v_current, 'history', v_history);
end $$;

--
-- Name: get_legacy_value_inventory(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_legacy_value_inventory(p_business uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_result jsonb;
begin
  if p_business is null then
    if not app.is_super_admin() then
      raise exception 'super-admin only for the platform-wide legacy value inventory' using errcode = '42501';
    end if;
  else
    if not (app.is_salon_owner(p_business) or app.is_super_admin()) then
      raise exception 'not permitted to view legacy value inventory for this business' using errcode = '42501';
    end if;
  end if;

  select coalesce(jsonb_agg(row order by (row->>'business_name')), '[]'::jsonb) into v_result
  from (
    select jsonb_build_object(
      'business_id', b.id,
      'business_name', b.name,
      'is_synthetic', b.is_synthetic,
      'authority_state', coalesce(sa.state, 'unbuilt'),
      'classification', cls.classification,
      'classification_reason', cls.reason,
      'latest_acknowledged_cents', ack.acknowledged_cents,
      'gift_card_total_cents', coalesce(gc.total, 0),
      'gift_cards', coalesce(gc.rows, '[]'::jsonb),
      'store_credit_total_cents', coalesce(cr.total, 0),
      'store_credit', coalesce(cr.rows, '[]'::jsonb)
    ) as row
    from public.businesses b
    left join lateral (
      select a.state from public.sv_authority a
       where a.business_id = b.id and a.asset = 'stored_value') sa on true
    left join lateral (
      select c.classification, c.reason from public.sv_legacy_classifications c
       where c.business_id = b.id order by c.seq desc limit 1) cls on true
    left join lateral (
      select k.acknowledged_cents from public.sv_legacy_acknowledgements k
       where k.business_id = b.id and k.asset = 'stored_value'
       order by k.seq desc limit 1) ack on true
    left join lateral (
      select sum(g.balance_cents)::bigint as total,
             jsonb_agg(jsonb_build_object(
               'gift_card_id', g.id, 'code_suffix', right(g.code, 4), 'cents', g.balance_cents,
               'status', g.status,
               'age_days', floor(extract(epoch from (now() - g.created_at)) / 86400)::int)
               order by g.created_at, g.id) as rows
        from public.gift_cards g
       where g.business_id = b.id and g.balance_cents <> 0) gc on true
    left join lateral (
      select sum(t.bal)::bigint as total,
             jsonb_agg(jsonb_build_object(
               'client_id', t.client_id, 'cents', t.bal,
               'age_days', floor(extract(epoch from (now() - t.first_at)) / 86400)::int)
               order by t.client_id) as rows
        from (select cl.client_id, sum(cl.amount_cents) as bal, min(cl.created_at) as first_at
                from public.credit_ledger cl
               where cl.business_id = b.id
               group by cl.client_id
              having sum(cl.amount_cents) <> 0) t) cr on true
    where p_business is null or b.id = p_business
  ) s;
  return v_result;
end $$;

--
-- Name: get_loyalty_reward_draft(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_loyalty_reward_draft(p_config_version uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_header public.firm_config_versions%rowtype;
  v_payload jsonb;
begin
  select * into v_header
    from public.firm_config_versions
   where id = p_config_version
   for share;

  if not found or not app.is_salon_owner(v_header.business_id) then
    raise exception 'owner only' using errcode = '42501';
  end if;
  if v_header.status <> 'draft' then
    raise exception 'only draft reward configurations can be read through this endpoint'
      using errcode = '42501';
  end if;

  perform 1
    from public.businesses
   where id = v_header.business_id
   for share;

  select jsonb_build_object(
    'config_version_id', v_header.id,
    'business_id', v_header.business_id,
    'version_no', v_header.version_no,
    'status', v_header.status,
    'source', v_header.source,
    'snapshot_hash', v_header.snapshot_hash,
    'program', (
      select jsonb_build_object(
        'config_version_id', lp.config_version_id,
        'business_id', lp.business_id,
        'kind', lp.kind,
        'loyalty_model', lp.loyalty_model,
        'active', lp.active,
        'earn_points_per_dollar', lp.earn_points_per_dollar,
        'redeem_points', lp.redeem_points,
        'reward_credit_cents', lp.reward_credit_cents,
        'stamp_target', lp.stamp_target,
        'stamp_per_cents', lp.stamp_per_cents,
        'tier_basis', lp.tier_basis,
        'expiry_mode', lp.expiry_mode,
        'expiry_days', lp.expiry_days,
        'configuration_status', 'draft'
      )
        from public.loyalty_program_versions lp
       where lp.config_version_id = v_header.id
         and lp.business_id = v_header.business_id
    ),
    'tiers', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', tv.id,
        'tier_id', tv.tier_id,
        'config_version_id', tv.config_version_id,
        'business_id', tv.business_id,
        'name', tv.name,
        'threshold', tv.threshold,
        'points_multiplier', tv.points_multiplier,
        'perk_note', tv.perk_note,
        'sort', tv.sort,
        'active', tv.active,
        'created_at', tv.created_at
      ) order by tv.threshold, tv.sort, tv.tier_id)
        from public.loyalty_tier_versions tv
       where tv.config_version_id = v_header.id
         and tv.business_id = v_header.business_id
    ), '[]'::jsonb),
    'rewards', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', rv.reward_id,
        'reward_id', rv.reward_id,
        'reward_version_id', rv.id,
        'business_id', rv.business_id,
        'config_version_id', rv.config_version_id,
        'name', rv.internal_name,
        'internal_name', rv.internal_name,
        'customer_name', rv.customer_name,
        'description', rv.description,
        'fulfillment_kind', rv.fulfillment_kind,
        'taxonomy_label', rv.taxonomy_label,
        'cost_points', rv.cost_points,
        'credit_cents', rv.credit_cents,
        'estimated_cost_cents', rv.estimated_cost_cents,
        'active', rv.active,
        'sort', rv.sort,
        'claim_available_from', rv.claim_available_from,
        'claim_available_until', rv.claim_available_until,
        'entitlement_expiry_days', rv.entitlement_expiry_days,
        'instructions', rv.instructions,
        'terms', rv.terms,
        'image_ref', rv.image_ref,
        'requires_purchase', coalesce(rv.requires_purchase, false),
        'min_tier_id', rv.min_tier_id,
        'min_tier_threshold', rv.min_tier_threshold,
        'usage_limit', rv.usage_limit,
        'created_at', rv.created_at,
        'eligibility', jsonb_build_object(
          'branches', coalesce((
            select jsonb_agg(e.branch_id order by e.branch_id)
              from public.loyalty_reward_branches e
             where e.reward_version_id = rv.id
               and e.reward_id = rv.reward_id
               and e.business_id = rv.business_id
          ), '[]'::jsonb),
          'services', coalesce((
            select jsonb_agg(e.service_id order by e.service_id)
              from public.loyalty_reward_services e
             where e.reward_version_id = rv.id
               and e.reward_id = rv.reward_id
               and e.business_id = rv.business_id
          ), '[]'::jsonb),
          'products', coalesce((
            select jsonb_agg(e.product_id order by e.product_id)
              from public.loyalty_reward_products e
             where e.reward_version_id = rv.id
               and e.reward_id = rv.reward_id
               and e.business_id = rv.business_id
          ), '[]'::jsonb)
        )
      ) order by rv.sort, rv.created_at, rv.reward_id)
        from public.loyalty_reward_versions rv
       where rv.config_version_id = v_header.id
         and rv.business_id = v_header.business_id
    ), '[]'::jsonb)
  ) into v_payload;

  return v_payload;
end $$;

--
-- Name: get_merchant_payment_status_v142(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_merchant_payment_status_v142(p_business uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_account public.merchant_payment_accounts_v142%rowtype;
begin
  if auth.uid() is null or not exists (
    select 1 from public.staff s
     where s.business_id = p_business and s.user_id = auth.uid() and s.active
  ) then
    raise exception 'merchant payment status access denied' using errcode = '42501';
  end if;
  select * into v_account from public.merchant_payment_accounts_v142
   where business_id = p_business;
  if not found then
    return jsonb_build_object('business_id',p_business,'status','not_set_up',
      'paynow_ready',false,'requirements_due_count',0);
  end if;
  return jsonb_build_object(
    'business_id', p_business,
    'status', case
      when v_account.charges_enabled and v_account.payouts_enabled
       and v_account.details_submitted and v_account.paynow_capability = 'active' then 'ready'
      when v_account.disabled_reason is not null or v_account.paynow_capability = 'restricted' then 'restricted'
      else 'more_information_needed' end,
    'paynow_ready', v_account.charges_enabled and v_account.payouts_enabled
      and v_account.details_submitted and v_account.paynow_capability = 'active',
    'charges_enabled', v_account.charges_enabled,
    'payouts_enabled', v_account.payouts_enabled,
    'details_submitted', v_account.details_submitted,
    'paynow_capability', v_account.paynow_capability,
    'livemode', v_account.livemode,
    'requirements_due_count', jsonb_array_length(v_account.requirements_currently_due),
    'updated_at', v_account.updated_at
  );
end $$;

--
-- Name: get_my_modules(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_modules(p_business uuid) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_perms jsonb;
begin
  v_perms := app.staff_module_perms_at_v115(p_business,null);
  return json_build_object(
    'modules', to_json(coalesce(
      (select array_agg(k order by k)
         from jsonb_object_keys(v_perms) as keys(k)),
      array[]::text[]
    )),
    'module_perms', v_perms,
    'role', (select s.role from public.staff s
              where s.business_id = p_business and s.user_id = auth.uid() and s.active
              order by case when s.role = 'owner' then 0 else 1 end, s.created_at limit 1),
    'capabilities', to_json(coalesce(
      (select s.capabilities from public.staff s
        where s.business_id = p_business and s.user_id = auth.uid() and s.active
        order by case when s.role = 'owner' then 0 else 1 end, s.created_at limit 1),
      array[]::text[]
    )),
    'is_super_admin', app.is_super_admin()
  );
end
$$;

--
-- Name: FUNCTION get_my_modules(p_business uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_my_modules(p_business uuid) IS 'v404: also returns the staff row''s capabilities array, so the workspace can decide whether to draw the manual-redemption control without a second round trip. v233: resolves the module set once rather than twice.';

--
-- Name: get_my_modules_at_v115(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_modules_at_v115(p_business uuid, p_branch uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  select jsonb_build_object(
    'business_id',p_business,
    'branch_id',p_branch,
    'modules',coalesce((
      select jsonb_agg(entry.key order by entry.key)
      from jsonb_each_text(
        app.staff_module_perms_at_v115(p_business,p_branch)
      ) entry
    ),'[]'::jsonb),
    'module_perms',app.staff_module_perms_at_v115(p_business,p_branch),
    'role',(
      select staff_row.role
      from public.staff staff_row
      where staff_row.business_id=p_business
        and staff_row.user_id=auth.uid()
        and staff_row.active
      order by case when staff_row.role='owner' then 0 else 1 end,
        staff_row.created_at,staff_row.id
      limit 1
    ),
    'is_super_admin',app.is_super_admin()
  )
$$;

--
-- Name: FUNCTION get_my_modules_at_v115(p_business uuid, p_branch uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_my_modules_at_v115(p_business uuid, p_branch uuid) IS 'v115 authenticated branch-effective module projection for tenant controls; never broadens platform or staff policy.';

--
-- Name: get_my_personas(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_personas() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid:=auth.uid();
  v_staff jsonb:='[]'::jsonb;
  v_customer jsonb:='[]'::jsonb;
  v_default_route text:='#/';
  /* v246: each flag was probed up to four times per call; once is enough. */
  v_identity boolean:=app.platform_feature_enabled('customer_identity');
  v_claims boolean:=app.platform_feature_enabled('customer_claims');
  v_wallet boolean:=app.platform_feature_enabled('customer_wallet');
begin
  if v_actor is null then
    raise exception 'authenticated session required' using errcode='28000';
  end if;
  select coalesce(jsonb_agg(jsonb_build_object(
    'business_id',business.id,
    'business_slug',business.slug,
    'business_name',business.name,
    'role',staff_row.role,
    /* v246: the sorted key list of the resolver's map — the exact expression
       app.staff_modules computes — read from a DIRECT resolver call instead of
       through two language-sql wrapper hops that each replan per invocation. */
    'modules',(
      select coalesce(array_agg(key.k order by key.k),array[]::text[])
      from jsonb_object_keys(
        app.staff_module_perms_at_v115(staff_row.business_id,null)
      ) as key(k)
    ),
    'workspace_access',app.business_workspace_open_v94(business.id),
    'approval_status',control.approval_status,
    'subscription_state',lifecycle.state,
    'workspace_paused',lifecycle.workspace_paused,
    'representative_name',representative.display_name,
    'representative_hotline',representative.hotline_phone
  ) order by business.name,business.slug),'[]'::jsonb)
  into v_staff
  from public.staff staff_row
  join public.businesses business on business.id=staff_row.business_id
  join public.business_workspace_controls_v94 control
    on control.business_id=business.id
  join public.business_subscription_lifecycle_v94 lifecycle
    on lifecycle.business_id=business.id
  left join lateral app.assigned_consultant_v94(business.id) representative
    on true
  where staff_row.user_id=v_actor and staff_row.active;
  if v_identity and v_claims and v_wallet then
    select coalesce(jsonb_agg(jsonb_build_object(
      'business_slug',business.slug,
      'business_name',business.name
    ) order by business.name,business.slug),'[]'::jsonb)
    into v_customer
    from public.customer_identities identity_row
    join public.customer_links link
      on link.identity_id=identity_row.id
      and link.auth_user_id=v_actor and link.state='verified'
    join public.businesses business on business.id=link.business_id
    where identity_row.auth_user_id=v_actor
      and identity_row.status='active';
  end if;
  if jsonb_array_length(v_staff)>0 then
    v_default_route:='#/workspace/'||(v_staff->0->>'business_slug')||'/dashboard';
  elsif jsonb_array_length(v_customer)>0 then
    v_default_route:='#/wallet';
  elsif v_identity then
    v_default_route:='#/claim';
  end if;
  return jsonb_build_object(
    'staff',v_staff,'customer',v_customer,'default_route',v_default_route
  );
end
$$;

--
-- Name: FUNCTION get_my_personas(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_my_personas() IS 'v246: identical payload (staff incl. modules fallback list, customer, default_route), but the module list comes from a direct staff_module_perms_at_v115 call instead of the staff_modules -> staff_module_perms wrapper chain, and the customer feature flags are probed once. Measured on production data: 48.3ms -> 21.2ms mean (15.6ms best), the residual being one genuine resolver evaluation per workspace.';

--
-- Name: get_notifications(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_notifications(p_business uuid, p_limit integer DEFAULT 30) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_result json;
begin
  if not app.is_salon_member(p_business) then raise exception 'not authorized'; end if;
  select json_build_object(
    'unread', (select count(*) from public.notifications where business_id = p_business and read_at is null),
    'items', coalesce((select json_agg(row_to_json(t)) from (
        select id, kind, title, body, ref_table, ref_id, created_at, read_at
        from public.notifications where business_id = p_business
        order by created_at desc
        limit greatest(coalesce(p_limit,30), 1)
      ) t), '[]'::json)
  ) into v_result;
  return v_result;
end $$;

--
-- Name: get_period_economics_v109(uuid, date, date, uuid, bigint, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_period_economics_v109(p_business uuid, p_from date, p_to date, p_branch uuid DEFAULT NULL::uuid, p_investment_cents bigint DEFAULT NULL::bigint, p_investment_reference text DEFAULT NULL::text, p_as_of timestamp with time zone DEFAULT statement_timestamp()) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_sales integer:=0;
  v_covered_sales integer:=0;
  v_sale_lines integer:=0;
  v_covered_sale_lines integer:=0;
  v_ambiguous_sale_lines integer:=0;
  v_revenue bigint:=0;
  v_covered_revenue bigint:=0;
  v_traceable_cogs bigint:=0;
  v_sale_transaction_coverage_bps integer;
  v_sale_revenue_coverage_bps integer;
  v_sale_coverage_passes boolean:=false;
  v_benefits integer:=0;
  v_covered_benefits integer:=0;
  v_benefit_value bigint:=0;
  v_covered_benefit_value bigint:=0;
  v_traceable_benefit_cost bigint:=0;
  v_benefit_coverage_bps integer;
  v_benefit_coverage_passes boolean:=true;
  v_deliveries integer:=0;
  v_covered_deliveries integer:=0;
  v_traceable_delivery_cost bigint:=0;
  v_delivery_coverage_bps integer;
  v_delivery_coverage_passes boolean:=true;
  v_coverage_passes boolean:=false;
  v_gross_profit bigint;
  v_contribution bigint;
  v_growth_investment bigint;
  v_total_investment bigint;
  v_net_return bigint;
  v_roi_bps bigint;
  v_unavailable jsonb:='[]'::jsonb;
  v_currency text;
  v_currency_count integer;
  v_extra_reference text;
begin
  perform app.v109_require_feature();
  perform app.v109_require_finance_scope(p_business,p_branch);
  if p_from is null or p_to is null or p_from>=p_to or p_as_of is null then
    raise exception 'valid half-open local-date period and as-of are required'
      using errcode='22023';
  end if;
  if p_investment_cents is not null and p_investment_cents<0 then
    raise exception 'investment cannot be negative' using errcode='22023';
  end if;
  if p_investment_cents>0
     and length(btrim(coalesce(p_investment_reference,'')))<3 then
    raise exception 'positive additional investment requires a source reference'
      using errcode='22023';
  end if;
  if p_branch is not null and not exists (
    select 1 from public.branches branch_row
    where branch_row.id=p_branch and branch_row.business_id=p_business
  ) then
    raise exception 'branch does not belong to business' using errcode='22023';
  end if;

  select count(distinct contract.currency),min(contract.currency)
  into v_currency_count,v_currency
  from public.sales sale
  cross join lateral app.v106_reporting_contract(
    sale.business_id,sale.branch_id,sale.occurred_at
  ) contract
  where sale.business_id=p_business
    and (p_branch is null or sale.branch_id=p_branch)
    and sale.counts_as_revenue and sale.reversal_of is null
    and sale.created_at<=p_as_of
    and (sale.occurred_at at time zone contract.timezone)::date>=p_from
    and (sale.occurred_at at time zone contract.timezone)::date<p_to;
  if v_currency_count>1 then
    raise exception 'cross-currency reporting periods are not supported'
      using errcode='22023';
  end if;
  if v_currency_count=0 then
    select upper(currency) into strict v_currency
    from public.businesses where id=p_business;
  end if;

  with eligible as (
    select sale.*,contract.currency,
      app.v106_sale_residual_minor(
        sale.id,p_to,p_as_of
      ) as residual_cents
    from public.sales sale
    cross join lateral app.v106_reporting_contract(
      sale.business_id,sale.branch_id,sale.occurred_at
    ) contract
    where sale.business_id=p_business
      and (p_branch is null or sale.branch_id=p_branch)
      and sale.counts_as_revenue and sale.reversal_of is null
      and sale.created_at<=p_as_of
      and (sale.occurred_at at time zone contract.timezone)::date>=p_from
      and (sale.occurred_at at time zone contract.timezone)::date<p_to
      and app.v106_sale_residual_minor(sale.id,p_to,p_as_of)>0
  ), sale_shape as (
    select sale.*,
      exists(
        select 1 from public.sale_items item
        where item.business_id=p_business and item.sale_id=sale.id
      ) as is_itemized,
      coalesce((
        select sum(item.line_cents)
        from public.sale_items item
        where item.business_id=p_business and item.sale_id=sale.id
          and item.line_cents>0
      ),0)::bigint as positive_line_cents
    from eligible sale
  ), itemized_base as (
    select sale.id as sale_id,item.id as cost_line_key,
      sale.branch_id,sale.occurred_at,sale.currency,sale.kind as sale_kind,
      true as is_itemized,item.qty,item.line_cents as source_line_cents,
      case
        when item.item_type='retail' and item.product_id is not null
          then 'product'
        when item.item_type='service' and item.ref_id is not null
          then 'service'
        when item.item_type='package' and item.ref_id is not null
          then 'package'
        else null
      end as desired_scope_kind,
      case
        when item.item_type='retail' and item.product_id is not null
          then item.product_id::text
        when item.item_type in ('service','package') and item.ref_id is not null
          then item.ref_id::text
        else null
      end as desired_scope_key,
      sale.amount_cents as sale_original_cents,
      sale.residual_cents as sale_residual_cents,
      floor(
        sale.residual_cents::numeric*item.line_cents
        /sale.positive_line_cents
      )::bigint as allocated_base_cents,
      mod(
        sale.residual_cents::numeric*item.line_cents,
        sale.positive_line_cents
      ) as allocation_remainder
    from sale_shape sale
    join public.sale_items item
      on item.business_id=p_business and item.sale_id=sale.id
    where sale.is_itemized and sale.positive_line_cents>0
      and item.line_cents>0
  ), itemized_ranked as (
    select itemized_base.*,
      itemized_base.sale_residual_cents
        -sum(itemized_base.allocated_base_cents) over(
          partition by itemized_base.sale_id
        ) as remainder_to_assign,
      row_number() over(
        partition by itemized_base.sale_id
        order by itemized_base.allocation_remainder desc,
          itemized_base.cost_line_key
      ) as allocation_rank
    from itemized_base
  ), economic_lines as (
    select sale_id,cost_line_key,branch_id,occurred_at,currency,sale_kind,
      is_itemized,qty,source_line_cents,desired_scope_kind,desired_scope_key,
      sale_original_cents,sale_residual_cents,
      allocated_base_cents
        +case when allocation_rank<=remainder_to_assign then 1 else 0 end
        as allocated_cents
    from itemized_ranked
    union all
    -- An itemized parent with no positive economic line is never silently
    -- reclassified as a parent sale.  Keep one uncovered line so the report
    -- fails closed while still reconciling its full residual revenue.
    select sale.id,sale.id,sale.branch_id,sale.occurred_at,sale.currency,
      sale.kind,true,coalesce(sale.qty,1),greatest(sale.amount_cents,1),
      null::text,null::text,sale.amount_cents,sale.residual_cents,
      sale.residual_cents
    from sale_shape sale
    where sale.is_itemized and sale.positive_line_cents=0
    union all
    -- Sale-kind fallback exists only for genuinely non-itemized legacy rows.
    select sale.id,sale.id,sale.branch_id,sale.occurred_at,sale.currency,
      sale.kind,false,coalesce(sale.qty,1),greatest(sale.amount_cents,1),
      case when sale.product_id is not null then 'product' else 'sale_kind' end,
      case
        when sale.product_id is not null then sale.product_id::text
        else sale.kind
      end,
      sale.amount_cents,sale.residual_cents,
      sale.residual_cents
    from sale_shape sale
    where not sale.is_itemized
  ), candidate_pool as (
    select line.*,candidate.id as candidate_rule_id,
      candidate.cost_method,candidate.cost_value,
      candidate.effective_from,candidate.version_no,
      case
        when candidate.scope_kind=line.desired_scope_kind
          and candidate.scope_key=line.desired_scope_key then 0
        when not line.is_itemized and candidate.scope_kind='sale_kind'
          and candidate.scope_key=line.sale_kind then 1
        else 2
      end as scope_priority,
      case when candidate.branch_id=line.branch_id then 0 else 1 end
        as branch_priority
    from economic_lines line
    left join public.economic_cost_rules_v109 candidate
      on candidate.business_id=p_business
      and candidate.currency=line.currency
      and (candidate.branch_id is null or candidate.branch_id=line.branch_id)
      and candidate.effective_from<=line.occurred_at
      and (
        candidate.effective_to is null
        or candidate.effective_to>line.occurred_at
      )
      and (
        (
          candidate.scope_kind=line.desired_scope_kind
          and candidate.scope_key=line.desired_scope_key
        )
        or (
          not line.is_itemized
          and line.desired_scope_kind='product'
          and candidate.scope_kind='sale_kind'
          and candidate.scope_key=line.sale_kind
        )
      )
  ), ranked_candidates as (
    select candidate_pool.*,
      row_number() over(
        partition by sale_id,cost_line_key
        order by scope_priority,branch_priority,
          effective_from desc nulls last,version_no desc nulls last
      ) as selection_rank,
      count(candidate_rule_id) over(
        partition by sale_id,cost_line_key,scope_priority,branch_priority,
          effective_from
      ) as equal_precedence_rules
    from candidate_pool
  ), selected as (
    select *,
      candidate_rule_id is not null and equal_precedence_rules=1
        as is_covered,
      candidate_rule_id is not null and equal_precedence_rules>1
        as is_ambiguous,
      case
        when candidate_rule_id is null or equal_precedence_rules<>1 then null
        when cost_method='revenue_bps' then
          round(allocated_cents*cost_value::numeric/10000)::bigint
        when cost_method='fixed_per_unit' then
          round(
            cost_value*qty*sale_residual_cents::numeric
            /greatest(sale_original_cents,1)
          )::bigint
        else null
      end as cost_cents
    from ranked_candidates
    where selection_rank=1
  ), sale_summary as (
    select sale_id,count(*)::integer as eligible_lines,
      count(*) filter(where is_covered)::integer as covered_lines,
      count(*) filter(where is_ambiguous)::integer as ambiguous_lines,
      sum(allocated_cents)::bigint as revenue_cents,
      coalesce(sum(allocated_cents) filter(where is_covered),0)::bigint
        as covered_revenue_cents,
      coalesce(sum(cost_cents) filter(where is_covered),0)::bigint
        as cost_cents
    from selected
    group by sale_id
  )
  select count(*)::integer,
    count(*) filter(
      where covered_lines=eligible_lines and ambiguous_lines=0
    )::integer,
    coalesce(sum(eligible_lines),0)::integer,
    coalesce(sum(covered_lines),0)::integer,
    coalesce(sum(ambiguous_lines),0)::integer,
    coalesce(sum(revenue_cents),0)::bigint,
    coalesce(sum(covered_revenue_cents),0)::bigint,
    coalesce(sum(cost_cents),0)::bigint
  into v_sales,v_covered_sales,v_sale_lines,v_covered_sale_lines,
    v_ambiguous_sale_lines,v_revenue,v_covered_revenue,v_traceable_cogs
  from sale_summary;

  with eligible as (
    select entitlement.id,entitlement.value_cents,
      entitlement.entitlement_type,entitlement.redeemed_at,
      execution_row.branch_id,contract.currency
    from public.growth_entitlements_v108 entitlement
    join public.growth_executions_v108 execution_row
      on execution_row.id=entitlement.execution_id
      and execution_row.business_id=entitlement.business_id
    cross join lateral app.v106_reporting_contract(
      entitlement.business_id,execution_row.branch_id,entitlement.redeemed_at
    ) contract
    left join lateral (
      select event_row.sale_id,reversal_sale.occurred_at
      from public.growth_entitlement_events_v108 event_row
      join public.sales reversal_sale
        on reversal_sale.id=event_row.sale_id
        and reversal_sale.business_id=event_row.business_id
      where event_row.entitlement_id=entitlement.id
        and event_row.business_id=entitlement.business_id
        and event_row.event_type='reversed'
        and event_row.created_at<=p_as_of
        and reversal_sale.created_at<=p_as_of
        and reversal_sale.reversal_of=entitlement.redeemed_sale_id
      order by event_row.created_at desc,event_row.id desc
      limit 1
    ) reversal_evidence on true
    left join lateral app.v106_reporting_contract(
      entitlement.business_id,execution_row.branch_id,
      reversal_evidence.occurred_at
    ) reversal_contract on reversal_evidence.sale_id is not null
    where entitlement.business_id=p_business
      and (p_branch is null or execution_row.branch_id=p_branch)
      and entitlement.redeemed_at is not null
      and entitlement.redeemed_at<=p_as_of
      and (
        entitlement.reversed_at is null
        or entitlement.reversed_at>p_as_of
        or (
          entitlement.reversed_at<=p_as_of
          and reversal_evidence.sale_id is not null
          and (
            reversal_evidence.occurred_at
              at time zone reversal_contract.timezone
          )::date>=p_to
        )
      )
      and (
        entitlement.redeemed_at at time zone contract.timezone
      )::date>=p_from
      and (
        entitlement.redeemed_at at time zone contract.timezone
      )::date<p_to
  ), matched as (
    select benefit.id,benefit.value_cents,rule_row.id as rule_id,
      case
        when rule_row.cost_method='value_bps' then
          round(
            benefit.value_cents*rule_row.cost_value::numeric/10000
          )::bigint
        when rule_row.cost_method='fixed_per_event' then rule_row.cost_value
        else null
      end as cost_cents
    from eligible benefit
    left join lateral (
      select candidate.*
      from public.growth_cost_rules_v114 candidate
      where candidate.business_id=p_business
        and candidate.cost_class='benefit'
        and candidate.scope_key=benefit.entitlement_type
        and candidate.currency=benefit.currency
        and (
          candidate.branch_id is null
          or candidate.branch_id=benefit.branch_id
        )
        and candidate.effective_from<=benefit.redeemed_at
        and (
          candidate.effective_to is null
          or candidate.effective_to>benefit.redeemed_at
        )
      order by
        case when candidate.branch_id=benefit.branch_id then 0 else 1 end,
        candidate.effective_from desc,candidate.version_no desc
      limit 1
    ) rule_row on true
  )
  select count(*),count(*) filter(where rule_id is not null),
    coalesce(sum(value_cents),0),
    coalesce(sum(value_cents) filter(where rule_id is not null),0),
    coalesce(sum(cost_cents) filter(where rule_id is not null),0)
  into v_benefits,v_covered_benefits,v_benefit_value,
    v_covered_benefit_value,v_traceable_benefit_cost
  from matched;

  with eligible as (
    select dispatch.id,dispatch.branch_id,dispatch.provider,
      dispatch.delivered_at,contract.currency
    from public.growth_delivery_dispatches_v110 dispatch
    cross join lateral app.v106_reporting_contract(
      dispatch.business_id,dispatch.branch_id,dispatch.delivered_at
    ) contract
    where dispatch.business_id=p_business
      and (p_branch is null or dispatch.branch_id=p_branch)
      and dispatch.delivered_at is not null
      and dispatch.delivered_at<=p_as_of
      and (
        dispatch.delivered_at at time zone contract.timezone
      )::date>=p_from
      and (
        dispatch.delivered_at at time zone contract.timezone
      )::date<p_to
  ), matched as (
    select delivery.id,rule_row.id as rule_id,
      rule_row.cost_value as cost_cents
    from eligible delivery
    left join lateral (
      select candidate.*
      from public.growth_cost_rules_v114 candidate
      where candidate.business_id=p_business
        and candidate.cost_class='delivery'
        and candidate.scope_key=delivery.provider
        and candidate.currency=delivery.currency
        and (
          candidate.branch_id is null
          or candidate.branch_id=delivery.branch_id
        )
        and candidate.effective_from<=delivery.delivered_at
        and (
          candidate.effective_to is null
          or candidate.effective_to>delivery.delivered_at
        )
      order by
        case when candidate.branch_id=delivery.branch_id then 0 else 1 end,
        candidate.effective_from desc,candidate.version_no desc
      limit 1
    ) rule_row on true
  )
  select count(*),count(*) filter(where rule_id is not null),
    coalesce(sum(cost_cents) filter(where rule_id is not null),0)
  into v_deliveries,v_covered_deliveries,v_traceable_delivery_cost
  from matched;

  v_sale_transaction_coverage_bps:=case
    when v_sales=0 then null
    else round(v_covered_sales*10000.0/v_sales)::integer
  end;
  v_sale_revenue_coverage_bps:=case
    when v_revenue=0 then null
    else round(v_covered_revenue*10000.0/v_revenue)::integer
  end;
  v_sale_coverage_passes:=v_sales>0
    and v_sale_lines>0
    and v_covered_sales=v_sales
    and v_covered_sale_lines=v_sale_lines
    and v_ambiguous_sale_lines=0
    and v_covered_revenue=v_revenue;
  v_benefit_coverage_bps:=case
    when v_benefits=0 then null
    else round(v_covered_benefits*10000.0/v_benefits)::integer
  end;
  v_benefit_coverage_passes:=v_benefits=0
    or v_covered_benefits=v_benefits;
  v_delivery_coverage_bps:=case
    when v_deliveries=0 then null
    else round(v_covered_deliveries*10000.0/v_deliveries)::integer
  end;
  v_delivery_coverage_passes:=v_deliveries=0
    or v_covered_deliveries=v_deliveries;
  v_coverage_passes:=v_sale_coverage_passes
    and v_benefit_coverage_passes and v_delivery_coverage_passes;

  if v_sales=0 then
    v_unavailable:=v_unavailable||jsonb_build_array('no_eligible_sales');
  elsif not v_sale_coverage_passes then
    v_unavailable:=v_unavailable
      ||jsonb_build_array('incomplete_traceable_sale_cost_coverage');
  end if;
  if v_ambiguous_sale_lines>0 then
    v_unavailable:=v_unavailable
      ||jsonb_build_array('ambiguous_traceable_sale_cost_rules');
  end if;
  if not v_benefit_coverage_passes then
    v_unavailable:=v_unavailable
      ||jsonb_build_array('incomplete_traceable_benefit_cost_coverage');
  end if;
  if not v_delivery_coverage_passes then
    v_unavailable:=v_unavailable
      ||jsonb_build_array('incomplete_traceable_delivery_cost_coverage');
  end if;

  if v_coverage_passes then
    v_gross_profit:=v_revenue-v_traceable_cogs;
    v_contribution:=v_gross_profit-v_traceable_benefit_cost
      -v_traceable_delivery_cost;
    v_growth_investment:=v_traceable_benefit_cost+v_traceable_delivery_cost;
    v_total_investment:=v_growth_investment+coalesce(p_investment_cents,0);
    if v_total_investment>0 then
      v_net_return:=v_contribution-coalesce(p_investment_cents,0);
      v_roi_bps:=round(v_net_return*10000.0/v_total_investment);
    else
      v_unavailable:=v_unavailable
        ||jsonb_build_array('positive_traceable_investment_required');
    end if;
  end if;
  v_extra_reference:=nullif(btrim(coalesce(p_investment_reference,'')),'');

  return jsonb_build_object(
    'contract_version','period_economics_v109',
    'cost_contract_version','growth_costs_v114',
    'business_id',p_business,'as_of',p_as_of,
    'period',jsonb_build_object(
      'from',p_from,'to',p_to,'basis','business_local_date'
    ),
    'status',case
      when v_sales=0 then 'no_data'
      when v_coverage_passes then 'ready'
      else 'insufficient_cost_coverage'
    end,
    'coverage',jsonb_build_object(
      'cost_contract_version','growth_costs_v114',
      'eligible_sales',v_sales,'covered_sales',v_covered_sales,
      'eligible_sale_lines',v_sale_lines,
      'covered_sale_lines',v_covered_sale_lines,
      'ambiguous_sale_lines',v_ambiguous_sale_lines,
      'transaction_coverage_bps',v_sale_transaction_coverage_bps,
      'eligible_revenue_cents',v_revenue,
      'covered_revenue_cents',v_covered_revenue,
      'revenue_coverage_bps',v_sale_revenue_coverage_bps,
      'sale_cost_coverage_passes',v_sale_coverage_passes,
      'eligible_redeemed_benefits',v_benefits,
      'covered_redeemed_benefits',v_covered_benefits,
      'eligible_redeemed_benefit_value_cents',v_benefit_value,
      'covered_redeemed_benefit_value_cents',v_covered_benefit_value,
      'benefit_cost_coverage_bps',v_benefit_coverage_bps,
      'benefit_cost_coverage_passes',v_benefit_coverage_passes,
      'eligible_deliveries',v_deliveries,
      'covered_deliveries',v_covered_deliveries,
      'delivery_cost_coverage_bps',v_delivery_coverage_bps,
      'delivery_cost_coverage_passes',v_delivery_coverage_passes,
      'traceable_cost_coverage_passes',v_coverage_passes
    ),
    'profit',case when v_coverage_passes then jsonb_build_object(
      'currency',v_currency,'revenue_cents',v_revenue,
      'traceable_cogs_cents',v_traceable_cogs,
      'gross_profit_before_growth_costs_cents',v_gross_profit,
      'traceable_benefit_cost_cents',v_traceable_benefit_cost,
      'traceable_delivery_cost_cents',v_traceable_delivery_cost,
      'traceable_growth_cost_cents',
        v_traceable_benefit_cost+v_traceable_delivery_cost,
      'total_traceable_cost_cents',
        v_traceable_cogs+v_traceable_benefit_cost+v_traceable_delivery_cost,
      'contribution_after_growth_costs_cents',v_contribution,
      -- Compatibility alias: this is gross profit before growth costs.
      'gross_profit_cents',v_gross_profit
    ) else 'null'::jsonb end,
    'roi',case when v_roi_bps is not null then jsonb_build_object(
      'investment_cents',v_total_investment,
      'traceable_growth_investment_cents',v_growth_investment,
      'additional_investment_cents',coalesce(p_investment_cents,0),
      'investment_reference',case
        when v_extra_reference is null then 'v114 traceable benefit and delivery cost rules'
        else 'v114 traceable growth costs + '||v_extra_reference
      end,
      'additional_investment_reference',v_extra_reference,
      'net_return_cents',v_net_return,
      'return_on_investment_bps',v_roi_bps
    ) else 'null'::jsonb end,
    'unavailable_reasons',v_unavailable,
    'limitations',jsonb_build_array(
      'profit and contribution are returned only at complete sale-line, redeemed-benefit and delivery cost coverage',
      'itemized sale residuals, including in-period refunds, are allocated proportionally with deterministic largest-remainder rounding',
      'fixed unit costs preserve full unit COGS across checkout discounts and are reduced only by the sale refund survival ratio',
      'benefit reversals use the recorded reversal sale business date rather than the entitlement wall-clock update time',
      'sale-kind cost fallback is used only for genuinely non-itemized legacy sales',
      'ROI uses traceable redeemed-benefit and delivered-provider costs plus any separately sourced additional investment',
      'this period result is descriptive and is not a causal increment claim'
    )
  );
end $$;

--
-- Name: FUNCTION get_period_economics_v109(p_business uuid, p_from date, p_to date, p_branch uuid, p_investment_cents bigint, p_investment_reference text, p_as_of timestamp with time zone); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_period_economics_v109(p_business uuid, p_from date, p_to date, p_branch uuid, p_investment_cents bigint, p_investment_reference text, p_as_of timestamp with time zone) IS 'Stable v109 response contract extended by v114: profit, contribution and ROI are withheld until sale, redeemed-benefit and delivered-provider costs are fully traceable.';

--
-- Name: get_platform_billing_v77(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_platform_billing_v77(p_business uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 100) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if auth.uid() is null or not app.is_super_admin() then
    raise exception 'super-admin access is required' using errcode='42501';
  end if;
  if p_limit not between 1 and 250 then
    raise exception 'limit must be between 1 and 250' using errcode='22023';
  end if;
  return coalesce((
    select jsonb_agg(to_jsonb(rows) order by rows.updated_at desc)
    from (
      select s.business_id,b.name business_name,s.status,s.payment_status,s.currency,
             s.billing_cadence cadence,s.cadence_months,s.billing_provider provider,
             s.provider_customer_id,s.provider_subscription_id,
             app.billable_seats(s.business_id) billable_seats,
             s.period_subtotal_cents,s.period_tax_cents,s.period_total_cents,
             s.next_payment_at,s.last_paid_at,s.last_paid_invoice_id,
             s.cancel_at_period_end,s.updated_at,
             (
               select array_agg(catalog.cadence order by catalog.cadence)
                 from public.billing_price_catalog catalog
                where catalog.currency=s.currency and catalog.active
                  and catalog.effective_from<=now()
                  and (catalog.effective_to is null or catalog.effective_to>now())
             ) catalog_ready_cadences,
             array(
               select required.cadence
                 from unnest(array['annual','half_yearly','quarterly']) required(cadence)
                where not exists(
                  select 1 from public.billing_price_catalog catalog
                   where catalog.currency=s.currency
                     and catalog.cadence=required.cadence
                     and catalog.active and catalog.effective_from<=now()
                     and (catalog.effective_to is null or catalog.effective_to>now())
                )
                order by required.cadence
             ) catalog_missing_cadences,
             (
               select count(*) from public.billing_provider_events e
                where e.business_id=s.business_id and e.processing_status='failed'
             ) failed_event_count
        from public.subscriptions s
        join public.businesses b on b.id=s.business_id
       where (p_business is null or s.business_id=p_business) and b.is_demo=false
       order by s.updated_at desc limit p_limit
    ) rows
  ),'[]'::jsonb);
end
$$;

--
-- Name: get_pos_paynow_attempt_v142(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_pos_paynow_attempt_v142(p_attempt uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_attempt public.pos_payment_attempts_v142%rowtype;
        v_eval public.checkout_evaluations%rowtype;
        v_client_name text; v_business_name text; v_branch_name text;
        v_points_earned int := 0; v_points_total int := 0; v_items jsonb := '[]'::jsonb;
begin
  select * into v_attempt from public.pos_payment_attempts_v142 where id=p_attempt;
  if not found or auth.uid() is null or not exists (
    select 1 from public.staff s where s.business_id=v_attempt.business_id
     and s.user_id=auth.uid() and s.active
  ) or not app.can_module_read_at_v94(v_attempt.business_id,v_attempt.branch_id,'clients')
    or not (app.can_module_read_at_v94(v_attempt.business_id,v_attempt.branch_id,'till')
         or app.can_module_read_at_v94(v_attempt.business_id,v_attempt.branch_id,'sales'))
  then raise exception 'payment attempt access denied' using errcode='42501'; end if;
  select * into v_eval from public.checkout_evaluations where id=v_attempt.evaluation_id;
  select full_name into v_client_name from public.clients where id=v_attempt.client_id;
  select name into v_business_name from public.businesses where id=v_attempt.business_id;
  select name into v_branch_name from public.branches where id=v_attempt.branch_id;
  if v_attempt.sale_id is not null then
    select coalesce(sum(points),0)::int into v_points_earned from public.points_ledger
     where business_id=v_attempt.business_id and sale_id=v_attempt.sale_id and entry_type='earn';
    v_points_total := app.client_points_balance_v409(v_attempt.business_id, v_attempt.client_id);
    select coalesce(jsonb_agg(jsonb_build_object('description',description,'qty',qty,
      'line_cents',line_cents,'item_type',item_type) order by created_at,id),'[]'::jsonb)
      into v_items from public.sale_items where business_id=v_attempt.business_id and sale_id=v_attempt.sale_id;
  end if;
  return jsonb_build_object('attempt_id',v_attempt.id,'business_id',v_attempt.business_id,
    'branch_id',v_attempt.branch_id,'amount_cents',v_attempt.amount_cents,'currency',v_attempt.currency,
    'status',case when v_attempt.status in ('prepared','awaiting_payment','processing')
                    and v_attempt.expires_at<=now() then 'expired' else v_attempt.status end,
    'sale_id',v_attempt.sale_id,'payment_reference',v_attempt.payment_reference,
    'provider_refund_id',v_attempt.provider_refund_id,
    'refund_failure_reason',v_attempt.refund_failure_reason,
    'paid_at',v_attempt.paid_at,'expires_at',v_attempt.expires_at,'updated_at',v_attempt.updated_at,
    'customer_name',v_client_name,'business_name',v_business_name,'branch_name',v_branch_name,
    'subtotal_cents',v_eval.subtotal_cents,'discount_total_cents',v_eval.discount_total_cents,
    'gst_cents',v_eval.gst_cents,'server_lines',v_eval.server_lines,'applied_effects',v_eval.applied_effects,
    'points_earned',v_points_earned,'points_total',v_points_total,'items',v_items);
end $$;

--
-- Name: get_product_adoption_summary_v100(uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_product_adoption_summary_v100(p_business uuid, p_from timestamp with time zone DEFAULT (now() - '30 days'::interval), p_to timestamp with time zone DEFAULT now()) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_authorized boolean:=false;
  v_totals jsonb;
  v_daily jsonb;
begin
  if auth.uid() is null then
    raise exception 'authenticated report session is required'
      using errcode='28000';
  end if;
  v_authorized:=
    app.is_super_admin()
    or app.has_perm(p_business,'view_finance')
    or (
      app.v89_can_access_business(p_business)
      and app.v89_platform_can('reports','r')
    );
  if not v_authorized then
    raise exception 'business adoption report is outside role scope'
      using errcode='42501';
  end if;
  if p_business is null
     or p_from is null
     or p_to is null
     or p_to<=p_from
     or p_to-p_from>interval '93 days'
     or p_to>clock_timestamp()+interval '5 minutes' then
    raise exception 'report range must be positive and no longer than 93 days'
      using errcode='22023';
  end if;
  select coalesce(
    pg_catalog.jsonb_agg(
      pg_catalog.jsonb_build_object(
        'event_name',summary.event_name,
        'source_authority',summary.source_authority,
        'economic_event',summary.economic_event,
        'event_count',summary.event_count
      )
      order by summary.event_count desc,summary.event_name
    ),
    '[]'::jsonb
  ) into v_totals
  from(
    select
      event_row.event_name,event_row.source_authority,
      taxonomy.economic_event,count(*)::bigint as event_count
    from public.product_adoption_events_v100 event_row
    join public.product_adoption_event_taxonomy_v100 taxonomy
      on taxonomy.event_name=event_row.event_name
    where event_row.business_id=p_business
      and event_row.occurred_at>=p_from
      and event_row.occurred_at<p_to
    group by
      event_row.event_name,event_row.source_authority,
      taxonomy.economic_event
  ) summary;
  select coalesce(
    pg_catalog.jsonb_agg(
      pg_catalog.jsonb_build_object(
        'date',daily.event_date,'client_interactions',daily.client_count,
        'server_outcomes',daily.server_count,
        'economic_events',daily.economic_count
      )
      order by daily.event_date
    ),
    '[]'::jsonb
  ) into v_daily
  from(
    select
      (event_row.occurred_at at time zone 'Asia/Singapore')::date
        as event_date,
      count(*) filter(
        where event_row.source_authority='client'
      )::bigint as client_count,
      count(*) filter(
        where event_row.source_authority='server'
      )::bigint as server_count,
      count(*) filter(
        where taxonomy.economic_event
      )::bigint as economic_count
    from public.product_adoption_events_v100 event_row
    join public.product_adoption_event_taxonomy_v100 taxonomy
      on taxonomy.event_name=event_row.event_name
    where event_row.business_id=p_business
      and event_row.occurred_at>=p_from
      and event_row.occurred_at<p_to
    group by 1
  ) daily;
  return pg_catalog.jsonb_build_object(
    'business_id',p_business,'from',p_from,'to',p_to,
    'taxonomy_version','v100','provider_status','not_configured',
    'privacy_contract',pg_catalog.jsonb_build_object(
      'contact_fields_collected',false,
      'free_text_collected',false,
      'raw_route_or_search_collected',false,
      'event_retention_days',400
    ),
    'totals',v_totals,'daily',v_daily
  );
end
$$;

--
-- Name: get_program_entitlements(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_program_entitlements(p_business uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_result jsonb;
begin
  if not (app.is_salon_member(p_business) or app.is_super_admin()) then raise exception 'access denied' using errcode = '42501'; end if;
  select coalesce(jsonb_agg(jsonb_build_object(
    'entitlement_id', e.id, 'client_id', e.client_id, 'rule_id', e.rule_id, 'period_key', e.period_key,
    'fulfilment_kind', e.fulfilment_kind, 'status', e.status, 'valid_from', e.valid_from, 'valid_until', e.valid_until,
    'benefit_snapshot', e.benefit_snapshot) order by e.created_at desc), '[]'::jsonb)
    into v_result from public.program_entitlements e where e.business_id = p_business;
  return jsonb_build_object('business_id', p_business, 'entitlements', v_result);
end $$;

--
-- Name: get_program_rules_draft(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_program_rules_draft(p_config_version uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_header public.firm_config_versions%rowtype; v_result jsonb;
begin
  select * into v_header from public.firm_config_versions where id=p_config_version;
  if not found or not app.is_salon_owner(v_header.business_id) then raise exception 'owner only' using errcode='42501'; end if;
  if v_header.status<>'draft' then raise exception 'only a draft program rule set may be read' using errcode='42501'; end if;
  select jsonb_build_object(
    'config_version_id',v_header.id,'business_id',v_header.business_id,'version_no',v_header.version_no,
    'status',v_header.status,'snapshot_hash',v_header.snapshot_hash,
    'rules', coalesce((select jsonb_agg(jsonb_build_object(
        'rule_id',pr.rule_id,'program_rule_id',pr.id,'schema_version',pr.schema_version,'name',pr.name,'active',pr.active,
        'when_event',pr.when_event,'if_conditions',pr.if_conditions,'then_effects',pr.then_effects,
        'with_params',pr.with_params,'during_schedule',pr.during_schedule,'using_stacking',pr.using_stacking,
        'rule_hash',pr.rule_hash,'sort',pr.sort,'notes',pr.notes,
        'execution_state', app.ps1c2_rule_state(v_header.business_id, pr.id, v_header.status, pr.active),
        'validation', public.validate_program_rule(v_header.business_id, jsonb_build_object(
          'schema_version',pr.schema_version,'when_event',pr.when_event,'if_conditions',pr.if_conditions,
          'then_effects',pr.then_effects,'with_params',pr.with_params,'during_schedule',pr.during_schedule,'using_stacking',pr.using_stacking))
      ) order by pr.sort, pr.rule_id) from public.program_rules pr where pr.config_version_id=p_config_version and pr.business_id=v_header.business_id),'[]'::jsonb),
    'allowlists', public.get_rule_allowlists(v_header.business_id)
  ) into v_result;
  return v_result;
end $$;

--
-- Name: get_programs_overview(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_programs_overview(p_business uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_active uuid; v_result jsonb;
begin
  if not (app.is_salon_owner(p_business) or app.is_super_admin()) then raise exception 'owner only' using errcode='42501'; end if;
  select active_config_version_id into v_active from public.businesses where id=p_business;
  select jsonb_build_object(
    'business_id', p_business,
    'active_config_version_id', v_active,
    'registry', coalesce((select jsonb_agg(jsonb_build_object(
        'source_engine',br.source_engine,'execution_authority',br.execution_authority,
        'cutover_status',br.cutover_status,'canonical_benefit_key_template',br.canonical_benefit_key_template
      ) order by br.source_engine) from public.benefit_registry br where br.business_id=p_business),'[]'::jsonb),
    'legacy_programs', coalesce((select jsonb_agg(jsonb_build_object(
        'source_engine',a.source_engine,'rule_key',a.rule_key,'synthetic_rule_id',a.synthetic_rule_id,
        'native_ref',a.native_ref,'name',a.name,'active',a.active,'when_event',a.when_event,
        'if_conditions',a.if_conditions,'then_effects',a.then_effects,'with_params',a.with_params,
        'during_schedule',a.during_schedule,'using_stacking',a.using_stacking,
        'execution_authority','legacy_trigger','execution_state',a.execution_state
      ) order by a.source_engine, a.rule_key) from public.v_program_rules_all a where a.business_id=p_business),'[]'::jsonb),
    'studio_rules', coalesce((select jsonb_agg(jsonb_build_object(
        'rule_id',s.rule_id,'program_rule_id',s.id,'config_version_id',s.config_version_id,
        'config_status',fv.status,'name',s.name,'active',s.active,'when_event',s.when_event,
        'if_conditions',s.if_conditions,'then_effects',s.then_effects,'with_params',s.with_params,
        'during_schedule',s.during_schedule,'using_stacking',s.using_stacking,'rule_hash',s.rule_hash,
        'source_engine','studio_rule','execution_authority','studio_executor',
        -- PS-1C.2: 'execution_state' (back-compat) == 'aggregate_state' == the truthful
        -- server-derived aggregate; 'effect_states' is the per-effect breakdown;
        -- 'emergency_pause' surfaces the ACTIVE pause (reason/actor/time) so the owner
        -- UI can show WHO suspended the rule, WHY and WHEN (null when none is active).
        'execution_state', app.ps1c2_rule_state(s.business_id, s.id, fv.status, s.active),
        'aggregate_state', app.ps1c2_rule_state(s.business_id, s.id, fv.status, s.active),
        'effect_states', app.ps1c2_rule_effect_states(s.business_id, s.id),
        'emergency_pause', (select jsonb_build_object(
            'pause_id', ep.id, 'reason', ep.reason, 'actor', ep.actor,
            'paused_at', ep.paused_at, 'lifted_at', ep.lifted_at)
          from public.studio_rule_emergency_pauses ep
         where ep.business_id = s.business_id and ep.rule_id = s.rule_id and ep.lifted_at is null
         order by ep.paused_at desc limit 1)
      ) order by fv.status, s.sort, s.rule_id) from public.program_rules s
        join public.firm_config_versions fv on fv.id=s.config_version_id and fv.business_id=s.business_id
       where s.business_id=p_business and fv.status in ('draft','published')),'[]'::jsonb)
  ) into v_result;
  return v_result;
end $$;

--
-- Name: get_reports_summary(uuid, date, date, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_reports_summary(p_business uuid, p_from date, p_to date, p_branch uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_revenue jsonb;
  v_non_revenue jsonb;
  v_points jsonb;
  v_credit_liability bigint;
  v_gift_card_liability bigint;
  v_active_memberships bigint;
  v_compensating_rows bigint;
  v_reversed_revenue_cents bigint;
  v_net_revenue_cents bigint;
  v_sales_export_available boolean;
  v_clients_export_available boolean;
  v_loyalty_available boolean;
  v_gift_cards_available boolean;
  v_memberships_available boolean;
  v_credit_liability_available boolean;
begin
  if auth.uid() is null
     or not app.has_perm(p_business, 'view_sales') then
    raise exception 'you do not have permission to view reports for this business'
      using errcode = '42501';
  end if;
  if p_from is null or p_to is null or p_from > p_to then
    raise exception 'a valid report date range is required'
      using errcode = '22007';
  end if;
  if p_to - p_from > 1826 then
    raise exception 'report date range cannot exceed 1827 days'
      using errcode = '22023';
  end if;
  if p_branch is not null and not exists (
    select 1 from public.branches b
    where b.id = p_branch and b.business_id = p_business
  ) then
    raise exception 'branch does not belong to this business'
      using errcode = '42501';
  end if;

  -- Every money/reversal field below is derived from Sales. Reports mode alone is not
  -- sufficient because a branch-level Sales override may intentionally make that
  -- source unreadable. A SECURITY DEFINER aggregate must fail closed for the exact
  -- selected scope rather than return a plausible complete total from hidden rows.
  perform app.require_metric_module_scope_v145(
    p_business, p_branch, 'reports'
  );
  if not app.platform_metric_source_scope_available_v145(
    p_business, p_branch, 'sales'
  ) then
    raise exception 'complete_metric_source_scope_required:sales'
      using errcode = '42501';
  end if;

  v_sales_export_available := app.metric_module_scope_available_v145(
    p_business, p_branch, 'sales'
  );
  v_clients_export_available := app.metric_module_scope_available_v145(
    p_business, p_branch, 'clients'
  );
  v_loyalty_available := app.metric_module_scope_available_v145(
    p_business, null, 'loyalty'
  );
  v_gift_cards_available := app.metric_module_scope_available_v145(
    p_business, null, 'giftcards'
  );
  v_memberships_available := app.metric_module_scope_available_v145(
    p_business, null, 'memberships'
  );
  v_credit_liability_available := app.metric_module_scope_available_v145(
    p_business, null, 'reports'
  ) and app.platform_metric_source_scope_available_v145(
    p_business, null, 'sales'
  );
  if not app.can_see_branch(p_business, p_branch) then
    raise exception 'you are not permitted to view this branch scope'
      using errcode = '42501';
  end if;
  -- Preserve the V94 branch-effective Reports boundary. A branch override may
  -- intentionally differ from the firm mode, and an all-branch report must not
  -- consolidate a branch the caller cannot see or where Reports is disabled.
  if p_branch is not null then
    perform app.require_branch_module_v94(p_business, p_branch, 'reports', 'r');
  elsif not app.is_super_admin() then
    if not app.can_module_read_at_v94(p_business, null, 'reports') then
      raise exception 'branch_module_access_required:reports:r'
        using errcode = '42501';
    end if;
    if exists (
      select 1
      from public.branches branch
      where branch.business_id = p_business
        and (
          not app.can_see_branch(p_business, branch.id)
          or not case when branch.active
            then app.can_module_read_at_v94(p_business, branch.id, 'reports')
            else app.can_module_read_at_v94(p_business, null, 'reports')
          end
        )
    ) then
      raise exception 'explicit_branch_required_for_partial_report_scope'
        using errcode = '42501';
    end if;
  end if;

  select coalesce(jsonb_object_agg(x.kind, x.amount_cents), '{}'::jsonb)
  into v_revenue
  from (
    select s.kind, sum(s.amount_cents) as amount_cents
    from public.sales s
    where s.business_id = p_business
      and s.counts_as_revenue
      and s.occurred_at >= (p_from::timestamp at time zone 'Asia/Singapore')
      and s.occurred_at < ((p_to + 1)::timestamp at time zone 'Asia/Singapore')
      and (p_branch is null or s.branch_id = p_branch)
    group by s.kind
  ) x;

  select
    count(*) filter (where s.reversal_of is not null),
    coalesce(sum(-s.amount_cents) filter (
      where s.counts_as_revenue
        and s.reversal_of is not null
        and s.amount_cents < 0
    ), 0),
    coalesce(sum(s.amount_cents) filter (where s.counts_as_revenue), 0)
  into v_compensating_rows, v_reversed_revenue_cents, v_net_revenue_cents
  from public.sales s
  where s.business_id = p_business
    and s.occurred_at >= (p_from::timestamp at time zone 'Asia/Singapore')
    and s.occurred_at < ((p_to + 1)::timestamp at time zone 'Asia/Singapore')
    and (p_branch is null or s.branch_id = p_branch);

  select coalesce(jsonb_object_agg(x.kind, x.amount_cents), '{}'::jsonb)
  into v_non_revenue
  from (
    select s.kind, sum(s.amount_cents) as amount_cents
    from public.sales s
    where s.business_id = p_business
      and not s.counts_as_revenue
      and s.occurred_at >= (p_from::timestamp at time zone 'Asia/Singapore')
      and s.occurred_at < ((p_to + 1)::timestamp at time zone 'Asia/Singapore')
      and (p_branch is null or s.branch_id = p_branch)
    group by s.kind
  ) x;

  if v_loyalty_available then
    select coalesce(jsonb_object_agg(x.entry_type, x.points), '{}'::jsonb)
    into v_points
    from (
      select pl.entry_type, sum(pl.points) as points
      from public.points_ledger pl
      where pl.business_id = p_business
        and pl.created_at >= (p_from::timestamp at time zone 'Asia/Singapore')
        and pl.created_at < ((p_to + 1)::timestamp at time zone 'Asia/Singapore')
      group by pl.entry_type
    ) x;
  else
    v_points := null;
  end if;

  if v_credit_liability_available then
    select coalesce(sum(greatest(cb.balance_cents, 0)), 0)
      into v_credit_liability
      from public.client_credit_balance cb
     where cb.business_id = p_business;
  else
    v_credit_liability := null;
  end if;

  if v_gift_cards_available then
    v_gift_card_liability := app.reports_gift_card_liability_v49b(
      p_business, p_branch
    );
  else
    v_gift_card_liability := null;
  end if;

  if v_memberships_available then
    select count(*) filter (where m.status = 'active')
    into v_active_memberships
    from public.memberships m
    where m.business_id = p_business;
  else
    v_active_memberships := null;
  end if;

  return jsonb_build_object(
    'revenue_by_kind', v_revenue,
    'non_revenue_by_kind', v_non_revenue,
    'points_by_type', v_points,
    'credit_liability_cents', v_credit_liability,
    'gift_card_liability_cents', v_gift_card_liability,
    'active_memberships', v_active_memberships,
    'reversal_reconciliation', jsonb_build_object(
      'compensating_rows', v_compensating_rows,
      'reversed_revenue_cents', v_reversed_revenue_cents,
      'net_revenue_cents', v_net_revenue_cents
    ),
    'availability', jsonb_build_object(
      'sales_export', v_sales_export_available,
      'clients_export', v_clients_export_available,
      'loyalty', v_loyalty_available,
      'gift_cards', v_gift_cards_available,
      'memberships', v_memberships_available,
      'credit_liability', v_credit_liability_available
    ),
    'scope', jsonb_build_object(
      'timezone', 'Asia/Singapore',
      'from', p_from,
      'to', p_to,
      'branch_id', p_branch,
      'sales', 'selected_period_and_branch_signed_ledger',
      'points', case when v_loyalty_available
        then 'business_wide_selected_period'
        else 'unavailable_without_complete_loyalty_scope' end,
      'credit_liability', case when v_credit_liability_available
        then 'business_wide_current_with_complete_business_reports_and_sales_source_scope'
        else 'unavailable_without_complete_business_reports_and_sales_source_scope' end,
      'gift_card_liability', case when v_gift_cards_available
        then 'business_wide_current' else 'unavailable_without_complete_giftcards_scope' end,
      'active_memberships', case when v_memberships_available
        then 'business_wide_current'
        else 'unavailable_without_complete_memberships_scope' end
    )
  );
end;
$$;

--
-- Name: get_reports_summary_v94_base(uuid, date, date, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_reports_summary_v94_base(p_business uuid, p_from date, p_to date, p_branch uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
declare
  v_revenue jsonb;
  v_non_revenue jsonb;
  v_points jsonb;
  v_credit_liability bigint;
  v_gift_card_liability bigint;
  v_active_memberships bigint;
begin
  if auth.uid() is null
     or not app.has_perm(p_business, 'view_sales')
     or not app.can_module_read(p_business, 'reports') then
    raise exception 'you do not have permission to view reports for this business'
      using errcode = '42501';
  end if;
  if p_from is null or p_to is null or p_from > p_to then
    raise exception 'a valid report date range is required'
      using errcode = '22007';
  end if;
  if p_branch is not null and not exists (
    select 1 from public.branches b
    where b.id = p_branch and b.business_id = p_business
  ) then
    raise exception 'branch does not belong to this business'
      using errcode = '42501';
  end if;
  if not app.can_see_branch(p_business, p_branch) then
    raise exception 'you are not permitted to view this branch scope'
      using errcode = '42501';
  end if;

  select coalesce(jsonb_object_agg(x.kind, x.amount_cents), '{}'::jsonb)
  into v_revenue
  from (
    select s.kind, sum(s.amount_cents) as amount_cents
    from public.sales s
    where s.business_id = p_business
      and s.counts_as_revenue
      and s.occurred_at >= (p_from::timestamp at time zone 'Asia/Singapore')
      and s.occurred_at < ((p_to + 1)::timestamp at time zone 'Asia/Singapore')
      and (p_branch is null or s.branch_id = p_branch)
    group by s.kind
  ) x;

  select coalesce(jsonb_object_agg(x.kind, x.amount_cents), '{}'::jsonb)
  into v_non_revenue
  from (
    select s.kind, sum(s.amount_cents) as amount_cents
    from public.sales s
    where s.business_id = p_business
      and not s.counts_as_revenue
      and s.occurred_at >= (p_from::timestamp at time zone 'Asia/Singapore')
      and s.occurred_at < ((p_to + 1)::timestamp at time zone 'Asia/Singapore')
      and (p_branch is null or s.branch_id = p_branch)
    group by s.kind
  ) x;

  select coalesce(jsonb_object_agg(x.entry_type, x.points), '{}'::jsonb)
  into v_points
  from (
    select pl.entry_type, sum(pl.points) as points
    from public.points_ledger pl
    where pl.business_id = p_business
      and pl.created_at >= (p_from::timestamp at time zone 'Asia/Singapore')
      and pl.created_at < ((p_to + 1)::timestamp at time zone 'Asia/Singapore')
    group by pl.entry_type
  ) x;

  select coalesce(sum(greatest(cb.balance_cents, 0)), 0)
  into v_credit_liability
  from public.client_credit_balance cb
  where cb.business_id = p_business;

  v_gift_card_liability := app.reports_gift_card_liability_v49b(p_business, p_branch);

  select count(*) filter (where m.status = 'active')
  into v_active_memberships
  from public.memberships m
  where m.business_id = p_business;

  return jsonb_build_object(
    'revenue_by_kind', v_revenue,
    'non_revenue_by_kind', v_non_revenue,
    'points_by_type', v_points,
    'credit_liability_cents', v_credit_liability,
    'gift_card_liability_cents', v_gift_card_liability,
    'active_memberships', v_active_memberships
  );
end;
$$;

--
-- Name: get_retention_config_draft(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_retention_config_draft(p_config_version uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_header public.firm_config_versions%rowtype; v_result jsonb;
begin
  select * into v_header from public.firm_config_versions
   where id=p_config_version for share;
  if not found or not app.is_salon_owner(v_header.business_id) then
    raise exception 'owner only' using errcode='42501';
  end if;
  if v_header.status<>'draft' then
    raise exception 'only a draft retention configuration may be read' using errcode='42501';
  end if;
  perform 1 from public.businesses where id=v_header.business_id for share;
  select jsonb_build_object(
    'config_version_id',v_header.id,'business_id',v_header.business_id,
    'version_no',v_header.version_no,'status',v_header.status,
    'snapshot_hash',v_header.snapshot_hash,
    'programs',coalesce((select jsonb_agg(jsonb_build_object(
      'retention_program_version_id',r.id,'program_id',r.program_id,
      'name',r.name,'active',r.active,'goal_visits',r.goal_visits,
      'period_days',r.period_days,'starts_on',r.starts_on,
      'reward_taxonomy_id',r.reward_taxonomy_id,'reward_label',t.label,
      'fulfillment_kind',r.fulfillment_kind,
      'discount_percent',r.discount_percent,'credit_cents',r.credit_cents,
      'manual_item',r.manual_item,'sort',r.sort,
      'customer_description',r.customer_description,'staff_description',r.staff_description
    ) order by r.sort,r.program_id) from public.retention_program_versions r
      join public.firm_reward_taxonomy t
        on t.id=r.reward_taxonomy_id and t.business_id=r.business_id
      where r.config_version_id=v_header.id and r.business_id=v_header.business_id),'[]'::jsonb),
    'taxonomy',coalesce((select jsonb_agg(jsonb_build_object(
      'id',t.id,'label',t.label,'fulfillment_kind',t.fulfillment_kind,
      'active',t.active,'sort',t.sort
    ) order by t.sort,t.label,t.id) from public.firm_reward_taxonomy t
      where t.business_id=v_header.business_id),'[]'::jsonb)
  ) into v_result;
  return v_result;
end $$;

--
-- Name: get_revenue_driver_decomposition_v109(uuid, date, date, date, date, uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_revenue_driver_decomposition_v109(p_business uuid, p_current_from date, p_current_to date, p_comparison_from date, p_comparison_to date, p_branch uuid DEFAULT NULL::uuid, p_as_of timestamp with time zone DEFAULT statement_timestamp()) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  c_total bigint:=0;
  c_identified bigint:=0;
  c_transactions integer:=0;
  c_clients integer:=0;
  c_total_transactions integer:=0;
  c_itemized_transactions integer:=0;
  c_itemized_revenue bigint:=0;
  p_total bigint:=0;
  p_identified bigint:=0;
  p_transactions integer:=0;
  p_clients integer:=0;
  p_total_transactions integer:=0;
  p_itemized_transactions integer:=0;
  p_itemized_revenue bigint:=0;
  c_anonymous bigint:=0;
  p_anonymous bigint:=0;
  c_coverage integer;
  p_coverage integer;
  c_itemized_transaction_coverage integer;
  p_itemized_transaction_coverage integer;
  c_itemized_revenue_coverage integer;
  p_itemized_revenue_coverage integer;
  p_frequency numeric;
  p_aov numeric;
  c_frequency numeric;
  c_aov numeric;
  d_customer bigint;
  d_frequency bigint;
  d_aov bigint;
  d_anonymous bigint;
  d_residual bigint;
  d_total bigint;
  d_sum bigint;
  v_available boolean:=false;
  v_reason text;
  v_currency text;
  v_currency_count integer;
begin
  perform app.v109_require_feature();
  perform app.v109_require_finance_scope(p_business,p_branch);
  if p_current_from is null
     or p_current_to is null
     or p_comparison_from is null
     or p_comparison_to is null
     or p_current_from>=p_current_to
     or p_comparison_from>=p_comparison_to
     or p_as_of is null then
    raise exception 'valid local-date periods and as-of are required'
      using errcode='22023';
  end if;
  if p_branch is not null and not exists (
    select 1 from public.branches branch
     where branch.id=p_branch and branch.business_id=p_business
  ) then
    raise exception 'branch does not belong to business' using errcode='22023';
  end if;

  select count(distinct contract.currency),min(contract.currency)
    into v_currency_count,v_currency
    from public.sales sale
    cross join lateral app.v106_reporting_contract(
      sale.business_id,sale.branch_id,sale.occurred_at
    ) contract
   where sale.business_id=p_business
     and (p_branch is null or sale.branch_id=p_branch)
     and sale.counts_as_revenue
     and sale.reversal_of is null
     and sale.created_at<=p_as_of
     and (
       (
         (sale.occurred_at at time zone contract.timezone)::date>=p_current_from
         and
         (sale.occurred_at at time zone contract.timezone)::date<p_current_to
       ) or (
         (sale.occurred_at at time zone contract.timezone)::date>=
           p_comparison_from
         and
         (sale.occurred_at at time zone contract.timezone)::date<p_comparison_to
       )
     );
  if v_currency_count>1 then
    raise exception 'cross-currency driver comparisons are not supported'
      using errcode='22023';
  end if;
  if v_currency_count=0 then
    select upper(currency) into strict v_currency
      from public.businesses where id=p_business;
  end if;

  with base as (
    select
      app.v113_effective_client_id(sale.business_id,sale.client_id) as client_id,
      app.v106_sale_residual_minor(
        sale.id,p_current_to,p_as_of
      ) as amount_cents,
      exists (
        select 1
          from public.sale_items item
         where item.business_id=sale.business_id
           and item.sale_id=sale.id
           and item.line_cents>0
      ) as is_itemized
    from public.sales sale
    cross join lateral app.v106_reporting_contract(
      sale.business_id,sale.branch_id,sale.occurred_at
    ) contract
    where sale.business_id=p_business
      and (p_branch is null or sale.branch_id=p_branch)
      and sale.counts_as_revenue
      and sale.reversal_of is null
      and sale.created_at<=p_as_of
      and (sale.occurred_at at time zone contract.timezone)::date>=p_current_from
      and (sale.occurred_at at time zone contract.timezone)::date<p_current_to
      and app.v106_sale_residual_minor(
        sale.id,p_current_to,p_as_of
      )>0
  )
  select coalesce(sum(amount_cents),0),
    coalesce(sum(amount_cents) filter(where client_id is not null),0),
    count(*) filter(where client_id is not null),
    count(distinct client_id) filter(where client_id is not null),
    count(*),
    count(*) filter(where is_itemized),
    coalesce(sum(amount_cents) filter(where is_itemized),0)
  into c_total,c_identified,c_transactions,c_clients,
       c_total_transactions,c_itemized_transactions,c_itemized_revenue
  from base;

  with base as (
    select
      app.v113_effective_client_id(sale.business_id,sale.client_id) as client_id,
      app.v106_sale_residual_minor(
        sale.id,p_comparison_to,p_as_of
      ) as amount_cents,
      exists (
        select 1
          from public.sale_items item
         where item.business_id=sale.business_id
           and item.sale_id=sale.id
           and item.line_cents>0
      ) as is_itemized
    from public.sales sale
    cross join lateral app.v106_reporting_contract(
      sale.business_id,sale.branch_id,sale.occurred_at
    ) contract
    where sale.business_id=p_business
      and (p_branch is null or sale.branch_id=p_branch)
      and sale.counts_as_revenue
      and sale.reversal_of is null
      and sale.created_at<=p_as_of
      and (sale.occurred_at at time zone contract.timezone)::date>=
        p_comparison_from
      and (sale.occurred_at at time zone contract.timezone)::date<
        p_comparison_to
      and app.v106_sale_residual_minor(
        sale.id,p_comparison_to,p_as_of
      )>0
  )
  select coalesce(sum(amount_cents),0),
    coalesce(sum(amount_cents) filter(where client_id is not null),0),
    count(*) filter(where client_id is not null),
    count(distinct client_id) filter(where client_id is not null),
    count(*),
    count(*) filter(where is_itemized),
    coalesce(sum(amount_cents) filter(where is_itemized),0)
  into p_total,p_identified,p_transactions,p_clients,
       p_total_transactions,p_itemized_transactions,p_itemized_revenue
  from base;

  c_anonymous:=c_total-c_identified;
  p_anonymous:=p_total-p_identified;
  c_coverage:=case when c_total=0 then null
    else round(c_identified*10000.0/c_total)::integer end;
  p_coverage:=case when p_total=0 then null
    else round(p_identified*10000.0/p_total)::integer end;
  c_itemized_transaction_coverage:=case when c_total_transactions=0 then null
    else round(c_itemized_transactions*10000.0/c_total_transactions)::integer end;
  p_itemized_transaction_coverage:=case when p_total_transactions=0 then null
    else round(p_itemized_transactions*10000.0/p_total_transactions)::integer end;
  c_itemized_revenue_coverage:=case when c_total=0 then null
    else round(c_itemized_revenue*10000.0/c_total)::integer end;
  p_itemized_revenue_coverage:=case when p_total=0 then null
    else round(p_itemized_revenue*10000.0/p_total)::integer end;
  d_total:=c_total-p_total;
  v_available:=c_clients>0 and p_clients>0
    and c_transactions>0 and p_transactions>0;
  if v_available then
    p_frequency:=p_transactions::numeric/p_clients;
    p_aov:=p_identified::numeric/p_transactions;
    c_frequency:=c_transactions::numeric/c_clients;
    c_aov:=c_identified::numeric/c_transactions;
    d_customer:=round((c_clients-p_clients)*p_frequency*p_aov);
    d_frequency:=round(c_clients*(c_frequency-p_frequency)*p_aov);
    d_aov:=round(c_clients*c_frequency*(c_aov-p_aov));
    d_anonymous:=c_anonymous-p_anonymous;
    d_residual:=d_total-d_customer-d_frequency-d_aov-d_anonymous;
    d_sum:=d_customer+d_frequency+d_aov+d_anonymous+d_residual;
  else
    v_reason:=case
      when p_total=0 then 'comparison_period_has_no_revenue'
      when c_total=0 then 'current_period_has_no_revenue'
      when p_clients=0 or p_transactions=0
        then 'comparison_period_has_no_identified_customer_base'
      else 'current_period_has_no_identified_customer_base'
    end;
  end if;

  return jsonb_build_object(
    'contract_version','revenue_driver_decomposition_v109',
    'business_id',p_business,'as_of',p_as_of,'currency',v_currency,
    'status',case when v_available then 'ready' else 'unavailable' end,
    'unavailable_reason',v_reason,
    'identity_attribution','v111_current_effective_identity',
    'periods',jsonb_build_object(
      'comparison',jsonb_build_object(
        'from',p_comparison_from,'to',p_comparison_to,
        'basis','business_local_date','revenue_cents',p_total,
        'identified_revenue_cents',p_identified,
        'anonymous_revenue_cents',p_anonymous,
        'identified_customers',p_clients,
        'identified_transactions',p_transactions,
        'transactions',p_total_transactions,
        'itemized_transactions',p_itemized_transactions,
        'itemized_revenue_cents',p_itemized_revenue
      ),
      'current',jsonb_build_object(
        'from',p_current_from,'to',p_current_to,
        'basis','business_local_date','revenue_cents',c_total,
        'identified_revenue_cents',c_identified,
        'anonymous_revenue_cents',c_anonymous,
        'identified_customers',c_clients,
        'identified_transactions',c_transactions,
        'transactions',c_total_transactions,
        'itemized_transactions',c_itemized_transactions,
        'itemized_revenue_cents',c_itemized_revenue
      )
    ),
    'coverage',jsonb_build_object(
      'comparison_identified_revenue_bps',p_coverage,
      'current_identified_revenue_bps',c_coverage,
      'comparison_itemized_transaction_bps',p_itemized_transaction_coverage,
      'current_itemized_transaction_bps',c_itemized_transaction_coverage,
      'comparison_itemized_revenue_bps',p_itemized_revenue_coverage,
      'current_itemized_revenue_bps',c_itemized_revenue_coverage,
      'anonymous_revenue_is_separate_driver',true
    ),
    'line_item_analysis',jsonb_build_object(
      'status','coverage_only',
      'price_volume_mix_status','not_claimed',
      'reason',
        'line-level price and mix effects require complete itemization and a versioned taxonomy',
      'causal_claim',false
    ),
    'drivers',case when v_available then jsonb_build_object(
      'identified_customer_count_cents',d_customer,
      'purchase_frequency_cents',d_frequency,
      'average_transaction_value_cents',d_aov,
      'anonymous_revenue_cents',d_anonymous,
      'rounding_residual_cents',d_residual
    ) else 'null'::jsonb end,
    'reconciliation',jsonb_build_object(
      'period_revenue_delta_cents',d_total,
      'sum_driver_contributions_cents',d_sum,
      'rounding_residual_cents',d_residual,
      'reconciles',case when v_available then d_sum=d_total else null end
    ),
    'method',jsonb_build_object(
      'identity',
        'revenue = effective identified customers × purchase frequency × average transaction value + anonymous revenue',
      'identity_resolver','v111_current_effective_identity',
      'order',jsonb_build_array(
        'identified_customer_count','purchase_frequency',
        'average_transaction_value','anonymous_revenue','rounding_residual'
      ),
      'deterministic',true,'causal_claim',false
    )
  );
end
$$;

--
-- Name: FUNCTION get_revenue_driver_decomposition_v109(p_business uuid, p_current_from date, p_current_to date, p_comparison_from date, p_comparison_to date, p_branch uuid, p_as_of timestamp with time zone); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_revenue_driver_decomposition_v109(p_business uuid, p_current_from date, p_current_to date, p_comparison_from date, p_comparison_to date, p_branch uuid, p_as_of timestamp with time zone) IS 'Deterministic non-causal revenue bridge whose customer counts and frequency resolve immutable source client ids through current v111 effective identity.';

--
-- Name: get_revenue_summary(uuid, date, date, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_revenue_summary(p_business uuid, p_from date, p_to date, p_branch uuid DEFAULT NULL::uuid) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_accrual bigint;
  v_cash bigint;
  v_sv_cash bigint;
  v_expenses bigint;
  v_unpaid bigint;
  v_collected bigint;
  v_from_ts timestamptz;
  v_to_ts timestamptz;
  v_expenses_by_category jsonb;
  v_monthly jsonb;
begin
  if p_from is null or p_to is null or p_from > p_to then
    raise exception 'p_from and p_to are required and p_from must be on or before p_to'
      using errcode = '22007';
  end if;
  if p_to - p_from > 1826 then
    raise exception 'report date range cannot exceed 1827 days'
      using errcode = '22023';
  end if;

  if not app.has_perm(p_business, 'view_finance') then
    raise exception 'you do not have permission to view finance for this business (view_finance)'
      using errcode = '42501';
  end if;

  if p_branch is not null and not exists (
    select 1
      from public.branches b
     where b.id = p_branch
       and b.business_id = p_business
  ) then
    raise exception 'branch does not belong to this business';
  end if;

  if not app.can_see_branch(p_business, p_branch) then
    raise exception 'you are not permitted to view this branch scope for this business (branch_visibility)'
      using errcode = '42501';
  end if;

  perform app.require_metric_module_scope_v145(p_business, p_branch, 'pnl');
  perform app.require_metric_module_scope_v145(p_business, p_branch, 'sales');
  perform app.require_metric_module_scope_v145(p_business, p_branch, 'expenses');

  v_from_ts := p_from::timestamp at time zone 'Asia/Singapore';
  v_to_ts := (p_to + 1)::timestamp at time zone 'Asia/Singapore';

  select coalesce(sum(s.amount_cents), 0)
    into v_accrual
    from public.sales s
   where s.business_id = p_business
     and s.counts_as_revenue
     and s.occurred_at >= v_from_ts
     and s.occurred_at < v_to_ts
     and (p_branch is null or s.branch_id = p_branch);

  select coalesce(sum(p.amount_cents), 0)
    into v_cash
    from public.payments p
    join public.sales s
      on s.business_id = p.business_id
     and s.reversal_of is null
     and (
       s.id = p.sale_id
       or (
         p.sale_id is null
         and p.appointment_id is not null
         and s.appointment_id = p.appointment_id
       )
     )
   where p.business_id = p_business
     and s.counts_as_revenue
     and p.occurred_at >= v_from_ts
     and p.occurred_at < v_to_ts
     and (p_branch is null or p.branch_id = p_branch);

  select coalesce(sum(t.reserved_cents), 0)
    into v_sv_cash
    from public.checkout_sv_tenders t
    join public.sales s
      on s.business_id = t.business_id
     and s.id = t.sale_id
     and s.reversal_of is null
   where t.business_id = p_business
     and t.status = 'consumed'
     and not exists (
       select 1 from public.checkout_sv_tender_reversals rv
        where rv.business_id = t.business_id and rv.tender_id = t.id)
     and s.counts_as_revenue
     and s.occurred_at >= v_from_ts
     and s.occurred_at < v_to_ts
     and (p_branch is null or s.branch_id = p_branch);
  v_cash := v_cash + v_sv_cash;

  select coalesce(sum(p.amount_cents), 0)
    into v_collected
    from public.payments p
   where p.business_id = p_business
     and p.method not in ('credit', 'gift_card')
     and p.occurred_at >= v_from_ts
     and p.occurred_at < v_to_ts
     and (p_branch is null or p.branch_id = p_branch);

  select coalesce(sum(b.balance_cents), 0)
    into v_unpaid
    from public.sale_balance b
   where b.business_id = p_business
     and b.counts_as_revenue
     and b.balance_cents > 0
     and b.occurred_at >= v_from_ts
     and b.occurred_at < v_to_ts
     and (p_branch is null or b.branch_id = p_branch);

  select coalesce(sum(round(e.amount_cents::numeric * e.fx_rate_to_base::numeric)), 0)::bigint
    into v_expenses
    from public.expenses e
   where e.business_id = p_business
     and e.voided_at is null
     and e.occurred_on between p_from and p_to
     and (p_branch is null or e.branch_id = p_branch);

  select coalesce(jsonb_object_agg(x.category, x.amount_cents order by x.category), '{}'::jsonb)
    into v_expenses_by_category
    from (
      select coalesce(nullif(btrim(e.category), ''), 'Uncategorised') as category,
             sum(round(e.amount_cents::numeric * e.fx_rate_to_base::numeric))::bigint as amount_cents
      from public.expenses e
      where e.business_id = p_business
        and e.voided_at is null
        and e.occurred_on between p_from and p_to
        and (p_branch is null or e.branch_id = p_branch)
      group by coalesce(nullif(btrim(e.category), ''), 'Uncategorised')
    ) x;

  with months as (
    select generate_series(
      date_trunc('month', p_from::timestamp),
      date_trunc('month', p_to::timestamp),
      interval '1 month'
    )::date as month_start
  ), revenue as (
    select date_trunc('month', s.occurred_at at time zone 'Asia/Singapore')::date as month_start,
           sum(s.amount_cents)::bigint as amount_cents
    from public.sales s
    where s.business_id = p_business
      and s.counts_as_revenue
      and s.occurred_at >= v_from_ts
      and s.occurred_at < v_to_ts
      and (p_branch is null or s.branch_id = p_branch)
    group by 1
  ), expense as (
    select date_trunc('month', e.occurred_on::timestamp)::date as month_start,
           sum(round(e.amount_cents::numeric * e.fx_rate_to_base::numeric))::bigint as amount_cents
    from public.expenses e
    where e.business_id = p_business
      and e.voided_at is null
      and e.occurred_on between p_from and p_to
      and (p_branch is null or e.branch_id = p_branch)
    group by 1
  )
  select coalesce(jsonb_object_agg(
    to_char(m.month_start, 'YYYY-MM'),
    jsonb_build_object(
      'revenue_accrual_cents', coalesce(r.amount_cents, 0),
      'expenses_cents', coalesce(e.amount_cents, 0)
    ) order by m.month_start
  ), '{}'::jsonb)
  into v_monthly
  from months m
  left join revenue r using (month_start)
  left join expense e using (month_start);

  return json_build_object(
    'from', p_from,
    'to', p_to,
    'branch_id', p_branch,
    'timezone', 'Asia/Singapore',
    'revenue_accrual_cents', v_accrual,
    'revenue_cash_cents', v_cash,
    'cash_collected_cents', v_collected,
    'unpaid_balance_cents', v_unpaid,
    'expenses_cents', v_expenses,
    'expenses_scope', case when p_branch is null
      then 'all_business_expenses'
      else 'selected_branch_expenses_only_business_wide_overhead_excluded'
    end,
    'business_wide_overhead_excluded', p_branch is not null,
    'net_accrual_cents', v_accrual - v_expenses,
    'net_cash_cents', v_cash - v_expenses,
    'expenses_by_category', v_expenses_by_category,
    'monthly', v_monthly
  );
end $$;

--
-- Name: get_revenue_truth_v106(uuid, date, date, uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_revenue_truth_v106(p_business uuid, p_from date, p_to date, p_branch uuid DEFAULT NULL::uuid, p_as_of timestamp with time zone DEFAULT clock_timestamp()) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_currency text;
  v_period_currency text;
  v_currency_count integer;
  v_timezone text;
  v_result jsonb;
begin
  if auth.uid() is null then
    raise exception 'authentication required' using errcode = '42501';
  end if;
  if p_to <= p_from then
    raise exception 'p_to must be after p_from' using errcode = '22023';
  end if;
  if not (app.is_super_admin() or app.has_perm(p_business, 'view_finance')) then
    raise exception 'finance permission required' using errcode = '42501';
  end if;
  if not app.can_see_branch(p_business, p_branch) then
    raise exception 'branch is outside actor scope' using errcode = '42501';
  end if;
  if p_branch is not null and not exists (
    select 1 from public.branches b
     where b.id = p_branch and b.business_id = p_business
  ) then
    raise exception 'branch does not belong to business' using errcode = '23503';
  end if;
  select upper(b.currency) into strict v_currency
    from public.businesses b where b.id = p_business;
  if p_branch is null then
    v_timezone := 'per_outlet';
  else
    select b.timezone into strict v_timezone
      from public.branches b
     where b.id = p_branch and b.business_id = p_business;
  end if;
  select count(distinct c.currency), min(c.currency)
    into v_currency_count, v_period_currency
    from public.sales s
    cross join lateral app.v106_reporting_contract(
      s.business_id, s.branch_id, s.occurred_at
    ) c
   where s.business_id = p_business
     and s.reversal_of is null
     and s.counts_as_revenue
     and s.created_at <= p_as_of
     and (p_branch is null or s.branch_id = p_branch)
     and (s.occurred_at at time zone c.timezone)::date >= p_from
     and (s.occurred_at at time zone c.timezone)::date < p_to;
  if v_currency_count > 1 then
    raise exception 'cross-currency reporting periods are not supported'
      using errcode = '22023';
  end if;
  if v_currency_count = 1 then
    v_currency := v_period_currency;
  end if;

  with original_sales as materialized (
    select s.id,
           app.v111_effective_client_id(s.business_id, s.client_id) as client_id,
           s.amount_cents, s.occurred_at, s.created_at,
           s.branch_id, c.timezone, c.currency,
           coalesce((
             select abs(sum(r.amount_cents))
             from public.sales r
              cross join lateral app.v106_reporting_contract(
                r.business_id, r.branch_id, r.occurred_at
              ) rc
              where r.business_id = s.business_id
                and r.reversal_of = s.id
                and r.created_at <= p_as_of
                and (r.occurred_at at time zone rc.timezone)::date < p_to
           ), 0)::bigint as native_refund_minor,
           coalesce((
             select sum(a.amount_minor)
               from public.commerce_refund_allocations_v106 a
               join public.commerce_event_reconciliations_v106 rr
                 on rr.id = a.reconciliation_id and rr.business_id = a.business_id
               join public.commerce_events_v106 e
                 on e.id = a.event_id and e.business_id = a.business_id
              where a.business_id = s.business_id
                and a.sale_id = s.id
                and rr.created_at <= p_as_of
                and e.business_date < p_to
           ), 0)::bigint as external_refund_minor,
           exists (
             select 1 from public.sale_items i
              where i.business_id = s.business_id and i.sale_id = s.id
           ) as is_itemized,
           exists (
             select 1
               from public.commerce_event_reconciliations_v106 rr
               join public.commerce_events_v106 e
                 on e.id = rr.event_id
                and e.business_id = rr.business_id
              where rr.business_id = s.business_id
                and rr.sale_id = s.id
                and rr.created_at <= p_as_of
                and e.received_at <= p_as_of
                and e.event_type = 'transaction_completed'
                and e.branch_id is not distinct from s.branch_id
                and e.currency = c.currency
                and e.amount_minor = s.amount_cents
           ) as is_reconciled
      from public.sales s
      cross join lateral app.v106_reporting_contract(
        s.business_id, s.branch_id, s.occurred_at
      ) c
     where s.business_id = p_business
       and s.reversal_of is null
       and s.counts_as_revenue
       and s.created_at <= p_as_of
       and (p_branch is null or s.branch_id = p_branch)
       and (s.occurred_at at time zone c.timezone)::date >= p_from
       and (s.occurred_at at time zone c.timezone)::date < p_to
  ), eligible as (
    select *,
      app.v106_sale_residual_minor(id, p_to, p_as_of) as net_minor
      from original_sales
  ), totals as (
    select
      coalesce(sum(net_minor), 0)::bigint as known_revenue,
      coalesce(sum(net_minor) filter (where client_id is not null), 0)::bigint
        as identified_revenue,
      coalesce(sum(net_minor) filter (where client_id is null), 0)::bigint
        as anonymous_revenue,
      count(*) filter (where net_minor > 0)::bigint as completed_transactions,
      count(*) filter (where net_minor > 0 and client_id is not null)::bigint
        as identified_transactions,
      count(*) filter (where net_minor > 0 and client_id is null)::bigint
        as anonymous_transactions,
      count(*) filter (where net_minor > 0 and is_itemized)::bigint
        as itemized_transactions,
      count(*) filter (where net_minor > 0 and is_reconciled)::bigint
        as reconciled_transactions,
      max(occurred_at) as latest_sale_occurred_at,
      max(created_at) as latest_sale_recorded_at,
      count(*)::bigint as cohort_rows
    from eligible
  ), event_freshness as (
    select max(e.received_at) as latest_external_event_received_at
      from public.commerce_events_v106 e
     where e.business_id = p_business
       and (p_branch is null or e.branch_id = p_branch)
       and e.received_at <= p_as_of
  ), conflict_count as (
    select count(*)::bigint as conflicts
      from public.commerce_event_conflicts_v106 q
      join public.commerce_events_v106 e
        on e.id = q.existing_event_id and e.business_id = q.business_id
     where q.business_id = p_business and q.created_at <= p_as_of
       and (p_branch is null or e.branch_id = p_branch)
  )
  select jsonb_build_object(
    'contract_version', 'v106.1',
    'generated_at', clock_timestamp(),
    'as_of', p_as_of,
    'scope', jsonb_build_object(
      'business_id', p_business,
      'branch_id', p_branch,
      'period', jsonb_build_object(
        'from', p_from,
        'to', p_to,
        'interval', '[from,to)'
      ),
      'timezone', v_timezone,
      'timezone_contract', case when p_branch is null
        then 'per_outlet_effective_timezone'
        else 'selected_outlet_effective_timezone'
      end,
      'currency', v_currency
    ),
    'status', case when t.completed_transactions = 0 then 'no_data' else 'ok' end,
    'totals', jsonb_build_object(
      'known_revenue_minor', t.known_revenue,
      'identified_revenue_minor', t.identified_revenue,
      'anonymous_revenue_minor', t.anonymous_revenue,
      'completed_transactions', t.completed_transactions,
      'identified_transactions', t.identified_transactions,
      'anonymous_transactions', t.anonymous_transactions,
      'itemized_transactions', t.itemized_transactions
    ),
    'coverage', jsonb_build_object(
      'identity_revenue_pct', case when t.known_revenue = 0 then null
        else round(100 * t.identified_revenue::numeric / t.known_revenue, 2) end,
      'identity_transaction_pct', case when t.completed_transactions = 0 then null
        else round(100 * t.identified_transactions::numeric / t.completed_transactions, 2) end,
      'itemization_transaction_pct', case when t.completed_transactions = 0 then null
        else round(100 * t.itemized_transactions::numeric / t.completed_transactions, 2) end,
      'reconciled_transaction_pct', case when t.completed_transactions = 0 then null
        else round(100 * t.reconciled_transactions::numeric / t.completed_transactions, 2) end
    ),
    'freshness', jsonb_build_object(
      'latest_sale_occurred_at', t.latest_sale_occurred_at,
      'latest_sale_recorded_at', t.latest_sale_recorded_at,
      'latest_external_event_received_at', f.latest_external_event_received_at,
      'reconciliation_conflicts', q.conflicts
    ),
    'formula_metadata', jsonb_build_object(
      'version', 'revenue_truth_v106_1',
      'eligible_sale', 'original sale with counts_as_revenue=true and created_at<=as_of',
      'period_assignment', 'sale occurred_at converted by its effective outlet timezone',
      'known_revenue', 'sum(max(original_amount-native_full_reversal-reconciled_external_refund_allocations,0))',
      'identity_split', 'identified iff the v111 current-attribution resolver returns a client_id; otherwise anonymous',
      'identity_attribution', 'immutable sales.client_id is resolved through app.v111_effective_client_id for current synchronized reporting',
      'invariant', 'known_revenue_minor = identified_revenue_minor + anonymous_revenue_minor',
      'refund_cutoff', 'refund business date is before report p_to and recorded by as_of',
      'zero_denominator', 'coverage ratios are null'
    ),
    'limitations', jsonb_build_array(
      'Known revenue covers the Peekaa sales ledger; it is not merchant-total revenue until a POS adapter proves source completeness.',
      'External transaction observations do not affect totals until reconciled to an existing sale.',
      'Legacy pre-v106 facts use an explicit migration-time timezone/currency assumption.',
      'Native reversals are full-sale only; v106 external allocations provide partial-refund attribution without rewriting old ledgers.'
    )
  ) into v_result
  from totals t cross join event_freshness f cross join conflict_count q;

  if (v_result #>> '{totals,known_revenue_minor}')::bigint <>
     (v_result #>> '{totals,identified_revenue_minor}')::bigint +
     (v_result #>> '{totals,anonymous_revenue_minor}')::bigint then
    raise exception 'v106 revenue identity invariant failed'
      using errcode = 'data_exception';
  end if;
  return v_result;
end $$;

--
-- Name: get_rule_allowlists(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_rule_allowlists(p_business uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_result jsonb;
begin
  if not (app.is_salon_member(p_business) or app.is_super_admin()) then raise exception 'access denied' using errcode='42501'; end if;
  select jsonb_build_object(
    'schema_versions', coalesce((select jsonb_agg(jsonb_build_object('schema_version',schema_version,'status',status) order by schema_version) from public.rule_schema_versions),'[]'::jsonb),
    'events', coalesce((select jsonb_agg(distinct ev order by ev) from (
        select event_type ev from public.rule_condition_allowlist
        union select event_type from public.rule_effect_allowlist) s),'[]'::jsonb),
    'conditions', coalesce((select jsonb_agg(jsonb_build_object(
        'schema_version',schema_version,'event_type',event_type,'field',field,'value_type',value_type,
        'operators',to_jsonb(operators),'catalog_kind',catalog_kind
      ) order by schema_version,event_type,field) from public.rule_condition_allowlist),'[]'::jsonb),
    'effects', coalesce((select jsonb_agg(jsonb_build_object(
        'schema_version',schema_version,'event_type',event_type,'effect_type',effect_type,
        'requires_catalog_ref',requires_catalog_ref,'catalog_kind',catalog_kind,'moves_value',moves_value
      ) order by schema_version,event_type,effect_type) from public.rule_effect_allowlist),'[]'::jsonb)
  ) into v_result;
  return v_result;
end $$;

--
-- Name: get_sale_policy(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_sale_policy(p_business uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if not app.is_salon_member(p_business) then raise exception 'not a member of this business'; end if;
  return (select coalesce(json_agg(row_to_json(p) order by p.kind), '[]'::json)
          from app.sale_policy_set(p_business) p);
end $$;

--
-- Name: get_self_serve_checkout_v130(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_self_serve_checkout_v130(p_business uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_email text;
  v_is_super_admin boolean := app.is_super_admin();
  v_onboarding public.self_serve_business_onboarding_v130%rowtype;
begin
  if v_actor is null then
    raise exception 'authenticated session required' using errcode = '28000';
  end if;
  select lower(email) into v_email from auth.users
   where id = v_actor and coalesce(email_confirmed_at, confirmed_at) is not null;
  if v_email is null then
    raise exception 'confirmed owner email required' using errcode = '42501';
  end if;
  select onboarding.* into v_onboarding
    from public.self_serve_business_onboarding_v130 onboarding
   where (onboarding.owner_user_id = v_actor
          or (v_is_super_admin and p_business is not null))
     and (p_business is null or onboarding.business_id = p_business);
  if p_business is not null and not found and not v_is_super_admin then
    raise exception 'self-service onboarding access required' using errcode = '42501';
  end if;
  return jsonb_build_object(
    'onboarding', case when v_onboarding.business_id is null then null else
      jsonb_build_object(
        'business_id', v_onboarding.business_id,
        'business_slug', v_onboarding.business_slug,
        'business_name', v_onboarding.business_name,
        'owner_name', v_onboarding.owner_name,
        'sector_key', v_onboarding.sector_key,
        'cadence', v_onboarding.selected_cadence,
        'customer_capacity', v_onboarding.selected_customer_capacity,
        'status', v_onboarding.status,
        'checkout_command_id', v_onboarding.checkout_command_id,
        'activated_at', v_onboarding.activated_at,
        'legal_document_version', v_onboarding.legal_document_version,
        'total_cents', app.self_serve_plan_total_v130(
          (select catalog from public.billing_plan_catalog_v124 catalog
            where catalog.id = v_onboarding.billing_catalog_id_v124),
          v_onboarding.selected_customer_capacity
        )
      ) end,
    'plans', coalesce((
      select jsonb_agg(jsonb_build_object(
        'cadence', catalog.cadence,
        'cadence_months', catalog.cadence_months,
        'base_amount_cents', catalog.base_amount_cents,
        'included_customer_capacity', catalog.included_customer_capacity,
        'capacity_block_size', catalog.capacity_block_size,
        'capacity_block_amount_cents', catalog.capacity_block_amount_cents,
        'compare_at_monthly_cents', catalog.compare_at_monthly_cents,
        'tax_behavior', catalog.tax_behavior
      ) order by case catalog.cadence when 'annual' then 0 else 1 end)
      from public.billing_plan_catalog_v124 catalog
      where catalog.currency = 'SGD' and catalog.active
        and catalog.effective_from <= now()
        and (catalog.effective_to is null or catalog.effective_to > now())
    ), '[]'::jsonb),
    'sectors', coalesce((
      select jsonb_agg(jsonb_build_object(
        'sector_key', profile.sector_key, 'label', profile.label
      ) order by profile.label)
      from public.sector_profiles profile
      where profile.active and exists (
        select 1 from public.sector_bundle_versions bundle
         where bundle.sector_key = profile.sector_key
           and bundle.status = 'published'
           and 'loyalty' = any(bundle.modules)
      )
    ), '[]'::jsonb),
    'gst_registered', false,
    'money_back_days', case
      when v_onboarding.business_id is not null
       and v_onboarding.legal_document_version < '2026-08-03' then 30
      else null
    end,
    'refund_policy', case
      when v_onboarding.business_id is not null
       and v_onboarding.legal_document_version < '2026-08-03'
        then 'legacy_30_day_request'
      else 'non_refundable_after_payment'
    end,
    'included_modules', jsonb_build_array(
      'Customer CRM and QR signup', 'Loyalty points, stamps and rewards',
      'Birthday benefits and referrals', 'Appointments, team schedule and waitlist',
      'Record sale and sales history', 'Packages, memberships and gift cards',
      'Customer wallet, history and redemption', 'Promotions and template-assisted promotion wording',
      'Feedback and Google review handoff', 'Configured notifications',
      'Profitability and operational reports', 'Branches, roles and permissions',
      'English, Simplified Chinese and Malay business UI'
    )
  );
end;
$$;

--
-- Name: get_sellable_sv_topup_plans(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_sellable_sv_topup_plans(p_business uuid, p_branch uuid, p_client uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_rows jsonb;
begin
  if not app.can_sell_topups(p_business) then raise exception 'not permitted to sell top-ups for this business' using errcode = '42501'; end if;
  select coalesce(jsonb_agg(app.sv_topup_projection(p_business, p_branch, p_client, cur.vid) order by cur.name), '[]'::jsonb)
    into v_rows
    from (select s.id as plan_id, s.name, app.current_sellable_sv_version(p_business, s.id) as vid
            from public.sv_plans s where s.business_id = p_business and s.active) cur
   where cur.vid is not null;
  return jsonb_build_object('business_id', p_business, 'branch_id', p_branch, 'client_id', p_client, 'plans', v_rows);
end $$;

--
-- Name: get_shadow_comparison(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_shadow_comparison(p_business uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if not (app.is_salon_owner(p_business) or app.is_super_admin()) then raise exception 'owner only' using errcode = '42501'; end if;
  return app.compare_shadow_vs_live(p_business, 'referral');
end $$;

--
-- Name: get_studio_dead_letters(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_studio_dead_letters(p_business uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_result jsonb;
begin
  if not (app.is_salon_owner(p_business) or app.is_super_admin()) then raise exception 'owner only' using errcode = '42501'; end if;
  select coalesce(jsonb_agg(jsonb_build_object(
    'outbox_id', o.id, 'event_id', o.event_id, 'consumer', o.consumer, 'delivery_status', o.delivery_status,
    'attempts', o.attempts, 'last_error', o.last_error, 'next_attempt_at', o.next_attempt_at) order by o.updated_at desc), '[]'::jsonb)
    into v_result from public.event_outbox o
   where o.business_id = p_business and o.delivery_status in ('failed','dead_letter');
  return jsonb_build_object('business_id', p_business, 'dead_letters', v_result);
end $$;

--
-- Name: get_studio_sales_baseline_v145(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_studio_sales_baseline_v145(p_business uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_count bigint; v_average bigint;
begin
  if auth.uid() is null or not app.is_salon_owner(p_business) then
    raise exception 'owner only' using errcode = '42501';
  end if;
  perform app.require_metric_module_scope_v145(p_business, null, 'sales');
  select count(*), coalesce(round(avg(sale.amount_cents)), 0)::bigint
    into v_count, v_average
    from public.sales sale
   where sale.business_id = p_business
     and sale.reversal_of is null
     and sale.counts_as_revenue
     and sale.occurred_at >= now() - interval '30 days'
     and not exists (
       select 1 from public.sales reversal
        where reversal.business_id = sale.business_id
          and reversal.reversal_of = sale.id
     );
  return jsonb_build_object(
    'available', true,
    'count30', v_count,
    'avg_bill_cents', coalesce(v_average, 0)
  );
end;
$$;

--
-- Name: get_sv_account(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_sv_account(p_business uuid, p_client uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_account uuid;
  v_state text;
  v_total int; v_paid int; v_bonus int;
  v_lots jsonb; v_moves jsonb;
begin
  if not (app.is_salon_member(p_business) or app.is_super_admin()) then
    raise exception 'not permitted to view stored value for this business' using errcode = '42501';
  end if;
  if not exists (select 1 from public.clients c where c.id = p_client and c.business_id = p_business) then
    raise exception 'stored-value client does not belong to this business' using errcode = '22023';
  end if;

  select id into v_account from public.sv_accounts
   where business_id = p_business and client_id = p_client and asset = 'stored_value';

  select coalesce(state, 'unbuilt') into v_state from public.sv_authority
   where business_id = p_business and asset = 'stored_value';
  v_state := coalesce(v_state, 'unbuilt');   -- fail closed if no authority row

  if v_account is null then
    v_total := 0; v_paid := 0; v_bonus := 0; v_lots := '[]'::jsonb; v_moves := '[]'::jsonb;
  else
    v_total := app.sv_available_balance(p_business, v_account);
    v_paid := app.sv_class_balance(p_business, v_account, 'paid');
    v_bonus := app.sv_class_balance(p_business, v_account, 'bonus');
    select coalesce(jsonb_agg(jsonb_build_object(
        'lot_id', l.id, 'class', l.class, 'minted_cents', l.minted_cents,
        'remaining_cents', app.sv_lot_remaining(l.id), 'expiry_key', l.expiry_key,
        'earned_seq', l.earned_seq, 'plan_version_id', l.plan_version_id) order by l.earned_seq), '[]'::jsonb)
      into v_lots from public.sv_lots l
     where l.business_id = p_business and l.account_id = v_account;
    select coalesce(jsonb_agg(jsonb_build_object(
        'movement_id', t.id, 'lot_id', t.lot_id, 'kind', t.kind,
        'cents', t.cents, 'created_at', t.created_at) order by t.created_at desc, t.id), '[]'::jsonb)
      into v_moves
      from (select mv.id, mv.lot_id, mv.kind, mv.cents, mv.created_at
              from public.sv_lot_movements mv
             where mv.business_id = p_business and mv.account_id = v_account
             order by mv.created_at desc, mv.id limit 50) t;
  end if;

  return jsonb_build_object(
    'business_id', p_business,
    'client_id', p_client,
    'account_id', v_account,
    'asset', 'stored_value',
    'authority_state', v_state,
    'spendable', (v_state = 'live'),
    'shadow_testing', (v_state = 'shadow_testing'),
    'disclaimer', case when v_state = 'live' then null else 'simulated — not spendable' end,
    'balances', jsonb_build_object('total_cents', v_total, 'paid_cents', v_paid, 'bonus_cents', v_bonus),
    'lots', v_lots,
    'recent_movements', v_moves);
end $$;

--
-- Name: get_sv_authority_overview(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_sv_authority_overview(p_business uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_asset text := 'stored_value';
  v_state text;
  v_snapshot public.sv_reconciliation_snapshots%rowtype;
  v_has_run boolean;
  v_pauses jsonb;
begin
  if not (app.is_salon_owner(p_business) or app.is_super_admin()) then
    raise exception 'not permitted to view stored-value authority for this business' using errcode = '42501';
  end if;

  select coalesce(state, 'unbuilt') into v_state from public.sv_authority
   where business_id = p_business and asset = v_asset;
  v_state := coalesce(v_state, 'unbuilt');   -- fail closed if no authority row

  select * into v_snapshot from public.sv_reconciliation_snapshots
   where business_id = p_business and asset = v_asset
   order by captured_at desc, id desc limit 1;
  v_has_run := found;

  select coalesce(jsonb_agg(jsonb_build_object(
      'scope', p.scope, 'reason', p.reason, 'actor', p.actor, 'paused_at', p.paused_at)
      order by p.scope, p.paused_at desc), '[]'::jsonb)
    into v_pauses
    from public.sv_pauses p
   where p.business_id = p_business and p.asset = v_asset and p.lifted_at is null;

  return jsonb_build_object(
    'business_id', p_business,
    'asset', v_asset,
    'authority_state', v_state,
    'spendable', (v_state = 'live'),
    'shadow_testing', (v_state = 'shadow_testing'),
    'reconciliation', jsonb_build_object(
      'has_run', v_has_run,
      'status', case when v_has_run then v_snapshot.status else null end,
      'discrepancy_count', case when v_has_run then v_snapshot.discrepancy_count else 0 end),
    'active_pauses', v_pauses,
    'can_cutover', coalesce((app.sv_cutover_readiness(p_business) ->> 'ready')::boolean, false));
end $$;

--
-- Name: get_sv_plans(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_sv_plans(p_business uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_plans jsonb; v_drafts jsonb; v_warn integer; v_hard integer;
begin
  if not (app.is_salon_owner(p_business) or app.is_super_admin()) then
    raise exception 'not permitted to view stored-value plans for this business' using errcode = '42501';
  end if;
  select coalesce(warn_discount_bps,3000), coalesce(hard_discount_bps,7000) into v_warn, v_hard
    from public.sv_plan_guardrails where business_id = p_business;
  v_warn := coalesce(v_warn,3000); v_hard := coalesce(v_hard,7000);

  select coalesce(jsonb_agg(jsonb_build_object(
      'plan_id', s.id, 'name', s.name, 'active', s.active,
      'versions', (select coalesce(jsonb_agg(app.sv_plan_version_json(pv) order by pv.version_no desc), '[]'::jsonb)
                     from public.sv_plan_versions pv where pv.plan_id = s.id and pv.business_id = p_business),
      'status_history', (select coalesce(jsonb_agg(jsonb_build_object(
          'prior_status', e.prior_status, 'new_status', e.new_status, 'reason', e.reason,
          'actor', e.actor, 'at', e.created_at) order by e.created_at desc), '[]'::jsonb)
        from public.sv_plan_status_events e where e.plan_id = s.id and e.business_id = p_business))
      order by s.created_at desc), '[]'::jsonb)
    into v_plans from public.sv_plans s where s.business_id = p_business;

  select coalesce(jsonb_agg(app.sv_plan_draft_json(d) order by d.created_at desc), '[]'::jsonb)
    into v_drafts from public.sv_plan_drafts d where d.business_id = p_business and d.status = 'draft';

  return jsonb_build_object('business_id', p_business, 'plans', v_plans, 'open_drafts', v_drafts,
    'guardrails', jsonb_build_object('warn_discount_bps', v_warn, 'hard_discount_bps', v_hard));
end $$;

--
-- Name: get_sv_reconciliation(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_sv_reconciliation(p_business uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_asset text := 'stored_value';
  v_authority text;
  v_snapshot public.sv_reconciliation_snapshots%rowtype;
  v_discrepancies jsonb;
begin
  if not (app.is_salon_owner(p_business) or app.is_super_admin()) then
    raise exception 'not permitted to view stored-value reconciliation for this business' using errcode = '42501';
  end if;

  select coalesce(state, 'unbuilt') into v_authority from public.sv_authority
   where business_id = p_business and asset = v_asset;
  v_authority := coalesce(v_authority, 'unbuilt');   -- fail closed if no authority row

  select * into v_snapshot from public.sv_reconciliation_snapshots
   where business_id = p_business and asset = v_asset
   order by captured_at desc, id desc limit 1;

  if not found then
    return jsonb_build_object(
      'business_id', p_business,
      'asset', v_asset,
      'authority_state', v_authority,
      'has_run', false,
      'latest_snapshot', null,
      'discrepancies', '[]'::jsonb);
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
      'discrepancy_id', d.id, 'category', d.category, 'legacy_ref', d.legacy_ref,
      'client_id', d.client_id, 'legacy_cents', d.legacy_cents, 'studio_cents', d.studio_cents,
      'delta_cents', d.delta_cents, 'detail', d.detail) order by d.category, d.legacy_ref), '[]'::jsonb)
    into v_discrepancies
    from public.sv_reconciliation_discrepancies d
   where d.business_id = p_business and d.run_id = v_snapshot.run_id;

  return jsonb_build_object(
    'business_id', p_business,
    'asset', v_asset,
    'authority_state', v_authority,
    'has_run', true,
    'latest_snapshot', jsonb_build_object(
      'snapshot_id', v_snapshot.id, 'run_id', v_snapshot.run_id, 'captured_at', v_snapshot.captured_at,
      'source', v_snapshot.source, 'status', v_snapshot.status,
      'legacy_total_cents', v_snapshot.legacy_total_cents, 'studio_total_cents', v_snapshot.studio_total_cents,
      'acknowledged_cents', v_snapshot.acknowledged_cents,
      'discrepancy_count', v_snapshot.discrepancy_count),
    'discrepancies', v_discrepancies);
end $$;

--
-- Name: get_workspace_locale_preference_v97(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_workspace_locale_preference_v97() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_user uuid:=auth.uid();
  v_row public.workspace_locale_preferences_v97%rowtype;
begin
  if v_user is null then
    raise exception using errcode='42501',message='authentication required';
  end if;
  select * into v_row
    from public.workspace_locale_preferences_v97
   where auth_user_id=v_user;
  return jsonb_build_object(
    'locale',coalesce(v_row.locale,'en'),
    'version',coalesce(v_row.version,0)
  );
end
$$;

--
-- Name: import_bookings(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.import_bookings(p_business uuid, p_rows jsonb) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  r jsonb; v_inserted int := 0; v_skipped int := 0; v_errors jsonb := '[]'::jsonb; v_idx int := 0;
  v_name text; v_phone text; v_email text; v_party int; v_pref timestamptz; v_notes text;
  v_tt uuid; v_ttname text;
begin
  if not app.is_salon_owner(p_business) then raise exception 'not authorized'; end if;
  if p_rows is null or jsonb_typeof(p_rows) <> 'array' then
    raise exception 'p_rows must be a JSON array';
  end if;
  perform set_config('app.suppress_booking_notify','on', true);   -- no toast per row

  for r in select * from jsonb_array_elements(p_rows) loop
    v_idx := v_idx + 1;
    begin
      v_name  := nullif(trim(coalesce(r->>'name','')),'');
      if v_name is null or length(v_name) < 2 then
        v_skipped := v_skipped + 1;
        v_errors  := v_errors || jsonb_build_object('row', v_idx, 'error', 'missing/short name');
        continue;
      end if;
      v_phone := nullif(trim(coalesce(r->>'phone','')),'');
      v_email := nullif(trim(coalesce(r->>'email','')),'');
      v_notes := nullif(trim(coalesce(r->>'notes','')),'');
      begin v_party := nullif(r->>'party_size','')::int; exception when others then v_party := null; end;
      begin v_pref  := nullif(r->>'preferred_at','')::timestamptz; exception when others then v_pref := null; end;

      v_tt := null;
      if coalesce(r->>'table_type_id','') <> '' then
        begin v_tt := (r->>'table_type_id')::uuid; exception when others then v_tt := null; end;
        if v_tt is not null then
          perform 1 from public.booking_tables where id = v_tt and business_id = p_business;
          if not found then v_tt := null; end if;
        end if;
      end if;
      if v_tt is null then
        v_ttname := nullif(trim(coalesce(r->>'table_type','')),'');
        if v_ttname is not null then
          select id into v_tt from public.booking_tables
           where business_id = p_business and active and lower(name) = lower(v_ttname) limit 1;
        end if;
      end if;

      insert into public.booking_requests (business_id, name, email, phone, party_size,
                                           preferred_at, notes, status, table_type_id)
      values (p_business, v_name, v_email, v_phone, v_party, v_pref, v_notes, 'new', v_tt);
      v_inserted := v_inserted + 1;
    exception when others then
      v_skipped := v_skipped + 1;
      v_errors  := v_errors || jsonb_build_object('row', v_idx, 'error', SQLERRM);
    end;
  end loop;

  return json_build_object('inserted', v_inserted, 'skipped', v_skipped, 'errors', v_errors);
end $$;

--
-- Name: ingest_external_commerce_event_v106(uuid, uuid, text, text, text, text, timestamp with time zone, text, bigint, jsonb, text, uuid, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ingest_external_commerce_event_v106(p_business uuid, p_branch uuid, p_event_type text, p_source_system text, p_source_event_id text, p_idempotency_key text, p_occurred_at timestamp with time zone, p_currency text, p_amount_minor bigint, p_payload jsonb DEFAULT '{}'::jsonb, p_actor_type text DEFAULT 'integration'::text, p_actor_id uuid DEFAULT NULL::uuid, p_causation_id text DEFAULT NULL::text, p_correlation_id text DEFAULT NULL::text, p_supersedes_event_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_source_lock text;
  v_request_lock text;
  v_identity text;
  v_hash text;
  v_receipt jsonb;
  v_existing_hash text;
begin
  if v_actor is null then
    raise exception 'authentication required' using errcode = '42501';
  end if;
  if not (
    app.is_super_admin()
    or (
      lower(btrim(p_event_type)) in (
        'refund_completed', 'chargeback_opened', 'chargeback_reversed'
      )
      and app.has_perm(p_business, 'refund_sales')
    )
    or (
      lower(btrim(p_event_type)) in (
        'transaction_completed', 'transaction_voided'
      )
      and app.has_perm(p_business, 'create_sales')
    )
  ) then
    raise exception 'sale-write permission required for this external event'
      using errcode = '42501';
  end if;
  if not app.can_see_branch(p_business, p_branch) then
    raise exception 'branch is outside actor scope' using errcode = '42501';
  end if;
  if p_branch is not null and not exists (
    select 1
    from public.branches b
    where b.id = p_branch and b.business_id = p_business
  ) then
    raise exception 'branch does not belong to business' using errcode = '23503';
  end if;
  v_source_lock := concat_ws(
    ':', 'v112-v106-source', p_business,
    lower(btrim(p_source_system)), btrim(p_source_event_id),
    lower(btrim(p_event_type))
  );
  v_request_lock := concat_ws(
    ':', 'v112-v106-idempotency', p_business,
    lower(btrim(p_source_system)), btrim(p_idempotency_key)
  );
  v_identity := app.v112_hash(jsonb_build_object(
    'operation', 'ingest_external_commerce_event_v106',
    'business_id', p_business,
    'source_system', lower(btrim(p_source_system)),
    'idempotency_key', btrim(p_idempotency_key)
  ));
  v_hash := app.v112_hash(jsonb_build_object(
    'business_id', p_business, 'branch_id', p_branch,
    'event_type', lower(btrim(p_event_type)),
    'source_system', lower(btrim(p_source_system)),
    'source_event_id', btrim(p_source_event_id),
    'idempotency_key', btrim(p_idempotency_key),
    'occurred_at', p_occurred_at, 'currency', upper(p_currency),
    'amount_minor', p_amount_minor, 'payload', p_payload,
    'actor_type', lower(btrim(p_actor_type)), 'actor_id', p_actor_id,
    'causation_id', p_causation_id, 'correlation_id', p_correlation_id,
    'supersedes_event_id', p_supersedes_event_id
  ));
  perform app.v112_lock_pair(v_source_lock, v_request_lock);
  select request_hash, receipt
  into v_existing_hash, v_receipt
  from public.concurrent_operation_receipts_v112
  where request_identity = v_identity;
  if v_receipt is not null then
    if v_existing_hash = v_hash then
      return v_receipt;
    end if;
    -- Let the canonical source identity decide this conflict.  A materially
    -- changed replay of the same source is quarantined by v106; a reused
    -- idempotency key for a different source still raises 23505.
    return public.ingest_external_commerce_event_v106_v112_inner(
      p_business, p_branch, p_event_type, p_source_system, p_source_event_id,
      p_idempotency_key, p_occurred_at, p_currency, p_amount_minor, p_payload,
      p_actor_type, p_actor_id, p_causation_id, p_correlation_id,
      p_supersedes_event_id
    );
  end if;
  v_receipt := public.ingest_external_commerce_event_v106_v112_inner(
    p_business, p_branch, p_event_type, p_source_system, p_source_event_id,
    p_idempotency_key, p_occurred_at, p_currency, p_amount_minor, p_payload,
    p_actor_type, p_actor_id, p_causation_id, p_correlation_id,
    p_supersedes_event_id
  );
  return app.v112_put_receipt(
    v_identity, 'ingest_external_commerce_event_v106', v_hash,
    jsonb_build_object(
      'business_id', p_business,
      'source_system', lower(btrim(p_source_system)),
      'source_event_id', btrim(p_source_event_id)
    ),
    v_receipt
  );
end $$;

--
-- Name: ingest_external_commerce_event_v106_v112_inner(uuid, uuid, text, text, text, text, timestamp with time zone, text, bigint, jsonb, text, uuid, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ingest_external_commerce_event_v106_v112_inner(p_business uuid, p_branch uuid, p_event_type text, p_source_system text, p_source_event_id text, p_idempotency_key text, p_occurred_at timestamp with time zone, p_currency text, p_amount_minor bigint, p_payload jsonb DEFAULT '{}'::jsonb, p_actor_type text DEFAULT 'integration'::text, p_actor_id uuid DEFAULT NULL::uuid, p_causation_id text DEFAULT NULL::text, p_correlation_id text DEFAULT NULL::text, p_supersedes_event_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_contract record;
  v_envelope jsonb;
  v_hash text;
  v_existing public.commerce_events_v106%rowtype;
  v_event public.commerce_events_v106%rowtype;
begin
  if auth.uid() is null then
    raise exception 'authentication required' using errcode = '42501';
  end if;
  if not (
    app.is_super_admin()
    or (
      lower(btrim(p_event_type)) in ('refund_completed', 'chargeback_opened', 'chargeback_reversed')
      and app.has_perm(p_business, 'refund_sales')
    )
    or (
      lower(btrim(p_event_type)) in ('transaction_completed', 'transaction_voided')
      and app.has_perm(p_business, 'create_sales')
    )
  ) then
    raise exception 'sale-write permission required for this external event'
      using errcode = '42501';
  end if;
  if not app.can_see_branch(p_business, p_branch) then
    raise exception 'branch is outside actor scope' using errcode = '42501';
  end if;
  if p_branch is not null and not exists (
    select 1 from public.branches b
     where b.id = p_branch and b.business_id = p_business
  ) then
    raise exception 'branch does not belong to business' using errcode = '23503';
  end if;
  if p_payload is null or jsonb_typeof(p_payload) <> 'object' then
    raise exception 'payload must be a JSON object' using errcode = '22023';
  end if;

  select * into strict v_contract
    from app.v106_reporting_contract(p_business, p_branch, p_occurred_at);
  if upper(p_currency) <> v_contract.currency then
    raise exception 'event currency % differs from effective reporting currency %',
      upper(p_currency), v_contract.currency using errcode = '22023';
  end if;

  v_envelope := jsonb_build_object(
    'event_type', lower(btrim(p_event_type)),
    'source_system', lower(btrim(p_source_system)),
    'source_event_id', btrim(p_source_event_id),
    'occurred_at', p_occurred_at,
    'currency', upper(p_currency),
    'amount_minor', p_amount_minor,
    'actor_type', lower(btrim(p_actor_type)),
    'actor_id', p_actor_id,
    'causation_id', p_causation_id,
    'correlation_id', p_correlation_id,
    'supersedes_event_id', p_supersedes_event_id,
    'payload', p_payload
  );
  v_hash := encode(
    extensions.digest(convert_to(v_envelope::text, 'UTF8'), 'sha256'), 'hex'
  );

  select * into v_existing
    from public.commerce_events_v106 e
   where e.business_id = p_business
     and e.source_system = lower(btrim(p_source_system))
     and e.source_event_id = btrim(p_source_event_id)
     and e.event_type = lower(btrim(p_event_type));
  if found then
    if v_existing.payload_hash = v_hash then
      return jsonb_build_object(
        'status', 'replayed',
        'event_id', v_existing.id,
        'payload_hash', v_hash,
        'ledger_changed', false
      );
    end if;
    insert into public.commerce_event_conflicts_v106(
      business_id, existing_event_id, source_system, source_event_id, event_type,
      received_idempotency_key, existing_payload_hash, received_payload_hash,
      received_envelope
    ) values (
      p_business, v_existing.id, lower(btrim(p_source_system)), btrim(p_source_event_id),
      lower(btrim(p_event_type)), btrim(p_idempotency_key),
      v_existing.payload_hash, v_hash, v_envelope
    );
    return jsonb_build_object(
      'status', 'quarantined',
      'event_id', v_existing.id,
      'existing_payload_hash', v_existing.payload_hash,
      'received_payload_hash', v_hash,
      'ledger_changed', false
    );
  end if;

  insert into public.commerce_events_v106(
    business_id, branch_id, event_type, source_system, source_event_id,
    idempotency_key, occurred_at, business_date, reporting_contract_id,
    timezone, currency, amount_minor, actor_type, actor_id, causation_id,
    correlation_id, supersedes_event_id, payload, payload_hash
  ) values (
    p_business, p_branch, lower(btrim(p_event_type)), lower(btrim(p_source_system)),
    btrim(p_source_event_id), btrim(p_idempotency_key), p_occurred_at,
    (p_occurred_at at time zone v_contract.timezone)::date, v_contract.contract_id,
    v_contract.timezone, upper(p_currency), p_amount_minor,
    lower(btrim(p_actor_type)), p_actor_id, nullif(btrim(p_causation_id), ''),
    nullif(btrim(p_correlation_id), ''), p_supersedes_event_id, p_payload, v_hash
  ) returning * into v_event;

  return jsonb_build_object(
    'status', 'accepted',
    'event_id', v_event.id,
    'business_date', v_event.business_date,
    'timezone', v_event.timezone,
    'currency', v_event.currency,
    'payload_hash', v_event.payload_hash,
    'ledger_changed', false
  );
exception
  when unique_violation then
    select * into v_existing
      from public.commerce_events_v106 e
     where e.business_id = p_business
       and e.source_system = lower(btrim(p_source_system))
       and e.idempotency_key = btrim(p_idempotency_key);
    if found and v_existing.payload_hash = v_hash then
      return jsonb_build_object(
        'status', 'replayed',
        'event_id', v_existing.id,
        'payload_hash', v_hash,
        'ledger_changed', false
      );
    end if;
    raise exception 'idempotency key was already used for a different event'
      using errcode = '23505';
end $$;

--
-- Name: ingest_stripe_billing_event_v77(text, text, text, timestamp with time zone, boolean, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ingest_stripe_billing_event_v77(p_event_id text, p_event_type text, p_object_id text, p_event_created_at timestamp with time zone, p_livemode boolean, p_payload jsonb, p_payload_sha256 text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $_$
declare
  v_existing public.billing_provider_events%rowtype;
  v_inserted uuid;
begin
  if p_event_id !~ '^evt_[A-Za-z0-9_]+$'
     or nullif(btrim(p_event_type),'') is null
     or nullif(btrim(p_object_id),'') is null
     or p_event_created_at is null
     or p_livemode is null
     or jsonb_typeof(p_payload) <> 'object'
     or p_payload_sha256 !~ '^[0-9a-f]{64}$' then
    raise exception 'invalid Stripe event envelope' using errcode = '22023';
  end if;

  insert into public.billing_provider_events(
    event_id,event_type,object_id,event_created_at,livemode,api_version,
    payload,payload_sha256
  ) values (
    p_event_id,p_event_type,p_object_id,p_event_created_at,p_livemode,
    nullif(p_payload->>'api_version',''),p_payload,p_payload_sha256
  )
  on conflict(provider,event_id) do nothing
  returning id into v_inserted;

  if v_inserted is not null then
    return jsonb_build_object('event_id',p_event_id,'status','accepted','duplicate',false);
  end if;

  select * into strict v_existing
    from public.billing_provider_events
   where provider = 'stripe' and event_id = p_event_id;
  if v_existing.event_type <> p_event_type
     or v_existing.object_id <> p_object_id
     or v_existing.event_created_at <> p_event_created_at
     or v_existing.livemode <> p_livemode
     or v_existing.payload <> p_payload
     or v_existing.payload_sha256 <> p_payload_sha256 then
    raise exception 'Stripe event id conflicts with a different envelope'
      using errcode = '22023';
  end if;
  return jsonb_build_object(
    'event_id',p_event_id,'status',v_existing.processing_status,'duplicate',true
  );
end
$_$;

--
-- Name: ingest_stripe_connect_event_v142(text, text, text, text, boolean, timestamp with time zone, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ingest_stripe_connect_event_v142(p_event_id text, p_connected_account_id text, p_event_type text, p_object_id text, p_livemode boolean, p_event_created_at timestamp with time zone, p_payload jsonb, p_payload_sha256 text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_existing public.stripe_connect_event_inbox_v142%rowtype;
        v_inserted boolean := false;
begin
  perform app.v142_service_guard();
  insert into public.stripe_connect_event_inbox_v142(
    event_id,connected_account_id,event_type,object_id,livemode,event_created_at,payload,payload_sha256)
  values(p_event_id,p_connected_account_id,p_event_type,p_object_id,p_livemode,p_event_created_at,p_payload,p_payload_sha256)
  on conflict(event_id) do nothing returning * into v_existing;
  v_inserted:=found;
  if not v_inserted then
    select * into v_existing from public.stripe_connect_event_inbox_v142 where event_id=p_event_id;
  end if;
  if v_existing.payload_sha256 is distinct from p_payload_sha256
     or v_existing.connected_account_id is distinct from p_connected_account_id then
    raise exception 'Stripe Connect event replay conflict' using errcode='22023';
  end if;
  return jsonb_build_object('event_id',p_event_id,'duplicate',not v_inserted);
end $$;

--
-- Name: internal_claim_ai_firm_report_v176(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.internal_claim_ai_firm_report_v176() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_id uuid;
  v_row public.ai_firm_reports_v176%rowtype;
  v_evidence jsonb;
begin
  select report.id into v_id
  from public.ai_firm_reports_v176 report
  where report.status = 'pending'
  order by report.created_at, report.id
  for update skip locked
  limit 1;

  if v_id is null then
    return pg_catalog.jsonb_build_object('claimed', false);
  end if;

  select report.* into v_row
  from public.ai_firm_reports_v176 report
  where report.id = v_id;

  v_evidence := app.v176_evidence_pack(
    v_row.business_id, v_row.period_kind, v_row.period_start, v_row.period_end
  );

  update public.ai_firm_reports_v176 report
  set status = 'generating',
      claimed_at = now(),
      evidence = v_evidence,
      error = null,
      model = coalesce(
        report.model, app.v176_model_for_period(report.period_kind)
      )
  where report.id = v_id
  returning * into v_row;

  return pg_catalog.jsonb_build_object(
    'claimed', true,
    'report', to_jsonb(v_row)
  );
end
$$;

--
-- Name: FUNCTION internal_claim_ai_firm_report_v176(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.internal_claim_ai_firm_report_v176() IS 'Service-role queue claim: oldest pending report -> generating, with the evidence pack assembled and stored at claim time. FOR UPDATE SKIP LOCKED.';

--
-- Name: internal_claim_receipt_for_extraction_v199(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.internal_claim_receipt_for_extraction_v199() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_row public.platform_accounting_receipts_v199%rowtype;
begin
  if current_setting('role',true) is distinct from 'service_role'
     and auth.role() is distinct from 'service_role' then
    raise exception 'service role is required' using errcode='42501';
  end if;
  select * into v_row from public.platform_accounting_receipts_v199
   where status='uploaded'
   order by created_at
   for update skip locked
   limit 1;
  if not found then return jsonb_build_object('claimed',false); end if;
  return jsonb_build_object('claimed',true,'receipt',jsonb_build_object(
    'id',v_row.id,'storage_path',v_row.storage_path,'mime_type',v_row.mime_type));
end $$;

--
-- Name: internal_complete_ai_firm_report_v176(uuid, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.internal_complete_ai_firm_report_v176(p_report uuid, p_status text, p_narrative_md text DEFAULT NULL::text, p_error text DEFAULT NULL::text, p_model text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_row public.ai_firm_reports_v176%rowtype;
begin
  if p_status not in ('succeeded','failed') then
    raise exception 'completion status must be succeeded or failed'
      using errcode = '22023';
  end if;
  if p_status = 'succeeded'
     and coalesce(btrim(p_narrative_md), '') = '' then
    raise exception 'a succeeded report requires narrative markdown'
      using errcode = '22023';
  end if;

  select report.* into v_row
  from public.ai_firm_reports_v176 report
  where report.id = p_report
  for update;
  if not found then
    raise exception 'ai_firm_report_not_found' using errcode = '22023';
  end if;
  if v_row.status <> 'generating' then
    raise exception 'only a claimed report can be completed'
      using errcode = '22023';
  end if;

  update public.ai_firm_reports_v176 report
  set status = p_status,
      narrative_md = case when p_status = 'succeeded'
        then p_narrative_md else null end,
      error = case when p_status = 'failed'
        then left(coalesce(nullif(btrim(p_error), ''), 'generation_failed'), 2000)
        else null end,
      model = coalesce(nullif(btrim(p_model), ''), report.model),
      completed_at = now()
  where report.id = p_report
  returning * into v_row;

  return to_jsonb(v_row) - 'evidence';
end
$$;

--
-- Name: FUNCTION internal_complete_ai_firm_report_v176(p_report uuid, p_status text, p_narrative_md text, p_error text, p_model text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.internal_complete_ai_firm_report_v176(p_report uuid, p_status text, p_narrative_md text, p_error text, p_model text) IS 'Service-role completion: stores the model narrative or the failure reason for a claimed report.';

--
-- Name: internal_customer_push_claim_v95(uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.internal_customer_push_claim_v95(p_worker_id uuid, p_limit integer DEFAULT 25, p_lease_seconds integer DEFAULT 60) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_limit integer; v_lease interval; v_result jsonb;
begin
  if p_worker_id is null then raise exception 'worker id is required' using errcode='22023'; end if;
  v_limit:=least(greatest(coalesce(p_limit,25),1),100);
  if coalesce(p_lease_seconds,60) not between 15 and 300 then
    raise exception 'lease seconds must be between 15 and 300' using errcode='22023';
  end if;
  v_lease:=make_interval(secs=>p_lease_seconds);

  update public.customer_push_deliveries_v95
     set status=case when attempt_count>=5 then 'failed' else 'retry' end,
         next_attempt_at=case when attempt_count>=5 then next_attempt_at else now() end,
         lease_token=null,leased_by=null,lease_until=null,
         completed_at=case when attempt_count>=5 then now() else null end,
         updated_at=now(),
         last_error_code=case when attempt_count>=5 then 'lease_exhausted' else 'lease_expired' end
   where status='leased' and lease_until<now();

  insert into public.customer_push_deliveries_v95(
    event_id,subscription_id,identity_id,auth_user_id
  )
  select event.id,subscription.id,event.identity_id,event.auth_user_id
    from public.customer_in_app_inbox_events event
    join public.customer_push_subscriptions_v95 subscription
      on subscription.identity_id=event.identity_id
     and subscription.auth_user_id=event.auth_user_id
     and subscription.status='active'
    left join public.customer_notification_preferences preference
      on preference.business_id=event.business_id
     and preference.identity_id=event.identity_id
     and preference.auth_user_id=event.auth_user_id
     and preference.link_id=event.link_id
     and preference.channel='in_app'
     and preference.topic=event.topic
    left join public.customer_in_app_inbox_state state on state.event_id=event.id
    left join public.customer_in_app_inbox_resolutions resolution on resolution.event_id=event.id
   where app.customer_push_event_eligible_v95(event.source_kind,event.topic)
     and coalesce(preference.opted_in,true)
     and app.customer_communication_topic_allows_v263(
       event.identity_id,event.topic,'push'
     )
     and state.dismissed_at is null and resolution.id is null
     and event.created_at>=subscription.created_at
     and (event.deadline_at is null or event.deadline_at>statement_timestamp())
     and not app.c46_in_quiet_hours(
       preference.quiet_hours_timezone,preference.quiet_hours_start,
       preference.quiet_hours_end,statement_timestamp()
     )
  on conflict(event_id,subscription_id) do nothing;

  with candidates as (
    select delivery.id
      from public.customer_push_deliveries_v95 delivery
      join public.customer_push_subscriptions_v95 subscription
        on subscription.id=delivery.subscription_id and subscription.status='active'
      join public.customer_in_app_inbox_events event on event.id=delivery.event_id
      left join public.customer_notification_preferences preference
        on preference.business_id=event.business_id
       and preference.identity_id=event.identity_id
       and preference.auth_user_id=event.auth_user_id
       and preference.link_id=event.link_id
       and preference.channel='in_app'
       and preference.topic=event.topic
      left join public.customer_in_app_inbox_state state
        on state.event_id=event.id
      left join public.customer_in_app_inbox_resolutions resolution
        on resolution.event_id=event.id
     where delivery.status in ('queued','retry')
       and coalesce(preference.opted_in,true)
       and app.customer_communication_topic_allows_v263(
         event.identity_id,event.topic,'push'
       )
       and delivery.next_attempt_at<=now() and delivery.attempt_count<5
       and state.dismissed_at is null and resolution.id is null
       and (event.deadline_at is null or event.deadline_at>statement_timestamp())
       and not app.c46_in_quiet_hours(
         preference.quiet_hours_timezone,preference.quiet_hours_start,
         preference.quiet_hours_end,statement_timestamp()
       )
     order by delivery.next_attempt_at,delivery.created_at,delivery.id
     for update of delivery skip locked
     limit v_limit
  ), leased as (
    update public.customer_push_deliveries_v95 delivery
       set status='leased',attempt_count=attempt_count+1,
           lease_token=gen_random_uuid(),leased_by=p_worker_id,
           lease_until=now()+v_lease,updated_at=now()
      from candidates
     where delivery.id=candidates.id
    returning delivery.*
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'delivery_id',leased.id,'lease_token',leased.lease_token,
    'attempt',leased.attempt_count,'event_id',event.id,
    'business_id',event.business_id,'business_slug',business.slug,
    'source_kind',event.source_kind,'topic',event.topic,
    'title',event.title,'body',event.body,'route_key',event.route_key,
    'deadline_at',event.deadline_at,
    'endpoint',subscription.endpoint,'p256dh',subscription.p256dh,
    'auth',subscription.auth_secret
  ) order by leased.created_at,leased.id),'[]'::jsonb)
  into v_result
  from leased
  join public.customer_in_app_inbox_events event on event.id=leased.event_id
  join public.businesses business on business.id=event.business_id
  join public.customer_push_subscriptions_v95 subscription
    on subscription.id=leased.subscription_id;
  return v_result;
end
$$;

--
-- Name: internal_customer_push_report_v95(uuid, uuid, uuid, text, integer, text, timestamp with time zone, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.internal_customer_push_report_v95(p_delivery_id uuid, p_lease_token uuid, p_worker_id uuid, p_result text, p_http_status integer, p_error_code text, p_retry_after timestamp with time zone, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_delivery public.customer_push_deliveries_v95%rowtype;
  v_hash text; v_prior record; v_response jsonb; v_status text;
begin
  if p_delivery_id is null or p_lease_token is null or p_worker_id is null
     or p_idempotency_key is null or p_result not in ('sent','retry','gone','failed')
     or (p_http_status is not null and p_http_status not between 100 and 599)
     or length(coalesce(p_error_code,''))>80 then
    raise exception 'invalid push delivery result' using errcode='22023';
  end if;
  v_hash:=app.c46_sha256_hex(jsonb_build_object(
    'delivery_id',p_delivery_id,'lease_token',p_lease_token,'worker_id',p_worker_id,
    'result',p_result,'http_status',p_http_status,'error_code',nullif(p_error_code,''),
    'retry_after',p_retry_after
  )::text);
  perform pg_advisory_xact_lock(hashtextextended(p_delivery_id::text||':'||p_idempotency_key::text,95));
  select request_hash,response into v_prior
    from public.customer_push_delivery_results_v95
   where delivery_id=p_delivery_id and idempotency_key=p_idempotency_key;
  if found then
    if v_prior.request_hash<>v_hash then
      raise exception 'idempotency key conflict' using errcode='22000';
    end if;
    return v_prior.response;
  end if;
  select * into v_delivery from public.customer_push_deliveries_v95
   where id=p_delivery_id for update;
  if not found or v_delivery.status<>'leased'
     or v_delivery.lease_token<>p_lease_token
     or v_delivery.leased_by<>p_worker_id
     or v_delivery.lease_until<now() then
    raise exception 'push delivery lease is not current' using errcode='40001';
  end if;
  v_status:=case
    when p_result='sent' then 'sent'
    when p_result='gone' then 'gone'
    when p_result='failed' or v_delivery.attempt_count>=5 then 'failed'
    else 'retry' end;
  v_response:=jsonb_build_object(
    'delivery_id',p_delivery_id,'status',v_status,'attempt',v_delivery.attempt_count
  );
  insert into public.customer_push_delivery_results_v95(
    delivery_id,attempt_number,lease_token,worker_id,result,http_status,error_code,
    idempotency_key,request_hash,response
  ) values(
    p_delivery_id,v_delivery.attempt_count,p_lease_token,p_worker_id,p_result,
    p_http_status,nullif(p_error_code,''),p_idempotency_key,v_hash,v_response
  );
  update public.customer_push_deliveries_v95 set
    status=v_status,lease_token=null,leased_by=null,lease_until=null,
    next_attempt_at=case when v_status='retry'
      then greatest(coalesce(p_retry_after,now()),now()+make_interval(secs=>least(300,15*(2^attempt_count)::integer)))
      else next_attempt_at end,
    last_http_status=p_http_status,last_error_code=nullif(p_error_code,''),
    completed_at=case when v_status in ('sent','failed','gone') then now() else null end,
    updated_at=now()
  where id=p_delivery_id;
  if v_status='gone' then
    update public.customer_push_subscriptions_v95
       set status='revoked',revoked_at=now(),updated_at=now()
     where id=v_delivery.subscription_id;
  end if;
  return v_response;
end
$$;

--
-- Name: internal_gateway_rate_limit(text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.internal_gateway_rate_limit(p_scope text, p_key_hash text, p_limit integer, p_window_seconds integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $_$
declare
  v_now timestamptz := clock_timestamp();
  v_row app.public_gateway_rate_limits%rowtype;
begin
  if p_scope !~ '^[a-z][a-z0-9_-]{1,63}$'
     or p_key_hash !~ '^[0-9a-f]{64}$'
     or p_limit not between 1 and 1000
     or p_window_seconds not between 1 and 86400 then
    raise exception using errcode = '22023', message = 'invalid request';
  end if;

  delete from app.public_gateway_rate_limits
   where expires_at < v_now - interval '1 day';

  insert into app.public_gateway_rate_limits
    (scope, key_hash, window_started_at, expires_at, request_count)
  values
    (p_scope, p_key_hash, v_now, v_now + make_interval(secs => p_window_seconds), 1)
  on conflict (scope, key_hash) do update
    set window_started_at = case
          when app.public_gateway_rate_limits.expires_at <= v_now then v_now
          else app.public_gateway_rate_limits.window_started_at end,
        expires_at = case
          when app.public_gateway_rate_limits.expires_at <= v_now
          then v_now + make_interval(secs => p_window_seconds)
          else app.public_gateway_rate_limits.expires_at end,
        request_count = case
          when app.public_gateway_rate_limits.expires_at <= v_now then 1
          else least(p_limit + 1, app.public_gateway_rate_limits.request_count + 1) end
  returning * into v_row;

  return jsonb_build_object(
    'allowed', v_row.request_count <= p_limit,
    'retry_after', greatest(0, ceil(extract(epoch from (v_row.expires_at - v_now)))::integer));
end;
$_$;

--
-- Name: internal_get_approved_business_invitation_v95(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.internal_get_approved_business_invitation_v95(p_invitation_token text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $_$
declare
  v_invitation public.business_application_invitations_v95%rowtype;
  v_application public.business_applications_v95%rowtype;
begin
  if coalesce(p_invitation_token,'')!~'^[0-9a-f]{64}$' then
    return jsonb_build_object('valid',false,'status','invalid');
  end if;
  select * into v_invitation
  from public.business_application_invitations_v95
  where token_hash=app.v95_sha256(p_invitation_token);
  if not found then
    return jsonb_build_object('valid',false,'status','invalid');
  end if;
  select * into v_application from public.business_applications_v95
  where id=v_invitation.application_id;
  if v_invitation.consumed_at is not null then
    return jsonb_build_object('valid',false,'status','consumed');
  elsif v_invitation.revoked_at is not null
        or v_application.status<>'approved' then
    return jsonb_build_object('valid',false,'status','inactive');
  elsif v_invitation.expires_at<=now() then
    return jsonb_build_object(
      'valid',false,'status','expired','expires_at',v_invitation.expires_at
    );
  end if;
  return jsonb_build_object(
    'valid',true,'status','approved',
    'application_id',v_application.id,
    'business_name',v_application.business_name,
    'approved_email',v_application.contact_email,
    'preferred_locale',v_application.preferred_locale,
    'expires_at',v_invitation.expires_at
  );
end
$_$;

--
-- Name: internal_public_booking_availability(text, uuid, uuid, date, integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.internal_public_booking_availability(p_slug text, p_service uuid, p_staff uuid, p_from date, p_days integer, p_branch uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $_$
declare
  v_business public.businesses%rowtype;
  v_duration integer;
  v_days integer := least(greatest(coalesce(p_days, 7), 1), 14);
  v_from date := greatest(coalesce(p_from, (statement_timestamp() at time zone 'Asia/Singapore')::date),
                          (statement_timestamp() at time zone 'Asia/Singapore')::date);
  v_hours_configured boolean;
  v_staff jsonb;
  v_days_out jsonb;
  v_earliest timestamptz := statement_timestamp() + interval '15 minutes';
begin
  if p_slug is null or p_slug !~ '^[a-z0-9][a-z0-9-]{0,62}$' then
    return null;
  end if;

  select business.* into v_business
    from public.businesses business
   where business.slug = p_slug
   limit 1;
  if not found then
    return null;
  end if;

  if coalesce(v_business.booking_staff_choice, false) is not true then
    return jsonb_build_object(
      'staff_choice', false, 'hours_configured', false,
      'slot_minutes', 30, 'staff', '[]'::jsonb, 'days', '[]'::jsonb
    );
  end if;

  if p_service is not null and not exists (
    select 1 from public.services service
     where service.id = p_service
       and service.business_id = v_business.id
       and service.active
       and service.show_on_booking_page
  ) then
    return null;
  end if;

  if p_branch is not null and not exists (
    select 1 from public.branches branch_row
     where branch_row.id = p_branch
       and branch_row.business_id = v_business.id
       and branch_row.active
  ) then
    return null;
  end if;

  select coalesce(service.duration_min, 60)
       + coalesce(service.buffer_before_min, 0)
       + coalesce(service.buffer_after_min, 0)
    into v_duration
    from public.services service
   where service.id = p_service
     and service.business_id = v_business.id;
  v_duration := greatest(coalesce(v_duration, 60), 5);

  select coalesce(jsonb_agg(jsonb_build_object(
           'id', bookable.staff_id, 'name', bookable.full_name, 'title', bookable.title
         ) order by lower(bookable.full_name), bookable.staff_id), '[]'::jsonb)
    into v_staff
    from app.v183_bookable_staff(v_business.id, p_service, p_staff, p_branch) bookable;

  v_hours_configured := exists (
    select 1 from public.staff_hours hours
     join app.v183_bookable_staff(v_business.id, p_service, p_staff, p_branch) bookable
       on bookable.staff_id = hours.staff_id
     where hours.business_id = v_business.id
  ) or exists (
    select 1 from public.branch_hours hours
     join public.branches branch_row
       on branch_row.id = hours.branch_id
      and branch_row.business_id = v_business.id
     where hours.business_id = v_business.id
       and (p_branch is null or branch_row.id = p_branch)
  );

  if not v_hours_configured or v_staff = '[]'::jsonb then
    return jsonb_build_object(
      'staff_choice', true,
      'hours_configured', v_hours_configured,
      'slot_minutes', 30,
      'staff', v_staff,
      'days', '[]'::jsonb
    );
  end if;

  with calendar as (
    select (v_from + offset_days)::date as day
      from generate_series(0, v_days - 1) as offset_days
  ), windows as (
    select calendar.day,
           member.staff_id,
           coalesce(own.starts_at, branch.opens_at) as starts_at,
           coalesce(own.ends_at, branch.closes_at) as ends_at
      from calendar
      cross join app.v183_bookable_staff(v_business.id, p_service, p_staff, p_branch) member
      left join public.staff_hours own
        on own.business_id = v_business.id
       and own.staff_id = member.staff_id
       and own.weekday = extract(dow from calendar.day)::smallint
      left join lateral (
        select hours.opens_at, hours.closes_at
          from public.branch_hours hours
          join public.branches branch_row
            on branch_row.id = hours.branch_id
           and branch_row.business_id = v_business.id
           and coalesce(branch_row.active, true)
         where hours.business_id = v_business.id
           and hours.weekday = extract(dow from calendar.day)::smallint
           and (p_branch is null or branch_row.id = p_branch)
         order by branch_row.is_default desc nulls last, branch_row.created_at, branch_row.id
         limit 1
      ) branch on not exists (
        select 1 from public.staff_hours any_row
         where any_row.business_id = v_business.id and any_row.staff_id = member.staff_id
      )
     where coalesce(own.starts_at, branch.opens_at) is not null
       and coalesce(own.ends_at, branch.closes_at) is not null
       -- v383: the public booking page never honoured off days at all — this function does not
       -- call staff_free_for_appointment, so a team member marked off was still offered slots to
       -- strangers. Both kinds are refused here, on the same weekday expression used above.
       and not exists (
         select 1 from public.staff_off_days off_day
          where off_day.business_id = v_business.id and off_day.staff_id = member.staff_id
            and calendar.day between off_day.starts_on and off_day.ends_on
       )
       and not exists (
         select 1 from public.staff_recurring_off_days recurring
          where recurring.business_id = v_business.id and recurring.staff_id = member.staff_id
            and recurring.weekday = extract(dow from calendar.day)::smallint
       )
  ), slots as (
    select windows.day,
           windows.staff_id,
           slot_at
      from windows
      cross join lateral generate_series(
        timezone('Asia/Singapore', (windows.day + windows.starts_at)::timestamp),
        timezone('Asia/Singapore', (windows.day + windows.ends_at)::timestamp) - make_interval(mins => v_duration),
        interval '30 minutes'
      ) as slot_at
  ), free as (
    select slots.day, slots.staff_id, slots.slot_at
      from slots
     where slots.slot_at >= v_earliest
       and not exists (
         select 1 from public.appointments booked
          where booked.business_id = v_business.id
            and booked.staff_id = slots.staff_id
            and booked.status not in ('cancelled', 'no_show', 'declined')
            and tstzrange(booked.starts_at,
                          coalesce(booked.ends_at, booked.starts_at + interval '1 hour'), '[)')
                && tstzrange(slots.slot_at, slots.slot_at + make_interval(mins => v_duration), '[)')
       )
       and not exists (
         select 1 from public.staff_blocked_times blocked
          where blocked.business_id = v_business.id
            and blocked.staff_id = slots.staff_id
            and tstzrange(blocked.starts_at, blocked.ends_at, '[)')
                && tstzrange(slots.slot_at, slots.slot_at + make_interval(mins => v_duration), '[)')
       )
       and not exists (
         select 1 from public.booking_requests pending
         left join public.services pending_service
           on pending_service.id = pending.service_id
          and pending_service.business_id = v_business.id
          where pending.business_id = v_business.id
            and pending.staff_id = slots.staff_id
            and pending.status in ('new', 'pending', 'waitlisted')
            and pending.preferred_at is not null
            and tstzrange(pending.preferred_at,
                          pending.preferred_at + make_interval(mins => greatest(
                            coalesce(pending_service.duration_min, 60)
                              + coalesce(pending_service.buffer_before_min, 0)
                              + coalesce(pending_service.buffer_after_min, 0),
                            5)),
                          '[)')
                && tstzrange(slots.slot_at, slots.slot_at + make_interval(mins => v_duration), '[)')
       )
  ), per_slot as (
    select free.day,
           free.slot_at,
           jsonb_agg(free.staff_id order by free.staff_id) as staff_ids
      from free
     group by free.day, free.slot_at
  )
  select coalesce(jsonb_agg(day_row order by day_row->>'date'), '[]'::jsonb)
    into v_days_out
    from (
      select jsonb_build_object(
               'date', to_char(per_slot.day, 'YYYY-MM-DD'),
               'slots', jsonb_agg(jsonb_build_object(
                 'at', per_slot.slot_at,
                 'staff_ids', per_slot.staff_ids
               ) order by per_slot.slot_at)
             ) as day_row
        from per_slot
       group by per_slot.day
    ) grouped;

  return jsonb_build_object(
    'staff_choice', true,
    'hours_configured', true,
    'slot_minutes', 30,
    'duration_minutes', v_duration,
    'staff', v_staff,
    'days', coalesce(v_days_out, '[]'::jsonb)
  );
exception when others then
  return null;
end;
$_$;

--
-- Name: internal_public_booking_change(text, uuid, text, text, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.internal_public_booking_change(p_token_hash text, p_submission_id uuid, p_request_fingerprint text, p_kind text, p_proposed timestamp with time zone DEFAULT NULL::timestamp with time zone, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $_$
declare
  v_token app.booking_management_tokens%rowtype;
  v_appt record;
  v_auto boolean;
  v_status text := 'pending';
  v_request uuid;
  v_prior app.booking_management_change_submissions%rowtype;
  v_result jsonb;
begin
  if p_token_hash !~ '^[0-9a-f]{64}$'
     or p_submission_id is null
     or p_request_fingerprint !~ '^[0-9a-f]{64}$'
     or p_kind not in ('cancel', 'reschedule')
     or char_length(coalesce(p_note, '')) > 500
     or (p_kind = 'cancel' and p_proposed is not null)
     or (p_kind = 'reschedule' and p_proposed is null) then
    raise exception using errcode = '22023', message = 'invalid request';
  end if;

  select * into v_token
    from app.booking_management_tokens t
   where t.token_hash = decode(p_token_hash, 'hex')
     and t.revoked_at is null and t.expires_at > clock_timestamp()
   for update;
  if not found then
    raise exception using errcode = '22023', message = 'invalid request';
  end if;

  select * into v_prior
    from app.booking_management_change_submissions s
   where s.management_token_id = v_token.id and s.submission_id = p_submission_id;
  if found then
    if v_prior.request_fingerprint <> decode(p_request_fingerprint, 'hex') then
      return jsonb_build_object('conflict', true);
    end if;
    return v_prior.result || jsonb_build_object('replayed', true);
  end if;

  if p_kind = 'reschedule' and
     (p_proposed < clock_timestamp() + interval '15 minutes'
      or p_proposed > clock_timestamp() + interval '365 days') then
    raise exception using errcode = '22023', message = 'invalid request';
  end if;

  select a.id, a.business_id, a.client_id, a.starts_at, a.ends_at, a.status,
         b.auto_approve_changes
    into v_appt
    from public.appointments a
    join public.businesses b on b.id = a.business_id
   where a.id = v_token.appointment_id and a.business_id = v_token.business_id
     and a.status = 'booked' and a.starts_at > clock_timestamp()
   for update of a;
  if not found then
    raise exception using errcode = '22023', message = 'invalid request';
  end if;

  -- v289: a reschedule is a change the business can switch off; the server is the boundary,
  -- the portal button only a courtesy. Cancel is never gated — refusing a cancellation does
  -- not keep the appointment, it manufactures a no-show. Missing capability row = fail closed,
  -- matching customer_get_business_actions_v89's coalesce(...,false) on the same flag.
  if p_kind = 'reschedule' and not coalesce((
    select cap.appointment_changes_enabled
      from public.business_customer_capabilities_v89 cap
     where cap.business_id = v_appt.business_id), false) then
    raise exception using errcode = '22023', message = 'invalid request';
  end if;

  select cr.id, cr.status into v_request, v_status
    from public.change_requests cr
   where cr.appointment_id = v_appt.id and cr.status = 'pending'
   order by cr.created_at desc
   limit 1;
  if found then
    return jsonb_build_object('conflict', true);
  end if;

  insert into public.change_requests
    (business_id, appointment_id, kind, proposed_at, phone, note, status)
  values
    (v_appt.business_id, v_appt.id, p_kind, p_proposed, null,
     nullif(btrim(p_note), ''), 'pending')
  returning id into v_request;

  v_auto := coalesce(v_appt.auto_approve_changes, false);
  -- Public reschedules always remain pending until the canonical availability,
  -- hours, capacity, staff and overlap engine can approve them.
  if v_auto and p_kind = 'cancel' then
    update public.appointments set status = 'cancelled'
     where id = v_appt.id and business_id = v_appt.business_id and status = 'booked';
    update public.change_requests
       set status = 'approved', decided_at = clock_timestamp()
     where id = v_request;
    v_status := 'approved';
  end if;

  update app.booking_management_tokens set last_used_at = clock_timestamp()
   where id = v_token.id;
  v_result := jsonb_build_object('id', v_request, 'status', v_status);
  insert into app.booking_management_change_submissions
    (management_token_id, submission_id, request_fingerprint, result)
  values
    (v_token.id, p_submission_id, decode(p_request_fingerprint, 'hex'), v_result);
  return v_result || jsonb_build_object('replayed', false);
end;
$_$;

--
-- Name: internal_public_booking_lookup(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.internal_public_booking_lookup(p_token_hash text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $_$
declare v_token app.booking_management_tokens%rowtype;
begin
  if p_token_hash !~ '^[0-9a-f]{64}$' then
    raise exception using errcode = '22023', message = 'invalid request';
  end if;

  select * into v_token
    from app.booking_management_tokens t
   where t.token_hash = decode(p_token_hash, 'hex')
     and t.revoked_at is null and t.expires_at > clock_timestamp()
   for update;
  if not found then
    raise exception using errcode = '22023', message = 'invalid request';
  end if;

  update app.booking_management_tokens set last_used_at = clock_timestamp()
   where id = v_token.id;

  return (
    select jsonb_build_object(
      'status', coalesce(a.status, br.status),
      'preferred_at', br.preferred_at,
      'starts_at', a.starts_at,
      'service_name', s.name,
      'can_change', a.id is not null and a.status = 'booked' and a.starts_at > clock_timestamp(),
      'expires_at', v_token.expires_at)
      from (select 1) seed
      left join public.booking_requests br on br.id = v_token.booking_request_id
      left join public.appointments a on a.id = coalesce(v_token.appointment_id, br.appointment_id)
      left join public.services s on s.id = coalesce(a.service_id, br.service_id)
  );
end;
$_$;

--
-- Name: internal_public_booking_page(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.internal_public_booking_page(p_slug text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $_$
declare
  v_page jsonb;
  v_business public.businesses%rowtype;
  v_staff jsonb := '[]'::jsonb;
  v_branches jsonb := '[]'::jsonb;
  v_branch_count integer;
begin
  if p_slug is null or p_slug !~ '^[a-z0-9][a-z0-9-]{0,62}$' then
    return null;
  end if;

  select public.get_business_public(p_slug)::jsonb into v_page;
  if v_page is null then
    return null;
  end if;

  select business.* into v_business
    from public.businesses business
   where business.slug = p_slug
   limit 1;
  if not found then
    return null;
  end if;

  select count(*) into v_branch_count
    from public.branches branch
   where branch.business_id = v_business.id and branch.active;

  -- v327: branch identity is exposed only when there is a real choice to make. A single-branch
  -- business (still most of them) gets no new step and no branch data on the page at all — the
  -- same "off by default, exposes nothing" contract v183 set for staff choice.
  if v_branch_count > 1 then
    select coalesce(jsonb_agg(jsonb_build_object(
             'id', branch.id, 'name', coalesce(nullif(btrim(branch.name), ''), 'Branch')
           ) order by branch.is_default desc nulls last, lower(branch.name), branch.id), '[]'::jsonb)
      into v_branches
      from public.branches branch
     where branch.business_id = v_business.id and branch.active;
  end if;

  if coalesce(v_business.booking_staff_choice, false) then
    select coalesce(jsonb_agg(jsonb_build_object(
             'id', member.id,
             'name', coalesce(nullif(btrim(member.full_name), ''), 'Team member'),
             'title', nullif(btrim(member.title), ''),
             'service_ids', coalesce((
               select jsonb_agg(mapped.service_id order by mapped.service_id)
                 from public.staff_services mapped
                where mapped.business_id = v_business.id
                  and mapped.staff_id = member.id
             ), '[]'::jsonb),
             'branch_ids', coalesce((
               select jsonb_agg(assignment.branch_id order by assignment.branch_id)
                 from public.staff_branches assignment
                where assignment.business_id = v_business.id
                  and assignment.staff_id = member.id
             ), '[]'::jsonb)
           ) order by lower(coalesce(member.full_name, '')), member.id), '[]'::jsonb)
      into v_staff
      from public.staff member
     where member.business_id = v_business.id
       and coalesce(member.active, true)
       and coalesce(member.customer_bookable, true);
  end if;

  return v_page || jsonb_build_object(
    'booking_auto_confirm', coalesce(v_business.booking_auto_confirm, false),
    'booking_staff_choice', coalesce(v_business.booking_staff_choice, false),
    'staff', v_staff,
    'branches', v_branches
  );
exception when others then
  return null;
end;
$_$;

--
-- Name: internal_public_booking_submit(text, text, text, text, uuid, integer, timestamp with time zone, text, uuid, boolean, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.internal_public_booking_submit(p_slug text, p_name text, p_email text, p_phone text, p_service uuid, p_party integer, p_preferred timestamp with time zone, p_notes text, p_table_type uuid, p_consent boolean, p_token_hash text, p_idempotency_hash text, p_request_fingerprint text) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  select public.internal_public_booking_submit(
    p_slug, p_name, p_email, p_phone, p_service, p_party, p_preferred,
    p_notes, p_table_type, p_consent, p_token_hash, p_idempotency_hash,
    p_request_fingerprint, null::uuid
  )
$$;

--
-- Name: internal_public_booking_submit(text, text, text, text, uuid, integer, timestamp with time zone, text, uuid, boolean, text, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.internal_public_booking_submit(p_slug text, p_name text, p_email text, p_phone text, p_service uuid, p_party integer, p_preferred timestamp with time zone, p_notes text, p_table_type uuid, p_consent boolean, p_token_hash text, p_idempotency_hash text, p_request_fingerprint text, p_authenticated_user uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $_$
declare
  v_business public.businesses%rowtype;
  v_bound_client uuid;
  v_result json;
  v_request uuid;
  v_appointment uuid;
  v_token_expiry timestamptz;
  v_prior jsonb;
  v_prior_fingerprint bytea;
  v_prior_authenticated_user uuid;
  v_prior_client uuid;
begin
  if p_slug is null or p_slug !~ '^[a-z0-9][a-z0-9-]{0,62}$'
     or p_name is null or char_length(btrim(p_name)) not between 2 and 100
     or p_party not between 1 and 50
     or p_preferred is null
     or char_length(coalesce(p_notes, '')) > 1000
     or p_token_hash !~ '^[0-9a-f]{64}$'
     or p_idempotency_hash !~ '^[0-9a-f]{64}$'
     or p_request_fingerprint !~ '^[0-9a-f]{64}$'
     or (p_email is null and p_phone is null)
     or (p_email is not null and (
       char_length(p_email) > 254
       or p_email !~* '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$'
     ))
     or (p_phone is not null and p_phone !~ '^\+[1-9][0-9]{7,14}$') then
    raise exception 'invalid request' using errcode = '22023';
  end if;

  select business.* into v_business
    from public.businesses business
   where business.slug = p_slug
   limit 1;
  if not found then
    raise exception 'invalid request' using errcode = '22023';
  end if;

  v_bound_client := app.resolve_verified_booking_client_v72(
    v_business.id, p_authenticated_user
  );

  select token.initial_response, token.request_fingerprint,
         token.authenticated_user_id, token.customer_client_id
    into v_prior, v_prior_fingerprint,
         v_prior_authenticated_user, v_prior_client
    from app.booking_management_tokens token
   where token.idempotency_hash = decode(p_idempotency_hash, 'hex')
     and token.business_id = v_business.id
   for update;
  if found then
    if v_prior_fingerprint <> decode(p_request_fingerprint, 'hex')
       or v_prior_authenticated_user is distinct from p_authenticated_user
       or v_prior_client is distinct from v_bound_client then
      return jsonb_build_object('conflict', true);
    end if;
    return v_prior || jsonb_build_object('replayed', true);
  end if;

  if p_preferred < clock_timestamp() + interval '15 minutes'
     or p_preferred > clock_timestamp() + interval '365 days' then
    raise exception 'invalid request' using errcode = '22023';
  end if;

  if p_service is not null and not exists (
    select 1 from public.services service
     where service.id = p_service
       and service.business_id = v_business.id
       and service.active
       and service.show_on_booking_page
  ) then
    raise exception 'invalid request' using errcode = '22023';
  end if;

  if p_table_type is not null and not exists (
    select 1 from public.booking_tables table_type
     where table_type.id = p_table_type
       and table_type.business_id = v_business.id
       and table_type.active
       and (table_type.pax is null or p_party <= table_type.pax)
  ) then
    raise exception 'invalid request' using errcode = '22023';
  end if;

  if v_bound_client is null then
    select public.request_booking(
      p_slug, btrim(p_name), nullif(btrim(p_email), ''), p_phone,
      p_service, p_party, p_preferred, nullif(btrim(p_notes), ''),
      p_table_type, coalesce(p_consent, false)
    ) into v_result;
  else
    select app.request_bound_booking_v72(
      v_business.id, v_bound_client, p_authenticated_user,
      btrim(p_name), nullif(btrim(p_email), ''), p_phone,
      p_service, p_party, p_preferred, nullif(btrim(p_notes), ''),
      p_table_type, coalesce(p_consent, false)
    ) into v_result;
  end if;

  v_request := nullif(v_result->>'request_id', '')::uuid;
  v_appointment := nullif(v_result->>'appointment_id', '')::uuid;
  if v_request is null and v_appointment is null then
    raise exception 'invalid request' using errcode = 'P0001';
  end if;

  v_token_expiry := greatest(
    clock_timestamp() + interval '30 days',
    p_preferred + interval '30 days'
  );
  insert into app.booking_management_tokens (
    token_hash, idempotency_hash, request_fingerprint,
    business_id, booking_request_id, appointment_id,
    authenticated_user_id, customer_client_id,
    expires_at, initial_response
  ) values (
    decode(p_token_hash, 'hex'), decode(p_idempotency_hash, 'hex'),
    decode(p_request_fingerprint, 'hex'), v_business.id,
    v_request, v_appointment, p_authenticated_user, v_bound_client,
    v_token_expiry, v_result::jsonb
  );

  return v_result::jsonb || jsonb_build_object('replayed', false);
end
$_$;

--
-- Name: internal_public_booking_submit(text, text, text, text, uuid, integer, timestamp with time zone, text, uuid, boolean, text, text, text, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.internal_public_booking_submit(p_slug text, p_name text, p_email text, p_phone text, p_service uuid, p_party integer, p_preferred timestamp with time zone, p_notes text, p_table_type uuid, p_consent boolean, p_token_hash text, p_idempotency_hash text, p_request_fingerprint text, p_authenticated_user uuid, p_staff uuid, p_branch uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_business_id uuid;
  v_result jsonb;
  v_request uuid;
  v_appointment uuid;
begin
  -- The staff/branch preference is validated BEFORE the shared submit path runs, so an
  -- invalid or foreign id is rejected outright rather than silently dropped.
  if p_staff is not null or p_branch is not null then
    select business.id into v_business_id
      from public.businesses business
     where business.slug = p_slug
     limit 1;
    if v_business_id is null then
      raise exception 'invalid request' using errcode = '22023';
    end if;
  end if;

  if p_staff is not null then
    if not exists (
      select 1 from public.businesses business
       where business.id = v_business_id
         and coalesce(business.booking_staff_choice, false)
    ) or not exists (
      select 1 from public.staff member
       where member.id = p_staff
         and member.business_id = v_business_id
         and coalesce(member.active, true)
         and coalesce(member.customer_bookable, true)
         and (p_branch is null or exists (
           select 1 from public.staff_branches assignment
            where assignment.business_id = v_business_id
              and assignment.staff_id = p_staff
              and assignment.branch_id = p_branch
         ))
    ) then
      raise exception 'invalid request' using errcode = '22023';
    end if;
    if p_service is not null
       and exists (
         select 1 from public.staff_services mapped
          where mapped.business_id = v_business_id and mapped.service_id = p_service
       )
       and not exists (
         select 1 from public.staff_services mapped
          where mapped.business_id = v_business_id
            and mapped.service_id = p_service
            and mapped.staff_id = p_staff
       ) then
      raise exception 'invalid request' using errcode = '22023';
    end if;
  end if;

  if p_branch is not null and not exists (
    select 1 from public.branches branch_row
     where branch_row.id = p_branch
       and branch_row.business_id = v_business_id
       and branch_row.active
  ) then
    raise exception 'invalid request' using errcode = '22023';
  end if;

  select public.internal_public_booking_submit(
    p_slug, p_name, p_email, p_phone, p_service, p_party, p_preferred,
    p_notes, p_table_type, p_consent, p_token_hash, p_idempotency_hash,
    p_request_fingerprint, p_authenticated_user
  ) into v_result;

  if (p_staff is null and p_branch is null) or v_result is null
     or coalesce((v_result->>'conflict')::boolean, false)
     or coalesce((v_result->>'replayed')::boolean, false) then
    return v_result;
  end if;

  v_request := nullif(v_result->>'request_id', '')::uuid;
  v_appointment := nullif(v_result->>'appointment_id', '')::uuid;

  if v_request is not null then
    update public.booking_requests
       set staff_id = case when p_staff is not null then p_staff else staff_id end,
           branch_id = case when p_branch is not null then p_branch else branch_id end
     where id = v_request
       and business_id = v_business_id;
  end if;
  if v_appointment is not null then
    -- An auto-confirmed booking becomes an appointment immediately; the request is what the
    -- customer asked for, so the staff assignment is only applied when the slot is still
    -- unassigned. The branch was just created moments ago in this same transaction by the
    -- default-branch trigger and nothing else has had a chance to touch it yet, so the branch
    -- the customer asked for can simply overwrite it outright.
    if p_staff is not null then
      update public.appointments
         set staff_id = p_staff
       where id = v_appointment
         and business_id = v_business_id
         and staff_id is null;
    end if;
    if p_branch is not null then
      update public.appointments
         set branch_id = p_branch
       where id = v_appointment
         and business_id = v_business_id;
    end if;
  end if;

  return v_result;
end;
$$;

--
-- Name: internal_public_join(text, text, text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.internal_public_join(p_slug text, p_name text, p_phone text, p_email text DEFAULT NULL::text, p_consent boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $_$
declare
  v_business record;
  v_phone_norm text;
  v_result json;
begin
  if p_slug is null or p_slug !~ '^[a-z0-9][a-z0-9-]{0,62}$'
     or p_name is null or char_length(btrim(p_name)) not between 2 and 100
     or p_phone is null or char_length(p_phone) > 32
     or (p_email is not null and (char_length(p_email) > 254
          or p_email !~* '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$')) then
    raise exception using errcode = '22023', message = 'invalid request';
  end if;

  select b.id, b.name into v_business
    from public.businesses b
   where b.slug = p_slug and coalesce(b.join_enabled, false)
   limit 1;
  if not found then
    raise exception using errcode = '22023', message = 'invalid request';
  end if;

  v_phone_norm := app.norm_phone(p_phone);
  if v_phone_norm is null then
    raise exception using errcode = '22023', message = 'invalid request';
  end if;

  -- Repeated phone-only signup is deliberately opaque and never mutates PII or consent.
  if exists (
    select 1 from public.clients c
     where c.business_id = v_business.id and c.phone_norm = v_phone_norm
  ) then
    return jsonb_build_object('status', 'ok', 'business_name', v_business.name);
  end if;

  select public.join_program(
    p_slug, btrim(p_name), v_phone_norm,
    nullif(btrim(p_email), ''), coalesce(p_consent, false))
  into v_result;
  return v_result::jsonb;
exception
  when unique_violation then
    return jsonb_build_object('status', 'ok', 'business_name', v_business.name);
end;
$_$;

--
-- Name: internal_public_join_page(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.internal_public_join_page(p_slug text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $_$
declare v_page json;
begin
  if p_slug is null or p_slug !~ '^[a-z0-9][a-z0-9-]{0,62}$' then
    return null;
  end if;
  select public.get_join_page(p_slug) into v_page;
  return v_page::jsonb;
exception when others then
  return null;
end;
$_$;

--
-- Name: internal_public_join_page_v89(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.internal_public_join_page_v89(p_join_token text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_result jsonb;
begin
  if length(coalesce(p_join_token,''))<32 then
    return null;
  end if;
  select jsonb_build_object(
    'name',business.name,'brand_color',business.brand_color,
    'industry',business.industry,'join_token',p_join_token,
    'expires_at',qr.expires_at
  ) into v_result
  from public.business_customer_join_qr_v89 qr
  join public.businesses business on business.id=qr.business_id
  where qr.token_hash=app.v89_sha256(p_join_token)
    and qr.status='active' and qr.expires_at>now() and business.join_enabled;
  return v_result;
end
$$;

--
-- Name: internal_public_join_v89(text, text, text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.internal_public_join_v89(p_join_token text, p_name text, p_phone text, p_email text DEFAULT NULL::text, p_consent boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_business uuid;v_name text:=nullif(btrim(p_name),'');
  v_phone text:=app.norm_phone(p_phone);v_client uuid;v_business_name text;
begin
  select qr.business_id,business.name into v_business,v_business_name
  from public.business_customer_join_qr_v89 qr
  join public.businesses business on business.id=qr.business_id
  where qr.token_hash=app.v89_sha256(p_join_token)
    and qr.status='active' and qr.expires_at>now() and business.join_enabled
  for share;
  if v_business is null then
    raise exception 'This join QR is not active.' using errcode='22023';
  end if;
  if v_name is null or length(v_name) not between 2 and 80 or v_phone is null then
    raise exception 'Enter a valid name and Singapore mobile number.'
      using errcode='22023';
  end if;
  insert into public.clients(
    business_id,full_name,phone,email,marketing_consent
  ) values(
    v_business,v_name,v_phone,nullif(btrim(coalesce(p_email,'')),''),
    coalesce(p_consent,false)
  ) on conflict(business_id,phone_norm) where phone_norm is not null
    do nothing returning id into v_client;
  if v_client is not null then
    insert into public.consents(business_id,client_id,channel,action,source)
    values(v_business,v_client,'marketing',
      case when coalesce(p_consent,false) then 'granted' else 'withdrawn' end,
      'qr_join_v89');
    insert into public.audit_log(business_id,actor,action,entity,entity_id,detail)
    values(v_business,null,'CUSTOMER_QR_SIGNUP_V89','clients',v_client,
      jsonb_build_object('consent',coalesce(p_consent,false)));
    -- v215: v_client is non-null ONLY when this insert actually created a client
    -- row (the on-conflict path returns null), so an existing customer re-entering
    -- their number never mints a second offer.
    perform app.issue_welcome_offer_v215(v_business,v_client);
  end if;
  -- Deliberately uniform for new/existing numbers. The token is handed through
  -- to the post-OTP authenticated QR claim; no link is created here.
  return jsonb_build_object('status','ok','business_name',v_business_name,
    'join_token',p_join_token,'next','customer_auth');
end
$$;

--
-- Name: internal_record_account_open_booking_token_v175(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.internal_record_account_open_booking_token_v175(p_token_hash text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $_$
declare
  v_token app.booking_management_tokens%rowtype;
begin
  if p_token_hash is null or p_token_hash !~ '^[0-9a-f]{64}$' then
    return pg_catalog.jsonb_build_object('recorded',false,'reason','no_token');
  end if;
  select management_token.* into v_token
  from app.booking_management_tokens management_token
  where management_token.token_hash=pg_catalog.decode(p_token_hash,'hex')
    and management_token.revoked_at is null
    and management_token.expires_at>clock_timestamp();
  if not found then
    return pg_catalog.jsonb_build_object('recorded',false,'reason','no_token');
  end if;
  if v_token.customer_client_id is null
     and v_token.authenticated_user_id is null then
    return pg_catalog.jsonb_build_object(
      'recorded',false,'reason','no_identity'
    );
  end if;
  return app.record_customer_account_open_v175(
    v_token.business_id,v_token.authenticated_user_id,
    v_token.customer_client_id,'booking',clock_timestamp()
  );
end
$_$;

--
-- Name: internal_record_account_open_join_v175(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.internal_record_account_open_join_v175(p_join_token text, p_phone text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_business uuid;
  v_phone text:=app.norm_phone(p_phone);
  v_client uuid;
begin
  if p_join_token is null or v_phone is null then
    return pg_catalog.jsonb_build_object(
      'recorded',false,'reason','no_identity'
    );
  end if;
  select join_qr.business_id into v_business
  from public.business_customer_join_qr_v89 join_qr
  where join_qr.token_hash=app.v89_sha256(p_join_token)
    and join_qr.status='active'
    and join_qr.expires_at>now();
  if v_business is null then
    return pg_catalog.jsonb_build_object(
      'recorded',false,'reason','no_business'
    );
  end if;
  select client.id into v_client
  from public.clients client
  where client.business_id=v_business
    and client.phone_norm=v_phone;
  if v_client is null then
    return pg_catalog.jsonb_build_object(
      'recorded',false,'reason','no_identity'
    );
  end if;
  return app.record_customer_account_open_v175(
    v_business,null,v_client,'join',clock_timestamp()
  );
end
$$;

--
-- Name: internal_record_receipt_extraction_v199(uuid, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.internal_record_receipt_extraction_v199(p_receipt uuid, p_extracted jsonb, p_error text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_row public.platform_accounting_receipts_v199%rowtype;
begin
  if current_setting('role',true) is distinct from 'service_role'
     and auth.role() is distinct from 'service_role' then
    raise exception 'service role is required' using errcode='42501';
  end if;
  update public.platform_accounting_receipts_v199
     set status=case when p_error is not null then 'extraction_failed' else 'extracted' end,
         extracted=case when p_error is null then p_extracted end,
         extraction_error=left(nullif(btrim(coalesce(p_error,'')),''),400),
         extracted_at=now()
   where id=p_receipt and status in ('uploaded','extraction_failed')
  returning * into v_row;
  if not found then
    return jsonb_build_object('updated',false,'receipt',p_receipt);
  end if;
  return jsonb_build_object('updated',true,'receipt',to_jsonb(v_row));
end $$;

--
-- Name: internal_submit_business_application_v95(text, text, text, text, text, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.internal_submit_business_application_v95(p_contact_name text, p_contact_email text, p_contact_phone text, p_business_name text, p_sector_key text, p_registration_number text, p_locale text, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $_$
declare
  v_email text:=lower(btrim(coalesce(p_contact_email,'')));
  v_hash text;
  v_application public.business_applications_v95%rowtype;
begin
  if p_idempotency_key is null
     or length(btrim(coalesce(p_contact_name,''))) not between 2 and 120
     or v_email!~'^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$'
     or coalesce(p_contact_phone,'')!~'^\+[1-9][0-9]{7,14}$'
     or length(btrim(coalesce(p_business_name,''))) not between 2 and 160
     or coalesce(p_locale,'') not in ('en','zh-CN','ms')
  then raise exception 'valid business application fields are required'
    using errcode='22023';end if;
  if not exists(
    select 1 from public.sector_bundle_versions bundle
    where bundle.sector_key=p_sector_key and bundle.status='published'
  ) then raise exception 'published_sector_required' using errcode='22023';end if;
  v_hash:=app.v95_sha256(concat_ws('|',
    btrim(p_contact_name),v_email,p_contact_phone,btrim(p_business_name),
    p_sector_key,btrim(coalesce(p_registration_number,'')),p_locale
  ));
  select * into v_application from public.business_applications_v95
  where idempotency_key=p_idempotency_key;
  if found then
    if v_application.request_hash<>v_hash then
      raise exception 'application_idempotency_conflict' using errcode='22023';
    end if;
    return jsonb_build_object(
      'application_id',v_application.id,
      'public_reference',v_application.public_reference,
      'status',v_application.status,'version',v_application.version,
      'replayed',true
    );
  end if;
  if exists(
    select 1 from public.business_applications_v95 application
    where application.contact_email=v_email
      and application.status in ('submitted','approved')
  ) then
    raise exception 'open_application_already_exists' using errcode='23505';
  end if;
  insert into public.business_applications_v95(
    idempotency_key,request_hash,contact_name,contact_email,contact_phone,
    business_name,sector_key,registration_number,preferred_locale
  ) values(
    p_idempotency_key,v_hash,btrim(p_contact_name),v_email,p_contact_phone,
    btrim(p_business_name),p_sector_key,
    nullif(btrim(coalesce(p_registration_number,'')),''),
    p_locale
  ) returning * into v_application;
  insert into public.business_application_audit_v95(
    application_id,event_type,new_status,reason,detail
  ) values(
    v_application.id,'submitted','submitted',
    'public pre-auth business application submitted',
    jsonb_build_object('sector_key',p_sector_key,'preferred_locale',p_locale)
  );
  return jsonb_build_object(
    'application_id',v_application.id,
    'public_reference',v_application.public_reference,
    'status','submitted','version',1,'replayed',false
  );
end
$_$;

--
-- Name: internal_verify_v176_dispatch_secret(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.internal_verify_v176_dispatch_secret(p_secret text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $_$
declare
  v_expected text;
begin
  if p_secret is null or length(p_secret) < 32 then
    return false;
  end if;
  begin
    execute 'select decrypted_secret from vault.decrypted_secrets where name = $1 order by created_at desc limit 1'
      into v_expected using 'v176_dispatch_secret';
  exception when others then
    return false;
  end;
  if coalesce(v_expected, '') = '' or length(v_expected) < 32 then
    return false;
  end if;
  return length(p_secret) = length(v_expected) and p_secret = v_expected;
end
$_$;

--
-- Name: FUNCTION internal_verify_v176_dispatch_secret(p_secret text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.internal_verify_v176_dispatch_secret(p_secret text) IS 'Service-role-only check used by the ai-firm-reports worker: does the supplied x-v176-dispatch-secret header match the Vault secret v176_dispatch_secret? Returns false (never raises) on missing/short/mismatched input so the worker can treat any non-true result as 401.';

--
-- Name: issue_campaign_offer(uuid, uuid, uuid, text, bigint, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.issue_campaign_offer(p_business uuid, p_campaign uuid, p_client uuid, p_idempotency_key text, p_offer_cost_cents bigint DEFAULT NULL::bigint, p_reward_grant_id uuid DEFAULT NULL::uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid:=auth.uid();
  v_campaign public.retention_campaigns%rowtype;
  v_rule public.retention_program_versions%rowtype;
  v_existing public.retention_campaign_grants%rowtype;
  v_existing_entitlement public.reward_grants%rowtype;
  v_existing_exposure public.retention_campaign_exposures_v99%rowtype;
  v_key text:=btrim(coalesce(p_idempotency_key,''));
  v_offer_cost bigint;
  v_issued_cost bigint;
  v_hash text;
  v_campaign_grant uuid:=gen_random_uuid();
  v_entitlement uuid;
  v_repaired boolean:=false;
  v_has_existing boolean:=false;
begin
  if v_actor is null
     or not app.is_salon_owner(p_business)
     or not app.can_module_write(p_business,'retention') then
    raise exception 'active owner retention write authorization is required'
      using errcode='42501';
  end if;
  if char_length(v_key) not between 8 and 200 then
    raise exception 'idempotency key must contain 8..200 characters'
      using errcode='22023';
  end if;
  if p_reward_grant_id is not null then
    raise exception
      'campaign reward entitlement is server-issued; reward grant input must be null'
      using errcode='22023';
  end if;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'v99:issue:'||p_business::text||':'||v_key,0
    )
  );
  select campaign.* into v_campaign
  from public.retention_campaigns campaign
  where campaign.id=p_campaign
    and campaign.business_id=p_business
  for update;
  if not found then
    raise exception 'campaign not found in this business'
      using errcode='22023';
  end if;
  if v_campaign.status<>'active' then
    raise exception 'offers require an active campaign'
      using errcode='object_not_in_prerequisite_state';
  end if;
  if not exists(
    select 1
    from public.retention_campaign_members member
    where member.campaign_id=p_campaign
      and member.business_id=p_business
      and member.client_id=p_client
      and member.assignment='treatment'
  ) then
    raise exception 'only a treatment member can receive the campaign reward'
      using errcode='42501';
  end if;
  -- v332: also require the live retention_programs row this campaign targets to still be
  -- undeleted. The rule.active check below only tests the frozen PUBLISHED snapshot, which
  -- cannot be forced false once published -- see migration header.
  select rule.* into v_rule
  from public.retention_program_versions rule
  join public.firm_config_versions config
    on config.id=rule.config_version_id
   and config.business_id=rule.business_id
   and config.status='published'
  join public.businesses business
    on business.id=rule.business_id
   and business.active_config_version_id=config.id
  join public.retention_programs prog
    on prog.id=rule.program_id
   and prog.business_id=rule.business_id
   and prog.deleted_at is null
  where rule.id=v_campaign.retention_program_version_id
    and rule.program_id=v_campaign.program_id
    and rule.business_id=p_business
    and rule.config_version_id=v_campaign.config_version_id
    and rule.active;
  if not found then
    raise exception
      'campaign reward is no longer an active published entitlement'
      using errcode='object_not_in_prerequisite_state';
  end if;
  if v_rule.fulfillment_kind='credit' then
    v_offer_cost:=v_rule.credit_cents::bigint;
    if p_offer_cost_cents is not null
       and p_offer_cost_cents<>v_offer_cost then
      raise exception
        'credit campaign cost must equal the published credit entitlement'
        using errcode='22023';
    end if;
  else
    v_offer_cost:=coalesce(p_offer_cost_cents,0);
  end if;
  if v_offer_cost<0 then
    raise exception 'offer cost cannot be negative' using errcode='22023';
  end if;

  v_hash:=pg_catalog.encode(
    extensions.digest(
      pg_catalog.convert_to(
        pg_catalog.concat_ws(
          '|','v99.campaign-entitlement',p_business::text,
          p_campaign::text,p_client::text,v_rule.id::text,
          v_rule.config_version_id::text,v_rule.fulfillment_kind,
          coalesce(v_rule.discount_percent::text,''),
          coalesce(v_rule.credit_cents::text,''),
          coalesce(v_rule.manual_item,''),v_offer_cost::text
        ),
        'UTF8'
      ),
      'sha256'
    ),
    'hex'
  );

  select campaign_grant.* into v_existing
  from public.retention_campaign_grants campaign_grant
  where campaign_grant.business_id=p_business
    and campaign_grant.idempotency_key=v_key;
  if found and (
    v_existing.campaign_id<>p_campaign
    or v_existing.client_id<>p_client
  ) then
    raise exception
      'idempotency key conflicts with another campaign entitlement'
      using errcode='23505';
  end if;
  if not found then
    select campaign_grant.* into v_existing
    from public.retention_campaign_grants campaign_grant
    where campaign_grant.campaign_id=p_campaign
      and campaign_grant.client_id=p_client;
  end if;
  v_has_existing:=found;
  if v_has_existing and v_existing.request_hash is not null
     and v_existing.request_hash<>v_hash then
    raise exception
      'campaign member already has different entitlement terms'
      using errcode='23505';
  end if;
  if v_has_existing and v_existing.offer_cost_cents<>v_offer_cost then
    raise exception
      'legacy campaign offer cost differs from the published entitlement'
      using errcode='23505';
  end if;
  if v_has_existing and v_existing.reward_grant_id is not null then
    select reward.* into v_existing_entitlement
    from public.reward_grants reward
    where reward.id=v_existing.reward_grant_id
      and reward.business_id=p_business
      and reward.client_id=p_client
      and reward.campaign_id=p_campaign
      and reward.campaign_assignment='treatment'
      and reward.retention_program_version_id=v_rule.id
      and reward.config_version_id=v_rule.config_version_id;
    if found then
      select exposure.* into v_existing_exposure
      from public.retention_campaign_exposures_v99 exposure
      where exposure.campaign_grant_id=v_existing.id;
      return pg_catalog.jsonb_build_object(
        'campaign_id',p_campaign,
        'client_id',p_client,
        'campaign_grant_id',v_existing.id,
        'grant_id',v_existing.id,
        'reward_grant_id',v_existing_entitlement.id,
        'entitlement_status',v_existing_entitlement.status,
        'fulfillment_kind',v_existing_entitlement.fulfillment_kind,
        'reward_label',v_existing_entitlement.reward_label,
        'offer_cost_cents',v_existing.offer_cost_cents,
        'exposure_status',case
          when v_existing_exposure.id is null
            then 'awaiting_manual_attestation'
          else 'verified'
        end,
        'exposure_id',v_existing_exposure.id,
        'exposed_at',v_existing_exposure.exposed_at,
        'exposure_channel',v_existing_exposure.channel,
        'delivery_provider_status','not_configured',
        'customer_history_visible',true,
        'economic_value_posted',false,
        'redemption_mode','merchant_fulfilment_pending',
        'replayed',true,
        'legacy_link_repaired',false
      );
    end if;
  end if;

  if not v_has_existing and v_campaign.budget_cap_cents>0 then
    select coalesce(sum(campaign_grant.offer_cost_cents),0)
    into v_issued_cost
    from public.retention_campaign_grants campaign_grant
    where campaign_grant.campaign_id=p_campaign
      and campaign_grant.business_id=p_business;
    if v_issued_cost+v_offer_cost>v_campaign.budget_cap_cents then
      raise exception 'campaign budget cap exceeded'
        using errcode='check_violation';
    end if;
  end if;

  insert into public.reward_grants(
    business_id,program_id,client_id,period_index,reward_type,
    reward_value,reward_item,status,granted_at,config_version_id,
    retention_program_version_id,campaign_id,campaign_assignment
  ) values(
    p_business,v_rule.program_id,p_client,0,v_rule.fulfillment_kind,
    coalesce(v_rule.discount_percent,v_rule.credit_cents,0),
    v_rule.manual_item,'granted',clock_timestamp(),v_rule.config_version_id,
    v_rule.id,p_campaign,'treatment'
  )
  returning id into v_entitlement;

  if v_has_existing then
    update public.retention_campaign_grants
    set reward_grant_id=v_entitlement,
        request_hash=v_hash
    where id=v_existing.id
    returning * into v_existing;
    v_campaign_grant:=v_existing.id;
    v_repaired:=true;
  else
    insert into public.retention_campaign_grants(
      id,campaign_id,business_id,client_id,assignment,reward_grant_id,
      offer_cost_cents,idempotency_key,issued_by,request_hash
    ) values(
      v_campaign_grant,p_campaign,p_business,p_client,'treatment',
      v_entitlement,v_offer_cost,v_key,v_actor,v_hash
    );
  end if;
  insert into public.audit_log(
    business_id,actor,action,entity,entity_id,detail
  ) values(
    p_business,v_actor,'ISSUE_CAMPAIGN_ENTITLEMENT_V99',
    'retention_campaign_grants',v_campaign_grant,
    pg_catalog.jsonb_build_object(
      'campaign_id',p_campaign,
      'client_id',p_client,
      'reward_grant_id',v_entitlement,
      'retention_program_version_id',v_rule.id,
      'fulfillment_kind',v_rule.fulfillment_kind,
      'offer_cost_cents',v_offer_cost,
      'legacy_link_repaired',v_repaired,
      'delivery_provider_status','not_configured'
    )
  );
  return pg_catalog.jsonb_build_object(
    'campaign_id',p_campaign,
    'client_id',p_client,
    'campaign_grant_id',v_campaign_grant,
    'grant_id',v_campaign_grant,
    'reward_grant_id',v_entitlement,
    'entitlement_status','granted',
    'fulfillment_kind',v_rule.fulfillment_kind,
    'reward_label',(
      select reward.reward_label
      from public.reward_grants reward
      where reward.id=v_entitlement
    ),
    'offer_cost_cents',v_offer_cost,
    'exposure_status','awaiting_manual_attestation',
    'delivery_provider_status','not_configured',
    'customer_history_visible',true,
    'economic_value_posted',false,
    'redemption_mode','merchant_fulfilment_pending',
    'replayed',v_repaired,
    'legacy_link_repaired',v_repaired
  );
end
$$;

--
-- Name: issue_gift_card(uuid, integer, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.issue_gift_card(p_business uuid, p_amount integer, p_purchaser uuid, p_recipient_email text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_code text; gc gift_cards;
begin
  if not app.is_salon_member(p_business) then raise exception 'not a member of this business'; end if;
  if p_amount is null or p_amount <= 0 then raise exception 'amount must be positive'; end if;
  -- v70 section 1: non-overlap (see the 5-arg overload). Refuse minting new legacy value when live.
  perform app.sv_legacy_issue_guard(p_business, 'gift_card');
  loop
    v_code := 'GC-' || upper(substr(md5(random()::text || clock_timestamp()::text),1,8));
    exit when not exists (select 1 from gift_cards where code = v_code);
  end loop;
  insert into gift_cards (business_id, code, initial_cents, balance_cents,
                          purchaser_client_id, recipient_email)
  values (p_business, v_code, p_amount, p_amount, p_purchaser, p_recipient_email)
  returning * into gc;
  -- was 'retail' (v5) -> cash collected against a liability, never revenue at purchase.
  insert into sales (business_id, client_id, kind, amount_cents, note)
  values (p_business, p_purchaser, 'gift_card', p_amount, 'gift card sold: ' || v_code);
  return row_to_json(gc);
end $$;

--
-- Name: issue_gift_card(uuid, integer, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.issue_gift_card(p_business uuid, p_amount integer, p_purchaser uuid, p_recipient_email text, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid:=auth.uid();
  v_staff uuid;
  v_email text:=nullif(lower(btrim(p_recipient_email)),'');
  v_payload jsonb;
  v_hash text;
  v_existing public.gift_card_issue_operations%rowtype;
  v_code text;
  v_card public.gift_cards%rowtype;
  v_sale public.sales%rowtype;
  v_result jsonb;
begin
  if v_actor is null
     or not app.can_module_write(p_business,'giftcards')
     or not app.has_perm(p_business,'create_sales') then
    raise exception 'active giftcards-module and create-sales authorization is required'
      using errcode='42501';
  end if;
  select staff_row.id into v_staff
  from public.staff staff_row
  where staff_row.business_id=p_business
    and staff_row.user_id=v_actor and staff_row.active
    and 'create_sales'=any(app.role_perms(staff_row.role))
  order by case when staff_row.role='owner' then 0 else 1 end,
           staff_row.created_at
  limit 1 for update;
  if not found then
    raise exception 'active staff authorization is required' using errcode='42501';
  end if;
  if p_idempotency_key is null or p_amount is null or p_amount<=0
     or p_amount>100000000
     or (v_email is not null and char_length(v_email)>320) then
    raise exception 'invalid gift-card issuance request' using errcode='22023';
  end if;
  if p_purchaser is not null and not exists(
    select 1 from public.clients client
    where client.id=p_purchaser and client.business_id=p_business
  ) then
    raise exception 'purchaser does not belong to this business' using errcode='22023';
  end if;
  v_payload:=jsonb_build_object(
    'amount_cents',p_amount,
    'business_id',p_business,
    'purchaser_client_id',p_purchaser,
    'recipient_email',v_email
  );
  v_hash:=app.v41_request_hash(v_payload::text);
  perform pg_advisory_xact_lock(hashtextextended(
    'v41:gift-card:'||p_business::text||':'||p_idempotency_key::text,0
  ));
  select * into v_existing
  from public.gift_card_issue_operations operation
  where operation.business_id=p_business
    and operation.idempotency_key=p_idempotency_key
  for update;
  if found then
    if v_existing.actor is distinct from v_actor
       or v_existing.request_hash<>v_hash then
      raise exception 'idempotency key conflicts with another gift-card request'
        using errcode='23505';
    end if;
    select * into v_card
    from public.gift_cards card
    where card.id=v_existing.gift_card_id
      and card.business_id=p_business
    for share;
    return jsonb_build_object(
      'status','completed',
      'gift_card_id',v_existing.gift_card_id,
      'sale_id',v_existing.sale_id,
      'code',v_card.code,
      'initial_cents',v_existing.amount_cents,
      'balance_cents',v_existing.amount_cents
    );
  end if;

  if not coalesce((
    select business.gift_card_sales_enabled
    from public.businesses business where business.id=p_business
  ),false) then
    raise exception 'gift_card_sales_disabled' using errcode='55000';
  end if;
  perform app.sv_legacy_issue_guard(p_business,'gift_card');
  if p_purchaser is not null then
    perform 1 from public.clients client
    where client.id=p_purchaser and client.business_id=p_business
    for share;
    if not found then
      raise exception 'purchaser does not belong to this business' using errcode='22023';
    end if;
  end if;
  loop
    v_code:='GC-'||upper(substr(md5(
      gen_random_uuid()::text||clock_timestamp()::text
    ),1,12));
    exit when not exists(
      select 1 from public.gift_cards card where card.code=v_code
    );
  end loop;
  insert into public.gift_cards(
    business_id,code,initial_cents,balance_cents,
    purchaser_client_id,recipient_email
  ) values(
    p_business,v_code,p_amount,p_amount,p_purchaser,v_email
  ) returning * into v_card;
  insert into public.sales(
    business_id,client_id,kind,amount_cents,note,staff_id
  ) values(
    p_business,p_purchaser,'gift_card',p_amount,
    'gift card liability issued',v_staff
  ) returning * into v_sale;
  v_result:=jsonb_build_object(
    'status','completed',
    'gift_card_id',v_card.id,
    'sale_id',v_sale.id,
    'code',v_card.code,
    'initial_cents',v_card.initial_cents,
    'balance_cents',v_card.balance_cents
  );
  insert into public.gift_card_issue_operations(
    business_id,actor,idempotency_key,request_hash,status,
    amount_cents,gift_card_id,sale_id
  ) values(
    p_business,v_actor,p_idempotency_key,v_hash,'completed',
    p_amount,v_card.id,v_sale.id
  );
  return v_result;
end
$$;

--
-- Name: issue_gift_card_at_branch_v117(uuid, uuid, integer, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.issue_gift_card_at_branch_v117(p_business uuid, p_branch uuid, p_amount integer, p_purchaser uuid, p_recipient_email text, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid:=auth.uid();
  v_staff uuid;
  v_email text:=nullif(lower(btrim(p_recipient_email)),'');
  v_payload jsonb;
  v_hash text;
  v_existing public.gift_card_issue_operations%rowtype;
  v_code text;
  v_card public.gift_cards%rowtype;
  v_sale public.sales%rowtype;
  v_result jsonb;
begin
  if v_actor is null
     or not app.can_module_write_at_v94(
       p_business,p_branch,'giftcards'
     )
     or not app.has_perm(p_business,'create_sales') then
    raise exception 'branch-effective giftcards and create-sales authorization is required'
      using errcode='42501';
  end if;
  perform 1
  from public.branches branch
  where branch.id=p_branch
    and branch.business_id=p_business
    and branch.active
    and app.can_see_branch(p_business,branch.id)
  for share;
  if not found then
    raise exception 'active visible gift-card branch is required'
      using errcode='42501';
  end if;
  select staff_row.id into v_staff
  from public.staff staff_row
  where staff_row.business_id=p_business
    and staff_row.user_id=v_actor
    and staff_row.active
    and 'create_sales'=any(app.role_perms(staff_row.role))
  order by case when staff_row.role='owner' then 0 else 1 end,
    staff_row.created_at
  limit 1
  for update;
  if not found then
    raise exception 'active staff authorization is required'
      using errcode='42501';
  end if;
  if p_idempotency_key is null or p_amount is null or p_amount<=0
     or p_amount>100000000
     or (v_email is not null and char_length(v_email)>320) then
    raise exception 'invalid gift-card issuance request' using errcode='22023';
  end if;
  if p_purchaser is not null and not exists(
    select 1
    from public.clients client
    where client.id=p_purchaser and client.business_id=p_business
  ) then
    raise exception 'purchaser does not belong to this business'
      using errcode='22023';
  end if;
  v_payload:=jsonb_build_object(
    'amount_cents',p_amount,
    'branch_id',p_branch,
    'business_id',p_business,
    'purchaser_client_id',p_purchaser,
    'recipient_email',v_email
  );
  v_hash:=app.v41_request_hash(v_payload::text);
  perform pg_advisory_xact_lock(hashtextextended(
    'v117:gift-card:'||p_business::text||':'||p_idempotency_key::text,0
  ));
  select * into v_existing
  from public.gift_card_issue_operations operation
  where operation.business_id=p_business
    and operation.idempotency_key=p_idempotency_key
  for update;
  if found then
    if v_existing.actor is distinct from v_actor
       or v_existing.request_hash<>v_hash then
      raise exception 'idempotency key conflicts with another gift-card request'
        using errcode='23505';
    end if;
    select * into v_card
    from public.gift_cards card
    where card.id=v_existing.gift_card_id
      and card.business_id=p_business
    for share;
    return jsonb_build_object(
      'status','completed',
      'gift_card_id',v_existing.gift_card_id,
      'sale_id',v_existing.sale_id,
      'code',v_card.code,
      'initial_cents',v_existing.amount_cents,
      'balance_cents',v_existing.amount_cents,
      'branch_id',p_branch,
      'replayed',true
    );
  end if;
  if not coalesce((
    select business.gift_card_sales_enabled
    from public.businesses business
    where business.id=p_business
  ),false) then
    raise exception 'gift_card_sales_disabled' using errcode='55000';
  end if;
  perform app.sv_legacy_issue_guard(p_business,'gift_card');
  loop
    v_code:='GC-'||upper(substr(md5(
      gen_random_uuid()::text||clock_timestamp()::text
    ),1,12));
    exit when not exists(
      select 1 from public.gift_cards card where card.code=v_code
    );
  end loop;
  insert into public.gift_cards(
    business_id,code,initial_cents,balance_cents,
    purchaser_client_id,recipient_email
  ) values(
    p_business,v_code,p_amount,p_amount,p_purchaser,v_email
  )
  returning * into v_card;
  insert into public.sales(
    business_id,client_id,kind,amount_cents,note,staff_id,branch_id
  ) values(
    p_business,p_purchaser,'gift_card',p_amount,
    'gift card liability issued',v_staff,p_branch
  )
  returning * into v_sale;
  v_result:=jsonb_build_object(
    'status','completed',
    'gift_card_id',v_card.id,
    'sale_id',v_sale.id,
    'code',v_card.code,
    'initial_cents',v_card.initial_cents,
    'balance_cents',v_card.balance_cents,
    'branch_id',p_branch,
    'replayed',false
  );
  insert into public.gift_card_issue_operations(
    business_id,actor,idempotency_key,request_hash,status,
    amount_cents,gift_card_id,sale_id
  ) values(
    p_business,v_actor,p_idempotency_key,v_hash,'completed',
    p_amount,v_card.id,v_sale.id
  );
  return v_result;
end
$$;

--
-- Name: join_program(text, text, text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.join_program(p_slug text, p_name text, p_phone text, p_email text DEFAULT NULL::text, p_consent boolean DEFAULT false) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_biz uuid; v_biz_name text; v_norm text; v_client uuid;
begin
  select id, name into v_biz, v_biz_name
    from public.businesses where slug = p_slug and join_enabled;
  if v_biz is null then raise exception 'This sign-up link is not active.'; end if;

  if p_name is null or length(trim(p_name)) < 2 then
    raise exception 'Please enter your name.';
  end if;
  if length(trim(p_name)) > 80 then raise exception 'Name is too long.'; end if;

  v_norm := app.norm_phone(p_phone);
  if v_norm is null then
    raise exception 'Please enter a valid 8-digit Singapore mobile number.';
  end if;

  insert into public.clients (business_id, full_name, phone, email, marketing_consent)
  values (v_biz, trim(p_name), v_norm,
          nullif(trim(coalesce(p_email,'')), ''), coalesce(p_consent, false))
  on conflict (business_id, phone_norm) where phone_norm is not null do nothing
  returning id into v_client;

  if v_client is not null then
    -- PDPA: record the consent decision at the moment it was made, with its source.
    insert into public.consents (business_id, client_id, channel, action, source)
    values (v_biz, v_client, 'marketing',
            case when coalesce(p_consent,false) then 'granted' else 'withdrawn' end,
            'self_signup');
    insert into public.audit_log (business_id, actor, action, entity, entity_id, detail)
    values (v_biz, null, 'CUSTOMER_SELF_SIGNUP', 'clients', v_client,
            json_build_object('source','qr_or_link','consent',coalesce(p_consent,false))::jsonb);
  end if;

  return json_build_object('status','ok','business_name', v_biz_name);
end $$;

--
-- Name: lift_emergency_pause(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lift_emergency_pause(p_business uuid, p_rule_id uuid, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_id uuid; v_reason text := nullif(btrim(coalesce(p_reason, '')), '');
begin
  if not app.is_salon_owner(p_business) then raise exception 'owner only' using errcode = '42501'; end if;
  update public.studio_rule_emergency_pauses
     set lifted_at = now(), lifted_by = auth.uid()
   where business_id = p_business and rule_id = p_rule_id and lifted_at is null
   returning id into v_id;
  if v_id is null then
    return jsonb_build_object('status', 'ok', 'business_id', p_business, 'rule_id', p_rule_id,
      'lifted', false, 'replayed', true);
  end if;
  insert into public.audit_log(business_id, actor, action, entity, entity_id, detail)
  values(p_business, auth.uid(), 'STUDIO_RULE_EMERGENCY_PAUSE_LIFTED', 'program_rules', p_rule_id,
    jsonb_build_object('rule_id', p_rule_id, 'pause_id', v_id, 'reason', v_reason));
  return jsonb_build_object('status', 'ok', 'business_id', p_business, 'rule_id', p_rule_id,
    'lifted', true, 'pause_id', v_id, 'replayed', false);
end $$;

--
-- Name: list_bar_bottles_v275(uuid, uuid, text, text, integer, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_bar_bottles_v275(p_business uuid, p_branch uuid, p_status text, p_search text, p_expiring_days integer, p_bottle uuid, p_limit integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_status text := lower(btrim(coalesce(p_status, '')));
  v_search text := nullif(btrim(coalesce(p_search, '')), '');
  v_limit integer := least(greatest(coalesce(p_limit, 100), 1), 200);
  v_storage boolean;
  v_items jsonb;
  v_counts jsonb;
  v_bottle public.bar_bottles%rowtype;
  v_events jsonb;
begin
  perform app.require_bar_business_v275(p_business);
  perform app.require_bar_staff_v275(p_business, false);

  -- Empty and 'storage' are the same question, so the default tab and an explicit Storage tab
  -- cannot drift apart.
  v_storage := v_status in ('', 'storage');

  if p_bottle is not null then
    select * into v_bottle from public.bar_bottles bottle
     where bottle.id = p_bottle and bottle.business_id = p_business;
    if not found then
      raise exception 'bottle not found' using errcode = '22023';
    end if;
    select coalesce(jsonb_agg(jsonb_build_object(
             'id', event.id, 'kind', event.kind, 'detail', event.detail,
             'occurred_at', event.occurred_at,
             'actor_name', staff_row.full_name
           ) order by event.occurred_at desc, event.id desc), '[]'::jsonb)
      into v_events
      from public.bar_bottle_events event
      left join public.staff staff_row
        on staff_row.business_id = p_business and staff_row.user_id = event.actor
     where event.bottle_id = v_bottle.id;
    return jsonb_build_object(
      'status', 'ok',
      'keep_days', app.bar_keep_days_v275(p_business),
      'auto_keep_days', app.bar_keep_days_for_client_v278(p_business, v_bottle.client_id),
      'storage_capacity', app.bar_storage_capacity_v279(p_business),
      'in_storage', app.bar_in_storage_count_v279(p_business),
      'can_write', app.is_salon_owner(p_business) or app.can_module_write(p_business, 'bottles'),
      'bottle', app.bar_bottle_json_v275(v_bottle)
        || jsonb_build_object('client_name', (
             select client.full_name from public.clients client where client.id = v_bottle.client_id
           ))
        || jsonb_build_object('client_phone', (
             select client.phone from public.clients client where client.id = v_bottle.client_id
           )),
      'events', v_events);
  end if;

  select coalesce(jsonb_agg(entry order by ordering_expires, ordering_serial), '[]'::jsonb)
    into v_items
    from (
      select app.bar_bottle_json_v275(bottle)
             || jsonb_build_object('client_name', client.full_name,
                                   'client_phone', client.phone) as entry,
             bottle.expires_at as ordering_expires,
             bottle.serial_seq as ordering_serial
        from public.bar_bottles bottle
        join public.clients client on client.id = bottle.client_id
        left join public.products product on product.id = bottle.product_id
       where bottle.business_id = p_business
         and (p_branch is null or bottle.branch_id = p_branch)
         and (v_status = 'all'
              or (v_storage and bottle.status in ('stored', 'called', 'at_table'))
              or (not v_storage and v_status <> 'all' and bottle.status = v_status))
         and (p_expiring_days is null
              or (bottle.status in ('stored', 'called', 'at_table')
                  and bottle.expires_at is not null
                  and bottle.expires_at <= now() + make_interval(days => p_expiring_days)))
         and (v_search is null
              or client.full_name ilike '%' || v_search || '%'
              or coalesce(client.phone, '') ilike '%' || v_search || '%'
              or bottle.serial_code ilike '%' || v_search || '%'
              or coalesce(bottle.label, '') ilike '%' || v_search || '%'
              or coalesce(product.name, '') ilike '%' || v_search || '%')
       order by bottle.expires_at, bottle.serial_seq
       limit v_limit
    ) page;

  -- The counts describe the WHOLE floor for this branch, never the filtered page: a number that
  -- shrank when you typed a search would be reporting the search, not the bar. 'active' and
  -- 'in_storage' are the same three states under two names because the dashboard reads one and
  -- the capacity gauge reads the other; keeping them one expression stops them disagreeing.
  select jsonb_build_object(
           'stored', count(*) filter (where bottle.status = 'stored'),
           'called', count(*) filter (where bottle.status = 'called'),
           'at_table', count(*) filter (where bottle.status = 'at_table'),
           'retrieved', count(*) filter (where bottle.status = 'retrieved'),
           'expired', count(*) filter (where bottle.status = 'expired'),
           'in_storage', count(*) filter (
             where bottle.status in ('stored', 'called', 'at_table')),
           'active', count(*) filter (
             where bottle.status in ('stored', 'called', 'at_table')),
           'expiring_soon', count(*) filter (
             where bottle.status in ('stored', 'called', 'at_table')
               and bottle.expires_at is not null
               and bottle.expires_at <= now() + make_interval(days => 7)))
    into v_counts
    from public.bar_bottles bottle
   where bottle.business_id = p_business
     and (p_branch is null or bottle.branch_id = p_branch);

  return jsonb_build_object(
    'status', 'ok',
    'as_of', now(),
    'keep_days', app.bar_keep_days_v275(p_business),
    'storage_capacity', app.bar_storage_capacity_v279(p_business),
    'in_storage', app.bar_in_storage_count_v279(p_business),
    'can_write', app.is_salon_owner(p_business) or app.can_module_write(p_business, 'bottles'),
    'counts', v_counts,
    'items', v_items);
end;
$$;

--
-- Name: list_client_erasures_v290(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_client_erasures_v290(p_business uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 100) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_limit integer := least(greatest(coalesce(p_limit,100),1),500);
  v_items jsonb;
begin
  if not app.is_super_admin() then
    raise exception 'platform administrator required' using errcode = '42501';
  end if;
  select coalesce(jsonb_agg(jsonb_build_object(
    'id',record.id,
    'business_id',record.business_id,
    'business_name',business.name,
    'client_id',record.client_id,
    'actor',record.actor,
    'reason',record.reason,
    'erased_fields',record.erased_fields,
    'created_at',record.created_at
  ) order by record.created_at desc, record.id desc),'[]'::jsonb)
    into v_items
    from (
      select * from public.client_erasures_v290 row_in
       where p_business is null or row_in.business_id = p_business
       order by row_in.created_at desc, row_in.id desc
       limit v_limit
    ) record
    left join public.businesses business on business.id = record.business_id;
  return jsonb_build_object('status','ok','limit',v_limit,'items',v_items);
end;
$$;

--
-- Name: list_customer_redemption_history_v145(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_customer_redemption_history_v145(p_business uuid, p_client uuid) RETURNS TABLE(id uuid, redeemed_at timestamp with time zone, reward_name text, points_spent integer, credit_cents integer, fulfillment_kind text, reversal_id uuid, reversed_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if auth.uid() is null
     or not app.has_perm(p_business, 'view_sales')
     or not app.can_module_read(p_business, 'loyalty') then
    raise exception 'active Loyalty read authorization is required'
      using errcode = '42501';
  end if;
  if not exists (
    select 1 from public.clients client
     where client.id = p_client and client.business_id = p_business
  ) then
    raise exception 'customer not found in this business'
      using errcode = '42501';
  end if;

  return query
  select redemption.id,
         redemption.redeemed_at,
         redemption.reward_name,
         redemption.points_spent,
         redemption.credit_cents,
         redemption.fulfillment_kind,
         reversal.id,
         reversal.created_at
    from public.loyalty_redemptions redemption
    left join public.loyalty_redemption_reversals reversal
      on reversal.business_id = redemption.business_id
     and reversal.redemption_id = redemption.id
   where redemption.business_id = p_business
     and redemption.client_id = p_client
   order by redemption.redeemed_at desc, redemption.id desc;
end;
$$;

--
-- Name: list_my_appointments(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_my_appointments(p_slug text, p_phone text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_biz uuid; v_key text; v_result json;
begin
  select id into v_biz from public.businesses where slug = p_slug;
  if v_biz is null then raise exception 'business not found'; end if;
  v_key := app.phone_match_key(p_phone);
  select coalesce(json_agg(row_to_json(t) order by t.starts_at), '[]'::json) into v_result
  from (
    select a.id, a.starts_at, s.name as service_name, a.status
    from public.appointments a
    join public.clients c on c.id = a.client_id
    left join public.services s on s.id = a.service_id
    where a.business_id = v_biz
      and a.status = 'booked'
      and a.starts_at > now()
      and v_key is not null
      and app.phone_match_key(c.phone) = v_key
    order by a.starts_at
  ) t;
  return v_result;
end $$;

--
-- Name: list_retention_campaigns(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_retention_campaigns(p_business uuid) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_result json;
begin
  if auth.uid() is null
     or not app.has_perm(p_business, 'view_finance')
     or not app.can_module_read(p_business, 'retention') then
    raise exception 'active owner or manager retention read authorization is required'
      using errcode = '42501';
  end if;
  select coalesce(jsonb_agg(c.obj order by c.created_at desc), '[]'::jsonb)::json
    into v_result
    from (
      select rc.created_at,
        jsonb_build_object(
          'campaign_id', rc.id,
          'name', rc.name,
          'status', rc.status,
          'holdout_percent', rc.holdout_percent,
          'audience_size', rc.audience_size,
          'budget_cap_cents', rc.budget_cap_cents,
          'expected_cost_cents', rc.expected_cost_cents,
          'expected_upside_cents', rc.expected_upside_cents,
          'attribution_window_days', rc.attribution_window_days,
          'retention_program_version_id', rc.retention_program_version_id,
          'offers_issued', (
            select count(*) from public.retention_campaign_grants g
             where g.campaign_id = rc.id and g.business_id = rc.business_id),
          'created_at', rc.created_at,
          'activated_at', rc.activated_at
        ) as obj
      from public.retention_campaigns rc
      where rc.business_id = p_business
      order by rc.created_at desc
      limit 500
    ) c;
  return v_result;
end $$;

--
-- Name: list_staff_blocked_times_v120(uuid, uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_staff_blocked_times_v120(p_business uuid, p_branch uuid, p_from timestamp with time zone, p_to timestamp with time zone) RETURNS TABLE(id uuid, staff_id uuid, starts_at timestamp with time zone, ends_at timestamp with time zone, reason text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if p_business is null or p_branch is null or p_from is null or p_to is null
     or p_to <= p_from or p_to > p_from + interval '366 days'
     or not app.can_module_read_at_v94(p_business,p_branch,'appointments') then
    raise exception 'permission denied or invalid blocked-time window'
      using errcode='42501';
  end if;

  -- A staff member cannot be free at two branches at once. Return local blocks
  -- with their management data and redact cross-branch details to "busy"
  -- while still letting the current branch suppress false availability.
  return query
    select
      case when blocked.branch_id=p_branch then blocked.id else null end,
      blocked.staff_id,blocked.starts_at,blocked.ends_at,
      case when blocked.branch_id=p_branch then blocked.reason else null end
      from public.staff_blocked_times blocked
     where blocked.business_id=p_business
       and exists (
         select 1 from public.staff_branches assignment
          where assignment.business_id=p_business
            and assignment.branch_id=p_branch
            and assignment.staff_id=blocked.staff_id
       )
       and blocked.starts_at < p_to and blocked.ends_at > p_from
     order by blocked.starts_at,blocked.staff_id,blocked.id;
end
$$;

--
-- Name: lookup_client_by_phone(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lookup_client_by_phone(p_business uuid, p_phone text) RETURNS json
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_norm text;
  c public.clients%rowtype;
  lp record;
  v_points integer;
  v_credit integer;
  v_visits integer;
begin
  if not app.has_perm(p_business, 'create_sales')
     or not app.can_module_read(p_business, 'clients') then
    raise exception 'clients read and create-sales authorization is required'
      using errcode = '42501';
  end if;
  v_norm := app.norm_phone(p_phone);
  if v_norm is null then
    return json_build_object('status','invalid',
      'message','Enter the customer''s 8-digit mobile number.');
  end if;
  select * into c from public.clients
   where business_id = p_business and phone_norm = v_norm;
  if not found then
    return json_build_object('status','not_found','phone',v_norm);
  end if;
  v_points := app.client_points_balance_v409(p_business, c.id);
  select coalesce(sum(amount_cents),0) into v_credit
    from public.credit_ledger where business_id=p_business and client_id=c.id;
  select count(*) into v_visits
    from public.sales where business_id=p_business and client_id=c.id and counts_as_visit;
  select * into lp from public.loyalty_programs
   where business_id=p_business and active limit 1;
  return json_build_object(
    'status','found','client_id',c.id,'full_name',c.full_name,'phone',c.phone_norm,
    'points',v_points,'credit_cents',v_credit,'visits',v_visits,
    'redeem_points',lp.redeem_points,'reward_credit_cents',lp.reward_credit_cents,
    'can_redeem',(lp.redeem_points is not null and v_points>=lp.redeem_points),
    'points_to_next',greatest(coalesce(lp.redeem_points,0)-v_points,0),
    'member_since',c.created_at);
end
$$;

--
-- Name: mark_all_notifications_read(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_all_notifications_read(p_business uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_count int;
begin
  if not app.is_salon_member(p_business) then raise exception 'not authorized'; end if;
  update public.notifications set read_at = now()
   where business_id = p_business and read_at is null;
  get diagnostics v_count = row_count;
  return json_build_object('status','ok','updated', v_count);
end $$;

--
-- Name: mark_notification_read(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_notification_read(p_id uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_count int;
begin
  update public.notifications set read_at = coalesce(read_at, now())
   where id = p_id and app.is_salon_member(business_id);
  get diagnostics v_count = row_count;
  return json_build_object('status','ok','updated', v_count);
end $$;

--
-- Name: mark_pos_paynow_refund_state_v142(uuid, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_pos_paynow_refund_state_v142(p_attempt uuid, p_event_id text, p_refund_id text, p_provider_status text, p_failure_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_attempt public.pos_payment_attempts_v142%rowtype;
        v_status text;
        v_signed_event boolean;
begin
  perform app.v142_service_guard();
  if p_provider_status not in ('pending','requires_action','succeeded','failed','canceled') then
    raise exception 'unsupported Stripe refund state' using errcode='22023';
  end if;
  select * into v_attempt from public.pos_payment_attempts_v142 where id=p_attempt for update;
  if not found or v_attempt.status not in
      ('refund_required','refund_pending','refund_failed','refunded') then
    raise exception 'payment attempt is not awaiting a refund' using errcode='22023';
  end if;
  if v_attempt.provider_refund_id is not null
     and v_attempt.provider_refund_id is distinct from p_refund_id then
    raise exception 'payment attempt is already bound to another refund' using errcode='23505';
  end if;
  v_signed_event:=current_setting('app.v142_signed_refund_event',true)=p_event_id;
  -- Direct refunds.create responses are requests, not terminal truth. Once any
  -- signed event has been projected, a delayed API response is a strict no-op.
  if not v_signed_event and v_attempt.refund_event_id is not null then
    return jsonb_build_object('status',v_attempt.status,'attempt_id',p_attempt,
      'refund_id',v_attempt.provider_refund_id,'signed_event_preserved',true);
  end if;
  v_status:=case when not v_signed_event then 'refund_pending'
    when p_provider_status='succeeded' then 'refunded'
    when p_provider_status in ('failed','canceled') then 'refund_failed'
    else 'refund_pending' end;
  update public.pos_payment_attempts_v142 set status=v_status,
    provider_refund_id=p_refund_id,
    failure_code=case when v_status='refund_failed' then 'refund_failed'
                      when v_status='refunded' then null else failure_code end,
    refund_failure_reason=case when v_status='refund_failed'
      then left(coalesce(nullif(p_failure_reason,''),'Stripe reported that the refund failed'),300)
      when v_status='refunded' then null else refund_failure_reason end,
    updated_at=now() where id=p_attempt;
  update public.stripe_connect_event_inbox_v142 set processing_status=v_status,
    processing_result=coalesce(processing_result,'{}'::jsonb)||jsonb_build_object(
      'status',v_status,'attempt_id',p_attempt,'refund_id',p_refund_id,
      'provider_refund_status',p_provider_status),
    processed_at=now() where event_id=p_event_id;
  return jsonb_build_object('status',v_status,'attempt_id',p_attempt,'refund_id',p_refund_id);
end $$;

--
-- Name: merchant_scan_redemption_qr_v117(uuid, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.merchant_scan_redemption_qr_v117(p_business uuid, p_branch uuid, p_qr_token text, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_intent public.customer_redemption_intents_v89%rowtype;
  v_result jsonb;
  v_redemption uuid;
  v_operation uuid;
  v_operation_type text;
  v_program public.loyalty_programs%rowtype;
  v_reward_version public.loyalty_reward_versions%rowtype;
  v_current_quote jsonb;
  v_customer_name text;
  v_reward_label text;
begin
  if p_idempotency_key is null or length(coalesce(p_qr_token,''))<32 then
    raise exception 'invalid redemption QR scan' using errcode='22023';
  end if;
  if not app.can_module_write_at_v94(p_business,p_branch,'loyalty')
     or not app.has_perm(p_business,'create_sales') then
    raise exception 'merchant loyalty redemption access is required'
      using errcode='42501';
  end if;
  if p_branch is null
     or not exists(
       select 1
       from public.branches branch
       where branch.id=p_branch
         and branch.business_id=p_business
         and branch.active
     ) then
    raise exception 'an active business branch is required'
      using errcode='22023';
  end if;
  if not app.can_see_branch(p_business,p_branch) then
    raise exception 'redemption branch scope is not permitted'
      using errcode='42501';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(
    'v117:scan:'||p_business::text||':'||app.v89_sha256(p_qr_token),0));
  select *
    into v_intent
    from public.customer_redemption_intents_v89 intent
   where intent.business_id=p_business
     and intent.token_hash=app.v89_sha256(p_qr_token)
   for update;
  if not found then
    raise exception 'redemption QR is invalid' using errcode='22023';
  end if;

  if v_intent.status='completed' then
    insert into public.customer_redemption_events_v89(
      intent_id,business_id,actor,event_type,idempotency_key,detail
    ) values(
      v_intent.id,p_business,auth.uid(),'scan_replayed',p_idempotency_key,
      jsonb_build_object(
        'redemption_kind',v_intent.redemption_kind,
        'redemption_id',v_intent.redemption_id,
        'operation_id',v_intent.completion_operation_id,
        'branch_id',p_branch
      )
    )
    on conflict(intent_id,event_type,idempotency_key) do nothing;
    return v_intent.completion_result||jsonb_build_object('replayed',true);
  end if;
  if v_intent.status<>'pending' then
    raise exception 'redemption QR is no longer pending' using errcode='22023';
  end if;
  if v_intent.expires_at<=now() then
    perform set_config('app.v89_redemption_intent_id',v_intent.id::text,true);
    update public.customer_redemption_intents_v89
       set status='expired'
     where id=v_intent.id;
    perform set_config('app.v89_redemption_intent_id','',true);
    insert into public.customer_redemption_events_v89(
      intent_id,business_id,actor,event_type,idempotency_key,detail
    ) values(
      v_intent.id,p_business,auth.uid(),'intent_expired',p_idempotency_key,
      jsonb_build_object('expired_at',v_intent.expires_at,'branch_id',p_branch)
    );
    return jsonb_build_object(
      'intent_id',v_intent.id,
      'status','expired',
      'expires_at',v_intent.expires_at,
      'branch_id',p_branch,
      'replayed',false
    );
  end if;
  if not app.platform_feature_enabled('customer_qr_redemption')
     or not coalesce((
       select capability.redemption_enabled
         from public.business_customer_capabilities_v89 capability
        where capability.business_id=p_business
     ),false)
     or not app.v89_business_module_enabled(p_business,'loyalty') then
    raise exception 'customer redemption is disabled for this business'
      using errcode='42501';
  end if;

  select *
    into v_program
    from public.loyalty_programs program
   where program.id=v_intent.quoted_program_id
     and program.business_id=p_business
   for share;
  if not found then
    raise exception 'redemption configuration changed; create a new QR'
      using errcode='23514';
  end if;
  if not exists(select 1 from public.business_programmes spine
                 where spine.business_id=p_business and spine.active
                   and spine.kind in ('points','stamps')) then
    raise exception 'redemption configuration changed; create a new QR'
      using errcode='23514';
  end if;
  select client.full_name
    into v_customer_name
    from public.clients client
   where client.id=v_intent.client_id
     and client.business_id=p_business;

  if v_intent.redemption_kind='classic_points' then
    v_current_quote:=jsonb_build_object(
      'program_id',v_program.id,
      'config_version_id',v_program.current_config_version_id,
      'loyalty_model',v_program.loyalty_model,
      'kind',v_program.kind,
      'points_spent',v_program.redeem_points,
      'credit_cents',v_program.reward_credit_cents
    );
    if v_current_quote is distinct from v_intent.quoted_terms then
      raise exception 'classic redemption terms changed; create a new QR'
        using errcode='23514';
    end if;
    v_reward_label:='Store credit';
    v_operation_type:='redeem_points';
    -- The public legacy wrapper authorizes at firm scope. This branch-aware
    -- scanner has already locked and proven the exact branch permission, so it
    -- calls the private canonical writer and keeps every economic invariant
    -- and idempotency record without widening browser execution rights.
    v_result:=app.redeem_points_v40_internal(
      p_business,v_intent.client_id,'v117:'||v_intent.id::text
    )::jsonb;
  else
    select reward_version.*
      into v_reward_version
      from public.loyalty_reward_versions reward_version
      join public.businesses business
        on business.id=reward_version.business_id
     where reward_version.id=v_intent.quoted_reward_version_id
       and reward_version.reward_id=v_intent.reward_id
       and reward_version.business_id=p_business
       and reward_version.config_version_id=business.active_config_version_id
       and reward_version.active
     for share;
    if not found
       or exists(
         select 1
           from public.loyalty_reward_services restriction
          where restriction.reward_version_id=v_intent.quoted_reward_version_id
       )
       or exists(
         select 1
           from public.loyalty_reward_products restriction
          where restriction.reward_version_id=v_intent.quoted_reward_version_id
       ) then
      raise exception 'catalog redemption terms changed; create a new QR'
        using errcode='23514';
    end if;
    if exists(
      select 1
        from public.loyalty_reward_branches restriction
       where restriction.reward_version_id=v_intent.quoted_reward_version_id
    ) and not exists(
      select 1
        from public.loyalty_reward_branches restriction
       where restriction.reward_version_id=v_intent.quoted_reward_version_id
         and restriction.branch_id=p_branch
    ) then
      raise exception 'reward is not eligible at this branch'
        using errcode='23514';
    end if;
    v_current_quote:=jsonb_build_object(
      'program_id',v_program.id,
      'config_version_id',v_reward_version.config_version_id,
      'reward_version_id',v_reward_version.id,
      'reward_id',v_intent.reward_id,
      'points_spent',v_reward_version.cost_points,
      'credit_cents',v_reward_version.credit_cents,
      'fulfillment_kind',v_reward_version.fulfillment_kind,
      'claim_available_from',v_reward_version.claim_available_from,
      'claim_available_until',v_reward_version.claim_available_until,
      'usage_limit',v_reward_version.usage_limit,
      'active',v_reward_version.active
    );
    if v_current_quote is distinct from v_intent.quoted_terms then
      raise exception 'catalog redemption terms changed; create a new QR'
        using errcode='23514';
    end if;
    v_reward_label:=coalesce(v_reward_version.customer_name,'Reward');
    v_operation_type:='redeem_reward';
    -- As above, avoid the legacy firm-scoped public wrapper after the exact
    -- branch authorization. The private canonical writer is not executable by
    -- browser roles and still records the normal redemption/provenance chain.
    v_result:=app.redeem_reward_core(
      p_business,
      v_intent.client_id,
      v_intent.reward_id,
      'v117:'||v_intent.id::text,
      p_branch,
      null,
      null
    )::jsonb;
  end if;

  select operation.id
    into v_operation
    from public.loyalty_operations operation
   where operation.business_id=p_business
     and operation.operation_type=v_operation_type
     and operation.idempotency_key='v117:'||v_intent.id::text
     and operation.status='completed';
  if not found then
    raise exception 'canonical redemption operation was not recorded'
      using errcode='40001';
  end if;
  if v_intent.redemption_kind='catalog_reward' then
    select provenance.redemption_id
      into v_redemption
      from public.loyalty_redemption_provenance provenance
     where provenance.business_id=p_business
       and provenance.operation_id=v_operation;
    if not found then
      raise exception 'canonical catalog redemption was not recorded'
        using errcode='40001';
    end if;
  end if;

  v_result:=jsonb_build_object(
    'intent_id',v_intent.id,
    'status','completed',
    'redemption_kind',v_intent.redemption_kind,
    'completed_at',now(),
    'branch_id',p_branch,
    'operation_id',v_operation,
    'redemption_id',v_redemption,
    'customer_name',v_customer_name,
    'reward_label',v_reward_label,
    'points_spent',v_intent.quoted_points_spent,
    'credit_cents',v_intent.quoted_credit_cents,
    'result',v_result,
    'replayed',false
  );
  perform set_config('app.v89_redemption_intent_id',v_intent.id::text,true);
  update public.customer_redemption_intents_v89
     set status='completed',
         completed_at=now(),
         completed_by=auth.uid(),
         completion_idempotency_key=p_idempotency_key,
         redemption_id=v_redemption,
         completion_operation_id=v_operation,
         completion_result=v_result
   where id=v_intent.id;
  perform set_config('app.v89_redemption_intent_id','',true);
  insert into public.customer_redemption_events_v89(
    intent_id,business_id,actor,event_type,idempotency_key,detail
  ) values(
    v_intent.id,p_business,auth.uid(),'scan_completed',p_idempotency_key,
    jsonb_build_object(
      'redemption_kind',v_intent.redemption_kind,
      'redemption_id',v_redemption,
      'operation_id',v_operation,
      'branch_id',p_branch
    )
  );
  return v_result;
end
$$;

--
-- Name: merchant_scan_redemption_qr_v89(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.merchant_scan_redemption_qr_v89(p_business uuid, p_qr_token text, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_intent public.customer_redemption_intents_v89%rowtype;
  v_result jsonb;v_redemption uuid;v_operation uuid;v_operation_type text;
  v_program public.loyalty_programs%rowtype;
  v_reward_version public.loyalty_reward_versions%rowtype;
  v_current_quote jsonb;
  v_customer_name text;v_reward_label text;
begin
  if p_idempotency_key is null or length(coalesce(p_qr_token,''))<32 then
    raise exception 'invalid redemption QR scan' using errcode='22023';
  end if;
  if not app.can_module_write(p_business,'loyalty')
     or not app.has_perm(p_business,'create_sales') then
    raise exception 'merchant loyalty redemption access is required'
      using errcode='42501';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(
    'v89:scan:'||p_business::text||':'||app.v89_sha256(p_qr_token),0));
  select * into v_intent from public.customer_redemption_intents_v89 intent
  where intent.business_id=p_business
    and intent.token_hash=app.v89_sha256(p_qr_token) for update;
  if not found then raise exception 'redemption QR is invalid' using errcode='22023';end if;
  if v_intent.status='completed' then
    insert into public.customer_redemption_events_v89(
      intent_id,business_id,actor,event_type,idempotency_key,detail
    ) values(v_intent.id,p_business,auth.uid(),'scan_replayed',p_idempotency_key,
      jsonb_build_object('redemption_kind',v_intent.redemption_kind,
        'redemption_id',v_intent.redemption_id,
        'operation_id',v_intent.completion_operation_id))
    on conflict(intent_id,event_type,idempotency_key) do nothing;
    return v_intent.completion_result||jsonb_build_object('replayed',true);
  end if;
  if v_intent.status<>'pending' then
    raise exception 'redemption QR is no longer pending' using errcode='22023';
  end if;
  if v_intent.expires_at<=now() then
    perform set_config('app.v89_redemption_intent_id',v_intent.id::text,true);
    update public.customer_redemption_intents_v89 set status='expired'
      where id=v_intent.id;
    perform set_config('app.v89_redemption_intent_id','',true);
    insert into public.customer_redemption_events_v89(
      intent_id,business_id,actor,event_type,idempotency_key,detail
    ) values(v_intent.id,p_business,auth.uid(),'intent_expired',p_idempotency_key,
      jsonb_build_object('expired_at',v_intent.expires_at));
    return jsonb_build_object('intent_id',v_intent.id,'status','expired',
      'expires_at',v_intent.expires_at,'replayed',false);
  end if;
  if not app.platform_feature_enabled('customer_qr_redemption')
     or not coalesce((select capability.redemption_enabled
       from public.business_customer_capabilities_v89 capability
       where capability.business_id=p_business),false)
     or not app.v89_business_module_enabled(p_business,'loyalty') then
    raise exception 'customer redemption is disabled for this business'
      using errcode='42501';
  end if;
  select * into v_program from public.loyalty_programs program
  where program.id=v_intent.quoted_program_id
    and program.business_id=p_business for share;
  if not found then
    raise exception 'redemption configuration changed; create a new QR'
      using errcode='23514';
  end if;
  if not exists(select 1 from public.business_programmes spine
                 where spine.business_id=p_business and spine.active
                   and spine.kind in ('points','stamps')) then
    raise exception 'redemption configuration changed; create a new QR'
      using errcode='23514';
  end if;
  select client.full_name into v_customer_name from public.clients client
  where client.id=v_intent.client_id and client.business_id=p_business;
  if v_intent.redemption_kind='classic_points' then
    v_current_quote:=jsonb_build_object(
      'program_id',v_program.id,
      'config_version_id',v_program.current_config_version_id,
      'loyalty_model',v_program.loyalty_model,'kind',v_program.kind,
      'points_spent',v_program.redeem_points,
      'credit_cents',v_program.reward_credit_cents);
    if v_current_quote is distinct from v_intent.quoted_terms then
      raise exception 'classic redemption terms changed; create a new QR'
        using errcode='23514';
    end if;
    v_reward_label:='Store credit';
    v_operation_type:='redeem_points';
    v_result:=public.redeem_points(
      p_business,v_intent.client_id,'v89:'||v_intent.id::text
    )::jsonb;
  else
    select reward_version.* into v_reward_version
    from public.loyalty_reward_versions reward_version
    join public.businesses business on business.id=reward_version.business_id
    where reward_version.id=v_intent.quoted_reward_version_id
      and reward_version.reward_id=v_intent.reward_id
      and reward_version.business_id=p_business
      and reward_version.config_version_id=business.active_config_version_id
      and reward_version.active for share;
    if not found
       or exists(select 1 from public.loyalty_reward_branches restriction
         where restriction.reward_version_id=v_intent.quoted_reward_version_id)
       or exists(select 1 from public.loyalty_reward_services restriction
         where restriction.reward_version_id=v_intent.quoted_reward_version_id)
       or exists(select 1 from public.loyalty_reward_products restriction
         where restriction.reward_version_id=v_intent.quoted_reward_version_id) then
      raise exception 'catalog redemption terms changed; create a new QR'
        using errcode='23514';
    end if;
    v_current_quote:=jsonb_build_object(
      'program_id',v_program.id,
      'config_version_id',v_reward_version.config_version_id,
      'reward_version_id',v_reward_version.id,'reward_id',v_intent.reward_id,
      'points_spent',v_reward_version.cost_points,
      'credit_cents',v_reward_version.credit_cents,
      'fulfillment_kind',v_reward_version.fulfillment_kind,
      'claim_available_from',v_reward_version.claim_available_from,
      'claim_available_until',v_reward_version.claim_available_until,
      'usage_limit',v_reward_version.usage_limit,
      'active',v_reward_version.active);
    if v_current_quote is distinct from v_intent.quoted_terms then
      raise exception 'catalog redemption terms changed; create a new QR'
        using errcode='23514';
    end if;
    v_reward_label:=coalesce(v_reward_version.customer_name,'Reward');
    v_operation_type:='redeem_reward';
    v_result:=public.redeem_reward(
      p_business,v_intent.client_id,v_intent.reward_id,
      'v89:'||v_intent.id::text
    )::jsonb;
  end if;
  select operation.id into v_operation from public.loyalty_operations operation
  where operation.business_id=p_business
    and operation.operation_type=v_operation_type
    and operation.idempotency_key='v89:'||v_intent.id::text
    and operation.status='completed';
  if not found then
    raise exception 'canonical redemption operation was not recorded'
      using errcode='40001';
  end if;
  if v_intent.redemption_kind='catalog_reward' then
    select provenance.redemption_id into v_redemption
    from public.loyalty_redemption_provenance provenance
    where provenance.business_id=p_business
      and provenance.operation_id=v_operation;
    if not found then
      raise exception 'canonical catalog redemption was not recorded'
        using errcode='40001';
    end if;
  end if;
  v_result:=jsonb_build_object('intent_id',v_intent.id,'status','completed',
    'redemption_kind',v_intent.redemption_kind,'completed_at',now(),
    'operation_id',v_operation,'redemption_id',v_redemption,
    'customer_name',v_customer_name,'reward_label',v_reward_label,
    'points_spent',v_intent.quoted_points_spent,
    'credit_cents',v_intent.quoted_credit_cents,
    'result',v_result,'replayed',false);
  perform set_config('app.v89_redemption_intent_id',v_intent.id::text,true);
  update public.customer_redemption_intents_v89 set
    status='completed',completed_at=now(),completed_by=auth.uid(),
    completion_idempotency_key=p_idempotency_key,redemption_id=v_redemption,
    completion_operation_id=v_operation,
    completion_result=v_result where id=v_intent.id;
  perform set_config('app.v89_redemption_intent_id','',true);
  insert into public.customer_redemption_events_v89(
    intent_id,business_id,actor,event_type,idempotency_key,detail
  ) values(v_intent.id,p_business,auth.uid(),'scan_completed',p_idempotency_key,
    jsonb_build_object('redemption_kind',v_intent.redemption_kind,
      'redemption_id',v_redemption,'operation_id',v_operation));
  return v_result;
end
$$;

--
-- Name: FUNCTION merchant_scan_redemption_qr_v89(p_business uuid, p_qr_token text, p_idempotency_key uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.merchant_scan_redemption_qr_v89(p_business uuid, p_qr_token text, p_idempotency_key uuid) IS 'Merchant-scanned atomic completion through the canonical loyalty redeemer.';

--
-- Name: merchant_scan_redemption_qr_v93(uuid, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.merchant_scan_redemption_qr_v93(p_business uuid, p_branch uuid, p_qr_token text, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_intent public.customer_redemption_intents_v89%rowtype;
  v_result jsonb;
  v_redemption uuid;
  v_operation uuid;
  v_operation_type text;
  v_program public.loyalty_programs%rowtype;
  v_reward_version public.loyalty_reward_versions%rowtype;
  v_current_quote jsonb;
  v_customer_name text;
  v_reward_label text;
begin
  if p_idempotency_key is null or length(coalesce(p_qr_token,''))<32 then
    raise exception 'invalid redemption QR scan' using errcode='22023';
  end if;
  if not app.can_module_write(p_business,'loyalty')
     or not app.has_perm(p_business,'create_sales') then
    raise exception 'merchant loyalty redemption access is required'
      using errcode='42501';
  end if;
  if p_branch is null
     or not exists(
       select 1
       from public.branches branch
       where branch.id=p_branch
         and branch.business_id=p_business
         and branch.active
     ) then
    raise exception 'an active business branch is required'
      using errcode='22023';
  end if;
  if not app.can_see_branch(p_business,p_branch) then
    raise exception 'redemption branch scope is not permitted'
      using errcode='42501';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(
    'v93:scan:'||p_business::text||':'||app.v89_sha256(p_qr_token),0));
  select *
    into v_intent
    from public.customer_redemption_intents_v89 intent
   where intent.business_id=p_business
     and intent.token_hash=app.v89_sha256(p_qr_token)
   for update;
  if not found then
    raise exception 'redemption QR is invalid' using errcode='22023';
  end if;

  if v_intent.status='completed' then
    insert into public.customer_redemption_events_v89(
      intent_id,business_id,actor,event_type,idempotency_key,detail
    ) values(
      v_intent.id,p_business,auth.uid(),'scan_replayed',p_idempotency_key,
      jsonb_build_object(
        'redemption_kind',v_intent.redemption_kind,
        'redemption_id',v_intent.redemption_id,
        'operation_id',v_intent.completion_operation_id,
        'branch_id',p_branch
      )
    )
    on conflict(intent_id,event_type,idempotency_key) do nothing;
    return v_intent.completion_result||jsonb_build_object('replayed',true);
  end if;
  if v_intent.status<>'pending' then
    raise exception 'redemption QR is no longer pending' using errcode='22023';
  end if;
  if v_intent.expires_at<=now() then
    perform set_config('app.v89_redemption_intent_id',v_intent.id::text,true);
    update public.customer_redemption_intents_v89
       set status='expired'
     where id=v_intent.id;
    perform set_config('app.v89_redemption_intent_id','',true);
    insert into public.customer_redemption_events_v89(
      intent_id,business_id,actor,event_type,idempotency_key,detail
    ) values(
      v_intent.id,p_business,auth.uid(),'intent_expired',p_idempotency_key,
      jsonb_build_object('expired_at',v_intent.expires_at,'branch_id',p_branch)
    );
    return jsonb_build_object(
      'intent_id',v_intent.id,
      'status','expired',
      'expires_at',v_intent.expires_at,
      'branch_id',p_branch,
      'replayed',false
    );
  end if;
  if not app.platform_feature_enabled('customer_qr_redemption')
     or not coalesce((
       select capability.redemption_enabled
         from public.business_customer_capabilities_v89 capability
        where capability.business_id=p_business
     ),false)
     or not app.v89_business_module_enabled(p_business,'loyalty') then
    raise exception 'customer redemption is disabled for this business'
      using errcode='42501';
  end if;

  select *
    into v_program
    from public.loyalty_programs program
   where program.id=v_intent.quoted_program_id
     and program.business_id=p_business
     and program.active
   for share;
  if not found then
    raise exception 'redemption configuration changed; create a new QR'
      using errcode='23514';
  end if;
  select client.full_name
    into v_customer_name
    from public.clients client
   where client.id=v_intent.client_id
     and client.business_id=p_business;

  if v_intent.redemption_kind='classic_points' then
    v_current_quote:=jsonb_build_object(
      'program_id',v_program.id,
      'config_version_id',v_program.current_config_version_id,
      'loyalty_model',v_program.loyalty_model,
      'kind',v_program.kind,
      'points_spent',v_program.redeem_points,
      'credit_cents',v_program.reward_credit_cents
    );
    if v_current_quote is distinct from v_intent.quoted_terms then
      raise exception 'classic redemption terms changed; create a new QR'
        using errcode='23514';
    end if;
    v_reward_label:='Store credit';
    v_operation_type:='redeem_points';
    -- Classic redemption has no branch-aware economic writer. Branch
    -- authorization is therefore locked and proven above, and the selected
    -- branch is included in the immutable merchant workflow receipt/events.
    v_result:=public.redeem_points(
      p_business,v_intent.client_id,'v93:'||v_intent.id::text
    )::jsonb;
  else
    select reward_version.*
      into v_reward_version
      from public.loyalty_reward_versions reward_version
      join public.businesses business
        on business.id=reward_version.business_id
     where reward_version.id=v_intent.quoted_reward_version_id
       and reward_version.reward_id=v_intent.reward_id
       and reward_version.business_id=p_business
       and reward_version.config_version_id=business.active_config_version_id
       and reward_version.active
     for share;
    if not found
       or exists(
         select 1
           from public.loyalty_reward_services restriction
          where restriction.reward_version_id=v_intent.quoted_reward_version_id
       )
       or exists(
         select 1
           from public.loyalty_reward_products restriction
          where restriction.reward_version_id=v_intent.quoted_reward_version_id
       ) then
      raise exception 'catalog redemption terms changed; create a new QR'
        using errcode='23514';
    end if;
    if exists(
      select 1
        from public.loyalty_reward_branches restriction
       where restriction.reward_version_id=v_intent.quoted_reward_version_id
    ) and not exists(
      select 1
        from public.loyalty_reward_branches restriction
       where restriction.reward_version_id=v_intent.quoted_reward_version_id
         and restriction.branch_id=p_branch
    ) then
      raise exception 'reward is not eligible at this branch'
        using errcode='23514';
    end if;
    v_current_quote:=jsonb_build_object(
      'program_id',v_program.id,
      'config_version_id',v_reward_version.config_version_id,
      'reward_version_id',v_reward_version.id,
      'reward_id',v_intent.reward_id,
      'points_spent',v_reward_version.cost_points,
      'credit_cents',v_reward_version.credit_cents,
      'fulfillment_kind',v_reward_version.fulfillment_kind,
      'claim_available_from',v_reward_version.claim_available_from,
      'claim_available_until',v_reward_version.claim_available_until,
      'usage_limit',v_reward_version.usage_limit,
      'active',v_reward_version.active
    );
    if v_current_quote is distinct from v_intent.quoted_terms then
      raise exception 'catalog redemption terms changed; create a new QR'
        using errcode='23514';
    end if;
    v_reward_label:=coalesce(v_reward_version.customer_name,'Reward');
    v_operation_type:='redeem_reward';
    v_result:=public.redeem_reward_at_context(
      p_business,
      v_intent.client_id,
      v_intent.reward_id,
      'v93:'||v_intent.id::text,
      p_branch,
      null,
      null
    )::jsonb;
  end if;

  select operation.id
    into v_operation
    from public.loyalty_operations operation
   where operation.business_id=p_business
     and operation.operation_type=v_operation_type
     and operation.idempotency_key='v93:'||v_intent.id::text
     and operation.status='completed';
  if not found then
    raise exception 'canonical redemption operation was not recorded'
      using errcode='40001';
  end if;
  if v_intent.redemption_kind='catalog_reward' then
    select provenance.redemption_id
      into v_redemption
      from public.loyalty_redemption_provenance provenance
     where provenance.business_id=p_business
       and provenance.operation_id=v_operation;
    if not found then
      raise exception 'canonical catalog redemption was not recorded'
        using errcode='40001';
    end if;
  end if;

  v_result:=jsonb_build_object(
    'intent_id',v_intent.id,
    'status','completed',
    'redemption_kind',v_intent.redemption_kind,
    'completed_at',now(),
    'branch_id',p_branch,
    'operation_id',v_operation,
    'redemption_id',v_redemption,
    'customer_name',v_customer_name,
    'reward_label',v_reward_label,
    'points_spent',v_intent.quoted_points_spent,
    'credit_cents',v_intent.quoted_credit_cents,
    'result',v_result,
    'replayed',false
  );
  perform set_config('app.v89_redemption_intent_id',v_intent.id::text,true);
  update public.customer_redemption_intents_v89
     set status='completed',
         completed_at=now(),
         completed_by=auth.uid(),
         completion_idempotency_key=p_idempotency_key,
         redemption_id=v_redemption,
         completion_operation_id=v_operation,
         completion_result=v_result
   where id=v_intent.id;
  perform set_config('app.v89_redemption_intent_id','',true);
  insert into public.customer_redemption_events_v89(
    intent_id,business_id,actor,event_type,idempotency_key,detail
  ) values(
    v_intent.id,p_business,auth.uid(),'scan_completed',p_idempotency_key,
    jsonb_build_object(
      'redemption_kind',v_intent.redemption_kind,
      'redemption_id',v_redemption,
      'operation_id',v_operation,
      'branch_id',p_branch
    )
  );
  return v_result;
end
$$;

--
-- Name: FUNCTION merchant_scan_redemption_qr_v93(p_business uuid, p_branch uuid, p_qr_token text, p_idempotency_key uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.merchant_scan_redemption_qr_v93(p_business uuid, p_branch uuid, p_qr_token text, p_idempotency_key uuid) IS 'Branch-scoped, replay-safe merchant completion of a customer QR redemption through canonical loyalty writers.';

--
-- Name: move_bottle_v278(uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.move_bottle_v278(p_business uuid, p_bottle uuid, p_storage_location uuid, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_key text := nullif(btrim(coalesce(p_idempotency_key, '')), '');
  v_existing uuid;
  v_bottle public.bar_bottles%rowtype;
  v_before uuid;
  v_before_name text;
  v_after_name text;
begin
  perform app.require_bar_business_v275(p_business);
  perform app.require_bar_staff_v275(p_business, true);
  if v_key is null then
    raise exception 'idempotency key required' using errcode = '22023';
  end if;

  v_existing := app.bar_bottle_replayed_v275(p_business, v_key);
  if v_existing is not null then
    select * into v_bottle from public.bar_bottles bottle where bottle.id = v_existing;
    return jsonb_build_object('status', 'duplicate_ignored',
      'bottle', app.bar_bottle_json_v275(v_bottle));
  end if;

  select * into v_bottle from public.bar_bottles bottle
   where bottle.id = p_bottle and bottle.business_id = p_business for update;
  if not found then
    raise exception 'bottle not found' using errcode = '22023';
  end if;
  if v_bottle.status in ('finished', 'transferred', 'removed') then
    raise exception 'this bottle is closed' using errcode = '22023';
  end if;
  if p_storage_location is not null
     and not exists (select 1 from public.bar_storage_locations location
                      where location.id = p_storage_location
                        and location.business_id = p_business
                        and location.active) then
    raise exception 'that storage place is not on your list' using errcode = '22023';
  end if;

  v_before := v_bottle.storage_location_id;
  select location.name into v_before_name from public.bar_storage_locations location
   where location.id = v_before;
  select location.name into v_after_name from public.bar_storage_locations location
   where location.id = p_storage_location;

  update public.bar_bottles bottle
     set storage_location_id = p_storage_location, updated_at = now()
   where bottle.id = v_bottle.id
  returning * into v_bottle;

  insert into public.bar_bottle_events (business_id, bottle_id, kind, actor, idem_key, detail)
  values (p_business, v_bottle.id, 'move', v_actor, v_key,
    jsonb_build_object('from', v_before, 'to', p_storage_location,
      'from_name', v_before_name, 'to_name', v_after_name));

  return jsonb_build_object('status', 'ok', 'bottle', app.bar_bottle_json_v275(v_bottle));
end;
$$;

--
-- Name: my_pending_access_v207(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_pending_access_v207() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object(
           'business_id', s.business_id, 'business_name', b.name, 'access_state', s.access_state)), '[]'::jsonb)
    from public.staff s join public.businesses b on b.id = s.business_id
   where s.user_id = auth.uid() and s.access_state = 'pending';
$$;

--
-- Name: notify_bottle_v278(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_bottle_v278(p_business uuid, p_bottle uuid, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_key text := nullif(btrim(coalesce(p_idempotency_key, '')), '');
  v_existing uuid;
  v_bottle public.bar_bottles%rowtype;
  v_link public.customer_links%rowtype;
  v_opted boolean := false;
  v_delivery text := 'no_customer_app';
  v_inserted integer := 0;
begin
  perform app.require_bar_business_v275(p_business);
  perform app.require_bar_staff_v275(p_business, true);
  if v_key is null then
    raise exception 'idempotency key required' using errcode = '22023';
  end if;

  v_existing := app.bar_bottle_replayed_v275(p_business, v_key);
  if v_existing is not null then
    select * into v_bottle from public.bar_bottles bottle where bottle.id = v_existing;
    return jsonb_build_object('status', 'duplicate_ignored',
      'bottle', app.bar_bottle_json_v275(v_bottle), 'delivery', 'duplicate_ignored');
  end if;

  select * into v_bottle from public.bar_bottles bottle
   where bottle.id = p_bottle and bottle.business_id = p_business for update;
  if not found then
    raise exception 'bottle not found' using errcode = '22023';
  end if;
  if v_bottle.status in ('finished', 'transferred', 'removed') then
    raise exception 'this bottle is closed' using errcode = '22023';
  end if;

  select * into v_link from public.customer_links link
   where link.business_id = p_business
     and link.client_id = v_bottle.client_id
     and link.state = 'verified'
     and link.unlinked_at is null
   order by link.created_at
   limit 1;

  if v_link.id is not null then
    select coalesce(preference.opted_in, false) into v_opted
      from public.customer_notification_preferences preference
     where preference.business_id = v_link.business_id
       and preference.identity_id = v_link.identity_id
       and preference.auth_user_id = v_link.auth_user_id
       and preference.link_id = v_link.id
       and preference.channel = 'in_app'
       and preference.topic = 'value_expiry';
    v_opted := coalesce(v_opted, false);
    if v_opted then
      insert into public.customer_in_app_inbox_events(
        business_id, identity_id, auth_user_id, link_id, client_id,
        source_kind, topic, route_key, source_fingerprint, dedupe_key,
        title, body, deadline_at
      ) values (
        v_link.business_id, v_link.identity_id, v_link.auth_user_id, v_link.id, v_link.client_id,
        'v278_bottle_reminder', 'value_expiry', 'wallet_business',
        app.c46_sha256_hex(jsonb_build_object(
          'bottle_id', v_bottle.id, 'idem_key', v_key)::text),
        app.c46_sha256_hex(jsonb_build_object(
          'identity_id', v_link.identity_id, 'bottle_id', v_bottle.id, 'idem_key', v_key)::text),
        'Your bottle is waiting',
        'Open this business wallet to see the bottle being kept for you.',
        v_bottle.expires_at
      )
      on conflict (identity_id, dedupe_key) do nothing;
      get diagnostics v_inserted = row_count;
      v_delivery := case when v_inserted > 0 then 'in_app' else 'already_notified' end;
    else
      v_delivery := 'opted_out';
    end if;
  end if;

  insert into public.bar_bottle_events (business_id, bottle_id, kind, actor, idem_key, detail)
  values (p_business, v_bottle.id, 'reminder', v_actor, v_key,
    jsonb_build_object('delivery', v_delivery,
      'notify_channel', v_bottle.notify_channel,
      'expires_at', v_bottle.expires_at));

  return jsonb_build_object('status', 'ok', 'delivery', v_delivery,
    'bottle', app.bar_bottle_json_v275(v_bottle));
end;
$$;

--
-- Name: offer_share_page_v268(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.offer_share_page_v268(p_offer uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  select jsonb_build_object(
    'offer_id', content.id,
    'name', coalesce(copy.name,'Offer'),
    'tagline', copy.tagline,
    'description', copy.description,
    'starts_at', content.starts_at,
    'ends_at', content.ends_at,
    'image_url', media.url,
    'image_alt', media.image_alt,
    'business_name', b.name,
    'business_slug', b.slug,
    'business_logo_url', app.v267_business_logo_url(b.id)
  )
  from public.business_customer_content_v95 content
  join public.businesses b on b.id = content.business_id
  left join public.business_localized_copy_v95 copy
    on copy.business_id = content.business_id
   and copy.entity_type = 'offer'
   and copy.entity_id = content.id
   and copy.locale = 'en'
  left join lateral (
    select app.v95_public_media_url(asset.object_path) url, asset.alt_en image_alt
    from public.business_media_assets_v95 asset
    where asset.business_id = content.business_id
      and asset.asset_kind = 'offer'
      and asset.entity_id = content.id
      and asset.customer_visible
      and asset.branch_id is null
    order by asset.updated_at desc, asset.id
    limit 1
  ) media on true
  where content.id = p_offer
    and content.content_type = 'offer'
    and content.active
    and (content.starts_at is null or content.starts_at <= now())
    and content.ends_at > now()
    and nullif(trim(b.slug),'') is not null
  limit 1;
$$;

--
-- Name: open_drawer(uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.open_drawer(p_business uuid, p_branch uuid, p_float_cents integer DEFAULT 0) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_row cash_drawer_sessions;
begin
  if not app.has_perm(p_business, 'view_finance') then
    raise exception 'you do not have permission to operate the cash drawer (view_finance)';
  end if;
  if not exists (select 1 from branches where id = p_branch and business_id = p_business) then
    raise exception 'branch does not belong to this business';
  end if;
  if app.open_drawer_session(p_branch) is not null then
    raise exception 'this branch already has an open drawer session';
  end if;
  insert into cash_drawer_sessions (business_id, branch_id, opening_float_cents)
  values (p_business, p_branch, coalesce(p_float_cents, 0))
  returning * into v_row;
  if coalesce(p_float_cents, 0) > 0 then
    insert into cash_drawer_movements (business_id, branch_id, session_id, kind,
                                       amount_cents, note)
    values (p_business, p_branch, v_row.id, 'open_float', p_float_cents, 'opening float');
  end if;
  return row_to_json(v_row);
end $$;

--
-- Name: owner_list_reward_profitability_products_v122(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.owner_list_reward_profitability_products_v122(p_business uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if auth.uid() is null then
    raise exception 'authenticated_session_required' using errcode='28000';
  end if;
  if p_business is null
     or not exists(
       select 1 from public.staff staff_row
       where staff_row.business_id=p_business
         and staff_row.user_id=auth.uid()
         and staff_row.active
         and staff_row.role='owner'
     )
     or not app.can_module_write(p_business,'loyalty')
  then
    raise exception 'owner_loyalty_write_required' using errcode='42501';
  end if;
  return jsonb_build_object('items',coalesce((
    select jsonb_agg(jsonb_build_object(
      'id',product.id,'name',product.name,
      'retail_price_cents',product.retail_price_cents,
      'cost_cents',product.cost_cents
    ) order by product.name,product.id)
    from public.products product
    where product.business_id=p_business and product.active
  ),'[]'::jsonb));
end
$$;

--
-- Name: owner_set_product_cost_v122(uuid, uuid, bigint, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.owner_set_product_cost_v122(p_business uuid, p_product uuid, p_cost_cents bigint, p_expected_cost_cents bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_product public.products%rowtype;
begin
  if auth.uid() is null then
    raise exception 'authenticated_session_required' using errcode='28000';
  end if;
  if p_business is null or p_product is null
     or p_cost_cents is null
     or p_cost_cents not between 0 and 2147483647
  then
    raise exception 'valid_product_cost_required' using errcode='22023';
  end if;
  if not exists(
       select 1 from public.staff staff_row
       where staff_row.business_id=p_business
         and staff_row.user_id=auth.uid()
         and staff_row.active
         and staff_row.role='owner'
     )
     or not app.can_module_write(p_business,'loyalty')
  then
    raise exception 'owner_loyalty_write_required' using errcode='42501';
  end if;
  select * into v_product
  from public.products product
  where product.id=p_product and product.business_id=p_business and product.active
  for update;
  if not found then
    raise exception 'active_product_not_found' using errcode='P0002';
  end if;
  -- A replay after a lost response is harmless; a genuinely stale editor
  -- refuses instead of silently overwriting another owner.
  if v_product.cost_cents is not distinct from p_cost_cents then
    return jsonb_build_object(
      'id',v_product.id,'cost_cents',v_product.cost_cents,'replayed',true
    );
  end if;
  if v_product.cost_cents is distinct from p_expected_cost_cents then
    raise exception 'product_cost_changed_refresh_required' using errcode='40001';
  end if;
  update public.products
  set cost_cents=p_cost_cents
  where id=v_product.id
  returning * into v_product;
  return jsonb_build_object(
    'id',v_product.id,'cost_cents',v_product.cost_cents,'replayed',false
  );
end
$$;

--
-- Name: park_bottle_v275(uuid, uuid, text, uuid, integer, integer, uuid, integer, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.park_bottle_v275(p_business uuid, p_client uuid, p_label text, p_product uuid, p_size_ml integer, p_fill_percent integer, p_storage_location uuid, p_reentry_limit integer, p_branch uuid, p_sale uuid, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_key text := nullif(btrim(coalesce(p_idempotency_key, '')), '');
  v_label text := nullif(btrim(coalesce(p_label, '')), '');
  v_fill integer := coalesce(p_fill_percent, 100);
  v_keep integer;
  v_year integer;
  v_seq integer;
  v_existing uuid;
  v_bottle public.bar_bottles%rowtype;
begin
  perform app.require_bar_business_v275(p_business);
  perform app.require_bar_staff_v275(p_business, true);
  if v_key is null then
    raise exception 'idempotency key required' using errcode = '22023';
  end if;
  if p_client is null then
    raise exception 'choose a customer' using errcode = '22023';
  end if;
  if v_label is null and p_product is null then
    raise exception 'name the bottle or pick it from the catalogue' using errcode = '22023';
  end if;
  if v_fill < 0 or v_fill > 100 then
    raise exception 'fill must be between 0 and 100' using errcode = '22023';
  end if;

  v_existing := app.bar_bottle_replayed_v275(p_business, v_key);
  if v_existing is not null then
    select * into v_bottle from public.bar_bottles bottle where bottle.id = v_existing;
    return jsonb_build_object('status', 'duplicate_ignored',
      'bottle', app.bar_bottle_json_v275(v_bottle));
  end if;

  -- Locking the settings row serialises serial allocation for this business. It is the cheapest
  -- correct answer: the alternative (max()+1 with no lock) races two bartenders parking at the
  -- same moment into the same PK-YYYY-NNNN, and a duplicate serial on a physical shelf label is
  -- exactly the failure this module exists to prevent.
  insert into public.bar_bottle_settings (business_id) values (p_business)
  on conflict (business_id) do nothing;
  select setting.keep_days into v_keep
    from public.bar_bottle_settings setting
   where setting.business_id = p_business
     for update;
  v_keep := coalesce(v_keep, 30);

  perform app.bar_capacity_guard_v279(p_business, 1);

  v_year := extract(year from (now() at time zone 'Asia/Singapore'))::integer;
  select coalesce(max(bottle.serial_seq), 0) + 1 into v_seq
    from public.bar_bottles bottle
   where bottle.business_id = p_business and bottle.serial_year = v_year;

  insert into public.bar_bottles (
    business_id, branch_id, client_id, serial_year, serial_seq, label, product_id,
    size_ml, fill_percent, storage_location_id, reentry_limit, status,
    parked_at, expires_at, sale_id
  ) values (
    p_business, p_branch, p_client, v_year, v_seq, v_label, p_product,
    p_size_ml, v_fill, p_storage_location, null, 'stored',
    now(), now() + make_interval(days => v_keep), p_sale
  )
  returning * into v_bottle;

  insert into public.bar_bottle_events (business_id, bottle_id, kind, actor, idem_key, detail)
  values (p_business, v_bottle.id, 'park', v_actor, v_key, jsonb_build_object(
    'serial_code', v_bottle.serial_code,
    'client_id', v_bottle.client_id,
    'fill_percent', v_bottle.fill_percent,
    'keep_days', v_keep,
    'expires_at', v_bottle.expires_at,
    'storage_location_id', v_bottle.storage_location_id,
    'sale_id', v_bottle.sale_id));

  return jsonb_build_object('status', 'ok', 'bottle', app.bar_bottle_json_v275(v_bottle));
end;
$$;

--
-- Name: park_bottle_v278(uuid, uuid, text, uuid, integer, integer, uuid, integer, uuid, uuid, text, date, text, text, date, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.park_bottle_v278(p_business uuid, p_client uuid, p_label text, p_product uuid, p_size_ml integer, p_fill_percent integer, p_storage_location uuid, p_reentry_limit integer, p_branch uuid, p_sale uuid, p_expiry_mode text, p_expiry_date date, p_notify_channel text, p_note text, p_purchased_on date, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_key text := nullif(btrim(coalesce(p_idempotency_key, '')), '');
  v_label text := nullif(btrim(coalesce(p_label, '')), '');
  v_note text := nullif(btrim(coalesce(p_note, '')), '');
  v_mode text := lower(btrim(coalesce(nullif(btrim(coalesce(p_expiry_mode, '')), ''), 'auto')));
  v_channel text := lower(btrim(coalesce(nullif(btrim(coalesce(p_notify_channel, '')), ''), 'none')));
  v_fill integer := coalesce(p_fill_percent, 100);
  v_size integer := p_size_ml;
  v_expires timestamptz;
  v_keep integer;
  v_year integer;
  v_seq integer;
  v_existing uuid;
  v_bottle public.bar_bottles%rowtype;
begin
  perform app.require_bar_business_v275(p_business);
  perform app.require_bar_staff_v275(p_business, true);
  if v_key is null then
    raise exception 'idempotency key required' using errcode = '22023';
  end if;
  if p_client is null then
    raise exception 'choose a customer' using errcode = '22023';
  end if;
  if v_label is null and p_product is null then
    raise exception 'name the bottle or pick it from the catalogue' using errcode = '22023';
  end if;
  if v_fill < 0 or v_fill > 100 then
    raise exception 'fill must be between 0 and 100' using errcode = '22023';
  end if;
  if v_channel not in ('whatsapp', 'email', 'none') then
    raise exception 'reminders go by WhatsApp, by email, or not at all' using errcode = '22023';
  end if;
  if v_note is not null and length(v_note) > 500 then
    raise exception 'a note is limited to 500 characters' using errcode = '22023';
  end if;
  if p_purchased_on is not null
     and p_purchased_on > ((now() at time zone 'Asia/Singapore')::date + 1) then
    raise exception 'a bottle cannot have been bought in the future' using errcode = '22023';
  end if;

  v_existing := app.bar_bottle_replayed_v275(p_business, v_key);
  if v_existing is not null then
    select * into v_bottle from public.bar_bottles bottle where bottle.id = v_existing;
    return jsonb_build_object('status', 'duplicate_ignored',
      'bottle', app.bar_bottle_json_v275(v_bottle));
  end if;

  -- The size ALWAYS comes from the catalogue when a catalogue bottle was picked. The browser is
  -- not trusted to have copied it, because the whole point of item 2 is that it is never typed.
  if p_product is not null then
    select coalesce(product.size_ml, v_size) into v_size
      from public.products product
     where product.id = p_product and product.business_id = p_business;
    if not found then
      raise exception 'that bottle is not in your catalogue' using errcode = '22023';
    end if;
  end if;

  -- Locking the settings row serialises serial allocation for this business, exactly as V275 does:
  -- a duplicate PK-YYYY-NNNN on a physical shelf label is the failure this module exists to
  -- prevent.
  insert into public.bar_bottle_settings (business_id) values (p_business)
  on conflict (business_id) do nothing;
  select setting.keep_days into v_keep
    from public.bar_bottle_settings setting
   where setting.business_id = p_business
     for update;

  v_expires := app.bar_bottle_expiry_v278(p_business, p_client, v_mode, p_expiry_date);

  perform app.bar_capacity_guard_v279(p_business, 1);

  v_year := extract(year from (now() at time zone 'Asia/Singapore'))::integer;
  select coalesce(max(bottle.serial_seq), 0) + 1 into v_seq
    from public.bar_bottles bottle
   where bottle.business_id = p_business and bottle.serial_year = v_year;

  insert into public.bar_bottles (
    business_id, branch_id, client_id, serial_year, serial_seq, label, product_id,
    size_ml, fill_percent, storage_location_id, reentry_limit, status,
    parked_at, expires_at, sale_id, expiry_mode, notify_channel, purchased_on
  ) values (
    p_business, p_branch, p_client, v_year, v_seq, v_label, p_product,
    v_size, v_fill, p_storage_location, null, 'stored',
    now(), v_expires, p_sale, v_mode, v_channel, p_purchased_on
  )
  returning * into v_bottle;

  -- Exactly ONE event per write stays true: a park note rides in the park event's detail rather
  -- than becoming a second row, so the idempotency key remains one key for one intention.
  insert into public.bar_bottle_events (business_id, bottle_id, kind, actor, idem_key, detail)
  values (p_business, v_bottle.id, 'park', v_actor, v_key, jsonb_build_object(
    'serial_code', v_bottle.serial_code,
    'client_id', v_bottle.client_id,
    'fill_percent', v_bottle.fill_percent,
    'expiry_mode', v_bottle.expiry_mode,
    'expires_at', v_bottle.expires_at,
    'notify_channel', v_bottle.notify_channel,
    'purchased_on', v_bottle.purchased_on,
    'storage_location_id', v_bottle.storage_location_id,
    'sale_id', v_bottle.sale_id,
    'note', v_note));

  return jsonb_build_object('status', 'ok', 'bottle', app.bar_bottle_json_v275(v_bottle));
end;
$$;

--
-- Name: park_bottles_v279(uuid, uuid, text, uuid, integer, integer, uuid, uuid, uuid, text, date, text, text, date, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.park_bottles_v279(p_business uuid, p_client uuid, p_label text, p_product uuid, p_size_ml integer, p_fill_percent integer, p_storage_location uuid, p_branch uuid, p_sale uuid, p_expiry_mode text, p_expiry_date date, p_notify_channel text, p_note text, p_purchased_on date, p_quantity integer, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_key text := nullif(btrim(coalesce(p_idempotency_key, '')), '');
  v_label text := nullif(btrim(coalesce(p_label, '')), '');
  v_note text := nullif(btrim(coalesce(p_note, '')), '');
  v_mode text := lower(btrim(coalesce(nullif(btrim(coalesce(p_expiry_mode, '')), ''), 'auto')));
  v_channel text := lower(btrim(coalesce(nullif(btrim(coalesce(p_notify_channel, '')), ''), 'none')));
  v_fill integer := coalesce(p_fill_percent, 100);
  v_size integer := p_size_ml;
  v_quantity integer := coalesce(p_quantity, 1);
  v_expires timestamptz;
  v_keep integer;
  v_year integer;
  v_seq integer;
  v_index integer;
  v_bottle public.bar_bottles%rowtype;
  v_bottles jsonb := '[]'::jsonb;
begin
  perform app.require_bar_business_v275(p_business);
  perform app.require_bar_staff_v275(p_business, true);
  if v_key is null then
    raise exception 'idempotency key required' using errcode = '22023';
  end if;
  if p_client is null then
    raise exception 'choose a customer' using errcode = '22023';
  end if;
  if v_label is null and p_product is null then
    raise exception 'name the bottle or pick it from the catalogue' using errcode = '22023';
  end if;
  if v_fill < 0 or v_fill > 100 then
    raise exception 'fill must be between 0 and 100' using errcode = '22023';
  end if;
  if v_quantity < 1 or v_quantity > 20 then
    raise exception 'park between 1 and 20 bottles at a time' using errcode = '22023';
  end if;
  if v_channel not in ('whatsapp', 'email', 'none') then
    raise exception 'reminders go by WhatsApp, by email, or not at all' using errcode = '22023';
  end if;
  if v_note is not null and length(v_note) > 500 then
    raise exception 'a note is limited to 500 characters' using errcode = '22023';
  end if;
  if p_purchased_on is not null
     and p_purchased_on > ((now() at time zone 'Asia/Singapore')::date + 1) then
    raise exception 'a bottle cannot have been bought in the future' using errcode = '22023';
  end if;

  -- Replay probe on the batch prefix. left(...) rather than LIKE so a key containing % or _ is
  -- compared literally instead of being read as a pattern.
  select coalesce(jsonb_agg(app.bar_bottle_json_v275(bottle) order by bottle.serial_seq), '[]'::jsonb)
    into v_bottles
    from public.bar_bottle_events event
    join public.bar_bottles bottle on bottle.id = event.bottle_id
   where event.business_id = p_business
     and event.kind = 'park'
     and left(event.idem_key, length(v_key) + 1) = v_key || '#';
  if jsonb_array_length(v_bottles) > 0 then
    return jsonb_build_object('status', 'duplicate_ignored',
      'count', jsonb_array_length(v_bottles),
      'bottles', v_bottles,
      'bottle', v_bottles -> 0);
  end if;

  -- The size ALWAYS comes from the catalogue when a catalogue bottle was picked. The browser is
  -- not trusted to have copied it.
  if p_product is not null then
    select coalesce(product.size_ml, v_size) into v_size
      from public.products product
     where product.id = p_product and product.business_id = p_business;
    if not found then
      raise exception 'that bottle is not in your catalogue' using errcode = '22023';
    end if;
  end if;

  -- Locking the settings row serialises serial allocation for this business, exactly as V275 and
  -- V278 do: a duplicate PK-YYYY-NNNN on a physical shelf label is the failure this module exists
  -- to prevent, and a batch allocates a whole RANGE of them.
  insert into public.bar_bottle_settings (business_id) values (p_business)
  on conflict (business_id) do nothing;
  select setting.keep_days into v_keep
    from public.bar_bottle_settings setting
   where setting.business_id = p_business
     for update;

  -- The WHOLE batch is asked for at once: two free slots refuse three bottles rather than parking
  -- two and failing on the third with a customer's property already behind the bar.
  perform app.bar_capacity_guard_v279(p_business, v_quantity);

  v_expires := app.bar_bottle_expiry_v278(p_business, p_client, v_mode, p_expiry_date);

  v_year := extract(year from (now() at time zone 'Asia/Singapore'))::integer;
  select coalesce(max(bottle.serial_seq), 0) + 1 into v_seq
    from public.bar_bottles bottle
   where bottle.business_id = p_business and bottle.serial_year = v_year;

  v_bottles := '[]'::jsonb;
  for v_index in 1..v_quantity loop
    insert into public.bar_bottles (
      business_id, branch_id, client_id, serial_year, serial_seq, label, product_id,
      size_ml, fill_percent, storage_location_id, reentry_limit, status,
      parked_at, expires_at, sale_id, expiry_mode, notify_channel, purchased_on
    ) values (
      p_business, p_branch, p_client, v_year, v_seq + v_index - 1, v_label, p_product,
      v_size, v_fill, p_storage_location, null, 'stored',
      now(), v_expires, p_sale, v_mode, v_channel, p_purchased_on
    )
    returning * into v_bottle;

    insert into public.bar_bottle_events (business_id, bottle_id, kind, actor, idem_key, detail)
    values (p_business, v_bottle.id, 'park', v_actor, v_key || '#' || v_index, jsonb_build_object(
      'serial_code', v_bottle.serial_code,
      'client_id', v_bottle.client_id,
      'fill_percent', v_bottle.fill_percent,
      'expiry_mode', v_bottle.expiry_mode,
      'expires_at', v_bottle.expires_at,
      'notify_channel', v_bottle.notify_channel,
      'purchased_on', v_bottle.purchased_on,
      'storage_location_id', v_bottle.storage_location_id,
      'sale_id', v_bottle.sale_id,
      'batch_key', v_key,
      'batch_index', v_index,
      'batch_size', v_quantity,
      'note', v_note));

    v_bottles := v_bottles || jsonb_build_array(app.bar_bottle_json_v275(v_bottle));
  end loop;

  return jsonb_build_object('status', 'ok',
    'count', v_quantity,
    'bottles', v_bottles,
    'bottle', v_bottles -> 0);
end;
$$;

--
-- Name: platform_acknowledge_partner_suppression_v282(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_acknowledge_partner_suppression_v282(p_suppression uuid, p_reference text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_reference text := nullif(btrim(coalesce(p_reference, '')), '');
  v_id uuid;
begin
  if v_actor is null then
    raise exception 'authenticated platform session is required' using errcode = '28000';
  end if;
  if not app.is_super_admin() then
    raise exception 'suppression instructions are super admin only' using errcode = '42501';
  end if;
  if v_reference is null or length(v_reference) not between 1 and 200 then
    raise exception 'an acknowledgement reference is required' using errcode = '22023';
  end if;

  update public.partner_suppressions_v282 suppression
     set acknowledged_at = now(), acknowledgement_reference = v_reference
   where suppression.id = p_suppression
     and suppression.acknowledged_at is null
  returning suppression.id into v_id;
  if v_id is null then
    raise exception 'no unacknowledged suppression instruction with that id' using errcode = '22023';
  end if;

  return jsonb_build_object('status', 'ok', 'suppression_id', v_id);
end;
$$;

--
-- Name: platform_activate_approved_application_v169(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_activate_approved_application_v169(p_application uuid, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid:=auth.uid();
  v_v277_prior_sub text:=current_setting('request.jwt.claim.sub',true);
  v_v277_prior_claims text:=current_setting('request.jwt.claims',true);
  v_application public.business_applications_v95%rowtype;
  v_owner uuid;
  v_bundle public.sector_bundle_versions%rowtype;
  v_business public.businesses%rowtype;
  v_staff uuid;
  v_branch uuid;
  v_slug_base text;
  v_slug text;
  v_suffix integer:=0;
begin
  if not app.is_super_admin() then
    raise exception 'super_admin_required' using errcode='42501';
  end if;
  if p_application is null or p_idempotency_key is null then
    raise exception 'application and idempotency key are required' using errcode='22023';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(p_idempotency_key::text,169));

  select * into v_application
    from public.business_applications_v95 application
   where application.id=p_application
   for update;
  if not found then
    raise exception 'application_not_found' using errcode='22023';
  end if;

  -- Idempotent replay: already activated by V167 or by an earlier call to this function.
  if v_application.status='consumed' then
    return jsonb_build_object(
      'application_id',v_application.id,'status','consumed',
      'business_id',v_application.consumed_business_id,
      'workspace_created',false,'workspace_access',true,'replayed',true
    );
  end if;
  if v_application.status<>'approved' then
    raise exception 'application_is_not_approved' using errcode='23514';
  end if;

  select user_row.id into v_owner
    from auth.users user_row
   where lower(user_row.email)=lower(v_application.contact_email)
     and coalesce(user_row.email_confirmed_at,user_row.confirmed_at) is not null
   order by user_row.created_at asc,user_row.id asc
   limit 1;
  if v_owner is null then
    raise exception 'owner_account_not_found_for_application' using errcode='42501';
  end if;
  if exists(select 1 from public.staff staff_row where staff_row.user_id=v_owner) then
    raise exception 'owner_account_already_has_workspace' using errcode='42501';
  end if;

  select * into v_bundle
    from public.sector_bundle_versions
   where sector_key=v_application.sector_key and status='published';
  if not found then
    raise exception 'published_sector_required' using errcode='23514';
  end if;

  v_slug_base:=lower(regexp_replace(v_application.business_name,'[^a-zA-Z0-9]+','-','g'));
  v_slug_base:=trim(both '-' from v_slug_base);
  if length(v_slug_base)<3 then
    v_slug_base:='business-'||left(v_application.public_reference::text,8);
  end if;
  v_slug_base:=left(v_slug_base,60);
  v_slug:=v_slug_base;
  while exists(select 1 from public.businesses where slug=v_slug) loop
    v_suffix:=v_suffix+1;
    v_slug:=left(v_slug_base,55)||'-'||v_suffix::text;
  end loop;

  update public.business_application_invitations_v95 invitation
     set revoked_at=coalesce(invitation.revoked_at,now())
   where invitation.application_id=p_application
     and invitation.revoked_at is null
     and invitation.consumed_at is null;

  insert into public.businesses(name,slug,industry,enabled_modules)
  values(v_application.business_name,v_slug,v_application.sector_key,v_bundle.modules)
  returning * into v_business;
  insert into public.staff(business_id,user_id,role,full_name,active)
  values(v_business.id,v_owner,'owner',v_application.contact_name,true)
  returning id into v_staff;
  insert into public.branches(business_id,name,is_default,active)
  values(v_business.id,v_application.business_name,true,true)
  returning id into v_branch;
  insert into public.staff_branches(business_id,staff_id,branch_id)
  values(v_business.id,v_staff,v_branch);

  update public.business_workspace_controls_v94
     set approval_status='approved',version=version+1,
         decided_by=coalesce(v_application.decided_by,v_actor),
         decided_at=coalesce(v_application.decided_at,now()),
         decision_reason='V169 activation of pre-V167 approved application '||v_application.id,
         updated_at=now()
   where business_id=v_business.id;
  insert into public.business_workspace_control_audit_v94(
    business_id,actor,event_type,prior_status,new_status,reason,control_version
  ) values(
    v_business.id,v_actor,'application_activated','pending','approved',
    'V169 activation of pre-V167 approved application',2
  );

  /*
    Deliberately NOT seeding public.loyalty_programs here.

    `app.c45_loyalty_program_version_write_guard` fires on the version row that
    `seed_loyalty_config_version()` creates, and requires app.c45_owner_loyalty_write(business)
    -> app.is_salon_owner(business) -> an ACTIVE owner staff row whose user_id = auth.uid().
    During activation auth.uid() is the SUPER ADMIN, who by design is never staff of the tenant,
    so the guard raises 42501 and rolls the whole activation back. Proven by rolled-back test
    against production on 2026-08-05.

    The seeded row was an inactive 'draft' preset anyway, so omitting it costs the owner
    nothing: they create their programme through Grow as the owner, where the guard passes.

    The same insert is removed from public.platform_decide_business_application_v105 in Part 2
    of this migration, which is what unblocks every FUTURE approval.
  */
  perform set_config('request.jwt.claim.sub',v_owner::text,true);
  perform set_config('request.jwt.claims',
    jsonb_build_object('sub',v_owner,'role','authenticated','aud','authenticated')::text,true);
  if app.c45_owner_loyalty_write(v_business.id) then
    insert into public.loyalty_programs(
      business_id,kind,earn_points_per_dollar,redeem_points,
      reward_credit_cents,active,loyalty_model,configuration_status,
      recommendation_source
    ) values(
      v_business.id,'points',1,800,2000,false,'classic','draft',
      'onboarding_preset'
    ) on conflict(business_id) do nothing;
  end if;
  perform set_config('request.jwt.claim.sub',coalesce(v_v277_prior_sub,''),true);
  perform set_config('request.jwt.claims',coalesce(v_v277_prior_claims,''),true);
  insert into public.subscriptions(business_id) values(v_business.id)
  on conflict(business_id) do nothing;
  insert into public.business_sector_assignments(
    business_id,bundle_version_id,version,assigned_by
  ) values(v_business.id,v_bundle.id,1,v_actor);

  update public.business_applications_v95
     set status='consumed',version=version+1,consumed_business_id=v_business.id,
         consumed_by=v_owner,consumed_at=now(),updated_at=now()
   where id=v_application.id
   returning * into v_application;

  insert into public.business_application_audit_v95(
    application_id,event_type,actor,prior_status,new_status,reason,detail
  ) values(
    v_application.id,'invitation_consumed',v_owner,'approved','consumed',
    'V169 activated an application approved before direct activation shipped',
    jsonb_build_object('business_id',v_business.id,'activated_by',v_actor)
  );
  insert into public.audit_log(
    business_id,actor,action,entity,entity_id,detail
  ) values(
    v_business.id,v_actor,'STRANDED_APPLICATION_ACTIVATED_V169',
    'businesses',v_business.id,jsonb_build_object(
      'application_id',v_application.id,
      'owner_user_id',v_owner,
      'sector_bundle_version_id',v_bundle.id,
      'originally_decided_at',v_application.decided_at
    )
  );

  return jsonb_build_object(
    'application_id',v_application.id,'status','consumed',
    'business_id',v_business.id,'business_slug',v_business.slug,
    'owner_staff_id',v_staff,'default_branch_id',v_branch,
    'workspace_created',true,'workspace_access',true,
    'approved_email',v_application.contact_email,'replayed',false
  );
end
$$;

--
-- Name: FUNCTION platform_activate_approved_application_v169(p_application uuid, p_idempotency_key uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.platform_activate_approved_application_v169(p_application uuid, p_idempotency_key uuid) IS 'V169 super-admin repair: finish workspace activation for applications approved before V167 shipped direct activation (status=approved, consumed_at is null). Idempotent on already-consumed rows.';

--
-- Name: platform_add_my_prospect_activity_v89(uuid, text, text, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_add_my_prospect_activity_v89(p_prospect uuid, p_activity_type text, p_summary text, p_detail text DEFAULT NULL::text, p_occurred_at timestamp with time zone DEFAULT now()) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_id uuid;v_type text:=lower(btrim(coalesce(p_activity_type,'')));
  v_summary text:=nullif(btrim(p_summary),'');
begin
  if not app.v89_platform_can('onboarding','rw')
     or not app.v89_can_access_prospect(p_prospect) then
    raise exception 'scoped onboarding write access is required' using errcode='42501';
  end if;
  if v_type not in(
    'note','call','email','whatsapp','meeting','demo','task','document_sent',
    'proposal_sent','contract_sent','payment','onboarding_session','npu_attempt',
    'system'
  ) or length(coalesce(v_summary,'')) not between 2 and 240
     or p_occurred_at>now()+interval '5 minutes' then
    raise exception 'invalid prospect activity' using errcode='22023';
  end if;
  insert into public.sme_prospect_activities(
    prospect_id,consultant_id,activity_type,summary,detail,occurred_at,created_by
  ) values(
    p_prospect,app.v89_sales_consultant_id(),v_type,v_summary,
    nullif(btrim(p_detail),''),p_occurred_at,auth.uid()
  ) returning id into v_id;
  update public.sme_prospects set updated_by=auth.uid(),updated_at=now(),
    version=version+1 where id=p_prospect;
  return jsonb_build_object('activity_id',v_id,'prospect_id',p_prospect,
    'status','created');
end
$$;

--
-- Name: platform_add_prospect_activity_v76(uuid, text, text, text, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_add_prospect_activity_v76(p_prospect uuid, p_activity_type text, p_summary text, p_detail text, p_occurred_at timestamp with time zone, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_actor uuid:=auth.uid();v_hash text;v_replay jsonb;v_id uuid;v_response jsonb;v_consultant uuid;
begin
  if not app.is_platform_operator_v75() then raise exception 'platform operator access is required' using errcode='42501';end if;
  if p_activity_type not in (
    'note','call','email','whatsapp','meeting','demo','task','document_sent',
    'proposal_sent','contract_sent','payment','onboarding_session','system'
  ) then
    raise exception 'unsupported manual activity type' using errcode='22023';end if;
  select assigned_consultant_id into v_consultant from public.sme_prospects where id=p_prospect;
  if not found then raise exception 'prospect was not found' using errcode='22023';end if;
  v_hash:=app.v76_sha256_hex(jsonb_build_object('prospect',p_prospect,'type',p_activity_type,
    'summary',p_summary,'detail',p_detail,'occurred_at',p_occurred_at)::text);
  v_replay:=app.v76_replay(v_actor,'add_activity',p_idempotency_key,v_hash);if v_replay is not null then return v_replay;end if;
  insert into public.sme_prospect_activities(prospect_id,consultant_id,activity_type,summary,detail,occurred_at,created_by)
  values(p_prospect,v_consultant,p_activity_type,btrim(p_summary),p_detail,coalesce(p_occurred_at,now()),v_actor) returning id into v_id;
  update public.sme_prospects set updated_at=now(),updated_by=v_actor where id=p_prospect;
  insert into public.audit_log(business_id,actor,action,entity,entity_id,detail)
  values(null,v_actor,'SME_PROSPECT_ACTIVITY_ADDED_V76','sme_prospect_activities',v_id,
    jsonb_build_object('prospect_id',p_prospect,'activity_type',p_activity_type));
  v_response:=jsonb_build_object('replayed',false,'activity',(select to_jsonb(a) from public.sme_prospect_activities a where id=v_id));
  perform app.v76_store_receipt(v_actor,'add_activity',p_idempotency_key,v_hash,v_response);return v_response;
end
$$;

--
-- Name: platform_analyse_prospect_import_v86(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_analyse_prospect_import_v86(p_batch uuid, p_column_mapping jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $_$
declare
  v_actor uuid:=auth.uid();v_batch public.sme_prospect_import_batches%rowtype;
  v_pair record;v_row public.sme_prospect_import_rows%rowtype;v_normal jsonb;
  v_company text;v_uen text;v_email text;v_phone text;v_domain text;v_postal text;v_stage text;
  v_errors text[];v_candidate record;v_candidate_count integer;v_status text;
  v_valid integer:=0;v_unmapped integer:=0;v_conflict integer:=0;v_invalid integer:=0;
begin
  if not app.is_platform_operator_v75() then raise exception 'platform operator access is required' using errcode='42501';end if;
  select * into v_batch from public.sme_prospect_import_batches where id=p_batch for update;
  if not found or v_batch.status<>'staged' then raise exception 'staged import batch was not found' using errcode='22023';end if;
  if p_column_mapping is null or jsonb_typeof(p_column_mapping)<>'object' then
    raise exception 'column mapping must be an object of canonical field to source header' using errcode='22023';end if;
  delete from public.sme_import_column_mappings where batch_id=p_batch;
  for v_pair in select key canonical_field,value source_header from jsonb_each_text(p_column_mapping)
  loop
    if v_pair.canonical_field like 'custom__%' then
      if substring(v_pair.canonical_field from 9)!~'^[a-z][a-z0-9_]{1,62}$' then
        raise exception 'invalid custom import field: %',v_pair.canonical_field using errcode='22023';end if;
      insert into public.sme_import_column_mappings(
        batch_id,source_header,canonical_field,custom_label,created_by
      ) values(p_batch,v_pair.source_header,null,
        replace(initcap(replace(substring(v_pair.canonical_field from 9),'_',' ')),'  ',' '),v_actor);
    else
      if not exists(select 1 from public.sme_import_field_definitions where canonical_field=v_pair.canonical_field) then
        raise exception 'unknown canonical import field: %',v_pair.canonical_field using errcode='22023';end if;
      insert into public.sme_import_column_mappings(batch_id,source_header,canonical_field,created_by)
      values(p_batch,v_pair.source_header,v_pair.canonical_field,v_actor);
    end if;
  end loop;
  if not exists(select 1 from public.sme_import_column_mappings where batch_id=p_batch and canonical_field='company_name') then
    raise exception 'company_name mapping is required' using errcode='22023';end if;
  delete from public.sme_import_dedupe_candidates where import_row_id in(
    select id from public.sme_prospect_import_rows where batch_id=p_batch);
  for v_row in select * from public.sme_prospect_import_rows where batch_id=p_batch order by row_number for update
  loop
    v_company:=app.v86_import_value(v_row.raw_payload,p_batch,'company_name');
    v_uen:=app.v86_import_value(v_row.raw_payload,p_batch,'registration_number');
    v_email:=lower(app.v86_import_value(v_row.raw_payload,p_batch,'email'));
    v_phone:=app.v86_normalize_phone(app.v86_import_value(v_row.raw_payload,p_batch,'phone'));
    v_domain:=app.v86_normalize_domain(app.v86_import_value(v_row.raw_payload,p_batch,'website'));
    v_postal:=app.v86_import_value(v_row.raw_payload,p_batch,'postal_code');
    v_stage:=app.map_sme_stage_v76(app.v86_import_value(v_row.raw_payload,p_batch,'stage'));
    v_errors:='{}';
    if v_company is null then v_errors:=array_append(v_errors,'company_name_required');end if;
    if v_email is not null and v_email!~'^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' then
      v_errors:=array_append(v_errors,'invalid_email');end if;
    if app.v86_import_value(v_row.raw_payload,p_batch,'phone') is not null and v_phone is null then
      v_errors:=array_append(v_errors,'invalid_phone');end if;
    if v_postal is not null and v_postal!~'^[A-Za-z0-9 -]{3,12}$' then
      v_errors:=array_append(v_errors,'invalid_postal_code');end if;
    if v_uen is not null and v_uen!~'^[A-Za-z0-9-]{5,32}$' then
      v_errors:=array_append(v_errors,'invalid_registration_number');end if;
    v_normal:=jsonb_build_object(
      'company_name',v_company,'registration_number',nullif(upper(v_uen),''),
      'contact_name',app.v86_import_value(v_row.raw_payload,p_batch,'contact_name'),
      'job_title',app.v86_import_value(v_row.raw_payload,p_batch,'job_title'),
      'email',v_email,'phone_e164',v_phone,'website_domain',v_domain,'postal_code',v_postal,
      'address',app.v86_import_value(v_row.raw_payload,p_batch,'address'),
      'directory_code',app.v86_import_value(v_row.raw_payload,p_batch,'directory_code'),
      'rating',app.v86_import_value(v_row.raw_payload,p_batch,'rating'),
      'review_count',app.v86_import_value(v_row.raw_payload,p_batch,'review_count'),
      'region',app.v86_import_value(v_row.raw_payload,p_batch,'region'),
      'industry',app.v86_import_value(v_row.raw_payload,p_batch,'industry'),
      'employee_count',app.v86_import_value(v_row.raw_payload,p_batch,'employee_count'),
      'notes',app.v86_import_value(v_row.raw_payload,p_batch,'notes'),
      'raw_stage',app.v86_import_value(v_row.raw_payload,p_batch,'stage'),'mapped_stage_key',v_stage
    );
    v_candidate_count:=0;
    for v_candidate in
      select prospect.id,
        case
          when v_uen is not null and lower(btrim(company.registration_number))=lower(btrim(v_uen)) then 'registration_number'
          when v_domain is not null and app.v86_normalize_domain(company.website)=v_domain then 'domain'
          when v_email is not null and (
            lower(btrim(company.email))=v_email or exists(select 1 from public.sme_prospect_contacts c where c.prospect_id=prospect.id and lower(btrim(c.email))=v_email)
          ) then 'email'
          when v_phone is not null and (
            app.v86_normalize_phone(company.phone)=v_phone or exists(select 1 from public.sme_prospect_contacts c where c.prospect_id=prospect.id and app.v86_normalize_phone(c.phone)=v_phone)
          ) then 'phone'
          when app.v86_normalize_text(coalesce(company.legal_name,company.trading_name))=app.v86_normalize_text(v_company)
            and (v_postal is null or coalesce(profile.postal_code,'')=v_postal) then 'company_name_postal'
          else 'similar_name' end match_basis,
        case
          when v_uen is not null and lower(btrim(company.registration_number))=lower(btrim(v_uen)) then 100
          when v_domain is not null and app.v86_normalize_domain(company.website)=v_domain then 95
          when v_email is not null and (
            lower(btrim(company.email))=v_email or exists(select 1 from public.sme_prospect_contacts c where c.prospect_id=prospect.id and lower(btrim(c.email))=v_email)
          ) then 90
          when v_phone is not null and (
            app.v86_normalize_phone(company.phone)=v_phone or exists(select 1 from public.sme_prospect_contacts c where c.prospect_id=prospect.id and app.v86_normalize_phone(c.phone)=v_phone)
          ) then 85
          else 70 end score
      from public.sme_prospects prospect
      join public.sme_companies company on company.id=prospect.company_id
      left join lateral(
        select p.* from public.sme_company_profile_versions p where p.company_id=company.id order by p.version desc limit 1
      ) profile on true
      where (v_uen is not null and lower(btrim(company.registration_number))=lower(btrim(v_uen)))
         or (v_domain is not null and app.v86_normalize_domain(company.website)=v_domain)
         or (v_email is not null and (lower(btrim(company.email))=v_email or exists(
           select 1 from public.sme_prospect_contacts c where c.prospect_id=prospect.id and lower(btrim(c.email))=v_email)))
         or (v_phone is not null and (app.v86_normalize_phone(company.phone)=v_phone or exists(
           select 1 from public.sme_prospect_contacts c where c.prospect_id=prospect.id and app.v86_normalize_phone(c.phone)=v_phone)))
         or app.v86_normalize_text(coalesce(company.legal_name,company.trading_name))=app.v86_normalize_text(v_company)
      order by score desc,prospect.created_at limit 20
    loop
      insert into public.sme_import_dedupe_candidates(
        import_row_id,candidate_prospect_id,match_basis,score,evidence
      ) values(v_row.id,v_candidate.id,v_candidate.match_basis,v_candidate.score,
        jsonb_build_object('priority',
          case v_candidate.match_basis when 'registration_number' then 1 when 'domain' then 2
            when 'email' then 3 when 'phone' then 4 else 5 end))
      on conflict do nothing;
      v_candidate_count:=v_candidate_count+1;
    end loop;
    if cardinality(v_errors)>0 then v_status:='invalid';v_invalid:=v_invalid+1;
    elsif v_candidate_count>0 or exists(
      select 1 from public.sme_prospect_import_rows prior
       where prior.batch_id=p_batch and prior.row_number<v_row.row_number and (
         (v_uen is not null and prior.normalized_payload->>'registration_number'=upper(v_uen))
         or (v_domain is not null and prior.normalized_payload->>'website_domain'=v_domain)
         or (v_email is not null and prior.normalized_payload->>'email'=v_email)
         or (v_phone is not null and prior.normalized_payload->>'phone_e164'=v_phone)
       )
    ) then v_status:='conflict';v_conflict:=v_conflict+1;
    elsif v_stage is null and v_normal->>'raw_stage' is not null then v_status:='unmapped';v_unmapped:=v_unmapped+1;
    else v_status:='valid';v_valid:=v_valid+1;end if;
    update public.sme_prospect_import_rows set normalized_payload=v_normal,mapped_stage_key=v_stage,
      raw_stage=v_normal->>'raw_stage',row_status=v_status,errors=v_errors where id=v_row.id;
    insert into public.sme_import_row_decision_versions(
      import_row_id,version,decision,reason,decided_by
    ) values(v_row.id,coalesce((select max(version)+1 from public.sme_import_row_decision_versions where import_row_id=v_row.id),1),
      case when v_status in ('valid','unmapped') then 'insert'
           when v_status='invalid' then 'skip' else 'review' end,
      'v86 normalized import analysis',v_actor);
  end loop;
  update public.sme_prospect_import_batches set valid_rows=v_valid,unmapped_rows=v_unmapped,
    conflict_rows=v_conflict,invalid_rows=v_invalid,skipped_rows=v_invalid where id=p_batch;
  insert into public.audit_log(business_id,actor,action,entity,entity_id,detail)
  values(null,v_actor,'SME_PROSPECT_IMPORT_ANALYSED_V86','sme_prospect_import_batches',p_batch,
    jsonb_build_object('valid_rows',v_valid,'unmapped_rows',v_unmapped,
      'conflict_rows',v_conflict,'invalid_rows',v_invalid));
  return jsonb_build_object('batch_id',p_batch,'valid_rows',v_valid,'unmapped_rows',v_unmapped,
    'conflict_rows',v_conflict,'invalid_rows',v_invalid);
end
$_$;

--
-- Name: platform_archive_prospect_v184(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_archive_prospect_v184(p_prospect uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_actor uuid:=auth.uid(); v_row public.sme_prospects%rowtype;
begin
  if not app.is_super_admin() then
    raise exception 'super admin access is required' using errcode='42501';
  end if;
  if coalesce(btrim(p_reason),'')='' then
    raise exception 'a reason is required to archive a firm record' using errcode='22023';
  end if;
  select * into v_row from public.sme_prospects where id=p_prospect;
  if not found then
    raise exception 'firm record not found' using errcode='22023';
  end if;
  if v_row.archived_at is not null then
    return jsonb_build_object('status','already_archived','prospect',p_prospect,
      'archived_at',v_row.archived_at);
  end if;
  perform app.v184_assert_archivable(p_prospect);

  update public.sme_prospects
     set archived_at=now(), archived_by=v_actor, archive_reason=btrim(p_reason),
         updated_at=now(), updated_by=v_actor
   where id=p_prospect;

  insert into public.audit_log(business_id,actor,action,entity,entity_id,detail)
  values(null,v_actor,'PLATFORM_PROSPECT_ARCHIVED_V184','sme_prospects',p_prospect,
    jsonb_build_object('reason',btrim(p_reason),'stage',v_row.current_stage_key));
  return jsonb_build_object('status','archived','prospect',p_prospect);
end $$;

--
-- Name: platform_assign_business_sector_v75(uuid, uuid, bigint, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_assign_business_sector_v75(p_business uuid, p_bundle_version uuid, p_expected_version bigint DEFAULT NULL::bigint, p_dry_run boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid(); v_assignment public.business_sector_assignments%rowtype;
  v_bundle public.sector_bundle_versions%rowtype; v_effective text[]; v_next bigint;
  v_changed boolean;
begin
  if not app.is_super_admin() then
    raise exception 'super admin access is required' using errcode = '42501';
  end if;
  perform 1 from public.businesses where id = p_business for update;
  if not found then raise exception 'business was not found' using errcode = '22023'; end if;
  select * into v_bundle from public.sector_bundle_versions
   where id = p_bundle_version and status = 'published';
  if not found then raise exception 'published sector bundle was not found' using errcode = '22023'; end if;
  select * into v_assignment from public.business_sector_assignments
   where business_id = p_business for update;
  if found and p_expected_version is not null and v_assignment.version <> p_expected_version then
    raise exception 'sector assignment version conflict' using errcode = '40001';
  end if;
  v_next := case when v_assignment.business_id is null then 1 else v_assignment.version + 1 end;
  v_effective := app.resolve_sector_entitlement_v75(v_bundle.id, '{}', '{}');
  v_changed := v_assignment.business_id is null
    or v_assignment.bundle_version_id <> v_bundle.id
    or v_assignment.override_version_id is not null;
  if not coalesce(p_dry_run, true) and v_changed then
    insert into public.business_sector_assignments(
      business_id,bundle_version_id,override_version_id,version,assigned_by,assigned_at,updated_at
    ) values (p_business,v_bundle.id,null,v_next,v_actor,now(),now())
    on conflict (business_id) do update set
      bundle_version_id=excluded.bundle_version_id, override_version_id=null,
      version=excluded.version, assigned_by=excluded.assigned_by, updated_at=now();
    perform set_config('app.sector_entitlement_sync', p_business::text, true);
    update public.businesses
       set enabled_modules = v_effective,
           industry = v_bundle.sector_key
     where id = p_business;
    insert into public.audit_log(business_id, actor, action, entity, entity_id, detail)
    values (p_business, v_actor, 'BUSINESS_SECTOR_ASSIGNED_V75', 'businesses',
            p_business, jsonb_build_object('bundle_version_id',v_bundle.id,
              'sector_key',v_bundle.sector_key,'assignment_version',v_next,
              'effective_modules',v_effective));
  end if;
  return jsonb_build_object(
    'dry_run',coalesce(p_dry_run,true),'changed',v_changed,'business_id',p_business,
    'assignment_version',case when v_changed then v_next else v_assignment.version end,
    'bundle_version_id',v_bundle.id,'sector_key',v_bundle.sector_key,
    'override_version_id',null,'effective_modules',to_jsonb(v_effective)
  );
end
$$;

--
-- Name: platform_assign_prospect_v89(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_assign_prospect_v89(p_prospect uuid, p_consultant uuid, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if not app.is_super_admin() then
    raise exception 'only the super admin may assign firms to consultants'
      using errcode='42501';
  end if;
  if p_consultant is not null and not exists(
    select 1 from public.platform_consultants consultant
    where consultant.id=p_consultant and consultant.active
  ) then raise exception 'active consultant is required' using errcode='22023';end if;
  perform 1 from public.sme_prospects where id=p_prospect for update;
  if not found then raise exception 'prospect was not found' using errcode='22023';end if;
  update public.sme_prospects set assigned_consultant_id=p_consultant,
    updated_by=auth.uid(),updated_at=now(),version=version+1
    where id=p_prospect;
  insert into public.sme_prospect_assignments(
    prospect_id,consultant_id,assigned_by,reason
  ) values(p_prospect,p_consultant,auth.uid(),nullif(btrim(p_reason),''));
  return jsonb_build_object('prospect_id',p_prospect,
    'assigned_consultant_id',p_consultant,'status','assigned');
end $$;

--
-- Name: platform_campaign_detail_v255(uuid, date, date, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_campaign_detail_v255(p_business uuid, p_from date, p_to date, p_limit integer DEFAULT 100, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid:=auth.uid();
  v_from timestamptz;
  v_to timestamptz;
  v_items jsonb;
  v_summary jsonb;
  v_total integer:=0;
begin
  if v_actor is null then
    raise exception 'authenticated platform session is required'
      using errcode='28000';
  end if;
  if not app.is_super_admin() then
    raise exception 'platform campaign reporting is super admin only'
      using errcode='42501';
  end if;
  if p_business is null then
    raise exception 'a business is required' using errcode='22023';
  end if;
  if p_from is null or p_to is null or p_to<p_from then
    raise exception 'report range must be positive' using errcode='22023';
  end if;
  if p_to>p_from+interval '24 months' then
    raise exception 'report range may not exceed 24 months'
      using errcode='22023';
  end if;
  if p_limit is null or p_limit not between 1 and 500 then
    raise exception 'row limit must be 1..500' using errcode='22023';
  end if;
  if p_offset is null or p_offset<0 or p_offset>100000 then
    raise exception 'offset must be 0..100000' using errcode='22023';
  end if;

  v_from:=(p_from::timestamp at time zone 'Asia/Singapore');
  v_to:=((p_to::timestamp+interval '1 day') at time zone 'Asia/Singapore');

  with scoped as(
    select record.*
    from public.campaign_send_records_v255 record
    where record.business_id=p_business
      and record.occurred_at>=v_from and record.occurred_at<v_to
  ),
  push_facts as(
    select
      scoped.campaign_kind,scoped.campaign_ref_id,
      count(*) filter(where result.result='sent')::bigint as push_sent,
      count(*) filter(
        where result.result in ('failed','gone')
      )::bigint as push_failed
    from scoped
    join public.customer_push_deliveries_v95 delivery
      on delivery.event_id=scoped.inbox_event_id
    join public.customer_push_delivery_results_v95 result
      on result.delivery_id=delivery.id
    group by 1,2
  ),
  open_facts as(
    select
      scoped.campaign_kind,scoped.campaign_ref_id,
      count(*) filter(where state.read_at is not null)::bigint as in_app_opens
    from scoped
    join public.customer_in_app_inbox_state state
      on state.event_id=scoped.inbox_event_id
    group by 1,2
  ),
  campaigns as(
    select
      scoped.campaign_kind,scoped.campaign_ref_id,
      max(scoped.campaign_label) as campaign_label,
      min(scoped.occurred_at) as first_sent_at,
      max(scoped.occurred_at) as last_sent_at,
      count(*)::bigint as recipients,
      count(*) filter(where scoped.channel='in_app')::bigint as in_app_sent,
      array_agg(distinct scoped.channel order by scoped.channel)
        as delivery_channels
    from scoped
    group by 1,2
  ),
  page as(
    select
      campaigns.*,
      coalesce(push_facts.push_sent,0) as push_sent,
      coalesce(push_facts.push_failed,0) as push_failed,
      coalesce(open_facts.in_app_opens,0) as in_app_opens
    from campaigns
    left join push_facts
      on push_facts.campaign_kind=campaigns.campaign_kind
     and push_facts.campaign_ref_id=campaigns.campaign_ref_id
    left join open_facts
      on open_facts.campaign_kind=campaigns.campaign_kind
     and open_facts.campaign_ref_id=campaigns.campaign_ref_id
    order by campaigns.first_sent_at desc,campaigns.campaign_label
    offset p_offset
    limit p_limit
  )
  select
    coalesce(
      pg_catalog.jsonb_agg(
        pg_catalog.jsonb_build_object(
          'campaign_kind',page.campaign_kind,
          'campaign_ref_id',page.campaign_ref_id,
          'campaign_label',page.campaign_label,
          'delivery_channels',pg_catalog.to_jsonb(page.delivery_channels),
          'first_sent_at',page.first_sent_at,
          'last_sent_at',page.last_sent_at,
          'recipients',page.recipients,
          'in_app_sent',page.in_app_sent,
          'in_app_opens',page.in_app_opens,
          'push_sent',page.push_sent,
          'push_failed',page.push_failed,
          'push_delivered',null::text,
          'push_opens',null::text
        )
        order by page.first_sent_at desc,page.campaign_label
      ),
      '[]'::jsonb
    ),
    (
      select count(distinct
        record.campaign_kind||':'||record.campaign_ref_id::text
      )::integer
      from public.campaign_send_records_v255 record
      where record.business_id=p_business
        and record.occurred_at>=v_from and record.occurred_at<v_to
    )
  into v_items,v_total
  from page;

  select pg_catalog.jsonb_build_object(
    'campaigns',count(*),
    'recipients',coalesce(sum((item->>'recipients')::bigint),0),
    'in_app_sent',coalesce(sum((item->>'in_app_sent')::bigint),0),
    'in_app_opens',coalesce(sum((item->>'in_app_opens')::bigint),0),
    'push_sent',coalesce(sum((item->>'push_sent')::bigint),0),
    'push_failed',coalesce(sum((item->>'push_failed')::bigint),0),
    'push_delivered',null::text,
    'push_opens',null::text
  ) into v_summary
  from pg_catalog.jsonb_array_elements(v_items) as element(item);

  return pg_catalog.jsonb_build_object(
    'scope',pg_catalog.jsonb_build_object(
      'business_id',p_business,'from',p_from,'to',p_to,
      'limit',p_limit,'offset',p_offset,'timezone','Asia/Singapore'
    ),
    'methodology',pg_catalog.jsonb_build_object(
      'delivered',
        'Not tracked. A web push provider returns no delivery confirmation.',
      'push_opens',
        'Not tracked. The Push API exposes no open callback to the server.',
      'in_app_opens',
        'Recipients who opened the in-app notification at least once.',
      'audience_only',
        'A campaign whose only channel is none was frozen as an audience and never delivered.'
    ),
    'summary',coalesce(v_summary,'{}'::jsonb),
    'items',v_items,
    'total_count',v_total,
    'has_more',v_total>p_offset+p_limit,
    'next_offset',p_offset+p_limit,
    'snapshot_at',clock_timestamp()
  );
end
$$;

--
-- Name: FUNCTION platform_campaign_detail_v255(p_business uuid, p_from date, p_to date, p_limit integer, p_offset integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.platform_campaign_detail_v255(p_business uuid, p_from date, p_to date, p_limit integer, p_offset integer) IS 'Per-campaign send history for one business. push_delivered and push_opens are always null because the Web Push API cannot report them; a zero would be a false measurement.';

--
-- Name: platform_commit_prospect_import_v76(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_commit_prospect_import_v76(p_batch uuid, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid:=auth.uid();v_hash text;v_replay jsonb;v_batch public.sme_prospect_import_batches%rowtype;
  v_row public.sme_prospect_import_rows%rowtype;v_company uuid;v_prospect uuid;v_imported integer:=0;v_response jsonb;
begin
  if not app.is_platform_operator_v75() then raise exception 'platform operator access is required' using errcode='42501';end if;
  v_hash:=app.v76_sha256_hex(jsonb_build_object('batch',p_batch)::text);
  v_replay:=app.v76_replay(v_actor,'commit_import',p_idempotency_key,v_hash);if v_replay is not null then return v_replay;end if;
  select * into v_batch from public.sme_prospect_import_batches where id=p_batch for update;
  if not found or v_batch.status<>'staged' then raise exception 'staged import batch was not found' using errcode='22023';end if;
  for v_row in select * from public.sme_prospect_import_rows
    where batch_id=p_batch and row_status in ('valid','unmapped') order by row_number for update
  loop
    insert into public.sme_companies(legal_name,trading_name,registration_number,industry,sector_key,email,phone)
    values(nullif(btrim(v_row.raw_payload->>'legal_name'),''),nullif(btrim(v_row.raw_payload->>'trading_name'),''),
      nullif(btrim(v_row.raw_payload->>'registration_number'),''),nullif(btrim(v_row.raw_payload->>'industry'),''),
      nullif(btrim(v_row.raw_payload->>'sector_key'),''),nullif(btrim(v_row.raw_payload->>'email'),''),
      nullif(btrim(v_row.raw_payload->>'phone'),'')) returning id into v_company;
    insert into public.sme_prospects(company_id,current_stage_key,legacy_stage_raw,created_by,updated_by)
    values(v_company,v_row.mapped_stage_key,case when v_row.mapped_stage_key is null then v_row.raw_stage end,v_actor,v_actor)
    returning id into v_prospect;
    if coalesce(v_row.raw_payload->>'contact_name','')<>'' and
       (coalesce(v_row.raw_payload->>'contact_email','')<>'' or coalesce(v_row.raw_payload->>'contact_phone','')<>'') then
      insert into public.sme_prospect_contacts(prospect_id,full_name,email,phone,is_primary)
      values(v_prospect,btrim(v_row.raw_payload->>'contact_name'),nullif(btrim(v_row.raw_payload->>'contact_email'),''),
        nullif(btrim(v_row.raw_payload->>'contact_phone'),''),true);
    end if;
    insert into public.sme_prospect_source_lineage(prospect_id,source_system,source_type,external_id,detail,created_by)
    values(v_prospect,v_batch.source_system,'import',nullif(v_row.raw_payload->>'external_id',''),
      jsonb_build_object('batch_id',p_batch,'row_number',v_row.row_number),v_actor);
    if v_row.mapped_stage_key is null then
      insert into public.sme_prospect_data_quality_flags(prospect_id,flag_code,severity,detail)
      values(v_prospect,'unmapped_stage','warning','Legacy stage: '||coalesce(v_row.raw_stage,'(blank)'));
    else
      insert into public.sme_prospect_stage_history(prospect_id,to_stage_key,actor)
      values(v_prospect,v_row.mapped_stage_key,v_actor);
    end if;
    update public.sme_prospect_import_rows set row_status='imported',prospect_id=v_prospect where id=v_row.id;
    v_imported:=v_imported+1;
  end loop;
  update public.sme_prospect_import_batches set status='committed',imported_rows=v_imported,committed_at=now() where id=p_batch;
  insert into public.audit_log(business_id,actor,action,entity,entity_id,detail)
  values(null,v_actor,'SME_PROSPECT_IMPORT_COMMITTED_V76','sme_prospect_import_batches',p_batch,
    jsonb_build_object('imported_rows',v_imported,'unmapped_rows',v_batch.unmapped_rows,
      'conflict_rows',v_batch.conflict_rows,'invalid_rows',v_batch.invalid_rows,
      'skipped_rows',v_batch.skipped_rows));
  v_response:=jsonb_build_object('replayed',false,'batch_id',p_batch,'status','committed',
    'imported_rows',v_imported,'unmapped_rows',v_batch.unmapped_rows,
    'conflict_rows',v_batch.conflict_rows,'invalid_rows',v_batch.invalid_rows,
    'skipped_rows',v_batch.skipped_rows);
  perform app.v76_store_receipt(v_actor,'commit_import',p_idempotency_key,v_hash,v_response);return v_response;
end
$$;

--
-- Name: platform_commit_prospect_import_v86(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_commit_prospect_import_v86(p_batch uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid:=auth.uid();v_batch public.sme_prospect_import_batches%rowtype;v_row record;
  v_company uuid;v_prospect uuid;v_contact uuid;v_source uuid;v_inserted integer:=0;v_merged integer:=0;v_skipped integer:=0;
begin
  if not app.is_platform_operator_v75() then raise exception 'platform operator access is required' using errcode='42501';end if;
  select * into v_batch from public.sme_prospect_import_batches where id=p_batch for update;
  if not found or v_batch.status<>'staged' then raise exception 'staged import batch was not found' using errcode='22023';end if;
  if exists(
    select 1 from public.sme_prospect_import_rows row
    left join lateral(
      select d.* from public.sme_import_row_decision_versions d where d.import_row_id=row.id order by d.version desc limit 1
    ) decision on true
    where row.batch_id=p_batch and (decision.id is null or decision.decision='review')
  ) then raise exception 'all import rows require a final insert, merge or skip decision' using errcode='22023';end if;
  for v_row in
    select row.*,decision.decision,decision.candidate_prospect_id
      from public.sme_prospect_import_rows row
      join lateral(
        select d.* from public.sme_import_row_decision_versions d where d.import_row_id=row.id order by d.version desc limit 1
      ) decision on true
     where row.batch_id=p_batch order by row.row_number for update of row
  loop
    if v_row.decision='skip' then v_skipped:=v_skipped+1;continue;end if;
    if v_row.decision='merge' then
      v_prospect:=v_row.candidate_prospect_id;
      select company_id into v_company from public.sme_prospects where id=v_prospect;
      insert into public.sme_prospect_source_lineage(
        prospect_id,source_system,source_type,external_id,detail,created_by
      ) values(v_prospect,v_batch.source_system,'import',null,
        jsonb_build_object('batch_id',p_batch,'row_number',v_row.row_number,
          'raw_payload',v_row.raw_payload,'merge_decision','reviewed_no_field_overwrite'),v_actor)
      returning id into v_source;
      insert into public.sme_import_commit_ledger(
        batch_id,import_row_id,decision,prospect_id,company_id,source_lineage_id,
        prospect_version_at_commit,committed_by
      ) select p_batch,v_row.id,'merge',prospect.id,prospect.company_id,v_source,prospect.version,v_actor
          from public.sme_prospects prospect where prospect.id=v_prospect;
      update public.sme_prospect_import_rows set row_status='imported',prospect_id=v_prospect where id=v_row.id;
      v_merged:=v_merged+1;continue;
    end if;
    insert into public.sme_companies(
      legal_name,trading_name,registration_number,industry,website,email,phone,address
    ) values(
      v_row.normalized_payload->>'company_name',v_row.normalized_payload->>'company_name',
      nullif(v_row.normalized_payload->>'registration_number',''),
      nullif(v_row.normalized_payload->>'industry',''),
      nullif(v_row.normalized_payload->>'website_domain',''),
      nullif(v_row.normalized_payload->>'email',''),
      nullif(v_row.normalized_payload->>'phone_e164',''),
      jsonb_build_object('registered_address',v_row.normalized_payload->>'address',
        'postal_code',v_row.normalized_payload->>'postal_code')
    ) returning id into v_company;
    insert into public.sme_prospects(
      company_id,current_stage_key,legacy_stage_raw,region,created_by,updated_by
    ) values(v_company,v_row.mapped_stage_key,
      case when v_row.mapped_stage_key is null then v_row.raw_stage end,
      nullif(v_row.normalized_payload->>'region',''),v_actor,v_actor)
    returning id into v_prospect;
    if nullif(v_row.normalized_payload->>'contact_name','') is not null and
       (nullif(v_row.normalized_payload->>'email','') is not null
         or nullif(v_row.normalized_payload->>'phone_e164','') is not null) then
      insert into public.sme_prospect_contacts(
        prospect_id,full_name,title,email,phone,is_primary
      ) values(v_prospect,v_row.normalized_payload->>'contact_name',
        nullif(v_row.normalized_payload->>'job_title',''),
        nullif(v_row.normalized_payload->>'email',''),
        nullif(v_row.normalized_payload->>'phone_e164',''),true) returning id into v_contact;
    end if;
    insert into public.sme_prospect_source_lineage(
      prospect_id,source_system,source_type,external_id,detail,created_by
    ) values(v_prospect,v_batch.source_system,'import',null,
      jsonb_build_object('batch_id',p_batch,'row_number',v_row.row_number,
        'raw_payload',v_row.raw_payload,'normalized_payload',v_row.normalized_payload),v_actor)
    returning id into v_source;
    if v_row.mapped_stage_key is not null then
      insert into public.sme_prospect_stage_history(prospect_id,to_stage_key,reason_code,actor)
      values(v_prospect,v_row.mapped_stage_key,'v86_import',v_actor);
    else
      insert into public.sme_prospect_data_quality_flags(prospect_id,flag_code,severity,detail)
      values(v_prospect,'unmapped_stage','warning','Legacy stage: '||coalesce(v_row.raw_stage,'(blank)'));
    end if;
    insert into public.sme_import_commit_ledger(
      batch_id,import_row_id,decision,prospect_id,company_id,source_lineage_id,
      prospect_version_at_commit,committed_by
    ) values(p_batch,v_row.id,'insert',v_prospect,v_company,v_source,1,v_actor);
    update public.sme_prospect_import_rows set row_status='imported',prospect_id=v_prospect where id=v_row.id;
    v_inserted:=v_inserted+1;
  end loop;
  update public.sme_prospect_import_batches set status='committed',imported_rows=v_inserted+v_merged,
    skipped_rows=v_skipped,committed_at=now() where id=p_batch;
  insert into public.audit_log(business_id,actor,action,entity,entity_id,detail)
  values(null,v_actor,'SME_PROSPECT_IMPORT_COMMITTED_V86','sme_prospect_import_batches',p_batch,
    jsonb_build_object('inserted_rows',v_inserted,'merged_rows',v_merged,'skipped_rows',v_skipped));
  return jsonb_build_object('batch_id',p_batch,'inserted_rows',v_inserted,
    'merged_rows',v_merged,'skipped_rows',v_skipped);
end
$$;

--
-- Name: platform_company_detail_v225(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_company_detail_v225(p_business uuid, p_payment_limit integer DEFAULT 24) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_limit integer := least(greatest(coalesce(p_payment_limit,24),1),200);
  v_today date := (clock_timestamp() at time zone 'Asia/Singapore')::date;
  v_company jsonb; v_subscription jsonb; v_outstanding jsonb;
  v_contacts jsonb; v_consultant jsonb; v_payments jsonb; v_lifecycle jsonb;
  v_prospect uuid;
begin
  if auth.uid() is null or not app.is_super_admin() then
    raise exception 'super-admin access is required' using errcode='42501';
  end if;
  if p_business is null then
    raise exception 'a company is required' using errcode='22023';
  end if;

  select b.source_prospect_id,
         jsonb_build_object(
           'id', b.id,
           'name', b.name,
           'legal_name', b.legal_name,
           'slug', b.slug,
           'sector', coalesce(nullif(btrim(b.industry),''),'unclassified'),
           'registration_number', b.registration_number,
           'currency', b.currency,
           'created_at', b.created_at,
           'onboarding_started_at', b.onboarding_started_at,
           'activated_at', b.activated_at,
           'is_demo', b.is_demo,
           'is_synthetic', b.is_synthetic,
           'branch_count', (select count(*) from public.branches br
                             where br.business_id = b.id and br.active),
           'seat_count', (select count(*) from public.staff st
                           where st.business_id = b.id
                             and st.user_id is not null and st.active))
    into v_prospect, v_company
    from public.businesses b
   where b.id = p_business;

  if v_company is null then
    raise exception 'company not found' using errcode='P0002';
  end if;

  select jsonb_build_object(
           'status', s.status,
           'payment_status', s.payment_status,
           'billing_provider', s.billing_provider,
           'collection_mode', case when s.billing_provider='stripe' then 'auto' else 'chase' end,
           'billing_cadence', s.billing_cadence,
           'cadence_months', s.cadence_months,
           'plan_code', s.plan_code,
           'product_code', s.product_code,
           'currency', s.currency,
           'base_price_cents', s.base_price_cents,
           'included_seats', s.included_seats,
           'per_seat_price_cents', s.per_seat_price_cents,
           'seat_limit', s.seat_limit,
           'period_total_cents', s.period_total_cents,
           'trial_ends_at', s.trial_ends_at,
           'current_period_start', s.current_period_start,
           'current_period_end', s.current_period_end,
           'next_payment_at', s.next_payment_at,
           'last_paid_at', s.last_paid_at,
           'cancel_at_period_end', s.cancel_at_period_end,
           'canceled_at', s.canceled_at,
           -- Positive = days until due; negative = days already overdue.
           -- Identical arithmetic to v203 so a row and its drawer never
           -- disagree about whether a firm is late.
           'days_until_due', case when s.next_payment_at is not null
             then ((s.next_payment_at at time zone 'Asia/Singapore')::date - v_today) end)
    into v_subscription
    from public.subscriptions s
   where s.business_id = p_business;

  -- Unpaid invoices only. A credit note or receipt carries no balance to chase.
  select jsonb_build_object(
           'open_invoice_count', count(*),
           'balance_due_cents', coalesce(sum(d.balance_due_cents),0),
           'currency', min(d.currency),
           'oldest_due_date', min(d.due_date),
           'days_outstanding', case when min(d.due_date) is not null
             then greatest(v_today - min(d.due_date), 0) end)
    into v_outstanding
    from public.platform_subscription_documents_v156 d
   where d.business_id = p_business
     and d.document_type = 'invoice'
     and coalesce(d.balance_due_cents,0) > 0;

  select coalesce(jsonb_agg(jsonb_build_object(
           'id', c.id,
           'full_name', c.full_name,
           'title', c.title,
           'email', c.email,
           'phone', c.phone,
           'is_primary', c.is_primary)
         order by c.is_primary desc, c.created_at), '[]'::jsonb)
    into v_contacts
    from public.sme_prospect_contacts c
   where c.prospect_id = v_prospect and c.active;

  select jsonb_build_object(
           'id', consultant.id,
           'display_name', consultant.display_name,
           'active', consultant.active)
    into v_consultant
    from public.sme_prospects prospect
    join public.platform_consultants consultant
      on consultant.id = prospect.assigned_consultant_id
   where prospect.id = v_prospect;

  -- Payment history: every financial document, newest first, with its manual
  -- payment record inline. A firm on auto-collect simply has no manual rows.
  select coalesce(jsonb_agg(to_jsonb(row) order by
           row.issue_date desc nulls last, row.created_at desc), '[]'::jsonb)
    into v_payments
    from (
      select d.id, d.document_type, d.document_number,
             d.issue_date, d.due_date,
             d.service_period_start, d.service_period_end,
             d.currency, d.total_cents, d.amount_paid_cents, d.balance_due_cents,
             d.created_at,
             m.status         as manual_status,
             m.value_date     as manual_value_date,
             m.payment_reference as manual_reference,
             m.bank_account_last4 as manual_bank_last4,
             m.amount_cents   as manual_amount_cents,
             m.verified_at    as manual_verified_at,
             m.rejection_reason as manual_rejection_reason
        from public.platform_subscription_documents_v156 d
        left join lateral (
          select status, value_date, payment_reference, bank_account_last4,
                 amount_cents, verified_at, rejection_reason
            from public.platform_manual_payments_v156
           where invoice_document_id = d.id
           order by (status='verified') desc, created_at desc
           limit 1) m on true
       where d.business_id = p_business
       order by d.issue_date desc nulls last, d.created_at desc
       limit v_limit) row;

  select coalesce(jsonb_agg(jsonb_build_object(
           'lifecycle_status', e.lifecycle_status,
           'source_type', e.source_type,
           'occurred_at', e.occurred_at)
         order by e.occurred_at desc), '[]'::jsonb)
    into v_lifecycle
    from (select lifecycle_status, source_type, occurred_at
            from public.platform_subscription_lifecycle_events_v156
           where business_id = p_business
           order by occurred_at desc
           limit 10) e;

  return jsonb_build_object(
    'today', v_today,
    'company', v_company,
    'subscription', v_subscription,
    'outstanding', coalesce(v_outstanding, jsonb_build_object(
      'open_invoice_count',0,'balance_due_cents',0,
      'currency',null,'oldest_due_date',null,'days_outstanding',null)),
    'contacts', coalesce(v_contacts,'[]'::jsonb),
    'consultant', v_consultant,
    'payments', coalesce(v_payments,'[]'::jsonb),
    'payments_truncated', (select count(*) > v_limit
       from public.platform_subscription_documents_v156
      where business_id = p_business),
    'lifecycle', coalesce(v_lifecycle,'[]'::jsonb));
end $$;

--
-- Name: platform_company_directory_v202(text, text, text, text, uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_company_directory_v202(p_search text DEFAULT NULL::text, p_sector text DEFAULT NULL::text, p_collection text DEFAULT NULL::text, p_due_window text DEFAULT NULL::text, p_consultant uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 100, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_limit integer := least(greatest(coalesce(p_limit,100),1),500);
  v_offset integer := greatest(coalesce(p_offset,0),0);
  v_today date := (clock_timestamp() at time zone 'Asia/Singapore')::date;
  v_search text := nullif(btrim(coalesce(p_search,'')),'');
  v_items jsonb; v_total bigint;
begin
  if auth.uid() is null or not app.is_super_admin() then
    raise exception 'super-admin access is required' using errcode='42501';
  end if;
  if p_collection is not null and p_collection not in ('auto','chase') then
    raise exception 'collection filter must be auto or chase' using errcode='22023';
  end if;
  if p_due_window is not null and p_due_window not in ('overdue','today','7','14','30') then
    raise exception 'unknown due window' using errcode='22023';
  end if;

  with base as (
    select
      b.id, b.name, b.legal_name, b.slug,
      coalesce(nullif(btrim(b.industry),''),'unclassified') as sector,
      b.created_at,
      s.status, s.payment_status, s.billing_provider,
      s.current_period_start, s.current_period_end,
      s.next_payment_at, s.last_paid_at, s.period_total_cents,
      s.cadence_months, s.cancel_at_period_end,
      case when s.billing_provider = 'stripe' then 'auto' else 'chase' end as collection_mode,
      p.assigned_consultant_id,
      c.full_name as contact_name, c.phone as contact_phone, c.email as contact_email,
      -- Positive = days until it falls due; negative = days already overdue.
      case when s.next_payment_at is not null
        then ((s.next_payment_at at time zone 'Asia/Singapore')::date - v_today)
      end as days_until_due
    from public.businesses b
    left join public.subscriptions s on s.business_id = b.id
    left join public.sme_prospects p on p.id = b.source_prospect_id
    left join lateral (
      select full_name, phone, email
        from public.sme_prospect_contacts
       where prospect_id = b.source_prospect_id and active
       order by is_primary desc, created_at
       limit 1) c on true
  ), filtered as (
    select * from base
     where (v_search is null
            or name ilike '%'||v_search||'%'
            or coalesce(legal_name,'') ilike '%'||v_search||'%'
            or coalesce(contact_name,'') ilike '%'||v_search||'%'
            or coalesce(contact_email,'') ilike '%'||v_search||'%'
            or coalesce(contact_phone,'') ilike '%'||v_search||'%')
       and (p_sector is null or sector = p_sector)
       and (p_collection is null or collection_mode = p_collection)
       and (p_consultant is null or assigned_consultant_id = p_consultant)
       and (p_due_window is null
            or (p_due_window = 'overdue' and days_until_due < 0)
            or (p_due_window = 'today'   and days_until_due = 0)
            or (p_due_window = '7'       and days_until_due between 0 and 7)
            or (p_due_window = '14'      and days_until_due between 0 and 14)
            or (p_due_window = '30'      and days_until_due between 0 and 30))
  )
  select
    coalesce(jsonb_agg(to_jsonb(row) order by
      (row.days_until_due is null), row.days_until_due, row.name), '[]'::jsonb),
    (select count(*) from filtered)
  into v_items, v_total
  from (select * from filtered order by
         (days_until_due is null), days_until_due, name
        limit v_limit offset v_offset) row;

  return jsonb_build_object(
    'items', v_items,
    'total_count', v_total,
    'returned', jsonb_array_length(v_items),
    'has_more', v_total > v_offset + jsonb_array_length(v_items),
    'today', v_today,
    'sectors', coalesce((select jsonb_agg(jsonb_build_object('sector',sector,'n',n) order by n desc, sector)
       from (select coalesce(nullif(btrim(industry),''),'unclassified') sector, count(*) n
               from public.businesses group by 1) t),'[]'::jsonb),
    'collection', coalesce((select jsonb_object_agg(mode,n) from (
       select case when s.billing_provider='stripe' then 'auto' else 'chase' end mode, count(*) n
         from public.businesses b left join public.subscriptions s on s.business_id=b.id
        group by 1) t),'{}'::jsonb),
    'due', (select jsonb_build_object(
       'overdue', count(*) filter (where d < 0),
       'today',   count(*) filter (where d = 0),
       'in_7',    count(*) filter (where d between 0 and 7),
       'in_14',   count(*) filter (where d between 0 and 14),
       'in_30',   count(*) filter (where d between 0 and 30))
       from (select ((s.next_payment_at at time zone 'Asia/Singapore')::date - v_today) d
               from public.businesses b join public.subscriptions s on s.business_id=b.id
              where s.next_payment_at is not null) t));
end $$;

--
-- Name: platform_complete_my_prospect_task_v89(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_complete_my_prospect_task_v89(p_task uuid, p_outcome text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_task public.sme_prospect_tasks%rowtype;
  v_outcome text:=nullif(btrim(p_outcome),'');
begin
  select * into v_task from public.sme_prospect_tasks where id=p_task for update;
  if not found or not app.v89_platform_can('onboarding','rw')
     or not app.v89_can_access_prospect(v_task.prospect_id) then
    raise exception 'scoped onboarding write access is required' using errcode='42501';
  end if;
  if length(coalesce(v_outcome,''))<2 then
    raise exception 'task outcome is required' using errcode='22023';
  end if;
  if v_task.status='completed' then
    return jsonb_build_object('task_id',p_task,'status','completed',
      'completed_at',v_task.completed_at);
  end if;
  update public.sme_prospect_tasks set status='completed',outcome=v_outcome,
    completed_at=now() where id=p_task returning * into v_task;
  return jsonb_build_object('task_id',p_task,'status','completed',
    'completed_at',v_task.completed_at);
end
$$;

--
-- Name: platform_complete_prospect_task_v76(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_complete_prospect_task_v76(p_task uuid, p_outcome text, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_actor uuid:=auth.uid();v_hash text;v_replay jsonb;v_row public.sme_prospect_tasks%rowtype;v_response jsonb;
begin
  if not app.is_platform_operator_v75() then raise exception 'platform operator access is required' using errcode='42501';end if;
  v_hash:=app.v76_sha256_hex(jsonb_build_object('task',p_task,'outcome',p_outcome)::text);
  v_replay:=app.v76_replay(v_actor,'complete_task',p_idempotency_key,v_hash);if v_replay is not null then return v_replay;end if;
  update public.sme_prospect_tasks set status='completed',outcome=btrim(p_outcome),completed_at=now()
   where id=p_task and status='open' returning * into v_row;
  if not found then raise exception 'open task was not found' using errcode='22023';end if;
  insert into public.audit_log(business_id,actor,action,entity,entity_id,detail)
  values(null,v_actor,'SME_PROSPECT_TASK_COMPLETED_V76','sme_prospect_tasks',p_task,
    jsonb_build_object('prospect_id',v_row.prospect_id,'outcome',v_row.outcome));
  v_response:=jsonb_build_object('replayed',false,'task',to_jsonb(v_row));
  perform app.v76_store_receipt(v_actor,'complete_task',p_idempotency_key,v_hash,v_response);return v_response;
end
$$;

--
-- Name: platform_complete_subscription_task_v156(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_complete_subscription_task_v156(p_task uuid, p_resolution text, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_actor uuid:=auth.uid();v_task public.platform_subscription_tasks_v156%rowtype;
begin
  if v_actor is null or not app.v156_can('rw') then raise exception 'billing write access is required' using errcode='42501';end if;
  if length(btrim(coalesce(p_resolution,'')))<3 or p_idempotency_key is null then raise exception 'resolution is required' using errcode='22023';end if;
  update public.platform_subscription_tasks_v156 set status='completed',completed_at=clock_timestamp(),resolution=btrim(p_resolution),updated_at=clock_timestamp() where id=p_task and status='open' returning * into v_task;
  if not found then select * into v_task from public.platform_subscription_tasks_v156 where id=p_task;if not found then raise exception 'task was not found' using errcode='22023';end if;end if;
  insert into public.platform_subscription_dispatch_audit_v156(action,entity_type,entity_id,detail,actor) values('subscription_task_completed','task',p_task,jsonb_build_object('resolution',p_resolution,'operation_key',p_idempotency_key),v_actor);
  return jsonb_build_object('task',to_jsonb(v_task));
end $$;

--
-- Name: platform_conversion_funnel_v312(date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_conversion_funnel_v312(p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_from timestamptz; v_to timestamptz; d jsonb;
begin
  perform app.v297_assert_prospecting('r');
  v_from := coalesce(p_from, current_date - 3650)::timestamptz;
  v_to := coalesce(p_to, current_date)::timestamptz + interval '1 day';

  with scoped as (
    select p.id, p.company_id, p.assigned_consultant_id, p.created_at,
           p.converted_at, p.current_stage_key,
           (c.peekaa_business_id is not null or p.converted_business_id is not null) as is_merchant,
           l.planning_area,
           sec.label as industry, cat.label as subcategory,
           (select min(h.occurred_at) from public.sme_prospect_stage_history h
             where h.prospect_id=p.id and h.to_stage_key='contacted') as contacted_at,
           (select min(h.occurred_at) from public.sme_prospect_stage_history h
             where h.prospect_id=p.id and h.to_stage_key='interested') as interested_at,
           (select min(h.occurred_at) from public.sme_prospect_stage_history h
             where h.prospect_id=p.id and h.to_stage_key='appointment') as appointment_at,
           (select min(h.occurred_at) from public.sme_prospect_stage_history h
             where h.prospect_id=p.id and h.to_stage_key in ('onboarding','account_created')) as onboarding_at,
           (select count(*) from public.sme_outreach_records o where o.prospect_id=p.id) as touches
      from public.sme_prospects p
      join public.sme_companies c on c.id=p.company_id
      left join public.sme_company_locations l on l.company_id=c.id and l.is_primary
      left join public.sme_company_categories cc on cc.company_id=c.id and cc.is_primary
      left join public.sme_categories cat on cat.id=cc.category_id
      left join public.sme_sectors sec on sec.id=cat.sector_id
     where p.archived_at is null and p.created_at >= v_from and p.created_at < v_to
  )
  select jsonb_build_object(
    'funnel', jsonb_build_object(
      'businesses', count(*),
      'non_peekaa', count(*) filter (where not is_merchant),
      'assigned', count(*) filter (where assigned_consultant_id is not null),
      'contacted', count(*) filter (where contacted_at is not null),
      'interested', count(*) filter (where interested_at is not null),
      'appointments', count(*) filter (where appointment_at is not null),
      'onboarding', count(*) filter (where onboarding_at is not null),
      'merchants', count(*) filter (where is_merchant)),
    'rates', jsonb_build_object(
      'contact_to_appointment', case when count(*) filter (where contacted_at is not null) > 0
        then round(100.0 * count(*) filter (where appointment_at is not null)
                 / count(*) filter (where contacted_at is not null), 1) else null end,
      'appointment_to_onboarding', case when count(*) filter (where appointment_at is not null) > 0
        then round(100.0 * count(*) filter (where onboarding_at is not null)
                 / count(*) filter (where appointment_at is not null), 1) else null end,
      'overall', case when count(*) > 0
        then round(100.0 * count(*) filter (where is_merchant) / count(*), 1) else null end),
    'effort', jsonb_build_object(
      'touches_per_conversion', case when count(*) filter (where is_merchant) > 0
        then round(sum(touches)::numeric / count(*) filter (where is_merchant), 1) else null end,
      'avg_days_to_conversion', (select round(avg(extract(epoch from (converted_at - created_at))/86400)::numeric,1)
                                   from scoped where converted_at is not null)),
    'by_consultant', coalesce((select jsonb_agg(x) from (
        select jsonb_build_object('consultant_id', assigned_consultant_id,
          'assigned', count(*), 'contacted', count(*) filter (where contacted_at is not null),
          'appointments', count(*) filter (where appointment_at is not null),
          'merchants', count(*) filter (where is_merchant)) as x
        from scoped where assigned_consultant_id is not null
        group by assigned_consultant_id) t),'[]'::jsonb),
    'by_location', coalesce((select jsonb_agg(x) from (
        select jsonb_build_object('planning_area', planning_area, 'businesses', count(*),
          'contacted', count(*) filter (where contacted_at is not null),
          'merchants', count(*) filter (where is_merchant)) as x
        from scoped where planning_area is not null group by planning_area) t),'[]'::jsonb),
    'by_industry', coalesce((select jsonb_agg(x) from (
        select jsonb_build_object('industry', industry, 'businesses', count(*),
          'merchants', count(*) filter (where is_merchant)) as x
        from scoped where industry is not null group by industry) t),'[]'::jsonb),
    'by_category', coalesce((select jsonb_agg(x) from (
        select jsonb_build_object('category', subcategory, 'businesses', count(*),
          'merchants', count(*) filter (where is_merchant)) as x
        from scoped where subcategory is not null group by subcategory) t),'[]'::jsonb)
  ) into d from scoped;

  return coalesce(d, '{}'::jsonb);
end $$;

--
-- Name: platform_create_invoice_v147(date, date, text, jsonb, jsonb, integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_create_invoice_v147(p_issue_date date, p_due_date date, p_transaction_reference text, p_counterparty jsonb, p_line_items jsonb, p_tax_rate_bps integer, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $_$
declare v_actor uuid:=auth.uid();v_policy public.platform_accounting_policies_v147%rowtype;v_existing public.platform_financial_documents_v147%rowtype;v_doc public.platform_financial_documents_v147%rowtype;
  v_id uuid:=gen_random_uuid();v_hash text;v_reference text:=upper(btrim(p_transaction_reference));v_subtotal bigint;v_tax bigint;v_total bigint;v_number text;v_journal jsonb;v_journal_id uuid;v_snapshot jsonb;
begin
  if v_actor is null or not app.is_super_admin() then raise exception 'super-admin access is required' using errcode='42501';end if;
  v_hash:=encode(extensions.digest(jsonb_build_object('issue_date',p_issue_date,'due_date',p_due_date,'transaction_reference',v_reference,'counterparty',p_counterparty,'line_items',p_line_items,'tax_rate_bps',p_tax_rate_bps)::text,'sha256'),'hex');
  perform pg_advisory_xact_lock(hashtextextended('platform_invoice:'||p_idempotency_key::text,147));
  select * into v_existing from public.platform_financial_documents_v147 where created_by=v_actor and operation_key=p_idempotency_key;
  if found then if v_existing.request_hash<>v_hash then raise exception 'idempotency key was reused with different input' using errcode='22023';end if;return jsonb_build_object('document',to_jsonb(v_existing),'replayed',true);end if;
  if v_reference is null or v_reference !~ '^NON-SUBSCRIPTION-[A-Z0-9][A-Z0-9._:/-]{0,82}$' then raise exception 'a unique approved NON-SUBSCRIPTION transaction reference is required' using errcode='22023';end if;
  perform pg_advisory_xact_lock(hashtextextended('platform_non_subscription_invoice:'||v_reference,147));
  if exists(select 1 from public.platform_financial_documents_v147 where source_type='generated_non_subscription_invoice' and source_id=v_reference)
     or exists(select 1 from public.billing_provider_invoices where upper(provider_invoice_id)=v_reference or upper(coalesce(number,''))=v_reference) then
    raise exception 'transaction reference already exists in generated or provider billing' using errcode='23505';
  end if;
  select * into v_policy from public.platform_accounting_policies_v147 where effective_from<=p_issue_date order by effective_from desc,version desc limit 1;
  if not found or v_policy.gst_status='pending_review' then raise exception 'reviewed accounting and tax identity must be configured first' using errcode='55000';end if;
  if p_due_date<p_issue_date or jsonb_typeof(p_counterparty)<>'object' or length(btrim(p_counterparty->>'legal_name'))<2 or jsonb_typeof(p_line_items)<>'array' or jsonb_array_length(p_line_items)=0 then raise exception 'valid invoice parties, dates and lines are required' using errcode='22023';end if;
  if (v_policy.gst_status='registered' and p_tax_rate_bps<>v_policy.gst_rate_bps) or (v_policy.gst_status<>'registered' and p_tax_rate_bps<>0) then raise exception 'invoice tax rate does not match reviewed tax status' using errcode='22023';end if;
  if v_policy.gst_status='registered' and (length(btrim(coalesce(p_counterparty->>'address','')))<5 or length(btrim(coalesce(p_counterparty->>'registration_number','')))<4) then raise exception 'GST invoice requires customer address and registration identity' using errcode='22023';end if;
  select sum((line->>'quantity')::bigint*(line->>'unit_amount_cents')::bigint) into v_subtotal from jsonb_array_elements(p_line_items) line where (line->>'quantity')::integer between 1 and 100000 and (line->>'unit_amount_cents')::integer>0 and length(btrim(line->>'description')) between 2 and 500;
  if v_subtotal is null or (select count(*) from jsonb_array_elements(p_line_items))<>(select count(*) from jsonb_array_elements(p_line_items) line where (line->>'quantity')::integer between 1 and 100000 and (line->>'unit_amount_cents')::integer>0 and length(btrim(line->>'description')) between 2 and 500) then raise exception 'invoice lines are invalid' using errcode='22023';end if;
  v_tax:=round(v_subtotal*p_tax_rate_bps/10000.0);v_total:=v_subtotal+v_tax;v_number:=app.platform_next_document_number_v147('invoice',v_policy.document_prefix);
  v_journal:=app.platform_post_journal_v147('generated_non_subscription_invoice',v_reference,p_issue_date,'Invoice '||v_number,jsonb_build_array(jsonb_build_object('account_code','1100','debit_cents',v_total,'credit_cents',0,'counterparty',p_counterparty->>'legal_name'),jsonb_build_object('account_code','4090','debit_cents',0,'credit_cents',v_subtotal,'counterparty',p_counterparty->>'legal_name'))||case when v_tax>0 then jsonb_build_array(jsonb_build_object('account_code','2200','debit_cents',0,'credit_cents',v_tax,'counterparty',p_counterparty->>'legal_name')) else '[]'::jsonb end,p_idempotency_key,v_hash,v_actor,null);
  v_journal_id:=(v_journal#>>'{entry,id}')::uuid;v_snapshot:=jsonb_build_object('issuer',app.platform_document_issuer_v147(v_policy),'number',v_number,'transaction_reference',v_reference,'issue_date',p_issue_date,'due_date',p_due_date,'counterparty',p_counterparty,'line_items',p_line_items,'subtotal_cents',v_subtotal,'tax_cents',v_tax,'total_cents',v_total,'currency','SGD');
  insert into public.platform_financial_documents_v147(id,document_type,document_number,issue_date,due_date,counterparty,line_items,subtotal_cents,tax_cents,total_cents,source_type,source_id,journal_entry,snapshot,snapshot_sha256,operation_key,request_hash,created_by)
  values(v_id,'invoice',v_number,p_issue_date,p_due_date,p_counterparty,p_line_items,v_subtotal,v_tax,v_total,'generated_non_subscription_invoice',v_reference,v_journal_id,v_snapshot,encode(extensions.digest(v_snapshot::text,'sha256'),'hex'),p_idempotency_key,v_hash,v_actor) returning * into v_doc;
  return jsonb_build_object('document',to_jsonb(v_doc),'snapshot',v_snapshot,'replayed',false);
end
$_$;

--
-- Name: platform_create_manual_invoice_v156(uuid, date, date, date, date, jsonb, bigint, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_create_manual_invoice_v156(p_business uuid, p_issue_date date, p_due_date date, p_service_start date, p_service_end date, p_line_items jsonb, p_discount_cents bigint, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'extensions', 'pg_temp'
    AS $$
declare v_actor uuid:=auth.uid();v_profile public.platform_billing_profiles_v156%rowtype;v_customer jsonb;v_doc public.platform_subscription_documents_v156%rowtype;v_subtotal bigint;v_tax bigint;v_total bigint;v_number text;v_snapshot jsonb;v_hash text;v_to text[];v_cc text[];
begin
  if v_actor is null or not app.v156_can('rw') then raise exception 'billing write access is required' using errcode='42501';end if;
  if p_business is null or p_due_date<p_issue_date or p_service_end<p_service_start or jsonb_typeof(p_line_items)<>'array' or jsonb_array_length(p_line_items)=0 or coalesce(p_discount_cents,0)<0 then raise exception 'valid manual invoice terms are required' using errcode='22023';end if;
  select * into v_profile from public.platform_billing_profiles_v156 order by version desc limit 1;if not app.v156_profile_ready(v_profile) then raise exception 'seller legal, GST and payment settings are incomplete' using errcode='22023';end if;
  v_customer:=app.v156_customer_snapshot(p_business,null);if v_customer is null then raise exception 'primary billing contact is required' using errcode='22023';end if;
  v_subtotal:=coalesce((select sum((line->>'quantity')::numeric*(line->>'unit_amount_cents')::bigint) from jsonb_array_elements(p_line_items) line),0);
  v_tax:=case when v_profile.gst_status='registered' then round((v_subtotal-coalesce(p_discount_cents,0))*v_profile.gst_rate_bps::numeric/10000) else 0 end;v_total:=v_subtotal-coalesce(p_discount_cents,0)+v_tax;
  if v_total<=0 then raise exception 'manual invoice total must be positive' using errcode='22023';end if;
  v_hash:=encode(extensions.digest(jsonb_build_object('business',p_business,'issue',p_issue_date,'due',p_due_date,'service_start',p_service_start,'service_end',p_service_end,'lines',p_line_items,'discount',p_discount_cents)::text,'sha256'),'hex');
  select * into v_doc from public.platform_subscription_documents_v156 where operation_key=p_idempotency_key;
  if found then if v_doc.request_hash<>v_hash then raise exception 'idempotency key conflict' using errcode='22023';end if;return jsonb_build_object('document',to_jsonb(v_doc),'replayed',true);end if;
  v_number:=app.v156_next_document_number('invoice',p_issue_date);
  v_snapshot:=jsonb_build_object('document_type','invoice','number',v_number,'issue_date',p_issue_date,'due_date',p_due_date,'service_period_start',p_service_start,'service_period_end',p_service_end,'seller',app.v156_seller_snapshot(v_profile),'customer',v_customer,'line_items',p_line_items,'discount_cents',coalesce(p_discount_cents,0),'subtotal_cents',v_subtotal,'tax_cents',v_tax,'total_cents',v_total,'amount_paid_cents',0,'balance_due_cents',v_total,'currency','SGD','payment_status','open','payment_method','bank_transfer');
  insert into public.platform_subscription_documents_v156(document_type,document_number,business_id,seller_profile_id,issue_date,due_date,service_period_start,service_period_end,subtotal_cents,discount_cents,tax_cents,total_cents,balance_due_cents,snapshot,snapshot_sha256,finalized_at,operation_key,request_hash,created_by)
  values('invoice',v_number,p_business,v_profile.id,p_issue_date,p_due_date,p_service_start,p_service_end,v_subtotal,coalesce(p_discount_cents,0),v_tax,v_total,v_total,v_snapshot,encode(extensions.digest(v_snapshot::text,'sha256'),'hex'),clock_timestamp(),p_idempotency_key,v_hash,v_actor) returning * into v_doc;
  insert into public.platform_subscription_document_events_v156(document_id,status,source_type,source_id,actor) values(v_doc.id,'open','admin',p_idempotency_key::text,v_actor);
  select array_agg(email order by email) filter(where recipient_role='primary'),array_agg(email order by recipient_role,email) filter(where recipient_role<>'primary') into v_to,v_cc from public.platform_billing_contacts_v156 where active and business_id=p_business;
  if v_profile.internal_copy_email is not null then select array_agg(distinct address) into v_cc from unnest(coalesce(v_cc,'{}'::text[])||array[v_profile.internal_copy_email]) address where not(address=any(v_to));end if;
  insert into public.platform_subscription_deliveries_v156(delivery_key,business_id,delivery_type,document_ids,recipients,cc_recipients,subject)
  values('manual-invoice:'||v_doc.id,p_business,'manual_invoice',array[v_doc.id],v_to,coalesce(v_cc,'{}'),'Peekaa invoice '||v_number||' for '||(v_customer->>'business_display_name'));
  insert into public.platform_subscription_dispatch_audit_v156(action,entity_type,entity_id,detail,actor) values('manual_invoice_finalized','document',v_doc.id,jsonb_build_object('document_number',v_number),v_actor);
  return jsonb_build_object('document',to_jsonb(v_doc),'replayed',false);
end $$;

--
-- Name: platform_create_my_prospect_task_v89(uuid, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_create_my_prospect_task_v89(p_prospect uuid, p_title text, p_due_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_id uuid;v_title text:=nullif(btrim(p_title),'');
begin
  if not app.v89_platform_can('onboarding','rw')
     or not app.v89_can_access_prospect(p_prospect) then
    raise exception 'scoped onboarding write access is required' using errcode='42501';
  end if;
  if length(coalesce(v_title,'')) not between 2 and 240 or p_due_at<=now() then
    raise exception 'invalid prospect task' using errcode='22023';
  end if;
  insert into public.sme_prospect_tasks(
    prospect_id,title,due_at,assigned_consultant_id,created_by
  ) values(
    p_prospect,v_title,p_due_at,app.v89_sales_consultant_id(),auth.uid()
  ) returning id into v_id;
  return jsonb_build_object('task_id',v_id,'prospect_id',p_prospect,
    'status','open');
end
$$;

--
-- Name: platform_create_my_prospect_v89(text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_create_my_prospect_v89(p_company_name text, p_sector_key text DEFAULT NULL::text, p_phone text DEFAULT NULL::text, p_email text DEFAULT NULL::text, p_contact_name text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $_$
declare
  v_name text:=nullif(btrim(p_company_name),'');
  v_sector text:=nullif(btrim(p_sector_key),'');
  v_phone text:=nullif(btrim(p_phone),'');
  v_email text:=nullif(lower(btrim(p_email)),'');
  v_contact text:=nullif(btrim(p_contact_name),'');
  v_company uuid;v_prospect uuid;v_consultant uuid;
begin
  if not app.v89_platform_can('onboarding','rw') then
    raise exception 'platform onboarding write access is required' using errcode='42501';
  end if;
  if length(coalesce(v_name,'')) not between 2 and 200
     or (v_phone is null and v_email is null) then
    raise exception 'company name and a phone or email are required' using errcode='22023';
  end if;
  if v_email is not null and v_email!~'^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' then
    raise exception 'invalid company email' using errcode='22023';
  end if;
  if v_sector is not null and not exists(
    select 1 from public.sector_profiles profile where profile.sector_key=v_sector
  ) then
    raise exception 'unknown sector' using errcode='22023';
  end if;
  if app.v89_platform_role()='sales_staff' then
    v_consultant:=app.v89_sales_consultant_id();
    if v_consultant is null then
      raise exception 'active sales consultant profile is required' using errcode='42501';
    end if;
  end if;
  insert into public.sme_companies(
    trading_name,sector_key,phone,email
  ) values(v_name,v_sector,v_phone,v_email)
  returning id into v_company;
  insert into public.sme_prospects(
    company_id,current_stage_key,assigned_consultant_id,created_by,updated_by
  ) values(v_company,'new_lead',v_consultant,auth.uid(),auth.uid())
  returning id into v_prospect;
  if v_phone is not null or v_email is not null then
    insert into public.sme_prospect_contacts(
      prospect_id,full_name,email,phone,is_primary
    ) values(v_prospect,coalesce(v_contact,v_name),v_email,v_phone,true);
  end if;
  insert into public.sme_prospect_stage_history(
    prospect_id,to_stage_key,reason_detail,actor
  ) values(v_prospect,'new_lead','created in scoped v89 platform console',auth.uid());
  if v_consultant is not null then
    insert into public.sme_prospect_assignments(
      prospect_id,consultant_id,assigned_by,reason
    ) values(v_prospect,v_consultant,auth.uid(),'self-created sales prospect');
  end if;
  insert into public.audit_log(
    business_id,actor,action,entity,entity_id,detail
  ) values(null,auth.uid(),'PLATFORM_CREATE_MY_PROSPECT_V89','sme_prospects',
    v_prospect,jsonb_build_object('company_id',v_company,'sector_key',v_sector,
      'assigned_consultant_id',v_consultant));
  return jsonb_build_object('prospect_id',v_prospect,'company_id',v_company,
    'stage_key','new_lead','version',1,'scope',
    case when app.v89_platform_role()='sales_staff'
      then 'own_created_or_assigned' else 'all' end);
end
$_$;

--
-- Name: platform_create_prospect_task_v76(uuid, text, timestamp with time zone, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_create_prospect_task_v76(p_prospect uuid, p_title text, p_due_at timestamp with time zone, p_assigned_consultant uuid, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_actor uuid:=auth.uid();v_hash text;v_replay jsonb;v_id uuid;v_response jsonb;
begin
  if not app.is_platform_operator_v75() then raise exception 'platform operator access is required' using errcode='42501';end if;
  if not exists(select 1 from public.sme_prospects where id=p_prospect) then raise exception 'prospect was not found' using errcode='22023';end if;
  if p_assigned_consultant is not null and not exists(select 1 from public.platform_consultants where id=p_assigned_consultant and active) then
    raise exception 'active consultant was not found' using errcode='22023';end if;
  v_hash:=app.v76_sha256_hex(jsonb_build_object('prospect',p_prospect,'title',p_title,'due',p_due_at,'consultant',p_assigned_consultant)::text);
  v_replay:=app.v76_replay(v_actor,'create_task',p_idempotency_key,v_hash);if v_replay is not null then return v_replay;end if;
  insert into public.sme_prospect_tasks(prospect_id,title,due_at,assigned_consultant_id,created_by)
  values(p_prospect,btrim(p_title),p_due_at,p_assigned_consultant,v_actor) returning id into v_id;
  insert into public.audit_log(business_id,actor,action,entity,entity_id,detail)
  values(null,v_actor,'SME_PROSPECT_TASK_CREATED_V76','sme_prospect_tasks',v_id,
    jsonb_build_object('prospect_id',p_prospect,'due_at',p_due_at));
  v_response:=jsonb_build_object('replayed',false,'task',(select to_jsonb(t) from public.sme_prospect_tasks t where id=v_id));
  perform app.v76_store_receipt(v_actor,'create_task',p_idempotency_key,v_hash,v_response);return v_response;
end
$$;

--
-- Name: platform_create_prospect_v76(jsonb, jsonb, text, uuid, jsonb, text[], text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_create_prospect_v76(p_company jsonb, p_primary_contact jsonb, p_stage_key text DEFAULT 'new_lead'::text, p_consultant uuid DEFAULT NULL::uuid, p_source jsonb DEFAULT '{}'::jsonb, p_tags text[] DEFAULT '{}'::text[], p_idempotency_key text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid:=auth.uid(); v_hash text; v_replay jsonb; v_company uuid; v_prospect uuid;
  v_response jsonb; v_source jsonb:=coalesce(p_source,'{}');
begin
  if not app.is_platform_operator_v75() then
    raise exception 'platform operator access is required' using errcode='42501';
  end if;
  if jsonb_typeof(p_company)<>'object' or jsonb_typeof(v_source)<>'object' then
    raise exception 'company and source must be objects' using errcode='22023';
  end if;
  if p_primary_contact is not null and jsonb_typeof(p_primary_contact)<>'object' then
    raise exception 'primary contact must be an object or null' using errcode='22023';
  end if;
  if not exists(select 1 from public.sme_pipeline_stages where stage_key=p_stage_key) then
    raise exception 'unknown SME stage' using errcode='22023';
  end if;
  if p_stage_key in ('account_created','onboarding','activated') then
    raise exception 'this SME stage is system-managed and requires conversion evidence'
      using errcode='42501';
  end if;
  if p_consultant is not null and not exists(
    select 1 from public.platform_consultants where id=p_consultant and active
  ) then raise exception 'active consultant was not found' using errcode='22023'; end if;
  v_hash:=app.v76_sha256_hex(jsonb_build_object('company',p_company,'contact',p_primary_contact,
    'stage',p_stage_key,'consultant',p_consultant,'source',v_source,'tags',p_tags)::text);
  v_replay:=app.v76_replay(v_actor,'create_prospect',p_idempotency_key,v_hash);
  if v_replay is not null then return v_replay; end if;
  insert into public.sme_companies(
    legal_name,trading_name,registration_number,industry,sector_key,website,phone,email,address
  ) values (
    nullif(btrim(p_company->>'legal_name'),''),nullif(btrim(p_company->>'trading_name'),''),
    nullif(btrim(p_company->>'registration_number'),''),nullif(btrim(p_company->>'industry'),''),
    nullif(btrim(p_company->>'sector_key'),''),nullif(btrim(p_company->>'website'),''),
    nullif(btrim(p_company->>'phone'),''),nullif(btrim(p_company->>'email'),''),
    coalesce(p_company->'address','{}'::jsonb)
  ) returning id into v_company;
  insert into public.sme_prospects(
    company_id,current_stage_key,assigned_consultant_id,created_by,updated_by
  ) values(v_company,p_stage_key,p_consultant,v_actor,v_actor) returning id into v_prospect;
  if p_primary_contact is not null and jsonb_typeof(p_primary_contact)='object' then
    insert into public.sme_prospect_contacts(prospect_id,full_name,title,email,phone,is_primary)
    values(v_prospect,btrim(p_primary_contact->>'full_name'),nullif(btrim(p_primary_contact->>'title'),''),
      nullif(btrim(p_primary_contact->>'email'),''),nullif(btrim(p_primary_contact->>'phone'),''),true);
  end if;
  insert into public.sme_prospect_stage_history(prospect_id,to_stage_key,actor)
  values(v_prospect,p_stage_key,v_actor);
  if p_consultant is not null then
    insert into public.sme_prospect_assignments(prospect_id,consultant_id,assigned_by,reason)
    values(v_prospect,p_consultant,v_actor,'prospect creation');
  end if;
  insert into public.sme_prospect_source_lineage(
    prospect_id,source_system,source_type,external_id,detail,created_by
  ) values(v_prospect,coalesce(nullif(v_source->>'source_system',''),'manual'),
    coalesce(nullif(v_source->>'source_type',''),'manual'),nullif(v_source->>'external_id',''),
    v_source-'source_system'-'source_type'-'external_id',v_actor);
  perform app.v76_set_tags(v_prospect,p_tags);
  insert into public.audit_log(business_id,actor,action,entity,entity_id,detail)
  values(null,v_actor,'SME_PROSPECT_CREATED_V76','sme_prospects',v_prospect,
    jsonb_build_object('stage',p_stage_key,'consultant_id',p_consultant));
  v_response:=jsonb_build_object('replayed',false,'prospect',app.sme_prospect_card_v76(v_prospect));
  perform app.v76_store_receipt(v_actor,'create_prospect',p_idempotency_key,v_hash,v_response);
  return v_response;
end
$$;

--
-- Name: platform_create_sector_bundle_v75(text, text, text[], boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_create_sector_bundle_v75(p_sector_key text, p_label text, p_modules text[], p_dry_run boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid(); v_resolved text[]; v_next integer; v_id uuid;
begin
  if not app.is_super_admin() then
    raise exception 'super admin access is required' using errcode = '42501';
  end if;
  perform 1 from public.sector_profiles
   where sector_key = p_sector_key and active for update;
  if not found then raise exception 'active sector profile was not found' using errcode = '22023'; end if;
  if length(btrim(coalesce(p_label, ''))) < 2 then
    raise exception 'bundle label is required' using errcode = '22023';
  end if;
  v_resolved := app.resolve_module_dependencies(coalesce(p_modules, '{}'::text[]));
  select coalesce(max(version), 0) + 1 into v_next
    from public.sector_bundle_versions where sector_key = p_sector_key;
  if not coalesce(p_dry_run, true) then
    insert into public.sector_bundle_versions(
      sector_key, version, label, modules, created_by
    ) values (p_sector_key, v_next, btrim(p_label), v_resolved, v_actor)
    returning id into v_id;
    insert into public.audit_log(business_id, actor, action, entity, entity_id, detail)
    values (null, v_actor, 'SECTOR_BUNDLE_CREATED_V75', 'sector_bundle_versions',
            v_id, jsonb_build_object('sector_key',p_sector_key,'version',v_next,'modules',v_resolved));
  end if;
  return jsonb_build_object(
    'dry_run', coalesce(p_dry_run, true), 'sector_key', p_sector_key,
    'next_version', v_next, 'label', btrim(p_label),
    'requested_modules', to_jsonb(coalesce(p_modules, '{}'::text[])),
    'resolved_modules', to_jsonb(v_resolved), 'bundle_version_id', v_id,
    'status', 'draft'
  );
end
$$;

--
-- Name: platform_crm_delete_filter_v297(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_crm_delete_filter_v297(p_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_n integer;
begin
  perform app.v297_assert_prospecting('r');
  delete from public.sme_saved_filters where id=p_id and user_id=auth.uid();
  get diagnostics v_n = row_count;
  return jsonb_build_object('deleted',v_n);
end $$;

--
-- Name: platform_crm_ingest_discovered_v297(jsonb, jsonb, boolean, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_crm_ingest_discovered_v297(p_places jsonb, p_request jsonb DEFAULT '{}'::jsonb, p_commit boolean DEFAULT false, p_search_calls integer DEFAULT 0, p_detail_calls integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_place jsonb; v_run uuid; v_company uuid; v_prospect uuid; v_category uuid;
  v_found integer := 0; v_new integer := 0; v_existing integer := 0;
  v_source text; v_source_id text; v_name text; v_geo_source text;
begin
  perform app.v297_assert_prospecting('rw');
  if not (app.is_super_admin() or app.v89_platform_role()='admin') then
    raise exception 'business_import_requires_admin' using errcode='42501';
  end if;
  if jsonb_typeof(coalesce(p_places,'null'::jsonb)) <> 'array' then
    raise exception 'places_payload_must_be_an_array' using errcode='22023';
  end if;

  insert into public.sme_discovery_runs(provider, request, status, search_calls, detail_calls, created_by)
  values (coalesce(p_request->>'provider','google_places'), coalesce(p_request,'{}'::jsonb),
          case when p_commit then 'importing' else 'preview' end,
          greatest(coalesce(p_search_calls,0),0), greatest(coalesce(p_detail_calls,0),0), auth.uid())
  returning id into v_run;

  for v_place in select * from jsonb_array_elements(p_places) loop
    v_found := v_found + 1;
    v_source := coalesce(nullif(btrim(v_place->>'source'),''),'google_places');
    v_source_id := nullif(btrim(v_place->>'source_id'),'');
    v_name := nullif(btrim(v_place->>'name'),'');
    v_geo_source := case when coalesce(v_place->>'geo_source','') = 'onemap'
                         then 'onemap' else 'google_places' end;
    if v_source_id is null or v_name is null then continue; end if;

    select company_id into v_company from public.sme_company_sources
     where source=v_source and source_id=v_source_id;

    if v_company is not null then
      v_existing := v_existing + 1;
      if p_commit then
        insert into public.sme_company_market_facts(
          company_id,business_status,rating,review_count,price_level,
          provider_phone,provider_website,last_synced_at,updated_at)
        values (v_company, v_place->>'business_status',
                nullif(v_place->>'rating','')::numeric, nullif(v_place->>'review_count','')::integer,
                nullif(v_place->>'price_level','')::smallint,
                v_place->>'phone', v_place->>'website', now(), now())
        on conflict (company_id) do update set
          business_status=coalesce(excluded.business_status,public.sme_company_market_facts.business_status),
          rating=coalesce(excluded.rating,public.sme_company_market_facts.rating),
          review_count=coalesce(excluded.review_count,public.sme_company_market_facts.review_count),
          price_level=coalesce(excluded.price_level,public.sme_company_market_facts.price_level),
          provider_phone=coalesce(excluded.provider_phone,public.sme_company_market_facts.provider_phone),
          provider_website=coalesce(excluded.provider_website,public.sme_company_market_facts.provider_website),
          last_synced_at=now(), updated_at=now();
        -- Refresh the retention window on the primary location too — but NEVER
        -- overwrite a manually-verified location (first-party beats provider).
        update public.sme_company_locations l
           set latitude=coalesce(nullif(v_place->>'latitude','')::double precision, l.latitude),
               longitude=coalesce(nullif(v_place->>'longitude','')::double precision, l.longitude),
               address=coalesce(nullif(v_place->>'address',''), l.address),
               postal_code=coalesce(nullif(v_place->>'postal_code',''), l.postal_code),
               geo_source=v_geo_source, geo_synced_at=now(), updated_at=now()
         where l.company_id=v_company and l.is_primary and l.geo_source <> 'manual';
        update public.sme_company_sources set last_synced_at=now()
         where source=v_source and source_id=v_source_id;
      end if;
      continue;
    end if;

    v_new := v_new + 1;
    if not p_commit then continue; end if;

    insert into public.sme_companies(legal_name, trading_name, phone, website)
    values (v_name, v_name, nullif(v_place->>'phone',''), nullif(v_place->>'website',''))
    returning id into v_company;

    insert into public.sme_company_sources(company_id,source,source_id,source_url,detail_fetched_at)
    values (v_company, v_source, v_source_id, nullif(v_place->>'source_url',''),
            case when (v_place ? 'rating') then now() end);

    insert into public.sme_company_locations(
      company_id,country,planning_area,district,address,postal_code,latitude,longitude,
      is_primary,geo_source,geo_synced_at)
    values (v_company, coalesce(nullif(v_place->>'country',''),'SG'),
            nullif(v_place->>'planning_area',''), nullif(v_place->>'district',''),
            nullif(v_place->>'address',''), nullif(v_place->>'postal_code',''),
            nullif(v_place->>'latitude','')::double precision,
            nullif(v_place->>'longitude','')::double precision, true,
            v_geo_source, now());

    insert into public.sme_company_market_facts(
      company_id,business_status,rating,review_count,price_level,
      provider_phone,provider_website,last_synced_at)
    values (v_company, v_place->>'business_status',
            nullif(v_place->>'rating','')::numeric, nullif(v_place->>'review_count','')::integer,
            nullif(v_place->>'price_level','')::smallint,
            v_place->>'phone', v_place->>'website', now());

    if nullif(v_place->>'category_key','') is not null then
      select id into v_category from public.sme_categories where category_key=v_place->>'category_key';
      if v_category is not null then
        insert into public.sme_company_categories(company_id,category_id,is_primary)
        values (v_company,v_category,true) on conflict do nothing;
      end if;
    end if;

    insert into public.sme_prospects(company_id,current_stage_key,created_by,updated_by)
    values (v_company,'new_lead',auth.uid(),auth.uid())
    returning id into v_prospect;
    perform app.v297_refresh_lead_score(v_prospect);
  end loop;

  update public.sme_discovery_runs
     set found_count=v_found, new_count=v_new, existing_count=v_existing,
         status=case when p_commit then 'completed' else 'preview' end,
         completed_at=now()
   where id=v_run;

  return jsonb_build_object('run_id',v_run,'committed',p_commit,
    'found',v_found,'new',v_new,'existing',v_existing,'duplicates',v_found-v_new-v_existing);
end $$;

--
-- Name: platform_crm_log_outreach_v297(uuid, text, text, text, uuid, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_crm_log_outreach_v297(p_prospect uuid, p_channel text, p_outcome text, p_notes text DEFAULT NULL::text, p_contact uuid DEFAULT NULL::uuid, p_next_follow_up_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_idempotency_key text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_self uuid; v_scoped boolean; v_assigned uuid; v_id uuid; v_existing uuid;
begin
  perform app.v297_assert_prospecting('rw');
  v_scoped := app.v89_platform_role()='sales_staff' and not app.is_super_admin();
  v_self := app.v226_self_consultant();
  select assigned_consultant_id into v_assigned from public.sme_prospects where id=p_prospect;
  if not found then raise exception 'prospect_not_found' using errcode='22023'; end if;
  if v_scoped and v_assigned is distinct from v_self then
    raise exception 'prospect_outside_your_book' using errcode='42501';
  end if;
  if p_outcome='follow_up' and p_next_follow_up_at is null then
    raise exception 'follow_up_requires_a_date' using errcode='22023';
  end if;
  if p_next_follow_up_at is not null and p_next_follow_up_at < now() - interval '1 day' then
    raise exception 'follow_up_cannot_be_in_the_past' using errcode='22023';
  end if;

  -- A double-tap on Log contact must not create two records.
  if p_idempotency_key is not null then
    select id into v_existing from public.sme_outreach_records
     where prospect_id=p_prospect and created_by=auth.uid()
       and notes is not distinct from p_notes and channel=p_channel and outcome=p_outcome
       and created_at > now() - interval '2 minutes' limit 1;
    if found then return jsonb_build_object('outreach_id',v_existing,'replayed',true); end if;
  end if;

  insert into public.sme_outreach_records(
    prospect_id, contact_id, consultant_id, channel, outcome, notes,
    next_follow_up_at, created_by)
  values (p_prospect, p_contact, coalesce(v_self, v_assigned), p_channel, p_outcome,
          nullif(btrim(coalesce(p_notes,'')),''), p_next_follow_up_at, auth.uid())
  returning id into v_id;

  if p_next_follow_up_at is not null then
    insert into public.sme_prospect_tasks(
      prospect_id, title, due_at, assigned_consultant_id, status, created_by)
    values (p_prospect, 'Follow up: '||p_outcome, p_next_follow_up_at,
            coalesce(v_self, v_assigned), 'open', auth.uid());
    update public.sme_prospects set next_action_at=p_next_follow_up_at, updated_at=now()
     where id=p_prospect;
  end if;

  perform app.v297_refresh_lead_score(p_prospect);
  insert into public.audit_log(business_id, actor, action, entity, entity_id, detail)
  values (null, auth.uid(), 'CRM_OUTREACH_LOGGED_V297','sme_prospects',p_prospect,
          jsonb_build_object('channel',p_channel,'outcome',p_outcome,
                             'follow_up',p_next_follow_up_at));
  return jsonb_build_object('outreach_id',v_id,'replayed',false,
    'lead_score',(select score from public.sme_lead_scores where prospect_id=p_prospect));
end $$;

--
-- Name: platform_crm_pipeline_v226(text, text, uuid, integer, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_crm_pipeline_v226(p_search text DEFAULT NULL::text, p_stage text DEFAULT NULL::text, p_consultant uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 100, p_before timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_limit integer := least(greatest(coalesce(p_limit,100),1),250);
  v_role text := app.v89_platform_role();
  v_scope text;
  v_self uuid;
  v_filter uuid;
  v_unlinked boolean := false;
  v_items jsonb; v_before timestamptz; v_total bigint;
begin
  if auth.uid() is null or v_role is null then
    raise exception 'platform access is required' using errcode='42501';
  end if;
  if not app.v89_platform_can('onboarding','r') then
    raise exception 'CRM access is required' using errcode='42501';
  end if;
  if p_stage is not null and p_stage <> 'unmapped'
     and not exists(select 1 from public.sme_pipeline_stages where stage_key = p_stage) then
    raise exception 'unknown SME stage' using errcode='22023';
  end if;

  if v_role = 'sales_staff' then
    v_scope := 'own';
    v_self := app.v226_self_consultant();
    if p_consultant is not null and p_consultant is distinct from v_self then
      raise exception 'a consultant may only read their own assigned firms'
        using errcode='42501';
    end if;
    v_filter := v_self;
    v_unlinked := v_self is null;
  else
    v_scope := 'all';
    v_filter := p_consultant;
  end if;

  if v_scope = 'own' and v_unlinked then
    return jsonb_build_object(
      'items','[]'::jsonb,'next_before',null,'total_count',0,
      'scope',v_scope,'role',v_role,'consultant',null,
      'consultant_unlinked',true,
      'stages',(select coalesce(jsonb_agg(jsonb_build_object(
          'stage_key',stage_key,'n',0) order by sort_order),'[]'::jsonb)
        from public.sme_pipeline_stages),
      'consultants','[]'::jsonb);
  end if;

  with scoped as (
    select prospect.id, prospect.updated_at, prospect.current_stage_key
      from public.sme_prospects prospect
      join public.sme_companies company on company.id = prospect.company_id
     where prospect.archived_at is null
       and (v_filter is null or prospect.assigned_consultant_id = v_filter)
       and app.sme_prospect_search_match_v76(prospect.id, p_search)
  ), staged as (
    select * from scoped
     where (p_stage is null
            or (p_stage = 'unmapped' and current_stage_key is null)
            or current_stage_key = p_stage)
  ), page as (
    select * from staged
     where (p_before is null or updated_at < p_before)
     order by updated_at desc
     limit v_limit
  )
  select
    coalesce((select jsonb_agg(
       app.sme_prospect_card_v76(page.id) || jsonb_build_object(
         -- Same rule as platform_request_ai_firm_report_v176: converted, and
         -- neither demo nor synthetic. A demo firm asking for a report is
         -- refused there with 22023, so it must not be offered here.
         'can_request_ai_report',
         (select business.id is not null
                 and not coalesce(business.is_demo,false)
                 and not coalesce(business.is_synthetic,false)
            from public.sme_prospects prospect
            left join public.businesses business
              on business.id = prospect.converted_business_id
           where prospect.id = page.id))
       order by page.updated_at desc) from page),'[]'::jsonb),
    (select min(updated_at) from page),
    (select count(*) from staged)
  into v_items, v_before, v_total;

  return jsonb_build_object(
    'items', v_items,
    'next_before', v_before,
    'total_count', v_total,
    'has_more', v_total > jsonb_array_length(v_items),
    'scope', v_scope,
    'role', v_role,
    'consultant', v_filter,
    'consultant_unlinked', false,
    'stages', coalesce((select jsonb_agg(jsonb_build_object(
        'stage_key', stage.stage_key, 'label', stage.label,
        'n', (select count(*) from public.sme_prospects prospect
               where prospect.archived_at is null
                 and prospect.current_stage_key = stage.stage_key
                 and (v_filter is null or prospect.assigned_consultant_id = v_filter)
                 and app.sme_prospect_search_match_v76(prospect.id, p_search)))
        order by stage.sort_order) from public.sme_pipeline_stages stage),'[]'::jsonb),
    'consultants', case when v_scope = 'all' then coalesce((
        select jsonb_agg(jsonb_build_object(
          'id', consultant.id,'display_name', consultant.display_name,
          'n', (select count(*) from public.sme_prospects prospect
                 where prospect.archived_at is null
                   and prospect.assigned_consultant_id = consultant.id))
          order by consultant.display_name)
        from public.platform_consultants consultant
       where consultant.active),'[]'::jsonb)
      else '[]'::jsonb end);
end $$;

--
-- Name: platform_crm_prospecting_detail_v297(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_crm_prospecting_detail_v297(p_prospect uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_row record; v_scoped boolean; v_self uuid;
begin
  perform app.v297_assert_prospecting('r');
  v_scoped := app.v89_platform_role()='sales_staff' and not app.is_super_admin();
  v_self := app.v226_self_consultant();
  select p.*, c.legal_name, c.trading_name, c.phone, c.website, c.email, c.registration_number
    into v_row
    from public.sme_prospects p join public.sme_companies c on c.id=p.company_id
   where p.id=p_prospect;
  if not found then raise exception 'prospect_not_found' using errcode='22023'; end if;
  if v_scoped and v_row.assigned_consultant_id is distinct from v_self then
    raise exception 'prospect_outside_your_book' using errcode='42501';
  end if;

  return jsonb_build_object(
    'prospect', jsonb_build_object(
      'id',v_row.id,'stage_key',v_row.current_stage_key,'version',v_row.version,
      'assigned_consultant_id',v_row.assigned_consultant_id,
      'converted_business_id',v_row.converted_business_id,'converted_at',v_row.converted_at,
      'next_action_at',v_row.next_action_at),
    'business', jsonb_build_object(
      'company_id',v_row.company_id,
      'name',coalesce(nullif(btrim(v_row.trading_name),''),v_row.legal_name),
      'legal_name',v_row.legal_name,'phone',v_row.phone,'website',v_row.website,
      'email',v_row.email,'registration_number',v_row.registration_number),
    'location', coalesce((select to_jsonb(l) from public.sme_company_locations l
                           where l.company_id=v_row.company_id and l.is_primary),'{}'::jsonb),
    'market', coalesce((select to_jsonb(f) from public.sme_company_market_facts f
                         where f.company_id=v_row.company_id),'{}'::jsonb),
    'sources', coalesce((select jsonb_agg(jsonb_build_object(
        'source',s.source,'source_id',s.source_id,'source_url',s.source_url,
        'last_synced_at',s.last_synced_at) order by s.last_synced_at desc)
      from public.sme_company_sources s where s.company_id=v_row.company_id),'[]'::jsonb),
    'categories', coalesce((select jsonb_agg(jsonb_build_object(
        'key',cat.category_key,'label',cat.label,'sector',sec.sector_key,'primary',cc.is_primary))
      from public.sme_company_categories cc
      join public.sme_categories cat on cat.id=cc.category_id
      join public.sme_sectors sec on sec.id=cat.sector_id
      where cc.company_id=v_row.company_id),'[]'::jsonb),
    'contacts', coalesce((select jsonb_agg(jsonb_build_object(
        'id',ct.id,'name',ct.full_name,'role',ct.title,'phone',ct.phone,
        'whatsapp',ct.whatsapp_number,'email',ct.email,'type',ct.contact_type,
        'is_primary',ct.is_primary) order by ct.is_primary desc, ct.full_name)
      from public.sme_prospect_contacts ct
      where ct.prospect_id=p_prospect and ct.active),'[]'::jsonb),
    'outreach', coalesce((select jsonb_agg(jsonb_build_object(
        'id',r.id,'channel',r.channel,'outcome',r.outcome,'notes',r.notes,
        'contacted_at',r.contacted_at,'next_follow_up_at',r.next_follow_up_at,
        'consultant',k.display_name) order by r.contacted_at desc)
      from public.sme_outreach_records r
      left join public.platform_consultants k on k.id=r.consultant_id
      where r.prospect_id=p_prospect),'[]'::jsonb),
    'lead_score', coalesce((select jsonb_build_object('score',sc.score,
        'breakdown',sc.score_breakdown,'computed_at',sc.computed_at)
      from public.sme_lead_scores sc where sc.prospect_id=p_prospect),
      app.v297_lead_score(p_prospect)),
    'can_write', app.v297_can_prospecting('rw'),
    'can_assign', app.is_super_admin()
  );
end $$;

--
-- Name: platform_crm_prospecting_search_v297(jsonb, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_crm_prospecting_search_v297(p_filters jsonb DEFAULT '{}'::jsonb, p_mode text DEFAULT 'list'::text, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_self uuid; v_scoped boolean; v_result jsonb; v_marker_cap integer := 2000;
  v_q text; v_lat double precision; v_lng double precision; v_km double precision;
begin
  perform app.v297_assert_prospecting('r');
  if p_mode not in ('list','markers') then
    raise exception 'invalid_search_mode' using errcode='22023';
  end if;
  if p_limit is null or p_limit not between 1 and 200 then
    raise exception 'invalid_page_size' using errcode='22023';
  end if;
  if p_offset is null or p_offset < 0 then
    raise exception 'invalid_page_offset' using errcode='22023';
  end if;
  v_scoped := app.v89_platform_role()='sales_staff' and not app.is_super_admin();
  v_self := app.v226_self_consultant();
  v_q := nullif(btrim(coalesce(p_filters->>'q','')),'');
  v_lat := nullif(p_filters#>>'{radius,lat}','')::double precision;
  v_lng := nullif(p_filters#>>'{radius,lng}','')::double precision;
  v_km  := nullif(p_filters#>>'{radius,km}','')::double precision;

  with hits as (
    select p.id as prospect_id, c.id as company_id,
           coalesce(nullif(btrim(c.trading_name),''), c.legal_name) as name,
           p.current_stage_key as stage_key,
           l.planning_area, l.district, l.address, l.postal_code, l.latitude, l.longitude,
           f.rating, f.review_count, f.price_level, f.business_status,
           coalesce(nullif(btrim(c.phone),''), f.provider_phone) as phone,
           coalesce(nullif(btrim(c.website),''), f.provider_website) as website,
           c.email,
           coalesce(sc.score,0) as score, p.assigned_consultant_id,
           k.display_name as assigned_name, p.converted_business_id,
           o.contacted_at as last_contacted_at, o.outcome as last_outcome,
           o.next_follow_up_at,
           case when v_lat is not null and l.latitude is not null
                then round(app.v297_haversine_km(v_lat,v_lng,l.latitude,l.longitude)::numeric,2)
           end as distance_km
      from public.sme_prospects p
      join public.sme_companies c on c.id=p.company_id
      left join public.sme_company_locations l on l.company_id=c.id and l.is_primary
      left join public.sme_company_market_facts f on f.company_id=c.id
      left join public.sme_lead_scores sc on sc.prospect_id=p.id
      left join public.platform_consultants k on k.id=p.assigned_consultant_id
      left join lateral (
        select r.contacted_at, r.outcome, r.next_follow_up_at
          from public.sme_outreach_records r
         where r.prospect_id=p.id order by r.contacted_at desc limit 1) o on true
     where p.archived_at is null
       and (not v_scoped or p.assigned_consultant_id = v_self)
       and (v_q is null or c.legal_name ilike '%'||v_q||'%'
            or coalesce(c.trading_name,'') ilike '%'||v_q||'%'
            or coalesce(l.address,'') ilike '%'||v_q||'%')
       and (jsonb_array_length(coalesce(p_filters->'planning_areas','[]'::jsonb))=0
            or l.planning_area in (select jsonb_array_elements_text(p_filters->'planning_areas')))
       and (jsonb_array_length(coalesce(p_filters->'districts','[]'::jsonb))=0
            or l.district in (select jsonb_array_elements_text(p_filters->'districts')))
       and (nullif(p_filters->>'postal_prefix','') is null
            or coalesce(l.postal_code,'') like (p_filters->>'postal_prefix')||'%')
       and (p_filters->'bbox' is null or (
              l.latitude between (p_filters#>>'{bbox,south}')::double precision
                             and (p_filters#>>'{bbox,north}')::double precision
          and l.longitude between (p_filters#>>'{bbox,west}')::double precision
                              and (p_filters#>>'{bbox,east}')::double precision))
       -- Radius: indexed bounding-box prefilter first, exact haversine second.
       and (v_lat is null or v_km is null or (
              l.latitude between v_lat-(v_km/111.0) and v_lat+(v_km/111.0)
          and l.longitude between v_lng-(v_km/(111.0*cos(radians(v_lat))))
                              and v_lng+(v_km/(111.0*cos(radians(v_lat))))
          and app.v297_haversine_km(v_lat,v_lng,l.latitude,l.longitude) <= v_km))
       and (jsonb_array_length(coalesce(p_filters->'sectors','[]'::jsonb))=0
            or exists (select 1 from public.sme_company_categories cc
                         join public.sme_categories cat on cat.id=cc.category_id
                         join public.sme_sectors sec on sec.id=cat.sector_id
                        where cc.company_id=c.id
                          and sec.sector_key in (select jsonb_array_elements_text(p_filters->'sectors'))))
       and (jsonb_array_length(coalesce(p_filters->'categories','[]'::jsonb))=0
            or exists (select 1 from public.sme_company_categories cc
                         join public.sme_categories cat on cat.id=cc.category_id
                        where cc.company_id=c.id
                          and cat.category_key in (select jsonb_array_elements_text(p_filters->'categories'))))
       and (nullif(p_filters->>'rating_min','') is null
            or coalesce(f.rating,0) >= (p_filters->>'rating_min')::numeric)
       and (nullif(p_filters->>'review_min','') is null
            or coalesce(f.review_count,0) >= (p_filters->>'review_min')::integer)
       and (nullif(p_filters->>'business_status','') is null
            or coalesce(f.business_status,'OPERATIONAL') = p_filters->>'business_status')
       and (jsonb_array_length(coalesce(p_filters->'price_levels','[]'::jsonb))=0
            or f.price_level::text in (select jsonb_array_elements_text(p_filters->'price_levels')))
       and (coalesce((p_filters->>'has_phone')::boolean,false)=false
            or coalesce(nullif(btrim(c.phone),''), f.provider_phone) is not null)
       and (coalesce((p_filters->>'has_website')::boolean,false)=false
            or coalesce(nullif(btrim(c.website),''), f.provider_website) is not null)
       and (coalesce((p_filters->>'has_email')::boolean,false)=false
            or nullif(btrim(coalesce(c.email,'')),'') is not null)
       and (coalesce((p_filters->>'has_whatsapp')::boolean,false)=false
            or exists (select 1 from public.sme_prospect_contacts ct
                        where ct.prospect_id=p.id and ct.active
                          and nullif(btrim(coalesce(ct.whatsapp_number,'')),'') is not null))
       and (nullif(p_filters->>'outreach','') is null or (
             case p_filters->>'outreach'
               when 'not_contacted' then o.contacted_at is null
               when 'contacted' then o.contacted_at is not null
               when 'follow_up' then o.outcome='follow_up'
               when 'interested' then o.outcome='interested'
               when 'not_interested' then o.outcome='not_interested'
               when 'do_not_contact' then o.outcome='do_not_contact'
               when 'converted' then p.converted_business_id is not null
               else true end))
       and (nullif(p_filters->>'contacted_within_days','') is null
            or o.contacted_at >= now() - ((p_filters->>'contacted_within_days')||' days')::interval)
       and (nullif(p_filters->>'follow_up','') is null or (
             case p_filters->>'follow_up'
               when 'due_today' then o.next_follow_up_at is not null
                 and (o.next_follow_up_at at time zone 'Asia/Singapore')::date
                     <= (now() at time zone 'Asia/Singapore')::date
               when 'overdue' then o.next_follow_up_at is not null and o.next_follow_up_at < now()
               else true end))
       and (nullif(p_filters->>'assigned_to','') is null
            or (p_filters->>'assigned_to'='unassigned' and p.assigned_consultant_id is null)
            or p.assigned_consultant_id::text = p_filters->>'assigned_to')
       and (nullif(p_filters->>'merchant_status','') is null or (
             case p_filters->>'merchant_status'
               when 'not_merchant' then p.converted_business_id is null
               when 'active' then p.converted_business_id is not null
               when 'onboarding' then p.current_stage_key in ('account_created','onboarding')
               when 'prospect' then p.converted_business_id is null and p.current_stage_key<>'lost'
               else true end))
       and (jsonb_array_length(coalesce(p_filters->'stage_keys','[]'::jsonb))=0
            or p.current_stage_key in (select jsonb_array_elements_text(p_filters->'stage_keys')))
       and (nullif(p_filters->>'score_min','') is null
            or coalesce(sc.score,0) >= (p_filters->>'score_min')::integer)
  ), agg as (
    select count(*) as total, count(*) filter (where latitude is not null) as mapped from hits
  )
  select case when p_mode='markers' then
    jsonb_build_object('mode','markers','total',(select total from agg),
      'mapped',(select mapped from agg),
      'capped',(select mapped from agg) > v_marker_cap,
      'marker_cap',v_marker_cap,
      'markers', coalesce((select jsonb_agg(jsonb_build_object(
          'prospect_id',m.prospect_id,'name',m.name,'lat',m.latitude,'lng',m.longitude,
          'score',m.score,'rating',m.rating,'contacted',m.last_contacted_at is not null,
          'converted',m.converted_business_id is not null))
        from (select * from hits where latitude is not null
               order by score desc limit v_marker_cap) m),'[]'::jsonb))
  else
    jsonb_build_object('mode','list','total',(select total from agg),
      'limit',p_limit,'offset',p_offset,
      'has_more',(select total from agg) > p_offset + p_limit,
      'rows', coalesce((select jsonb_agg(to_jsonb(r))
        from (select * from hits order by score desc, name
               limit p_limit offset p_offset) r),'[]'::jsonb))
  end into v_result;
  return v_result;
end $$;

--
-- Name: platform_crm_prospecting_summary_v297(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_crm_prospecting_summary_v297() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_scoped boolean; v_self uuid;
begin
  perform app.v297_assert_prospecting('r');
  v_scoped := app.v89_platform_role()='sales_staff' and not app.is_super_admin();
  v_self := app.v226_self_consultant();
  return (
    with base as (
      select p.id, p.current_stage_key, p.converted_business_id, p.assigned_consultant_id,
             o.contacted_at, o.outcome, o.next_follow_up_at, l.planning_area,
             (select sec.sector_key from public.sme_company_categories cc
                join public.sme_categories cat on cat.id=cc.category_id
                join public.sme_sectors sec on sec.id=cat.sector_id
               where cc.company_id=p.company_id limit 1) as sector_key
        from public.sme_prospects p
        left join public.sme_company_locations l on l.company_id=p.company_id and l.is_primary
        left join lateral (select r.contacted_at,r.outcome,r.next_follow_up_at
                             from public.sme_outreach_records r
                            where r.prospect_id=p.id order by r.contacted_at desc limit 1) o on true
       where p.archived_at is null
         and (not v_scoped or p.assigned_consultant_id = v_self)
    )
    select jsonb_build_object(
      'total',(select count(*) from base),
      'uncontacted',(select count(*) from base where contacted_at is null),
      'contacted',(select count(*) from base where contacted_at is not null),
      'interested',(select count(*) from base where outcome='interested'),
      'not_interested',(select count(*) from base where outcome='not_interested'),
      'converted',(select count(*) from base where converted_business_id is not null),
      'follow_up_due',(select count(*) from base where next_follow_up_at is not null
         and (next_follow_up_at at time zone 'Asia/Singapore')::date
             <= (now() at time zone 'Asia/Singapore')::date),
      'follow_up_overdue',(select count(*) from base where next_follow_up_at < now()),
      'unassigned',(select count(*) from base where assigned_consultant_id is null),
      'by_sector',coalesce((select jsonb_agg(jsonb_build_object('key',sector_key,'count',n)
         order by n desc) from (select sector_key,count(*) n from base
           where sector_key is not null group by sector_key) s),'[]'::jsonb),
      'by_area',coalesce((select jsonb_agg(jsonb_build_object('name',planning_area,'count',n)
         order by n desc) from (select planning_area,count(*) n from base
           where planning_area is not null group by planning_area limit 12) a),'[]'::jsonb),
      'pipeline',coalesce((select jsonb_agg(jsonb_build_object(
           'key',st.stage_key,'label',st.label,'count',
           (select count(*) from base b where b.current_stage_key=st.stage_key))
         order by st.sort_order) from public.sme_pipeline_stages st),'[]'::jsonb)
    ));
end $$;

--
-- Name: platform_crm_prospecting_taxonomy_v297(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_crm_prospecting_taxonomy_v297() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  perform app.v297_assert_prospecting('r');
  return jsonb_build_object(
    'role', app.v89_platform_role(),
    'can_write', app.v297_can_prospecting('rw'),
    'can_assign', app.is_super_admin(),
    'sectors', coalesce((select jsonb_agg(jsonb_build_object(
        'key',s.sector_key,'label',s.label) order by s.sort_order)
      from public.sme_sectors s where s.active),'[]'::jsonb),
    'categories', coalesce((select jsonb_agg(jsonb_build_object(
        'key',c.category_key,'label',c.label,'sector',ps.sector_key,
        'parent',pc.category_key) order by ps.sort_order, c.sort_order)
      from public.sme_categories c
      join public.sme_sectors ps on ps.id=c.sector_id
      left join public.sme_categories pc on pc.id=c.parent_category_id
      where c.active),'[]'::jsonb),
    'planning_areas', coalesce((select jsonb_agg(jsonb_build_object(
        'name',a.name,'region',a.region,'lat',a.latitude,'lng',a.longitude)
        order by a.sort_order) from public.sme_planning_areas a),'[]'::jsonb),
    'stages', coalesce((select jsonb_agg(jsonb_build_object(
        'key',st.stage_key,'label',st.label) order by st.sort_order)
      from public.sme_pipeline_stages st),'[]'::jsonb),
    'consultants', coalesce((select jsonb_agg(jsonb_build_object(
        'id',k.id,'name',k.display_name) order by k.display_name)
      from public.platform_consultants k where k.active),'[]'::jsonb),
    'score_weights', coalesce((select jsonb_agg(jsonb_build_object(
        'key',w.signal_key,'label',w.label,'weight',w.weight) order by w.weight desc)
      from public.sme_lead_score_weights w where w.active),'[]'::jsonb)
  );
end $$;

--
-- Name: platform_crm_save_filter_v297(text, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_crm_save_filter_v297(p_name text, p_config jsonb, p_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_id uuid;
begin
  perform app.v297_assert_prospecting('r');
  if length(btrim(coalesce(p_name,''))) not between 1 and 80 then
    raise exception 'filter_name_required' using errcode='22023';
  end if;
  if p_id is not null then
    update public.sme_saved_filters
       set name=btrim(p_name), filter_config=coalesce(p_config,'{}'::jsonb), updated_at=now()
     where id=p_id and user_id=auth.uid() returning id into v_id;
    if v_id is null then raise exception 'filter_not_found' using errcode='22023'; end if;
  else
    insert into public.sme_saved_filters(user_id,name,filter_config)
    values (auth.uid(), btrim(p_name), coalesce(p_config,'{}'::jsonb))
    on conflict (user_id,name) do update
      set filter_config=excluded.filter_config, updated_at=now()
    returning id into v_id;
  end if;
  return jsonb_build_object('id',v_id);
end $$;

--
-- Name: platform_crm_saved_filters_v297(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_crm_saved_filters_v297() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  perform app.v297_assert_prospecting('r');
  return coalesce((select jsonb_agg(jsonb_build_object(
      'id',s.id,'name',s.name,'filter_config',s.filter_config,'updated_at',s.updated_at)
      order by s.updated_at desc)
    from public.sme_saved_filters s where s.user_id=auth.uid()),'[]'::jsonb);
end $$;

--
-- Name: platform_crm_stale_google_sources_v297(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_crm_stale_google_sources_v297(p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  perform app.v297_assert_prospecting('rw');
  if not (app.is_super_admin() or app.v89_platform_role()='admin') then
    raise exception 'business_import_requires_admin' using errcode='42501';
  end if;
  if p_limit is null or p_limit not between 1 and 200 then
    raise exception 'invalid_page_size' using errcode='22023';
  end if;
  return coalesce((select jsonb_agg(jsonb_build_object(
      'source_id', s.source_id, 'company_id', s.company_id))
    from (
      select distinct src.source_id, src.company_id
        from public.sme_company_sources src
        left join public.sme_company_market_facts f on f.company_id=src.company_id
        left join public.sme_company_locations l on l.company_id=src.company_id and l.is_primary
       where src.source='google_places'
         and (f.company_id is null
              or f.last_synced_at < now() - interval '25 days'
              or (l.geo_source='google_places' and l.geo_synced_at < now() - interval '25 days'))
       limit p_limit
    ) s),'[]'::jsonb);
end $$;

--
-- Name: platform_customer_account_opens_v175(uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_customer_account_opens_v175(p_business uuid, p_from date DEFAULT ((((now() AT TIME ZONE 'Asia/Singapore'::text))::date - '29 days'::interval))::date, p_to date DEFAULT ((now() AT TIME ZONE 'Asia/Singapore'::text))::date) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_authorized boolean:=false;
  v_today date:=(clock_timestamp() at time zone 'Asia/Singapore')::date;
  v_totals jsonb;
  v_channels jsonb;
  v_daily jsonb;
begin
  if auth.uid() is null then
    raise exception 'authenticated report session is required'
      using errcode='28000';
  end if;
  v_authorized:=
    app.is_super_admin()
    or app.has_perm(p_business,'view_finance')
    or (
      app.v89_can_access_business(p_business)
      and app.v89_platform_can('reports','r')
    );
  if not v_authorized then
    raise exception 'business adoption report is outside role scope'
      using errcode='42501';
  end if;
  if p_business is null
     or p_from is null
     or p_to is null
     or p_to<p_from
     or (p_to-p_from)>366
     or p_to>v_today+1 then
    raise exception
      'report range must be ordered, no longer than 367 days and not future'
      using errcode='22023';
  end if;

  with window_rows as(
    select
      day_row.subject_key,day_row.channel,day_row.open_date
    from public.customer_account_open_days_v175 day_row
    where day_row.business_id=p_business
      and day_row.open_date between p_from and p_to
  ), subject_first as(
    select
      day_row.subject_key,min(day_row.open_date) as first_open_date
    from public.customer_account_open_days_v175 day_row
    where day_row.business_id=p_business
    group by day_row.subject_key
  )
  select
    pg_catalog.jsonb_build_object(
      'opens',(select count(*) from window_rows),
      'distinct_customers',(
        select count(distinct window_row.subject_key) from window_rows window_row
      ),
      'first_time_customers',(
        select count(*)
        from subject_first
        where subject_first.first_open_date between p_from and p_to
      )
    ),
    coalesce((
      select pg_catalog.jsonb_agg(
        pg_catalog.jsonb_build_object(
          'channel',channel_summary.channel,
          'opens',channel_summary.opens,
          'distinct_customers',channel_summary.distinct_customers
        ) order by channel_summary.channel
      )
      from(
        select
          window_row.channel,
          count(*)::bigint as opens,
          count(distinct window_row.subject_key)::bigint
            as distinct_customers
        from window_rows window_row
        group by window_row.channel
      ) channel_summary
    ),'[]'::jsonb),
    coalesce((
      select pg_catalog.jsonb_agg(
        pg_catalog.jsonb_build_object(
          'date',daily_summary.open_date,
          'opens',daily_summary.opens,
          'distinct_customers',daily_summary.distinct_customers,
          'first_time_customers',daily_summary.first_time_customers
        ) order by daily_summary.open_date
      )
      from(
        select
          window_row.open_date,
          count(*)::bigint as opens,
          count(distinct window_row.subject_key)::bigint
            as distinct_customers,
          count(distinct window_row.subject_key) filter(
            where subject_first.first_open_date=window_row.open_date
          )::bigint as first_time_customers
        from window_rows window_row
        join subject_first
          on subject_first.subject_key=window_row.subject_key
        group by window_row.open_date
      ) daily_summary
    ),'[]'::jsonb)
  into v_totals,v_channels,v_daily;

  return pg_catalog.jsonb_build_object(
    'business_id',p_business,
    'from',p_from,
    'to',p_to,
    'timezone','Asia/Singapore',
    'contract_version','v175',
    'dedupe','one event per customer subject per channel per calendar day',
    'totals',v_totals,
    'by_channel',v_channels,
    'daily',v_daily
  );
end
$$;

--
-- Name: FUNCTION platform_customer_account_opens_v175(p_business uuid, p_from date, p_to date); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.platform_customer_account_opens_v175(p_business uuid, p_from date, p_to date) IS 'Per-firm customer account-open report. Opens are deduplicated per customer subject, channel and Singapore calendar day; first_time_customers counts subjects whose earliest open for this firm falls inside the window.';

--
-- Name: platform_decide_business_application_v105(uuid, text, text, bigint, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_decide_business_application_v105(p_application uuid, p_decision text, p_reason text, p_expected_version bigint, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid:=auth.uid();
  v_v277_prior_sub text:=current_setting('request.jwt.claim.sub',true);
  v_v277_prior_claims text:=current_setting('request.jwt.claims',true);
  v_reason text:=case
    when p_decision='approved' then 'Approved by Super Admin'
    else btrim(coalesce(p_reason,''))
  end;
  v_request_hash text;
  v_receipt public.platform_application_decision_receipts_v105%rowtype;
  v_application public.business_applications_v95%rowtype;
  v_owner uuid;
  v_bundle public.sector_bundle_versions%rowtype;
  v_business public.businesses%rowtype;
  v_staff uuid;
  v_branch uuid;
  v_slug_base text;
  v_slug text;
  v_suffix integer:=0;
  v_response jsonb;
begin
  if not app.is_super_admin() then
    raise exception 'super_admin_required' using errcode='42501';
  end if;
  if p_application is null or p_idempotency_key is null
     or p_decision not in ('approved','rejected')
     or length(v_reason) not between 3 and 1000
     or p_expected_version is null
  then
    raise exception 'valid decision, reason, version and idempotency key are required'
      using errcode='22023';
  end if;

  v_request_hash:=app.v95_sha256(concat_ws('|',
    p_application::text,p_decision,v_reason,p_expected_version::text
  ));
  perform pg_advisory_xact_lock(hashtextextended(p_idempotency_key::text,105));

  select * into v_receipt
    from public.platform_application_decision_receipts_v105 receipt
   where receipt.idempotency_key=p_idempotency_key
   for update;
  if found then
    if v_receipt.actor<>v_actor
       or v_receipt.application_id<>p_application
       or v_receipt.request_hash<>v_request_hash then
      raise exception 'application_decision_idempotency_conflict'
        using errcode='22023';
    end if;
    select * into v_application
      from public.business_applications_v95 application
     where application.id=p_application
     for update;
    if v_application.status not in (v_receipt.decision,'consumed') then
      raise exception 'application_decision_receipt_state_conflict'
        using errcode='40001';
    end if;
    return jsonb_build_object(
      'application_id',p_application,
      'status',v_application.status,
      'version',v_application.version,
      'business_id',v_application.consumed_business_id,
      'workspace_created',v_application.status='consumed',
      'workspace_access',v_application.status='consumed',
      'replayed',true,
      'response_version',v_receipt.response_version
    );
  end if;

  select * into v_application
    from public.business_applications_v95 application
   where application.id=p_application
   for update;
  if not found then
    raise exception 'application_not_found' using errcode='22023';
  end if;
  if v_application.status<>'submitted' then
    raise exception 'application_is_not_pending' using errcode='23514';
  end if;
  if v_application.version<>p_expected_version then
    raise exception 'application_version_conflict' using errcode='40001';
  end if;

  if p_decision='rejected' then
    update public.business_applications_v95
       set status='rejected',version=version+1,decided_by=v_actor,
           decided_at=now(),decision_reason=v_reason,updated_at=now()
     where id=p_application
     returning * into v_application;
    insert into public.business_application_audit_v95(
      application_id,event_type,actor,prior_status,new_status,reason
    ) values(
      p_application,'rejected',v_actor,'submitted','rejected',v_reason
    );
    insert into public.platform_application_decision_receipts_v105(
      idempotency_key,application_id,actor,request_hash,decision,
      invitation_id,response_version
    ) values(
      p_idempotency_key,p_application,v_actor,v_request_hash,'rejected',
      null,1
    ) returning * into v_receipt;
    return jsonb_build_object(
      'application_id',p_application,'status','rejected',
      'version',v_application.version,'workspace_created',false,
      'workspace_access',false,'replayed',false,'response_version',1
    );
  end if;

  select user_row.id into v_owner
    from auth.users user_row
   where lower(user_row.email)=v_application.contact_email
     and coalesce(user_row.email_confirmed_at,user_row.confirmed_at) is not null
   order by user_row.created_at asc,user_row.id asc
   limit 1;
  if v_owner is null then
    raise exception 'owner_account_not_found_for_application' using errcode='42501';
  end if;
  if exists(select 1 from public.staff staff_row where staff_row.user_id=v_owner) then
    raise exception 'owner_account_already_has_workspace' using errcode='42501';
  end if;

  select * into v_bundle
    from public.sector_bundle_versions
   where sector_key=v_application.sector_key and status='published';
  if not found then
    raise exception 'published_sector_required' using errcode='23514';
  end if;

  v_slug_base:=lower(regexp_replace(v_application.business_name,'[^a-zA-Z0-9]+','-','g'));
  v_slug_base:=trim(both '-' from v_slug_base);
  if length(v_slug_base)<3 then
    v_slug_base:='business-'||left(v_application.public_reference::text,8);
  end if;
  v_slug_base:=left(v_slug_base,60);
  v_slug:=v_slug_base;
  while exists(select 1 from public.businesses where slug=v_slug) loop
    v_suffix:=v_suffix+1;
    v_slug:=left(v_slug_base,55)||'-'||v_suffix::text;
  end loop;

  update public.business_applications_v95
     set status='approved',version=version+1,decided_by=v_actor,
         decided_at=now(),decision_reason=v_reason,updated_at=now()
   where id=p_application
   returning * into v_application;
  insert into public.business_application_audit_v95(
    application_id,event_type,actor,prior_status,new_status,reason
  ) values(
    p_application,'approved',v_actor,'submitted','approved',v_reason
  );

  update public.business_application_invitations_v95 invitation
     set revoked_at=coalesce(invitation.revoked_at,now())
   where invitation.application_id=p_application
     and invitation.revoked_at is null
     and invitation.consumed_at is null;

  insert into public.businesses(name,slug,industry,enabled_modules)
  values(v_application.business_name,v_slug,v_application.sector_key,v_bundle.modules)
  returning * into v_business;
  insert into public.staff(business_id,user_id,role,full_name,active)
  values(v_business.id,v_owner,'owner',v_application.contact_name,true)
  returning id into v_staff;
  insert into public.branches(business_id,name,is_default,active)
  values(v_business.id,v_application.business_name,true,true)
  returning id into v_branch;
  insert into public.staff_branches(business_id,staff_id,branch_id)
  values(v_business.id,v_staff,v_branch);

  update public.business_workspace_controls_v94
     set approval_status='approved',version=version+1,
         decided_by=v_actor,decided_at=v_application.decided_at,
         decision_reason='direct super-admin application approval '||v_application.id,
         updated_at=now()
   where business_id=v_business.id;
  insert into public.business_workspace_control_audit_v94(
    business_id,actor,event_type,prior_status,new_status,reason,control_version
  ) values(
    v_business.id,v_actor,'application_activated','pending','approved',
    'direct super-admin application approval',2
  );
  /*
    V169 removed the loyalty_programs seed from here and V277 restored it, just below, under the owner identity (the app.activate_self_serve_paid_v130 shape). Do not remove it again: without it public.create_loyalty_config_draft raises base configuration not found and the tenant can never open Grow. The V169 note that followed is kept for history and its closing claim - that the owner could just build the programme in Grow - was wrong.

    It fired seed_loyalty_config_version(), whose version row trips
    app.c45_loyalty_program_version_write_guard. That guard requires
    app.c45_owner_loyalty_write(business) -> app.is_salon_owner(business) -> an ACTIVE owner
    staff row whose user_id = auth.uid(). During approval auth.uid() is the SUPER ADMIN, who by
    design is never tenant staff, so the guard raised 42501 and rolled back the ENTIRE approval.
    Result: no approval had ever succeeded (zero DIRECT_APPLICATION_APPROVED_ACTIVATED_V167 rows
    in audit_log as of 2026-08-05); approved owners were left with no workspace and no login.

    The seeded row was an INACTIVE 'draft' preset, so omitting it costs the owner nothing: they
    create their programme through Grow as the owner, where the guard legitimately passes. This
    keeps the guard's security property intact - no new super-admin write path into tenant
    loyalty configuration.
  */
  perform set_config('request.jwt.claim.sub',v_owner::text,true);
  perform set_config('request.jwt.claims',
    jsonb_build_object('sub',v_owner,'role','authenticated','aud','authenticated')::text,true);
  if app.c45_owner_loyalty_write(v_business.id) then
    insert into public.loyalty_programs(
      business_id,kind,earn_points_per_dollar,redeem_points,
      reward_credit_cents,active,loyalty_model,configuration_status,
      recommendation_source
    ) values(
      v_business.id,'points',1,800,2000,false,'classic','draft',
      'onboarding_preset'
    ) on conflict(business_id) do nothing;
  end if;
  perform set_config('request.jwt.claim.sub',coalesce(v_v277_prior_sub,''),true);
  perform set_config('request.jwt.claims',coalesce(v_v277_prior_claims,''),true);
  insert into public.subscriptions(business_id) values(v_business.id)
  on conflict(business_id) do nothing;
  insert into public.business_sector_assignments(
    business_id,bundle_version_id,version,assigned_by
  ) values(v_business.id,v_bundle.id,1,v_actor);

  update public.business_applications_v95
     set status='consumed',version=version+1,consumed_business_id=v_business.id,
         consumed_by=v_owner,consumed_at=now(),updated_at=now()
   where id=v_application.id
   returning * into v_application;

  v_response:=jsonb_build_object(
    'application_id',v_application.id,'status','consumed',
    'business_id',v_business.id,'business_slug',v_business.slug,
    'owner_staff_id',v_staff,'default_branch_id',v_branch,
    'workspace_created',true,'workspace_access',true,
    'approved_email',v_application.contact_email,
    'replayed',false,'response_version',1
  );

  insert into public.business_application_audit_v95(
    application_id,event_type,actor,prior_status,new_status,reason,detail
  ) values(
    v_application.id,'invitation_consumed',v_owner,'approved','consumed',
    'super-admin approval activated existing owner account directly',
    jsonb_build_object('business_id',v_business.id,'approved_by',v_actor)
  );
  insert into public.audit_log(
    business_id,actor,action,entity,entity_id,detail
  ) values(
    v_business.id,v_actor,'DIRECT_APPLICATION_APPROVED_ACTIVATED_V167',
    'businesses',v_business.id,jsonb_build_object(
      'application_id',v_application.id,
      'owner_user_id',v_owner,
      'sector_bundle_version_id',v_bundle.id
    )
  );
  insert into public.platform_application_decision_receipts_v105(
    idempotency_key,application_id,actor,request_hash,decision,
    invitation_id,response_version
  ) values(
    p_idempotency_key,p_application,v_actor,v_request_hash,'approved',
    null,1
  ) returning * into v_receipt;

  return v_response;
end
$$;

--
-- Name: FUNCTION platform_decide_business_application_v105(p_application uuid, p_decision text, p_reason text, p_expected_version bigint, p_idempotency_key uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.platform_decide_business_application_v105(p_application uuid, p_decision text, p_reason text, p_expected_version bigint, p_idempotency_key uuid) IS 'V167 retry-safe Super Admin business application decision. Approval directly activates the matching confirmed owner account and workspace without returning an invitation link.';

--
-- Name: platform_decide_business_application_v95(uuid, text, text, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_decide_business_application_v95(p_application uuid, p_decision text, p_reason text, p_expected_version bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_application public.business_applications_v95%rowtype;
  v_raw_token text;
  v_invitation public.business_application_invitations_v95%rowtype;
begin
  if not app.is_super_admin() then
    raise exception 'super_admin_required' using errcode='42501';
  end if;
  if p_decision not in ('approved','rejected')
     or length(btrim(coalesce(p_reason,''))) not between 3 and 1000
     or p_expected_version is null
  then raise exception 'valid decision reason and version are required'
    using errcode='22023';end if;
  select * into v_application from public.business_applications_v95
  where id=p_application for update;
  if not found then raise exception 'application_not_found' using errcode='22023';end if;
  if v_application.status<>'submitted' then
    raise exception 'application_is_not_pending' using errcode='23514';
  end if;
  if v_application.version<>p_expected_version then
    raise exception 'application_version_conflict' using errcode='40001';
  end if;
  update public.business_applications_v95
  set status=p_decision,version=version+1,decided_by=auth.uid(),
    decided_at=now(),decision_reason=btrim(p_reason),updated_at=now()
  where id=p_application returning * into v_application;
  insert into public.business_application_audit_v95(
    application_id,event_type,actor,prior_status,new_status,reason
  ) values(
    p_application,p_decision,auth.uid(),'submitted',p_decision,btrim(p_reason)
  );
  if p_decision='approved' then
    v_raw_token:=encode(extensions.gen_random_bytes(32),'hex');
    insert into public.business_application_invitations_v95(
      application_id,token_hash,expires_at,issued_by
    ) values(
      p_application,app.v95_sha256(v_raw_token),now()+interval '72 hours',
      auth.uid()
    ) returning * into v_invitation;
  end if;
  return jsonb_build_object(
    'application_id',p_application,'status',p_decision,
    'version',v_application.version,
    'approved_email',case when p_decision='approved'
      then v_application.contact_email else null end,
    'invitation_token',v_raw_token,
    'invitation_expires_at',v_invitation.expires_at
  );
end
$$;

--
-- Name: platform_decide_business_approval_v94(uuid, text, text, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_decide_business_approval_v94(p_business uuid, p_decision text, p_reason text, p_expected_version bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_actor uuid:=auth.uid();v_control public.business_workspace_controls_v94%rowtype;
  v_prior_status text;
begin
  if not app.is_super_admin() then
    raise exception 'super_admin_required' using errcode='42501';
  end if;
  if p_decision not in ('approved','rejected')
     or length(btrim(coalesce(p_reason,''))) not between 3 and 1000 then
    raise exception 'valid approval decision and reason are required'
      using errcode='22023';
  end if;
  select * into v_control
  from public.business_workspace_controls_v94 control
  where control.business_id=p_business for update;
  if not found then raise exception 'business_control_not_found' using errcode='22023';end if;
  if p_expected_version is null or p_expected_version<>v_control.version then
    raise exception 'business_control_version_conflict' using errcode='40001';
  end if;
  v_prior_status:=v_control.approval_status;
  update public.business_workspace_controls_v94
  set approval_status=p_decision,version=version+1,decided_by=v_actor,
    decided_at=now(),decision_reason=btrim(p_reason),updated_at=now()
  where business_id=p_business returning * into v_control;
  insert into public.business_workspace_control_audit_v94(
    business_id,actor,event_type,prior_status,new_status,reason,control_version
  ) values(
    p_business,v_actor,
    case p_decision when 'approved' then 'firm_approved' else 'firm_rejected' end,
    v_prior_status,p_decision,btrim(p_reason),v_control.version
  );
  return jsonb_build_object(
    'business_id',p_business,'approval_status',v_control.approval_status,
    'workspace_access',app.business_workspace_open_v94(p_business),
    'version',v_control.version,'decided_at',v_control.decided_at,
    'decided_by',v_control.decided_by
  );
end
$$;

--
-- Name: platform_decide_import_row_v86(uuid, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_decide_import_row_v86(p_import_row uuid, p_decision text, p_candidate_prospect uuid DEFAULT NULL::uuid, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_actor uuid:=auth.uid();v_version integer;v_batch uuid;v_row public.sme_import_row_decision_versions%rowtype;
begin
  if not app.is_platform_operator_v75() then raise exception 'platform operator access is required' using errcode='42501';end if;
  select batch_id into v_batch from public.sme_prospect_import_rows where id=p_import_row;
  if v_batch is null or not exists(select 1 from public.sme_prospect_import_batches where id=v_batch and status='staged') then
    raise exception 'staged import row was not found' using errcode='22023';end if;
  if p_decision not in ('insert','skip','merge','review') then raise exception 'invalid import decision' using errcode='22023';end if;
  if p_decision='merge' and not exists(
    select 1 from public.sme_import_dedupe_candidates
     where import_row_id=p_import_row and candidate_prospect_id=p_candidate_prospect
  ) then raise exception 'merge requires a reviewed dedupe candidate' using errcode='22023';end if;
  select coalesce(max(version),0)+1 into v_version
    from public.sme_import_row_decision_versions where import_row_id=p_import_row;
  insert into public.sme_import_row_decision_versions(
    import_row_id,version,decision,candidate_prospect_id,reason,decided_by
  ) values(p_import_row,v_version,p_decision,p_candidate_prospect,nullif(btrim(p_reason),''),v_actor)
  returning * into v_row;
  insert into public.audit_log(business_id,actor,action,entity,entity_id,detail)
  values(null,v_actor,'SME_IMPORT_ROW_DECIDED_V86','sme_prospect_import_rows',p_import_row,
    jsonb_build_object('batch_id',v_batch,'decision',p_decision,
      'candidate_prospect_id',p_candidate_prospect,'version',v_version));
  return jsonb_build_object('decision',to_jsonb(v_row));
end
$$;

--
-- Name: platform_decide_merchant_match_v312(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_decide_merchant_match_v312(p_match uuid, p_confirm boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_actor uuid := auth.uid(); m public.sme_merchant_match_candidates%rowtype;
begin
  perform app.v297_assert_prospecting('rw');
  if not (app.is_super_admin() or app.v89_platform_role()='admin') then
    raise exception 'merchant match review requires admin' using errcode='42501';
  end if;
  select * into m from public.sme_merchant_match_candidates where id=p_match for update;
  if not found then raise exception 'match was not found' using errcode='22023'; end if;
  if m.status <> 'pending' then
    return jsonb_build_object('outcome','already_decided','status',m.status);
  end if;

  if p_confirm then
    update public.sme_companies
       set peekaa_business_id = m.business_id, merchant_linked_at = now(),
           merchant_link_basis = 'reviewed'
     where id = m.company_id;
  end if;

  update public.sme_merchant_match_candidates
     set status = case when p_confirm then 'confirmed' else 'rejected' end,
         decided_by = v_actor, decided_at = now()
   where id = p_match;

  insert into public.audit_log(business_id, actor, action, entity, entity_id, detail)
  values (m.business_id, v_actor, 'MERCHANT_MATCH_DECIDED_V312',
          'sme_merchant_match_candidates', p_match,
          jsonb_build_object('confirmed', p_confirm, 'company_id', m.company_id));

  return jsonb_build_object('outcome', case when p_confirm then 'linked' else 'rejected' end);
end $$;

--
-- Name: platform_discard_receipt_v199(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_discard_receipt_v199(p_receipt uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_actor uuid:=auth.uid(); v_row public.platform_accounting_receipts_v199%rowtype;
begin
  if v_actor is null or not app.is_super_admin() then
    raise exception 'super-admin access is required' using errcode='42501';
  end if;
  if coalesce(btrim(p_reason),'')='' then
    raise exception 'a reason is required to discard a receipt' using errcode='22023';
  end if;
  update public.platform_accounting_receipts_v199
     set status='discarded', discarded_at=now(), discarded_by=v_actor,
         discard_reason=btrim(p_reason)
   where id=p_receipt and status<>'posted'
  returning * into v_row;
  if not found then
    raise exception 'only an unposted receipt can be discarded' using errcode='22023';
  end if;
  insert into public.audit_log(business_id,actor,action,entity,entity_id,detail)
  values(null,v_actor,'PLATFORM_RECEIPT_DISCARDED_V199',
    'platform_accounting_receipts_v199',p_receipt,
    jsonb_build_object('reason',btrim(p_reason)));
  return jsonb_build_object('receipt',to_jsonb(v_row));
end $$;

--
-- Name: platform_engagement_monthly_v255(date, date, uuid[], integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_engagement_monthly_v255(p_from date, p_to date, p_businesses uuid[] DEFAULT NULL::uuid[], p_limit integer DEFAULT 100) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid:=auth.uid();
  v_from timestamptz;
  v_to timestamptz;
  v_rows jsonb;
  v_trend jsonb;
  v_summary jsonb;
  v_total integer:=0;
begin
  if v_actor is null then
    raise exception 'authenticated platform session is required'
      using errcode='28000';
  end if;
  if not app.is_super_admin() then
    raise exception 'platform engagement reporting is super admin only'
      using errcode='42501';
  end if;
  if p_from is null or p_to is null or p_to<p_from then
    raise exception 'report range must be positive' using errcode='22023';
  end if;
  if p_to>p_from+interval '24 months' then
    raise exception 'report range may not exceed 24 months'
      using errcode='22023';
  end if;
  if p_businesses is not null
     and coalesce(array_length(p_businesses,1),0)>100 then
    raise exception 'at most 100 businesses may be requested'
      using errcode='22023';
  end if;
  if p_limit is null or p_limit not between 1 and 1000 then
    raise exception 'row limit must be 1..1000' using errcode='22023';
  end if;

  v_from:=(date_trunc('month',p_from::timestamp) at time zone 'Asia/Singapore');
  v_to:=(
    (date_trunc('month',p_to::timestamp)+interval '1 month')
    at time zone 'Asia/Singapore'
  );

  with sends as(
    select
      record.business_id,
      pg_catalog.to_char(
        date_trunc('month',record.occurred_at at time zone 'Asia/Singapore'),
        'YYYY-MM'
      ) as month,
      count(*)::bigint as sends,
      count(distinct
        record.campaign_kind||':'||record.campaign_ref_id::text
      )::bigint as campaigns
    from public.campaign_send_records_v255 record
    where record.occurred_at>=v_from and record.occurred_at<v_to
      and (p_businesses is null or record.business_id=any(p_businesses))
    group by 1,2
  ),
  pushes as(
    select
      event_row.business_id,
      pg_catalog.to_char(
        date_trunc('month',result.created_at at time zone 'Asia/Singapore'),
        'YYYY-MM'
      ) as month,
      count(*) filter(where result.result='sent')::bigint as push_sent,
      count(*) filter(
        where result.result in ('failed','gone')
      )::bigint as push_failed
    from public.customer_push_delivery_results_v95 result
    join public.customer_push_deliveries_v95 delivery
      on delivery.id=result.delivery_id
    join public.customer_in_app_inbox_events event_row
      on event_row.id=delivery.event_id
    where result.created_at>=v_from and result.created_at<v_to
      and (p_businesses is null or event_row.business_id=any(p_businesses))
    group by 1,2
  ),
  opens as(
    select
      state.business_id,
      pg_catalog.to_char(
        date_trunc('month',state.read_at at time zone 'Asia/Singapore'),
        'YYYY-MM'
      ) as month,
      count(*)::bigint as inbox_opens
    from public.customer_in_app_inbox_state state
    where state.read_at>=v_from and state.read_at<v_to
      and (p_businesses is null or state.business_id=any(p_businesses))
    group by 1,2
  ),
  adoption as(
    select
      event_row.business_id,
      pg_catalog.to_char(
        date_trunc('month',event_row.occurred_at at time zone 'Asia/Singapore'),
        'YYYY-MM'
      ) as month,
      count(distinct event_row.actor_user_id) filter(
        where event_row.actor_scope='merchant'
      )::bigint as merchant_mau,
      count(distinct event_row.session_id)::bigint as sessions
    from public.product_adoption_events_v100 event_row
    where event_row.business_id is not null
      and event_row.occurred_at>=v_from and event_row.occurred_at<v_to
      and (p_businesses is null or event_row.business_id=any(p_businesses))
    group by 1,2
  ),
  merchant_daily as(
    select
      event_row.business_id,
      pg_catalog.to_char(
        date_trunc('month',event_row.occurred_at at time zone 'Asia/Singapore'),
        'YYYY-MM'
      ) as month,
      (event_row.occurred_at at time zone 'Asia/Singapore')::date as open_day,
      count(distinct event_row.actor_user_id)::bigint as actors
    from public.product_adoption_events_v100 event_row
    where event_row.business_id is not null
      and event_row.actor_scope='merchant'
      and event_row.occurred_at>=v_from and event_row.occurred_at<v_to
      and (p_businesses is null or event_row.business_id=any(p_businesses))
    group by 1,2,3
  ),
  merchant_dau as(
    select
      daily.business_id,daily.month,
      round(avg(daily.actors),2) as merchant_dau
    from merchant_daily daily
    group by 1,2
  ),
  customer_opens as(
    select
      open_row.business_id,
      pg_catalog.to_char(
        date_trunc('month',open_row.open_date::timestamp),'YYYY-MM'
      ) as month,
      count(distinct coalesce(
        open_row.auth_user_id,open_row.client_id
      ))::bigint as customer_mau
    from public.customer_account_open_days_v175 open_row
    where open_row.open_date>=(v_from at time zone 'Asia/Singapore')::date
      and open_row.open_date<(v_to at time zone 'Asia/Singapore')::date
      and (p_businesses is null or open_row.business_id=any(p_businesses))
    group by 1,2
  ),
  redemptions as(
    select
      redemption.business_id,
      pg_catalog.to_char(
        date_trunc(
          'month',redemption.redeemed_at at time zone 'Asia/Singapore'
        ),'YYYY-MM'
      ) as month,
      count(*)::bigint as redemptions
    from public.loyalty_redemptions redemption
    where redemption.redeemed_at>=v_from and redemption.redeemed_at<v_to
      and (p_businesses is null or redemption.business_id=any(p_businesses))
    group by 1,2
  ),
  bookings as(
    select
      request.business_id,
      pg_catalog.to_char(
        date_trunc('month',request.created_at at time zone 'Asia/Singapore'),
        'YYYY-MM'
      ) as month,
      count(*)::bigint as bookings
    from public.booking_requests request
    where request.created_at>=v_from and request.created_at<v_to
      and (p_businesses is null or request.business_id=any(p_businesses))
    group by 1,2
  ),
  sale_counts as(
    select
      sale.business_id,
      pg_catalog.to_char(
        date_trunc('month',sale.occurred_at at time zone 'Asia/Singapore'),
        'YYYY-MM'
      ) as month,
      count(*)::bigint as sales_count
    from public.sales sale
    where sale.occurred_at>=v_from and sale.occurred_at<v_to
      and sale.reversal_of is null
      and (p_businesses is null or sale.business_id=any(p_businesses))
    group by 1,2
  ),
  keys as(
    select business_id,month from sends
    union select business_id,month from pushes
    union select business_id,month from opens
    union select business_id,month from adoption
    union select business_id,month from customer_opens
    union select business_id,month from redemptions
    union select business_id,month from bookings
    union select business_id,month from sale_counts
  ),
  rows_out as(
    select
      key.business_id,key.month,
      coalesce(business.name,'Removed business') as business_name,
      (
        select count(*)::bigint
        from public.customer_links link
        where link.business_id=key.business_id
          and link.state='verified'
          and link.created_at
              <((key.month||'-01')::date+interval '1 month')
                at time zone 'Asia/Singapore'
      ) as customers,
      coalesce(sends.campaigns,0) as campaigns,
      coalesce(pushes.push_sent,0) as push_sent,
      coalesce(pushes.push_failed,0) as push_failed,
      coalesce(sends.sends,0) as sends,
      coalesce(opens.inbox_opens,0) as inbox_opens,
      coalesce(merchant_dau.merchant_dau,0) as merchant_dau,
      coalesce(adoption.merchant_mau,0) as merchant_mau,
      coalesce(adoption.sessions,0) as sessions,
      coalesce(customer_opens.customer_mau,0) as customer_mau,
      coalesce(redemptions.redemptions,0) as redemptions,
      coalesce(bookings.bookings,0) as bookings,
      coalesce(sale_counts.sales_count,0) as sales_count
    from keys key
    left join public.businesses business on business.id=key.business_id
    left join sends
      on sends.business_id=key.business_id and sends.month=key.month
    left join pushes
      on pushes.business_id=key.business_id and pushes.month=key.month
    left join opens
      on opens.business_id=key.business_id and opens.month=key.month
    left join adoption
      on adoption.business_id=key.business_id and adoption.month=key.month
    left join merchant_dau
      on merchant_dau.business_id=key.business_id
     and merchant_dau.month=key.month
    left join customer_opens
      on customer_opens.business_id=key.business_id
     and customer_opens.month=key.month
    left join redemptions
      on redemptions.business_id=key.business_id
     and redemptions.month=key.month
    left join bookings
      on bookings.business_id=key.business_id and bookings.month=key.month
    left join sale_counts
      on sale_counts.business_id=key.business_id
     and sale_counts.month=key.month
  ),
  page as(
    select * from rows_out
    order by month desc,business_name,business_id
    limit p_limit
  )
  select
    coalesce(
      pg_catalog.jsonb_agg(
        pg_catalog.jsonb_build_object(
          'business_id',page.business_id,'business_name',page.business_name,
          'month',page.month,'customers',page.customers,
          'campaigns',page.campaigns,'push_sent',page.push_sent,
          'push_failed',page.push_failed,'sends',page.sends,
          'inbox_opens',page.inbox_opens,'merchant_dau',page.merchant_dau,
          'merchant_mau',page.merchant_mau,'sessions',page.sessions,
          'customer_mau',page.customer_mau,'redemptions',page.redemptions,
          'bookings',page.bookings,'sales_count',page.sales_count
        )
        order by page.month desc,page.business_name,page.business_id
      ),
      '[]'::jsonb
    ),
    (select count(*)::integer from rows_out)
  into v_rows,v_total
  from page;

  select coalesce(
    pg_catalog.jsonb_agg(
      pg_catalog.jsonb_build_object(
        'month',trend.month,'businesses',trend.businesses,
        'customers',trend.customers,'campaigns',trend.campaigns,
        'push_sent',trend.push_sent,'sends',trend.sends,
        'inbox_opens',trend.inbox_opens
      )
      order by trend.month desc
    ),
    '[]'::jsonb
  ) into v_trend
  from(
    select
      item->>'month' as month,
      count(*)::bigint as businesses,
      sum((item->>'customers')::bigint) as customers,
      sum((item->>'campaigns')::bigint) as campaigns,
      sum((item->>'push_sent')::bigint) as push_sent,
      sum((item->>'sends')::bigint) as sends,
      sum((item->>'inbox_opens')::bigint) as inbox_opens
    from pg_catalog.jsonb_array_elements(v_rows) as element(item)
    group by 1
  ) trend;

  -- 'customers' is a running total per business-month, so summing every month
  -- would count the same customer once per month. The headline is the newest
  -- month only.
  select pg_catalog.jsonb_build_object(
    'businesses',count(distinct item->>'business_id'),
    'months',count(distinct item->>'month'),
    'customers',coalesce(sum((item->>'customers')::bigint) filter(
      where item->>'month'=(
        select pg_catalog.max(latest->>'month')
        from pg_catalog.jsonb_array_elements(v_rows) as newest(latest)
      )
    ),0),
    'campaigns',coalesce(sum((item->>'campaigns')::bigint),0),
    'push_sent',coalesce(sum((item->>'push_sent')::bigint),0),
    'sends',coalesce(sum((item->>'sends')::bigint),0),
    'inbox_opens',coalesce(sum((item->>'inbox_opens')::bigint),0)
  ) into v_summary
  from pg_catalog.jsonb_array_elements(v_rows) as element(item);

  return pg_catalog.jsonb_build_object(
    'scope',pg_catalog.jsonb_build_object(
      'from',p_from,'to',p_to,'limit',p_limit,
      'business_filter_count',coalesce(array_length(p_businesses,1),0),
      'timezone','Asia/Singapore'
    ),
    'methodology',pg_catalog.jsonb_build_object(
      'customers',
        'Verified customer links that existed at the end of that month.',
      'campaigns',
        'Distinct campaigns with at least one send record in that month.',
      'push_sent',
        'Web push attempts the dispatcher reported as sent in that month.',
      'push_opens',
        'Not tracked. The Web Push API returns no delivery receipt or open callback.',
      'months','Calendar months in Asia/Singapore.'
    ),
    'summary',coalesce(v_summary,'{}'::jsonb),
    'businesses',v_rows,
    'monthly_trend',v_trend,
    'total_count',v_total,
    'has_more',v_total>p_limit,
    'snapshot_at',clock_timestamp()
  );
end
$$;

--
-- Name: platform_erase_prospect_contact_pii_v184(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_erase_prospect_contact_pii_v184(p_contact uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_actor uuid:=auth.uid(); v_prospect uuid; v_versions integer:=0;
begin
  if not app.is_super_admin() then
    raise exception 'super admin access is required' using errcode='42501';
  end if;
  if coalesce(btrim(p_reason),'')='' then
    raise exception 'a reason is required to erase personal data' using errcode='22023';
  end if;
  select prospect_id into v_prospect from public.sme_prospect_contacts where id=p_contact;
  if v_prospect is null then
    raise exception 'contact not found' using errcode='22023';
  end if;

  update public.sme_prospect_contacts
     set full_name='[erased]', email=null, phone=null, active=false, updated_at=now()
   where id=p_contact;

  -- The profile history is columnar, so each personal field is nulled in
  -- place. do_not_contact is deliberately forced true rather than erased: an
  -- erasure request is also a standing instruction never to contact again.
  update public.sme_contact_profile_versions
     set preferred_name=null, mobile_original=null, mobile_e164=null,
         office_phone_original=null, office_phone_e164=null,
         whatsapp_original=null, whatsapp_e164=null,
         profile_url=null, contact_hours=null, notes=null,
         marketing_opt_in=false, do_not_contact=true
   where contact_id=p_contact;
  get diagnostics v_versions=row_count;

  insert into public.audit_log(business_id,actor,action,entity,entity_id,detail)
  values(null,v_actor,'PLATFORM_CONTACT_PII_ERASED_V184','sme_prospect_contacts',p_contact,
    jsonb_build_object('prospect',v_prospect,'reason',btrim(p_reason),
      'profile_versions_scrubbed',v_versions));
  return jsonb_build_object('status','erased','contact',p_contact,
    'profile_versions_scrubbed',v_versions);
end $$;

--
-- Name: platform_explore_demand_v255(date, date, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_explore_demand_v255(p_from date, p_to date, p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid:=auth.uid();
  v_from timestamptz;
  v_to timestamptz;
  v_items jsonb;
  v_total integer:=0;
  v_suppressed integer:=0;
begin
  if v_actor is null then
    raise exception 'authenticated platform session is required'
      using errcode='28000';
  end if;
  if not app.is_super_admin() then
    raise exception 'platform demand reporting is super admin only'
      using errcode='42501';
  end if;
  if p_from is null or p_to is null or p_to<p_from then
    raise exception 'report range must be positive' using errcode='22023';
  end if;
  if p_to>p_from+interval '24 months' then
    raise exception 'report range may not exceed 24 months'
      using errcode='22023';
  end if;
  if p_limit is null or p_limit not between 1 and 200 then
    raise exception 'row limit must be 1..200' using errcode='22023';
  end if;

  v_from:=(p_from::timestamp at time zone 'Asia/Singapore');
  v_to:=((p_to::timestamp+interval '1 day') at time zone 'Asia/Singapore');

  with shapes as(
    select
      nullif(btrim(event_row.event_context->>'query_shape'),'') as query_shape,
      count(*)::bigint as searches,
      count(distinct event_row.actor_user_id)::bigint as customers
    from public.product_adoption_events_v100 event_row
    where event_row.event_name='customer.explore_searched'
      and event_row.occurred_at>=v_from and event_row.occurred_at<v_to
    group by 1
  ),
  visible as(
    select * from shapes
    where shapes.query_shape is not null and shapes.searches>=5
  ),
  page as(
    select * from visible order by searches desc,query_shape limit p_limit
  )
  select
    coalesce(
      pg_catalog.jsonb_agg(
        pg_catalog.jsonb_build_object(
          'query_shape',page.query_shape,
          'searches',page.searches,
          'customers',page.customers
        )
        order by page.searches desc,page.query_shape
      ),
      '[]'::jsonb
    ),
    (select count(*)::integer from visible),
    (
      select count(*)::integer from shapes
      where shapes.query_shape is not null and shapes.searches<5
    )
  into v_items,v_total,v_suppressed
  from page;

  return pg_catalog.jsonb_build_object(
    'scope',pg_catalog.jsonb_build_object(
      'from',p_from,'to',p_to,'limit',p_limit,'timezone','Asia/Singapore'
    ),
    'methodology',pg_catalog.jsonb_build_object(
      'shape_only',
        'Only the normalized shape of a search is recorded. Typed text is never stored.',
      'k_anonymity',
        'A shape seen fewer than 5 times in the range is suppressed entirely.'
    ),
    'items',v_items,
    'suppressed_buckets',coalesce(v_suppressed,0),
    'total_count',v_total,
    'has_more',v_total>p_limit,
    'snapshot_at',clock_timestamp()
  );
end
$$;

--
-- Name: platform_explorer_bulk_assign_v312(uuid[], uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_explorer_bulk_assign_v312(p_prospects uuid[], p_consultant uuid, p_reason text DEFAULT 'Bulk assigned from the Business Explorer'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_actor uuid := auth.uid(); v_assigned integer := 0; v_skipped integer := 0; v_id uuid;
begin
  perform app.v297_assert_prospecting('rw');
  if not app.is_super_admin() then
    raise exception 'only a super admin may assign prospects' using errcode='42501';
  end if;
  if p_prospects is null or cardinality(p_prospects) = 0 then
    raise exception 'no prospects were selected' using errcode='22023';
  end if;
  if cardinality(p_prospects) > 500 then
    raise exception 'assign at most 500 prospects at a time' using errcode='22023';
  end if;
  if p_consultant is null then
    raise exception 'a consultant is required' using errcode='22023';
  end if;

  foreach v_id in array p_prospects loop
    -- Never hand a rep a business that is already ours.
    update public.sme_prospects p
       set assigned_consultant_id = p_consultant,
           current_stage_key = case when p.current_stage_key='new_lead' then 'assigned'
                                    else p.current_stage_key end,
           stage_entered_at = case when p.current_stage_key='new_lead' then now()
                                   else p.stage_entered_at end,
           version = p.version + 1, updated_by = v_actor, updated_at = now()
      from public.sme_companies c
     where p.id = v_id and c.id = p.company_id
       and p.archived_at is null
       and p.converted_business_id is null and c.peekaa_business_id is null;
    if found then
      v_assigned := v_assigned + 1;
      insert into public.sme_prospect_assignments(prospect_id, consultant_id, assigned_by, reason)
      values (v_id, p_consultant, v_actor, p_reason);
    else
      v_skipped := v_skipped + 1;
    end if;
  end loop;

  insert into public.audit_log(business_id, actor, action, entity, entity_id, detail)
  values (null, v_actor, 'PROSPECTS_BULK_ASSIGNED_V312', 'sme_prospects', null,
          jsonb_build_object('consultant', p_consultant, 'requested', cardinality(p_prospects),
                             'assigned', v_assigned, 'skipped', v_skipped));

  return jsonb_build_object('assigned', v_assigned, 'skipped', v_skipped,
                            'requested', cardinality(p_prospects));
end $$;

--
-- Name: platform_explorer_search_v312(jsonb, text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_explorer_search_v312(p_filters jsonb DEFAULT '{}'::jsonb, p_mode text DEFAULT 'list'::text, p_sort text DEFAULT 'added_desc'::text, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_rows jsonb; v_total integer; v_self uuid; v_is_admin boolean;
begin
  perform app.v297_assert_prospecting('r');
  if p_mode not in ('list','markers','ids','count') then
    raise exception 'unknown explorer mode' using errcode='22023';
  end if;
  if p_limit is null or p_limit not between 1 and 500 then
    raise exception 'invalid_page_size' using errcode='22023';
  end if;
  if p_sort not in ('added_desc','added_asc','name_asc','name_desc','area_asc',
                    'category_asc','rating_desc','reviews_desc',
                    'contacted_desc','follow_up_asc') then
    raise exception 'unknown sort order' using errcode='22023';
  end if;

  v_is_admin := app.is_super_admin() or app.v89_platform_role() = 'admin';
  v_self := app.v226_self_consultant();

  with base as (
    select
      p.id as prospect_id, c.id as company_id,
      coalesce(c.trading_name, c.legal_name) as name,
      c.phone, c.website, c.email,
      l.planning_area, l.district, l.postal_code, l.address, l.latitude, l.longitude,
      f.rating, f.review_count, f.business_status, f.price_level,
      src.source_id as place_id, src.source_url,
      sec.label as industry, parent.label as category, cat.label as subcategory,
      cat.category_key,
      p.current_stage_key, st.label as stage_label, st.kind as stage_kind,
      p.assigned_consultant_id, p.created_at,
      -- A business is OURS if we converted it OR it matched a live merchant.
      -- Either way it must leave the prospecting pool.
      (c.peekaa_business_id is not null or p.converted_business_id is not null) as is_peekaa_merchant,
      coalesce(c.peekaa_business_id, p.converted_business_id) as merchant_id,
      (select max(o.contacted_at) from public.sme_outreach_records o where o.prospect_id=p.id) as last_contacted_at,
      (select min(t.due_at) from public.sme_prospect_tasks t
        where t.prospect_id=p.id and t.completed_at is null) as next_follow_up_at
      from public.sme_prospects p
      join public.sme_companies c on c.id = p.company_id
      left join public.sme_company_locations l on l.company_id=c.id and l.is_primary
      left join public.sme_company_market_facts f on f.company_id=c.id
      left join public.sme_company_sources src on src.company_id=c.id and src.source='google_places'
      left join public.sme_company_categories cc on cc.company_id=c.id and cc.is_primary
      left join public.sme_categories cat on cat.id=cc.category_id
      left join public.sme_categories parent on parent.id=cat.parent_category_id
      left join public.sme_sectors sec on sec.id=cat.sector_id
      left join public.sme_pipeline_stages st on st.stage_key=p.current_stage_key
     where p.archived_at is null
       and (v_is_admin or p.assigned_consultant_id = v_self)
  ),
  filtered as (
    select b.*, count(*) over() as total_count from base b
     where (nullif(p_filters->>'q','') is null
            or b.name ilike '%'||(p_filters->>'q')||'%'
            or coalesce(b.phone,'') ilike '%'||(p_filters->>'q')||'%'
            or coalesce(b.postal_code,'') ilike (p_filters->>'q')||'%')
       and (jsonb_array_length(coalesce(p_filters->'planning_areas','[]'::jsonb))=0
            or b.planning_area in (select jsonb_array_elements_text(p_filters->'planning_areas')))
       and (jsonb_array_length(coalesce(p_filters->'industries','[]'::jsonb))=0
            or b.industry in (select jsonb_array_elements_text(p_filters->'industries')))
       and (jsonb_array_length(coalesce(p_filters->'categories','[]'::jsonb))=0
            or b.category in (select jsonb_array_elements_text(p_filters->'categories')))
       and (jsonb_array_length(coalesce(p_filters->'subcategories','[]'::jsonb))=0
            or b.category_key in (select jsonb_array_elements_text(p_filters->'subcategories')))
       and (jsonb_array_length(coalesce(p_filters->'stage_keys','[]'::jsonb))=0
            or b.current_stage_key in (select jsonb_array_elements_text(p_filters->'stage_keys')))
       and (case coalesce(p_filters->>'peekaa_status','not_merchant')
              when 'not_merchant' then b.is_peekaa_merchant = false
              when 'merchant' then b.is_peekaa_merchant = true
              else true end)
       and (case coalesce(p_filters->>'assignment','all')
              when 'unassigned' then b.assigned_consultant_id is null
              when 'assigned' then b.assigned_consultant_id is not null
              else true end)
       and (nullif(p_filters->>'assigned_to','') is null
            or b.assigned_consultant_id = (p_filters->>'assigned_to')::uuid)
       and (case coalesce(p_filters->>'contact','all')
              when 'not_contacted' then b.last_contacted_at is null
              when 'contacted' then b.last_contacted_at is not null
              else true end)
       and (case coalesce(p_filters->>'follow_up','all')
              when 'overdue' then b.next_follow_up_at < now()
              when 'due_today' then b.next_follow_up_at::date = (now() at time zone 'Asia/Singapore')::date
              when 'scheduled' then b.next_follow_up_at is not null
              when 'none' then b.next_follow_up_at is null
              else true end)
       and (nullif(p_filters->>'business_status','') is null
            or b.business_status = p_filters->>'business_status')
       and (nullif(p_filters->>'rating_min','') is null
            or b.rating >= (p_filters->>'rating_min')::numeric)
       and (nullif(p_filters->>'review_min','') is null
            or b.review_count >= (p_filters->>'review_min')::integer)
       and (coalesce((p_filters->>'has_phone')::boolean,false) = false or b.phone is not null)
       and (coalesce((p_filters->>'has_website')::boolean,false) = false or b.website is not null)
       and (p_filters->'bbox' is null or (
             b.latitude between (p_filters#>>'{bbox,south}')::double precision
                            and (p_filters#>>'{bbox,north}')::double precision
         and b.longitude between (p_filters#>>'{bbox,west}')::double precision
                             and (p_filters#>>'{bbox,east}')::double precision))
  ),
  ordered as (
    select * from filtered
     order by
       case when p_sort='name_asc' then name end asc nulls last,
       case when p_sort='name_desc' then name end desc nulls last,
       case when p_sort='area_asc' then planning_area end asc nulls last,
       case when p_sort='category_asc' then subcategory end asc nulls last,
       case when p_sort='rating_desc' then rating end desc nulls last,
       case when p_sort='reviews_desc' then review_count end desc nulls last,
       case when p_sort='contacted_desc' then last_contacted_at end desc nulls last,
       case when p_sort='follow_up_asc' then next_follow_up_at end asc nulls last,
       case when p_sort='added_asc' then created_at end asc,
       case when p_sort='added_desc' then created_at end desc,
       name asc
     limit case when p_mode='ids' then 5000 when p_mode='count' then 1 else p_limit end
    offset case when p_mode in ('ids','count') then 0 else p_offset end
  )
  select
    coalesce(max(o.total_count)::integer, 0),
    case p_mode
      when 'count' then '[]'::jsonb
      when 'ids' then coalesce(jsonb_agg(to_jsonb(o.prospect_id)),'[]'::jsonb)
      when 'markers' then coalesce(jsonb_agg(jsonb_build_object(
        'prospect_id',o.prospect_id,'name',o.name,'lat',o.latitude,'lng',o.longitude,
        'is_peekaa_merchant',o.is_peekaa_merchant,
        'assigned',o.assigned_consultant_id is not null,
        'stage',o.current_stage_key)) filter (where o.latitude is not null),'[]'::jsonb)
      else coalesce(jsonb_agg(to_jsonb(o) - 'total_count'),'[]'::jsonb) end
  into v_total, v_rows
  from ordered o;

  return jsonb_build_object(
    'total', v_total, 'limit', p_limit, 'offset', p_offset,
    'sort', p_sort, 'mode', p_mode,
    case p_mode when 'ids' then 'ids' when 'markers' then 'markers' else 'rows' end, v_rows);
end $$;

--
-- Name: platform_finalize_quotation_v156(uuid, date, date, jsonb, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_finalize_quotation_v156(p_prospect uuid, p_issue_date date, p_expiry_date date, p_line_items jsonb, p_notes text, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'extensions', 'pg_temp'
    AS $$
declare v_actor uuid:=auth.uid();v_profile public.platform_billing_profiles_v156%rowtype;v_customer jsonb;v_commercial public.platform_crm_commercial_v156%rowtype;v_doc public.platform_subscription_documents_v156%rowtype;v_subtotal bigint;v_discount bigint;v_tax bigint;v_total bigint;v_number text;v_snapshot jsonb;v_hash text;
begin
  if v_actor is null or not app.v156_can_prospect(p_prospect,'rw') then raise exception 'CRM write access is required' using errcode='42501';end if;
  if p_expiry_date<p_issue_date or jsonb_typeof(p_line_items)<>'array' or jsonb_array_length(p_line_items)=0 then raise exception 'valid quotation dates and lines are required' using errcode='22023';end if;
  select * into v_profile from public.platform_billing_profiles_v156 order by version desc limit 1;
  if not app.v156_profile_ready(v_profile) then raise exception 'seller legal, GST and payment settings are incomplete' using errcode='22023';end if;
  v_customer:=app.v156_customer_snapshot(null,p_prospect);if v_customer is null then raise exception 'primary billing contact is required' using errcode='22023';end if;
  select * into v_commercial from public.platform_crm_commercial_v156 where prospect_id=p_prospect;
  v_subtotal:=coalesce((select sum((line->>'quantity')::numeric*(line->>'unit_amount_cents')::bigint) from jsonb_array_elements(p_line_items) line),0);
  v_discount:=coalesce(v_commercial.proposed_discount_cents,0);v_tax:=case when v_profile.gst_status='registered' then round((v_subtotal-v_discount)*v_profile.gst_rate_bps::numeric/10000) else 0 end;v_total:=v_subtotal-v_discount+v_tax;
  if v_total<=0 then raise exception 'quotation total must be positive' using errcode='22023';end if;
  v_hash:=encode(extensions.digest(jsonb_build_object('prospect',p_prospect,'issue',p_issue_date,'expiry',p_expiry_date,'lines',p_line_items,'notes',p_notes)::text,'sha256'),'hex');
  select * into v_doc from public.platform_subscription_documents_v156 where operation_key=p_idempotency_key;
  if found then if v_doc.request_hash<>v_hash then raise exception 'idempotency key conflict' using errcode='22023';end if;return jsonb_build_object('document',to_jsonb(v_doc),'replayed',true);end if;
  v_number:=app.v156_next_document_number('quotation',p_issue_date);
  v_snapshot:=jsonb_build_object('document_type','quotation','number',v_number,'issue_date',p_issue_date,'expiry_date',p_expiry_date,
    'seller',app.v156_seller_snapshot(v_profile),'customer',v_customer,'plan',v_commercial.expected_plan,
    'billing_interval',v_commercial.billing_interval,'intended_duration',v_commercial.intended_duration,
    'line_items',p_line_items,'discount_cents',v_discount,'subtotal_cents',v_subtotal,'tax_cents',v_tax,
    'total_cents',v_total,'currency','SGD','payment_received',false,'notes',nullif(btrim(p_notes),''));
  insert into public.platform_subscription_documents_v156(document_type,document_number,prospect_id,seller_profile_id,
    issue_date,expiry_date,subtotal_cents,discount_cents,tax_cents,total_cents,balance_due_cents,snapshot,snapshot_sha256,
    finalized_at,operation_key,request_hash,created_by)
  values('quotation',v_number,p_prospect,v_profile.id,p_issue_date,p_expiry_date,v_subtotal,v_discount,v_tax,v_total,v_total,
    v_snapshot,encode(extensions.digest(v_snapshot::text,'sha256'),'hex'),clock_timestamp(),p_idempotency_key,v_hash,v_actor) returning * into v_doc;
  insert into public.platform_subscription_document_events_v156(document_id,status,source_type,source_id,actor)
  values(v_doc.id,'finalized','admin',p_idempotency_key::text,v_actor);
  update public.platform_crm_commercial_v156 set quotation_status='draft',updated_by=v_actor,updated_at=clock_timestamp() where prospect_id=p_prospect;
  insert into public.sme_prospect_activities(prospect_id,consultant_id,activity_type,summary,detail,created_by)
  select p_prospect,assigned_consultant_id,'system','Quotation generated',v_number,v_actor from public.sme_prospects where id=p_prospect;
  return jsonb_build_object('document',to_jsonb(v_doc),'snapshot',v_snapshot,'replayed',false);
end $$;

--
-- Name: platform_generate_improvement_report_v82(text, uuid[], uuid, date, date, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_generate_improvement_report_v82(p_sector text DEFAULT NULL::text, p_businesses uuid[] DEFAULT NULL::uuid[], p_branch uuid DEFAULT NULL::uuid, p_from date DEFAULT (((now() AT TIME ZONE 'Asia/Singapore'::text))::date - 365), p_to date DEFAULT ((now() AT TIME ZONE 'Asia/Singapore'::text))::date, p_search text DEFAULT NULL::text, p_snapshot_at timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_from_ts timestamptz;
  v_to_ts timestamptz;
  v_midpoint timestamptz;
  v_snapshot_at timestamptz:=coalesce(p_snapshot_at,clock_timestamp());
  v_search text:=nullif(btrim(p_search),'');
  v_result jsonb;
  v_insights jsonb:='[]'::jsonb;
  v_completed integer;
  v_active integer;
  v_returning integer;
  v_rate numeric;
  v_lapsed integer;
begin
  if not app.is_super_admin() then
    raise exception 'super_admin_required' using errcode='42501';
  end if;
  if p_from is null or p_to is null or p_from>p_to then
    raise exception 'invalid_report_window' using errcode='22023';
  end if;
  if p_to-p_from>1826 then
    raise exception 'report_window_exceeds_five_years' using errcode='22023';
  end if;
  if coalesce(cardinality(p_businesses),0)>100 then
    raise exception 'business_filter_exceeds_100' using errcode='22023';
  end if;
  if p_snapshot_at is not null and p_snapshot_at>clock_timestamp()+interval '1 minute' then
    raise exception 'snapshot_cannot_be_in_the_future' using errcode='22023';
  end if;
  if p_branch is not null and not exists(
    select 1 from public.branches branch where branch.id=p_branch
  ) then
    raise exception 'branch_not_found' using errcode='22023';
  end if;
  v_from_ts:=p_from::timestamp at time zone 'Asia/Singapore';
  v_to_ts:=(p_to+1)::timestamp at time zone 'Asia/Singapore';
  v_midpoint:=v_from_ts+((v_to_ts-v_from_ts)/2);

  with selected_businesses as materialized (
    select business.id,business.name,business.industry,business.currency,
      (
        v_search is null
        or business.name ilike '%'||v_search||'%'
        or business.industry ilike '%'||v_search||'%'
        or exists(
          select 1 from public.branches branch
          where branch.business_id=business.id
            and branch.created_at<=v_snapshot_at
            and (p_branch is null or branch.id=p_branch)
            and branch.name ilike '%'||v_search||'%'
        )
      ) search_all
    from public.businesses business
    where business.is_synthetic=false and business.is_demo=false and business.created_at<=v_snapshot_at
      and (nullif(btrim(p_sector),'') is null
           or business.industry=btrim(p_sector))
      and (coalesce(cardinality(p_businesses),0)=0
           or business.id=any(p_businesses))
      and (p_branch is null or exists(
        select 1 from public.branches branch
        where branch.id=p_branch and branch.business_id=business.id
          and branch.created_at<=v_snapshot_at
      ))
      and (
        v_search is null
        or business.name ilike '%'||v_search||'%'
        or business.industry ilike '%'||v_search||'%'
        or exists(
          select 1 from public.branches branch
          where branch.business_id=business.id
            and branch.created_at<=v_snapshot_at
            and (p_branch is null or branch.id=p_branch)
            and branch.name ilike '%'||v_search||'%'
        )
        or exists(
          select 1 from public.clients client
          where client.business_id=business.id
            and client.created_at<=v_snapshot_at
            and (
              client.full_name ilike '%'||v_search||'%'
              or coalesce(client.email,'') ilike '%'||v_search||'%'
              or coalesce(client.phone,'') ilike '%'||v_search||'%'
            )
            and (p_branch is null or exists(
              select 1 from public.sales sale
              where sale.business_id=business.id and sale.client_id=client.id
                and sale.branch_id=p_branch and sale.created_at<=v_snapshot_at
                and sale.occurred_at<v_to_ts
            ))
        )
      )
  ),
  eligible_clients as materialized (
    select client.*,business.name business_name,business.industry,
           business.currency
    from selected_businesses business
    join public.clients client on client.business_id=business.id
    where client.created_at<=v_snapshot_at
      and (
        business.search_all
        or client.full_name ilike '%'||v_search||'%'
        or coalesce(client.email,'') ilike '%'||v_search||'%'
        or coalesce(client.phone,'') ilike '%'||v_search||'%'
      )
      and (p_branch is null or exists(
        select 1 from public.sales sale
        where sale.business_id=client.business_id and sale.client_id=client.id
          and sale.branch_id=p_branch and sale.created_at<=v_snapshot_at
          and sale.occurred_at<v_to_ts
      ))
  ),
  sales_scope as materialized (
    select sale.*,business.currency
    from public.sales sale
    join selected_businesses business on business.id=sale.business_id
    where sale.created_at<=v_snapshot_at
      and sale.occurred_at>=v_from_ts and sale.occurred_at<v_to_ts
      and (p_branch is null or sale.branch_id=p_branch)
      and (
        business.search_all
        or sale.client_id in(
          select client.id from eligible_clients client
          where client.business_id=sale.business_id
        )
      )
  ),
  completed_sales as materialized (
    select sale.* from sales_scope sale
    where sale.reversal_of is null and sale.amount_cents>0
      and sale.counts_as_revenue and not exists(
        select 1 from public.sales reversal
        where reversal.business_id=sale.business_id
          and reversal.reversal_of=sale.id
          and reversal.created_at<=v_snapshot_at
          and reversal.occurred_at<v_to_ts
      )
  ),
  visit_sales as materialized (
    select sale.* from sales_scope sale
    where sale.reversal_of is null and sale.amount_cents>0
      and sale.counts_as_visit and not exists(
        select 1 from public.sales reversal
        where reversal.business_id=sale.business_id
          and reversal.reversal_of=sale.id
          and reversal.created_at<=v_snapshot_at
          and reversal.occurred_at<v_to_ts
      )
  ),
  payment_scope as materialized (
    select payment.*,business.currency,
           coalesce(payment.client_id,linked_sale.client_id) resolved_client_id
    from public.payments payment
    join selected_businesses business on business.id=payment.business_id
    left join public.sales linked_sale
      on linked_sale.id=payment.sale_id
     and linked_sale.business_id=payment.business_id
    where payment.created_at<=v_snapshot_at
      and payment.occurred_at>=v_from_ts and payment.occurred_at<v_to_ts
      and (p_branch is null or payment.branch_id=p_branch)
      and (
        business.search_all
        or coalesce(payment.client_id,linked_sale.client_id) in(
          select client.id from eligible_clients client
          where client.business_id=payment.business_id
        )
      )
  ),
  period_customers as materialized (
    select client.id client_id,client.business_id,client.business_name,
      client.industry,client.currency,client.full_name,client.email,client.phone,
      client.created_at customer_since,
      coalesce(sum(sale.amount_cents)
        filter(where sale.counts_as_revenue),0)::bigint net_revenue_cents,
      count(*) filter(
        where sale.id is not null and sale.reversal_of is null
          and sale.amount_cents>0 and sale.counts_as_revenue
          and not exists(
            select 1 from public.sales reversal
            where reversal.business_id=sale.business_id
              and reversal.reversal_of=sale.id
              and reversal.created_at<=v_snapshot_at
              and reversal.occurred_at<v_to_ts
          )
      )::integer completed_transactions,
      count(*) filter(
        where sale.id is not null and sale.reversal_of is null
          and sale.amount_cents>0 and sale.counts_as_visit
          and not exists(
            select 1 from public.sales reversal
            where reversal.business_id=sale.business_id
              and reversal.reversal_of=sale.id
              and reversal.created_at<=v_snapshot_at
              and reversal.occurred_at<v_to_ts
          )
      )::integer visit_count,
      min(sale.occurred_at) filter(
        where sale.reversal_of is null and sale.amount_cents>0
          and sale.counts_as_revenue and not exists(
            select 1 from public.sales reversal
            where reversal.business_id=sale.business_id
              and reversal.reversal_of=sale.id
              and reversal.created_at<=v_snapshot_at
              and reversal.occurred_at<v_to_ts
          )
      ) period_first_purchase_at,
      max(sale.occurred_at) filter(
        where sale.reversal_of is null and sale.amount_cents>0
          and sale.counts_as_revenue and not exists(
            select 1 from public.sales reversal
            where reversal.business_id=sale.business_id
              and reversal.reversal_of=sale.id
              and reversal.created_at<=v_snapshot_at
              and reversal.occurred_at<v_to_ts
          )
      ) period_last_purchase_at
    from eligible_clients client
    left join sales_scope sale
      on sale.business_id=client.business_id and sale.client_id=client.id
    group by client.id,client.business_id,client.business_name,client.industry,
             client.currency,client.full_name,client.email,client.phone,
             client.created_at
  ),
  customer_metrics as materialized (
    select customer.*,
      coalesce((
        select sum(payment.amount_cents)
          filter(where payment.method not in('credit','gift_card'))
        from payment_scope payment
        where payment.business_id=customer.business_id
          and payment.resolved_client_id=customer.client_id
      ),0)::bigint cash_collected_cents,
      lifetime.first_purchase_at,lifetime.last_purchase_at,
      case when lifetime.last_purchase_at is null then null
        else p_to-(lifetime.last_purchase_at at time zone 'Asia/Singapore')::date
      end days_since_last_purchase
    from period_customers customer
    left join lateral(
      select min(sale.occurred_at) first_purchase_at,
             max(sale.occurred_at) last_purchase_at
      from public.sales sale
      where sale.business_id=customer.business_id
        and sale.client_id=customer.client_id
        and sale.created_at<=v_snapshot_at and sale.occurred_at<v_to_ts
        and (p_branch is null or sale.branch_id=p_branch)
        and sale.reversal_of is null and sale.amount_cents>0
        and sale.counts_as_revenue and not exists(
          select 1 from public.sales reversal
          where reversal.business_id=sale.business_id
            and reversal.reversal_of=sale.id
            and reversal.created_at<=v_snapshot_at
            and reversal.occurred_at<v_to_ts
        )
    ) lifetime on true
  ),
  currency_metrics as materialized (
    select business.currency,
      coalesce((
        select sum(sale.amount_cents)
          filter(where sale.counts_as_revenue)
        from sales_scope sale where sale.currency=business.currency
      ),0)::bigint net_revenue_cents,
      coalesce((
        select sum(payment.amount_cents)
          filter(where payment.method not in('credit','gift_card'))
        from payment_scope payment where payment.currency=business.currency
      ),0)::bigint cash_collected_cents,
      (select count(*) from completed_sales sale
        where sale.currency=business.currency)::integer completed_transactions,
      (select count(*) from customer_metrics customer
        where customer.currency=business.currency
          and customer.visit_count>0)::integer active_customers,
      (select count(*) from customer_metrics customer
        where customer.currency=business.currency
          and customer.visit_count>=2)::integer returning_customers,
      (select count(*) from customer_metrics customer
        where customer.currency=business.currency
          and customer.days_since_last_purchase>90)::integer lapsed_customers,
      coalesce((
        select sum(sale.amount_cents)
          filter(where sale.counts_as_revenue and sale.occurred_at<v_midpoint)
        from sales_scope sale where sale.currency=business.currency
      ),0)::bigint previous_half_revenue_cents,
      coalesce((
        select sum(sale.amount_cents)
          filter(where sale.counts_as_revenue and sale.occurred_at>=v_midpoint)
        from sales_scope sale where sale.currency=business.currency
      ),0)::bigint current_half_revenue_cents
    from (select distinct currency from selected_businesses) business
  ),
  business_metrics as materialized (
    select business.id business_id,business.name,business.industry,
      business.currency,
      coalesce(sum(sale.amount_cents)
        filter(where sale.counts_as_revenue),0)::bigint net_revenue_cents,
      count(*) filter(
        where sale.reversal_of is null and sale.amount_cents>0
          and sale.counts_as_revenue and not exists(
            select 1 from public.sales reversal
            where reversal.business_id=sale.business_id
              and reversal.reversal_of=sale.id
              and reversal.created_at<=v_snapshot_at
              and reversal.occurred_at<v_to_ts
          )
      )::integer completed_transactions,
      (select count(*) from customer_metrics customer
        where customer.business_id=business.id
          and customer.visit_count>0)::integer active_customers,
      (select count(*) from customer_metrics customer
        where customer.business_id=business.id
          and customer.visit_count>=2)::integer returning_customers
    from selected_businesses business
    left join sales_scope sale on sale.business_id=business.id
    group by business.id,business.name,business.industry,business.currency
  ),
  branch_metrics as materialized (
    select branch.id branch_id,branch.business_id,business.name business_name,
      business.currency,branch.name,branch.active,
      coalesce(sum(sale.amount_cents)
        filter(where sale.counts_as_revenue),0)::bigint net_revenue_cents,
      count(*) filter(
        where sale.reversal_of is null and sale.amount_cents>0
          and sale.counts_as_revenue and not exists(
            select 1 from public.sales reversal
            where reversal.business_id=sale.business_id
              and reversal.reversal_of=sale.id
              and reversal.created_at<=v_snapshot_at
              and reversal.occurred_at<v_to_ts
          )
      )::integer completed_transactions,
      count(distinct sale.client_id) filter(
        where sale.reversal_of is null and sale.amount_cents>0
          and sale.counts_as_visit
          and not exists(
            select 1 from public.sales reversal
            where reversal.business_id=sale.business_id
              and reversal.reversal_of=sale.id
              and reversal.created_at<=v_snapshot_at
              and reversal.occurred_at<v_to_ts
          )
      )::integer active_customers
    from selected_businesses business
    join public.branches branch on branch.business_id=business.id
      and branch.created_at<=v_snapshot_at
    left join sales_scope sale
      on sale.business_id=branch.business_id and sale.branch_id=branch.id
    where p_branch is null or branch.id=p_branch
    group by branch.id,branch.business_id,business.name,business.currency,
             branch.name,branch.active
  ),
  month_series as (
    select month_start::date from generate_series(
      date_trunc('month',v_from_ts at time zone 'Asia/Singapore')::date,
      date_trunc('month',(v_to_ts-interval '1 millisecond')
        at time zone 'Asia/Singapore')::date,
      interval '1 month'
    ) month_start
  ),
  monthly as materialized (
    select month.month_start,currency.currency,
      coalesce(sum(sale.amount_cents)
        filter(where sale.counts_as_revenue),0)::bigint net_revenue_cents,
      count(*) filter(
        where sale.reversal_of is null and sale.amount_cents>0
          and sale.counts_as_revenue
          and not exists(
            select 1 from public.sales reversal
            where reversal.business_id=sale.business_id
              and reversal.reversal_of=sale.id
              and reversal.created_at<=v_snapshot_at
              and reversal.occurred_at<v_to_ts
          )
      )::integer transactions,
      count(distinct sale.client_id)
        filter(where sale.client_id is not null
          and sale.reversal_of is null and sale.amount_cents>0
          and sale.counts_as_visit
          and not exists(
            select 1 from public.sales reversal
            where reversal.business_id=sale.business_id
              and reversal.reversal_of=sale.id
              and reversal.created_at<=v_snapshot_at
              and reversal.occurred_at<v_to_ts
          ))::integer active_customers
    from month_series month
    cross join (select distinct currency from selected_businesses) currency
    left join sales_scope sale on sale.currency=currency.currency
      and (sale.occurred_at at time zone 'Asia/Singapore')::date
        >=month.month_start
      and (sale.occurred_at at time zone 'Asia/Singapore')::date
        <(month.month_start+interval '1 month')::date
    group by month.month_start,currency.currency
  )
  select jsonb_build_object(
    'generated_at',v_snapshot_at,'snapshot_at',v_snapshot_at,
    'methodology',jsonb_build_object(
      'timezone','Asia/Singapore',
      'revenue','net immutable sales-ledger events in the selected period',
      'cash','payment ledger including refunds, excluding credit and gift-card tenders',
      'returning_customer','at least two unreversed visit-counting sales in the selected period',
      'returning_rate_denominator','customers with at least one visit in the selected period',
      'lapsed_customer','lifetime last unreversed revenue purchase as of report end is more than 90 days old',
      'search','firm or branch match includes its whole scope; otherwise only matching customers and their transactions',
      'currency','money aggregates are calculated independently by currency'
    ),
    'scope',jsonb_build_object(
      'sector',nullif(btrim(p_sector),''),
      'business_ids',coalesce(to_jsonb(p_businesses),'[]'::jsonb),
      'branch_id',p_branch,'from',p_from,'to',p_to,'search',v_search,
      'days',(p_to-p_from)+1,'firm_count',(select count(*) from selected_businesses),
      'branch_count',(select count(*) from branch_metrics),
      'customer_count',(select count(*) from customer_metrics)
    ),
    'summary',jsonb_build_object(
      'currency_mode',case when (select count(*) from currency_metrics)<=1
        then 'single' else 'multiple' end,
      'currency',case when (select count(*) from currency_metrics)=1
        then (select currency from currency_metrics limit 1) else null end,
      'net_revenue_cents',case when (select count(*) from currency_metrics)=1
        then (select net_revenue_cents from currency_metrics limit 1) else null end,
      'cash_collected_cents',case when (select count(*) from currency_metrics)=1
        then (select cash_collected_cents from currency_metrics limit 1) else null end,
      'completed_transactions',(select count(*) from completed_sales),
      'active_customers',(select count(*) from customer_metrics where visit_count>0),
      'returning_customers',(select count(*) from customer_metrics where visit_count>=2),
      'returning_rate_pct',case
        when (select count(*) from customer_metrics where visit_count>0)=0 then 0
        else round(100.0*(select count(*) from customer_metrics where visit_count>=2)
          /(select count(*) from customer_metrics where visit_count>0),1) end,
      'lapsed_customers',(select count(*) from customer_metrics
        where days_since_last_purchase>90)
    ),
    'summary_by_currency',coalesce((
      select jsonb_agg(to_jsonb(metric)||jsonb_build_object(
        'returning_rate_pct',case when metric.active_customers=0 then 0
          else round(100.0*metric.returning_customers/metric.active_customers,1) end,
        'average_revenue_per_active_customer_cents',
          case when metric.active_customers=0 then 0
          else round(metric.net_revenue_cents::numeric/metric.active_customers)::bigint end
      ) order by metric.currency)
      from currency_metrics metric
    ),'[]'::jsonb),
    'businesses',coalesce((
      select jsonb_agg(to_jsonb(metric)
        order by metric.currency,metric.net_revenue_cents desc,metric.name)
      from business_metrics metric
    ),'[]'::jsonb),
    'branches',coalesce((
      select jsonb_agg(to_jsonb(metric)
        order by metric.currency,metric.net_revenue_cents desc,
                 metric.business_name,metric.name)
      from branch_metrics metric
    ),'[]'::jsonb),
    'monthly_trend',coalesce((
      select jsonb_agg(to_jsonb(metric)
        order by metric.month_start,metric.currency)
      from monthly metric
    ),'[]'::jsonb),
    'customer_total',(select count(*) from customer_metrics)
  ) into v_result;

  v_completed:=coalesce((v_result#>>'{summary,completed_transactions}')::integer,0);
  v_active:=coalesce((v_result#>>'{summary,active_customers}')::integer,0);
  v_returning:=coalesce((v_result#>>'{summary,returning_customers}')::integer,0);
  v_rate:=coalesce((v_result#>>'{summary,returning_rate_pct}')::numeric,0);
  v_lapsed:=coalesce((v_result#>>'{summary,lapsed_customers}')::integer,0);
  if v_completed<30 then
    v_insights:=v_insights||jsonb_build_array(jsonb_build_object(
      'key','data_foundation','priority','foundation',
      'title','Build a larger transaction baseline',
      'evidence',jsonb_build_object('completed_transactions',v_completed,'target',30),
      'recommendation','Wait for at least 30 completed transactions in this exact scope before treating movement as a durable trend.'
    ));
  end if;
  if v_active>=5 and v_rate<30 then
    v_insights:=v_insights||jsonb_build_array(jsonb_build_object(
      'key','repeat_visit_gap','priority','high',
      'title','Strengthen the second-visit journey',
      'evidence',jsonb_build_object('active_customers',v_active,
        'returning_customers',v_returning,'returning_rate_pct',v_rate),
      'recommendation','Give first-time customers one clear next-visit action and measure conversion to a second completed visit.'
    ));
  end if;
  if v_lapsed>0 then
    v_insights:=v_insights||jsonb_build_array(jsonb_build_object(
      'key','lapsed_customers','priority','medium',
      'title','Create a lapsed-customer recovery queue',
      'evidence',jsonb_build_object('customers_over_90_days',v_lapsed),
      'recommendation','Prioritise customers whose lifetime last completed purchase is over 90 days old.'
    ));
  end if;
  if exists(
    select 1 from jsonb_to_recordset(v_result->'summary_by_currency')
      as currency(currency text,previous_half_revenue_cents bigint,
        current_half_revenue_cents bigint)
    where currency.previous_half_revenue_cents>0
      and currency.current_half_revenue_cents<currency.previous_half_revenue_cents
  ) then
    v_insights:=v_insights||jsonb_build_array(jsonb_build_object(
      'key','revenue_momentum_by_currency','priority','high',
      'title','Investigate recent revenue slowdowns',
      'evidence',jsonb_build_object(
        'currencies',(
          select jsonb_agg(to_jsonb(currency))
          from jsonb_to_recordset(v_result->'summary_by_currency')
            as currency(currency text,previous_half_revenue_cents bigint,
              current_half_revenue_cents bigint)
          where currency.previous_half_revenue_cents>0
            and currency.current_half_revenue_cents
              <currency.previous_half_revenue_cents
        )
      ),
      'recommendation','Compare branch and customer movement inside each currency; never combine unlike currencies.'
    ));
  end if;
  if jsonb_array_length(v_insights)=0 then
    v_insights:=jsonb_build_array(jsonb_build_object(
      'key','maintain_and_test','priority','monitor',
      'title','Maintain the baseline and test one improvement',
      'evidence',jsonb_build_object('completed_transactions',v_completed,
        'returning_rate_pct',v_rate),
      'recommendation','Keep this exact scope and date window as the baseline, then measure one controlled retention change.'
    ));
  end if;
  return v_result||jsonb_build_object('insights',v_insights);
end
$$;

--
-- Name: FUNCTION platform_generate_improvement_report_v82(p_sector text, p_businesses uuid[], p_branch uuid, p_from date, p_to date, p_search text, p_snapshot_at timestamp with time zone); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.platform_generate_improvement_report_v82(p_sector text, p_businesses uuid[], p_branch uuid, p_from date, p_to date, p_search text, p_snapshot_at timestamp with time zone) IS 'v92: enterprise improvement reports exclude structurally synthetic businesses.';

--
-- Name: platform_generate_my_report_v89(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_generate_my_report_v89(p_business_ids uuid[]) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_ids uuid[];v_result jsonb;
begin
  if not app.v89_platform_can('reports','r') then
    raise exception 'platform reports access is required' using errcode='42501';
  end if;
  select coalesce(array_agg(distinct requested.id order by requested.id),'{}'::uuid[])
    into v_ids from unnest(coalesce(p_business_ids,'{}'::uuid[])) requested(id);
  if cardinality(v_ids)=0 or exists(select 1 from unnest(v_ids) id
    where not app.v89_business_in_role_scope(id)) then
    raise exception 'report contains an out-of-scope business' using errcode='42501';
  end if;
  select jsonb_build_object(
    'scope',jsonb_build_object('business_ids',to_jsonb(v_ids),
      'generated_at',now(),'currency','SGD'),
    'summary',jsonb_build_object(
      'business_count',cardinality(v_ids),
      'customer_count',(select count(*) from public.clients where business_id=any(v_ids)),
      'sales_count',(select count(*) from public.sales where business_id=any(v_ids)
        and reversal_of is null),
      'revenue_cents',coalesce((select sum(amount_cents)::bigint
        from public.sales where business_id=any(v_ids)
          and reversal_of is null and counts_as_revenue),0),
      'appointment_count',(select count(*) from public.appointments
        where business_id=any(v_ids)),
      'completed_appointments',(select count(*) from public.appointments
        where business_id=any(v_ids) and status='completed')
    ),
    'businesses',coalesce((select jsonb_agg(jsonb_build_object(
      'id',business.id,'name',business.name,'industry',business.industry,
      'customers',(select count(*) from public.clients where business_id=business.id),
      'revenue_cents',coalesce((select sum(amount_cents)::bigint
        from public.sales where business_id=business.id
          and reversal_of is null and counts_as_revenue),0)
    ) order by lower(business.name),business.id)
      from public.businesses business where business.id=any(v_ids)),'[]'::jsonb)
  ) into v_result;
  return v_result;
end
$$;

--
-- Name: platform_generate_subscription_reminders_v156(date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_generate_subscription_reminders_v156(p_as_of date DEFAULT ((clock_timestamp() AT TIME ZONE 'Asia/Singapore'::text))::date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare r record;v_count integer:=0;v_day integer;v_prospect uuid;
begin
  if auth.uid() is not null and not app.v156_can('rw') then raise exception 'billing write access is required' using errcode='42501';end if;
  for r in select subscription.* from public.billing_provider_subscriptions subscription where subscription.status in ('active','trialing','past_due') loop
    select id into v_prospect from public.sme_prospects where converted_business_id=r.business_id order by converted_at desc nulls last limit 1;
    if r.status='past_due' then perform app.v156_upsert_task('past-due:'||r.provider_subscription_id,'past_due',r.business_id,v_prospect,r.provider_subscription_id,null,'urgent',p_as_of::timestamptz,'Subscription payment is past due',null);v_count:=v_count+1;end if;
    if r.cadence='annual' and r.current_period_end is not null then
      v_day:=((r.current_period_end at time zone 'Asia/Singapore')::date-p_as_of);
      if v_day in (30,14,7) then perform app.v156_upsert_task('renewal-'||v_day||':'||r.provider_subscription_id||':'||(r.current_period_end::date),'renewal_'||v_day,r.business_id,v_prospect,r.provider_subscription_id,null,case when v_day=7 then 'high' else 'normal' end,p_as_of::timestamptz,'Annual subscription renews in '||v_day||' days',null);v_count:=v_count+1;end if;
    end if;
  end loop;
  return jsonb_build_object('created_or_refreshed',v_count,'as_of',p_as_of);
end $$;

--
-- Name: platform_get_accounting_books_v147(date, date, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_get_accounting_books_v147(p_from date, p_to date, p_limit integer DEFAULT 5000) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_count bigint;v_document_count bigint;v_policy jsonb;begin
  if auth.uid() is null or not app.is_super_admin() then raise exception 'super-admin access is required' using errcode='42501';end if;
  if p_from is null or p_to<p_from or p_to-p_from>1826 or p_limit not between 1 and 5000 then raise exception 'valid accounting range and limit are required' using errcode='22023';end if;
  select count(*) into v_count from public.platform_accounting_journal_entries_v147 where journal_date between p_from and p_to;
  select count(*) into v_document_count from public.platform_financial_documents_v147 where issue_date between p_from and p_to;
  select to_jsonb(policy)-'created_by' into v_policy from public.platform_accounting_policies_v147 policy where effective_from<=p_to order by effective_from desc,version desc limit 1;
  return jsonb_build_object('from',p_from,'to',p_to,'currency','SGD','policy',v_policy,
    'row_counts',jsonb_build_object('journals',v_count,'documents',v_document_count),
    'complete',jsonb_build_object('journals',v_count<=p_limit,'documents',v_document_count<=p_limit),
    'summary',(select jsonb_build_object(
      'revenue_cents',coalesce(sum(case when account.account_type='revenue' and entry.journal_date between p_from and p_to then line.credit_cents-line.debit_cents else 0 end),0),
      'expense_cents',coalesce(sum(case when account.account_type='expense' and entry.journal_date between p_from and p_to then line.debit_cents-line.credit_cents else 0 end),0),
      'profit_cents',coalesce(sum(case when account.account_type='revenue' and entry.journal_date between p_from and p_to then line.credit_cents-line.debit_cents when account.account_type='expense' and entry.journal_date between p_from and p_to then line.credit_cents-line.debit_cents else 0 end),0),
      'assets_cents',coalesce(sum(case when account.account_type='asset' then line.debit_cents-line.credit_cents else 0 end),0),
      'liabilities_cents',coalesce(sum(case when account.account_type='liability' then line.credit_cents-line.debit_cents else 0 end),0),
      'equity_and_current_profit_cents',coalesce(sum(case when account.account_type='equity' then line.credit_cents-line.debit_cents when account.account_type='revenue' then line.credit_cents-line.debit_cents when account.account_type='expense' then line.credit_cents-line.debit_cents else 0 end),0))
      from public.platform_accounting_journal_lines_v147 line join public.platform_accounting_journal_entries_v147 entry on entry.id=line.entry_id join public.platform_accounting_accounts_v147 account on account.code=line.account_code where entry.journal_date<=p_to),
    'trial_balance',coalesce((select jsonb_agg(to_jsonb(rows) order by rows.code) from (
      select account.code,account.name,account.account_type,account.normal_balance,
        coalesce(sum(line.debit_cents) filter(where entry.journal_date<p_from),0) opening_debits_cents,
        coalesce(sum(line.credit_cents) filter(where entry.journal_date<p_from),0) opening_credits_cents,
        coalesce(sum(line.debit_cents) filter(where entry.journal_date between p_from and p_to),0) period_debits_cents,
        coalesce(sum(line.credit_cents) filter(where entry.journal_date between p_from and p_to),0) period_credits_cents,
        coalesce(sum(line.debit_cents-line.credit_cents) filter(where entry.journal_date<=p_to),0) closing_debit_net_cents
      from public.platform_accounting_accounts_v147 account left join public.platform_accounting_journal_lines_v147 line on line.account_code=account.code left join public.platform_accounting_journal_entries_v147 entry on entry.id=line.entry_id group by account.code,account.name,account.account_type,account.normal_balance
    ) rows),'[]'::jsonb),
    'journals',coalesce((select jsonb_agg(to_jsonb(rows) order by rows.journal_date desc,rows.journal_number desc) from (
      select entry.id,entry.journal_number,entry.journal_date,entry.description,entry.source_type,entry.source_id,entry.reversal_of,entry.created_at,
        (select jsonb_agg(jsonb_build_object('line_number',line.line_number,'account_code',line.account_code,'account_name',account.name,'debit_cents',line.debit_cents,'credit_cents',line.credit_cents,'memo',line.memo,'counterparty',line.counterparty) order by line.line_number) from public.platform_accounting_journal_lines_v147 line join public.platform_accounting_accounts_v147 account on account.code=line.account_code where line.entry_id=entry.id) lines
      from public.platform_accounting_journal_entries_v147 entry where entry.journal_date between p_from and p_to order by entry.journal_date desc,entry.journal_number desc limit p_limit
    ) rows),'[]'::jsonb),
    'documents',coalesce((select jsonb_agg(to_jsonb(rows) order by rows.issue_date desc,rows.document_number desc) from (
      select document.id,document.document_type,document.document_number,document.issue_date,document.due_date,document.currency,document.counterparty,document.line_items,document.subtotal_cents,document.tax_cents,document.total_cents,document.original_document,document.journal_entry,document.snapshot,document.snapshot_sha256,document.created_at,
        exists(select 1 from public.platform_financial_documents_v147 reversal where reversal.original_document=document.id and reversal.document_type='journal_voucher') reversed,
        case when document.document_type='invoice' then greatest(0,document.total_cents
          +coalesce((select sum(child.total_cents) from public.platform_financial_documents_v147 child where child.original_document=document.id and child.document_type='debit_note' and not exists(select 1 from public.platform_financial_documents_v147 child_reversal where child_reversal.original_document=child.id and child_reversal.document_type='journal_voucher')),0)
          -coalesce((select sum(child.total_cents) from public.platform_financial_documents_v147 child where child.original_document=document.id and child.document_type='receipt' and not exists(select 1 from public.platform_financial_documents_v147 child_reversal where child_reversal.original_document=child.id and child_reversal.document_type='journal_voucher')),0)
          -coalesce((select sum(child.total_cents) from public.platform_financial_documents_v147 child where child.original_document=document.id and child.document_type='credit_note' and not exists(select 1 from public.platform_financial_documents_v147 child_reversal where child_reversal.original_document=child.id and child_reversal.document_type='journal_voucher')),0)) else null end outstanding_cents
      from public.platform_financial_documents_v147 document where document.issue_date between p_from and p_to order by document.issue_date desc,document.document_number desc limit p_limit
    ) rows),'[]'::jsonb),
    'period_locked',exists(select 1 from generate_series(p_from,p_to,'1 day'::interval) day where app.platform_accounting_date_locked_v147(day::date)));
end
$$;

--
-- Name: platform_get_assigned_firm_report_v94(uuid, uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_get_assigned_firm_report_v94(p_business uuid, p_branch uuid, p_from date, p_to date) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_result jsonb;v_from timestamptz;v_to timestamptz;
begin
  if not app.platform_firm_report_access_v94(p_business) then
    raise exception 'assigned_platform_report_access_required' using errcode='42501';
  end if;
  if p_from is null or p_to is null or p_from>p_to or p_to-p_from>1826 then
    raise exception 'invalid_report_window' using errcode='22023';
  end if;
  if p_branch is not null and not exists(
    select 1 from public.branches branch
    where branch.id=p_branch and branch.business_id=p_business
  ) then raise exception 'branch_not_in_business' using errcode='22023';end if;
  v_from:=p_from::timestamp at time zone 'Asia/Singapore';
  v_to:=(p_to+1)::timestamp at time zone 'Asia/Singapore';
  with valid_sales as (
    select sale.*
    from public.sales sale
    where sale.business_id=p_business and sale.reversal_of is null
      and sale.occurred_at>=v_from and sale.occurred_at<v_to
      and (p_branch is null or sale.branch_id=p_branch)
      and not exists(
        select 1 from public.sales reversal
        where reversal.business_id=sale.business_id
          and reversal.reversal_of=sale.id
      )
  ), customer_metrics as (
    select client.id,count(valid_sales.id) purchases,
      coalesce(sum(valid_sales.amount_cents),0) revenue_cents,
      min(valid_sales.occurred_at) first_purchase_at,
      max(valid_sales.occurred_at) last_purchase_at
    from public.clients client
    left join valid_sales on valid_sales.client_id=client.id
    where client.business_id=p_business and client.is_synthetic=false
    group by client.id
  ), classified as (
    select customer_metrics.*,
      case
        when purchases=1
          and first_purchase_at>=(p_to-29)::timestamp at time zone 'Asia/Singapore'
          then 'new'
        when purchases>=5
          and last_purchase_at>=(p_to-29)::timestamp at time zone 'Asia/Singapore'
          then 'champions'
        when purchases>=2
          and last_purchase_at>=(p_to-59)::timestamp at time zone 'Asia/Singapore'
          then 'loyal'
        when purchases>=2
          and last_purchase_at>=(p_to-89)::timestamp at time zone 'Asia/Singapore'
          then 'at_risk'
        when last_purchase_at<(p_to-89)::timestamp at time zone 'Asia/Singapore'
          then 'lapsed'
        else 'other'
      end cohort
    from customer_metrics
  ), preference_rows as (
    select item.item_type,item.ref_id,
      coalesce(
        max(case when item.item_type='service' then service.name
                 when item.item_type='retail' then product.name end),
        max(item.description),'Unlabelled item'
      ) item_name,
      count(distinct item.sale_id) orders,sum(item.qty) units,
      sum(item.line_cents) revenue_cents
    from public.sale_items item
    join valid_sales sale on sale.id=item.sale_id
    left join public.services service
      on item.item_type='service' and service.id=item.ref_id
        and service.business_id=p_business
    left join public.products product
      on item.item_type='retail' and product.id=item.ref_id
        and product.business_id=p_business
    where item.business_id=p_business
      and item.item_type in ('service','retail')
    group by item.item_type,item.ref_id
  ), ranked_preferences as (
    select preference_rows.*,
      row_number() over(
        partition by item_type
        order by orders desc,revenue_cents desc,ref_id nulls last,item_name
      ) preference_rank
    from preference_rows
  ), preferences as (
    select
      coalesce(jsonb_agg(jsonb_build_object(
        'item_id',ref_id,'name',item_name,'orders',orders,'units',units,
        'revenue_cents',revenue_cents
      ) order by preference_rank) filter(
        where item_type='service' and preference_rank<=5
      ),'[]'::jsonb) services,
      coalesce(jsonb_agg(jsonb_build_object(
        'item_id',ref_id,'name',item_name,'orders',orders,'units',units,
        'revenue_cents',revenue_cents
      ) order by preference_rank) filter(
        where item_type='retail' and preference_rank<=5
      ),'[]'::jsonb) products
    from ranked_preferences
  )
  select jsonb_build_object(
    'scope',jsonb_build_object(
      'business_id',business.id,'business_name',business.name,
      'branch_id',p_branch,'from',p_from,'to',p_to
    ),
    'kpis',jsonb_build_object(
      'net_revenue_cents',coalesce((select sum(amount_cents)
        from valid_sales where counts_as_revenue),0),
      'visits',(select count(*) from valid_sales where counts_as_visit),
      'active_customers',(select count(*) from customer_metrics where purchases>0),
      'returning_customers',(select count(*) from customer_metrics where purchases>=2),
      'average_order_cents',coalesce((select round(avg(amount_cents))::bigint
        from valid_sales where counts_as_revenue),0)
    ),
    'cohorts',jsonb_build_object(
      'definitions',jsonb_build_object(
        'champions','5+ purchases; last purchase in final 30 days',
        'loyal','2-4 purchases; last purchase in final 60 days',
        'at_risk','2+ purchases; last purchase 61-90 days before report end',
        'new','exactly 1 purchase; first purchase in final 30 days',
        'lapsed','last purchase more than 90 days before report end',
        'other','does not meet a named cohort'
      ),
      'counts',jsonb_build_object(
        'champions',(select count(*) from classified where cohort='champions'),
        'loyal',(select count(*) from classified where cohort='loyal'),
        'at_risk',(select count(*) from classified where cohort='at_risk'),
        'new',(select count(*) from classified where cohort='new'),
        'lapsed',(select count(*) from classified where cohort='lapsed'),
        'other',(select count(*) from classified where cohort='other')
      )
    ),
    'preferences',jsonb_build_object(
      'services',preferences.services,'products',preferences.products
    ),
    'customer_intelligence',jsonb_build_object(
      'total_customers',(select count(*) from customer_metrics),
      'customers_with_purchase',(select count(*) from customer_metrics where purchases>0),
      'customers_over_90_days_inactive',(select count(*) from classified
        where cohort='lapsed'),
      'top_customer_revenue_cents',coalesce((select max(revenue_cents)
        from customer_metrics),0)
    ),
    'data_quality',jsonb_build_object(
      'synthetic_excluded',true,'reversed_sales_excluded',true,
      'timezone','Asia/Singapore','cohort_anchor',p_to
    )
  ) into v_result
  from public.businesses business cross join preferences
  where business.id=p_business;
  return v_result;
end
$$;

