--
-- Name: platform_get_business_application_v95(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_get_business_application_v95(p_application uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_result jsonb;
begin
  if not app.is_super_admin() then
    raise exception 'super_admin_required' using errcode='42501';
  end if;
  select jsonb_build_object(
    'application',jsonb_build_object(
      'id',application.id,'public_reference',application.public_reference,
      'contact_name',application.contact_name,
      'contact_email',application.contact_email,
      'contact_phone',application.contact_phone,
      'business_name',application.business_name,
      'sector_key',application.sector_key,
      'registration_number',application.registration_number,
      'preferred_locale',application.preferred_locale,
      'status',application.status,'version',application.version,
      'decision_reason',application.decision_reason,
      'submitted_at',application.created_at,
      'decided_at',application.decided_at,
      'consumed_business_id',application.consumed_business_id,
      'consumed_at',application.consumed_at
    ),
    'invitation',case when invitation.id is null then null
      else jsonb_build_object(
        'id',invitation.id,'issued_at',invitation.issued_at,
        'expires_at',invitation.expires_at,
        'revoked_at',invitation.revoked_at,
        'consumed_at',invitation.consumed_at,
        'business_id',invitation.business_id
      ) end,
    'audit',coalesce((
      select jsonb_agg(jsonb_build_object(
        'event_type',audit.event_type,'prior_status',audit.prior_status,
        'new_status',audit.new_status,'reason',audit.reason,
        'created_at',audit.created_at
      ) order by audit.created_at,audit.id)
      from public.business_application_audit_v95 audit
      where audit.application_id=application.id
    ),'[]'::jsonb)
  ) into v_result
  from public.business_applications_v95 application
  left join lateral(
    select invitation_row.*
    from public.business_application_invitations_v95 invitation_row
    where invitation_row.application_id=application.id
    order by invitation_row.issued_at desc,invitation_row.id desc
    limit 1
  ) invitation on true
  where application.id=p_application;
  if v_result is null then raise exception 'application_not_found'
    using errcode='22023';end if;
  return v_result;
end
$$;

--
-- Name: platform_get_business_control_v94(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_get_business_control_v94(p_business uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_result jsonb;
begin
  if not app.is_super_admin()
     and not app.platform_firm_report_access_v94(p_business)
     and not exists(
       select 1 from public.staff active_staff
       where active_staff.business_id=p_business
         and active_staff.user_id=auth.uid()
         and active_staff.active
     ) then
    raise exception 'business_control_access_required' using errcode='42501';
  end if;
  select jsonb_build_object(
    'business_id',business.id,
    'approval',jsonb_build_object(
      'status',control.approval_status,'version',control.version,
      'decided_at',control.decided_at,'decided_by',control.decided_by,
      'reason',control.decision_reason
    ),
    'subscription',jsonb_build_object(
      'state',lifecycle.state,'due_date',lifecycle.due_date,
      'overdue_day',lifecycle.overdue_day,
      'workspace_paused',lifecycle.workspace_paused,
      'paused_at',lifecycle.paused_at,'recovered_at',lifecycle.recovered_at,
      'version',lifecycle.version
    ),
    'workspace_access',app.business_workspace_open_v94(business.id),
    'representative',case when representative.consultant_id is null then null
      else jsonb_build_object(
        'consultant_id',representative.consultant_id,
        'display_name',representative.display_name,
        'hotline_phone',representative.hotline_phone
      ) end,
    'catalogue_intelligence',jsonb_build_object(
      'enabled',setting.catalogue_intelligence_enabled,
      'version',setting.version,'updated_at',setting.updated_at
    ),
    'quick_earn_catalogue_enabled',
      checkout_setting.platform_allowed and checkout_setting.owner_enabled,
    'checkout_catalogue',jsonb_build_object(
      'platform_allowed',checkout_setting.platform_allowed,
      'owner_enabled',checkout_setting.owner_enabled,
      'enabled',
        checkout_setting.platform_allowed and checkout_setting.owner_enabled,
      'version',checkout_setting.version,
      'updated_at',checkout_setting.updated_at
    )
  ) into v_result
  from public.businesses business
  join public.business_workspace_controls_v94 control
    on control.business_id=business.id
  join public.business_subscription_lifecycle_v94 lifecycle
    on lifecycle.business_id=business.id
  join public.business_platform_intelligence_settings_v94 setting
    on setting.business_id=business.id
  join public.business_checkout_catalogue_settings_v94 checkout_setting
    on checkout_setting.business_id=business.id
  left join lateral app.assigned_consultant_v94(business.id) representative
    on true
  where business.id=p_business;
  if v_result is null then raise exception 'business_not_found' using errcode='22023';end if;
  return v_result;
end
$$;

--
-- Name: platform_get_catalogue_affinity_v94(uuid, uuid, date, date, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_get_catalogue_affinity_v94(p_business uuid, p_branch uuid, p_from date, p_to date, p_limit integer DEFAULT 25) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_pairs jsonb:='[]'::jsonb;v_enabled boolean;v_from timestamptz;v_to timestamptz;
  v_transactions integer;v_customers integer;v_weeks integer;
  v_reasons jsonb:='[]'::jsonb;v_ready boolean;
begin
  if not app.platform_firm_report_access_v94(p_business) then
    raise exception 'assigned_platform_report_access_required' using errcode='42501';
  end if;
  if p_limit not between 1 and 100 or p_from is null or p_to is null
     or p_from>p_to or p_to-p_from>1826 then
    raise exception 'invalid_affinity_request' using errcode='22023';
  end if;
  if p_branch is not null and not exists(
    select 1 from public.branches branch
    where branch.id=p_branch and branch.business_id=p_business
  ) then raise exception 'branch_not_in_business' using errcode='22023';end if;
  select catalogue_intelligence_enabled into v_enabled
  from public.business_platform_intelligence_settings_v94
  where business_id=p_business;
  v_from:=p_from::timestamp at time zone 'Asia/Singapore';
  v_to:=(p_to+1)::timestamp at time zone 'Asia/Singapore';
  with valid_sales as (
    select sale.id,sale.client_id,sale.occurred_at
    from public.sales sale
    where sale.business_id=p_business and sale.reversal_of is null
      and sale.occurred_at>=v_from and sale.occurred_at<v_to
      and (p_branch is null or sale.branch_id=p_branch)
      and not exists(select 1 from public.sales reversal
        where reversal.business_id=sale.business_id
          and reversal.reversal_of=sale.id)
  )
  select count(*),count(distinct client_id),
    count(distinct date_trunc('week',occurred_at at time zone 'Asia/Singapore'))
  into v_transactions,v_customers,v_weeks from valid_sales;
  if not coalesce(v_enabled,false) then
    v_reasons:=v_reasons||jsonb_build_array('catalogue_intelligence_disabled');
  end if;
  if v_transactions<20 then
    v_reasons:=v_reasons||jsonb_build_array('minimum_20_transactions_required');
  end if;
  if v_customers<10 then
    v_reasons:=v_reasons||jsonb_build_array('minimum_10_customers_required');
  end if;
  if v_weeks<4 then
    v_reasons:=v_reasons||jsonb_build_array('minimum_4_active_weeks_required');
  end if;
  v_ready:=jsonb_array_length(v_reasons)=0;
  if v_ready then
    with valid_sales as (
      select sale.id
      from public.sales sale
      where sale.business_id=p_business and sale.reversal_of is null
        and sale.occurred_at>=v_from and sale.occurred_at<v_to
        and (p_branch is null or sale.branch_id=p_branch)
        and not exists(select 1 from public.sales reversal
          where reversal.business_id=sale.business_id
            and reversal.reversal_of=sale.id)
    ), service_orders as (
      select item.ref_id service_id,count(distinct item.sale_id) orders
      from public.sale_items item join valid_sales sale on sale.id=item.sale_id
      where item.business_id=p_business and item.item_type='service'
        and item.ref_id is not null group by item.ref_id
    ), pairs as (
      select service_item.ref_id service_id,service.name service_name,
        product_item.ref_id product_id,product.name product_name,
        count(distinct service_item.sale_id) support_orders,
        max(service_orders.orders) sample_orders,
        sum(product_item.qty) product_units,
        sum(product_item.line_cents) paired_revenue_cents
      from public.sale_items service_item
      join public.sale_items product_item
        on product_item.business_id=service_item.business_id
        and product_item.sale_id=service_item.sale_id
        and product_item.item_type='retail'
      join valid_sales sale on sale.id=service_item.sale_id
      join public.services service
        on service.id=service_item.ref_id and service.business_id=p_business
      join public.products product
        on product.id=product_item.ref_id and product.business_id=p_business
      join service_orders on service_orders.service_id=service_item.ref_id
      where service_item.business_id=p_business
        and service_item.item_type='service'
      group by service_item.ref_id,service.name,product_item.ref_id,product.name
      having count(distinct service_item.sale_id)>=3
        and count(distinct service_item.sale_id)::numeric
          /nullif(max(service_orders.orders),0)>=0.10
      order by support_orders desc,service_item.ref_id,product_item.ref_id
      limit p_limit
    )
    select coalesce(jsonb_agg(jsonb_build_object(
      'service_id',service_id,'service_name',service_name,
      'product_id',product_id,'product_name',product_name,
      'support_orders',support_orders,'sample_orders',sample_orders,
      'confidence_pct',
        round(support_orders::numeric*100/nullif(sample_orders,0),2),
      'product_units',product_units,
      'paired_revenue_cents',paired_revenue_cents
    ) order by support_orders desc,service_id,product_id),'[]'::jsonb)
    into v_pairs from pairs;
  end if;
  return jsonb_build_object(
    'scope',jsonb_build_object('business_id',p_business,'branch_id',p_branch,
      'from',p_from,'to',p_to),
    'enabled',coalesce(v_enabled,false),
    'readiness',jsonb_build_object(
      'ready',v_ready,
      'thresholds',jsonb_build_object(
        'transactions',20,'customers',10,'active_weeks',4,
        'pair_support_orders',3,'pair_confidence_pct',10
      ),
      'observed',jsonb_build_object(
        'transactions',v_transactions,'customers',v_customers,
        'active_weeks',v_weeks
      ),
      'suppression_reasons',v_reasons
    ),
    'summary',jsonb_build_object('pair_count',jsonb_array_length(v_pairs)),
    'pairs',v_pairs
  );
end
$$;

--
-- Name: FUNCTION platform_get_catalogue_affinity_v94(p_business uuid, p_branch uuid, p_from date, p_to date, p_limit integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.platform_get_catalogue_affinity_v94(p_business uuid, p_branch uuid, p_from date, p_to date, p_limit integer) IS 'Platform-only service/product co-purchase affinity for assigned consultants and platform report readers.';

--
-- Name: platform_get_consultative_recommendations_v94(uuid, uuid, date, date, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_get_consultative_recommendations_v94(p_business uuid, p_branch uuid, p_from date, p_to date, p_limit integer DEFAULT 25) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_affinity jsonb;v_recommendations jsonb:='[]'::jsonb;
  v_pair jsonb;v_reasons jsonb;
begin
  v_affinity:=public.platform_get_catalogue_affinity_v94(
    p_business,p_branch,p_from,p_to,p_limit
  );
  v_reasons:=v_affinity#>'{readiness,suppression_reasons}';
  if not coalesce((v_affinity#>>'{readiness,ready}')::boolean,false) then
    return jsonb_build_object(
      'scope',v_affinity->'scope','generated_at',now(),
      'readiness',v_affinity->'readiness',
      'suppression_reasons',v_reasons,
      'recommendations','[]'::jsonb
    );
  end if;
  select value into v_pair
  from jsonb_array_elements(v_affinity->'pairs')
  order by (value->>'support_orders')::integer desc,
    (value->>'confidence_pct')::numeric desc
  limit 1;
  if v_pair is null then
    v_reasons:=jsonb_build_array('no_pair_meets_evidence_threshold');
  else
    v_recommendations:=jsonb_build_array(jsonb_build_object(
      'priority','high','category','cross_sell',
      'title','Bundle the strongest service and product pair',
      'evidence',jsonb_build_object(
        'service_id',v_pair->'service_id',
        'product_id',v_pair->'product_id',
        'support_orders',v_pair->'support_orders',
        'sample_orders',v_pair->'sample_orders',
        'confidence_pct',v_pair->'confidence_pct'
      ),
      'recommended_action',
        'Offer the product during booking, checkout and follow-up for this service.'
    ));
  end if;
  return jsonb_build_object(
    'scope',v_affinity->'scope','generated_at',now(),
    'readiness',v_affinity->'readiness',
    'suppression_reasons',v_reasons,
    'recommendations',v_recommendations
  );
end
$$;

--
-- Name: platform_get_effective_modules_v105(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_get_effective_modules_v105(p_business uuid, p_branch uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_modules jsonb;
begin
  if not app.v89_platform_can('sectors','r') then
    raise exception 'platform_module_access_required' using errcode='42501';
  end if;
  if p_branch is not null and not exists(
    select 1 from public.branches branch
    where branch.id=p_branch and branch.business_id=p_business
  ) then
    raise exception 'branch_not_in_business' using errcode='22023';
  end if;
  with module_keys as (
    select unnest(business.enabled_modules) module_key
    from public.businesses business where business.id=p_business
    union
    select module_key from public.platform_module_overrides_v94
    where business_id=p_business
    union
    select 'inventory'
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'module_key',module_keys.module_key,
    'mode',resolved.mode,
    'source',resolved.source,
    'version',resolved.version,
    'override_mode',coalesce(scoped.mode,'inherit'),
    'override_version',scoped.version
  ) order by module_keys.module_key),'[]'::jsonb)
  into v_modules
  from module_keys
  cross join lateral app.effective_platform_module_mode_v94(
    p_business,p_branch,module_keys.module_key
  ) resolved
  left join lateral (
    select override_row.mode,override_row.version
    from public.platform_module_overrides_v94 override_row
    where override_row.business_id=p_business
      and override_row.branch_scope is not distinct from p_branch
      and override_row.module_key=module_keys.module_key
  ) scoped on true;
  return jsonb_build_object(
    'business_id',p_business,
    'branch_id',p_branch,
    'workspace_access',app.business_workspace_open_v94(p_business),
    'inventory_global_disabled',true,
    'modules',v_modules
  );
end
$$;

--
-- Name: FUNCTION platform_get_effective_modules_v105(p_business uuid, p_branch uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.platform_get_effective_modules_v105(p_business uuid, p_branch uuid) IS 'v105 effective module projection plus the exact firm/branch override mode and optimistic version required by the editor.';

--
-- Name: platform_get_effective_modules_v94(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_get_effective_modules_v94(p_business uuid, p_branch uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_modules jsonb;
begin
  if not app.v89_platform_can('sectors','r') then
    raise exception 'platform_module_access_required' using errcode='42501';
  end if;
  if p_branch is not null and not exists(
    select 1 from public.branches branch
    where branch.id=p_branch and branch.business_id=p_business
  ) then raise exception 'branch_not_in_business' using errcode='22023';end if;
  with module_keys as (
    select unnest(business.enabled_modules) module_key
    from public.businesses business where business.id=p_business
    union select module_key from public.platform_module_overrides_v94
      where business_id=p_business
    union select 'inventory'
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'module_key',module_key,'mode',resolved.mode,'source',resolved.source,
    'version',resolved.version
  ) order by module_key),'[]'::jsonb)
  into v_modules
  from module_keys
  cross join lateral app.effective_platform_module_mode_v94(
    p_business,p_branch,module_keys.module_key
  ) resolved;
  return jsonb_build_object(
    'business_id',p_business,'branch_id',p_branch,
    'workspace_access',app.business_workspace_open_v94(p_business),
    'inventory_global_disabled',true,'modules',v_modules
  );
end
$$;

--
-- Name: platform_get_enterprise_hierarchy_v82(text, uuid[], uuid, date, date, text, integer, timestamp with time zone, timestamp with time zone, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_get_enterprise_hierarchy_v82(p_sector text DEFAULT NULL::text, p_businesses uuid[] DEFAULT NULL::uuid[], p_branch uuid DEFAULT NULL::uuid, p_from date DEFAULT (((now() AT TIME ZONE 'Asia/Singapore'::text))::date - 365), p_to date DEFAULT ((now() AT TIME ZONE 'Asia/Singapore'::text))::date, p_search text DEFAULT NULL::text, p_limit integer DEFAULT 100, p_snapshot_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_after_created_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_after_business uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_from_ts timestamptz;
  v_to_ts timestamptz;
  v_snapshot_at timestamptz:=coalesce(p_snapshot_at,clock_timestamp());
  v_search text:=nullif(btrim(p_search),'');
  v_result jsonb;
begin
  if not app.is_super_admin() then
    raise exception 'super_admin_required' using errcode='42501';
  end if;
  if p_from is null or p_to is null or p_from>p_to then
    raise exception 'invalid_report_window' using errcode='22023';
  end if;
  if p_to-p_from>1826 then
    raise exception 'report_window_exceeds_five_years' using errcode='22023';
  end if;
  if p_limit is null or p_limit<1 or p_limit>500 then
    raise exception 'limit_must_be_between_1_and_500' using errcode='22023';
  end if;
  if coalesce(cardinality(p_businesses),0)>100 then
    raise exception 'business_filter_exceeds_100' using errcode='22023';
  end if;
  if (p_after_created_at is null)<>(p_after_business is null) then
    raise exception 'complete_firm_cursor_required' using errcode='22023';
  end if;
  if p_snapshot_at is not null and p_snapshot_at>clock_timestamp()+interval '1 minute' then
    raise exception 'snapshot_cannot_be_in_the_future' using errcode='22023';
  end if;
  if p_branch is not null and not exists(
    select 1 from public.branches branch where branch.id=p_branch
  ) then
    raise exception 'branch_not_found' using errcode='22023';
  end if;

  v_from_ts:=p_from::timestamp at time zone 'Asia/Singapore';
  v_to_ts:=(p_to+1)::timestamp at time zone 'Asia/Singapore';

  with eligible_businesses as materialized (
    select business.id,business.name,business.slug,business.industry,
           business.currency,business.created_at,
           (
             v_search is null
             or business.name ilike '%'||v_search||'%'
             or business.industry ilike '%'||v_search||'%'
             or exists(
               select 1 from public.branches branch
               where branch.business_id=business.id
                 and branch.created_at<=v_snapshot_at
                 and (p_branch is null or branch.id=p_branch)
                 and branch.name ilike '%'||v_search||'%'
             )
           ) search_all
    from public.businesses business
    where business.is_synthetic=false and business.is_demo=false and business.created_at<=v_snapshot_at
      and (nullif(btrim(p_sector),'') is null
           or business.industry=btrim(p_sector))
      and (coalesce(cardinality(p_businesses),0)=0
           or business.id=any(p_businesses))
      and (p_branch is null or exists(
        select 1 from public.branches branch
        where branch.id=p_branch and branch.business_id=business.id
          and branch.created_at<=v_snapshot_at
      ))
      and (
        v_search is null
        or business.name ilike '%'||v_search||'%'
        or business.industry ilike '%'||v_search||'%'
        or exists(
          select 1 from public.branches branch
          where branch.business_id=business.id
            and branch.created_at<=v_snapshot_at
            and (p_branch is null or branch.id=p_branch)
            and branch.name ilike '%'||v_search||'%'
        )
        or exists(
          select 1 from public.clients client
          where client.business_id=business.id
            and client.created_at<=v_snapshot_at
            and (
              client.full_name ilike '%'||v_search||'%'
              or coalesce(client.email,'') ilike '%'||v_search||'%'
              or coalesce(client.phone,'') ilike '%'||v_search||'%'
            )
            and (p_branch is null or exists(
              select 1 from public.sales sale
              where sale.business_id=business.id and sale.client_id=client.id
                and sale.branch_id=p_branch and sale.created_at<=v_snapshot_at
                and sale.occurred_at<v_to_ts
            ))
        )
      )
  ),
  searched_businesses as materialized (
    select business.*
    from eligible_businesses business
    where business.search_all or exists(
      select 1 from public.clients client
      where client.business_id=business.id
        and client.created_at<=v_snapshot_at
        and (
          client.full_name ilike '%'||v_search||'%'
          or coalesce(client.email,'') ilike '%'||v_search||'%'
          or coalesce(client.phone,'') ilike '%'||v_search||'%'
        )
        and (p_branch is null or exists(
          select 1 from public.sales sale
          where sale.business_id=business.id and sale.client_id=client.id
            and sale.branch_id=p_branch and sale.created_at<=v_snapshot_at
            and sale.occurred_at<v_to_ts
        ))
    )
  ),
  page as materialized (
    select business.*
    from searched_businesses business
    where p_after_created_at is null
       or (business.created_at,business.id)>(p_after_created_at,p_after_business)
    order by business.created_at,business.id
    limit p_limit
  ),
  rows as materialized (
    select business.*,
      (
        select count(*)::integer from public.branches branch
        where branch.business_id=business.id
          and branch.created_at<=v_snapshot_at
          and (p_branch is null or branch.id=p_branch)
      ) branch_count,
      (
        select count(*)::integer from public.staff staff
        where staff.business_id=business.id and staff.active
          and staff.created_at<=v_snapshot_at
      ) staff_count,
      (
        select count(*)::integer from public.clients client
        where client.business_id=business.id
          and client.created_at<=v_snapshot_at
          and (
            business.search_all
            or client.full_name ilike '%'||v_search||'%'
            or coalesce(client.email,'') ilike '%'||v_search||'%'
            or coalesce(client.phone,'') ilike '%'||v_search||'%'
          )
          and (p_branch is null or exists(
            select 1 from public.sales sale
            where sale.business_id=business.id and sale.client_id=client.id
              and sale.branch_id=p_branch and sale.created_at<=v_snapshot_at
              and sale.occurred_at<v_to_ts
          ))
      ) customer_count
    from page business
  )
  select jsonb_build_object(
    'snapshot_at',v_snapshot_at,
    'scope',jsonb_build_object(
      'sector',nullif(btrim(p_sector),''),
      'business_ids',coalesce(to_jsonb(p_businesses),'[]'::jsonb),
      'branch_id',p_branch,'from',p_from,'to',p_to,'search',v_search,
      'timezone','Asia/Singapore',
      'search_behavior','firm_or_branch_match_includes_whole_scope_otherwise_matching_customers_only'
    ),
    'firms',coalesce((
      select jsonb_agg(jsonb_build_object(
        'business_id',business.id,'name',business.name,'slug',business.slug,
        'industry',business.industry,'currency',business.currency,
        'created_at',business.created_at,'branch_count',business.branch_count,
        'staff_count',business.staff_count,'customer_count',business.customer_count,
        'summary',jsonb_build_object(
          'net_revenue_cents',(
            select coalesce(sum(sale.amount_cents)
              filter(where sale.counts_as_revenue),0)
            from public.sales sale
            where sale.business_id=business.id
              and sale.created_at<=v_snapshot_at
              and sale.occurred_at>=v_from_ts and sale.occurred_at<v_to_ts
              and (p_branch is null or sale.branch_id=p_branch)
              and (
                business.search_all
                or sale.client_id in(
                  select client.id from public.clients client
                  where client.business_id=business.id
                    and client.created_at<=v_snapshot_at
                    and (
                      client.full_name ilike '%'||v_search||'%'
                      or coalesce(client.email,'') ilike '%'||v_search||'%'
                      or coalesce(client.phone,'') ilike '%'||v_search||'%'
                    )
                )
              )
          ),
          'cash_collected_cents',(
            select coalesce(sum(payment.amount_cents)
              filter(where payment.method not in('credit','gift_card')),0)
            from public.payments payment
            left join public.sales linked_sale
              on linked_sale.id=payment.sale_id
             and linked_sale.business_id=payment.business_id
            where payment.business_id=business.id
              and payment.created_at<=v_snapshot_at
              and payment.occurred_at>=v_from_ts and payment.occurred_at<v_to_ts
              and (p_branch is null or payment.branch_id=p_branch)
              and (
                business.search_all
                or coalesce(payment.client_id,linked_sale.client_id) in(
                  select client.id from public.clients client
                  where client.business_id=business.id
                    and client.created_at<=v_snapshot_at
                    and (
                      client.full_name ilike '%'||v_search||'%'
                      or coalesce(client.email,'') ilike '%'||v_search||'%'
                      or coalesce(client.phone,'') ilike '%'||v_search||'%'
                    )
                )
              )
          ),
          'completed_transactions',(
            select count(*) from public.sales sale
            where sale.business_id=business.id
              and sale.created_at<=v_snapshot_at
              and sale.occurred_at>=v_from_ts and sale.occurred_at<v_to_ts
              and (p_branch is null or sale.branch_id=p_branch)
              and sale.reversal_of is null and sale.amount_cents>0
              and sale.counts_as_revenue
              and (
                business.search_all
                or sale.client_id in(
                  select client.id from public.clients client
                  where client.business_id=business.id
                    and client.created_at<=v_snapshot_at
                    and (
                      client.full_name ilike '%'||v_search||'%'
                      or coalesce(client.email,'') ilike '%'||v_search||'%'
                      or coalesce(client.phone,'') ilike '%'||v_search||'%'
                    )
                )
              )
              and not exists(
                select 1 from public.sales reversal
                where reversal.business_id=sale.business_id
                  and reversal.reversal_of=sale.id
                  and reversal.created_at<=v_snapshot_at
                  and reversal.occurred_at<v_to_ts
              )
          ),
          'returning_customers',(
            select count(*) from (
              select sale.client_id
              from public.sales sale
              where sale.business_id=business.id
                and sale.client_id is not null
                and sale.created_at<=v_snapshot_at
                and sale.occurred_at>=v_from_ts and sale.occurred_at<v_to_ts
                and (p_branch is null or sale.branch_id=p_branch)
                and sale.reversal_of is null and sale.amount_cents>0
                and sale.counts_as_visit
                and (
                  business.search_all
                  or sale.client_id in(
                    select client.id from public.clients client
                    where client.business_id=business.id
                      and client.created_at<=v_snapshot_at
                      and (
                        client.full_name ilike '%'||v_search||'%'
                        or coalesce(client.email,'') ilike '%'||v_search||'%'
                        or coalesce(client.phone,'') ilike '%'||v_search||'%'
                      )
                  )
                )
                and not exists(
                  select 1 from public.sales reversal
                  where reversal.business_id=sale.business_id
                    and reversal.reversal_of=sale.id
                    and reversal.created_at<=v_snapshot_at
                    and reversal.occurred_at<v_to_ts
                )
              group by sale.client_id having count(*)>=2
            ) returning_set
          )
        ),
        'branches',coalesce((
          select jsonb_agg(jsonb_build_object(
            'branch_id',branch.id,'name',branch.name,'address',branch.address,
            'phone',branch.phone,'email',branch.email,'active',branch.active,
            'is_default',branch.is_default,'created_at',branch.created_at,
            'customer_count',(
              select count(distinct sale.client_id)
              from public.sales sale
              where sale.business_id=business.id and sale.branch_id=branch.id
                and sale.client_id is not null and sale.created_at<=v_snapshot_at
                and sale.occurred_at<v_to_ts
                and (
                  business.search_all
                  or sale.client_id in(
                    select client.id from public.clients client
                    where client.business_id=business.id
                      and client.created_at<=v_snapshot_at
                      and (
                        client.full_name ilike '%'||v_search||'%'
                        or coalesce(client.email,'') ilike '%'||v_search||'%'
                        or coalesce(client.phone,'') ilike '%'||v_search||'%'
                      )
                  )
                )
            ),
            'staff_count',(
              select count(distinct staff.id)
              from public.staff_branches staff_branch
              join public.staff staff
                on staff.id=staff_branch.staff_id
               and staff.business_id=staff_branch.business_id
              where staff_branch.business_id=business.id
                and staff_branch.branch_id=branch.id
                and staff.active
                and staff.created_at<=v_snapshot_at
            ),
            'net_revenue_cents',(
              select coalesce(sum(sale.amount_cents)
                filter(where sale.counts_as_revenue),0)
              from public.sales sale
              where sale.business_id=business.id and sale.branch_id=branch.id
                and sale.created_at<=v_snapshot_at
                and sale.occurred_at>=v_from_ts and sale.occurred_at<v_to_ts
                and (
                  business.search_all
                  or sale.client_id in(
                    select client.id from public.clients client
                    where client.business_id=business.id
                      and client.created_at<=v_snapshot_at
                      and (
                        client.full_name ilike '%'||v_search||'%'
                        or coalesce(client.email,'') ilike '%'||v_search||'%'
                        or coalesce(client.phone,'') ilike '%'||v_search||'%'
                      )
                  )
                )
            ),
            'completed_transactions',(
              select count(*) from public.sales sale
              where sale.business_id=business.id and sale.branch_id=branch.id
                and sale.created_at<=v_snapshot_at
                and sale.occurred_at>=v_from_ts and sale.occurred_at<v_to_ts
                and sale.reversal_of is null and sale.amount_cents>0
                and sale.counts_as_revenue
                and (
                  business.search_all
                  or sale.client_id in(
                    select client.id from public.clients client
                    where client.business_id=business.id
                      and client.created_at<=v_snapshot_at
                      and (
                        client.full_name ilike '%'||v_search||'%'
                        or coalesce(client.email,'') ilike '%'||v_search||'%'
                        or coalesce(client.phone,'') ilike '%'||v_search||'%'
                      )
                  )
                )
                and not exists(
                  select 1 from public.sales reversal
                  where reversal.business_id=sale.business_id
                    and reversal.reversal_of=sale.id
                    and reversal.created_at<=v_snapshot_at
                    and reversal.occurred_at<v_to_ts
                )
            )
          ) order by branch.is_default desc,branch.name,branch.id)
          from public.branches branch
          where branch.business_id=business.id
            and branch.created_at<=v_snapshot_at
            and (p_branch is null or branch.id=p_branch)
        ),'[]'::jsonb)
      ) order by business.created_at,business.id)
      from rows business
    ),'[]'::jsonb),
    'pagination',jsonb_build_object(
      'limit',p_limit,'total_firms',(select count(*) from searched_businesses),
      'returned_firms',(select count(*) from rows),
      'has_more',exists(
        select 1 from searched_businesses candidate
        where (candidate.created_at,candidate.id)>(
          (select created_at from rows order by created_at desc,id desc limit 1),
          (select id from rows order by created_at desc,id desc limit 1)
        )
      ),
      'next_cursor',case when exists(
        select 1 from searched_businesses candidate
        where (candidate.created_at,candidate.id)>(
          (select created_at from rows order by created_at desc,id desc limit 1),
          (select id from rows order by created_at desc,id desc limit 1)
        )
      ) then (
        select jsonb_build_object('created_at',created_at,'business_id',id)
        from rows order by created_at desc,id desc limit 1
      ) else null end
    )
  ) into v_result;
  return v_result;
end
$$;

--
-- Name: FUNCTION platform_get_enterprise_hierarchy_v82(p_sector text, p_businesses uuid[], p_branch uuid, p_from date, p_to date, p_search text, p_limit integer, p_snapshot_at timestamp with time zone, p_after_created_at timestamp with time zone, p_after_business uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.platform_get_enterprise_hierarchy_v82(p_sector text, p_businesses uuid[], p_branch uuid, p_from date, p_to date, p_search text, p_limit integer, p_snapshot_at timestamp with time zone, p_after_created_at timestamp with time zone, p_after_business uuid) IS 'v92: enterprise hierarchy excludes structurally synthetic businesses.';

--
-- Name: platform_get_finance_v146(date, date, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_get_finance_v146(p_from date, p_to date, p_limit integer DEFAULT 100) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_income bigint;v_adjustments bigint;v_expenses bigint;v_reversals bigint;v_pending bigint;
  v_start timestamptz;v_end timestamptz;
begin
  if auth.uid() is null or not app.is_super_admin() then
    raise exception 'super-admin access is required' using errcode='42501';
  end if;
  if p_from is null or p_to is null or p_to<p_from or p_to-p_from>1826
     or p_limit not between 1 and 5000 then
    raise exception 'valid finance range and limit are required' using errcode='22023';
  end if;
  v_start:=p_from::timestamp at time zone 'Asia/Singapore';
  v_end:=(p_to+1)::timestamp at time zone 'Asia/Singapore';
  select coalesce(sum(net_cash_ex_tax_cents),0) into v_income
    from public.billing_provider_invoices
   where paid_normalized and currency='SGD' and paid_at>=v_start and paid_at<v_end;
  select coalesce(sum(case
      when adjustment.adjustment_type in ('refund','chargeback','external_payment')
        then adjustment.total_cents
      when adjustment.adjustment_type='reversal'
       and original.adjustment_type in ('refund','chargeback','external_payment')
        then adjustment.total_cents
      else 0 end),0) into v_adjustments
    from public.billing_adjustments adjustment
    left join public.billing_adjustments original on original.id=adjustment.reversal_of
   where adjustment.currency='SGD' and adjustment.occurred_at>=v_start and adjustment.occurred_at<v_end;
  select coalesce(sum(amount_cents) filter(where entry_type='expense'),0),
         coalesce(sum(amount_cents) filter(where entry_type='reversal'),0)
    into v_expenses,v_reversals
    from public.platform_operating_expense_entries_v146
   where expense_date between p_from and p_to;
  select coalesce(sum(amount_remaining_cents),0) into v_pending
    from public.billing_provider_invoices
   where currency='SGD' and not paid_normalized and status='open' and created_at<v_end;
  return jsonb_build_object(
    'from',p_from,'to',p_to,'currency','SGD','basis','cash',
    'summary',jsonb_build_object(
      'income_cents',v_income,'billing_adjustments_cents',v_adjustments,
      'expense_outflows_cents',v_expenses,'expense_reversals_cents',v_reversals,
      'net_expenses_cents',v_expenses-v_reversals,
      'net_cash_cents',v_income+v_adjustments-v_expenses+v_reversals,
      'pending_invoice_cents',v_pending
    ),
    'row_counts',jsonb_build_object(
      'invoices',(select count(*) from public.billing_provider_invoices invoice where invoice.currency='SGD' and coalesce(invoice.paid_at,invoice.created_at)>=v_start and coalesce(invoice.paid_at,invoice.created_at)<v_end),
      'adjustments',(select count(*) from public.billing_adjustments adjustment where adjustment.currency='SGD' and adjustment.occurred_at>=v_start and adjustment.occurred_at<v_end),
      'expenses',(select count(*) from public.platform_operating_expense_entries_v146 entry where entry.expense_date between p_from and p_to)
    ),
    'complete',jsonb_build_object(
      'invoices',(select count(*)<=p_limit from public.billing_provider_invoices invoice where invoice.currency='SGD' and coalesce(invoice.paid_at,invoice.created_at)>=v_start and coalesce(invoice.paid_at,invoice.created_at)<v_end),
      'adjustments',(select count(*)<=p_limit from public.billing_adjustments adjustment where adjustment.currency='SGD' and adjustment.occurred_at>=v_start and adjustment.occurred_at<v_end),
      'expenses',(select count(*)<=p_limit from public.platform_operating_expense_entries_v146 entry where entry.expense_date between p_from and p_to)
    ),
    'invoices',coalesce((select jsonb_agg(to_jsonb(rows) order by rows.sort_at desc) from (
      select invoice.id,invoice.business_id,business.name business_name,
        invoice.provider_invoice_id,invoice.number,invoice.status,invoice.paid_normalized,
        invoice.currency,invoice.total_cents,invoice.amount_paid_cents,
        invoice.amount_remaining_cents,invoice.paid_at,invoice.created_at,
        invoice.hosted_invoice_url,invoice.invoice_pdf_url,invoice.provider_receipt_url,
        coalesce(invoice.paid_at,invoice.created_at) sort_at
      from public.billing_provider_invoices invoice
      join public.businesses business on business.id=invoice.business_id
      where invoice.currency='SGD' and coalesce(invoice.paid_at,invoice.created_at)>=v_start
        and coalesce(invoice.paid_at,invoice.created_at)<v_end
      order by sort_at desc limit p_limit
    ) rows),'[]'::jsonb),
    'adjustments',coalesce((select jsonb_agg(to_jsonb(rows) order by rows.occurred_at desc) from (
      select adjustment.id,adjustment.business_id,business.name business_name,
        adjustment.provider_invoice_id,adjustment.adjustment_type,
        adjustment.subtotal_ex_tax_cents,adjustment.tax_cents,adjustment.total_cents,
        adjustment.currency,adjustment.reason,adjustment.source_event_id,
        adjustment.provider_object_id,adjustment.reversal_of,adjustment.occurred_at,
        case
          when adjustment.adjustment_type in ('refund','chargeback','external_payment')
            then adjustment.total_cents
          when adjustment.adjustment_type='reversal'
           and original.adjustment_type in ('refund','chargeback','external_payment')
            then adjustment.total_cents
          else 0
        end cash_effect_cents,
        (adjustment.adjustment_type in ('refund','chargeback','external_payment')
          or (adjustment.adjustment_type='reversal'
            and original.adjustment_type in ('refund','chargeback','external_payment'))) cash_affecting
      from public.billing_adjustments adjustment
      left join public.billing_adjustments original on original.id=adjustment.reversal_of
      join public.businesses business on business.id=adjustment.business_id
      where adjustment.currency='SGD' and adjustment.occurred_at>=v_start
        and adjustment.occurred_at<v_end
      order by adjustment.occurred_at desc limit p_limit
    ) rows),'[]'::jsonb),
    'expenses',coalesce((select jsonb_agg(to_jsonb(rows) order by rows.expense_date desc,rows.created_at desc) from (
      select entry.id,entry.entry_type,entry.reversal_of,entry.expense_date,entry.category,
        entry.description,entry.amount_cents,entry.currency,entry.created_at,
        exists(select 1 from public.platform_operating_expense_entries_v146 reversal where reversal.reversal_of=entry.id) reversed
      from public.platform_operating_expense_entries_v146 entry
      where entry.expense_date between p_from and p_to
      order by entry.expense_date desc,entry.created_at desc limit p_limit
    ) rows),'[]'::jsonb)
  );
end
$$;

--
-- Name: platform_get_import_batch_v86(uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_get_import_batch_v86(p_batch uuid, p_limit integer DEFAULT 100, p_after_row integer DEFAULT NULL::integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_limit integer:=least(greatest(coalesce(p_limit,100),1),250);
begin
  if not app.is_platform_operator_v75() then raise exception 'platform operator access is required' using errcode='42501';end if;
  if not exists(select 1 from public.sme_prospect_import_batches where id=p_batch) then
    raise exception 'import batch was not found' using errcode='22023';end if;
  return jsonb_build_object(
    'batch',(select to_jsonb(batch) from public.sme_prospect_import_batches batch where batch.id=p_batch),
    'reversal',(select to_jsonb(reversal) from public.sme_import_batch_reversals reversal where reversal.batch_id=p_batch),
    'mappings',coalesce((select jsonb_agg(to_jsonb(mapping) order by mapping.source_header)
      from public.sme_import_column_mappings mapping where mapping.batch_id=p_batch),'[]'::jsonb),
    'rows',coalesce((select jsonb_agg(to_jsonb(page) order by page.row_number) from(
      select row.id import_row_id,row.row_number,row.row_status,row.errors,row.raw_payload,
        row.normalized_payload,row.mapped_stage_key,row.prospect_id,
        (select to_jsonb(decision) from public.sme_import_row_decision_versions decision
          where decision.import_row_id=row.id order by decision.version desc limit 1) latest_decision,
        coalesce((select jsonb_agg(jsonb_build_object(
          'candidate_prospect_id',candidate.candidate_prospect_id,
          'match_basis',candidate.match_basis,'score',candidate.score,'evidence',candidate.evidence)
          order by candidate.score desc,candidate.candidate_prospect_id)
          from public.sme_import_dedupe_candidates candidate
          where candidate.import_row_id=row.id),'[]'::jsonb) candidates
      from public.sme_prospect_import_rows row where row.batch_id=p_batch
        and (p_after_row is null or row.row_number>p_after_row)
      order by row.row_number limit v_limit
    ) page),'[]'::jsonb),
    'next_after_row',(select max(page.row_number) from(
      select row.row_number from public.sme_prospect_import_rows row where row.batch_id=p_batch
        and (p_after_row is null or row.row_number>p_after_row)
      order by row.row_number limit v_limit
    ) page)
  );
end
$$;

--
-- Name: platform_get_import_errors_v86(uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_get_import_errors_v86(p_batch uuid, p_limit integer DEFAULT 500, p_after_row integer DEFAULT NULL::integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_limit integer:=least(greatest(coalesce(p_limit,500),1),500);
begin
  if not app.is_platform_operator_v75() then raise exception 'platform operator access is required' using errcode='42501';end if;
  return jsonb_build_object(
    'batch_id',p_batch,
    'items',coalesce((select jsonb_agg(to_jsonb(page) order by page.row_number) from(
      select row.id import_row_id,row.row_number,row.row_status,row.errors,row.raw_payload,row.normalized_payload,
        (select to_jsonb(decision) from public.sme_import_row_decision_versions decision
          where decision.import_row_id=row.id order by decision.version desc limit 1) latest_decision,
        coalesce((select jsonb_agg(jsonb_build_object(
          'candidate_prospect_id',candidate.candidate_prospect_id,'match_basis',candidate.match_basis,
          'score',candidate.score) order by candidate.score desc)
          from public.sme_import_dedupe_candidates candidate where candidate.import_row_id=row.id),'[]'::jsonb) candidates
      from public.sme_prospect_import_rows row where row.batch_id=p_batch
        and (p_after_row is null or row.row_number>p_after_row)
        and (cardinality(row.errors)>0 or row.row_status in ('conflict','unmapped'))
      order by row.row_number limit v_limit
    ) page),'[]'::jsonb),
    'next_after_row',(select max(page.row_number) from(
      select row.row_number from public.sme_prospect_import_rows row where row.batch_id=p_batch
        and (p_after_row is null or row.row_number>p_after_row)
        and (cardinality(row.errors)>0 or row.row_status in ('conflict','unmapped'))
      order by row.row_number limit v_limit
    ) page),
    'download_format','csv_ready_json'
  );
end
$$;

--
-- Name: platform_get_my_prospect_v89(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_get_my_prospect_v89(p_prospect uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_result jsonb;
begin
  if not app.v89_platform_can('onboarding','r')
     or not app.v89_can_access_prospect(p_prospect) then
    raise exception 'scoped onboarding read access is required' using errcode='42501';
  end if;
  select jsonb_build_object(
    'prospect',to_jsonb(prospect),
    'company',to_jsonb(company),
    'contacts',coalesce((select jsonb_agg(to_jsonb(contact)
      order by contact.is_primary desc,contact.created_at,contact.id)
      from public.sme_prospect_contacts contact
      where contact.prospect_id=prospect.id and contact.active),'[]'::jsonb),
    'activities',coalesce((select jsonb_agg(to_jsonb(activity)
      order by activity.occurred_at desc,activity.id desc)
      from (select * from public.sme_prospect_activities activity_source
        where activity_source.prospect_id=prospect.id
        order by activity_source.occurred_at desc,activity_source.id desc
        limit 100) activity),'[]'::jsonb),
    'tasks',coalesce((select jsonb_agg(to_jsonb(task)
      order by task.status,task.due_at,task.id)
      from public.sme_prospect_tasks task
      where task.prospect_id=prospect.id),'[]'::jsonb)
  ) into v_result
  from public.sme_prospects prospect
  join public.sme_companies company on company.id=prospect.company_id
  where prospect.id=p_prospect;
  return v_result;
end
$$;

--
-- Name: platform_get_prospect_detail_v76(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_get_prospect_detail_v76(p_prospect uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_prospect public.sme_prospects%rowtype; v_company public.sme_companies%rowtype;
begin
  if not app.is_platform_operator_v75() then
    raise exception 'platform operator access is required' using errcode='42501';
  end if;
  select * into v_prospect from public.sme_prospects where id=p_prospect;
  if not found then raise exception 'prospect was not found' using errcode='22023'; end if;
  select * into strict v_company from public.sme_companies where id=v_prospect.company_id;
  return jsonb_build_object(
    'prospect',to_jsonb(v_prospect),'company',to_jsonb(v_company),
    'contacts',coalesce((select jsonb_agg(to_jsonb(contact) order by contact.is_primary desc,contact.created_at)
      from public.sme_prospect_contacts contact where contact.prospect_id=p_prospect),'[]'::jsonb),
    'assignment',case when v_prospect.assigned_consultant_id is null then null else
      (select jsonb_build_object('consultant_id',id,'display_name',display_name,'tier',tier)
       from public.platform_consultants where id=v_prospect.assigned_consultant_id) end,
    'activities',coalesce((select jsonb_agg(to_jsonb(activity) order by activity.occurred_at desc)
      from public.sme_prospect_activities activity where activity.prospect_id=p_prospect),'[]'::jsonb),
    'tasks',coalesce((select jsonb_agg(to_jsonb(task) order by task.status,task.due_at)
      from public.sme_prospect_tasks task where task.prospect_id=p_prospect),'[]'::jsonb),
    'stage_history',coalesce((select jsonb_agg(to_jsonb(history) order by history.occurred_at desc)
      from public.sme_prospect_stage_history history where history.prospect_id=p_prospect),'[]'::jsonb),
    'qualification',(select to_jsonb(q) from public.sme_prospect_qualification_versions q
      where q.prospect_id=p_prospect order by q.version desc limit 1),
    'commercial_terms',(select to_jsonb(terms) from public.sme_commercial_terms terms
      where terms.prospect_id=p_prospect order by terms.version desc limit 1),
    'sources',coalesce((select jsonb_agg(to_jsonb(source) order by source.created_at)
      from public.sme_prospect_source_lineage source where source.prospect_id=p_prospect),'[]'::jsonb),
    'tags',coalesce((select jsonb_agg(jsonb_build_object('tag_key',tag.tag_key,'label',tag.label)
      order by tag.label) from public.sme_prospect_tags link join public.sme_tags tag on tag.id=link.tag_id
      where link.prospect_id=p_prospect),'[]'::jsonb),
    'data_quality_flags',coalesce((select jsonb_agg(to_jsonb(flag) order by flag.resolved_at nulls first,flag.created_at)
      from public.sme_prospect_data_quality_flags flag where flag.prospect_id=p_prospect),'[]'::jsonb)
  );
end
$$;

--
-- Name: platform_get_prospect_detail_v86(uuid, timestamp with time zone, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_get_prospect_detail_v86(p_prospect uuid, p_snapshot_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_snapshot timestamptz:=coalesce(p_snapshot_at,clock_timestamp());v_limit integer:=least(greatest(coalesce(p_limit,50),1),100);
begin
  if not app.is_platform_operator_v75() then raise exception 'platform operator access is required' using errcode='42501';end if;
  if not exists(select 1 from public.sme_prospects where id=p_prospect and created_at<=v_snapshot) then
    raise exception 'prospect was not found' using errcode='22023';end if;
  return jsonb_build_object(
    'snapshot_at',v_snapshot,
    'prospect',(select to_jsonb(p) from public.sme_prospects p where p.id=p_prospect),
    'company',(select to_jsonb(c) from public.sme_companies c join public.sme_prospects p on p.company_id=c.id where p.id=p_prospect),
    'company_profile',(select to_jsonb(profile) from public.sme_company_profile_versions profile
      join public.sme_prospects p on p.company_id=profile.company_id
      where p.id=p_prospect and profile.created_at<=v_snapshot order by profile.version desc limit 1),
    'contacts',coalesce((select jsonb_agg(jsonb_build_object(
      'contact',to_jsonb(contact),'profile',(select to_jsonb(profile)
        from public.sme_contact_profile_versions profile where profile.contact_id=contact.id
          and profile.created_at<=v_snapshot order by profile.version desc limit 1))
      order by contact.is_primary desc,contact.created_at)
      from public.sme_prospect_contacts contact where contact.prospect_id=p_prospect
        and contact.created_at<=v_snapshot),'[]'::jsonb),
    'qualification',(select to_jsonb(q) from public.sme_qualification_detail_versions q
      where q.prospect_id=p_prospect and q.created_at<=v_snapshot order by q.version desc limit 1),
    'commercial_terms',(select jsonb_build_object('terms',to_jsonb(terms),
      'detail',(select to_jsonb(d) from public.sme_commercial_detail_versions d
        where d.commercial_terms_id=terms.id and d.created_at<=v_snapshot order by d.version desc limit 1))
      from public.sme_commercial_terms terms where terms.prospect_id=p_prospect
        and terms.created_at<=v_snapshot order by terms.version desc limit 1),
    'conversion_configuration',(select to_jsonb(config) from public.sme_conversion_configuration_versions config
      where config.prospect_id=p_prospect and config.created_at<=v_snapshot order by config.version desc limit 1),
    'activities',coalesce((select jsonb_agg(to_jsonb(page) order by page.occurred_at desc,page.id desc) from(
      select activity.*, (select to_jsonb(detail) from public.sme_activity_detail_versions detail
        where detail.activity_id=activity.id and detail.created_at<=v_snapshot order by detail.version desc limit 1) extended_detail
      from public.sme_prospect_activities activity where activity.prospect_id=p_prospect
        and activity.created_at<=v_snapshot order by activity.occurred_at desc,activity.id desc limit v_limit
    ) page),'[]'::jsonb),
    'documents',case when app.can_access_prospect_sensitive_v86(p_prospect) then
      coalesce((select jsonb_agg(to_jsonb(page)-'object_path' order by page.created_at desc,page.id desc) from(
        select document.* from public.sme_document_versions document where document.prospect_id=p_prospect
          and document.created_at<=v_snapshot order by document.created_at desc,document.id desc limit v_limit
      ) page),'[]'::jsonb) else '[]'::jsonb end,
    'stage_evidence',coalesce((select jsonb_agg(to_jsonb(page) order by page.created_at desc,page.id desc) from(
      select evidence.* from public.sme_stage_entry_evidence evidence where evidence.prospect_id=p_prospect
        and evidence.created_at<=v_snapshot order by evidence.created_at desc,evidence.id desc limit v_limit
    ) page),'[]'::jsonb),
    'data_quality',(select to_jsonb(snapshot) from public.sme_data_quality_snapshots snapshot
      where snapshot.prospect_id=p_prospect and snapshot.evaluated_at<=v_snapshot
      order by snapshot.evaluated_at desc,snapshot.id desc limit 1),
    'page_limit',v_limit
  );
end
$$;

--
-- Name: platform_get_prospect_subscription_ops_v156(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_get_prospect_subscription_ops_v156(p_prospect uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if auth.uid() is null or not app.v156_can_prospect(p_prospect,'r') then raise exception 'CRM read access is required' using errcode='42501';end if;
  if not exists(select 1 from public.sme_prospects where id=p_prospect) then raise exception 'prospect was not found' using errcode='22023';end if;
  return jsonb_build_object(
    'commercial',(select to_jsonb(c) from public.platform_crm_commercial_v156 c where c.prospect_id=p_prospect),
    'billing_contacts',coalesce((select jsonb_agg(to_jsonb(c)-'created_by'-'updated_by' order by case c.recipient_role when 'primary' then 0 else 1 end,c.email) from public.platform_billing_contacts_v156 c where c.prospect_id=p_prospect and c.active),'[]'::jsonb),
    'documents',coalesce((select jsonb_agg(jsonb_build_object('id',d.id,'type',d.document_type,'number',d.document_number,'issue_date',d.issue_date,'expiry_date',d.expiry_date,'total_cents',d.total_cents,'currency',d.currency,'pdf_ready',exists(select 1 from public.platform_subscription_document_files_v156 f where f.document_id=d.id),'status',(select e.status from public.platform_subscription_document_events_v156 e where e.document_id=d.id order by e.occurred_at desc limit 1)) order by d.created_at desc) from public.platform_subscription_documents_v156 d where d.prospect_id=p_prospect),'[]'::jsonb),
    'deliveries',coalesce((select jsonb_agg(to_jsonb(d)-'recipients'-'cc_recipients' order by d.created_at desc) from public.platform_subscription_deliveries_v156 d where d.prospect_id=p_prospect),'[]'::jsonb));
end $$;

--
-- Name: platform_get_sme_analytics_v86(date, date, timestamp with time zone, uuid, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_get_sme_analytics_v86(p_from date, p_to date, p_snapshot_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_consultant uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 100, p_after_source text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_snapshot timestamptz:=coalesce(p_snapshot_at,clock_timestamp());
  v_limit integer:=least(greatest(coalesce(p_limit,100),1),200);
  v_from timestamptz;v_to timestamptz;v_effective_consultant uuid:=p_consultant;
begin
  if not app.is_platform_operator_v75() then raise exception 'platform operator access is required' using errcode='42501';end if;
  if p_from is null or p_to is null or p_from>p_to or p_to-p_from>731 then
    raise exception 'analytics window must contain at most two years' using errcode='22023';end if;
  if not app.is_super_admin() then
    select id into v_effective_consultant from public.platform_consultants
      where user_id=auth.uid() and active;
  end if;
  v_from:=p_from::timestamp at time zone 'Asia/Singapore';
  v_to:=(p_to+1)::timestamp at time zone 'Asia/Singapore';
  return jsonb_build_object(
    'snapshot_at',v_snapshot,'scope',jsonb_build_object('from',p_from,'to',p_to,
      'consultant_id',v_effective_consultant),
    'summary',jsonb_build_object(
      'leads_created',(select count(*) from public.sme_prospects p where p.created_at>=v_from and p.created_at<v_to
        and p.created_at<=v_snapshot and (v_effective_consultant is null or p.assigned_consultant_id=v_effective_consultant)),
      'won',(select count(*) from public.sme_prospect_stage_history h join public.sme_prospects p on p.id=h.prospect_id
        where h.to_stage_key='client' and h.occurred_at>=v_from and h.occurred_at<v_to and h.occurred_at<=v_snapshot
          and (v_effective_consultant is null or p.assigned_consultant_id=v_effective_consultant)),
      'activated',(select count(*) from public.sme_prospect_stage_history h join public.sme_prospects p on p.id=h.prospect_id
        where h.to_stage_key='activated' and h.occurred_at>=v_from and h.occurred_at<v_to and h.occurred_at<=v_snapshot
          and (v_effective_consultant is null or p.assigned_consultant_id=v_effective_consultant)),
      'overdue_next_actions',(select count(*) from public.sme_prospects p where p.next_action_at<v_snapshot
        and p.current_stage_key not in ('lost','activated')
        and (v_effective_consultant is null or p.assigned_consultant_id=v_effective_consultant)),
      'pipeline_value_cents',(select coalesce(sum(terms.accepted_value_cents),0) from public.sme_commercial_terms terms
        join public.sme_prospects p on p.id=terms.prospect_id where terms.created_at<=v_snapshot
          and p.current_stage_key not in ('lost','activated')
          and (v_effective_consultant is null or p.assigned_consultant_id=v_effective_consultant))
    ),
    'stages',coalesce((select jsonb_agg(jsonb_build_object(
      'stage_key',stage.stage_key,'label',stage.label,'current_count',coalesce(metric.current_count,0),
      'entries',coalesce(metric.entries,0),'median_age_days',metric.median_age_days) order by stage.sort_order)
      from public.sme_pipeline_stages stage left join lateral(
        select
          (select count(*) from public.sme_prospects p where p.current_stage_key=stage.stage_key
            and p.created_at<=v_snapshot and (v_effective_consultant is null or p.assigned_consultant_id=v_effective_consultant)) current_count,
          count(*) entries,
          percentile_cont(.5) within group(order by greatest(0,
            extract(epoch from (least(v_snapshot,coalesce(next_event.occurred_at,v_snapshot))-history.occurred_at))/86400)) median_age_days
        from public.sme_prospect_stage_history history
        join public.sme_prospects p on p.id=history.prospect_id
        left join lateral(select h2.occurred_at from public.sme_prospect_stage_history h2
          where h2.prospect_id=history.prospect_id and (h2.occurred_at,h2.id)>(history.occurred_at,history.id)
          order by h2.occurred_at,h2.id limit 1) next_event on true
        where history.to_stage_key=stage.stage_key and history.occurred_at>=v_from
          and history.occurred_at<v_to and history.occurred_at<=v_snapshot
          and (v_effective_consultant is null or p.assigned_consultant_id=v_effective_consultant)
      ) metric on true),'[]'::jsonb),
    'source_page',coalesce((select jsonb_agg(to_jsonb(page) order by page.source_type) from(
      select source.source_type,count(distinct source.prospect_id) leads,
        count(distinct source.prospect_id) filter(where p.converted_business_id is not null) converted
      from public.sme_prospect_source_lineage source join public.sme_prospects p on p.id=source.prospect_id
      where source.created_at>=v_from and source.created_at<v_to and source.created_at<=v_snapshot
        and (p_after_source is null or source.source_type>p_after_source)
        and (v_effective_consultant is null or p.assigned_consultant_id=v_effective_consultant)
      group by source.source_type order by source.source_type limit v_limit
    ) page),'[]'::jsonb),
    'next_after_source',(select max(page.source_type) from(
      select source.source_type from public.sme_prospect_source_lineage source
      join public.sme_prospects p on p.id=source.prospect_id
      where source.created_at>=v_from and source.created_at<v_to and source.created_at<=v_snapshot
        and (p_after_source is null or source.source_type>p_after_source)
        and (v_effective_consultant is null or p.assigned_consultant_id=v_effective_consultant)
      group by source.source_type order by source.source_type limit v_limit
    ) page),
    'loss_reasons',coalesce((select jsonb_agg(jsonb_build_object('reason_code',history.reason_code,'count',history.count)
      order by history.count desc,history.reason_code) from(
      select h.reason_code,count(*) count from public.sme_prospect_stage_history h
      join public.sme_prospects p on p.id=h.prospect_id
      where h.to_stage_key='lost' and h.occurred_at>=v_from and h.occurred_at<v_to
        and h.occurred_at<=v_snapshot and (v_effective_consultant is null or p.assigned_consultant_id=v_effective_consultant)
      group by h.reason_code limit 50
    ) history),'[]'::jsonb),
    'contact_attempt_distribution',coalesce((select jsonb_agg(jsonb_build_object('attempts',attempts,'prospects',count)
      order by attempts) from(
      select attempts,count(*) from(
        select p.id,count(a.id)::integer attempts from public.sme_prospects p
        left join public.sme_prospect_activities a on a.prospect_id=p.id
          and a.activity_type in ('call','npu_attempt','whatsapp','email')
          and a.occurred_at>=v_from and a.occurred_at<v_to and a.occurred_at<=v_snapshot
        where p.created_at<=v_snapshot and (v_effective_consultant is null or p.assigned_consultant_id=v_effective_consultant)
        group by p.id
      ) attempts_by_prospect group by attempts
    ) distribution),'[]'::jsonb)
  );
end
$$;

--
-- Name: platform_get_subscription_operations_v156(text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_get_subscription_operations_v156(p_search text DEFAULT NULL::text, p_status text DEFAULT NULL::text, p_limit integer DEFAULT 250) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_profile public.platform_billing_profiles_v156%rowtype;
begin
  if auth.uid() is null or not app.v156_can('r') then raise exception 'billing read access is required' using errcode='42501';end if;
  if p_limit not between 1 and 500 then raise exception 'limit is invalid' using errcode='22023';end if;
  select * into v_profile from public.platform_billing_profiles_v156 order by version desc limit 1;
  return jsonb_build_object('profile',to_jsonb(v_profile)-'bank_account_number','bank_account_last4',right(v_profile.bank_account_number,4),'profile_ready',app.v156_profile_ready(v_profile),
    'summary',jsonb_build_object(
      'active',(select count(*) from public.billing_provider_subscriptions where status='active'),
      'new_this_month',(select count(*) from public.billing_provider_subscriptions where created_at>=date_trunc('month',clock_timestamp() at time zone 'Asia/Singapore')),
      'renewing_30',(select count(*) from public.billing_provider_subscriptions where status='active' and current_period_end::date between current_date and current_date+30),
      'renewing_14',(select count(*) from public.billing_provider_subscriptions where status='active' and current_period_end::date between current_date and current_date+14),
      'renewing_7',(select count(*) from public.billing_provider_subscriptions where status='active' and current_period_end::date between current_date and current_date+7),
      'payment_failed',(select count(*) from public.platform_subscription_tasks_v156 where status='open' and task_type='payment_failed'),
      'past_due',(select count(*) from public.billing_provider_subscriptions where status='past_due'),
      'cancel_at_period_end',(select count(*) from public.billing_provider_subscriptions where cancel_at_period_end),
      'cancelled_this_month',(select count(*) from public.billing_provider_subscriptions where status='canceled' and ended_at>=date_trunc('month',clock_timestamp() at time zone 'Asia/Singapore'))),
    'subscriptions',coalesce((select jsonb_agg(to_jsonb(rows) order by rows.next_renewal nulls last,rows.business_name) from (
      select business.id business_id,business.name business_name,subscription.provider_customer_id,subscription.provider_subscription_id,
        subscription.status canonical_status,subscription.cadence billing_interval,subscription.created_at subscription_created_at,
        subscription.current_period_start,subscription.current_period_end,
        case when paid_invoice.period_end is not null then (paid_invoice.period_end at time zone 'Asia/Singapore')::date-1 end paid_through,
        case when not subscription.cancel_at_period_end and subscription.status not in ('canceled') then subscription.current_period_end end next_renewal,
        case when subscription.cancel_at_period_end then subscription.current_period_end end scheduled_end,subscription.ended_at actual_end,
        subscription.cancel_at_period_end,subscription.trial_end,invoice.provider_invoice_id latest_invoice_id,invoice.number latest_invoice_number,
        invoice.status latest_invoice_status,invoice.paid_at latest_payment_at,invoice.amount_paid_cents latest_amount_paid_cents,
        contact.contact_name billing_contact_name,contact.email billing_email,prospect.assigned_consultant_id crm_owner,
        (select e.lifecycle_status from public.platform_subscription_lifecycle_events_v156 e where e.business_id=business.id order by e.occurred_at desc,e.id desc limit 1) lifecycle_status,
        (select count(*) from public.platform_subscription_tasks_v156 task where task.business_id=business.id and task.status='open') open_tasks,
        (select status from public.platform_subscription_deliveries_v156 delivery where delivery.business_id=business.id order by created_at desc limit 1) document_delivery_status
      from public.billing_provider_subscriptions subscription join public.businesses business on business.id=subscription.business_id
      left join lateral(select * from public.billing_provider_invoices i where i.provider_subscription_id=subscription.provider_subscription_id order by coalesce(i.paid_at,i.created_at) desc limit 1) invoice on true
      left join lateral(select * from public.billing_provider_invoices i where i.provider_subscription_id=subscription.provider_subscription_id and i.paid_normalized order by i.paid_at desc nulls last,i.created_at desc limit 1) paid_invoice on true
      left join public.platform_billing_contacts_v156 contact on contact.business_id=business.id and contact.active and contact.recipient_role='primary'
      left join public.sme_prospects prospect on prospect.converted_business_id=business.id
      where (p_search is null or business.name ilike '%'||p_search||'%' or subscription.provider_subscription_id ilike '%'||p_search||'%' or invoice.provider_invoice_id ilike '%'||p_search||'%')
        and (p_status is null or subscription.status=p_status
          or (p_status='renewing_30' and subscription.status='active' and subscription.current_period_end::date between current_date and current_date+30)
          or (p_status='renewing_14' and subscription.status='active' and subscription.current_period_end::date between current_date and current_date+14)
          or (p_status='renewing_7' and subscription.status='active' and subscription.current_period_end::date between current_date and current_date+7)
          or (p_status='payment_failed' and exists(select 1 from public.platform_subscription_tasks_v156 t where t.business_id=business.id and t.status='open' and t.task_type='payment_failed'))
          or (p_status='cancel_at_period_end' and subscription.cancel_at_period_end)) limit p_limit) rows),'[]'::jsonb),
    'tasks',coalesce((select jsonb_agg(to_jsonb(task) order by task.due_at,task.priority desc) from public.platform_subscription_tasks_v156 task where task.status='open'),'[]'::jsonb),
    'documents',coalesce((select jsonb_agg(to_jsonb(doc) order by doc.created_at desc) from (select d.id,d.document_type,d.document_number,d.business_id,d.prospect_id,d.provider_invoice_id,d.provider_subscription_id,d.issue_date,d.due_date,d.service_period_start,d.service_period_end,d.total_cents,d.amount_paid_cents,d.balance_due_cents,d.currency,d.finalized_at,d.created_at,
      (select e.status from public.platform_subscription_document_events_v156 e where e.document_id=d.id order by e.occurred_at desc,e.id desc limit 1) status,
      exists(select 1 from public.platform_subscription_document_files_v156 f where f.document_id=d.id) pdf_ready from public.platform_subscription_documents_v156 d order by d.created_at desc limit p_limit) doc),'[]'::jsonb),
    'deliveries',coalesce((select jsonb_agg(to_jsonb(delivery) order by created_at desc) from (select id,business_id,provider_invoice_id,delivery_type,status,attempt_count,failure_code,failure_reason,last_attempt_at,delivered_at,created_at from public.platform_subscription_deliveries_v156 order by created_at desc limit p_limit) delivery),'[]'::jsonb),
    'manual_payments',coalesce((select jsonb_agg(to_jsonb(payment) order by payment.created_at desc) from (select p.id,p.invoice_document_id,p.amount_cents,p.currency,p.payment_reference,p.value_date,p.bank_account_last4,p.status,p.recorded_by,p.verified_by,p.verified_at,p.rejection_reason,p.created_at,d.business_id,d.document_number from public.platform_manual_payments_v156 p join public.platform_subscription_documents_v156 d on d.id=p.invoice_document_id order by p.created_at desc limit p_limit) payment),'[]'::jsonb));
end $$;

--
-- Name: platform_issue_credit_note_v147(uuid, date, integer, integer, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_issue_credit_note_v147(p_invoice uuid, p_issue_date date, p_subtotal_cents integer, p_tax_cents integer, p_reason text, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_actor uuid:=auth.uid();v_invoice public.platform_financial_documents_v147%rowtype;v_policy public.platform_accounting_policies_v147%rowtype;v_existing public.platform_financial_documents_v147%rowtype;v_doc public.platform_financial_documents_v147%rowtype;v_id uuid:=gen_random_uuid();v_hash text;v_total bigint:=p_subtotal_cents+p_tax_cents;v_credited bigint;v_credited_subtotal bigint;v_credited_tax bigint;v_paid bigint;v_debited bigint;v_number text;v_journal jsonb;v_journal_id uuid;v_snapshot jsonb;
begin
  if v_actor is null or not app.is_super_admin() then raise exception 'super-admin access is required' using errcode='42501';end if;
  v_hash:=encode(extensions.digest(jsonb_build_object('invoice',p_invoice,'date',p_issue_date,'subtotal',p_subtotal_cents,'tax',p_tax_cents,'reason',btrim(p_reason))::text,'sha256'),'hex');perform pg_advisory_xact_lock(hashtextextended('platform_credit_note:'||p_idempotency_key::text,147));
  select * into v_existing from public.platform_financial_documents_v147 where created_by=v_actor and operation_key=p_idempotency_key;if found then if v_existing.request_hash<>v_hash then raise exception 'idempotency key was reused with different input' using errcode='22023';end if;return jsonb_build_object('document',to_jsonb(v_existing),'replayed',true);end if;
  perform pg_advisory_xact_lock(hashtextextended('platform_document_chain:'||p_invoice::text,147));
  select * into v_invoice from public.platform_financial_documents_v147 where id=p_invoice and document_type='invoice';if not found then raise exception 'invoice was not found' using errcode='22023';end if;
  select coalesce(sum(document.total_cents),0) into v_paid from public.platform_financial_documents_v147 document where document.original_document=p_invoice and document.document_type='receipt' and not exists(select 1 from public.platform_financial_documents_v147 reversal where reversal.original_document=document.id and reversal.document_type='journal_voucher');
  select coalesce(sum(document.total_cents),0),coalesce(sum(document.subtotal_cents),0),coalesce(sum(document.tax_cents),0)
    into v_credited,v_credited_subtotal,v_credited_tax
    from public.platform_financial_documents_v147 document where document.original_document=p_invoice and document.document_type='credit_note' and not exists(select 1 from public.platform_financial_documents_v147 reversal where reversal.original_document=document.id and reversal.document_type='journal_voucher');
  select coalesce(sum(document.total_cents),0) into v_debited from public.platform_financial_documents_v147 document where document.original_document=p_invoice and document.document_type='debit_note' and not exists(select 1 from public.platform_financial_documents_v147 reversal where reversal.original_document=document.id and reversal.document_type='journal_voucher');
  if p_subtotal_cents<=0 or p_tax_cents<0 or v_total>v_invoice.total_cents+v_debited-v_paid-v_credited or p_issue_date<v_invoice.issue_date or length(btrim(p_reason))<8 then raise exception 'credit note amount, date or reason is invalid' using errcode='22023';end if;
  if v_credited_subtotal+p_subtotal_cents>v_invoice.subtotal_cents or v_credited_tax+p_tax_cents>v_invoice.tax_cents
     or (v_invoice.tax_cents=0 and v_credited_tax+p_tax_cents<>0)
     or (v_invoice.tax_cents>0 and v_credited_tax+p_tax_cents<>round((v_credited_subtotal+p_subtotal_cents)*v_invoice.tax_cents::numeric/v_invoice.subtotal_cents)) then raise exception 'cumulative credit note tax must proportionally reverse the original invoice tax' using errcode='22023';end if;
  select * into v_policy from public.platform_accounting_policies_v147 where effective_from<=p_issue_date order by effective_from desc,version desc limit 1;v_number:=app.platform_next_document_number_v147('credit_note',v_policy.document_prefix);
  v_journal:=app.platform_post_journal_v147('generated_credit_note',v_id::text,p_issue_date,'Credit note '||v_number,jsonb_build_array(jsonb_build_object('account_code','4010','debit_cents',p_subtotal_cents,'credit_cents',0,'counterparty',v_invoice.counterparty->>'legal_name'),jsonb_build_object('account_code','1100','debit_cents',0,'credit_cents',v_total,'counterparty',v_invoice.counterparty->>'legal_name'))||case when p_tax_cents>0 then jsonb_build_array(jsonb_build_object('account_code','2200','debit_cents',p_tax_cents,'credit_cents',0,'counterparty',v_invoice.counterparty->>'legal_name')) else '[]'::jsonb end,p_idempotency_key,v_hash,v_actor,null);v_journal_id:=(v_journal#>>'{entry,id}')::uuid;
  v_snapshot:=jsonb_build_object('issuer',app.platform_document_issuer_v147(v_policy),'number',v_number,'invoice_number',v_invoice.document_number,'issue_date',p_issue_date,'reason',btrim(p_reason),'subtotal_cents',p_subtotal_cents,'tax_cents',p_tax_cents,'total_cents',v_total,'counterparty',v_invoice.counterparty,'currency','SGD');
  insert into public.platform_financial_documents_v147(id,document_type,document_number,issue_date,counterparty,line_items,subtotal_cents,tax_cents,total_cents,source_type,source_id,original_document,journal_entry,snapshot,snapshot_sha256,operation_key,request_hash,created_by)
  values(v_id,'credit_note',v_number,p_issue_date,v_invoice.counterparty,jsonb_build_array(jsonb_build_object('description',btrim(p_reason))),p_subtotal_cents,p_tax_cents,v_total,'generated_credit_note',v_id::text,p_invoice,v_journal_id,v_snapshot,encode(extensions.digest(v_snapshot::text,'sha256'),'hex'),p_idempotency_key,v_hash,v_actor) returning * into v_doc;
  return jsonb_build_object('document',to_jsonb(v_doc),'snapshot',v_snapshot,'replayed',false);
end
$$;

--
-- Name: platform_issue_debit_note_v147(uuid, date, integer, integer, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_issue_debit_note_v147(p_invoice uuid, p_issue_date date, p_subtotal_cents integer, p_tax_cents integer, p_reason text, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_actor uuid:=auth.uid();v_invoice public.platform_financial_documents_v147%rowtype;v_policy public.platform_accounting_policies_v147%rowtype;v_existing public.platform_financial_documents_v147%rowtype;v_doc public.platform_financial_documents_v147%rowtype;v_id uuid:=gen_random_uuid();v_hash text;v_total bigint:=p_subtotal_cents+p_tax_cents;v_number text;v_journal jsonb;v_journal_id uuid;v_snapshot jsonb;
begin
  if v_actor is null or not app.is_super_admin() then raise exception 'super-admin access is required' using errcode='42501';end if;
  v_hash:=encode(extensions.digest(jsonb_build_object('invoice',p_invoice,'date',p_issue_date,'subtotal',p_subtotal_cents,'tax',p_tax_cents,'reason',btrim(p_reason))::text,'sha256'),'hex');perform pg_advisory_xact_lock(hashtextextended('platform_debit_note:'||p_idempotency_key::text,147));
  select * into v_existing from public.platform_financial_documents_v147 where created_by=v_actor and operation_key=p_idempotency_key;if found then if v_existing.request_hash<>v_hash then raise exception 'idempotency key was reused with different input' using errcode='22023';end if;return jsonb_build_object('document',to_jsonb(v_existing),'replayed',true);end if;
  perform pg_advisory_xact_lock(hashtextextended('platform_document_chain:'||p_invoice::text,147));
  select * into v_invoice from public.platform_financial_documents_v147 where id=p_invoice and document_type='invoice';if not found then raise exception 'invoice was not found' using errcode='22023';end if;
  if p_subtotal_cents<=0 or p_tax_cents<0 or p_issue_date<v_invoice.issue_date or length(btrim(p_reason))<8 then raise exception 'debit note amount, date or reason is invalid' using errcode='22023';end if;
  if v_invoice.tax_cents<>0 or p_tax_cents<>0 then raise exception 'debit notes are limited to transactions where no GST is charged; issue a tax invoice instead' using errcode='22023';end if;
  select * into v_policy from public.platform_accounting_policies_v147 where effective_from<=p_issue_date order by effective_from desc,version desc limit 1;v_number:=app.platform_next_document_number_v147('debit_note',v_policy.document_prefix);
  v_journal:=app.platform_post_journal_v147('generated_debit_note',v_id::text,p_issue_date,'Debit note '||v_number,jsonb_build_array(jsonb_build_object('account_code','1100','debit_cents',v_total,'credit_cents',0,'counterparty',v_invoice.counterparty->>'legal_name'),jsonb_build_object('account_code','4090','debit_cents',0,'credit_cents',p_subtotal_cents,'counterparty',v_invoice.counterparty->>'legal_name'))||case when p_tax_cents>0 then jsonb_build_array(jsonb_build_object('account_code','2200','debit_cents',0,'credit_cents',p_tax_cents,'counterparty',v_invoice.counterparty->>'legal_name')) else '[]'::jsonb end,p_idempotency_key,v_hash,v_actor,null);v_journal_id:=(v_journal#>>'{entry,id}')::uuid;
  v_snapshot:=jsonb_build_object('issuer',app.platform_document_issuer_v147(v_policy),'number',v_number,'invoice_number',v_invoice.document_number,'issue_date',p_issue_date,'reason',btrim(p_reason),'subtotal_cents',p_subtotal_cents,'tax_cents',p_tax_cents,'total_cents',v_total,'counterparty',v_invoice.counterparty,'currency','SGD');
  insert into public.platform_financial_documents_v147(id,document_type,document_number,issue_date,counterparty,line_items,subtotal_cents,tax_cents,total_cents,source_type,source_id,original_document,journal_entry,snapshot,snapshot_sha256,operation_key,request_hash,created_by)
  values(v_id,'debit_note',v_number,p_issue_date,v_invoice.counterparty,jsonb_build_array(jsonb_build_object('description',btrim(p_reason))),p_subtotal_cents,p_tax_cents,v_total,'generated_debit_note',v_id::text,p_invoice,v_journal_id,v_snapshot,encode(extensions.digest(v_snapshot::text,'sha256'),'hex'),p_idempotency_key,v_hash,v_actor) returning * into v_doc;
  return jsonb_build_object('document',to_jsonb(v_doc),'snapshot',v_snapshot,'replayed',false);
end
$$;

--
-- Name: platform_link_checkout_command_v156(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_link_checkout_command_v156(p_prospect uuid, p_command uuid, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_actor uuid:=auth.uid();v_business uuid;v_command public.billing_commands%rowtype;v_row public.platform_crm_commercial_v156%rowtype;
begin
  if v_actor is null or not app.v156_can_prospect(p_prospect,'rw') then raise exception 'CRM write access is required' using errcode='42501';end if;
  select converted_business_id into v_business from public.sme_prospects where id=p_prospect;if v_business is null then raise exception 'create and link the business before Stripe Checkout' using errcode='22023';end if;
  select * into v_command from public.billing_commands where id=p_command and business_id=v_business and command_type='create_checkout' and status='completed' and provider_object_id like 'cs_%' and redirect_url~'^https://checkout\\.stripe\\.com/' ;if not found then raise exception 'completed Stripe Checkout command was not found' using errcode='22023';end if;
  insert into public.platform_crm_commercial_v156(prospect_id,checkout_session_id,checkout_url,checkout_created_at,payment_link_status,updated_by)
  values(p_prospect,v_command.provider_object_id,v_command.redirect_url,coalesce(v_command.completed_at,clock_timestamp()),'created',v_actor)
  on conflict(prospect_id) do update set checkout_session_id=excluded.checkout_session_id,checkout_url=excluded.checkout_url,checkout_created_at=excluded.checkout_created_at,payment_link_status='created',updated_by=v_actor,updated_at=clock_timestamp() returning * into v_row;
  if not exists(select 1 from public.sme_prospect_activities where prospect_id=p_prospect and detail='checkout-command:'||p_command) then insert into public.sme_prospect_activities(prospect_id,activity_type,summary,detail,created_by) values(p_prospect,'system','Stripe Checkout created','checkout-command:'||p_command,v_actor);end if;
  return jsonb_build_object('commercial',to_jsonb(v_row),'checkout_url',v_command.redirect_url,'replayed',false);
end $$;

--
-- Name: platform_list_access_grants_v89(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_list_access_grants_v89() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_result jsonb;
begin
  if not app.is_super_admin() then
    raise exception 'super admin access is required' using errcode='42501';
  end if;
  select jsonb_build_object('items',coalesce(jsonb_agg(jsonb_build_object(
    'user_id',grant_row.user_id,'email',auth_user.email,'role',grant_row.role,
    'module_perms',grant_row.module_perms,'active',grant_row.active,
    'updated_at',grant_row.updated_at
  ) order by lower(auth_user.email),grant_row.user_id),'[]'::jsonb))
  into v_result from public.platform_access_grants_v89 grant_row
  join auth.users auth_user on auth_user.id=grant_row.user_id;
  return v_result;
end
$$;

--
-- Name: platform_list_account_deletion_requests_v131(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_list_account_deletion_requests_v131(p_status text DEFAULT 'pending'::text, p_limit integer DEFAULT 50) RETURNS TABLE(request_id uuid, subject_ref uuid, status text, requested_at timestamp with time zone, response_due_at timestamp with time zone, updated_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if not app.is_super_admin() then
    raise exception 'super-admin only' using errcode='42501';
  end if;
  if p_status is not null and p_status not in ('pending','processing','completed','rejected','cancelled') then
    raise exception 'invalid status' using errcode='22023';
  end if;
  return query
    select request_row.id,request_row.subject_ref,request_row.status,request_row.requested_at,request_row.response_due_at,request_row.updated_at
      from public.account_deletion_requests request_row
     where p_status is null or request_row.status=p_status
     order by request_row.requested_at,request_row.id
     limit least(greatest(coalesce(p_limit,50),1),100);
end
$$;

--
-- Name: FUNCTION platform_list_account_deletion_requests_v131(p_status text, p_limit integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.platform_list_account_deletion_requests_v131(p_status text, p_limit integer) IS 'V131 bounded super-admin operations queue without email, phone, or business data.';

--
-- Name: platform_list_account_deletion_requests_v133(text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_list_account_deletion_requests_v133(p_status text DEFAULT NULL::text, p_limit integer DEFAULT 100, p_offset integer DEFAULT 0) RETURNS TABLE(request_id uuid, subject_ref uuid, status text, requested_at timestamp with time zone, response_due_at timestamp with time zone, updated_at timestamp with time zone, claimed_at timestamp with time zone, claimed_by uuid, resolution_code text, retention_until timestamp with time zone, resolution_reference text, is_overdue boolean, total_count bigint)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if auth.uid() is null or not app.is_super_admin() then
    raise exception 'super-admin only' using errcode='42501';
  end if;
  if p_status is not null
     and p_status not in('pending','processing','completed','rejected','cancelled') then
    raise exception 'invalid status' using errcode='22023';
  end if;

  return query
    select request_row.id,request_row.subject_ref,request_row.status,
      request_row.requested_at,request_row.response_due_at,request_row.updated_at,
      request_row.claimed_at,request_row.claimed_by,request_row.resolution_code,
      request_row.retention_until,request_row.resolution_reference,
      ((request_row.status in('pending','processing') and now()>request_row.response_due_at)
        or (request_row.status='completed'
          and request_row.resolution_code='retained_legal'
          and request_row.retention_until<=now())),
      count(*) over()
      from public.account_deletion_requests request_row
     where p_status is null or request_row.status=p_status
     order by
       case when (request_row.status in('pending','processing') and now()>request_row.response_due_at)
          or (request_row.status='completed' and request_row.resolution_code='retained_legal'
            and request_row.retention_until<=now()) then 0
         when request_row.status in('pending','processing') then 1 else 2 end,
       request_row.response_due_at,request_row.id
     limit least(greatest(coalesce(p_limit,100),1),100)
    offset least(greatest(coalesce(p_offset,0),0),1000000);
end
$$;

--
-- Name: platform_list_account_signups_v160(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_list_account_signups_v160(p_search text DEFAULT NULL::text, p_limit integer DEFAULT 100) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_limit integer:=least(greatest(coalesce(p_limit,100),1),100);
  v_search text:=nullif(trim(coalesce(p_search,'')),'');
  v_items jsonb;
begin
  if auth.uid() is null or not app.is_super_admin() then
    raise exception 'super_admin_required' using errcode='42501';
  end if;

  with candidates as (
    select user_row.*,triage.triage_status,triage.note as triage_note,
           triage.last_contacted_at,triage.archived_at,triage.updated_at as triage_updated_at
      from auth.users user_row
      left join public.platform_account_signup_triage_v164 triage
        on triage.auth_user_id=user_row.id
     where user_row.created_at >= now()-interval '30 days'
       and coalesce(triage.triage_status,'new') <> 'archived'
       and (
         user_row.raw_user_meta_data->>'account_type'='business_owner'
         or exists(
           select 1
             from app.business_account_legal_acceptances_v138 acceptance
            where acceptance.auth_user_id=user_row.id
              and acceptance.source='google_oauth_signup'
         )
       )
       and not exists(select 1 from public.staff staff_row where staff_row.user_id=user_row.id)
       and not exists(select 1 from public.self_serve_business_onboarding_v130 onboarding where onboarding.owner_user_id=user_row.id)
       and not exists(select 1 from public.business_applications_v95 application where lower(application.contact_email)=lower(user_row.email))
       and (
         v_search is null
         or lower(coalesce(user_row.email,'')) like '%'||lower(v_search)||'%'
         or coalesce(user_row.phone,'') like '%'||v_search||'%'
         or lower(coalesce(triage.note,'')) like '%'||lower(v_search)||'%'
       )
     order by user_row.created_at desc,user_row.id desc
     limit v_limit+1
  ), limited as (
    select * from candidates
     order by created_at desc,id desc
     limit v_limit
  )
  select coalesce(jsonb_agg(jsonb_build_object(
      'user_id',limited.id,
      'email',lower(limited.email),
      'phone',limited.phone,
      'confirmed',coalesce(limited.email_confirmed_at,limited.confirmed_at) is not null,
      'created_at',limited.created_at,
      'last_sign_in_at',limited.last_sign_in_at,
      'status',case
        when coalesce(limited.email_confirmed_at,limited.confirmed_at) is null then 'email_unconfirmed'
        else 'needs_business_details'
      end,
      'triage_status',coalesce(limited.triage_status,'new'),
      'triage_note',limited.triage_note,
      'last_contacted_at',limited.last_contacted_at,
      'triage_updated_at',limited.triage_updated_at,
      'manageable',true
    ) order by limited.created_at desc,limited.id desc),'[]'::jsonb)
    into v_items
    from limited;

  return jsonb_build_object(
    'items',v_items,
    'count',jsonb_array_length(v_items),
    'window_days',30,
    'truncated',(
      select count(*)>v_limit from (
        select 1
          from auth.users user_row
          left join public.platform_account_signup_triage_v164 triage
            on triage.auth_user_id=user_row.id
         where user_row.created_at >= now()-interval '30 days'
           and coalesce(triage.triage_status,'new') <> 'archived'
           and (
             user_row.raw_user_meta_data->>'account_type'='business_owner'
             or exists(
               select 1
                 from app.business_account_legal_acceptances_v138 acceptance
                where acceptance.auth_user_id=user_row.id
                  and acceptance.source='google_oauth_signup'
             )
           )
           and not exists(select 1 from public.staff staff_row where staff_row.user_id=user_row.id)
           and not exists(select 1 from public.self_serve_business_onboarding_v130 onboarding where onboarding.owner_user_id=user_row.id)
           and not exists(select 1 from public.business_applications_v95 application where lower(application.contact_email)=lower(user_row.email))
           and (
             v_search is null
             or lower(coalesce(user_row.email,'')) like '%'||lower(v_search)||'%'
             or coalesce(user_row.phone,'') like '%'||v_search||'%'
             or lower(coalesce(triage.note,'')) like '%'||lower(v_search)||'%'
           )
         limit v_limit+1
      ) overflow_check
    )
  );
end
$$;

