--
-- Name: platform_list_ai_firm_reports_v176(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_list_ai_firm_reports_v176(p_business uuid, p_limit integer DEFAULT 12) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_rows jsonb;
begin
  if auth.uid() is null then
    raise exception 'authenticated platform session is required'
      using errcode = '28000';
  end if;
  if not app.v176_can_read_firm_report(p_business) then
    raise exception 'ai_firm_report_read_outside_role_scope'
      using errcode = '42501';
  end if;
  if p_limit is null or p_limit not between 1 and 50 then
    raise exception 'limit must be 1..50' using errcode = '22023';
  end if;

  select coalesce(pg_catalog.jsonb_agg(row_json order by ordinality), '[]'::jsonb)
  into v_rows
  from (
    select pg_catalog.jsonb_build_object(
      'id', report.id,
      'business_id', report.business_id,
      'period_kind', report.period_kind,
      'period_start', report.period_start,
      'period_end', report.period_end,
      'status', report.status,
      'model', report.model,
      'narrative_md', report.narrative_md,
      'error', report.error,
      'generation', report.generation,
      'requested_by', report.requested_by,
      'created_at', report.created_at,
      'completed_at', report.completed_at
    ) as row_json,
    row_number() over(
      order by report.period_start desc, report.period_kind, report.id
    ) as ordinality
    from public.ai_firm_reports_v176 report
    where report.business_id = p_business
    order by report.period_start desc, report.period_kind, report.id
    limit p_limit
  ) recent;

  return pg_catalog.jsonb_build_object(
    'business_id', p_business,
    'contract_version', 'v176',
    'reports', v_rows
  );
end
$$;

--
-- Name: FUNCTION platform_list_ai_firm_reports_v176(p_business uuid, p_limit integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.platform_list_ai_firm_reports_v176(p_business uuid, p_limit integer) IS 'Recent stored AI narrative reports for one firm. Evidence packs are deliberately not returned to the browser.';

--
-- Name: platform_list_archived_prospects_v196(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_list_archived_prospects_v196(p_search text DEFAULT NULL::text, p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid:=auth.uid();
  v_limit integer:=least(greatest(coalesce(p_limit,50),1),200);
  v_search text:=nullif(btrim(coalesce(p_search,'')),'');
  v_result jsonb;
begin
  if not app.is_super_admin() then
    raise exception 'super admin access is required' using errcode='42501';
  end if;

  select jsonb_build_object(
    'items',coalesce((
      select jsonb_agg(row_payload order by row_payload->>'archived_at' desc)
      from (
        select jsonb_build_object(
          'id',prospect.id,
          'company_name',coalesce(company.trading_name,company.legal_name),
          'registration_number',company.registration_number,
          'stage_key',prospect.current_stage_key,
          'archived_at',prospect.archived_at,
          'archive_reason',prospect.archive_reason,
          'archived_by_name',coalesce(consultant.display_name,'Super admin'),
          'merged_into_prospect_id',prospect.merged_into_prospect_id,
          'merged_into_name',survivor_company.legal_name,
          -- A merged-away record cannot be restored on its own; the console
          -- uses this to show "Merged" instead of a Restore button.
          'restorable',prospect.merged_into_prospect_id is null,
          'contacts',(select count(*) from public.sme_prospect_contacts contact
                       where contact.prospect_id=prospect.id)
        ) as row_payload
        from public.sme_prospects prospect
        join public.sme_companies company on company.id=prospect.company_id
        left join public.platform_consultants consultant
          on consultant.user_id=prospect.archived_by
        left join public.sme_prospects survivor
          on survivor.id=prospect.merged_into_prospect_id
        left join public.sme_companies survivor_company
          on survivor_company.id=survivor.company_id
        where prospect.archived_at is not null
          and (v_search is null
            or lower(concat_ws(' ',company.legal_name,company.trading_name,
                 company.registration_number,prospect.archive_reason))
                like '%'||lower(v_search)||'%')
        order by prospect.archived_at desc
        limit v_limit
      ) rows
    ),'[]'::jsonb),
    'total_count',(select count(*) from public.sme_prospects
                    where archived_at is not null),
    'truncated',(select count(*) from public.sme_prospects
                  where archived_at is not null) > v_limit
  ) into v_result;

  insert into public.audit_log(business_id,actor,action,entity,detail)
  values(null,v_actor,'PLATFORM_ARCHIVED_PROSPECTS_READ_V196','sme_prospects',
    jsonb_build_object('search',v_search,'limit',v_limit,
      'result_count',jsonb_array_length(v_result->'items')));
  return v_result;
end $$;

