-- Name: FUNCTION platform_list_enterprise_customers_v82(p_sector text, p_businesses uuid[], p_branch uuid, p_from date, p_to date, p_search text, p_limit integer, p_snapshot_at timestamp with time zone, p_after_created_at timestamp with time zone, p_after_client uuid); Type: COMMENT; Schema: public; Owner: -
