--
-- Name: platform_list_firm_attention_v88(timestamp with time zone, integer, integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_list_firm_attention_v88(p_snapshot_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_limit integer DEFAULT 100, p_after_days_unattended integer DEFAULT NULL::integer, p_after_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid:=auth.uid();
  v_snapshot timestamptz:=coalesce(p_snapshot_at,clock_timestamp());
  v_snapshot_expires_at timestamptz;
  v_limit integer:=least(greatest(coalesce(p_limit,100),1),250);
  v_result jsonb;
begin
  if not app.is_super_admin() then
    raise exception 'super admin access is required' using errcode='42501';
  end if;
  if (p_after_days_unattended is null)<>(p_after_id is null) then
    raise exception 'complete attention cursor is required' using errcode='22023';
  end if;
  if p_snapshot_at is null and p_after_days_unattended is not null then
    raise exception 'snapshot token is required after the first page' using errcode='22023';
  end if;
  if p_after_days_unattended is not null and p_after_days_unattended<0 then
    raise exception 'attention cursor days must not be negative' using errcode='22023';
  end if;
  v_snapshot_expires_at:=app.ensure_platform_firm_snapshot_v88(
    v_actor,v_snapshot,p_snapshot_at is null
  );

  with due as materialized (
    select firm.* from app.platform_firm_snapshot_rows_v88 firm
    where firm.actor_id=v_actor and firm.snapshot_at=v_snapshot and firm.attention_due
  ), page as materialized (
    select firm.* from due firm
    where p_after_days_unattended is null
       or (firm.days_unattended,firm.row_id)<(p_after_days_unattended,p_after_id)
    order by firm.days_unattended desc,firm.row_id desc
    limit v_limit
  )
  select jsonb_build_object(
    'snapshot_at',v_snapshot,
    'snapshot_expires_at',v_snapshot_expires_at,
    'items',coalesce((select jsonb_agg(
      item.payload||jsonb_build_object('id',item.row_id,'total_count',(select count(*) from due))
      order by item.days_unattended desc,item.row_id desc
    ) from page item),'[]'::jsonb),
    'next_cursor',(select jsonb_build_object(
      'days_unattended',item.days_unattended,'id',item.row_id
    ) from page item order by item.days_unattended,item.row_id limit 1),
    'total_count',(select count(*) from due),
    'summary',jsonb_build_object(
      'critical',(select count(*) from due where attention_severity='critical'),
      'warning',(select count(*) from due where attention_severity='warning')
    )
  ) into v_result;

  insert into public.audit_log(business_id,actor,action,entity,detail)
  values(null,auth.uid(),'PLATFORM_FIRM_ATTENTION_READ_V88','businesses',
    jsonb_build_object('snapshot_at',v_snapshot,'limit',v_limit,
      'result_count',jsonb_array_length(v_result->'items'),
      'total_count',v_result->'total_count'));
  return v_result;
end
$$;

--
-- Name: FUNCTION platform_list_firm_attention_v88(p_snapshot_at timestamp with time zone, p_limit integer, p_after_days_unattended integer, p_after_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.platform_list_firm_attention_v88(p_snapshot_at timestamp with time zone, p_limit integer, p_after_days_unattended integer, p_after_id uuid) IS 'v88 deterministic SA-only stale-attention queue. No external delivery or mutable notification state.';

--
-- Name: platform_list_firm_onboarding_v88(jsonb, timestamp with time zone, integer, timestamp with time zone, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_list_firm_onboarding_v88(p_filters jsonb DEFAULT '{}'::jsonb, p_snapshot_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_limit integer DEFAULT 100, p_after_updated_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_after_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid:=auth.uid();
  v_snapshot timestamptz:=coalesce(p_snapshot_at,clock_timestamp());
  v_snapshot_expires_at timestamptz;
  v_limit integer:=least(greatest(coalesce(p_limit,100),1),250);
  v_filters jsonb:=jsonb_strip_nulls(coalesce(p_filters,'{}'::jsonb));
  v_result jsonb;
begin
  if not app.is_super_admin() then
    raise exception 'super admin access is required' using errcode='42501';
  end if;
  perform app.v86_assert_object_keys(v_filters,array[
    'search','lane','sector','onboarding_status','subscription_status',
    'attention_severity','attention_due'
  ],'firm onboarding filters');
  if (p_after_updated_at is null)<>(p_after_id is null) then
    raise exception 'complete firm cursor is required' using errcode='22023';
  end if;
  if p_snapshot_at is null and p_after_updated_at is not null then
    raise exception 'snapshot token is required after the first page' using errcode='22023';
  end if;
  if v_filters?'attention_due'
     and v_filters->>'attention_due' not in ('true','false') then
    raise exception 'attention_due must be a boolean' using errcode='22023';
  end if;
  v_snapshot_expires_at:=app.ensure_platform_firm_snapshot_v88(
    v_actor,v_snapshot,p_snapshot_at is null
  );

  with filtered as materialized (
    select firm.*
    from app.platform_firm_snapshot_rows_v88 firm
    where firm.actor_id=v_actor and firm.snapshot_at=v_snapshot
      and (nullif(v_filters->>'lane','') is null or firm.lane_key=v_filters->>'lane')
      and (nullif(v_filters->>'sector','') is null
        or firm.sector_key=v_filters->>'sector' or firm.industry=v_filters->>'sector')
      and (nullif(v_filters->>'onboarding_status','') is null
        or firm.onboarding_status=v_filters->>'onboarding_status')
      and (nullif(v_filters->>'subscription_status','') is null
        or firm.subscription_status=v_filters->>'subscription_status')
      and (nullif(v_filters->>'attention_severity','') is null
        or firm.attention_severity=v_filters->>'attention_severity')
      and (not (v_filters?'attention_due')
        or firm.attention_due=(v_filters->>'attention_due')::boolean)
      and (nullif(btrim(v_filters->>'search'),'') is null
        or firm.search_text like '%'||lower(btrim(v_filters->>'search'))||'%')
  ), page as materialized (
    select firm.*
    from filtered firm
    where p_after_updated_at is null
       or (firm.updated_at,firm.row_id)<(p_after_updated_at,p_after_id)
    order by firm.updated_at desc,firm.row_id desc
    limit v_limit
  )
  select jsonb_build_object(
    'snapshot_at',v_snapshot,
    'snapshot_expires_at',v_snapshot_expires_at,
    'items',coalesce((select jsonb_agg(
      item.payload||jsonb_build_object('id',item.row_id,'total_count',(select count(*) from filtered))
      order by item.updated_at desc,item.row_id desc
    ) from page item),'[]'::jsonb),
    'next_cursor',(select jsonb_build_object('updated_at',item.updated_at,'id',item.row_id)
      from page item order by item.updated_at,item.row_id limit 1),
    'total_count',(select count(*) from filtered),
    'attention_summary',jsonb_build_object(
      'due',(select count(*) from filtered where attention_due),
      'critical',(select count(*) from filtered where attention_severity='critical'),
      'warning',(select count(*) from filtered where attention_severity='warning'),
      'info',(select count(*) from filtered where attention_severity='info')
    )
  ) into v_result;

  insert into public.audit_log(business_id,actor,action,entity,detail)
  values(null,auth.uid(),'PLATFORM_FIRM_ONBOARDING_READ_V88','businesses',
    jsonb_build_object('snapshot_at',v_snapshot,'filters',v_filters,
      'limit',v_limit,'result_count',jsonb_array_length(v_result->'items'),
      'total_count',v_result->'total_count'));
  return v_result;
end
$$;

--
-- Name: FUNCTION platform_list_firm_onboarding_v88(p_filters jsonb, p_snapshot_at timestamp with time zone, p_limit integer, p_after_updated_at timestamp with time zone, p_after_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.platform_list_firm_onboarding_v88(p_filters jsonb, p_snapshot_at timestamp with time zone, p_limit integer, p_after_updated_at timestamp with time zone, p_after_id uuid) IS 'v88 SA-only unified prospect/business onboarding directory. Keyset-paginated, searchable and de-duplicated; exposes owner contact only through this guarded reader.';

--
-- Name: platform_list_my_access_v89(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_list_my_access_v89() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_role text:=app.v89_platform_role();v_perms jsonb;
begin
  if v_role is null then raise exception 'platform access is required' using errcode='42501';end if;
  v_perms:=case when v_role='super_admin' then jsonb_build_object('*','rw')
    else coalesce((select module_perms from public.platform_access_grants_v89
      where user_id=auth.uid() and active),'{}'::jsonb) end;
  return jsonb_build_object('role',v_role,'module_perms',v_perms,
    'scope',case when v_role='sales_staff' then 'own_created_or_assigned' else 'all' end);
end
$$;

--
-- Name: platform_list_my_firms_v105(text, integer, timestamp with time zone, timestamp with time zone, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_list_my_firms_v105(p_search text DEFAULT NULL::text, p_limit integer DEFAULT 50, p_snapshot_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_after_updated_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_after_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid:=auth.uid();
  v_limit integer:=least(greatest(coalesce(p_limit,50),1),100);
  v_snapshot_at timestamptz:=coalesce(p_snapshot_at,clock_timestamp());
  v_snapshot_expires_at timestamptz;
  v_current_scope text:=case when app.v89_platform_role()='sales_staff'
    then 'own_created_or_assigned' else 'all' end;
  v_captured_scope text;
  v_result jsonb;
begin
  if not (
    app.v89_platform_can('overview','r')
    or app.v89_platform_can('onboarding','r')
    or app.v89_platform_can('firms','r')
    or app.v89_platform_can('reports','r')
  ) then
    raise exception 'platform firm-list read access is required' using errcode='42501';
  end if;
  if (p_after_updated_at is null)<>(p_after_id is null) then
    raise exception 'complete firm cursor is required' using errcode='22023';
  end if;
  if p_snapshot_at is null and p_after_updated_at is not null then
    raise exception 'snapshot token is required after the first page'
      using errcode='22023';
  end if;

  v_snapshot_expires_at:=app.ensure_platform_firm_snapshot_v88(
    v_actor,v_snapshot_at,p_snapshot_at is null
  );

  if p_snapshot_at is null then
    insert into app.platform_firm_snapshot_scopes_v105(
      actor_id,snapshot_at,scope_key
    ) values(v_actor,v_snapshot_at,v_current_scope)
    on conflict(actor_id,snapshot_at) do nothing;

    if v_current_scope='own_created_or_assigned' then
      delete from app.platform_firm_snapshot_rows_v88 snapshot_row
      where snapshot_row.actor_id=v_actor
        and snapshot_row.snapshot_at=v_snapshot_at
        and (
          nullif(snapshot_row.payload->>'prospect_id','') is null
          or not app.v89_prospect_in_role_scope(
            (snapshot_row.payload->>'prospect_id')::uuid
          )
        );
    end if;
  end if;

  select scope_row.scope_key into v_captured_scope
  from app.platform_firm_snapshot_scopes_v105 scope_row
  where scope_row.actor_id=v_actor
    and scope_row.snapshot_at=v_snapshot_at;
  if v_captured_scope is null then
    raise exception 'delegated firm snapshot token was not found'
      using errcode='22023';
  end if;
  if v_current_scope='own_created_or_assigned' and v_captured_scope='all' then
    raise exception 'firm snapshot scope is no longer permitted'
      using errcode='42501';
  end if;

  with eligible as materialized (
    select snapshot_row.*
    from app.platform_firm_snapshot_rows_v88 snapshot_row
    where snapshot_row.actor_id=v_actor
      and snapshot_row.snapshot_at=v_snapshot_at
      and (
        nullif(btrim(p_search),'') is null
        or snapshot_row.search_text like '%'||lower(btrim(p_search))||'%'
      )
  ), page as materialized (
    select snapshot_row.*
    from eligible snapshot_row
    where p_after_updated_at is null
       or (snapshot_row.updated_at,snapshot_row.row_id)
          <(p_after_updated_at,p_after_id)
    order by snapshot_row.updated_at desc,snapshot_row.row_id desc
    limit v_limit
  )
  select jsonb_build_object(
    'items',coalesce((
      select jsonb_agg(item.payload
        order by item.updated_at desc,item.row_id desc)
      from page item
    ),'[]'::jsonb),
    'scope',v_captured_scope,
    'snapshot_at',v_snapshot_at,
    'snapshot_expires_at',v_snapshot_expires_at,
    'total_count',(select count(*) from eligible),
    'next_cursor',case when (select count(*) from page)=v_limit then (
      select jsonb_build_object('updated_at',item.updated_at,'id',item.row_id)
      from page item order by item.updated_at,item.row_id limit 1
    ) else null end
  ) into v_result;
  return v_result;
end
$$;

--
-- Name: FUNCTION platform_list_my_firms_v105(p_search text, p_limit integer, p_snapshot_at timestamp with time zone, p_after_updated_at timestamp with time zone, p_after_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.platform_list_my_firms_v105(p_search text, p_limit integer, p_snapshot_at timestamp with time zone, p_after_updated_at timestamp with time zone, p_after_id uuid) IS 'v105 role-scoped, searchable, fixed-snapshot keyset-paginated delegated firm and prospect directory.';

--
-- Name: platform_list_my_firms_v89(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_list_my_firms_v89(p_search text DEFAULT NULL::text, p_limit integer DEFAULT 100) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_limit integer:=least(greatest(coalesce(p_limit,100),1),250);
  v_result jsonb;
begin
  if not (
    app.v89_platform_can('overview','r')
    or app.v89_platform_can('onboarding','r')
    or app.v89_platform_can('firms','r')
    or app.v89_platform_can('reports','r')
  ) then
    raise exception 'platform firm-list read access is required' using errcode='42501';
  end if;
  select jsonb_build_object('items',coalesce(jsonb_agg(row_data.payload
    order by row_data.updated_at desc,row_data.row_id desc),'[]'::jsonb),
    'scope',case when app.v89_platform_role()='sales_staff'
      then 'own_created_or_assigned' else 'all' end,
    'truncated',(select count(*)>v_limit from app.platform_firm_rows_v88(now()) all_rows
      where (
        (all_rows.prospect_id is not null
          and app.v89_prospect_in_role_scope(all_rows.prospect_id))
        or (all_rows.prospect_id is null
          and app.v89_platform_role() in ('super_admin','admin'))
      )
        and (nullif(btrim(p_search),'') is null or lower(concat_ws(' ',
          all_rows.name,all_rows.legal_name,all_rows.registration_number,
          all_rows.boss_name,all_rows.boss_email,all_rows.boss_phone))
          like '%'||lower(btrim(p_search))||'%'))
  ) into v_result
  from (
    select row_source.row_id,row_source.updated_at,to_jsonb(row_source) payload
    from app.platform_firm_rows_v88(now()) row_source
    where (
      (row_source.prospect_id is not null
        and app.v89_prospect_in_role_scope(row_source.prospect_id))
      or (row_source.prospect_id is null
        and app.v89_platform_role() in ('super_admin','admin'))
    )
      and (nullif(btrim(p_search),'') is null or lower(concat_ws(' ',
        row_source.name,row_source.legal_name,row_source.registration_number,
        row_source.boss_name,row_source.boss_email,row_source.boss_phone))
        like '%'||lower(btrim(p_search))||'%')
    order by row_source.updated_at desc,row_source.row_id desc limit v_limit
  ) row_data;
  return v_result;
end
$$;

--
-- Name: platform_list_partner_obligations_v282(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_list_partner_obligations_v282(p_limit integer DEFAULT 100) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_limit integer;
  v_partners jsonb;
  v_disclosures jsonb;
  v_suppressions jsonb;
begin
  if v_actor is null then
    raise exception 'authenticated platform session is required' using errcode = '28000';
  end if;
  if not app.is_super_admin() then
    raise exception 'partner obligations are super admin only' using errcode = '42501';
  end if;
  if p_limit is null or p_limit not between 1 and 500 then
    raise exception 'row limit must be 1..500' using errcode = '22023';
  end if;
  v_limit := p_limit;

  select coalesce(jsonb_agg(entry order by entry->>'name'), '[]'::jsonb)
    into v_partners
  from (
    select jsonb_build_object(
      'id', partner.id,
      'name', partner.name,
      'purpose', partner.purpose,
      'status', partner.status,
      'created_at', partner.created_at,
      'updated_at', partner.updated_at,
      'disclosure_count', (
        select count(*) from public.partner_disclosures_v282 disclosure
         where disclosure.partner_id = partner.id
      ),
      'open_suppressions', (
        select count(*) from public.partner_suppressions_v282 suppression
         where suppression.partner_id = partner.id
           and suppression.acknowledged_at is null
      )
    ) as entry
    from public.partner_registry_v282 partner
    order by partner.name
    limit v_limit
  ) as partners;

  -- Customers are counted, never listed: a cross-tenant console has no reason
  -- to render a person's identity, and a partner ledger that leaks the roster
  -- it exists to protect would be self-defeating.
  select coalesce(jsonb_agg(entry order by entry->>'disclosed_on' desc), '[]'::jsonb)
    into v_disclosures
  from (
    select jsonb_build_object(
      'partner_id', disclosure.partner_id,
      'partner_name', partner.name,
      'dataset', disclosure.dataset,
      'scope_version', disclosure.scope_version,
      'disclosed_on', to_char(
        date_trunc('day', disclosure.disclosed_at at time zone 'Asia/Singapore'),
        'YYYY-MM-DD'),
      'customers', count(*)
    ) as entry
    from public.partner_disclosures_v282 disclosure
    join public.partner_registry_v282 partner on partner.id = disclosure.partner_id
    group by disclosure.partner_id, partner.name, disclosure.dataset,
             disclosure.scope_version,
             date_trunc('day', disclosure.disclosed_at at time zone 'Asia/Singapore')
    order by date_trunc('day', disclosure.disclosed_at at time zone 'Asia/Singapore') desc
    limit v_limit
  ) as disclosures;

  select coalesce(jsonb_agg(entry order by entry->>'issued_at' desc), '[]'::jsonb)
    into v_suppressions
  from (
    select jsonb_build_object(
      'id', suppression.id,
      'partner_id', suppression.partner_id,
      'partner_name', partner.name,
      'reason', suppression.reason,
      'issued_at', suppression.issued_at,
      'acknowledged_at', suppression.acknowledged_at,
      'acknowledgement_reference', suppression.acknowledgement_reference,
      'scope', case when suppression.identity_id is null
        then 'all_customers' else 'one_customer' end
    ) as entry
    from public.partner_suppressions_v282 suppression
    join public.partner_registry_v282 partner on partner.id = suppression.partner_id
    order by suppression.issued_at desc
    limit v_limit
  ) as suppressions;

  return jsonb_build_object(
    'status', 'ok',
    'partners', v_partners,
    'disclosures', v_disclosures,
    'suppressions', v_suppressions);
end;
$$;

--
-- Name: platform_list_prospect_audit_v86(uuid, timestamp with time zone, integer, timestamp with time zone, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_list_prospect_audit_v86(p_prospect uuid, p_snapshot_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_limit integer DEFAULT 100, p_after_created_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_after_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_snapshot timestamptz:=coalesce(p_snapshot_at,clock_timestamp());v_limit integer:=least(greatest(coalesce(p_limit,100),1),200);
begin
  if not app.can_access_prospect_sensitive_v86(p_prospect) then
    raise exception 'assigned consultant or super admin access is required' using errcode='42501';end if;
  if (p_after_created_at is null)<>(p_after_id is null) then
    raise exception 'complete audit cursor is required' using errcode='22023';end if;
  return jsonb_build_object(
    'snapshot_at',v_snapshot,
    'items',coalesce((select jsonb_agg(to_jsonb(page) order by page.created_at desc,page.id desc) from(
      select audit.id,audit.actor,audit.action,audit.entity,audit.entity_id,audit.detail,audit.created_at
      from public.audit_log audit where audit.created_at<=v_snapshot and (
        (audit.entity='sme_prospects' and audit.entity_id=p_prospect)
        or audit.detail->>'prospect_id'=p_prospect::text
      ) and (p_after_created_at is null or (audit.created_at,audit.id)<(p_after_created_at,p_after_id))
      order by audit.created_at desc,audit.id desc limit v_limit
    ) page),'[]'::jsonb),
    'next_cursor',(select jsonb_build_object('created_at',page.created_at,'id',page.id) from(
      select audit.id,audit.created_at from public.audit_log audit where audit.created_at<=v_snapshot and (
        (audit.entity='sme_prospects' and audit.entity_id=p_prospect)
        or audit.detail->>'prospect_id'=p_prospect::text
      ) and (p_after_created_at is null or (audit.created_at,audit.id)<(p_after_created_at,p_after_id))
      order by audit.created_at desc,audit.id desc limit v_limit
    ) page order by page.created_at,page.id limit 1)
  );
end
$$;

--
-- Name: platform_list_prospects_v76(text, uuid, text, integer, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_list_prospects_v76(p_stage text DEFAULT NULL::text, p_consultant uuid DEFAULT NULL::uuid, p_search text DEFAULT NULL::text, p_limit integer DEFAULT 100, p_before timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_limit integer:=least(greatest(coalesce(p_limit,100),1),250);
begin
  if not app.is_platform_operator_v75() then
    raise exception 'platform operator access is required' using errcode='42501';
  end if;
  if p_stage is not null and p_stage<>'unmapped'
     and not exists(select 1 from public.sme_pipeline_stages where stage_key=p_stage) then
    raise exception 'unknown SME stage' using errcode='22023';
  end if;
  return jsonb_build_object(
    'items',coalesce((select jsonb_agg(item.card order by item.updated_at desc)
      from (select app.sme_prospect_card_v76(prospect.id) card,prospect.updated_at
        from public.sme_prospects prospect join public.sme_companies company on company.id=prospect.company_id
        where (p_stage is null or (p_stage='unmapped' and prospect.current_stage_key is null)
          or prospect.current_stage_key=p_stage)
          and (p_consultant is null or prospect.assigned_consultant_id=p_consultant)
          and (p_before is null or prospect.updated_at<p_before)
          and app.sme_prospect_search_match_v76(prospect.id,p_search) and prospect.archived_at is null
        order by prospect.updated_at desc limit v_limit) item),'[]'::jsonb),
    'next_before',(select min(item.updated_at) from (
      select prospect.updated_at from public.sme_prospects prospect
      join public.sme_companies company on company.id=prospect.company_id
      where (p_stage is null or (p_stage='unmapped' and prospect.current_stage_key is null)
        or prospect.current_stage_key=p_stage)
        and (p_consultant is null or prospect.assigned_consultant_id=p_consultant)
        and (p_before is null or prospect.updated_at<p_before)
        and app.sme_prospect_search_match_v76(prospect.id,p_search) and prospect.archived_at is null
      order by prospect.updated_at desc limit v_limit) item),
    'unmapped_count',(select count(*) from public.sme_prospects where current_stage_key is null)
  );
end
$$;

--
-- Name: platform_list_receipts_v199(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_list_receipts_v199(p_status text DEFAULT NULL::text, p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_limit integer:=least(greatest(coalesce(p_limit,50),1),200);
begin
  if auth.uid() is null or not app.is_super_admin() then
    raise exception 'super-admin access is required' using errcode='42501';
  end if;
  if p_status is not null and p_status not in
     ('uploaded','extracted','extraction_failed','posted','discarded') then
    raise exception 'unknown receipt status' using errcode='22023';
  end if;
  return jsonb_build_object(
    'items',coalesce((select jsonb_agg(to_jsonb(row) order by row.created_at desc)
      from (select * from public.platform_accounting_receipts_v199 receipt
             where p_status is null or receipt.status=p_status
             order by receipt.created_at desc limit v_limit) row),'[]'::jsonb),
    'counts',(select jsonb_object_agg(status,n) from
      (select status,count(*) n from public.platform_accounting_receipts_v199
        group by status) totals));
end $$;

--
-- Name: platform_list_sector_entitlements_v75(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_list_sector_entitlements_v75() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if not app.is_super_admin() then
    raise exception 'super admin access is required' using errcode = '42501';
  end if;
  return jsonb_build_object(
    'profiles', coalesce((
      select jsonb_agg(jsonb_build_object(
        'sector_key', profile.sector_key, 'label', profile.label, 'active', profile.active,
        'published_version', case when bundle.id is null then null else jsonb_build_object(
          'id', bundle.id, 'version', bundle.version, 'label', bundle.label,
          'modules', to_jsonb(bundle.modules), 'published_at', bundle.published_at
        ) end
      ) order by profile.label)
        from public.sector_profiles profile
        left join public.sector_bundle_versions bundle
          on bundle.sector_key = profile.sector_key and bundle.status = 'published'
    ), '[]'::jsonb),
    'businesses', coalesce((
      select jsonb_agg(jsonb_build_object(
        'business_id', business.id, 'business_name', business.name,
        'industry', business.industry, 'assignment_version', assignment.version,
        'bundle_version_id', bundle.id, 'sector_key', bundle.sector_key,
        'bundle_version', bundle.version, 'override_version_id', override_row.id,
        'effective_modules', to_jsonb(app.resolve_sector_entitlement_v75(
          bundle.id, coalesce(override_row.add_modules, '{}'::text[]),
          coalesce(override_row.remove_modules, '{}'::text[])
        ))
      ) order by business.name)
        from public.business_sector_assignments assignment
        join public.businesses business on business.id = assignment.business_id
        join public.sector_bundle_versions bundle on bundle.id = assignment.bundle_version_id
        left join public.business_sector_override_versions override_row
          on override_row.id = assignment.override_version_id
    ), '[]'::jsonb)
  );
end
$$;

--
-- Name: platform_list_sector_firms_v89(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_list_sector_firms_v89() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if not app.v89_platform_can('sectors','r') then
    raise exception 'platform sectors read access is required'
      using errcode='42501';
  end if;
  return jsonb_build_object('items',coalesce((
    select jsonb_agg(jsonb_build_object(
      'id',business.id,'name',business.name,'industry',business.industry,
      'enabled_modules',to_jsonb(business.enabled_modules),
      'source_prospect_id',business.source_prospect_id
    ) order by lower(business.name),business.id)
    from public.businesses business
  ),'[]'::jsonb));
end
$$;

--
-- Name: platform_lookup_access_user_v89(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_lookup_access_user_v89(p_query text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_query text:=lower(nullif(btrim(p_query),''));v_items jsonb;
  v_count integer;
begin
  if not app.is_super_admin() then
    raise exception 'super-admin access is required' using errcode='42501';
  end if;
  if length(coalesce(v_query,''))<3 or length(v_query)>160 then
    raise exception 'enter at least 3 characters' using errcode='22023';
  end if;
  with matches as (
    select auth_user.id user_id,auth_user.email,
      nullif(btrim(coalesce(auth_user.raw_user_meta_data->>'full_name',
        auth_user.raw_user_meta_data->>'name','')),'') display_name,
      case when lower(coalesce(auth_user.email,''))=v_query then 0 else 1 end rank
    from auth.users auth_user
    where lower(coalesce(auth_user.email,''))=v_query
       or lower(coalesce(auth_user.email,'')) like '%'||v_query||'%'
       or lower(coalesce(auth_user.raw_user_meta_data->>'full_name',
         auth_user.raw_user_meta_data->>'name','')) like '%'||v_query||'%'
    order by rank,lower(coalesce(auth_user.email,'')),auth_user.id limit 20
  )
  select count(*)::integer,coalesce(jsonb_agg(jsonb_build_object(
    'user_id',match.user_id,'email',match.email,
    'display_name',match.display_name
  ) order by match.rank,lower(coalesce(match.email,'')),match.user_id),'[]'::jsonb)
  into v_count,v_items from matches match;
  return jsonb_build_object(
    'status',case when v_count=0 then 'not_found'
      when v_count=1 then 'matched' else 'ambiguous' end,
    'items',v_items
  );
end
$$;

--
-- Name: platform_mark_demo_request_v292(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_mark_demo_request_v292(p_request uuid, p_status text, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_status text := nullif(btrim(coalesce(p_status, '')), '');
  v_note text := nullif(btrim(coalesce(p_note, '')), '');
  v_id uuid;
begin
  if v_actor is null then
    raise exception 'authenticated platform session is required' using errcode = '28000';
  end if;
  if not app.is_super_admin() then
    raise exception 'demo requests are super admin only' using errcode = '42501';
  end if;
  if v_status is null or v_status not in ('new', 'contacted', 'archived') then
    raise exception 'demo request status must be new, contacted or archived' using errcode = '22023';
  end if;
  if v_note is not null and length(v_note) > 500 then
    raise exception 'a triage note must be 500 characters or fewer' using errcode = '22023';
  end if;

  update public.demo_requests_v292 request
     set status = v_status,
         triage_note = coalesce(v_note, request.triage_note),
         contacted_at = case
           when v_status = 'contacted' then coalesce(request.contacted_at, now())
           else request.contacted_at end,
         contacted_by = case
           when v_status = 'contacted' then coalesce(request.contacted_by, v_actor)
           else request.contacted_by end
   where request.id = p_request
  returning request.id into v_id;

  if v_id is null then
    raise exception 'no demo request with that id' using errcode = '22023';
  end if;

  return jsonb_build_object('status', 'ok', 'request_id', v_id, 'demo_status', v_status);
end;
$$;

--
-- Name: FUNCTION platform_mark_demo_request_v292(p_request uuid, p_status text, p_note text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.platform_mark_demo_request_v292(p_request uuid, p_status text, p_note text) IS 'V292: records the admin decision on one demo request. Idempotent on re-marking; contacted_at and contacted_by keep their FIRST value.';

--
-- Name: platform_merchant_matches_v312(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_merchant_matches_v312(p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  perform app.v297_assert_prospecting('r');
  if not (app.is_super_admin() or app.v89_platform_role()='admin') then
    raise exception 'merchant match review requires admin' using errcode='42501';
  end if;
  return coalesce((select jsonb_agg(jsonb_build_object(
      'id', m.id, 'company_id', m.company_id, 'business_id', m.business_id,
      'company_name', coalesce(c.trading_name, c.legal_name),
      'merchant_name', coalesce(b.legal_name, b.name),
      'company_postal', l.postal_code, 'merchant_postal', b.postal_code,
      'match_basis', m.match_basis, 'created_at', m.created_at))
    from public.sme_merchant_match_candidates m
    join public.sme_companies c on c.id=m.company_id
    join public.businesses b on b.id=m.business_id
    left join public.sme_company_locations l on l.company_id=c.id and l.is_primary
   where m.status='pending'
   order by m.created_at desc
   limit greatest(least(coalesce(p_limit,50),200),1)),'[]'::jsonb);
end $$;

--
-- Name: platform_merge_prospects_v184(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_merge_prospects_v184(p_source uuid, p_target uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid:=auth.uid();
  v_source public.sme_prospects%rowtype;
  v_target public.sme_prospects%rowtype;
  v_moved jsonb:='{}'::jsonb;
  v_count integer;
begin
  if not app.is_super_admin() then
    raise exception 'super admin access is required' using errcode='42501';
  end if;
  if p_source is null or p_target is null or p_source=p_target then
    raise exception 'choose two different firm records to merge' using errcode='22023';
  end if;
  if coalesce(btrim(p_reason),'')='' then
    raise exception 'a reason is required to merge firm records' using errcode='22023';
  end if;
  select * into v_source from public.sme_prospects where id=p_source;
  if not found then raise exception 'source firm record not found' using errcode='22023'; end if;
  select * into v_target from public.sme_prospects where id=p_target;
  if not found then raise exception 'surviving firm record not found' using errcode='22023'; end if;
  if v_source.archived_at is not null then
    raise exception 'the record being merged away is already archived' using errcode='22023';
  end if;
  if v_target.archived_at is not null then
    raise exception 'the surviving record is archived; restore it first' using errcode='22023';
  end if;
  -- The source disappears from the board, so it must satisfy the same rule as
  -- a plain archive: nothing may have become a workspace from it.
  perform app.v184_assert_archivable(p_source);

  -- Working data follows the survivor.
  -- An incoming contact never displaces the survivor's primary contact.
  update public.sme_prospect_contacts source_contact
     set prospect_id=p_target,
         is_primary=case when exists(select 1 from public.sme_prospect_contacts e
           where e.prospect_id=p_target and e.is_primary) then false else is_primary end
   where source_contact.prospect_id=p_source
     and not exists (
       select 1 from public.sme_prospect_contacts kept
        where kept.prospect_id=p_target
          and (
            (source_contact.email is not null and kept.email is not null
              and lower(btrim(kept.email))=lower(btrim(source_contact.email)))
            or (source_contact.email is null and kept.email is null
              and source_contact.phone is not null and kept.phone is not null
              and btrim(kept.phone)=btrim(source_contact.phone))
          )
     );
  get diagnostics v_count=row_count; v_moved:=v_moved||jsonb_build_object('contacts',v_count);
  select count(*) into v_count from public.sme_prospect_contacts
   where prospect_id=p_source;
  v_moved:=v_moved||jsonb_build_object('duplicate_contacts',v_count);

  update public.sme_prospect_activities set prospect_id=p_target where prospect_id=p_source;
  get diagnostics v_count=row_count; v_moved:=v_moved||jsonb_build_object('activities',v_count);

  update public.sme_prospect_tasks set prospect_id=p_target where prospect_id=p_source;
  get diagnostics v_count=row_count; v_moved:=v_moved||jsonb_build_object('tasks',v_count);

  update public.sme_document_versions set prospect_id=p_target where prospect_id=p_source;
  get diagnostics v_count=row_count; v_moved:=v_moved||jsonb_build_object('documents',v_count);

  select count(*) into v_count from public.sme_prospect_source_lineage
   where prospect_id=p_source;
  v_moved:=v_moved||jsonb_build_object('source_lineage_retained',v_count);

  -- Tags are keyed (prospect_id, tag_id): drop the ones the survivor already
  -- carries, then move the rest.
  delete from public.sme_prospect_tags source_tag
   where source_tag.prospect_id=p_source
     and exists(select 1 from public.sme_prospect_tags kept
                 where kept.prospect_id=p_target and kept.tag_id=source_tag.tag_id);
  update public.sme_prospect_tags set prospect_id=p_target where prospect_id=p_source;
  get diagnostics v_count=row_count; v_moved:=v_moved||jsonb_build_object('tags',v_count);

  -- History, evidence and quality stay with the record they describe.
  update public.sme_prospects
     set archived_at=now(), archived_by=v_actor,
         archive_reason=btrim(p_reason), merged_into_prospect_id=p_target,
         updated_at=now(), updated_by=v_actor
   where id=p_source;
  update public.sme_prospects
     set updated_at=now(), updated_by=v_actor
   where id=p_target;

  insert into public.audit_log(business_id,actor,action,entity,entity_id,detail)
  values(null,v_actor,'PLATFORM_PROSPECTS_MERGED_V184','sme_prospects',p_target,
    jsonb_build_object('source',p_source,'target',p_target,
      'reason',btrim(p_reason),'moved',v_moved));
  return jsonb_build_object('status','merged','source',p_source,'target',p_target,
    'moved',v_moved);
end $$;

--
-- Name: platform_move_my_prospect_stage_v89(uuid, text, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_move_my_prospect_stage_v89(p_prospect uuid, p_to_stage text, p_expected_version bigint, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_row public.sme_prospects%rowtype;v_from text;
begin
  if not app.v89_platform_can('onboarding','rw')
     or not app.v89_can_access_prospect(p_prospect) then
    raise exception 'scoped onboarding write access is required' using errcode='42501';
  end if;
  select * into v_row from public.sme_prospects where id=p_prospect for update;
  if not found or v_row.version<>p_expected_version then
    raise exception 'prospect version conflict' using errcode='40001';
  end if;
  if not exists(select 1 from public.sme_pipeline_stages where stage_key=p_to_stage) then
    raise exception 'unknown prospect stage' using errcode='22023';
  end if;
  v_from:=v_row.current_stage_key;
  update public.sme_prospects set current_stage_key=p_to_stage,
    stage_entered_at=now(),version=version+1,updated_by=auth.uid(),updated_at=now()
  where id=p_prospect returning * into v_row;
  insert into public.sme_prospect_stage_history(
    prospect_id,from_stage_key,to_stage_key,reason_detail,actor
  ) values(p_prospect,v_from,p_to_stage,nullif(btrim(p_reason),''),auth.uid());
  insert into public.audit_log(business_id,actor,action,entity,entity_id,detail)
  values(v_row.converted_business_id,auth.uid(),'PLATFORM_MOVE_MY_PROSPECT_STAGE_V89',
    'sme_prospects',p_prospect,jsonb_build_object(
      'from_stage',v_from,'to_stage',p_to_stage,'version',v_row.version));
  return jsonb_build_object('prospect_id',p_prospect,'stage_key',p_to_stage,
    'version',v_row.version,'updated_at',v_row.updated_at);
end
$$;

--
-- Name: platform_move_prospect_stage_v76(uuid, text, bigint, text, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_move_prospect_stage_v76(p_prospect uuid, p_to_stage text, p_expected_version bigint, p_reason_code text DEFAULT NULL::text, p_reason_detail text DEFAULT NULL::text, p_commercial_terms jsonb DEFAULT NULL::jsonb, p_idempotency_key text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $_$
declare
  v_actor uuid:=auth.uid();v_hash text;v_replay jsonb;v_row public.sme_prospects%rowtype;
  v_from text;v_event uuid;v_activity uuid;v_terms_version integer;v_response jsonb;
  v_lost_codes constant text[]:=array[
    'no_response','not_interested','no_budget','timing','chose_competitor',
    'missing_required_feature','procurement_security_blocker','price',
    'internal_priority_changed','business_ceased','duplicate','bad_fit','other'
  ];
begin
  if not app.is_platform_operator_v75() then raise exception 'platform operator access is required' using errcode='42501';end if;
  if not exists(select 1 from public.sme_pipeline_stages where stage_key=p_to_stage) then
    raise exception 'unknown SME stage' using errcode='22023';end if;
  -- System-managed stages are driven by the conversion machinery, never chosen
  -- by hand. Read the flag rather than a hard-coded list, so the guard tracks
  -- the pipeline instead of drifting from it.
  if exists(select 1 from public.sme_pipeline_stages where stage_key=p_to_stage and is_system) then
    raise exception 'this SME stage is system-managed and requires conversion evidence'
      using errcode='42501';end if;
  if p_to_stage='lost' and (p_reason_code is null or not (p_reason_code=any(v_lost_codes))) then
    raise exception 'Lost requires a structured reason code' using errcode='22023';end if;
  if p_to_stage='lost' and p_reason_code='other' and length(btrim(coalesce(p_reason_detail,'')))<3 then
    raise exception 'Lost reason other requires detail' using errcode='22023';end if;
  if p_to_stage='client' and (
    p_commercial_terms is null or jsonb_typeof(p_commercial_terms)<>'object'
    or coalesce(p_commercial_terms->>'plan_code','')=''
    or coalesce(p_commercial_terms->>'product_code','')=''
    or coalesce(p_commercial_terms->>'billing_cycle','') not in ('quarterly','half_yearly','annual')
    or coalesce((p_commercial_terms->>'seats')::integer,0)<=0
    or coalesce(p_commercial_terms->>'currency','')!~'^[A-Z]{3}$'
    or coalesce(p_commercial_terms->>'owner_email','') not like '%@%'
    or coalesce(p_commercial_terms->>'contract_status','') not in ('accepted','signed')
  ) then raise exception 'Client requires accepted commercial fields' using errcode='22023';end if;
  v_hash:=app.v76_sha256_hex(jsonb_build_object('prospect',p_prospect,'to',p_to_stage,
    'version',p_expected_version,'reason_code',p_reason_code,'reason_detail',p_reason_detail,
    'commercial_terms',p_commercial_terms)::text);
  v_replay:=app.v76_replay(v_actor,'move_stage',p_idempotency_key,v_hash);if v_replay is not null then return v_replay;end if;
  select * into v_row from public.sme_prospects where id=p_prospect and version=p_expected_version for update;
  if not found then raise exception 'prospect version conflict' using errcode='40001';end if;
  v_from:=v_row.current_stage_key;
  update public.sme_prospects set current_stage_key=p_to_stage,legacy_stage_raw=null,
    stage_entered_at=now(),version=version+1,updated_by=v_actor,updated_at=now()
   where id=p_prospect returning * into v_row;
  insert into public.sme_prospect_stage_history(prospect_id,from_stage_key,to_stage_key,reason_code,reason_detail,actor)
  values(p_prospect,v_from,p_to_stage,p_reason_code,nullif(btrim(p_reason_detail),''),v_actor) returning id into v_event;
  if p_commercial_terms is not null then
    select coalesce(max(version),0)+1 into v_terms_version from public.sme_commercial_terms where prospect_id=p_prospect;
    insert into public.sme_commercial_terms(
      prospect_id,version,plan_code,product_code,billing_cycle,seats,currency,
      accepted_value_cents,owner_email,onboarding_owner_consultant_id,target_go_live,
      contract_status,accepted_at,notes,created_by
    ) values(p_prospect,v_terms_version,btrim(p_commercial_terms->>'plan_code'),
      btrim(p_commercial_terms->>'product_code'),p_commercial_terms->>'billing_cycle',
      (p_commercial_terms->>'seats')::integer,p_commercial_terms->>'currency',
      coalesce((p_commercial_terms->>'accepted_value_cents')::integer,0),
      lower(btrim(p_commercial_terms->>'owner_email')),
      nullif(p_commercial_terms->>'onboarding_owner_consultant_id','')::uuid,
      nullif(p_commercial_terms->>'target_go_live','')::date,
      p_commercial_terms->>'contract_status',
      case when p_commercial_terms->>'contract_status' in ('accepted','signed')
        then coalesce((p_commercial_terms->>'accepted_at')::timestamptz,now()) else null end,
      p_commercial_terms->>'notes',v_actor);
  end if;
  insert into public.audit_log(business_id,actor,action,entity,entity_id,detail)
  values(null,v_actor,'SME_PROSPECT_STAGE_MOVED_V76','sme_prospects',p_prospect,
    jsonb_build_object('from_stage',v_from,'to_stage',p_to_stage,'reason_code',p_reason_code,
      'new_version',v_row.version,'commercial_terms_version',v_terms_version));
  v_response:=jsonb_build_object('replayed',false,'prospect',app.sme_prospect_card_v76(p_prospect),
    'stage_event',(select to_jsonb(h) from public.sme_prospect_stage_history h where id=v_event),
    'activity',(select to_jsonb(a) from public.sme_prospect_activities a where id=v_activity));
  perform app.v76_store_receipt(v_actor,'move_stage',p_idempotency_key,v_hash,v_response);return v_response;
end
$_$;

--
-- Name: platform_move_prospect_stage_v86(uuid, text, bigint, jsonb, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_move_prospect_stage_v86(p_prospect uuid, p_to_stage text, p_expected_version bigint, p_entry_evidence jsonb, p_commercial_terms jsonb DEFAULT NULL::jsonb, p_idempotency_key text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_actor uuid:=auth.uid();v_rule public.sme_stage_entry_requirements%rowtype;v_result jsonb;
begin
  if not app.is_platform_operator_v75() then raise exception 'platform operator access is required' using errcode='42501';end if;
  perform app.v184_assert_prospect_active(p_prospect);
  perform app.validate_stage_entry_v86(p_prospect,p_to_stage,p_entry_evidence,p_commercial_terms);
  select * into strict v_rule from public.sme_stage_entry_requirements where stage_key=p_to_stage;
  insert into public.sme_stage_entry_evidence(
    prospect_id,stage_key,prospect_version,schema_version,evidence,actor
  ) values(p_prospect,p_to_stage,p_expected_version,v_rule.evidence_schema_version,p_entry_evidence,v_actor);
  v_result:=public.platform_move_prospect_stage_v76(
    p_prospect,p_to_stage,p_expected_version,
    case when p_to_stage='lost' then p_entry_evidence->>'reason_code' end,
    case when p_to_stage='lost' then p_entry_evidence->>'context' end,
    p_commercial_terms,p_idempotency_key
  );
  insert into public.audit_log(business_id,actor,action,entity,entity_id,detail)
  values(null,v_actor,'SME_PROSPECT_STAGE_EVIDENCE_RECORDED_V86','sme_prospects',p_prospect,
    jsonb_build_object('to_stage',p_to_stage,'prospect_version',p_expected_version,
      'evidence_schema_version',v_rule.evidence_schema_version));
  return v_result||jsonb_build_object('entry_evidence_recorded',true);
end
$$;

--
-- Name: platform_post_receipt_expense_v199(uuid, date, text, text, integer, text, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_post_receipt_expense_v199(p_receipt uuid, p_expense_date date, p_category text, p_description text, p_amount_cents integer, p_counterparty_name text, p_payment_reference text, p_counterparty_registration_number text DEFAULT NULL::text, p_idempotency_key uuid DEFAULT gen_random_uuid()) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid:=auth.uid(); v_row public.platform_accounting_receipts_v199%rowtype;
  v_result jsonb; v_entry uuid;
begin
  if v_actor is null or not app.is_super_admin() then
    raise exception 'super-admin access is required' using errcode='42501';
  end if;
  select * into v_row from public.platform_accounting_receipts_v199
   where id=p_receipt for update;
  if not found then raise exception 'receipt not found' using errcode='22023'; end if;
  if v_row.status='posted' then
    raise exception 'this receipt is already posted' using errcode='22023';
  end if;
  if v_row.status='discarded' then
    raise exception 'this receipt was discarded' using errcode='22023';
  end if;

  -- Reuses the audited, immutable, journal-posting expense path unchanged. The
  -- stored object is the evidence reference, so the books point at the file.
  v_result := public.platform_record_operating_expense_v147(
    p_expense_date, p_category, p_description, p_amount_cents,
    p_counterparty_name, p_counterparty_registration_number,
    p_payment_reference, v_row.storage_path, p_idempotency_key);
  v_entry := ((v_result->'entry')->>'id')::uuid;

  update public.platform_accounting_receipts_v199
     set status='posted', expense_entry_id=v_entry, posted_at=now(), posted_by=v_actor
   where id=p_receipt;

  insert into public.audit_log(business_id,actor,action,entity,entity_id,detail)
  values(null,v_actor,'PLATFORM_RECEIPT_POSTED_V199',
    'platform_accounting_receipts_v199',p_receipt,
    jsonb_build_object('expense_entry',v_entry,'amount_cents',p_amount_cents,
      'confirmed_by_human',true));
  return jsonb_build_object('receipt',p_receipt,'expense',v_result);
end $$;

--
-- Name: platform_prepare_manual_evidence_upload_v156(uuid, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_prepare_manual_evidence_upload_v156(p_invoice uuid, p_filename text, p_content_type text, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_actor uuid:=auth.uid();v_doc public.platform_subscription_documents_v156%rowtype;v_extension text;v_path text;
begin
  if v_actor is null or not app.v156_can('rw') then raise exception 'billing write access is required' using errcode='42501';end if;
  select * into v_doc from public.platform_subscription_documents_v156 where id=p_invoice and document_type='invoice' and provider_invoice_id is null and finalized_at is not null;
  if not found then raise exception 'manual invoice was not found' using errcode='22023';end if;
  if p_content_type not in ('application/pdf','image/jpeg','image/png') then raise exception 'payment evidence must be PDF, JPEG or PNG' using errcode='22023';end if;
  v_extension:=case p_content_type when 'application/pdf' then 'pdf' when 'image/jpeg' then 'jpg' else 'png' end;
  v_path:='platform-subscriptions/manual-evidence/'||v_doc.business_id||'/'||v_doc.id||'/'||p_idempotency_key||'.'||v_extension;
  insert into public.platform_subscription_dispatch_audit_v156(action,entity_type,entity_id,detail,actor)
  values('manual_evidence_upload_authorised','invoice',v_doc.id,jsonb_build_object('object_path',v_path,'filename',left(p_filename,180),'content_type',p_content_type),v_actor);
  return jsonb_build_object('bucket_id','sme-private','object_path',v_path,'content_type',p_content_type,'expires_in',300);
end $$;

--
-- Name: platform_publish_sector_bundle_v75(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_publish_sector_bundle_v75(p_bundle_version uuid, p_dry_run boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid(); v_bundle public.sector_bundle_versions%rowtype;
  v_previous uuid;
begin
  if not app.is_super_admin() then
    raise exception 'super admin access is required' using errcode = '42501';
  end if;
  select * into v_bundle from public.sector_bundle_versions
   where id = p_bundle_version for update;
  if not found then raise exception 'sector bundle version was not found' using errcode = '22023'; end if;
  if v_bundle.status = 'retired' then
    raise exception 'a retired sector bundle cannot be published again' using errcode = '22023';
  end if;
  select id into v_previous from public.sector_bundle_versions
   where sector_key = v_bundle.sector_key and status = 'published'
     and id <> v_bundle.id;
  if not coalesce(p_dry_run, true) and v_bundle.status = 'draft' then
    update public.sector_bundle_versions
       set status = 'retired', retired_at = now()
     where sector_key = v_bundle.sector_key and status = 'published'
       and id <> v_bundle.id;
    update public.sector_bundle_versions
       set status = 'published', published_at = now()
     where id = v_bundle.id;
    insert into public.audit_log(business_id, actor, action, entity, entity_id, detail)
    values (null, v_actor, 'SECTOR_BUNDLE_PUBLISHED_V75', 'sector_bundle_versions',
            v_bundle.id, jsonb_build_object('sector_key',v_bundle.sector_key,
              'version',v_bundle.version,'previous_published_version_id',v_previous));
  end if;
  return jsonb_build_object(
    'dry_run', coalesce(p_dry_run, true), 'bundle_version_id', v_bundle.id,
    'sector_key', v_bundle.sector_key, 'version', v_bundle.version,
    'status', case when v_bundle.status = 'published' or not coalesce(p_dry_run, true)
                   then 'published' else v_bundle.status end,
    'modules', to_jsonb(v_bundle.modules),
    'previous_published_version_id', v_previous
  );
end
$$;

--
-- Name: platform_queue_document_resend_v156(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_queue_document_resend_v156(p_delivery uuid, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_actor uuid:=auth.uid();v_source public.platform_subscription_deliveries_v156%rowtype;v_new public.platform_subscription_deliveries_v156%rowtype;
begin
  if v_actor is null or not app.v156_can('rw') then raise exception 'billing write access is required' using errcode='42501';end if;
  select * into v_source from public.platform_subscription_deliveries_v156 where id=p_delivery;if not found then raise exception 'delivery was not found' using errcode='22023';end if;
  insert into public.platform_subscription_deliveries_v156(delivery_key,business_id,prospect_id,provider_invoice_id,delivery_type,document_ids,recipients,cc_recipients,subject,manual_resend_by)
  values('resend:'||p_delivery||':'||p_idempotency_key,v_source.business_id,v_source.prospect_id,v_source.provider_invoice_id,'document_resend',v_source.document_ids,v_source.recipients,v_source.cc_recipients,v_source.subject,v_actor)
  on conflict(delivery_key) do update set updated_at=platform_subscription_deliveries_v156.updated_at returning * into v_new;
  insert into public.platform_subscription_dispatch_audit_v156(action,entity_type,entity_id,detail,actor) values('document_resend_queued','delivery',v_new.id,jsonb_build_object('source_delivery',p_delivery),v_actor);
  insert into public.platform_subscription_document_events_v156(document_id,status,source_type,source_id,actor)
  select document_id,case when d.document_type='receipt' then 'reissued_copy' else coalesce((select e.status from public.platform_subscription_document_events_v156 e where e.document_id=d.id order by e.occurred_at desc,e.id desc limit 1),'finalized') end,'admin','resend:'||v_new.id,v_actor
  from unnest(v_new.document_ids) document_id join public.platform_subscription_documents_v156 d on d.id=document_id on conflict do nothing;
  return jsonb_build_object('delivery',to_jsonb(v_new));
end $$;

--
-- Name: platform_reconcile_subscription_payment_v94(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_reconcile_subscription_payment_v94(p_business uuid, p_idempotency_key text, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if not app.is_super_admin() then
    raise exception 'super_admin_required' using errcode='42501';
  end if;
  return app.reconcile_subscription_payment_v94(
    p_business,p_idempotency_key,p_reason,auth.uid(),true
  );
end
$$;

--
-- Name: platform_record_account_signup_triage_v164(uuid, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_record_account_signup_triage_v164(p_user uuid, p_status text, p_note text DEFAULT NULL::text, p_idempotency_key uuid DEFAULT gen_random_uuid()) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid:=auth.uid();
  v_status text:=lower(nullif(btrim(coalesce(p_status,'')),''));
  v_note text:=nullif(btrim(coalesce(p_note,'')),'');
  v_row public.platform_account_signup_triage_v164%rowtype;
begin
  if v_actor is null or not app.is_super_admin() then
    raise exception 'super_admin_required' using errcode='42501';
  end if;
  if p_user is null or v_status not in ('new','follow_up','contacted','archived') then
    raise exception 'invalid account-signup triage request' using errcode='22023';
  end if;
  if v_note is not null and length(v_note)>1000 then
    raise exception 'triage note is too long' using errcode='22023';
  end if;
  if not exists(
    select 1
      from auth.users user_row
     where user_row.id=p_user
       and (
         user_row.raw_user_meta_data->>'account_type'='business_owner'
         or exists(
           select 1
             from app.business_account_legal_acceptances_v138 acceptance
            where acceptance.auth_user_id=user_row.id
              and acceptance.source='google_oauth_signup'
         )
       )
       and not exists(select 1 from public.staff staff_row where staff_row.user_id=user_row.id)
       and not exists(select 1 from public.self_serve_business_onboarding_v130 onboarding where onboarding.owner_user_id=user_row.id)
       and not exists(select 1 from public.business_applications_v95 application where lower(application.contact_email)=lower(user_row.email))
  ) then
    raise exception 'account-only business signup not found' using errcode='42501';
  end if;

  insert into public.platform_account_signup_triage_v164(
    auth_user_id,triage_status,note,last_contacted_at,archived_at,updated_at,updated_by
  ) values(
    p_user,v_status,v_note,
    case when v_status in ('contacted','follow_up') then now() else null end,
    case when v_status='archived' then now() else null end,
    now(),v_actor
  )
  on conflict(auth_user_id) do update set
    triage_status=excluded.triage_status,
    note=coalesce(excluded.note,public.platform_account_signup_triage_v164.note),
    last_contacted_at=case
      when excluded.triage_status in ('contacted','follow_up') then now()
      else public.platform_account_signup_triage_v164.last_contacted_at
    end,
    archived_at=case
      when excluded.triage_status='archived' then now()
      else null
    end,
    updated_at=now(),
    updated_by=v_actor
  returning * into v_row;

  insert into public.audit_log(business_id,actor,action,entity,entity_id,detail)
  values(null,v_actor,'PLATFORM_ACCOUNT_SIGNUP_TRIAGED_V164',
    'auth.users',p_user,jsonb_build_object(
      'status',v_status,
      'note_present',v_note is not null,
      'idempotency_key',p_idempotency_key
    ));

  return jsonb_build_object(
    'user_id',v_row.auth_user_id,
    'triage_status',v_row.triage_status,
    'note',v_row.note,
    'last_contacted_at',v_row.last_contacted_at,
    'archived_at',v_row.archived_at,
    'updated_at',v_row.updated_at
  );
end
$$;

--
-- Name: FUNCTION platform_record_account_signup_triage_v164(p_user uuid, p_status text, p_note text, p_idempotency_key uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.platform_record_account_signup_triage_v164(p_user uuid, p_status text, p_note text, p_idempotency_key uuid) IS 'V164 Super Admin triage for account-only business owner signups. Contacted/follow-up/archive actions are CRM evidence only and never activate access.';

--
-- Name: platform_record_activity_detail_v86(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_record_activity_detail_v86(p_activity uuid, p_detail jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_actor uuid:=auth.uid();v_version integer;v_row public.sme_activity_detail_versions%rowtype;
begin
  if not app.is_platform_operator_v75() then raise exception 'platform operator access is required' using errcode='42501';end if;
  if not exists(select 1 from public.sme_prospect_activities where id=p_activity) then raise exception 'activity was not found' using errcode='22023';end if;
  perform app.v86_assert_object_keys(p_detail,array[
    'contact_id','outcome','disposition','duration_seconds','direction','channel','next_action',
    'next_action_owner','next_action_due_at','meeting_at','meeting_url','meeting_location',
    'calendar_event_id','recording_transcript_url','attachments','created_source','supersedes_activity_id'
  ],'activity detail');
  v_version:=app.v86_next_version('public.sme_activity_detail_versions','activity_id',p_activity);
  insert into public.sme_activity_detail_versions(
    activity_id,version,contact_id,outcome,disposition,duration_seconds,direction,channel,
    next_action,next_action_owner,next_action_due_at,meeting_at,meeting_url,meeting_location,
    calendar_event_id,recording_transcript_url,attachments,created_source,supersedes_activity_id,created_by
  ) values(
    p_activity,v_version,nullif(p_detail->>'contact_id','')::uuid,nullif(p_detail->>'outcome',''),
