--
-- Name: platform_record_invoice_receipt_v147(uuid, date, integer, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_record_invoice_receipt_v147(p_invoice uuid, p_payment_date date, p_amount_cents integer, p_reference text, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_actor uuid:=auth.uid();v_invoice public.platform_financial_documents_v147%rowtype;v_policy public.platform_accounting_policies_v147%rowtype;v_existing public.platform_financial_documents_v147%rowtype;v_doc public.platform_financial_documents_v147%rowtype;
 v_id uuid:=gen_random_uuid();v_hash text;v_paid bigint;v_credited bigint;v_debited bigint;v_number text;v_journal jsonb;v_journal_id uuid;v_snapshot jsonb;
begin
  if v_actor is null or not app.is_super_admin() then raise exception 'super-admin access is required' using errcode='42501';end if;
  v_hash:=encode(extensions.digest(jsonb_build_object('invoice',p_invoice,'date',p_payment_date,'amount',p_amount_cents,'reference',btrim(p_reference))::text,'sha256'),'hex');perform pg_advisory_xact_lock(hashtextextended('platform_receipt:'||p_idempotency_key::text,147));
  select * into v_existing from public.platform_financial_documents_v147 where created_by=v_actor and operation_key=p_idempotency_key;if found then if v_existing.request_hash<>v_hash then raise exception 'idempotency key was reused with different input' using errcode='22023';end if;return jsonb_build_object('document',to_jsonb(v_existing),'replayed',true);end if;
  perform pg_advisory_xact_lock(hashtextextended('platform_document_chain:'||p_invoice::text,147));
  select * into v_invoice from public.platform_financial_documents_v147 where id=p_invoice and document_type='invoice';if not found then raise exception 'invoice was not found' using errcode='22023';end if;
  select coalesce(sum(document.total_cents),0) into v_paid from public.platform_financial_documents_v147 document where document.original_document=p_invoice and document.document_type='receipt' and not exists(select 1 from public.platform_financial_documents_v147 reversal where reversal.original_document=document.id and reversal.document_type='journal_voucher');
  select coalesce(sum(document.total_cents),0) into v_credited from public.platform_financial_documents_v147 document where document.original_document=p_invoice and document.document_type='credit_note' and not exists(select 1 from public.platform_financial_documents_v147 reversal where reversal.original_document=document.id and reversal.document_type='journal_voucher');
  select coalesce(sum(document.total_cents),0) into v_debited from public.platform_financial_documents_v147 document where document.original_document=p_invoice and document.document_type='debit_note' and not exists(select 1 from public.platform_financial_documents_v147 reversal where reversal.original_document=document.id and reversal.document_type='journal_voucher');
  if p_amount_cents<=0 or p_amount_cents>v_invoice.total_cents+v_debited-v_paid-v_credited or p_payment_date<v_invoice.issue_date or length(btrim(p_reference))<3 then raise exception 'payment exceeds the invoice balance or is invalid' using errcode='22023';end if;
  select * into v_policy from public.platform_accounting_policies_v147 where effective_from<=p_payment_date order by effective_from desc,version desc limit 1;v_number:=app.platform_next_document_number_v147('receipt',v_policy.document_prefix);
  v_journal:=app.platform_post_journal_v147('generated_receipt',v_id::text,p_payment_date,'Receipt '||v_number,jsonb_build_array(jsonb_build_object('account_code','1000','debit_cents',p_amount_cents,'credit_cents',0,'counterparty',v_invoice.counterparty->>'legal_name'),jsonb_build_object('account_code','1100','debit_cents',0,'credit_cents',p_amount_cents,'counterparty',v_invoice.counterparty->>'legal_name')),p_idempotency_key,v_hash,v_actor,null);v_journal_id:=(v_journal#>>'{entry,id}')::uuid;
  v_snapshot:=jsonb_build_object('issuer',app.platform_document_issuer_v147(v_policy),'number',v_number,'invoice_number',v_invoice.document_number,'payment_date',p_payment_date,'amount_cents',p_amount_cents,'reference',btrim(p_reference),'counterparty',v_invoice.counterparty,'currency','SGD');
  insert into public.platform_financial_documents_v147(id,document_type,document_number,issue_date,counterparty,line_items,subtotal_cents,tax_cents,total_cents,source_type,source_id,original_document,journal_entry,snapshot,snapshot_sha256,operation_key,request_hash,created_by)
  values(v_id,'receipt',v_number,p_payment_date,v_invoice.counterparty,jsonb_build_array(jsonb_build_object('description','Payment for '||v_invoice.document_number,'reference',btrim(p_reference))),p_amount_cents,0,p_amount_cents,'generated_receipt',v_id::text,p_invoice,v_journal_id,v_snapshot,encode(extensions.digest(v_snapshot::text,'sha256'),'hex'),p_idempotency_key,v_hash,v_actor) returning * into v_doc;
  return jsonb_build_object('document',to_jsonb(v_doc),'snapshot',v_snapshot,'remaining_cents',v_invoice.total_cents+v_debited-v_paid-v_credited-p_amount_cents,'replayed',false);
end
$$;

--
-- Name: platform_record_manual_payment_v156(uuid, bigint, text, date, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_record_manual_payment_v156(p_invoice uuid, p_amount_cents bigint, p_payment_reference text, p_value_date date, p_bank_account_last4 text, p_evidence_object_path text, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'extensions', 'pg_temp'
    AS $_$
declare v_actor uuid:=auth.uid();v_doc public.platform_subscription_documents_v156%rowtype;v_payment public.platform_manual_payments_v156%rowtype;v_hash text;
begin
  if v_actor is null or not app.v156_can('rw') then raise exception 'billing write access is required' using errcode='42501';end if;
  select * into v_doc from public.platform_subscription_documents_v156 where id=p_invoice and document_type='invoice' and provider_invoice_id is null and finalized_at is not null;if not found then raise exception 'manual invoice was not found' using errcode='22023';end if;
  if p_amount_cents<>v_doc.balance_due_cents or coalesce(btrim(p_payment_reference),'')='' or p_bank_account_last4!~'^[0-9]{4}$'
    or p_evidence_object_path!~('^platform-subscriptions/manual-evidence/'||v_doc.business_id||'/'||v_doc.id||'/[0-9a-f-]+\\.(pdf|jpg|png)$')
    or not exists(select 1 from storage.objects o where o.bucket_id='sme-private' and o.name=p_evidence_object_path)
  then raise exception 'valid private full-payment evidence is required' using errcode='22023';end if;
  v_hash:=encode(extensions.digest(jsonb_build_object('invoice',p_invoice,'amount',p_amount_cents,'reference',p_payment_reference,'value_date',p_value_date,'bank_last4',p_bank_account_last4,'evidence',p_evidence_object_path)::text,'sha256'),'hex');
  select * into v_payment from public.platform_manual_payments_v156 where idempotency_key=p_idempotency_key;
  if found then if v_payment.request_hash<>v_hash then raise exception 'idempotency key conflict' using errcode='22023';end if;return jsonb_build_object('payment',to_jsonb(v_payment),'replayed',true);end if;
  insert into public.platform_manual_payments_v156(invoice_document_id,amount_cents,payment_reference,value_date,bank_account_last4,evidence_object_path,recorded_by,request_hash,idempotency_key)
  values(p_invoice,p_amount_cents,btrim(p_payment_reference),p_value_date,p_bank_account_last4,p_evidence_object_path,v_actor,v_hash,p_idempotency_key) returning * into v_payment;
  insert into public.platform_subscription_dispatch_audit_v156(action,entity_type,entity_id,detail,actor) values('manual_payment_recorded','manual_payment',v_payment.id,jsonb_build_object('invoice',p_invoice,'reference',p_payment_reference),v_actor);
  return jsonb_build_object('payment',to_jsonb(v_payment),'replayed',false);
end $_$;

--
-- Name: platform_record_operating_expense_v146(date, text, text, integer, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_record_operating_expense_v146(p_expense_date date, p_category text, p_description text, p_amount_cents integer, p_currency text, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_actor uuid:=auth.uid();v_hash text;v_existing public.platform_operating_expense_entries_v146%rowtype;
  v_row public.platform_operating_expense_entries_v146%rowtype;
begin
  if v_actor is null or not app.is_super_admin() then
    raise exception 'super-admin access is required' using errcode='42501';
  end if;
  if p_expense_date is null or p_expense_date>(clock_timestamp() at time zone 'Asia/Singapore')::date
     or p_category not in ('software','marketing','professional_services','banking','operations','other')
     or length(btrim(coalesce(p_description,''))) not between 3 and 240
     or coalesce(p_amount_cents,0)<=0 or upper(coalesce(p_currency,''))<>'SGD'
     or p_idempotency_key is null then
    raise exception 'valid SGD expense details are required' using errcode='22023';
  end if;
  v_hash:=encode(extensions.digest(convert_to(concat_ws('|',p_expense_date,p_category,btrim(p_description),p_amount_cents,'SGD'),'UTF8'),'sha256'),'hex');
  perform pg_advisory_xact_lock(hashtextextended(v_actor::text||':'||p_idempotency_key::text,0));
  select * into v_existing from public.platform_operating_expense_entries_v146
   where recorded_by=v_actor and idempotency_key=p_idempotency_key;
  if found then
    if v_existing.request_hash<>v_hash then
      raise exception 'idempotency key was reused with different input' using errcode='22023';
    end if;
    return jsonb_build_object('entry',to_jsonb(v_existing),'replayed',true);
  end if;
  insert into public.platform_operating_expense_entries_v146(
    entry_type,expense_date,category,description,amount_cents,currency,
    recorded_by,idempotency_key,request_hash
  ) values('expense',p_expense_date,p_category,btrim(p_description),p_amount_cents,
    'SGD',v_actor,p_idempotency_key,v_hash) returning * into v_row;
  insert into public.audit_log(business_id,actor,action,entity,entity_id,detail)
  values(null,v_actor,'PLATFORM_EXPENSE_RECORDED_V146','platform_operating_expense_entries_v146',v_row.id,
    jsonb_build_object('expense_date',v_row.expense_date,'category',v_row.category,'amount_cents',v_row.amount_cents,'currency',v_row.currency));
  return jsonb_build_object('entry',to_jsonb(v_row),'replayed',false);
end
$$;

--
-- Name: platform_record_operating_expense_v147(date, text, text, integer, text, text, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_record_operating_expense_v147(p_expense_date date, p_category text, p_description text, p_amount_cents integer, p_counterparty_name text, p_counterparty_registration_number text, p_payment_reference text, p_evidence_reference text, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_actor uuid:=auth.uid();v_hash text;v_existing public.platform_operating_expense_entries_v146%rowtype;v_row public.platform_operating_expense_entries_v146%rowtype;v_document public.platform_financial_documents_v147%rowtype;
begin
  if v_actor is null or not app.is_super_admin() then raise exception 'super-admin access is required' using errcode='42501';end if;
  if p_expense_date is null or p_expense_date>(clock_timestamp() at time zone 'Asia/Singapore')::date
     or p_category not in ('software','marketing','professional_services','banking','operations','other')
     or length(btrim(coalesce(p_description,''))) not between 3 and 240 or coalesce(p_amount_cents,0)<=0
     or length(btrim(coalesce(p_counterparty_name,''))) not between 2 and 200
     or length(btrim(coalesce(p_payment_reference,''))) not between 3 and 200
     or length(btrim(coalesce(p_evidence_reference,''))) not between 8 and 300 or p_idempotency_key is null then
    raise exception 'complete SGD supplier expense evidence is required' using errcode='22023';
  end if;
  if not exists(select 1 from public.platform_accounting_policies_v147 where effective_from<=p_expense_date) then raise exception 'reviewed accounting identity must be configured first' using errcode='55000';end if;
  v_hash:=encode(extensions.digest(jsonb_build_object('date',p_expense_date,'category',p_category,'description',btrim(p_description),'amount',p_amount_cents,'counterparty',btrim(p_counterparty_name),'counterparty_registration',nullif(btrim(p_counterparty_registration_number),''),'payment_reference',btrim(p_payment_reference),'evidence',btrim(p_evidence_reference))::text,'sha256'),'hex');
  perform pg_advisory_xact_lock(hashtextextended(v_actor::text||':'||p_idempotency_key::text,147));
  select * into v_existing from public.platform_operating_expense_entries_v146 where recorded_by=v_actor and idempotency_key=p_idempotency_key;
  if found then if v_existing.request_hash<>v_hash then raise exception 'idempotency key was reused with different input' using errcode='22023';end if;select * into v_document from public.platform_financial_documents_v147 where source_type='platform_expense_voucher' and source_id=v_existing.id::text;return jsonb_build_object('entry',to_jsonb(v_existing),'document',to_jsonb(v_document),'replayed',true);end if;
  insert into public.platform_operating_expense_entries_v146(entry_type,expense_date,category,description,amount_cents,currency,recorded_by,idempotency_key,request_hash,counterparty_name,counterparty_registration_number,payment_reference,evidence_reference)
  values('expense',p_expense_date,p_category,btrim(p_description),p_amount_cents,'SGD',v_actor,p_idempotency_key,v_hash,btrim(p_counterparty_name),nullif(btrim(p_counterparty_registration_number),''),btrim(p_payment_reference),btrim(p_evidence_reference)) returning * into v_row;
  insert into public.audit_log(business_id,actor,action,entity,entity_id,detail) values(null,v_actor,'PLATFORM_EXPENSE_RECORDED_V147','platform_operating_expense_entries_v146',v_row.id,jsonb_build_object('amount_cents',p_amount_cents,'counterparty',v_row.counterparty_name,'payment_reference',v_row.payment_reference,'evidence_reference',v_row.evidence_reference));
  select * into v_document from public.platform_financial_documents_v147 where source_type='platform_expense_voucher' and source_id=v_row.id::text;
  return jsonb_build_object('entry',to_jsonb(v_row),'document',to_jsonb(v_document),'replayed',false);
end
$$;

--
-- Name: platform_record_partner_suppression_v282(uuid, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_record_partner_suppression_v282(p_partner uuid, p_reason text, p_idempotency_key text, p_identity uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_reason text := lower(btrim(coalesce(p_reason, '')));
  v_key text := nullif(btrim(coalesce(p_idempotency_key, '')), '');
  v_auth uuid;
  v_id uuid;
begin
  if v_actor is null then
    raise exception 'authenticated platform session is required' using errcode = '28000';
  end if;
  if not app.is_super_admin() then
    raise exception 'suppression instructions are super admin only' using errcode = '42501';
  end if;
  if v_key is null then
    raise exception 'idempotency key required' using errcode = '22023';
  end if;
  if v_reason not in ('consent_withdrawn', 'account_closed', 'customer_request', 'platform_decision') then
    raise exception 'unsupported suppression reason' using errcode = '22023';
  end if;
  if not exists (select 1 from public.partner_registry_v282 partner where partner.id = p_partner) then
    raise exception 'partner not found' using errcode = '22023';
  end if;

  select id into v_id from public.partner_suppressions_v282 suppression
   where suppression.partner_id = p_partner and suppression.idempotency_key = v_key;
  if v_id is not null then
    return jsonb_build_object('status', 'duplicate_ignored', 'suppression_id', v_id);
  end if;

  if p_identity is not null then
    select identity.auth_user_id into v_auth
      from public.customer_identities identity
     where identity.id = p_identity;
    if v_auth is null then
      raise exception 'customer not found' using errcode = '22023';
    end if;
  end if;

  insert into public.partner_suppressions_v282 (
    partner_id, identity_id, auth_user_id, reason, issued_by, idempotency_key
  ) values (
    p_partner, p_identity, v_auth, v_reason, v_actor, v_key
  )
  returning id into v_id;

  return jsonb_build_object('status', 'ok', 'suppression_id', v_id);
end;
$$;

--
-- Name: platform_record_qualification_v86(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_record_qualification_v86(p_prospect uuid, p_profile jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_actor uuid:=auth.uid();v_version integer;v_row public.sme_qualification_detail_versions%rowtype;
begin
  if not app.is_platform_operator_v75() then raise exception 'platform operator access is required' using errcode='42501';end if;
  if not exists(select 1 from public.sme_prospects where id=p_prospect) then raise exception 'prospect was not found' using errcode='22023';end if;
  perform app.v86_assert_object_keys(p_profile,array[
    'primary_problem','why_change','existing_workflow','current_tool_vendor','pain_points',
    'consequence_of_inaction','desired_outcome','required_features','nice_to_have_features',
    'success_criteria','expected_user_count','expected_usage_volume','required_integrations',
    'required_migration','security_requirements','compliance_requirements',
    'decision_maker_contact_id','champion_contact_id','budget_owner_contact_id','budget_status',
    'budget_min_cents','budget_max_cents','expected_subscription_cents','expected_setup_fee_cents',
    'purchase_timeframe','target_go_live','procurement_process','legal_review_required',
    'security_review_required','competitors_considered','decision_criteria','decision_date',
    'main_objection','risk_level','fit_score','intent_score','qualification_status',
    'disqualification_reason','system_suggested_score','score_reasons','human_confirmed_score'
  ],'qualification profile');
  v_version:=app.v86_next_version('public.sme_qualification_detail_versions','prospect_id',p_prospect);
  insert into public.sme_qualification_detail_versions(
    prospect_id,version,primary_problem,why_change,existing_workflow,current_tool_vendor,
    pain_points,consequence_of_inaction,desired_outcome,required_features,nice_to_have_features,
    success_criteria,expected_user_count,expected_usage_volume,required_integrations,
    required_migration,security_requirements,compliance_requirements,decision_maker_contact_id,
    champion_contact_id,budget_owner_contact_id,budget_status,budget_min_cents,budget_max_cents,
    expected_subscription_cents,expected_setup_fee_cents,purchase_timeframe,target_go_live,
    procurement_process,legal_review_required,security_review_required,competitors_considered,
    decision_criteria,decision_date,main_objection,risk_level,fit_score,intent_score,
    qualification_status,disqualification_reason,system_suggested_score,score_reasons,
    human_confirmed_score,confirmed_by,confirmed_at,created_by
  ) values(
    p_prospect,v_version,nullif(p_profile->>'primary_problem',''),nullif(p_profile->>'why_change',''),
    nullif(p_profile->>'existing_workflow',''),nullif(p_profile->>'current_tool_vendor',''),
    coalesce(array(select jsonb_array_elements_text(p_profile->'pain_points')),'{}'),
    nullif(p_profile->>'consequence_of_inaction',''),nullif(p_profile->>'desired_outcome',''),
    coalesce(array(select jsonb_array_elements_text(p_profile->'required_features')),'{}'),
    coalesce(array(select jsonb_array_elements_text(p_profile->'nice_to_have_features')),'{}'),
    coalesce(array(select jsonb_array_elements_text(p_profile->'success_criteria')),'{}'),
    nullif(p_profile->>'expected_user_count','')::integer,
    nullif(p_profile->>'expected_usage_volume','')::integer,
    coalesce(array(select jsonb_array_elements_text(p_profile->'required_integrations')),'{}'),
    nullif(p_profile->>'required_migration',''),
    coalesce(array(select jsonb_array_elements_text(p_profile->'security_requirements')),'{}'),
    coalesce(array(select jsonb_array_elements_text(p_profile->'compliance_requirements')),'{}'),
    nullif(p_profile->>'decision_maker_contact_id','')::uuid,
    nullif(p_profile->>'champion_contact_id','')::uuid,
    nullif(p_profile->>'budget_owner_contact_id','')::uuid,nullif(p_profile->>'budget_status',''),
    nullif(p_profile->>'budget_min_cents','')::bigint,nullif(p_profile->>'budget_max_cents','')::bigint,
    nullif(p_profile->>'expected_subscription_cents','')::bigint,
    nullif(p_profile->>'expected_setup_fee_cents','')::bigint,
    nullif(p_profile->>'purchase_timeframe',''),nullif(p_profile->>'target_go_live','')::date,
    nullif(p_profile->>'procurement_process',''),
    coalesce((p_profile->>'legal_review_required')::boolean,false),
    coalesce((p_profile->>'security_review_required')::boolean,false),
    coalesce(array(select jsonb_array_elements_text(p_profile->'competitors_considered')),'{}'),
    coalesce(array(select jsonb_array_elements_text(p_profile->'decision_criteria')),'{}'),
    nullif(p_profile->>'decision_date','')::date,nullif(p_profile->>'main_objection',''),
    nullif(p_profile->>'risk_level',''),nullif(p_profile->>'fit_score','')::smallint,
    nullif(p_profile->>'intent_score','')::smallint,nullif(p_profile->>'qualification_status',''),
    nullif(p_profile->>'disqualification_reason',''),
    nullif(p_profile->>'system_suggested_score','')::smallint,
    coalesce(array(select jsonb_array_elements_text(p_profile->'score_reasons')),'{}'),
    nullif(p_profile->>'human_confirmed_score','')::smallint,
    case when p_profile?'human_confirmed_score' then v_actor end,
    case when p_profile?'human_confirmed_score' then now() end,v_actor
  ) returning * into v_row;
  insert into public.audit_log(business_id,actor,action,entity,entity_id,detail)
  values(null,v_actor,'SME_QUALIFICATION_RECORDED_V86','sme_qualification_detail_versions',v_row.id,
    jsonb_build_object('prospect_id',p_prospect,'version',v_version,
      'human_confirmed',v_row.human_confirmed_score is not null));
  return jsonb_build_object('qualification',to_jsonb(v_row));
end
$$;

--
-- Name: platform_register_receipt_v199(text, text, text, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_register_receipt_v199(p_storage_path text, p_content_sha256 text, p_mime_type text, p_byte_size integer, p_original_filename text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_actor uuid:=auth.uid(); v_row public.platform_accounting_receipts_v199%rowtype;
begin
  if v_actor is null or not app.is_super_admin() then
    raise exception 'super-admin access is required' using errcode='42501';
  end if;
  if coalesce(btrim(p_storage_path),'')='' or p_storage_path not like 'receipts/%' then
    raise exception 'receipts must be stored under receipts/' using errcode='22023';
  end if;

  select * into v_row from public.platform_accounting_receipts_v199
   where content_sha256=p_content_sha256;
  if found then
    -- Same bytes as something already captured: hand back what exists rather
    -- than creating a second route to the same expense.
    return jsonb_build_object('receipt',to_jsonb(v_row),'duplicate',true);
  end if;

  insert into public.platform_accounting_receipts_v199(
    storage_path,content_sha256,mime_type,byte_size,original_filename,uploaded_by)
  values(btrim(p_storage_path),p_content_sha256,p_mime_type,p_byte_size,
    nullif(btrim(coalesce(p_original_filename,'')),''),v_actor)
  returning * into v_row;

  insert into public.audit_log(business_id,actor,action,entity,entity_id,detail)
  values(null,v_actor,'PLATFORM_RECEIPT_REGISTERED_V199',
    'platform_accounting_receipts_v199',v_row.id,
    jsonb_build_object('bytes',p_byte_size,'mime',p_mime_type));
  return jsonb_build_object('receipt',to_jsonb(v_row),'duplicate',false);
end $$;

--
-- Name: platform_request_ai_firm_report_v176(uuid, text, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_request_ai_firm_report_v176(p_business uuid, p_period_kind text, p_period_start date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_end date;
  v_business record;
  v_row public.ai_firm_reports_v176%rowtype;
begin
  if v_actor is null then
    raise exception 'authenticated platform session is required'
      using errcode = '28000';
  end if;
  if not app.is_super_admin()
     and not app.v176_is_assigned_consultant(p_business) then
    raise exception 'ai_firm_report_request_requires_platform_owner'
      using errcode = '42501';
  end if;

  select business.id, business.name, business.is_demo, business.is_synthetic
  into v_business
  from public.businesses business
  where business.id = p_business
  for share;
  if not found then
    raise exception 'business_not_found' using errcode = '22023';
  end if;
  if v_business.is_demo or v_business.is_synthetic then
    raise exception 'ai_firm_reports_exclude_demo_firms'
      using errcode = '22023';
  end if;

  v_end := app.v176_assert_period(p_period_kind, p_period_start);

  insert into public.ai_firm_reports_v176(
    business_id, period_kind, period_start, period_end,
    status, model, requested_by
  ) values(
    p_business, p_period_kind, p_period_start, v_end,
    'pending', app.v176_model_for_period(p_period_kind), v_actor
  )
  on conflict (business_id, period_kind, period_start) do update
    set status = 'pending',
        model = app.v176_model_for_period(excluded.period_kind),
        evidence = null,
        narrative_md = null,
        error = null,
        claimed_at = null,
        completed_at = null,
        requested_by = v_actor,
        generation = ai_firm_reports_v176.generation + 1
  returning * into v_row;

  insert into public.audit_log(
    business_id, actor, action, entity, entity_id, detail
  ) values(
    p_business, v_actor, 'AI_FIRM_REPORT_REQUESTED_V176',
    'ai_firm_reports_v176', v_row.id,
    pg_catalog.jsonb_build_object(
      'period_kind', v_row.period_kind,
      'period_start', v_row.period_start,
      'period_end', v_row.period_end,
      'generation', v_row.generation,
      'model', v_row.model
    )
  );

  return to_jsonb(v_row) - 'evidence';
end
$$;

--
-- Name: FUNCTION platform_request_ai_firm_report_v176(p_business uuid, p_period_kind text, p_period_start date); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.platform_request_ai_firm_report_v176(p_business uuid, p_period_kind text, p_period_start date) IS 'Queues (or re-queues) an AI narrative report for one non-demo firm and one closed calendar period. Super admin or the assigned consultant only.';

--
-- Name: platform_request_document_read_v156(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_request_document_read_v156(p_document uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_file public.platform_subscription_document_files_v156%rowtype;v_prospect uuid;
begin
  select prospect_id into v_prospect from public.platform_subscription_documents_v156 where id=p_document;
  if auth.uid() is null or not (app.v156_can('r') or (v_prospect is not null and app.v156_can_prospect(v_prospect,'r'))) then raise exception 'document read access is required' using errcode='42501';end if;
  select * into v_file from public.platform_subscription_document_files_v156 where document_id=p_document order by revision desc limit 1;
  if not found then raise exception 'document PDF is not ready' using errcode='22023';end if;
  return jsonb_build_object('bucket_id',v_file.bucket_id,'object_path',v_file.object_path,'filename',(select document_number||'.pdf' from public.platform_subscription_documents_v156 where id=p_document),'expires_in',300);
end $$;

--
-- Name: platform_request_manual_evidence_read_v156(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_request_manual_evidence_read_v156(p_payment uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_actor uuid:=auth.uid();v_payment public.platform_manual_payments_v156%rowtype;
begin
  if v_actor is null or not app.is_super_admin() then raise exception 'super admin verification is required' using errcode='42501';end if;
  select * into v_payment from public.platform_manual_payments_v156 where id=p_payment;if not found then raise exception 'manual payment was not found' using errcode='22023';end if;
  return jsonb_build_object('bucket_id','sme-private','object_path',v_payment.evidence_object_path,'expires_in',300);
end $$;

--
-- Name: platform_request_prospect_document_upload_v86(uuid, text, text, text, bigint, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_request_prospect_document_upload_v86(p_prospect uuid, p_document_type text, p_original_filename text, p_mime_type text, p_size_bytes bigint, p_logical_document uuid DEFAULT NULL::uuid, p_notes text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid:=auth.uid();v_company uuid;v_logical uuid:=coalesce(p_logical_document,gen_random_uuid());
  v_version integer;v_document public.sme_document_versions%rowtype;v_token text;v_request uuid;
  v_safe_name text;
begin
  if not app.can_access_prospect_sensitive_v86(p_prospect) then
    raise exception 'assigned consultant or super admin access is required' using errcode='42501';end if;
  select company_id into v_company from public.sme_prospects where id=p_prospect;
  if v_company is null then raise exception 'prospect was not found' using errcode='22023';end if;
  select coalesce(max(version),0)+1 into v_version
    from public.sme_document_versions where logical_document_id=v_logical;
  v_safe_name:=left(regexp_replace(lower(btrim(p_original_filename)),'[^a-z0-9._-]+','_','g'),180);
  if v_safe_name='' then raise exception 'document filename is invalid' using errcode='22023';end if;
  insert into public.sme_document_versions(
    logical_document_id,version,prospect_id,company_id,document_type,original_filename,
    object_path,mime_type,size_bytes,status,notes,uploaded_by,created_by
  ) values(
    v_logical,v_version,p_prospect,v_company,p_document_type,btrim(p_original_filename),
    'prospects/'||p_prospect||'/'||v_logical||'/v'||v_version||'/'||v_safe_name,
    p_mime_type,p_size_bytes,'reserved',nullif(btrim(p_notes),''),v_actor,v_actor
  ) returning * into v_document;
  v_token:=encode(extensions.gen_random_bytes(24),'hex');
  insert into public.sme_document_signing_requests(
    document_version_id,purpose,token_hash,requested_by,expires_at
  ) values(v_document.id,'upload',app.v76_sha256_hex(v_token),v_actor,now()+interval '10 minutes')
  returning id into v_request;
  insert into public.audit_log(business_id,actor,action,entity,entity_id,detail)
  values(null,v_actor,'SME_DOCUMENT_UPLOAD_REQUESTED_V86','sme_document_versions',v_document.id,
    jsonb_build_object('prospect_id',p_prospect,'document_type',p_document_type,
      'mime_type',p_mime_type,'size_bytes',p_size_bytes,'request_id',v_request));
  return jsonb_build_object(
    'request_id',v_request,'exchange_token',v_token,'expires_at',now()+interval '10 minutes',
    'document_version_id',v_document.id,'logical_document_id',v_logical,'version',v_version,
    'bucket_id',v_document.bucket_id,'object_path',v_document.object_path,
    'signed_url',null,'requires_trusted_signer',true
  );
end
$$;

--
-- Name: platform_restore_prospect_v184(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_restore_prospect_v184(p_prospect uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_actor uuid:=auth.uid(); v_row public.sme_prospects%rowtype;
begin
  if not app.is_super_admin() then
    raise exception 'super admin access is required' using errcode='42501';
  end if;
  select * into v_row from public.sme_prospects where id=p_prospect;
  if not found then
    raise exception 'firm record not found' using errcode='22023';
  end if;
  if v_row.archived_at is null then
    return jsonb_build_object('status','already_active','prospect',p_prospect);
  end if;
  -- A merged-away record must not be revived on its own: it would resurrect
  -- a duplicate whose data now lives on the survivor.
  if v_row.merged_into_prospect_id is not null then
    raise exception 'this record was merged into another firm and cannot be restored'
      using errcode='42501';
  end if;

  update public.sme_prospects
     set archived_at=null, archived_by=null, archive_reason=null,
         updated_at=now(), updated_by=v_actor
   where id=p_prospect;

  insert into public.audit_log(business_id,actor,action,entity,entity_id,detail)
  values(null,v_actor,'PLATFORM_PROSPECT_RESTORED_V184','sme_prospects',p_prospect,
    jsonb_build_object('reason',nullif(btrim(coalesce(p_reason,'')),''),
      'was_archived_at',v_row.archived_at));
  return jsonb_build_object('status','restored','prospect',p_prospect);
end $$;

--
-- Name: platform_reverse_financial_document_v147(uuid, date, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_reverse_financial_document_v147(p_document uuid, p_reversal_date date, p_reason text, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_actor uuid:=auth.uid();v_original public.platform_financial_documents_v147%rowtype;v_policy public.platform_accounting_policies_v147%rowtype;v_existing public.platform_financial_documents_v147%rowtype;v_doc public.platform_financial_documents_v147%rowtype;v_id uuid:=gen_random_uuid();v_hash text;v_number text;v_journal jsonb;v_journal_id uuid;v_snapshot jsonb;
begin
  if v_actor is null or not app.is_super_admin() then raise exception 'super-admin access is required' using errcode='42501';end if;
  v_hash:=encode(extensions.digest(jsonb_build_object('document',p_document,'date',p_reversal_date,'reason',btrim(p_reason))::text,'sha256'),'hex');perform pg_advisory_xact_lock(hashtextextended('platform_document_reversal:'||p_idempotency_key::text,147));
  select * into v_existing from public.platform_financial_documents_v147 where created_by=v_actor and operation_key=p_idempotency_key;if found then if v_existing.request_hash<>v_hash then raise exception 'idempotency key was reused with different input' using errcode='22023';end if;return jsonb_build_object('document',to_jsonb(v_existing),'replayed',true);end if;
  select * into v_original from public.platform_financial_documents_v147 where id=p_document;if not found then raise exception 'document is missing or already reversed' using errcode='22023';end if;
  perform pg_advisory_xact_lock(hashtextextended('platform_document_chain:'||coalesce(v_original.original_document,v_original.id)::text,147));
  select * into v_original from public.platform_financial_documents_v147 where id=p_document;
  if exists(select 1 from public.platform_financial_documents_v147 where original_document=p_document and document_type='journal_voucher') then raise exception 'document is missing or already reversed' using errcode='22023';end if;
  if v_original.document_type='invoice' and exists(select 1 from public.platform_financial_documents_v147 where original_document=p_document and document_type in ('receipt','credit_note','debit_note')) then raise exception 'invoice with payments, credits or debits must be corrected through linked documents' using errcode='22023';end if;
  if p_reversal_date<v_original.issue_date or length(btrim(p_reason))<8 then raise exception 'valid reversal date and reason are required' using errcode='22023';end if;
  select * into v_policy from public.platform_accounting_policies_v147 where effective_from<=p_reversal_date order by effective_from desc,version desc limit 1;v_number:=app.platform_next_document_number_v147('journal_voucher',v_policy.document_prefix);
  v_journal:=app.platform_reverse_journal_v147(v_original.journal_entry,'generated_document_reversal',v_id::text,p_reversal_date,'Reversal '||v_number||': '||btrim(p_reason),p_idempotency_key,v_actor);v_journal_id:=(v_journal#>>'{entry,id}')::uuid;
  v_snapshot:=jsonb_build_object('issuer',v_original.snapshot->'issuer','number',v_number,'original_number',v_original.document_number,'reversal_date',p_reversal_date,'reason',btrim(p_reason),'total_cents',v_original.total_cents,'currency','SGD');
  insert into public.platform_financial_documents_v147(id,document_type,document_number,issue_date,counterparty,line_items,subtotal_cents,tax_cents,total_cents,source_type,source_id,original_document,journal_entry,snapshot,snapshot_sha256,operation_key,request_hash,created_by)
  values(v_id,'journal_voucher',v_number,p_reversal_date,v_original.counterparty,jsonb_build_array(jsonb_build_object('description',btrim(p_reason))),v_original.subtotal_cents,v_original.tax_cents,v_original.total_cents,'generated_document_reversal',v_id::text,p_document,v_journal_id,v_snapshot,encode(extensions.digest(v_snapshot::text,'sha256'),'hex'),p_idempotency_key,v_hash,v_actor) returning * into v_doc;
  return jsonb_build_object('document',to_jsonb(v_doc),'snapshot',v_snapshot,'replayed',false);
end
$$;

--
-- Name: platform_reverse_operating_expense_v146(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_reverse_operating_expense_v146(p_expense uuid, p_reason text, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_actor uuid:=auth.uid();v_original public.platform_operating_expense_entries_v146%rowtype;
  v_existing public.platform_operating_expense_entries_v146%rowtype;v_row public.platform_operating_expense_entries_v146%rowtype;
  v_hash text;
begin
  if v_actor is null or not app.is_super_admin() then
    raise exception 'super-admin access is required' using errcode='42501';
  end if;
  if p_expense is null or length(btrim(coalesce(p_reason,''))) not between 3 and 240
     or p_idempotency_key is null then
    raise exception 'expense, reversal reason and idempotency key are required' using errcode='22023';
  end if;
  select * into v_original from public.platform_operating_expense_entries_v146
   where id=p_expense and entry_type='expense';
  if not found then raise exception 'platform expense was not found' using errcode='22023';end if;
  v_hash:=encode(extensions.digest(convert_to(concat_ws('|',p_expense,btrim(p_reason)),'UTF8'),'sha256'),'hex');
  perform pg_advisory_xact_lock(hashtextextended(v_actor::text||':'||p_idempotency_key::text,0));
  perform pg_advisory_xact_lock(hashtextextended('platform-expense:'||p_expense::text,0));
  select * into v_existing from public.platform_operating_expense_entries_v146
   where recorded_by=v_actor and idempotency_key=p_idempotency_key;
  if found then
    if v_existing.request_hash<>v_hash then
      raise exception 'idempotency key was reused with different input' using errcode='22023';
    end if;
    return jsonb_build_object('entry',to_jsonb(v_existing),'replayed',true);
  end if;
  if exists(select 1 from public.platform_operating_expense_entries_v146 where reversal_of=p_expense) then
    raise exception 'platform expense is already reversed' using errcode='22023';
  end if;
  insert into public.platform_operating_expense_entries_v146(
    entry_type,reversal_of,expense_date,category,description,amount_cents,currency,
    recorded_by,idempotency_key,request_hash
  ) values('reversal',p_expense,(clock_timestamp() at time zone 'Asia/Singapore')::date,v_original.category,btrim(p_reason),
    v_original.amount_cents,v_original.currency,v_actor,p_idempotency_key,v_hash)
  returning * into v_row;
  insert into public.audit_log(business_id,actor,action,entity,entity_id,detail)
  values(null,v_actor,'PLATFORM_EXPENSE_REVERSED_V146','platform_operating_expense_entries_v146',v_row.id,
    jsonb_build_object('reversal_of',p_expense,'amount_cents',v_row.amount_cents,'reason',v_row.description));
  return jsonb_build_object('entry',to_jsonb(v_row),'replayed',false);
end
$$;

--
-- Name: platform_run_subscription_revenue_v200(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_run_subscription_revenue_v200() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_captured integer; v_recognized integer;
begin
  if auth.uid() is not null and not app.is_super_admin() then
    raise exception 'super-admin access is required' using errcode='42501';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('platform_subscription_revenue_v200', 200));
  v_captured := app.v200_capture_paid_periods();
  v_recognized := app.v200_recognize_due_months();
  return jsonb_build_object(
    'captured_periods', v_captured,
    'recognized_months', v_recognized,
    'deferred_balance_cents', coalesce((
      select sum(m.amount_cents) from public.platform_subscription_revenue_months_v200 m
       join public.platform_subscription_revenue_periods_v200 p on p.id = m.period_id
      where m.journal_entry_id is null and p.cash_journal_entry_id is not null), 0),
    'ran_at', now());
end $$;

--
-- Name: platform_save_crm_commercial_v156(uuid, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_save_crm_commercial_v156(p_prospect uuid, p_data jsonb, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_actor uuid:=auth.uid();v_row public.platform_crm_commercial_v156%rowtype;v_hash text;v_replay jsonb;
begin
  if v_actor is null or not app.v156_can_prospect(p_prospect,'rw') then raise exception 'CRM write access is required' using errcode='42501';end if;
  if p_idempotency_key is null or jsonb_typeof(p_data)<>'object' then raise exception 'valid commercial request is required' using errcode='22023';end if;
  v_hash:=encode(extensions.digest(jsonb_build_object('prospect',p_prospect,'data',p_data)::text,'sha256'),'hex');
  perform pg_advisory_xact_lock(hashtextextended('v156-commercial:'||p_idempotency_key::text,156));
  v_replay:=app.v156_operation_replay(p_idempotency_key,'crm_commercial',v_actor,v_hash);if v_replay is not null then return v_replay;end if;
  insert into public.platform_crm_commercial_v156(prospect_id,lead_source,expected_plan,billing_interval,expected_value_cents,
    proposed_discount_cents,expected_close_date,intended_duration,purchase_order_number,customer_reference,updated_by)
  values(p_prospect,nullif(btrim(p_data->>'lead_source'),''),nullif(btrim(p_data->>'expected_plan'),''),
    nullif(p_data->>'billing_interval',''),nullif(p_data->>'expected_value_cents','')::bigint,
    coalesce((p_data->>'proposed_discount_cents')::bigint,0),nullif(p_data->>'expected_close_date','')::date,
    nullif(btrim(p_data->>'intended_duration'),''),nullif(btrim(p_data->>'purchase_order_number'),''),
    nullif(btrim(p_data->>'customer_reference'),''),v_actor)
  on conflict(prospect_id) do update set lead_source=excluded.lead_source,expected_plan=excluded.expected_plan,
    billing_interval=excluded.billing_interval,expected_value_cents=excluded.expected_value_cents,
    proposed_discount_cents=excluded.proposed_discount_cents,expected_close_date=excluded.expected_close_date,
    intended_duration=excluded.intended_duration,purchase_order_number=excluded.purchase_order_number,
    customer_reference=excluded.customer_reference,updated_by=v_actor,updated_at=clock_timestamp()
  returning * into v_row;
  return app.v156_store_operation(p_idempotency_key,'crm_commercial',v_actor,v_hash,jsonb_build_object('commercial',to_jsonb(v_row)));
end $$;

--
-- Name: platform_save_partner_v282(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_save_partner_v282(p_partner uuid, p_name text, p_purpose text, p_status text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_name text := nullif(btrim(coalesce(p_name, '')), '');
  v_purpose text := nullif(btrim(coalesce(p_purpose, '')), '');
  v_status text := lower(btrim(coalesce(p_status, 'prospective')));
  v_id uuid;
begin
  if v_actor is null then
    raise exception 'authenticated platform session is required' using errcode = '28000';
  end if;
  if not app.is_super_admin() then
    raise exception 'the partner registry is super admin only' using errcode = '42501';
  end if;
  if v_name is null or length(v_name) not between 2 and 120 then
    raise exception 'a partner name of 2 to 120 characters is required' using errcode = '22023';
  end if;
  if v_purpose is null or length(v_purpose) not between 2 and 400 then
    raise exception 'a stated purpose of 2 to 400 characters is required' using errcode = '22023';
  end if;
  if v_status not in ('prospective', 'active', 'suspended', 'ended') then
    raise exception 'unsupported partner status' using errcode = '22023';
  end if;

  if p_partner is null then
    insert into public.partner_registry_v282 (name, purpose, status, created_by, updated_by)
    values (v_name, v_purpose, v_status, v_actor, v_actor)
    returning id into v_id;
  else
    update public.partner_registry_v282 partner
       set name = v_name, purpose = v_purpose, status = v_status,
           updated_at = now(), updated_by = v_actor
     where partner.id = p_partner
    returning partner.id into v_id;
    if v_id is null then
      raise exception 'partner not found' using errcode = '22023';
    end if;
  end if;

  return jsonb_build_object('status', 'ok', 'partner_id', v_id);
end;
$$;

--
-- Name: platform_send_quotation_v156(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_send_quotation_v156(p_document uuid, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'extensions', 'pg_temp'
    AS $$
declare v_actor uuid:=auth.uid();v_doc public.platform_subscription_documents_v156%rowtype;v_customer jsonb;v_delivery public.platform_subscription_deliveries_v156%rowtype;v_to text[];v_cc text[];v_internal text;v_hash text;v_replay jsonb;
begin
  select * into v_doc from public.platform_subscription_documents_v156 where id=p_document and document_type='quotation' and finalized_at is not null;
  if not found then raise exception 'finalized quotation was not found' using errcode='22023';end if;
  if v_actor is null or not app.v156_can_prospect(v_doc.prospect_id,'rw') then raise exception 'CRM write access is required' using errcode='42501';end if;
  v_hash:=encode(extensions.digest(jsonb_build_object('document',p_document)::text,'sha256'),'hex');
  perform pg_advisory_xact_lock(hashtextextended('v156-send-quote:'||p_idempotency_key::text,156));
  v_replay:=app.v156_operation_replay(p_idempotency_key,'send_quotation',v_actor,v_hash);if v_replay is not null then return v_replay;end if;
  select array_agg(email order by email) filter(where recipient_role='primary'),array_agg(email order by recipient_role,email) filter(where recipient_role<>'primary') into v_to,v_cc from public.platform_billing_contacts_v156 where active and prospect_id=v_doc.prospect_id;
  if coalesce(cardinality(v_to),0)=0 then raise exception 'primary billing recipient is required' using errcode='22023';end if;
  select internal_copy_email into v_internal from public.platform_billing_profiles_v156 where id=v_doc.seller_profile_id;
  if v_internal is not null then select array_agg(distinct address) into v_cc from unnest(coalesce(v_cc,'{}'::text[])||array[v_internal]) address where not(address=any(v_to));end if;
  v_customer:=v_doc.snapshot->'customer';
  insert into public.platform_subscription_deliveries_v156(delivery_key,business_id,prospect_id,provider_invoice_id,delivery_type,document_ids,recipients,cc_recipients,subject)
  values('quotation:'||p_document,v_doc.business_id,v_doc.prospect_id,null,'quotation',array[p_document],v_to,coalesce(v_cc,'{}'),'Peekaa quotation for '||coalesce(v_customer->>'business_display_name',v_customer->>'legal_entity_name'))
  on conflict(delivery_key) do update set updated_at=platform_subscription_deliveries_v156.updated_at returning * into v_delivery;
  -- "Sent" is recorded by v156_service_finish_delivery only after the provider
  -- accepts the message.  Queueing is not delivery evidence.
  return app.v156_store_operation(p_idempotency_key,'send_quotation',v_actor,v_hash,jsonb_build_object('delivery',to_jsonb(v_delivery),'document_number',v_doc.document_number));
end $$;

--
-- Name: platform_set_accounting_period_lock_v147(date, date, boolean, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_set_accounting_period_lock_v147(p_from date, p_to date, p_locked boolean, p_reason text, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_actor uuid:=auth.uid();v_hash text;v_existing public.platform_accounting_period_events_v147%rowtype;v_row public.platform_accounting_period_events_v147%rowtype;
begin
  if v_actor is null or not app.is_super_admin() then raise exception 'super-admin access is required' using errcode='42501';end if;
  v_hash:=encode(extensions.digest(jsonb_build_object('from',p_from,'to',p_to,'locked',p_locked,'reason',btrim(p_reason))::text,'sha256'),'hex');
  perform pg_advisory_xact_lock(hashtextextended('platform_period:'||p_idempotency_key::text,147));
  select * into v_existing from public.platform_accounting_period_events_v147 where created_by=v_actor and operation_key=p_idempotency_key;
  if found then if v_existing.request_hash<>v_hash then raise exception 'idempotency key was reused with different input' using errcode='22023';end if;return jsonb_build_object('event',to_jsonb(v_existing),'replayed',true);end if;
  if p_from is null or p_to<p_from or p_to-p_from>366 or length(btrim(p_reason))<8 then raise exception 'valid period and reason are required' using errcode='22023';end if;
  perform pg_advisory_xact_lock(hashtextextended('platform_accounting_period_gate',147));
  insert into public.platform_accounting_period_events_v147(period_from,period_to,action,reason,operation_key,request_hash,created_by) values(p_from,p_to,case when p_locked then 'lock' else 'unlock' end,btrim(p_reason),p_idempotency_key,v_hash,v_actor) returning * into v_row;
  insert into public.audit_log(business_id,actor,action,entity,entity_id,detail) values(null,v_actor,'PLATFORM_ACCOUNTING_PERIOD_'||upper(v_row.action)||'_V147','platform_accounting_period_events_v147',v_row.id,jsonb_build_object('from',p_from,'to',p_to));
  return jsonb_build_object('event',to_jsonb(v_row),'replayed',false);
end
$$;

--
-- Name: platform_set_accounting_policy_v147(date, text, text, text, text, text, integer, integer, integer, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_set_accounting_policy_v147(p_effective_from date, p_legal_name text, p_registration_number text, p_registered_address text, p_gst_status text, p_gst_registration_number text, p_gst_rate_bps integer, p_fye_month integer, p_fye_day integer, p_document_prefix text, p_evidence_reference text, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_actor uuid:=auth.uid();v_hash text;v_existing public.platform_accounting_policies_v147%rowtype;v_previous uuid;v_row public.platform_accounting_policies_v147%rowtype;v_version integer;
begin
  if v_actor is null or not app.is_super_admin() then raise exception 'super-admin access is required' using errcode='42501';end if;
  if p_idempotency_key is null then raise exception 'idempotency key is required' using errcode='22023';end if;
  v_hash:=encode(extensions.digest(jsonb_build_object('effective_from',p_effective_from,'legal_name',btrim(p_legal_name),'registration_number',btrim(p_registration_number),'address',btrim(p_registered_address),'gst_status',p_gst_status,'gst_number',nullif(btrim(p_gst_registration_number),''),'gst_rate_bps',p_gst_rate_bps,'fye_month',p_fye_month,'fye_day',p_fye_day,'prefix',upper(btrim(p_document_prefix)),'evidence',btrim(p_evidence_reference))::text,'sha256'),'hex');
  perform pg_advisory_xact_lock(hashtextextended('platform_accounting_policy:'||p_idempotency_key::text,147));
  select * into v_existing from public.platform_accounting_policies_v147 where created_by=v_actor and operation_key=p_idempotency_key;
  if found then
    if v_existing.request_hash<>v_hash then raise exception 'idempotency key was reused with different input' using errcode='22023';end if;
    return jsonb_build_object('policy',to_jsonb(v_existing),'replayed',true);
  end if;
  if p_effective_from is null or p_effective_from<(clock_timestamp() at time zone 'Asia/Singapore')::date-366 or p_gst_status not in ('not_registered','registered','pending_review') then raise exception 'valid policy configuration is required' using errcode='22023';end if;
  perform pg_advisory_xact_lock(hashtextextended('platform_accounting_policy_version',147));
  select id into v_previous from public.platform_accounting_policies_v147 order by effective_from desc,version desc limit 1;
  select coalesce(max(version),0)+1 into v_version from public.platform_accounting_policies_v147;
  insert into public.platform_accounting_policies_v147(version,effective_from,legal_name,registration_number,registered_address,gst_status,gst_registration_number,gst_rate_bps,financial_year_end_month,financial_year_end_day,document_prefix,operation_key,request_hash,supersedes,evidence_reference,created_by)
  values(v_version,p_effective_from,btrim(p_legal_name),btrim(p_registration_number),btrim(p_registered_address),p_gst_status,nullif(btrim(p_gst_registration_number),''),p_gst_rate_bps,p_fye_month,p_fye_day,upper(btrim(p_document_prefix)),p_idempotency_key,v_hash,v_previous,btrim(p_evidence_reference),v_actor) returning * into v_row;
  insert into public.audit_log(business_id,actor,action,entity,entity_id,detail) values(null,v_actor,'PLATFORM_ACCOUNTING_POLICY_SET_V147','platform_accounting_policies_v147',v_row.id,jsonb_build_object('operation_key',p_idempotency_key,'request_hash',v_hash,'version',v_version));
  perform app.platform_sync_expense_document_v147(expense) from public.platform_operating_expense_entries_v146 expense order by expense.created_at,expense.id;
  return jsonb_build_object('policy',to_jsonb(v_row),'replayed',false);
end
$$;

--
-- Name: platform_set_billing_profile_v156(jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_set_billing_profile_v156(p_profile jsonb, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'extensions', 'pg_temp'
    AS $$
declare v_actor uuid:=auth.uid();v_current public.platform_billing_profiles_v156%rowtype;v_new public.platform_billing_profiles_v156%rowtype;v_hash text;
begin
  if v_actor is null or not app.is_super_admin() then raise exception 'super admin access is required' using errcode='42501';end if;
  if jsonb_typeof(p_profile)<>'object' or p_idempotency_key is null then raise exception 'valid billing profile is required' using errcode='22023';end if;
  select * into v_current from public.platform_billing_profiles_v156 order by version desc limit 1;
  v_hash:=encode(extensions.digest(jsonb_build_object('profile',p_profile)::text,'sha256'),'hex');
  perform pg_advisory_xact_lock(hashtextextended('v156-profile:'||p_idempotency_key::text,156));
  perform pg_advisory_xact_lock(hashtextextended('v156-profile-version',156));
  select * into v_new from public.platform_billing_profiles_v156 where operation_key=p_idempotency_key;
  if found then
    if v_new.request_hash<>v_hash then raise exception 'idempotency key conflict' using errcode='22023';end if;
    return jsonb_build_object('profile',to_jsonb(v_new)-'bank_account_number','bank_account_last4',right(v_new.bank_account_number,4),'ready',app.v156_profile_ready(v_new),'replayed',true);
  end if;
  insert into public.platform_billing_profiles_v156(version,brand_name,legal_name,uen,registered_address,
    billing_email,currency,gst_status,gst_registration_number,gst_rate_bps,default_payment_terms,
    logo_object_path,authorised_signature_object_path,bank_account_name,bank_name,bank_code,branch_code,
    swift_code,bank_account_number,bank_account_location,billing_contact_name,billing_contact_mobile,
    internal_copy_email,customer_reminders_enabled,annual_reminder_days,created_by,operation_key,request_hash)
  values(v_current.version+1,coalesce(nullif(btrim(p_profile->>'brand_name'),''),v_current.brand_name),
    coalesce(nullif(btrim(p_profile->>'legal_name'),''),v_current.legal_name),case when p_profile?'uen' then nullif(btrim(p_profile->>'uen'),'') else v_current.uen end,
    case when p_profile?'registered_address' then nullif(btrim(p_profile->>'registered_address'),'') else v_current.registered_address end,
    case when p_profile?'billing_email' then lower(nullif(btrim(p_profile->>'billing_email'),'')) else v_current.billing_email end,
    'SGD',coalesce(nullif(p_profile->>'gst_status',''),v_current.gst_status),case when p_profile?'gst_registration_number' then nullif(btrim(p_profile->>'gst_registration_number'),'') else v_current.gst_registration_number end,
    coalesce((p_profile->>'gst_rate_bps')::integer,v_current.gst_rate_bps),case when p_profile?'default_payment_terms' then nullif(btrim(p_profile->>'default_payment_terms'),'') else v_current.default_payment_terms end,
    nullif(btrim(p_profile->>'logo_object_path'),''),nullif(btrim(p_profile->>'authorised_signature_object_path'),''),
    coalesce(nullif(btrim(p_profile->>'bank_account_name'),''),v_current.bank_account_name),
    coalesce(nullif(btrim(p_profile->>'bank_name'),''),v_current.bank_name),
    coalesce(nullif(btrim(p_profile->>'bank_code'),''),v_current.bank_code),
    coalesce(nullif(btrim(p_profile->>'branch_code'),''),v_current.branch_code),
    coalesce(nullif(btrim(p_profile->>'swift_code'),''),v_current.swift_code),
    coalesce(nullif(btrim(p_profile->>'bank_account_number'),''),v_current.bank_account_number),
    coalesce(nullif(btrim(p_profile->>'bank_account_location'),''),v_current.bank_account_location),
    coalesce(nullif(btrim(p_profile->>'billing_contact_name'),''),v_current.billing_contact_name),
    coalesce(nullif(btrim(p_profile->>'billing_contact_mobile'),''),v_current.billing_contact_mobile),
    case when p_profile?'internal_copy_email' then lower(nullif(btrim(p_profile->>'internal_copy_email'),'')) else v_current.internal_copy_email end,
    coalesce((p_profile->>'customer_reminders_enabled')::boolean,v_current.customer_reminders_enabled),
    case when jsonb_typeof(p_profile->'annual_reminder_days')='array' then array(select jsonb_array_elements_text(p_profile->'annual_reminder_days')::integer) else v_current.annual_reminder_days end,
    v_actor,p_idempotency_key,v_hash)
  returning * into v_new;
  insert into public.platform_subscription_dispatch_audit_v156(action,entity_type,entity_id,detail,actor)
  values('billing_profile_versioned','billing_profile',v_new.id,jsonb_build_object('version',v_new.version,'request_hash',v_hash),v_actor);
  return jsonb_build_object('profile',to_jsonb(v_new)-'bank_account_number','bank_account_last4',right(v_new.bank_account_number,4),'ready',app.v156_profile_ready(v_new),'replayed',false);
end $$;

--
-- Name: platform_set_business_sector_override_v75(uuid, text[], text[], text, bigint, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_set_business_sector_override_v75(p_business uuid, p_add_modules text[], p_remove_modules text[], p_reason text, p_expected_version bigint DEFAULT NULL::bigint, p_dry_run boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid(); v_assignment public.business_sector_assignments%rowtype;
  v_bundle public.sector_bundle_versions%rowtype; v_effective text[];
  v_override_id uuid; v_override_version integer; v_next bigint;
begin
  if not app.is_super_admin() then
    raise exception 'super admin access is required' using errcode = '42501';
  end if;
  if length(btrim(coalesce(p_reason,''))) < 3 then
    raise exception 'override reason is required' using errcode = '22023';
  end if;
  select * into v_assignment from public.business_sector_assignments
   where business_id = p_business for update;
  if not found then raise exception 'business sector assignment was not found' using errcode = '22023'; end if;
  if p_expected_version is not null and v_assignment.version <> p_expected_version then
    raise exception 'sector assignment version conflict' using errcode = '40001';
  end if;
  select * into strict v_bundle from public.sector_bundle_versions
   where id = v_assignment.bundle_version_id;
  v_effective := app.resolve_sector_entitlement_v75(
    v_bundle.id, coalesce(p_add_modules,'{}'), coalesce(p_remove_modules,'{}')
  );
  select coalesce(max(version),0)+1 into v_override_version
    from public.business_sector_override_versions where business_id = p_business;
  v_next := v_assignment.version + 1;
  if not coalesce(p_dry_run, true) then
    insert into public.business_sector_override_versions(
      business_id,version,add_modules,remove_modules,reason,created_by
    ) values (
      p_business,v_override_version,coalesce(p_add_modules,'{}'),
      coalesce(p_remove_modules,'{}'),btrim(p_reason),v_actor
    ) returning id into v_override_id;
    update public.business_sector_assignments
       set override_version_id=v_override_id,version=v_next,
           assigned_by=v_actor,updated_at=now()
     where business_id=p_business;
    perform set_config('app.sector_entitlement_sync', p_business::text, true);
    update public.businesses set enabled_modules=v_effective where id=p_business;
    insert into public.audit_log(business_id, actor, action, entity, entity_id, detail)
    values (p_business,v_actor,'BUSINESS_SECTOR_OVERRIDE_SET_V75','businesses',p_business,
            jsonb_build_object('override_version_id',v_override_id,
              'override_version',v_override_version,'assignment_version',v_next,
              'add_modules',coalesce(p_add_modules,'{}'),'remove_modules',coalesce(p_remove_modules,'{}'),
              'effective_modules',v_effective,'reason',btrim(p_reason)));
  end if;
  return jsonb_build_object(
    'dry_run',coalesce(p_dry_run,true),'changed',true,'business_id',p_business,
    'assignment_version',v_next,'bundle_version_id',v_bundle.id,
    'sector_key',v_bundle.sector_key,'override_version_id',v_override_id,
    'override_version',v_override_version,'add_modules',to_jsonb(coalesce(p_add_modules,'{}')),
    'remove_modules',to_jsonb(coalesce(p_remove_modules,'{}')),
    'effective_modules',to_jsonb(v_effective)
  );
end
$$;

--
-- Name: platform_set_catalogue_intelligence_v94(uuid, boolean, text, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_set_catalogue_intelligence_v94(p_business uuid, p_enabled boolean, p_reason text, p_expected_version bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_row public.business_platform_intelligence_settings_v94%rowtype;
begin
  if not app.is_super_admin() then
    raise exception 'super_admin_required' using errcode='42501';
  end if;
  if p_enabled is null or length(btrim(coalesce(p_reason,''))) not between 3 and 1000 then
    raise exception 'valid catalogue setting and reason are required' using errcode='22023';
  end if;
  select * into v_row from public.business_platform_intelligence_settings_v94
  where business_id=p_business for update;
  if not found then raise exception 'business_not_found' using errcode='22023';end if;
  if p_expected_version is null or p_expected_version<>v_row.version then
    raise exception 'catalogue_setting_version_conflict' using errcode='40001';
  end if;
  update public.business_platform_intelligence_settings_v94
  set catalogue_intelligence_enabled=p_enabled,version=version+1,
    reason=btrim(p_reason),updated_by=auth.uid(),updated_at=now()
  where business_id=p_business returning * into v_row;
  insert into public.audit_log(
    business_id,actor,action,entity,entity_id,detail
  ) values(
    p_business,auth.uid(),'CATALOGUE_INTELLIGENCE_SET_V94',
    'businesses',p_business,jsonb_build_object(
      'enabled',p_enabled,'version',v_row.version,'reason',btrim(p_reason)
    )
  );
  return jsonb_build_object(
    'business_id',p_business,
    'catalogue_intelligence_enabled',v_row.catalogue_intelligence_enabled,
    'version',v_row.version,'updated_at',v_row.updated_at
  );
end
$$;

--
-- Name: platform_set_consultant_hotline_v94(uuid, text, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_set_consultant_hotline_v94(p_consultant uuid, p_phone text, p_expected_version bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $_$
declare v_row public.platform_consultant_hotlines_v94%rowtype;v_name text;
begin
  if not app.is_super_admin() then
    raise exception 'super_admin_required' using errcode='42501';
  end if;
  if p_phone is null or p_phone!~'^\+[1-9][0-9]{7,14}$' then
    raise exception 'hotline_must_be_e164' using errcode='22023';
  end if;
  select display_name into v_name from public.platform_consultants
  where id=p_consultant and active;
  if not found then raise exception 'active_consultant_not_found' using errcode='22023';end if;
  select * into v_row from public.platform_consultant_hotlines_v94
  where consultant_id=p_consultant for update;
  if found then
    if p_expected_version is null or p_expected_version<>v_row.version then
      raise exception 'hotline_version_conflict' using errcode='40001';
    end if;
    update public.platform_consultant_hotlines_v94
    set hotline_phone=p_phone,version=version+1,updated_by=auth.uid(),updated_at=now()
    where consultant_id=p_consultant returning * into v_row;
  else
    if p_expected_version is not null then
      raise exception 'hotline_version_conflict' using errcode='40001';
    end if;
    insert into public.platform_consultant_hotlines_v94(
      consultant_id,hotline_phone,updated_by
    ) values(p_consultant,p_phone,auth.uid()) returning * into v_row;
  end if;
  return jsonb_build_object(
    'consultant_id',p_consultant,'display_name',v_name,
    'hotline_phone',v_row.hotline_phone,'version',v_row.version
  );
end
$_$;

--
-- Name: platform_set_module_override_v94(uuid, uuid, text, text, text, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_set_module_override_v94(p_business uuid, p_branch uuid, p_module text, p_mode text, p_reason text, p_expected_version bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $_$
declare v_actor uuid:=auth.uid();v_prior public.platform_module_overrides_v94%rowtype;
  v_row public.platform_module_overrides_v94%rowtype;v_effective record;
begin
  if not app.is_super_admin() then
    raise exception 'super_admin_required' using errcode='42501';
  end if;
  if p_module is null or p_module!~'^[a-z][a-z0-9_]*$'
     or p_mode not in ('inherit','disabled','r','rw')
     or length(btrim(coalesce(p_reason,''))) not between 3 and 1000 then
    raise exception 'valid module override is required' using errcode='22023';
  end if;
  if p_branch is not null and not exists(
    select 1 from public.branches branch
    where branch.id=p_branch and branch.business_id=p_business
  ) then raise exception 'branch_not_in_business' using errcode='22023';end if;
  select * into v_prior from public.platform_module_overrides_v94 override_row
  where override_row.business_id=p_business
    and override_row.branch_scope is not distinct from p_branch
    and override_row.module_key=p_module for update;
  if found then
    if p_expected_version is null or p_expected_version<>v_prior.version then
      raise exception 'module_override_version_conflict' using errcode='40001';
    end if;
    update public.platform_module_overrides_v94
    set mode=p_mode,version=version+1,reason=btrim(p_reason),
      updated_by=v_actor,updated_at=now()
    where business_id=p_business
      and branch_scope is not distinct from p_branch
      and module_key=p_module returning * into v_row;
  else
    if p_expected_version is not null then
      raise exception 'module_override_version_conflict' using errcode='40001';
    end if;
    insert into public.platform_module_overrides_v94(
      business_id,branch_scope,module_key,mode,reason,updated_by
    ) values(p_business,p_branch,p_module,p_mode,btrim(p_reason),v_actor)
    returning * into v_row;
  end if;
  insert into public.platform_module_override_audit_v94(
    business_id,branch_scope,module_key,prior_mode,new_mode,prior_version,
    new_version,reason,actor
  ) values(
    p_business,p_branch,p_module,v_prior.mode,p_mode,v_prior.version,
    v_row.version,btrim(p_reason),v_actor
  );
  select * into v_effective
  from app.effective_platform_module_mode_v94(p_business,p_branch,p_module);
  return jsonb_build_object(
    'business_id',p_business,'branch_id',p_branch,'module_key',p_module,
    'mode',p_mode,'version',v_row.version,
    'effective_mode',v_effective.mode,'source',v_effective.source
  );
end
$_$;

--
-- Name: platform_set_module_overrides_v105(uuid, uuid, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_set_module_overrides_v105(p_business uuid, p_branch uuid, p_changes jsonb, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $_$
declare
  v_actor uuid:=auth.uid();
  v_change jsonb;
  v_module text;
  v_mode text;
  v_expected_version bigint;
  v_prior_mode text;
  v_prior_version bigint;
  v_new_version bigint;
  v_effective record;
  v_results jsonb:='[]'::jsonb;
begin
  if not app.is_super_admin() then
    raise exception 'super_admin_required' using errcode='42501';
  end if;
  if length(btrim(coalesce(p_reason,''))) not between 3 and 1000 then
    raise exception 'module_override_reason_required' using errcode='22023';
  end if;
  if jsonb_typeof(p_changes) is distinct from 'array'
     or jsonb_array_length(p_changes) not between 1 and 100 then
    raise exception 'module_override_changes_required' using errcode='22023';
  end if;
  perform 1 from public.businesses where id=p_business for key share;
  if not found then
    raise exception 'business_not_found' using errcode='22023';
  end if;
  if p_branch is not null and not exists(
    select 1 from public.branches branch
    where branch.id=p_branch and branch.business_id=p_business
  ) then
    raise exception 'branch_not_in_business' using errcode='22023';
  end if;
  if exists(
    select 1
    from jsonb_array_elements(p_changes) change
    group by change->>'module'
    having count(*)>1
  ) then
    raise exception 'duplicate_module_override' using errcode='22023';
  end if;

  -- Validate the complete request before taking any write action.
  for v_change in
    select change
    from jsonb_array_elements(p_changes) change
    order by change->>'module'
  loop
    perform app.v86_assert_object_keys(
      v_change,array['module','mode','expected_version'],'module override change'
    );
    v_module:=v_change->>'module';
    v_mode:=v_change->>'mode';
    if v_module is null or v_module!~'^[a-z][a-z0-9_]*$'
       or v_mode not in ('inherit','disabled','r','rw')
       or jsonb_typeof(v_change->'expected_version') not in ('number','null') then
      raise exception 'valid_module_override_change_required' using errcode='22023';
    end if;
  end loop;

  -- Lock every existing row in deterministic order, then preflight every
  -- optimistic version. Any mismatch aborts the single PostgreSQL transaction.
  perform 1
  from public.platform_module_overrides_v94 override_row
  where override_row.business_id=p_business
    and override_row.branch_scope is not distinct from p_branch
    and override_row.module_key in (
      select change->>'module' from jsonb_array_elements(p_changes) change
    )
  order by override_row.module_key
  for update;

  for v_change in
    select change
    from jsonb_array_elements(p_changes) change
    order by change->>'module'
  loop
    v_module:=v_change->>'module';
    v_prior_version:=null;
    v_expected_version:=case
      when jsonb_typeof(v_change->'expected_version')='number'
        then (v_change->>'expected_version')::bigint
      else null
    end;
    select override_row.version
    into v_prior_version
    from public.platform_module_overrides_v94 override_row
    where override_row.business_id=p_business
      and override_row.branch_scope is not distinct from p_branch
      and override_row.module_key=v_module;
    if found then
      if v_expected_version is null or v_expected_version<>v_prior_version then
        raise exception 'module_override_version_conflict' using errcode='40001';
      end if;
    elsif v_expected_version is not null then
      raise exception 'module_override_version_conflict' using errcode='40001';
    end if;
  end loop;

  for v_change in
    select change
    from jsonb_array_elements(p_changes) change
    order by change->>'module'
  loop
    v_module:=v_change->>'module';
    v_mode:=v_change->>'mode';
    v_prior_mode:=null;
    v_prior_version:=null;
    select override_row.mode,override_row.version
    into v_prior_mode,v_prior_version
    from public.platform_module_overrides_v94 override_row
    where override_row.business_id=p_business
      and override_row.branch_scope is not distinct from p_branch
      and override_row.module_key=v_module;
    if found then
      update public.platform_module_overrides_v94
      set mode=v_mode,version=version+1,reason=btrim(p_reason),
        updated_by=v_actor,updated_at=now()
      where business_id=p_business
        and branch_scope is not distinct from p_branch
        and module_key=v_module
      returning version into v_new_version;
    else
      insert into public.platform_module_overrides_v94(
        business_id,branch_scope,module_key,mode,reason,updated_by
      ) values(
        p_business,p_branch,v_module,v_mode,btrim(p_reason),v_actor
      )
      returning version into v_new_version;
    end if;
    insert into public.platform_module_override_audit_v94(
      business_id,branch_scope,module_key,prior_mode,new_mode,prior_version,
      new_version,reason,actor
    ) values(
      p_business,p_branch,v_module,v_prior_mode,v_mode,v_prior_version,
      v_new_version,btrim(p_reason),v_actor
    );
    select * into v_effective
    from app.effective_platform_module_mode_v94(
      p_business,p_branch,v_module
    );
    v_results:=v_results||jsonb_build_array(jsonb_build_object(
      'business_id',p_business,
      'branch_id',p_branch,
      'module_key',v_module,
      'mode',v_mode,
      'version',v_new_version,
      'effective_mode',v_effective.mode,
      'source',v_effective.source
    ));
  end loop;
  return jsonb_build_object(
    'business_id',p_business,
    'branch_id',p_branch,
    'updated_count',jsonb_array_length(v_results),
    'items',v_results
  );
end
$_$;

--
-- Name: FUNCTION platform_set_module_overrides_v105(p_business uuid, p_branch uuid, p_changes jsonb, p_reason text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.platform_set_module_overrides_v105(p_business uuid, p_branch uuid, p_changes jsonb, p_reason text) IS 'v105 super-admin atomic batch module policy writer. Validates and version-checks every change before writing any row.';

--
-- Name: platform_set_promotion_entitlement_v104(uuid, integer, timestamp with time zone, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_set_promotion_entitlement_v104(p_business uuid, p_max_published_offers integer, p_complimentary_until timestamp with time zone, p_expected_version bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_row public.business_promotion_entitlements_v104%rowtype;
begin
  if auth.uid() is null or not app.is_super_admin() then
    raise exception 'super_admin_required' using errcode='42501';
  end if;
  if p_business is null
     or p_max_published_offers is null
     or p_max_published_offers not between 0 and 100
     or p_complimentary_until is null
     or p_expected_version is null
     or not exists(
       select 1 from public.businesses business where business.id=p_business
     )
  then
    raise exception 'valid_promotion_entitlement_required'
      using errcode='22023';
  end if;

  perform app.v104_lock_promotion_business(p_business);

  select * into v_row
  from public.business_promotion_entitlements_v104 entitlement
  where entitlement.business_id=p_business
  for update;

  if found then
    if v_row.version<>p_expected_version then
      raise exception 'promotion_entitlement_version_conflict'
        using errcode='40001';
    end if;
    update public.business_promotion_entitlements_v104
    set max_published_offers=p_max_published_offers,
        complimentary_until=p_complimentary_until,
        version=version+1,
        updated_by=auth.uid(),
        updated_at=now()
    where business_id=p_business
    returning * into v_row;
  else
    if p_expected_version<>0 then
      raise exception 'promotion_entitlement_version_conflict'
        using errcode='40001';
    end if;
    insert into public.business_promotion_entitlements_v104(
      business_id,max_published_offers,complimentary_until,updated_by
    ) values(
      p_business,p_max_published_offers,p_complimentary_until,auth.uid()
    )
    returning * into v_row;
  end if;

  return jsonb_build_object(
    'business_id',v_row.business_id,
    'max_published_offers',v_row.max_published_offers,
    'complimentary_until',v_row.complimentary_until,
    'version',v_row.version
  );
end
$$;

--
-- Name: platform_stage_prospect_import_v76(text, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_stage_prospect_import_v76(p_source_system text, p_source_name text, p_rows jsonb, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid:=auth.uid();v_hash text;v_replay jsonb;v_batch uuid;v_row jsonb;v_n integer:=0;
  v_stage text;v_status text;v_registration text;v_valid integer:=0;v_unmapped integer:=0;
  v_conflict integer:=0;v_invalid integer:=0;v_response jsonb;
begin
  if not app.is_platform_operator_v75() then raise exception 'platform operator access is required' using errcode='42501';end if;
  if jsonb_typeof(p_rows)<>'array' or jsonb_array_length(p_rows)>1000 then raise exception 'import rows must be an array of at most 1000 objects' using errcode='22023';end if;
  v_hash:=app.v76_sha256_hex(jsonb_build_object('system',p_source_system,'name',p_source_name,'rows',p_rows)::text);
  v_replay:=app.v76_replay(v_actor,'stage_import',p_idempotency_key,v_hash);if v_replay is not null then return v_replay;end if;
  insert into public.sme_prospect_import_batches(source_system,source_name,total_rows,created_by)
  values(btrim(p_source_system),btrim(p_source_name),jsonb_array_length(p_rows),v_actor) returning id into v_batch;
  for v_row in select value from jsonb_array_elements(p_rows) loop
    v_n:=v_n+1;v_stage:=app.map_sme_stage_v76(v_row->>'stage');
    v_registration:=nullif(lower(btrim(v_row->>'registration_number')),'');
    if jsonb_typeof(v_row)<>'object' or (coalesce(v_row->>'legal_name','')='' and coalesce(v_row->>'trading_name','')='') then
      v_status:='invalid';v_invalid:=v_invalid+1;
    elsif v_registration is not null and (
      exists(select 1 from public.sme_companies company
        where lower(btrim(company.registration_number))=v_registration)
      or exists(select 1 from public.sme_prospect_import_rows prior
        where prior.batch_id=v_batch and prior.row_number<v_n
          and lower(btrim(prior.raw_payload->>'registration_number'))=v_registration)
    ) then v_status:='conflict';v_conflict:=v_conflict+1;
    elsif v_stage is null then v_status:='unmapped';v_unmapped:=v_unmapped+1;
    else v_status:='valid';v_valid:=v_valid+1;end if;
    insert into public.sme_prospect_import_rows(
      batch_id,row_number,raw_payload,normalized_payload,raw_stage,mapped_stage_key,row_status,errors
    ) values(v_batch,v_n,v_row,v_row,v_row->>'stage',v_stage,v_status,
      case when v_status='invalid' then array['company_name_required']
           when v_status='conflict' then array['duplicate_registration_number']
           when v_status='unmapped' then array['unmapped_stage'] else '{}' end);
  end loop;
  update public.sme_prospect_import_batches set valid_rows=v_valid,unmapped_rows=v_unmapped,
    conflict_rows=v_conflict,invalid_rows=v_invalid,skipped_rows=v_conflict+v_invalid where id=v_batch;
  insert into public.audit_log(business_id,actor,action,entity,entity_id,detail)
  values(null,v_actor,'SME_PROSPECT_IMPORT_STAGED_V76','sme_prospect_import_batches',v_batch,
    jsonb_build_object('total_rows',v_n,'valid_rows',v_valid,
      'unmapped_rows',v_unmapped,'conflict_rows',v_conflict,'invalid_rows',v_invalid));
  v_response:=jsonb_build_object('replayed',false,'batch_id',v_batch,'status','staged',
    'total_rows',v_n,'valid_rows',v_valid,'unmapped_rows',v_unmapped,
    'conflict_rows',v_conflict,'invalid_rows',v_invalid,'skipped_rows',v_conflict+v_invalid);
  perform app.v76_store_receipt(v_actor,'stage_import',p_idempotency_key,v_hash,v_response);return v_response;
end
$$;

--
-- Name: platform_transition_account_deletion_request_v133(uuid, text, text, text, timestamp with time zone, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_transition_account_deletion_request_v133(p_request uuid, p_action text, p_reason text, p_disposition text DEFAULT NULL::text, p_retention_until timestamp with time zone DEFAULT NULL::timestamp with time zone, p_evidence_reference text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid:=auth.uid();
  v_action text:=btrim(coalesce(p_action,''));
  v_reason text:=btrim(coalesce(p_reason,''));
  v_disposition text:=nullif(btrim(coalesce(p_disposition,'')),'');
  v_reference text:=nullif(btrim(coalesce(p_evidence_reference,'')),'');
  v_key text:=btrim(coalesce(p_idempotency_key,''));
  v_fingerprint text;
  v_existing public.account_deletion_request_events%rowtype;
  v_request public.account_deletion_requests%rowtype;
  v_receipt jsonb;
begin
  if v_actor is null or not app.is_super_admin() then
    raise exception 'super-admin only' using errcode='42501';
  end if;
  if p_request is null or v_action not in('claim','resolve','retention_review') then
    raise exception 'invalid action' using errcode='22023';
  end if;
  if length(v_reason) not between 8 and 1000
     or length(v_key) not between 8 and 200 then
    raise exception 'reason and idempotency key are required' using errcode='22023';
  end if;
  v_fingerprint:=encode(extensions.digest(convert_to(concat_ws('|',
    p_request::text,v_action,v_reason,coalesce(v_disposition,'-'),
    coalesce(p_retention_until::text,'-'),coalesce(v_reference,'-')
  ),'UTF8'),'sha256'),'hex');

  perform pg_advisory_xact_lock(hashtextextended(p_request::text,133));

  select * into v_existing
    from public.account_deletion_request_events event_row
   where event_row.operator_auth_user_id=v_actor
     and event_row.idempotency_key=v_key;
  if v_existing.id is not null then
    if v_existing.request_fingerprint<>v_fingerprint then
      raise exception 'idempotency key reused with different request' using errcode='22023';
    end if;
    return v_existing.result_snapshot;
  end if;

  if v_action='claim' and (
    v_disposition is not null or p_retention_until is not null or v_reference is not null
  ) then
    raise exception 'claim cannot include resolution fields' using errcode='22023';
  end if;
  if v_action in('resolve','retention_review') then
    if v_disposition not in(
      'deleted_where_permitted','anonymised_where_permitted',
      'retained_legal','request_invalid'
    ) or length(v_reference) not between 8 and 200 then
      raise exception 'valid disposition and evidence reference are required' using errcode='22023';
    end if;
    if v_disposition='retained_legal' and (
      p_retention_until is null or p_retention_until<=now()
    ) then
      raise exception 'future retention deadline required' using errcode='22023';
    end if;
    if v_disposition<>'retained_legal' and p_retention_until is not null then
      raise exception 'retention deadline is only valid for retained records' using errcode='22023';
    end if;
    if v_action='retention_review' and v_disposition='request_invalid' then
      raise exception 'an accepted retained request cannot become invalid' using errcode='22023';
    end if;
  end if;

  select * into v_request
    from public.account_deletion_requests
   where id=p_request for update;
  if v_request.id is null then
    raise exception 'deletion request not found' using errcode='22023';
  end if;

  if v_action='claim' then
    if v_request.status<>'pending' then
      raise exception 'only a pending request can be claimed' using errcode='22023';
    end if;
    update public.account_deletion_requests
       set status='processing',claimed_at=now(),claimed_by=v_actor,updated_at=now()
     where id=v_request.id returning * into v_request;
  elsif v_action='resolve' then
    if v_request.status<>'processing' then
      raise exception 'only a processing request can be resolved' using errcode='22023';
    end if;
    update public.account_deletion_requests
       set status='completed',completed_at=now(),updated_at=now(),
           operator_note=v_reason,resolution_code=v_disposition,
           retention_until=p_retention_until,resolution_reference=v_reference
     where id=v_request.id returning * into v_request;
  else
    if v_request.status<>'completed' or v_request.resolution_code<>'retained_legal'
       or v_request.retention_until is null or v_request.retention_until>now() then
      raise exception 'retention review is available only when legal retention is due' using errcode='22023';
    end if;
    update public.account_deletion_requests
       set completed_at=now(),updated_at=now(),claimed_at=now(),claimed_by=v_actor,
           operator_note=v_reason,resolution_code=v_disposition,
           retention_until=p_retention_until,resolution_reference=v_reference
     where id=v_request.id returning * into v_request;
  end if;

  v_receipt:=jsonb_build_object(
    'request_id',v_request.id,'status',v_request.status,
    'claimed_at',v_request.claimed_at,'completed_at',v_request.completed_at,
    'resolution_code',v_request.resolution_code,
    'retention_until',v_request.retention_until
  );

  insert into public.account_deletion_request_events(
    request_id,operator_auth_user_id,action,disposition,reason,
    evidence_reference,retention_until,idempotency_key,request_fingerprint,result_snapshot
  ) values(
    v_request.id,v_actor,v_action,v_disposition,v_reason,
    v_reference,p_retention_until,v_key,v_fingerprint,v_receipt
  );

  return v_receipt;
end
$$;

--
-- Name: FUNCTION platform_transition_account_deletion_request_v133(p_request uuid, p_action text, p_reason text, p_disposition text, p_retention_until timestamp with time zone, p_evidence_reference text, p_idempotency_key text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.platform_transition_account_deletion_request_v133(p_request uuid, p_action text, p_reason text, p_disposition text, p_retention_until timestamp with time zone, p_evidence_reference text, p_idempotency_key text) IS 'V133 super-admin claim/resolution receipt. Resolution records reviewed off-console fulfilment and never deletes data itself.';

--
-- Name: platform_update_prospect_v76(uuid, bigint, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_update_prospect_v76(p_prospect uuid, p_expected_version bigint, p_patch jsonb, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid:=auth.uid(); v_hash text; v_replay jsonb; v_row public.sme_prospects%rowtype;
  v_unknown text[]; v_qversion integer; v_response jsonb;
begin
  if not app.is_platform_operator_v75() then raise exception 'platform operator access is required' using errcode='42501'; end if;
  if jsonb_typeof(p_patch)<>'object' then raise exception 'patch must be an object' using errcode='22023'; end if;
  perform app.v184_assert_prospect_active(p_prospect);
  select array_agg(key order by key) into v_unknown from jsonb_object_keys(p_patch) key
   where key not in ('legal_name','trading_name','registration_number','industry','sector_key',
     'website','phone','email','address','next_action_at','priority','region','qualification','tags');
  if cardinality(v_unknown)>0 then raise exception 'unsupported prospect patch fields: %',array_to_string(v_unknown,', ') using errcode='22023'; end if;
  v_hash:=app.v76_sha256_hex(jsonb_build_object('prospect',p_prospect,'version',p_expected_version,'patch',p_patch)::text);
  v_replay:=app.v76_replay(v_actor,'update_prospect',p_idempotency_key,v_hash);
  if v_replay is not null then return v_replay; end if;
  update public.sme_prospects set
    next_action_at=case when p_patch?'next_action_at' then (p_patch->>'next_action_at')::timestamptz else next_action_at end,
    priority=case when p_patch?'priority' then p_patch->>'priority' else priority end,
    region=case when p_patch?'region' then nullif(btrim(p_patch->>'region'),'') else region end,
    version=version+1,updated_by=v_actor,updated_at=now()
   where id=p_prospect and version=p_expected_version returning * into v_row;
  if not found then raise exception 'prospect version conflict' using errcode='40001'; end if;
  update public.sme_companies set
    legal_name=case when p_patch?'legal_name' then nullif(btrim(p_patch->>'legal_name'),'') else legal_name end,
    trading_name=case when p_patch?'trading_name' then nullif(btrim(p_patch->>'trading_name'),'') else trading_name end,
    registration_number=case when p_patch?'registration_number' then nullif(btrim(p_patch->>'registration_number'),'') else registration_number end,
    industry=case when p_patch?'industry' then nullif(btrim(p_patch->>'industry'),'') else industry end,
    sector_key=case when p_patch?'sector_key' then nullif(btrim(p_patch->>'sector_key'),'') else sector_key end,
    website=case when p_patch?'website' then nullif(btrim(p_patch->>'website'),'') else website end,
    phone=case when p_patch?'phone' then nullif(btrim(p_patch->>'phone'),'') else phone end,
    email=case when p_patch?'email' then nullif(btrim(p_patch->>'email'),'') else email end,
    address=case when p_patch?'address' then p_patch->'address' else address end,
    updated_at=now() where id=v_row.company_id;
  if p_patch?'qualification' then
    select coalesce(max(version),0)+1 into v_qversion from public.sme_prospect_qualification_versions where prospect_id=p_prospect;
    insert into public.sme_prospect_qualification_versions(
      prospect_id,version,budget_status,authority_status,need_status,timeline_status,score,notes,created_by
    ) values(p_prospect,v_qversion,p_patch#>>'{qualification,budget_status}',
      p_patch#>>'{qualification,authority_status}',p_patch#>>'{qualification,need_status}',
      p_patch#>>'{qualification,timeline_status}',(p_patch#>>'{qualification,score}')::smallint,
      p_patch#>>'{qualification,notes}',v_actor);
  end if;
  if p_patch?'tags' then
    perform app.v76_set_tags(p_prospect,array(select jsonb_array_elements_text(p_patch->'tags')));
  end if;
  insert into public.audit_log(business_id,actor,action,entity,entity_id,detail)
  values(null,v_actor,'SME_PROSPECT_UPDATED_V76','sme_prospects',p_prospect,
    jsonb_build_object('prior_version',p_expected_version,'new_version',v_row.version,'fields',
      (select jsonb_agg(key) from jsonb_object_keys(p_patch) key)));
  v_response:=jsonb_build_object('replayed',false,'prospect',app.sme_prospect_card_v76(p_prospect));
  perform app.v76_store_receipt(v_actor,'update_prospect',p_idempotency_key,v_hash,v_response);
  return v_response;
end
$$;

--
-- Name: platform_upsert_access_grant_v89(uuid, text, jsonb, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_upsert_access_grant_v89(p_user uuid, p_role text, p_module_perms jsonb, p_active boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $_$
declare v_before public.platform_access_grants_v89%rowtype;
  v_after public.platform_access_grants_v89%rowtype;v_event text;
begin
  if not app.is_super_admin() then
    raise exception 'super admin access is required' using errcode='42501';
  end if;
  if p_user is null or p_role not in ('admin','sales_staff')
     or jsonb_typeof(p_module_perms)<>'object'
     or jsonb_path_exists(p_module_perms,'$.* ? (@ != "r" && @ != "rw")') then
    raise exception 'invalid platform access grant' using errcode='22023';
  end if;
  if exists(
    select 1 from jsonb_object_keys(p_module_perms) permission_key
    where permission_key not in(
      '*','overview','onboarding','firms','reports','billing','commissions',
      'sectors','automation'
    )
  ) then
    raise exception 'unknown platform module permission' using errcode='22023';
  end if;
  if p_role='sales_staff' and (
    coalesce(p_module_perms->>'onboarding','')<>'rw'
    or coalesce(p_module_perms->>'reports','') not in ('r','rw')
  ) then
    raise exception 'sales staff require onboarding rw and reports read access'
      using errcode='22023';
  end if;
  if p_role='sales_staff' and not exists(
    select 1 from public.platform_consultants consultant
    where consultant.user_id=p_user and consultant.active
  ) then
    raise exception 'sales staff require an active consultant profile'
      using errcode='22023';
  end if;
  if p_role='admin' and not(p_module_perms?'*') then
    -- Explicit per-module maps are supported; an empty admin map is not.
    if (select count(*) from jsonb_object_keys(p_module_perms))=0 then
      raise exception 'admin module permissions must not be empty' using errcode='22023';
    end if;
  end if;
  select * into v_before from public.platform_access_grants_v89
    where user_id=p_user for update;
  insert into public.platform_access_grants_v89(
    user_id,role,module_perms,active,created_by,updated_by
  ) values(
    p_user,p_role,p_module_perms,coalesce(p_active,true),auth.uid(),auth.uid()
  ) on conflict(user_id) do update set
    role=excluded.role,module_perms=excluded.module_perms,active=excluded.active,
    updated_by=auth.uid(),updated_at=now()
  returning * into v_after;
  v_event:=case when v_before.user_id is null then 'grant_created'
    when not v_after.active then 'grant_disabled' else 'grant_updated' end;
  insert into public.platform_access_audit_v89(
    subject_user_id,actor,event_type,before_value,after_value
  ) values(p_user,auth.uid(),v_event,
    case when v_before.user_id is null then null else to_jsonb(v_before) end,
    to_jsonb(v_after));
  return jsonb_build_object('user_id',v_after.user_id,'role',v_after.role,
    'module_perms',v_after.module_perms,'active',v_after.active,
    'updated_at',v_after.updated_at);
end
$_$;

--
-- Name: platform_upsert_billing_contact_v156(jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_upsert_billing_contact_v156(p_contact jsonb, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'extensions', 'pg_temp'
    AS $_$
declare v_actor uuid:=auth.uid();v_business uuid:=nullif(p_contact->>'business_id','')::uuid;v_prospect uuid:=nullif(p_contact->>'prospect_id','')::uuid;v_id uuid:=coalesce(nullif(p_contact->>'id','')::uuid,gen_random_uuid());v_row public.platform_billing_contacts_v156%rowtype;v_hash text;v_replay jsonb;
begin
  if v_actor is null or p_idempotency_key is null or ((v_business is not null)=(v_prospect is not null)) then raise exception 'valid scoped billing contact is required' using errcode='22023';end if;
  if v_business is not null and not app.v156_can('rw') then raise exception 'billing write access is required' using errcode='42501';end if;
  if v_prospect is not null and not app.v156_can_prospect(v_prospect,'rw') then raise exception 'CRM write access is required' using errcode='42501';end if;
  if coalesce(p_contact->>'email','')!~*'^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' then raise exception 'valid billing email is required' using errcode='22023';end if;
  v_hash:=encode(extensions.digest(jsonb_build_object('contact',p_contact)::text,'sha256'),'hex');
  perform pg_advisory_xact_lock(hashtextextended('v156-contact:'||p_idempotency_key::text,156));
  v_replay:=app.v156_operation_replay(p_idempotency_key,'billing_contact',v_actor,v_hash);if v_replay is not null then return v_replay;end if;
  if p_contact?'id' and exists(select 1 from public.platform_billing_contacts_v156 c where c.id=v_id and (c.business_id is distinct from v_business or c.prospect_id is distinct from v_prospect)) then
    raise exception 'billing contact scope does not match' using errcode='42501';
  end if;
  if p_contact->>'recipient_role'='primary' then update public.platform_billing_contacts_v156 set active=false,updated_by=v_actor,updated_at=clock_timestamp() where active and recipient_role='primary' and id<>v_id and (business_id=v_business or prospect_id=v_prospect);end if;
  insert into public.platform_billing_contacts_v156(id,business_id,prospect_id,business_display_name,legal_entity_name,
    registration_number,billing_address,country,contact_name,email,telephone,recipient_role,purchase_order_number,
    customer_reference,active,created_by,updated_by)
  values(v_id,v_business,v_prospect,btrim(p_contact->>'business_display_name'),btrim(p_contact->>'legal_entity_name'),
    nullif(btrim(p_contact->>'registration_number'),''),coalesce(p_contact->'billing_address','{}'::jsonb),
    coalesce(nullif(btrim(p_contact->>'country'),''),'Singapore'),btrim(p_contact->>'contact_name'),
    lower(btrim(p_contact->>'email')),nullif(btrim(p_contact->>'telephone'),''),p_contact->>'recipient_role',
    nullif(btrim(p_contact->>'purchase_order_number'),''),nullif(btrim(p_contact->>'customer_reference'),''),
    coalesce((p_contact->>'active')::boolean,true),v_actor,v_actor)
  on conflict(id) do update set business_display_name=excluded.business_display_name,legal_entity_name=excluded.legal_entity_name,
    registration_number=excluded.registration_number,billing_address=excluded.billing_address,country=excluded.country,
    contact_name=excluded.contact_name,email=excluded.email,telephone=excluded.telephone,recipient_role=excluded.recipient_role,
    purchase_order_number=excluded.purchase_order_number,customer_reference=excluded.customer_reference,active=excluded.active,
    updated_by=v_actor,updated_at=clock_timestamp() returning * into v_row;
  insert into public.platform_subscription_dispatch_audit_v156(action,entity_type,entity_id,detail,actor)
  values('billing_contact_saved','billing_contact',v_row.id,jsonb_build_object('business_id',v_business,'prospect_id',v_prospect,'recipient_role',v_row.recipient_role),v_actor);
  return app.v156_store_operation(p_idempotency_key,'billing_contact',v_actor,v_hash,jsonb_build_object('contact',to_jsonb(v_row)));
end $_$;

--
-- Name: platform_upsert_commission_consultant_v89(uuid, uuid, text, text, date, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_upsert_commission_consultant_v89(p_consultant uuid, p_user uuid, p_display_name text, p_tier text, p_employment_started_on date, p_active boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_actor uuid:=auth.uid();v_row public.platform_consultants%rowtype;
  v_name text:=nullif(btrim(p_display_name),'');
begin
  if not app.v89_platform_can('commissions','rw') then
    raise exception 'platform commissions write access is required'
      using errcode='42501';
  end if;
  if p_user is null or length(coalesce(v_name,'')) not between 2 and 120
     or p_tier not in ('senior','junior')
     or p_employment_started_on is null then
    raise exception 'valid consultant details are required' using errcode='22023';
  end if;
  if p_consultant is null then
    insert into public.platform_consultants(
      user_id,display_name,tier,employment_started_on,active,departed_at,created_by
    ) values(
      p_user,v_name,p_tier,p_employment_started_on,coalesce(p_active,true),
      case when p_active is false then now() end,v_actor
    ) returning * into v_row;
  else
    if p_active is false then
      perform app.forfeit_consultant_core_v78(
        p_consultant,now(),
        'directory deactivation via v89 commissions RPC',v_actor
      );
    end if;
    update public.platform_consultants set
      user_id=p_user,display_name=v_name,tier=p_tier,
      employment_started_on=p_employment_started_on,
      active=coalesce(p_active,active),
      departed_at=case
        when p_active is true then null
        when p_active is false then coalesce(departed_at,now())
        else departed_at end,
      updated_at=now()
    where id=p_consultant returning * into v_row;
    if not found then
      raise exception 'platform consultant was not found' using errcode='22023';
    end if;
  end if;
  insert into public.audit_log(
    business_id,actor,action,entity,entity_id,detail
  ) values(
    null,v_actor,'PLATFORM_CONSULTANT_UPSERT_V89','platform_consultants',
    v_row.id,to_jsonb(v_row)-'user_id'
  );
  return jsonb_build_object('consultant',to_jsonb(v_row));
end
$$;

--
-- Name: platform_upsert_consultant_v75(uuid, uuid, text, text, date, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_upsert_consultant_v75(p_consultant uuid, p_user uuid, p_display_name text, p_tier text, p_employment_started_on date, p_active boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid:=auth.uid();
  v_row public.platform_consultants%rowtype;
begin
  if v_actor is null or not app.is_super_admin() then
    raise exception 'super admin access is required' using errcode='42501';
  end if;
  if p_consultant is null then
    insert into public.platform_consultants(
      user_id,display_name,tier,employment_started_on,active,departed_at,created_by
    ) values (
      p_user,btrim(p_display_name),p_tier,p_employment_started_on,
      coalesce(p_active,true),
      case when p_active is false then now() end,v_actor
    ) returning * into v_row;
  else
    if p_active is false then
      perform app.forfeit_consultant_core_v78(
        p_consultant,now(),'directory deactivation via v75 compatibility RPC',v_actor
      );
    end if;
    update public.platform_consultants
       set user_id=p_user,display_name=btrim(p_display_name),tier=p_tier,
           employment_started_on=p_employment_started_on,
           active=coalesce(p_active,active),
           departed_at=case
             when p_active is true then null
             when p_active is false then coalesce(departed_at,now())
             else departed_at
           end,
           updated_at=now()
     where id=p_consultant returning * into v_row;
    if not found then
      raise exception 'platform consultant was not found' using errcode='22023';
    end if;
  end if;
  insert into public.audit_log(
    business_id,actor,action,entity,entity_id,detail
  ) values (
    null,v_actor,'PLATFORM_CONSULTANT_UPSERT_V75','platform_consultants',
    v_row.id,to_jsonb(v_row)-'user_id'
  );
  return jsonb_build_object('consultant',to_jsonb(v_row));
end
$$;

--
-- Name: platform_upsert_prospect_contact_v86(uuid, uuid, jsonb, jsonb, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_upsert_prospect_contact_v86(p_prospect uuid, p_contact uuid, p_base jsonb, p_profile jsonb, p_expected_version bigint, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid:=auth.uid();v_hash text;v_replay jsonb;v_contact public.sme_prospect_contacts%rowtype;
  v_prospect public.sme_prospects%rowtype;v_profile jsonb;v_response jsonb;
begin
  if not app.is_platform_operator_v75() then raise exception 'platform operator access is required' using errcode='42501';end if;
  perform app.require_idempotency_key_v79(p_idempotency_key);
  perform app.v86_assert_object_keys(p_base,array[
    'full_name','title','email','phone','is_primary','active'
  ],'contact base');
  if length(btrim(coalesce(p_base->>'full_name','')))<2
    or (nullif(btrim(p_base->>'email'),'') is null and nullif(btrim(p_base->>'phone'),'') is null) then
    raise exception 'contact name and email or phone are required' using errcode='22023';end if;
  v_hash:=app.v76_sha256_hex(jsonb_build_object(
    'prospect',p_prospect,'contact',p_contact,'base',p_base,'profile',p_profile,
    'expected_version',p_expected_version
  )::text);
  v_replay:=app.v76_replay(v_actor,'upsert_contact_v86',p_idempotency_key,v_hash);
  if v_replay is not null then return v_replay;end if;
  update public.sme_prospects set version=version+1,updated_by=v_actor,updated_at=now()
   where id=p_prospect and version=p_expected_version returning * into v_prospect;
  if not found then raise exception 'prospect version conflict' using errcode='40001';end if;
  if coalesce((p_base->>'is_primary')::boolean,false) then
    update public.sme_prospect_contacts set is_primary=false,updated_at=now()
      where prospect_id=p_prospect and is_primary and (p_contact is null or id<>p_contact);
  end if;
  if p_contact is null then
    insert into public.sme_prospect_contacts(
      prospect_id,full_name,title,email,phone,is_primary,active
    ) values(
      p_prospect,btrim(p_base->>'full_name'),nullif(btrim(p_base->>'title'),''),
      nullif(lower(btrim(p_base->>'email')),''),nullif(btrim(p_base->>'phone'),''),
      coalesce((p_base->>'is_primary')::boolean,false),
      coalesce((p_base->>'active')::boolean,true)
    ) returning * into v_contact;
  else
    update public.sme_prospect_contacts set
      full_name=btrim(p_base->>'full_name'),title=nullif(btrim(p_base->>'title'),''),
      email=nullif(lower(btrim(p_base->>'email')),''),phone=nullif(btrim(p_base->>'phone'),''),
      is_primary=coalesce((p_base->>'is_primary')::boolean,is_primary),
      active=coalesce((p_base->>'active')::boolean,active),updated_at=now()
     where id=p_contact and prospect_id=p_prospect returning * into v_contact;
    if not found then raise exception 'prospect contact was not found' using errcode='22023';end if;
  end if;
  if p_profile is not null then
    v_profile:=public.platform_record_contact_profile_v86(v_contact.id,p_profile)->'profile';
  end if;
  insert into public.audit_log(business_id,actor,action,entity,entity_id,detail)
  values(null,v_actor,'SME_PROSPECT_CONTACT_UPSERTED_V86','sme_prospect_contacts',v_contact.id,
    jsonb_build_object('prospect_id',p_prospect,'new_prospect_version',v_prospect.version,
      'created',p_contact is null,'profile_recorded',v_profile is not null));
  v_response:=jsonb_build_object('replayed',false,'contact',to_jsonb(v_contact),
    'profile',v_profile,'prospect_version',v_prospect.version);
  perform app.v76_store_receipt(v_actor,'upsert_contact_v86',p_idempotency_key,v_hash,v_response);
  return v_response;
end
$$;

--
-- Name: platform_verify_manual_payment_v156(uuid, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_verify_manual_payment_v156(p_payment uuid, p_decision text, p_reason text, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'extensions', 'pg_temp'
    AS $$
declare v_actor uuid:=auth.uid();v_payment public.platform_manual_payments_v156%rowtype;v_invoice public.platform_subscription_documents_v156%rowtype;v_profile public.platform_billing_profiles_v156%rowtype;v_receipt public.platform_subscription_documents_v156%rowtype;v_customer jsonb;v_snapshot jsonb;v_number text;v_key uuid;v_hash text;v_to text[];v_cc text[];
begin
  if v_actor is null or not app.is_super_admin() then raise exception 'super admin verification is required' using errcode='42501';end if;
  if p_decision not in ('verified','rejected') then raise exception 'manual payment decision is invalid' using errcode='22023';end if;
  select * into v_payment from public.platform_manual_payments_v156 where id=p_payment for update;if not found then raise exception 'manual payment was not found' using errcode='22023';end if;
  if v_payment.status<>'pending_verification' then return jsonb_build_object('payment',to_jsonb(v_payment),'replayed',true);end if;
  if v_payment.recorded_by=v_actor then raise exception 'a second authorised admin must verify manual payment' using errcode='42501';end if;
  update public.platform_manual_payments_v156 set status=p_decision,verified_by=v_actor,verified_at=clock_timestamp(),rejection_reason=case when p_decision='rejected' then nullif(btrim(p_reason),'') end where id=p_payment returning * into v_payment;
  insert into public.platform_subscription_dispatch_audit_v156(action,entity_type,entity_id,detail,actor) values('manual_payment_'||p_decision,'manual_payment',p_payment,jsonb_build_object('reason',nullif(btrim(p_reason),''),'operation_key',p_idempotency_key),v_actor);
  if p_decision='rejected' then return jsonb_build_object('payment',to_jsonb(v_payment),'replayed',false);end if;
  select * into v_invoice from public.platform_subscription_documents_v156 where id=v_payment.invoice_document_id;select * into v_profile from public.platform_billing_profiles_v156 where id=v_invoice.seller_profile_id;v_customer:=v_invoice.snapshot->'customer';
  v_key:=(md5('v156-manual-receipt:'||p_payment))::uuid;select * into v_receipt from public.platform_subscription_documents_v156 where operation_key=v_key;
  if not found then
    v_number:=app.v156_next_document_number('receipt',v_payment.value_date);v_snapshot:=jsonb_build_object('document_type','receipt','number',v_number,'related_invoice_number',v_invoice.document_number,'issue_date',v_payment.value_date,'payment_date',v_payment.value_date,'seller',app.v156_seller_snapshot(v_profile),'customer',v_customer,'service_period_start',v_invoice.service_period_start,'service_period_end',v_invoice.service_period_end,'currency',v_payment.currency,'total_cents',v_payment.amount_cents,'amount_paid_cents',v_payment.amount_cents,'balance_due_cents',0,'payment_method','bank_transfer','payment_method_label','Payment received via bank transfer','payment_reference',v_payment.payment_reference);
    v_hash:=encode(extensions.digest(v_snapshot::text,'sha256'),'hex');
    insert into public.platform_subscription_documents_v156(document_type,document_number,business_id,prospect_id,seller_profile_id,original_document_id,issue_date,service_period_start,service_period_end,currency,subtotal_cents,total_cents,amount_paid_cents,balance_due_cents,snapshot,snapshot_sha256,finalized_at,operation_key,request_hash,created_by)
    values('receipt',v_number,v_invoice.business_id,v_invoice.prospect_id,v_invoice.seller_profile_id,v_invoice.id,v_payment.value_date,v_invoice.service_period_start,v_invoice.service_period_end,v_payment.currency,v_payment.amount_cents,v_payment.amount_cents,v_payment.amount_cents,0,v_snapshot,v_hash,clock_timestamp(),v_key,v_hash,v_actor) returning * into v_receipt;
    insert into public.platform_subscription_document_events_v156(document_id,status,source_type,source_id,actor) values(v_receipt.id,'issued','admin',p_payment::text,v_actor);
    insert into public.platform_subscription_document_events_v156(document_id,status,source_type,source_id,actor) values(v_invoice.id,'paid','admin',p_payment::text,v_actor);
    select array_agg(email order by email) filter(where recipient_role='primary'),array_agg(email order by recipient_role,email) filter(where recipient_role<>'primary') into v_to,v_cc from public.platform_billing_contacts_v156 where active and business_id=v_invoice.business_id;
    if v_profile.internal_copy_email is not null then select array_agg(distinct address) into v_cc from unnest(coalesce(v_cc,'{}'::text[])||array[v_profile.internal_copy_email]) address where not(address=any(v_to));end if;
    insert into public.platform_subscription_deliveries_v156(delivery_key,business_id,delivery_type,document_ids,recipients,cc_recipients,subject)
    values('manual-receipt:'||p_payment,v_invoice.business_id,'manual_receipt',array[v_invoice.id,v_receipt.id],v_to,coalesce(v_cc,'{}'),'Payment received – Peekaa subscription for '||(v_customer->>'business_display_name')) on conflict(delivery_key) do nothing;
    insert into public.platform_subscription_lifecycle_events_v156(business_id,lifecycle_status,snapshot,source_type,source_id)
    values(v_invoice.business_id,'payment_received',jsonb_build_object('manual_payment_id',p_payment,'paid_through',v_invoice.service_period_end,'entitlement_status','manual_policy_review_required'),'manual_payment',p_payment::text) on conflict do nothing;
    perform app.v156_upsert_task('onboarding:manual:'||p_payment,'onboarding',v_invoice.business_id,v_invoice.prospect_id,null,null,'high',clock_timestamp()+interval '1 day','Review manual-payment entitlement and schedule onboarding',null);
  end if;
  return jsonb_build_object('payment',to_jsonb(v_payment),'receipt',to_jsonb(v_receipt),'replayed',false);
end $$;

--
-- Name: platform_void_document_v156(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_void_document_v156(p_document uuid, p_reason text, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_actor uuid:=auth.uid();v_doc public.platform_subscription_documents_v156%rowtype;v_existing text;
begin
  if v_actor is null or not app.v156_can('rw') then raise exception 'billing write access is required' using errcode='42501';end if;
  if length(btrim(coalesce(p_reason,'')))<3 then raise exception 'void reason is required' using errcode='22023';end if;
  select * into v_doc from public.platform_subscription_documents_v156 where id=p_document for update;if not found then raise exception 'document was not found' using errcode='22023';end if;
  if v_doc.document_type not in ('quotation','invoice') or (v_doc.document_type='invoice' and v_doc.provider_invoice_id is not null) then raise exception 'Stripe invoices must be voided through Stripe' using errcode='42501';end if;
  select status into v_existing from public.platform_subscription_document_events_v156 where document_id=p_document order by occurred_at desc,id desc limit 1;
  if v_existing in ('paid','void','refunded','partially_refunded') then raise exception 'document cannot be voided in its current state' using errcode='22023';end if;
  insert into public.platform_subscription_document_events_v156(document_id,status,source_type,source_id,actor)
  values(p_document,case when v_doc.document_type='quotation' then 'superseded' else 'void' end,'admin',p_idempotency_key::text,v_actor) on conflict do nothing;
  insert into public.platform_subscription_dispatch_audit_v156(action,entity_type,entity_id,detail,actor) values('document_voided','document',p_document,jsonb_build_object('reason',btrim(p_reason),'document_number',v_doc.document_number),v_actor);
  return jsonb_build_object('document_id',p_document,'document_number',v_doc.document_number,'status',case when v_doc.document_type='quotation' then 'superseded' else 'void' end);
end $$;

--
-- Name: platform_workspace_mirror_v177(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_workspace_mirror_v177(p_business uuid, p_branch uuid DEFAULT NULL::uuid, p_section text DEFAULT 'overview'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_section text := lower(btrim(coalesce(p_section, 'overview')));
  v_business public.businesses%rowtype;
  v_branch_name text;
  v_branches jsonb;
  v_workspace jsonb;
  v_data jsonb;
begin
  if p_business is null then
    raise exception 'business_required' using errcode = '22023';
  end if;
  if v_section not in ('overview','appointments','customers','programmes','staff') then
    raise exception 'unknown_section' using errcode = '22023';
  end if;
  if not app.v177_can_view_workspace(p_business) then
    raise exception 'workspace_mirror_not_permitted' using errcode = '42501';
  end if;

  select * into v_business from public.businesses where id = p_business;
  if not found then
    raise exception 'business_not_found' using errcode = '22023';
  end if;

  if p_branch is not null then
    select branch.name into v_branch_name
    from public.branches branch
    where branch.id = p_branch and branch.business_id = p_business;
    if v_branch_name is null then
      raise exception 'branch_not_in_business' using errcode = '22023';
    end if;
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
    'id', branch.id,
    'name', branch.name,
    'is_default', branch.is_default,
    'active', branch.active
  ) order by branch.is_default desc, branch.name asc, branch.id asc), '[]'::jsonb)
  into v_branches
  from public.branches branch
  where branch.business_id = p_business;

  select jsonb_build_object(
    'approval_status', coalesce(control.approval_status, 'pending'),
    'decided_at', control.decided_at,
    'lifecycle_state', coalesce(lifecycle.state, 'current'),
    'workspace_paused', coalesce(lifecycle.workspace_paused, false),
    'overdue_day', lifecycle.overdue_day,
    'paused_at', lifecycle.paused_at
  ) into v_workspace
  from (select 1) anchor
  left join public.business_workspace_controls_v94 control
    on control.business_id = p_business
  left join public.business_subscription_lifecycle_v94 lifecycle
    on lifecycle.business_id = p_business;

  if v_section = 'overview' then
    v_data := app.v177_overview(p_business, p_branch);
  elsif v_section = 'appointments' then
    v_data := app.v177_appointments(p_business, p_branch);
  elsif v_section = 'customers' then
    v_data := app.v177_customers(p_business);
  elsif v_section = 'programmes' then
    v_data := app.v177_programmes(p_business);
  else
    v_data := app.v177_staff(p_business, p_branch);
  end if;

  -- Every open of the mirror is on the record. One row per call is acceptable
  -- at this scale and keeps "who looked at this firm, and when" answerable.
  insert into public.audit_log(business_id, actor, action, entity, entity_id, detail)
  values(
    p_business, auth.uid(), 'WORKSPACE_MIRROR_VIEWED_V177', 'businesses', p_business,
    jsonb_build_object('section', v_section, 'branch', p_branch)
  );

  return jsonb_build_object(
    'contract_version', 'v177',
    'read_only', true,
    'generated_at', now(),
    'section', v_section,
    'business_id', v_business.id,
    'business_name', v_business.name,
    'industry', v_business.industry,
    'currency', coalesce(v_business.currency, 'SGD'),
    'is_demo', coalesce(v_business.is_demo, false),
    'workspace', v_workspace,
    'branches', v_branches,
    'branch_id', p_branch,
    'branch_name', v_branch_name,
    'data', v_data
  );
end
$$;

--
-- Name: FUNCTION platform_workspace_mirror_v177(p_business uuid, p_branch uuid, p_section text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.platform_workspace_mirror_v177(p_business uuid, p_branch uuid, p_section text) IS 'Read-only "view as firm" mirror for the platform console. Super admin or the assigned consultant only (42501 otherwise). Returns one section snapshot per call with read_only=true, never a write path and never customer contact details. Every call writes one WORKSPACE_MIRROR_VIEWED_V177 audit row.';

--
-- Name: preview_billing_plan_catalog_v124(text, text, text, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.preview_billing_plan_catalog_v124(p_cadence text, p_provider_base_price_id text, p_provider_capacity_price_id text, p_tax_behavior text, p_effective_from timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $_$
declare
  v_actor uuid:=auth.uid();
  v_base integer;
  v_addon integer;
  v_hash text;
begin
  if v_actor is null or not app.is_super_admin() then
    raise exception 'super-admin access is required' using errcode='42501';
  end if;
  if p_cadence not in ('monthly','annual')
     or p_provider_base_price_id !~ '^price_[A-Za-z0-9_]+$'
     or p_provider_capacity_price_id !~ '^price_[A-Za-z0-9_]+$'
     or p_provider_base_price_id=p_provider_capacity_price_id
     or p_tax_behavior not in ('inclusive','exclusive','unspecified')
     or p_effective_from is null then
    raise exception 'invalid V124 Stripe price proposal' using errcode='22023';
  end if;
  v_base:=case p_cadence when 'monthly' then 14800 else 118800 end;
  v_addon:=case p_cadence when 'monthly' then 1000 else 12000 end;
  v_hash:=encode(extensions.digest(convert_to(
    'SGD'||E'\n'||p_cadence||E'\n'||p_provider_base_price_id||E'\n'
    ||p_provider_capacity_price_id||E'\n'||v_base::text||E'\n'||v_addon::text
    ||E'\n1000\n1000\n16800\n'||p_tax_behavior||E'\n'||p_effective_from::text,
    'utf8'),'sha256'),'hex');
  return jsonb_build_object(
    'currency','SGD','cadence',p_cadence,
    'base_amount_cents',v_base,'capacity_block_amount_cents',v_addon,
    'included_customer_capacity',1000,'capacity_block_size',1000,
    'compare_at_monthly_cents',16800,'tax_behavior',p_tax_behavior,
    'effective_from',p_effective_from,'confirmation_hash',v_hash
  );
end
$_$;

--
-- Name: preview_billing_plan_catalog_v125(text, text, text, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.preview_billing_plan_catalog_v125(p_cadence text, p_provider_base_price_id text, p_provider_capacity_price_id text, p_tax_behavior text, p_effective_from timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if p_tax_behavior is distinct from 'exclusive' then
    raise exception 'NESTLY TECHNOLOGIES PTE. LTD. is not GST-registered; Stripe prices must use exclusive tax behavior'
      using errcode='22023';
  end if;
  return public.preview_billing_plan_catalog_v124(
    p_cadence,p_provider_base_price_id,p_provider_capacity_price_id,
    'exclusive',p_effective_from
  ) || jsonb_build_object(
    'gst_registered',false,
    'tax_collection_enabled',false,
    'tax_label','GST not charged',
    'tax_cents',0
  );
end
$$;

--
-- Name: preview_billing_price_catalog_v77(text, text, text, text, integer, integer, integer, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.preview_billing_price_catalog_v77(p_currency text, p_cadence text, p_provider_base_price_id text, p_provider_seat_price_id text, p_base_amount_cents integer, p_per_seat_amount_cents integer, p_included_seats integer, p_tax_behavior text, p_effective_from timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $_$
declare
  v_months smallint;
  v_current jsonb;
  v_hash text;
begin
  if auth.uid() is null or not app.is_super_admin() then
    raise exception 'super-admin access is required' using errcode='42501';
  end if;
  v_months := case p_cadence
    when 'quarterly' then 3 when 'half_yearly' then 6 when 'annual' then 12
  end;
  if p_currency !~ '^[A-Z]{3}$' or v_months is null
     or p_provider_base_price_id !~ '^price_[A-Za-z0-9_]+$'
     or p_provider_seat_price_id !~ '^price_[A-Za-z0-9_]+$'
     or p_provider_base_price_id=p_provider_seat_price_id
     or p_base_amount_cents < 0 or p_per_seat_amount_cents < 0
     or p_included_seats < 0
     or p_tax_behavior not in ('inclusive','exclusive','unspecified')
     or p_effective_from is null then
    raise exception 'invalid Stripe price catalog proposal' using errcode='22023';
  end if;
  select to_jsonb(catalog) into v_current
    from public.billing_price_catalog catalog
   where currency=p_currency and cadence=p_cadence
     and active and effective_to is null
   order by effective_from desc limit 1;
  v_hash := app.billing_price_confirmation_v77(
    p_currency,p_cadence,p_provider_base_price_id,p_provider_seat_price_id,
    p_base_amount_cents,p_per_seat_amount_cents,p_included_seats,
    p_tax_behavior,p_effective_from
  );
  return jsonb_build_object(
    'proposal',jsonb_build_object(
      'currency',p_currency,'cadence',p_cadence,'cadence_months',v_months,
      'provider_base_price_id',p_provider_base_price_id,
      'provider_seat_price_id',p_provider_seat_price_id,
      'base_amount_cents',p_base_amount_cents,
      'per_seat_amount_cents',p_per_seat_amount_cents,
      'included_seats',p_included_seats,'tax_behavior',p_tax_behavior,
      'effective_from',p_effective_from
    ),
    'current',v_current,'confirmation_hash',v_hash
  );
end
$_$;

--
-- Name: FUNCTION preview_billing_price_catalog_v77(p_currency text, p_cadence text, p_provider_base_price_id text, p_provider_seat_price_id text, p_base_amount_cents integer, p_per_seat_amount_cents integer, p_included_seats integer, p_tax_behavior text, p_effective_from timestamp with time zone); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.preview_billing_price_catalog_v77(p_currency text, p_cadence text, p_provider_base_price_id text, p_provider_seat_price_id text, p_base_amount_cents integer, p_per_seat_amount_cents integer, p_included_seats integer, p_tax_behavior text, p_effective_from timestamp with time zone) IS 'SA preview for a versioned Stripe price activation. Confirmation hashes bind all cents, tax and cadence fields.';

--
-- Name: preview_campaign_audience_v155(uuid, text, text, uuid[], uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.preview_campaign_audience_v155(p_business uuid, p_audience_key text, p_scope_mode text DEFAULT 'all'::text, p_branch_ids uuid[] DEFAULT ARRAY[]::uuid[], p_operational_branch uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_scope_ids uuid[];
  v_label text;
  v_scope_is_whole_business boolean := false;
  v_buckets text[] := case
    when p_audience_key in ('inactive_30_59','30_59') then array['30_59']
    when p_audience_key in ('inactive_60_89','60_89') then array['60_89']
    when p_audience_key in ('inactive_90_plus','90_plus') then array['90_plus']
    when p_audience_key in ('inactive_60_plus') then array['60_89','90_plus']
    when p_audience_key in ('never','never_visited') then array['never']
    else null
  end;
  v_total integer;
  v_consent integer;
begin
  if v_buckets is null then
    raise exception 'unsupported_campaign_audience' using errcode='22023';
  end if;
  select coalesce(array_agg(scope.branch_id order by scope.branch_name),array[]::uuid[])
    into v_scope_ids
  from app.resolve_reporting_branch_scope_v155(
    p_business,p_scope_mode,p_branch_ids,p_operational_branch
  ) scope;
  v_label := app.reporting_scope_label_v155(
    p_business,p_scope_mode,p_branch_ids,p_operational_branch
  );
  select not exists(
    select 1
    from public.branches branch
    where branch.business_id = p_business
      and coalesce(branch.active,true)
      and not (branch.id = any(v_scope_ids))
  ) into v_scope_is_whole_business;

  with visit_facts as materialized (
    select sale.client_id,max(sale.occurred_at) as last_visit_at
    from public.sales sale
    where sale.business_id = p_business
      and sale.client_id is not null
      and sale.counts_as_visit
      and sale.reversal_of is null
      and sale.occurred_at <= statement_timestamp()
      and sale.branch_id = any(v_scope_ids)
      and not exists(
        select 1 from public.sales reversal
        where reversal.business_id = sale.business_id
          and reversal.reversal_of = sale.id
          and reversal.created_at <= statement_timestamp()
      )
    group by sale.client_id
  ), customer_scope as materialized (
    select distinct sale.client_id
    from public.sales sale
    where sale.business_id = p_business
      and sale.client_id is not null
      and sale.counts_as_visit
      and sale.reversal_of is null
      and sale.branch_id = any(v_scope_ids)
  ), customer_rows as materialized (
    select customer.id,customer.marketing_consent,visit.last_visit_at,
      case when visit.last_visit_at is null then 'never'
        when ((statement_timestamp() at time zone 'Asia/Singapore')::date-
          (visit.last_visit_at at time zone 'Asia/Singapore')::date) between 30 and 59 then '30_59'
        when ((statement_timestamp() at time zone 'Asia/Singapore')::date-
          (visit.last_visit_at at time zone 'Asia/Singapore')::date) between 60 and 89 then '60_89'
        when ((statement_timestamp() at time zone 'Asia/Singapore')::date-
          (visit.last_visit_at at time zone 'Asia/Singapore')::date) >= 90 then '90_plus'
        else null
      end as bucket
    from public.clients customer
    left join visit_facts visit on visit.client_id = customer.id
    where customer.business_id = p_business
      and (
        v_scope_is_whole_business
        or exists(select 1 from customer_scope scoped where scoped.client_id = customer.id)
      )
  ), eligible_rows as (
    select *
    from customer_rows customer
    where customer.bucket = any(v_buckets)
      and (customer.bucket <> 'never' or v_scope_is_whole_business)
  )
  select count(*)::integer,
         count(*) filter (where marketing_consent is true)::integer
    into v_total,v_consent
  from eligible_rows;

  return jsonb_build_object(
    'status','ok',
    'audience_key',p_audience_key,
    'scope',jsonb_build_object(
      'mode',p_scope_mode,
      'label',v_label,
      'branch_ids',to_jsonb(v_scope_ids),
      'wording',case when v_scope_is_whole_business
        then 'Business-wide audience'
        else 'Inactive in this branch scope'
      end
    ),
    'matching_customers',v_total,
    'unique_customers_after_deduplication',v_total,
    'eligible_notification_recipients',null,
    'consent_recorded',v_consent,
    'missing_or_unknown_consent',greatest(v_total-v_consent,0),
    'delivery_enabled',false,
    'message','Campaign delivery is not enabled yet. This preview is preparation-only.'
  );
end
$$;

--
-- Name: preview_growth_recommendation_v108(uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.preview_growth_recommendation_v108(p_business uuid, p_recommendation uuid, p_limit integer DEFAULT 100) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_row public.growth_recommendations_v108%rowtype;
begin
  if auth.uid() is null or (
     not app.is_super_admin()
     and (
       not app.has_perm(p_business, 'view_finance')
       or not app.can_module_read(p_business, 'retention')
     )
  ) then
    raise exception 'finance and retention access required' using errcode = '42501';
  end if;
  if coalesce(p_limit, 0) not between 1 and 200 then
    raise exception 'preview limit must be 1..200' using errcode = '22023';
  end if;
  select * into v_row from public.growth_recommendations_v108
  where id = p_recommendation and business_id = p_business;
  if not found then raise exception 'recommendation not found'; end if;
  if not app.can_see_branch(v_row.business_id, v_row.branch_id) then
    raise exception 'recommendation branch is outside actor scope' using errcode = '42501';
  end if;
  return jsonb_build_object(
    'recommendation_id', v_row.id,
    'status', v_row.status,
    'eligible_count', v_row.audience_size,
    'excluded_count', v_row.excluded_size,
    'eligible', coalesce((
      select jsonb_agg(jsonb_build_object(
        'client_id', m.client_id, 'evidence', m.evidence
      ) order by m.historical_revenue_cents desc, m.client_id)
      from (
        select * from public.growth_recommendation_members_v108
        where recommendation_id = p_recommendation and eligible
        order by historical_revenue_cents desc, client_id limit p_limit
      ) m
    ), '[]'::jsonb),
    'excluded_by_reason', coalesce((
      select jsonb_object_agg(reason, count_rows)
      from (
        select exclusion_reason as reason, count(*) as count_rows
        from public.growth_recommendation_members_v108
        where recommendation_id = p_recommendation and not eligible
        group by exclusion_reason
      ) excluded
    ), '{}'::jsonb)
  );
end $$;

--
-- Name: preview_publish_impact(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.preview_publish_impact(p_config_version_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_header public.firm_config_versions%rowtype; r public.program_rules%rowtype;
  v_eff jsonb; v_effs jsonb; v_idx int; v_family text; v_state text; v_fin boolean; v_cf boolean;
  v_rules jsonb := '[]'::jsonb; v_any_live_fin boolean := false; v_any_live_cf boolean := false;
begin
  select * into v_header from public.firm_config_versions where id = p_config_version_id;
  if not found or not app.is_salon_owner(v_header.business_id) then
    raise exception 'owner only' using errcode = '42501';
  end if;
  for r in select * from public.program_rules
            where config_version_id = p_config_version_id and business_id = v_header.business_id
            order by sort, rule_id loop
    v_effs := '[]'::jsonb; v_idx := 0;
    for v_eff in select * from jsonb_array_elements(coalesce(r.then_effects, '[]'::jsonb)) loop
      v_family := app.ps1c2_effect_family(v_eff->>'effect_type');
      v_state := app.ps1c2_effect_state(v_header.business_id, v_eff->>'effect_type');
      v_fin := (v_family = 'checkout') or (v_family = 'points_loyalty')
               or (v_family = 'recurring' and v_eff->>'effect_type' = 'grant_free_item');
      v_cf := v_family in ('comms', 'checkout', 'recurring', 'points_loyalty');
      -- Only an ACTIVE rule can actually activate value on publish.
      if r.active and v_state = 'live' and v_fin then v_any_live_fin := true; end if;
      if r.active and v_state = 'live' and v_cf  then v_any_live_cf  := true; end if;
      v_effs := v_effs || jsonb_build_array(jsonb_build_object(
        'effect_index', v_idx, 'effect_type', v_eff->>'effect_type', 'family', v_family,
        'state_after_publish', v_state, 'financial', v_fin, 'customer_facing', v_cf));
      v_idx := v_idx + 1;
    end loop;
    v_rules := v_rules || jsonb_build_array(jsonb_build_object(
      'rule_id', r.rule_id, 'name', r.name, 'active', r.active,
      'aggregate_state_after_publish', app.ps1c2_rule_state(v_header.business_id, r.id, 'published', r.active),
      'effects', v_effs));
  end loop;
  return jsonb_build_object(
    'config_version_id', p_config_version_id,
    'business_id', v_header.business_id,
    'status', v_header.status,
    'rules', v_rules,
    'will_activate_live_financial', v_any_live_fin,
    'will_activate_customer_facing', v_any_live_cf,
    'requires_confirmation', v_any_live_fin or v_any_live_cf);
end $$;

--
-- Name: preview_staff_invite(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.preview_staff_invite(p_code text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
declare
  v_code text;
  inv public.staff_invites%rowtype;
  biz record;
  v_status text;
begin
  v_code := upper(regexp_replace(btrim(coalesce(p_code, '')), '[\s-]+', '', 'g'));
  if v_code !~ '^[A-Z0-9]{4,32}$' then
    return jsonb_build_object('status', 'invalid');
  end if;

  select * into inv
  from public.staff_invites
  where code = v_code;

  if not found then
    return jsonb_build_object('status', 'invalid');
  end if;

  select name, slug, industry into biz
  from public.businesses
  where id = inv.business_id;

  if not found then
    return jsonb_build_object('status', 'business_unavailable');
  end if;

  v_status := case
    when inv.status = 'accepted' then 'already_used'
    when inv.status = 'revoked' then 'revoked'
    when inv.status = 'expired' or inv.expires_at <= now() then 'expired'
    when inv.status = 'pending' then 'valid'
    else 'invalid'
  end;

  return jsonb_build_object(
    'status', v_status,
    'business_name', biz.name,
    'business_slug', biz.slug,
    'business_industry', biz.industry,
    'role', inv.role,
    'restricted_email', nullif(btrim(coalesce(inv.email, '')), ''),
    'expires_at', inv.expires_at
  );
end;
$_$;

--
-- Name: preview_sv_cutover(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.preview_sv_cutover(p_business uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_readiness jsonb;
begin
  if not app.is_salon_owner(p_business) then
    raise exception 'owner only' using errcode = '42501';
  end if;
  v_readiness := app.sv_cutover_readiness(p_business);
  return jsonb_build_object(
    'business_id', p_business,
    'asset', v_readiness->>'asset',
    'authority_state', v_readiness->>'authority_state',
    'reconciliation_status', v_readiness->>'reconciliation_status',
    'discrepancy_count', (v_readiness->>'discrepancy_count')::int,
    'blocking_reasons', v_readiness->'blocking_reasons',
    'blocking_codes', v_readiness->'blocking_codes',
    'automation', v_readiness->'automation',
    'designated', (v_readiness->>'designation_id') is not null,
    'evidence_hash', v_readiness->>'evidence_hash',
    'reversible', false,
    'ready', (v_readiness->>'ready')::boolean);
end $$;

--
-- Name: preview_sv_plan(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.preview_sv_plan(p_business uuid, p_draft uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_row public.sv_plan_drafts%rowtype; v_val jsonb;
begin
  if not app.is_salon_owner(p_business) then raise exception 'owner only' using errcode = '42501'; end if;
  select * into v_row from public.sv_plan_drafts where id = p_draft and business_id = p_business;
  if not found then raise exception 'stored-value plan draft not found in this business' using errcode = '22023'; end if;
  v_val := app.sv_plan_validate(p_business, p_draft);
  return jsonb_build_object(
    'draft_id', v_row.id, 'customer_facing_name', v_row.customer_facing_name,
    'price_cents', v_row.price_cents, 'bonus_cents', v_row.bonus_cents,
    'total_usable_cents', v_row.price_cents + v_row.bonus_cents,
    'effective_discount_bps', v_val->'effective_discount_bps',
    'warn_threshold_bps', v_val->'warn_threshold_bps', 'hard_threshold_bps', v_val->'hard_threshold_bps',
    'validation_errors', v_val->'validation_errors', 'warnings', v_val->'warnings',
    'override_required', v_val->'override_required', 'publishable', v_val->'publishable');
end $$;

--
-- Name: preview_sv_topup_sale(uuid, uuid, uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.preview_sv_topup_sale(p_business uuid, p_branch uuid, p_client uuid, p_plan_version uuid, p_payment jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_proj jsonb;
begin
  if not app.can_sell_topups(p_business) then raise exception 'not permitted to sell top-ups for this business' using errcode = '42501'; end if;
  if not exists (select 1 from public.clients c where c.id = p_client and c.business_id = p_business) then
    raise exception 'customer not in this business' using errcode = '22023'; end if;
  v_proj := app.sv_topup_projection(p_business, p_branch, p_client, p_plan_version);
  return v_proj || jsonb_build_object('preview', true, 'advisory_only', true);
end $$;

--
-- Name: propose_customer_identity_correction_v111(uuid, uuid, uuid, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.propose_customer_identity_correction_v111(p_business uuid, p_branch uuid, p_source_client uuid, p_target_client uuid, p_reason text, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid:=auth.uid();
  v_payload jsonb;
  v_hash text;
  v_existing public.customer_identity_request_ledger_v111%rowtype;
  v_proposal uuid:=gen_random_uuid();
  v_target_link public.customer_links%rowtype;
  v_source_identity uuid;
  v_receipt jsonb;
begin
  if v_actor is null then raise exception 'authentication required' using errcode='42501'; end if;
  if p_idempotency_key is null then
    raise exception 'idempotency key is required' using errcode='22023';
  end if;
  if not app.v111_can_propose(p_business,p_branch) then
    raise exception 'identity proposal is outside actor business or branch scope'
      using errcode='42501';
  end if;
  p_reason:=nullif(btrim(p_reason),'');
  v_payload:=jsonb_build_object(
    'operation','propose','business_id',p_business,'branch_id',p_branch,
    'source_client_id',p_source_client,'target_client_id',p_target_client,
    'reason',p_reason
  );
  v_hash:=app.v111_request_hash(v_payload);
  perform pg_advisory_xact_lock(hashtextextended(
    'v111:request:'||v_actor||':'||p_idempotency_key,0
  ));
  select * into v_existing from public.customer_identity_request_ledger_v111
   where actor_auth_user_id=v_actor and idempotency_key=p_idempotency_key;
  if found then
    if v_existing.operation<>'propose' or v_existing.request_hash<>v_hash then
      raise exception 'idempotency key was already used for a different identity mutation'
        using errcode='23505';
    end if;
    return v_existing.receipt;
  end if;
  perform pg_advisory_xact_lock(hashtextextended(
    'v111:client:'||p_business||':'||least(p_source_client::text,p_target_client::text),0
  ));
  perform pg_advisory_xact_lock(hashtextextended(
    'v111:client:'||p_business||':'||greatest(p_source_client::text,p_target_client::text),0
  ));
  if p_source_client=p_target_client or p_reason is null
     or length(p_reason) not between 3 and 500 then
    raise exception 'distinct customers and a concise reason are required'
      using errcode='22023';
  end if;
  perform 1 from public.clients c
   where c.id=p_source_client and c.business_id=p_business;
  if not found then raise exception 'source customer is cross-business or missing' using errcode='42501'; end if;
  select * into v_target_link from public.customer_links link
   where link.business_id=p_business and link.client_id=p_target_client
     and link.state='verified'
     and exists (
       select 1
         from public.customer_identities identity_row
        where identity_row.id=link.identity_id
          and identity_row.status='active'
     );
  if not found then
    raise exception 'target customer needs one active verified business identity'
      using errcode='42501';
  end if;
  if exists (
    select 1 from public.customer_links link
     where link.business_id=p_business and link.client_id=p_source_client
       and link.state='verified'
  ) then
    raise exception 'source customer already has a verified identity; no automatic merge is allowed'
      using errcode='42501';
  end if;
  select link.identity_id into v_source_identity
    from public.customer_links link
   where link.business_id=p_business and link.client_id=p_source_client
   order by link.created_at desc limit 1;
  if exists (
    select 1 from public.customer_identity_current_attribution_v111 current
     where current.business_id=p_business
       and current.effective_client_id<>current.source_client_id
       and (
         current.source_client_id in (p_source_client,p_target_client)
         or current.effective_client_id in (p_source_client,p_target_client)
       )
  ) then
    raise exception 'source or target already participates in an active identity correction'
      using errcode='55000';
  end if;
  insert into public.customer_identity_proposals_v111(
    id,business_id,branch_id,source_client_id,target_client_id,
    source_identity_id,target_identity_id,target_link_id,reason,proposed_by
  ) values (
    v_proposal,p_business,p_branch,p_source_client,p_target_client,
    v_source_identity,v_target_link.identity_id,v_target_link.id,p_reason,v_actor
  );
  v_receipt:=jsonb_build_object(
    'status','proposed','proposal_id',v_proposal,'business_id',p_business,
    'source_client_id',p_source_client,'target_client_id',p_target_client
  );
  insert into public.customer_identity_request_ledger_v111(
    actor_auth_user_id,business_id,operation,idempotency_key,request_hash,receipt
  ) values(v_actor,p_business,'propose',p_idempotency_key,v_hash,v_receipt);
  return v_receipt;
end
$$;

--
-- Name: publish_loyalty_config(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.publish_loyalty_config(p_version uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_header public.firm_config_versions%rowtype; v_typed public.loyalty_program_versions%rowtype; v_prior uuid;
  v_rule public.program_rules%rowtype; v_rule_errs text[]; v_active_rule_count integer;
  v_tier_carry_ids uuid[]; v_tier_carry_paused boolean[]; v_tier_carry_deleted timestamptz[];
begin
  select * into v_header from public.firm_config_versions where id=p_version for update;
  if not found or not app.c45_owner_loyalty_write(v_header.business_id) then raise exception 'owner loyalty configuration access required' using errcode='42501'; end if;
  if v_header.status<>'draft' then raise exception 'only a draft may be published'; end if;
  perform 1 from public.businesses where id=v_header.business_id for update;
  select * into v_typed from public.loyalty_program_versions where config_version_id=p_version;
  if exists(select 1 from public.business_programmes spine where spine.business_id=v_header.business_id and spine.kind='stamps' and spine.active) and coalesce(v_typed.stamp_per_cents,0)<=0 then raise exception 'active stamps configuration requires spend per stamp' using errcode='23514'; end if;
  if exists(select 1 from public.business_programmes spine where spine.business_id=v_header.business_id and spine.kind='stamps' and spine.active) then
    if coalesce(v_typed.stamp_target,0)<=0 then
      raise exception 'a live stamp card needs a number of stamps' using errcode='23514';
    end if;
    if exists(select 1 from public.loyalty_reward_versions rv join public.business_programmes spine on spine.id=rv.programme_id
               where rv.config_version_id=p_version and rv.business_id=v_header.business_id and rv.active and spine.kind='stamps' and rv.cost_points>v_typed.stamp_target) then
      raise exception 'a stamp gift sits past the last stamp on the card' using errcode='23514';
    end if;
    if not exists(select 1 from public.loyalty_reward_versions rv join public.business_programmes spine on spine.id=rv.programme_id
                   where rv.config_version_id=p_version and rv.business_id=v_header.business_id and rv.active and spine.kind='stamps' and rv.cost_points=v_typed.stamp_target) then
      raise exception 'a live stamp card needs a gift at the last stamp' using errcode='23514';
    end if;
  end if;
  if exists(select 1 from public.retention_program_versions rv left join public.firm_reward_taxonomy t on t.id=rv.reward_taxonomy_id and t.business_id=rv.business_id where rv.config_version_id=p_version and rv.business_id=v_header.business_id and rv.active and coalesce(t.active,false)=false) then
    raise exception 'active retention programs cannot publish a retired taxonomy' using errcode='23514';
  end if;
  if exists(select 1 from public.birthday_program_versions bp where bp.config_version_id=p_version and bp.business_id=v_header.business_id and bp.active and bp.window_days_before+bp.window_days_after+1>365) then
    raise exception 'birthday benefit windows may not overlap annually' using errcode='23514';
  end if;
  for v_rule in select * from public.program_rules where config_version_id=p_version and business_id=v_header.business_id loop
    v_rule_errs := app.program_rule_errors(v_header.business_id, jsonb_build_object(
      'schema_version',v_rule.schema_version,'when_event',v_rule.when_event,'if_conditions',v_rule.if_conditions,
      'then_effects',v_rule.then_effects,'with_params',v_rule.with_params,'during_schedule',v_rule.during_schedule,'using_stacking',v_rule.using_stacking));
    if coalesce(array_length(v_rule_errs,1),0)>0 then
      raise exception 'cannot publish: program rule % is invalid (%)', v_rule.name, array_to_string(v_rule_errs,', ') using errcode='23514';
    end if;
  end loop;
  select count(*) into v_active_rule_count from public.program_rules where config_version_id=p_version and business_id=v_header.business_id and active;
  if v_active_rule_count>200 then
    raise exception 'cannot publish: too many active program rules (%)', v_active_rule_count using errcode='23514';
  end if;
  perform app.refresh_loyalty_config_snapshot(p_version);
  select * into v_header from public.firm_config_versions where id=p_version;
  select active_config_version_id into v_prior from public.businesses where id=v_header.business_id;
  update public.firm_config_versions set status='superseded',superseded_at=now() where id=v_prior and status='published';
  update public.firm_config_versions set status='published',published_at=now() where id=p_version;
  update public.businesses set active_config_version_id=p_version where id=v_header.business_id;
  update public.loyalty_programs set kind=v_typed.kind,loyalty_model=v_typed.loyalty_model,active=v_typed.active,earn_points_per_dollar=v_typed.earn_points_per_dollar,redeem_points=v_typed.redeem_points,reward_credit_cents=v_typed.reward_credit_cents,stamp_target=v_typed.stamp_target,stamp_per_cents=v_typed.stamp_per_cents,tier_basis=v_typed.tier_basis,expiry_mode=v_typed.expiry_mode,expiry_days=v_typed.expiry_days,configuration_status='published',current_config_version_id=p_version where business_id=v_header.business_id;
  update public.loyalty_rewards r set programme_id=rv.programme_id,name=rv.customer_name,internal_name=rv.internal_name,customer_name=rv.customer_name,description=rv.description,fulfillment_kind=rv.fulfillment_kind,taxonomy_label=rv.taxonomy_label,cost_points=rv.cost_points,credit_cents=rv.credit_cents,estimated_cost_cents=rv.estimated_cost_cents,active=rv.active,sort=rv.sort,claim_available_from=rv.claim_available_from,claim_available_until=rv.claim_available_until,entitlement_expiry_days=rv.entitlement_expiry_days,instructions=rv.instructions,terms=rv.terms,image_ref=rv.image_ref,requires_purchase=rv.requires_purchase,usage_limit=rv.usage_limit,min_tier_id=rv.min_tier_id,min_tier_threshold=rv.min_tier_threshold,current_config_version_id=p_version from public.loyalty_reward_versions rv where rv.reward_id=r.id and rv.business_id=r.business_id and rv.config_version_id=p_version;
  select array_agg(id), array_agg(paused), array_agg(deleted_at)
    into v_tier_carry_ids, v_tier_carry_paused, v_tier_carry_deleted
    from public.loyalty_tiers
   where business_id=v_header.business_id and (paused or deleted_at is not null);
  delete from public.loyalty_tiers where business_id=v_header.business_id;
  insert into public.loyalty_tiers(id,business_id,name,threshold,points_multiplier,perk_note,sort,effective_from,expires_at) select tier_id,business_id,name,threshold,points_multiplier,perk_note,sort,effective_from,expires_at from public.loyalty_tier_versions where config_version_id=p_version and business_id=v_header.business_id and active;
  if v_tier_carry_ids is not null then
    update public.loyalty_tiers t set paused=c.paused,deleted_at=c.deleted_at
      from (select unnest(v_tier_carry_ids) as id, unnest(v_tier_carry_paused) as paused, unnest(v_tier_carry_deleted) as deleted_at) c
     where c.id=t.id and t.business_id=v_header.business_id;
  end if;
  -- v332: `active` is now `rv.active and rp.deleted_at is null` -- rv.active alone can be a stale
  -- true (cloned from a frozen published snapshot before the program was deleted, or left stale in
  -- a draft this migration's delete RPC never touched). rp.deleted_at is the live, durable truth;
  -- it is not one of this UPDATE's target columns, so it can never be reset by this statement.
  update public.retention_programs rp set name=rv.name,active=(rv.active and rp.deleted_at is null),goal_visits=rv.goal_visits,period_days=rv.period_days,starts_on=rv.starts_on,reward_taxonomy_id=rv.reward_taxonomy_id,reward_type=rv.fulfillment_kind,reward_value=coalesce(rv.discount_percent,rv.credit_cents,0),reward_item=rv.manual_item,current_config_version_id=p_version from public.retention_program_versions rv where rv.program_id=rp.id and rv.business_id=rp.business_id and rv.config_version_id=p_version and rp.business_id=v_header.business_id;
  perform app.compile_program_rules(p_version);
  insert into public.audit_log(business_id,actor,action,entity,entity_id,detail)
  values(v_header.business_id,auth.uid(),'PUBLISH_CONFIG','firm_config_versions',p_version,jsonb_build_object('prior_version_id',v_prior,'new_version_id',p_version,'snapshot_hash',v_header.snapshot_hash,'birthday_program_count',(select count(*) from public.birthday_program_versions where config_version_id=p_version),'program_rule_count',(select count(*) from public.program_rules where config_version_id=p_version)));
  return json_build_object('version_id',p_version,'version_no',v_header.version_no,'status','published');
end $$;

--
-- Name: publish_sv_plan_version(uuid, uuid, integer, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.publish_sv_plan_version(p_business uuid, p_draft uuid, p_expected_revision integer, p_idempotency_key uuid, p_override_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_row public.sv_plan_drafts%rowtype;
  v_plan uuid; v_active boolean; v_old_name text; v_version uuid := gen_random_uuid(); v_version_no integer;
  v_val jsonb; v_disc integer; v_hard integer; v_reason text := nullif(btrim(coalesce(p_override_reason,'')),'');
  v_hash text; v_hit jsonb; v_new_plan boolean := false; v_result jsonb;
begin
  if not app.is_salon_owner(p_business) then raise exception 'owner only' using errcode = '42501'; end if;
  v_hash := app.ps1b_sha256(jsonb_build_object('op','publish','business',p_business,'draft',p_draft,
    'expected_revision',p_expected_revision,'override_reason',v_reason)::text);
  v_hit := app.sv_plan_idem_lookup(p_business, 'publish', p_idempotency_key, v_hash);
  if v_hit is not null then return v_hit; end if;

  select * into v_row from public.sv_plan_drafts where id = p_draft and business_id = p_business for update;
  if not found then raise exception 'stored-value plan draft not found in this business' using errcode = '22023'; end if;
  if v_row.status = 'published' then
    return jsonb_build_object('status','ok','plan_id',v_row.plan_id,'version_id',v_row.published_version_id,'replayed',true);
  end if;
  if v_row.status = 'discarded' then raise exception 'a discarded stored-value plan draft cannot be published' using errcode = '22023'; end if;
  if p_expected_revision is null or p_expected_revision <> v_row.revision then
    raise exception 'stored-value plan draft was changed in another session (expected revision %, current %)', p_expected_revision, v_row.revision using errcode = '22023';
  end if;

  -- structural validation gate (blocks; not overridable)
  v_val := app.sv_plan_validate(p_business, p_draft);
  if (v_val->>'publishable')::boolean is not true then
    raise exception 'plan is not publishable: %', (v_val->'validation_errors')::text using errcode = '22023';
  end if;
  v_disc := (v_val->>'effective_discount_bps')::integer;
  v_hard := (v_val->>'hard_threshold_bps')::integer;
  if v_disc >= v_hard and (v_reason is null or char_length(v_reason) < 3) then
    raise exception 'effective discount is at/above the firm hard limit - an override reason of at least 3 characters is required' using errcode = '22023';
  end if;

  -- bind or create the plan container; LOCK it before numbering (Sec 7)
  v_plan := v_row.plan_id;
  if v_plan is null then
    v_plan := gen_random_uuid(); v_new_plan := true;
    insert into public.sv_plans(id, business_id, name, active) values (v_plan, p_business, v_row.customer_facing_name, true);
    insert into public.sv_plan_status_events(business_id, plan_id, actor, prior_status, new_status, reason)
    values (p_business, v_plan, v_actor, null, 'active', 'plan created');
  end if;
  perform 1 from public.sv_plans where id = v_plan and business_id = p_business for update;
  select active, name into v_active, v_old_name from public.sv_plans where id = v_plan and business_id = p_business;
  if v_active is not true then
    raise exception 'stored-value plan is retired - reactivate it before publishing a new version' using errcode = '22023';
  end if;
  select coalesce(max(version_no),0) + 1 into v_version_no from public.sv_plan_versions where plan_id = v_plan and business_id = p_business;

  insert into public.sv_plan_versions(
    id, business_id, plan_id, version_no, price_cents, bonus_cents, expiry_days, terms_snapshot,
    customer_facing_name, paid_expiry_days, bonus_expiry_days, eligible_branch_ids, eligible_service_ids,
    eligible_product_ids, eligible_service_categories, min_spend_cents, stacking_policy, max_balance_cents,
    purchase_window_days, purchase_max_in_window, purchase_lifetime_cap, refund_policy, spend_order,
    topup_purchase_earns_points, stored_value_spend_earns_points, customer_terms, accounting_inputs,
    effective_at, source_draft_id)
  values (
    v_version, p_business, v_plan, v_version_no, v_row.price_cents, v_row.bonus_cents,
    coalesce(v_row.paid_expiry_days, v_row.bonus_expiry_days),
    jsonb_build_object('customer_terms', v_row.customer_terms, 'accounting_inputs', v_row.accounting_inputs, 'source_draft_id', v_row.id),
    v_row.customer_facing_name, v_row.paid_expiry_days, v_row.bonus_expiry_days, v_row.eligible_branch_ids,
    v_row.eligible_service_ids, v_row.eligible_product_ids, v_row.eligible_service_categories, v_row.min_spend_cents,
    v_row.stacking_policy, v_row.max_balance_cents, v_row.purchase_window_days, v_row.purchase_max_in_window,
    v_row.purchase_lifetime_cap, v_row.refund_policy, v_row.spend_order, v_row.topup_purchase_earns_points,
    v_row.stored_value_spend_earns_points, v_row.customer_terms, v_row.accounting_inputs, v_row.effective_at, v_row.id);

  update public.sv_plan_drafts set status = 'published', plan_id = v_plan, published_version_id = v_version
   where id = p_draft and business_id = p_business;

  -- display-name contract: keep sv_plans.name in step with the latest published version (in-txn, audited).
  if (not v_new_plan) and v_old_name is distinct from v_row.customer_facing_name then
    update public.sv_plans set name = v_row.customer_facing_name where id = v_plan and business_id = p_business;
    insert into public.audit_log(business_id, actor, action, entity, entity_id, detail)
    values (p_business, v_actor, 'SV_PLAN_RENAMED', 'sv_plans', v_plan, jsonb_build_object(
      'old_name', v_old_name, 'new_name', v_row.customer_facing_name, 'version_id', v_version));
  end if;

  v_result := jsonb_build_object('status','ok','plan_id',v_plan,'version_id',v_version,'version_no',v_version_no,
    'effective_discount_bps',v_disc,'override_applied',(v_disc >= v_hard),'new_plan',v_new_plan,'replayed',false);
  insert into public.sv_plan_operations(business_id, op_type, idempotency_key, request_hash, actor, result)
  values (p_business, 'publish', p_idempotency_key, v_hash, v_actor, v_result);
  insert into public.audit_log(business_id, actor, action, entity, entity_id, detail)
  values (p_business, v_actor, 'SV_PLAN_PUBLISHED', 'sv_plan_versions', v_version, jsonb_build_object(
    'plan_id', v_plan, 'version_no', v_version_no, 'price_cents', v_row.price_cents, 'bonus_cents', v_row.bonus_cents,
    'effective_discount_bps', v_disc, 'override_reason', v_reason, 'override_applied', (v_disc >= v_hard)));
  return v_result;
end $$;

--
-- Name: purge_campaign_send_records_v255(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purge_campaign_send_records_v255(p_limit integer DEFAULT 5000) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_deleted integer:=0;
begin
  if p_limit not between 1 and 10000 then
    raise exception 'purge limit must be 1..10000' using errcode='22023';
  end if;
  perform pg_catalog.set_config('app.v255_retention_purge','on',true);
  with expired as(
    select send_row.id
    from public.campaign_send_records_v255 send_row
    where send_row.retention_until<clock_timestamp()
    order by send_row.retention_until,send_row.id
    limit p_limit
    for update skip locked
  )
  delete from public.campaign_send_records_v255 send_row
  using expired
  where send_row.id=expired.id;
  get diagnostics v_deleted=row_count;
  perform pg_catalog.set_config('app.v255_retention_purge','',true);
  return v_deleted;
end
$$;

--
-- Name: purge_customer_account_open_days_v175(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purge_customer_account_open_days_v175(p_limit integer DEFAULT 5000) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_deleted integer:=0;
begin
  if p_limit not between 1 and 10000 then
    raise exception 'purge limit must be 1..10000' using errcode='22023';
  end if;
  perform pg_catalog.set_config('app.v175_retention_purge','on',true);
  with expired as(
    select day_row.id
    from public.customer_account_open_days_v175 day_row
    where day_row.retention_until<clock_timestamp()
    order by day_row.retention_until,day_row.id
    limit p_limit
    for update skip locked
  )
  delete from public.customer_account_open_days_v175 day_row
  using expired
  where day_row.id=expired.id;
  get diagnostics v_deleted=row_count;
  perform pg_catalog.set_config('app.v175_retention_purge','',true);
  return v_deleted;
end
$$;

