--
-- Name: quick_add_client(uuid, text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.quick_add_client(p_business uuid, p_phone text, p_name text, p_consent boolean DEFAULT false) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_norm text; c public.clients;
begin
  if not app.can_module(p_business, 'clients') then
    raise exception 'not allowed to add customers for this business';
  end if;
  v_norm := app.norm_phone(p_phone);
  if v_norm is null then raise exception 'Enter a valid 8-digit mobile number.'; end if;
  if p_name is null or length(trim(p_name)) < 2 then raise exception 'Enter the customer''s name.'; end if;

  insert into public.clients (business_id, full_name, phone, marketing_consent)
  values (p_business, trim(p_name), v_norm, coalesce(p_consent,false))
  on conflict (business_id, phone_norm) where phone_norm is not null do nothing
  returning * into c;

  if c.id is null then
    select * into c from public.clients where business_id = p_business and phone_norm = v_norm;
    return json_build_object('status','existing','client_id', c.id, 'full_name', c.full_name);
  end if;
  insert into public.consents (business_id, client_id, channel, action, source, actor)
  values (p_business, c.id, 'marketing',
          case when coalesce(p_consent,false) then 'granted' else 'withdrawn' end,
          'till', auth.uid());
  return json_build_object('status','created','client_id', c.id, 'full_name', c.full_name);
end $$;

--
-- Name: reactivate_sv_plan(uuid, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reactivate_sv_plan(p_business uuid, p_plan uuid, p_reason text, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid(); v_reason text := nullif(btrim(coalesce(p_reason,'')),''); v_active boolean;
  v_hash text; v_hit jsonb; v_result jsonb;
begin
  if not app.is_salon_owner(p_business) then raise exception 'owner only' using errcode = '42501'; end if;
  if v_reason is null or char_length(v_reason) < 3 then raise exception 'reactivating a stored-value plan requires a reason of at least 3 characters' using errcode = '22023'; end if;
  v_hash := app.ps1b_sha256(jsonb_build_object('op','reactivate','business',p_business,'plan',p_plan,'reason',v_reason)::text);
  v_hit := app.sv_plan_idem_lookup(p_business, 'reactivate', p_idempotency_key, v_hash);
  if v_hit is not null then return v_hit; end if;

  select active into v_active from public.sv_plans where id = p_plan and business_id = p_business for update;
  if not found then raise exception 'stored-value plan does not belong to this business' using errcode = '22023'; end if;
  if v_active is not true then
    update public.sv_plans set active = true where id = p_plan and business_id = p_business;
    insert into public.sv_plan_status_events(business_id, plan_id, actor, prior_status, new_status, reason)
    values (p_business, p_plan, v_actor, 'retired', 'active', v_reason);
    insert into public.audit_log(business_id, actor, action, entity, entity_id, detail)
    values (p_business, v_actor, 'SV_PLAN_REACTIVATED', 'sv_plans', p_plan, jsonb_build_object('reason', v_reason));
    v_result := jsonb_build_object('status','ok','plan_id',p_plan,'active',true,'replayed',false);
  else
    v_result := jsonb_build_object('status','ok','plan_id',p_plan,'active',true,'replayed',true);
  end if;
  insert into public.sv_plan_operations(business_id, op_type, idempotency_key, request_hash, actor, result)
  values (p_business, 'reactivate', p_idempotency_key, v_hash, v_actor, v_result);
  return v_result;
end $$;

--
-- Name: receive_stock(uuid, uuid, integer, date, date, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.receive_stock(p_business uuid, p_product uuid, p_qty integer, p_expires_on date, p_received_on date, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_staff uuid;
  v_sgt_today date := (timezone('Asia/Singapore', now()))::date;
  v_received date := coalesce(p_received_on, (timezone('Asia/Singapore', now()))::date);
  v_payload jsonb;
  v_hash text;
  v_existing public.f2_write_operations%rowtype;
  v_batch_id uuid;
  v_result jsonb;
begin
  if v_actor is null then
    raise exception 'authenticated staff required' using errcode = '42501';
  end if;
  if p_idempotency_key is null then
    raise exception 'a stock-receive idempotency key is required' using errcode = '22023';
  end if;
  select s.id into v_staff
    from public.staff s
   where s.business_id = p_business
     and s.user_id = v_actor
     and s.active
   order by case when s.role = 'owner' then 0 else 1 end, s.created_at
   limit 1
   for update;
  if v_staff is null or not app.can_module_write(p_business, 'inventory') then
    raise exception 'active inventory-module write authorization is required'
      using errcode = '42501';
  end if;

  -- THE cross-tenant gate: an active product that belongs to p_business.
  if p_product is null or not exists (
    select 1 from public.products p
     where p.id = p_product and p.business_id = p_business and p.active
  ) then
    raise exception 'stock product does not belong to this business or is inactive'
      using errcode = '22023';
  end if;
  if p_qty is null or p_qty < 1 or p_qty > 1000000 then
    raise exception 'received quantity must be between 1 and 1000000' using errcode = '22023';
  end if;
  if v_received > v_sgt_today + 1
     or v_received < (v_sgt_today - interval '5 years')::date then
    raise exception 'received date is outside the accepted window' using errcode = '22023';
  end if;
  if p_expires_on is not null and p_expires_on <= v_received then
    raise exception 'expiry date must be strictly after the received date' using errcode = '22023';
  end if;

  v_payload := jsonb_build_object(
    'business_id', p_business,
    'expires_on', p_expires_on,
    'product_id', p_product,
    'qty', p_qty,
    'received_on', v_received
  );
  v_hash := app.v41_request_hash(v_payload::text);
  perform pg_advisory_xact_lock(hashtextextended(
    'v54:stock:' || p_business::text || ':' || p_idempotency_key::text, 0));

  select * into v_existing
    from public.f2_write_operations o
   where o.business_id = p_business and o.idempotency_key = p_idempotency_key
   for update;
  if found then
    if v_existing.actor is distinct from v_actor
       or v_existing.operation_type <> 'stock_receive'
       or v_existing.request_hash <> v_hash then
      raise exception 'idempotency key conflicts with another stock-receive request'
        using errcode = '23505';
    end if;
    return jsonb_build_object(
      'status', 'duplicate_ignored',
      'stock_batch_id', (v_existing.result->>'stock_batch_id')::uuid,
      'replayed', true
    );
  end if;

  insert into public.stock_batches (product_id, qty, expires_on, received_on)
  values (p_product, p_qty, p_expires_on, v_received)
  returning id into v_batch_id;

  insert into public.audit_log (business_id, actor, action, entity, entity_id, detail)
  values (p_business, v_actor, 'stock_receive', 'stock_batches', v_batch_id,
          jsonb_build_object(
            'idempotency_key', p_idempotency_key,
            'product_id', p_product,
            'qty', p_qty,
            'expires_on', p_expires_on,
            'received_on', v_received));

  v_result := jsonb_build_object('status', 'ok', 'stock_batch_id', v_batch_id, 'replayed', false);
  insert into public.f2_write_operations (
    business_id, actor, operation_type, idempotency_key, request_hash, status, result
  ) values (
    p_business, v_actor, 'stock_receive', p_idempotency_key, v_hash, 'completed', v_result);
  return v_result;
end $$;

--
-- Name: reclassify_sale_policy(uuid, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reclassify_sale_policy(p_sale uuid, p_counts_as_revenue boolean, p_reason text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  o public.sales%rowtype;
  n public.sales%rowtype;
  r public.sales%rowtype;
  v_reversal_ids uuid[] := '{}'::uuid[];
  v_actor uuid := auth.uid();
  v_actor_staff uuid;
begin
  if p_counts_as_revenue is null then
    raise exception 'p_counts_as_revenue is required';
  end if;
  if p_reason is null or length(btrim(p_reason)) < 10 then
    raise exception 'a reason of at least 10 characters is required to reclassify a historical sale';
  end if;

  select * into o
    from public.sales
   where id = p_sale;
  if not found then
    raise exception 'sale not found';
  end if;
  if o.reversal_of is not null then
    raise exception 'reclassify the original sale %, not reversal %', o.reversal_of, o.id;
  end if;
  if not app.has_perm(o.business_id, 'reclassify_sales') then
    raise exception 'only an active owner may reclassify a historical sale'
      using errcode = '42501';
  end if;
  if not app.can_see_branch(o.business_id, o.branch_id) then
    raise exception 'you are not permitted to reclassify this branch scope'
      using errcode = '42501';
  end if;

  select st.id into v_actor_staff
    from public.staff st
   where st.business_id = o.business_id
     and st.user_id = v_actor
     and st.active
     and 'reclassify_sales' = any (app.role_perms(st.role))
   order by st.created_at
   limit 1
   for update;
  if not found then
    raise exception 'active owner authorization is required to reclassify a sale'
      using errcode = '42501';
  end if;

  select * into o
    from public.sales
   where id = p_sale
   for update;
  if not app.has_perm(o.business_id, 'reclassify_sales')
     or not app.can_see_branch(o.business_id, o.branch_id) then
    raise exception 'reclassification authorization changed while the sale was being locked'
      using errcode = '42501';
  end if;
  if o.counts_as_revenue = p_counts_as_revenue then
    raise exception 'sale % already has counts_as_revenue = %; nothing to restate',
      p_sale, p_counts_as_revenue;
  end if;

  perform set_config('app.reclassify_sale', o.id::text, true);
  update public.sales
     set counts_as_revenue = p_counts_as_revenue
   where id = o.id
  returning * into n;
  perform set_config('app.reclassify_sale', '', true);

  for r in
    select * from public.sales
     where business_id = o.business_id
       and reversal_of = o.id
     for update
  loop
    perform set_config('app.reclassify_sale', r.id::text, true);
    update public.sales
       set counts_as_revenue = p_counts_as_revenue
     where id = r.id;
    perform set_config('app.reclassify_sale', '', true);
    v_reversal_ids := array_append(v_reversal_ids, r.id);
  end loop;

  insert into public.audit_log (business_id, actor, action, entity, entity_id, detail)
  values (
    o.business_id,
    auth.uid(),
    'RECLASSIFY',
    'sales',
    o.id,
    jsonb_build_object(
      'reason', p_reason,
      'occurred_at', o.occurred_at,
      'kind', o.kind,
      'amount_cents', o.amount_cents,
      'before', jsonb_build_object('counts_as_revenue', o.counts_as_revenue),
      'after', jsonb_build_object('counts_as_revenue', n.counts_as_revenue),
      'reversal_sale_ids', v_reversal_ids,
      'frozen', jsonb_build_object(
        'counts_as_visit', o.counts_as_visit,
        'earns_points', o.earns_points,
        'commission_rate_bps', o.commission_rate_bps
      )
    )
  );

  return row_to_json(n);
end $$;

--
-- Name: reconcile_external_commerce_event_v106(uuid, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reconcile_external_commerce_event_v106(p_event uuid, p_sale uuid, p_idempotency_key text, p_allocations jsonb DEFAULT '[]'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_event public.commerce_events_v106%rowtype;
  v_sale public.sales%rowtype;
  v_existing public.commerce_event_reconciliations_v106%rowtype;
  v_recon public.commerce_event_reconciliations_v106%rowtype;
  v_line jsonb;
  v_alloc_total bigint := 0;
  v_prior_refunds bigint := 0;
  v_hash text;
  v_item uuid;
  v_payment uuid;
  v_amount bigint;
begin
  if auth.uid() is null then
    raise exception 'authentication required' using errcode = '42501';
  end if;
  if p_allocations is null or jsonb_typeof(p_allocations) <> 'array' then
    raise exception 'allocations must be a JSON array' using errcode = '22023';
  end if;

  select * into strict v_event from public.commerce_events_v106 where id = p_event;
  if not (
    app.is_super_admin()
    or (
      v_event.event_type in ('refund_completed', 'chargeback_opened', 'chargeback_reversed')
      and app.has_perm(v_event.business_id, 'refund_sales')
    )
    or (
      v_event.event_type in ('transaction_completed', 'transaction_voided')
      and app.has_perm(v_event.business_id, 'create_sales')
    )
  ) then
    raise exception 'sale-write permission required to reconcile this event'
      using errcode = '42501';
  end if;
  if not app.can_see_branch(v_event.business_id, v_event.branch_id) then
    raise exception 'branch is outside actor scope' using errcode = '42501';
  end if;
  select * into strict v_sale
    from public.sales s
   where s.id = p_sale and s.business_id = v_event.business_id
   for update;
  if v_sale.branch_id is distinct from v_event.branch_id then
    raise exception 'event and sale branch differ' using errcode = '22023';
  end if;
  if not app.can_see_branch(v_sale.business_id, v_sale.branch_id) then
    raise exception 'sale branch is outside actor scope' using errcode = '42501';
  end if;
  if v_event.currency <> (
    select c.currency
      from app.v106_reporting_contract(v_sale.business_id, v_sale.branch_id, v_sale.occurred_at) c
  ) then
    raise exception 'event and sale reporting currency differ' using errcode = '22023';
  end if;
  if v_event.event_type = 'transaction_completed'
     and (
       v_sale.reversal_of is not null
       or not v_sale.counts_as_revenue
       or v_sale.amount_cents <= 0
       or v_event.amount_minor <> v_sale.amount_cents
     ) then
    raise exception 'transaction_completed must match one positive completed revenue sale exactly'
      using errcode = '22023';
  end if;
  if v_event.event_type = 'transaction_voided'
     and (
       v_sale.reversal_of is null
       or v_sale.amount_cents >= 0
       or v_event.amount_minor <> v_sale.amount_cents
     ) then
    raise exception 'transaction_voided must match one native reversal sale exactly'
      using errcode = '22023';
  end if;

  v_hash := encode(extensions.digest(convert_to(jsonb_build_object(
    'event_id', p_event, 'sale_id', p_sale, 'allocations', p_allocations
  )::text, 'UTF8'), 'sha256'), 'hex');
  select * into v_existing
    from public.commerce_event_reconciliations_v106
   where event_id = p_event;
  if found then
    if v_existing.reconciliation_hash = v_hash then
      return jsonb_build_object(
        'status', 'replayed',
        'reconciliation_id', v_existing.id,
        'ledger_changed', false
      );
    end if;
    raise exception 'event is already reconciled differently'
      using errcode = '23505';
  end if;

  if v_event.event_type = 'refund_completed' then
    if v_sale.reversal_of is not null then
      raise exception 'a refund cannot be allocated to a reversal row'
        using errcode = '22023';
    end if;
    if exists (
      select 1 from public.sales r
       where r.business_id = v_sale.business_id and r.reversal_of = v_sale.id
    ) then
      raise exception 'sale already has a native full reversal'
        using errcode = '22023';
    end if;
    for v_line in select value from jsonb_array_elements(p_allocations)
    loop
      if jsonb_typeof(v_line) <> 'object' then
        raise exception 'each allocation must be a JSON object' using errcode = '22023';
      end if;
      v_item := nullif(v_line->>'sale_item_id', '')::uuid;
      v_payment := nullif(v_line->>'payment_id', '')::uuid;
      v_amount := (v_line->>'amount_minor')::bigint;
      if v_amount <= 0 then
        raise exception 'allocation amount_minor must be positive' using errcode = '22023';
      end if;
      if v_item is not null and not exists (
        select 1 from public.sale_items i
         where i.id = v_item and i.sale_id = v_sale.id
           and i.business_id = v_sale.business_id
      ) then
        raise exception 'sale_item allocation target is outside the sale'
          using errcode = '23503';
      end if;
      if v_payment is not null and not exists (
        select 1 from public.payments p
         where p.id = v_payment and p.sale_id = v_sale.id
           and p.business_id = v_sale.business_id
      ) then
        raise exception 'payment allocation target is outside the sale'
          using errcode = '23503';
      end if;
      v_alloc_total := v_alloc_total + v_amount;
    end loop;
    if v_alloc_total <> abs(v_event.amount_minor) then
      raise exception 'refund allocations % do not equal event amount %',
        v_alloc_total, abs(v_event.amount_minor) using errcode = '22023';
    end if;
    select coalesce(sum(a.amount_minor), 0) into v_prior_refunds
      from public.commerce_refund_allocations_v106 a
      join public.commerce_event_reconciliations_v106 r
        on r.id = a.reconciliation_id and r.business_id = a.business_id
     where a.business_id = v_sale.business_id and a.sale_id = v_sale.id;
    if v_prior_refunds + v_alloc_total > v_sale.amount_cents then
      raise exception 'cumulative external refunds exceed the original sale'
        using errcode = '22023';
    end if;
  elsif p_allocations <> '[]'::jsonb then
    raise exception 'only refund_completed events may carry allocations'
      using errcode = '22023';
  end if;

  insert into public.commerce_event_reconciliations_v106(
    business_id, event_id, sale_id, idempotency_key, reconciliation_hash
  ) values (
    v_event.business_id, v_event.id, v_sale.id, btrim(p_idempotency_key), v_hash
  ) returning * into v_recon;

  if v_event.event_type = 'refund_completed' then
    for v_line in select value from jsonb_array_elements(p_allocations)
    loop
      insert into public.commerce_refund_allocations_v106(
        business_id, reconciliation_id, event_id, sale_id,
        sale_item_id, payment_id, amount_minor
      ) values (
        v_event.business_id, v_recon.id, v_event.id, v_sale.id,
        nullif(v_line->>'sale_item_id', '')::uuid,
        nullif(v_line->>'payment_id', '')::uuid,
        (v_line->>'amount_minor')::bigint
      );
    end loop;
  end if;

  return jsonb_build_object(
    'status', 'reconciled',
    'reconciliation_id', v_recon.id,
    'event_id', v_event.id,
    'sale_id', v_sale.id,
    'allocated_refund_minor', v_alloc_total,
    'ledger_changed', false
  );
end $$;

--
-- Name: record_campaign_exposure_v99(uuid, uuid, uuid, text, text, timestamp with time zone, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_campaign_exposure_v99(p_business uuid, p_campaign uuid, p_campaign_grant uuid, p_channel text, p_idempotency_key text, p_exposed_at timestamp with time zone DEFAULT now(), p_evidence_reference_hash text DEFAULT NULL::text, p_evidence_context jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $_$
declare
  v_actor uuid:=auth.uid();
  v_grant public.retention_campaign_grants%rowtype;
  v_existing public.retention_campaign_exposures_v99%rowtype;
  v_context jsonb:=coalesce(p_evidence_context,'{}'::jsonb);
  v_key text:=btrim(coalesce(p_idempotency_key,''));
  v_hash text;
  v_id uuid:=gen_random_uuid();
begin
  if v_actor is null
     or not app.is_salon_owner(p_business)
     or not app.can_module_write(p_business,'retention') then
    raise exception 'active owner retention write authorization is required'
      using errcode='42501';
  end if;
  if p_channel not in ('in_app','email','sms','whatsapp','other') then
    raise exception 'unsupported exposure channel' using errcode='22023';
  end if;
  if char_length(v_key) not between 8 and 200 then
    raise exception 'idempotency key must contain 8..200 characters'
      using errcode='22023';
  end if;
  if p_exposed_at is null
     or p_exposed_at>clock_timestamp()+interval '5 minutes'
     or p_exposed_at<clock_timestamp()-interval '90 days' then
    raise exception 'exposure time is outside the accepted evidence window'
      using errcode='22023';
  end if;
  if p_evidence_reference_hash is not null
     and p_evidence_reference_hash!~'^[0-9a-f]{64}$' then
    raise exception 'evidence reference must be a lowercase SHA-256 hash'
      using errcode='22023';
  end if;
  if jsonb_typeof(v_context)<>'object'
     or octet_length(v_context::text)>2048
     or exists(
       select 1
       from pg_catalog.jsonb_object_keys(v_context) as context_key(key)
       where context_key.key not in (
         'entry_point','locale','device_class','surface_version','outcome'
       )
     )
     or exists(
       select 1
       from pg_catalog.jsonb_each(v_context) as context_item(key,value)
       where pg_catalog.jsonb_typeof(context_item.value)
               not in ('string','number','boolean','null')
          or (
            pg_catalog.jsonb_typeof(context_item.value)='string'
            and char_length(context_item.value#>>'{}')>80
          )
     ) then
    raise exception 'evidence context is not privacy-safe'
      using errcode='22023';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'v99:exposure:'||p_business::text||':'||v_key,0
    )
  );
  select grant_row.* into v_grant
  from public.retention_campaign_grants grant_row
  where grant_row.id=p_campaign_grant
    and grant_row.business_id=p_business
    and grant_row.campaign_id=p_campaign
  for share;
  if not found then
    raise exception 'campaign grant was not found in this campaign'
      using errcode='22023';
  end if;
  if v_grant.reward_grant_id is null then
    raise exception 'campaign grant has no linked reward entitlement'
      using errcode='check_violation';
  end if;
  if not exists(
    select 1
    from public.reward_grants reward
    where reward.id=v_grant.reward_grant_id
      and reward.business_id=p_business
      and reward.client_id=v_grant.client_id
      and reward.campaign_id=p_campaign
      and reward.campaign_assignment='treatment'
      and reward.status in ('granted','redeemed')
      and reward.granted_at<=p_exposed_at
  ) then
    raise exception
      'linked reward entitlement is not valid for this campaign member'
      using errcode='check_violation';
  end if;
  if p_exposed_at<v_grant.issued_at then
    raise exception 'exposure cannot precede the campaign grant'
      using errcode='22023';
  end if;
  if exists(
    select 1
    from public.retention_campaign_measurement_windows_v99 measurement
    where measurement.campaign_id=p_campaign
  ) then
    raise exception 'campaign exposure batch is already sealed'
      using errcode='object_not_in_prerequisite_state';
  end if;

  v_hash:=pg_catalog.encode(
    extensions.digest(
      pg_catalog.convert_to(
        pg_catalog.concat_ws(
          '|','v99.campaign-exposure',p_business::text,p_campaign::text,
          p_campaign_grant::text,p_channel,p_exposed_at::text,
          coalesce(p_evidence_reference_hash,''),v_context::text
        ),
        'UTF8'
      ),
      'sha256'
    ),
    'hex'
  );
  select exposure.* into v_existing
  from public.retention_campaign_exposures_v99 exposure
  where exposure.business_id=p_business
    and exposure.idempotency_key=v_key;
  if found then
    if v_existing.request_hash<>v_hash then
      raise exception 'idempotency key conflicts with another exposure envelope'
        using errcode='23505';
    end if;
    return pg_catalog.jsonb_build_object(
      'exposure_id',v_existing.id,
      'campaign_id',v_existing.campaign_id,
      'client_id',v_existing.client_id,
      'exposure_status','verified',
      'delivery_provider_status','not_configured',
      'replayed',true
    );
  end if;
  select exposure.* into v_existing
  from public.retention_campaign_exposures_v99 exposure
  where exposure.campaign_grant_id=p_campaign_grant;
  if found then
    if v_existing.request_hash<>v_hash then
      raise exception 'campaign grant already has different exposure evidence'
        using errcode='23505';
    end if;
    return pg_catalog.jsonb_build_object(
      'exposure_id',v_existing.id,
      'campaign_id',v_existing.campaign_id,
      'client_id',v_existing.client_id,
      'exposure_status','verified',
      'delivery_provider_status','not_configured',
      'replayed',true
    );
  end if;

  insert into public.retention_campaign_exposures_v99(
    id,business_id,campaign_id,client_id,campaign_grant_id,reward_grant_id,
    assignment,channel,evidence_kind,evidence_reference_hash,
    evidence_context,exposed_at,recorded_by,idempotency_key,request_hash
  ) values(
    v_id,p_business,p_campaign,v_grant.client_id,p_campaign_grant,
    v_grant.reward_grant_id,'treatment',p_channel,'manual_confirmation',
    p_evidence_reference_hash,v_context,p_exposed_at,v_actor,v_key,v_hash
  );
  insert into public.audit_log(
    business_id,actor,action,entity,entity_id,detail
  ) values(
    p_business,v_actor,'CAMPAIGN_EXPOSURE_VERIFIED_V99',
    'retention_campaign_exposures_v99',v_id,
    pg_catalog.jsonb_build_object(
      'campaign_id',p_campaign,'campaign_grant_id',p_campaign_grant,
      'channel',p_channel,'evidence_kind','manual_confirmation',
      'delivery_provider_status','not_configured'
    )
  );
  return pg_catalog.jsonb_build_object(
    'exposure_id',v_id,'campaign_id',p_campaign,
    'client_id',v_grant.client_id,'exposure_status','verified',
    'delivery_provider_status','not_configured','replayed',false
  );
end
$_$;

--
-- Name: record_campaign_returns(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_campaign_returns(p_business uuid, p_campaign uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid:=auth.uid();
  v_campaign public.retention_campaigns%rowtype;
  v_window public.retention_campaign_measurement_windows_v99%rowtype;
  v_recorded integer:=0;
begin
  if v_actor is null
     or not app.is_salon_owner(p_business)
     or not app.can_module_write(p_business,'retention') then
    raise exception 'active owner retention write authorization is required'
      using errcode='42501';
  end if;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('v99:returns:'||p_campaign::text,0)
  );
  select campaign.* into v_campaign
  from public.retention_campaigns campaign
  where campaign.id=p_campaign and campaign.business_id=p_business
  for share;
  if not found then
    raise exception 'campaign not found in this business'
      using errcode='22023';
  end if;
  if v_campaign.status not in ('active','completed') then
    raise exception 'returns require an active or completed campaign'
      using errcode='object_not_in_prerequisite_state';
  end if;
  select measurement.* into v_window
  from public.retention_campaign_measurement_windows_v99 measurement
  where measurement.campaign_id=p_campaign
    and measurement.business_id=p_business;
  if not found then
    raise exception 'verified exposure measurement is not sealed'
      using errcode='object_not_in_prerequisite_state';
  end if;

  insert into public.retention_campaign_attributions_v99(
    measurement_window_id,business_id,campaign_id,client_id,assignment,
    sale_id,returned_at,recorded_by
  )
  select
    v_window.id,p_business,p_campaign,member.client_id,member.assignment,
    first_return.sale_id,first_return.occurred_at,v_actor
  from public.retention_campaign_members member
  join lateral(
    select sale.id as sale_id,sale.occurred_at
    from public.sales sale
    where sale.business_id=p_business
      and sale.client_id=member.client_id
      and sale.counts_as_visit
      and sale.reversal_of is null
      and sale.occurred_at>=v_window.measurement_started_at
      and sale.occurred_at<v_window.measurement_ends_at
      and not exists(
        select 1
        from public.sales reversal
        where reversal.business_id=sale.business_id
          and reversal.reversal_of=sale.id
      )
    order by sale.occurred_at,sale.id
    limit 1
  ) first_return on true
  where member.campaign_id=p_campaign
    and member.business_id=p_business
  on conflict (campaign_id,client_id) do nothing;
  get diagnostics v_recorded=row_count;

  insert into public.audit_log(
    business_id,actor,action,entity,entity_id,detail
  ) values(
    p_business,v_actor,'RECORD_CAMPAIGN_ATTRIBUTIONS_V99',
    'retention_campaign_measurement_windows_v99',v_window.id,
    pg_catalog.jsonb_build_object(
      'campaign_id',p_campaign,'newly_recorded',v_recorded,
      'measurement_started_at',v_window.measurement_started_at
    )
  );
  return pg_catalog.jsonb_build_object(
    'campaign_id',p_campaign,'measurement_window_id',v_window.id,
    'newly_recorded',v_recorded,
    'legacy_v50_return_evidence_used',false
  );
end
$$;

--
-- Name: record_cart_sale(uuid, uuid, uuid, uuid, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_cart_sale(p_business uuid, p_client uuid, p_branch uuid, p_staff uuid, p_method text, p_idempotency_key text, p_lines jsonb) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_key text := nullif(btrim(p_idempotency_key), '');
  v_method text := lower(nullif(btrim(p_method), ''));
  v_types text[] := array['service', 'retail', 'package', 'membership', 'gift_card', 'custom'];
  v_line jsonb;
  v_type text;
  v_ref uuid;
  v_qn numeric;
  v_un numeric;
  v_qty integer;
  v_unit integer;
  v_line_staff uuid;
  v_count integer;
  v_total bigint := 0;
  v_retail_lines integer := 0;
  v_stamp_product uuid;
  v_stamp_qty integer;
  v_financial jsonb;
  v_sale_id uuid;
  v_replayed boolean;
  v_points integer := 0;
  v_items json;
begin
  if v_actor is null then
    raise exception 'authenticated staff required to record a cart sale' using errcode = '42501';
  end if;
  if not app.has_perm(p_business, 'create_sales') then
    raise exception 'you do not have permission to record a sale in this business (create_sales)'
      using errcode = '42501';
  end if;
  if v_key is null or length(v_key) < 8 then
    raise exception 'a cart-sale idempotency key of at least 8 characters is required'
      using errcode = '22023';
  end if;
  if v_method is null or v_method not in ('cash', 'card', 'paynow', 'other') then
    raise exception 'choose Cash, Card, PayNow or Other' using errcode = '22023';
  end if;
  if p_lines is null or jsonb_typeof(p_lines) <> 'array' then
    raise exception 'cart lines must be a JSON array' using errcode = '22023';
  end if;
  v_count := jsonb_array_length(p_lines);
  if v_count < 1 or v_count > 50 then
    raise exception 'a cart must have between 1 and 50 lines' using errcode = '22023';
  end if;
  if p_client is not null and not exists (
    select 1 from public.clients c where c.id = p_client and c.business_id = p_business
  ) then
    raise exception 'cart-sale client does not belong to this business' using errcode = '22023';
  end if;

  -- Validate every line before creating anything.
  for v_line in select * from jsonb_array_elements(p_lines) loop
    v_type := v_line->>'item_type';
    if v_type is null or not (v_type = any (v_types)) then
      raise exception 'unsupported cart line item_type %', coalesce(v_type, '(null)')
        using errcode = '22023';
    end if;
    if jsonb_typeof(v_line->'qty') is distinct from 'number'
       or jsonb_typeof(v_line->'unit_cents') is distinct from 'number' then
      raise exception 'each cart line requires numeric qty and unit_cents' using errcode = '22023';
    end if;
    v_qn := (v_line->>'qty')::numeric;
    v_un := (v_line->>'unit_cents')::numeric;
    if v_qn <> trunc(v_qn) or v_qn <= 0 or v_qn > 1000000 then
      raise exception 'cart line qty must be a whole number between 1 and 1000000'
        using errcode = '22023';
    end if;
    if v_un <> trunc(v_un) or v_un < 0 or v_un > 100000000 then
      raise exception 'cart line unit_cents must be a whole number between 0 and 100000000'
        using errcode = '22023';
    end if;
    v_qty := v_qn::integer;
    v_unit := v_un::integer;
    v_ref := nullif(v_line->>'ref_id', '')::uuid;
    v_line_staff := nullif(v_line->>'staff_id', '')::uuid;

    if v_type = 'service' then
      if v_ref is null or not exists (
        select 1 from public.services s where s.id = v_ref and s.business_id = p_business
      ) then
        raise exception 'service line references a service outside this business'
          using errcode = '22023';
      end if;
    elsif v_type = 'retail' then
      if v_ref is null or not exists (
        select 1 from public.products p where p.id = v_ref and p.business_id = p_business
      ) then
        raise exception 'retail line references a product outside this business'
          using errcode = '22023';
      end if;
      v_retail_lines := v_retail_lines + 1;
      v_stamp_product := v_ref;
      v_stamp_qty := v_qty;
    elsif v_type = 'package' then
      if v_ref is null or not exists (
        select 1 from public.package_plans pp where pp.id = v_ref and pp.business_id = p_business
      ) then
        raise exception 'package line references a plan outside this business'
          using errcode = '22023';
      end if;
    elsif v_type = 'membership' then
      if v_ref is null or not exists (
        select 1 from public.membership_plans mp where mp.id = v_ref and mp.business_id = p_business
      ) then
        raise exception 'membership line references a plan outside this business'
          using errcode = '22023';
      end if;
    else
      -- gift_card / custom carry no typed reference.
      if v_ref is not null then
        raise exception 'a % line must not carry a ref_id', v_type using errcode = '22023';
      end if;
    end if;

    if v_line_staff is not null and not exists (
      select 1 from public.staff s
       where s.id = v_line_staff and s.business_id = p_business and s.active
    ) then
      raise exception 'cart line staff is inactive or outside this business' using errcode = '22023';
    end if;

    v_total := v_total + (v_qty::bigint * v_unit::bigint);
  end loop;

  if v_total <= 0 then
    raise exception 'a cart sale must total more than zero' using errcode = '22023';
  end if;
  if v_total > 2147483647 then
    raise exception 'cart total exceeds the supported maximum' using errcode = '22023';
  end if;

  -- Only a single-retail-line cart can carry the parent product_id/qty that v6 FEFO
  -- (single-product-per-sale) can act on. Otherwise leave product_id NULL: no deduction,
  -- identical to every other checkout surface today.
  if v_retail_lines <> 1 then
    v_stamp_product := null;
    v_stamp_qty := null;
  end if;

  perform set_config('app.cart_line_product_id', coalesce(v_stamp_product::text, ''), true);
  perform set_config('app.cart_line_qty', coalesce(v_stamp_qty::text, ''), true);
  v_financial := public.record_quick_sale(
    p_business => p_business,
    p_amount_cents => v_total::integer,
    p_method => v_method,
    p_client => p_client,
    p_staff => p_staff,
    p_branch => p_branch,
    p_note => 'cart checkout',
    p_idempotency_key => v_key,
    p_paid => true
  )::jsonb;
  perform set_config('app.cart_line_product_id', '', true);
  perform set_config('app.cart_line_qty', '', true);

  v_sale_id := nullif(v_financial #>> '{sale,id}', '')::uuid;
  v_replayed := coalesce((v_financial->>'replayed')::boolean, false);
  if v_sale_id is null then
    raise exception 'cart sale did not produce a parent sale row' using errcode = 'XX001';
  end if;

  -- First run inserts the child lines; a replay already committed them, so skip to avoid
  -- duplicates. sale_id committed <=> its items committed (one transaction), so this holds.
  if not v_replayed then
    insert into public.sale_items(
      sale_id, business_id, item_type, ref_id, description,
      qty, unit_cents, line_cents, product_id, staff_id)
    select v_sale_id,
           p_business,
           e->>'item_type',
           nullif(e->>'ref_id', '')::uuid,
           nullif(e->>'description', ''),
           (e->>'qty')::integer,
           (e->>'unit_cents')::integer,
           (e->>'qty')::integer * (e->>'unit_cents')::integer,
           case when e->>'item_type' = 'retail' then nullif(e->>'ref_id', '')::uuid end,
           nullif(e->>'staff_id', '')::uuid
      from jsonb_array_elements(p_lines) as e;
  end if;

  if p_client is not null then
    select coalesce(sum(pl.points), 0) into v_points
      from public.points_ledger pl
     where pl.business_id = p_business
       and pl.client_id = p_client
       and pl.sale_id = v_sale_id
       and pl.entry_type = 'earn';
  end if;

  select coalesce(json_agg(row_to_json(si) order by si.created_at, si.id), '[]'::json)
    into v_items
    from public.sale_items si
   where si.business_id = p_business and si.sale_id = v_sale_id;

  return json_build_object(
    'status', case when v_replayed then 'duplicate_ignored' else 'ok' end,
    'sale_id', v_sale_id,
    'business_id', p_business,
    'total_cents', v_total,
    'item_count', v_count,
    'replayed', v_replayed,
    'points_earned', case when v_replayed then 0 else v_points end,
    'sale', v_financial->'sale',
    'items', v_items
  );
end $$;

--
-- Name: record_cart_sale(uuid, uuid, uuid, uuid, text, text, jsonb, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_cart_sale(p_business uuid, p_client uuid, p_branch uuid, p_staff uuid, p_method text, p_idempotency_key text, p_lines jsonb, p_evaluation_id uuid, p_paid boolean DEFAULT true) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_key text := nullif(btrim(p_idempotency_key), '');
  v_method text := lower(nullif(btrim(p_method), ''));
  v_paid boolean := coalesce(p_paid, true);
  v_eval public.checkout_evaluations%rowtype;
  v_line jsonb; v_ord int; v_rehash text; v_price jsonb;
  v_kind text; v_cid uuid; v_qty int; v_unit int;
  v_reproj jsonb := '[]'::jsonb;
  v257_bundle jsonb; v257_bline jsonb; v257_bid uuid; v257_bqty int;
  v257_cur_bid uuid; v257_cur_bqty int; v257_pos int := 0;
  v_retail_lines int := 0; v_stamp_product uuid; v_stamp_qty int;
  v_financial jsonb; v_sale_id uuid; v_replayed boolean;
  eff jsonb; v_ps timestamptz; v_amt int; v_ful uuid; v_key_ben text; v_rule uuid; v_rule_name text;
  bp record; v_bp_id uuid; v_committed int; v_points int := 0; v_items json;
  -- v67 stored-value tender locals
  v_tender public.checkout_sv_tenders%rowtype; v_has_sv boolean := false;
  v_sv_amount int := 0; v_sv_remainder int := 0; v_spend jsonb; v_sv_json jsonb := null;
begin
  if v_actor is null then
    raise exception 'authenticated staff required to finalise a cart sale' using errcode = '42501';
  end if;
  if not app.has_perm(p_business, 'create_sales') then
    raise exception 'you do not have permission to record a sale in this business (create_sales)' using errcode = '42501';
  end if;
  if v_key is null or length(v_key) < 8 then
    raise exception 'a cart-sale idempotency key of at least 8 characters is required' using errcode = '22023';
  end if;
  if v_method is null or v_method not in ('cash', 'card', 'paynow', 'other') then
    raise exception 'choose Cash, Card, PayNow or Other' using errcode = '22023';
  end if;
  if p_evaluation_id is null then
    raise exception 'the kernel finaliser requires a checkout evaluation token' using errcode = '22023';
  end if;

  -- 8.1 Lock the token. Single-use + tenant + scope validation.
  select * into v_eval from public.checkout_evaluations
   where id = p_evaluation_id and business_id = p_business for update;
  if not found then
    raise exception 'checkout evaluation not found in this business' using errcode = '42501';
  end if;
  if p_branch is not null and p_branch is distinct from v_eval.branch_id then
    raise exception 'stale_evaluation: branch does not match the evaluation token' using errcode = 'P0001';
  end if;
  if p_client is not null and p_client is distinct from v_eval.client_id then
    raise exception 'stale_evaluation: client does not match the evaluation token' using errcode = 'P0001';
  end if;

  -- 8.2 If already consumed: exact replay of THIS key, or a same-token/different-key loser
  --     (which must fail stale, never double-sell).
  if v_eval.consumed_at is not null then
    if exists (select 1 from public.financial_operations fo
                where fo.business_id = p_business and fo.sale_id = v_eval.consumed_sale_id
                  and fo.operation_type = 'quick_sale' and fo.idempotency_key = v_key) then
      select coalesce(sum(pl.points), 0) into v_points from public.points_ledger pl
       where pl.business_id = p_business and pl.sale_id = v_eval.consumed_sale_id and pl.entry_type = 'earn';
      select coalesce(json_agg(row_to_json(si) order by si.created_at, si.id), '[]'::json) into v_items
        from public.sale_items si where si.business_id = p_business and si.sale_id = v_eval.consumed_sale_id;
      return json_build_object('status', 'duplicate_ignored', 'sale_id', v_eval.consumed_sale_id,
        'business_id', p_business, 'total_cents', v_eval.total_cents, 'discount_total_cents', v_eval.discount_total_cents,
        'replayed', true, 'points_earned', 0, 'evaluation_id', v_eval.id, 'items', v_items,
        'stored_value', (select jsonb_build_object('sv_paid_cents', t.reserved_cents,
            'cash_collected_cents', t.cash_remainder_cents) from public.checkout_sv_tenders t
           where t.evaluation_id = v_eval.id and t.status = 'consumed' limit 1));
    end if;
    raise exception 'stale_evaluation: this checkout evaluation was already consumed by another sale' using errcode = 'P0001';
  end if;
  if v_eval.expires_at <= now() then
    raise exception 'stale_evaluation: the checkout evaluation has expired; re-evaluate' using errcode = 'P0001';
  end if;

  -- 8.3 Config drift: the active config version must be UNCHANGED since evaluation.
  if v_eval.config_version_id is distinct from
     (select active_config_version_id from public.businesses where id = p_business) then
    raise exception 'stale_evaluation: the active configuration changed since evaluation; re-evaluate' using errcode = 'P0001';
  end if;

  -- 8.3b Stored-value tender bound to this token? Discover + re-validate gates (TOCTOU). Any drift
  --      (reservation missing/expired/released) -> stale_evaluation so the till re-evaluates once.
  select * into v_tender from public.checkout_sv_tenders
   where business_id = p_business and evaluation_id = v_eval.id and status = 'reserved'
   for update;
  if found then
    v_has_sv := true;
    -- Gate re-validation after the lock (authority live, no synthetic on live, redeem pause, currency).
    perform app.sv_checkout_tender_gate(p_business, v_eval.client_id, v_tender.currency);
    if not exists (select 1 from public.sv_reservations r
                    where r.id = v_tender.reservation_id and r.business_id = p_business and r.status = 'active') then
      raise exception 'stale_evaluation: the stored-value hold is no longer active; re-evaluate' using errcode = 'P0001';
    end if;
    v_sv_amount := least(v_tender.reserved_cents, v_eval.total_cents);
    if v_sv_amount < 1 then
      raise exception 'stale_evaluation: the stored-value hold no longer covers this checkout; re-evaluate' using errcode = 'P0001';
    end if;
    v_sv_remainder := v_eval.total_cents - v_sv_amount;
  elsif exists (select 1 from public.checkout_sv_tenders t
                 where t.business_id = p_business and t.evaluation_id = v_eval.id and t.status = 'released') then
    -- The staff opted into stored value for this token but the hold was released (superseded by a
    -- later checkout for the same customer, or swept). Never silently downgrade to cash: fail stale
    -- so the till re-evaluates once (one winner in a two-token race; the loser gets a typed stale).
    raise exception 'stale_evaluation: the stored-value hold for this checkout was released; re-evaluate' using errcode = 'P0001';
  end if;

  -- 8.4 Price drift: re-resolve every server line and recompute the cart hash. A custom line is
  --     re-projected AS-IS from the immutable token.
  v_ord := 0;
  for v_line in select * from jsonb_array_elements(v_eval.server_lines) loop
    v_ord := v_ord + 1;
    v_kind := v_line->>'catalog_kind';
    v_cid := nullif(v_line->>'catalog_id', '')::uuid;
    v_qty := (v_line->>'qty')::int;
    if v_kind = 'custom' then
      v_unit := (v_line->>'unit_price_cents')::int;
    elsif nullif(v_line->>'bundle_id', '') is not null then
      v257_bid := (v_line->>'bundle_id')::uuid;
      v257_bqty := coalesce(nullif(v_line->>'bundle_qty', '')::int, 1);
      if v257_cur_bid is distinct from v257_bid or v257_cur_bqty is distinct from v257_bqty then
        v257_bundle := app.ps1c_bundle_lines_v204(p_business, v257_bid, v257_bqty);
        if v257_bundle->>'status' <> 'ok' then
          raise exception 'stale_evaluation: bundle on line % can no longer be priced (%); re-evaluate', v_ord, v257_bundle->>'status'
            using errcode = 'P0001';
        end if;
        v257_cur_bid := v257_bid; v257_cur_bqty := v257_bqty; v257_pos := 0;
      end if;
      v257_pos := v257_pos + 1;
      v257_bline := v257_bundle->'lines'->(v257_pos - 1);
      if v257_bline is null or nullif(v257_bline->>'service_id', '')::uuid is distinct from v_cid then
        raise exception 'stale_evaluation: the bundle on line % changed since evaluation; re-evaluate', v_ord
          using errcode = 'P0001';
      end if;
      v_unit := (v257_bline->>'line_cents')::int;
    else
      v_price := app.ps1b_catalog_price(p_business, v_kind, v_cid);
      if v_price->>'status' <> 'ok' then
        raise exception 'stale_evaluation: line % can no longer be priced (%); re-evaluate', v_ord, v_price->>'status'
          using errcode = 'P0001';
      end if;
      v_unit := (v_price->>'price_cents')::int;
      if v_kind = 'product' then v_retail_lines := v_retail_lines + 1; v_stamp_product := v_cid; v_stamp_qty := v_qty; end if;
    end if;
    v_reproj := v_reproj || jsonb_build_array(jsonb_build_object(
      'catalog_kind', v_kind, 'catalog_id', v_cid, 'name', v_line->>'name',
      'unit_price_cents', v_unit, 'qty', v_qty, 'line_total_cents', v_unit * v_qty));
  end loop;
  v_rehash := app.ps1c_cart_hash(v_reproj);
  if v_rehash is distinct from v_eval.cart_hash then
    raise exception 'stale_evaluation: catalog prices changed since evaluation; re-evaluate' using errcode = 'P0001';
  end if;

  -- 8.5 Budget re-check + COMMIT, atomically, under a deterministic
  --     (business_id, rule_id, period_start) lock order.
  for eff in select e from jsonb_array_elements(v_eval.applied_effects) e
              where (e->>'suppressed')::boolean is not true and coalesce((e->>'capped')::boolean, false) loop
    insert into public.budget_periods(business_id, rule_id, period_start, period_end, cap_cents)
    values(p_business, (eff->>'rule_id')::uuid, (eff->>'period_start')::timestamptz,
           (eff->>'period_end')::timestamptz, (eff->>'cap_cents')::int)
    on conflict (business_id, rule_id, period_start) do nothing;
  end loop;
  for bp in select (e->>'rule_id')::uuid as rule_id, (e->>'period_start')::timestamptz as ps,
                    (e->>'cap_cents')::int as cap, sum((e->>'amount_cents')::int) as amt
              from jsonb_array_elements(v_eval.applied_effects) e
             where (e->>'suppressed')::boolean is not true and coalesce((e->>'capped')::boolean, false)
             group by 1, 2, 3
             order by 1, 2 loop
    select coalesce(committed_cents, 0) into v_committed from public.budget_periods
     where business_id = p_business and rule_id = bp.rule_id and period_start = bp.ps
     for update;
    if coalesce(v_committed, 0) + bp.amt > bp.cap then
      raise exception 'stale_evaluation: rule budget was exhausted since evaluation; re-evaluate' using errcode = 'P0001';
    end if;
  end loop;

  -- 8.6 Belt-guard (contract B, v59): a zero total must NEVER create a sale, and must fail as a
  --     TYPED 22023 (not a stale P0001 that would spin a client re-evaluation loop).
  if v_eval.total_cents = 0 then
    raise exception 'total_zero_not_supported: this checkout totals zero after discounts and cannot be recorded; re-price it'
      using errcode = '22023';
  end if;

  -- 8.7 Create the parent sale for the DISCOUNTED total via the kernel candidate. When stored value
  --     tenders any portion, finalise the parent p_paid=false so the finaliser writes NO full-amount
  --     payment (the non-SV remainder is recorded below; the SV portion collects no new cash).
  perform set_config('app.cart_line_product_id',
    coalesce(case when v_retail_lines = 1 then v_stamp_product::text end, ''), true);
  perform set_config('app.cart_line_qty',
    coalesce(case when v_retail_lines = 1 then v_stamp_qty::text end, ''), true);
  v_financial := public.record_quick_sale(
    p_business => p_business, p_amount_cents => v_eval.total_cents, p_method => v_method,
    p_client => v_eval.client_id, p_staff => p_staff, p_branch => v_eval.branch_id, p_note => 'cart checkout (kernel)',
    p_idempotency_key => v_key, p_paid => case when v_has_sv then false else v_paid end)::jsonb;
  perform set_config('app.cart_line_product_id', '', true);
  perform set_config('app.cart_line_qty', '', true);

  v_sale_id := nullif(v_financial #>> '{sale,id}', '')::uuid;
  v_replayed := coalesce((v_financial->>'replayed')::boolean, false);
  if v_sale_id is null then
    raise exception 'kernel finaliser did not produce a parent sale row' using errcode = 'XX001';
  end if;
  if v_replayed then
    raise exception 'stale_evaluation: this idempotency key already produced a sale for a different token' using errcode = 'P0001';
  end if;

  -- 8.8 Write server-line sale_items (positive; custom -> item_type 'custom') then one signed
  --     studio_discount line per applied effect (negative).
  insert into public.sale_items(sale_id, business_id, item_type, ref_id, description, qty, unit_cents, line_cents, product_id)
  select v_sale_id, p_business,
         case e->>'catalog_kind' when 'service' then 'service' when 'product' then 'retail' else 'custom' end,
         nullif(e->>'catalog_id', '')::uuid, e->>'name', (e->>'qty')::int, (e->>'unit_price_cents')::int,
         (e->>'unit_price_cents')::int * (e->>'qty')::int,
         case when e->>'catalog_kind' = 'product' then nullif(e->>'catalog_id', '')::uuid end
    from jsonb_array_elements(v_eval.server_lines) e;

  -- 8.8b One CUSTOM_PRICE_LINE audit row per custom line.
  for eff in select e from jsonb_array_elements(v_eval.server_lines) e where e->>'catalog_kind' = 'custom' loop
    insert into public.audit_log(business_id, actor, action, entity, entity_id, detail)
    values(p_business, v_actor, 'CUSTOM_PRICE_LINE', 'sale_items', v_sale_id,
      jsonb_build_object(
        'description', eff->>'name',
        'amount_cents', (eff->>'unit_price_cents')::int,
        'reason', eff->>'reason',
        'entered_by', eff->>'entered_by'));
  end loop;

  -- 8.9 Per applied (non-suppressed) discount: fulfilment registry row, provenance line, signed
  --     sale_items line, and (if capped) a committed budget reservation.
  for eff in select e from jsonb_array_elements(v_eval.applied_effects) e
              where (e->>'suppressed')::boolean is not true and (e->>'amount_cents')::int > 0
              order by (e->>'rule_id'), (e->>'effect_index')::int loop
    v_rule := (eff->>'rule_id')::uuid;
    v_amt := (eff->>'amount_cents')::int;
    -- V370: an effect with NO rule is the automatic tier discount (app.ps1c_plan_checkout). It is
    -- named by the benefit it came from, and its fulfilment key is keyed on that benefit — the
    -- rule-keyed key would collapse to null and collide with itself.
    if v_rule is null then
      v_rule_name := coalesce(nullif(btrim(coalesce(eff->>'label','')),''), 'Tier discount');
      v_key_ben := 'tierdiscount:' || v_sale_id::text || ':' || coalesce(eff->>'tier_benefit_id','');
    else
      select name into v_rule_name from public.program_rules
        where rule_id = v_rule and config_version_id = v_eval.config_version_id and business_id = p_business;
      v_rule_name := coalesce(v_rule_name, 'Studio discount');
      v_key_ben := 'discount:' || v_sale_id::text || ':' || v_rule::text || ':' || (eff->>'effect_index');
    end if;
    insert into public.benefit_fulfilments(
      business_id, canonical_benefit_key, source_engine, fulfilment_kind, client_id, detail_ref,
      face_value_cents, estimated_cost_cents, cost_basis, cost_confidence, config_version_id, occurred_at)
    values(p_business, v_key_ben, 'checkout', 'checkout_discount', v_eval.client_id, v_sale_id,
      v_amt, v_amt, 'discount_face', 'high', v_eval.config_version_id, now())
    returning id into v_ful;

    -- V370: public.checkout_discount_lines is Studio provenance — rule_id is NOT NULL, its unique
    -- key is (sale_id, rule_id, effect_index), and both reverse_sale and
    -- get_checkout_discount_report key off it. A tier discount has no rule, so it gets no row
    -- there rather than a fabricated one; its money is still fully recorded, by the fulfilment
    -- above and the signed sale_items line below, and it is inside the sale total either way.
    if v_rule is not null then
      insert into public.checkout_discount_lines(
        business_id, sale_id, evaluation_id, rule_id, effect_index, effect_type, level, target_line_index,
        amount_cents, benefit_fulfilment_id, config_version_id)
      values(p_business, v_sale_id, v_eval.id, v_rule, (eff->>'effect_index')::int, eff->>'effect_type',
        eff->>'level', nullif(eff->>'target_line_index', '')::int, v_amt, v_ful, v_eval.config_version_id);
    end if;

    insert into public.sale_items(sale_id, business_id, item_type, ref_id, description, qty, unit_cents, line_cents)
    values(v_sale_id, p_business, 'studio_discount',
      coalesce(v_rule, nullif(eff->>'tier_benefit_id','')::uuid),
      left(case when v_rule is null then 'Tier benefit: ' else 'Discount: ' end || v_rule_name, 200),
      1, -v_amt, -v_amt);

    if coalesce((eff->>'capped')::boolean, false) then
      v_ps := (eff->>'period_start')::timestamptz;
      select id into v_bp_id from public.budget_periods
        where business_id = p_business and rule_id = v_rule and period_start = v_ps;
      insert into public.budget_reservations(business_id, budget_period_id, discount_fulfilment_id, amount_cents)
      values(p_business, v_bp_id, v_ful, v_amt);
      update public.budget_periods set committed_cents = committed_cents + v_amt, updated_at = now()
       where id = v_bp_id;
    end if;
  end loop;

  -- 8.9b Stored-value tender consumption (v67). Release the token hold, then spend the SV portion
  --      via the v63 engine (paid/bonus split per PS-0), record tender evidence, and record only the
  --      non-SV remainder as a payment. All within this atomic transaction with the sale.
  if v_has_sv then
    perform app.sv_release_core(p_business, v_tender.reservation_id, gen_random_uuid());
    v_spend := app.sv_spend_core(p_business, v_tender.account_id, v_sv_amount, gen_random_uuid());
    update public.checkout_sv_tenders
       set status = 'consumed', spend_operation_id = (v_spend->>'operation_id')::uuid, sale_id = v_sale_id,
           sv_paid_cents = (v_spend->>'paid_draw_cents')::int, sv_bonus_cents = (v_spend->>'bonus_draw_cents')::int,
           cash_remainder_cents = v_sv_remainder, updated_at = now()
     where id = v_tender.id;
    if v_sv_remainder > 0 and v_paid then
      perform public.record_payment(
        p_business => p_business, p_method => v_method, p_amount_cents => v_sv_remainder, p_sale => v_sale_id,
        p_client => v_eval.client_id, p_staff => p_staff, p_branch => v_eval.branch_id,
        p_idempotency_key => left(v_key || '-svrem', 255));
    end if;
    insert into public.audit_log(business_id, actor, action, entity, entity_id, detail)
    values(p_business, v_actor, 'SV_CHECKOUT_TENDER_SPENT', 'checkout_sv_tenders', v_tender.id, jsonb_build_object(
      'evaluation_id', v_eval.id, 'sale_id', v_sale_id, 'spend_operation_id', (v_spend->>'operation_id')::uuid,
      'sv_spend_cents', v_sv_amount, 'sv_paid_cents', (v_spend->>'paid_draw_cents')::int,
      'sv_bonus_cents', (v_spend->>'bonus_draw_cents')::int, 'cash_remainder_cents', v_sv_remainder));
    v_sv_json := jsonb_build_object(
      'sv_spend_cents', v_sv_amount, 'sv_paid_cents', (v_spend->>'paid_draw_cents')::int,
      'sv_bonus_cents', (v_spend->>'bonus_draw_cents')::int, 'cash_collected_cents', v_sv_remainder,
      'spend_operation_id', (v_spend->>'operation_id')::uuid);
  end if;

  -- 8.10 Consume the token (single-use).
  update public.checkout_evaluations set consumed_at = now(), consumed_sale_id = v_sale_id
   where id = v_eval.id and consumed_at is null;
  if not found then
    raise exception 'stale_evaluation: token consumed concurrently; re-evaluate' using errcode = 'P0001';
  end if;

  if v_eval.client_id is not null then
    select coalesce(sum(pl.points), 0) into v_points from public.points_ledger pl
     where pl.business_id = p_business and pl.client_id = v_eval.client_id and pl.sale_id = v_sale_id and pl.entry_type = 'earn';
  end if;
  select coalesce(json_agg(row_to_json(si) order by si.created_at, si.id), '[]'::json) into v_items
    from public.sale_items si where si.business_id = p_business and si.sale_id = v_sale_id;

  return json_build_object(
    'status', 'ok', 'sale_id', v_sale_id, 'business_id', p_business,
    'subtotal_cents', v_eval.subtotal_cents, 'discount_total_cents', v_eval.discount_total_cents,
    'total_cents', v_eval.total_cents, 'gst_cents', v_eval.gst_cents,
    'replayed', false, 'points_earned', v_points, 'evaluation_id', v_eval.id,
    'sale', v_financial->'sale', 'items', v_items, 'stored_value', v_sv_json);
end $$;

--
-- Name: record_consultant_payout_v78(uuid, integer, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_consultant_payout_v78(p_line uuid, p_amount_cents integer, p_reference text, p_paid_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid:=auth.uid();
  v_line public.consultant_payout_lines%rowtype;
  v_batch public.consultant_payout_batches%rowtype;
  v_accrual public.consultant_commission_accruals%rowtype;
  v_consultant public.platform_consultants%rowtype;
  v_line_paid integer;
  v_accrual_paid integer;
  v_net integer;
  v_payment uuid;
begin
  if v_actor is null or not app.v89_platform_can('commissions','rw') then
    raise exception 'super-admin access is required' using errcode='42501';
  end if;
  if p_amount_cents<=0 or nullif(btrim(p_reference),'') is null
     or length(p_reference)>240 or p_paid_at is null
     or p_paid_at>now()+interval '5 minutes' then
    raise exception 'invalid payout evidence' using errcode='22023';
  end if;
  select * into strict v_line from public.consultant_payout_lines
   where id=p_line for update;
  select * into v_batch from public.consultant_payout_batches
   where id=v_line.batch_id and status in ('approved','processing') for update;
  if not found then raise exception 'approved payout batch was not found' using errcode='22023'; end if;
  select * into strict v_accrual from public.consultant_commission_accruals
   where id=v_line.accrual_id for update;
  select * into strict v_consultant from public.platform_consultants
   where id=v_line.consultant_id for update;
  if not v_consultant.active or v_consultant.departed_at is not null
     or p_paid_at<v_consultant.employment_started_on::timestamptz then
    return app.forfeit_consultant_core_v78(
      v_consultant.id,coalesce(v_consultant.departed_at,now()),
      'payout refused because consultant is inactive or departed',v_actor
    );
  end if;
  select coalesce(sum(amount_cents),0) into v_line_paid
    from public.consultant_payout_payments where line_id=p_line;
  select coalesce(sum(payment.amount_cents),0) into v_accrual_paid
    from public.consultant_payout_lines line
    join public.consultant_payout_payments payment on payment.line_id=line.id
   where line.accrual_id=v_accrual.id;
  select v_accrual.commission_cents+coalesce(sum(
    case when settlement_status='payable' then commission_adjustment_cents else 0 end
  ),0) into v_net
    from public.consultant_commission_adjustments
   where accrual_id=v_accrual.id;
  if p_amount_cents>v_line.amount_cents-v_line_paid
     or p_amount_cents>greatest(v_net-v_accrual_paid,0) then
    raise exception 'partial payout exceeds line or current net payable'
      using errcode='22023';
  end if;
  insert into public.consultant_payout_payments(
    line_id,amount_cents,payment_reference,paid_at,recorded_by
  ) values (
    p_line,p_amount_cents,btrim(p_reference),p_paid_at,v_actor
  ) returning id into v_payment;
  update public.consultant_payout_batches set status='processing'
   where id=v_batch.id and status='approved';
  if v_accrual_paid+p_amount_cents>=v_net then
    update public.consultant_commission_accruals
       set status='paid' where id=v_accrual.id and status='approved';
  end if;
  if not exists(
    select 1
      from public.consultant_payout_lines line
     where line.batch_id=v_batch.id
       and (
         select coalesce(sum(payment.amount_cents),0)
           from public.consultant_payout_payments payment
          where payment.line_id=line.id
       ) < line.amount_cents
  ) then
    update public.consultant_payout_batches
       set status='paid',paid_at=p_paid_at where id=v_batch.id;
  end if;
  return jsonb_build_object(
    'payment_id',v_payment,'line_id',p_line,'amount_cents',p_amount_cents,
    'reference',btrim(p_reference),'paid_at',p_paid_at
  );
end
$$;

--
-- Name: record_credit_tender(uuid, uuid, integer, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_credit_tender(p_business uuid, p_sale uuid, p_amount_cents integer, p_reason text, p_idempotency_key text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  s public.sales%rowtype;
  v_existing public.credit_tenders%rowtype;
  v_operation public.financial_operations%rowtype;
  v_operation_id uuid := gen_random_uuid();
  v_request_payload jsonb;
  v_request_hash text;
  v_result jsonb;
  v_credit_balance integer;
  v_sale_net integer;
  v_paid integer;
  v_balance_due integer;
  v_payment public.payments%rowtype;
  v_payment_id uuid := gen_random_uuid();
  v_payment_key text;
  v_ledger public.credit_ledger%rowtype;
  v_ledger_id uuid := gen_random_uuid();
  v_ledger_key text;
  v_actor uuid := auth.uid();
  v_actor_staff uuid;
begin
  if p_idempotency_key is null or length(btrim(p_idempotency_key)) < 8 then
    raise exception 'p_idempotency_key is required and must be at least 8 characters';
  end if;
  if coalesce(p_amount_cents, 0) <= 0 then
    raise exception 'store-credit tender amount must be positive';
  end if;

  if not app.has_perm(p_business, 'create_sales') then
    raise exception 'you do not have permission to take payment in this business (create_sales)'
      using errcode = '42501';
  end if;

  select * into s
    from public.sales
   where id = p_sale
     and business_id = p_business;
  if not found then
    raise exception 'sale not found in this business';
  end if;
  if not app.can_see_branch(p_business, s.branch_id) then
    raise exception 'you are not permitted to take payment for this branch scope'
      using errcode = '42501';
  end if;

  select st.id into v_actor_staff
    from public.staff st
   where st.business_id = p_business
     and st.user_id = v_actor
     and st.active
     and 'create_sales' = any (app.role_perms(st.role))
   order by case st.role when 'owner' then 0 when 'manager' then 1 else 2 end, st.created_at
   limit 1
   for update;
  if not found then
    raise exception 'active staff authorization is required to take store-credit tender'
      using errcode = '42501';
  end if;

  select * into s
    from public.sales
   where id = p_sale
     and business_id = p_business
   for update;
  if not found then
    raise exception 'sale not found in this business';
  end if;
  if s.appointment_id is not null then
    perform 1
      from public.appointments a
     where a.id = s.appointment_id
       and a.business_id = s.business_id
     for update;
  end if;

  if not app.has_perm(p_business, 'create_sales')
     or not app.can_see_branch(p_business, s.branch_id) then
    raise exception 'store-credit authorization changed while the operation was being locked'
      using errcode = '42501';
  end if;

  v_request_payload := jsonb_build_object(
    'business_id', p_business,
    'sale_id', s.id,
    'branch_id', s.branch_id,
    'client_id', s.client_id,
    'actor', v_actor,
    'amount_cents', p_amount_cents,
    'reason', nullif(btrim(p_reason), '')
  );
  v_request_hash := md5(v_request_payload::text);

  select * into v_operation
    from public.financial_operations fo
   where fo.business_id = p_business
     and fo.operation_type = 'credit_tender'
     and fo.idempotency_key = btrim(p_idempotency_key);
  if found then
    if (v_operation.sale_id, v_operation.branch_id, v_operation.actor,
        v_operation.request_payload, v_operation.request_hash)
       is distinct from
       (s.id, s.branch_id, v_actor, v_request_payload, v_request_hash) then
      raise exception 'credit tender idempotency key conflicts with a different immutable request'
        using errcode = '23505';
    end if;
    if v_operation.status <> 'completed' or v_operation.result is null then
      raise exception 'credit tender operation is reserved but incomplete'
        using errcode = '55000';
    end if;
    select * into v_existing
      from public.credit_tenders ct
     where ct.operation_id = v_operation.id
       and ct.business_id = p_business
       and ct.sale_id = s.id
       and ct.client_id is not distinct from s.client_id
       and ct.branch_id is not distinct from s.branch_id
       and ct.actor = v_actor
       and ct.amount_cents = p_amount_cents
       and ct.idempotency_key = btrim(p_idempotency_key);
    if not found or not exists (
      select 1
        from public.payments p
        join public.credit_ledger cl
          on cl.id = v_existing.credit_ledger_id
         and cl.business_id = v_existing.business_id
       where p.id = v_existing.payment_id
         and p.business_id = v_existing.business_id
         and p.sale_id = v_existing.sale_id
         and p.client_id = v_existing.client_id
         and p.branch_id is not distinct from v_existing.branch_id
         and p.method = 'credit'
         and p.kind = 'payment'
         and p.amount_cents = v_existing.amount_cents
         and p.created_by = v_existing.actor
         and cl.client_id = v_existing.client_id
         and cl.entry_type = 'spend'
         and cl.amount_cents = -v_existing.amount_cents
         and cl.sale_id = v_existing.sale_id
         and cl.payment_id = v_existing.payment_id
         and cl.actor = v_existing.actor
    ) then
      raise exception 'completed credit tender is missing exact payment/ledger proof'
        using errcode = 'XX001';
    end if;
    return (v_operation.result || jsonb_build_object('replayed', true))::json;
  end if;

  if s.reversal_of is not null then
    raise exception 'cannot take store-credit tender on a reversal sale';
  end if;
  if s.client_id is null then
    raise exception 'store-credit tender requires a sale with a client';
  end if;
  if exists (
    select 1 from public.sales r
     where r.business_id = s.business_id
       and r.reversal_of = s.id
  ) then
    raise exception 'cannot take store-credit tender on a reversed sale';
  end if;

  perform 1
    from public.clients c
   where c.id = s.client_id
     and c.business_id = p_business
   for update;
  if not found then
    raise exception 'sale client does not belong to this business';
  end if;

  select coalesce(sum(cl.amount_cents), 0)::integer
    into v_credit_balance
    from public.credit_ledger cl
   where cl.business_id = p_business
     and cl.client_id = s.client_id;

  select (s.amount_cents + coalesce(sum(r.amount_cents), 0))::integer
    into v_sale_net
    from public.sales r
   where r.business_id = s.business_id
     and r.reversal_of = s.id;
  v_sale_net := coalesce(v_sale_net, s.amount_cents);

  select coalesce(sum(p.amount_cents), 0)::integer
    into v_paid
    from public.payments p
   where p.business_id = p_business
     and (
       p.sale_id = s.id
       or (
         p.sale_id is null
         and s.appointment_id is not null
         and p.appointment_id = s.appointment_id
       )
     );

  v_balance_due := v_sale_net - v_paid;

  if v_balance_due <= 0 then
    raise exception 'sale % has no positive balance due for store-credit tender', s.id;
  end if;
  if p_amount_cents > v_balance_due then
    raise exception 'store-credit tender % exceeds sale balance due %', p_amount_cents, v_balance_due;
  end if;
  if p_amount_cents > v_credit_balance then
    raise exception 'insufficient store credit: % available, % requested',
      v_credit_balance, p_amount_cents
      using errcode = '23514';
  end if;

  perform set_config('app.financial_operation_insert_id', v_operation_id::text, true);
  insert into public.financial_operations (
    id, business_id, branch_id, sale_id, operation_type, actor,
    idempotency_key, request_payload, request_hash
  )
  values (
    v_operation_id, p_business, s.branch_id, s.id, 'credit_tender', v_actor,
    btrim(p_idempotency_key), v_request_payload, v_request_hash
  )
  on conflict (business_id, operation_type, idempotency_key) do nothing
  returning * into v_operation;
  perform set_config('app.financial_operation_insert_id', '', true);

  if v_operation.id is null then
    select * into v_operation
      from public.financial_operations fo
     where fo.business_id = p_business
       and fo.operation_type = 'credit_tender'
       and fo.idempotency_key = btrim(p_idempotency_key);
    if not found
       or (v_operation.sale_id, v_operation.branch_id, v_operation.actor,
           v_operation.request_payload, v_operation.request_hash)
          is distinct from
          (s.id, s.branch_id, v_actor, v_request_payload, v_request_hash) then
      raise exception 'credit tender idempotency reservation conflicts with a different immutable request'
        using errcode = '23505';
    end if;
    if v_operation.status = 'completed' and v_operation.result is not null then
      return (v_operation.result || jsonb_build_object('replayed', true))::json;
    end if;
    raise exception 'credit tender operation is already reserved but incomplete'
      using errcode = '55000';
  end if;

  v_payment_key := 'v20:' || v_operation.id || ':payment';
  perform set_config('app.payment_insert_id', v_payment_id::text, true);
  perform set_config('app.payment_write_scope', 'credit_tender', true);

  insert into public.payments (
    id, business_id, branch_id, sale_id, appointment_id, client_id, staff_id,
    method, kind, amount_cents, reference, note, idempotency_key, created_by
  )
  values (
    v_payment_id,
    p_business,
    s.branch_id,
    s.id,
    null,
    s.client_id,
    coalesce(v_actor_staff, s.staff_id),
    'credit',
    'payment',
    p_amount_cents,
    coalesce(p_reason, 'store credit tender'),
    'auto payment from store credit tender',
    v_payment_key,
    v_actor
  )
  on conflict (business_id, idempotency_key) where idempotency_key is not null
    do nothing
  returning * into v_payment;

  perform set_config('app.payment_insert_id', '', true);
  perform set_config('app.payment_write_scope', '', true);

  if v_payment.id is null then
    select * into v_payment
      from public.payments
     where business_id = p_business
       and idempotency_key = v_payment_key;
    if not found
       or (v_payment.branch_id, v_payment.sale_id, v_payment.appointment_id,
           v_payment.client_id, v_payment.staff_id, v_payment.method, v_payment.kind,
           v_payment.amount_cents, v_payment.created_by)
          is distinct from
          (s.branch_id, s.id, null::uuid, s.client_id,
           coalesce(v_actor_staff, s.staff_id), 'credit'::text, 'payment'::text,
           p_amount_cents, v_actor) then
      raise exception 'credit tender payment key conflicts with a different immutable child'
        using errcode = '23505';
    end if;
  end if;

  v_ledger_key := 'v20:' || v_operation.id || ':ledger';
  perform set_config('app.credit_ledger_insert_id', v_ledger_id::text, true);
  perform set_config('app.credit_ledger_write_scope', 'credit_tender', true);
  insert into public.credit_ledger (
    id, business_id, client_id, entry_type, amount_cents, reference,
    sale_id, payment_id, actor, idempotency_key
  )
  values (
    v_ledger_id,
    p_business,
    s.client_id,
    'spend',
    -p_amount_cents,
    coalesce(p_reason, 'store credit tender') || ' sale ' || s.id,
    s.id,
    v_payment.id,
    v_actor,
    v_ledger_key
  )
  on conflict (business_id, idempotency_key) where idempotency_key is not null
    do nothing
  returning * into v_ledger;
  perform set_config('app.credit_ledger_insert_id', '', true);
  perform set_config('app.credit_ledger_write_scope', '', true);

  if v_ledger.id is null then
    select * into v_ledger
      from public.credit_ledger
     where business_id = p_business
       and idempotency_key = v_ledger_key;
    if not found
       or (v_ledger.client_id, v_ledger.entry_type, v_ledger.amount_cents,
           v_ledger.sale_id, v_ledger.payment_id, v_ledger.actor)
          is distinct from
          (s.client_id, 'spend'::text, -p_amount_cents,
           s.id, v_payment.id, v_actor) then
      raise exception 'credit tender ledger key conflicts with a different immutable child'
        using errcode = '23505';
    end if;
  end if;

  insert into public.credit_tenders (
    operation_id, business_id, sale_id, payment_id, credit_ledger_id, client_id, branch_id,
    actor, amount_cents, idempotency_key, reason,
    balance_before_cents, balance_after_cents
  )
  values (
    v_operation.id,
    p_business,
    s.id,
    v_payment.id,
    v_ledger.id,
    s.client_id,
    s.branch_id,
    v_actor,
    p_amount_cents,
    btrim(p_idempotency_key),
    p_reason,
    v_credit_balance,
    v_credit_balance - p_amount_cents
  )
  returning * into v_existing;

  if v_existing.operation_id is distinct from v_operation.id
     or v_existing.payment_id is distinct from v_payment.id
     or v_existing.credit_ledger_id is distinct from v_ledger.id
     or v_existing.balance_after_cents is distinct from
        (v_existing.balance_before_cents - v_existing.amount_cents)
     or (select coalesce(sum(cl.amount_cents), 0)::integer
           from public.credit_ledger cl
          where cl.business_id = p_business
            and cl.client_id = s.client_id) is distinct from
        (v_credit_balance - p_amount_cents) then
    raise exception 'credit_tenders proof or resulting balance is not exact'
      using errcode = 'check_violation';
  end if;

  v_result := jsonb_build_object(
    'replayed', false,
    'operation_id', v_operation.id,
    'sale_id', s.id,
    'payment_id', v_payment.id,
    'credit_ledger_id', v_ledger.id,
    'amount_cents', p_amount_cents,
    'balance_after_cents', v_credit_balance - p_amount_cents
  );

  perform set_config('app.financial_operation_complete_id', v_operation.id::text, true);
  update public.financial_operations
     set status = 'completed',
         result = v_result,
         completed_at = now()
   where id = v_operation.id
     and status = 'reserved';
  perform set_config('app.financial_operation_complete_id', '', true);
  if not found then
    raise exception 'failed to complete reserved credit tender operation'
      using errcode = '55000';
  end if;

  insert into public.audit_log (business_id, actor, action, entity, entity_id, detail)
  values (
    p_business,
    v_actor,
    'STORE_CREDIT_TENDER',
    'sales',
    s.id,
    jsonb_build_object(
      'operation_id', v_operation.id,
      'sale_id', s.id,
      'payment_id', v_payment.id,
      'credit_ledger_id', v_ledger.id,
      'amount_cents', p_amount_cents,
      'balance_before_cents', v_credit_balance,
      'balance_after_cents', v_credit_balance - p_amount_cents
    )
  );

  return v_result::json;
end $$;

--
-- Name: record_drawer_movement(uuid, uuid, text, integer, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_drawer_movement(p_business uuid, p_branch uuid, p_kind text, p_amount_cents integer, p_note text DEFAULT NULL::text, p_staff uuid DEFAULT NULL::uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_row cash_drawer_movements; v_amt integer;
begin
  if not app.has_perm(p_business, 'view_finance') then
    raise exception 'you do not have permission to move cash in or out of the drawer (view_finance)';
  end if;
  if not exists (select 1 from branches where id = p_branch and business_id = p_business) then
    raise exception 'branch does not belong to this business';
  end if;
  if p_kind not in ('pay_in','pay_out') then
    raise exception 'kind must be pay_in or pay_out (sale_cash is posted automatically; open_float and close_variance are posted by open_drawer/close_drawer)';
  end if;
  if coalesce(p_amount_cents, 0) = 0 then raise exception 'amount must be non-zero'; end if;
  v_amt := case when p_kind = 'pay_out' then -abs(p_amount_cents) else abs(p_amount_cents) end;
  insert into cash_drawer_movements (business_id, branch_id, session_id, kind,
                                     amount_cents, staff_id, note)
  values (p_business, p_branch, app.open_drawer_session(p_branch), p_kind, v_amt, p_staff, p_note)
  returning * into v_row;
  return row_to_json(v_row);
end $$;

--
-- Name: record_onboarding_manual_evidence_v79(uuid, text, jsonb, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_onboarding_manual_evidence_v79(p_business uuid, p_item_key text, p_evidence jsonb, p_expected_version bigint, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_actor uuid:=auth.uid();v_hash text;v_replay jsonb;v_check public.business_onboarding_checklists%rowtype;v_item public.business_onboarding_items%rowtype;v_response jsonb;
begin
  if not app.is_platform_operator_v75() then raise exception 'platform operator access is required' using errcode='42501';end if;
  perform app.require_idempotency_key_v79(p_idempotency_key);
  if jsonb_typeof(p_evidence)<>'object' or p_evidence='{}'::jsonb then raise exception 'manual evidence must be a non-empty object' using errcode='22023';end if;
  v_hash:=app.v76_sha256_hex(jsonb_build_object('business',p_business,'item',p_item_key,'evidence',p_evidence,'version',p_expected_version)::text);
  v_replay:=app.v76_replay(v_actor,'manual_onboarding_evidence_v79',p_idempotency_key,v_hash);if v_replay is not null then return v_replay;end if;
  select * into v_check from public.business_onboarding_checklists where business_id=p_business and version=p_expected_version for update;
  if not found then raise exception 'onboarding version conflict' using errcode='40001';end if;
  select * into v_item from public.business_onboarding_items where business_id=p_business and item_key=p_item_key for update;
  if not found or v_item.verification_mode not in ('manual','sa_approval') then raise exception 'manual onboarding item was not found' using errcode='22023';end if;
  if v_item.verification_mode='sa_approval' and not app.is_super_admin() then
    raise exception 'go-live approval requires a super admin' using errcode='42501';end if;
  if v_item.status='blocked' then raise exception 'blocked onboarding evidence cannot be satisfied' using errcode='22023';end if;
  update public.business_onboarding_items set status='satisfied',evidence=p_evidence,
    satisfied_by=v_actor,satisfied_at=now(),waived_by=null,waived_at=null,waiver_reason=null,
    updated_at=now() where id=v_item.id;
  insert into public.business_onboarding_events(checklist_id,business_id,item_id,event_type,from_status,to_status,evidence,actor)
  values(v_check.id,p_business,v_item.id,'evidence_recorded',v_item.status,'satisfied',p_evidence,v_actor);
  perform app.recompute_onboarding_status_v79(p_business,v_actor);
  v_response:=jsonb_build_object('replayed',false,'onboarding',app.get_onboarding_core_v79(p_business));
  perform app.v76_store_receipt(v_actor,'manual_onboarding_evidence_v79',p_idempotency_key,v_hash,v_response);return v_response;
end
$$;

--
-- Name: record_payment(uuid, text, integer, uuid, uuid, uuid, uuid, text, uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_payment(p_business uuid, p_method text, p_amount_cents integer, p_sale uuid DEFAULT NULL::uuid, p_appointment uuid DEFAULT NULL::uuid, p_client uuid DEFAULT NULL::uuid, p_staff uuid DEFAULT NULL::uuid, p_kind text DEFAULT 'payment'::text, p_branch uuid DEFAULT NULL::uuid, p_reference text DEFAULT NULL::text, p_note text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_sale public.sales%rowtype;
  v_appointment public.appointments%rowtype;
  v_row public.payments%rowtype;
  v_branch uuid;
  v_client uuid;
  v_actor uuid := auth.uid();
  v_actor_staff uuid;
  v_payment_id uuid := gen_random_uuid();
  v_amount_bigint bigint;
  v_amount integer;
  v_key text;
  v_reference text;
  v_note text;
begin
  v_key := nullif(btrim(p_idempotency_key), '');
  v_reference := nullif(btrim(p_reference), '');
  v_note := nullif(btrim(p_note), '');
  if v_key is null or length(v_key) < 8 then
    raise exception 'payment idempotency key is required and must be at least 8 characters';
  end if;
  if p_kind = 'refund' then
    raise exception 'standalone refunds are disabled; use public.reverse_sale()'
      using errcode = 'feature_not_supported';
  end if;
  if p_kind not in ('payment', 'deposit', 'no_show_fee') then
    raise exception 'unsupported positive payment kind %', p_kind;
  end if;
  if p_method in ('credit', 'gift_card') then
    raise exception '% tender must use its proof-carrying internal workflow', p_method
      using errcode = 'feature_not_supported';
  end if;
  if p_method not in ('cash', 'card', 'paynow', 'bank_transfer', 'other') then
    raise exception 'unsupported payment method %', p_method;
  end if;
  if p_sale is null and p_appointment is null then
    raise exception 'a payment must reference a sale or an appointment';
  end if;
  if not app.has_perm(p_business, 'create_sales') then
    raise exception 'you do not have permission to take a payment in this business (create_sales)'
      using errcode = '42501';
  end if;

  -- Resolve attacker-controlled identifiers without locks, authorize their branch, then lock
  -- and re-read below. Unauthorized callers never reach a row or advisory lock.
  if p_sale is not null then
    select * into v_sale
      from public.sales
     where id = p_sale
       and business_id = p_business;
    if not found then
      raise exception 'sale does not belong to this business';
    end if;
  end if;
  if p_appointment is not null then
    select * into v_appointment
      from public.appointments
     where id = p_appointment
       and business_id = p_business;
    if not found then
      raise exception 'appointment does not belong to this business';
    end if;
  end if;

  if v_sale.id is not null and v_appointment.id is not null then
    if v_sale.appointment_id is distinct from v_appointment.id
       or v_sale.branch_id is distinct from v_appointment.branch_id
       or v_sale.client_id is distinct from v_appointment.client_id then
      raise exception 'payment sale and appointment do not describe one checkout';
    end if;
  end if;
  v_branch := coalesce(v_sale.branch_id, v_appointment.branch_id);
  v_client := coalesce(v_sale.client_id, v_appointment.client_id);
  if p_branch is not null and p_branch is distinct from v_branch then
    raise exception 'payment branch override conflicts with the sale/appointment branch';
  end if;
  if p_client is not null and p_client is distinct from v_client then
    raise exception 'payment client override conflicts with the sale/appointment client';
  end if;
  if not app.can_see_branch(p_business, v_branch) then
    raise exception 'you are not permitted to take payment for this branch scope'
      using errcode = '42501';
  end if;

  select s.id into v_actor_staff
    from public.staff s
   where s.business_id = p_business
     and s.user_id = v_actor
     and s.active
     and 'create_sales' = any (app.role_perms(s.role))
   order by case s.role when 'owner' then 0 when 'manager' then 1 else 2 end, s.created_at
   limit 1
   for update;
  if not found then
    raise exception 'active staff authorization is required to take payment'
      using errcode = '42501';
  end if;

  if p_sale is not null then
    select * into v_sale
      from public.sales
     where id = p_sale
       and business_id = p_business
     for update;
    if not found then
      raise exception 'sale no longer belongs to this business';
    end if;
  end if;
  if p_appointment is not null then
    select * into v_appointment
      from public.appointments
     where id = p_appointment
       and business_id = p_business
     for update;
    if not found then
      raise exception 'appointment no longer belongs to this business';
    end if;
  end if;

  if v_sale.id is not null and v_appointment.id is not null then
    if v_sale.appointment_id is distinct from v_appointment.id then
      raise exception 'payment sale and appointment do not describe the same checkout';
    end if;
    if v_sale.branch_id is distinct from v_appointment.branch_id then
      raise exception 'payment sale and appointment have contradictory branches';
    end if;
    if v_sale.client_id is distinct from v_appointment.client_id then
      raise exception 'payment sale and appointment have contradictory clients';
    end if;
  end if;

  v_branch := coalesce(v_sale.branch_id, v_appointment.branch_id);
  v_client := coalesce(v_sale.client_id, v_appointment.client_id);
  if p_branch is not null and p_branch is distinct from v_branch then
    raise exception 'payment branch override conflicts with the locked sale/appointment branch';
  end if;
  if p_client is not null and p_client is distinct from v_client then
    raise exception 'payment client override conflicts with the locked sale/appointment client';
  end if;
  if not app.has_perm(p_business, 'create_sales')
     or not app.can_see_branch(p_business, v_branch) then
    raise exception 'payment authorization changed while the operation was being locked'
      using errcode = '42501';
  end if;
  if v_sale.reversal_of is not null then
    raise exception 'payments cannot attach to a reversal sale';
  end if;
  if v_sale.id is not null and exists (
    select 1 from public.sales r
     where r.business_id = p_business
       and r.reversal_of = v_sale.id
  ) then
    raise exception 'positive payment is forbidden on a fully reversed sale';
  end if;
  if v_sale.id is null and v_appointment.id is not null and exists (
    select 1
      from public.sales s
      join public.sales r
        on r.business_id = s.business_id
       and r.reversal_of = s.id
     where s.business_id = p_business
       and s.appointment_id = v_appointment.id
  ) then
    raise exception 'positive appointment payment is forbidden after its sale was reversed';
  end if;
  if p_staff is not null and not exists (
    select 1 from public.staff s
     where s.id = p_staff
       and s.business_id = p_business
  ) then
    raise exception 'staff does not belong to this business';
  end if;
  if v_client is not null and not exists (
    select 1 from public.clients c
     where c.id = v_client
       and c.business_id = p_business
  ) then
    raise exception 'client does not belong to this business';
  end if;

  v_amount_bigint := abs(p_amount_cents::bigint);
  if coalesce(v_amount_bigint, 0) <= 0 or v_amount_bigint > 2147483647 then
    raise exception 'payment amount must be a positive 32-bit cent value';
  end if;
  v_amount := v_amount_bigint::integer;

  perform pg_advisory_xact_lock(
    hashtextextended(p_business::text || ':payment:' || v_key, 0)
  );

  perform set_config('app.payment_insert_id', v_payment_id::text, true);
  perform set_config('app.payment_write_scope', 'record_payment', true);
  insert into public.payments (
    id, business_id, branch_id, sale_id, appointment_id, client_id, staff_id,
    method, kind, amount_cents, reference, note, idempotency_key, created_by
  )
  values (
    v_payment_id, p_business, v_branch, p_sale, p_appointment, v_client, p_staff,
    p_method, p_kind, v_amount, v_reference, v_note,
    v_key, v_actor
  )
  on conflict (business_id, idempotency_key) where idempotency_key is not null
    do nothing
  returning * into v_row;
  perform set_config('app.payment_insert_id', '', true);
  perform set_config('app.payment_write_scope', '', true);

  if v_row.id is null then
    select * into v_row
      from public.payments
     where business_id = p_business
       and idempotency_key = v_key;
    if not found
       or (v_row.business_id, v_row.branch_id, v_row.sale_id, v_row.appointment_id,
           v_row.client_id, v_row.staff_id, v_row.method, v_row.kind,
           v_row.amount_cents, v_row.reference, v_row.note, v_row.created_by)
          is distinct from
          (p_business, v_branch, p_sale, p_appointment,
           v_client, p_staff, p_method, p_kind, v_amount,
           v_reference, v_note, v_actor) then
      raise exception 'payment idempotency key conflicts with a different immutable request'
        using errcode = '23505';
    end if;
  end if;

  return row_to_json(v_row);
end $$;

--
-- Name: record_product_interaction_v100(text, uuid, uuid, uuid, text, timestamp with time zone, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_product_interaction_v100(p_event_name text, p_business uuid, p_branch uuid, p_session_id uuid, p_idempotency_key text, p_occurred_at timestamp with time zone DEFAULT now(), p_context jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid:=auth.uid();
  v_taxonomy public.product_adoption_event_taxonomy_v100%rowtype;
  v_context jsonb:=coalesce(p_context,'{}'::jsonb);
  v_key text:=btrim(coalesce(p_idempotency_key,''));
  v_hash text;
  v_existing public.product_adoption_events_v100%rowtype;
  v_id uuid:=gen_random_uuid();
begin
  if v_actor is null then
    raise exception 'authenticated interaction session is required'
      using errcode='28000';
  end if;
  select taxonomy.* into v_taxonomy
  from public.product_adoption_event_taxonomy_v100 taxonomy
  where taxonomy.event_name=p_event_name
    and taxonomy.source_authority='client';
  if not found then
    raise exception 'event is not in the client interaction allowlist'
      using errcode='22023';
  end if;
  if char_length(v_key) not between 8 and 200 then
    raise exception 'idempotency key must contain 8..200 characters'
      using errcode='22023';
  end if;
  if p_occurred_at is null
     or p_occurred_at<clock_timestamp()-interval '24 hours'
     or p_occurred_at>clock_timestamp()+interval '5 minutes' then
    raise exception 'interaction time is outside the accepted window'
      using errcode='22023';
  end if;
  if v_taxonomy.business_scope_required and p_business is null then
    raise exception 'interaction requires a business scope'
      using errcode='22023';
  end if;
  if jsonb_typeof(v_context)<>'object'
     or octet_length(v_context::text)>2048
     or exists(
       select 1
       from pg_catalog.jsonb_object_keys(v_context) as context_key(key)
       where context_key.key not in (
         'action_key','entry_point','locale','device_class','install_mode',
         'surface_version','outcome','surface_key','promotion_id','query_shape'
       )
     )
     or exists(
       select 1
       from pg_catalog.jsonb_each(v_context) as context_item(key,value)
       where pg_catalog.jsonb_typeof(context_item.value)
               not in ('string','number','boolean','null')
          or (
            pg_catalog.jsonb_typeof(context_item.value)='string'
            and char_length(context_item.value#>>'{}')>80
          )
     ) then
    raise exception
      'context may contain only short privacy-safe allowlisted dimensions'
      using errcode='22023';
  end if;

  if v_taxonomy.actor_scope='customer' then
    if p_business is not null and not exists(
      select 1
      from public.customer_links customer_link
      where customer_link.business_id=p_business
        and customer_link.auth_user_id=v_actor
        and customer_link.state='verified'
    ) then
      raise exception 'verified customer relationship is required'
        using errcode='42501';
    end if;
    if p_branch is not null and not exists(
      select 1
      from public.branches branch
      where branch.id=p_branch and branch.business_id=p_business
    ) then
      raise exception 'branch does not belong to this business'
        using errcode='42501';
    end if;
  elsif v_taxonomy.actor_scope='merchant' then
    if not app.is_salon_member(p_business) then
      raise exception 'active merchant membership is required'
        using errcode='42501';
    end if;
    if v_taxonomy.required_module is not null
       and (
         (
           v_taxonomy.required_mode='r'
           and not app.can_module_read(
             p_business,v_taxonomy.required_module
           )
         )
         or (
           v_taxonomy.required_mode='rw'
           and not app.can_module_write(
             p_business,v_taxonomy.required_module
           )
         )
       ) then
      raise exception 'module access does not permit this interaction'
        using errcode='42501';
    end if;
    if p_branch is not null
       and not app.can_see_branch(p_business,p_branch) then
      raise exception 'branch is outside the merchant scope'
        using errcode='42501';
    end if;
  else
    raise exception 'unsupported client actor scope' using errcode='22023';
  end if;

  v_hash:=pg_catalog.encode(
    extensions.digest(
      pg_catalog.convert_to(
        pg_catalog.concat_ws(
          '|','v100.client-interaction',p_event_name,
          coalesce(p_business::text,''),coalesce(p_branch::text,''),
          coalesce(p_session_id::text,''),p_occurred_at::text,v_context::text
        ),
        'UTF8'
      ),
      'sha256'
    ),
    'hex'
  );
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'v100:interaction:'||v_actor::text||':'||v_key,0
    )
  );
  select event_row.* into v_existing
  from public.product_adoption_events_v100 event_row
  where event_row.actor_user_id=v_actor
    and event_row.idempotency_key=v_key;
  if found then
    if v_existing.request_hash<>v_hash then
      raise exception 'idempotency key conflicts with another interaction'
        using errcode='23505';
    end if;
    return pg_catalog.jsonb_build_object(
      'event_id',v_existing.id,'event_name',v_existing.event_name,
      'recording_status','accepted_interaction_only',
      'business_outcome_asserted',false,'replayed',true
    );
  end if;
  insert into public.product_adoption_events_v100(
    id,event_name,source_authority,actor_scope,actor_user_id,
    business_id,branch_id,session_id,event_context,idempotency_key,
    request_hash,occurred_at
  ) values(
    v_id,p_event_name,'client',v_taxonomy.actor_scope,v_actor,
    p_business,p_branch,p_session_id,v_context,v_key,v_hash,p_occurred_at
  );
  return pg_catalog.jsonb_build_object(
    'event_id',v_id,'event_name',p_event_name,
    'recording_status','accepted_interaction_only',
    'business_outcome_asserted',false,'replayed',false
  );
end
$$;

--
-- Name: FUNCTION record_product_interaction_v100(p_event_name text, p_business uuid, p_branch uuid, p_session_id uuid, p_idempotency_key text, p_occurred_at timestamp with time zone, p_context jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.record_product_interaction_v100(p_event_name text, p_business uuid, p_branch uuid, p_session_id uuid, p_idempotency_key text, p_occurred_at timestamp with time zone, p_context jsonb) IS 'Records only allowlisted client interactions and never asserts that the requested business outcome completed.';

--
-- Name: record_product_interactions_batch_v255(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_product_interactions_batch_v255(p_events jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid:=auth.uid();
  v_event jsonb;
  v_results jsonb:='[]'::jsonb;
  v_accepted integer:=0;
  v_replayed integer:=0;
  v_rejected integer:=0;
  v_outcome jsonb;
  v_count integer;
begin
  if v_actor is null then
    raise exception 'authenticated interaction session is required'
      using errcode='28000';
  end if;
  if p_events is null or jsonb_typeof(p_events)<>'array' then
    raise exception 'a batch must be a JSON array of interaction events'
      using errcode='22023';
  end if;
  select count(*)::integer into v_count
  from pg_catalog.jsonb_array_elements(p_events);
  if v_count=0 then
    raise exception 'a batch must contain at least one interaction event'
      using errcode='22023';
  end if;
  if v_count>50 then
    raise exception 'a batch may contain at most 50 interaction events'
      using errcode='22023';
  end if;
  if octet_length(p_events::text)>65536 then
    raise exception 'batch payload exceeds the accepted size'
      using errcode='22023';
  end if;

  for v_event in
    select value from pg_catalog.jsonb_array_elements(p_events) as element(value)
  loop
    begin
      if jsonb_typeof(v_event)<>'object' then
        raise exception 'each batch entry must be an object'
          using errcode='22023';
      end if;
      v_outcome:=public.record_product_interaction_v100(
        v_event->>'event_name',
        nullif(v_event->>'business_id','')::uuid,
        nullif(v_event->>'branch_id','')::uuid,
        nullif(v_event->>'session_id','')::uuid,
        v_event->>'idempotency_key',
        coalesce(
          nullif(v_event->>'occurred_at','')::timestamptz,clock_timestamp()
        ),
        coalesce(v_event->'context','{}'::jsonb)
      );
      if coalesce((v_outcome->>'replayed')::boolean,false) then
        v_replayed:=v_replayed+1;
      else
        v_accepted:=v_accepted+1;
      end if;
      v_results:=v_results||pg_catalog.jsonb_build_object(
        'idempotency_key',v_event->>'idempotency_key',
        'status',case when coalesce((v_outcome->>'replayed')::boolean,false)
          then 'replayed' else 'accepted' end
      );
    exception when others then
      v_rejected:=v_rejected+1;
      v_results:=v_results||pg_catalog.jsonb_build_object(
        'idempotency_key',v_event->>'idempotency_key',
        'status','rejected',
        'errcode',pg_catalog.upper(sqlstate)
      );
    end;
  end loop;

  return pg_catalog.jsonb_build_object(
    'submitted',v_count,'accepted',v_accepted,'replayed',v_replayed,
    'rejected',v_rejected,'results',v_results,
    'recording_status','accepted_interaction_only',
    'business_outcome_asserted',false
  );
end
$$;

--
-- Name: FUNCTION record_product_interactions_batch_v255(p_events jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.record_product_interactions_batch_v255(p_events jsonb) IS 'Batched wrapper over record_product_interaction_v100. Every privacy, authorization and idempotency rule stays in the single-event function; one bad event never discards the batch.';

--
-- Name: record_quick_sale(uuid, integer, text, uuid, uuid, uuid, text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_quick_sale(p_business uuid, p_amount_cents integer, p_method text, p_client uuid DEFAULT NULL::uuid, p_staff uuid DEFAULT NULL::uuid, p_branch uuid DEFAULT NULL::uuid, p_note text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text, p_paid boolean DEFAULT true) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_actor_staff uuid;
  v_branch uuid;
  v_method text := lower(nullif(btrim(p_method), ''));
  v_note text := nullif(btrim(p_note), '');
  v_key text := nullif(btrim(p_idempotency_key), '');
  v_paid boolean := coalesce(p_paid, true);
  v_operation_id uuid := gen_random_uuid();
  v_operation public.financial_operations%rowtype;
  v_payload jsonb;
  v_sale public.sales%rowtype;
  v_payment jsonb;
  v_result jsonb;
begin
  if v_key is null or length(v_key) < 8 then
    raise exception 'quick-sale idempotency key is required and must be at least 8 characters';
  end if;
  if coalesce(p_amount_cents, 0) <= 0 then
    raise exception 'a quick sale must have a positive amount';
  end if;
  if v_method not in ('cash', 'card', 'paynow', 'bank_transfer', 'other') then
    raise exception 'unsupported quick-sale payment method %', p_method;
  end if;
  if not app.has_perm(p_business, 'create_sales') then
    raise exception 'you do not have permission to record a sale in this business (create_sales)'
      using errcode = '42501';
  end if;

  v_branch := coalesce(p_branch, app.default_branch(p_business));
  if v_branch is null or not exists (
    select 1 from public.branches b
     where b.id = v_branch and b.business_id = p_business and b.active
  ) then
    raise exception 'quick-sale branch is missing, inactive, or belongs to another business';
  end if;
  if not app.can_see_branch(p_business, v_branch) then
    raise exception 'you are not permitted to record a quick sale for this branch scope'
      using errcode = '42501';
  end if;
  if p_client is not null and not exists (
    select 1 from public.clients c where c.id = p_client and c.business_id = p_business
  ) then
    raise exception 'quick-sale client does not belong to this business';
  end if;
  if p_staff is not null and not exists (
    select 1 from public.staff s
     where s.id = p_staff and s.business_id = p_business and s.active
  ) then
    raise exception 'quick-sale staff is inactive or does not belong to this business';
  end if;

  select s.id into v_actor_staff
    from public.staff s
   where s.business_id = p_business
     and s.user_id = v_actor
     and s.active
     and 'create_sales' = any (app.role_perms(s.role))
   order by case s.role when 'owner' then 0 when 'manager' then 1 else 2 end, s.created_at
   limit 1
   for update;
  if not found then
    raise exception 'active staff authorization is required to record a quick sale'
      using errcode = '42501';
  end if;
  perform 1 from public.branches b
   where b.id = v_branch and b.business_id = p_business and b.active
   for update;
  if not found then
    raise exception 'quick-sale branch changed while authorization was being locked';
  end if;
  if p_client is not null then
    perform 1 from public.clients c
     where c.id = p_client and c.business_id = p_business for update;
    if not found then
      raise exception 'quick-sale client changed while authorization was being locked';
    end if;
  end if;
  if p_staff is not null then
    perform 1 from public.staff s
     where s.id = p_staff and s.business_id = p_business and s.active for update;
    if not found then
      raise exception 'quick-sale staff changed while authorization was being locked';
    end if;
  end if;
  if not app.has_perm(p_business, 'create_sales')
     or not app.can_see_branch(p_business, v_branch) then
    raise exception 'quick-sale authorization changed while the operation was being locked'
      using errcode = '42501';
  end if;

  v_payload := jsonb_build_object(
    'business_id', p_business,
    'branch_id', v_branch,
    'client_id', p_client,
    'staff_id', p_staff,
    'actor', v_actor,
    'amount_cents', p_amount_cents,
    'method', v_method,
    'note', v_note,
    'paid', v_paid
  );

  select * into v_operation
    from public.financial_operations fo
   where fo.business_id = p_business
     and fo.operation_type = 'quick_sale'
     and fo.idempotency_key = v_key;
  if found then
    if (v_operation.branch_id, v_operation.actor, v_operation.request_payload,
        v_operation.request_hash)
       is distinct from
       (v_branch, v_actor, v_payload, md5(v_payload::text)) then
      raise exception 'quick-sale idempotency key conflicts with a different immutable request'
        using errcode = '23505';
    end if;
    if v_operation.status <> 'completed' or v_operation.sale_id is null
       or v_operation.result is null then
      raise exception 'quick-sale operation is reserved but incomplete'
        using errcode = '55000';
    end if;
    if not exists (
      select 1 from public.sales s
       where s.id = v_operation.sale_id
         and s.business_id = p_business
         and s.branch_id = v_branch
         and s.client_id is not distinct from p_client
         and s.staff_id is not distinct from p_staff
         and s.kind = 'quick_sale'
         and s.amount_cents = p_amount_cents
         and s.note is not distinct from v_note
    ) or (v_paid and not exists (
      select 1 from public.payments p
       where p.id = (v_operation.result->>'payment_id')::uuid
         and p.business_id = p_business
         and p.sale_id = v_operation.sale_id
         and p.method = v_method
         and p.kind = 'payment'
         and p.amount_cents = p_amount_cents
         and p.created_by = v_actor
    )) or (not v_paid and v_operation.result ? 'payment_id') then
      raise exception 'completed quick sale is missing exact sale/payment proof'
        using errcode = 'XX001';
    end if;
    return (v_operation.result || jsonb_build_object('replayed', true))::json;
  end if;

  perform set_config('app.financial_operation_insert_id', v_operation_id::text, true);
  insert into public.financial_operations(
    id, business_id, branch_id, sale_id, operation_type, actor,
    idempotency_key, request_payload, request_hash
  ) values (
    v_operation_id, p_business, v_branch, null, 'quick_sale', v_actor,
    v_key, v_payload, md5(v_payload::text)
  )
  on conflict (business_id, operation_type, idempotency_key) do nothing
  returning * into v_operation;
  perform set_config('app.financial_operation_insert_id', '', true);

  if v_operation.id is null then
    select * into v_operation from public.financial_operations fo
     where fo.business_id = p_business
       and fo.operation_type = 'quick_sale'
       and fo.idempotency_key = v_key;
    if not found
       or (v_operation.branch_id, v_operation.actor, v_operation.request_payload,
           v_operation.request_hash)
          is distinct from
          (v_branch, v_actor, v_payload, md5(v_payload::text)) then
      raise exception 'quick-sale idempotency reservation conflicts with a different immutable request'
        using errcode = '23505';
    end if;
    if v_operation.status = 'completed' and v_operation.result is not null then
      -- Re-enter the completed replay path so a concurrent winner receives the same exact
      -- sale/payment proof checks as a later replay, rather than trusting the parent alone.
      return public.record_quick_sale(
        p_business, p_amount_cents, v_method, p_client, p_staff, v_branch,
        v_note, v_key, v_paid
      );
    end if;
    raise exception 'quick-sale operation is already reserved but incomplete'
      using errcode = '55000';
  end if;

  insert into public.sales(
    business_id, client_id, kind, amount_cents, branch_id, staff_id, note
  ) values (
    p_business, p_client, 'quick_sale', p_amount_cents, v_branch, p_staff, v_note
  ) returning * into v_sale;

  if v_paid then
    v_payment := public.record_payment(
      p_business => p_business,
      p_method => v_method,
      p_amount_cents => p_amount_cents,
      p_sale => v_sale.id,
      p_client => p_client,
      p_staff => p_staff,
      p_kind => 'payment',
      p_branch => v_branch,
      p_reference => 'quick sale checkout',
      p_note => v_note,
      p_idempotency_key => 'v20:' || v_operation.id || ':payment'
    )::jsonb;
  end if;

  v_result := jsonb_build_object(
    'sale', to_jsonb(v_sale),
    'replayed', false,
    'operation_id', v_operation.id
  );
  if v_paid then
    v_result := v_result || jsonb_build_object(
      'payment', v_payment,
      'payment_id', v_payment->>'id'
    );
  else
    v_result := v_result || jsonb_build_object('payment', null);
  end if;

  perform set_config('app.financial_operation_complete_id', v_operation.id::text, true);
  update public.financial_operations
     set sale_id = v_sale.id,
         status = 'completed',
         result = v_result,
         completed_at = now()
   where id = v_operation.id and status = 'reserved';
  perform set_config('app.financial_operation_complete_id', '', true);
  if not found then
    raise exception 'failed to complete reserved quick-sale operation'
      using errcode = '55000';
  end if;

  return v_result::json;
end $$;

--
-- Name: record_sale_by_phone(uuid, text, integer, text, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_sale_by_phone(p_business uuid, p_phone text, p_amount_cents integer, p_kind text DEFAULT 'quick_sale'::text, p_note text DEFAULT NULL::text, p_staff uuid DEFAULT NULL::uuid, p_idem text DEFAULT NULL::text) RETURNS json
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  raise exception 'Legacy phone-sale signature is retired; use the hardened nine-argument operation'
    using errcode='42501';
end
$$;

--
-- Name: record_sale_by_phone(uuid, text, integer, text, text, uuid, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_sale_by_phone(p_business uuid, p_phone text, p_amount_cents integer, p_kind text, p_note text, p_staff uuid, p_idem text, p_branch uuid, p_method text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_norm text;
  v_actor_staff uuid;
  v_client public.clients%rowtype;
  v_financial jsonb;
  v_sale_id uuid;
  v_payment_id uuid;
  v_points_earned integer;
  v_points_after integer;
  v_note text;
begin
  if not app.has_perm(p_business,'create_sales')
     or not app.can_module_read(p_business,'clients') then
    raise exception 'clients read and create-sales authorization is required' using errcode='42501';
  end if;
  select staff.id into v_actor_staff from public.staff staff
   where staff.business_id=p_business and staff.user_id=auth.uid() and staff.active limit 1;
  if not found then raise exception 'an active staff identity is required' using errcode='42501'; end if;
  if p_staff is not null and p_staff is distinct from v_actor_staff then
    raise exception 'sale staff attribution must match the authenticated staff identity'
      using errcode='42501';
  end if;
  if p_idem is null or char_length(btrim(p_idem)) not between 8 and 200 then
    raise exception 'an idempotency key of 8 to 200 characters is required' using errcode='22023';
  end if;
  if p_amount_cents is null or p_amount_cents<=0 then
    raise exception 'Enter the amount paid.' using errcode='22023';
  end if;
  if p_kind is distinct from 'quick_sale' then
    raise exception 'Quick earn only accepts quick-sale purchases' using errcode='22023';
  end if;
  if p_branch is null then
    raise exception 'Choose the branch where payment was received' using errcode='22023';
  end if;
  if lower(coalesce(btrim(p_method),'')) not in ('cash','card','paynow','other') then
    raise exception 'Choose Cash, Card, PayNow or Other' using errcode='22023';
  end if;
  if p_note is not null and char_length(p_note)>1000 then
    raise exception 'sale note is too long' using errcode='22023';
  end if;
  v_norm:=app.norm_phone(p_phone);
  if v_norm is null then raise exception 'Enter a valid 8-digit mobile number.' using errcode='22023'; end if;
  select * into v_client from public.clients
   where business_id=p_business and phone_norm=v_norm;
  if not found then raise exception 'No customer with that number. Add them first.' using errcode='22023'; end if;
  v_note:=coalesce(p_note,'till: '||v_norm);
  v_financial:=public.record_quick_sale(
    p_business=>p_business,p_amount_cents=>p_amount_cents,
    p_method=>lower(btrim(p_method)),p_client=>v_client.id,p_staff=>v_actor_staff,
    p_branch=>p_branch,p_note=>v_note,p_idempotency_key=>btrim(p_idem),p_paid=>true
  )::jsonb;
  v_sale_id:=nullif(v_financial #>> '{sale,id}','')::uuid;
  v_payment_id:=nullif(v_financial->>'payment_id','')::uuid;
  if v_sale_id is null or v_payment_id is null then
    raise exception 'Quick earn did not produce exact sale and payment proof' using errcode='XX001';
  end if;
  select coalesce(sum(points),0) into v_points_earned from public.points_ledger
   where business_id=p_business and client_id=v_client.id and sale_id=v_sale_id;
  v_points_after := app.client_points_balance_v409(p_business, v_client.id);
  return json_build_object(
    'status',case when coalesce((v_financial->>'replayed')::boolean,false)
                  then 'duplicate_ignored' else 'ok' end,
    'sale_id',v_sale_id,'payment_id',v_payment_id,'client_id',v_client.id,
    'full_name',v_client.full_name,'amount_cents',p_amount_cents,'kind','quick_sale',
    'branch_id',p_branch,'payment_method',lower(btrim(p_method)),
    'points_earned',case when coalesce((v_financial->>'replayed')::boolean,false)
                         then 0 else v_points_earned end,
    'points',v_points_after
  );
end
$$;

--
-- Name: record_sv_topup_sale(uuid, uuid, uuid, uuid, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_sv_topup_sale(p_business uuid, p_branch uuid, p_client uuid, p_plan_version uuid, p_payment jsonb, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  pv public.sv_plan_versions%rowtype; v_plan_active boolean; v_state text; v_biz_synth boolean; v_client_synth boolean;
  v_biz_currency text;
  v_method text; v_currency text; v_amount integer; v_reference text; v_ref_norm text; v_staff_confirmed boolean;
  v_confirmation_mode text;
  v_hash text; v_existing public.sv_operations%rowtype;
  v_account uuid; v_outstanding integer;
  v_op uuid := gen_random_uuid(); v_paid_lot uuid := gen_random_uuid(); v_bonus_lot uuid; v_payment_id uuid := gen_random_uuid();
  v_paid_seq bigint; v_bonus_seq bigint; v_paid_expiry timestamptz; v_bonus_expiry timestamptz;
  v_result jsonb;
begin
  -- permission + branch
  if not app.can_sell_topups(p_business) then raise exception 'not permitted to sell top-ups for this business' using errcode = '42501'; end if;
  if not app.can_see_branch(p_business, p_branch) then raise exception 'no access to this branch' using errcode = '42501'; end if;
  if not exists (select 1 from public.branches b where b.id = p_branch and b.business_id = p_business and b.active) then
    raise exception 'branch is not part of this business or is inactive' using errcode = '22023'; end if;

  -- payment shape
  if p_payment is null or jsonb_typeof(p_payment) <> 'object' then raise exception 'payment must be a JSON object' using errcode = '22023'; end if;
  v_method := lower(btrim(coalesce(p_payment->>'method','')));
  if v_method not in ('cash','card_terminal','paynow','manual','test') then raise exception 'invalid payment method' using errcode = '22023'; end if;
  if not app.sv_jsonb_is_int(p_payment->'amount_cents') then raise exception 'payment amount_cents must be a whole number' using errcode = '22023'; end if;
  v_amount := (p_payment->>'amount_cents')::integer;
  v_currency := upper(btrim(coalesce(p_payment->>'currency','')));
  v_reference := nullif(btrim(p_payment->>'reference'), '');
  v_ref_norm := lower(v_reference);
  v_staff_confirmed := coalesce((p_payment->>'staff_confirmed')::boolean, false);

  -- customer + plan version
  select c.is_synthetic into v_client_synth from public.clients c where c.id = p_client and c.business_id = p_business;
  if not found then raise exception 'customer not in this business' using errcode = '22023'; end if;
  select * into pv from public.sv_plan_versions where id = p_plan_version and business_id = p_business;
  if not found then raise exception 'plan version not in this business' using errcode = '22023'; end if;
  select active into v_plan_active from public.sv_plans where id = pv.plan_id and business_id = p_business;
  if not coalesce(v_plan_active,false) then raise exception 'plan is retired' using errcode = '22023'; end if;
  if pv.effective_at is not null and pv.effective_at > now() then raise exception 'plan version is not yet effective' using errcode = '22023'; end if;
  if p_plan_version is distinct from app.current_sellable_sv_version(p_business, pv.plan_id) then raise exception 'not_current_version: only the current sellable plan version may be sold' using errcode = '22023'; end if;
  if pv.eligible_branch_ids is not null and not (p_branch = any(pv.eligible_branch_ids)) then raise exception 'branch is not eligible for this plan' using errcode = '22023'; end if;

  -- authority + synthetic gate
  select is_synthetic, currency into v_biz_synth, v_biz_currency from public.businesses where id = p_business;
  select coalesce(state,'unbuilt') into v_state from public.sv_authority where business_id = p_business and asset = 'stored_value';
  v_state := coalesce(v_state,'unbuilt');
  if v_state = 'unbuilt' then
    raise exception 'sv_not_ready: stored value is not ready for top-ups' using errcode = '22023';
  elsif v_state in ('shadow_testing','ready_for_cutover') then
    if not (coalesce(v_biz_synth,false) and coalesce(v_client_synth,false)) then raise exception 'only synthetic test top-ups are permitted in %', v_state using errcode = '22023'; end if;
    if v_method <> 'test' then raise exception 'only the test payment method is permitted in synthetic testing' using errcode = '22023'; end if;
  elsif v_state = 'live' then
    if coalesce(v_biz_synth,false) or coalesce(v_client_synth,false) then raise exception 'a synthetic entity cannot transact on a live business' using errcode = '22023'; end if;
    if v_method = 'test' then raise exception 'the test payment method is not permitted on a live business' using errcode = '22023'; end if;
  else
    raise exception 'stored value is % for this business', v_state using errcode = '22023';
  end if;

  -- earn pause
  if app.sv_pause_active(p_business, 'stored_value', 'earn') then raise exception 'sv_paused: stored-value earns are paused' using errcode = '22023'; end if;

  -- currency + amount + reference/attestation
  if v_currency <> upper(coalesce(v_biz_currency,'SGD')) then raise exception 'currency_mismatch: payment currency must be %', upper(coalesce(v_biz_currency,'SGD')) using errcode = '22023'; end if;
  if v_amount <> pv.price_cents then raise exception 'payment amount must equal the plan price (%.0f cents)', pv.price_cents::numeric using errcode = '22023'; end if;
  if v_method in ('card_terminal','paynow','manual') then
    if v_reference is null then raise exception 'a payment reference is required for this method' using errcode = '22023'; end if;
    if not v_staff_confirmed then raise exception 'explicit staff confirmation is required for this method' using errcode = '22023'; end if;
  end if;

  -- points policy (correction / directive §5)
  if pv.topup_purchase_earns_points then
    return jsonb_build_object('status','policy_not_yet_supported','reason','points-on-topup is not supported in this pilot');
  end if;

  -- idempotency envelope
  v_hash := app.ps1b_sha256(jsonb_build_object('op','topup_sale','business',p_business,'branch',p_branch,'client',p_client,
    'plan_version',p_plan_version,'method',v_method,'amount',v_amount,'currency',v_currency,'reference',v_ref_norm)::text);
  perform pg_advisory_xact_lock(hashtextextended('v66:topupsale:'||p_business::text||':'||p_idempotency_key::text, 0));
  select * into v_existing from public.sv_operations o
   where o.business_id = p_business and o.operation_type = 'topup' and o.idempotency_key = p_idempotency_key for update;
  if found then
    if v_existing.request_hash <> v_hash then raise exception 'idempotency key conflicts with a different top-up request' using errcode = '22023'; end if;
    return v_existing.result;
  end if;

  -- account lock + limits (max-balance on TOTAL OUTSTANDING incl reserved)
  perform pg_advisory_xact_lock(hashtextextended('v66:acct:'||p_business::text||':'||p_client::text, 0));
  v_account := app.sv_ensure_account(p_business, p_client);
  perform 1 from public.sv_accounts where id = v_account and business_id = p_business for update;

  -- FINALISATION RE-VALIDATION (close authority-state + version TOCTOU): re-read the authority row and the
  -- current sellable version under READ COMMITTED after the account lock, so a concurrent authority
  -- transition or a newly-effective version committed since the early checks cannot slip a mint through a
  -- stale state. No yield point exists between this re-check and the inserts below.
  select coalesce(state,'unbuilt') into v_state from public.sv_authority where business_id = p_business and asset = 'stored_value';
  v_state := coalesce(v_state,'unbuilt');
  if v_state = 'unbuilt' then
    raise exception 'sv_not_ready: stored value is not ready for top-ups' using errcode = '22023';
  elsif v_state in ('shadow_testing','ready_for_cutover') then
    if not (coalesce(v_biz_synth,false) and coalesce(v_client_synth,false)) or v_method <> 'test' then
      raise exception 'top-up is no longer permitted under the current authority state (%)', v_state using errcode = '22023'; end if;
  elsif v_state = 'live' then
    if coalesce(v_biz_synth,false) or coalesce(v_client_synth,false) or v_method = 'test' then
      raise exception 'top-up is no longer permitted under the current authority state (live)' using errcode = '22023'; end if;
  else
    raise exception 'stored value is % for this business', v_state using errcode = '22023';
  end if;
  if p_plan_version is distinct from app.current_sellable_sv_version(p_business, pv.plan_id) then
    raise exception 'not_current_version: the sellable plan version changed before finalisation' using errcode = '22023';
  end if;

  if pv.max_balance_cents is not null then
    v_outstanding := app.sv_total_outstanding(p_business, v_account);
    if v_outstanding + (pv.price_cents + pv.bonus_cents) > pv.max_balance_cents then
      raise exception 'max_balance_exceeded: this top-up would exceed the customer maximum balance' using errcode = '22023'; end if;
  end if;
  if pv.purchase_window_days is not null and pv.purchase_max_in_window is not null
     and app.sv_topup_count(p_business, v_account, pv.plan_id, now() - (pv.purchase_window_days||' days')::interval) >= pv.purchase_max_in_window then
    raise exception 'purchase_window_cap: purchase frequency limit reached' using errcode = '22023'; end if;
  if pv.purchase_lifetime_cap is not null
     and app.sv_topup_count(p_business, v_account, pv.plan_id, null) >= pv.purchase_lifetime_cap then
    raise exception 'lifetime_cap: lifetime purchase cap reached' using errcode = '22023'; end if;
  -- non-cash reference pre-check (partial unique index is the hard guarantee)
  if v_method <> 'cash' and v_ref_norm is not null
     and exists (select 1 from public.sv_topup_payments where business_id = p_business and method = v_method and reference_norm = v_ref_norm) then
    raise exception 'duplicate_payment_reference: this payment reference has already funded a top-up' using errcode = '22023'; end if;

  -- MINT (paid + bonus lots, independent expiry, immutable plan_version_id preserved)
  v_confirmation_mode := case v_method when 'cash' then 'cash_received' when 'test' then 'synthetic_test' else 'staff_attested' end;
  v_paid_seq := nextval('app.sv_earned_seq');
  v_paid_expiry := case when pv.paid_expiry_days is null then null else now() + (pv.paid_expiry_days||' days')::interval end;
  if pv.bonus_cents > 0 then
    v_bonus_lot := gen_random_uuid(); v_bonus_seq := nextval('app.sv_earned_seq');
    v_bonus_expiry := case when pv.bonus_expiry_days is null then null else now() + (pv.bonus_expiry_days||' days')::interval end;
  end if;

  v_result := jsonb_build_object(
    'status','ok','operation_id',v_op,'account_id',v_account,'payment_id',v_payment_id,'plan_version_id',p_plan_version,
    'paid_lot', jsonb_build_object('lot_id',v_paid_lot,'class','paid','minted_cents',pv.price_cents,'expiry_key',v_paid_expiry),
    'bonus_lot', case when pv.bonus_cents > 0 then jsonb_build_object('lot_id',v_bonus_lot,'class','bonus','minted_cents',pv.bonus_cents,'expiry_key',v_bonus_expiry) else null end,
    'cash_collected_cents', v_amount, 'paid_value_issued_cents', pv.price_cents, 'bonus_value_issued_cents', pv.bonus_cents,
    'total_value_issued_cents', pv.price_cents + pv.bonus_cents, 'account_total_after_cents', app.sv_total_outstanding(p_business, v_account) + pv.price_cents + pv.bonus_cents,
    'payment', jsonb_build_object('method',v_method,'reference',v_reference,'confirmation_mode',v_confirmation_mode,'currency',v_currency),
    'authority_state', v_state, 'spendable', (v_state = 'live'),
    'accounting', jsonb_build_object('cash_collected_cents', v_amount, 'paid_value_liability_cents', pv.price_cents, 'bonus_value_promotional_exposure_cents', pv.bonus_cents, 'is_revenue', false));

  insert into public.sv_operations(id,business_id,operation_type,idempotency_key,request_hash,actor,result)
  values (v_op,p_business,'topup',p_idempotency_key,v_hash,v_actor,v_result);
  insert into public.sv_lots(id,business_id,account_id,operation_id,class,minted_cents,expiry_key,earned_seq,plan_version_id)
  values (v_paid_lot,p_business,v_account,v_op,'paid',pv.price_cents,v_paid_expiry,v_paid_seq,p_plan_version);
  insert into public.sv_lot_movements(business_id,account_id,lot_id,operation_id,kind,cents)
  values (p_business,v_account,v_paid_lot,v_op,'issue',pv.price_cents);
  if pv.bonus_cents > 0 then
    insert into public.sv_lots(id,business_id,account_id,operation_id,class,minted_cents,expiry_key,earned_seq,plan_version_id)
    values (v_bonus_lot,p_business,v_account,v_op,'bonus',pv.bonus_cents,v_bonus_expiry,v_bonus_seq,p_plan_version);
    insert into public.sv_lot_movements(business_id,account_id,lot_id,operation_id,kind,cents)
    values (p_business,v_account,v_bonus_lot,v_op,'issue',pv.bonus_cents);
  end if;
  insert into public.sv_topup_payments(id,business_id,branch_id,client_id,operation_id,plan_version_id,amount_cents,currency,method,reference,confirmation_mode,actor,confirmed_at)
  values (v_payment_id,p_business,p_branch,p_client,v_op,p_plan_version,v_amount,v_currency,v_method,v_reference,v_confirmation_mode,v_actor,now());
  insert into public.sv_topup_payment_events(business_id,payment_id,event_type,operation_id,actor,reason)
  values (p_business,v_payment_id,'confirmed',v_op,v_actor,'top-up confirmed at sale');
  insert into public.audit_log(business_id,actor,action,entity,entity_id,detail)
  values (p_business,v_actor,'SV_TOPUP_SALE','sv_accounts',v_account,jsonb_build_object(
    'operation_id',v_op,'payment_id',v_payment_id,'plan_version_id',p_plan_version,'method',v_method,
    'paid_cents',pv.price_cents,'bonus_cents',pv.bonus_cents,'confirmation_mode',v_confirmation_mode));

  return v_result;
end $$;

--
-- Name: redeem_customer_birthday_benefit(uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.redeem_customer_birthday_benefit(p_business_id uuid, p_client_id uuid, p_branch_id uuid, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_entitlement public.customer_birthday_entitlements%rowtype; v_staff uuid;
  v_existing public.customer_birthday_redemptions%rowtype; v_redemption public.customer_birthday_redemptions%rowtype;
  v_hash text; v_as_of timestamptz:=statement_timestamp();
begin
  if not app.platform_feature_enabled('customer_birthday_benefits') then
    raise exception 'birthday benefit unavailable' using errcode='0A000';
  end if;
  -- The counter selects its own tenant-scoped client record. Customer-safe
  -- wallet JSON never carries an entitlement UUID to a browser.
  if auth.uid() is null or not app.can_module_write(p_business_id,'loyalty')
     or not exists(select 1 from public.clients c where c.id=p_client_id and c.business_id=p_business_id) then
    raise exception 'birthday benefit unavailable' using errcode='42501'; end if;
  select s.id into v_staff from public.staff s where s.business_id=p_business_id and s.user_id=auth.uid() and s.active
    order by case when s.role='owner' then 0 else 1 end,s.created_at limit 1 for update;
  if not found or p_branch_id is null or not exists(select 1 from public.staff_branches sb where sb.business_id=p_business_id and sb.staff_id=v_staff and sb.branch_id=p_branch_id) then
    raise exception 'birthday benefit unavailable' using errcode='42501'; end if;
  if p_idempotency_key is null then raise exception 'birthday benefit unavailable' using errcode='22023'; end if;
  v_hash:=app.c45_hash(jsonb_build_object('business_id',p_business_id,'client_id',p_client_id,'branch_id',p_branch_id)::text);
  select * into v_existing from public.customer_birthday_redemptions
   where business_id=p_business_id and client_id=p_client_id and actor=auth.uid() and operation_kind='redemption' and idempotency_key=p_idempotency_key for share;
  if found then
    if v_existing.request_hash is distinct from v_hash then raise exception 'birthday redemption conflicts with an existing operation' using errcode='40001'; end if;
    return jsonb_build_object('status','redeemed','replayed',true);
  end if;
  select * into v_entitlement from public.customer_birthday_entitlements
   where business_id=p_business_id and client_id=p_client_id
   order by valid_until desc,activated_at desc limit 1 for update;
  if not found then raise exception 'birthday benefit unavailable' using errcode='42501'; end if;
  -- The first lookup can legitimately miss a same-key request that commits
  -- while this session waits on the entitlement lock. Re-check after the lock
  -- and return the exact replay before evaluating the redeemed state.
  select * into v_existing from public.customer_birthday_redemptions
   where business_id=p_business_id and client_id=p_client_id and actor=auth.uid()
     and operation_kind='redemption' and idempotency_key=p_idempotency_key for share;
  if found then
    if v_existing.request_hash is distinct from v_hash then
      raise exception 'birthday redemption conflicts with an existing operation' using errcode='40001';
    end if;
    return jsonb_build_object('status','redeemed','replayed',true);
  end if;
  if v_entitlement.status<>'available' or v_entitlement.valid_from>v_as_of or v_entitlement.valid_until<=v_as_of then
    -- A different key racing with the successful redemption must be a clear
    -- optimistic conflict, never a misleading generic unavailability error.
    if exists(select 1 from public.customer_birthday_redemptions r
                where r.entitlement_id=v_entitlement.id and r.operation_kind='redemption' and r.active) then
      raise exception 'birthday redemption conflicts with an existing operation' using errcode='40001';
    end if;
    raise exception 'birthday benefit unavailable' using errcode='42501';
  end if;
  insert into public.customer_birthday_redemptions(entitlement_id,business_id,client_id,branch_id,actor,operation_kind,idempotency_key,request_hash)
  values(v_entitlement.id,v_entitlement.business_id,v_entitlement.client_id,p_branch_id,auth.uid(),'redemption',p_idempotency_key,v_hash)
  returning * into v_redemption;
  perform set_config('app.c45_entitlement_id',v_entitlement.id::text,true);
  update public.customer_birthday_entitlements set status='redeemed' where id=v_entitlement.id;
  insert into public.audit_log(business_id,actor,action,entity,entity_id,detail)
  values(v_entitlement.business_id,auth.uid(),'REDEEM_BIRTHDAY_BENEFIT','customer_birthday_redemptions',v_redemption.id,jsonb_build_object('status','redeemed'));
  return jsonb_build_object('status','redeemed','replayed',false);
exception when unique_violation then
  select * into v_existing from public.customer_birthday_redemptions
   where business_id=p_business_id and client_id=p_client_id and actor=auth.uid()
     and operation_kind='redemption' and idempotency_key=p_idempotency_key;
  if found and v_existing.request_hash = v_hash then
    return jsonb_build_object('status','redeemed','replayed',true);
  end if;
  raise exception 'birthday redemption conflicts with an existing operation' using errcode='40001';
end $$;

--
-- Name: redeem_gift_card(uuid, text, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.redeem_gift_card(p_business uuid, p_code text, p_client uuid, p_amount integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  gc public.gift_cards%rowtype;
  v_actor uuid := auth.uid();
  v_staff uuid;
  v_load integer;
  v_credit_id uuid := gen_random_uuid();
begin
  if not app.has_perm(p_business, 'create_sales') then
    raise exception 'you do not have permission to redeem gift cards in this business'
      using errcode = '42501';
  end if;
  select s.id into v_staff
    from public.staff s
   where s.business_id = p_business
     and s.user_id = v_actor
     and s.active
     and 'create_sales' = any (app.role_perms(s.role))
   order by case s.role when 'owner' then 0 when 'manager' then 1 else 2 end, s.created_at
   limit 1
   for update;
  if not found then
    raise exception 'active staff authorization is required to redeem a gift card'
      using errcode = '42501';
  end if;
  perform 1 from public.clients c
   where c.id = p_client and c.business_id = p_business
   for update;
  if not found then
    raise exception 'client does not belong to this business';
  end if;
  select * into gc
    from public.gift_cards g
   where g.business_id = p_business
     and upper(g.code) = upper(btrim(p_code))
   for update;
  if not found or gc.status <> 'active' or gc.balance_cents <= 0 then
    raise exception 'gift card is not active or has no remaining balance';
  end if;
  v_load := coalesce(p_amount, gc.balance_cents);
  if v_load <= 0 or v_load > gc.balance_cents then
    raise exception 'gift-card redemption % exceeds available balance %',
      v_load, gc.balance_cents;
  end if;

  update public.gift_cards
     set balance_cents = balance_cents - v_load,
         status = case when balance_cents - v_load = 0 then 'redeemed' else 'active' end
   where id = gc.id;

  perform set_config('app.credit_ledger_insert_id', v_credit_id::text, true);
  perform set_config('app.credit_ledger_write_scope', 'redeem_gift_card', true);
  insert into public.credit_ledger (
    id, business_id, client_id, entry_type, amount_cents, reference, actor
  ) values (
    v_credit_id, p_business, p_client, 'gift_card_load', v_load,
    'gift card redeemed: ' || gc.code, v_actor
  );
  perform set_config('app.credit_ledger_insert_id', '', true);
  perform set_config('app.credit_ledger_write_scope', '', true);

  return json_build_object(
    'loaded_cents', v_load,
    'remaining_cents', gc.balance_cents - v_load
  );
end $$;

--
-- Name: redeem_gift_card_at_branch_v117(uuid, uuid, text, uuid, integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.redeem_gift_card_at_branch_v117(p_business uuid, p_branch uuid, p_code text, p_client uuid, p_amount integer, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid:=auth.uid();
  v_result jsonb;
  v_payload jsonb;
  v_hash text;
  v_existing public.gift_card_redeem_operations_v117%rowtype;
  v_gift_card uuid;
begin
  if v_actor is null
     or not app.can_module_write_at_v94(p_business,p_branch,'till')
     or not app.can_module_read_at_v94(p_business,p_branch,'clients')
     or not app.has_perm(p_business,'create_sales') then
    raise exception 'branch-effective Till, Clients and create-sales authorization is required'
      using errcode='42501';
  end if;
  perform 1
  from public.branches branch
  where branch.id=p_branch
    and branch.business_id=p_business
    and branch.active
    and app.can_see_branch(p_business,branch.id)
  for share;
  if not found then
    raise exception 'active visible redemption branch is required'
      using errcode='42501';
  end if;
  if p_idempotency_key is null
     or p_code is null
     or btrim(p_code)=''
     or p_client is null
     or (p_amount is not null and p_amount<=0) then
    raise exception 'invalid gift-card redemption request'
      using errcode='22023';
  end if;
  v_payload:=jsonb_build_object(
    'amount_cents',p_amount,
    'branch_id',p_branch,
    'business_id',p_business,
    'client_id',p_client,
    'code',upper(btrim(p_code))
  );
  v_hash:=app.v41_request_hash(v_payload::text);
  perform pg_advisory_xact_lock(hashtextextended(
    'v117:gift-card-redeem:'||p_business::text||':'||
      p_idempotency_key::text,0
  ));
  select * into v_existing
  from public.gift_card_redeem_operations_v117 operation
  where operation.business_id=p_business
    and operation.idempotency_key=p_idempotency_key;
  if found then
    if v_existing.actor is distinct from v_actor
       or v_existing.request_hash<>v_hash then
      raise exception
        'idempotency key conflicts with another gift-card redemption'
        using errcode='23505';
    end if;
    return v_existing.result||jsonb_build_object('replayed',true);
  end if;
  v_result:=public.redeem_gift_card(
    p_business,p_code,p_client,p_amount
  )::jsonb;
  select card.id into v_gift_card
  from public.gift_cards card
  where card.business_id=p_business
    and upper(card.code)=upper(btrim(p_code));
  if not found then
    raise exception 'gift-card redemption receipt could not be resolved'
      using errcode='40001';
  end if;
  v_result:=v_result||jsonb_build_object(
    'branch_id',p_branch,
    'replayed',false
  );
  insert into public.gift_card_redeem_operations_v117(
    business_id,branch_id,actor,idempotency_key,request_hash,status,
    gift_card_id,client_id,amount_cents,result
  ) values(
    p_business,p_branch,v_actor,p_idempotency_key,v_hash,'completed',
    v_gift_card,p_client,(v_result->>'loaded_cents')::integer,v_result
  );
  return v_result;
end
$$;

--
-- Name: redeem_gift_card_v41(uuid, text, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.redeem_gift_card_v41(p_business uuid, p_code text, p_client uuid, p_amount integer DEFAULT NULL::integer) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_actor uuid:=auth.uid(); v_staff uuid; v_result json;
begin
  if v_actor is null or not app.can_module_write(p_business,'giftcards')
     or not app.has_perm(p_business,'create_sales') then
    raise exception 'active giftcards-module and create-sales authorization is required' using errcode='42501';
  end if;
  select s.id into v_staff from public.staff s
   where s.business_id=p_business and s.user_id=v_actor and s.active
     and 'create_sales'=any(app.role_perms(s.role))
   order by case when s.role='owner' then 0 else 1 end,s.created_at limit 1 for update;
  if not found then raise exception 'active staff authorization is required' using errcode='42501'; end if;
  v_result:=public.redeem_gift_card(p_business,p_code,p_client,p_amount);
  return v_result;
end
$$;

--
-- Name: redeem_growth_offer_v108(uuid, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.redeem_growth_offer_v108(p_business uuid, p_token text, p_sale uuid, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid:=auth.uid();
  v_intent public.growth_redemption_intents_v108%rowtype;
  v_entitlement public.growth_entitlements_v108%rowtype;
  v_execution public.growth_executions_v108%rowtype;
  v_sale public.sales%rowtype;
  v_existing public.growth_entitlement_events_v108%rowtype;
  v_now timestamptz:=clock_timestamp();
  v_request_hash text;
  v_receipt jsonb;
begin
  if v_actor is null
     or not app.has_perm(p_business,'create_sales')
     or not app.can_module_read(p_business,'retention') then
    raise exception 'sales and retention access required' using errcode='42501';
  end if;
  select * into v_intent
    from public.growth_redemption_intents_v108 intent
   where intent.business_id=p_business
     and intent.token_hash=encode(
       extensions.digest(convert_to(p_token,'UTF8'),'sha256'),'hex'
     )
   for update;
  if not found then raise exception 'invalid offer QR'; end if;
  v_request_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'business_id',p_business,'intent_id',v_intent.id,
    'entitlement_id',v_intent.entitlement_id,'sale_id',p_sale
  )::text,'UTF8'),'sha256'),'hex');
  select * into v_existing
    from public.growth_entitlement_events_v108 event
   where event.business_id=p_business
     and event.actor=v_actor
     and event.event_type='redeemed'
     and event.idempotency_key=p_idempotency_key;
  if found then
    if v_existing.detail->>'request_hash'<>v_request_hash then
      raise exception 'idempotency key reused with a different redemption request'
        using errcode='23505';
    end if;
    return v_existing.detail->'receipt';
  end if;
  if v_intent.status<>'pending' or v_intent.expires_at<=v_now then
    raise exception 'offer QR is no longer valid' using errcode='42501';
  end if;
  select * into v_entitlement
    from public.growth_entitlements_v108 entitlement
   where entitlement.id=v_intent.entitlement_id
     and entitlement.business_id=p_business
   for update;
  if v_entitlement.status<>'issued' or v_entitlement.expires_at<=v_now then
    raise exception 'offer is no longer redeemable' using errcode='42501';
  end if;
  select * into strict v_execution
    from public.growth_executions_v108 execution
   where execution.id=v_entitlement.execution_id
     and execution.business_id=p_business;
  if not app.can_see_branch(v_execution.business_id,v_execution.branch_id) then
    raise exception 'offer branch is outside actor scope' using errcode='42501';
  end if;
  select * into v_sale
    from public.sales sale
   where sale.id=p_sale and sale.business_id=p_business
   for share;
  if not found
     or v_sale.client_id is null
     or app.v113_effective_client_id(v_sale.business_id,v_sale.client_id)
        <>app.v113_effective_client_id(
             v_entitlement.business_id,v_entitlement.client_id
           )
     or not v_sale.counts_as_visit
     or not v_sale.counts_as_revenue
     or v_sale.reversal_of is not null
     or v_sale.amount_cents<=0
     or v_sale.created_at>v_now
     or v_sale.occurred_at>v_now
     or app.v106_sale_residual_minor(v_sale.id,v_now)<=0
     or exists (
       select 1 from public.sales reversal
        where reversal.business_id=v_sale.business_id
          and reversal.reversal_of=v_sale.id
          and reversal.created_at<=v_now
     )
     or v_sale.created_at<greatest(v_entitlement.issued_at,v_execution.started_at)
     or v_sale.occurred_at<greatest(v_entitlement.issued_at,v_execution.started_at)
     or v_sale.occurred_at>=least(v_entitlement.expires_at,v_execution.ends_at)
     or (
       v_execution.branch_id is not null
       and v_sale.branch_id is distinct from v_execution.branch_id
     )
     or not app.can_see_branch(v_sale.business_id,v_sale.branch_id) then
    raise exception 'offer must attach to this customer''s qualifying sale'
      using errcode='22023';
  end if;
  v_receipt:=jsonb_build_object(
    'entitlement_id',v_entitlement.id,'sale_id',p_sale,
    'value_cents',v_entitlement.value_cents,'status','redeemed',
    'identity_attribution','v111_current_effective_identity'
  );
  update public.growth_entitlements_v108
     set status='redeemed',redeemed_at=v_now,redeemed_sale_id=p_sale
   where id=v_entitlement.id;
  update public.growth_redemption_intents_v108
     set status='completed',completed_at=v_now
   where id=v_intent.id;
  insert into public.growth_entitlement_events_v108(
    entitlement_id,business_id,event_type,actor,sale_id,idempotency_key,detail
  ) values (
    v_entitlement.id,p_business,'redeemed',v_actor,p_sale,p_idempotency_key,
    jsonb_build_object(
      'intent_id',v_intent.id,'value_cents',v_entitlement.value_cents,
      'request_hash',v_request_hash,'receipt',v_receipt,
      'identity_attribution','v111_current_effective_identity'
    )
  );
  return v_receipt;
end
$$;

--
-- Name: redeem_points(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.redeem_points(p_business uuid, p_client uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  lp public.loyalty_programs%rowtype;
  bal integer;
  v_batch_balance integer;
  v_remaining integer;
  v_take integer;
  v_batch record;
  v_actor uuid := auth.uid();
  v_staff uuid;
  v_points_id uuid := gen_random_uuid();
  v_credit_id uuid := gen_random_uuid();
  v_points_programme uuid;
begin
  if not app.has_perm(p_business, 'create_sales') then
    raise exception 'you do not have permission to redeem points in this business (create_sales)'
      using errcode = '42501';
  end if;

  select s.id into v_staff
    from public.staff s
   where s.business_id = p_business
     and s.user_id = v_actor
     and s.active
     and 'create_sales' = any (app.role_perms(s.role))
   order by case s.role when 'owner' then 0 when 'manager' then 1 else 2 end, s.created_at
   limit 1
   for update;
  if not found or not app.has_perm(p_business, 'create_sales') then
    raise exception 'active staff authorization changed while redeeming points'
      using errcode = '42501';
  end if;

  perform 1
    from public.clients c
   where c.id = p_client
     and c.business_id = p_business
   for update;
  if not found then
    raise exception 'client does not belong to this business';
  end if;

  select * into lp
    from public.loyalty_programs
   where business_id = p_business
     and active
     and kind = 'points'
     and redeem_points > 0
     and reward_credit_cents > 0
   limit 1;
  if not found then
    raise exception 'no active redeemable points program with positive points and credit values';
  end if;
  -- v23g (#3): this firm may run the reward-catalog model instead.
  if lp.loyalty_model is distinct from 'classic' then
    raise exception 'this business redeems points through its reward catalog (points_tiers model) — use redeem_reward';
  end if;

  select coalesce(sum(pl.points), 0)::integer into bal
    from public.points_ledger pl
   where pl.business_id = p_business
     and pl.client_id = p_client;
  if bal < lp.redeem_points then
    raise exception 'insufficient points: % < %', bal, lp.redeem_points;
  end if;

  v_points_programme := app.resolve_ledger_programme_v309(p_business);
  if v_points_programme is null then
    raise exception 'redemption programme is not resolvable for this business'
      using errcode = 'XX001';
  end if;
  select coalesce(sum(pb.remaining), 0)::integer into v_batch_balance
    from public.points_batches pb
   where pb.business_id = p_business
     and pb.client_id = p_client
     and pb.programme_id = v_points_programme
     and pb.remaining > 0;
  if v_batch_balance < lp.redeem_points then
    raise exception 'points batches % cannot prove redemption %',
      v_batch_balance, lp.redeem_points
      using errcode = 'check_violation';
  end if;

  v_remaining := lp.redeem_points;
  for v_batch in
    select pb.id, pb.remaining
      from public.points_batches pb
     where pb.business_id = p_business
       and pb.client_id = p_client
       and pb.programme_id = v_points_programme
       and pb.remaining > 0
     order by pb.expires_at nulls last, pb.earned_at, pb.id
     for update
  loop
    exit when v_remaining = 0;
    v_take := least(v_batch.remaining, v_remaining);
    update public.points_batches
       set remaining = remaining - v_take
     where id = v_batch.id;
    v_remaining := v_remaining - v_take;
  end loop;

  perform set_config('app.points_ledger_insert_id', v_points_id::text, true);
  perform set_config('app.points_ledger_write_scope', 'redeem_points', true);
  insert into public.points_ledger
    (id, business_id, client_id, entry_type, points, reference, actor, programme_id)
  values
    (v_points_id, p_business, p_client, 'redeem', -lp.redeem_points,
     'redeemed to credit', v_actor, v_points_programme);
  perform set_config('app.points_ledger_insert_id', '', true);
  perform set_config('app.points_ledger_write_scope', '', true);

  perform set_config('app.credit_ledger_insert_id', v_credit_id::text, true);
  perform set_config('app.credit_ledger_write_scope', 'redeem_points', true);
  insert into public.credit_ledger
    (id, business_id, client_id, entry_type, amount_cents, reference, actor)
  values
    (v_credit_id, p_business, p_client, 'loyalty_earn', lp.reward_credit_cents,
     'points redemption', v_actor);
  perform set_config('app.credit_ledger_insert_id', '', true);
  perform set_config('app.credit_ledger_write_scope', '', true);

  return json_build_object(
    'points_spent', lp.redeem_points,
    'credit_cents', lp.reward_credit_cents
  );
end $$;

--
-- Name: redeem_points(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.redeem_points(p_business uuid, p_client uuid, p_idempotency_key text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if not app.can_module_write(p_business, 'loyalty') then
    raise exception 'loyalty write authorization is required'
      using errcode = '42501';
  end if;
  return app.redeem_points_v40_internal(
    p_business, p_client, p_idempotency_key);
end
$$;

--
-- Name: redeem_program_entitlement(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.redeem_program_entitlement(p_entitlement uuid, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare e public.program_entitlements%rowtype; v_hash text; v_prior uuid; v_prior_hash text;
begin
  if p_idempotency_key is null then raise exception 'idempotency key required' using errcode = '22023'; end if;
  select * into e from public.program_entitlements where id = p_entitlement for update;
  if not found or not app.is_salon_member(e.business_id) then raise exception 'access denied' using errcode = '42501'; end if;
  if not app.can_module(e.business_id, 'loyalty') then raise exception 'access denied' using errcode = '42501'; end if;
  v_hash := app.ps1b_sha256('redeem:' || p_entitlement::text);
  -- idempotent replay — the key must belong to THIS request (v41/v51a house
  -- pattern: reusing a key for a different entitlement is an error, not a replay).
  select entitlement_id, request_hash into v_prior, v_prior_hash
    from public.program_entitlement_operations
   where business_id = e.business_id and operation_type = 'redeem' and idempotency_key = p_idempotency_key;
  if v_prior is not null then
    if v_prior <> e.id or v_prior_hash <> v_hash then
      raise exception 'idempotency key was already used for a different request' using errcode = '22023';
    end if;
    return jsonb_build_object('entitlement_id', e.id, 'status', e.status, 'replayed', true);
  end if;
  if e.status <> 'available' then raise exception 'entitlement is not available' using errcode = '23514'; end if;
  update public.program_entitlements set status = 'redeemed', redeemed_at = now(), updated_at = now() where id = e.id;
  insert into public.program_entitlement_operations(business_id, client_id, operation_type, idempotency_key, request_hash, entitlement_id)
  values(e.business_id, e.client_id, 'redeem', p_idempotency_key, v_hash, e.id);
  insert into public.audit_log(business_id, actor, action, entity, entity_id, detail)
  values(e.business_id, auth.uid(), 'REDEEM_ENTITLEMENT', 'program_entitlements', e.id, jsonb_build_object('client_id', e.client_id));
  return jsonb_build_object('entitlement_id', e.id, 'status', 'redeemed', 'replayed', false);
end $$;

