--
-- Name: refresh_business_onboarding_v79(uuid, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refresh_business_onboarding_v79(p_business uuid, p_expected_version bigint, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_actor uuid:=auth.uid();v_hash text;v_replay jsonb;v_check uuid;v_response jsonb;
begin
  if not app.is_platform_operator_v75() then raise exception 'platform operator access is required' using errcode='42501';end if;
  perform app.require_idempotency_key_v79(p_idempotency_key);
  v_hash:=app.v76_sha256_hex(jsonb_build_object('business',p_business,'version',p_expected_version)::text);
  v_replay:=app.v76_replay(v_actor,'refresh_onboarding_v79',p_idempotency_key,v_hash);if v_replay is not null then return v_replay;end if;
  select id into v_check from public.business_onboarding_checklists
   where business_id=p_business and version=p_expected_version for update;
  if not found then raise exception 'onboarding version conflict' using errcode='40001';end if;
  perform app.refresh_onboarding_core_v79(p_business,v_actor);
  insert into public.business_onboarding_events(checklist_id,business_id,event_type,evidence,actor)
  values(v_check,p_business,'refreshed',jsonb_build_object('derived_rules','v79'),v_actor);
  v_response:=jsonb_build_object('replayed',false,'onboarding',app.get_onboarding_core_v79(p_business));
  perform app.v76_store_receipt(v_actor,'refresh_onboarding_v79',p_idempotency_key,v_hash,v_response);return v_response;
end
$$;

--
-- Name: refresh_growth_recommendation_v108(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refresh_growth_recommendation_v108(p_business uuid, p_branch uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid:=auth.uid();
  v_now timestamptz:=statement_timestamp();
  v_policy public.growth_policies_v108%rowtype;
  v_recommendation uuid:=gen_random_uuid();
  v_total_revenue bigint:=0;
  v_identified_revenue bigint:=0;
  v_total_sales integer:=0;
  v_identified_sales integer:=0;
  v_coverage_bps integer:=0;
  v_eligible integer:=0;
  v_excluded integer:=0;
  v_avg_value bigint:=0;
  v_confidence_bps integer:=0;
  v_status text;
  v_suppressions jsonb:='[]'::jsonb;
  v_dedupe text;
  v_existing uuid;
  v_member_fingerprint text;
  v_currency text;
  v_effective_policy jsonb;
  v_candidates jsonb:='[]'::jsonb;
begin
  if v_actor is null or (
    not app.is_super_admin()
    and (
      not app.has_perm(p_business,'view_finance')
      or not app.can_module_read(p_business,'retention')
    )
  ) then
    raise exception 'finance and retention access required' using errcode='42501';
  end if;
  if not app.can_see_branch(p_business,p_branch) then
    raise exception 'branch is outside actor scope' using errcode='42501';
  end if;
  if p_branch is not null and not exists (
    select 1 from public.branches branch
     where branch.id=p_branch and branch.business_id=p_business
  ) then
    raise exception 'branch does not belong to business' using errcode='22023';
  end if;
  if not app.platform_feature_enabled('growth_closed_loop_v108') then
    raise exception 'growth closed loop is not enabled' using errcode='0A000';
  end if;
  select upper(currency) into strict v_currency
    from public.businesses where id=p_business;

  insert into public.growth_policies_v108(business_id,updated_by)
  values(p_business,v_actor)
  on conflict (business_id) do nothing;
  select * into strict v_policy
    from public.growth_policies_v108 where business_id=p_business;
  v_effective_policy:=app.growth_v108_effective_parameters(p_business);

  select
    coalesce(sum(app.v106_sale_residual_minor(sale.id,v_now))
      filter(where sale.counts_as_revenue),0),
    coalesce(sum(app.v106_sale_residual_minor(sale.id,v_now))
      filter(where sale.counts_as_revenue and sale.client_id is not null),0),
    count(*) filter(where sale.counts_as_revenue),
    count(*) filter(where sale.counts_as_revenue and sale.client_id is not null)
  into v_total_revenue,v_identified_revenue,v_total_sales,v_identified_sales
  from public.sales sale
  where sale.business_id=p_business
    and (p_branch is null or sale.branch_id=p_branch)
    and sale.occurred_at>=v_now-interval '90 days'
    and sale.occurred_at<v_now
    and sale.reversal_of is null
    and not exists (
      select 1 from public.sales reversal
       where reversal.business_id=sale.business_id
         and reversal.reversal_of=sale.id
    );
  v_coverage_bps:=case when v_total_revenue>0
    then least(10000,(v_identified_revenue*10000/v_total_revenue)::integer)
    else 0 end;

  with canonical_sales as (
    select
      app.v113_effective_client_id(sale.business_id,sale.client_id) as client_id,
      sale.occurred_at,
      sale.id,
      app.v106_sale_residual_minor(sale.id,v_now) as amount_cents
    from public.sales sale
    where sale.business_id=p_business
      and (p_branch is null or sale.branch_id=p_branch)
      and sale.client_id is not null
      and sale.counts_as_visit
      and sale.reversal_of is null
      and app.v106_sale_residual_minor(sale.id,v_now)>0
      and sale.occurred_at>=v_now-make_interval(days=>v_policy.observation_days)
      and sale.occurred_at<v_now
      and not exists (
        select 1 from public.sales reversal
         where reversal.business_id=sale.business_id
           and reversal.reversal_of=sale.id
      )
  ),
  visits as (
    select canonical_sales.*,
      extract(epoch from (
        occurred_at-lag(occurred_at) over (
          partition by client_id order by occurred_at,id
        )
      ))/86400.0 as interval_days
    from canonical_sales
  ),
  metrics as (
    select visit.client_id,
      count(*)::integer as prior_visits,
      max(visit.occurred_at) as last_visit_at,
      percentile_cont(0.5) within group(order by visit.interval_days)
        filter(where visit.interval_days is not null) as cadence_days,
      floor(extract(epoch from(v_now-max(visit.occurred_at)))/86400)::integer
        as lapse_days,
      round(avg(visit.amount_cents))::bigint as average_transaction_cents,
      sum(visit.amount_cents)::bigint as historical_revenue_cents
    from visits visit
    group by visit.client_id
  ),
  judged as (
    select metric.*,
      case
        when metric.prior_visits<
          (v_effective_policy#>>'{parameters,minimum_prior_visits}')::integer
          then 'insufficient_history'
        when metric.cadence_days is null then 'insufficient_history'
        when metric.lapse_days<greatest(
          (v_effective_policy#>>'{parameters,minimum_lapse_days}')::integer,
          ceil(metric.cadence_days*
            (v_effective_policy#>>'{parameters,cadence_multiplier}')::numeric
          )::integer
        ) then 'not_lapsed'
        when not exists (
          select 1
            from public.customer_links link
            join public.customer_identities identity_row
              on identity_row.id=link.identity_id
             and identity_row.status='active'
           where link.business_id=p_business
             and app.v113_effective_client_id(link.business_id,link.client_id)
                 =metric.client_id
             and link.state='verified'
        ) then 'no_verified_link'
        when not exists (
          select 1
            from public.customer_notification_preferences preference
            join public.customer_links link
              on link.id=preference.link_id
             and link.business_id=preference.business_id
            join public.customer_identities identity_row
              on identity_row.id=link.identity_id
             and identity_row.status='active'
           where preference.business_id=p_business
             and app.v113_effective_client_id(
                   preference.business_id,preference.client_id
                 )=metric.client_id
             and preference.channel='in_app'
             and preference.topic='marketing'
             and preference.opted_in
             and link.state='verified'
        ) then 'no_marketing_consent'
        when exists (
          select 1 from public.growth_deliveries_v108 delivery
           where delivery.business_id=p_business
             and app.v113_effective_client_id(
                   delivery.business_id,delivery.client_id
                 )=metric.client_id
             and delivery.delivery_status='delivered'
             and delivery.delivered_at>=
               v_now-make_interval(days=>v_policy.frequency_cap_days)
        ) then 'frequency_cap'
        when exists (
          select 1
            from public.growth_execution_members_v108 member
            join public.growth_executions_v108 execution
              on execution.id=member.execution_id
           where member.business_id=p_business
             and app.v113_effective_client_id(
                   member.business_id,member.client_id
                 )=metric.client_id
             and execution.status='running'
             and execution.ends_at>v_now
        ) then 'active_experiment'
        else null
      end as exclusion_reason
    from metrics metric
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'client_id',judged.client_id,
    'prior_visits',judged.prior_visits,
    'last_visit_at',judged.last_visit_at,
    'cadence_days',judged.cadence_days,
    'lapse_days',judged.lapse_days,
    'average_transaction_cents',judged.average_transaction_cents,
    'historical_revenue_cents',judged.historical_revenue_cents,
    'eligible',judged.exclusion_reason is null,
    'exclusion_reason',judged.exclusion_reason
  ) order by judged.client_id),'[]'::jsonb)
  into v_candidates
  from judged;

  select count(*) filter(where eligible),
         count(*) filter(where not eligible),
         coalesce(round(avg(average_transaction_cents)
           filter(where eligible)),0)::bigint
    into v_eligible,v_excluded,v_avg_value
    from jsonb_to_recordset(v_candidates) as candidate(
      client_id uuid,
      prior_visits integer,
      last_visit_at timestamptz,
      cadence_days numeric,
      lapse_days integer,
      average_transaction_cents bigint,
      historical_revenue_cents bigint,
      eligible boolean,
      exclusion_reason text
    );
  v_confidence_bps:=least(9500,
    greatest(0,v_coverage_bps*7/10)+least(2500,v_eligible*100)
  );

  if not v_policy.enabled then
    v_suppressions:=v_suppressions||jsonb_build_array('policy_disabled');
  end if;
  if v_total_sales<50 then
    v_suppressions:=v_suppressions||jsonb_build_array('cold_start_under_50_sales');
  end if;
  if v_coverage_bps<v_policy.minimum_identity_coverage_bps then
    v_suppressions:=v_suppressions||
      jsonb_build_array('identity_coverage_below_threshold');
  end if;
  if v_eligible<
     (v_effective_policy#>>'{parameters,minimum_audience}')::integer then
    v_suppressions:=v_suppressions||jsonb_build_array('audience_below_minimum');
  end if;
  v_suppressions:=v_suppressions||
    coalesce(v_effective_policy->'suppression_reasons','[]'::jsonb);
  if floor(v_eligible*v_policy.holdout_percent/100.0)<v_policy.minimum_arm_size
     or v_eligible-floor(v_eligible*v_policy.holdout_percent/100.0)
        <v_policy.minimum_arm_size then
    v_suppressions:=v_suppressions||
      jsonb_build_array('experiment_arms_too_small');
  end if;
  v_status:=case when jsonb_array_length(v_suppressions)=0
    then 'presented' else 'suppressed' end;

  select encode(extensions.digest(convert_to(
    coalesce(jsonb_agg(jsonb_build_array(
      candidate.client_id,candidate.eligible,candidate.exclusion_reason,
      candidate.prior_visits,candidate.last_visit_at,
      round(candidate.cadence_days,2),candidate.lapse_days,
      candidate.average_transaction_cents,candidate.historical_revenue_cents
    ) order by candidate.client_id)::text,'[]'),'UTF8'
  ),'sha256'),'hex')
  into v_member_fingerprint
  from jsonb_to_recordset(v_candidates) as candidate(
    client_id uuid,
    prior_visits integer,
    last_visit_at timestamptz,
    cadence_days numeric,
    lapse_days integer,
    average_transaction_cents bigint,
    historical_revenue_cents bigint,
    eligible boolean,
    exclusion_reason text
  );

  v_dedupe:=encode(extensions.digest(convert_to(concat_ws(':',
    'v113',p_business,coalesce(p_branch::text,'all'),v_policy.policy_version,
    date_trunc('day',v_now)::text,v_status,v_currency,v_total_sales,
    v_identified_sales,v_total_revenue,v_identified_revenue,v_eligible,
    v_excluded,v_avg_value,v_policy.default_credit_cents,
    v_policy.maximum_credit_cents,v_policy.frequency_cap_days,
    v_policy.attribution_days,v_policy.minimum_arm_size,
    v_policy.holdout_percent,v_member_fingerprint,v_effective_policy::text
  ),'UTF8'),'sha256'),'hex');
  perform pg_advisory_xact_lock(
    hashtextextended('growth-v108-refresh:'||v_dedupe,0)
  );
  select recommendation.id into v_existing
    from public.growth_recommendations_v108 recommendation
   where recommendation.dedupe_key=v_dedupe;
  if found then
    return jsonb_build_object(
      'recommendation_id',v_existing,'status',v_status,
      'eligible',v_eligible,'excluded',v_excluded,
      'coverage_bps',v_coverage_bps,
      'suppression_reasons',v_suppressions,'replayed',true
    );
  end if;

  insert into public.growth_recommendations_v108(
    id,business_id,branch_id,recommendation_type,policy_version,
    generated_at,valid_until,observation_start,observation_end,
    comparison_start,comparison_end,finding,supporting_evidence,baseline,
    opportunity,expected_incremental_revenue,expected_incremental_gross_profit,
    confidence,assumptions,recommended_action,recommended_channel,
    recommended_offer,estimated_cost_cents,audience_size,excluded_size,
    success_metric,frequency_cap_days,attribution_window_days,holdout_percent,
    stop_conditions,status,suppression_reasons,data_freshness_at,data_coverage,
    dedupe_key,created_by
  ) values (
    v_recommendation,p_business,p_branch,'lapsed_high_value_bring_back',
    v_policy.policy_version,v_now,v_now+interval '24 hours',
    v_now-make_interval(days=>v_policy.observation_days),v_now,
    v_now-interval '180 days',v_now-interval '90 days',
    case when v_status='presented'
      then v_eligible||
        ' previously active customers are beyond their observed visit cadence.'
      else 'No reliable bring-back action is available yet.' end,
    jsonb_build_array(
      jsonb_build_object('metric','eligible_customers','value',v_eligible),
      jsonb_build_object(
        'metric','identified_revenue_coverage_bps','value',v_coverage_bps
      ),
      jsonb_build_object(
        'metric','average_historical_transaction_cents','value',v_avg_value
      ),
      jsonb_build_object(
        'metric','effective_policy_lineage','value',v_effective_policy
      ),
      jsonb_build_object(
        'metric','identity_attribution','value','v111_current_effective_identity'
      )
    ),
    jsonb_build_object(
      'total_sales_90d',v_total_sales,
      'identified_sales_90d',v_identified_sales,
      'total_revenue_cents_90d',v_total_revenue,
      'identified_revenue_cents_90d',v_identified_revenue
    ),
    jsonb_build_object(
      'eligible_customers',v_eligible,
      'historical_average_transaction_cents',v_avg_value
    ),
    jsonb_build_object(
      'currency',v_currency,'status','withheld_uncalibrated',
      'kind','incremental_revenue_not_yet_available',
      'reason','no completed calibrated experiment evidence'
    ),
    null,
    jsonb_build_object(
      'score_bps',v_confidence_bps,'score_kind','data_quality_only',
      'level',case
        when v_confidence_bps>=8000 then 'high'
        when v_confidence_bps>=6500 then 'medium'
        else 'low' end,
      'reasons',jsonb_build_array(
        'identity coverage and audience size determine confidence',
        'causal result remains unavailable until a valid holdout completes'
      )
    ),
    jsonb_build_array(
      'future behaviour may differ from historical cadence',
      'expected revenue is a range, not a guarantee',
      'gross profit is unavailable until item cost coverage is complete'
    ),
    jsonb_build_object(
      'label','Approve measured bring-back','channel','in_app',
      'requires_owner_approval',true
    ),
    'in_app',
    jsonb_build_object(
      'type','credit_cents','value_cents',v_policy.default_credit_cents,
      'currency',v_currency,'expires_in_days',7
    ),
    greatest(0,
      (v_eligible-floor(v_eligible*v_policy.holdout_percent/100.0)::integer)
      *v_policy.default_credit_cents
    ),
    v_eligible,v_excluded,'incremental_completed_purchase_revenue',
    v_policy.frequency_cap_days,v_policy.attribution_days,
    v_policy.holdout_percent,
    jsonb_build_object(
      'budget_cap_cents',v_eligible*v_policy.maximum_credit_cents,
      'one_active_experiment_per_customer',true,
      'consent_rechecked_at_execution',true,
      'minimum_arm_size',v_policy.minimum_arm_size,
      'identity_attribution','v111_current_effective_identity'
    ),
    v_status,v_suppressions,v_now,
    jsonb_build_object(
      'identified_revenue_bps',v_coverage_bps,
      'total_sales',v_total_sales,'identified_sales',v_identified_sales,
      'effective_policy',v_effective_policy,
      'identity_attribution','v111_current_effective_identity','as_of',v_now
    ),
    v_dedupe,v_actor
  );

  insert into public.growth_recommendation_members_v108(
    recommendation_id,business_id,client_id,eligible,exclusion_reason,
    prior_visits,last_visit_at,cadence_days,lapse_days,
    average_transaction_cents,historical_revenue_cents,evidence
  )
  select v_recommendation,p_business,candidate.client_id,candidate.eligible,
    candidate.exclusion_reason,candidate.prior_visits,candidate.last_visit_at,
    round(candidate.cadence_days,2),candidate.lapse_days,
    candidate.average_transaction_cents,candidate.historical_revenue_cents,
    jsonb_build_object(
      'prior_visits',candidate.prior_visits,
      'last_visit_at',candidate.last_visit_at,
      'observed_median_cadence_days',round(candidate.cadence_days,2),
      'days_since_last_visit',candidate.lapse_days,
      'historical_average_transaction_cents',
        candidate.average_transaction_cents,
      'identity_attribution','v111_current_effective_identity'
    )
  from jsonb_to_recordset(v_candidates) as candidate(
    client_id uuid,
    prior_visits integer,
    last_visit_at timestamptz,
    cadence_days numeric,
    lapse_days integer,
    average_transaction_cents bigint,
    historical_revenue_cents bigint,
    eligible boolean,
    exclusion_reason text
  );

  insert into public.audit_log(
    business_id,actor,action,entity,entity_id,detail
  ) values (
    p_business,v_actor,'REFRESH_GROWTH_RECOMMENDATION_V108',
    'growth_recommendations_v108',v_recommendation,
    jsonb_build_object(
      'status',v_status,'eligible',v_eligible,'excluded',v_excluded,
      'coverage_bps',v_coverage_bps,
      'identity_attribution','v111_current_effective_identity'
    )
  );
  return jsonb_build_object(
    'recommendation_id',v_recommendation,'status',v_status,
    'eligible',v_eligible,'excluded',v_excluded,
    'coverage_bps',v_coverage_bps,
    'suppression_reasons',v_suppressions,'replayed',false
  );
end
$$;

--
-- Name: refund_sale(uuid, uuid, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refund_sale(p_business uuid, p_sale uuid, p_reason text, p_idempotency_key text, p_reference text DEFAULT NULL::text, p_restock_policy text DEFAULT 'none'::text) RETURNS json
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  select public.reverse_sale(
    p_business, p_sale, p_reason, p_idempotency_key, p_reference, p_restock_policy
  )
$$;

--
-- Name: refund_sv_operation(uuid, uuid, integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refund_sv_operation(p_business uuid, p_topup_operation uuid, p_cash_cents integer, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_hash text;
  v_existing public.sv_operations%rowtype;
  v_op uuid := gen_random_uuid();
  v_account uuid;
  v_topup_type text;
  v_plan jsonb;
  v_entry jsonb;
  v_result jsonb;
  v_policy text;
  v_net_spent integer;
  v_collected jsonb;
  v_collected_cents integer;
  v_prior_cash integer;
  v_cash integer;
  v_cumulative integer;
begin
  if not app.is_salon_owner(p_business) then
    raise exception 'owner only' using errcode = '42501';
  end if;
  if coalesce((select state from public.sv_authority
                where business_id = p_business and asset = 'stored_value'), 'unbuilt') <> 'live' then
    raise exception 'sv_not_live: stored value is not the authority for this business' using errcode = '22023';
  end if;

  -- PS-2A Increment D pause gate (contract D §1: a refund returns customer cash = an earn-side
  -- correction, so an active 'all' or 'earn' sv_pause blocks it). Second gate, independent of
  -- sv_not_live; this block is the ONLY addition over the v63 body.
  if app.sv_pause_active(p_business, 'stored_value', 'earn') then
    raise exception 'sv_paused: stored-value earns are paused' using errcode = '22023';
  end if;
  if p_idempotency_key is null then
    raise exception 'a stored-value refund idempotency key is required' using errcode = '22023';
  end if;

  select o.operation_type into v_topup_type from public.sv_operations o
   where o.id = p_topup_operation and o.business_id = p_business;
  if v_topup_type is null then
    raise exception 'stored-value top-up operation not found in this business' using errcode = '22023';
  end if;
  -- v68a (0): target symmetry with sv_chargeback_topup - only a top-up can be refunded.
  if v_topup_type <> 'topup' then
    raise exception 'stored-value refund target is not a top-up operation' using errcode = '22023';
  end if;

  select account_id into v_account from public.sv_lots
   where business_id = p_business and operation_id = p_topup_operation and class = 'paid'
   order by earned_seq asc, id asc limit 1;
  if v_account is null then
    raise exception 'stored-value operation has no paid lot to refund' using errcode = '22023';
  end if;

  -- v68a (0): payment evidence is MANDATORY before any cash can leave. No sv_topup_payments row
  -- means no cash was ever collected for this operation, so there is nothing to refund and no
  -- honest bound for the cap. Fails CLOSED, exactly as sv_chargeback_topup does.
  v_collected := app.sv_cash_collected_cents(p_business, p_topup_operation);
  if coalesce(v_collected->>'basis', 'none') <> 'payment_evidence' then
    raise exception 'sv_no_payment_evidence: this top-up carries no recorded funding payment, so no cash can be refunded'
      using errcode = '22023';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('v63:sv_acct:' || p_business::text || ':' || v_account::text, 0));
  perform pg_advisory_xact_lock(hashtextextended('v63:sv_refund:' || p_business::text || ':' || p_idempotency_key::text, 0));

  select * into v_existing from public.sv_operations o
   where o.business_id = p_business and o.operation_type = 'refund' and o.idempotency_key = p_idempotency_key
   for update;
  v_hash := app.ps1b_sha256(jsonb_build_object(
    'op', 'refund', 'business_id', p_business, 'topup_operation_id', p_topup_operation,
    'cash_cents', p_cash_cents)::text);
  if found then
    if v_existing.request_hash <> v_hash then
      raise exception 'idempotency key conflicts with a different stored-value refund' using errcode = '22023';
    end if;
    return v_existing.result;
  end if;

  -- FEFO row locks over the operations lots (one-winner vs a concurrent spend on the same account).
  perform 1 from public.sv_lots l
   where l.business_id = p_business and l.account_id = v_account
   order by l.expiry_key asc nulls last, l.earned_seq asc, l.id asc
   for update;

  -- v68a (a): a charged-back top-up can no longer return cash - the funding is gone.
  if exists (select 1 from public.sv_chargebacks c
              where c.business_id = p_business and c.topup_operation_id = p_topup_operation) then
    raise exception 'sv_charged_back: this top-up has been charged back and can no longer be refunded'
      using errcode = '22023';
  end if;

  -- v68a (b): the immutable plan-version refund policy the paid lot pinned at mint (v65 config).
  v_policy := app.sv_operation_refund_policy(p_business, p_topup_operation);
  if v_policy = 'no_refund' then
    raise exception 'sv_refund_not_permitted: the plan version for this top-up does not permit refunds'
      using errcode = '22023';
  end if;
  -- A variant may only ever be STRICTER than 'proportional' (PS-0 §4). 'full_unused' has no pinned
  -- semantics, so it fails CLOSED rather than silently resolving to the looser proportional path.
  if v_policy = 'full_unused' then
    raise exception 'sv_refund_policy_unimplemented: the plan version pins refund_policy=full_unused, whose semantics are not pinned; use unused_only or proportional'
      using errcode = '22023';
  end if;
  if v_policy = 'unused_only' then
    v_net_spent := app.sv_operation_net_spent(p_business, p_topup_operation);
    if v_net_spent > 0 then
      raise exception 'sv_refund_unused_only: the plan version permits a refund only while the top-up is wholly unspent (% cents already consumed)',
        v_net_spent using errcode = '22023';
    end if;
  end if;

  v_plan := app.sv_plan_refund(p_business, p_topup_operation, p_cash_cents);
  if (v_plan->>'ok')::boolean is not true then
    raise exception 'stored-value refund failed: %', coalesce(v_plan->>'reason', 'unknown') using errcode = '22023';
  end if;

  -- v68a (c): the cumulative cash cap, bounded by sv_topup_payments.amount_cents and nothing else.
  -- Re-read under the locks (TOCTOU pattern) and re-assert the evidence, so the bound the writes use
  -- is the one checked here. Prior cash comes from the MOVEMENT AUTHORITY, so the cap is correct
  -- even for operations refunded before v68a existed.
  v_collected := app.sv_cash_collected_cents(p_business, p_topup_operation);
  if coalesce(v_collected->>'basis', 'none') <> 'payment_evidence' then
    raise exception 'sv_no_payment_evidence: this top-up carries no recorded funding payment, so no cash can be refunded'
      using errcode = '22023';
  end if;
  v_collected_cents := (v_collected->>'collected_cents')::int;
  v_prior_cash := app.sv_cash_refunded_cents(p_business, p_topup_operation);
  v_cash := (v_plan->>'cash_cents')::int;
  v_cumulative := v_prior_cash + v_cash;
  if v_cumulative > v_collected_cents then
    raise exception 'sv_cash_refund_cap: refunding % cents would take cumulative cash to % on a top-up that collected % cents',
      v_cash, v_cumulative, v_collected_cents using errcode = '22023';
  end if;

  v_result := jsonb_build_object(
    'status', 'ok', 'operation_id', v_op, 'topup_operation_id', p_topup_operation, 'account_id', v_account,
    'cash_cents', (v_plan->>'cash_cents')::int, 'clawback_cents', (v_plan->>'clawback_cents')::int,
    'final', (v_plan->>'final')::boolean, 'plan', v_plan->'plan',
    'refund_policy', v_policy, 'cash_collected_cents', v_collected_cents,
    'cash_basis', v_collected->>'basis',
    'cash_refunded_before_cents', v_prior_cash, 'cash_refunded_cumulative_cents', v_cumulative);

  insert into public.sv_operations(id, business_id, operation_type, idempotency_key, request_hash, actor, result)
  values (v_op, p_business, 'refund', p_idempotency_key, v_hash, v_actor, v_result);
  for v_entry in select * from jsonb_array_elements(v_plan->'plan') loop
    insert into public.sv_lot_movements(business_id, account_id, lot_id, operation_id, kind, cents)
    values (p_business, v_account, (v_entry->>'lot_id')::uuid, v_op, v_entry->>'kind', (v_entry->>'cents')::int);
  end loop;
  -- The structural half of the cap: the running total is materialised under a CHECK bounding it by
  -- the collected cash and a unique index that no two concurrent refunds can both satisfy.
  if v_cash > 0 then
    insert into public.sv_topup_cash_refunds(
      business_id, account_id, topup_operation_id, refund_operation_id, paid_lot_id,
      cash_cents, cumulative_cash_cents, cash_collected_cents, cash_basis, actor)
    values (
      p_business, v_account, p_topup_operation, v_op, (v_plan->>'paid_lot')::uuid,
      v_cash, v_cumulative, v_collected_cents, v_collected->>'basis', v_actor);
  end if;
  insert into public.audit_log(business_id, actor, action, entity, entity_id, detail)
  values (p_business, v_actor, 'SV_REFUND', 'sv_accounts', v_account, jsonb_build_object(
    'operation_id', v_op, 'topup_operation_id', p_topup_operation,
    'cash_cents', (v_plan->>'cash_cents')::int, 'clawback_cents', (v_plan->>'clawback_cents')::int,
    'refund_policy', v_policy, 'cash_collected_cents', v_collected_cents,
    'cash_refunded_cumulative_cents', v_cumulative));

  return v_result;
end $$;

--
-- Name: reissue_workspace_owner_invite_v79(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reissue_workspace_owner_invite_v79(p_business uuid, p_owner_email text, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid:=auth.uid();v_hash text;v_replay jsonb;v_prospect uuid;v_email text;
  v_invite jsonb;v_response jsonb;
begin
  if not app.is_platform_operator_v75() then raise exception 'platform operator access is required' using errcode='42501';end if;
  perform app.require_idempotency_key_v79(p_idempotency_key);
  v_hash:=app.v76_sha256_hex(jsonb_build_object('business',p_business,'email',lower(btrim(coalesce(p_owner_email,''))))::text);
  v_replay:=app.v76_replay(v_actor,'reissue_owner_invite_v79',p_idempotency_key,v_hash);
  if v_replay is not null then return v_replay;end if;
  select source_prospect_id into v_prospect from public.businesses where id=p_business;
  if v_prospect is null then raise exception 'converted business was not found' using errcode='22023';end if;
  select coalesce(nullif(lower(btrim(p_owner_email)),''),
    (select lower(btrim(owner_email)) from public.sme_commercial_terms
      where prospect_id=v_prospect and contract_status in ('accepted','signed')
      order by version desc limit 1)) into v_email;
  v_invite:=app.issue_workspace_owner_invite_core_v79(p_business,v_prospect,v_email,v_actor);
  insert into public.audit_log(business_id,actor,action,entity,entity_id,detail)
  values(p_business,v_actor,'WORKSPACE_OWNER_INVITE_REISSUED_V79','workspace_owner_invitations',
    (v_invite->>'id')::uuid,jsonb_build_object('owner_email',v_email,'version',v_invite->>'version'));
  v_response:=jsonb_build_object('replayed',false,'outcome','reissued',
    'business_id',p_business,'owner_invitation',v_invite);
  perform app.v76_store_receipt(v_actor,'reissue_owner_invite_v79',p_idempotency_key,
    v_hash,v_response#-'{owner_invitation,raw_token}');
  return v_response;
end
$$;

--
-- Name: reject_customer_identity_correction_v111(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reject_customer_identity_correction_v111(p_proposal uuid, p_reason text, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid:=auth.uid();
  v_proposal public.customer_identity_proposals_v111%rowtype;
  v_payload jsonb;
  v_hash text;
  v_existing public.customer_identity_request_ledger_v111%rowtype;
  v_decision uuid;
  v_snapshot jsonb;
  v_receipt jsonb;
begin
  if v_actor is null then raise exception 'authentication required' using errcode='42501'; end if;
  if p_idempotency_key is null then
    raise exception 'idempotency key is required' using errcode='22023';
  end if;
  select * into v_proposal from public.customer_identity_proposals_v111
   where id=p_proposal;
  if not found then raise exception 'identity proposal not found' using errcode='23503'; end if;
  if not app.v111_can_decide(v_proposal.business_id) then
    raise exception 'owner or global business authority is required to reject'
      using errcode='42501';
  end if;
  p_reason:=nullif(btrim(p_reason),'');
  if p_reason is null or length(p_reason)>500 then
    raise exception 'rejection reason is required' using errcode='22023';
  end if;
  v_payload:=jsonb_build_object('operation','reject','proposal_id',p_proposal,'reason',p_reason);
  v_hash:=app.v111_request_hash(v_payload);
  perform pg_advisory_xact_lock(hashtextextended(
    'v111:request:'||v_actor||':'||p_idempotency_key,0
  ));
  select * into v_existing from public.customer_identity_request_ledger_v111
   where actor_auth_user_id=v_actor and idempotency_key=p_idempotency_key;
  if found then
    if v_existing.operation<>'reject' or v_existing.request_hash<>v_hash then
      raise exception 'idempotency key was already used for a different identity mutation'
        using errcode='23505';
    end if;
    return v_existing.receipt;
  end if;
  select * into v_proposal from public.customer_identity_proposals_v111
   where id=p_proposal for update;
  if not found then raise exception 'identity proposal not found' using errcode='23503'; end if;
  if v_proposal.status='rejected' then
    select id into v_decision from public.customer_identity_decisions_v111
     where proposal_id=p_proposal and decision_type='reject';
  elsif v_proposal.status in ('approved','reversed') then
    raise exception 'identity proposal already has a conflicting terminal decision'
      using errcode='55000';
  else
    v_snapshot:=app.v111_attribution_snapshot(
      v_proposal.business_id,v_proposal.source_client_id,
      v_proposal.target_client_id,v_proposal.source_client_id
    );
    v_decision:=gen_random_uuid();
    insert into public.customer_identity_decisions_v111(
      id,proposal_id,business_id,decision_type,before_client_id,after_client_id,
      before_attribution,after_attribution,reason,decided_by
    ) values (
      v_decision,p_proposal,v_proposal.business_id,'reject',
      v_proposal.source_client_id,v_proposal.source_client_id,
      v_snapshot,v_snapshot,p_reason,v_actor
    );
    update public.customer_identity_proposals_v111
       set status='rejected',decided_at=statement_timestamp(),
           updated_at=statement_timestamp()
     where id=p_proposal;
  end if;
  v_receipt:=jsonb_build_object(
    'status','rejected','proposal_id',p_proposal,'decision_id',v_decision
  );
  insert into public.customer_identity_request_ledger_v111(
    actor_auth_user_id,business_id,operation,idempotency_key,request_hash,receipt
  ) values(v_actor,v_proposal.business_id,'reject',p_idempotency_key,v_hash,v_receipt);
  return v_receipt;
end
$$;

--
-- Name: remove_bottle_v288(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.remove_bottle_v288(p_business uuid, p_bottle uuid, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_key text := nullif(btrim(coalesce(p_idempotency_key, '')), '');
  v_existing uuid;
  v_bottle public.bar_bottles%rowtype;
  v_before text;
begin
  -- The bar gate is FIRST, exactly as every other function in this module orders it.
  perform app.require_bar_business_v275(p_business);
  perform app.require_bar_staff_v275(p_business, true);
  if v_key is null then
    raise exception 'idempotency key required' using errcode = '22023';
  end if;

  v_existing := app.bar_bottle_replayed_v275(p_business, v_key);
  if v_existing is not null then
    select * into v_bottle from public.bar_bottles bottle where bottle.id = v_existing;
    return jsonb_build_object('status', 'duplicate_ignored',
      'bottle', app.bar_bottle_json_v275(v_bottle));
  end if;

  select * into v_bottle from public.bar_bottles bottle
   where bottle.id = p_bottle and bottle.business_id = p_business for update;
  if not found then
    raise exception 'bottle not found' using errcode = '22023';
  end if;
  -- Removable from every state in which the bar still physically holds the bottle. A bottle that
  -- has already ended — retrieved, finished, transferred, or removed once — is not re-ended.
  if v_bottle.status not in ('stored', 'called', 'at_table', 'expired') then
    raise exception 'this bottle is already closed' using errcode = '22023';
  end if;
  v_before := v_bottle.status;

  update public.bar_bottles bottle
     set status = 'removed', updated_at = now()
   where bottle.id = v_bottle.id
  returning * into v_bottle;

  insert into public.bar_bottle_events (business_id, bottle_id, kind, actor, idem_key, detail)
  values (p_business, v_bottle.id, 'status', v_actor, v_key,
    jsonb_build_object('from', v_before, 'to', 'removed', 'reason', 'removed_from_list'));

  return jsonb_build_object('status', 'ok', 'bottle', app.bar_bottle_json_v275(v_bottle));
end;
$$;

--
-- Name: remove_loyalty_branch_override_draft(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.remove_loyalty_branch_override_draft(p_config_version uuid, p_branch uuid, p_expected_snapshot_hash text DEFAULT NULL::text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_header public.firm_config_versions%rowtype;
  v_hash text;
begin
  select * into v_header
    from public.firm_config_versions
   where id = p_config_version
   for update;

  if not found or not app.is_salon_owner(v_header.business_id) then
    raise exception 'owner only' using errcode = '42501';
  end if;
  if v_header.status <> 'draft' then
    raise exception 'only a draft branch override may be edited' using errcode = '42501';
  end if;
  if p_expected_snapshot_hash is not null
     and v_header.snapshot_hash is distinct from p_expected_snapshot_hash then
    raise exception 'draft configuration changed; reload before saving'
      using errcode = '40001';
  end if;
  if not exists (
    select 1 from public.branches b
     where b.id = p_branch
       and b.business_id = v_header.business_id
  ) then
    raise exception 'branch does not belong to this business' using errcode = '42501';
  end if;

  delete from public.loyalty_branch_overrides
   where config_version_id = p_config_version
     and business_id = v_header.business_id
     and branch_id = p_branch;

  perform app.refresh_loyalty_config_snapshot(p_config_version);
  select snapshot_hash into v_hash
    from public.firm_config_versions
   where id = p_config_version;

  return json_build_object(
    'config_version_id', p_config_version,
    'branch_id', p_branch,
    'status', 'draft',
    'snapshot_hash', v_hash
  );
end $$;

--
-- Name: report_client_error_v177(text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.report_client_error_v177(p_surface text, p_message text, p_stack text DEFAULT NULL::text, p_url text DEFAULT NULL::text, p_build text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_surface text;
  v_message text;
  v_hash text;
  v_recent integer;
begin
  v_surface := coalesce(nullif(btrim(p_surface),''),'public');
  if v_surface not in ('customer','business','public') then v_surface := 'public'; end if;
  v_message := left(coalesce(nullif(btrim(p_message),''),'unknown error'),500);
  v_hash := app.v31_sha256_hex(v_surface||':'||v_message||':'||coalesce(left(p_url,300),''));
  select count(*) into v_recent from public.client_error_reports
   where occurred_at > now() - interval '1 hour';
  if v_recent >= 300 then return; end if;
  if exists (
    select 1 from public.client_error_reports
     where dedupe_hash = v_hash and occurred_at > now() - interval '1 minute'
  ) then return; end if;
  insert into public.client_error_reports
    (auth_user_id, surface, message, stack, url, build, user_agent, dedupe_hash)
  values (
    auth.uid(), v_surface, v_message, left(p_stack,2000), left(p_url,300),
    left(p_build,64),
    left(coalesce(current_setting('request.headers',true),'{}')::jsonb->>'user-agent',300),
    v_hash
  );
exception when others then
  return;
end $$;

--
-- Name: FUNCTION report_client_error_v177(p_surface text, p_message text, p_stack text, p_url text, p_build text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.report_client_error_v177(p_surface text, p_message text, p_stack text, p_url text, p_build text) IS 'Fire-and-forget client error intake: payload caps, 300/hour global flood guard, per-error one-minute dedupe. Never raises.';

--
-- Name: request_account_deletion_v131(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_account_deletion_v131(p_confirmation text, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_user uuid:=auth.uid();
  v_key text:=btrim(coalesce(p_idempotency_key,''));
  v_row public.account_deletion_requests%rowtype;
begin
  if v_user is null then
    raise exception 'authentication required' using errcode='42501';
  end if;
  if coalesce(p_confirmation,'')<>'DELETE' then
    raise exception 'type DELETE to confirm' using errcode='22023';
  end if;
  if length(v_key) not between 8 and 200 then
    raise exception 'invalid idempotency key' using errcode='22023';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(v_user::text,131));

  select * into v_row
    from public.account_deletion_requests
   where subject_ref=v_user and idempotency_key=v_key
   order by requested_at desc limit 1;

  if v_row.id is null then
    select * into v_row
      from public.account_deletion_requests
     where subject_ref=v_user and status in ('pending','processing')
     order by requested_at desc limit 1;
  end if;

  if v_row.id is null then
    insert into public.account_deletion_requests(
      subject_auth_user_id,subject_ref,idempotency_key,
      requested_at,response_due_at,updated_at
    ) values(v_user,v_user,v_key,now(),now()+interval '30 days',now())
    returning * into v_row;
  end if;

  return jsonb_build_object(
    'request_id',v_row.id,'status',v_row.status,
    'requested_at',v_row.requested_at,'response_due_at',v_row.response_due_at
  );
end
$$;

--
-- Name: FUNCTION request_account_deletion_v131(p_confirmation text, p_idempotency_key text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.request_account_deletion_v131(p_confirmation text, p_idempotency_key text) IS 'V131 authenticated, idempotent deletion-request intake. Returns the same open request after retry or lost response.';

--
-- Name: request_billing_command_v124(uuid, text, text, integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_billing_command_v124(p_business uuid, p_command_type text, p_cadence text, p_customer_capacity integer, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid:=auth.uid();
  v_fingerprint text;
  v_command public.billing_commands%rowtype;
  v_current_customer_count integer;
  v_existing_capacity integer;
  v_catalog public.billing_plan_catalog_v124%rowtype;
begin
  if v_actor is null
     or not (app.is_salon_owner(p_business) or app.is_super_admin()) then
    raise exception 'active owner or super-admin access is required'
      using errcode='42501';
  end if;
  if p_command_type not in (
      'create_checkout','create_portal','change_cadence','change_capacity',
      'change_branches','cancel_at_period_end','resume'
    ) or p_idempotency_key is null then
    raise exception 'invalid billing command' using errcode='22023';
  end if;
  if p_command_type in ('create_checkout','change_cadence','change_capacity','change_branches') then
    if p_cadence not in ('monthly','annual')
       or p_customer_capacity < 1000
       or p_customer_capacity % 1000 <> 0 then
      raise exception 'canonical cadence and customer capacity are required'
        using errcode='22023';
    end if;
    select count(*)::integer into v_current_customer_count
      from public.clients client where client.business_id=p_business;
    if p_customer_capacity < greatest(1000,
         ceil(v_current_customer_count::numeric/1000)::integer*1000) then
      raise exception 'selected capacity is below the current customer count'
        using errcode='22023';
    end if;
    select * into v_catalog
      from public.billing_plan_catalog_v124 catalog
       where catalog.currency='SGD' and catalog.cadence=p_cadence
         and catalog.active and catalog.effective_from<=now()
         and (catalog.effective_to is null or catalog.effective_to>now())
       order by catalog.effective_from desc limit 1;
    if not found then
      raise exception 'active V124 Stripe price catalog entry was not found'
        using errcode='22023';
    end if;
    if p_command_type in ('change_cadence','change_capacity') then
      select terms.customer_capacity into v_existing_capacity
        from public.billing_subscription_terms_v124 terms
       where terms.business_id=p_business;
      if p_command_type='change_capacity' and (
           v_existing_capacity is null
           or p_customer_capacity<=v_existing_capacity
         ) then
        raise exception 'capacity changes must be an increase'
          using errcode='22023';
      elsif p_command_type='change_cadence'
            and v_existing_capacity is not null
            and p_customer_capacity<v_existing_capacity then
        raise exception 'billing-cycle changes cannot decrease customer capacity'
          using errcode='22023';
      end if;
    end if;
  elsif p_cadence is not null or p_customer_capacity is not null then
    raise exception 'cadence and capacity are not valid for this command'
      using errcode='22023';
  end if;

  v_fingerprint:=encode(extensions.digest(convert_to(
    p_business::text||E'\n'||p_command_type||E'\n'||coalesce(p_cadence,'')
    ||E'\n'||coalesce(p_customer_capacity::text,'')
    ||E'\nv124_customer_capacity','utf8'
  ),'sha256'),'hex');
  select * into v_command from public.billing_commands
   where business_id=p_business and command_type=p_command_type
     and idempotency_key=p_idempotency_key;
  if found then
    if v_command.request_fingerprint<>v_fingerprint then
      raise exception 'billing command idempotency key conflicts with another request'
        using errcode='22023';
    end if;
  else
    insert into public.billing_commands(
      business_id,command_type,requested_cadence,pricing_model,
      requested_customer_capacity,billing_catalog_id_v124,
      idempotency_key,request_fingerprint,requested_by
    ) values (
      p_business,p_command_type,p_cadence,'v124_customer_capacity',
      p_customer_capacity,v_catalog.id,p_idempotency_key,v_fingerprint,v_actor
    ) returning * into v_command;
  end if;
  return jsonb_build_object(
    'command_id',v_command.id,'status',v_command.status,
    'command_type',v_command.command_type,'cadence',v_command.requested_cadence,
    'requested_customer_capacity',v_command.requested_customer_capacity,
    'redirect_url',v_command.redirect_url,'requested_at',v_command.requested_at
  );
end
$$;

--
-- Name: FUNCTION request_billing_command_v124(p_business uuid, p_command_type text, p_cadence text, p_customer_capacity integer, p_idempotency_key uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.request_billing_command_v124(p_business uuid, p_command_type text, p_cadence text, p_customer_capacity integer, p_idempotency_key uuid) IS 'Owner/super-admin V124 command request binding cadence and customer capacity.';

--
-- Name: request_billing_command_v77(uuid, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_billing_command_v77(p_business uuid, p_command_type text, p_cadence text, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_fingerprint text;
  v_command public.billing_commands%rowtype;
begin
  if v_actor is null
     or not (app.is_salon_owner(p_business) or app.is_super_admin()) then
    raise exception 'active owner or super-admin access is required'
      using errcode='42501';
  end if;
  if p_command_type not in (
    'create_checkout','create_portal','change_cadence',
    'cancel_at_period_end','resume'
  ) or p_idempotency_key is null then
    raise exception 'invalid billing command' using errcode='22023';
  end if;
  if p_command_type in ('create_checkout','change_cadence')
     and p_cadence not in ('quarterly','half_yearly','annual') then
    raise exception 'a canonical cadence is required' using errcode='22023';
  end if;
  if p_command_type not in ('create_checkout','change_cadence')
     and p_cadence is not null then
    raise exception 'cadence is not valid for this command' using errcode='22023';
  end if;
  v_fingerprint := encode(extensions.digest(convert_to(
    p_business::text||E'\n'||p_command_type||E'\n'||coalesce(p_cadence,''),
    'utf8'
  ),'sha256'),'hex');

  select * into v_command
    from public.billing_commands
   where business_id=p_business and command_type=p_command_type
     and idempotency_key=p_idempotency_key;
  if found then
    if v_command.request_fingerprint <> v_fingerprint then
      raise exception 'billing command idempotency key conflicts with another request'
        using errcode='22023';
    end if;
  else
    insert into public.billing_commands(
      business_id,command_type,requested_cadence,idempotency_key,
      request_fingerprint,requested_by
    ) values (
      p_business,p_command_type,p_cadence,p_idempotency_key,
      v_fingerprint,v_actor
    ) returning * into v_command;
  end if;
  return jsonb_build_object(
    'command_id',v_command.id,'status',v_command.status,
    'command_type',v_command.command_type,'cadence',v_command.requested_cadence,
    'redirect_url',v_command.redirect_url,'requested_at',v_command.requested_at
  );
end
$$;

--
-- Name: FUNCTION request_billing_command_v77(p_business uuid, p_command_type text, p_cadence text, p_idempotency_key uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.request_billing_command_v77(p_business uuid, p_command_type text, p_cadence text, p_idempotency_key uuid) IS 'Owner/SA command outbox. It never accepts or returns Stripe secrets and never treats a checkout redirect as payment truth.';

--
-- Name: request_booking(text, text, text, text, uuid, integer, timestamp with time zone, text, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_booking(p_slug text, p_name text, p_email text, p_phone text, p_service uuid, p_party integer, p_preferred timestamp with time zone, p_notes text, p_table_type uuid DEFAULT NULL::uuid, p_consent boolean DEFAULT false) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_biz uuid; v_overflow text; v_hold int; v_auto boolean;
  v_avail int; v_client uuid; v_id uuid; v_appt public.appointments; v_ttid uuid; v_dur int;
begin
  select id, booking_overflow, booking_hold_minutes, booking_auto_confirm
    into v_biz, v_overflow, v_hold, v_auto
    from public.businesses where slug = p_slug;
  if v_biz is null then raise exception 'business not found'; end if;
  if p_name is null or length(trim(p_name)) < 2 then raise exception 'name required'; end if;

  -- Services-only / salon style (no table): unchanged -> 'new', firm confirms manually.
  if p_table_type is null then
    insert into public.booking_requests (business_id, name, email, phone, service_id,
                                         party_size, preferred_at, notes, status, marketing_consent)
    values (v_biz, trim(p_name), p_email, p_phone, p_service, p_party, p_preferred, p_notes, 'new',
            coalesce(p_consent, false))
    returning id into v_id;
    return json_build_object('status','pending','request_id', v_id);
  end if;

  -- Table chosen: lock the type row to serialise concurrent draw-down, validate ownership.
  select bt.id into v_ttid
    from public.booking_tables bt
   where bt.id = p_table_type and bt.business_id = v_biz and bt.active
   for update;
  if v_ttid is null then raise exception 'invalid table type'; end if;

  select available into v_avail from public.v_table_availability where table_type_id = p_table_type;
  v_avail := coalesce(v_avail, 0);

  if v_avail > 0 then
    if v_auto then
      -- Auto-confirm: create client + real appointment (draws down), record confirmed request.
      v_client := app.upsert_portal_client(v_biz, p_name, p_phone, p_email);
      perform app.apply_booking_consent(v_biz, v_client, p_consent);
      v_dur := coalesce((select duration_min from public.services where id = p_service), 60);
      insert into public.appointments (business_id, client_id, service_id, starts_at, ends_at,
                                       status, party_size, source, note, table_type_id)
      values (v_biz, v_client, p_service,
              coalesce(p_preferred, now() + interval '1 day'),
              coalesce(p_preferred, now() + interval '1 day') + make_interval(mins => greatest(v_dur,1)),
              'booked', p_party, 'portal', p_notes, p_table_type)
      returning * into v_appt;
      insert into public.booking_requests (business_id, name, email, phone, service_id,
                                           party_size, preferred_at, notes, status,
                                           table_type_id, appointment_id, marketing_consent)
      values (v_biz, trim(p_name), p_email, p_phone, p_service, p_party, p_preferred, p_notes,
              'confirmed', p_table_type, v_appt.id, coalesce(p_consent, false))
      returning id into v_id;
      return json_build_object('status','confirmed','request_id', v_id, 'appointment_id', v_appt.id);
    else
      -- Manual-confirm firm: hold the table as 'pending' with a countdown (WS3).
      insert into public.booking_requests (business_id, name, email, phone, service_id,
                                           party_size, preferred_at, notes, status,
                                           table_type_id, expires_at, marketing_consent)
      values (v_biz, trim(p_name), p_email, p_phone, p_service, p_party, p_preferred, p_notes,
              'pending', p_table_type,
              case when v_hold > 0 then now() + make_interval(mins => v_hold) else null end,
              coalesce(p_consent, false))
      returning id into v_id;
      return json_build_object('status','pending','request_id', v_id);
    end if;
  else
    -- No capacity: overflow policy decides.
    if v_overflow = 'reject' then
      insert into public.booking_requests (business_id, name, email, phone, service_id,
                                           party_size, preferred_at, notes, status, table_type_id,
                                           marketing_consent)
      values (v_biz, trim(p_name), p_email, p_phone, p_service, p_party, p_preferred,
              trim(coalesce(p_notes,'') || ' [auto-declined: no capacity]'), 'declined', p_table_type,
              coalesce(p_consent, false))
      returning id into v_id;
      return json_build_object('status','rejected','request_id', v_id);
    else
      insert into public.booking_requests (business_id, name, email, phone, service_id,
                                           party_size, preferred_at, notes, status, table_type_id,
                                           marketing_consent)
      values (v_biz, trim(p_name), p_email, p_phone, p_service, p_party, p_preferred, p_notes,
              'waitlisted', p_table_type, coalesce(p_consent, false))
      returning id into v_id;
      insert into public.waitlist (business_id, name, phone, service_id, preferred, notes,
                                   status, booking_request_id, table_type_id)
      values (v_biz, trim(p_name), p_phone, p_service,
              to_char(coalesce(p_preferred, now()) at time zone 'Asia/Singapore', 'YYYY-MM-DD HH24:MI'),
              p_notes, 'waiting', v_id, p_table_type);
      return json_build_object('status','waitlisted','request_id', v_id);
    end if;
  end if;
end $$;

--
-- Name: request_change(text, uuid, text, text, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_change(p_slug text, p_appointment uuid, p_phone text, p_kind text, p_proposed timestamp with time zone, p_note text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_biz uuid; v_appt record; v_auto boolean; v_status text := 'pending'; v_id uuid;
begin
  select id, auto_approve_changes into v_biz, v_auto from public.businesses where slug = p_slug;
  if v_biz is null then raise exception 'business not found'; end if;
  if p_kind not in ('cancel','reschedule') then raise exception 'invalid kind: %', p_kind; end if;
  if p_kind = 'reschedule' and (p_proposed is null or p_proposed <= now()) then
    raise exception 'reschedule requires a future proposed time';
  end if;
  select a.*, c.phone as client_phone into v_appt
    from public.appointments a join public.clients c on c.id = a.client_id
   where a.id = p_appointment and a.business_id = v_biz;
  if not found then raise exception 'appointment not found'; end if;
  if v_appt.status <> 'booked' then raise exception 'appointment is not booked'; end if;
  if v_appt.client_phone is null
     or app.phone_match_key(p_phone) is null
     or app.phone_match_key(v_appt.client_phone) is distinct from app.phone_match_key(p_phone) then
    raise exception 'phone does not match this appointment';
  end if;
  insert into public.change_requests (business_id, appointment_id, kind, proposed_at, phone, note, status)
  values (v_biz, p_appointment, p_kind, p_proposed, trim(p_phone), p_note, 'pending')
  returning id into v_id;
  if v_auto then
    if p_kind = 'cancel' then
      update public.appointments set status = 'cancelled' where id = p_appointment and status = 'booked';
    elsif p_kind = 'reschedule' then
      update public.appointments
         set starts_at = p_proposed, ends_at = p_proposed + (ends_at - starts_at)
       where id = p_appointment and status = 'booked';
    end if;
    update public.change_requests set status = 'approved', decided_at = now() where id = v_id;
    v_status := 'approved';
  end if;
  return json_build_object('id', v_id, 'status', v_status);
end $$;

--
-- Name: request_self_serve_checkout_v130(uuid, text, integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_self_serve_checkout_v130(p_business uuid, p_cadence text, p_customer_capacity integer, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid:=auth.uid();
  v_onboarding public.self_serve_business_onboarding_v130%rowtype;
  v_catalog public.billing_plan_catalog_v124%rowtype;
  v_command public.billing_commands%rowtype;
  v_command_key uuid;
  v_fingerprint text;
begin
  if v_actor is null or p_idempotency_key is null then
    raise exception 'authenticated idempotent checkout required' using errcode='28000';
  end if;
  select * into v_onboarding
    from public.self_serve_business_onboarding_v130 onboarding
   where onboarding.business_id=p_business
     and onboarding.owner_user_id=v_actor for update;
  if not found or v_onboarding.status<>'payment_pending' then
    raise exception 'payment-pending self-service owner access required'
      using errcode='42501';
  end if;
  if p_cadence is distinct from v_onboarding.selected_cadence
     or p_customer_capacity is distinct from v_onboarding.selected_customer_capacity then
    raise exception 'checkout must use the locked onboarding selection'
      using errcode='22023';
  end if;
  if v_onboarding.checkout_command_id is not null then
    select * into strict v_command from public.billing_commands
     where id=v_onboarding.checkout_command_id;
    -- Reuse uncertain work and a conservatively still-live Checkout URL.
    -- Stripe's default maximum is 24 hours, so rotate completed sessions at
    -- 23 hours rather than ever returning an already expired redirect.
    if v_command.status in ('pending','processing','uncertain')
       or (v_command.status='completed'
           and v_command.requested_at>now()-interval '23 hours') then
      return jsonb_build_object(
        'command_id',v_command.id,'status',v_command.status,
        'cadence',v_command.requested_cadence,
        'requested_customer_capacity',v_command.requested_customer_capacity,
        'redirect_url',v_command.redirect_url,'replayed',true
      );
    end if;
  end if;
  select * into v_catalog from public.billing_plan_catalog_v124 catalog
   where catalog.id=v_onboarding.billing_catalog_id_v124
     and catalog.currency='SGD' and catalog.cadence=p_cadence
     and catalog.active and catalog.effective_from<=now()
     and (catalog.effective_to is null or catalog.effective_to>now());
  if not found then
    raise exception 'snapshotted Stripe plan is no longer available'
      using errcode='22023';
  end if;
  v_fingerprint:=app.v95_sha256(
    p_business::text||E'\ncreate_checkout\n'||p_cadence||E'\n'
    ||p_customer_capacity::text||E'\nv124_customer_capacity'
  );
  v_command_key:=case
    when v_onboarding.checkout_command_id is null then p_idempotency_key
    else gen_random_uuid()
  end;
  insert into public.billing_commands(
    business_id,command_type,requested_cadence,pricing_model,
    requested_customer_capacity,billing_catalog_id_v124,
    idempotency_key,request_fingerprint,requested_by
  ) values(
    p_business,'create_checkout',p_cadence,'v124_customer_capacity',
    p_customer_capacity,v_catalog.id,v_command_key,v_fingerprint,v_actor
  ) returning * into v_command;
  update public.self_serve_business_onboarding_v130
     set checkout_command_id=v_command.id,version=version+1,updated_at=now()
   where business_id=p_business;
  return jsonb_build_object(
    'command_id',v_command.id,'status',v_command.status,
    'cadence',v_command.requested_cadence,
    'requested_customer_capacity',v_command.requested_customer_capacity,
    'redirect_url',v_command.redirect_url,'replayed',false
  );
end
$$;

--
-- Name: FUNCTION request_self_serve_checkout_v130(p_business uuid, p_cadence text, p_customer_capacity integer, p_idempotency_key uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.request_self_serve_checkout_v130(p_business uuid, p_cadence text, p_customer_capacity integer, p_idempotency_key uuid) IS 'Creates or reuses the single server-priced Stripe Checkout command for pending onboarding.';

--
-- Name: request_self_serve_manual_application_v159(text, text, text, text, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_self_serve_manual_application_v159(p_contact_name text, p_contact_phone text, p_business_name text, p_sector_key text, p_registration_number text, p_locale text, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid:=auth.uid();
  v_email text;
  v_application jsonb;
begin
  if v_actor is null then
    raise exception 'authenticated owner account required'
      using errcode='28000';
  end if;

  select lower(email) into v_email
    from auth.users
   where id=v_actor
     and coalesce(email_confirmed_at,confirmed_at) is not null;

  if v_email is null then
    raise exception 'confirmed owner email required'
      using errcode='42501';
  end if;

  if exists(select 1 from public.staff where user_id=v_actor) then
    raise exception 'this account is already assigned to a business workspace'
      using errcode='42501';
  end if;

  v_application:=public.internal_submit_business_application_v95(
    p_contact_name,
    v_email,
    p_contact_phone,
    p_business_name,
    p_sector_key,
    p_registration_number,
    p_locale,
    p_idempotency_key
  );

  if coalesce((v_application->>'replayed')::boolean,false) is false then
    insert into public.audit_log(
      business_id,actor,action,entity,entity_id,detail
    ) values(
      null,v_actor,'SELF_SERVICE_MANUAL_APPLICATION_REQUESTED_V159',
      'business_applications_v95',(v_application->>'application_id')::uuid,
      jsonb_build_object(
        'source','self_serve_checkout_unavailable',
        'public_reference',v_application->>'public_reference',
        'replayed',false
      )
    );
  end if;

  return v_application||jsonb_build_object(
    'submitted_for_manual_help',true,
    'contact_email',v_email
  );
end
$$;

--
-- Name: FUNCTION request_self_serve_manual_application_v159(p_contact_name text, p_contact_phone text, p_business_name text, p_sector_key text, p_registration_number text, p_locale text, p_idempotency_key uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.request_self_serve_manual_application_v159(p_contact_name text, p_contact_phone text, p_business_name text, p_sector_key text, p_registration_number text, p_locale text, p_idempotency_key uuid) IS 'V159 authenticated fallback: when Stripe checkout catalogue is unavailable or the owner needs bank/cash handling, capture one admin-visible assisted application without activating access.';

--
-- Name: require_module_scope_v145(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.require_module_scope_v145(p_business uuid, p_branch uuid, p_module text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_dependency text;
  v_permission text;
begin
  if p_module is null or p_module not in (
    'dailyreport', 'staffperf', 'expenses', 'retention', 'appointments', 'clients',
    'reports', 'sales', 'loyalty', 'memberships', 'packages', 'referrals'
  ) then
    raise exception 'unsupported metric module'
      using errcode = '22023';
  end if;
  v_permission := case when p_module in ('staffperf', 'expenses')
    then 'view_finance' else 'view_sales' end;
  if auth.uid() is null or not app.has_perm(p_business, v_permission) then
    raise exception 'metric module permission required:%', p_module
      using errcode = '42501';
  end if;
  perform app.require_metric_module_scope_v145(p_business, p_branch, p_module);
  for v_dependency in
    select dependency
    from public.module_registry registry
    cross join lateral unnest(registry.requires_modules) dependency
    where registry.module_key = p_module
  loop
    perform app.require_metric_module_scope_v145(
      p_business, p_branch, v_dependency
    );
  end loop;
  return jsonb_build_object(
    'status', 'ok',
    'module', p_module,
    'branch_id', p_branch
  );
end;
$$;

--
-- Name: reschedule_appointment_v48(uuid, uuid, timestamp with time zone, integer, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reschedule_appointment_v48(p_business uuid, p_appointment uuid, p_starts timestamp with time zone, p_duration_minutes integer, p_staff uuid, p_note text, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_branch uuid;
begin
  select branch_id into v_branch from public.appointments
  where id=p_appointment and business_id=p_business;
  perform app.require_branch_module_v94(
    p_business,v_branch,'appointments','rw'
  );
  return public.reschedule_appointment_v48_v94_base(
    p_business,p_appointment,p_starts,p_duration_minutes,p_staff,p_note,
    p_idempotency_key
  );
end
$$;

--
-- Name: reschedule_appointment_v48_v94_base(uuid, uuid, timestamp with time zone, integer, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reschedule_appointment_v48_v94_base(p_business uuid, p_appointment uuid, p_starts timestamp with time zone, p_duration_minutes integer, p_staff uuid, p_note text, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'extensions', 'pg_temp'
    AS $$
declare
  v_actor uuid:=auth.uid();
  v_appointment public.appointments%rowtype;
  v_existing app.appointment_reschedule_operations%rowtype;
  v_request_hash text;
  v_ends timestamptz;
  v_note text:=nullif(btrim(coalesce(p_note,'')),'');
  v_suggestions jsonb;
  v_response jsonb;
  v_identity public.customer_identities%rowtype;
  v_link public.customer_links%rowtype;
  v_notification_state text:='unavailable';
  v_source_fingerprint text;
  v_dedupe_key text;
begin
  if v_actor is null or not app.can_module_write(p_business,'appointments') then
    raise exception 'appointment write access is required' using errcode='42501';
  end if;
  if p_appointment is null or p_staff is null or p_starts is null
     or p_idempotency_key is null or p_duration_minutes not between 15 and 720 then
    raise exception 'appointment, future time, duration, staff and idempotency key are required'
      using errcode='22023';
  end if;
  if p_starts<=clock_timestamp() then
    raise exception 'appointment start must be in the future' using errcode='22023';
  end if;
  if p_note is not null and (char_length(p_note)>1000 or p_note is distinct from btrim(p_note)) then
    raise exception 'appointment note must be trimmed and at most 1000 characters'
      using errcode='22023';
  end if;
  v_ends:=p_starts+make_interval(mins=>p_duration_minutes);
  v_request_hash:=app.c46_sha256_hex(jsonb_build_object(
    'business_id',p_business,'appointment_id',p_appointment,'starts_at',p_starts,
    'duration_minutes',p_duration_minutes,'staff_id',p_staff,'note',v_note
  )::text);

  perform pg_advisory_xact_lock(hashtextextended(
    'v48:appointment-reschedule:'||p_business::text||':'||p_idempotency_key::text,0));
  select operation.* into v_existing from app.appointment_reschedule_operations operation
   where operation.business_id=p_business and operation.idempotency_key=p_idempotency_key;
  if found then
    if v_existing.request_hash is distinct from v_request_hash then
      raise exception 'idempotency key was already used for a different appointment change'
        using errcode='22023';
    end if;
    return v_existing.response||jsonb_build_object('replayed',true);
  end if;

  perform pg_advisory_xact_lock(hashtextextended(
    'v48:appointment:'||p_business::text||':'||p_appointment::text,0));
  select appointment.* into v_appointment from public.appointments appointment
   where appointment.id=p_appointment and appointment.business_id=p_business for update;
  if not found or not app.can_see_branch(p_business,v_appointment.branch_id) then
    raise exception 'appointment not found for this branch scope' using errcode='42501';
  end if;
  if v_appointment.status<>'booked' then
    raise exception 'only a booked appointment can be amended' using errcode='22023';
  end if;
  if not exists(select 1 from public.branches branch
                 where branch.id=v_appointment.branch_id
                   and branch.business_id=p_business and branch.active) then
    raise exception 'appointment branch is not active' using errcode='22023';
  end if;
  if v_appointment.service_id is not null and not exists(
    select 1 from public.services service
     where service.id=v_appointment.service_id and service.business_id=p_business and service.active
       and (
         not exists(select 1 from public.service_branches configured
                     where configured.business_id=p_business
                       and configured.service_id=v_appointment.service_id)
         or exists(select 1 from public.service_branches allowed
                    where allowed.business_id=p_business
                      and allowed.service_id=v_appointment.service_id
                      and allowed.branch_id=v_appointment.branch_id)
       )
  ) then
    raise exception 'appointment service is not active at this branch' using errcode='22023';
  end if;
  if not exists(
    select 1 from public.staff staff
    join public.staff_branches staff_branch
      on staff_branch.business_id=staff.business_id and staff_branch.staff_id=staff.id
     and staff_branch.branch_id=v_appointment.branch_id
   where staff.id=p_staff and staff.business_id=p_business and staff.active
  ) then
    raise exception 'assigned staff must be active at this branch' using errcode='22023';
  end if;
  if v_appointment.starts_at=p_starts and v_appointment.ends_at=v_ends
     and v_appointment.staff_id is not distinct from p_staff
     and v_appointment.note is not distinct from v_note then
    raise exception 'choose a different date, time, duration, staff member or note'
      using errcode='22023';
  end if;

  -- Join v47's exact per-business scheduling lock domain. New bookings and every
  -- reschedule therefore serialize their final availability check and mutation.
  perform pg_advisory_xact_lock(hashtextextended(p_business::text,47));

  if not app.staff_free_for_appointment_v47(
    p_business,p_staff,v_appointment.branch_id,v_appointment.service_id,
    p_starts,v_ends,p_appointment
  ) then
    v_suggestions:=app.suggest_appointment_reschedule_v48(
      p_business,p_appointment,v_appointment.branch_id,v_appointment.service_id,
      p_starts,p_duration_minutes,5
    );
    v_response:=jsonb_build_object(
      'status','conflict','replayed',false,'appointment_id',p_appointment,
      'notification_state','not_applicable','suggestions',v_suggestions
    );
    insert into app.appointment_reschedule_operations(
      business_id,idempotency_key,request_hash,appointment_id,actor,
      old_starts_at,old_ends_at,old_staff_id,requested_starts_at,requested_ends_at,
      requested_staff_id,outcome,notification_state,response
    ) values (
      p_business,p_idempotency_key,v_request_hash,p_appointment,v_actor,
      v_appointment.starts_at,v_appointment.ends_at,v_appointment.staff_id,
      p_starts,v_ends,p_staff,'conflict','not_applicable',v_response
    );
    return v_response;
  end if;

  update public.appointments
     set starts_at=p_starts,ends_at=v_ends,staff_id=p_staff,note=v_note
   where id=p_appointment and business_id=p_business;

  if app.platform_feature_enabled('customer_in_app_inbox') then
    v_notification_state:='not_applicable';
    select link.* into v_link from public.customer_links link
     where link.business_id=p_business and link.client_id=v_appointment.client_id
       and link.state='verified' order by link.verified_at desc,link.id limit 1;
    if found then
      select identity.* into v_identity from public.customer_identities identity
       where identity.id=v_link.identity_id and identity.auth_user_id=v_link.auth_user_id
         and identity.status='active';
      if found then
        if exists(
          select 1 from public.customer_notification_preferences preference
           where preference.business_id=p_business and preference.identity_id=v_identity.id
             and preference.auth_user_id=v_identity.auth_user_id
             and preference.link_id=v_link.id and preference.client_id=v_appointment.client_id
             and preference.channel='in_app' and preference.topic='booking_updates'
             and preference.opted_in
        ) then
          v_source_fingerprint:=app.c46_sha256_hex(jsonb_build_object(
            'appointment_id',p_appointment,'starts_at',p_starts,'ends_at',v_ends
          )::text);
          v_dedupe_key:=app.c46_sha256_hex(jsonb_build_object(
            'identity_id',v_identity.id,'source_kind','v48_appointment_reschedule',
            'source_fingerprint',v_source_fingerprint,'idempotency_key',p_idempotency_key
          )::text);
          insert into public.customer_in_app_inbox_events(
            business_id,identity_id,auth_user_id,link_id,client_id,source_kind,topic,
            route_key,source_fingerprint,dedupe_key,title,body,deadline_at
          ) values (
            p_business,v_identity.id,v_identity.auth_user_id,v_link.id,
            v_appointment.client_id,'v48_appointment_reschedule','booking_updates',
            'wallet_business',v_source_fingerprint,v_dedupe_key,'Appointment time changed',
            'Open this business wallet to review your updated appointment.',p_starts
          ) on conflict (identity_id,dedupe_key) do nothing;
          v_notification_state:='in_app_created';
        else
          v_notification_state:='suppressed';
        end if;
      end if;
    end if;
  end if;

  v_response:=jsonb_build_object(
    'status','rescheduled','replayed',false,'appointment_id',p_appointment,
    'starts_at',p_starts,'ends_at',v_ends,'staff_id',p_staff,
    'notification_state',v_notification_state
  );
  insert into app.appointment_reschedule_operations(
    business_id,idempotency_key,request_hash,appointment_id,actor,
    old_starts_at,old_ends_at,old_staff_id,requested_starts_at,requested_ends_at,
    requested_staff_id,outcome,notification_state,response
  ) values (
    p_business,p_idempotency_key,v_request_hash,p_appointment,v_actor,
    v_appointment.starts_at,v_appointment.ends_at,v_appointment.staff_id,
    p_starts,v_ends,p_staff,'rescheduled',v_notification_state,v_response
  );
  insert into public.audit_log(business_id,actor,action,entity,entity_id,detail)
  values (p_business,v_actor,'APPOINTMENT_RESCHEDULE_V48','appointments',p_appointment,
    jsonb_build_object(
      'from_starts_at',v_appointment.starts_at,'to_starts_at',p_starts,
      'from_ends_at',v_appointment.ends_at,'to_ends_at',v_ends,
      'from_staff_id',v_appointment.staff_id,'to_staff_id',p_staff,
      'notification_state',v_notification_state,'idempotency_key',p_idempotency_key
    ));
  return v_response;
end
$$;

--
-- Name: reserve_checkout_sv_tender(uuid, uuid, integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reserve_checkout_sv_tender(p_business uuid, p_evaluation_id uuid, p_requested_cents integer, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_eval public.checkout_evaluations%rowtype;
  v_currency text;
  v_account uuid;
  v_existing public.checkout_sv_tenders%rowtype;
  v_prior public.checkout_sv_tenders%rowtype;
  v_available integer;
  v_amount integer;
  v_reserve jsonb;
  v_row_id uuid := gen_random_uuid();
begin
  if v_actor is null then
    raise exception 'authenticated staff required to add stored value to a checkout' using errcode = '42501';
  end if;
  if not app.has_perm(p_business, 'create_sales') then
    raise exception 'you do not have permission to add stored value to a checkout (create_sales)' using errcode = '42501';
  end if;
  if p_idempotency_key is null then
    raise exception 'a stored-value tender idempotency key is required' using errcode = '22023';
  end if;
  if p_requested_cents is null or p_requested_cents < 1 then
    raise exception 'a stored-value tender must request a whole number of at least 1 cent' using errcode = '22023';
  end if;

  select * into v_eval from public.checkout_evaluations
   where id = p_evaluation_id and business_id = p_business for update;
  if not found then
    raise exception 'checkout evaluation not found in this business' using errcode = '42501';
  end if;
  if not app.can_see_branch(p_business, v_eval.branch_id) then
    raise exception 'you are not permitted to tender for this branch scope' using errcode = '42501';
  end if;
  if v_eval.client_id is null then
    raise exception 'stored value needs a named customer on the checkout' using errcode = '22023';
  end if;
  if v_eval.consumed_at is not null then
    raise exception 'stale_evaluation: this checkout is already finalised; re-evaluate' using errcode = '22023';
  end if;
  if v_eval.expires_at <= now() then
    raise exception 'stale_evaluation: the checkout evaluation has expired; re-evaluate' using errcode = '22023';
  end if;

  -- Tender gate: authority live, no synthetic on live, redeem pause, currency.
  v_currency := app.sv_checkout_tender_gate(p_business, v_eval.client_id, null);

  -- Serialize per (business, evaluation) so a double opt-in is idempotent, not a double reservation.
  perform pg_advisory_xact_lock(hashtextextended('v67:tender:' || p_business::text || ':' || p_evaluation_id::text, 0));

  v_account := app.sv_ensure_account(p_business, v_eval.client_id);

  -- Exact replay: an active tender for THIS evaluation under THIS key returns unchanged.
  select * into v_existing from public.checkout_sv_tenders
   where business_id = p_business and evaluation_id = p_evaluation_id and status = 'reserved'
   order by created_at desc limit 1 for update;
  if found and v_existing.idempotency_key = p_idempotency_key then
    return jsonb_build_object(
      'status', 'ok', 'replayed', true, 'evaluation_id', p_evaluation_id, 'account_id', v_account,
      'reservation_id', v_existing.reservation_id, 'reserved_cents', v_existing.reserved_cents,
      'requested_cents', v_existing.requested_cents, 'bill_total_cents', v_eval.total_cents,
      'remaining_due_cents', greatest(v_eval.total_cents - v_existing.reserved_cents, 0), 'currency', v_currency);
  end if;

  -- Supersede any prior active tender for THIS account (re-evaluation / re-bind releases the prior).
  for v_prior in
    select * from public.checkout_sv_tenders
     where business_id = p_business and account_id = v_account and status = 'reserved'
     for update
  loop
    perform app.sv_release_core(p_business, v_prior.reservation_id, gen_random_uuid());
    update public.checkout_sv_tenders
       set status = 'released', released_reason = 'superseded', updated_at = now()
     where id = v_prior.id;
  end loop;

  v_available := coalesce(app.sv_available_balance(p_business, v_account), 0);
  v_amount := least(p_requested_cents, v_available, v_eval.total_cents);
  if v_amount < 1 then
    raise exception 'sv_no_coverage: this customer has no spendable stored value for this checkout' using errcode = '22023';
  end if;

  v_reserve := app.sv_reserve_core(p_business, v_account, v_amount, p_idempotency_key);

  -- The two unique constraints that can fire here are both "this customer's checkout hold is
  -- already spoken for", and both must reach the till as a TYPED refusal rather than a raw 23505:
  --   * checkout_sv_tenders_reservation_uk - reusing a reserve idempotency key across tokens.
  --     app.sv_reserve_core replays the stored result, so the SUPERSEDED (already released)
  --     reservation_id comes back and collides. Deterministic, not a race.
  --   * checkout_sv_tenders_active_uk - two tokens binding the same account concurrently, where the
  --     loser's supersede scan ran before the winner committed.
  -- Catching here changes nothing else: the idempotent-replay path returned long before this point,
  -- and both advisory locks are transaction-scoped, so the handler perturbs no lock or replay
  -- semantics - it only re-labels an error that already aborted the transaction.
  begin
    insert into public.checkout_sv_tenders(
      id, business_id, evaluation_id, account_id, reservation_id, reserve_operation_id, idempotency_key,
      requested_cents, reserved_cents, currency, status)
    values (
      v_row_id, p_business, p_evaluation_id, v_account,
      (v_reserve->>'reservation_id')::uuid, (v_reserve->>'operation_id')::uuid, p_idempotency_key,
      p_requested_cents, v_amount, v_currency, 'reserved');
  exception when unique_violation then
    raise exception 'sv_tender_conflict: this customer''s stored value is already held by another checkout or tender key; re-evaluate and bind with a fresh key'
      using errcode = '22023';
  end;

  insert into public.audit_log(business_id, actor, action, entity, entity_id, detail)
  values (p_business, v_actor, 'SV_CHECKOUT_TENDER_RESERVED', 'checkout_sv_tenders', v_row_id, jsonb_build_object(
    'evaluation_id', p_evaluation_id, 'account_id', v_account, 'reserved_cents', v_amount,
    'requested_cents', p_requested_cents, 'reservation_id', (v_reserve->>'reservation_id')::uuid));

  return jsonb_build_object(
    'status', 'ok', 'replayed', false, 'evaluation_id', p_evaluation_id, 'account_id', v_account,
    'reservation_id', (v_reserve->>'reservation_id')::uuid, 'reserved_cents', v_amount,
    'requested_cents', p_requested_cents, 'bill_total_cents', v_eval.total_cents,
    'remaining_due_cents', greatest(v_eval.total_cents - v_amount, 0), 'currency', v_currency);
end $$;

--
-- Name: resolve_legacy_referral(uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_legacy_referral(p_business uuid, p_referral uuid, p_selected_sale uuid DEFAULT NULL::uuid, p_reason text DEFAULT NULL::text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_staff uuid;
  v_reason text := nullif(btrim(p_reason), '');
  v_decision text := case when p_selected_sale is null then 'no_link' else 'selected_sale' end;
  v_event public.legacy_referral_resolution_events%rowtype;
  v_sale public.sales%rowtype;
begin
  if v_reason is null or length(v_reason) < 10 then
    raise exception 'legacy referral resolution reason must be at least 10 characters';
  end if;
  if not app.has_perm(p_business, 'refund_sales') then
    raise exception 'you do not have permission to resolve legacy referrals in this business'
      using errcode = '42501';
  end if;
  if not exists (
    select 1 from public.legacy_referral_provenance p
     where p.referral_id = p_referral and p.business_id = p_business
  ) then
    raise exception 'legacy referral provenance was not captured for this business';
  end if;
  if p_selected_sale is not null then
    select * into v_sale from public.sales s
     where s.id = p_selected_sale and s.business_id = p_business;
    if not found or not exists (
      select 1 from public.legacy_referral_sale_candidates c
       where c.referral_id = p_referral
         and c.business_id = p_business
         and c.sale_id = p_selected_sale
    ) then
      raise exception 'selected sale is not a captured candidate for this legacy referral';
    end if;
    if not app.can_see_branch(p_business, v_sale.branch_id) then
      raise exception 'you are not permitted to resolve a referral for this branch scope'
        using errcode = '42501';
    end if;
  end if;

  select s.id into v_staff from public.staff s
   where s.business_id = p_business
     and s.user_id = v_actor
     and s.active
     and 'refund_sales' = any (app.role_perms(s.role))
   order by case s.role when 'owner' then 0 when 'manager' then 1 else 2 end, s.created_at
   limit 1
   for update;
  if not found then
    raise exception 'active refund-authorized staff is required to resolve legacy referrals'
      using errcode = '42501';
  end if;
  perform 1 from public.legacy_referral_provenance p
   where p.referral_id = p_referral and p.business_id = p_business for update;
  if not found then
    raise exception 'legacy referral provenance changed while authorization was being locked';
  end if;
  perform 1 from public.referrals rf
   where rf.id = p_referral
     and rf.business_id = p_business
     and rf.status = 'rewarded'
     and (rf.qualified_sale_id is null
          or rf.qualified_sale_id is not distinct from p_selected_sale)
   for update;
  if not found then
    raise exception 'legacy referral is no longer an unresolved rewarded referral'
      using errcode = '55000';
  end if;
  if p_selected_sale is not null then
    select * into v_sale from public.sales s
     where s.id = p_selected_sale and s.business_id = p_business for update;
    if not found or not exists (
      select 1 from public.legacy_referral_sale_candidates c
       where c.referral_id = p_referral
         and c.business_id = p_business
         and c.sale_id = p_selected_sale
    ) then
      raise exception 'selected legacy referral candidate changed while being locked';
    end if;
  end if;
  if not app.has_perm(p_business, 'refund_sales')
     or (p_selected_sale is not null
         and not app.can_see_branch(p_business, v_sale.branch_id)) then
    raise exception 'legacy referral authorization changed while the operation was being locked'
      using errcode = '42501';
  end if;

  insert into public.legacy_referral_resolution_events(
    referral_id, business_id, actor, decision, selected_sale_id, reason
  ) values (p_referral, p_business, v_actor, v_decision, p_selected_sale, v_reason)
  on conflict (referral_id) do nothing
  returning * into v_event;
  if v_event.id is null then
    select * into v_event from public.legacy_referral_resolution_events e
     where e.referral_id = p_referral;
    if not found
       or (v_event.business_id, v_event.actor, v_event.decision,
           v_event.selected_sale_id, v_event.reason)
          is distinct from
          (p_business, v_actor, v_decision, p_selected_sale, v_reason) then
      raise exception 'legacy referral already has a different immutable resolution'
        using errcode = '23505';
    end if;
    return (to_jsonb(v_event) || jsonb_build_object('replayed', true))::json;
  end if;

  if p_selected_sale is not null then
    update public.referrals
       set qualified_sale_id = p_selected_sale
     where id = p_referral and business_id = p_business and qualified_sale_id is null;
    if not found then
      raise exception 'legacy referral cannot accept the selected sale link'
        using errcode = '55000';
    end if;
  end if;
  return (to_jsonb(v_event) || jsonb_build_object('replayed', false))::json;
end $$;

--
-- Name: retention_lapsed_candidates_v244(uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.retention_lapsed_candidates_v244(p_business uuid, p_lapsed_days integer, p_min_visits integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_cap constant integer := 20000;
  v_lapsed integer := greatest(1, least(365, coalesce(p_lapsed_days, 45)));
  v_min integer := greatest(1, least(99, coalesce(p_min_visits, 3)));
  v_today date := (now() at time zone 'Asia/Singapore')::date;
  v_total bigint;
  v_rows jsonb;
begin
  -- Same gate the browser applied before its raw table reads (raises 42501).
  perform public.require_module_scope_v145(p_business, null, 'retention');

  with visit_rows as (
    select s.id, s.client_id, s.occurred_at, s.reversal_of
    from public.sales s
    where s.business_id = p_business
      and s.counts_as_visit = true
  ),
  valid_visits as (
    -- validVisitSales: reversals are never visits; a reversed original is out.
    select v.client_id, v.occurred_at
    from visit_rows v
    where v.reversal_of is null
      and not exists (
        select 1 from visit_rows r where r.reversal_of = v.id
      )
  ),
  per_client as (
    select vv.client_id,
           count(*)::integer as net_visits,
           max(vv.occurred_at) as last_visit_at
    from valid_visits vv
    group by vv.client_id
  ),
  candidates as (
    select c.id, c.full_name, c.phone,
           pc.net_visits,
           greatest(0, v_today - (pc.last_visit_at at time zone 'Asia/Singapore')::date)::integer
             as last_visit_days
    from per_client pc
    join public.clients c
      on c.id = pc.client_id and c.business_id = p_business
    where pc.net_visits >= v_min
      and greatest(0, v_today - (pc.last_visit_at at time zone 'Asia/Singapore')::date) >= v_lapsed
  )
  select count(*),
         coalesce(jsonb_agg(x.row order by x.last_visit_days desc, x.id)
                    filter (where x.rank <= v_cap), '[]'::jsonb)
    into v_total, v_rows
    from (
      select cand.id, cand.last_visit_days,
             row_number() over (order by cand.last_visit_days desc, cand.id) as rank,
             jsonb_build_object(
               'id', cand.id,
               'full_name', cand.full_name,
               'phone', cand.phone,
               'net_visits', cand.net_visits,
               'last_visit_days', cand.last_visit_days
             ) as row
      from candidates cand
    ) x;

  return jsonb_build_object(
    'candidates', v_rows,
    'total', coalesce(v_total, 0),
    'truncated', coalesce(v_total, 0) > v_cap
  );
end;
$$;

--
-- Name: FUNCTION retention_lapsed_candidates_v244(p_business uuid, p_lapsed_days integer, p_min_visits integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.retention_lapsed_candidates_v244(p_business uuid, p_lapsed_days integer, p_min_visits integer) IS 'v244: server-side bring-back audience. Replaces the browser downloading every client and every visit-marked sale (fetchAllRows) to compute lapsed regulars. Visit validity, SG calendar-day lapse and the >=min-visits filter reproduce app/app.js validVisitSales + pbComputeCandidates exactly; authorization is the same require_module_scope_v145(business, null, retention) the client called. Capped at 20000 candidates with an honest truncated flag — the UI must refuse to freeze a truncated audience.';

--
-- Name: retire_sv_plan(uuid, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.retire_sv_plan(p_business uuid, p_plan uuid, p_reason text, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid(); v_reason text := nullif(btrim(coalesce(p_reason,'')),''); v_active boolean;
  v_hash text; v_hit jsonb; v_result jsonb;
begin
  if not app.is_salon_owner(p_business) then raise exception 'owner only' using errcode = '42501'; end if;
  if v_reason is null or char_length(v_reason) < 3 then raise exception 'retiring a stored-value plan requires a reason of at least 3 characters' using errcode = '22023'; end if;
  v_hash := app.ps1b_sha256(jsonb_build_object('op','retire','business',p_business,'plan',p_plan,'reason',v_reason)::text);
  v_hit := app.sv_plan_idem_lookup(p_business, 'retire', p_idempotency_key, v_hash);
  if v_hit is not null then return v_hit; end if;

  select active into v_active from public.sv_plans where id = p_plan and business_id = p_business for update;
  if not found then raise exception 'stored-value plan does not belong to this business' using errcode = '22023'; end if;
  if v_active is true then
    update public.sv_plans set active = false where id = p_plan and business_id = p_business;
    insert into public.sv_plan_status_events(business_id, plan_id, actor, prior_status, new_status, reason)
    values (p_business, p_plan, v_actor, 'active', 'retired', v_reason);
    insert into public.audit_log(business_id, actor, action, entity, entity_id, detail)
    values (p_business, v_actor, 'SV_PLAN_RETIRED', 'sv_plans', p_plan, jsonb_build_object('reason', v_reason));
    v_result := jsonb_build_object('status','ok','plan_id',p_plan,'active',false,'replayed',false);
  else
    v_result := jsonb_build_object('status','ok','plan_id',p_plan,'active',false,'replayed',true);
  end if;
  insert into public.sv_plan_operations(business_id, op_type, idempotency_key, request_hash, actor, result)
  values (p_business, 'retire', p_idempotency_key, v_hash, v_actor, v_result);
  return v_result;
end $$;

--
-- Name: retry_growth_delivery_v110(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.retry_growth_delivery_v110(p_business uuid, p_dispatch uuid, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_identity text;
  v_hash text;
  v_receipt jsonb;
  v_event public.growth_delivery_state_events_v110%rowtype;
  v_dispatch public.growth_delivery_dispatches_v110%rowtype;
  v_dispatch_branch uuid;
begin
  if not app.is_salon_owner(p_business)
     or not app.can_module_write(p_business, 'retention') then
    raise exception 'owner retention access required' using errcode = '42501';
  end if;
  select d.branch_id into v_dispatch_branch
  from public.growth_delivery_dispatches_v110 d
  where d.id = p_dispatch and d.business_id = p_business;
  if not found then
    raise exception 'dispatch not found';
  end if;
  if not app.can_see_branch(p_business, v_dispatch_branch) then
    raise exception 'delivery branch is outside actor scope'
      using errcode = '42501';
  end if;
  v_identity := app.v112_hash(jsonb_build_object(
    'operation', 'retry_growth_delivery_v110',
    'business_id', p_business, 'dispatch_id', p_dispatch,
    'actor', v_actor, 'idempotency_key', p_idempotency_key
  ));
  v_hash := app.v112_hash(jsonb_build_object(
    'business_id', p_business, 'dispatch_id', p_dispatch
  ));
  perform app.v112_lock_dispatch(p_dispatch);
  perform app.v112_lock_pair(
    'v112-v110-retry-request:' || v_identity,
    'v112-v110-retry-request:' || v_identity
  );
  v_receipt := app.v112_get_receipt(v_identity, v_hash);
  if v_receipt is not null then return v_receipt; end if;
  v_receipt := public.retry_growth_delivery_v110_v112_inner(
    p_business, p_dispatch, p_idempotency_key
  );
  select * into strict v_dispatch
  from public.growth_delivery_dispatches_v110
  where id = p_dispatch;
  select * into strict v_event
  from public.growth_delivery_state_events_v110
  where dispatch_id = p_dispatch and idempotency_key = p_idempotency_key;
  v_receipt := v_receipt || jsonb_build_object(
    'next_attempt_at', v_dispatch.next_attempt_at,
    'retry_policy', v_event.detail -> 'v112_backoff'
  );
  return app.v112_put_receipt(
    v_identity, 'retry_growth_delivery_v110', v_hash,
    jsonb_build_object(
      'business_id', p_business, 'dispatch_id', p_dispatch,
      'actor', v_actor
    ),
    v_receipt
  );
end $$;

--
-- Name: retry_growth_delivery_v110_v112_inner(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.retry_growth_delivery_v110_v112_inner(p_business uuid, p_dispatch uuid, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  perform app.v112_lock_dispatch(p_dispatch);
  return public.retry_growth_delivery_v110_v112_unsafe_row_inner(
    p_business, p_dispatch, p_idempotency_key
  );
end $$;

--
-- Name: retry_growth_delivery_v110_v112_unsafe_row_inner(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.retry_growth_delivery_v110_v112_unsafe_row_inner(p_business uuid, p_dispatch uuid, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_dispatch public.growth_delivery_dispatches_v110%rowtype;
begin
  if not app.is_salon_owner(p_business)
     or not app.can_module_write(p_business, 'retention') then
    raise exception 'owner retention access required' using errcode = '42501';
  end if;
  select * into strict v_dispatch
  from public.growth_delivery_dispatches_v110
  where id = p_dispatch and business_id = p_business for update;
  if not app.can_see_branch(v_dispatch.business_id, v_dispatch.branch_id) then
    raise exception 'delivery branch is outside actor scope' using errcode = '42501';
  end if;
  if v_dispatch.lifecycle_status <> 'failed' or v_dispatch.attempt_count >= 5 then
    raise exception 'only failed deliveries below retry limit can be retried'
      using errcode = '22023';
  end if;
  v_dispatch := app.v110_transition_delivery(
    p_dispatch, 'queued', null, null, p_idempotency_key,
    jsonb_build_object('owner_retry', true)
  );
  return jsonb_build_object(
    'dispatch_id', v_dispatch.id,
    'status', v_dispatch.lifecycle_status,
    'attempt_count', v_dispatch.attempt_count
  );
end $$;

--
-- Name: reverse_customer_birthday_benefit_for_client(uuid, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reverse_customer_birthday_benefit_for_client(p_business_id uuid, p_client_id uuid, p_reason text, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_redemption_id uuid;
begin
  if not app.platform_feature_enabled('customer_birthday_benefits') then
    raise exception 'birthday benefit unavailable' using errcode='0A000';
  end if;
  if auth.uid() is null or not app.c45_owner_loyalty_write(p_business_id)
     or not exists(select 1 from public.clients c where c.id=p_client_id and c.business_id=p_business_id) then
    raise exception 'birthday benefit unavailable' using errcode='42501';
  end if;
  -- Preserve an exact retry even after the original redemption is no longer
  -- live. The underlying reversal RPC compares the reason hash and rejects a
  -- changed request with 40001.
  select original_redemption_id into v_redemption_id
    from public.customer_birthday_redemptions
   where business_id=p_business_id and client_id=p_client_id and actor=auth.uid()
     and operation_kind='reversal' and idempotency_key=p_idempotency_key
   order by created_at desc,id desc
   limit 1 for share;
  if found then
    return app.reverse_customer_birthday_benefit_redemption(v_redemption_id,p_reason,p_idempotency_key);
  end if;
  select id into v_redemption_id
    from public.customer_birthday_redemptions
   where business_id=p_business_id and client_id=p_client_id
     and operation_kind='redemption' and active
   order by created_at desc,id desc
   limit 1 for update;
  if not found then
    -- A same-key concurrent reversal can commit while this statement waits on
    -- the active-redemption row and therefore leaves no active row to return.
    -- Resolve that exact replay before reporting unavailability.
    select original_redemption_id into v_redemption_id
      from public.customer_birthday_redemptions
     where business_id=p_business_id and client_id=p_client_id and actor=auth.uid()
       and operation_kind='reversal' and idempotency_key=p_idempotency_key
     order by created_at desc,id desc limit 1 for share;
    if not found then raise exception 'birthday benefit unavailable' using errcode='42501'; end if;
  end if;
  return app.reverse_customer_birthday_benefit_redemption(v_redemption_id,p_reason,p_idempotency_key);
end $$;

--
-- Name: reverse_customer_identity_correction_v111(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reverse_customer_identity_correction_v111(p_proposal uuid, p_reason text, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid:=auth.uid();
  v_proposal public.customer_identity_proposals_v111%rowtype;
  v_payload jsonb;
  v_hash text;
  v_existing public.customer_identity_request_ledger_v111%rowtype;
  v_approval uuid;
  v_decision uuid;
  v_event uuid;
  v_before jsonb;
  v_after jsonb;
  v_receipt jsonb;
begin
  if v_actor is null then raise exception 'authentication required' using errcode='42501'; end if;
  if p_idempotency_key is null then
    raise exception 'idempotency key is required' using errcode='22023';
  end if;
  select * into v_proposal from public.customer_identity_proposals_v111
   where id=p_proposal;
  if not found then raise exception 'identity proposal not found' using errcode='23503'; end if;
  if not app.v111_can_decide(v_proposal.business_id) then
    raise exception 'owner or global business authority is required to reverse'
      using errcode='42501';
  end if;
  p_reason:=nullif(btrim(p_reason),'');
  if p_reason is null or length(p_reason)>500 then
    raise exception 'reversal reason is required' using errcode='22023';
  end if;
  v_payload:=jsonb_build_object('operation','reverse','proposal_id',p_proposal,'reason',p_reason);
  v_hash:=app.v111_request_hash(v_payload);
  perform pg_advisory_xact_lock(hashtextextended(
    'v111:request:'||v_actor||':'||p_idempotency_key,0
  ));
  select * into v_existing from public.customer_identity_request_ledger_v111
   where actor_auth_user_id=v_actor and idempotency_key=p_idempotency_key;
  if found then
    if v_existing.operation<>'reverse' or v_existing.request_hash<>v_hash then
      raise exception 'idempotency key was already used for a different identity mutation'
        using errcode='23505';
    end if;
    return v_existing.receipt;
  end if;
  select * into v_proposal from public.customer_identity_proposals_v111
   where id=p_proposal for update;
  if not found then raise exception 'identity proposal not found' using errcode='23503'; end if;
  perform pg_advisory_xact_lock(hashtextextended(
    'v111:source:'||v_proposal.business_id||':'||v_proposal.source_client_id,0
  ));
  if v_proposal.status='reversed' then
    select id into v_decision from public.customer_identity_decisions_v111
     where proposal_id=p_proposal and decision_type='reverse';
    select id into v_event from public.customer_identity_attribution_events_v111
     where decision_id=v_decision;
  elsif v_proposal.status<>'approved' then
    raise exception 'only an approved identity correction may be reversed'
      using errcode='55000';
  else
    select id into strict v_approval from public.customer_identity_decisions_v111
     where proposal_id=p_proposal and decision_type='approve';
    if not exists (
      select 1 from public.customer_identity_current_attribution_v111 current
       where current.business_id=v_proposal.business_id
         and current.source_client_id=v_proposal.source_client_id
         and current.proposal_id=p_proposal
         and current.effective_client_id=v_proposal.target_client_id
    ) then
      raise exception 'approved attribution is no longer the current correction'
        using errcode='55000';
    end if;
    v_before:=app.v111_attribution_snapshot(
      v_proposal.business_id,v_proposal.source_client_id,
      v_proposal.target_client_id,v_proposal.target_client_id
    );
    v_after:=app.v111_attribution_snapshot(
      v_proposal.business_id,v_proposal.source_client_id,
      v_proposal.target_client_id,v_proposal.source_client_id
    );
    v_decision:=gen_random_uuid();
    insert into public.customer_identity_decisions_v111(
      id,proposal_id,business_id,decision_type,prior_decision_id,
      before_client_id,after_client_id,before_attribution,after_attribution,
      reason,decided_by
    ) values (
      v_decision,p_proposal,v_proposal.business_id,'reverse',v_approval,
      v_proposal.target_client_id,v_proposal.source_client_id,
      v_before,v_after,p_reason,v_actor
    );
    v_event:=gen_random_uuid();
    insert into public.customer_identity_attribution_events_v111(
      id,proposal_id,decision_id,business_id,source_client_id,
      before_client_id,after_client_id,event_type,actor_auth_user_id
    ) values (
      v_event,p_proposal,v_decision,v_proposal.business_id,
      v_proposal.source_client_id,v_proposal.target_client_id,
      v_proposal.source_client_id,'correction_reversed',v_actor
    );
    update public.customer_identity_proposals_v111
       set status='reversed',reversed_at=statement_timestamp(),
           updated_at=statement_timestamp()
     where id=p_proposal;
  end if;
  v_receipt:=jsonb_build_object(
    'status','reversed','proposal_id',p_proposal,'decision_id',v_decision,
    'attribution_event_id',v_event,'source_client_id',v_proposal.source_client_id,
    'effective_client_id',v_proposal.source_client_id
  );
  insert into public.customer_identity_request_ledger_v111(
    actor_auth_user_id,business_id,operation,idempotency_key,request_hash,receipt
  ) values(v_actor,v_proposal.business_id,'reverse',p_idempotency_key,v_hash,v_receipt);
  return v_receipt;
end
$$;

--
-- Name: reverse_loyalty_redemption(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reverse_loyalty_redemption(p_business uuid, p_redemption uuid, p_reason text, p_idempotency_key text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_branch uuid;
  v_staff uuid;
  v_role text;
  v_redemption public.loyalty_redemptions%rowtype;
  v_existing public.loyalty_redemption_reversals%rowtype;
  v_provenance public.loyalty_redemption_provenance%rowtype;
  v_source_credit public.credit_ledger%rowtype;
begin
  if v_actor is null or not app.has_perm(p_business, 'refund_sales') then
    raise exception 'refund_sales permission required' using errcode = '42501';
  end if;
  select s.id,s.role into v_staff,v_role
    from public.staff s
     where s.business_id = p_business
       and s.user_id = v_actor
       and s.active
       and 'refund_sales' = any(app.role_perms(s.role))
     order by case s.role when 'owner' then 0 when 'manager' then 1 else 2 end,
              s.created_at, s.id
     limit 1
     for update;
  if not found then
    raise exception 'active staff authorization required' using errcode = '42501';
  end if;
  select nullif(lr.eligibility_snapshot #>> '{selected,branch_id}', '')::uuid
    into v_branch
    from public.loyalty_redemptions lr
   where lr.id = p_redemption and lr.business_id = p_business;
  if not found then
    raise exception 'loyalty redemption not found in this business' using errcode = '42501';
  end if;
  if not app.can_see_branch(p_business, v_branch) then
    raise exception 'redemption branch scope is not permitted' using errcode = '42501';
  end if;

  -- Owner/admin roles are firm-wide. A future refund-authorized employee must retain the
  -- exact assignment through the final authorization check; locking the assignment after
  -- staff and before the economic rows matches the branch-management lock hierarchy.
  if app.role_class(v_role) not in ('owner','admin') then
    perform 1 from public.staff_branches sb
     where sb.business_id=p_business and sb.staff_id=v_staff and sb.branch_id=v_branch
     for share;
    if not found then
      raise exception 'redemption branch assignment is not permitted' using errcode='42501';
    end if;
  end if;

  -- Staff -> optional assignment -> redemption -> client is the stable order. The client
  -- row is the same balance-serialization point record_credit_tender locks before reading
  -- or appending credit_ledger, so a tender and this compensation cannot both win.
  select lr.* into v_redemption
    from public.loyalty_redemptions lr
   where lr.id = p_redemption and lr.business_id = p_business
   for update;
  v_branch:=nullif(v_redemption.eligibility_snapshot #>> '{selected,branch_id}', '')::uuid;
  if not found
     or not app.has_perm(p_business, 'refund_sales')
     or not app.can_see_branch(p_business, v_branch) then
    raise exception 'redemption reversal authorization changed while locking'
      using errcode = '42501';
  end if;
  perform 1 from public.clients c
   where c.id=v_redemption.client_id and c.business_id=p_business
   for update;
  if not found then
    raise exception 'redemption client does not belong to this business' using errcode='42501';
  end if;

  -- A completed compensation necessarily contains its own negative credit row. Hand an
  -- already-reversed request back to the immutable v34 replay/conflict decision before
  -- applying the pre-compensation spent-credit test.
  select * into v_existing from public.loyalty_redemption_reversals rr
   where rr.business_id=p_business and rr.redemption_id=p_redemption;
  if found then
    return public.reverse_loyalty_redemption_v34_base(
      p_business, p_redemption, p_reason, p_idempotency_key
    );
  end if;

  select * into v_provenance from public.loyalty_redemption_provenance p
   where p.business_id=p_business and p.redemption_id=p_redemption
     and p.client_id=v_redemption.client_id;
  if not found or v_provenance.config_version_id is distinct from v_redemption.config_version_id then
    raise exception 'redemption exact provenance is missing or inconsistent';
  end if;
  if v_redemption.credit_cents>0 then
    if v_provenance.credit_ledger_id is null then
      raise exception 'original loyalty credit provenance is missing';
    end if;
    select * into v_source_credit from public.credit_ledger cl
     where cl.id=v_provenance.credit_ledger_id
       and cl.business_id=p_business
       and cl.client_id=v_redemption.client_id
       and cl.entry_type='loyalty_earn'
       and cl.amount_cents=v_redemption.credit_cents
       and cl.config_version_id=v_redemption.config_version_id;
    if not found then
      raise exception 'original loyalty credit provenance does not match the redemption';
    end if;
    if exists (
      select 1 from public.credit_ledger spend
       where spend.business_id=p_business and spend.client_id=v_redemption.client_id
         and spend.amount_cents<0 and spend.created_at>=v_source_credit.created_at
    ) then
      raise exception 'reward credit may have been spent; exact source credit is no longer reversible';
    end if;
  end if;
  if not app.has_perm(p_business,'refund_sales')
     or not app.can_see_branch(p_business,v_branch) then
    raise exception 'redemption reversal authorization changed after balance lock'
      using errcode='42501';
  end if;
  return public.reverse_loyalty_redemption_v34_base(
    p_business, p_redemption, p_reason, p_idempotency_key
  );
end $$;

--
-- Name: reverse_loyalty_redemption_v34_base(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reverse_loyalty_redemption_v34_base(p_business uuid, p_redemption uuid, p_reason text, p_idempotency_key text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_redemption public.loyalty_redemptions%rowtype; v_provenance public.loyalty_redemption_provenance%rowtype;
  v_existing public.loyalty_redemption_reversals%rowtype; v_actor uuid:=auth.uid(); v_staff uuid;
  v_payload jsonb; v_request_hash text; v_points_id uuid:=gen_random_uuid(); v_credit_id uuid;
  v_source_credit public.credit_ledger%rowtype; v_result jsonb; v_drain record;
  v_restore_programme uuid; v_restore_programmes integer;
begin
  if p_idempotency_key is null or length(btrim(p_idempotency_key))<8 then raise exception 'idempotency key must contain at least 8 characters' using errcode='22023'; end if;
  if p_reason is null or length(btrim(p_reason))<10 then raise exception 'reason must contain at least 10 characters'; end if;
  if not app.has_perm(p_business,'refund_sales') then raise exception 'refund_sales permission required' using errcode='42501'; end if;
  select s.id into v_staff from public.staff s where s.business_id=p_business and s.user_id=v_actor and s.active and 'refund_sales'=any(app.role_perms(s.role)) limit 1 for update;
  if not found then raise exception 'active staff authorization required' using errcode='42501'; end if;
  select * into v_redemption from public.loyalty_redemptions where id=p_redemption and business_id=p_business for update;
  if not found then raise exception 'loyalty redemption not found in this business'; end if;
  v_payload:=jsonb_build_object('business_id',p_business,'redemption_id',p_redemption,'reason',btrim(p_reason),'actor',v_actor);
  v_request_hash:=md5(v_payload::text);
  select * into v_existing from public.loyalty_redemption_reversals where redemption_id=p_redemption;
  if found then
    if v_existing.idempotency_key is distinct from btrim(p_idempotency_key) or v_existing.request_hash is distinct from v_request_hash then raise exception 'redemption already reversed by another request' using errcode='23505'; end if;
    return (v_existing.result||jsonb_build_object('replayed',true))::json;
  end if;
  select * into v_provenance from public.loyalty_redemption_provenance where redemption_id=p_redemption and business_id=p_business for update;
  if not found then raise exception 'legacy or incomplete redemption has missing provenance evidence'; end if;
  if v_provenance.config_version_id is distinct from v_redemption.config_version_id then
    raise exception 'redemption configuration provenance is inconsistent';
  end if;
  perform 1 from public.points_ledger pl
   where pl.id=v_provenance.points_ledger_id and pl.business_id=p_business
     and pl.client_id=v_redemption.client_id and pl.points=-v_redemption.points_spent
     and pl.config_version_id=v_redemption.config_version_id for share;
  if not found then raise exception 'original points ledger provenance is incomplete'; end if;
  if not exists(select 1 from public.loyalty_redemption_batch_drains where provenance_id=v_provenance.id) then raise exception 'incomplete batch drain provenance evidence'; end if;
  if (select coalesce(sum(drained_points),0) from public.loyalty_redemption_batch_drains where provenance_id=v_provenance.id) <> v_redemption.points_spent then raise exception 'batch drain provenance is incomplete'; end if;
  for v_drain in select d.points_batch_id,d.drained_points from public.loyalty_redemption_batch_drains d
    where d.provenance_id=v_provenance.id and d.business_id=p_business
      and d.client_id=v_redemption.client_id order by d.id for update of d loop
    update public.points_batches set remaining=remaining+v_drain.drained_points
     where id=v_drain.points_batch_id and business_id=p_business and client_id=v_redemption.client_id
       and remaining+v_drain.drained_points<=earned;
    if not found then raise exception 'batch restoration would exceed immutable earned points'; end if;
  end loop;
  -- The compensation is a positive points adjustment, exactly equal to the proven drains.
  perform set_config('app.redemption_reversal_config_version_id',v_redemption.config_version_id::text,true);
  perform set_config('app.points_ledger_insert_id',v_points_id::text,true); perform set_config('app.points_ledger_write_scope','redemption_reversal',true);
  select count(distinct pb.programme_id) into v_restore_programmes
    from public.points_batches pb
   where pb.id in (select d.points_batch_id from public.loyalty_redemption_batch_drains d
                    where d.provenance_id=v_provenance.id);
  if v_restore_programmes<>1 then raise exception 'restored batches span more than one programme or none' using errcode='XX001'; end if;
  select distinct pb.programme_id into strict v_restore_programme
    from public.points_batches pb
   where pb.id in (select d.points_batch_id from public.loyalty_redemption_batch_drains d
                    where d.provenance_id=v_provenance.id);
  insert into public.points_ledger(id,business_id,client_id,entry_type,points,reference,actor,config_version_id,programme_id)
  values(v_points_id,p_business,v_redemption.client_id,'adjust',v_redemption.points_spent,'redemption reversal: '||p_redemption,v_actor,v_redemption.config_version_id,v_restore_programme);
  perform set_config('app.points_ledger_insert_id','',true); perform set_config('app.points_ledger_write_scope','',true);
  if v_provenance.credit_ledger_id is not null then
    select * into v_source_credit from public.credit_ledger cl
     where cl.id=v_provenance.credit_ledger_id and cl.business_id=p_business
       and cl.client_id=v_redemption.client_id and cl.entry_type='loyalty_earn'
       and cl.amount_cents=v_redemption.credit_cents
       and cl.config_version_id=v_redemption.config_version_id for share;
    if not found then raise exception 'original credit ledger provenance is incomplete'; end if;
    if exists (
      select 1 from public.credit_ledger spend
       where spend.business_id=p_business and spend.client_id=v_redemption.client_id
         and spend.amount_cents<0 and spend.created_at>=v_source_credit.created_at
    ) then
      raise exception 'reward credit may have been spent; exact source credit is no longer reversible';
    end if;
    v_credit_id:=gen_random_uuid();
    perform set_config('app.credit_ledger_insert_id',v_credit_id::text,true); perform set_config('app.credit_ledger_write_scope','redemption_reversal',true);
    insert into public.credit_ledger(id,business_id,client_id,entry_type,amount_cents,reference,actor,idempotency_key,config_version_id)
    values(v_credit_id,p_business,v_redemption.client_id,'manual_adjust',-v_redemption.credit_cents,
      'loyalty redemption reversal of credit entry '||v_source_credit.id,v_actor,
      'v34:'||btrim(p_idempotency_key),v_redemption.config_version_id);
    perform set_config('app.credit_ledger_insert_id','',true); perform set_config('app.credit_ledger_write_scope','',true);
  end if;
  if (select coalesce(sum(points),0) from public.points_ledger where business_id=p_business and client_id=v_redemption.client_id)
     <> (select coalesce(sum(remaining),0) from public.points_batches where business_id=p_business and client_id=v_redemption.client_id) then
    raise exception 'points ledger and points batch remaining invariant diverged';
  end if;
  if (select coalesce(sum(points),0) from public.points_ledger where business_id=p_business and client_id=v_redemption.client_id and programme_id=v_restore_programme)
     <> (select coalesce(sum(remaining),0) from public.points_batches where business_id=p_business and client_id=v_redemption.client_id and programme_id=v_restore_programme) then
    raise exception 'per-programme points ledger and batch remaining invariant diverged';
  end if;
  v_result:=jsonb_build_object('redemption_id',p_redemption,'restored_points',v_redemption.points_spent,'reversed_credit_cents',case when v_credit_id is null then 0 else v_redemption.credit_cents end,'replayed',false);
  insert into public.loyalty_redemption_reversals
    (business_id,redemption_id,provenance_id,client_id,actor,idempotency_key,request_payload,
     request_hash,restored_points_ledger_id,reversed_credit_ledger_id,result)
  values(p_business,p_redemption,v_provenance.id,v_redemption.client_id,v_actor,
    btrim(p_idempotency_key),v_payload,v_request_hash,v_points_id,v_credit_id,v_result);
  perform set_config('app.redemption_reversal_config_version_id','',true);
  return v_result::json;
end $$;

--
-- Name: reverse_program_entitlement(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reverse_program_entitlement(p_entitlement uuid, p_reason text, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare e public.program_entitlements%rowtype; v_hash text; v_prior uuid; v_prior_hash text;
begin
  if p_idempotency_key is null then raise exception 'idempotency key required' using errcode = '22023'; end if;
  if char_length(coalesce(btrim(p_reason), '')) < 3 then raise exception 'a reason is required' using errcode = '22023'; end if;
  select * into e from public.program_entitlements where id = p_entitlement for update;
  if not found or not app.is_salon_owner(e.business_id) then raise exception 'owner only' using errcode = '42501'; end if;
  v_hash := app.ps1b_sha256('reverse:' || p_entitlement::text || ':' || p_reason);
  select entitlement_id, request_hash into v_prior, v_prior_hash
    from public.program_entitlement_operations
   where business_id = e.business_id and operation_type = 'reverse' and idempotency_key = p_idempotency_key;
  if v_prior is not null then
    if v_prior <> e.id or v_prior_hash <> v_hash then
      raise exception 'idempotency key was already used for a different request' using errcode = '22023';
    end if;
    return jsonb_build_object('entitlement_id', e.id, 'status', e.status, 'replayed', true);
  end if;
  if e.status not in ('available','redeemed') then raise exception 'entitlement cannot be reversed' using errcode = '23514'; end if;
  update public.program_entitlements set status = 'reversed', reversed_at = now(), updated_at = now() where id = e.id;
  insert into public.program_entitlement_operations(business_id, client_id, operation_type, idempotency_key, request_hash, entitlement_id)
  values(e.business_id, e.client_id, 'reverse', p_idempotency_key, v_hash, e.id);
  insert into public.audit_log(business_id, actor, action, entity, entity_id, detail)
  values(e.business_id, auth.uid(), 'REVERSE_ENTITLEMENT', 'program_entitlements', e.id, jsonb_build_object('reason', p_reason));
  return jsonb_build_object('entitlement_id', e.id, 'status', 'reversed', 'replayed', false);
end $$;

--
-- Name: reverse_sale(uuid, uuid, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reverse_sale(p_business uuid, p_sale uuid, p_reason text, p_idempotency_key text, p_reference text DEFAULT NULL::text, p_restock_policy text DEFAULT 'none'::text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_res json;
  v_reversal_sale uuid;
  d record;
  v_key text;
begin
  -- Delegate the entire existing reversal (auth, package/provenance, money core).
  v_res := public.reverse_sale_v40_base(p_business, p_sale, p_reason, p_idempotency_key, p_reference, p_restock_policy);
  v_reversal_sale := nullif(v_res->>'reversal_sale_id', '')::uuid;
  if v_reversal_sale is null then
    return v_res;   -- nothing reversed (should not happen on success) - pass through.
  end if;

  -- Compensate any checkout discounts recorded against the ORIGINAL sale. Idempotent:
  -- the compensating fulfilment key and the per-reservation release uniqueness make a
  -- replayed reversal a strict no-op.
  for d in
    select cdl.rule_id, cdl.effect_index, cdl.amount_cents, cdl.benefit_fulfilment_id, cdl.config_version_id
      from public.checkout_discount_lines cdl
     where cdl.business_id = p_business and cdl.sale_id = p_sale
     order by cdl.rule_id, cdl.effect_index
  loop
    v_key := 'discount_reversal:' || v_reversal_sale::text || ':' || d.rule_id::text || ':' || d.effect_index::text;
    insert into public.benefit_fulfilments(
      business_id, canonical_benefit_key, source_engine, fulfilment_kind, client_id, detail_ref,
      face_value_cents, estimated_cost_cents, cost_basis, cost_confidence, config_version_id,
      reverses_fulfilment_id, occurred_at)
    select p_business, v_key, 'checkout', 'checkout_discount_reversal',
      (select client_id from public.benefit_fulfilments where id = d.benefit_fulfilment_id and business_id = p_business),
      v_reversal_sale, -d.amount_cents, -d.amount_cents, 'discount_face', 'high', d.config_version_id,
      d.benefit_fulfilment_id, now()
    on conflict (business_id, canonical_benefit_key) do nothing;

    -- Release the budget commitment (committed_cents -= amount) under a row lock,
    -- exactly once per reservation. The CTE inserts the release only when it does
    -- not already exist and RETURNS only the newly-inserted row, so the counter
    -- decrement happens once. A replayed reversal inserts nothing and decrements
    -- nothing. Invariant: committed = Σreservations − Σreleases >= 0.
    perform 1 from public.budget_periods bp
     where bp.business_id = p_business
       and bp.id in (select budget_period_id from public.budget_reservations
                      where business_id = p_business and discount_fulfilment_id = d.benefit_fulfilment_id)
     for update;
    with rel as (
      insert into public.budget_commitment_releases(
        business_id, budget_period_id, reservation_id, amount_cents, reversal_sale_id)
      select p_business, br.budget_period_id, br.id, br.amount_cents, v_reversal_sale
        from public.budget_reservations br
       where br.business_id = p_business and br.discount_fulfilment_id = d.benefit_fulfilment_id
      on conflict (reservation_id) do nothing
      returning budget_period_id, amount_cents)
    update public.budget_periods bp
       set committed_cents = committed_cents - rel.amount_cents, updated_at = now()
      from rel where bp.id = rel.budget_period_id;
  end loop;

  return v_res;
end $$;

--
-- Name: FUNCTION reverse_sale(p_business uuid, p_sale uuid, p_reason text, p_idempotency_key text, p_reference text, p_restock_policy text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.reverse_sale(p_business uuid, p_sale uuid, p_reason text, p_idempotency_key text, p_reference text, p_restock_policy text) IS 'Sale reversal (door B). CONCURRENCY CONTRACT (v69, LOW-1): racing door A (public.sv_reverse_spend) may resolve through Postgres deadlock detection - the loser receives SQLSTATE 40P01. That is an ACCEPTED, RETRIABLE outcome, not a defect: it is fail-closed, money invariants hold, exactly one restitution occurs, and a retry succeeds. Callers must retry 40P01 rather than surface it.';

--
-- Name: reverse_sale_fast_v84(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reverse_sale_fast_v84(p_business uuid, p_sale uuid, p_note text, p_idempotency_key text) RETURNS json
    LANGUAGE sql
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
  select public.reverse_sale(
    p_business,
    p_sale,
    case
      when nullif(btrim(p_note),'') is null then 'Staff-confirmed sale reversal'
      else 'Staff note: ' || btrim(p_note)
    end,
    p_idempotency_key,
    'Peekaa quick reversal',
    'none'
  )
$$;

--
-- Name: FUNCTION reverse_sale_fast_v84(p_business uuid, p_sale uuid, p_note text, p_idempotency_key text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.reverse_sale_fast_v84(p_business uuid, p_sale uuid, p_note text, p_idempotency_key text) IS 'Optional-note adapter over the existing exact reversal engine; authorization and compensation remain in reverse_sale.';

--
-- Name: reverse_sale_v20_base(uuid, uuid, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reverse_sale_v20_base(p_business uuid, p_sale uuid, p_reason text, p_idempotency_key text, p_reference text DEFAULT NULL::text, p_restock_policy text DEFAULT 'none'::text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  o public.sales%rowtype;
  v_reversal public.sales%rowtype;
  v_existing public.sale_reversal_audits%rowtype;
  v_operation public.financial_operations%rowtype;
  v_operation_id uuid := gen_random_uuid();
  v_request_payload jsonb;
  v_request_hash text;
  v_result jsonb;
  v_reversal_id uuid := gen_random_uuid();
  v_actor uuid := auth.uid();
  v_actor_staff uuid;
  v_paid_cents integer;
  v_validated_refund_cents integer;
  v_credit_payment_cents integer := 0;
  v_refund_payment_cents integer := 0;
  v_credit_restored_cents integer := 0;
  v_points_earned_observed integer := 0;
  v_referral_reversed boolean := false;
  v_payment_ids uuid[] := '{}'::uuid[];
  v_effects jsonb;
  pay record;
  v_payment public.payments%rowtype;
  v_payment_id uuid;
  v_payment_key text;
  v_credit public.credit_ledger%rowtype;
  v_credit_id uuid;
  v_credit_key text;
  v_referral public.referrals%rowtype;
begin
  if p_idempotency_key is null or length(btrim(p_idempotency_key)) < 8 then
    raise exception 'p_idempotency_key is required and must be at least 8 characters';
  end if;
  if p_reason is null or length(btrim(p_reason)) < 10 then
    raise exception 'a reversal reason of at least 10 characters is required';
  end if;
  if coalesce(p_restock_policy, 'none') <> 'none' then
    raise exception 'automatic restock policy "%" is unsupported in v20; use none and post manual stock adjustment evidence',
      p_restock_policy;
  end if;

  -- Coarse authorization precedes every attacker-selected advisory or row lock.
  if not app.has_perm(p_business, 'refund_sales') then
    raise exception 'you do not have permission to reverse/refund sales in this business (refund_sales)'
      using errcode = '42501';
  end if;

  select * into o
    from public.sales
   where id = p_sale
     and business_id = p_business;
  if not found then
    raise exception 'sale not found in this business';
  end if;
  if not app.can_see_branch(p_business, o.branch_id) then
    raise exception 'you are not permitted to reverse/refund this branch scope'
      using errcode = '42501';
  end if;

  select st.id into v_actor_staff
    from public.staff st
   where st.business_id = p_business
     and st.user_id = v_actor
     and st.active
     and 'refund_sales' = any (app.role_perms(st.role))
   order by case st.role when 'owner' then 0 when 'manager' then 1 else 2 end, st.created_at
   limit 1
   for update;
  if not found then
    raise exception 'active staff authorization is required to reverse a sale'
      using errcode = '42501';
  end if;

  select * into o
    from public.sales
   where id = p_sale
     and business_id = p_business
   for update;
  if not found then
    raise exception 'sale not found in this business';
  end if;
  if o.appointment_id is not null then
    perform 1
      from public.appointments a
     where a.id = o.appointment_id
       and a.business_id = o.business_id
     for update;
  end if;

  if not app.has_perm(o.business_id, 'refund_sales')
     or not app.can_see_branch(o.business_id, o.branch_id) then
    raise exception 'sale reversal authorization changed while the operation was being locked'
      using errcode = '42501';
  end if;

  v_request_payload := jsonb_build_object(
    'business_id', p_business,
    'sale_id', o.id,
    'branch_id', o.branch_id,
    'actor', v_actor,
    'reason', btrim(p_reason),
    'reference', nullif(btrim(p_reference), ''),
    'restock_policy', 'none'
  );
  v_request_hash := md5(v_request_payload::text);

  select * into v_operation
    from public.financial_operations fo
   where fo.business_id = p_business
     and fo.operation_type = 'sale_reversal'
     and fo.idempotency_key = btrim(p_idempotency_key);
  if found then
    if (v_operation.sale_id, v_operation.branch_id, v_operation.actor,
        v_operation.request_payload, v_operation.request_hash)
       is distinct from
       (o.id, o.branch_id, v_actor, v_request_payload, v_request_hash) then
      raise exception 'sale reversal idempotency key conflicts with a different immutable request'
        using errcode = '23505';
    end if;
    if v_operation.status <> 'completed' or v_operation.result is null then
      raise exception 'sale reversal operation is reserved but incomplete'
        using errcode = '55000';
    end if;
    select * into v_existing
      from public.sale_reversal_audits a
     where a.operation_id = v_operation.id
       and a.business_id = p_business
       and a.original_sale_id = o.id
       and a.actor = v_actor
       and a.idempotency_key = btrim(p_idempotency_key);
    if not found
       or v_existing.reversal_sale_id is distinct from
          (v_operation.result->>'reversal_sale_id')::uuid then
      raise exception 'completed reversal operation is missing exact audit evidence'
        using errcode = 'XX001';
    end if;
    return (v_operation.result || jsonb_build_object('replayed', true))::json;
  end if;

  if o.reversal_of is not null then
    raise exception 'cannot reverse a reversal sale %', o.id;
  end if;
  if o.amount_cents <= 0 then
    raise exception 'sale % has no positive economic amount to reverse', o.id;
  end if;
  if o.kind not in ('service', 'retail', 'quick_sale') then
    raise exception 'v20 supports only service, retail and quick_sale reversals; kind % has no proven launch correction path',
      o.kind;
  end if;
  if exists (
    select 1 from public.sales r
     where r.business_id = o.business_id
       and r.reversal_of = o.id
  ) then
    raise exception 'sale % is already fully reversed; replay with the original idempotency key to retrieve it',
      o.id;
  end if;

  select coalesce(sum(p.amount_cents), 0)::integer
    into v_paid_cents
    from public.payments p
   where p.business_id = o.business_id
     and (
       p.sale_id = o.id
       or (
         p.sale_id is null
         and o.appointment_id is not null
         and p.appointment_id = o.appointment_id
       )
     );

  if v_paid_cents > o.amount_cents then
    raise exception 'sale % is overpaid by % cents; overpayment returns are not part of v20 sale reversal',
      o.id, v_paid_cents - o.amount_cents;
  end if;
  if v_paid_cents < 0 then
    raise exception 'sale % has negative net payments %; standalone payment correction is outside v20 sale reversal',
      o.id, v_paid_cents;
  end if;

  if exists (
    select 1
      from public.payments p
     where p.business_id = o.business_id
       and (
         p.sale_id = o.id
         or (p.sale_id is null and o.appointment_id is not null
             and p.appointment_id = o.appointment_id)
       )
     group by p.method
    having sum(p.amount_cents) < 0
  ) then
    raise exception 'sale % has a negative per-method payment net; undefined payment corrections cannot be reversed', o.id;
  end if;

  if exists (
    select 1
      from public.payments p
     where p.business_id = o.business_id
       and (
         p.sale_id = o.id
         or (p.sale_id is null and o.appointment_id is not null
             and p.appointment_id = o.appointment_id)
       )
     group by p.method
    having sum(p.amount_cents) > 0
       and p.method not in ('cash', 'credit')
  ) then
    raise exception 'launch refunds support only cash and proven store credit; provider-settled methods are disabled'
      using errcode = 'feature_not_supported';
  end if;

  -- Every positive credit payment must be the exact child of one credit_tenders proof row,
  -- including the original negative ledger spend. Aggregates alone are insufficient proof.
  if exists (
    select 1
      from public.payments p
     where p.business_id = o.business_id
       and p.method = 'credit'
       and (
         p.sale_id = o.id
         or (p.sale_id is null and o.appointment_id is not null
             and p.appointment_id = o.appointment_id)
       )
       and not (
         p.kind = 'payment'
         and p.amount_cents > 0
         and p.sale_id = o.id
         and p.appointment_id is null
         and p.client_id is not distinct from o.client_id
         and p.branch_id is not distinct from o.branch_id
         and exists (
           select 1
             from public.credit_tenders ct
             join public.credit_ledger cl
               on cl.id = ct.credit_ledger_id
              and cl.business_id = ct.business_id
            where ct.business_id = o.business_id
              and ct.sale_id = o.id
              and ct.payment_id = p.id
              and ct.client_id is not distinct from o.client_id
              and ct.branch_id is not distinct from o.branch_id
              and ct.amount_cents = p.amount_cents
              and cl.client_id = ct.client_id
              and cl.entry_type = 'spend'
              and cl.amount_cents = -ct.amount_cents
              and cl.sale_id = ct.sale_id
              and cl.payment_id = ct.payment_id
              and cl.actor is not distinct from ct.actor
         )
       )
  ) then
    raise exception 'store-credit refund requires exact credit_tenders and negative credit_ledger proof'
      using errcode = 'check_violation';
  end if;

  select coalesce(sum(p.amount_cents), 0)::integer
    into v_credit_payment_cents
    from public.payments p
   where p.business_id = o.business_id
     and p.method = 'credit'
     and (
       p.sale_id = o.id
       or (p.sale_id is null and o.appointment_id is not null
           and p.appointment_id = o.appointment_id)
     );

  select coalesce(sum(m.net_cents), 0)::integer
    into v_validated_refund_cents
    from (
      select p.method, sum(p.amount_cents)::integer as net_cents
        from public.payments p
       where p.business_id = o.business_id
         and (
           p.sale_id = o.id
           or (p.sale_id is null and o.appointment_id is not null
               and p.appointment_id = o.appointment_id)
         )
       group by p.method
      having sum(p.amount_cents) > 0
         and p.method in ('cash', 'credit')
    ) m;
  if v_validated_refund_cents is distinct from v_paid_cents then
    raise exception 'validated refundable methods % do not equal sale payment net %',
      v_validated_refund_cents, v_paid_cents
      using errcode = 'check_violation';
  end if;

  if exists (
    select 1
      from public.legacy_referral_sale_candidates c
     where c.business_id = o.business_id
       and c.sale_id = o.id
       and not exists (
         select 1 from public.legacy_referral_resolution_events e
          where e.referral_id = c.referral_id
            and e.business_id = c.business_id
       )
  ) then
    raise exception 'sale % is an ambiguous pre-v20 referral qualification candidate; resolve its captured provenance before reversal',
      o.id
      using errcode = 'feature_not_supported';
  end if;

  select coalesce(sum(pl.points), 0)::integer
    into v_points_earned_observed
    from public.points_ledger pl
   where pl.business_id = o.business_id
     and pl.sale_id = o.id
     and pl.entry_type = 'earn';

  -- Parent reservation is the idempotency decision. No sale, payment, loyalty or referral
  -- side effect occurs before this row is accepted.
  perform set_config('app.financial_operation_insert_id', v_operation_id::text, true);
  insert into public.financial_operations (
    id, business_id, branch_id, sale_id, operation_type, actor,
    idempotency_key, request_payload, request_hash
  )
  values (
    v_operation_id, o.business_id, o.branch_id, o.id, 'sale_reversal', v_actor,
    btrim(p_idempotency_key), v_request_payload, v_request_hash
  )
  on conflict (business_id, operation_type, idempotency_key) do nothing
  returning * into v_operation;
  perform set_config('app.financial_operation_insert_id', '', true);

  if v_operation.id is null then
    select * into v_operation
      from public.financial_operations fo
     where fo.business_id = o.business_id
       and fo.operation_type = 'sale_reversal'
       and fo.idempotency_key = btrim(p_idempotency_key);
    if not found
       or (v_operation.sale_id, v_operation.branch_id, v_operation.actor,
           v_operation.request_payload, v_operation.request_hash)
          is distinct from
          (o.id, o.branch_id, v_actor, v_request_payload, v_request_hash) then
      raise exception 'sale reversal idempotency reservation conflicts with a different immutable request'
        using errcode = '23505';
    end if;
    if v_operation.status = 'completed' and v_operation.result is not null then
      return (v_operation.result || jsonb_build_object('replayed', true))::json;
    end if;
    raise exception 'sale reversal operation is already reserved but incomplete'
      using errcode = '55000';
  end if;

  perform set_config('app.sale_reversal_insert_id', v_reversal_id::text, true);
  perform set_config('app.sale_reversal_original_id', o.id::text, true);

  insert into public.sales (
    id, business_id, client_id, kind, amount_cents, occurred_at, note,
    appointment_id, product_id, qty, branch_id, staff_id,
    reversal_of, reversal_reason, reversal_actor, reversal_idempotency_key
  )
  values (
    v_reversal_id, o.business_id, o.client_id, o.kind, -o.amount_cents, now(),
    coalesce(p_reference, 'sale reversal') || ': ' || left(btrim(p_reason), 200),
    null, null, null, o.branch_id, o.staff_id,
    o.id, btrim(p_reason), v_actor, btrim(p_idempotency_key)
  )
  returning * into v_reversal;

  perform set_config('app.sale_reversal_insert_id', '', true);
  perform set_config('app.sale_reversal_original_id', '', true);

  perform app.sv_reverse_settlement_for_sale(o.business_id, o.id, v_reversal.id, btrim(p_reason));

  -- Launch-safe points policy: observe, but do not claw back. Earned points may already have
  -- been redeemed into credit and the current schema has no immutable redemption-to-earn
  -- provenance or tenant policy that can prove the correct compensating chain.

  select * into v_referral
    from public.referrals rf
   where rf.business_id = o.business_id
     and rf.qualified_sale_id = o.id
     and rf.status = 'rewarded'
   for update;

  if found and coalesce(v_referral.reward_cents, 0) > 0 then
    v_credit_id := gen_random_uuid();
    v_credit_key := 'v20:' || v_operation.id || ':referral:' || v_referral.id;
    perform set_config('app.credit_ledger_insert_id', v_credit_id::text, true);
    perform set_config('app.credit_ledger_write_scope', 'sale_reversal', true);
    insert into public.credit_ledger (
      id, business_id, client_id, entry_type, amount_cents, reference,
      sale_id, actor, idempotency_key
    )
    values (
      v_credit_id,
      o.business_id,
      v_referral.referrer_client_id,
      'manual_adjust',
      -v_referral.reward_cents,
      'sale reversal: referral reward clawback for sale ' || o.id,
      v_reversal.id,
      v_actor,
      v_credit_key
    )
    on conflict (business_id, idempotency_key) where idempotency_key is not null
      do nothing
    returning * into v_credit;
    perform set_config('app.credit_ledger_insert_id', '', true);
    perform set_config('app.credit_ledger_write_scope', '', true);

    if v_credit.id is null then
      select * into v_credit
        from public.credit_ledger cl
       where cl.business_id = o.business_id
         and cl.idempotency_key = v_credit_key;
      if not found
         or (v_credit.client_id, v_credit.entry_type, v_credit.amount_cents,
             v_credit.sale_id, v_credit.payment_id, v_credit.actor)
            is distinct from
            (v_referral.referrer_client_id, 'manual_adjust'::text,
             -v_referral.reward_cents, v_reversal.id, null::uuid, v_actor) then
        raise exception 'referral reversal ledger key conflicts with a different immutable child'
          using errcode = '23505';
      end if;
    end if;

    update public.referrals
       set status = 'pending',
           qualified_at = null,
           qualified_sale_id = null,
           reward_cents = 0
     where id = v_referral.id;
    v_referral_reversed := true;
  end if;

  for pay in
    select p.method,
           sum(p.amount_cents)::integer as net_cents,
           array_agg(p.id order by p.created_at, p.id) as source_payment_ids
      from public.payments p
     where p.business_id = o.business_id
       and (
         p.sale_id = o.id
         or (
           p.sale_id is null
           and o.appointment_id is not null
           and p.appointment_id = o.appointment_id
         )
       )
       and p.method in ('cash', 'credit')
     group by p.method
    having sum(p.amount_cents) > 0
  loop
    v_payment_id := gen_random_uuid();
    v_payment_key := 'v20:' || v_operation.id || ':refund:' || pay.method;
    v_payment := null;
    perform set_config('app.payment_insert_id', v_payment_id::text, true);
    perform set_config('app.payment_write_scope', 'sale_reversal', true);

    insert into public.payments (
      id, business_id, branch_id, sale_id, appointment_id, client_id, staff_id,
      method, kind, amount_cents, reference, note, idempotency_key, created_by
    )
    values (
      v_payment_id,
      o.business_id,
      o.branch_id,
      o.id,
      null,
      o.client_id,
      coalesce(v_actor_staff, o.staff_id),
      pay.method,
      'refund',
      -pay.net_cents,
      coalesce(p_reference, 'sale reversal ' || o.id),
      'auto refund for full sale reversal ' || v_reversal.id,
      v_payment_key,
      v_actor
    )
    on conflict (business_id, idempotency_key) where idempotency_key is not null
      do nothing
    returning * into v_payment;

    perform set_config('app.payment_insert_id', '', true);
    perform set_config('app.payment_write_scope', '', true);

    if v_payment.id is null then
      select * into v_payment
        from public.payments
       where business_id = o.business_id
         and idempotency_key = v_payment_key;
      if not found
         or (v_payment.branch_id, v_payment.sale_id, v_payment.appointment_id,
             v_payment.client_id, v_payment.staff_id, v_payment.method, v_payment.kind,
             v_payment.amount_cents, v_payment.created_by)
            is distinct from
            (o.branch_id, o.id, null::uuid, o.client_id,
             coalesce(v_actor_staff, o.staff_id), pay.method, 'refund'::text,
             -pay.net_cents, v_actor) then
        raise exception 'refund payment key conflicts with a different immutable child %',
          v_payment_key
          using errcode = '23505';
      end if;
    end if;

    v_payment_ids := array_append(v_payment_ids, v_payment.id);
    v_refund_payment_cents := v_refund_payment_cents + pay.net_cents;

    if pay.method = 'credit' then
      v_credit_id := gen_random_uuid();
      v_credit_key := 'v20:' || v_operation.id || ':credit-restore';
      v_credit := null;
      perform set_config('app.credit_ledger_insert_id', v_credit_id::text, true);
      perform set_config('app.credit_ledger_write_scope', 'sale_reversal', true);
      insert into public.credit_ledger (
        id, business_id, client_id, entry_type, amount_cents, reference,
        sale_id, payment_id, actor, idempotency_key
      )
      values (
        v_credit_id,
        o.business_id,
        o.client_id,
        'manual_adjust',
        pay.net_cents,
        'sale reversal: restore store credit tender for sale ' || o.id,
        v_reversal.id,
        v_payment.id,
        v_actor,
        v_credit_key
      )
      on conflict (business_id, idempotency_key) where idempotency_key is not null
        do nothing
      returning * into v_credit;
      perform set_config('app.credit_ledger_insert_id', '', true);
      perform set_config('app.credit_ledger_write_scope', '', true);

      if v_credit.id is null then
        select * into v_credit
          from public.credit_ledger cl
         where cl.business_id = o.business_id
           and cl.idempotency_key = v_credit_key;
        if not found
           or (v_credit.client_id, v_credit.entry_type, v_credit.amount_cents,
               v_credit.sale_id, v_credit.payment_id, v_credit.actor)
              is distinct from
              (o.client_id, 'manual_adjust'::text, pay.net_cents,
               v_reversal.id, v_payment.id, v_actor) then
          raise exception 'credit restoration key conflicts with a different immutable child'
            using errcode = '23505';
        end if;
      end if;
      v_credit_restored_cents := v_credit_restored_cents + pay.net_cents;
    end if;

    insert into public.sale_reversal_payment_links (
      operation_id, business_id, branch_id, original_sale_id, reversal_sale_id, refund_payment_id,
      method, amount_cents, source_payment_ids
    )
    values (
      v_operation.id,
      o.business_id,
      o.branch_id,
      o.id,
      v_reversal.id,
      v_payment.id,
      pay.method,
      pay.net_cents,
      pay.source_payment_ids
    );
  end loop;

  if v_refund_payment_cents is distinct from v_validated_refund_cents then
    raise exception 'generated refunds % do not equal validated refundable total %',
      v_refund_payment_cents, v_validated_refund_cents
      using errcode = 'check_violation';
  end if;
  if v_credit_restored_cents is distinct from v_credit_payment_cents then
    raise exception 'restored credit % does not equal proven credit tender total %',
      v_credit_restored_cents, v_credit_payment_cents
      using errcode = 'check_violation';
  end if;
  if (select coalesce(sum(p.amount_cents), 0)::integer
        from public.payments p
       where p.id = any(v_payment_ids)) is distinct from -v_validated_refund_cents then
    raise exception 'persisted refund payments do not exactly equal the validated total'
      using errcode = 'check_violation';
  end if;
  if (select coalesce(sum(l.amount_cents), 0)::integer
        from public.sale_reversal_payment_links l
       where l.operation_id = v_operation.id) is distinct from v_validated_refund_cents then
    raise exception 'refund evidence links do not exactly equal the validated total'
      using errcode = 'check_violation';
  end if;

  v_effects := jsonb_build_object(
    'supported_scope', 'full reversal only for service/retail/quick_sale',
    'unsupported_sale_kinds', jsonb_build_array('gift_card', 'package', 'membership'),
    'refund_methods', jsonb_build_array('cash', 'credit'),
    'provider_refunds', 'disabled_until_provider_settlement_integration',
    'inventory_restock_policy', 'none_manual_stock_adjustment_required',
    'payment_refund_ids', v_payment_ids,
    'points_policy', 'clawback_disabled_until_provenance_and_tenant_policy_exist',
    'points_earned_observed', v_points_earned_observed,
    'points_clawed_back', 0,
    'points_batch_remaining_decremented', 0,
    'referral_reversed', v_referral_reversed,
    'credit_restored_cents', v_credit_restored_cents,
    'commission_policy', 'reversal row inherits original commission snapshot; sale_commission nets negative',
    'cash_drawer_policy', 'cash refund payment auto-posts negative sale_cash via trg_payment_drawer'
  );

  insert into public.sale_reversal_audits (
    operation_id, business_id, branch_id, original_sale_id, reversal_sale_id,
    actor, reason, idempotency_key,
    reversed_cents, refunded_payment_cents, credit_restored_cents,
    points_clawed_back, points_batch_remaining_decremented,
    referral_reversed, restock_policy, effects
  )
  values (
    v_operation.id,
    o.business_id,
    o.branch_id,
    o.id,
    v_reversal.id,
    v_actor,
    btrim(p_reason),
    btrim(p_idempotency_key),
    o.amount_cents,
    v_refund_payment_cents,
    v_credit_restored_cents,
    0,
    0,
    v_referral_reversed,
    'none',
    v_effects
  );

  v_result := jsonb_build_object(
    'replayed', false,
    'operation_id', v_operation.id,
    'original_sale_id', o.id,
    'reversal_sale_id', v_reversal.id,
    'reversed_cents', o.amount_cents,
    'refunded_payment_cents', v_refund_payment_cents,
    'credit_restored_cents', v_credit_restored_cents,
    'payment_refund_ids', v_payment_ids,
    'effects', v_effects
  );

  perform set_config('app.financial_operation_complete_id', v_operation.id::text, true);
  update public.financial_operations
     set status = 'completed',
         result = v_result,
         completed_at = now()
   where id = v_operation.id
     and status = 'reserved';
  perform set_config('app.financial_operation_complete_id', '', true);
  if not found then
    raise exception 'failed to complete reserved sale reversal operation'
      using errcode = '55000';
  end if;

  insert into public.audit_log (business_id, actor, action, entity, entity_id, detail)
  values (
    o.business_id,
    v_actor,
    'SALE_REVERSAL',
    'sales',
    o.id,
    jsonb_build_object(
      'reason', btrim(p_reason),
      'operation_id', v_operation.id,
      'original_sale_id', o.id,
      'reversal_sale_id', v_reversal.id,
      'reversed_cents', o.amount_cents,
      'refunded_payment_cents', v_refund_payment_cents,
      'credit_restored_cents', v_credit_restored_cents,
      'payment_refund_ids', v_payment_ids,
      'effects', v_effects
    )
  );

  return v_result::json;
end $$;

--
-- Name: reverse_sale_v34_base(uuid, uuid, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reverse_sale_v34_base(p_business uuid, p_sale uuid, p_reason text, p_idempotency_key text, p_reference text DEFAULT NULL::text, p_restock_policy text DEFAULT 'none'::text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  o public.sales%rowtype;
  v_consumption public.package_session_consumptions%rowtype;
  v_existing public.package_session_reversals%rowtype;
  v_actor uuid := auth.uid();
  v_staff uuid;
  v_reversal_id uuid := gen_random_uuid();
  v_payload jsonb;
  v_request_hash text;
  v_result jsonb;
begin
  select * into o from public.sales where id=p_sale and business_id=p_business;
  if not found then raise exception 'sale not found in this business'; end if;
  if o.amount_cents > 0 then
    return public.reverse_sale_v20_base(p_business,p_sale,p_reason,p_idempotency_key,p_reference,p_restock_policy);
  end if;
  if o.amount_cents < 0 or o.reversal_of is not null then raise exception 'cannot reverse this sale'; end if;
  if p_idempotency_key is null or length(btrim(p_idempotency_key)) < 8 then
    raise exception 'idempotency key must contain at least 8 characters' using errcode='22023';
  end if;
  if p_reason is null or length(btrim(p_reason)) < 10 then raise exception 'reversal reason must contain at least 10 characters'; end if;
  if coalesce(p_restock_policy,'none') <> 'none' then raise exception 'package reversal does not restock inventory'; end if;
  if not app.has_perm(p_business,'refund_sales') then raise exception 'refund_sales permission required' using errcode='42501'; end if;
  if not app.can_see_branch(p_business,o.branch_id) then raise exception 'branch scope is not permitted' using errcode='42501'; end if;
  select s.id into v_staff from public.staff s
   where s.business_id=p_business and s.user_id=v_actor and s.active
     and 'refund_sales'=any(app.role_perms(s.role))
   order by case s.role when 'owner' then 0 when 'manager' then 1 else 2 end limit 1 for update;
  if not found then raise exception 'active staff authorization required' using errcode='42501'; end if;

  select * into o from public.sales where id=p_sale and business_id=p_business for update;
  if not app.has_perm(p_business,'refund_sales') or not app.can_see_branch(p_business,o.branch_id) then
    raise exception 'sale reversal authorization changed while locking' using errcode='42501';
  end if;
  select * into v_consumption from public.package_session_consumptions
   where business_id=p_business and sale_id=o.id for update;
  if not found then raise exception 'zero-dollar sale has no package session provenance'; end if;
  v_payload := jsonb_build_object('business_id',p_business,'sale_id',p_sale,'reason',btrim(p_reason),'actor',v_actor);
  v_request_hash := md5(v_payload::text);
  select * into v_existing from public.package_session_reversals where consumption_id=v_consumption.id;
  if found then
    if v_existing.idempotency_key is distinct from btrim(p_idempotency_key)
       or v_existing.request_hash is distinct from v_request_hash then
      raise exception 'package session already reversed by another immutable request' using errcode='23505';
    end if;
    return json_build_object('reversal_sale_id',v_existing.reversal_sale_id,'restored_sessions',1,
      'refunded_payment_cents',0,'no_money_refund',true,'replayed',true);
  end if;

  insert into public.package_session_reversals
    (business_id,consumption_id,original_sale_id,reversal_sale_id,actor,idempotency_key,
     request_payload,request_hash)
  values (p_business,v_consumption.id,o.id,v_reversal_id,v_actor,btrim(p_idempotency_key),v_payload,v_request_hash);
  update public.client_packages
     set remaining=remaining+1,status='active'
   where id=v_consumption.client_package_id and business_id=p_business;
  if not found then raise exception 'proven package no longer exists'; end if;

  perform set_config('app.sale_reversal_insert_id',v_reversal_id::text,true);
  perform set_config('app.sale_reversal_original_id',o.id::text,true);
  insert into public.sales
    (id,business_id,client_id,kind,amount_cents,occurred_at,note,branch_id,staff_id,
     reversal_of,reversal_reason,reversal_actor,reversal_idempotency_key)
  values
    (v_reversal_id,o.business_id,o.client_id,o.kind,0,now(),
     coalesce(nullif(btrim(p_reference),''),'package session reversal')||': '||left(btrim(p_reason),200),
     o.branch_id,o.staff_id,o.id,btrim(p_reason),v_actor,btrim(p_idempotency_key));
  perform set_config('app.sale_reversal_insert_id','',true);
  perform set_config('app.sale_reversal_original_id','',true);
  v_result := jsonb_build_object('reversal_sale_id',v_reversal_id,'restored_sessions',1,
    'refunded_payment_cents',0,'no_money_refund',true,'replayed',false);
  return v_result::json;
end $$;

--
-- Name: reverse_sale_v40_base(uuid, uuid, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reverse_sale_v40_base(p_business uuid, p_sale uuid, p_reason text, p_idempotency_key text, p_reference text DEFAULT NULL::text, p_restock_policy text DEFAULT 'none'::text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_staff uuid;
  v_sale public.sales%rowtype;
  v_existing public.package_session_reversals%rowtype;
  v_reversal_note text;
  v_expected_note text;
begin
  if v_actor is null or not app.has_perm(p_business, 'refund_sales') then
    raise exception 'refund_sales permission required' using errcode = '42501';
  end if;
  select s.id into v_staff
    from public.staff s
   where s.business_id = p_business
     and s.user_id = v_actor
     and s.active
     and 'refund_sales' = any(app.role_perms(s.role))
   order by case s.role when 'owner' then 0 when 'manager' then 1 else 2 end,
            s.created_at, s.id
   limit 1
   for update;
  if not found then
    raise exception 'active staff authorization required' using errcode = '42501';
  end if;
  select * into v_sale from public.sales
   where id = p_sale and business_id = p_business
   for update;
  if not found then raise exception 'sale not found in this business' using errcode = '42501'; end if;
  if not app.has_perm(p_business, 'refund_sales')
     or not app.can_see_branch(p_business, v_sale.branch_id) then
    raise exception 'sale reversal authorization changed while locking' using errcode = '42501';
  end if;

  if v_sale.amount_cents = 0 then
    select pr.* into v_existing
      from public.package_session_consumptions pc
      join public.package_session_reversals pr
        on pr.business_id = pc.business_id and pr.consumption_id = pc.id
      join public.sales r
        on r.business_id = pr.business_id and r.id = pr.reversal_sale_id
     where pc.business_id = p_business and pc.sale_id = p_sale;
    if found then
      select r.note into v_reversal_note
        from public.sales r
       where r.business_id = v_existing.business_id
         and r.id = v_existing.reversal_sale_id;
    end if;
    if v_existing.id is not null and v_existing.idempotency_key = btrim(p_idempotency_key) then
      v_expected_note := coalesce(nullif(btrim(p_reference), ''), 'package session reversal')
        || ': ' || left(btrim(p_reason), 200);
      if v_reversal_note is distinct from v_expected_note then
        raise exception 'package reversal idempotency key conflicts with a changed reference'
          using errcode = '23505';
      end if;
    end if;
  end if;
  return public.reverse_sale_v34_base(
    p_business,p_sale,p_reason,p_idempotency_key,p_reference,p_restock_policy
  );
end $$;

--
-- Name: rls_auto_enable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rls_auto_enable() RETURNS event_trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$$;

--
-- Name: run_expiry_now(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.run_expiry_now(p_business uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_staff uuid;
begin
  if not exists (
    select 1 from public.staff s
     where s.business_id = p_business
       and s.user_id = v_actor
       and s.active
       and s.role = 'owner'
  ) then
    raise exception 'only an active owner may run points expiry for this business'
      using errcode = '42501';
  end if;

  select s.id into v_staff
    from public.staff s
   where s.business_id = p_business
     and s.user_id = v_actor
     and s.active
     and s.role = 'owner'
   order by s.created_at
   limit 1
   for update;
  if not found then
    raise exception 'active owner authorization is required to run points expiry'
      using errcode = '42501';
  end if;
  if not exists (
    select 1 from public.staff s
     where s.id = v_staff
       and s.business_id = p_business
       and s.user_id = v_actor
       and s.active
       and s.role = 'owner'
  ) then
    raise exception 'points-expiry authorization changed while the actor was locked'
      using errcode = '42501';
  end if;

  perform app.run_points_expiry_for_business(p_business);
end $$;

--
-- Name: run_subscription_lifecycle_v94(date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.run_subscription_lifecycle_v94(p_as_of date DEFAULT ((now() AT TIME ZONE 'Asia/Singapore'::text))::date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if not app.is_super_admin()
     and coalesce(auth.jwt()->>'role','')<>'service_role' then
    raise exception 'subscription_lifecycle_runner_required' using errcode='42501';
  end if;
  return app.run_subscription_lifecycle_v94(p_as_of);
end
$$;

--
-- Name: run_sv_reconciliation(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.run_sv_reconciliation(p_business uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_asset text := 'stored_value';
  v_run uuid := gen_random_uuid();
  v_snapshot uuid := gen_random_uuid();
  v_authority text;
  gc record;
  v_legacy_ref text;
  v_studio integer;
  v_legacy_total bigint := 0;
  v_studio_total bigint := 0;
  v_disc integer;
  v_status text;
  v_category text;
  v_dup boolean;
  v_discrepancies jsonb := '[]'::jsonb;
  v_ack_cents bigint;       -- v70: latest acknowledged outstanding legacy amount (null = none)
  v_missing_total bigint;   -- v70: outstanding legacy value flagged missing_in_studio
  v_net bigint;             -- v70: missing_total - acknowledged (0 = clean; != 0 = drift)
begin
  if not (app.is_salon_owner(p_business) or app.sv_automation_context()) then
    raise exception 'owner only' using errcode = '42501';
  end if;
  select state into v_authority from public.sv_authority
   where business_id = p_business and asset = v_asset;
  if v_authority is null then
    raise exception 'stored-value authority is not initialised for this business' using errcode = '22023';
  end if;

  -- v70: the LATEST amount-specific acknowledgement for this (business, asset). NULL => behave
  -- exactly as v69 (every outstanding card reads missing_in_studio). Never a blanket ignore.
  select acknowledged_cents into v_ack_cents from public.sv_legacy_acknowledgements
   where business_id = p_business and asset = v_asset
   order by seq desc limit 1;

  -- Direction 1: legacy (gift_cards, READ-ONLY) -> studio projection. No migration linkage
  -- exists in PS-2A, so the studio value attributable to any legacy gift card is 0.
  for gc in
    select id, code, balance_cents, status, purchaser_client_id
      from public.gift_cards
     where business_id = p_business
     order by id
  loop
    v_legacy_ref := 'legacy:giftcard:' || gc.id::text;
    v_studio := 0;
    v_legacy_total := v_legacy_total + coalesce(gc.balance_cents, 0);
    v_studio_total := v_studio_total + v_studio;

    -- Shadow evaluation: the would-be mint projection of this legacy balance into the studio
    -- ledger. Writing it moves NO value (append-only shadow log only).
    perform app.sv_write_shadow_evaluation(
      p_business, null, v_asset, 'topup',
      jsonb_build_array(jsonb_build_object('class', 'paid', 'kind', 'issue', 'cents', coalesce(gc.balance_cents, 0))),
      coalesce(gc.balance_cents, 0), v_legacy_ref, 'reconcile_projection');

    select count(*) > 1 into v_dup from public.gift_cards g
     where g.business_id = p_business and g.code = gc.code;

    v_category := null;
    if gc.balance_cents is null or gc.balance_cents < 0 then
      v_category := 'invalid_legacy_balance';
    elsif v_dup then
      v_category := 'duplicate_legacy_event';
    elsif gc.status in ('void', 'redeemed') and gc.balance_cents > 0 then
      v_category := 'orphan_legacy_record';
    elsif gc.balance_cents > 0 and v_studio = 0 then
      v_category := 'missing_in_studio';
    elsif gc.balance_cents <> v_studio then
      v_category := 'amount_mismatch';
    else
      v_category := null;   -- balance 0 (or exact match) -> clean, no discrepancy row
    end if;

    if v_category is not null then
      v_discrepancies := v_discrepancies || jsonb_build_object(
        'category', v_category,
        'legacy_ref', v_legacy_ref,
        'client_id', gc.purchaser_client_id,
        'legacy_cents', gc.balance_cents,
        'studio_cents', v_studio,
        'delta_cents', case when gc.balance_cents is null then null else gc.balance_cents - v_studio end,
        'detail', jsonb_build_object('code', gc.code, 'status', gc.status, 'source', 'gift_cards'));
    end if;
  end loop;

  -- Direction 2: a studio record claiming a legacy gift-card origin (a prior shadow
  -- evaluation's legacy_ref) whose gift card has vanished -> missing_in_legacy. Empty on a
  -- fresh tenant (every current card exists); DISTINCT so each vanished ref is one row.
  for v_legacy_ref in
    select distinct se.legacy_ref
      from public.sv_shadow_evaluations se
     where se.business_id = p_business
       and se.legacy_ref like 'legacy:giftcard:%'
       and not exists (
         select 1 from public.gift_cards g
          where g.business_id = p_business
            and 'legacy:giftcard:' || g.id::text = se.legacy_ref)
     order by se.legacy_ref
  loop
    v_discrepancies := v_discrepancies || jsonb_build_object(
      'category', 'missing_in_legacy',
      'legacy_ref', v_legacy_ref,
      'client_id', null,
      'legacy_cents', null,
      'studio_cents', 0,
      'delta_cents', null,
      'detail', jsonb_build_object('source', 'studio_shadow_origin'));
  end loop;

  -- v70: amount-specific acknowledgement netting (contract section 2). The outstanding legacy value
  -- flagged missing_in_studio is netted against the LATEST acknowledged amount. Exact match nets to
  -- clean (the missing_in_studio rows are removed); any drift - a new card grows the total, or a
  -- partial redemption (incl. to zero) shrinks it below the acknowledgement - re-blocks as ONE
  -- acknowledgement_drift row, until re-acknowledged at the new amount. Only missing_in_studio is
  -- subject to acknowledgement; data-integrity categories (invalid/duplicate/orphan/amount_mismatch/
  -- missing_in_legacy) are never papered over. When v_ack_cents is NULL this block is a no-op.
  if v_ack_cents is not null then
    select coalesce(sum((d->>'legacy_cents')::bigint), 0) into v_missing_total
      from jsonb_array_elements(v_discrepancies) d
     where d->>'category' = 'missing_in_studio';
    select coalesce(jsonb_agg(d), '[]'::jsonb) into v_discrepancies
      from jsonb_array_elements(v_discrepancies) d
     where d->>'category' <> 'missing_in_studio';
    v_net := v_missing_total - v_ack_cents;
    if v_net <> 0 then
      v_discrepancies := v_discrepancies || jsonb_build_object(
        'category', 'acknowledgement_drift',
        'legacy_ref', 'legacy:acknowledgement:' || v_asset,
        'client_id', null,
        'legacy_cents', v_missing_total,
        'studio_cents', v_ack_cents,
        'delta_cents', v_net,
        'detail', jsonb_build_object(
          'source', 'legacy_acknowledgement',
          'acknowledged_cents', v_ack_cents,
          'outstanding_missing_cents', v_missing_total,
          'direction', case when v_net > 0 then 'legacy_exceeds_acknowledgement'
                            else 'acknowledgement_exceeds_legacy' end));
    end if;
  end if;

  v_disc := jsonb_array_length(v_discrepancies);
  v_status := case when v_disc = 0 then 'clean' else 'blocked' end;

  -- Snapshot FIRST (the discrepancy rows carry a composite FK to it). v70: acknowledged_cents.
  insert into public.sv_reconciliation_snapshots(
    id, business_id, run_id, asset, source, actor,
    legacy_total_cents, studio_total_cents, discrepancy_count, status, acknowledged_cents)
  values (v_snapshot, p_business, v_run, v_asset, 'gift_cards', v_actor,
    v_legacy_total, v_studio_total, v_disc, v_status, v_ack_cents);

  insert into public.sv_reconciliation_discrepancies(
    business_id, run_id, snapshot_id, category, legacy_ref, client_id,
    legacy_cents, studio_cents, delta_cents, detail)
  select p_business, v_run, v_snapshot,
    d->>'category', d->>'legacy_ref', nullif(d->>'client_id', '')::uuid,
    (d->>'legacy_cents')::integer, (d->>'studio_cents')::integer, (d->>'delta_cents')::integer,
    coalesce(d->'detail', '{}'::jsonb)
  from jsonb_array_elements(v_discrepancies) d;

  -- Any open discrepancy blocks cutover (drives 'reconciliation_blocked' via the INTERNAL
  -- state path). NEVER auto-corrects, NEVER writes a legacy row.
  -- v69 (ADDED PREDICATE): a LIVE tenant is NEVER downgraded by this run. The discrepancy is
  -- still captured in the snapshot, the discrepancy rows and the audit entry; the owner control
  -- is sv_pause (§5). The state is re-read here rather than reusing the entry-time value so a
  -- cutover committed mid-run cannot be undone by a stale read.
  if v_disc > 0 and coalesce((select state from public.sv_authority
                               where business_id = p_business and asset = v_asset), '') <> 'live' then
    perform app.sv_apply_authority_state(
      p_business, v_asset, 'reconciliation_blocked', 'open stored-value reconciliation discrepancies', v_actor);
  end if;

  insert into public.audit_log(business_id, actor, action, entity, entity_id, detail)
  values (p_business, v_actor, 'SV_RECONCILIATION_RUN', 'sv_reconciliation_snapshots', v_snapshot, jsonb_build_object(
    'run_id', v_run, 'status', v_status, 'discrepancy_count', v_disc,
    'legacy_total_cents', v_legacy_total, 'studio_total_cents', v_studio_total,
    'acknowledged_cents', v_ack_cents));

  return jsonb_build_object(
    'status', 'ok',
    'run_id', v_run,
    'snapshot_id', v_snapshot,
    'source', 'gift_cards',
    'reconciliation_status', v_status,
    'discrepancy_count', v_disc,
    'legacy_total_cents', v_legacy_total,
    'studio_total_cents', v_studio_total,
    'acknowledged_cents', v_ack_cents,
    'authority_state', (select state from public.sv_authority where business_id = p_business and asset = v_asset));
end $$;

--
-- Name: save_birthday_program_draft(uuid, uuid, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_birthday_program_draft(p_config_version uuid, p_program_id uuid, p_program jsonb, p_expected_snapshot_hash text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_header public.firm_config_versions%rowtype;
  v_existing public.birthday_program_versions%rowtype;
  v_hash text;
  v_request_hash text;
  v_replay public.birthday_program_draft_operations%rowtype;
  v_active boolean;
  v_label text;
  v_description text;
  v_terms text;
  v_kind text;
  v_discount numeric(5,2);
  v_item text;
  v_before integer;
  v_after integer;
  v_sort integer;
  v_mode text;
begin
  if p_program_id is null or p_program is null or jsonb_typeof(p_program) <> 'object'
     or p_expected_snapshot_hash is null or length(p_expected_snapshot_hash) <> 32 then
    raise exception 'birthday draft request is invalid' using errcode = '22023';
  end if;
  if exists (select 1 from jsonb_object_keys(p_program) k where k not in (
    'active','customer_label','customer_description','customer_terms','fulfillment_kind',
    'discount_percent','manual_item','window_days_before','window_days_after','sort','window_mode'
  )) then
    raise exception 'birthday program contains unsupported fields' using errcode = '22023';
  end if;
  v_request_hash := app.c45_hash(jsonb_build_object('program_id',p_program_id,'program',p_program)::text);
  select * into v_header from public.firm_config_versions where id = p_config_version for update;
  if not found or not app.c45_owner_loyalty_write(v_header.business_id) then
    raise exception 'owner loyalty configuration access required' using errcode = '42501';
  end if;
  if v_header.status <> 'draft' then raise exception 'only a draft birthday program may be edited' using errcode = '42501'; end if;
  select * into v_replay from public.birthday_program_draft_operations
   where config_version_id=p_config_version and actor=auth.uid() and program_id=p_program_id
     and expected_snapshot_hash=p_expected_snapshot_hash for share;
  if found then
    if v_replay.request_hash is distinct from v_request_hash then
      raise exception 'birthday draft request conflicts with an existing operation' using errcode = '40001';
    end if;
    return jsonb_build_object('status','draft','snapshot_hash',v_replay.result_snapshot_hash,'replayed',true);
  end if;
  if v_header.snapshot_hash is distinct from p_expected_snapshot_hash then
    raise exception 'draft configuration changed; reload before saving' using errcode = '40001';
  end if;
  select * into v_existing from public.birthday_program_versions
   where config_version_id=p_config_version and business_id=v_header.business_id and program_id=p_program_id for update;
  if v_existing.id is null and exists (
    select 1 from public.birthday_program_versions p
     where p.config_version_id=p_config_version and p.business_id=v_header.business_id
  ) then
    raise exception 'only one birthday program may exist in a configuration version' using errcode='22023';
  end if;
  if v_existing.id is null then
    if exists (select 1 from public.birthday_programs where id=p_program_id and business_id<>v_header.business_id) then
      raise exception 'birthday program does not belong to this business' using errcode = '42501';
    end if;
    insert into public.birthday_programs(id,business_id) values(p_program_id,v_header.business_id)
      on conflict (id) do nothing;
  end if;
  v_active := case when p_program ? 'active' then (p_program->>'active')::boolean else coalesce(v_existing.active,true) end;
  v_label := coalesce(nullif(btrim(p_program->>'customer_label'),''),v_existing.customer_label);
  v_description := coalesce(nullif(btrim(p_program->>'customer_description'),''),v_existing.customer_description);
  v_terms := coalesce(nullif(btrim(p_program->>'customer_terms'),''),v_existing.customer_terms);
  v_kind := coalesce(nullif(btrim(p_program->>'fulfillment_kind'),''),v_existing.fulfillment_kind);
  v_discount := case when p_program ? 'discount_percent' then nullif(p_program->>'discount_percent','')::numeric else v_existing.discount_percent end;
  v_item := case when p_program ? 'manual_item' then nullif(btrim(p_program->>'manual_item'),'') else v_existing.manual_item end;
  v_before := case when p_program ? 'window_days_before' then (p_program->>'window_days_before')::integer else coalesce(v_existing.window_days_before,0) end;
  v_after := case when p_program ? 'window_days_after' then (p_program->>'window_days_after')::integer else coalesce(v_existing.window_days_after,0) end;
  v_sort := case when p_program ? 'sort' then (p_program->>'sort')::integer else coalesce(v_existing.sort,0) end;
  v_mode := case when p_program ? 'window_mode' then nullif(btrim(p_program->>'window_mode'),'')
                 else coalesce(v_existing.window_mode,'days') end;
  if v_label is null or v_description is null or v_terms is null or v_kind not in ('discount_pct','free_item')
     or v_before not between 0 and 182 or v_after not between 0 and 182 or v_before+v_after+1 > 365
     or v_sort not between 0 and 10000 or v_mode not in ('days','month')
     or (v_kind='discount_pct' and (v_discount is null or v_discount<=0 or v_discount>100 or v_item is not null))
     or (v_kind='free_item' and (v_discount is not null or v_item is null)) then
    raise exception 'birthday programme values are invalid' using errcode = '22023';
  end if;
  insert into public.birthday_program_versions(
    program_id,config_version_id,business_id,active,customer_label,customer_description,
    customer_terms,fulfillment_kind,discount_percent,manual_item,window_days_before,window_days_after,sort,window_mode
  ) values(
    p_program_id,p_config_version,v_header.business_id,v_active,v_label,v_description,
    v_terms,v_kind,v_discount,v_item,v_before,v_after,v_sort,v_mode
  ) on conflict(program_id,config_version_id) do update set
    active=excluded.active, customer_label=excluded.customer_label,
    customer_description=excluded.customer_description, customer_terms=excluded.customer_terms,
    fulfillment_kind=excluded.fulfillment_kind, discount_percent=excluded.discount_percent,
    manual_item=excluded.manual_item, window_mode=excluded.window_mode, window_days_before=excluded.window_days_before,
    window_days_after=excluded.window_days_after, sort=excluded.sort;
  perform app.refresh_loyalty_config_snapshot(p_config_version);
  select snapshot_hash into v_hash from public.firm_config_versions where id=p_config_version;
  insert into public.birthday_program_draft_operations(
    config_version_id,business_id,actor,program_id,expected_snapshot_hash,request_hash,result_snapshot_hash
  ) values(p_config_version,v_header.business_id,auth.uid(),p_program_id,p_expected_snapshot_hash,v_request_hash,v_hash);
  return jsonb_build_object('status','draft','snapshot_hash',v_hash,'replayed',false);
end $$;

--
-- Name: save_loyalty_branch_override_draft(uuid, uuid, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_loyalty_branch_override_draft(p_config_version uuid, p_branch uuid, p_override jsonb, p_expected_snapshot_hash text DEFAULT NULL::text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_header public.firm_config_versions%rowtype;
  v_hash text;
  v_active boolean;
  v_earn numeric;
  v_stamp integer;
  v_expiry_mode text;
  v_expiry_days integer;
begin
  if p_override is null or jsonb_typeof(p_override) <> 'object' then
    raise exception 'override must be a JSON object' using errcode = '22023';
  end if;
  if exists (
    select 1 from jsonb_object_keys(p_override) k
     where k not in ('active','earn_points_per_dollar','stamp_per_cents','expiry_mode','expiry_days')
  ) then
    raise exception 'branch override contains unsupported fields' using errcode = '22023';
  end if;

  select * into v_header
    from public.firm_config_versions
   where id = p_config_version
   for update;

  if not found or not app.is_salon_owner(v_header.business_id) then
    raise exception 'owner only' using errcode = '42501';
  end if;
  if v_header.status <> 'draft' then
    raise exception 'only a draft branch override may be edited' using errcode = '42501';
  end if;
  if p_expected_snapshot_hash is not null
     and v_header.snapshot_hash is distinct from p_expected_snapshot_hash then
    raise exception 'draft configuration changed; reload before saving'
      using errcode = '40001';
  end if;
  if not exists (
    select 1 from public.branches b
     where b.id = p_branch
       and b.business_id = v_header.business_id
  ) then
    raise exception 'branch does not belong to this business' using errcode = '42501';
  end if;

  v_active := case when p_override ? 'active' then (p_override->>'active')::boolean end;
  v_earn := case when p_override ? 'earn_points_per_dollar' then nullif(p_override->>'earn_points_per_dollar','')::numeric end;
  v_stamp := case when p_override ? 'stamp_per_cents' then nullif(p_override->>'stamp_per_cents','')::integer end;
  v_expiry_mode := case when p_override ? 'expiry_mode' then nullif(p_override->>'expiry_mode','') end;
  v_expiry_days := case when p_override ? 'expiry_days' then nullif(p_override->>'expiry_days','')::integer end;

  if v_earn is not null and v_earn < 0 then
    raise exception 'earn_points_per_dollar must be at least zero' using errcode = '22023';
  end if;
  if v_stamp is not null and v_stamp <= 0 then
    raise exception 'stamp_per_cents must be positive' using errcode = '22023';
  end if;
  if v_expiry_mode is not null and v_expiry_mode not in ('none','fixed','inactivity') then
    raise exception 'unsupported expiry_mode' using errcode = '22023';
  end if;
  if v_expiry_days is not null and v_expiry_days <= 0 then
    raise exception 'expiry_days must be positive' using errcode = '22023';
  end if;
  if v_active is null
     and v_earn is null
     and v_stamp is null
     and v_expiry_mode is null
     and v_expiry_days is null then
    raise exception 'use remove_loyalty_branch_override_draft to inherit every firm setting'
      using errcode = '22023';
  end if;

  insert into public.loyalty_branch_overrides (
    config_version_id, business_id, branch_id, active,
    earn_points_per_dollar, stamp_per_cents, expiry_mode, expiry_days
  ) values (
    p_config_version, v_header.business_id, p_branch, v_active,
    v_earn, v_stamp, v_expiry_mode, v_expiry_days
  )
  on conflict (config_version_id, branch_id) do update set
    active = excluded.active,
    earn_points_per_dollar = excluded.earn_points_per_dollar,
    stamp_per_cents = excluded.stamp_per_cents,
    expiry_mode = excluded.expiry_mode,
    expiry_days = excluded.expiry_days;

  perform app.refresh_loyalty_config_snapshot(p_config_version);
  select snapshot_hash into v_hash
    from public.firm_config_versions
   where id = p_config_version;

  return json_build_object(
    'config_version_id', p_config_version,
    'branch_id', p_branch,
    'status', 'draft',
    'snapshot_hash', v_hash
  );
end $$;

--
-- Name: save_loyalty_config_draft(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_loyalty_config_draft(p_version uuid, p_config jsonb) RETURNS json
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$ select public.save_loyalty_config_draft(p_version, p_config, null::text) $$;

--
-- Name: save_loyalty_config_draft(uuid, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_loyalty_config_draft(p_version uuid, p_config jsonb, p_expected_snapshot_hash text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_header public.firm_config_versions%rowtype;
  v_typed public.loyalty_program_versions%rowtype;
  v_hash text;
  v_tier jsonb;
  v_tier_id uuid;
begin
  select * into v_header
    from public.firm_config_versions
   where id = p_version
   for update;

  if not found or not app.is_salon_owner(v_header.business_id) then
    raise exception 'owner only' using errcode = '42501';
  end if;
  if v_header.status <> 'draft' then
    raise exception 'only a draft may be edited';
  end if;
  if p_expected_snapshot_hash is not null
     and v_header.snapshot_hash is distinct from p_expected_snapshot_hash then
    raise exception 'draft configuration changed; reload before saving'
      using errcode = '40001';
  end if;

  select * into v_typed
    from public.loyalty_program_versions
   where config_version_id = p_version;

  update public.loyalty_program_versions set
    kind = coalesce(p_config->>'kind', v_typed.kind),
    loyalty_model = coalesce(p_config->>'loyalty_model', v_typed.loyalty_model),
    active = coalesce((p_config->>'active')::boolean, v_typed.active),
    earn_points_per_dollar = coalesce((p_config->>'earn_points_per_dollar')::numeric, v_typed.earn_points_per_dollar),
    redeem_points = coalesce((p_config->>'redeem_points')::integer, v_typed.redeem_points),
    reward_credit_cents = coalesce((p_config->>'reward_credit_cents')::integer, v_typed.reward_credit_cents),
    stamp_target = case when p_config ? 'stamp_target' then (p_config->>'stamp_target')::integer else v_typed.stamp_target end,
    stamp_per_cents = case when p_config ? 'stamp_per_cents' then (p_config->>'stamp_per_cents')::integer else v_typed.stamp_per_cents end,
    tier_basis = coalesce(p_config->>'tier_basis', v_typed.tier_basis),
    expiry_mode = coalesce(p_config->>'expiry_mode', v_typed.expiry_mode),
    expiry_days = case when p_config ? 'expiry_days' then (p_config->>'expiry_days')::integer else v_typed.expiry_days end
   where config_version_id = p_version;

  if p_config ? 'reward' then
    if jsonb_typeof(p_config->'reward') <> 'object' then
      raise exception 'reward must be a JSON object' using errcode = '22023';
    end if;
    perform public.save_loyalty_reward_draft(
      p_version,
      nullif(p_config->'reward'->>'id', '')::uuid,
      p_config->'reward',
      jsonb_build_object(
        'branches', coalesce(p_config->'reward_branch_ids', '[]'::jsonb),
        'services', coalesce(p_config->'reward_service_ids', '[]'::jsonb),
        'products', coalesce(p_config->'reward_product_ids', '[]'::jsonb)
      )
    );
  elsif p_config ? 'reward_branch_ids' or p_config ? 'reward_service_ids' or p_config ? 'reward_product_ids' then
    raise exception 'eligibility requires a reward envelope' using errcode = '22023';
  end if;

  if p_config ? 'tier' then
    v_tier := p_config->'tier';
    if jsonb_typeof(v_tier) <> 'object' then
      raise exception 'tier must be an object' using errcode = '22023';
    end if;
    if exists (
      select 1 from jsonb_object_keys(v_tier) k
       where k not in ('id','name','threshold','points_multiplier','perk_note','sort','active')
    ) then
      raise exception 'tier contains unsupported fields' using errcode = '22023';
    end if;
    v_tier_id := coalesce(nullif(v_tier->>'id', '')::uuid, gen_random_uuid());
    if nullif(btrim(v_tier->>'name'), '') is null
       or coalesce((v_tier->>'threshold')::integer, -1) < 0
       or coalesce((v_tier->>'points_multiplier')::numeric, 0) < 1 then
      raise exception 'tier requires a name, non-negative threshold and multiplier of at least 1'
        using errcode = '22023';
    end if;
    insert into public.loyalty_tier_versions
      (tier_id, config_version_id, business_id, name, threshold, points_multiplier, perk_note, sort, active)
    values (
      v_tier_id, p_version, v_header.business_id, btrim(v_tier->>'name'),
      (v_tier->>'threshold')::integer, (v_tier->>'points_multiplier')::numeric,
      nullif(btrim(v_tier->>'perk_note'), ''), coalesce((v_tier->>'sort')::integer, 0),
      coalesce((v_tier->>'active')::boolean, true)
    )
    on conflict (tier_id, config_version_id) do update set
      name = excluded.name,
      threshold = excluded.threshold,
      points_multiplier = excluded.points_multiplier,
      perk_note = excluded.perk_note,
      sort = excluded.sort,
      active = excluded.active;
  end if;

  perform app.refresh_loyalty_config_snapshot(p_version);
  select snapshot_hash into v_hash
    from public.firm_config_versions
   where id = p_version;

  return json_build_object('version_id', p_version, 'status', 'draft', 'snapshot_hash', v_hash);
end $$;

--
-- Name: save_loyalty_reward_draft(uuid, uuid, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_loyalty_reward_draft(p_config_version uuid, p_reward_id uuid, p_reward jsonb, p_eligibility jsonb DEFAULT '{}'::jsonb) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_header public.firm_config_versions%rowtype;
  v_existing public.loyalty_reward_versions%rowtype;
  v_reward_id uuid := coalesce(p_reward_id, gen_random_uuid());
  v_version_id uuid;
  v_internal_name text;
  v_customer_name text;
  v_description text;
  v_kind text;
  v_taxonomy text;
  v_cost integer;
  v_credit integer;
  v_estimated integer;
  v_active boolean;
  v_sort integer;
  v_claim_from timestamptz;
  v_claim_until timestamptz;
  v_entitlement_days integer;
  v_instructions text;
  v_terms text;
  v_image text;
  v_limit integer;
  v_requires_purchase boolean;
begin
  if p_reward is null or jsonb_typeof(p_reward) <> 'object' then
    raise exception 'reward must be a JSON object' using errcode = '22023';
  end if;
  if p_eligibility is null or jsonb_typeof(p_eligibility) <> 'object' then
    raise exception 'eligibility must be a JSON object' using errcode = '22023';
  end if;
  if exists (
    select 1 from jsonb_object_keys(p_reward) k
     where k not in (
       'id','business_id','name','internal_name','customer_name','description','fulfillment_kind','taxonomy_label',
       'cost_points','credit_cents','estimated_cost_cents','active','sort',
       'claim_available_from','claim_available_until','entitlement_expiry_days',
       'instructions','terms','image_ref','usage_limit','requires_purchase'
     )
  ) then raise exception 'reward contains unsupported fields' using errcode = '22023'; end if;
  if exists (select 1 from jsonb_object_keys(p_eligibility) k where k not in ('branches','services','products')) then
    raise exception 'eligibility contains unsupported fields' using errcode = '22023';
  end if;
  if jsonb_typeof(coalesce(p_eligibility->'branches','[]'::jsonb)) <> 'array'
     or jsonb_typeof(coalesce(p_eligibility->'services','[]'::jsonb)) <> 'array'
     or jsonb_typeof(coalesce(p_eligibility->'products','[]'::jsonb)) <> 'array' then
    raise exception 'each eligibility value must be an array' using errcode = '22023';
  end if;
  if jsonb_array_length(coalesce(p_eligibility->'branches','[]'::jsonb)) > 500
     or jsonb_array_length(coalesce(p_eligibility->'services','[]'::jsonb)) > 500
     or jsonb_array_length(coalesce(p_eligibility->'products','[]'::jsonb)) > 500 then
    raise exception 'eligibility arrays may contain at most 500 items' using errcode = '22023';
  end if;

  select * into v_header from public.firm_config_versions where id = p_config_version for update;
  if not found or not app.is_salon_owner(v_header.business_id) then
    raise exception 'owner only' using errcode = '42501';
  end if;
  if v_header.status <> 'draft' then raise exception 'only a draft reward configuration may be edited'; end if;
  if p_reward ? 'business_id' and (p_reward->>'business_id')::uuid is distinct from v_header.business_id then
    raise exception 'reward business does not match configuration business' using errcode = '42501';
  end if;
  if p_reward_id is not null and not exists (
    select 1 from public.loyalty_rewards where id = p_reward_id and business_id = v_header.business_id
  ) then raise exception 'reward does not belong to this business' using errcode = '42501'; end if;

  select * into v_existing from public.loyalty_reward_versions
   where reward_id = v_reward_id and config_version_id = p_config_version for update;

  v_internal_name := coalesce(nullif(btrim(p_reward->>'internal_name'),''), nullif(btrim(p_reward->>'name'),''), v_existing.internal_name);
  v_customer_name := coalesce(nullif(btrim(p_reward->>'customer_name'),''), v_existing.customer_name);
  v_description := case when p_reward ? 'description' then nullif(p_reward->>'description','') else v_existing.description end;
  v_kind := coalesce(p_reward->>'fulfillment_kind', v_existing.fulfillment_kind, 'credit');
  v_taxonomy := case when p_reward ? 'taxonomy_label' then nullif(btrim(p_reward->>'taxonomy_label'),'') else v_existing.taxonomy_label end;
  v_cost := coalesce((p_reward->>'cost_points')::integer, v_existing.cost_points);
  v_credit := coalesce((p_reward->>'credit_cents')::integer, v_existing.credit_cents, 0);
  v_estimated := coalesce((p_reward->>'estimated_cost_cents')::integer, v_existing.estimated_cost_cents, v_credit);
  v_active := case when p_reward ? 'active' then (p_reward->>'active')::boolean else coalesce(v_existing.active, true) end;
  v_sort := coalesce((p_reward->>'sort')::integer, v_existing.sort, 0);
  v_claim_from := case when p_reward ? 'claim_available_from' then nullif(p_reward->>'claim_available_from','')::timestamptz else v_existing.claim_available_from end;
  v_claim_until := case when p_reward ? 'claim_available_until' then nullif(p_reward->>'claim_available_until','')::timestamptz else v_existing.claim_available_until end;
  v_entitlement_days := case when p_reward ? 'entitlement_expiry_days' then nullif(p_reward->>'entitlement_expiry_days','')::integer else v_existing.entitlement_expiry_days end;
  v_instructions := case when p_reward ? 'instructions' then nullif(p_reward->>'instructions','') else v_existing.instructions end;
  v_terms := case when p_reward ? 'terms' then nullif(p_reward->>'terms','') else v_existing.terms end;
  v_image := case when p_reward ? 'image_ref' then nullif(p_reward->>'image_ref','') else v_existing.image_ref end;
  v_requires_purchase := case when p_reward ? 'requires_purchase' then coalesce((p_reward->>'requires_purchase')::boolean, false) else coalesce(v_existing.requires_purchase, false) end;
  v_limit := case when p_reward ? 'usage_limit' then nullif(p_reward->>'usage_limit','')::integer else v_existing.usage_limit end;
  if v_internal_name is null or v_customer_name is null or v_cost is null then
    raise exception 'internal_name, customer_name, and cost_points are required' using errcode = '22023';
  end if;
  if v_kind not in ('credit','manual_item') then raise exception 'unsupported fulfillment kind' using errcode = '22023'; end if;
  if (v_kind='credit' and v_credit <= 0) or (v_kind='manual_item' and v_credit <> 0) then
    raise exception 'credit rewards need positive credit; manual-item rewards must have zero credit' using errcode = '22023';
  end if;

  if not found then
    insert into public.loyalty_rewards (
      id, business_id, name, internal_name, customer_name, description, fulfillment_kind,
      taxonomy_label, cost_points, credit_cents, estimated_cost_cents, active, sort,
      claim_available_from, claim_available_until, entitlement_expiry_days, instructions, terms,
      image_ref, requires_purchase, usage_limit, current_config_version_id
    ) values (
      v_reward_id, v_header.business_id, v_customer_name, v_internal_name, v_customer_name,
      v_description, v_kind, v_taxonomy, v_cost, v_credit, v_estimated, false, v_sort,
      v_claim_from, v_claim_until, v_entitlement_days, v_instructions, v_terms, v_image, v_requires_purchase, v_limit,
      p_config_version
    );
  end if;

  insert into public.loyalty_reward_versions (
    reward_id, business_id, config_version_id, internal_name, customer_name, description,
    fulfillment_kind, taxonomy_label, cost_points, credit_cents, estimated_cost_cents, active,
    sort, claim_available_from, claim_available_until, entitlement_expiry_days, instructions,
    terms, image_ref, requires_purchase, usage_limit
  ) values (
    v_reward_id, v_header.business_id, p_config_version, v_internal_name, v_customer_name,
    v_description, v_kind, v_taxonomy, v_cost, v_credit, v_estimated, v_active, v_sort,
    v_claim_from, v_claim_until, v_entitlement_days, v_instructions, v_terms, v_image, v_requires_purchase, v_limit
  ) on conflict (reward_id, config_version_id) do update set
    internal_name = excluded.internal_name, customer_name = excluded.customer_name,
    description = excluded.description, fulfillment_kind = excluded.fulfillment_kind,
    taxonomy_label = excluded.taxonomy_label, cost_points = excluded.cost_points,
    credit_cents = excluded.credit_cents, estimated_cost_cents = excluded.estimated_cost_cents,
    active = excluded.active, sort = excluded.sort, claim_available_from = excluded.claim_available_from,
    claim_available_until = excluded.claim_available_until,
    entitlement_expiry_days = excluded.entitlement_expiry_days, instructions = excluded.instructions,
    terms = excluded.terms, image_ref = excluded.image_ref, requires_purchase = excluded.requires_purchase,
    usage_limit = excluded.usage_limit
  returning id into v_version_id;

  delete from public.loyalty_reward_branches where reward_version_id = v_version_id;
  delete from public.loyalty_reward_services where reward_version_id = v_version_id;
  delete from public.loyalty_reward_products where reward_version_id = v_version_id;
  insert into public.loyalty_reward_branches (reward_version_id, reward_id, business_id, branch_id)
  select v_version_id, v_reward_id, v_header.business_id, x.value::uuid
    from jsonb_array_elements_text(coalesce(p_eligibility->'branches','[]'::jsonb)) x;
  insert into public.loyalty_reward_services (reward_version_id, reward_id, business_id, service_id)
  select v_version_id, v_reward_id, v_header.business_id, x.value::uuid
    from jsonb_array_elements_text(coalesce(p_eligibility->'services','[]'::jsonb)) x;
  insert into public.loyalty_reward_products (reward_version_id, reward_id, business_id, product_id)
  select v_version_id, v_reward_id, v_header.business_id, x.value::uuid
    from jsonb_array_elements_text(coalesce(p_eligibility->'products','[]'::jsonb)) x;
  perform app.refresh_loyalty_config_snapshot(p_config_version);
  return json_build_object('reward_id', v_reward_id, 'reward_version_id', v_version_id, 'status', 'draft');
end $$;

--
-- Name: save_loyalty_tier_draft_v143(uuid, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_loyalty_tier_draft_v143(p_version uuid, p_tier jsonb, p_expected_snapshot_hash text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_header public.firm_config_versions%rowtype;
  v_tier_id uuid;
  v_effective_from timestamptz;
  v_expires_at timestamptz;
  v_hash text;
begin
  if p_tier is null or jsonb_typeof(p_tier)<>'object' then
    raise exception 'tier must be an object' using errcode='22023';
  end if;
  if exists(
    select 1 from jsonb_object_keys(p_tier) field
    where field not in (
      'id','name','threshold','points_multiplier','perk_note','sort','active',
      'effective_from','expires_at'
    )
  ) then
    raise exception 'tier contains unsupported fields' using errcode='22023';
  end if;

  select * into v_header
  from public.firm_config_versions
  where id=p_version
  for update;
  if not found or not app.c45_owner_loyalty_write(v_header.business_id) then
    raise exception 'owner loyalty configuration access required' using errcode='42501';
  end if;
  if v_header.status<>'draft' then
    raise exception 'only a draft may be edited' using errcode='55000';
  end if;
  if p_expected_snapshot_hash is not null
     and v_header.snapshot_hash is distinct from p_expected_snapshot_hash then
    raise exception 'draft configuration changed; reload before saving'
      using errcode='40001';
  end if;

  begin
    v_tier_id:=coalesce(nullif(p_tier->>'id','')::uuid,gen_random_uuid());
    v_effective_from:=nullif(p_tier->>'effective_from','')::timestamptz;
    v_expires_at:=nullif(p_tier->>'expires_at','')::timestamptz;
  exception when others then
    raise exception 'tier identifiers and effective boundaries must be valid'
      using errcode='22023';
  end;
  if nullif(btrim(p_tier->>'name'),'') is null
     or coalesce((p_tier->>'threshold')::integer,-1)<0
     or coalesce((p_tier->>'points_multiplier')::numeric,0)<1 then
    raise exception 'tier requires a name, non-negative threshold and multiplier of at least 1'
      using errcode='22023';
  end if;
  if v_expires_at is not null and v_effective_from is not null
     and v_expires_at<=v_effective_from then
    raise exception 'tier expiration must be after its effective time'
      using errcode='22023';
  end if;

  insert into public.loyalty_tier_versions(
    tier_id,config_version_id,business_id,name,threshold,points_multiplier,
    perk_note,sort,active,effective_from,expires_at
  ) values(
    v_tier_id,p_version,v_header.business_id,btrim(p_tier->>'name'),
    (p_tier->>'threshold')::integer,(p_tier->>'points_multiplier')::numeric,
    nullif(btrim(p_tier->>'perk_note'),''),coalesce((p_tier->>'sort')::integer,0),
    coalesce((p_tier->>'active')::boolean,true),v_effective_from,v_expires_at
  )
  on conflict(tier_id,config_version_id) do update set
    name=excluded.name,
    threshold=excluded.threshold,
    points_multiplier=excluded.points_multiplier,
    perk_note=excluded.perk_note,
    sort=excluded.sort,
    active=excluded.active,
    effective_from=excluded.effective_from,
    expires_at=excluded.expires_at;

  perform app.refresh_loyalty_config_snapshot(p_version);
  select snapshot_hash into v_hash
  from public.firm_config_versions
  where id=p_version;
  return jsonb_build_object(
    'version_id',p_version,'tier_id',v_tier_id,'status','draft',
    'snapshot_hash',v_hash,'effective_from',v_effective_from,'expires_at',v_expires_at
  );
end
$$;

--
-- Name: save_membership_plan(uuid, uuid, text, integer, text, integer, numeric, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_membership_plan(p_business uuid, p_plan uuid, p_name text, p_price_cents integer, p_cadence text, p_credit_cents integer, p_discount_pct numeric, p_active boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_staff uuid;
  v_name text := nullif(btrim(p_name), '');
  v_plan public.membership_plans%rowtype;
begin
  if v_actor is null or not app.can_module_write(p_business, 'memberships') then
    raise exception 'active memberships-module write authorization is required'
      using errcode = '42501';
  end if;
  select s.id into v_staff from public.staff s
   where s.business_id=p_business and s.user_id=v_actor and s.active
   order by case when s.role='owner' then 0 else 1 end,s.created_at limit 1 for update;
  if not found then raise exception 'active staff authorization is required' using errcode='42501'; end if;
  if v_name is null or char_length(v_name)>200 or p_price_cents is null or p_price_cents<0
     or p_cadence not in ('monthly','annual') or p_credit_cents is null or p_credit_cents<0
     or p_discount_pct is null or p_discount_pct<0 or p_discount_pct>100 or p_active is null then
    raise exception 'invalid membership plan' using errcode='22023';
  end if;
  if p_plan is null then
    insert into public.membership_plans
      (business_id,name,price_cents,cadence,credit_cents,discount_pct,active)
    values (p_business,v_name,p_price_cents,p_cadence,p_credit_cents,p_discount_pct,p_active)
    returning * into v_plan;
  else
    perform 1 from public.membership_plans p
     where p.id=p_plan and p.business_id=p_business and p.deleted_at is null for update;
    if not found then raise exception 'membership plan does not belong to this business' using errcode='22023'; end if;
    update public.membership_plans set name=v_name,price_cents=p_price_cents,
      cadence=p_cadence,credit_cents=p_credit_cents,discount_pct=p_discount_pct,active=p_active
     where id=p_plan and business_id=p_business returning * into v_plan;
  end if;
  return jsonb_build_object('status','completed','plan_id',v_plan.id,'name',v_plan.name,
    'price_cents',v_plan.price_cents,'cadence',v_plan.cadence,'credit_cents',v_plan.credit_cents,
    'discount_pct',v_plan.discount_pct,'active',v_plan.active);
end
$$;

--
-- Name: save_module_template(uuid, text, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_module_template(p_business uuid, p_name text, p_modules text[]) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare t public.module_templates;
begin
  if not app.is_salon_owner(p_business) then raise exception 'owner role required'; end if;
  if p_name is null or length(trim(p_name)) < 1 then raise exception 'template name required'; end if;
  insert into public.module_templates (business_id, name, modules)
  values (p_business, trim(p_name), coalesce(p_modules, '{}'))
  on conflict (business_id, name) do update set modules = excluded.modules
  returning * into t;
  return row_to_json(t);
end $$;

--
-- Name: package_plans; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.package_plans (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    business_id uuid NOT NULL,
    name text NOT NULL,
    price_cents integer NOT NULL,
    sessions integer NOT NULL,
    service_id uuid,
    active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    list_unit_cents_snapshot bigint,
    list_value_cents_snapshot bigint,
    version_no integer DEFAULT 1 NOT NULL,
    supersedes_plan_id uuid,
    CONSTRAINT package_plans_list_unit_snapshot_check CHECK (((list_unit_cents_snapshot IS NULL) OR (list_unit_cents_snapshot >= 0))),
    CONSTRAINT package_plans_list_value_snapshot_check CHECK (((list_value_cents_snapshot IS NULL) OR (list_value_cents_snapshot >= 0))),
    CONSTRAINT package_plans_price_cents_check CHECK ((price_cents >= 0)),
    CONSTRAINT package_plans_sessions_check CHECK ((sessions > 0))
);

--
-- Name: save_package_plan_v102(uuid, uuid, text, integer, integer, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_package_plan_v102(p_business uuid, p_plan uuid, p_name text, p_price_cents integer, p_sessions integer, p_service uuid, p_active boolean) RETURNS public.package_plans
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_service public.services%rowtype;
  v_plan public.package_plans%rowtype;
  v_previous public.package_plans%rowtype;
begin
  if not (
    app.is_super_admin()
    or app.can_module_write(p_business,'packages')
  ) then
    raise exception 'packages_write_required' using errcode='42501';
  end if;
  if p_name is null or length(btrim(p_name)) not between 2 and 120 then
    raise exception 'package_name_invalid' using errcode='22023';
  end if;
  if p_price_cents is null or p_price_cents < 0 then
    raise exception 'package_price_invalid' using errcode='22023';
  end if;
  if p_sessions is null or p_sessions < 1 or p_sessions > 1000 then
    raise exception 'package_sessions_invalid' using errcode='22023';
  end if;
  if p_active is null then
    raise exception 'package_active_required' using errcode='22023';
  end if;
  if p_service is not null then
    select * into v_service
    from public.services service
    where service.id=p_service and service.business_id=p_business;
    if not found then
      raise exception 'package_service_not_found' using errcode='22023';
    end if;
  end if;
  if p_plan is null then
    insert into public.package_plans(
      business_id,name,price_cents,sessions,service_id,active,
      list_unit_cents_snapshot,list_value_cents_snapshot,
      version_no,supersedes_plan_id
    ) values(
      p_business,btrim(p_name),p_price_cents,p_sessions,p_service,p_active,
      case when p_service is null then null else v_service.price_cents::bigint end,
      case when p_service is null then null
        else v_service.price_cents::bigint*p_sessions::bigint end,
      1,null
    ) returning * into v_plan;
  else
    select * into v_previous
    from public.package_plans plan
    where plan.id=p_plan and plan.business_id=p_business
    for update;
    if not found then
      raise exception 'package_plan_not_found' using errcode='22023';
    end if;
    if exists(
      select 1 from public.package_plans child
      where child.business_id=p_business
        and child.supersedes_plan_id=v_previous.id
    ) then
      raise exception 'package_plan_version_superseded' using errcode='40001';
    end if;

    -- Clone-on-edit: existing purchases keep their original plan FK and the
    -- snapshots taken at checkout. Only the new version becomes sellable.
    insert into public.package_plans(
      business_id,name,price_cents,sessions,service_id,active,
      list_unit_cents_snapshot,list_value_cents_snapshot,
      version_no,supersedes_plan_id
    ) values(
      p_business,btrim(p_name),p_price_cents,p_sessions,p_service,p_active,
      case when p_service is null then null else v_service.price_cents::bigint end,
      case when p_service is null then null
        else v_service.price_cents::bigint*p_sessions::bigint end,
      v_previous.version_no+1,v_previous.id
    ) returning * into v_plan;

    update public.package_plans
    set active=false
    where id=v_previous.id and business_id=p_business;
  end if;
  insert into public.audit_log(
    business_id,actor,action,entity,entity_id,detail
  ) values(
    p_business,auth.uid(),'PACKAGE_PLAN_SAVED_V102','package_plans',v_plan.id,
    jsonb_build_object(
      'service_id',v_plan.service_id,
      'version_no',v_plan.version_no,
      'supersedes_plan_id',v_plan.supersedes_plan_id,
      'sessions',v_plan.sessions,
      'price_cents',v_plan.price_cents,
      'list_value_cents_snapshot',v_plan.list_value_cents_snapshot,
      'active',v_plan.active
    )
  );
  return v_plan;
end
$$;

--
-- Name: save_program_rule_draft(uuid, uuid, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_program_rule_draft(p_config_version uuid, p_rule_id uuid, p_rule jsonb, p_expected_snapshot_hash text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_business uuid;
begin
  select version.business_id into v_business
    from public.firm_config_versions version
   where version.id = p_config_version;
  if v_business is null or not app.is_salon_owner(v_business) then
    raise exception 'owner only' using errcode = '42501';
  end if;
  raise exception 'advanced rule authoring is unavailable for launch'
    using errcode = '55000';
end;
$$;

--
-- Name: save_referral_program(uuid, boolean, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_referral_program(p_business uuid, p_enabled boolean, p_reward_cents integer, p_min_spend_cents integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_staff uuid;
  v_program public.referral_programs%rowtype;
begin
  if v_actor is null or not app.can_module_write(p_business, 'referrals') then
    raise exception 'active referrals-module write authorization is required'
      using errcode = '42501';
  end if;
  select s.id into v_staff from public.staff s
   where s.business_id = p_business and s.user_id = v_actor and s.active
   order by case when s.role = 'owner' then 0 else 1 end, s.created_at limit 1 for update;
  if not found then raise exception 'active staff authorization is required' using errcode='42501'; end if;
  if p_enabled is null or p_reward_cents is null or p_reward_cents < 0
     or p_min_spend_cents is null or p_min_spend_cents < 0 then
    raise exception 'invalid referral program' using errcode='22023';
  end if;
  insert into public.referral_programs (business_id, enabled, reward_cents, min_spend_cents)
  values (p_business, p_enabled, p_reward_cents, p_min_spend_cents)
  on conflict (business_id) do update set
    enabled = excluded.enabled,
    reward_cents = excluded.reward_cents,
    min_spend_cents = excluded.min_spend_cents
  returning * into v_program;
  return jsonb_build_object('status','completed','program_id',v_program.id,
    'enabled',v_program.enabled,'reward_cents',v_program.reward_cents,
    'min_spend_cents',v_program.min_spend_cents);
end
$$;

