--
-- Name: save_referral_program_v420(uuid, boolean, text, integer, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_referral_program_v420(p_business uuid, p_enabled boolean, p_reward_kind text, p_reward_points integer, p_reward_label text, p_min_spend_cents integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_staff uuid;
  v_kind text := lower(btrim(coalesce(p_reward_kind,'points')));
  v_label text := nullif(btrim(coalesce(p_reward_label,'')),'');
  v_program public.referral_programs%rowtype;
begin
  if v_actor is null or not app.can_module_write(p_business, 'referrals') then
    raise exception 'active referrals-module write authorization is required' using errcode='42501';
  end if;
  select s.id into v_staff from public.staff s
   where s.business_id = p_business and s.user_id = v_actor and s.active
   order by case when s.role = 'owner' then 0 else 1 end, s.created_at limit 1 for update;
  if not found then raise exception 'active staff authorization is required' using errcode='42501'; end if;
  if v_kind not in ('points','voucher') then
    raise exception 'a referral pays either points or a free gift' using errcode='22023';
  end if;
  if p_enabled is null or p_min_spend_cents is null or p_min_spend_cents < 0 then
    raise exception 'invalid referral program' using errcode='22023';
  end if;
  -- Each kind validates only what IT needs. A firm switching to a gift should not have to invent
  -- a points figure it will never pay, and one switching back should not lose the points it had.
  if v_kind='points' and (p_reward_points is null or p_reward_points < 1) then
    raise exception 'a points referral must award at least one point' using errcode='22023';
  end if;
  if v_kind='voucher' and v_label is null then
    raise exception 'name the gift the referrer receives' using errcode='22023';
  end if;

  insert into public.referral_programs (business_id, enabled, reward_kind, reward_points, reward_label, min_spend_cents)
  values (p_business, p_enabled, v_kind, coalesce(p_reward_points,0), v_label, p_min_spend_cents)
  on conflict (business_id) do update set
    enabled = excluded.enabled,
    reward_kind = excluded.reward_kind,
    reward_points = case when excluded.reward_kind='points' then excluded.reward_points
                         else public.referral_programs.reward_points end,
    reward_label = case when excluded.reward_kind='voucher' then excluded.reward_label
                        else public.referral_programs.reward_label end,
    min_spend_cents = excluded.min_spend_cents
  returning * into v_program;

  insert into public.audit_log(business_id, actor, action, entity, entity_id, detail)
  values (p_business, v_actor, 'referral_program.saved', 'referral_programs', v_program.id,
    jsonb_build_object('enabled',v_program.enabled,'reward_kind',v_program.reward_kind,
                       'reward_points',v_program.reward_points,'reward_label',v_program.reward_label,
                       'min_spend_cents',v_program.min_spend_cents));

  return jsonb_build_object('status','completed','program_id',v_program.id,
    'enabled',v_program.enabled,'reward_kind',v_program.reward_kind,
    'reward_points',v_program.reward_points,'reward_label',v_program.reward_label,
    'min_spend_cents',v_program.min_spend_cents);
end $$;

--
-- Name: save_referral_program_v421(uuid, boolean, text, integer, text, integer, boolean, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_referral_program_v421(p_business uuid, p_enabled boolean, p_reward_kind text, p_reward_points integer, p_reward_label text, p_min_spend_cents integer, p_friend_enabled boolean, p_friend_reward_points integer, p_friend_reward_label text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_staff uuid;
  v_kind text := lower(btrim(coalesce(p_reward_kind,'points')));
  v_label text := nullif(btrim(coalesce(p_reward_label,'')),'');
  v_friend_on boolean := coalesce(p_friend_enabled,true);
  v_friend_label text := nullif(btrim(coalesce(p_friend_reward_label,'')),'');
  v_program public.referral_programs%rowtype;
begin
  if v_actor is null or not app.can_module_write(p_business, 'referrals') then
    raise exception 'active referrals-module write authorization is required' using errcode='42501';
  end if;
  select s.id into v_staff from public.staff s
   where s.business_id = p_business and s.user_id = v_actor and s.active
   order by case when s.role = 'owner' then 0 else 1 end, s.created_at limit 1 for update;
  if not found then raise exception 'active staff authorization is required' using errcode='42501'; end if;
  if v_kind not in ('points','voucher') then
    raise exception 'a referral pays either points or a free gift' using errcode='22023';
  end if;
  if p_enabled is null or p_min_spend_cents is null or p_min_spend_cents < 0 then
    raise exception 'invalid referral program' using errcode='22023';
  end if;
  -- Each kind validates only what IT needs. A firm switching to a gift should not have to invent
  -- a points figure it will never pay, and one switching back should not lose the points it had.
  if v_kind='points' and (p_reward_points is null or p_reward_points < 1) then
    raise exception 'a points referral must award at least one point' using errcode='22023';
  end if;
  if v_kind='voucher' and v_label is null then
    raise exception 'name the gift the referrer receives' using errcode='22023';
  end if;
  -- The friend's side is only validated when it is switched ON, and NULL always means "the same as
  -- the referrer" rather than "nothing" - so a firm that never touches these fields gets the
  -- two-sided referral the owner asked for without filling anything in.
  if v_friend_on and p_friend_reward_points is not null and p_friend_reward_points < 0 then
    raise exception 'the friend''s points cannot be negative' using errcode='22023';
  end if;

  insert into public.referral_programs (business_id, enabled, reward_kind, reward_points, reward_label, min_spend_cents,
                                        friend_enabled, friend_reward_points, friend_reward_label)
  values (p_business, p_enabled, v_kind, coalesce(p_reward_points,0), v_label, p_min_spend_cents,
          v_friend_on, p_friend_reward_points, v_friend_label)
  on conflict (business_id) do update set
    enabled = excluded.enabled,
    reward_kind = excluded.reward_kind,
    reward_points = case when excluded.reward_kind='points' then excluded.reward_points
                         else public.referral_programs.reward_points end,
    reward_label = case when excluded.reward_kind='voucher' then excluded.reward_label
                        else public.referral_programs.reward_label end,
    min_spend_cents = excluded.min_spend_cents,
    friend_enabled = excluded.friend_enabled,
    friend_reward_points = case when excluded.reward_kind='points' then excluded.friend_reward_points
                                else public.referral_programs.friend_reward_points end,
    friend_reward_label = case when excluded.reward_kind='voucher' then excluded.friend_reward_label
                               else public.referral_programs.friend_reward_label end
  returning * into v_program;

  insert into public.audit_log(business_id, actor, action, entity, entity_id, detail)
  values (p_business, v_actor, 'referral_program.saved', 'referral_programs', v_program.id,
    jsonb_build_object('enabled',v_program.enabled,'reward_kind',v_program.reward_kind,
                       'reward_points',v_program.reward_points,'reward_label',v_program.reward_label,
                       'min_spend_cents',v_program.min_spend_cents,
                       'friend_enabled',v_program.friend_enabled,
                       'friend_reward_points',v_program.friend_reward_points,
                       'friend_reward_label',v_program.friend_reward_label));

  return jsonb_build_object('status','completed','program_id',v_program.id,
    'enabled',v_program.enabled,'reward_kind',v_program.reward_kind,
    'reward_points',v_program.reward_points,'reward_label',v_program.reward_label,
    'min_spend_cents',v_program.min_spend_cents,
    'friend_enabled',v_program.friend_enabled,
    'friend_reward_points',v_program.friend_reward_points,
    'friend_reward_label',v_program.friend_reward_label);
end $$;

--
-- Name: save_retention_program_draft(uuid, uuid, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_retention_program_draft(p_config_version uuid, p_program_id uuid, p_program jsonb, p_expected_snapshot_hash text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_header public.firm_config_versions%rowtype; v_existing public.retention_program_versions%rowtype;
  v_tax public.firm_reward_taxonomy%rowtype; v_program_id uuid:=p_program_id;
  v_id uuid; v_hash text; v_name text; v_active boolean; v_goal integer; v_period integer;
  v_starts date; v_tax_id uuid; v_discount numeric; v_credit integer; v_item text;
  v_sort integer; v_customer text; v_staff text;
begin
  if p_program_id is null then
    raise exception 'a stable program id is required for retry-safe creation' using errcode='22023';
  end if;
  if p_program is null or jsonb_typeof(p_program)<>'object' then
    raise exception 'retention program must be a JSON object' using errcode='22023';
  end if;
  if exists(select 1 from jsonb_object_keys(p_program) k where k not in(
    'name','active','goal_visits','period_days','starts_on','reward_taxonomy_id',
    'discount_percent','credit_cents','manual_item','sort','customer_description','staff_description'
  )) then raise exception 'retention program contains unsupported fields' using errcode='22023'; end if;
  select * into v_header from public.firm_config_versions where id=p_config_version for update;
  if not found or not app.is_salon_owner(v_header.business_id) then raise exception 'owner only' using errcode='42501'; end if;
  if v_header.status<>'draft' then raise exception 'only a draft retention program may be edited' using errcode='42501'; end if;
  perform 1 from public.businesses where id=v_header.business_id for share;
  if p_expected_snapshot_hash is null then
    raise exception 'expected snapshot hash is required' using errcode='22023';
  end if;
  select * into v_existing from public.retention_program_versions
   where program_id=v_program_id and config_version_id=p_config_version and business_id=v_header.business_id;
  if v_existing.id is null and exists(select 1 from public.retention_programs where id=p_program_id) then
    if exists(select 1 from public.retention_programs where id=p_program_id and business_id<>v_header.business_id) then
      raise exception 'retention program does not belong to this business' using errcode='42501';
    end if;
    raise exception 'retention program is not part of this draft' using errcode='22023';
  end if;
  if v_existing.id is not null and exists(
    select 1 from public.retention_programs prog
     where prog.id=v_program_id and prog.business_id=v_header.business_id and prog.deleted_at is not null
  ) then
    raise exception 'retention program does not belong to this business, or is already deleted' using errcode='22023';
  end if;
  v_name:=coalesce(nullif(btrim(p_program->>'name'),''),v_existing.name);
  v_active:=case when p_program?'active' then (p_program->>'active')::boolean else coalesce(v_existing.active,true) end;
  v_goal:=case when p_program?'goal_visits' then (p_program->>'goal_visits')::integer else v_existing.goal_visits end;
  v_period:=case when p_program?'period_days' then (p_program->>'period_days')::integer else v_existing.period_days end;
  v_starts:=case when p_program?'starts_on' then (p_program->>'starts_on')::date else coalesce(v_existing.starts_on,(timezone('Asia/Singapore', now()))::date) end;
  v_tax_id:=case when p_program?'reward_taxonomy_id' then (p_program->>'reward_taxonomy_id')::uuid else v_existing.reward_taxonomy_id end;
  v_discount:=case when p_program?'discount_percent' then nullif(p_program->>'discount_percent','')::numeric else v_existing.discount_percent end;
  v_credit:=case when p_program?'credit_cents' then nullif(p_program->>'credit_cents','')::integer else v_existing.credit_cents end;
  v_item:=case when p_program?'manual_item' then nullif(btrim(p_program->>'manual_item'),'') else v_existing.manual_item end;
  v_sort:=case when p_program?'sort' then (p_program->>'sort')::integer else coalesce(v_existing.sort,0) end;
  v_customer:=case when p_program?'customer_description' then nullif(btrim(p_program->>'customer_description'),'') else v_existing.customer_description end;
  v_staff:=case when p_program?'staff_description' then nullif(btrim(p_program->>'staff_description'),'') else v_existing.staff_description end;
  if v_name is null or v_goal is null or v_goal<=0 or v_period is null or v_period<=0 or v_tax_id is null then
    raise exception 'name, positive goal/period, and reward taxonomy are required' using errcode='22023';
  end if;
  select * into v_tax from public.firm_reward_taxonomy where id=v_tax_id and business_id=v_header.business_id and active;
  if not found then raise exception 'reward taxonomy is missing, retired, or belongs to another business' using errcode='22023'; end if;
  if (v_tax.fulfillment_kind='discount_pct' and not(coalesce(v_discount,0)>0 and v_discount<=100))
     or (v_tax.fulfillment_kind='credit' and coalesce(v_credit,0)<=0)
     or (v_tax.fulfillment_kind='free_item' and char_length(coalesce(v_item,''))<2) then
    raise exception 'retention reward parameters do not match the immutable fulfillment kind' using errcode='22023';
  end if;
  if v_tax.fulfillment_kind<>'discount_pct' then v_discount:=null; end if;
  if v_tax.fulfillment_kind<>'credit' then v_credit:=null; end if;
  if v_tax.fulfillment_kind<>'free_item' then v_item:=null; end if;
  if v_header.snapshot_hash is distinct from p_expected_snapshot_hash then
    if v_existing.id is not null
       and (v_existing.name,v_existing.active,v_existing.goal_visits,v_existing.period_days,
            v_existing.starts_on,v_existing.reward_taxonomy_id,v_existing.discount_percent,
            v_existing.credit_cents,v_existing.manual_item,v_existing.sort,
            v_existing.customer_description,v_existing.staff_description)
           is not distinct from
           (v_name,v_active,v_goal,v_period,v_starts,v_tax.id,v_discount,v_credit,v_item,
            v_sort,v_customer,v_staff) then
      return jsonb_build_object('program_id',v_program_id,
        'retention_program_version_id',v_existing.id,'config_version_id',p_config_version,
        'status','draft','snapshot_hash',v_header.snapshot_hash,'replayed',true);
    end if;
    raise exception 'draft configuration changed; reload before saving' using errcode='40001';
  end if;
  if v_existing.id is null then
    insert into public.retention_programs(
      id,business_id,name,goal_visits,period_days,reward_taxonomy_id,reward_type,
      reward_value,reward_item,starts_on,active,current_config_version_id
    ) values(v_program_id,v_header.business_id,v_name,v_goal,v_period,v_tax.id,v_tax.fulfillment_kind,
      coalesce(v_discount,v_credit,0),v_item,v_starts,false,null);
  end if;
  insert into public.retention_program_versions(
    program_id,config_version_id,business_id,name,active,goal_visits,period_days,
    starts_on,reward_taxonomy_id,fulfillment_kind,
    discount_percent,credit_cents,manual_item,sort,customer_description,staff_description
  ) values(v_program_id,p_config_version,v_header.business_id,v_name,v_active,v_goal,v_period,
    v_starts,v_tax.id,v_tax.fulfillment_kind,v_discount,v_credit,v_item,v_sort,v_customer,v_staff)
  on conflict(program_id,config_version_id) do update set
    name=excluded.name,active=excluded.active,goal_visits=excluded.goal_visits,
    period_days=excluded.period_days,starts_on=excluded.starts_on,
    reward_taxonomy_id=excluded.reward_taxonomy_id,
    fulfillment_kind=excluded.fulfillment_kind,discount_percent=excluded.discount_percent,
    credit_cents=excluded.credit_cents,manual_item=excluded.manual_item,sort=excluded.sort,
    customer_description=excluded.customer_description,staff_description=excluded.staff_description
  returning id into v_id;
  perform app.refresh_loyalty_config_snapshot(p_config_version);
  select snapshot_hash into v_hash from public.firm_config_versions where id=p_config_version;
  return jsonb_build_object('program_id',v_program_id,'retention_program_version_id',v_id,
    'config_version_id',p_config_version,'status','draft','snapshot_hash',v_hash,'replayed',false);
end $$;

--
-- Name: save_reward_taxonomy(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_reward_taxonomy(p_business uuid, p_taxonomy_id uuid, p_taxonomy jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_row public.firm_reward_taxonomy%rowtype; v_id uuid:=coalesce(p_taxonomy_id,gen_random_uuid());
  v_label text; v_kind text; v_active boolean; v_sort integer;
begin
  if not app.is_salon_owner(p_business) then raise exception 'owner only' using errcode='42501'; end if;
  perform 1 from public.businesses where id=p_business for update;
  if p_taxonomy is null or jsonb_typeof(p_taxonomy)<>'object' then raise exception 'taxonomy must be a JSON object' using errcode='22023'; end if;
  if exists(select 1 from jsonb_object_keys(p_taxonomy) k where k not in('label','fulfillment_kind','active','sort')) then
    raise exception 'taxonomy contains unsupported fields' using errcode='22023';
  end if;
  if p_taxonomy_id is not null then
    select * into v_row from public.firm_reward_taxonomy where id=p_taxonomy_id and business_id=p_business for update;
    if not found then raise exception 'taxonomy does not belong to this business' using errcode='42501'; end if;
  end if;
  v_label:=coalesce(nullif(btrim(p_taxonomy->>'label'),''),v_row.label);
  v_kind:=coalesce(nullif(p_taxonomy->>'fulfillment_kind',''),v_row.fulfillment_kind);
  v_active:=case when p_taxonomy?'active' then (p_taxonomy->>'active')::boolean else coalesce(v_row.active,true) end;
  v_sort:=case when p_taxonomy?'sort' then (p_taxonomy->>'sort')::integer else coalesce(v_row.sort,0) end;
  if v_label is null or char_length(v_label) not between 2 and 80
     or v_kind not in('discount_pct','free_item','credit') or v_sort not between 0 and 10000 then
    raise exception 'invalid taxonomy values' using errcode='22023';
  end if;
  if p_taxonomy_id is not null and v_kind is distinct from v_row.fulfillment_kind then
    raise exception 'reward fulfillment behavior is immutable; create a new reward type' using errcode='23001';
  end if;
  if p_taxonomy_id is not null and not v_active and exists(
    select 1
      from public.retention_program_versions rv
      join public.businesses b
        on b.id=rv.business_id and b.active_config_version_id=rv.config_version_id
      join public.retention_programs prog
        on prog.id=rv.program_id and prog.business_id=rv.business_id
       and prog.deleted_at is null
     where rv.business_id=p_business
       and rv.reward_taxonomy_id=p_taxonomy_id
       and rv.active
  ) then
    raise exception 'publish a replacement or disable the live retention program before retiring this taxonomy'
      using errcode='23514';
  end if;
  insert into public.firm_reward_taxonomy(id,business_id,label,fulfillment_kind,active,sort,created_by)
  values(v_id,p_business,v_label,v_kind,v_active,v_sort,auth.uid())
  on conflict(id) do update set label=excluded.label,active=excluded.active,sort=excluded.sort;
  return jsonb_build_object('id',v_id,'label',v_label,'fulfillment_kind',v_kind,'active',v_active,'sort',v_sort);
end $$;

--
-- Name: seal_campaign_measurement_v99(uuid, uuid, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.seal_campaign_measurement_v99(p_business uuid, p_campaign uuid, p_idempotency_key text, p_minimum_sample_per_arm integer DEFAULT 30) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid:=auth.uid();
  v_campaign public.retention_campaigns%rowtype;
  v_existing public.retention_campaign_measurement_windows_v99%rowtype;
  v_key text:=btrim(coalesce(p_idempotency_key,''));
  v_hash text;
  v_treatment integer;
  v_holdout integer;
  v_exposures integer;
  v_last_exposure timestamptz;
  v_id uuid:=gen_random_uuid();
  v_started timestamptz;
  v_ends timestamptz;
begin
  if v_actor is null
     or not app.is_salon_owner(p_business)
     or not app.can_module_write(p_business,'retention') then
    raise exception 'active owner retention write authorization is required'
      using errcode='42501';
  end if;
  if char_length(v_key) not between 8 and 200 then
    raise exception 'idempotency key must contain 8..200 characters'
      using errcode='22023';
  end if;
  if p_minimum_sample_per_arm not between 10 and 10000 then
    raise exception 'minimum sample per arm must be 10..10000'
      using errcode='22023';
  end if;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('v99:seal:'||p_campaign::text,0)
  );
  select campaign.* into v_campaign
  from public.retention_campaigns campaign
  where campaign.id=p_campaign and campaign.business_id=p_business
  for update;
  if not found then
    raise exception 'campaign not found in this business'
      using errcode='22023';
  end if;
  if v_campaign.status<>'active' then
    raise exception 'only an active campaign can seal measurement'
      using errcode='object_not_in_prerequisite_state';
  end if;

  v_hash:=pg_catalog.encode(
    extensions.digest(
      pg_catalog.convert_to(
        pg_catalog.concat_ws(
          '|','v99.measurement-seal',p_business::text,p_campaign::text,
          p_minimum_sample_per_arm::text
        ),
        'UTF8'
      ),
      'sha256'
    ),
    'hex'
  );
  select measurement.* into v_existing
  from public.retention_campaign_measurement_windows_v99 measurement
  where measurement.campaign_id=p_campaign;
  if found then
    if v_existing.request_hash<>v_hash then
      raise exception 'campaign measurement was sealed with different terms'
        using errcode='23505';
    end if;
    return pg_catalog.jsonb_build_object(
      'measurement_window_id',v_existing.id,
      'campaign_id',p_campaign,
      'measurement_started_at',v_existing.measurement_started_at,
      'measurement_ends_at',v_existing.measurement_ends_at,
      'minimum_sample_per_arm',v_existing.minimum_sample_per_arm,
      'replayed',true
    );
  end if;
  if exists(
    select 1
    from public.retention_campaign_measurement_windows_v99 measurement
    where measurement.business_id=p_business
      and measurement.idempotency_key=v_key
  ) then
    raise exception 'idempotency key conflicts with another measurement seal'
      using errcode='23505';
  end if;

  select
    count(*) filter (where member.assignment='treatment'),
    count(*) filter (where member.assignment='holdout')
  into v_treatment,v_holdout
  from public.retention_campaign_members member
  where member.campaign_id=p_campaign
    and member.business_id=p_business;
  select count(*),max(exposure.exposed_at)
  into v_exposures,v_last_exposure
  from public.retention_campaign_exposures_v99 exposure
  where exposure.campaign_id=p_campaign
    and exposure.business_id=p_business;
  if coalesce(v_treatment,0)=0 or coalesce(v_holdout,0)=0 then
    raise exception 'causal comparison requires non-empty treatment and holdout arms'
      using errcode='check_violation';
  end if;
  if v_exposures<>v_treatment then
    raise exception
      'measurement cannot seal until every treatment member has verified exposure (%/% verified)',
      v_exposures,v_treatment
      using errcode='object_not_in_prerequisite_state';
  end if;
  if exists(
    select 1
    from public.retention_campaign_members member
    left join public.retention_campaign_grants grant_row
      on grant_row.campaign_id=member.campaign_id
     and grant_row.client_id=member.client_id
    left join public.retention_campaign_exposures_v99 exposure
      on exposure.campaign_grant_id=grant_row.id
    left join public.reward_grants reward
      on reward.id=grant_row.reward_grant_id
     and reward.business_id=grant_row.business_id
     and reward.client_id=member.client_id
     and reward.campaign_id=member.campaign_id
     and reward.campaign_assignment='treatment'
    where member.campaign_id=p_campaign
      and member.business_id=p_business
      and member.assignment='treatment'
      and (
        grant_row.reward_grant_id is null
        or reward.id is null
        or reward.status not in ('granted','redeemed')
        or exposure.id is null
        or exposure.reward_grant_id<>grant_row.reward_grant_id
      )
  ) then
    raise exception 'treatment entitlement or exposure evidence is incomplete'
      using errcode='object_not_in_prerequisite_state';
  end if;

  v_started:=greatest(v_campaign.activated_at,v_last_exposure);
  v_ends:=v_started
    + pg_catalog.make_interval(days=>v_campaign.attribution_window_days);
  insert into public.retention_campaign_measurement_windows_v99(
    id,business_id,campaign_id,exposure_cutoff_at,
    measurement_started_at,measurement_ends_at,treatment_members,
    holdout_members,verified_treatment_exposures,
    minimum_sample_per_arm,sealed_by,idempotency_key,request_hash
  ) values(
    v_id,p_business,p_campaign,v_last_exposure,v_started,v_ends,
    v_treatment,v_holdout,v_exposures,p_minimum_sample_per_arm,
    v_actor,v_key,v_hash
  );
  insert into public.audit_log(
    business_id,actor,action,entity,entity_id,detail
  ) values(
    p_business,v_actor,'CAMPAIGN_MEASUREMENT_SEALED_V99',
    'retention_campaign_measurement_windows_v99',v_id,
    pg_catalog.jsonb_build_object(
      'campaign_id',p_campaign,'treatment_members',v_treatment,
      'holdout_members',v_holdout,'verified_exposures',v_exposures,
      'minimum_sample_per_arm',p_minimum_sample_per_arm,
      'measurement_started_at',v_started,'measurement_ends_at',v_ends
    )
  );
  return pg_catalog.jsonb_build_object(
    'measurement_window_id',v_id,'campaign_id',p_campaign,
    'measurement_started_at',v_started,'measurement_ends_at',v_ends,
    'minimum_sample_per_arm',p_minimum_sample_per_arm,'replayed',false
  );
end
$$;

--
-- Name: sell_package(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sell_package(p_business uuid, p_client uuid, p_plan uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare plan record; cp client_packages;
begin
  if not app.is_salon_member(p_business) then raise exception 'not a member of this business'; end if;
  select * into plan from package_plans where id = p_plan and business_id = p_business and active;
  if not found then raise exception 'package plan not found or inactive'; end if;
  insert into client_packages (business_id, client_id, plan_id, remaining)
  values (p_business, p_client, p_plan, plan.sessions)
  returning * into cp;
  insert into sales (business_id, client_id, kind, amount_cents, note)
  values (p_business, p_client, 'package', plan.price_cents, 'package sold: ' || plan.name);
  return row_to_json(cp);
end $$;

--
-- Name: sell_package(uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sell_package(p_business uuid, p_client uuid, p_plan uuid, p_idempotency_key uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_payload jsonb;
  v_hash text;
  v_existing public.sale_intent_operations%rowtype;
  v_result json;
begin
  if v_actor is null then
    raise exception 'authenticated staff required' using errcode = '42501';
  end if;
  if p_idempotency_key is null then
    raise exception 'a package-sale idempotency key is required' using errcode = '22023';
  end if;
  if p_client is null or not exists (
    select 1 from public.clients c where c.id = p_client and c.business_id = p_business
  ) then
    raise exception 'package-sale client does not belong to this business' using errcode = '22023';
  end if;

  v_payload := jsonb_build_object('business_id', p_business, 'client_id', p_client, 'plan_id', p_plan);
  v_hash := app.v41_request_hash(v_payload::text);
  perform pg_advisory_xact_lock(hashtextextended(
    'v51a:package:' || p_business::text || ':' || p_idempotency_key::text, 0));

  select * into v_existing
    from public.sale_intent_operations o
   where o.business_id = p_business and o.idempotency_key = p_idempotency_key
   for update;
  if found then
    if v_existing.actor is distinct from v_actor
       or v_existing.operation_type <> 'package_sale'
       or v_existing.request_hash <> v_hash then
      raise exception 'idempotency key conflicts with another package sale' using errcode = '23505';
    end if;
    return v_existing.result::json;
  end if;

  -- Delegate the actual sale to the existing v10 implementation (its own auth + work).
  v_result := public.sell_package(p_business, p_client, p_plan);

  insert into public.sale_intent_operations(
    business_id, actor, operation_type, idempotency_key, request_hash, status, client_id, result)
  values (
    p_business, v_actor, 'package_sale', p_idempotency_key, v_hash, 'completed', p_client, v_result::jsonb);
  return v_result;
end $$;

--
-- Name: sell_package_v102(uuid, uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sell_package_v102(p_business uuid, p_client uuid, p_plan uuid, p_branch uuid, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_staff uuid;
  v_plan public.package_plans%rowtype;
  v_service public.services%rowtype;
  v_existing public.sale_intent_operations%rowtype;
  v_client_package_id uuid := gen_random_uuid();
  v_sale_id uuid := gen_random_uuid();
  v_payload jsonb;
  v_hash text;
  v_points_earned bigint;
  v_points_total bigint;
  v_result jsonb;
begin
  if v_actor is null or p_idempotency_key is null then
    raise exception 'authenticated staff and idempotency key required'
      using errcode='42501';
  end if;
  if not app.has_perm(p_business,'create_sales')
     or not (
       app.can_module_write(p_business,'till')
       or app.can_module_write(p_business,'sales')
       or app.can_module_write(p_business,'packages')
     ) then
    raise exception 'package checkout authorization required' using errcode='42501';
  end if;
  select staff_row.id into v_staff
  from public.staff staff_row
  where staff_row.business_id=p_business
    and staff_row.user_id=v_actor
    and staff_row.active
    and 'create_sales'=any(app.role_perms(staff_row.role))
  order by case staff_row.role when 'owner' then 0 when 'manager' then 1 else 2 end,
           staff_row.created_at,staff_row.id
  limit 1
  for update;
  if not found then
    raise exception 'active staff authorization required' using errcode='42501';
  end if;
  if p_client is null or not exists(
    select 1 from public.clients client
    where client.id=p_client and client.business_id=p_business
  ) then
    raise exception 'package_sale_client_invalid' using errcode='22023';
  end if;

  v_payload:=jsonb_build_object(
    'branch_id',p_branch,
    'business_id',p_business,
    'client_id',p_client,
    'plan_id',p_plan
  );
  v_hash:=app.v41_request_hash(v_payload::text);
  perform pg_advisory_xact_lock(hashtextextended(
    'v102:package-sale:'||p_business::text||':'||p_idempotency_key::text,0
  ));

  select * into v_existing
  from public.sale_intent_operations operation
  where operation.business_id=p_business
    and operation.idempotency_key=p_idempotency_key
  for update;
  if found then
    if v_existing.actor is distinct from v_actor
       or v_existing.operation_type<>'package_sale'
       or v_existing.request_hash<>v_hash then
      raise exception 'package sale idempotency key conflict' using errcode='23505';
    end if;
    return v_existing.result;
  end if;

  select * into v_plan
  from public.package_plans plan
  where plan.id=p_plan and plan.business_id=p_business and plan.active
  for share;
  if not found then
    raise exception 'package_plan_not_found_or_inactive' using errcode='22023';
  end if;
  if v_plan.service_id is not null then
    select * into v_service
    from public.services service
    where service.id=v_plan.service_id and service.business_id=p_business;
    if not found then
      raise exception 'package_service_not_found' using errcode='22023';
    end if;
  end if;
  perform 1
  from public.branches branch
  where branch.id=p_branch and branch.business_id=p_business and branch.active
    and app.can_see_branch(p_business,branch.id)
    and (
      v_plan.service_id is null
      or not exists(
        select 1 from public.service_branches any_branch
        where any_branch.business_id=p_business
          and any_branch.service_id=v_plan.service_id
      )
      or exists(
        select 1 from public.service_branches allowed
        where allowed.business_id=p_business
          and allowed.service_id=v_plan.service_id
          and allowed.branch_id=branch.id
      )
    )
  for share;
  if not found then
    raise exception 'package_branch_not_permitted' using errcode='42501';
  end if;

  insert into public.client_packages(
    id,business_id,client_id,plan_id,remaining,
    plan_name_snapshot,plan_version_snapshot,sessions_snapshot,
    price_cents_snapshot,service_id_snapshot,service_name_snapshot,
    service_variant_snapshot,service_duration_min_snapshot,
    list_unit_cents_snapshot,list_value_cents_snapshot
  ) values(
    v_client_package_id,p_business,p_client,v_plan.id,v_plan.sessions,
    v_plan.name,v_plan.version_no,v_plan.sessions,v_plan.price_cents::bigint,
    v_plan.service_id,case when v_plan.service_id is null then null else v_service.name end,
    case when v_plan.service_id is null then null else v_service.variant_label end,
    case when v_plan.service_id is null then null else v_service.duration_min end,
    v_plan.list_unit_cents_snapshot,v_plan.list_value_cents_snapshot
  );
  insert into public.sales(
    id,business_id,client_id,kind,amount_cents,note,branch_id,staff_id
  ) values(
    v_sale_id,p_business,p_client,'package',v_plan.price_cents,
    'package sold: '||v_plan.name,p_branch,v_staff
  );

  select coalesce(sum(ledger.points),0)::bigint into v_points_earned
  from public.points_ledger ledger
  where ledger.business_id=p_business
    and ledger.client_id=p_client
    and ledger.sale_id=v_sale_id;
  v_points_total := app.client_points_balance_v409(p_business, p_client)::bigint;

  v_result:=jsonb_build_object(
    'status','completed',
    'replayed',false,
    'client_package_id',v_client_package_id,
    'sale_id',v_sale_id,
    'plan_id',v_plan.id,
    'plan_version',v_plan.version_no,
    'branch_id',p_branch,
    'price_cents',v_plan.price_cents::bigint,
    'sessions',v_plan.sessions,
    'remaining',v_plan.sessions,
    'points_earned',v_points_earned,
    'points_total',v_points_total
  );
  insert into public.sale_intent_operations(
    business_id,actor,operation_type,idempotency_key,request_hash,
    status,client_id,result
  ) values(
    p_business,v_actor,'package_sale',p_idempotency_key,v_hash,
    'completed',p_client,v_result
  );
  return v_result;
end
$$;

--
-- Name: service_claim_growth_deliveries_v110(integer, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.service_claim_growth_deliveries_v110(p_limit integer DEFAULT 25, p_worker_id text DEFAULT 'growth-dispatcher'::text, p_idempotency_key uuid DEFAULT gen_random_uuid()) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_identity text;
  v_hash text;
  v_request_lock text;
  v_receipt jsonb;
begin
  if coalesce(auth.jwt() ->> 'role', '') <> 'service_role' then
    raise exception 'service role required' using errcode = '42501';
  end if;
  if coalesce(p_limit, 0) not between 1 and 100
     or length(btrim(coalesce(p_worker_id, ''))) not between 2 and 120
     or p_idempotency_key is null then
    raise exception 'valid claim limit, worker and idempotency are required'
      using errcode = '22023';
  end if;
  v_identity := app.v112_hash(jsonb_build_object(
    'operation', 'service_claim_growth_deliveries_v110',
    'idempotency_key', p_idempotency_key
  ));
  v_hash := app.v112_hash(jsonb_build_object(
    'limit', p_limit,
    'worker_id', p_worker_id
  ));
  v_request_lock := 'v112-v110-claim-request:' || v_identity;
  perform app.v112_lock_pair(v_request_lock, v_request_lock);
  v_receipt := app.v112_get_receipt(v_identity, v_hash);
  if v_receipt is not null then
    return v_receipt;
  end if;
  v_receipt := public.service_claim_growth_deliveries_v110_v112_inner(
    p_limit, p_worker_id, p_idempotency_key
  );
  return app.v112_put_receipt(
    v_identity, 'service_claim_growth_deliveries_v110', v_hash,
    jsonb_build_object(
      'idempotency_key', p_idempotency_key,
      'limit', p_limit,
      'worker_id', p_worker_id
    ),
    v_receipt
  );
end $$;

--
-- Name: service_claim_growth_deliveries_v110_v112_inner(integer, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.service_claim_growth_deliveries_v110_v112_inner(p_limit integer DEFAULT 25, p_worker_id text DEFAULT 'growth-dispatcher'::text, p_idempotency_key uuid DEFAULT gen_random_uuid()) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_candidate record;
  v_dispatch public.growth_delivery_dispatches_v110%rowtype;
  v_delivery public.growth_deliveries_v108%rowtype;
  v_execution public.growth_executions_v108%rowtype;
  v_preference public.customer_notification_preferences%rowtype;
  v_claims jsonb := '[]'::jsonb;
  v_reason text;
  v_spend bigint;
  v_event_key uuid;
begin
  if coalesce(auth.jwt() ->> 'role', '') <> 'service_role' then
    raise exception 'service role required' using errcode = '42501';
  end if;
  if coalesce(p_limit, 0) not between 1 and 100
     or length(btrim(coalesce(p_worker_id, ''))) not between 2 and 120
     or p_idempotency_key is null then
    raise exception 'valid claim limit, worker and idempotency are required'
      using errcode = '22023';
  end if;
  for v_candidate in
    select dispatch.id, dispatch.execution_id
    from public.growth_delivery_dispatches_v110 dispatch
    where dispatch.lifecycle_status in ('queued', 'scheduled')
      and dispatch.scheduled_for <= statement_timestamp()
      and dispatch.next_attempt_at <= statement_timestamp()
    order by dispatch.scheduled_for, dispatch.created_at, dispatch.id
    limit p_limit
  loop
    -- Preserve v110's execution-level budget serialization, but acquire it
    -- before the shared dispatch advisory and dispatch row locks.
    perform pg_advisory_xact_lock(
      hashtextextended('v110-dispatch:' || v_candidate.execution_id::text, 0)
    );
    perform app.v112_lock_dispatch(v_candidate.id);
    select * into v_dispatch
    from public.growth_delivery_dispatches_v110
    where id = v_candidate.id
      and lifecycle_status in ('queued', 'scheduled')
      and scheduled_for <= statement_timestamp()
      and next_attempt_at <= statement_timestamp()
    for update;
    if not found then
      continue;
    end if;
    select * into strict v_delivery
    from public.growth_deliveries_v108
    where id = v_dispatch.delivery_id for update;
    select * into strict v_execution
    from public.growth_executions_v108
    where id = v_dispatch.execution_id
      and business_id = v_dispatch.business_id for update;
    select * into v_preference
    from public.customer_notification_preferences preference
    where preference.business_id = v_delivery.business_id
      and preference.client_id = v_delivery.client_id
      and preference.link_id = v_delivery.link_id
      and preference.channel = 'in_app'
      and preference.topic = 'marketing'
    order by preference.updated_at desc, preference.id
    limit 1;
    v_reason := null;
    if not app.platform_feature_enabled('growth_closed_loop_v108') then
      v_reason := 'feature_disabled';
    elsif not exists (
      select 1 from public.businesses business
      where business.id = v_dispatch.business_id
        and 'retention' = any(coalesce(business.enabled_modules, '{}'::text[]))
    ) then
      v_reason := 'module_disabled';
    elsif v_execution.status <> 'running'
       or v_execution.ends_at <= statement_timestamp() then
      v_reason := 'execution_expired';
    elsif not exists (
      select 1 from public.customer_links link
      where link.id = v_delivery.link_id
        and link.business_id = v_delivery.business_id
        and link.client_id = v_delivery.client_id
        and link.identity_id = v_delivery.identity_id
        and link.state = 'verified'
    ) then
      v_reason := 'link_unavailable';
    elsif v_preference.opted_in is distinct from true then
      v_reason := 'consent_withdrawn';
    elsif app.c46_in_quiet_hours(
      v_preference.quiet_hours_timezone,
      v_preference.quiet_hours_start,
      v_preference.quiet_hours_end,
      statement_timestamp()
    ) then
      perform set_config('app.growth_delivery_v110_transition', 'on', true);
      update public.growth_delivery_dispatches_v110
      set lifecycle_status = 'scheduled',
          scheduled_for = app.v110_next_allowed_at(
            v_preference.quiet_hours_timezone,
            v_preference.quiet_hours_start,
            v_preference.quiet_hours_end,
            statement_timestamp()
          ),
          next_attempt_at = app.v110_next_allowed_at(
            v_preference.quiet_hours_timezone,
            v_preference.quiet_hours_start,
            v_preference.quiet_hours_end,
            statement_timestamp()
          ),
          updated_at = statement_timestamp()
      where id = v_dispatch.id;
      update public.growth_deliveries_v108
      set delivery_status = 'scheduled'
      where id = v_delivery.id;
      continue;
    elsif exists (
      select 1
      from public.growth_delivery_dispatches_v110 prior_dispatch
      join public.growth_deliveries_v108 prior_delivery
        on prior_delivery.id = prior_dispatch.delivery_id
      where prior_delivery.business_id = v_delivery.business_id
        and prior_delivery.client_id = v_delivery.client_id
        and prior_dispatch.lifecycle_status = 'delivered'
        and prior_dispatch.delivered_at >= statement_timestamp()
          - make_interval(days => (
              select frequency_cap_days
              from public.growth_recommendations_v108 recommendation
              where recommendation.id = v_execution.recommendation_id
            ))
    ) then
      v_reason := 'frequency_cap';
    end if;
    select coalesce(sum(delivery.estimated_cost_cents), 0)
    into v_spend
    from public.growth_delivery_dispatches_v110 dispatch
    join public.growth_deliveries_v108 delivery
      on delivery.id = dispatch.delivery_id
    where dispatch.execution_id = v_execution.id
      and dispatch.lifecycle_status in ('delivering', 'delivered');
    if v_reason is null
       and v_spend + v_delivery.estimated_cost_cents >
         v_execution.budget_cap_cents then
      v_reason := 'budget_cap';
    end if;
    v_event_key := extensions.uuid_generate_v5(
      p_idempotency_key, v_dispatch.id::text || ':claim'
    );
    if v_reason is not null then
      perform app.v110_transition_delivery(
        v_dispatch.id, 'cancelled', v_reason, null, v_event_key,
        jsonb_build_object('worker_id', p_worker_id, 'gate_recheck', true)
      );
      continue;
    end if;
    v_dispatch := app.v110_transition_delivery(
      v_dispatch.id, 'delivering', null, null, v_event_key,
      jsonb_build_object('worker_id', p_worker_id, 'gate_recheck', true)
    );
    v_claims := v_claims || jsonb_build_array(jsonb_build_object(
      'dispatch_id', v_dispatch.id,
      'delivery_id', v_dispatch.delivery_id,
      'execution_id', v_execution.id,
      'business_id', v_execution.business_id,
      'branch_id', v_execution.branch_id,
      'provider', v_dispatch.provider,
      'identity_id', v_delivery.identity_id,
      'governed_copy', v_execution.governed_copy,
      'attempt', v_dispatch.attempt_count
    ));
  end loop;
  return jsonb_build_object(
    'contract_version', 'growth_delivery_lifecycle_v110',
    'claims', v_claims,
    'claimed_count', jsonb_array_length(v_claims)
  );
end $$;

--
-- Name: service_claim_growth_deliveries_v110_v112_unsafe_row_inner(integer, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.service_claim_growth_deliveries_v110_v112_unsafe_row_inner(p_limit integer DEFAULT 25, p_worker_id text DEFAULT 'growth-dispatcher'::text, p_idempotency_key uuid DEFAULT gen_random_uuid()) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_dispatch public.growth_delivery_dispatches_v110%rowtype;
  v_delivery public.growth_deliveries_v108%rowtype;
  v_execution public.growth_executions_v108%rowtype;
  v_preference public.customer_notification_preferences%rowtype;
  v_claims jsonb := '[]'::jsonb;
  v_reason text;
  v_spend bigint;
  v_event_key uuid;
begin
  if coalesce(auth.jwt() ->> 'role', '') <> 'service_role' then
    raise exception 'service role required' using errcode = '42501';
  end if;
  if coalesce(p_limit, 0) not between 1 and 100
     or length(btrim(coalesce(p_worker_id, ''))) not between 2 and 120
     or p_idempotency_key is null then
    raise exception 'valid claim limit, worker and idempotency are required'
      using errcode = '22023';
  end if;
  for v_dispatch in
    select dispatch.*
    from public.growth_delivery_dispatches_v110 dispatch
    where dispatch.lifecycle_status in ('queued', 'scheduled')
      and dispatch.scheduled_for <= statement_timestamp()
      and dispatch.next_attempt_at <= statement_timestamp()
    order by dispatch.scheduled_for, dispatch.created_at, dispatch.id
    for update skip locked
    limit p_limit
  loop
    perform pg_advisory_xact_lock(
      hashtextextended('v110-dispatch:' || v_dispatch.execution_id::text, 0)
    );
    select * into strict v_delivery
    from public.growth_deliveries_v108
    where id = v_dispatch.delivery_id for update;
    select * into strict v_execution
    from public.growth_executions_v108
    where id = v_dispatch.execution_id
      and business_id = v_dispatch.business_id for update;
    select * into v_preference
    from public.customer_notification_preferences preference
    where preference.business_id = v_delivery.business_id
      and preference.client_id = v_delivery.client_id
      and preference.link_id = v_delivery.link_id
      and preference.channel = 'in_app'
      and preference.topic = 'marketing'
    order by preference.updated_at desc, preference.id
    limit 1;
    v_reason := null;
    if not app.platform_feature_enabled('growth_closed_loop_v108') then
      v_reason := 'feature_disabled';
    elsif not exists (
      select 1 from public.businesses business
      where business.id = v_dispatch.business_id
        and 'retention' = any(coalesce(business.enabled_modules, '{}'::text[]))
    ) then
      v_reason := 'module_disabled';
    elsif v_execution.status <> 'running'
       or v_execution.ends_at <= statement_timestamp() then
      v_reason := 'execution_expired';
    elsif not exists (
      select 1 from public.customer_links link
      where link.id = v_delivery.link_id
        and link.business_id = v_delivery.business_id
        and link.client_id = v_delivery.client_id
        and link.identity_id = v_delivery.identity_id
        and link.state = 'verified'
    ) then
      v_reason := 'link_unavailable';
    elsif v_preference.opted_in is distinct from true then
      v_reason := 'consent_withdrawn';
    elsif app.c46_in_quiet_hours(
      v_preference.quiet_hours_timezone,
      v_preference.quiet_hours_start,
      v_preference.quiet_hours_end,
      statement_timestamp()
    ) then
      perform set_config('app.growth_delivery_v110_transition', 'on', true);
      update public.growth_delivery_dispatches_v110
      set lifecycle_status = 'scheduled',
          scheduled_for = app.v110_next_allowed_at(
            v_preference.quiet_hours_timezone,
            v_preference.quiet_hours_start,
            v_preference.quiet_hours_end,
            statement_timestamp()
          ),
          next_attempt_at = app.v110_next_allowed_at(
            v_preference.quiet_hours_timezone,
            v_preference.quiet_hours_start,
            v_preference.quiet_hours_end,
            statement_timestamp()
          ),
          updated_at = statement_timestamp()
      where id = v_dispatch.id;
      update public.growth_deliveries_v108
      set delivery_status = 'scheduled'
      where id = v_delivery.id;
      continue;
    elsif exists (
      select 1
      from public.growth_delivery_dispatches_v110 prior_dispatch
      join public.growth_deliveries_v108 prior_delivery
        on prior_delivery.id = prior_dispatch.delivery_id
      where prior_delivery.business_id = v_delivery.business_id
        and prior_delivery.client_id = v_delivery.client_id
        and prior_dispatch.lifecycle_status = 'delivered'
        and prior_dispatch.delivered_at >= statement_timestamp()
          - make_interval(days => (
              select frequency_cap_days
              from public.growth_recommendations_v108 recommendation
              where recommendation.id = v_execution.recommendation_id
            ))
    ) then
      v_reason := 'frequency_cap';
    end if;
    select coalesce(sum(delivery.estimated_cost_cents), 0)
    into v_spend
    from public.growth_delivery_dispatches_v110 dispatch
    join public.growth_deliveries_v108 delivery
      on delivery.id = dispatch.delivery_id
    where dispatch.execution_id = v_execution.id
      and dispatch.lifecycle_status in ('delivering', 'delivered');
    if v_reason is null
       and v_spend + v_delivery.estimated_cost_cents >
         v_execution.budget_cap_cents then
      v_reason := 'budget_cap';
    end if;
    v_event_key := extensions.uuid_generate_v5(
      p_idempotency_key, v_dispatch.id::text || ':claim'
    );
    if v_reason is not null then
      perform app.v110_transition_delivery(
        v_dispatch.id, 'cancelled', v_reason, null, v_event_key,
        jsonb_build_object('worker_id', p_worker_id, 'gate_recheck', true)
      );
      continue;
    end if;
    v_dispatch := app.v110_transition_delivery(
      v_dispatch.id, 'delivering', null, null, v_event_key,
      jsonb_build_object('worker_id', p_worker_id, 'gate_recheck', true)
    );
    v_claims := v_claims || jsonb_build_array(jsonb_build_object(
      'dispatch_id', v_dispatch.id,
      'delivery_id', v_dispatch.delivery_id,
      'execution_id', v_execution.id,
      'business_id', v_execution.business_id,
      'branch_id', v_execution.branch_id,
      'provider', v_dispatch.provider,
      'identity_id', v_delivery.identity_id,
      'governed_copy', v_execution.governed_copy,
      'attempt', v_dispatch.attempt_count
    ));
  end loop;
  return jsonb_build_object(
    'contract_version', 'growth_delivery_lifecycle_v110',
    'claims', v_claims,
    'claimed_count', jsonb_array_length(v_claims)
  );
end $$;

--
-- Name: FUNCTION service_claim_growth_deliveries_v110_v112_unsafe_row_inner(p_limit integer, p_worker_id text, p_idempotency_key uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.service_claim_growth_deliveries_v110_v112_unsafe_row_inner(p_limit integer, p_worker_id text, p_idempotency_key uuid) IS 'Service-only SKIP LOCKED claim with feature, module, execution, consent, quiet-hours, frequency and budget rechecks.';

--
-- Name: service_complete_growth_delivery_v110(uuid, text, boolean, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.service_complete_growth_delivery_v110(p_dispatch uuid, p_provider_message_id text, p_succeeded boolean, p_error_code text, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_identity text;
  v_hash text;
  v_receipt jsonb;
begin
  if coalesce(auth.jwt() ->> 'role', '') <> 'service_role' then
    raise exception 'service role required' using errcode = '42501';
  end if;
  v_identity := app.v112_hash(jsonb_build_object(
    'operation', 'service_complete_growth_delivery_v110',
    'dispatch_id', p_dispatch, 'idempotency_key', p_idempotency_key
  ));
  v_hash := app.v112_hash(jsonb_build_object(
    'dispatch_id', p_dispatch,
    'provider_message_id', nullif(btrim(coalesce(p_provider_message_id, '')), ''),
    'succeeded', p_succeeded,
    'error_code', nullif(btrim(coalesce(p_error_code, '')), '')
  ));
  perform app.v112_lock_dispatch(p_dispatch);
  perform app.v112_lock_pair(
    'v112-v110-callback-request:' || v_identity,
    'v112-v110-callback-request:' || v_identity
  );
  v_receipt := app.v112_get_receipt(v_identity, v_hash);
  if v_receipt is not null then
    return v_receipt;
  end if;
  v_receipt := public.service_complete_growth_delivery_v110_v112_inner(
    p_dispatch, p_provider_message_id, p_succeeded, p_error_code,
    p_idempotency_key
  );
  return app.v112_put_receipt(
    v_identity, 'service_complete_growth_delivery_v110', v_hash,
    jsonb_build_object(
      'dispatch_id', p_dispatch, 'idempotency_key', p_idempotency_key
    ),
    v_receipt
  );
end $$;

--
-- Name: service_complete_growth_delivery_v110_v112_inner(uuid, text, boolean, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.service_complete_growth_delivery_v110_v112_inner(p_dispatch uuid, p_provider_message_id text, p_succeeded boolean, p_error_code text, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_dispatch public.growth_delivery_dispatches_v110%rowtype;
  v_delivery public.growth_deliveries_v108%rowtype;
  v_execution public.growth_executions_v108%rowtype;
  v_suppression_reason text;
  v_now timestamptz := statement_timestamp();
begin
  perform app.v112_lock_dispatch(p_dispatch);
  if p_succeeded then
    if length(btrim(coalesce(p_provider_message_id, ''))) < 3 then
      raise exception 'verified provider message id is required'
        using errcode = '22023';
    end if;
    select * into strict v_dispatch
    from public.growth_delivery_dispatches_v110
    where id = p_dispatch for update;
    select * into strict v_delivery
    from public.growth_deliveries_v108
    where id = v_dispatch.delivery_id for update;
    select * into strict v_execution
    from public.growth_executions_v108
    where id = v_dispatch.execution_id
      and business_id = v_dispatch.business_id;

    if not app.platform_feature_enabled('growth_closed_loop_v108') then
      v_suppression_reason := 'feature_disabled';
    elsif not exists (
      select 1 from public.businesses business
      where business.id = v_dispatch.business_id
        and 'retention' = any(coalesce(business.enabled_modules, '{}'::text[]))
    ) then
      v_suppression_reason := 'module_disabled';
    elsif v_execution.status <> 'running' then
      v_suppression_reason := 'execution_cancelled';
    elsif v_execution.ends_at <= v_now then
      v_suppression_reason := 'execution_expired';
    elsif v_dispatch.branch_id is not null and not exists (
      select 1 from public.branches branch
      where branch.id = v_dispatch.branch_id
        and branch.business_id = v_dispatch.business_id
        and branch.active
    ) then
      v_suppression_reason := 'branch_unavailable';
    elsif not exists (
      select 1 from public.customer_links link
      where link.id = v_delivery.link_id
        and link.business_id = v_delivery.business_id
        and link.client_id = v_delivery.client_id
        and link.identity_id = v_delivery.identity_id
        and link.state = 'verified'
    ) then
      v_suppression_reason := 'link_unavailable';
    elsif not exists (
      select 1
      from public.customer_notification_preferences preference
      where preference.business_id = v_delivery.business_id
        and preference.client_id = v_delivery.client_id
        and preference.link_id = v_delivery.link_id
        and preference.channel = 'in_app'
        and preference.topic = 'marketing'
        and preference.opted_in
    ) then
      v_suppression_reason := 'consent_withdrawn';
    end if;

    if v_suppression_reason is not null then
      v_dispatch := app.v110_transition_delivery(
        p_dispatch, 'delivered', v_suppression_reason,
        btrim(p_provider_message_id), p_idempotency_key,
        jsonb_build_object(
          'callback_verified', true,
          'entitlement_suppressed', true,
          'suppression_reason', v_suppression_reason,
          'eligibility_rechecked_at', v_now
        )
      );
      return jsonb_build_object(
        'dispatch_id', v_dispatch.id,
        'delivery_id', v_dispatch.delivery_id,
        'status', v_dispatch.lifecycle_status,
        'entitlement_id', null,
        'entitlement_suppressed', true,
        'suppression_reason', v_suppression_reason,
        'replayed', false
      );
    end if;
  end if;
  return public.service_complete_growth_delivery_v110_v112_unsafe_row_inner(
    p_dispatch, p_provider_message_id, p_succeeded, p_error_code,
    p_idempotency_key
  );
end $$;

--
-- Name: service_complete_growth_delivery_v110_v112_unsafe_row_inner(uuid, text, boolean, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.service_complete_growth_delivery_v110_v112_unsafe_row_inner(p_dispatch uuid, p_provider_message_id text, p_succeeded boolean, p_error_code text, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_dispatch public.growth_delivery_dispatches_v110%rowtype;
  v_delivery public.growth_deliveries_v108%rowtype;
  v_execution public.growth_executions_v108%rowtype;
  v_entitlement public.growth_entitlements_v108%rowtype;
begin
  if coalesce(auth.jwt() ->> 'role', '') <> 'service_role' then
    raise exception 'service role required' using errcode = '42501';
  end if;
  if p_dispatch is null or p_succeeded is null or p_idempotency_key is null then
    raise exception 'dispatch result and idempotency are required'
      using errcode = '22023';
  end if;
  select * into strict v_dispatch
  from public.growth_delivery_dispatches_v110
  where id = p_dispatch for update;
  select * into strict v_delivery
  from public.growth_deliveries_v108
  where id = v_dispatch.delivery_id for update;
  select * into strict v_execution
  from public.growth_executions_v108
  where id = v_dispatch.execution_id
    and business_id = v_dispatch.business_id;
  if p_succeeded then
    if length(btrim(coalesce(p_provider_message_id, ''))) < 3 then
      raise exception 'verified provider message id is required'
        using errcode = '22023';
    end if;
    v_dispatch := app.v110_transition_delivery(
      p_dispatch, 'delivered', null, btrim(p_provider_message_id),
      p_idempotency_key, jsonb_build_object('callback_verified', true)
    );
    insert into public.growth_entitlements_v108(
      delivery_id, execution_id, business_id, client_id, identity_id,
      entitlement_type, value_cents, estimated_cost_cents, expires_at
    ) values (
      v_delivery.id, v_execution.id, v_execution.business_id,
      v_delivery.client_id, v_delivery.identity_id,
      'credit_cents', v_execution.offer_value_cents,
      v_execution.offer_value_cents,
      least(statement_timestamp() + interval '7 days', v_execution.ends_at)
    )
    on conflict (delivery_id) do nothing
    returning * into v_entitlement;
    if v_entitlement.id is null then
      select * into strict v_entitlement
      from public.growth_entitlements_v108
      where delivery_id = v_delivery.id;
    end if;
    insert into public.growth_entitlement_events_v108(
      entitlement_id, business_id, event_type, actor,
      idempotency_key, detail
    ) values (
      v_entitlement.id, v_entitlement.business_id, 'issued', null,
      extensions.uuid_generate_v5(p_idempotency_key, 'entitlement-issued'),
      jsonb_build_object(
        'execution_id', v_execution.id,
        'delivery_id', v_delivery.id,
        'provider_message_id', btrim(p_provider_message_id),
        'value_cents', v_entitlement.value_cents
      )
    ) on conflict do nothing;
  else
    if length(btrim(coalesce(p_error_code, ''))) < 2 then
      raise exception 'provider error code is required' using errcode = '22023';
    end if;
    v_dispatch := app.v110_transition_delivery(
      p_dispatch, 'failed', btrim(p_error_code), null,
      p_idempotency_key, jsonb_build_object('callback_verified', true)
    );
  end if;
  return jsonb_build_object(
    'dispatch_id', v_dispatch.id,
    'delivery_id', v_dispatch.delivery_id,
    'status', v_dispatch.lifecycle_status,
    'entitlement_id', v_entitlement.id,
    'replayed', exists (
      select 1 from public.growth_delivery_state_events_v110 event_row
      where event_row.dispatch_id = p_dispatch
        and event_row.idempotency_key = p_idempotency_key
        and event_row.occurred_at < statement_timestamp()
    )
  );
end $$;

--
-- Name: service_consume_document_signing_request_v86(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.service_consume_document_signing_request_v86(p_request uuid, p_exchange_token text, p_actor uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_request public.sme_document_signing_requests%rowtype;v_document public.sme_document_versions%rowtype;
begin
  select * into v_request from public.sme_document_signing_requests where id=p_request for update;
  if p_actor is null or not found or v_request.requested_by<>p_actor
    or v_request.consumed_at is not null or v_request.expires_at<=now()
    or v_request.token_hash<>app.v76_sha256_hex(coalesce(p_exchange_token,'')) then
    raise exception 'document signing request is invalid or expired' using errcode='22023';end if;
  update public.sme_document_signing_requests set consumed_at=now() where id=v_request.id;
  select * into strict v_document from public.sme_document_versions where id=v_request.document_version_id;
  return jsonb_build_object(
    'purpose',v_request.purpose,'bucket_id',v_document.bucket_id,'object_path',v_document.object_path,
    'mime_type',v_document.mime_type,'size_bytes',v_document.size_bytes,
    'original_filename',v_document.original_filename,
    'expires_at',v_request.expires_at,'document_version_id',v_document.id,
    'requested_by',v_request.requested_by
  );
end
$$;

--
-- Name: service_finalize_document_upload_v86(uuid, text, bigint, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.service_finalize_document_upload_v86(p_request uuid, p_sha256 text, p_observed_size_bytes bigint, p_actor uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $_$
declare v_request public.sme_document_signing_requests%rowtype;v_document public.sme_document_versions%rowtype;
begin
  select * into v_request from public.sme_document_signing_requests where id=p_request for update;
  if p_actor is null or not found or v_request.requested_by<>p_actor
    or v_request.purpose<>'upload' or v_request.consumed_at is null
    or v_request.expires_at<=now() then
    raise exception 'consumed upload signing request was not found or has expired' using errcode='22023';end if;
  select * into v_document from public.sme_document_versions
    where id=v_request.document_version_id for update;
  if v_document.status<>'reserved' or p_observed_size_bytes<>v_document.size_bytes
    or p_sha256!~'^[0-9a-f]{64}$' then
    raise exception 'uploaded object metadata does not match its reservation' using errcode='22023';end if;
  update public.sme_document_versions set status='uploaded',sha256=p_sha256,uploaded_at=now()
    where id=v_document.id returning * into v_document;
  insert into public.audit_log(business_id,actor,action,entity,entity_id,detail)
  values(null,v_request.requested_by,'SME_DOCUMENT_UPLOAD_FINALIZED_V86',
    'sme_document_versions',v_document.id,
    jsonb_build_object('prospect_id',v_document.prospect_id,'request_id',p_request,
      'size_bytes',p_observed_size_bytes));
  return jsonb_build_object('document',to_jsonb(v_document)-'object_path');
end
$_$;

--
-- Name: service_get_consumed_document_upload_v86(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.service_get_consumed_document_upload_v86(p_request uuid, p_actor uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_request public.sme_document_signing_requests%rowtype;v_document public.sme_document_versions%rowtype;
begin
  select * into v_request from public.sme_document_signing_requests where id=p_request;
  if p_actor is null or not found or v_request.requested_by<>p_actor
    or v_request.purpose<>'upload' or v_request.consumed_at is null
    or v_request.expires_at<=now() then
    raise exception 'consumed upload signing request was not found or has expired' using errcode='22023';end if;
  select * into v_document from public.sme_document_versions
    where id=v_request.document_version_id;
  if not found or v_document.status<>'reserved' then
    raise exception 'reserved document upload target was not found' using errcode='22023';end if;
  return jsonb_build_object(
    'request_id',v_request.id,'purpose',v_request.purpose,
    'bucket_id',v_document.bucket_id,'object_path',v_document.object_path,
    'mime_type',v_document.mime_type,'size_bytes',v_document.size_bytes,
    'original_filename',v_document.original_filename,
    'expires_at',v_request.expires_at,'document_version_id',v_document.id,
    'requested_by',v_request.requested_by
  );
end
$$;

--
-- Name: set_appointment_status_v47(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_appointment_status_v47(p_business uuid, p_appointment uuid, p_status text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_branch uuid;
begin
  select branch_id into v_branch from public.appointments
  where id=p_appointment and business_id=p_business;
  perform app.require_branch_module_v94(
    p_business,v_branch,'appointments','rw'
  );
  return public.set_appointment_status_v47_v94_base(
    p_business,p_appointment,p_status
  );
end
$$;

--
-- Name: set_appointment_status_v47_v94_base(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_appointment_status_v47_v94_base(p_business uuid, p_appointment uuid, p_status text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_appointment public.appointments%rowtype;
begin
  if auth.uid() is null or not app.can_module_write(p_business,'appointments') then
    raise exception 'appointment write access is required' using errcode='42501';
  end if;
  if p_status not in ('completed','cancelled','no_show') then
    raise exception 'unsupported appointment status transition' using errcode='22023';
  end if;
  if p_status='completed' and not app.has_perm(p_business,'create_sales') then
    raise exception 'create-sales authorization is required to complete an appointment'
      using errcode='42501';
  end if;
  select * into v_appointment from public.appointments a
   where a.id=p_appointment and a.business_id=p_business for update;
  if not found or not app.can_see_branch(p_business,v_appointment.branch_id) then
    raise exception 'appointment not found for this branch scope' using errcode='42501';
  end if;
  if p_status in ('completed','no_show') and v_appointment.starts_at>clock_timestamp() then
    raise exception 'a future appointment cannot be completed or marked no-show'
      using errcode='22023';
  end if;
  if v_appointment.status=p_status then
    return jsonb_build_object('status',p_status,'replayed',true,
      'appointment_id',p_appointment);
  end if;
  if v_appointment.status<>'booked' then
    raise exception 'appointment is already % and cannot move to %',v_appointment.status,p_status
      using errcode='22023';
  end if;
  update public.appointments set status=p_status where id=p_appointment;
  insert into public.audit_log (business_id,actor,action,entity,entity_id,detail)
  values (p_business,auth.uid(),'APPOINTMENT_STATUS','appointments',p_appointment,
    jsonb_build_object('from','booked','to',p_status));
  return jsonb_build_object('status',p_status,'replayed',false,
    'appointment_id',p_appointment);
end
$$;

--
-- Name: set_booking_settings(uuid, integer, text, boolean, boolean, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_booking_settings(p_business uuid, p_hold_minutes integer, p_overflow text, p_notify boolean, p_auto_confirm boolean DEFAULT NULL::boolean, p_takes_table_reservations boolean DEFAULT NULL::boolean) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if not app.is_salon_owner(p_business) then raise exception 'not authorized'; end if;
  if p_overflow is not null and p_overflow not in ('waitlist','reject') then
    raise exception 'invalid overflow (waitlist|reject)';
  end if;
  if p_hold_minutes is not null and p_hold_minutes < 0 then
    raise exception 'hold minutes must be >= 0';
  end if;
  update public.businesses set
    booking_hold_minutes = coalesce(p_hold_minutes, booking_hold_minutes),
    booking_overflow     = coalesce(p_overflow, booking_overflow),
    notify_new_bookings  = coalesce(p_notify, notify_new_bookings),
    booking_auto_confirm = coalesce(p_auto_confirm, booking_auto_confirm),
    takes_table_reservations = coalesce(p_takes_table_reservations, takes_table_reservations)
  where id = p_business;
  return json_build_object('status','ok');
end $$;

--
-- Name: set_bottle_expiry_v278(uuid, uuid, text, date, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_bottle_expiry_v278(p_business uuid, p_bottle uuid, p_expiry_mode text, p_expiry_date date, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_key text := nullif(btrim(coalesce(p_idempotency_key, '')), '');
  v_mode text := lower(btrim(coalesce(p_expiry_mode, '')));
  v_existing uuid;
  v_bottle public.bar_bottles%rowtype;
  v_before timestamptz;
  v_before_mode text;
  v_next timestamptz;
begin
  perform app.require_bar_business_v275(p_business);
  perform app.require_bar_staff_v275(p_business, true);
  if v_key is null then
    raise exception 'idempotency key required' using errcode = '22023';
  end if;
  if v_mode not in ('auto', 'custom', 'none') then
    raise exception 'expiry is automatic, a chosen date, or none' using errcode = '22023';
  end if;

  v_existing := app.bar_bottle_replayed_v275(p_business, v_key);
  if v_existing is not null then
    select * into v_bottle from public.bar_bottles bottle where bottle.id = v_existing;
    return jsonb_build_object('status', 'duplicate_ignored',
      'bottle', app.bar_bottle_json_v275(v_bottle));
  end if;

  select * into v_bottle from public.bar_bottles bottle
   where bottle.id = p_bottle and bottle.business_id = p_business for update;
  if not found then
    raise exception 'bottle not found' using errcode = '22023';
  end if;
  if v_bottle.status in ('finished', 'transferred', 'removed') then
    raise exception 'this bottle is closed' using errcode = '22023';
  end if;

  v_before := v_bottle.expires_at;
  v_before_mode := v_bottle.expiry_mode;
  v_next := app.bar_bottle_expiry_v278(p_business, v_bottle.client_id, v_mode, p_expiry_date);

  update public.bar_bottles bottle
     set expires_at = v_next,
         expiry_mode = v_mode,
         status = case when bottle.status = 'expired' then 'stored' else bottle.status end,
         updated_at = now()
   where bottle.id = v_bottle.id
  returning * into v_bottle;

  insert into public.bar_bottle_events (business_id, bottle_id, kind, actor, idem_key, detail)
  values (p_business, v_bottle.id, 'extend', v_actor, v_key,
    jsonb_build_object('from', v_before, 'to', v_next,
      'from_mode', v_before_mode, 'to_mode', v_mode, 'edited', true));

  return jsonb_build_object('status', 'ok', 'bottle', app.bar_bottle_json_v275(v_bottle));
end;
$$;

