--
-- Name: set_bottle_status_v275(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_bottle_status_v275(p_business uuid, p_bottle uuid, p_status text, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_key text := nullif(btrim(coalesce(p_idempotency_key, '')), '');
  v_status text := lower(btrim(coalesce(p_status, '')));
  v_existing uuid;
  v_bottle public.bar_bottles%rowtype;
  v_before text;
begin
  perform app.require_bar_business_v275(p_business);
  perform app.require_bar_staff_v275(p_business, true);
  if v_key is null then
    raise exception 'idempotency key required' using errcode = '22023';
  end if;
  if v_status not in ('stored', 'called', 'at_table', 'retrieved') then
    raise exception 'a bottle on the floor is stored, called, at table or retrieved' using errcode = '22023';
  end if;

  v_existing := app.bar_bottle_replayed_v275(p_business, v_key);
  if v_existing is not null then
    select * into v_bottle from public.bar_bottles bottle where bottle.id = v_existing;
    return jsonb_build_object('status', 'duplicate_ignored',
      'bottle', app.bar_bottle_json_v275(v_bottle));
  end if;

  select * into v_bottle from public.bar_bottles bottle
   where bottle.id = p_bottle and bottle.business_id = p_business for update;
  if not found then
    raise exception 'bottle not found' using errcode = '22023';
  end if;
  if v_bottle.status not in ('stored', 'called', 'at_table') then
    raise exception 'this bottle has already been sent out' using errcode = '22023';
  end if;
  if not app.bar_status_transition_allowed_v279(v_bottle.status, v_status) then
    raise exception 'this bottle has already been sent out' using errcode = '22023';
  end if;
  v_before := v_bottle.status;

  update public.bar_bottles bottle
     set status = v_status, updated_at = now()
   where bottle.id = v_bottle.id
  returning * into v_bottle;

  insert into public.bar_bottle_events (business_id, bottle_id, kind, actor, idem_key, detail)
  values (p_business, v_bottle.id, 'status', v_actor, v_key,
    jsonb_build_object('from', v_before, 'to', v_status));

  return jsonb_build_object('status', 'ok', 'bottle', app.bar_bottle_json_v275(v_bottle));
end;
$$;

--
-- Name: set_business_demo_flag_v174(uuid, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_business_demo_flag_v174(p_business uuid, p_is_demo boolean, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_actor uuid:=auth.uid();v_prior boolean;
begin
  if not app.is_super_admin() then
    raise exception 'super_admin_required' using errcode='42501';
  end if;
  if p_business is null or p_is_demo is null then
    raise exception 'business and is_demo are required' using errcode='22023';
  end if;
  select is_demo into v_prior from public.businesses where id=p_business for update;
  if not found then raise exception 'business_not_found' using errcode='22023';end if;
  if v_prior=p_is_demo then
    return jsonb_build_object('business_id',p_business,'is_demo',p_is_demo,'changed',false);
  end if;
  update public.businesses set is_demo=p_is_demo where id=p_business;
  insert into public.business_demo_flag_audit_v174(
    business_id,actor,prior_is_demo,new_is_demo,reason
  ) values(p_business,v_actor,v_prior,p_is_demo,nullif(btrim(coalesce(p_reason,'')),''));
  insert into public.audit_log(business_id,actor,action,entity,entity_id,detail)
  values(p_business,v_actor,
    case when p_is_demo then 'BUSINESS_MARKED_DEMO_V174' else 'BUSINESS_UNMARKED_DEMO_V174' end,
    'businesses',p_business,jsonb_build_object('is_demo',p_is_demo,'reason',p_reason));
  return jsonb_build_object('business_id',p_business,'is_demo',p_is_demo,'changed',true);
end
$$;

--
-- Name: set_business_modules(uuid, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_business_modules(p_business uuid, p_modules text[]) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_requested text[] := coalesce(p_modules,'{}'); v_resolved text[]; v_added text[];
begin
  if not app.is_salon_owner(p_business) then
    raise exception 'only the business owner can change modules' using errcode = '42501';
  end if;
  if exists (
    select 1 from public.business_sector_assignments where business_id=p_business
  ) then
    raise exception 'business modules are fixed by the assigned sector entitlement'
      using errcode = '42501';
  end if;
  v_resolved := app.resolve_module_dependencies(v_requested);
  update public.businesses set enabled_modules=v_resolved where id=p_business;
  if not found then raise exception 'business not found'; end if;
  select coalesce(array_agg(module_key order by module_key),'{}') into v_added
    from (select unnest(v_resolved) module_key except select unnest(v_requested)) added;
  return json_build_object('modules',v_resolved,'added_dependencies',v_added);
end
$$;

--
-- Name: set_business_sector_policy_override_v109(uuid, text, jsonb, text, timestamp with time zone, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_business_sector_policy_override_v109(p_business uuid, p_policy_key text, p_override_parameters jsonb, p_reason text, p_effective_from timestamp with time zone, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_identity text;
  v_hash text;
  v_receipt jsonb;
begin
  if v_actor is null then
    raise exception 'authentication required' using errcode = '42501';
  end if;
  perform app.v109_require_feature();
  if not app.is_salon_owner(p_business) then
    raise exception 'owner only' using errcode = '42501';
  end if;
  if not app.can_see_branch(p_business, null) then
    raise exception 'business-wide sector policy is outside actor scope'
      using errcode = '42501';
  end if;
  v_identity := app.v112_hash(jsonb_build_object(
    'operation', 'set_business_sector_policy_override_v109',
    'business_id', p_business, 'actor', v_actor,
    'idempotency_key', p_idempotency_key
  ));
  v_hash := app.v112_hash(jsonb_build_object(
    'business_id', p_business, 'policy_key', p_policy_key,
    'override_parameters', p_override_parameters,
    'reason', btrim(p_reason), 'effective_from', p_effective_from
  ));
  perform app.v112_lock_pair(
    'v112-v109-sector-request:' || v_identity,
    concat_ws(':', 'v112-v109-sector-scope', p_business, p_policy_key)
  );
  v_receipt := app.v112_get_receipt(v_identity, v_hash);
  if v_receipt is not null then
    return v_receipt;
  end if;
  v_receipt :=
    public.set_business_sector_policy_override_v109_v112_inner(
      p_business, p_policy_key, p_override_parameters, p_reason,
      p_effective_from, p_idempotency_key
    );
  return app.v112_put_receipt(
    v_identity, 'set_business_sector_policy_override_v109', v_hash,
    jsonb_build_object(
      'business_id', p_business, 'policy_key', p_policy_key, 'actor', v_actor
    ),
    v_receipt
  );
end $$;

--
-- Name: set_business_sector_policy_override_v109_v112_inner(uuid, text, jsonb, text, timestamp with time zone, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_business_sector_policy_override_v109_v112_inner(p_business uuid, p_policy_key text, p_override_parameters jsonb, p_reason text, p_effective_from timestamp with time zone, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid:=auth.uid();
  v_effective jsonb;
  v_base uuid;
  v_existing public.business_sector_policy_overrides_v109%rowtype;
  v_prior public.business_sector_policy_overrides_v109%rowtype;
  v_row public.business_sector_policy_overrides_v109%rowtype;
  v_version integer;
  v_request_hash text;
begin
  perform app.v109_require_feature();
  if not app.is_salon_owner(p_business) then
    raise exception 'owner only' using errcode='42501';
  end if;
  if not app.can_see_branch(p_business,null) then
    raise exception 'business-wide sector policy is outside actor scope'
      using errcode='42501';
  end if;
  if p_effective_from is null
     or coalesce(jsonb_typeof(p_override_parameters),'null')<>'object'
     or p_override_parameters='{}'::jsonb then
    raise exception 'non-empty override parameters and effective time are required'
      using errcode='22023';
  end if;
  if exists(
    select 1 from jsonb_object_keys(p_override_parameters) k
    where k not in (
      'minimum_prior_visits','cadence_multiplier',
      'minimum_lapse_days','minimum_audience'
    )
  ) then
    raise exception 'override contains an unsupported parameter' using errcode='22023';
  end if;
  if p_override_parameters ? 'minimum_prior_visits'
     and (
       jsonb_typeof(p_override_parameters->'minimum_prior_visits')<>'number'
       or (p_override_parameters->>'minimum_prior_visits')::numeric<>trunc(
         (p_override_parameters->>'minimum_prior_visits')::numeric
       )
       or (p_override_parameters->>'minimum_prior_visits')::numeric not between 2 and 20
     ) then
    raise exception 'minimum_prior_visits must be 2..20' using errcode='22023';
  end if;
  if p_override_parameters ? 'cadence_multiplier'
     and (
       jsonb_typeof(p_override_parameters->'cadence_multiplier')<>'number'
       or (p_override_parameters->>'cadence_multiplier')::numeric not between 1.10 and 5.00
     ) then
    raise exception 'cadence_multiplier must be 1.10..5.00' using errcode='22023';
  end if;
  if p_override_parameters ? 'minimum_lapse_days'
     and (
       jsonb_typeof(p_override_parameters->'minimum_lapse_days')<>'number'
       or (p_override_parameters->>'minimum_lapse_days')::numeric<>trunc(
         (p_override_parameters->>'minimum_lapse_days')::numeric
       )
       or (p_override_parameters->>'minimum_lapse_days')::numeric not between 3 and 365
     ) then
    raise exception 'minimum_lapse_days must be 3..365' using errcode='22023';
  end if;
  if p_override_parameters ? 'minimum_audience'
     and (
       jsonb_typeof(p_override_parameters->'minimum_audience')<>'number'
       or (p_override_parameters->>'minimum_audience')::numeric<>trunc(
         (p_override_parameters->>'minimum_audience')::numeric
       )
       or (p_override_parameters->>'minimum_audience')::numeric not between 10 and 5000
     ) then
    raise exception 'minimum_audience must be 10..5000' using errcode='22023';
  end if;
  if length(btrim(coalesce(p_reason,'')))<3 then
    raise exception 'override reason is required' using errcode='22023';
  end if;
  v_request_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'business_id',p_business,'policy_key',p_policy_key,
    'override_parameters',p_override_parameters,
    'reason',btrim(p_reason),'effective_from',p_effective_from
  )::text,'UTF8'),'sha256'),'hex');
  select * into v_existing
  from public.business_sector_policy_overrides_v109
  where business_id=p_business and created_by=v_actor
    and idempotency_key=p_idempotency_key;
  if found then
    if v_existing.request_hash<>v_request_hash then
      raise exception 'idempotency key reused with a different sector override request'
        using errcode='23505';
    end if;
    return jsonb_build_object(
      'override_id',v_existing.id,'version_no',v_existing.version_no,'replayed',true
    );
  end if;
  v_effective:=public.get_effective_sector_policy_v109(
    p_business,p_policy_key,p_effective_from
  );
  v_base:=(v_effective#>>'{base_policy,id}')::uuid;
  perform pg_advisory_xact_lock(hashtextextended(
    'v109-sector-override:'||p_business::text||':'||p_policy_key,0
  ));
  select * into v_prior
  from public.business_sector_policy_overrides_v109 o
  where o.business_id=p_business and o.policy_key=p_policy_key
    and o.effective_from<=p_effective_from
    and (o.effective_to is null or o.effective_to>p_effective_from)
  order by o.effective_from desc,o.version_no desc limit 1 for update;
  if found then
    if v_prior.effective_from=p_effective_from then
      raise exception 'an override already starts at this effective time'
        using errcode='23505';
    end if;
    update public.business_sector_policy_overrides_v109
    set effective_to=p_effective_from where id=v_prior.id;
  end if;
  if exists(
    select 1 from public.business_sector_policy_overrides_v109 o
    where o.business_id=p_business and o.policy_key=p_policy_key
      and o.effective_from>p_effective_from
  ) then
    raise exception 'overrides must be appended in effective-time order'
      using errcode='22023';
  end if;
  select coalesce(max(version_no),0)+1 into v_version
  from public.business_sector_policy_overrides_v109
  where business_id=p_business and policy_key=p_policy_key;
  insert into public.business_sector_policy_overrides_v109(
    business_id,policy_key,base_policy_id,version_no,override_parameters,
    reason,effective_from,created_by,idempotency_key,request_hash
  ) values(
    p_business,p_policy_key,v_base,v_version,p_override_parameters,
    btrim(p_reason),p_effective_from,v_actor,p_idempotency_key,v_request_hash
  ) returning * into v_row;
  insert into public.audit_log(business_id,actor,action,entity,entity_id,detail)
  values(
    p_business,v_actor,'SET_SECTOR_POLICY_OVERRIDE_V109',
    'business_sector_policy_overrides_v109',v_row.id,
    jsonb_build_object(
      'policy_key',p_policy_key,'base_policy_id',v_base,
      'version_no',v_version,'parameters',p_override_parameters,
      'reason',btrim(p_reason),'effective_from',p_effective_from
    )
  );
  return jsonb_build_object(
    'override_id',v_row.id,'base_policy_id',v_base,
    'version_no',v_version,'replayed',false
  );
end $$;

--
-- Name: set_customer_lifecycle_policy_v107(uuid, integer, integer, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_customer_lifecycle_policy_v107(p_business uuid, p_fallback_lapse_days integer, p_customer_interval_min_observations integer DEFAULT 3, p_reactivation_multiplier numeric DEFAULT 2.000, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_version integer;
  v_row public.customer_lifecycle_policies_v107%rowtype;
begin
  if auth.uid() is null then
    raise exception 'authentication required' using errcode = '42501';
  end if;
  if not (app.is_super_admin() or app.is_salon_owner(p_business)) then
    raise exception 'owner or super-admin required' using errcode = '42501';
  end if;
  if not app.can_see_branch(p_business, null) then
    raise exception 'business-wide lifecycle policy is outside actor scope'
      using errcode = '42501';
  end if;
  if not exists (select 1 from public.businesses where id = p_business) then
    raise exception 'business not found' using errcode = '23503';
  end if;
  if p_fallback_lapse_days not between 1 and 3650
     or p_customer_interval_min_observations not between 2 and 100
     or p_reactivation_multiplier not between 1.000 and 20.000 then
    raise exception 'lifecycle policy values are outside supported bounds'
      using errcode = '22023';
  end if;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(p_business::text, 107)
  );
  select coalesce(max(version_no), 0) + 1 into v_version
    from public.customer_lifecycle_policies_v107 where business_id = p_business;
  insert into public.customer_lifecycle_policies_v107(
    business_id, version_no, effective_from, fallback_lapse_days,
    customer_interval_min_observations, reactivation_multiplier,
    note, legacy_assumption
  ) values (
    p_business, v_version, clock_timestamp(), p_fallback_lapse_days,
    p_customer_interval_min_observations, p_reactivation_multiplier,
    nullif(btrim(p_note), ''), false
  ) returning * into v_row;
  return jsonb_build_object(
    'status', 'created',
    'policy_id', v_row.id,
    'version_no', v_row.version_no,
    'effective_from', v_row.effective_from,
    'fallback_lapse_days', v_row.fallback_lapse_days,
    'customer_interval_min_observations', v_row.customer_interval_min_observations,
    'reactivation_multiplier', v_row.reactivation_multiplier
  );
end $$;

--
-- Name: set_effective_cost_rule_v109(uuid, uuid, text, text, text, bigint, text, text, jsonb, timestamp with time zone, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_effective_cost_rule_v109(p_business uuid, p_branch uuid, p_scope_kind text, p_scope_key text, p_cost_method text, p_cost_value bigint, p_source_type text, p_source_reference text, p_evidence jsonb, p_effective_from timestamp with time zone, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_identity text;
  v_hash text;
  v_receipt jsonb;
begin
  if v_actor is null then
    raise exception 'authentication required' using errcode = '42501';
  end if;
  perform app.v109_require_feature();
  perform app.v109_require_finance_scope(p_business, p_branch);
  v_identity := app.v112_hash(jsonb_build_object(
    'operation', 'set_effective_cost_rule_v109',
    'business_id', p_business, 'actor', v_actor,
    'idempotency_key', p_idempotency_key
  ));
  v_hash := app.v112_hash(jsonb_build_object(
    'business_id', p_business, 'branch_id', p_branch,
    'scope_kind', p_scope_kind, 'scope_key', btrim(p_scope_key),
    'cost_method', p_cost_method, 'cost_value', p_cost_value,
    'source_type', p_source_type,
    'source_reference', btrim(p_source_reference),
    'evidence', p_evidence, 'effective_from', p_effective_from,
    'currency', (select upper(currency) from public.businesses where id=p_business)
  ));
  perform app.v112_lock_pair(
    'v112-v109-cost-request:' || v_identity,
    concat_ws(
      ':', 'v112-v109-cost-scope', p_business,
      coalesce(p_branch::text, 'all'), p_scope_kind, btrim(p_scope_key)
    )
  );
  v_receipt := app.v112_get_receipt(v_identity, v_hash);
  if v_receipt is not null then
    return v_receipt;
  end if;
  v_receipt := public.set_effective_cost_rule_v109_v112_inner(
    p_business, p_branch, p_scope_kind, p_scope_key, p_cost_method,
    p_cost_value, p_source_type, p_source_reference, p_evidence,
    p_effective_from, p_idempotency_key
  );
  return app.v112_put_receipt(
    v_identity, 'set_effective_cost_rule_v109', v_hash,
    jsonb_build_object(
      'business_id', p_business, 'branch_id', p_branch, 'actor', v_actor,
      'scope_kind', p_scope_kind, 'scope_key', btrim(p_scope_key)
    ),
    v_receipt
  );
end $$;

--
-- Name: set_effective_cost_rule_v109_v112_inner(uuid, uuid, text, text, text, bigint, text, text, jsonb, timestamp with time zone, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_effective_cost_rule_v109_v112_inner(p_business uuid, p_branch uuid, p_scope_kind text, p_scope_key text, p_cost_method text, p_cost_value bigint, p_source_type text, p_source_reference text, p_evidence jsonb, p_effective_from timestamp with time zone, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $_$
declare
  v_actor uuid:=auth.uid();
  v_existing public.economic_cost_rules_v109%rowtype;
  v_prior public.economic_cost_rules_v109%rowtype;
  v_rule public.economic_cost_rules_v109%rowtype;
  v_version integer;
  v_currency text;
  v_request_hash text;
begin
  perform app.v109_require_feature();
  perform app.v109_require_finance_scope(p_business,p_branch);
  if p_effective_from is null then
    raise exception 'effective_from is required' using errcode='22023';
  end if;
  if p_branch is not null and not exists(
    select 1 from public.branches b
    where b.id=p_branch and b.business_id=p_business
  ) then
    raise exception 'branch does not belong to business' using errcode='22023';
  end if;
  if p_scope_kind not in ('sale_kind','product','service','package')
     or nullif(btrim(p_scope_key),'') is null then
    raise exception 'valid cost scope is required' using errcode='22023';
  end if;
  if p_scope_kind in ('product','service','package')
     and btrim(p_scope_key) !~
       '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then
    raise exception 'line cost scope must be a valid item UUID'
      using errcode='22023';
  end if;
  if p_scope_kind='sale_kind'
     and btrim(p_scope_key) not in (
       'service','retail','membership','quick_sale','gift_card','package'
     ) then
    raise exception 'valid sale kind cost scope is required'
      using errcode='22023';
  end if;
  if p_cost_method not in ('revenue_bps','fixed_per_unit')
     or p_cost_value is null or p_cost_value<0
     or (p_cost_method='revenue_bps' and p_cost_value>10000) then
    raise exception 'valid cost method/value is required' using errcode='22023';
  end if;
  if p_source_type not in (
    'supplier_invoice','supplier_contract','accounting_import','owner_attestation'
  ) or length(btrim(coalesce(p_source_reference,'')))<3 then
    raise exception 'traceable cost source is required' using errcode='22023';
  end if;
  if coalesce(jsonb_typeof(p_evidence),'null')<>'object' then
    raise exception 'cost evidence must be a JSON object' using errcode='22023';
  end if;
  select upper(currency) into strict v_currency
  from public.businesses where id=p_business;
  v_request_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'business_id',p_business,'branch_id',p_branch,
    'scope_kind',p_scope_kind,'scope_key',btrim(p_scope_key),
    'cost_method',p_cost_method,'cost_value',p_cost_value,
    'source_type',p_source_type,'source_reference',btrim(p_source_reference),
    'evidence',p_evidence,'effective_from',p_effective_from,
    'currency',v_currency
  )::text,'UTF8'),'sha256'),'hex');

  select * into v_existing from public.economic_cost_rules_v109
  where business_id=p_business and created_by=v_actor
    and idempotency_key=p_idempotency_key;
  if found then
    if v_existing.request_hash<>v_request_hash then
      raise exception 'idempotency key reused with a different cost rule request'
        using errcode='23505';
    end if;
    return jsonb_build_object(
      'rule_id',v_existing.id,'version_no',v_existing.version_no,'replayed',true
    );
  end if;

  perform pg_advisory_xact_lock(hashtextextended(
    concat_ws(':','v109-cost',p_business,coalesce(p_branch::text,'all'),
      p_scope_kind,btrim(p_scope_key)),0
  ));
  select * into v_prior
  from public.economic_cost_rules_v109 r
  where r.business_id=p_business
    and r.branch_id is not distinct from p_branch
    and r.scope_kind=p_scope_kind and r.scope_key=btrim(p_scope_key)
    and r.effective_from<=p_effective_from
    and (r.effective_to is null or r.effective_to>p_effective_from)
  order by r.effective_from desc,r.version_no desc limit 1 for update;
  if found then
    if v_prior.effective_from=p_effective_from then
      raise exception 'a cost rule already starts at this effective time'
        using errcode='23505';
    end if;
    update public.economic_cost_rules_v109
    set effective_to=p_effective_from where id=v_prior.id;
  end if;
  if exists(
    select 1 from public.economic_cost_rules_v109 r
    where r.business_id=p_business
      and r.branch_id is not distinct from p_branch
      and r.scope_kind=p_scope_kind and r.scope_key=btrim(p_scope_key)
      and r.effective_from>p_effective_from
  ) then
    raise exception 'cost rules must be appended in effective-time order'
      using errcode='22023';
  end if;
  select coalesce(max(version_no),0)+1 into v_version
  from public.economic_cost_rules_v109 r
  where r.business_id=p_business
    and r.branch_id is not distinct from p_branch
    and r.scope_kind=p_scope_kind and r.scope_key=btrim(p_scope_key);
  insert into public.economic_cost_rules_v109(
    business_id,branch_id,scope_kind,scope_key,cost_method,cost_value,
    currency,source_type,source_reference,evidence,effective_from,version_no,
    created_by,idempotency_key,request_hash
  ) values(
    p_business,p_branch,p_scope_kind,btrim(p_scope_key),p_cost_method,p_cost_value,
    v_currency,p_source_type,btrim(p_source_reference),p_evidence,
    p_effective_from,v_version,v_actor,p_idempotency_key,v_request_hash
  ) returning * into v_rule;
  insert into public.audit_log(business_id,actor,action,entity,entity_id,detail)
  values(
    p_business,v_actor,'SET_EFFECTIVE_COST_RULE_V109',
    'economic_cost_rules_v109',v_rule.id,
    jsonb_build_object(
      'scope_kind',v_rule.scope_kind,'scope_key',v_rule.scope_key,
      'version_no',v_rule.version_no,'effective_from',v_rule.effective_from,
      'source_type',v_rule.source_type,
      'source_reference',v_rule.source_reference
    )
  );
  return jsonb_build_object(
    'rule_id',v_rule.id,'version_no',v_rule.version_no,
    'effective_from',v_rule.effective_from,'replayed',false
  );
end $_$;

--
-- Name: set_expense_void(uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_expense_void(p_business uuid, p_expense uuid, p_void boolean) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_row expenses;
begin
  if not app.has_perm(p_business, 'view_finance') then
    raise exception 'you do not have permission to void an expense (view_finance)';
  end if;
  update expenses
     set voided_at = case when p_void then now() else null end,
         voided_by = case when p_void then auth.uid() else null end
   where id = p_expense and business_id = p_business
  returning * into v_row;
  if not found then raise exception 'expense not found'; end if;
  return row_to_json(v_row);
end $$;

--
-- Name: set_gift_card_sales_enabled_v102(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_gift_card_sales_enabled_v102(p_business uuid, p_enabled boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if p_enabled is null then
    raise exception 'enabled_required' using errcode='22023';
  end if;
  if not (app.is_super_admin() or app.is_salon_owner(p_business)) then
    raise exception 'owner_required' using errcode='42501';
  end if;
  update public.businesses
  set gift_card_sales_enabled=p_enabled
  where id=p_business;
  if not found then
    raise exception 'business_not_found' using errcode='22023';
  end if;
  insert into public.audit_log(
    business_id,actor,action,entity,entity_id,detail
  ) values(
    p_business,auth.uid(),'GIFT_CARD_SALES_SET_V102','businesses',p_business,
    jsonb_build_object('enabled',p_enabled)
  );
  return jsonb_build_object('gift_card_sales_enabled',p_enabled);
end
$$;

--
-- Name: set_growth_cost_rule_v114(uuid, uuid, text, text, text, bigint, text, text, jsonb, timestamp with time zone, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_growth_cost_rule_v114(p_business uuid, p_branch uuid, p_cost_class text, p_scope_key text, p_cost_method text, p_cost_value bigint, p_source_type text, p_source_reference text, p_evidence jsonb, p_effective_from timestamp with time zone, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid:=auth.uid();
  v_prior public.growth_cost_rules_v114%rowtype;
  v_rule public.growth_cost_rules_v114%rowtype;
  v_version integer;
  v_currency text;
  v_identity text;
  v_request_hash text;
  v_receipt jsonb;
begin
  perform app.v109_require_feature();
  perform app.v109_require_finance_scope(p_business,p_branch);
  if p_effective_from is null or p_idempotency_key is null then
    raise exception 'effective_from and idempotency_key are required'
      using errcode='22023';
  end if;
  if p_branch is not null and not exists (
    select 1 from public.branches branch_row
    where branch_row.id=p_branch and branch_row.business_id=p_business
  ) then
    raise exception 'branch does not belong to business' using errcode='22023';
  end if;
  if p_cost_class not in ('benefit','delivery')
     or nullif(btrim(p_scope_key),'') is null then
    raise exception 'valid growth cost scope is required' using errcode='22023';
  end if;
  if (
    p_cost_class='benefit'
    and (
      btrim(p_scope_key)<>'credit_cents'
      or p_cost_method not in ('value_bps','fixed_per_event')
    )
  ) or (
    p_cost_class='delivery'
    and p_cost_method<>'fixed_per_event'
  ) or p_cost_value is null or p_cost_value<0
     or (p_cost_method='value_bps' and p_cost_value>10000) then
    raise exception 'valid growth cost method/value is required'
      using errcode='22023';
  end if;
  if p_source_type not in (
    'supplier_invoice','supplier_contract','accounting_import',
    'owner_attestation','provider_invoice','provider_contract'
  ) or length(btrim(coalesce(p_source_reference,'')))<3 then
    raise exception 'traceable growth cost source is required'
      using errcode='22023';
  end if;
  if coalesce(jsonb_typeof(p_evidence),'null')<>'object' then
    raise exception 'growth cost evidence must be a JSON object'
      using errcode='22023';
  end if;
  select upper(currency) into strict v_currency
  from public.businesses where id=p_business;
  v_request_hash:=app.v110_request_hash(jsonb_build_object(
    'business_id',p_business,'branch_id',p_branch,
    'cost_class',p_cost_class,'scope_key',btrim(p_scope_key),
    'cost_method',p_cost_method,'cost_value',p_cost_value,
    'source_type',p_source_type,
    'source_reference',btrim(p_source_reference),
    'evidence',p_evidence,'effective_from',p_effective_from,
    'currency',v_currency
  ));

  v_identity:=app.v112_hash(jsonb_build_object(
    'operation','set_growth_cost_rule_v114',
    'business_id',p_business,'actor',v_actor,
    'idempotency_key',p_idempotency_key
  ));
  perform app.v112_lock_pair(
    'v114-growth-cost-request:'||v_identity,
    concat_ws(
      ':','v114-growth-cost-scope',p_business,
      coalesce(p_branch::text,'all'),p_cost_class,btrim(p_scope_key)
    )
  );
  v_receipt:=app.v112_get_receipt(v_identity,v_request_hash);
  if v_receipt is not null then
    return v_receipt;
  end if;

  select * into v_prior
  from public.growth_cost_rules_v114 rule_row
  where rule_row.business_id=p_business
    and rule_row.branch_id is not distinct from p_branch
    and rule_row.cost_class=p_cost_class
    and rule_row.scope_key=btrim(p_scope_key)
    and rule_row.effective_from<=p_effective_from
    and (
      rule_row.effective_to is null
      or rule_row.effective_to>p_effective_from
    )
  order by rule_row.effective_from desc,rule_row.version_no desc
  limit 1 for update;
  if found then
    if v_prior.effective_from=p_effective_from then
      raise exception 'a growth cost rule already starts at this effective time'
        using errcode='23505';
    end if;
    update public.growth_cost_rules_v114
    set effective_to=p_effective_from where id=v_prior.id;
  end if;
  if exists (
    select 1 from public.growth_cost_rules_v114 rule_row
    where rule_row.business_id=p_business
      and rule_row.branch_id is not distinct from p_branch
      and rule_row.cost_class=p_cost_class
      and rule_row.scope_key=btrim(p_scope_key)
      and rule_row.effective_from>p_effective_from
  ) then
    raise exception 'growth cost rules must be appended in effective-time order'
      using errcode='22023';
  end if;
  select coalesce(max(version_no),0)+1 into v_version
  from public.growth_cost_rules_v114 rule_row
  where rule_row.business_id=p_business
    and rule_row.branch_id is not distinct from p_branch
    and rule_row.cost_class=p_cost_class
    and rule_row.scope_key=btrim(p_scope_key);

  insert into public.growth_cost_rules_v114 (
    business_id,branch_id,cost_class,scope_key,cost_method,cost_value,
    currency,source_type,source_reference,evidence,effective_from,version_no,
    created_by,idempotency_key,request_hash
  ) values (
    p_business,p_branch,p_cost_class,btrim(p_scope_key),
    p_cost_method,p_cost_value,v_currency,p_source_type,
    btrim(p_source_reference),p_evidence,p_effective_from,v_version,
    v_actor,p_idempotency_key,v_request_hash
  ) returning * into v_rule;

  insert into public.audit_log(
    business_id,actor,action,entity,entity_id,detail
  ) values (
    p_business,v_actor,'SET_GROWTH_COST_RULE_V114',
    'growth_cost_rules_v114',v_rule.id,jsonb_build_object(
      'branch_id',v_rule.branch_id,'cost_class',v_rule.cost_class,
      'scope_key',v_rule.scope_key,'cost_method',v_rule.cost_method,
      'cost_value',v_rule.cost_value,'currency',v_rule.currency,
      'version_no',v_rule.version_no,
      'effective_from',v_rule.effective_from,
      'source_type',v_rule.source_type,
      'source_reference',v_rule.source_reference
    )
  );
  v_receipt:=jsonb_build_object(
    'rule_id',v_rule.id,'version_no',v_rule.version_no,
    'effective_from',v_rule.effective_from,'replayed',false
  );
  return app.v112_put_receipt(
    v_identity,'set_growth_cost_rule_v114',v_request_hash,
    jsonb_build_object(
      'business_id',p_business,'branch_id',p_branch,'actor',v_actor,
      'cost_class',p_cost_class,'scope_key',btrim(p_scope_key)
    ),
    v_receipt
  );
end $$;

--
-- Name: FUNCTION set_growth_cost_rule_v114(p_business uuid, p_branch uuid, p_cost_class text, p_scope_key text, p_cost_method text, p_cost_value bigint, p_source_type text, p_source_reference text, p_evidence jsonb, p_effective_from timestamp with time zone, p_idempotency_key uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.set_growth_cost_rule_v114(p_business uuid, p_branch uuid, p_cost_class text, p_scope_key text, p_cost_method text, p_cost_value bigint, p_source_type text, p_source_reference text, p_evidence jsonb, p_effective_from timestamp with time zone, p_idempotency_key uuid) IS 'Finance-gated append-only benefit/delivery cost rule with concurrency-safe idempotent receipt replay.';

--
-- Name: set_membership_status(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_membership_status(p_business uuid, p_membership uuid, p_status text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_staff uuid;
  v_membership public.memberships%rowtype;
begin
  if v_actor is null or not app.can_module_write(p_business, 'memberships') then
    raise exception 'active memberships-module write authorization is required'
      using errcode='42501';
  end if;
  select s.id into v_staff from public.staff s
   where s.business_id=p_business and s.user_id=v_actor and s.active
   order by case when s.role='owner' then 0 else 1 end,s.created_at limit 1 for update;
  if not found then raise exception 'active staff authorization is required' using errcode='42501'; end if;
  if p_status not in ('active','paused','cancel_at_period_end','cancelled') then
    raise exception 'invalid membership status' using errcode='22023';
  end if;
  select * into v_membership from public.memberships m
   where m.id=p_membership and m.business_id=p_business for update;
  if not found then raise exception 'membership does not belong to this business' using errcode='22023'; end if;
  update public.memberships set status=p_status
   where id=p_membership and business_id=p_business returning * into v_membership;
  return jsonb_build_object('status','completed','membership_id',v_membership.id,
    'membership_status',v_membership.status);
end
$$;

--
-- Name: set_package_points_policy_v102(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_package_points_policy_v102(p_business uuid, p_earns_points boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if p_earns_points is null then
    raise exception 'earns_points_required' using errcode='22023';
  end if;
  if not (app.is_super_admin() or app.is_salon_owner(p_business)) then
    raise exception 'owner_required' using errcode='42501';
  end if;
  insert into public.sale_policies(
    business_id,kind,earns_points,note
  ) values(
    p_business,'package',p_earns_points,
    'Owner package-purchase points setting (Peekaa v102)'
  )
  on conflict (business_id,kind) do update
  set earns_points=excluded.earns_points,
      note=excluded.note,
      updated_at=now();
  return jsonb_build_object('package_earns_points',p_earns_points);
end
$$;

--
-- Name: set_programmes_v314(uuid, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_programmes_v314(p_business uuid, p_switches jsonb, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_hash text;
  v_rows integer;
  v_existing public.programme_switch_operations_v314%rowtype;
  v_kind text;
  v_want boolean;
  v_before boolean;
  v_changes jsonb := '[]'::jsonb;
  v_result jsonb;
  v_points boolean;
  v_stamps boolean;
  v_points_before boolean;
  v_stamps_before boolean;
  v_from uuid;
  v_to uuid;
  v_migration uuid;
  v_after_points boolean;
  v_after_tiers boolean;
  v_after_stamps boolean;
  v_model text;
  v_program_kind text;
begin
  if p_business is null or p_idempotency_key is null then
    raise exception 'business and idempotency key are required' using errcode = '22023';
  end if;
  if p_switches is null or jsonb_typeof(p_switches) <> 'object' then
    raise exception 'switches must be a JSON object' using errcode = '22023';
  end if;
  if jsonb_typeof(p_switches) = 'object' and exists (
    select 1 from jsonb_object_keys(p_switches) key
     where key not in ('points','tiers','stamps','referral')
  ) then
    raise exception 'switches may only name points, tiers, stamps or referral'
      using errcode = '22023';
  end if;
  if exists (
    select 1 from jsonb_each(p_switches) entry
     where jsonb_typeof(entry.value) <> 'boolean'
  ) then
    raise exception 'every switch must be true or false' using errcode = '22023';
  end if;
  if p_switches = '{}'::jsonb then
    raise exception 'at least one switch is required' using errcode = '22023';
  end if;

  if not app.c45_owner_loyalty_write(p_business) then
    raise exception 'owner loyalty configuration access required' using errcode = '42501';
  end if;

  v_hash := md5(p_business::text || ':' || (
    select coalesce(string_agg(key || '=' || (p_switches ->> key), ',' order by key), '')
      from jsonb_object_keys(p_switches) key
  ));

  insert into public.programme_switch_operations_v314
    (business_id, idempotency_key, actor, request_hash)
  values (p_business, p_idempotency_key, v_actor, v_hash)
  on conflict (business_id, idempotency_key) do nothing;
  get diagnostics v_rows = row_count;
  if v_rows = 0 then
    select * into strict v_existing from public.programme_switch_operations_v314
     where business_id = p_business and idempotency_key = p_idempotency_key
       for update;
    if v_existing.request_hash is distinct from v_hash then
      raise exception 'idempotency key conflicts with another programme switch'
        using errcode = '23505';
    end if;
    if v_existing.result is not null then
      return v_existing.result;
    end if;
    raise exception 'programme switch already in progress' using errcode = '55P03';
  end if;

  perform 1 from public.businesses target where target.id = p_business for update;
  if not found then
    raise exception 'business does not exist' using errcode = '42501';
  end if;

  select coalesce(bool_or(spine.active) filter (where spine.kind = 'points'), false),
         coalesce(bool_or(spine.active) filter (where spine.kind = 'stamps'), false)
    into v_points_before, v_stamps_before
    from public.business_programmes spine
   where spine.business_id = p_business;

  insert into public.business_programmes (business_id, kind, active, sort, activated_at)
  select p_business, model.kind, model.running,
         (case model.kind
            when 'points' then 1 when 'tiers' then 2 when 'stamps' then 3 when 'referral' then 4
          end)::smallint,
         case when model.running then now() end
    from app.business_programmes_v307(p_business) model
  on conflict (business_id, kind) do nothing;

  select coalesce((p_switches ->> 'points')::boolean,
                  bool_or(spine.active) filter (where spine.kind = 'points'), false),
         coalesce((p_switches ->> 'tiers')::boolean,
                  bool_or(spine.active) filter (where spine.kind = 'tiers'), false),
         coalesce((p_switches ->> 'stamps')::boolean,
                  bool_or(spine.active) filter (where spine.kind = 'stamps'), false)
    into v_after_points, v_after_tiers, v_after_stamps
    from public.business_programmes spine
   where spine.business_id = p_business;

  if v_after_stamps and (v_after_points or v_after_tiers) then
    raise exception 'The stamp card runs on its own. Turn Points & gifts and Tier membership off '
      'before turning the stamp card on, or turn the stamp card off to run points and tiers.'
      using errcode = '22023';
  end if;

  for v_kind, v_want in
    select entry.key, (entry.value)::boolean
      from jsonb_each_text(p_switches) entry
     order by case entry.key
                when 'points' then 1 when 'tiers' then 2 when 'stamps' then 3 else 4 end
  loop
    select spine.active into v_before
      from public.business_programmes spine
     where spine.business_id = p_business and spine.kind = v_kind
       for update;
    if not found then
      raise exception 'business % has no % programme row', p_business, v_kind
        using errcode = 'XX001';
    end if;
    if v_before is distinct from v_want then
      update public.business_programmes spine
         set active = v_want,
             activated_at = case when v_want and not spine.active then now()
                                 else spine.activated_at end,
             deactivated_at = case when spine.active and not v_want then now()
                                   else spine.deactivated_at end
       where spine.business_id = p_business and spine.kind = v_kind;
      v_changes := v_changes || jsonb_build_object('kind', v_kind, 'from', v_before, 'to', v_want);
      insert into public.audit_log (business_id, actor, action, entity, entity_id, detail)
      select p_business, v_actor, 'PROGRAMME_SWITCH_V314', 'business_programmes', spine.id,
             jsonb_build_object('kind', v_kind, 'from', v_before, 'to', v_want,
                                'source', 'set_programmes_v314')
        from public.business_programmes spine
       where spine.business_id = p_business and spine.kind = v_kind;
    end if;
  end loop;

  select coalesce(bool_or(spine.active) filter (where spine.kind = 'points'), false),
         coalesce(bool_or(spine.active) filter (where spine.kind = 'stamps'), false)
    into v_points, v_stamps
    from public.business_programmes spine
   where spine.business_id = p_business;

  -- V355: THE POT MIGRATION IS GONE FROM THIS PATH, DELIBERATELY.
  -- Owner ruling 2026-08-16: "i just want to ensure that the points doesn't flow to become
  -- stamps, if points is off - it will be switch off and show no. of stamps. not conveniently
  -- convert all the points into stamps." V312 used to move every client's balance from the
  -- outgoing programme's pot into the incoming one on a points<->stamps switch, so a firm that
  -- toggled the stamp card on saw 75,877 POINTS reappear as 75,877 STAMPS -- a unit the customer
  -- never earned. Cubbly's own trail shows it firing four times in ninety seconds of toggling.
  -- points_ledger.programme_id already keeps the two pots apart; leaving them apart IS the fix.
  -- A programme that is switched off now simply parks its pot untouched, and the customer sees
  -- only the live programme's own balance, which is what "turned off" should mean. The machinery
  -- (programme_pot_migrations, app.migrate_programme_pot_v312, run_programme_pot_migrations_v312)
  -- is intentionally left in place and callable for a deliberate, super-admin-initiated move --
  -- it is only no longer fired automatically by an owner flipping a switch.
  -- V354: the spine has just moved, so the declared model follows it, in this same transaction.
  -- Without this the two disagree the moment an owner switches back (the live defect above).
  v_model := case when v_stamps then 'stamps' else 'classic' end;
  v_program_kind := case when v_stamps then 'stamps' else 'points' end;
  update public.loyalty_programs
     set loyalty_model = v_model, kind = v_program_kind
   where business_id = p_business
     and (loyalty_model is distinct from v_model or kind is distinct from v_program_kind);
  if found then
    insert into public.audit_log(business_id, actor, action, entity, entity_id, detail)
    values (p_business, v_actor, 'loyalty_model.synced_to_spine', 'loyalty_programs', p_business,
      jsonb_build_object('loyalty_model', v_model, 'kind', v_program_kind,
                         'source', 'set_programmes_v314'));
  end if;

  v_result := jsonb_build_object(
    'business_id', p_business,
    'changed', v_changes,
    'pot_migration_id', v_migration,
    'programmes', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', spine.id,
               'kind', spine.kind,
               'active', spine.active,
               'running_since', spine.activated_at,
               'paused_since', spine.deactivated_at) order by spine.sort)
        from public.business_programmes spine
       where spine.business_id = p_business), '[]'::jsonb));

  update public.programme_switch_operations_v314
     set result = v_result
   where business_id = p_business and idempotency_key = p_idempotency_key;

  return v_result;
end
$$;

--
-- Name: FUNCTION set_programmes_v314(p_business uuid, p_switches jsonb, p_idempotency_key uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.set_programmes_v314(p_business uuid, p_switches jsonb, p_idempotency_key uuid) IS 'v314 W6i1: THE one intended writer of public.business_programmes. Takes a SET of switches in one call — per-kind calls would deadlock two owners against each other on the businesses row — gated by app.c45_owner_loyalty_write, locking the businesses row before the spine rows in kind order (V308 standing invariant 1). Reproduces the retired sync''s breadcrumb semantics exactly, writes nothing for a no-op flip, audits every real one as PROGRAMME_SWITCH_V314, and routes an accruing-identity change through app.enqueue_programme_pot_migration_v312 (V311/V312 standing invariant 2) — it never moves a point itself. Idempotent through public.programme_switch_operations_v314.';

--
-- Name: set_sale_policy(uuid, text, boolean, boolean, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_sale_policy(p_business uuid, p_kind text, p_counts_as_revenue boolean, p_counts_as_visit boolean, p_earns_points boolean, p_note text DEFAULT NULL::text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_row record;
begin
  if not app.has_perm(p_business, 'manage_sale_policy') then
    raise exception 'only an owner may change sale accounting policy';
  end if;
  if not exists (select 1 from app.sale_policy_defaults() d where d.kind = p_kind) then
    raise exception 'unknown sale kind: %', p_kind;
  end if;
  insert into sale_policies (business_id, kind, counts_as_revenue, counts_as_visit,
                             earns_points, note)
  values (p_business, p_kind, p_counts_as_revenue, p_counts_as_visit, p_earns_points, p_note)
  on conflict (business_id, kind) do update
    set counts_as_revenue = excluded.counts_as_revenue,
        counts_as_visit   = excluded.counts_as_visit,
        earns_points      = excluded.earns_points,
        note              = excluded.note,
        updated_at        = now();
  select * into v_row from app.sale_policy(p_business, p_kind);
  return row_to_json(v_row);
end $$;

--
-- Name: set_staff_capability_v404(uuid, uuid, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_staff_capability_v404(p_business uuid, p_staff uuid, p_capability text, p_enabled boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_actor_role text;
  v_target public.staff%rowtype;
  v_after text[];
begin
  if v_actor is null then
    raise exception 'authenticated staff required' using errcode='42501';
  end if;
  -- Only the two roles the owner named may hand this out.
  select s.role into v_actor_role from public.staff s
   where s.business_id=p_business and s.user_id=v_actor and s.active
   order by case when s.role='owner' then 0 else 1 end, s.created_at limit 1;
  if v_actor_role is null or app.role_class(v_actor_role) not in ('owner','admin') then
    raise exception 'only an owner or manager may change staff capabilities' using errcode='42501';
  end if;
  -- One capability exists today. A whitelist, not free text, so this can never
  -- become a way to invent permissions the rest of the schema does not check.
  if p_capability is distinct from 'manual_reward_redemption' then
    raise exception 'unknown capability' using errcode='22023';
  end if;

  select * into v_target from public.staff
   where id=p_staff and business_id=p_business for update;
  if not found then
    raise exception 'staff member not found in this business' using errcode='42704';
  end if;
  -- An owner already holds this by role; letting it be written onto an owner row
  -- would imply it could also be taken away, which it cannot.
  if v_target.role='owner' then
    raise exception 'an owner already holds every capability' using errcode='22023';
  end if;

  v_after := case
    when coalesce(p_enabled,false)
      then (select array(select distinct unnest(coalesce(v_target.capabilities,'{}'::text[]) || array[p_capability])))
    else (select array(select unnest(coalesce(v_target.capabilities,'{}'::text[])) except select p_capability))
  end;
  update public.staff set capabilities=v_after where id=p_staff;

  insert into public.audit_log(id,business_id,actor,action,entity,entity_id,detail)
  values (gen_random_uuid(), p_business, v_actor,
          case when coalesce(p_enabled,false) then 'capability.granted' else 'capability.revoked' end,
          'staff', p_staff,
          jsonb_build_object('capability',p_capability,'enabled',coalesce(p_enabled,false),
                             'capabilities_after',to_jsonb(v_after)));

  return jsonb_build_object('status','ok','staff_id',p_staff,'capabilities',to_jsonb(v_after));
end
$$;

--
-- Name: set_staff_module_permissions_v74(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_staff_module_permissions_v74(p_staff uuid, p_module_perms jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_target public.staff%rowtype;
  v_enabled_modules text[];
  v_new_modules text[];
  v_permission_closure text[];
  v_resolved_perms jsonb;
  v_invalid_keys text[];
  v_invalid_values text[];
begin
  if v_actor is null then
    raise exception 'authenticated owner session is required'
      using errcode = '42501';
  end if;
  if p_staff is null then
    raise exception 'staff member is required' using errcode = '22023';
  end if;
  if not exists (
    select 1
      from public.staff actor_staff
     where actor_staff.user_id = v_actor
       and actor_staff.role = 'owner'
       and actor_staff.active
  ) then
    raise exception 'owner role is required' using errcode = '42501';
  end if;

  select target.* into v_target
    from public.staff target
   where target.id = p_staff
     and target.active
     and exists (
       select 1
         from public.staff owner_staff
        where owner_staff.business_id = target.business_id
          and owner_staff.user_id = v_actor
          and owner_staff.role = 'owner'
          and owner_staff.active
     )
   for update;
  if not found then
    raise exception 'active staff member was not found in an owned business'
      using errcode = '22023';
  end if;

  perform app.require_workspace_open_v173(v_target.business_id);

  if v_target.role = 'owner' then
    raise exception 'the owner cannot be module-restricted'
      using errcode = '22023';
  end if;
  if v_target.role not in ('manager', 'staff', 'frontdesk', 'bookkeeper') then
    raise exception 'target staff role is invalid' using errcode = '22023';
  end if;

  select business.enabled_modules into v_enabled_modules
    from public.businesses business
   where business.id = v_target.business_id
   for share;
  if not found then
    raise exception 'staff business was not found' using errcode = '22023';
  end if;

  if p_module_perms is not null then
    if jsonb_typeof(p_module_perms) <> 'object' then
      raise exception 'module permissions must be an object or SQL NULL'
        using errcode = '22023';
    end if;

    select array_agg(entry.key order by entry.key)
      into v_invalid_values
      from jsonb_each(p_module_perms) entry
     where jsonb_typeof(entry.value) <> 'string'
        or entry.value #>> '{}' not in ('r', 'rw');
    if coalesce(cardinality(v_invalid_values), 0) > 0 then
      raise exception 'module permission values must be r or rw: %',
        array_to_string(v_invalid_values, ', ')
        using errcode = '22023';
    end if;

    select array_agg(key_row.module_key order by key_row.module_key)
      into v_invalid_keys
      from jsonb_object_keys(p_module_perms) key_row(module_key)
      left join public.module_registry registry
        on registry.module_key = key_row.module_key
     where registry.module_key is null
        or not (key_row.module_key = any(coalesce(v_enabled_modules, '{}'::text[])))
        or key_row.module_key in ('branches', 'settings', 'setup');
    if coalesce(cardinality(v_invalid_keys), 0) > 0 then
      raise exception 'module keys are not currently enabled and assignable: %',
        array_to_string(v_invalid_keys, ', ')
        using errcode = '22023';
    end if;

    -- Resolve required (not recommended) dependencies. Missing dependencies
    -- receive read access; an explicitly requested rw mode always wins.
    with recursive permission_closure(module_key) as (
      select requested.module_key
        from jsonb_object_keys(p_module_perms) requested(module_key)
      union
      select dependency.module_key
        from permission_closure current_key
        join public.module_registry registry
          on registry.module_key = current_key.module_key
        cross join lateral unnest(registry.requires_modules) dependency(module_key)
    )
    select coalesce(
      array_agg(permission_closure.module_key order by permission_closure.module_key),
      '{}'::text[]
    ) into v_permission_closure
      from permission_closure;

    select array_agg(module_key order by module_key)
      into v_invalid_keys
      from unnest(v_permission_closure) module_key
     where not (module_key = any(coalesce(v_enabled_modules, '{}'::text[])))
        or module_key in ('branches', 'settings', 'setup');
    if coalesce(cardinality(v_invalid_keys), 0) > 0 then
      raise exception 'required module dependencies are not currently enabled and assignable: %',
        array_to_string(v_invalid_keys, ', ')
        using errcode = '22023';
    end if;

    if (
         'expenses' = any(v_permission_closure)
         or 'pnl' = any(v_permission_closure)
       )
       and not ('view_finance' = any(app.role_perms(v_target.role))) then
      raise exception 'expenses and pnl require a finance-capable staff role'
        using errcode = '22023';
    end if;

    select coalesce(
      jsonb_object_agg(
        module_key,
        coalesce(p_module_perms ->> module_key, 'r')
      ),
      '{}'::jsonb
    ) into v_resolved_perms
      from unnest(v_permission_closure) module_key;
    v_new_modules := v_permission_closure;
  else
    -- SQL NULL restores the legacy all-enabled inheritance contract.
    v_resolved_perms := null;
    v_new_modules := null;
  end if;

  update public.staff
     set module_perms = v_resolved_perms,
         modules = v_new_modules
   where id = v_target.id
     and business_id = v_target.business_id;

  insert into public.audit_log(
    business_id, actor, action, entity, entity_id, detail
  ) values (
    v_target.business_id, v_actor, 'STAFF_MODULE_PERMISSIONS_SET_V74',
    'staff', v_target.id,
    jsonb_build_object(
      'prior_module_perms', v_target.module_perms,
      'new_module_perms', v_resolved_perms,
      'prior_modules', to_jsonb(v_target.modules),
      'new_modules', to_jsonb(v_new_modules)
    )
  );

  return jsonb_build_object(
    'staff_id', v_target.id,
    'module_perms', v_resolved_perms,
    'modules', to_jsonb(v_new_modules)
  );
end
$$;

--
-- Name: set_staff_modules(uuid, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_staff_modules(p_staff uuid, p_modules text[]) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_module_perms jsonb;
  v_staff public.staff%rowtype;
begin
  if p_modules is null then
    v_module_perms := null;
  else
    if array_position(p_modules, null) is not null then
      raise exception 'legacy module list cannot contain NULL'
        using errcode = '22023';
    end if;
    select coalesce(
      jsonb_object_agg(module_name, 'rw'::text order by module_name),
      '{}'::jsonb
    ) into v_module_perms
      from (
        select distinct requested_module as module_name
          from unnest(p_modules) requested_module
      ) requested;
  end if;

  perform public.set_staff_module_permissions_v74(p_staff, v_module_perms);
  select staff_row.* into strict v_staff
    from public.staff staff_row
   where staff_row.id = p_staff;
  return row_to_json(v_staff);
end
$$;

--
-- Name: set_staff_role_v74(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_staff_role_v74(p_staff uuid, p_role text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_target public.staff%rowtype;
  v_new_module_perms jsonb;
  v_new_modules text[];
begin
  if v_actor is null then
    raise exception 'authenticated owner session is required'
      using errcode = '42501';
  end if;
  if p_staff is null then
    raise exception 'staff member is required' using errcode = '22023';
  end if;
  if p_role is null
     or p_role not in ('manager', 'staff', 'frontdesk', 'bookkeeper') then
    raise exception 'staff role must be manager, staff, frontdesk, or bookkeeper'
      using errcode = '22023';
  end if;
  if not exists (
    select 1
      from public.staff actor_staff
     where actor_staff.user_id = v_actor
       and actor_staff.role = 'owner'
       and actor_staff.active
  ) then
    raise exception 'owner role is required' using errcode = '42501';
  end if;

  select target.* into v_target
    from public.staff target
   where target.id = p_staff
     and target.active
     and exists (
       select 1
         from public.staff owner_staff
        where owner_staff.business_id = target.business_id
          and owner_staff.user_id = v_actor
          and owner_staff.role = 'owner'
          and owner_staff.active
     )
   for update;
  if not found then
    raise exception 'active staff member was not found in an owned business'
      using errcode = '22023';
  end if;

  perform app.require_workspace_open_v173(v_target.business_id);

  if v_target.role = 'owner' then
    raise exception 'the owner role cannot be changed here'
      using errcode = '22023';
  end if;
  if v_target.role not in ('manager', 'staff', 'frontdesk', 'bookkeeper') then
    raise exception 'target staff role is invalid' using errcode = '22023';
  end if;

  v_new_module_perms := v_target.module_perms;
  v_new_modules := v_target.modules;
  if not ('view_finance' = any(app.role_perms(p_role))) then
    if v_new_module_perms is not null then
      v_new_module_perms := v_new_module_perms - 'expenses' - 'pnl';
      select coalesce(array_agg(key_row.module_key order by key_row.module_key), '{}'::text[])
        into v_new_modules
        from jsonb_object_keys(v_new_module_perms) key_row(module_key);
    elsif v_new_modules is not null then
      select coalesce(array_agg(module_name order by module_name), '{}'::text[])
        into v_new_modules
        from unnest(v_new_modules) module_name
       where module_name not in ('expenses', 'pnl');
    end if;
  end if;

  update public.staff
     set role = p_role,
         module_perms = v_new_module_perms,
         modules = v_new_modules
   where id = v_target.id
     and business_id = v_target.business_id;

  insert into public.audit_log(
    business_id, actor, action, entity, entity_id, detail
  ) values (
    v_target.business_id, v_actor, 'STAFF_ROLE_SET_V74',
    'staff', v_target.id,
    jsonb_build_object(
      'prior_role', v_target.role,
      'new_role', p_role,
      'prior_module_perms', v_target.module_perms,
      'new_module_perms', v_new_module_perms,
      'prior_modules', to_jsonb(v_target.modules),
      'new_modules', to_jsonb(v_new_modules)
    )
  );

  return jsonb_build_object(
    'staff_id', v_target.id,
    'role', p_role,
    'module_perms', v_new_module_perms,
    'modules', to_jsonb(v_new_modules)
  );
end
$$;

--
-- Name: set_studio_rule_active(uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_studio_rule_active(p_business uuid, p_rule_id uuid, p_active boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_active_cfg uuid; v_current boolean; v_draft uuid; v_pub jsonb; v_new uuid;
begin
  if not app.is_salon_owner(p_business) then raise exception 'owner only' using errcode = '42501'; end if;
  if p_active is null then raise exception 'p_active is required' using errcode = '22023'; end if;
  select active_config_version_id into v_active_cfg from public.businesses where id = p_business;
  if v_active_cfg is null then raise exception 'no active published configuration' using errcode = '22023'; end if;
  select active into v_current from public.program_rules
   where rule_id = p_rule_id and config_version_id = v_active_cfg and business_id = p_business;
  if not found then raise exception 'program rule not found in the active configuration' using errcode = '42501'; end if;
  if v_current = p_active then
    return jsonb_build_object('status', 'ok', 'rule_id', p_rule_id, 'active', p_active,
      'changed', false, 'config_version_id', v_active_cfg);
  end if;

  v_draft := (public.create_loyalty_config_draft(p_business, v_active_cfg, 'studio_rule_active_set')::jsonb->>'version_id')::uuid;
  update public.program_rules set active = p_active
   where rule_id = p_rule_id and config_version_id = v_draft and business_id = p_business;
  if not found then raise exception 'cloned draft did not contain the target rule' using errcode = 'XX001'; end if;
  perform app.refresh_loyalty_config_snapshot(v_draft);
  v_pub := public.publish_loyalty_config(v_draft)::jsonb;
  v_new := (v_pub->>'version_id')::uuid;
  insert into public.audit_log(business_id, actor, action, entity, entity_id, detail)
  values(p_business, auth.uid(), 'STUDIO_RULE_ACTIVE_SET', 'program_rules', p_rule_id,
    jsonb_build_object('rule_id', p_rule_id, 'active', p_active, 'from_config', v_active_cfg, 'new_config', v_new));
  return jsonb_build_object('status', 'ok', 'rule_id', p_rule_id, 'active', p_active,
    'changed', true, 'config_version_id', v_new);
end $$;

--
-- Name: set_sv_authority_state(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_sv_authority_state(p_business uuid, p_asset text, p_state text, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_asset text := coalesce(p_asset, 'stored_value');
  v_new text;
begin
  if not app.is_salon_owner(p_business) then
    raise exception 'owner only' using errcode = '42501';
  end if;
  -- HARD CHECK: the only nameable states are the safe subset. 'live'/'ready_for_cutover' are
  -- unreachable - this RPC cannot set them, they raise 22023.
  if p_state is null or p_state not in ('unbuilt', 'shadow_testing', 'reconciliation_blocked') then
    raise exception 'stored-value authority state must be one of unbuilt/shadow_testing/reconciliation_blocked (cutover states are unreachable in PS-2A)'
      using errcode = '22023';
  end if;
  v_new := app.sv_apply_authority_state(p_business, v_asset, p_state, p_reason, v_actor);
  return jsonb_build_object('status', 'ok', 'business_id', p_business, 'asset', v_asset, 'state', v_new);
end $$;

--
-- Name: set_sv_cutover_designation(uuid, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_sv_cutover_designation(p_business uuid, p_designated boolean, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_reason text := btrim(coalesce(p_reason, ''));
  v_existing public.sv_cutover_designations%rowtype;
  v_id uuid;
begin
  if not app.is_super_admin() then
    raise exception 'super admin only: a business cannot designate itself for stored-value cutover'
      using errcode = '42501';
  end if;
  if char_length(v_reason) < 10 then
    raise exception 'a stored-value cutover designation requires a reason of at least 10 characters'
      using errcode = '22023';
  end if;
  if not exists (select 1 from public.businesses b where b.id = p_business) then
    raise exception 'business not found' using errcode = '22023';
  end if;
  if coalesce(p_designated, false) and coalesce(
       (select b.is_synthetic from public.businesses b where b.id = p_business), false) then
    raise exception 'sv_synthetic_business: a synthetic business may never be designated for cutover'
      using errcode = '22023';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('v69:sv_designation', 0));
  select * into v_existing from public.sv_cutover_designations
   where business_id = p_business and asset = 'stored_value' and revoked_at is null
   for update;

  if coalesce(p_designated, false) then
    if found then
      return jsonb_build_object('status', 'ok', 'business_id', p_business, 'designated', true,
        'designation_id', v_existing.id, 'unchanged', true);
    end if;
    -- rev-2, review D2: the designation singleton (sv_cutover_designations_singleton_uk) allows at
    -- most one active designation platform-wide. Rather than let a second concurrent designation hit
    -- a raw 23505, pre-check it under the global advisory lock already held above and raise a typed
    -- error the caller can act on. (This bounds concurrent DESIGNATIONS; the one-live-business
    -- mandate is enforced separately on the authority - see §10a / sv_pilot_already_live.)
    if exists (
      select 1 from public.sv_cutover_designations d
       where d.asset = 'stored_value' and d.revoked_at is null and d.business_id <> p_business)
    then
      raise exception 'sv_pilot_already_designated: another business is already designated for stored-value cutover; revoke it first'
        using errcode = '22023';
    end if;
    insert into public.sv_cutover_designations(business_id, asset, designated_by, reason)
    values (p_business, 'stored_value', v_actor, v_reason)
    returning id into v_id;
    insert into public.audit_log(business_id, actor, action, entity, entity_id, detail)
    values (p_business, v_actor, 'SV_CUTOVER_DESIGNATED', 'sv_cutover_designations', v_id,
      jsonb_build_object('reason', v_reason));
    return jsonb_build_object('status', 'ok', 'business_id', p_business, 'designated', true,
      'designation_id', v_id, 'unchanged', false);
  end if;

  if not found then
    return jsonb_build_object('status', 'ok', 'business_id', p_business, 'designated', false,
      'designation_id', null, 'unchanged', true);
  end if;
  update public.sv_cutover_designations
     set revoked_at = now(), revoked_by = v_actor
   where id = v_existing.id;
  insert into public.audit_log(business_id, actor, action, entity, entity_id, detail)
  values (p_business, v_actor, 'SV_CUTOVER_DESIGNATION_REVOKED', 'sv_cutover_designations',
    v_existing.id, jsonb_build_object('reason', v_reason));
  return jsonb_build_object('status', 'ok', 'business_id', p_business, 'designated', false,
    'designation_id', v_existing.id, 'unchanged', false);
end $$;

--
-- Name: set_sv_plan_guardrails(uuid, integer, integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_sv_plan_guardrails(p_business uuid, p_warn_bps integer, p_hard_bps integer, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_hash text; v_hit jsonb; v_result jsonb;
begin
  if not app.is_salon_owner(p_business) then raise exception 'owner only' using errcode = '42501'; end if;
  if p_warn_bps is null or p_hard_bps is null or p_warn_bps < 0 or p_hard_bps > 10000 or p_warn_bps > p_hard_bps then
    raise exception 'guardrails require 0 <= warn_discount_bps <= hard_discount_bps <= 10000' using errcode = '22023';
  end if;
  v_hash := app.ps1b_sha256(jsonb_build_object('op','guardrails','business',p_business,'warn',p_warn_bps,'hard',p_hard_bps)::text);
  v_hit := app.sv_plan_idem_lookup(p_business, 'guardrails', p_idempotency_key, v_hash);
  if v_hit is not null then return v_hit; end if;

  insert into public.sv_plan_guardrails(business_id, warn_discount_bps, hard_discount_bps, updated_at)
  values (p_business, p_warn_bps, p_hard_bps, now())
  on conflict (business_id) do update set warn_discount_bps = excluded.warn_discount_bps,
    hard_discount_bps = excluded.hard_discount_bps, updated_at = now();

  v_result := jsonb_build_object('status','ok','business_id',p_business,'warn_discount_bps',p_warn_bps,'hard_discount_bps',p_hard_bps);
  insert into public.sv_plan_operations(business_id, op_type, idempotency_key, request_hash, actor, result)
  values (p_business, 'guardrails', p_idempotency_key, v_hash, v_actor, v_result);
  insert into public.audit_log(business_id, actor, action, entity, entity_id, detail)
  values (p_business, v_actor, 'SV_PLAN_GUARDRAILS_SET', 'sv_plan_guardrails', p_business,
    jsonb_build_object('warn_discount_bps',p_warn_bps,'hard_discount_bps',p_hard_bps));
  return v_result;
end $$;

--
-- Name: set_synthetic_marker(uuid, uuid, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_synthetic_marker(p_business uuid, p_client uuid, p_is_synthetic boolean, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_actor uuid := auth.uid(); v_reason text := nullif(btrim(coalesce(p_reason,'')),'');
begin
  if not app.is_super_admin() then raise exception 'super-admin only' using errcode = '42501'; end if;
  if v_reason is null or char_length(v_reason) < 3 then raise exception 'a reason of at least 3 characters is required' using errcode = '22023'; end if;
  if p_client is null then
    update public.businesses set is_synthetic = p_is_synthetic where id = p_business;
    if not found then raise exception 'business not found' using errcode = '22023'; end if;
  else
    update public.clients set is_synthetic = p_is_synthetic where id = p_client and business_id = p_business;
    if not found then raise exception 'client not found in business' using errcode = '22023'; end if;
  end if;
  insert into public.audit_log(business_id, actor, action, entity, entity_id, detail)
  values (p_business, v_actor, 'SV_SYNTHETIC_MARKER_SET', case when p_client is null then 'businesses' else 'clients' end,
    coalesce(p_client, p_business), jsonb_build_object('is_synthetic', p_is_synthetic, 'reason', v_reason));
  return jsonb_build_object('status','ok','business_id',p_business,'client_id',p_client,'is_synthetic',p_is_synthetic);
end $$;

--
-- Name: set_workspace_locale_preference_v97(text, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_workspace_locale_preference_v97(p_locale text, p_expected_version bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_user uuid:=auth.uid();
  v_row public.workspace_locale_preferences_v97%rowtype;
begin
  if v_user is null then
    raise exception using errcode='42501',message='authentication required';
  end if;
  if p_locale is null or p_locale not in ('en','zh-CN','ms')
     or p_expected_version is null or p_expected_version < 0 then
    raise exception using errcode='22023',message='invalid locale preference';
  end if;

  insert into public.workspace_locale_preferences_v97(
    auth_user_id,locale,version,updated_at
  ) values(v_user,p_locale,1,now())
  on conflict(auth_user_id) do update
    set locale=excluded.locale,
        version=public.workspace_locale_preferences_v97.version+1,
        updated_at=now()
    where public.workspace_locale_preferences_v97.version=p_expected_version
  returning * into v_row;

  if v_row.auth_user_id is null then
    raise exception using errcode='40001',message='workspace locale preference changed; refresh and retry';
  end if;
  if p_expected_version<>0 and v_row.version<>p_expected_version+1 then
    raise exception using errcode='40001',message='workspace locale preference changed; refresh and retry';
  end if;
  return jsonb_build_object('locale',v_row.locale,'version',v_row.version);
end
$$;

--
-- Name: staff_create_client(uuid, uuid, text, text, text, date, text, boolean, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.staff_create_client(p_business uuid, p_idempotency_key uuid, p_full_name text, p_phone text DEFAULT NULL::text, p_email text DEFAULT NULL::text, p_birth_date date DEFAULT NULL::date, p_gender text DEFAULT NULL::text, p_marketing_consent boolean DEFAULT false, p_referrer_code text DEFAULT NULL::text, p_source text DEFAULT 'staff customer form'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_staff uuid;
  v_name text := nullif(btrim(p_full_name), '');
  v_phone text := nullif(btrim(p_phone), '');
  v_email text := nullif(lower(btrim(p_email)), '');
  v_gender text := nullif(lower(btrim(p_gender)), '');
  v_referrer_code text := nullif(upper(btrim(p_referrer_code)), '');
  v_source text := coalesce(nullif(btrim(p_source), ''), 'staff customer form');
  v_payload jsonb;
  v_hash text;
  v_existing public.customer_staff_operations%rowtype;
  v_client public.clients%rowtype;
  v_consent_id uuid;
  v_referrer uuid;
  v_referral_id uuid;
  v_result jsonb;
begin
  if v_actor is null or not app.can_module_write(p_business, 'clients') then
    raise exception 'active clients-module write authorization is required'
      using errcode = '42501';
  end if;
  if v_referrer_code is not null
     and not app.can_module_write(p_business, 'referrals') then
    raise exception 'active referrals-module write authorization is required for referral links'
      using errcode = '42501';
  end if;
  select s.id into v_staff
    from public.staff s
   where s.business_id = p_business
     and s.user_id = v_actor
     and s.active
   order by case when s.role = 'owner' then 0 else 1 end, s.created_at
   limit 1
   for update;
  if not found then
    raise exception 'active staff authorization is required'
      using errcode = '42501';
  end if;
  if p_idempotency_key is null or v_name is null or char_length(v_name) < 2
     or char_length(v_name) > 200
     or (v_gender is not null and v_gender not in ('female', 'male', 'other'))
     or (v_phone is not null and char_length(v_phone) > 80)
     or (v_email is not null and char_length(v_email) > 320)
     or char_length(v_source) > 200 then
    raise exception 'invalid customer request' using errcode = '22023';
  end if;

  v_payload := jsonb_build_object(
    'birth_date', p_birth_date,
    'business_id', p_business,
    'email', v_email,
    'full_name', v_name,
    'gender', v_gender,
    'marketing_consent', coalesce(p_marketing_consent, false),
    'phone', v_phone,
    'referrer_code', v_referrer_code,
    'source', v_source
  );
  v_hash := app.v41_request_hash(v_payload::text);
  perform pg_advisory_xact_lock(hashtextextended(
    'v41:customer:' || p_business::text || ':' || p_idempotency_key::text, 0));

  select * into v_existing
    from public.customer_staff_operations o
   where o.business_id = p_business
     and o.idempotency_key = p_idempotency_key
   for update;
  if found then
    if v_existing.actor is distinct from v_actor
       or v_existing.operation_type <> 'create_client'
       or v_existing.request_hash <> v_hash then
      raise exception 'idempotency key conflicts with another customer request'
        using errcode = '23505';
    end if;
    return jsonb_build_object(
      'status', 'completed',
      'client_id', v_existing.client_id,
      'marketing_consent', v_existing.requested_marketing_consent,
      'consent_event_id', v_existing.consent_event_id,
      'referral_id', v_existing.referral_id
    );
  end if;

  insert into public.clients (
    business_id, full_name, phone, email, birth_date, gender, marketing_consent
  ) values (
    p_business, v_name, v_phone, v_email, p_birth_date, v_gender,
    coalesce(p_marketing_consent, false)
  ) returning * into v_client;

  insert into public.consents (
    business_id, client_id, channel, action, source, actor
  ) values (
    p_business, v_client.id, 'marketing',
    case when coalesce(p_marketing_consent, false) then 'granted' else 'withdrawn' end,
    v_source, v_actor
  ) returning id into v_consent_id;

  if v_referrer_code is not null then
    select c.id into v_referrer
      from public.clients c
     where c.business_id = p_business
       and c.referral_code = v_referrer_code
     limit 1
     for share;
    if not found or v_referrer = v_client.id then
      raise exception 'referrer code does not belong to this business'
        using errcode = '22023';
    end if;
    insert into public.referrals (
      business_id, referrer_client_id, referred_client_id, status
    ) values (
      p_business, v_referrer, v_client.id, 'pending'
    ) returning id into v_referral_id;
  end if;

  v_result := jsonb_build_object(
    'status', 'completed',
    'client_id', v_client.id,
    'marketing_consent', v_client.marketing_consent,
    'consent_event_id', v_consent_id,
    'referral_id', v_referral_id
  );
  insert into public.customer_staff_operations (
    business_id, actor, operation_type, idempotency_key, request_hash, status,
    requested_marketing_consent, client_id, consent_event_id, referral_id
  ) values (
    p_business, v_actor, 'create_client', p_idempotency_key, v_hash, 'completed',
    v_client.marketing_consent, v_client.id, v_consent_id, v_referral_id
  );
  return v_result;
end
$$;

--
-- Name: staff_customer_bucket_counts_v290(uuid, text, text, uuid[], uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.staff_customer_bucket_counts_v290(p_business uuid, p_search text DEFAULT NULL::text, p_scope_mode text DEFAULT 'all'::text, p_branch_ids uuid[] DEFAULT ARRAY[]::uuid[], p_operational_branch uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_as_of timestamptz := statement_timestamp();
  v_search text := lower(btrim(coalesce(p_search,'')));
  v_phone_search text := regexp_replace(coalesce(p_search,''),'[^0-9]','','g');
  v_scope_ids uuid[];
  v_scope_label text;
  v_scope_is_whole_business boolean := false;
  v_result jsonb;
begin
  if length(v_phone_search)=10 and left(v_phone_search,2)='65' then
    v_phone_search := right(v_phone_search,8);
  end if;
  if auth.uid() is null or not app.can_module_read(p_business,'clients') then
    raise exception 'customer read access required' using errcode='42501';
  end if;

  select coalesce(array_agg(scope.branch_id order by scope.branch_name),array[]::uuid[])
    into v_scope_ids
  from app.resolve_reporting_branch_scope_v155(
    p_business,p_scope_mode,p_branch_ids,p_operational_branch
  ) scope;
  v_scope_label := app.reporting_scope_label_v155(
    p_business,p_scope_mode,p_branch_ids,p_operational_branch
  );
  select not exists(
    select 1
    from public.branches branch
    where branch.business_id = p_business
      and coalesce(branch.active,true)
      and not (branch.id = any(v_scope_ids))
  ) into v_scope_is_whole_business;

  with visit_facts as materialized (
    select sale.client_id,max(sale.occurred_at) as last_visit_at
    from public.sales sale
    where sale.business_id = p_business
      and sale.client_id is not null
      and sale.counts_as_visit
      and sale.reversal_of is null
      and sale.occurred_at <= v_as_of
      and sale.branch_id = any(v_scope_ids)
      and not exists(
        select 1 from public.sales reversal
        where reversal.business_id = sale.business_id
          and reversal.reversal_of = sale.id
          and reversal.created_at <= v_as_of
      )
    group by sale.client_id
  ), customer_scope as materialized (
    select distinct sale.client_id
    from public.sales sale
    where sale.business_id = p_business
      and sale.client_id is not null
      and sale.counts_as_visit
      and sale.reversal_of is null
      and sale.branch_id = any(v_scope_ids)
  ), customer_rows as materialized (
    select customer.id,
      case when visit.last_visit_at is null then null
        else ((v_as_of at time zone 'Asia/Singapore')::date-
          (visit.last_visit_at at time zone 'Asia/Singapore')::date)::integer
      end as days_since_last_visit
    from public.clients customer
    left join visit_facts visit on visit.client_id = customer.id
    where customer.business_id = p_business
      and (
        v_scope_is_whole_business
        or exists(select 1 from customer_scope scoped where scoped.client_id = customer.id)
      )
      and (
        v_search = ''
        or position(v_search in lower(customer.full_name)) > 0
        or (length(v_phone_search) >= 4 and
          position(v_phone_search in coalesce(customer.phone_norm,'')) > 0)
      )
  )
  select jsonb_build_object(
    'status','ok',
    'as_of',v_as_of,
    'scope',jsonb_build_object(
      'mode',coalesce(p_scope_mode,'all'),
      'label',v_scope_label,
      'branch_ids',to_jsonb(v_scope_ids),
      'whole_business',v_scope_is_whole_business
    ),
    'counts',jsonb_build_object(
      '30_59',count(*) filter (
        where days_since_last_visit between 30 and 59),
      '60_89',count(*) filter (
        where days_since_last_visit between 60 and 89),
      '90_plus',count(*) filter (
        where days_since_last_visit >= 90),
      'all_inactive',count(*) filter (
        where days_since_last_visit >= 30),
      'never',count(*) filter (
        where v_scope_is_whole_business and days_since_last_visit is null),
      'active',count(*) filter (
        where days_since_last_visit is not null and days_since_last_visit < 30),
      'total',count(*)
    )
  ) into v_result
  from customer_rows;

  return v_result;
end
$$;

--
-- Name: staff_decide_booking_request_v73(uuid, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.staff_decide_booking_request_v73(p_business uuid, p_request uuid, p_decision text, p_branch uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_branch uuid;
  v_customer_branch uuid;
begin
  if p_branch is null then
    select request.branch_id into v_customer_branch
      from public.booking_requests request
     where request.id=p_request and request.business_id=p_business;
  end if;
  v_branch:=app.require_branch_module_v94(
    p_business,coalesce(p_branch,v_customer_branch),'bookings','rw'
  );
  if p_decision='confirm' then
    perform app.require_branch_module_v94(
      p_business,v_branch,'appointments','rw'
    );
  end if;
  return public.staff_decide_booking_request_v73_v94_base(
    p_business,p_request,p_decision,v_branch
  );
end
$$;

--
-- Name: staff_decide_booking_request_v73_v94_base(uuid, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.staff_decide_booking_request_v73_v94_base(p_business uuid, p_request uuid, p_decision text, p_branch uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_request public.booking_requests%rowtype;
  v_waitlist public.waitlist%rowtype;
  v_appointment public.appointments%rowtype;
  v_client uuid;
  v_branch uuid;
  v_staff uuid;
  v_duration integer;
  v_available integer;
  v_booking jsonb;
begin
  if p_business is null or p_request is null or p_decision is null
     or p_decision not in ('confirm', 'decline') then
    raise exception 'invalid booking decision request' using errcode = '22023';
  end if;
  if v_actor is null then
    raise exception 'authenticated staff session is required' using errcode = '42501';
  end if;

  -- This is the natural idempotency lock. Every later lock follows it.
  select request.* into v_request
    from public.booking_requests request
   where request.id = p_request
     and request.business_id = p_business
   for update;
  if not found then
    raise exception 'booking request not found' using errcode = '22023';
  end if;

  select waitlist_row.* into v_waitlist
    from public.waitlist waitlist_row
   where waitlist_row.booking_request_id = p_request
     and waitlist_row.business_id = p_business
   for update;

  if p_decision = 'decline' then
    if not app.can_module_write(p_business, 'bookings') then
      raise exception 'booking write access is required' using errcode = '42501';
    end if;
    if v_request.status = 'declined' then
      return app.booking_decision_result_v73(
        p_business, p_request, p_decision, 'replayed', true
      );
    end if;
    if v_request.status in ('confirmed', 'expired', 'cancelled') then
      return app.booking_decision_result_v73(
        p_business, p_request, p_decision, 'terminal_conflict', false
      );
    end if;
    if v_request.status not in ('new', 'pending', 'waitlisted') then
      return app.booking_decision_result_v73(
        p_business, p_request, p_decision, 'state_conflict', false
      );
    end if;
    if (v_request.status = 'waitlisted' and v_waitlist.id is null)
       or (v_waitlist.id is not null
           and v_waitlist.status not in ('waiting', 'contacted')) then
      return app.booking_decision_result_v73(
        p_business, p_request, p_decision, 'waitlist_conflict', false
      );
    end if;

    update public.booking_requests
       set status = 'declined',
           expires_at = null
     where id = p_request
       and business_id = p_business;
    if v_waitlist.id is not null then
      update public.waitlist
         set status = 'removed'
       where id = v_waitlist.id
         and business_id = p_business;
    end if;
    insert into public.audit_log(
      business_id, actor, action, entity, entity_id, detail
    ) values (
      p_business, v_actor, 'BOOKING_REQUEST_DECISION_V73',
      'booking_requests', p_request,
      jsonb_build_object(
        'decision', 'decline',
        'from_status', v_request.status,
        'to_status', 'declined',
        'waitlist_id', v_waitlist.id
      )
    );
    return app.booking_decision_result_v73(
      p_business, p_request, p_decision, 'applied', false
    );
  end if;

  -- Confirm always requires the appointments write boundary as well.
  if not app.can_module_write(p_business, 'appointments') then
    raise exception 'appointment write access is required' using errcode = '42501';
  end if;

  if v_request.status = 'confirmed' then
    select appointment.* into v_appointment
      from public.appointments appointment
     where appointment.id = v_request.appointment_id
       and appointment.business_id = p_business;
    if not found or v_appointment.branch_id is null
       or not app.can_see_branch(p_business, v_appointment.branch_id) then
      return app.booking_decision_result_v73(
        p_business, p_request, p_decision, 'terminal_conflict', false
      );
    end if;
    return app.booking_decision_result_v73(
      p_business, p_request, p_decision, 'replayed', true
    );
  end if;
  if v_request.status in ('declined', 'expired', 'cancelled') then
    return app.booking_decision_result_v73(
      p_business, p_request, p_decision, 'terminal_conflict', false
    );
  end if;
  if v_request.status not in ('new', 'pending', 'waitlisted') then
    return app.booking_decision_result_v73(
      p_business, p_request, p_decision, 'state_conflict', false
    );
  end if;
  if (v_request.status = 'waitlisted' and v_waitlist.id is null)
     or (v_waitlist.id is not null
         and v_waitlist.status not in ('waiting', 'contacted')) then
    return app.booking_decision_result_v73(
      p_business, p_request, p_decision, 'waitlist_conflict', false
    );
  end if;

  if p_branch is not null then
    select branch.id into v_branch
      from public.branches branch
     where branch.id = p_branch
       and branch.business_id = p_business
       and branch.active;
  else
    select branch.id into v_branch
      from public.branches branch
     where branch.business_id = p_business
       and branch.active
     order by branch.is_default desc, branch.created_at, branch.id
     limit 1;
  end if;
  if v_branch is null then
    raise exception 'an active booking branch is required' using errcode = '22023';
  end if;
  if not app.can_see_branch(p_business, v_branch) then
    raise exception 'appointment write access for this branch is required'
      using errcode = '42501';
  end if;

  -- v328: the CUSTOMER's staff choice (v183, booking_requests.staff_id) wins over round-robin
  -- when they made one. If that staff member is gone or was deactivated since the request came
  -- in, fall through to round-robin exactly as before, rather than failing the confirmation.
  if v_request.staff_id is not null then
    select member.id into v_staff
      from public.staff member
     where member.id = v_request.staff_id
       and member.business_id = p_business
       and coalesce(member.active, true);
  end if;

  -- Waitlisted table requests do not hold capacity. Serialize against the table
  -- type and re-read actual current availability before creating an appointment.
  if v_request.table_type_id is not null
     and (
       v_request.status = 'waitlisted'
       or (
         v_request.status = 'pending'
         and v_request.expires_at is not null
         and v_request.expires_at <= clock_timestamp()
       )
     ) then
    perform 1
      from public.booking_tables table_type
     where table_type.id = v_request.table_type_id
       and table_type.business_id = p_business
       and table_type.active
     for update;
    if not found then
      return app.booking_decision_result_v73(
        p_business, p_request, p_decision, 'capacity_conflict', false
      );
    end if;
    select greatest(
      table_type.quantity
      - (
        select count(*)::integer
          from public.booking_requests held_request
         where held_request.table_type_id = v_request.table_type_id
           and held_request.status in ('new', 'pending')
           and held_request.id <> p_request
           and (
             held_request.expires_at is null
             or held_request.expires_at > clock_timestamp()
           )
      )
      - (
        select count(*)::integer
          from public.appointments held_appointment
         where held_appointment.table_type_id = v_request.table_type_id
           and held_appointment.status = 'booked'
      ),
      0
    ) into v_available
      from public.booking_tables table_type
     where table_type.id = v_request.table_type_id
       and table_type.business_id = p_business;
    if coalesce(v_available, 0) <= 0 then
      return app.booking_decision_result_v73(
        p_business, p_request, p_decision, 'capacity_conflict', false
      );
    end if;
  end if;

  -- Keep guest client creation/consent inside a subtransaction. If scheduling
  -- conflicts, the exception handler rolls every tentative side effect back.
  begin
    if v_request.customer_client_id is not null then
      select client.id into v_client
        from public.clients client
       where client.id = v_request.customer_client_id
         and client.business_id = p_business;
      if not found then
        raise exception 'bound booking client is unavailable' using errcode = '23503';
      end if;
    else
      v_client := app.upsert_portal_client(
        p_business, v_request.name, v_request.phone, v_request.email
      );
      perform app.apply_booking_consent(
        p_business, v_client, v_request.marketing_consent
      );
    end if;

    select greatest(service.duration_min, 15) into v_duration
      from public.services service
     where service.id = v_request.service_id
       and service.business_id = p_business;
    v_duration := coalesce(v_duration, 60);

    v_booking := public.book_appointment_smart_v47(
      p_business, v_client, v_branch, v_request.service_id,
      coalesce(v_request.preferred_at, clock_timestamp() + interval '1 day'),
      v_duration, v_staff,
      case when v_staff is not null then 'manual' else 'round_robin' end,
      v_request.notes,
      'booking-request:' || p_request::text
    );
    if v_booking->>'status' = 'conflict' then
      raise exception 'v73 scheduling conflict' using errcode = 'P0731';
    end if;

    select appointment.* into v_appointment
      from public.appointments appointment
     where appointment.id = (v_booking->>'appointment_id')::uuid
       and appointment.business_id = p_business;
    if not found then
      raise exception 'scheduler returned no appointment' using errcode = 'P0001';
    end if;

    update public.appointments
       set party_size = v_request.party_size,
           source = 'portal',
           table_type_id = v_request.table_type_id
     where id = v_appointment.id
       and business_id = p_business
    returning * into v_appointment;

    update public.booking_requests
       set status = 'confirmed',
           appointment_id = v_appointment.id,
           expires_at = null
     where id = p_request
       and business_id = p_business;
    if v_waitlist.id is not null then
      update public.waitlist
         set status = 'booked'
       where id = v_waitlist.id
         and business_id = p_business;
    end if;

    insert into public.audit_log(
      business_id, actor, action, entity, entity_id, detail
    ) values (
      p_business, v_actor, 'BOOKING_REQUEST_DECISION_V73',
      'booking_requests', p_request,
      jsonb_build_object(
        'decision', 'confirm',
        'from_status', v_request.status,
        'to_status', 'confirmed',
        'appointment_id', v_appointment.id,
        'branch_id', v_branch,
        'staff_id', v_staff,
        'waitlist_id', v_waitlist.id
      )
    );
  exception
    when sqlstate 'P0731' or exclusion_violation then
      return app.booking_decision_result_v73(
        p_business, p_request, p_decision, 'scheduling_conflict', false
      );
  end;

  return app.booking_decision_result_v73(
    p_business, p_request, p_decision, 'applied', false
  );
end
$$;

--
-- Name: staff_get_client_credit_history(uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.staff_get_client_credit_history(p_business uuid, p_client uuid, p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_staff uuid;
  v_limit integer := least(greatest(coalesce(p_limit, 50), 1), 200);
  v_credit jsonb := '[]'::jsonb;
  v_cards jsonb := '[]'::jsonb;
begin
  if v_actor is null then
    raise exception 'authenticated staff required' using errcode = '42501';
  end if;
  if not app.can_module_read(p_business, 'clients')
     or not app.has_perm(p_business, 'view_finance') then
    raise exception 'active customers-module read and finance authorization is required'
      using errcode = '42501';
  end if;
  select s.id into v_staff
    from public.staff s
   where s.business_id = p_business
     and s.user_id = v_actor
     and s.active
     and 'view_finance' = any (app.role_perms(s.role))
   order by case when s.role = 'owner' then 0 else 1 end, s.created_at, s.id
   limit 1;
  if not found then
    raise exception 'active staff authorization is required' using errcode = '42501';
  end if;
  if not exists (
    select 1 from public.clients c where c.id = p_client and c.business_id = p_business
  ) then
    raise exception 'customer not found in this business' using errcode = '42501';
  end if;

  -- Raw in-store-credit movements for this customer, most recent first, bounded.
  select coalesce(jsonb_agg(jsonb_build_object(
    'entry_id', x.id,
    'entry_type', x.entry_type,
    'amount_cents', x.amount_cents,
    'reference', x.reference,
    'created_at', x.created_at
  ) order by x.created_at desc, x.id desc), '[]'::jsonb)
    into v_credit
    from (
      select cl.id, cl.entry_type, cl.amount_cents, cl.reference, cl.created_at
        from public.credit_ledger cl
       where cl.business_id = p_business
         and cl.client_id = p_client
       order by cl.created_at desc, cl.id desc
       limit v_limit
    ) x;

  -- Gift cards this customer purchased (bearer-safe: masked code suffix only).
  select coalesce(jsonb_agg(jsonb_build_object(
    'gift_card_id', y.id,
    'code_suffix', right(y.code, 4),
    'initial_cents', y.initial_cents,
    'balance_cents', y.balance_cents,
    'status', y.status,
    'created_at', y.created_at
  ) order by y.created_at desc, y.id desc), '[]'::jsonb)
    into v_cards
    from (
      select g.id, g.code, g.initial_cents, g.balance_cents, g.status, g.created_at
        from public.gift_cards g
       where g.business_id = p_business
         and g.purchaser_client_id = p_client
       order by g.created_at desc, g.id desc
       limit v_limit
    ) y;

  return jsonb_build_object(
    'status', 'ok',
    'client_id', p_client,
    'limit', v_limit,
    'credit_entries', v_credit,
    'credit_entry_count', jsonb_array_length(v_credit),
    'gift_cards', v_cards,
    'gift_card_count', jsonb_array_length(v_cards)
  );
end $$;

--
-- Name: staff_get_customer_actionable_loyalty_v145(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.staff_get_customer_actionable_loyalty_v145(p_business uuid, p_client uuid, p_branch uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_as_of timestamptz := statement_timestamp();
  v_result jsonb;
  -- v381: which pot this balance is, and whether this tenant's pots are safe to read per programme
  v_balance_scope text := app.programme_balance_scope_v312(p_business);
  v_live_programme uuid := app.live_balance_programme_v381(p_business);
begin
  perform public.require_module_scope_v145(
    p_business, p_branch, 'clients'
  );
  perform public.require_module_scope_v145(
    p_business, p_branch, 'loyalty'
  );
  if not exists (
    select 1
      from public.clients client
     where client.id = p_client
       and client.business_id = p_business
  ) then
    raise exception 'customer not found in business'
      using errcode = '22023';
  end if;

  with program as (
    select
      loyalty.id,
      loyalty.kind,
      loyalty.loyalty_model,
      loyalty.earn_points_per_dollar,
      loyalty.redeem_points,
      loyalty.reward_credit_cents,
      loyalty.stamp_per_cents,
      loyalty.expiry_mode,
      loyalty.configuration_status,
      coalesce(loyalty.active, false)
        and loyalty.configuration_status = 'published' as enabled,
      business.active_config_version_id
    from public.businesses business
    left join public.loyalty_programs loyalty
      on loyalty.business_id = business.id
    where business.id = p_business
  ), ledger_balance as (
    select greatest(coalesce(sum(ledger.points), 0), 0)::integer as units
      from public.points_ledger ledger
     where ledger.business_id = p_business
       and ledger.client_id = p_client
       -- v381: the balance is the LIVE programme's pot, never every pot added together
       and (v_balance_scope <> 'programme_pot'
            or ledger.programme_id is not distinct from v_live_programme)
  ), unexpired_batches as (
    select
      batch.id,
      batch.remaining,
      batch.earned_at,
      batch.expires_at,
      sum(batch.remaining) over (
        order by batch.expires_at nulls last, batch.earned_at, batch.id
        rows between unbounded preceding and current row
      )::bigint as cumulative_remaining
      from public.points_batches batch
     where batch.business_id = p_business
       and batch.client_id = p_client
       and batch.remaining > 0
       and (v_balance_scope <> 'programme_pot'
            or batch.programme_id is not distinct from v_live_programme)
       and (batch.expires_at is null or batch.expires_at > v_as_of)
  ), batch_balance as (
    select coalesce(sum(batch.remaining), 0)::integer as units
      from unexpired_batches batch
  ), loyalty_balance as (
    select case when program.enabled
      then greatest(least(ledger_balance.units, batch_balance.units), 0)
      else 0 end::integer as units
      from program cross join ledger_balance cross join batch_balance
  ), actionable_batches as (
    select
      batch.expires_at,
      least(
        batch.remaining::bigint,
        greatest(
          loyalty_balance.units::bigint
            - (batch.cumulative_remaining - batch.remaining::bigint),
          0
        )
      )::integer as actionable_remaining
      from unexpired_batches batch
      cross join loyalty_balance
     where loyalty_balance.units > 0
       and batch.cumulative_remaining - batch.remaining::bigint
           < loyalty_balance.units::bigint
  ), next_expiry as (
    select batch.expires_at,
           sum(batch.actionable_remaining)::integer as units
      from actionable_batches batch
     where batch.expires_at is not null
       and batch.actionable_remaining > 0
     group by batch.expires_at
     order by batch.expires_at
     limit 1
  ), credit_balance as (
    select greatest(coalesce(sum(ledger.amount_cents), 0), 0)::integer
      as balance_cents
      from public.credit_ledger ledger
     where ledger.business_id = p_business
       and ledger.client_id = p_client
  ), redemption_capability as (
    select (
      program.enabled
      and app.platform_feature_enabled('customer_qr_redemption')
      and coalesce(capability.redemption_enabled, false)
    ) as enabled
    from program
    left join public.business_customer_capabilities_v89 capability
      on capability.business_id = p_business
  ), candidate_rewards as (
    select
      'catalog'::text as source,
      reward_version.reward_id,
      reward_version.customer_name as name,
      reward_version.cost_points::integer as cost_units,
      reward_version.credit_cents::integer,
      reward_version.fulfillment_kind,
      reward_version.sort::integer as sort_order,
      greatest(reward_version.cost_points - loyalty_balance.units, 0)::integer
        as remaining_units,
      (redemption_capability.enabled
        and loyalty_balance.units >= reward_version.cost_points) as available_now
    from program
    cross join loyalty_balance
    cross join redemption_capability
    join public.loyalty_reward_versions reward_version
      on reward_version.business_id = p_business
     and reward_version.config_version_id = program.active_config_version_id
     and reward_version.active
    join public.loyalty_rewards reward
      on reward.id = reward_version.reward_id
     and reward.business_id = reward_version.business_id
     and reward.active
     and not reward.paused
    left join lateral (
      select count(*)::integer as used_count
        from public.loyalty_redemptions redemption
       where redemption.business_id = p_business
         and redemption.client_id = p_client
         and redemption.reward_id = reward_version.reward_id
    ) usage on true
    where program.enabled
      and (reward_version.claim_available_from is null
        or reward_version.claim_available_from <= v_as_of)
      and (reward_version.claim_available_until is null
        or reward_version.claim_available_until > v_as_of)
      and (reward_version.usage_limit is null
        or usage.used_count < reward_version.usage_limit)
      and not exists (
        select 1 from public.loyalty_reward_branches restriction
         where restriction.reward_version_id = reward_version.id
      )
      and not exists (
        select 1 from public.loyalty_reward_services restriction
         where restriction.reward_version_id = reward_version.id
      )
      and not exists (
        select 1 from public.loyalty_reward_products restriction
         where restriction.reward_version_id = reward_version.id
      )
  ), reward_list as (
    select coalesce(jsonb_agg(jsonb_build_object(
      'source', candidate.source,
      'reward_id', candidate.reward_id,
      'name', candidate.name,
      'cost_units', candidate.cost_units,
      'credit_cents', candidate.credit_cents,
      'fulfillment_kind', candidate.fulfillment_kind,
      'remaining_units', candidate.remaining_units,
      'available_now', candidate.available_now
    ) order by candidate.remaining_units, candidate.sort_order,
      lower(candidate.name), candidate.reward_id nulls first), '[]'::jsonb)
      as rewards
      from candidate_rewards candidate
  ), next_reward as (
    select jsonb_build_object(
      'source', candidate.source,
      'reward_id', candidate.reward_id,
      'name', candidate.name,
      'cost_units', candidate.cost_units,
      'credit_cents', candidate.credit_cents,
      'fulfillment_kind', candidate.fulfillment_kind,
      'remaining_units', candidate.remaining_units,
      'available_now', candidate.available_now
    ) as reward
    from candidate_rewards candidate
    order by candidate.remaining_units, candidate.sort_order,
      lower(candidate.name), candidate.reward_id nulls first
    limit 1
  )
  select jsonb_build_object(
    'as_of', v_as_of,
    'program', case when program.id is null then null else jsonb_build_object(
      'id', program.id,
      'active', program.enabled,
      'kind', program.kind,
      'model', program.loyalty_model,
      'unit', case when program.loyalty_model = 'stamps'
        then 'stamps' else 'points' end,
      'earn_points_per_dollar', program.earn_points_per_dollar,
      'stamp_per_cents', program.stamp_per_cents,
      'redeem_points', program.redeem_points,
      'reward_credit_cents', program.reward_credit_cents,
      'expiry_mode', program.expiry_mode,
      'configuration_status', program.configuration_status
    ) end,
    'points_balance', loyalty_balance.units,
    'credit_balance_cents', credit_balance.balance_cents,
    'expiry', case
      when not program.enabled or program.expiry_mode = 'none'
        or next_expiry.expires_at is null then null
      else jsonb_build_object(
        'expires_at', next_expiry.expires_at,
        'units', next_expiry.units
      ) end,
    'redemption_enabled', redemption_capability.enabled,
    'rewards', reward_list.rewards,
    'next_reward', next_reward.reward
  ) into v_result
  from program
  cross join loyalty_balance
  cross join credit_balance
  cross join redemption_capability
  cross join reward_list
  left join next_expiry on true
  left join next_reward on true;

  return v_result;
end;
$$;

--
-- Name: staff_get_customer_birthday_benefit(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.staff_get_customer_birthday_benefit(p_business_id uuid, p_client_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_entitlement public.customer_birthday_entitlements%rowtype;
begin
  if not app.platform_feature_enabled('customer_birthday_benefits') then
    raise exception 'birthday benefit unavailable' using errcode='0A000';
  end if;
  if auth.uid() is null or not app.can_module_read(p_business_id,'loyalty')
     or not exists(select 1 from public.clients c where c.id=p_client_id and c.business_id=p_business_id) then
    raise exception 'birthday benefit unavailable' using errcode='42501';
  end if;
  select * into v_entitlement from public.customer_birthday_entitlements
   where business_id=p_business_id and client_id=p_client_id
   order by valid_until desc,activated_at desc limit 1;
  if not found then return jsonb_build_object('status','unavailable'); end if;
  return app.c45_staff_safe_birthday_entitlement(v_entitlement,statement_timestamp());
end $$;

--
-- Name: staff_get_customer_entitlements_v102(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.staff_get_customer_entitlements_v102(p_business uuid, p_client uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_bringback jsonb;
  v_referral jsonb;
  v_welcome jsonb;
  v_packages jsonb;
  v_vouchers jsonb;
begin
  if not (
    app.is_super_admin()
    or app.can_module_read(p_business,'till')
    or app.can_module_read(p_business,'sales')
    or app.can_module_read(p_business,'packages')
  ) then
    raise exception 'customer_entitlements_access_required' using errcode='42501';
  end if;
  if not exists(
    select 1 from public.clients client
    where client.id=p_client and client.business_id=p_business
  ) then
    raise exception 'customer_not_found' using errcode='22023';
  end if;
  select coalesce(jsonb_agg(jsonb_build_object(
    'client_package_id',customer_package.id,
    'remaining',customer_package.remaining,
    'status',customer_package.status,
    'plan_id',customer_package.plan_id,
    'plan_version',customer_package.plan_version_snapshot,
    'plan_name',customer_package.plan_name_snapshot,
    'sessions',customer_package.sessions_snapshot,
    'price_cents',customer_package.price_cents_snapshot,
    'service_id',customer_package.service_id_snapshot,
    'service_name',customer_package.service_name_snapshot,
    'variant_label',customer_package.service_variant_snapshot,
    'list_unit_cents',customer_package.list_unit_cents_snapshot,
    'list_value_cents',customer_package.list_value_cents_snapshot,
    'duration_min',customer_package.service_duration_min_snapshot
  ) order by customer_package.purchased_at,customer_package.id),'[]'::jsonb)
  into v_packages
  from public.client_packages customer_package
  where customer_package.business_id=p_business
    and customer_package.client_id=p_client
    and customer_package.status='active'
    and customer_package.remaining>0;

  select coalesce(jsonb_agg(jsonb_build_object(
    'intent_id',intent.id,
    'redemption_kind',intent.redemption_kind,
    'reward_name',coalesce(reward.name,'Points reward'),
    'points_spent',intent.quoted_points_spent,
    'credit_cents',intent.quoted_credit_cents,
    'expires_at',intent.expires_at
  ) order by intent.expires_at,intent.id),'[]'::jsonb)
  into v_vouchers
  from public.customer_redemption_intents_v89 intent
  left join public.loyalty_rewards reward on reward.id=intent.reward_id
    and reward.business_id=intent.business_id
  where intent.business_id=p_business
    and intent.client_id=p_client
    and intent.status='pending'
    and intent.expires_at>now();

  -- v215: the welcome offer belongs next to packages and vouchers because this
  -- is the one payload the till reads for a looked-up customer. An expired
  -- grant is withheld here rather than offered and then refused at redeem time.
  select jsonb_build_object(
    'grant_id',grant_row.id,
    'reward_label',grant_row.reward_label,
    'reward_catalog_kind',grant_row.reward_catalog_kind,
    'reward_catalog_id',grant_row.reward_catalog_id,
    'min_spend_cents',grant_row.min_spend_cents,
    'expires_at',grant_row.expires_at)
  into v_welcome
  from public.welcome_offer_grants_v215 grant_row
  where grant_row.business_id=p_business
    and grant_row.client_id=p_client
    and grant_row.status='granted'
    and (grant_row.expires_at is null or grant_row.expires_at>now());

  select jsonb_build_object('grant_id',bb.id,'reward_label',bb.reward_label,'away_days',bb.away_days,'expires_at',bb.expires_at) into v_bringback from public.bringback_grants_v361 bb where bb.business_id=p_business and bb.client_id=p_client and bb.status='granted' and (bb.expires_at is null or bb.expires_at>now()) order by bb.granted_at limit 1; select jsonb_build_object('grant_id',rg.id,'reward_label',rg.reward_label,'expires_at',rg.expires_at)
    into v_referral
    from public.referral_grants_v420 rg
   where rg.business_id=p_business and rg.client_id=p_client and rg.status='granted'
     and (rg.expires_at is null or rg.expires_at>now())
   order by rg.granted_at limit 1;
  -- nestly_v420: the referral gift joins the one payload the till reads for a looked-up customer,
  -- beside the welcome offer and the bring-back voucher it is shaped after. An expired grant is
  -- withheld here rather than offered and then refused at redeem time (v215's rule).
  return jsonb_build_object('packages',v_packages,'vouchers',v_vouchers,'welcome_offer',v_welcome,'bringback_offer',v_bringback,'referral_offer',v_referral);
end
$$;

--
-- Name: staff_get_reversal_workflows(uuid, uuid, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.staff_get_reversal_workflows(p_business uuid, p_client uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 50, p_mode text DEFAULT 'all'::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_staff uuid;
  v_role text;
  v_limit integer := case when p_limit = 0 then null else least(greatest(coalesce(p_limit, 50), 1), 100) end;
  v_mode text := lower(coalesce(nullif(btrim(p_mode), ''), 'all'));
  v_sales_total bigint := 0;
  v_sales jsonb := '[]'::jsonb;
  v_redemptions jsonb := '[]'::jsonb;
begin
  if v_actor is null then
    raise exception 'authenticated staff required' using errcode = '42501';
  end if;
  if v_mode not in ('all','package') then
    raise exception 'unsupported reversal workflow mode %', p_mode using errcode = '22023';
  end if;
  if not app.has_perm(p_business, 'refund_sales') then
    raise exception 'refund_sales permission required' using errcode = '42501';
  end if;
  select s.id, s.role into v_staff, v_role
    from public.staff s
   where s.business_id = p_business
     and s.user_id = v_actor
     and s.active
     and 'refund_sales' = any(app.role_perms(s.role))
   order by case s.role when 'owner' then 0 when 'manager' then 1 else 2 end,
            s.created_at, s.id
   limit 1;
  if not found then
    raise exception 'active staff authorization required' using errcode = '42501';
  end if;
  if p_client is not null and not exists (
    select 1 from public.clients c
     where c.id = p_client and c.business_id = p_business
  ) then
    raise exception 'customer not found in this business' using errcode = '42501';
  end if;

  select coalesce(jsonb_agg(x.item order by x.occurred_at desc, x.id desc), '[]'::jsonb),
         coalesce(max(x.total_count), 0)
    into v_sales, v_sales_total
    from (
      select s.id, s.occurred_at, count(*) over() as total_count,
             jsonb_build_object(
               'id', s.id,
               'client_id', s.client_id,
               'customer_name', c.full_name,
               'branch_id', s.branch_id,
               'kind', s.kind,
               'amount_cents', s.amount_cents,
               'net_amount_cents', case
                 when s.reversal_of is null then s.amount_cents + coalesce(rev.amount_cents, 0)
                 else coalesce(original.amount_cents, 0) + s.amount_cents
               end,
               'occurred_at', s.occurred_at,
               'note', s.note,
               'is_reversal', s.reversal_of is not null,
               'original_sale_id', s.reversal_of,
               'correction_record_id', corr.correction_id,
               'correction_sale_id', case when corr.corr_original_sale_id = s.id
                 then corr.corr_replacement_sale_id end,
               'corrected_sale_id', case when corr.corr_replacement_sale_id = s.id
                 then corr.corr_original_sale_id end,
               'correction_role', case
                 when corr.corr_original_sale_id = s.id then 'original'
                 when corr.corr_replacement_sale_id = s.id then 'replacement'
                 when corr.corr_reversal_sale_id = s.id then 'reversal'
               end,
               'correction_before_cents', corr.corr_before_cents,
               'correction_after_cents', corr.corr_after_cents,
               'corrected_at', corr.corr_created_at,
               'reversal_sale_id', case when s.reversal_of is null then rev.id else s.id end,
               'reversal_reason', coalesce(rev.reversal_reason, s.reversal_reason),
               'reversed_at', coalesce(rev.occurred_at,
                 case when s.reversal_of is not null then s.occurred_at end),
               'is_package_session', pkg.consumption_id is not null,
               'no_money_refund', pkg.consumption_id is not null,
               'can_reverse', s.reversal_of is null and rev.id is null and (
                 (s.amount_cents > 0 and s.kind in ('service', 'retail', 'quick_sale'))
                 or (s.amount_cents = 0 and pkg.consumption_id is not null)
               ),
               'refusal_reason', case
                 when s.reversal_of is not null then 'This row is already a reversal.'
                 when rev.id is not null then 'This sale is already fully reversed.'
                 when s.amount_cents = 0 and pkg.consumption_id is null then 'This zero-value sale has no package-session provenance.'
                 when s.amount_cents <= 0 then 'This sale has no positive economic amount to reverse.'
                 when s.kind not in ('service', 'retail', 'quick_sale') then 'This sale type has no proven reversal path.'
                 else null
               end,
               'completed_result', coalesce(
                 fin.result,
                 case when pkg.reversal_sale_id is not null then jsonb_build_object(
                   'reversal_sale_id', pkg.reversal_sale_id,
                   'restored_sessions', 1,
                   'refunded_payment_cents', 0,
                   'no_money_refund', true,
                   'replayed', false
                 ) end
               )
             ) as item
        from public.sales s
        left join public.clients c
          on c.id = s.client_id and c.business_id = s.business_id
        left join public.sales original
          on original.id = s.reversal_of and original.business_id = s.business_id
        left join lateral (
          select r.id, r.amount_cents, r.occurred_at, r.reversal_reason
            from public.sales r
           where r.business_id = s.business_id and r.reversal_of = s.id
           order by r.occurred_at, r.id limit 1
        ) rev on true
        left join lateral (
          select jsonb_strip_nulls(jsonb_build_object(
            'reversal_sale_id',fo.result->'reversal_sale_id',
            'reversed_cents',fo.result->'reversed_cents',
            'refunded_payment_cents',fo.result->'refunded_payment_cents',
            'replayed',coalesce(fo.result->'replayed','false'::jsonb)
          )) as result
            from public.financial_operations fo
           where fo.business_id = s.business_id
             and fo.sale_id = s.id
             and fo.operation_type = 'sale_reversal'
             and fo.status = 'completed'
           order by fo.completed_at desc, fo.id desc limit 1
        ) fin on true
        left join lateral (
          select pc.id as consumption_id, pr.reversal_sale_id
            from public.package_session_consumptions pc
            left join public.package_session_reversals pr
              on pr.business_id = pc.business_id and pr.consumption_id = pc.id
           where pc.business_id = s.business_id
             and pc.sale_id = coalesce(s.reversal_of, s.id)
           limit 1
        ) pkg on true
        left join lateral (
          select corr.id as correction_id,
                 corr.original_sale_id as corr_original_sale_id,
                 corr.reversal_sale_id as corr_reversal_sale_id,
                 corr.replacement_sale_id as corr_replacement_sale_id,
                 corr.original_amount_cents as corr_before_cents,
                 corr.corrected_amount_cents as corr_after_cents,
                 corr.created_at as corr_created_at
            from public.sale_amount_corrections_v84 corr
           where corr.business_id = s.business_id
             and (corr.original_sale_id = s.id
               or corr.replacement_sale_id = s.id
               or corr.reversal_sale_id = s.id)
           order by corr.created_at desc, corr.id desc
           limit 1
        ) corr on true
       where s.business_id = p_business
         and (p_client is null or s.client_id = p_client)
         and app.can_see_branch(p_business, s.branch_id)
         and (v_mode = 'all' or pkg.consumption_id is not null)
       order by s.occurred_at desc, s.id desc
       limit v_limit
    ) x;

  select coalesce(jsonb_agg(x.item order by x.redeemed_at desc, x.id desc), '[]'::jsonb)
    into v_redemptions
    from (
      select lr.id, lr.redeemed_at,
             jsonb_build_object(
               'id', lr.id,
               'client_id', lr.client_id,
               'customer_name', c.full_name,
               'branch_id', scope.branch_id,
               'reward_name', lr.reward_name,
               'points_spent', lr.points_spent,
               'credit_cents', lr.credit_cents,
               'fulfillment_kind', lr.fulfillment_kind,
               'redeemed_at', lr.redeemed_at,
               'reversal_id', rr.id,
               'reversed_at', rr.created_at,
               'completed_result', rr.result,
               'has_exact_provenance', prov.id is not null
                 and prov.config_version_id is not distinct from lr.config_version_id
                 and coalesce(drains.drained_points, 0) = lr.points_spent
                 and points_ok.proven
                 and credit_state.proven,
               'credit_may_be_spent', coalesce(credit_state.may_be_spent, false),
               'can_reverse', rr.id is null
                 and prov.id is not null
                 and prov.config_version_id is not distinct from lr.config_version_id
                 and coalesce(drains.drained_points, 0) = lr.points_spent
                 and points_ok.proven
                 and credit_state.proven
                 and not coalesce(credit_state.may_be_spent, false),
               'refusal_reason', case
                 when rr.id is not null then 'This redemption is already reversed.'
                 when prov.id is null then 'Legacy or incomplete redemption provenance cannot be reversed safely.'
                 when prov.config_version_id is distinct from lr.config_version_id then 'Configuration provenance is inconsistent.'
                 when not coalesce(points_ok.proven, false) then 'Original points-ledger provenance is incomplete.'
                 when coalesce(drains.drained_points, 0) <> lr.points_spent then 'FEFO batch-drain provenance does not reconcile.'
                 when not coalesce(credit_state.proven, false) then 'Original loyalty credit provenance is missing or does not match.'
                 when coalesce(credit_state.may_be_spent, false) then 'Reward credit may have been spent; exact compensation is refused.'
                 else null
               end
             ) as item
        from public.loyalty_redemptions lr
        join public.clients c
          on c.id = lr.client_id and c.business_id = lr.business_id
        left join public.loyalty_redemption_provenance prov
          on prov.business_id = lr.business_id and prov.redemption_id = lr.id
        left join public.loyalty_redemption_reversals rr
          on rr.business_id = lr.business_id and rr.redemption_id = lr.id
        left join lateral (
          select nullif(lr.eligibility_snapshot #>> '{selected,branch_id}', '')::uuid as branch_id
        ) scope on true
        left join lateral (
          select coalesce(sum(d.drained_points), 0)::integer as drained_points
            from public.loyalty_redemption_batch_drains d
           where d.business_id = lr.business_id and d.redemption_id = lr.id
        ) drains on true
        left join lateral (
          select exists (
            select 1 from public.points_ledger pl
             where pl.id = prov.points_ledger_id
               and pl.business_id = lr.business_id
               and pl.client_id = lr.client_id
               and pl.points = -lr.points_spent
               and pl.config_version_id = lr.config_version_id
          ) as proven
        ) points_ok on true
        left join lateral (
          select
            case when lr.credit_cents<=0 then true else exists (
              select 1 from public.credit_ledger source
               where source.id=prov.credit_ledger_id
                 and source.business_id=lr.business_id
                 and source.client_id=lr.client_id
                 and source.entry_type='loyalty_earn'
                 and source.amount_cents=lr.credit_cents
                 and source.config_version_id=lr.config_version_id
            ) end as proven,
            case when lr.credit_cents<=0 then false else exists (
              select 1
                from public.credit_ledger source
                join public.credit_ledger spend
                  on spend.business_id=source.business_id
                 and spend.client_id=source.client_id
                 and spend.amount_cents<0
                 and spend.created_at>=source.created_at
                 and spend.id is distinct from rr.reversed_credit_ledger_id
               where source.id=prov.credit_ledger_id
                 and source.business_id=lr.business_id
                 and source.client_id=lr.client_id
                 and source.entry_type='loyalty_earn'
                 and source.amount_cents=lr.credit_cents
                 and source.config_version_id=lr.config_version_id
            ) end as may_be_spent
        ) credit_state on true
       where v_mode = 'all'
         and lr.business_id = p_business
         and (p_client is null or lr.client_id = p_client)
         and app.can_see_branch(p_business, scope.branch_id)
       order by lr.redeemed_at desc, lr.id desc
       limit v_limit
    ) x;

  return jsonb_build_object(
    'can_reverse', true,
    'actor_role', v_role,
    'mode', v_mode,
    'limit', v_limit,
    'bounded', v_limit is not null,
    'total_sales', v_sales_total,
    'may_have_more', case when v_limit is null then false else v_sales_total > v_limit end,
    'sales', v_sales,
    'redemptions', v_redemptions
  );
end $$;

--
-- Name: staff_get_reward_entitlements_v99(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.staff_get_reward_entitlements_v99(p_business uuid, p_client uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid:=auth.uid();
  v_result jsonb;
begin
  if v_actor is null
     or not app.can_module_read(p_business,'clients') then
    raise exception 'customer read access is required' using errcode='42501';
  end if;
  if not exists(
    select 1
    from public.clients client
    where client.id=p_client
      and client.business_id=p_business
  ) then
    raise exception 'customer was not found in this business'
      using errcode='22023';
  end if;

  select coalesce(
    pg_catalog.jsonb_agg(
      pg_catalog.jsonb_build_object(
        'id',reward.id,
        'granted_at',reward.granted_at,
        'program_name',program.name,
        'campaign_id',reward.campaign_id,
        'is_campaign_entitlement',reward.campaign_id is not null,
        'entitlement_status',reward.status,
        'fulfillment_status',case
          when reward.campaign_id is not null and reward.status='expired'
            then 'expired_unfulfilled'
          when reward.campaign_id is not null
            then 'merchant_fulfilment_pending'
          else reward.status
        end,
        'redemption_mode',case when reward.campaign_id is not null
          then 'merchant_fulfilment_pending' else null end,
        'economic_value_posted',case when reward.campaign_id is not null
          then false else null end,
        'fulfillment_kind',reward.fulfillment_kind,
        'reward_label',reward.reward_label,
        'reward_value_hidden',reward.campaign_id is not null,
        'display_label',case when reward.campaign_id is not null
          then 'Offer awaiting merchant fulfilment'
          else coalesce(nullif(btrim(reward.reward_label),''),'Reward')
        end,
        'display_amount_cents',case
          when reward.campaign_id is null
           and reward.fulfillment_kind='credit'
            then reward.reward_value::bigint
          else null
        end,
        'display_discount_percent',case
          when reward.campaign_id is null
           and reward.fulfillment_kind='discount_pct'
            then reward.reward_value
          else null
        end,
        'display_item',case
          when reward.campaign_id is null
           and reward.fulfillment_kind='free_item'
            then reward.reward_item
          else null
        end
      )
      order by reward.granted_at desc,reward.id desc
    ),
    '[]'::jsonb
  ) into v_result
  from public.reward_grants reward
  left join public.retention_programs program
    on program.id=reward.program_id
   and program.business_id=reward.business_id
  where reward.business_id=p_business
    and reward.client_id=p_client;
  return v_result;
end
$$;

--
-- Name: staff_issue_tier_benefit_v365(uuid, uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.staff_issue_tier_benefit_v365(p_business uuid, p_client uuid, p_benefit uuid, p_branch uuid DEFAULT NULL::uuid, p_idempotency_key uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_key uuid := coalesce(p_idempotency_key, gen_random_uuid());
  v_benefit public.tier_benefits_v365%rowtype;
  v_tier public.loyalty_tiers%rowtype;
  v_benefit_tier public.loyalty_tiers%rowtype;
  v_period_key text;
  v_used integer;
  v_existing public.tier_benefit_issues_v365%rowtype;
  v_id uuid;
  v_birth date;
begin
  if v_actor is null then raise exception 'authenticated staff required' using errcode='42501'; end if;
  if not (app.is_salon_owner(p_business) or app.can_module_write(p_business,'till')
          or app.can_module_write(p_business,'loyalty')) then
    raise exception 'till or loyalty write authorization required' using errcode='42501';
  end if;

  select * into v_benefit from public.tier_benefits_v365
   where id=p_benefit and business_id=p_business and deleted_at is null and active;
  if not found then raise exception 'tier_benefit_not_found' using errcode='42704'; end if;
  select * into v_benefit_tier from public.loyalty_tiers
   where id=v_benefit.tier_id and business_id=p_business
     and coalesce(paused,false)=false and deleted_at is null;
  if not found then raise exception 'tier_benefit_not_found' using errcode='42704'; end if;

  -- Replay BEFORE the limit check: a double-tap must return the first issue, never be counted as
  -- a second one and never be reported as "limit reached".
  select * into v_existing from public.tier_benefit_issues_v365
   where benefit_id=p_benefit and client_id=p_client and idem_key=v_key;
  if found then
    return jsonb_build_object('status','duplicate_ignored','issue_id',v_existing.id,
      'label',v_existing.label,'period_key',v_existing.period_key);
  end if;

  -- One customer, one benefit, one period at a time: two counters racing would both read "0 used".
  perform pg_advisory_xact_lock(hashtextextended('v365:issue:'||p_benefit::text||':'||p_client::text,0));

  v_tier := app.v365_client_tier(p_business,p_client);
  if v_tier.id is null or v_tier.threshold < v_benefit_tier.threshold then
    raise exception 'tier_benefit_not_earned' using errcode='42501';
  end if;

  -- V367: the birthday-month test. Refused loudly when the profile carries no birth date rather
  -- than allowed — see the migration header.
  if v_benefit.limit_period='birthday_month' then
    select birth_date into v_birth from public.clients where id=p_client and business_id=p_business;
    if v_birth is null then
      raise exception 'tier_benefit_birthday_unknown' using errcode='22023';
    end if;
    if not app.v367_in_birthday_month(p_client, now()) then
      raise exception 'tier_benefit_not_birthday_month' using errcode='22023';
    end if;
  end if;

  v_period_key := app.v365_period_key(v_benefit.limit_period, now());
  if v_benefit.limit_count is not null then
    select count(*) into v_used from public.tier_benefit_issues_v365
     where benefit_id=p_benefit and client_id=p_client and period_key=v_period_key;
    if v_used >= v_benefit.limit_count then
      raise exception 'tier_benefit_limit_reached' using errcode='22023';
    end if;
  end if;

  if p_branch is not null then
    perform 1 from public.branches branch
     where branch.id=p_branch and branch.business_id=p_business and branch.active
       and app.can_see_branch(p_business, branch.id);
    if not found then raise exception 'tier_benefit_branch_not_permitted' using errcode='42501'; end if;
  end if;

  insert into public.tier_benefit_issues_v365(
    business_id,benefit_id,client_id,tier_id,label,limit_count,limit_period,period_key,
    branch_id,issued_by,idem_key)
  values(p_business,p_benefit,p_client,v_benefit.tier_id,v_benefit.label,v_benefit.limit_count,
    v_benefit.limit_period,v_period_key,p_branch,v_actor,v_key)
  returning id into v_id;

  insert into public.audit_log(business_id,actor,action,entity,entity_id,detail)
  values(p_business,v_actor,'TIER_BENEFIT_ISSUED_V365','tier_benefit_issues_v365',v_id,
    jsonb_build_object('client_id',p_client,'benefit_id',p_benefit,'label',v_benefit.label,
                       'period_key',v_period_key,'branch_id',p_branch));

  return jsonb_build_object('status','issued','issue_id',v_id,'label',v_benefit.label,
    'period_key',v_period_key,
    'remaining',case when v_benefit.limit_count is null then null
      else greatest(0,v_benefit.limit_count-(
        select count(*) from public.tier_benefit_issues_v365
         where benefit_id=p_benefit and client_id=p_client and period_key=v_period_key)) end);
end $$;

--
-- Name: staff_list_customers_v129(uuid, text, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.staff_list_customers_v129(p_business uuid, p_search text DEFAULT NULL::text, p_inactive_days integer DEFAULT NULL::integer, p_limit integer DEFAULT 100, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_as_of timestamptz := statement_timestamp();
  v_search text := lower(btrim(coalesce(p_search, '')));
  v_phone_search text := regexp_replace(coalesce(p_search, ''), '[^0-9]', '', 'g');
  v_cutoff_date date;
  v_loyalty_available boolean;
  v_program_enabled boolean;
  v_result jsonb;
begin
  if length(v_phone_search) = 10 and left(v_phone_search, 2) = '65' then
    v_phone_search := right(v_phone_search, 8);
  end if;
  if auth.uid() is null or not app.can_module_read(p_business, 'clients') then
    raise exception 'customer read access required' using errcode = '42501';
  end if;
  if p_inactive_days is not null and p_inactive_days not in (30, 60, 90) then
    raise exception 'inactive days must be 30, 60 or 90' using errcode = '22023';
  end if;
  if p_limit < 1 or p_limit > 100 then
    raise exception 'limit must be between 1 and 100' using errcode = '22023';
  end if;
  if p_offset < 0 or p_offset > 100000 then
    raise exception 'offset must be between 0 and 100000' using errcode = '22023';
  end if;

  v_cutoff_date := (v_as_of at time zone 'Asia/Singapore')::date - p_inactive_days;
  v_loyalty_available := app.metric_module_scope_available_v145(
    p_business, null, 'loyalty'
  );
  select exists (
    select 1
      from public.loyalty_programs program
     where program.business_id = p_business
       and coalesce(program.active, false)
       and program.configuration_status = 'published'
  ) into v_program_enabled;

  with visit_facts as materialized (
    select sale.client_id, max(sale.occurred_at) as last_visit_at
      from public.sales sale
     where sale.business_id = p_business
       and sale.client_id is not null
       and sale.counts_as_visit
       and sale.reversal_of is null
       and sale.occurred_at <= v_as_of
       and not exists (
         select 1 from public.sales reversal
          where reversal.business_id = sale.business_id
            and reversal.reversal_of = sale.id
            and reversal.created_at <= v_as_of
       )
     group by sale.client_id
  ), customer_rows as materialized (
    select customer.id, customer.full_name, customer.phone, customer.email,
      customer.birth_date, customer.marketing_consent, customer.created_at,
      visit.last_visit_at,
      case when visit.last_visit_at is null then null
        else ((v_as_of at time zone 'Asia/Singapore')::date -
          (visit.last_visit_at at time zone 'Asia/Singapore')::date)::integer
      end as days_since_last_visit
      from public.clients customer
      left join visit_facts visit on visit.client_id = customer.id
     where customer.business_id = p_business
       and (
         v_search = ''
         or position(v_search in lower(customer.full_name)) > 0
         or (length(v_phone_search) >= 4 and
           position(v_phone_search in coalesce(customer.phone_norm, '')) > 0)
       )
       and (
         p_inactive_days is null
         or visit.last_visit_at is null
         or (visit.last_visit_at at time zone 'Asia/Singapore')::date <= v_cutoff_date
       )
  ), page as materialized (
    select * from customer_rows customer
     order by
       case when p_inactive_days is not null and customer.last_visit_at is null then 0 else 1 end,
       case when p_inactive_days is not null then customer.last_visit_at end asc nulls first,
       case when p_inactive_days is null then customer.created_at end desc,
       customer.full_name, customer.id
     limit p_limit offset p_offset
  ), page_ledger as materialized (
    select ledger.client_id,
           greatest(coalesce(sum(ledger.points), 0), 0)::bigint as units
      from public.points_ledger ledger
      join page customer on customer.id = ledger.client_id
     where ledger.business_id = p_business
     group by ledger.client_id
  ), page_batches as materialized (
    select batch.client_id,
           greatest(coalesce(sum(batch.remaining), 0), 0)::bigint as units
      from public.points_batches batch
      join page customer on customer.id = batch.client_id
     where batch.business_id = p_business
       and batch.remaining > 0
       and (batch.expires_at is null or batch.expires_at > v_as_of)
     group by batch.client_id
  ), page_credit as materialized (
    select ledger.client_id,
           greatest(coalesce(sum(ledger.amount_cents), 0), 0)::bigint as balance_cents
      from public.credit_ledger ledger
      join page customer on customer.id = ledger.client_id
     where ledger.business_id = p_business
     group by ledger.client_id
  ), page_balances as materialized (
    select customer.*,
      case
        when not v_loyalty_available then null::bigint
        when not v_program_enabled then 0::bigint
        else least(coalesce(points.units, 0), coalesce(batches.units, 0))
      end as points,
      case when v_loyalty_available
        then coalesce(credit.balance_cents, 0)
        else null::bigint
      end as balance_cents
      from page customer
      left join page_ledger points on points.client_id = customer.id
      left join page_batches batches on batches.client_id = customer.id
      left join page_credit credit on credit.client_id = customer.id
  )
  select jsonb_build_object(
    'status', 'ok',
    'as_of', v_as_of,
    'inactive_days', p_inactive_days,
    'loyalty_available', v_loyalty_available,
    'loyalty_program_enabled', v_program_enabled,
    'total', (select count(*) from customer_rows),
    'customers', coalesce((select jsonb_agg(jsonb_build_object(
      'id', customer.id,
      'full_name', customer.full_name,
      'phone', customer.phone,
      'email', customer.email,
      'birth_date', customer.birth_date,
      'marketing_consent', customer.marketing_consent,
      'created_at', customer.created_at,
      'last_visit_at', customer.last_visit_at,
      'days_since_last_visit', customer.days_since_last_visit,
      'points', customer.points,
      'balance_cents', customer.balance_cents
    ) order by
      case when p_inactive_days is not null and customer.last_visit_at is null then 0 else 1 end,
      case when p_inactive_days is not null then customer.last_visit_at end asc nulls first,
      case when p_inactive_days is null then customer.created_at end desc,
      customer.full_name, customer.id) from page_balances customer), '[]'::jsonb)
  ) into v_result;

  return v_result;
end;
$$;

--
-- Name: FUNCTION staff_list_customers_v129(p_business uuid, p_search text, p_inactive_days integer, p_limit integer, p_offset integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.staff_list_customers_v129(p_business uuid, p_search text, p_inactive_days integer, p_limit integer, p_offset integer) IS 'Lists a bounded customer page with valid last-visit facts and V145 actionable/nonnegative loyalty balances; an unavailable complete Loyalty scope returns null balance fields rather than inferred zero.';

--
-- Name: staff_list_customers_v155(uuid, text, text, text, uuid[], uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.staff_list_customers_v155(p_business uuid, p_search text DEFAULT NULL::text, p_inactive_bucket text DEFAULT NULL::text, p_scope_mode text DEFAULT 'all'::text, p_branch_ids uuid[] DEFAULT ARRAY[]::uuid[], p_operational_branch uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 100, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_as_of timestamptz := statement_timestamp();
  v_search text := lower(btrim(coalesce(p_search,'')));
  v_phone_search text := regexp_replace(coalesce(p_search,''),'[^0-9]','','g');
  v_scope_ids uuid[];
  v_scope_label text;
  v_scope_is_whole_business boolean := false;
  v_result jsonb;
  -- v381: same pot rule as the customer profile — one programme's balance, not the sum of all
  v_balance_scope text := app.programme_balance_scope_v312(p_business);
  v_live_programme uuid := app.live_balance_programme_v381(p_business);
begin
  if length(v_phone_search)=10 and left(v_phone_search,2)='65' then
    v_phone_search := right(v_phone_search,8);
  end if;
  if auth.uid() is null or not app.can_module_read(p_business,'clients') then
    raise exception 'customer read access required' using errcode='42501';
  end if;
  if p_inactive_bucket is not null
     and p_inactive_bucket not in ('30_59','60_89','90_plus','never','all_inactive') then
    raise exception 'unsupported_inactivity_bucket' using errcode='22023';
  end if;
  if p_limit < 1 or p_limit > 100 then
    raise exception 'limit must be between 1 and 100' using errcode='22023';
  end if;
  if p_offset < 0 or p_offset > 100000 then
    raise exception 'offset must be between 0 and 100000' using errcode='22023';
  end if;

  select coalesce(array_agg(scope.branch_id order by scope.branch_name),array[]::uuid[])
    into v_scope_ids
  from app.resolve_reporting_branch_scope_v155(
    p_business,p_scope_mode,p_branch_ids,p_operational_branch
  ) scope;
  v_scope_label := app.reporting_scope_label_v155(
    p_business,p_scope_mode,p_branch_ids,p_operational_branch
  );
  select not exists(
    select 1
    from public.branches branch
    where branch.business_id = p_business
      and coalesce(branch.active,true)
      and not (branch.id = any(v_scope_ids))
  ) into v_scope_is_whole_business;

  with visit_facts as materialized (
    select sale.client_id,max(sale.occurred_at) as last_visit_at
    from public.sales sale
    where sale.business_id = p_business
      and sale.client_id is not null
      and sale.counts_as_visit
      and sale.reversal_of is null
      and sale.occurred_at <= v_as_of
      and sale.branch_id = any(v_scope_ids)
      and not exists(
        select 1 from public.sales reversal
        where reversal.business_id = sale.business_id
          and reversal.reversal_of = sale.id
          and reversal.created_at <= v_as_of
      )
    group by sale.client_id
  ), customer_scope as materialized (
    select distinct sale.client_id
    from public.sales sale
    where sale.business_id = p_business
      and sale.client_id is not null
      and sale.counts_as_visit
      and sale.reversal_of is null
      and sale.branch_id = any(v_scope_ids)
  ), customer_rows as materialized (
    select customer.id,customer.full_name,customer.phone,
      customer.marketing_consent,customer.created_at,
      visit.last_visit_at,
      case when visit.last_visit_at is null then null
        else ((v_as_of at time zone 'Asia/Singapore')::date-
          (visit.last_visit_at at time zone 'Asia/Singapore')::date)::integer
      end as days_since_last_visit
    from public.clients customer
    left join visit_facts visit on visit.client_id = customer.id
    where customer.business_id = p_business
      and (
        v_scope_is_whole_business
        or exists(select 1 from customer_scope scoped where scoped.client_id = customer.id)
      )
      and (
        v_search = ''
        or position(v_search in lower(customer.full_name)) > 0
        or (length(v_phone_search) >= 4 and
          position(v_phone_search in coalesce(customer.phone_norm,'')) > 0)
      )
      and (
        p_inactive_bucket is null
        or (p_inactive_bucket = 'never' and v_scope_is_whole_business
          and visit.last_visit_at is null)
        or (p_inactive_bucket = '30_59' and visit.last_visit_at is not null
          and ((v_as_of at time zone 'Asia/Singapore')::date-
            (visit.last_visit_at at time zone 'Asia/Singapore')::date) between 30 and 59)
        or (p_inactive_bucket = '60_89' and visit.last_visit_at is not null
          and ((v_as_of at time zone 'Asia/Singapore')::date-
            (visit.last_visit_at at time zone 'Asia/Singapore')::date) between 60 and 89)
        or (p_inactive_bucket = '90_plus' and visit.last_visit_at is not null
          and ((v_as_of at time zone 'Asia/Singapore')::date-
            (visit.last_visit_at at time zone 'Asia/Singapore')::date) >= 90)
        or (p_inactive_bucket = 'all_inactive' and visit.last_visit_at is not null
          and ((v_as_of at time zone 'Asia/Singapore')::date-
            (visit.last_visit_at at time zone 'Asia/Singapore')::date) >= 30)
      )
  ), page as materialized (
    select * from customer_rows customer
    order by customer.last_visit_at asc nulls last, customer.full_name, customer.id
    limit p_limit offset p_offset
  ), page_balances as materialized (
    select customer.*,
      coalesce((select sum(ledger.points) from public.points_ledger ledger
        where ledger.business_id = p_business and ledger.client_id = customer.id
          and (v_balance_scope <> 'programme_pot'
               or ledger.programme_id is not distinct from v_live_programme)),0)::bigint as points,
      coalesce((select sum(ledger.amount_cents) from public.credit_ledger ledger
        where ledger.business_id = p_business and ledger.client_id = customer.id),0)::bigint as balance_cents
    from page customer
  )
  select jsonb_build_object(
    'status','ok',
    'as_of',v_as_of,
    'scope',jsonb_build_object(
      'mode',coalesce(p_scope_mode,'all'),
      'label',v_scope_label,
      'branch_ids',to_jsonb(v_scope_ids),
      'definition',case when v_scope_is_whole_business
        then 'Business-wide last valid visit across all included authorised branches.'
        else 'Inactive in this branch scope: last valid visit within that selected scope.'
      end
    ),
    'inactive_bucket',p_inactive_bucket,
    'loyalty_available',app.metric_module_scope_available_v145(p_business,null,'loyalty'),
    'total',(select count(*) from customer_rows),
    'customers',coalesce((select jsonb_agg(jsonb_build_object(
      'id',customer.id,
      'full_name',customer.full_name,
      'phone',customer.phone,
      'marketing_consent',customer.marketing_consent,
      'created_at',customer.created_at,
      'last_visit_at',customer.last_visit_at,
      'days_since_last_visit',customer.days_since_last_visit,
      'points',customer.points,
      'balance_cents',customer.balance_cents
    ) order by customer.last_visit_at asc nulls last,customer.full_name,customer.id)
    from page_balances customer),'[]'::jsonb)
  ) into v_result;

  return v_result;
end
$$;

--
-- Name: FUNCTION staff_list_customers_v155(p_business uuid, p_search text, p_inactive_bucket text, p_scope_mode text, p_branch_ids uuid[], p_operational_branch uuid, p_limit integer, p_offset integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.staff_list_customers_v155(p_business uuid, p_search text, p_inactive_bucket text, p_scope_mode text, p_branch_ids uuid[], p_operational_branch uuid, p_limit integer, p_offset integer) IS 'Lists a bounded, branch-scoped customer page with valid last-visit facts and loyalty balances; V248 restores the loyalty_available flag (complete business-wide Loyalty read scope) that V155 dropped, so the client can tell unconfirmed access apart from a genuine zero.';

--
-- Name: staff_list_gift_cards(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.staff_list_gift_cards(p_business uuid, p_limit integer DEFAULT 100) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_staff uuid;
  v_limit integer := least(greatest(coalesce(p_limit, 100), 1), 100);
  v_result jsonb;
begin
  if v_actor is null or not app.can_module_read(p_business, 'giftcards') then
    raise exception 'active giftcards-module read authorization is required'
      using errcode = '42501';
  end if;
  select s.id into v_staff
    from public.staff s
   where s.business_id = p_business
     and s.user_id = v_actor
     and s.active
   order by case when s.role = 'owner' then 0 else 1 end, s.created_at
   limit 1;
  if not found then
    raise exception 'active staff authorization is required'
      using errcode = '42501';
  end if;
  select coalesce(jsonb_agg(jsonb_build_object(
    'gift_card_id', x.id,
    'code_suffix', right(x.code, 4),
    'initial_cents', x.initial_cents,
    'balance_cents', x.balance_cents,
    'status', x.status,
    'created_at', x.created_at
  ) order by x.created_at desc, x.id), '[]'::jsonb)
    into v_result
    from (
      select g.id, g.code, g.initial_cents, g.balance_cents, g.status, g.created_at
        from public.gift_cards g
       where g.business_id = p_business
       order by g.created_at desc, g.id
       limit v_limit
    ) x;
  return v_result;
end
$$;

--
-- Name: staff_list_gift_cards_v145(uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.staff_list_gift_cards_v145(p_business uuid, p_limit integer DEFAULT 100, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_staff uuid;
  v_limit integer := least(greatest(coalesce(p_limit, 100), 1), 100);
  v_offset integer := greatest(coalesce(p_offset, 0), 0);
  v_total bigint;
  v_items jsonb;
begin
  if v_actor is null or not app.can_module_read(p_business, 'giftcards') then
    raise exception 'active giftcards-module read authorization is required'
      using errcode = '42501';
  end if;
  select staff.id into v_staff
    from public.staff staff
   where staff.business_id = p_business
     and staff.user_id = v_actor
     and staff.active
   order by case when staff.role = 'owner' then 0 else 1 end,
            staff.created_at, staff.id
   limit 1;
  if not found then
    raise exception 'active staff authorization is required'
      using errcode = '42501';
  end if;
  select count(*) into v_total
    from public.gift_cards card
   where card.business_id = p_business;
  select coalesce(jsonb_agg(jsonb_build_object(
    'gift_card_id', page.id,
    'code_suffix', right(page.code, 4),
    'initial_cents', page.initial_cents,
    'balance_cents', page.balance_cents,
    'status', page.status,
    'created_at', page.created_at
  ) order by page.created_at desc, page.id), '[]'::jsonb)
    into v_items
    from (
      select card.id, card.code, card.initial_cents, card.balance_cents,
             card.status, card.created_at
        from public.gift_cards card
       where card.business_id = p_business
       order by card.created_at desc, card.id
       limit v_limit offset v_offset
    ) page;
  return jsonb_build_object(
    'status', 'ok', 'cards', v_items, 'total', v_total,
    'limit', v_limit, 'offset', v_offset
  );
end;
$$;

--
-- Name: staff_list_package_entitlements_v102(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.staff_list_package_entitlements_v102(p_business uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if not (
    app.is_super_admin()
    or app.can_module_read(p_business,'till')
    or app.can_module_read(p_business,'sales')
    or app.can_module_read(p_business,'packages')
  ) then
    raise exception 'package_entitlements_access_required' using errcode='42501';
  end if;
  return (
    select coalesce(jsonb_agg(jsonb_build_object(
      'client_package_id',customer_package.id,
      'client_id',customer_package.client_id,
      'client_name',client.full_name,
      'client_phone',client.phone,
      'plan_id',customer_package.plan_id,
      'plan_version',customer_package.plan_version_snapshot,
      'plan_name',customer_package.plan_name_snapshot,
      'sessions',customer_package.sessions_snapshot,
      'price_cents',customer_package.price_cents_snapshot,
      'remaining',customer_package.remaining,
      'status',customer_package.status,
      'service_id',customer_package.service_id_snapshot,
      'service_name',customer_package.service_name_snapshot,
      'variant_label',customer_package.service_variant_snapshot,
      'duration_min',customer_package.service_duration_min_snapshot,
      'list_unit_cents',customer_package.list_unit_cents_snapshot,
      'list_value_cents',customer_package.list_value_cents_snapshot,
      'purchased_at',customer_package.purchased_at
    ) order by customer_package.purchased_at desc,customer_package.id),'[]'::jsonb)
    from public.client_packages customer_package
    join public.clients client
      on client.id=customer_package.client_id
     and client.business_id=customer_package.business_id
    where customer_package.business_id=p_business
  );
end
$$;

--
-- Name: staff_list_returned_customers_v300(uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.staff_list_returned_customers_v300(p_business uuid, p_away_days integer, p_window_days integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_cap constant integer := 50;
  v_away integer := greatest(1, least(365, coalesce(p_away_days, 60)));
  v_window integer := greatest(1, least(90, coalesce(p_window_days, 30)));
  v_today date := (now() at time zone 'Asia/Singapore')::date;
  v_total bigint;
  v_rows jsonb;
begin
  -- Same gate as retention_lapsed_candidates_v244 (raises 42501 when out of scope).
  perform public.require_module_scope_v145(p_business, null, 'retention');

  with visit_rows as (
    select s.id, s.client_id, s.occurred_at, s.reversal_of
    from public.sales s
    where s.business_id = p_business
      and s.counts_as_visit = true
  ),
  valid_visits as (
    -- validVisitSales, verbatim from v244: reversals are never visits; a reversed
    -- original is out. The two readers MUST agree on what a visit is.
    select v.client_id, v.occurred_at
    from visit_rows v
    where v.reversal_of is null
      and not exists (
        select 1 from visit_rows r where r.reversal_of = v.id
      )
  ),
  ordered as (
    select vv.client_id, vv.occurred_at,
           lag(vv.occurred_at) over (partition by vv.client_id order by vv.occurred_at) as previous_visit_at,
           row_number() over (partition by vv.client_id order by vv.occurred_at desc) as recency
    from valid_visits vv
  ),
  returned as (
    -- The LATEST visit per client, only when it closed a gap of >= v_away days and
    -- landed inside the last v_window days (Singapore calendar on both counts).
    select o.client_id,
           o.occurred_at as returned_at,
           ((o.occurred_at at time zone 'Asia/Singapore')::date
             - (o.previous_visit_at at time zone 'Asia/Singapore')::date)::integer as away_days
    from ordered o
    where o.recency = 1
      and o.previous_visit_at is not null
      and (v_today - (o.occurred_at at time zone 'Asia/Singapore')::date) <= v_window
      and ((o.occurred_at at time zone 'Asia/Singapore')::date
            - (o.previous_visit_at at time zone 'Asia/Singapore')::date) >= v_away
  )
  select count(*),
         coalesce(jsonb_agg(x.row order by x.returned_at desc)
                    filter (where x.rank <= v_cap), '[]'::jsonb)
    into v_total, v_rows
    from (
      select r.returned_at,
             row_number() over (order by r.returned_at desc, r.client_id) as rank,
             jsonb_build_object(
               'id', c.id,
               'full_name', c.full_name,
               'phone', c.phone,
               'away_days', r.away_days,
               'returned_at', r.returned_at
             ) as row
      from returned r
      join public.clients c on c.id = r.client_id and c.business_id = p_business
    ) x;

  return jsonb_build_object(
    'away_days', v_away,
    'window_days', v_window,
    'total_returned', coalesce(v_total, 0),
    'truncated', coalesce(v_total, 0) > v_cap,
    'rows', v_rows
  );
end
$$;

--
-- Name: staff_list_visit_feedback(uuid, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.staff_list_visit_feedback(p_business uuid, p_status text DEFAULT NULL::text, p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_staff uuid;
  v_status text := nullif(btrim(lower(coalesce(p_status, ''))), '');
  v_limit integer := least(greatest(coalesce(p_limit, 50), 1), 200);
  v_result jsonb;
begin
  if v_actor is null then
    raise exception 'authenticated staff required' using errcode = '42501';
  end if;
  if not app.can_module_read(p_business, 'clients') then
    raise exception 'active customers-module read authorization is required' using errcode = '42501';
  end if;
  select s.id into v_staff
    from public.staff s
   where s.business_id = p_business and s.user_id = v_actor and s.active
   order by case when s.role = 'owner' then 0 else 1 end, s.created_at, s.id
   limit 1;
  if not found then
    raise exception 'active staff authorization is required' using errcode = '42501';
  end if;
  if v_status is not null and v_status not in ('open', 'acknowledged', 'resolved', 'closed') then
    raise exception 'unsupported feedback status filter' using errcode = '22023';
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
    'id', x.id,
    'client_id', x.client_id,
    'customer_name', x.full_name,
    'sale_id', x.sale_id,
    'rating', x.rating,
    'comment', x.comment,
    'recovery_status', x.recovery_status,
    'resolved_by', x.resolved_by,
    'resolved_at', x.resolved_at,
    'resolution_note', x.resolution_note,
    'created_at', x.created_at
  ) order by x.created_at desc, x.id desc), '[]'::jsonb)
    into v_result
    from (
      select f.id, f.client_id, c.full_name, f.sale_id, f.rating, f.comment,
             f.recovery_status, f.resolved_by, f.resolved_at, f.resolution_note, f.created_at
        from public.visit_feedback f
        left join public.clients c on c.id = f.client_id and c.business_id = f.business_id
       where f.business_id = p_business
         and (v_status is null or f.recovery_status = v_status)
       order by f.created_at desc, f.id desc
       limit v_limit
    ) x;
  return jsonb_build_object('status', 'ok', 'feedback', v_result);
end $$;

--
-- Name: staff_list_visit_feedback_v145(uuid, text, integer, integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.staff_list_visit_feedback_v145(p_business uuid, p_status text DEFAULT NULL::text, p_limit integer DEFAULT 100, p_offset integer DEFAULT 0, p_client uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_staff uuid;
  v_status text := nullif(btrim(lower(coalesce(p_status, ''))), '');
  v_limit integer := least(greatest(coalesce(p_limit, 100), 1), 100);
  v_offset integer := greatest(coalesce(p_offset, 0), 0);
  v_total bigint;
  v_items jsonb;
begin
  if v_actor is null or not app.can_module_read(p_business, 'clients') then
    raise exception 'active customers-module read authorization is required'
      using errcode = '42501';
  end if;
  select staff.id into v_staff
    from public.staff staff
   where staff.business_id = p_business
     and staff.user_id = v_actor
     and staff.active
   order by case when staff.role = 'owner' then 0 else 1 end,
            staff.created_at, staff.id
   limit 1;
  if not found then
    raise exception 'active staff authorization is required'
      using errcode = '42501';
  end if;
  if v_status is not null
     and v_status not in ('open', 'acknowledged', 'resolved', 'closed') then
    raise exception 'unsupported feedback status filter'
      using errcode = '22023';
  end if;
  if p_client is not null and not exists (
    select 1 from public.clients client
     where client.id = p_client and client.business_id = p_business
  ) then
    raise exception 'customer does not belong to this business'
      using errcode = '42501';
  end if;

  select count(*) into v_total
    from public.visit_feedback feedback
   where feedback.business_id = p_business
     and (v_status is null or feedback.recovery_status = v_status)
     and (p_client is null or feedback.client_id = p_client);

  select coalesce(jsonb_agg(jsonb_build_object(
    'id', page.id,
    'client_id', page.client_id,
    'customer_name', page.full_name,
    'sale_id', page.sale_id,
    'rating', page.rating,
    'comment', page.comment,
    'recovery_status', page.recovery_status,
    'resolved_by', page.resolved_by,
    'resolved_at', page.resolved_at,
    'resolution_note', page.resolution_note,
    'created_at', page.created_at
  ) order by page.created_at desc, page.id desc), '[]'::jsonb)
    into v_items
    from (
      select feedback.id, feedback.client_id, client.full_name, feedback.sale_id,
             feedback.rating, feedback.comment, feedback.recovery_status,
             feedback.resolved_by, feedback.resolved_at, feedback.resolution_note,
             feedback.created_at
        from public.visit_feedback feedback
        left join public.clients client
          on client.id = feedback.client_id
         and client.business_id = feedback.business_id
       where feedback.business_id = p_business
         and (v_status is null or feedback.recovery_status = v_status)
         and (p_client is null or feedback.client_id = p_client)
       order by feedback.created_at desc, feedback.id desc
       limit v_limit offset v_offset
    ) page;

  return jsonb_build_object(
    'status', 'ok',
    'feedback', v_items,
    'total', v_total,
    'limit', v_limit,
    'offset', v_offset
  );
end;
$$;

--
-- Name: staff_manual_redeem_reward_v404(uuid, uuid, uuid, integer, uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.staff_manual_redeem_reward_v404(p_business uuid, p_client uuid, p_reward uuid, p_quantity integer, p_branch uuid, p_reason_code text, p_reason_note text, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_staff uuid;
  v_qty integer := coalesce(p_quantity,1);
  v_max constant integer := 20;
  v_existing public.loyalty_manual_redemptions_v404%rowtype;
  v_unit_key text;
  v_operation uuid;
  v_operations uuid[] := '{}';
  v_result json;
  v_last json;
  i integer;
begin
  if v_actor is null then
    raise exception 'authenticated staff required' using errcode='42501';
  end if;
  if p_idempotency_key is null or length(btrim(p_idempotency_key)) < 8 then
    raise exception 'idempotency key must contain at least 8 characters' using errcode='22023';
  end if;
  -- Quantity is bounded HERE; affordability is proved by actually performing each
  -- unit below, never by this function recomputing a balance against a cost.
  if v_qty < 1 or v_qty > v_max then
    raise exception 'manual_redeem_quantity_out_of_range' using errcode='22023';
  end if;
  if p_reason_code is null or p_reason_code not in ('customer_unable_to_show_qr','other') then
    raise exception 'manual_redeem_reason_required' using errcode='22023';
  end if;
  if p_reason_code='other' and coalesce(btrim(p_reason_note),'')='' then
    raise exception 'manual_redeem_reason_note_required' using errcode='22023';
  end if;
  -- The permission the owner defined, re-derived server-side. The browser's copy
  -- of it is a rendering hint and is never trusted.
  if not app.can_manual_redeem_v404(p_business, p_branch) then
    raise exception 'manual_reward_redemption is not permitted for this staff member or branch'
      using errcode='42501';
  end if;

  select s.id into v_staff from public.staff s
   where s.business_id=p_business and s.user_id=v_actor and s.active
   order by case when s.role='owner' then 0 else 1 end, s.created_at limit 1;

  -- Replay of the same action returns the same receipt and redeems nothing further.
  select * into v_existing from public.loyalty_manual_redemptions_v404
   where business_id=p_business and idempotency_key=p_idempotency_key;
  if found then
    return jsonb_build_object('status','duplicate_ignored','quantity',v_existing.quantity,
                              'operation_ids',to_jsonb(v_existing.operation_ids));
  end if;

  -- Two staff cannot interleave halves of two multi-unit redemptions of one balance.
  perform pg_advisory_xact_lock(hashtextextended('v404:manual-redeem:'||p_business::text||':'||p_client::text, 0));

  for i in 1..v_qty loop
    -- One core call per unit, each with its own derived key: a replay of the whole
    -- action re-uses the same unit keys, and the core answers each from its stored
    -- result rather than redeeming again.
    v_unit_key := p_idempotency_key||':'||i::text;
    v_result := app.redeem_reward_core(p_business, p_client, p_reward, v_unit_key, p_branch, null, null);
    v_last := v_result;
    select o.id into v_operation from public.loyalty_operations o
     where o.business_id=p_business and o.operation_type='redeem_reward' and o.idempotency_key=v_unit_key;
    if v_operation is null then
      raise exception 'manual redemption operation was not recorded' using errcode='40001';
    end if;
    v_operations := v_operations || v_operation;
  end loop;

  insert into public.loyalty_manual_redemptions_v404(
    business_id,client_id,reward_id,staff_id,actor,branch_id,quantity,operation_ids,
    method,reason_code,reason_note,idempotency_key)
  values (p_business,p_client,p_reward,v_staff,v_actor,p_branch,v_qty,v_operations,
          'manual_no_qr',p_reason_code,nullif(btrim(p_reason_note),''),p_idempotency_key);

  return jsonb_build_object('status','ok','quantity',v_qty,
                            'operation_ids',to_jsonb(v_operations),'last',to_jsonb(v_last));
end
$$;

--
-- Name: staff_redeem_bringback_v361(uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.staff_redeem_bringback_v361(p_business uuid, p_client uuid, p_branch uuid, p_grant uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_grant public.bringback_grants_v361%rowtype;
  v_sale_id uuid := gen_random_uuid();
begin
  if v_actor is null then raise exception 'authenticated staff required' using errcode='42501'; end if;
  if not (app.is_salon_owner(p_business) or app.can_module_write(p_business,'till')
          or app.can_module_write(p_business,'loyalty')) then
    raise exception 'bringback redemption authorization required' using errcode='42501';
  end if;

  select * into v_grant from public.bringback_grants_v361
   where id=p_grant and business_id=p_business and client_id=p_client for update;
  if not found then raise exception 'bringback_grant_not_found' using errcode='22023'; end if;
  if v_grant.status='redeemed' then raise exception 'bringback_already_redeemed' using errcode='22023'; end if;
  if v_grant.status<>'granted' then raise exception 'bringback_not_redeemable' using errcode='22023'; end if;
  if v_grant.expires_at is not null and v_grant.expires_at<=now() then
    update public.bringback_grants_v361 set status='expired' where id=v_grant.id;
    raise exception 'bringback_expired' using errcode='22023';
  end if;

  perform 1 from public.branches branch
   where branch.id=p_branch and branch.business_id=p_business and branch.active
     and app.can_see_branch(p_business, branch.id);
  if not found then raise exception 'bringback_branch_not_permitted' using errcode='42501'; end if;

  -- A $0 sale: a real visit worth nothing, never phantom revenue (v215's own rule).
  insert into public.sales(id,business_id,client_id,kind,amount_cents,note,branch_id)
  values (v_sale_id,p_business,p_client,'retail',0,'bring-back voucher redeemed: '||v_grant.reward_label,p_branch);

  update public.bringback_grants_v361
     set status='redeemed', redeemed_at=now(), redeemed_sale_id=v_sale_id, redeemed_by=v_actor
   where id=v_grant.id;

  insert into public.audit_log(business_id,actor,action,entity,entity_id,detail)
  values(p_business,v_actor,'BRINGBACK_REDEEMED_V361','bringback_grants_v361',v_grant.id,
    jsonb_build_object('client_id',p_client,'branch_id',p_branch,'sale_id',v_sale_id,
                       'reward_label',v_grant.reward_label));

  return jsonb_build_object('status','completed','grant_id',v_grant.id,'sale_id',v_sale_id,
    'reward_label',v_grant.reward_label);
end $_$;

--
-- Name: staff_redeem_promotion_intent_v290(uuid, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.staff_redeem_promotion_intent_v290(p_business uuid, p_token text, p_branch uuid, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_token text := nullif(btrim(coalesce(p_token,'')),'');
  v_key text := nullif(btrim(coalesce(p_idempotency_key,'')),'');
  v_intent public.promotion_redemption_intents_v290%rowtype;
  v_existing public.promotion_redemptions_v290%rowtype;
  v_name text;
  v_customer text;
  v_id uuid;
begin
  -- Either right accepts an offer at the counter: the person who can record the sale, or the
  -- person who administers loyalty (which is what already gates the scanner the browser opens).
  if v_actor is null or p_business is null
     or not (app.can_module_write(p_business,'sales')
       or app.can_module_write(p_business,'loyalty')) then
    raise exception 'staff authorization is required to accept an offer' using errcode = '42501';
  end if;
  if v_token is null or char_length(v_token) not between 20 and 512 then
    raise exception 'a redemption token is required' using errcode = '22023';
  end if;
  if v_key is null or char_length(v_key) not between 8 and 200 then
    raise exception 'an idempotency key of 8 to 200 characters is required' using errcode = '22023';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended(p_business::text||':promotion-redeem-v290:'||v_key,0));

  select * into v_existing from public.promotion_redemptions_v290 record
   where record.business_id = p_business and record.idempotency_key = v_key;
  if found then
    return jsonb_build_object('status','duplicate_ignored','redemption_id',v_existing.id,
      'intent_id',v_existing.intent_id,'promotion_id',v_existing.promotion_id,
      'redeemed_at',v_existing.created_at);
  end if;

  select * into v_intent from public.promotion_redemption_intents_v290 intent
   where intent.business_id = p_business
     and intent.token_hash = app.v89_sha256(v_token)
   for update;
  if not found then
    raise exception 'this offer code does not belong to this business' using errcode = '22023';
  end if;
  if v_intent.status = 'redeemed' then
    return jsonb_build_object('status','already_redeemed','intent_id',v_intent.id,
      'promotion_id',v_intent.promotion_id,'redeemed_at',v_intent.redeemed_at);
  end if;
  if v_intent.status <> 'pending' or v_intent.expires_at <= now() then
    update public.promotion_redemption_intents_v290 stale
       set status = 'expired'
     where stale.id = v_intent.id and stale.status = 'pending';
    return jsonb_build_object('status','expired','intent_id',v_intent.id,
      'promotion_id',v_intent.promotion_id,'expires_at',v_intent.expires_at);
  end if;
  if p_branch is not null and not app.can_see_branch(p_business,p_branch) then
    raise exception 'this branch is not in your scope' using errcode = '42501';
  end if;

  update public.promotion_redemption_intents_v290 intent
     set status = 'redeemed', redeemed_at = now(), redeemed_by = v_actor
   where intent.id = v_intent.id;

  insert into public.promotion_redemptions_v290(
    business_id,promotion_id,intent_id,client_id,branch_id,staff_actor,idempotency_key,detail
  ) values (
    p_business,v_intent.promotion_id,v_intent.id,v_intent.client_id,p_branch,v_actor,v_key,
    jsonb_build_object('identity_id',v_intent.identity_id,'intent_created_at',v_intent.created_at)
  ) returning id into v_id;

  select coalesce(copy.name,'Offer') into v_name
    from public.business_localized_copy_v95 copy
   where copy.business_id = p_business
     and copy.entity_type = 'offer'
     and copy.entity_id = v_intent.promotion_id
     and copy.locale = 'en';
  select customer.full_name into v_customer
    from public.clients customer
   where customer.id = v_intent.client_id and customer.business_id = p_business;

  insert into public.audit_log(business_id, actor, action, entity, entity_id, detail)
  values (p_business, v_actor, 'PROMOTION_REDEEMED_V290',
    'promotion_redemptions_v290', v_id,
    jsonb_build_object('promotion_id',v_intent.promotion_id,'intent_id',v_intent.id,
      'client_id',v_intent.client_id,'branch_id',p_branch));

  return jsonb_build_object('status','redeemed','redemption_id',v_id,'intent_id',v_intent.id,
    'promotion_id',v_intent.promotion_id,'promotion_name',coalesce(v_name,'Offer'),
    'customer_name',coalesce(v_customer,'Customer'),'redeemed_at',now());
end;
$$;

--
-- Name: staff_redeem_referral_v420(uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.staff_redeem_referral_v420(p_business uuid, p_client uuid, p_branch uuid, p_grant uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_grant public.referral_grants_v420%rowtype;
  v_sale_id uuid := gen_random_uuid();
begin
  if v_actor is null then raise exception 'authenticated staff required' using errcode='42501'; end if;
  if not (app.is_salon_owner(p_business) or app.can_module_write(p_business,'till')
          or app.can_module_write(p_business,'referrals')) then
    raise exception 'referral redemption authorization required' using errcode='42501';
  end if;

  select * into v_grant from public.referral_grants_v420
   where id=p_grant and business_id=p_business and client_id=p_client for update;
  if not found then raise exception 'referral_grant_not_found' using errcode='22023'; end if;
  if v_grant.status='redeemed' then raise exception 'referral_already_redeemed' using errcode='22023'; end if;
  if v_grant.status<>'granted' then raise exception 'referral_not_redeemable' using errcode='22023'; end if;
  if v_grant.expires_at is not null and v_grant.expires_at<=now() then
    update public.referral_grants_v420 set status='expired' where id=v_grant.id;
    raise exception 'referral_expired' using errcode='22023';
  end if;

  perform 1 from public.branches branch
   where branch.id=p_branch and branch.business_id=p_business and branch.active
     and app.can_see_branch(p_business, branch.id);
  if not found then raise exception 'referral_branch_not_permitted' using errcode='42501'; end if;

  -- A $0 sale: a real visit worth nothing, never phantom revenue.
  insert into public.sales(id,business_id,client_id,kind,amount_cents,note,branch_id)
  values (v_sale_id,p_business,p_client,'retail',0,'referral gift redeemed: '||v_grant.reward_label,p_branch);

  update public.referral_grants_v420
     set status='redeemed', redeemed_at=now(), redeemed_sale_id=v_sale_id, redeemed_by=v_actor
   where id=v_grant.id;

  insert into public.audit_log(business_id,actor,action,entity,entity_id,detail)
  values(p_business,v_actor,'REFERRAL_GIFT_REDEEMED_V420','referral_grants_v420',v_grant.id,
    jsonb_build_object('client_id',p_client,'branch_id',p_branch,'sale_id',v_sale_id,
                       'reward_label',v_grant.reward_label));

  return jsonb_build_object('status','completed','grant_id',v_grant.id,'sale_id',v_sale_id,
    'reward_label',v_grant.reward_label);
end $_$;

--
-- Name: staff_redeem_welcome_offer_v215(uuid, uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.staff_redeem_welcome_offer_v215(p_business uuid, p_client uuid, p_branch uuid, p_qualifying_sale uuid, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_staff uuid;
  v_grant public.welcome_offer_grants_v215%rowtype;
  v_sale_id uuid := gen_random_uuid();
  v_spend bigint := 0;
  v_result jsonb;
begin
  p_idempotency_key := btrim(p_idempotency_key);
  if v_actor is null or p_idempotency_key is null or length(p_idempotency_key) < 8 then
    raise exception 'authenticated staff and valid idempotency key required' using errcode='22023';
  end if;
  if not app.has_perm(p_business,'create_sales')
     or not (app.can_module_write(p_business,'till')
             or app.can_module_write(p_business,'sales')) then
    raise exception 'welcome offer redemption authorization required' using errcode='42501';
  end if;

  select staff_row.id into v_staff
  from public.staff staff_row
  where staff_row.business_id = p_business
    and staff_row.user_id = v_actor
    and staff_row.active
    and 'create_sales' = any(app.role_perms(staff_row.role))
  order by case staff_row.role when 'owner' then 0 when 'manager' then 1 else 2 end,
           staff_row.created_at, staff_row.id
  limit 1;
  if v_staff is null then
    raise exception 'active staff authorization required' using errcode='42501';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(
    'v215:welcome-offer:'||p_business::text||':'||p_idempotency_key, 0));

  select * into v_grant
  from public.welcome_offer_grants_v215
  where business_id = p_business and client_id = p_client
  for update;
  if not found then
    raise exception 'welcome_offer_not_found' using errcode='22023';
  end if;

  -- Replay of the same request returns the same receipt rather than a second
  -- free item. A double-tap at a busy counter must not cost the firm twice.
  if v_grant.status = 'redeemed' then
    if v_grant.redeem_idempotency_key is not distinct from p_idempotency_key then
      return jsonb_build_object('status','completed','replayed',true,
        'grant_id',v_grant.id,'sale_id',v_grant.redeemed_sale_id,
        'reward_label',v_grant.reward_label);
    end if;
    raise exception 'welcome_offer_already_redeemed' using errcode='22023';
  end if;
  if v_grant.status <> 'granted' then
    raise exception 'welcome_offer_not_redeemable' using errcode='22023';
  end if;
  if v_grant.expires_at is not null and v_grant.expires_at <= now() then
    update public.welcome_offer_grants_v215 set status='expired' where id = v_grant.id;
    raise exception 'welcome_offer_expired' using errcode='22023';
  end if;

  perform 1 from public.branches branch
  where branch.id = p_branch and branch.business_id = p_business and branch.active
    and app.can_see_branch(p_business, branch.id);
  if not found then
    raise exception 'welcome_offer_branch_not_permitted' using errcode='42501';
  end if;

  -- The minimum spend is proved against a real recorded sale for this customer,
  -- never against a number the till sends. Zero minimum needs no sale at all,
  -- which is the owner's second example ("no minimum spend and free xx product").
  if v_grant.min_spend_cents > 0 then
    if p_qualifying_sale is null then
      raise exception 'welcome_offer_requires_qualifying_sale' using errcode='22023';
    end if;
    select sale.amount_cents into v_spend
    from public.sales sale
    where sale.id = p_qualifying_sale
      and sale.business_id = p_business
      and sale.client_id = p_client
      and sale.reversal_of is null
      and not exists(select 1 from public.sales reversal
                     where reversal.reversal_of = sale.id)
    for share;
    if v_spend is null then
      raise exception 'welcome_offer_qualifying_sale_not_found' using errcode='22023';
    end if;
    if v_spend < v_grant.min_spend_cents then
      raise exception 'welcome_offer_min_spend_not_met' using errcode='22023';
    end if;
  end if;

  -- The free item is a $0 sale, exactly as a package session is: a real visit
  -- worth nothing. It must never look like revenue.
  insert into public.sales(id, business_id, client_id, kind, amount_cents, note, branch_id, staff_id)
  values (v_sale_id, p_business, p_client,
          case when v_grant.reward_catalog_kind = 'service' then 'service' else 'retail' end,
          0, 'welcome offer redeemed: '||v_grant.reward_label, p_branch, v_staff);

  update public.welcome_offer_grants_v215
  set status='redeemed', redeemed_at=now(), redeemed_sale_id=v_sale_id,
      redeemed_by=v_actor, qualifying_sale_id=p_qualifying_sale,
      redeem_idempotency_key=p_idempotency_key
  where id = v_grant.id;

  insert into public.audit_log(business_id, actor, action, entity, entity_id, detail)
  values (p_business, v_actor, 'WELCOME_OFFER_REDEEMED_V215',
          'welcome_offer_grants_v215', v_grant.id, jsonb_build_object(
    'grant_id', v_grant.id, 'client_id', p_client, 'branch_id', p_branch,
    'sale_id', v_sale_id, 'reward_label', v_grant.reward_label,
    'min_spend_cents', v_grant.min_spend_cents,
    'qualifying_sale_id', p_qualifying_sale, 'qualifying_amount_cents', v_spend));

  v_result := jsonb_build_object('status','completed','replayed',false,
    'grant_id',v_grant.id,'sale_id',v_sale_id,'reward_label',v_grant.reward_label,
    'reward_catalog_kind',v_grant.reward_catalog_kind);
  return v_result;
end
$_$;

--
-- Name: staff_reschedule_and_confirm_booking_request_v329(uuid, uuid, timestamp with time zone, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.staff_reschedule_and_confirm_booking_request_v329(p_business uuid, p_request uuid, p_preferred timestamp with time zone, p_staff uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_request public.booking_requests%rowtype;
begin
  -- Defence in depth, matching the existing decline check's shape in
  -- staff_decide_booking_request_v73_v94_base. The real, branch-scoped authorization still
  -- happens inside the staff_decide_booking_request_v73 call below via
  -- app.require_branch_module_v94 — this is not a substitute for it.
  if not app.can_module_write(p_business, 'bookings') then
    raise exception 'booking write access is required' using errcode = '42501';
  end if;

  select * into v_request
    from public.booking_requests
   where id = p_request and business_id = p_business
   for update;
  if not found then
    raise exception 'booking request not found' using errcode = '22023';
  end if;
  if v_request.status not in ('new', 'pending', 'waitlisted') then
    raise exception 'this request is no longer pending' using errcode = '22023';
  end if;

  if p_preferred is null or p_preferred < clock_timestamp() then
    raise exception 'a future date and time is required' using errcode = '22023';
  end if;

  if p_staff is not null and not exists (
    select 1 from public.staff member
     where member.id = p_staff
       and member.business_id = p_business
       and coalesce(member.active, true)
  ) then
    raise exception 'invalid request' using errcode = '22023';
  end if;

  update public.booking_requests
     set preferred_at = p_preferred,
         staff_id = coalesce(p_staff, staff_id)
   where id = p_request and business_id = p_business;

  return public.staff_decide_booking_request_v73(p_business, p_request, 'confirm', null);
end;
$$;

--
-- Name: staff_resolve_feedback(uuid, uuid, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.staff_resolve_feedback(p_business uuid, p_feedback uuid, p_new_status text, p_note text DEFAULT NULL::text, p_idempotency_key uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_staff uuid;
  v_new text := nullif(btrim(lower(coalesce(p_new_status, ''))), '');
  v_note text := nullif(btrim(p_note), '');
  v_row public.visit_feedback%rowtype;
begin
  if v_actor is null then
    raise exception 'authenticated staff required' using errcode = '42501';
  end if;
  if not app.can_module_write(p_business, 'clients')
     or not app.has_perm(p_business, 'refund_sales') then
    raise exception 'customers-module write and refund_sales authorization is required'
      using errcode = '42501';
  end if;
  select s.id into v_staff
    from public.staff s
   where s.business_id = p_business and s.user_id = v_actor and s.active
     and 'refund_sales' = any (app.role_perms(s.role))
   order by case when s.role = 'owner' then 0 else 1 end, s.created_at, s.id
   limit 1;
  if not found then
    raise exception 'active staff authorization is required' using errcode = '42501';
  end if;
  if v_new not in ('acknowledged', 'resolved') then
    raise exception 'new status must be acknowledged or resolved' using errcode = '22023';
  end if;
  if v_note is not null and length(v_note) > 2000 then
    raise exception 'resolution note is too long' using errcode = '22023';
  end if;

  select * into v_row from public.visit_feedback f
   where f.id = p_feedback and f.business_id = p_business
   for update;
  if not found then
    raise exception 'feedback not found in this business' using errcode = '42501';
  end if;

  -- Idempotent no-op: already in the requested state.
  if v_row.recovery_status = v_new then
    return app.v53_feedback_staff_json(v_row);
  end if;
  if not (
       (v_row.recovery_status = 'open' and v_new in ('acknowledged', 'resolved'))
    or (v_row.recovery_status = 'acknowledged' and v_new = 'resolved')
  ) then
    raise exception 'illegal service-recovery transition % -> %', v_row.recovery_status, v_new
      using errcode = '22023';
  end if;

  perform set_config('app.visit_feedback_resolve_id', p_feedback::text, true);
  update public.visit_feedback f
     set recovery_status = v_new,
         resolved_by = case when v_new = 'resolved' then v_staff else f.resolved_by end,
         resolved_at = case when v_new = 'resolved' then now() else f.resolved_at end,
         resolution_note = coalesce(v_note, f.resolution_note)
   where f.id = p_feedback and f.business_id = p_business
   returning * into v_row;
  perform set_config('app.visit_feedback_resolve_id', '', true);

  return app.v53_feedback_staff_json(v_row);
end $$;

--
-- Name: staff_scan_member_qr_v327(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.staff_scan_member_qr_v327(p_business uuid, p_member_qr text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $_$
declare
  v_token text;
  v_hash text;
  v_identity public.customer_identities%rowtype;
  v_link public.customer_links%rowtype;
  v_client public.clients%rowtype;
  v_actor uuid := auth.uid();
  v_display_name text;
  v_link_id uuid;
  v_created boolean := false;
  v_points integer;
  v_credit integer;
  v_visits integer;
  lp record;
begin
  if not app.has_perm(p_business, 'create_sales')
     or not app.can_module_write(p_business, 'clients') then
    raise exception 'clients write and create-sales authorization is required'
      using errcode='42501';
  end if;

  v_token := btrim(coalesce(p_member_qr,''));
  if v_token like 'nestly:member:%' then
    v_token := substring(v_token from length('nestly:member:')+1);
  end if;
  if v_token !~ '^[0-9a-f]{64}$' then
    return jsonb_build_object('status','invalid','message','This QR is not a Peekaa member code.');
  end if;
  v_hash := app.v89_sha256(v_token);

  perform pg_advisory_xact_lock(hashtextextended('v327:scan:'||p_business::text||':'||v_hash,0));

  select * into v_identity from public.customer_identities
   where qr_token_hash = v_hash for share;
  if not found or v_identity.status <> 'active' then
    return jsonb_build_object('status','invalid','message','This member QR is no longer active.');
  end if;

  select * into v_link from public.customer_links
   where business_id=p_business and identity_id=v_identity.id and state='verified'
   order by created_at desc limit 1
   for update;

  if found then
    select * into v_client from public.clients where id=v_link.client_id and business_id=p_business;
  else
    select coalesce(nullif(btrim(u.raw_user_meta_data->>'full_name'),''), 'Peekaa Member')
      into v_display_name
      from auth.users u where u.id=v_identity.auth_user_id;

    insert into public.clients (business_id, full_name)
    values (p_business, v_display_name)
    returning * into v_client;

    v_link_id := gen_random_uuid();
    perform set_config('app.customer_link_insert_id', v_link_id::text, true);
    insert into public.customer_links (
      id, business_id, identity_id, auth_user_id, client_id, state,
      verification_method, verified_at
    ) values (
      v_link_id, p_business, v_identity.id, v_identity.auth_user_id, v_client.id, 'verified',
      'qr_scan', now()
    )
    returning * into v_link;
    perform set_config('app.customer_link_insert_id', '', true);
    v_created := true;

    insert into public.audit_log(business_id,actor,action,entity,entity_id,detail)
    values(p_business, v_actor, 'AUTO_PROVISION_CLIENT_FROM_MEMBER_QR_V327',
      'clients', v_client.id, jsonb_build_object('identity_id', v_identity.id, 'link_id', v_link.id));
  end if;

  v_points := app.client_points_balance_v409(p_business, v_client.id);
  select coalesce(sum(amount_cents),0) into v_credit
    from public.credit_ledger where business_id=p_business and client_id=v_client.id;
  select count(*) into v_visits
    from public.sales where business_id=p_business and client_id=v_client.id and counts_as_visit;
  select * into lp from public.loyalty_programs
   where business_id=p_business and active limit 1;

  return jsonb_build_object(
    'status','found','client_id',v_client.id,'full_name',v_client.full_name,
    'phone',v_client.phone_norm,
    'points',v_points,'credit_cents',v_credit,'visits',v_visits,
    'redeem_points',lp.redeem_points,'reward_credit_cents',lp.reward_credit_cents,
    'can_redeem',(lp.redeem_points is not null and v_points>=lp.redeem_points),
    'points_to_next',greatest(coalesce(lp.redeem_points,0)-v_points,0),
    'member_since',v_client.created_at,
    'newly_linked',v_created);
end $_$;

--
-- Name: staff_set_marketing_consent(uuid, uuid, uuid, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.staff_set_marketing_consent(p_business uuid, p_client uuid, p_idempotency_key uuid, p_marketing_consent boolean, p_source text DEFAULT 'staff client page'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_staff uuid;
  v_source text := coalesce(nullif(btrim(p_source), ''), 'staff client page');
  v_payload jsonb;
  v_hash text;
  v_existing public.customer_staff_operations%rowtype;
  v_client public.clients%rowtype;
  v_consent_id uuid;
  v_result jsonb;
begin
  if v_actor is null or not app.can_module_write(p_business, 'clients') then
    raise exception 'active clients-module write authorization is required'
      using errcode = '42501';
  end if;
  select s.id into v_staff
    from public.staff s
   where s.business_id = p_business
     and s.user_id = v_actor
     and s.active
   order by case when s.role = 'owner' then 0 else 1 end, s.created_at
   limit 1
   for update;
  if not found then
    raise exception 'active staff authorization is required'
      using errcode = '42501';
  end if;
  if p_client is null or p_idempotency_key is null or p_marketing_consent is null
     or char_length(v_source) > 200 then
    raise exception 'invalid consent request' using errcode = '22023';
  end if;

  v_payload := jsonb_build_object(
    'business_id', p_business,
    'client_id', p_client,
    'marketing_consent', p_marketing_consent,
    'source', v_source
  );
  v_hash := app.v41_request_hash(v_payload::text);
  perform pg_advisory_xact_lock(hashtextextended(
    'v41:customer:' || p_business::text || ':' || p_idempotency_key::text, 0));

  select * into v_existing
    from public.customer_staff_operations o
   where o.business_id = p_business
     and o.idempotency_key = p_idempotency_key
   for update;
  if found then
    if v_existing.actor is distinct from v_actor
       or v_existing.operation_type <> 'consent_transition'
       or v_existing.request_hash <> v_hash then
      raise exception 'idempotency key conflicts with another customer request'
        using errcode = '23505';
    end if;
    return jsonb_build_object(
      'status', 'completed',
      'client_id', v_existing.client_id,
      'marketing_consent', v_existing.requested_marketing_consent,
      'consent_event_id', v_existing.consent_event_id
    );
  end if;

  select * into v_client
    from public.clients c
   where c.id = p_client
     and c.business_id = p_business
   for update;
  if not found then
    raise exception 'client does not belong to this business'
      using errcode = '22023';
  end if;
  if v_client.marketing_consent = p_marketing_consent then
    raise exception 'requested consent state is already current'
      using errcode = '22023';
  end if;

  update public.clients
     set marketing_consent = p_marketing_consent
   where id = p_client and business_id = p_business;
  insert into public.consents (
    business_id, client_id, channel, action, source, actor
  ) values (
    p_business, p_client, 'marketing',
    case when p_marketing_consent then 'granted' else 'withdrawn' end,
    v_source, v_actor
  ) returning id into v_consent_id;

  v_result := jsonb_build_object(
    'status', 'completed',
    'client_id', p_client,
    'marketing_consent', p_marketing_consent,
    'consent_event_id', v_consent_id
  );
  insert into public.customer_staff_operations (
    business_id, actor, operation_type, idempotency_key, request_hash, status,
    requested_marketing_consent, client_id, consent_event_id
  ) values (
    p_business, v_actor, 'consent_transition', p_idempotency_key, v_hash, 'completed',
    p_marketing_consent, p_client, v_consent_id
  );
  return v_result;
end
$$;

--
-- Name: staff_tier_benefits_for_client_v365(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.staff_tier_benefits_for_client_v365(p_business uuid, p_client uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_tier public.loyalty_tiers%rowtype;
  v_rows jsonb;
  v_birthday boolean;
begin
  if auth.uid() is null then raise exception 'authenticated staff required' using errcode='42501'; end if;
  if not (app.is_salon_owner(p_business) or app.can_module_read(p_business,'till')
          or app.can_module_read(p_business,'loyalty')) then
    raise exception 'till or loyalty access required' using errcode='42501';
  end if;
  perform 1 from public.clients where id=p_client and business_id=p_business;
  if not found then raise exception 'client not found in this business' using errcode='42704'; end if;

  v_tier := app.v365_client_tier(p_business,p_client);
  if v_tier.id is null then
    return jsonb_build_object('status','ok','tier',null,'benefits','[]'::jsonb);
  end if;
  v_birthday := coalesce(app.v367_in_birthday_month(p_client, now()), false);

  select coalesce(jsonb_agg(jsonb_build_object(
      'benefit_id',b.id,'tier_id',b.tier_id,'tier_label',t.name,'label',b.label,
      'benefit_kind',b.benefit_kind,'discount_percent',b.discount_percent,
      'product_id',b.product_id,
      'item_label',coalesce((select p.name from public.products p where p.id=b.product_id),b.item_label),
      'limit_count',b.limit_count,'limit_period',b.limit_period,
      'sentence',app.v365_benefit_sentence(b.label,b.limit_count,b.limit_period),
      'used',used.count_in_period,
      'remaining',case when b.limit_count is null then null
                       else greatest(0,b.limit_count-used.count_in_period) end,
      'claimable_now',(b.limit_period<>'birthday_month' or v_birthday)
        and (b.limit_count is null or used.count_in_period < b.limit_count),
      'blocked_reason',case when b.limit_period='birthday_month' and not v_birthday then 'not_birthday_month'
                            when b.limit_count is not null and used.count_in_period >= b.limit_count then 'used_up'
                            else null end
    ) order by t.threshold desc, b.sort, b.id),'[]'::jsonb) into v_rows
    from public.tier_benefits_v365 b
    join public.loyalty_tiers t on t.id=b.tier_id and t.business_id=b.business_id
    cross join lateral (
      select count(*)::integer as count_in_period from public.tier_benefit_issues_v365 i
       where i.benefit_id=b.id and i.client_id=p_client
         and i.period_key=app.v365_period_key(b.limit_period,now())
    ) used
   where b.business_id=p_business and b.deleted_at is null and b.active
     and coalesce(t.paused,false)=false and t.deleted_at is null
     and t.threshold<=v_tier.threshold
     and (t.effective_from is null or t.effective_from<=statement_timestamp())
     and (t.expires_at is null or t.expires_at>statement_timestamp());

  return jsonb_build_object('status','ok',
    'tier',jsonb_build_object('id',v_tier.id,'label',v_tier.name,'threshold',v_tier.threshold),
    'in_birthday_month',v_birthday,
    'benefits',v_rows);
end $$;

--
-- Name: staff_update_client_v170(uuid, uuid, text, text, text, date, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.staff_update_client_v170(p_business uuid, p_client uuid, p_full_name text, p_phone text DEFAULT NULL::text, p_email text DEFAULT NULL::text, p_birth_date date DEFAULT NULL::date, p_gender text DEFAULT NULL::text, p_marketing_consent boolean DEFAULT NULL::boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_name text := nullif(btrim(p_full_name), '');
  v_phone text := nullif(btrim(p_phone), '');
  v_email text := nullif(lower(btrim(p_email)), '');
  v_gender text := nullif(lower(btrim(p_gender)), '');
  v_before public.clients%rowtype;
  v_client public.clients%rowtype;
  v_consent boolean;
begin
  if v_actor is null or not app.can_module_write(p_business, 'clients') then
    raise exception 'active clients-module write authorization is required'
      using errcode = '42501';
  end if;
  if not exists (
    select 1 from public.staff s
     where s.business_id = p_business and s.user_id = v_actor and s.active
  ) then
    raise exception 'active staff authorization is required' using errcode = '42501';
  end if;
  if p_client is null or v_name is null or char_length(v_name) < 2
     or char_length(v_name) > 200
     or (v_gender is not null and v_gender not in ('female','male','other'))
     or (v_phone is not null and char_length(v_phone) > 80)
     or (v_email is not null and char_length(v_email) > 320) then
    raise exception 'invalid customer request' using errcode = '22023';
  end if;

  select * into v_before from public.clients c
   where c.id = p_client and c.business_id = p_business
   for update;
  if not found then
    raise exception 'customer_not_found' using errcode = '22023';
  end if;

  v_consent := coalesce(p_marketing_consent, v_before.marketing_consent);

  begin
    update public.clients
       set full_name = v_name,
           phone = v_phone,
           email = v_email,
           birth_date = p_birth_date,
           gender = v_gender,
           marketing_consent = v_consent
     where id = p_client and business_id = p_business
     returning * into v_client;
  exception when unique_violation then
    raise exception 'phone_already_used_by_another_customer' using errcode = '23505';
  end;

  if v_consent is distinct from v_before.marketing_consent then
    insert into public.consents (business_id, client_id, channel, action, source, actor)
    values (p_business, p_client, 'marketing',
      case when v_consent then 'granted' else 'withdrawn' end,
      'staff customer edit', v_actor);
  end if;

  insert into public.audit_log (business_id, actor, action, entity, entity_id, detail)
  values (p_business, v_actor, 'CLIENT_UPDATED_V170', 'clients', p_client,
    jsonb_build_object(
      'before', jsonb_build_object('full_name', v_before.full_name, 'phone', v_before.phone,
        'email', v_before.email, 'birth_date', v_before.birth_date, 'gender', v_before.gender,
        'marketing_consent', v_before.marketing_consent),
      'after', jsonb_build_object('full_name', v_client.full_name, 'phone', v_client.phone,
        'email', v_client.email, 'birth_date', v_client.birth_date, 'gender', v_client.gender,
        'marketing_consent', v_client.marketing_consent)));

  return jsonb_build_object(
    'status', 'completed', 'client_id', v_client.id,
    'full_name', v_client.full_name, 'phone', v_client.phone, 'email', v_client.email,
    'birth_date', v_client.birth_date, 'gender', v_client.gender,
    'marketing_consent', v_client.marketing_consent);
end
$$;

--
-- Name: FUNCTION staff_update_client_v170(p_business uuid, p_client uuid, p_full_name text, p_phone text, p_email text, p_birth_date date, p_gender text, p_marketing_consent boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.staff_update_client_v170(p_business uuid, p_client uuid, p_full_name text, p_phone text, p_email text, p_birth_date date, p_gender text, p_marketing_consent boolean) IS 'V170: staff with clients write access correct a customer record; consent transitions write a consents event; before/after audited. Closes the "customer can never be edited" blocker.';

--
-- Name: stage_import_rows(uuid, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.stage_import_rows(p_business uuid, p_entity text, p_rows jsonb, p_idempotency_key text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_job_id uuid := gen_random_uuid();
  v_hash text;
  v_existing public.import_jobs%rowtype;
  v_raw jsonb;
  v_stored_raw jsonb;
  v_normalized jsonb;
  v_errors text[];
  v_row_number integer;
  v_total integer;
  v_valid integer := 0;
  v_invalid integer := 0;
  v_name text;
  v_phone text;
  v_phone_norm text;
  v_gender text;
  v_birth_date date;
  v_price bigint;
  v_duration bigint;
  v_qty bigint;
  v_pax bigint;
  v_sort bigint;
  v_role text;
  v_color text;
  v_timezone text;
  v_rows_inserted integer;
  v_error_preview json;
begin
  if not app.is_salon_owner(p_business) then
    raise exception 'only the business owner can stage imports' using errcode = '42501';
  end if;
  if p_entity not in (
    'customers', 'services', 'inventory', 'staff', 'branches', 'reservations'
  ) then
    raise exception 'unsupported import entity %', p_entity using errcode = '22023';
  end if;
  if p_idempotency_key is null or length(btrim(p_idempotency_key)) < 8 then
    raise exception 'idempotency key must contain at least 8 characters' using errcode = '22023';
  end if;
  if jsonb_typeof(p_rows) <> 'array' then
    raise exception 'import rows must be a JSON array' using errcode = '22023';
  end if;
  v_total := jsonb_array_length(p_rows);
  if v_total < 1 or v_total > 500 then
    raise exception 'an import must contain between 1 and 500 rows' using errcode = '22023';
  end if;
  p_idempotency_key := btrim(p_idempotency_key);
  v_hash := md5(p_rows::text);

  insert into public.import_jobs
    (id, business_id, entity_type, actor, idempotency_key, request_hash,
     total_rows, valid_rows, invalid_rows)
  values
    (v_job_id, p_business, p_entity, v_actor, p_idempotency_key, v_hash,
     v_total, 0, v_total)
  on conflict (business_id, entity_type, idempotency_key) do nothing;
  get diagnostics v_rows_inserted = row_count;

  if v_rows_inserted = 0 then
    select * into v_existing from public.import_jobs
     where business_id = p_business and entity_type = p_entity
       and idempotency_key = p_idempotency_key;
    if v_existing.actor is distinct from v_actor or v_existing.request_hash <> v_hash then
      raise exception 'idempotency key was already used for another import'
        using errcode = '22023';
    end if;
    select coalesce(json_agg(e order by e.row_number), '[]'::json) into v_error_preview
      from (
        select row_number, errors from public.import_rows
         where job_id = v_existing.id and cardinality(errors) > 0
         order by row_number limit 10
      ) e;
    return json_build_object(
      'job_id', v_existing.id, 'status', v_existing.status,
      'total', v_existing.total_rows, 'valid', v_existing.valid_rows,
      'invalid', v_existing.invalid_rows, 'errors', v_error_preview,
      'result', v_existing.result
    );
  end if;

  for v_raw, v_row_number in
    select value, ordinality::integer
      from jsonb_array_elements(p_rows) with ordinality
  loop
    v_errors := '{}';
    v_normalized := '{}'::jsonb;
    v_stored_raw := v_raw;
    if jsonb_typeof(v_raw) <> 'object' then
      v_errors := array_append(v_errors, 'row must be an object');
      v_stored_raw := jsonb_build_object('_invalid_value', v_raw);
    elsif octet_length(v_raw::text) > 32768 then
      v_errors := array_append(v_errors, 'row is too large');
      v_stored_raw := jsonb_build_object('_omitted', true);
    else
      v_name := btrim(coalesce(v_raw->>'full_name', v_raw->>'name', ''));
      if length(v_name) < 2 or length(v_name) > 160 then
        v_errors := array_append(v_errors, 'name must contain 2 to 160 characters');
      end if;

      if p_entity = 'customers' then
        v_phone := nullif(btrim(v_raw->>'phone'), '');
        v_gender := nullif(lower(btrim(v_raw->>'gender')), '');
        if v_gender is not null and v_gender not in ('female', 'male', 'other') then
          v_errors := array_append(v_errors, 'gender must be female, male or other');
        end if;
        v_birth_date := null;
        if nullif(btrim(v_raw->>'birth_date'), '') is not null then
          begin
            v_birth_date := (v_raw->>'birth_date')::date;
          exception when others then
            v_errors := array_append(v_errors, 'birth_date must be YYYY-MM-DD');
          end;
        end if;
        v_phone_norm := case when v_phone is null then null else app.norm_phone(v_phone) end;
        if v_phone is not null and v_phone_norm is null then
          v_errors := array_append(v_errors, 'phone number is invalid');
        elsif v_phone_norm is not null and exists (
          select 1 from public.clients
           where business_id = p_business and phone_norm = v_phone_norm
        ) then
          v_errors := array_append(v_errors, 'phone already belongs to a customer');
        end if;
        v_normalized := jsonb_strip_nulls(jsonb_build_object(
          'full_name', v_name, 'phone', v_phone,
          'email', nullif(btrim(v_raw->>'email'), ''), 'gender', v_gender,
          'birth_date', v_birth_date, 'notes', nullif(btrim(v_raw->>'notes'), '')
        ));
      elsif p_entity = 'services' then
        if coalesce(v_raw->>'price_cents', '') !~ '^[0-9]+$' then
          v_errors := array_append(v_errors, 'price must be zero or a positive whole number of cents');
          v_price := 0;
        else
          v_price := (v_raw->>'price_cents')::bigint;
          if v_price > 100000000 then v_errors := array_append(v_errors, 'price is too large'); end if;
        end if;
        if coalesce(v_raw->>'duration_min', '') !~ '^[0-9]+$' then
          v_errors := array_append(v_errors, 'duration must be a whole number of minutes');
          v_duration := 60;
        else
          v_duration := (v_raw->>'duration_min')::bigint;
          if v_duration < 1 or v_duration > 1440 then
            v_errors := array_append(v_errors, 'duration must be between 1 and 1440 minutes');
          end if;
        end if;
        v_normalized := jsonb_strip_nulls(jsonb_build_object(
          'name', v_name, 'price_cents', v_price, 'duration_min', v_duration,
          'category', nullif(btrim(v_raw->>'category'), ''),
          'description', nullif(btrim(v_raw->>'description'), '')
        ));
        if exists (
          select 1 from public.services s
           where s.business_id=p_business and lower(btrim(s.name))=lower(v_name)
             and s.price_cents=v_price and s.duration_min=v_duration
        ) then v_errors:=array_append(v_errors,'matching service already exists'); end if;
      elsif p_entity = 'inventory' then
        if coalesce(v_raw->>'retail_price_cents', '') !~ '^[0-9]+$' then
          v_errors := array_append(v_errors, 'retail price must be zero or a positive whole number of cents');
          v_price := 0;
        else
          v_price := (v_raw->>'retail_price_cents')::bigint;
          if v_price > 100000000 then v_errors := array_append(v_errors, 'retail price is too large'); end if;
        end if;
        if coalesce(v_raw->>'opening_qty', '0') !~ '^[0-9]+$' then
          v_errors := array_append(v_errors, 'opening quantity must be a positive whole number');
          v_qty := 0;
        else
          v_qty := coalesce((v_raw->>'opening_qty')::bigint, 0);
          if v_qty > 100000000 then v_errors := array_append(v_errors, 'opening quantity is too large'); end if;
        end if;
        if nullif(btrim(v_raw->>'sku'), '') is not null and exists (
          select 1 from public.products
           where business_id = p_business and sku = btrim(v_raw->>'sku')
        ) then
          v_errors := array_append(v_errors, 'SKU already exists');
        end if;
        v_normalized := jsonb_strip_nulls(jsonb_build_object(
          'name', v_name, 'sku', nullif(btrim(v_raw->>'sku'), ''),
          'retail_price_cents', v_price, 'opening_qty', v_qty
        ));
      elsif p_entity = 'staff' then
        v_role := coalesce(nullif(lower(btrim(v_raw->>'role')), ''), 'staff');
        v_color := coalesce(nullif(btrim(v_raw->>'calendar_color'), ''), '#7C9CBF');
        if v_role not in ('manager', 'staff', 'frontdesk', 'bookkeeper') then
          v_errors := array_append(v_errors, 'role must be manager, staff, frontdesk or bookkeeper');
        end if;
        if v_color !~ '^#[0-9A-Fa-f]{6}$' then
          v_errors := array_append(v_errors, 'calendar colour must be a 6-digit hex colour');
        end if;
        v_normalized := jsonb_strip_nulls(jsonb_build_object(
          'full_name', v_name, 'email', nullif(btrim(v_raw->>'email'), ''),
          'phone', nullif(btrim(v_raw->>'phone'), ''),
          'title', nullif(btrim(v_raw->>'title'), ''),
          'role', v_role, 'calendar_color', v_color
        ));
        if exists (
          select 1 from public.staff s where s.business_id=p_business and (
            (nullif(btrim(v_raw->>'email'),'') is not null
             and lower(btrim(s.email))=lower(btrim(v_raw->>'email')))
            or (nullif(regexp_replace(coalesce(v_raw->>'phone',''),'\D','','g'),'') is not null
                and regexp_replace(coalesce(s.phone,''),'\D','','g')=
                    regexp_replace(v_raw->>'phone','\D','','g'))
          )
        ) then v_errors:=array_append(v_errors,'staff email or phone already exists'); end if;
      elsif p_entity = 'branches' then
        v_timezone := coalesce(nullif(btrim(v_raw->>'timezone'), ''), 'Asia/Singapore');
        if not exists (select 1 from pg_timezone_names where name = v_timezone) then
          v_errors := array_append(v_errors, 'timezone is not recognised');
        end if;
        v_normalized := jsonb_strip_nulls(jsonb_build_object(
          'name', v_name, 'address', nullif(btrim(v_raw->>'address'), ''),
          'phone', nullif(btrim(v_raw->>'phone'), ''),
          'email', nullif(btrim(v_raw->>'email'), ''), 'timezone', v_timezone
        ));
        if exists (
          select 1 from public.branches b where b.business_id=p_business
           and lower(btrim(b.name))=lower(v_name)
           and lower(btrim(coalesce(b.address,'')))=
               lower(btrim(coalesce(v_raw->>'address','')))
        ) then v_errors:=array_append(v_errors,'matching branch already exists'); end if;
      else
        if coalesce(v_raw->>'quantity', '') !~ '^[0-9]+$' then
          v_errors := array_append(v_errors, 'quantity must be a positive whole number');
          v_qty := 1;
        else
          v_qty := (v_raw->>'quantity')::bigint;
          if v_qty < 1 or v_qty > 1000 then
            v_errors := array_append(v_errors, 'quantity must be between 1 and 1000');
          end if;
        end if;
        v_pax := null;
        if nullif(v_raw->>'pax', '') is not null then
          if (v_raw->>'pax') !~ '^[0-9]+$' then
            v_errors := array_append(v_errors, 'pax must be a positive whole number');
          else
            v_pax := (v_raw->>'pax')::bigint;
            if v_pax < 1 or v_pax > 1000 then
              v_errors := array_append(v_errors, 'pax must be between 1 and 1000');
            end if;
          end if;
        end if;
        if coalesce(v_raw->>'sort', '0') !~ '^-?[0-9]+$' then
          v_errors := array_append(v_errors, 'sort must be a whole number');
          v_sort := 0;
        else
          v_sort := coalesce((v_raw->>'sort')::bigint, 0);
        end if;
        v_normalized := jsonb_strip_nulls(jsonb_build_object(
          'name', v_name, 'pax', v_pax, 'quantity', v_qty, 'sort', v_sort
        ));
        if exists (
          select 1 from public.booking_tables t where t.business_id=p_business
           and lower(btrim(t.name))=lower(v_name)
           and t.pax is not distinct from v_pax::integer
        ) then v_errors:=array_append(v_errors,'matching reservation table already exists'); end if;
      end if;
    end if;

    insert into public.import_rows
      (job_id, business_id, row_number, raw_data, normalized_data, errors)
    values
      (v_job_id, p_business, v_row_number, v_stored_raw, v_normalized, v_errors);
    if cardinality(v_errors) = 0 then v_valid := v_valid + 1;
    else v_invalid := v_invalid + 1;
    end if;
  end loop;

  -- Identify duplicates inside this upload before commit, so the owner gets row-specific
  -- feedback instead of a generic unique-constraint failure after pressing Import.
  if p_entity = 'customers' then
    update public.import_rows current_row
       set errors = array_append(current_row.errors, 'phone is duplicated in this import')
     where current_row.job_id = v_job_id
       and nullif(current_row.normalized_data->>'phone', '') is not null
       and exists (
         select 1 from public.import_rows earlier
          where earlier.job_id = current_row.job_id
            and earlier.row_number < current_row.row_number
            and app.norm_phone(earlier.normalized_data->>'phone')
                = app.norm_phone(current_row.normalized_data->>'phone')
       );
  elsif p_entity = 'inventory' then
    update public.import_rows current_row
       set errors = array_append(current_row.errors, 'SKU is duplicated in this import')
     where current_row.job_id = v_job_id
       and nullif(current_row.normalized_data->>'sku', '') is not null
       and exists (
         select 1 from public.import_rows earlier
          where earlier.job_id = current_row.job_id
            and earlier.row_number < current_row.row_number
            and earlier.normalized_data->>'sku' = current_row.normalized_data->>'sku'
       );
  else
    update public.import_rows current_row
       set errors = array_append(current_row.errors, 'matching row is duplicated in this import')
     where current_row.job_id = v_job_id
       and exists (
         select 1 from public.import_rows earlier
          where earlier.job_id = current_row.job_id
            and earlier.row_number < current_row.row_number
            and earlier.normalized_data = current_row.normalized_data
       );
  end if;

  select count(*) filter (where cardinality(errors) = 0),
         count(*) filter (where cardinality(errors) > 0)
    into v_valid, v_invalid
    from public.import_rows where job_id = v_job_id;

  update public.import_jobs
     set valid_rows = v_valid, invalid_rows = v_invalid
   where id = v_job_id;
  select coalesce(json_agg(e order by e.row_number), '[]'::json) into v_error_preview
    from (
      select row_number, errors from public.import_rows
       where job_id = v_job_id and cardinality(errors) > 0
       order by row_number limit 10
    ) e;
  return json_build_object(
    'job_id', v_job_id, 'status', 'staged', 'total', v_total,
    'valid', v_valid, 'invalid', v_invalid, 'errors', v_error_preview
  );
end $_$;

--
-- Name: start_billing_reconciliation_v77(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.start_billing_reconciliation_v77(p_run_mode text, p_cursor_start text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_id uuid;
begin
  if p_run_mode not in ('dry_run','apply','scheduled') then
    raise exception 'invalid reconciliation mode' using errcode='22023';
  end if;
  insert into public.billing_reconciliation_runs(run_mode,cursor_start)
  values(p_run_mode,p_cursor_start) returning id into v_id;
  return v_id;
end
$$;

--
-- Name: start_business_onboarding_v79(uuid, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.start_business_onboarding_v79(p_business uuid, p_expected_version bigint, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid:=auth.uid();v_hash text;v_replay jsonb;
  v_check public.business_onboarding_checklists%rowtype;
  v_prospect public.sme_prospects%rowtype;v_response jsonb;
  v_onboarding_started_at timestamptz;
begin
  if not app.is_platform_operator_v75() then raise exception 'platform operator access is required' using errcode='42501';end if;
  perform app.require_idempotency_key_v79(p_idempotency_key);
  v_hash:=app.v76_sha256_hex(jsonb_build_object('business',p_business,'version',p_expected_version)::text);
  v_replay:=app.v76_replay(v_actor,'start_onboarding_v79',p_idempotency_key,v_hash);if v_replay is not null then return v_replay;end if;
  select * into v_check from public.business_onboarding_checklists where business_id=p_business for update;
  if not found or v_check.version<>p_expected_version then raise exception 'onboarding version conflict' using errcode='40001';end if;
  if v_check.status='in_progress' then
    v_response:=jsonb_build_object('replayed',false,'onboarding',app.get_onboarding_core_v79(p_business));
    perform app.v76_store_receipt(v_actor,'start_onboarding_v79',p_idempotency_key,v_hash,v_response);
    return v_response;
  end if;
  if v_check.status<>'not_started' then raise exception 'onboarding cannot start from its current status' using errcode='22023';end if;
  if not exists(
    select 1 from public.business_onboarding_items
    where checklist_id=v_check.id and item_key='owner_access' and status='satisfied'
  ) then raise exception 'workspace owner must accept access before onboarding starts' using errcode='22023';end if;
  update public.business_onboarding_checklists set status='in_progress',
    started_at=coalesce(started_at,now()),version=version+1,updated_at=now() where id=v_check.id;
  select * into v_prospect from public.sme_prospects where id=v_check.prospect_id for update;
  perform set_config('app.v79_system_transition','on',true);
  update public.businesses
    set onboarding_started_at=coalesce(onboarding_started_at,now()),updated_at=now()
    where id=p_business
    returning onboarding_started_at into v_onboarding_started_at;
  if v_prospect.current_stage_key='account_created' then
    update public.sme_prospects set current_stage_key='onboarding',stage_entered_at=now(),
      version=version+1,updated_by=v_actor,updated_at=now() where id=v_prospect.id;
    insert into public.sme_prospect_stage_history(prospect_id,from_stage_key,to_stage_key,reason_code,actor)
    values(v_prospect.id,'account_created','onboarding','onboarding_started',v_actor);
  end if;
  if v_prospect.assigned_consultant_id is not null and exists(
    select 1 from public.platform_consultants consultant
    where consultant.id=v_prospect.assigned_consultant_id
      and consultant.active and consultant.departed_at is null
  ) then
    perform app.attribute_consultant_core_v78(
      v_prospect.assigned_consultant_id,v_prospect.id,p_business,
      v_onboarding_started_at,'v79 active assigned consultant at onboarding start',v_actor
    );
  end if;
  insert into public.business_onboarding_events(checklist_id,business_id,event_type,from_status,to_status,evidence,actor)
  values(v_check.id,p_business,'started',v_check.status,'in_progress','{}',v_actor);
  perform app.refresh_onboarding_core_v79(p_business,v_actor);
  v_response:=jsonb_build_object('replayed',false,'onboarding',app.get_onboarding_core_v79(p_business));
  perform app.v76_store_receipt(v_actor,'start_onboarding_v79',p_idempotency_key,v_hash,v_response);
  return v_response;
end
$$;

--
-- Name: start_self_serve_business_v130(text, text, text, text, text, text, text, integer, boolean, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.start_self_serve_business_v130(p_owner_name text, p_business_name text, p_business_slug text, p_sector_key text, p_registration_number text, p_locale text, p_cadence text, p_customer_capacity integer, p_legal_accepted boolean, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $_$
declare
  v_actor uuid:=auth.uid();
  v_email text;
  v_owner_name text:=btrim(coalesce(p_owner_name,''));
  v_business_name text:=btrim(coalesce(p_business_name,''));
  v_business_slug text:=lower(btrim(coalesce(p_business_slug,'')));
  v_registration text:=nullif(btrim(coalesce(p_registration_number,'')),'');
  v_locale text:=coalesce(p_locale,'en');
  v_hash text;
  v_existing public.self_serve_business_onboarding_v130%rowtype;
  v_catalog public.billing_plan_catalog_v124%rowtype;
  v_bundle public.sector_bundle_versions%rowtype;
  v_business public.businesses%rowtype;
  v_staff uuid;
  v_branch uuid;
begin
  if v_actor is null or p_idempotency_key is null then
    raise exception 'authenticated idempotent setup required' using errcode='28000';
  end if;
  select lower(email) into v_email from auth.users
   where id=v_actor and coalesce(email_confirmed_at,confirmed_at) is not null;
  if v_email is null then
    raise exception 'confirmed owner email required' using errcode='42501';
  end if;
  if length(v_owner_name) not between 2 and 120
     or length(v_business_name) not between 2 and 160
     or v_business_slug!~'^[a-z0-9]+(?:-[a-z0-9]+)*$'
     or length(v_business_slug) not between 3 and 80
     or coalesce(p_sector_key,'')!~'^[a-z][a-z0-9_]*$'
     or (v_registration is not null and length(v_registration) not between 3 and 80)
     or v_locale not in ('en','zh-CN','ms')
     or p_cadence not in ('monthly','annual')
     or p_customer_capacity<1000 or p_customer_capacity%1000<>0
     or p_legal_accepted is distinct from true then
    raise exception 'valid owner, business, plan and legal acceptance are required'
      using errcode='22023';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(v_actor::text,130));
  v_hash:=app.v95_sha256(
    v_actor::text||E'\n'||v_owner_name||E'\n'||v_business_name||E'\n'
    ||v_business_slug||E'\n'||p_sector_key||E'\n'||coalesce(v_registration,'')
    ||E'\n'||v_locale||E'\n'||p_cadence||E'\n'||p_customer_capacity::text
    ||E'\n2026-08-04'
  );
  select * into v_existing
    from public.self_serve_business_onboarding_v130 onboarding
   where onboarding.owner_user_id=v_actor for update;
  if found then
    if v_existing.request_hash<>v_hash then
      raise exception 'self-service setup is locked to the existing selection'
        using errcode='22023';
    end if;
    return jsonb_build_object(
      'business_id',v_existing.business_id,
      'business_slug',v_existing.business_slug,
      'owner_staff_id',v_existing.owner_staff_id,
      'default_branch_id',v_existing.default_branch_id,
      'status',v_existing.status,'workspace_access',v_existing.status='active',
      'replayed',true
    );
  end if;
  if exists(select 1 from public.staff where user_id=v_actor) then
    raise exception 'this account is already assigned to a business workspace'
      using errcode='42501';
  end if;
  select * into v_catalog
    from public.billing_plan_catalog_v124 catalog
   where catalog.currency='SGD' and catalog.cadence=p_cadence
     and catalog.active and catalog.effective_from<=now()
     and (catalog.effective_to is null or catalog.effective_to>now())
   order by catalog.effective_from desc limit 1;
  if not found or v_catalog.tax_behavior<>'exclusive' then
    raise exception 'selected Stripe plan is not available' using errcode='22023';
  end if;
  select * into v_bundle from public.sector_bundle_versions bundle
   where bundle.sector_key=p_sector_key and bundle.status='published';
  if not found then
    raise exception 'published sector is required' using errcode='23514';
  end if;
  insert into public.businesses(name,slug,industry,enabled_modules)
  values(v_business_name,v_business_slug,p_sector_key,v_bundle.modules)
  returning * into v_business;
  insert into public.staff(business_id,user_id,role,full_name,email,active)
  values(v_business.id,v_actor,'owner',v_owner_name,v_email,true)
  returning id into v_staff;
  insert into public.branches(business_id,name,is_default,active)
  values(v_business.id,v_business_name,true,true)
  returning id into v_branch;
  insert into public.staff_branches(business_id,staff_id,branch_id)
  values(v_business.id,v_staff,v_branch);
  insert into public.subscriptions(business_id,status,billing_provider)
  values(v_business.id,'incomplete','stripe')
  on conflict(business_id) do nothing;
  insert into public.self_serve_business_onboarding_v130(
    business_id,owner_user_id,owner_staff_id,default_branch_id,
    bundle_version_id,setup_idempotency_key,request_hash,owner_name,
    owner_email,business_name,business_slug,sector_key,registration_number,
    preferred_locale,selected_cadence,selected_customer_capacity,
    billing_catalog_id_v124,legal_accepted_at
  ) values(
    v_business.id,v_actor,v_staff,v_branch,v_bundle.id,p_idempotency_key,
    v_hash,v_owner_name,v_email,v_business_name,v_business_slug,p_sector_key,
    v_registration,v_locale,p_cadence,p_customer_capacity,v_catalog.id,now()
  );
  insert into public.business_workspace_control_audit_v94(
    business_id,actor,event_type,prior_status,new_status,reason,control_version
  ) values(
    v_business.id,v_actor,'self_service_started','pending','pending',
    'self-service owner workspace locked pending provider-confirmed payment',1
  );
  insert into public.audit_log(
    business_id,actor,action,entity,entity_id,detail
  ) values(
    v_business.id,v_actor,'SELF_SERVICE_STARTED',
    'self_serve_business_onboarding_v130',v_business.id,
    jsonb_build_object(
      'cadence',p_cadence,'customer_capacity',p_customer_capacity,
      'sector_key',p_sector_key,'legal_document_version','2026-08-04'
    )
  );
  return jsonb_build_object(
    'business_id',v_business.id,'business_slug',v_business.slug,
    'owner_staff_id',v_staff,'default_branch_id',v_branch,
    'status','payment_pending','workspace_access',false,'replayed',false,
    'cadence',p_cadence,'customer_capacity',p_customer_capacity,
    'total_cents',app.self_serve_plan_total_v130(v_catalog,p_customer_capacity)
  );
exception when unique_violation then
  raise exception 'business address or setup identity is already in use'
    using errcode='23505';
end
$_$;

--
-- Name: FUNCTION start_self_serve_business_v130(p_owner_name text, p_business_name text, p_business_slug text, p_sector_key text, p_registration_number text, p_locale text, p_cadence text, p_customer_capacity integer, p_legal_accepted boolean, p_idempotency_key uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.start_self_serve_business_v130(p_owner_name text, p_business_name text, p_business_slug text, p_sector_key text, p_registration_number text, p_locale text, p_cadence text, p_customer_capacity integer, p_legal_accepted boolean, p_idempotency_key uuid) IS 'Creates exactly one locked owner workspace using published sector and Stripe plan truth.';

--
-- Name: submit_demo_request_v292(text, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_demo_request_v292(p_contact_name text, p_business_name text, p_contact_email text DEFAULT NULL::text, p_contact_phone text DEFAULT NULL::text, p_sector text DEFAULT NULL::text, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $_$
declare
  v_name text := nullif(btrim(coalesce(p_contact_name, '')), '');
  v_business text := nullif(btrim(coalesce(p_business_name, '')), '');
  v_email text := lower(nullif(btrim(coalesce(p_contact_email, '')), ''));
  v_phone_raw text := nullif(btrim(coalesce(p_contact_phone, '')), '');
  v_phone text;
  v_sector text := nullif(btrim(coalesce(p_sector, '')), '');
  v_note text := nullif(btrim(coalesce(p_note, '')), '');
  v_hash text;
  v_recent integer;
  v_id uuid;
begin
  -- Shape refusals are LOUD, because the form can and should fix them.
  if v_name is null or length(v_name) not between 2 and 100 then
    raise exception 'a contact name is required' using errcode = '22023';
  end if;
  if v_business is null or length(v_business) not between 2 and 160 then
    raise exception 'a business name is required' using errcode = '22023';
  end if;
  if v_email is not null and (length(v_email) > 254 or v_email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$') then
    raise exception 'that email address is not valid' using errcode = '22023';
  end if;
  if v_phone_raw is not null then
    -- Accept what a Singapore prospect actually types: 8123 4567, +65 8123 4567,
    -- 65-8123-4567. app.norm_phone folds every one of those to 81234567.
    v_phone := app.norm_phone(v_phone_raw);
    if v_phone is null or v_phone !~ '^[0-9]{6,15}$' then
      raise exception 'that mobile number is not valid' using errcode = '22023';
    end if;
  end if;
  if v_email is null and v_phone is null then
    raise exception 'an email address or a mobile number is required' using errcode = '22023';
  end if;
  if v_sector is not null and length(v_sector) > 120 then
    v_sector := left(v_sector, 120);
  end if;
  if v_note is not null and length(v_note) > 2000 then
    v_note := left(v_note, 2000);
  end if;

  v_hash := app.v31_sha256_hex(
    coalesce(v_email, '') || ':' || coalesce(v_phone, '') || ':' || lower(v_business));

  -- Abuse ceiling, following report_client_error_v177: silent drop, uniform
  -- answer. A flood cannot fill the table and cannot learn that it was capped.
  select count(*) into v_recent
    from public.demo_requests_v292
   where created_at > now() - interval '1 hour';
  if v_recent >= 200 then
    return jsonb_build_object('status', 'ok');
  end if;

  -- Honest double-tap protection. The same prospect asking twice in half an
  -- hour is one request, not two, and the operator should see one card.
  if exists (
    select 1 from public.demo_requests_v292
     where dedupe_hash = v_hash
       and created_at > now() - interval '30 minutes'
  ) then
    return jsonb_build_object('status', 'ok', 'outcome', 'duplicate_ignored');
  end if;

  insert into public.demo_requests_v292
    (contact_name, business_name, contact_email, contact_phone, sector, note, dedupe_hash)
  values (v_name, v_business, v_email, v_phone, v_sector, v_note, v_hash)
  returning id into v_id;

  return jsonb_build_object('status', 'ok', 'outcome', 'recorded', 'request_id', v_id);
end;
$_$;

--
-- Name: FUNCTION submit_demo_request_v292(p_contact_name text, p_business_name text, p_contact_email text, p_contact_phone text, p_sector text, p_note text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.submit_demo_request_v292(p_contact_name text, p_business_name text, p_contact_email text, p_contact_phone text, p_sector text, p_note text) IS 'V292: anonymous demo-request capture. Write-only, self-throttled (200/hour platform-wide, 30-minute contact dedupe), reads nothing and discloses nothing.';

--
-- Name: suggest_appointment_staff_v47(uuid, uuid, uuid, timestamp with time zone, integer, integer, integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.suggest_appointment_staff_v47(p_business uuid, p_branch uuid, p_service uuid, p_starts timestamp with time zone, p_duration_minutes integer, p_limit integer DEFAULT 5, p_recent_days integer DEFAULT 30, p_staff uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  perform app.require_branch_module_v94(
    p_business,p_branch,'appointments','r'
  );
  return public.suggest_appointment_staff_v47_v94_base(
    p_business,p_branch,p_service,p_starts,p_duration_minutes,p_limit,p_recent_days,p_staff
  );
end
$$;

--
-- Name: suggest_appointment_staff_v47_v94_base(uuid, uuid, uuid, timestamp with time zone, integer, integer, integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.suggest_appointment_staff_v47_v94_base(p_business uuid, p_branch uuid, p_service uuid, p_starts timestamp with time zone, p_duration_minutes integer, p_limit integer DEFAULT 5, p_recent_days integer DEFAULT 30, p_staff uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_recent_days integer := coalesce(p_recent_days, 30);
  v_ends timestamptz;
  v_timezone text;
  v_day_end timestamptz;
  v_candidate timestamptz;
  v_available jsonb := '[]'::jsonb;
  v_next jsonb := '[]'::jsonb;
  v_staff record;
begin
  if v_recent_days not in (1, 3, 7, 30) then
    raise exception 'unsupported_recent_window' using errcode='22023';
  end if;
  if auth.uid() is null
     or not app.can_module_read(p_business, 'appointments')
     or not app.can_see_branch(p_business, p_branch) then
    raise exception 'active appointment access for this branch is required'
      using errcode = '42501';
  end if;
  if p_starts is null or p_duration_minutes not between 15 and 720 then
    raise exception 'appointment duration must be between 15 and 720 minutes'
      using errcode = '22023';
  end if;
  if p_limit not between 1 and 10 then
    raise exception 'suggestion limit must be between 1 and 10'
      using errcode = '22023';
  end if;

  select b.timezone into v_timezone from public.branches b
   where b.id = p_branch and b.business_id = p_business and b.active;
  if not found then
    raise exception 'active branch not found' using errcode = '22023';
  end if;
  if p_service is not null and not exists(
    select 1 from public.services service
     where service.id=p_service and service.business_id=p_business and service.active
       and (
         not exists(select 1 from public.service_branches configured
                     where configured.business_id=p_business and configured.service_id=p_service)
         or exists(select 1 from public.service_branches allowed
                    where allowed.business_id=p_business and allowed.service_id=p_service
                      and allowed.branch_id=p_branch)
       )
  ) then
    raise exception 'service is not bookable at this branch' using errcode = '22023';
  end if;

  v_ends := p_starts + make_interval(mins => p_duration_minutes);
  v_day_end := (((p_starts at time zone v_timezone)::date + 1)::timestamp
                at time zone v_timezone);

  select coalesce(jsonb_agg(jsonb_build_object(
           'staff_id', ranked.id,
           'staff_name', ranked.full_name,
           'calendar_color', ranked.calendar_color,
           'recent_appointments', ranked.recent_appointments,
           'hours_configured', ranked.hours_configured
         ) order by ranked.recent_appointments, ranked.last_assigned nulls first,
                    ranked.full_name, ranked.id), '[]'::jsonb)
    into v_available
    from (
      select s.id, s.full_name, s.calendar_color,
             exists(select 1 from public.staff_hours sh
                     where sh.business_id=p_business and sh.staff_id=s.id) as hours_configured,
             (select count(*)::integer from public.appointments a
               where a.business_id=p_business and a.staff_id=s.id
                 and a.status in ('booked','completed')
                 and a.starts_at >= now() - make_interval(days => v_recent_days)) as recent_appointments,
             (select max(a.created_at) from public.appointments a
               where a.business_id=p_business and a.staff_id=s.id
                 and a.status in ('booked','completed')) as last_assigned
        from public.staff s
        join public.staff_branches sb
          on sb.business_id=s.business_id and sb.staff_id=s.id and sb.branch_id=p_branch
       where s.business_id=p_business and s.active
         and app.staff_free_for_appointment_v47(
               p_business,s.id,p_branch,p_service,p_starts,v_ends,null)
       order by recent_appointments, last_assigned nulls first, s.full_name, s.id
       limit p_limit
    ) ranked;

  v_candidate := p_starts + interval '15 minutes';
  while v_candidate + make_interval(mins => p_duration_minutes) <= v_day_end
        and jsonb_array_length(v_next) < 2 loop
    select s.id, s.full_name, s.calendar_color into v_staff
      from public.staff s
      join public.staff_branches sb
        on sb.business_id=s.business_id and sb.staff_id=s.id and sb.branch_id=p_branch
     where s.business_id=p_business and s.active
       and (p_staff is null or s.id = p_staff)
       and app.staff_free_for_appointment_v47(
             p_business,s.id,p_branch,p_service,v_candidate,
             v_candidate + make_interval(mins => p_duration_minutes),null)
     order by
       (select count(*) from public.appointments a
         where a.business_id=p_business and a.staff_id=s.id
           and a.status in ('booked','completed')
           and a.starts_at >= now() - make_interval(days => v_recent_days)),
       (select max(a.created_at) from public.appointments a
         where a.business_id=p_business and a.staff_id=s.id
           and a.status in ('booked','completed')) nulls first,
       s.full_name, s.id
     limit 1;
    if found then
      v_next := v_next || jsonb_build_array(jsonb_build_object(
        'starts_at', v_candidate,
        'ends_at', v_candidate + make_interval(mins => p_duration_minutes),
        'staff_id', v_staff.id,
        'staff_name', v_staff.full_name,
        'calendar_color', v_staff.calendar_color
      ));
    end if;
    v_candidate := v_candidate + interval '15 minutes';
  end loop;

  return jsonb_build_object(
    'requested_starts_at', p_starts,
    'requested_ends_at', v_ends,
    'available_staff', v_available,
    'recommended_staff_id', v_available #>> '{0,staff_id}',
    'next_best_slots', v_next
  );
end
$$;

--
-- Name: super_admin_list_businesses(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.super_admin_list_businesses() RETURNS TABLE(business_id uuid, name text, industry text, branch_count integer, staff_count integer, client_count integer, billable_seats integer, subscription_status text, est_monthly_cents integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
begin
  if not app.is_super_admin() then
    raise exception 'super admin only' using errcode = '42501';
  end if;
  insert into public.audit_log(business_id, actor, action, entity, detail)
    values (null, auth.uid(), 'READ', 'businesses',
            jsonb_build_object('fn','super_admin_list_businesses'));
  return query
    select b.id, b.name, b.industry,
           (select count(*)::int from public.branches br where br.business_id = b.id),
           (select count(*)::int from public.staff    s  where s.business_id  = b.id),
           (select count(*)::int from public.clients  c  where c.business_id  = b.id),
           app.billable_seats(b.id),
           coalesce(sub.status, 'none'),
           coalesce(sub.base_price_cents
             + greatest(0, app.billable_seats(b.id) - sub.included_seats)
               * sub.per_seat_price_cents, 0)::int
    from public.businesses b
    left join public.subscriptions sub on sub.business_id = b.id
    order by b.name;
end;
$$;

--
-- Name: FUNCTION super_admin_list_businesses(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.super_admin_list_businesses() IS 'v17: platform super-admin roster of all tenants. is_super_admin() guarded; audited.';

--
-- Name: sv_chargeback_topup(uuid, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sv_chargeback_topup(p_business uuid, p_topup_operation uuid, p_reason text, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_reason text := btrim(coalesce(p_reason, ''));
  v_hash text;
  v_existing public.sv_operations%rowtype;
  v_op uuid := gen_random_uuid();
  v_state text;
  v_topup_type text;
  v_account uuid;
  v_client uuid;
  v_biz_synth boolean;
  v_client_synth boolean;
  v_biz_currency text;
  v_payment public.sv_topup_payments%rowtype;
  v_collected jsonb;
  v_plan jsonb;
  v_entry jsonb;
  v_result jsonb;
begin
  if not app.is_salon_owner(p_business) then
    raise exception 'owner only' using errcode = '42501';
  end if;
  -- HARD SAFETY GATE (v63): value only moves when stored value is the authority for this business.
  if coalesce((select state from public.sv_authority
                where business_id = p_business and asset = 'stored_value'), 'unbuilt') <> 'live' then
    raise exception 'sv_not_live: stored value is not the authority for this business' using errcode = '22023';
  end if;
  -- PAUSE GATE (v64 family mapping): a chargeback removes value the customer currently holds, so it
  -- is a redemption-family correction - an active 'all' or 'redeem' pause blocks it.
  if app.sv_pause_active(p_business, 'stored_value', 'redeem') then
    raise exception 'sv_paused: stored-value redemptions are paused' using errcode = '22023';
  end if;
  if p_idempotency_key is null then
    raise exception 'a stored-value chargeback idempotency key is required' using errcode = '22023';
  end if;
  if char_length(v_reason) < 3 then
    raise exception 'a stored-value chargeback requires a reason of at least 3 characters' using errcode = '22023';
  end if;

  select o.operation_type into v_topup_type from public.sv_operations o
   where o.id = p_topup_operation and o.business_id = p_business;
  if v_topup_type is null then
    raise exception 'stored-value top-up operation not found in this business' using errcode = '22023';
  end if;
  if v_topup_type <> 'topup' then
    raise exception 'stored-value chargeback target is not a top-up operation' using errcode = '22023';
  end if;

  select l.account_id into v_account from public.sv_lots l
   where l.business_id = p_business and l.operation_id = p_topup_operation and l.class = 'paid'
   order by l.earned_seq asc, l.id asc limit 1;
  if v_account is null then
    raise exception 'stored-value operation has no paid lot to charge back' using errcode = '22023';
  end if;
  select a.client_id into v_client from public.sv_accounts a
   where a.id = v_account and a.business_id = p_business;

  -- Payment evidence is mandatory: a chargeback is the reversal of a RECORDED funding payment.
  select * into v_payment from public.sv_topup_payments
   where business_id = p_business and operation_id = p_topup_operation;
  if not found then
    raise exception 'sv_no_payment_evidence: this top-up carries no recorded funding payment to charge back'
      using errcode = '22023';
  end if;

  -- SYNTHETIC/LIVE COHERENCE (v66): a synthetic entity cannot transact on a live business.
  select b.is_synthetic, b.currency into v_biz_synth, v_biz_currency
    from public.businesses b where b.id = p_business;
  select c.is_synthetic into v_client_synth from public.clients c
   where c.id = v_client and c.business_id = p_business;
  if coalesce(v_biz_synth, false) or coalesce(v_client_synth, false) then
    raise exception 'a synthetic entity cannot transact on a live business' using errcode = '22023';
  end if;
  -- CURRENCY: the recorded funding currency must still be this business's currency.
  if upper(btrim(coalesce(v_payment.currency, ''))) <> upper(btrim(coalesce(v_biz_currency, 'SGD'))) then
    raise exception 'currency_mismatch: the recorded funding currency (%) is not this business currency (%)',
      v_payment.currency, upper(coalesce(v_biz_currency, 'SGD')) using errcode = '22023';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('v63:sv_acct:' || p_business::text || ':' || v_account::text, 0));
  perform pg_advisory_xact_lock(hashtextextended('v68a:sv_chargeback:' || p_business::text || ':' || p_idempotency_key::text, 0));

  select * into v_existing from public.sv_operations o
   where o.business_id = p_business and o.operation_type = 'chargeback' and o.idempotency_key = p_idempotency_key
   for update;
  v_hash := app.ps1b_sha256(jsonb_build_object(
    'op', 'chargeback', 'business_id', p_business, 'topup_operation_id', p_topup_operation,
    'reason', v_reason)::text);
  if found then
    if v_existing.request_hash <> v_hash then
      raise exception 'idempotency key conflicts with a different stored-value chargeback' using errcode = '22023';
    end if;
    return v_existing.result;   -- same key, same request -> ONE effect, replayed result
  end if;

  -- TOCTOU RE-VALIDATION (v66/v67 pattern): re-read the gates under the locks so a concurrent
  -- authority transition or pause committed since the early checks cannot slip a write through.
  select coalesce(state, 'unbuilt') into v_state from public.sv_authority
   where business_id = p_business and asset = 'stored_value';
  if coalesce(v_state, 'unbuilt') <> 'live' then
    raise exception 'sv_not_live: stored value is not the authority for this business' using errcode = '22023';
  end if;
  if app.sv_pause_active(p_business, 'stored_value', 'redeem') then
    raise exception 'sv_paused: stored-value redemptions are paused' using errcode = '22023';
  end if;

  -- ONE chargeback per top-up operation. The unique index is the hard guarantee; this is the typed
  -- refusal the caller sees.
  if exists (select 1 from public.sv_chargebacks c
              where c.business_id = p_business and c.topup_operation_id = p_topup_operation) then
    raise exception 'sv_already_charged_back: this top-up has already been charged back' using errcode = '22023';
  end if;

  -- FEFO row locks over the account's lot set (one-winner vs a concurrent spend or refund; the same
  -- deterministic order the v63 engine uses, so no deadlock).
  perform 1 from public.sv_lots l
   where l.business_id = p_business and l.account_id = v_account
   order by l.expiry_key asc nulls last, l.earned_seq asc, l.id asc
   for update;

  v_plan := app.sv_chargeback_plan(p_business, p_topup_operation);
  if (v_plan->>'ok')::boolean is not true then
    raise exception 'stored-value chargeback failed: %', coalesce(v_plan->>'reason', 'unknown') using errcode = '22023';
  end if;
  v_collected := app.sv_cash_collected_cents(p_business, p_topup_operation);

  v_result := jsonb_build_object(
    'status', 'ok', 'operation_id', v_op, 'topup_operation_id', p_topup_operation,
    'account_id', v_account, 'payment_id', v_payment.id,
    'paid_lot', v_plan->'paid_lot', 'bonus_lot', v_plan->'bonus_lot',
    'void_paid_cents', (v_plan->>'void_paid_cents')::int,
    'void_bonus_cents', (v_plan->>'void_bonus_cents')::int,
    'voided_total_cents', (v_plan->>'void_paid_cents')::int + (v_plan->>'void_bonus_cents')::int,
    'bad_debt_cents', (v_plan->>'bad_debt_cents')::int,
    'cash_already_refunded_cents', (v_plan->>'cash_already_refunded_cents')::int,
    'cash_collected_cents', (v_collected->>'collected_cents')::int,
    'cash_basis', v_collected->>'basis',
    'currency', upper(btrim(v_payment.currency)),
    'reason', v_reason,
    'sales_delivered_stand', true,
    'bad_debt_accounting_classification', 'not_classified_owner_and_accountant_review_required',
    'plan', v_plan->'plan');

  insert into public.sv_operations(id, business_id, operation_type, idempotency_key, request_hash, actor, result)
  values (v_op, p_business, 'chargeback', p_idempotency_key, v_hash, v_actor, v_result);

  -- Apply: a negative 'correction' per lot that still holds value, plus exactly one zero-cents
  -- 'bad_debt' loss record on the paid lot. The bad_debt row cannot disturb
  -- `remaining == Sum(movements)` because v61's CHECK forces its cents to 0.
  for v_entry in select * from jsonb_array_elements(v_plan->'plan') loop
    insert into public.sv_lot_movements(business_id, account_id, lot_id, operation_id, kind, cents)
    values (p_business, v_account, (v_entry->>'lot_id')::uuid, v_op, v_entry->>'kind', (v_entry->>'cents')::int);
  end loop;

  insert into public.sv_chargebacks(
    business_id, account_id, topup_operation_id, operation_id, payment_id, paid_lot_id, bonus_lot_id,
    voided_paid_cents, voided_bonus_cents, bad_debt_cents, cash_already_refunded_cents,
    cash_collected_cents, currency, reason, actor)
  values (
    p_business, v_account, p_topup_operation, v_op, v_payment.id,
    (v_plan->>'paid_lot')::uuid, nullif(v_plan->>'bonus_lot', '')::uuid,
    (v_plan->>'void_paid_cents')::int, (v_plan->>'void_bonus_cents')::int,
    (v_plan->>'bad_debt_cents')::int, (v_plan->>'cash_already_refunded_cents')::int,
    (v_collected->>'collected_cents')::int, upper(btrim(v_payment.currency)), v_reason, v_actor);

  -- The payment itself is immutable (v66); the chargeback is append-only evidence beside it.
  insert into public.sv_topup_payment_events(business_id, payment_id, event_type, operation_id, actor, reason)
  values (p_business, v_payment.id, 'chargeback', v_op, v_actor, v_reason);

  insert into public.audit_log(business_id, actor, action, entity, entity_id, detail)
  values (p_business, v_actor, 'SV_CHARGEBACK', 'sv_accounts', v_account, jsonb_build_object(
    'operation_id', v_op, 'topup_operation_id', p_topup_operation, 'payment_id', v_payment.id,
    'void_paid_cents', (v_plan->>'void_paid_cents')::int,
    'void_bonus_cents', (v_plan->>'void_bonus_cents')::int,
    'bad_debt_cents', (v_plan->>'bad_debt_cents')::int,
    'cash_already_refunded_cents', (v_plan->>'cash_already_refunded_cents')::int,
    'cash_collected_cents', (v_collected->>'collected_cents')::int,
    'bad_debt_accounting_classification', 'not_classified_owner_and_accountant_review_required',
    'reason', v_reason));

  return v_result;
end $$;

--
-- Name: sv_correct_lot(uuid, uuid, integer, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sv_correct_lot(p_business uuid, p_lot uuid, p_cents integer, p_reason text, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_reason text := btrim(coalesce(p_reason, ''));
  v_hash text;
  v_existing public.sv_operations%rowtype;
  v_op uuid := gen_random_uuid();
  v_state text;
  v_lot public.sv_lots%rowtype;
  v_client uuid;
  v_biz_synth boolean;
  v_client_synth boolean;
  v_biz_currency text;
  v_remaining integer;
  v_after bigint;
  v_result jsonb;
begin
  if not app.is_salon_owner(p_business) then
    raise exception 'owner only' using errcode = '42501';
  end if;
  if coalesce((select state from public.sv_authority
                where business_id = p_business and asset = 'stored_value'), 'unbuilt') <> 'live' then
    raise exception 'sv_not_live: stored value is not the authority for this business' using errcode = '22023';
  end if;
  -- Same redemption-family mapping as the chargeback (see header): a correction adjusts value the
  -- customer currently holds, so 'all' or 'redeem' blocks it.
  if app.sv_pause_active(p_business, 'stored_value', 'redeem') then
    raise exception 'sv_paused: stored-value redemptions are paused' using errcode = '22023';
  end if;
  if p_idempotency_key is null then
    raise exception 'a stored-value correction idempotency key is required' using errcode = '22023';
  end if;
  if char_length(v_reason) < 3 then
    raise exception 'a stored-value correction requires a reason of at least 3 characters' using errcode = '22023';
  end if;
  if p_cents is null or p_cents = 0 then
    raise exception 'a stored-value correction must be a non-zero whole number of cents' using errcode = '22023';
  end if;

  select * into v_lot from public.sv_lots where id = p_lot and business_id = p_business;
  if not found then
    raise exception 'stored-value lot not found in this business' using errcode = '22023';
  end if;
  select a.client_id into v_client from public.sv_accounts a
   where a.id = v_lot.account_id and a.business_id = p_business;

  select b.is_synthetic, b.currency into v_biz_synth, v_biz_currency
    from public.businesses b where b.id = p_business;
  select c.is_synthetic into v_client_synth from public.clients c
   where c.id = v_client and c.business_id = p_business;
  if coalesce(v_biz_synth, false) or coalesce(v_client_synth, false) then
    raise exception 'a synthetic entity cannot transact on a live business' using errcode = '22023';
  end if;
  if btrim(coalesce(v_biz_currency, '')) !~ '^[A-Za-z]{3}$' then
    raise exception 'currency_missing: this business has no valid three-letter currency configured'
      using errcode = '22023';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('v63:sv_acct:' || p_business::text || ':' || v_lot.account_id::text, 0));
  perform pg_advisory_xact_lock(hashtextextended('v68a:sv_correct:' || p_business::text || ':' || p_idempotency_key::text, 0));

  select * into v_existing from public.sv_operations o
   where o.business_id = p_business and o.operation_type = 'correction' and o.idempotency_key = p_idempotency_key
   for update;
  v_hash := app.ps1b_sha256(jsonb_build_object(
    'op', 'correction', 'business_id', p_business, 'lot_id', p_lot, 'cents', p_cents,
    'reason', v_reason)::text);
  if found then
    if v_existing.request_hash <> v_hash then
      raise exception 'idempotency key conflicts with a different stored-value correction' using errcode = '22023';
    end if;
    return v_existing.result;
  end if;

  -- TOCTOU RE-VALIDATION under the locks.
  select coalesce(state, 'unbuilt') into v_state from public.sv_authority
   where business_id = p_business and asset = 'stored_value';
  if coalesce(v_state, 'unbuilt') <> 'live' then
    raise exception 'sv_not_live: stored value is not the authority for this business' using errcode = '22023';
  end if;
  if app.sv_pause_active(p_business, 'stored_value', 'redeem') then
    raise exception 'sv_paused: stored-value redemptions are paused' using errcode = '22023';
  end if;

  if exists (select 1 from public.sv_chargebacks c
              where c.business_id = p_business and c.topup_operation_id = v_lot.operation_id) then
    raise exception 'sv_charged_back: this lot belongs to a charged-back top-up and can no longer be corrected'
      using errcode = '22023';
  end if;

  -- Lock exactly the target lot's row (a correction never touches another lot).
  perform 1 from public.sv_lots l where l.id = p_lot and l.business_id = p_business for update;

  v_remaining := app.sv_lot_remaining(p_lot);
  v_after := coalesce(v_remaining, 0)::bigint + p_cents;
  if v_after < 0 then
    raise exception 'sv_correction_below_zero: a correction of % would drive lot remaining from % to %',
      p_cents, v_remaining, v_after using errcode = '22023';
  end if;
  if v_after > v_lot.minted_cents then
    raise exception 'sv_correction_above_mint: a correction of % would drive lot remaining from % to %, above the minted %',
      p_cents, v_remaining, v_after, v_lot.minted_cents using errcode = '22023';
  end if;
  if p_cents > 0 and v_lot.expiry_key is not null and v_lot.expiry_key <= now() then
    raise exception 'sv_correct_expired_lot: a positive correction cannot be applied to an expired lot (expired %)',
      v_lot.expiry_key using errcode = '22023';
  end if;

  v_result := jsonb_build_object(
    'status', 'ok', 'operation_id', v_op, 'lot_id', p_lot, 'account_id', v_lot.account_id,
    'class', v_lot.class, 'cents', p_cents, 'direction', case when p_cents > 0 then 'increase' else 'decrease' end,
    'remaining_before_cents', coalesce(v_remaining, 0), 'remaining_after_cents', v_after::int,
    'minted_cents', v_lot.minted_cents, 'currency', upper(btrim(v_biz_currency)),
    'reason', v_reason, 'is_mint', false);

  insert into public.sv_operations(id, business_id, operation_type, idempotency_key, request_hash, actor, result)
  values (v_op, p_business, 'correction', p_idempotency_key, v_hash, v_actor, v_result);
  insert into public.sv_lot_movements(business_id, account_id, lot_id, operation_id, kind, cents)
  values (p_business, v_lot.account_id, p_lot, v_op, 'correction', p_cents);
  insert into public.audit_log(business_id, actor, action, entity, entity_id, detail)
  values (p_business, v_actor, 'SV_CORRECT_LOT', 'sv_lots', p_lot, jsonb_build_object(
    'operation_id', v_op, 'account_id', v_lot.account_id, 'class', v_lot.class, 'cents', p_cents,
    'remaining_before_cents', coalesce(v_remaining, 0), 'remaining_after_cents', v_after::int,
    'minted_cents', v_lot.minted_cents, 'reason', v_reason));

  return v_result;
end $_$;

--
-- Name: sv_cutover_business(uuid, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sv_cutover_business(p_business uuid, p_reason text, p_evidence_hash text, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_reason text := btrim(coalesce(p_reason, ''));
  v_evidence text := btrim(coalesce(p_evidence_hash, ''));
  v_readiness jsonb;
  v_hash text;
  v_existing public.sv_operations%rowtype;
  v_op uuid := gen_random_uuid();
  v_prior text;
  v_designation public.sv_cutover_designations%rowtype;
  v_result jsonb;
begin
  if not app.is_salon_owner(p_business) then
    raise exception 'owner only' using errcode = '42501';
  end if;
  if p_idempotency_key is null then
    raise exception 'a stored-value cutover idempotency key is required' using errcode = '22023';
  end if;
  if char_length(v_reason) < 10 then
    raise exception 'a stored-value cutover requires a reason of at least 10 characters (this is a financial go-live, not a toggle)'
      using errcode = '22023';
  end if;
  if v_evidence = '' then
    raise exception 'sv_evidence_required: the evidence hash returned by preview_sv_cutover is required'
      using errcode = '22023';
  end if;

  -- Per-business lock first (two different keys racing the same business serialize here), then the
  -- per-key lock (the envelope). Deterministic order -> no deadlock between the two.
  perform pg_advisory_xact_lock(hashtextextended('v69:sv_cutover:' || p_business::text, 0));
  perform pg_advisory_xact_lock(hashtextextended(
    'v69:sv_cutover_key:' || p_business::text || ':' || p_idempotency_key::text, 0));

  v_hash := app.ps1b_sha256(jsonb_build_object(
    'op', 'cutover', 'business_id', p_business, 'reason', v_reason)::text);
  select * into v_existing from public.sv_operations o
   where o.business_id = p_business and o.operation_type = 'cutover'
     and o.idempotency_key = p_idempotency_key
   for update;
  if found then
    if v_existing.request_hash <> v_hash then
      raise exception 'idempotency key conflicts with a different stored-value cutover' using errcode = '22023';
    end if;
    return v_existing.result;   -- same key, same request -> ONE transition, replayed result
  end if;

  -- Readiness, evaluated under the locks on the SAME oracle preview_sv_cutover renders. Being under
  -- the locks makes it a TOCTOU-safe check for everything the per-business lock serialises: a
  -- concurrent cutover of THIS business cannot slip a second transition through. It is NOT by itself
  -- TOCTOU-safe against designate/revoke, which serialise on a different (global) mutex - that is
  -- what the attribution re-read below closes (rev-3, MEDIUM-1, §3a).
  v_readiness := app.sv_cutover_readiness(p_business);
  perform app.sv_cutover_raise(v_readiness);
  if (v_readiness->>'evidence_hash') <> v_evidence then
    raise exception 'sv_evidence_stale: the cutover conditions changed since preview_sv_cutover was taken; re-run the preview and act on the new evidence'
      using errcode = '22023';
  end if;

  select state into v_prior from public.sv_authority
   where business_id = p_business and asset = 'stored_value' for update;

  -- rev-3, review MEDIUM-1 (§3a). The values below are the PERMANENT attribution: sv_cutover_events
  -- is immutable and UNIQUE(business_id, asset), so a NULL written here can never be repaired. Take
  -- the SAME global mutex public.set_sv_cutover_designation takes for BOTH designate and revoke (§11)
  -- so this read is mutually exclusive with them, then re-read under it. The window being closed is
  -- widest exactly here: the sv_authority row lock taken immediately above is also held by
  -- app.sv_apply_authority_state, which the nightly frenly-sv-reconciliation sweep drives, so this
  -- call can sit blocked for as long as that sweep's transaction runs while a revoke commits.
  perform pg_advisory_xact_lock(hashtextextended('v69:sv_designation', 0));
  select * into v_designation from public.sv_cutover_designations
   where business_id = p_business and asset = 'stored_value' and revoked_at is null;
  if not found then
    -- FAIL CLOSED, and deliberately NOT "pin the readiness-time id and proceed": completing a go-live
    -- attributed to a designation the super admin has since withdrawn is worse than refusing. This is
    -- a legitimate, retriable race outcome - nothing was mutated, no idempotency key was reserved
    -- (the envelope insert is below), and the caller may re-preview and retry with the same key.
    raise exception 'sv_designation_revoked: the super-admin designation for this business was revoked while the cutover was in flight; re-run preview_sv_cutover and retry'
      using errcode = '22023';
  end if;

  v_result := jsonb_build_object(
    'status', 'ok',
    'business_id', p_business,
    'asset', 'stored_value',
    'operation_id', v_op,
    'prior_state', v_prior,
    'new_state', 'live',
    'reason', v_reason,
    'evidence_hash', v_readiness->>'evidence_hash',
    'designation_id', v_designation.id,
    'designated_by', v_designation.designated_by,
    'readiness', v_readiness,
    'reversible', false,
    'emergency_control', 'sv_pause');

  insert into public.sv_operations(id, business_id, operation_type, idempotency_key, request_hash, actor, result)
  values (v_op, p_business, 'cutover', p_idempotency_key, v_hash, v_actor, v_result);

  -- The event row is written BEFORE the authority update: it is what authorizes the update.
  insert into public.sv_cutover_events(
    business_id, asset, operation_id, actor, designation_id, designated_by,
    prior_state, new_state, reason, evidence_hash, readiness, authorized_txid)
  values (
    p_business, 'stored_value', v_op, v_actor, v_designation.id, v_designation.designated_by,
    v_prior, 'live', v_reason, v_readiness->>'evidence_hash', v_readiness,
    pg_catalog.pg_current_xact_id()::text::bigint);

  update public.sv_authority
     set state = 'live', updated_at = now(), updated_by = v_actor
   where business_id = p_business and asset = 'stored_value';

  insert into public.audit_log(business_id, actor, action, entity, entity_id, detail)
  values (p_business, v_actor, 'SV_CUTOVER', 'sv_authority', p_business, jsonb_build_object(
    'operation_id', v_op, 'from', v_prior, 'to', 'live', 'reason', v_reason,
    'evidence_hash', v_readiness->>'evidence_hash',
    'designation_id', v_designation.id, 'designated_by', v_designation.designated_by,
    'reversible', false));

  return v_result;
end $$;

--
-- Name: sv_expire_due(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sv_expire_due(p_business uuid, p_limit integer DEFAULT 1000) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_op uuid := gen_random_uuid();
  v_limit integer := least(greatest(coalesce(p_limit, 1000), 1), 100000);
  v_acc uuid;
  l record;
  v_rem integer;
  v_expired_lots integer := 0;
  v_expired_cents bigint := 0;
  v_details jsonb := '[]'::jsonb;
begin
  if not (app.is_salon_owner(p_business) or app.sv_automation_context()) then
    raise exception 'owner only' using errcode = '42501';
  end if;
  if coalesce((select state from public.sv_authority
                where business_id = p_business and asset = 'stored_value'), 'unbuilt') <> 'live' then
    raise exception 'sv_not_live: stored value is not the authority for this business' using errcode = '22023';
  end if;

  -- PS-2A Increment D pause gate (contract D §1: expiry is a system sweep, not an earn or a
  -- redeem, so ONLY an 'all' sv_pause blocks it). Second gate, independent of sv_not_live;
  -- this block is the ONLY addition over the v63 body.
  if app.sv_pause_active(p_business, 'stored_value', 'all_only') then
    raise exception 'sv_paused: stored value is paused' using errcode = '22023';
  end if;

  -- Serialize per touched account (ascending order -> deadlock-free vs per-account spend locks).
  for v_acc in
    select distinct l2.account_id from public.sv_lots l2
     where l2.business_id = p_business and l2.expiry_key is not null and l2.expiry_key <= now()
     order by l2.account_id
  loop
    perform pg_advisory_xact_lock(hashtextextended('v63:sv_acct:' || p_business::text || ':' || v_acc::text, 0));
  end loop;

  -- Compute the sweep plan under FOR UPDATE row locks (sv_operations is append-only, so the anchor
  -- op is inserted ONCE with its final result). Locking the candidate lots holds them for the txn.
  for l in
    select ll.id as lot_id, ll.account_id
      from public.sv_lots ll
     where ll.business_id = p_business and ll.expiry_key is not null and ll.expiry_key <= now()
     order by ll.account_id, ll.expiry_key asc, ll.earned_seq asc, ll.id asc
     for update
  loop
    exit when v_expired_lots >= v_limit;
    v_rem := app.sv_lot_remaining(l.lot_id);
    if v_rem is null or v_rem <= 0 then continue; end if;   -- spent / already-expired -> skip
    v_expired_lots := v_expired_lots + 1;
    v_expired_cents := v_expired_cents + v_rem;
    v_details := v_details || jsonb_build_array(jsonb_build_object(
      'lot_id', l.lot_id, 'account_id', l.account_id, 'expired_cents', v_rem));
  end loop;

  insert into public.sv_operations(id, business_id, operation_type, idempotency_key, request_hash, actor, result)
  values (v_op, p_business, 'expire', gen_random_uuid(),
    app.ps1b_sha256(jsonb_build_object('op', 'expire', 'business_id', p_business, 'at', now())::text),
    v_actor, jsonb_build_object('status', 'ok', 'expired_lots', v_expired_lots,
      'expired_cents', v_expired_cents::int, 'details', v_details));

  for l in select value from jsonb_array_elements(v_details) as t(value) loop
    insert into public.sv_lot_movements(business_id, account_id, lot_id, operation_id, kind, cents)
    values (p_business, (l.value->>'account_id')::uuid, (l.value->>'lot_id')::uuid, v_op, 'expiry',
      (-(l.value->>'expired_cents')::int)::int);
  end loop;

  if v_expired_lots > 0 then
    insert into public.audit_log(business_id, actor, action, entity, entity_id, detail)
    values (p_business, v_actor, 'SV_EXPIRE_SWEEP', 'sv_accounts', v_op, jsonb_build_object(
      'operation_id', v_op, 'expired_lots', v_expired_lots, 'expired_cents', v_expired_cents::int));
  end if;

  return jsonb_build_object('status', 'ok', 'operation_id', v_op,
    'expired_lots', v_expired_lots, 'expired_cents', v_expired_cents::int, 'details', v_details);
end $$;

