--
-- Name: sync_merchant_payment_account_v142(text, boolean, boolean, boolean, boolean, text, jsonb, jsonb, text, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_merchant_payment_account_v142(p_account_id text, p_livemode boolean, p_details_submitted boolean, p_charges_enabled boolean, p_payouts_enabled boolean, p_paynow_capability text, p_currently_due jsonb, p_eventually_due jsonb, p_disabled_reason text, p_event_id text DEFAULT NULL::text, p_event_created_at timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_business uuid;
begin
  perform app.v142_service_guard();
  update public.merchant_payment_accounts_v142 set
    livemode=p_livemode,details_submitted=coalesce(p_details_submitted,false),
    charges_enabled=coalesce(p_charges_enabled,false),payouts_enabled=coalesce(p_payouts_enabled,false),
    paynow_capability=p_paynow_capability,
    requirements_currently_due=coalesce(p_currently_due,'[]'::jsonb),
    requirements_eventually_due=coalesce(p_eventually_due,'[]'::jsonb),
    disabled_reason=nullif(left(coalesce(p_disabled_reason,''),300),''),
    provider_event_id=coalesce(p_event_id,provider_event_id),
    provider_event_created_at=coalesce(p_event_created_at,provider_event_created_at),updated_at=now()
  where provider_account_id=p_account_id
    and livemode=p_livemode
    and (p_event_created_at is null or provider_event_created_at is null or p_event_created_at>=provider_event_created_at)
  returning business_id into v_business;
  return jsonb_build_object('status',case when v_business is null then 'ignored' else 'updated' end,
    'business_id',v_business);
end $$;

--
-- Name: transfer_bottle_v275(uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.transfer_bottle_v275(p_business uuid, p_bottle uuid, p_client uuid, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_key text := nullif(btrim(coalesce(p_idempotency_key, '')), '');
  v_existing uuid;
  v_bottle public.bar_bottles%rowtype;
  v_before uuid;
begin
  perform app.require_bar_business_v275(p_business);
  perform app.require_bar_staff_v275(p_business, true);
  if v_key is null then
    raise exception 'idempotency key required' using errcode = '22023';
  end if;
  if p_client is null then
    raise exception 'choose the customer to transfer to' using errcode = '22023';
  end if;

  v_existing := app.bar_bottle_replayed_v275(p_business, v_key);
  if v_existing is not null then
    select * into v_bottle from public.bar_bottles bottle where bottle.id = v_existing;
    return jsonb_build_object('status', 'duplicate_ignored',
      'bottle', app.bar_bottle_json_v275(v_bottle));
  end if;

  select * into v_bottle from public.bar_bottles bottle
   where bottle.id = p_bottle and bottle.business_id = p_business for update;
  if not found then
    raise exception 'bottle not found' using errcode = '22023';
  end if;
  if v_bottle.status in ('finished', 'transferred', 'removed') then
    raise exception 'this bottle is closed' using errcode = '22023';
  end if;
  if v_bottle.client_id = p_client then
    raise exception 'that customer already holds this bottle' using errcode = '22023';
  end if;
  v_before := v_bottle.client_id;

  update public.bar_bottles bottle
     set client_id = p_client, updated_at = now()
   where bottle.id = v_bottle.id
  returning * into v_bottle;

  insert into public.bar_bottle_events (business_id, bottle_id, kind, actor, idem_key, detail)
  values (p_business, v_bottle.id, 'transfer', v_actor, v_key,
    jsonb_build_object('from_client_id', v_before, 'to_client_id', p_client));

  return jsonb_build_object('status', 'ok', 'bottle', app.bar_bottle_json_v275(v_bottle));
end;
$$;

--
-- Name: unblock_business_onboarding_v79(uuid, text, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.unblock_business_onboarding_v79(p_business uuid, p_item_key text, p_expected_version bigint, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_checklist public.business_onboarding_checklists%rowtype;
  v_item public.business_onboarding_items%rowtype;
  v_request jsonb;
  v_replay jsonb;
  v_response jsonb;
begin
  if not app.is_super_admin() then
    raise exception 'super_admin_required';
  end if;
  perform app.require_idempotency_key_v79(p_idempotency_key);
  if nullif(btrim(p_idempotency_key), '') is null then
    raise exception 'idempotency_key_required';
  end if;

  v_request := jsonb_build_object(
    'business_id', p_business,
    'item_key', p_item_key,
    'expected_version', p_expected_version
  );
  v_replay := app.v76_replay(
    v_actor, 'unblock_business_onboarding_v79', p_idempotency_key,
    app.v76_sha256_hex(v_request::text)
  );
  if v_replay is not null then return v_replay; end if;

  select * into v_checklist
  from public.business_onboarding_checklists
  where business_id = p_business
  for update;
  if not found then raise exception 'onboarding_checklist_not_found'; end if;
  if v_checklist.version <> p_expected_version then raise exception 'version_conflict'; end if;
  if v_checklist.status = 'activated' then raise exception 'business_already_activated'; end if;

  if nullif(btrim(p_item_key), '') is null then
    if v_checklist.blocked_at is null then raise exception 'onboarding_not_globally_blocked'; end if;
    update public.business_onboarding_checklists
    set blocked_reason = null,
        blocked_by = null,
        blocked_at = null,
        updated_at = now()
    where id = v_checklist.id;
  else
    select * into v_item
    from public.business_onboarding_items
    where checklist_id = v_checklist.id
      and item_key = btrim(p_item_key)
    for update;
    if not found then raise exception 'onboarding_item_not_found'; end if;
    if v_item.status <> 'blocked' then raise exception 'onboarding_item_not_blocked'; end if;

    update public.business_onboarding_items
    set status = coalesce(status_before_block, 'pending'),
        status_before_block = null,
        block_reason = null,
        blocked_by = null,
        blocked_at = null,
        updated_at = now()
    where id = v_item.id;
  end if;

  perform app.recompute_onboarding_status_v79(p_business, v_actor);
  insert into public.business_onboarding_events(
    checklist_id, business_id, item_id, event_type, actor, evidence
  ) values (
    v_checklist.id, p_business, v_item.id, 'unblocked', v_actor,
    jsonb_build_object('item_key', nullif(btrim(p_item_key), ''))
  );

  v_response := jsonb_build_object(
    'replayed',false,'onboarding',app.get_onboarding_core_v79(p_business)
  );
  perform app.v76_store_receipt(
    v_actor, 'unblock_business_onboarding_v79', p_idempotency_key,
    app.v76_sha256_hex(v_request::text), v_response
  );
  insert into public.audit_log(business_id,actor,action,entity,entity_id,detail)
  values(p_business,v_actor,'BUSINESS_ONBOARDING_UNBLOCKED_V79','businesses',p_business,
    jsonb_build_object('item_key',nullif(btrim(p_item_key),'')));
  return v_response;
end
$$;

--
-- Name: update_expense_v285(uuid, uuid, integer, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_expense_v285(p_business uuid, p_expense uuid, p_amount_cents integer, p_category text, p_note text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_category text := nullif(btrim(coalesce(p_category, '')), '');
  v_row public.expenses%rowtype;
begin
  if v_actor is null or p_business is null or p_expense is null
     or not app.has_perm(p_business, 'view_finance') then
    raise exception 'permission denied' using errcode = '42501';
  end if;
  if p_amount_cents is not null and p_amount_cents not between 1 and 100000000 then
    raise exception 'the amount is not a valid cost' using errcode = '22023';
  end if;
  if v_category is not null and char_length(v_category) not between 2 and 120 then
    raise exception 'a category is between 2 and 120 characters' using errcode = '22023';
  end if;
  if p_note is not null and char_length(p_note) > 500 then
    raise exception 'a note is limited to 500 characters' using errcode = '22023';
  end if;

  select * into v_row
    from public.expenses expense
   where expense.id = p_expense and expense.business_id = p_business
     for update;
  if not found then
    raise exception 'expense not found' using errcode = '22023';
  end if;
  if v_row.voided_at is not null then
    raise exception 'a voided expense cannot be edited' using errcode = '22023';
  end if;

  update public.expenses expense
     set amount_cents = coalesce(p_amount_cents, expense.amount_cents),
         category = coalesce(v_category, expense.category),
         note = coalesce(nullif(btrim(coalesce(p_note, '')), ''), expense.note)
   where expense.id = p_expense and expense.business_id = p_business
  returning * into v_row;

  insert into public.audit_log (business_id, actor, action, entity, entity_id, detail)
  values (
    p_business, v_actor, 'EXPENSE_UPDATE', 'expenses', p_expense,
    jsonb_build_object('amount_cents', v_row.amount_cents, 'category', v_row.category)
  );

  return to_jsonb(v_row);
end;
$$;

--
-- Name: update_service_bundle_v285(uuid, uuid, text, integer, uuid[], boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_service_bundle_v285(p_business uuid, p_bundle uuid, p_name text, p_price_cents integer, p_service_ids uuid[], p_active boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_name text := nullif(btrim(coalesce(p_name, '')), '');
  v_service_ids uuid[];
  v_bundle public.bundles%rowtype;
begin
  if v_actor is null or p_business is null or p_bundle is null
     or not app.can_module_write(p_business, 'services') then
    raise exception 'permission denied' using errcode = '42501';
  end if;

  select * into v_bundle
    from public.bundles bundle
   where bundle.id = p_bundle and bundle.business_id = p_business
     for update;
  if not found then
    raise exception 'bundle not found' using errcode = '22023';
  end if;

  if v_name is not null and char_length(v_name) not between 2 and 120 then
    raise exception 'invalid service bundle' using errcode = '22023';
  end if;
  if p_price_cents is not null and p_price_cents not between 0 and 100000000 then
    raise exception 'invalid service bundle' using errcode = '22023';
  end if;

  if p_service_ids is not null then
    select array_agg(service_id order by service_id)
      into v_service_ids
      from (
        select distinct candidate as service_id
          from unnest(p_service_ids) candidate
         where candidate is not null
      ) normalized;
    if cardinality(coalesce(v_service_ids, array[]::uuid[])) not between 2 and 50 then
      raise exception 'a bundle holds between 2 and 50 services' using errcode = '22023';
    end if;
    if (
      select count(*)
        from public.services service
       where service.business_id = p_business
         and service.active
         and service.id = any(v_service_ids)
    ) <> cardinality(v_service_ids) then
      raise exception 'bundle services must be active in this business'
        using errcode = '22023';
    end if;
  end if;

  update public.bundles bundle
     set name = coalesce(v_name, bundle.name),
         price_cents = coalesce(p_price_cents, bundle.price_cents),
         active = coalesce(p_active, bundle.active)
   where bundle.id = p_bundle and bundle.business_id = p_business;

  if v_service_ids is not null then
    delete from public.bundle_items item where item.bundle_id = p_bundle;
    insert into public.bundle_items (bundle_id, service_id)
    select p_bundle, service_id from unnest(v_service_ids) service_id;
  end if;

  insert into public.audit_log (business_id, actor, action, entity, entity_id, detail)
  values (
    p_business, v_actor, 'SERVICE_BUNDLE_UPDATE', 'bundles', p_bundle,
    jsonb_build_object(
      'name', v_name,
      'price_cents', p_price_cents,
      'active', p_active,
      'service_count', cardinality(coalesce(v_service_ids, array[]::uuid[]))
    )
  );

  return jsonb_build_object('status', 'updated', 'bundle_id', p_bundle);
end;
$$;

--
-- Name: update_sv_plan_draft(uuid, uuid, jsonb, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_sv_plan_draft(p_business uuid, p_draft uuid, p_config jsonb, p_expected_revision integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_row public.sv_plan_drafts%rowtype;
begin
  if not app.is_salon_owner(p_business) then raise exception 'owner only' using errcode = '42501'; end if;
  select * into v_row from public.sv_plan_drafts where id = p_draft and business_id = p_business for update;
  if not found then raise exception 'stored-value plan draft not found in this business' using errcode = '22023'; end if;
  if v_row.status <> 'draft' then raise exception 'stored-value plan draft is % and can no longer be edited', v_row.status using errcode = '22023'; end if;
  if p_expected_revision is null or p_expected_revision <> v_row.revision then
    raise exception 'stored-value plan draft was changed in another session (expected revision %, current %)', p_expected_revision, v_row.revision using errcode = '22023';
  end if;

  perform app.sv_plan_apply_config(p_business, p_draft, p_config);
  update public.sv_plan_drafts set revision = revision + 1 where id = p_draft and business_id = p_business;
  select * into v_row from public.sv_plan_drafts where id = p_draft and business_id = p_business;
  insert into public.audit_log(business_id, actor, action, entity, entity_id, detail)
  values (p_business, v_actor, 'SV_PLAN_DRAFT_UPDATED', 'sv_plan_drafts', p_draft, jsonb_build_object('revision', v_row.revision));
  return app.sv_plan_draft_json(v_row);
end $$;

--
-- Name: use_package_session(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.use_package_session(p_business uuid, p_cp uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare cp record; plan record;
begin
  if not app.is_salon_member(p_business) then raise exception 'not a member of this business'; end if;
  select * into cp from client_packages where id = p_cp and business_id = p_business for update;
  if not found then raise exception 'package not found'; end if;
  if cp.remaining <= 0 then raise exception 'no sessions remaining'; end if;
  select * into plan from package_plans where id = cp.plan_id;
  update client_packages set remaining = remaining - 1,
    status = case when remaining - 1 = 0 then 'used_up' else 'active' end
    where id = cp.id;
  insert into sales (business_id, client_id, kind, amount_cents, note)
  values (p_business, cp.client_id, 'service', 0, 'package session used: ' || plan.name);
  return cp.remaining - 1;
end $$;

--
-- Name: use_package_session(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.use_package_session(p_business uuid, p_cp uuid, p_idempotency_key text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_cp public.client_packages%rowtype;
  v_plan public.package_plans%rowtype;
  v_existing public.package_session_consumptions%rowtype;
  v_actor uuid := auth.uid();
  v_staff uuid;
  v_branch uuid;
  v_sale_id uuid := gen_random_uuid();
  v_payload jsonb;
  v_request_hash text;
begin
  if p_idempotency_key is null or length(btrim(p_idempotency_key)) < 8 then
    raise exception 'idempotency key must contain at least 8 characters' using errcode = '22023';
  end if;
  if v_actor is null then raise exception 'authenticated staff required' using errcode = '42501'; end if;
  if not app.has_perm(p_business,'create_sales') then
    raise exception 'create_sales permission required' using errcode='42501';
  end if;
  select s.id into v_staff from public.staff s
   where s.business_id=p_business and s.user_id=v_actor and s.active
     and 'create_sales'=any(app.role_perms(s.role))
   order by case s.role when 'owner' then 0 when 'manager' then 1 else 2 end,s.created_at
   limit 1 for update;
  if not found then raise exception 'active staff authorization required' using errcode='42501'; end if;
  p_idempotency_key := btrim(p_idempotency_key);
  perform pg_advisory_xact_lock(hashtextextended(
    'v34:package-session:' || p_business::text || ':' || p_idempotency_key, 0
  ));
  v_payload := jsonb_build_object('business_id', p_business, 'client_package_id', p_cp);
  v_request_hash := md5(v_payload::text);

  select * into v_existing from public.package_session_consumptions
   where business_id = p_business and idempotency_key = p_idempotency_key;
  if found then
    if v_existing.actor is distinct from v_actor or v_existing.request_hash is distinct from v_request_hash then
      raise exception 'package session idempotency key conflicts with another request' using errcode = '23505';
    end if;
    return v_existing.remaining_after;
  end if;

  select * into v_cp from public.client_packages
   where id = p_cp and business_id = p_business for update;
  if not found then raise exception 'package not found'; end if;
  if v_cp.remaining <= 0 then raise exception 'no sessions remaining'; end if;
  select * into v_plan from public.package_plans
   where id = v_cp.plan_id and business_id = p_business for share;
  if not found then raise exception 'package plan not found in this business'; end if;
  select b.id into v_branch from public.branches b
   where b.business_id=p_business and b.active and app.can_see_branch(p_business,b.id)
     and (v_plan.service_id is null or not exists (
       select 1 from public.service_branches all_sb where all_sb.service_id=v_plan.service_id
     ) or exists (
       select 1 from public.service_branches allowed_sb
        where allowed_sb.service_id=v_plan.service_id and allowed_sb.branch_id=b.id
          and allowed_sb.business_id=p_business
     ))
   order by b.is_default desc,b.created_at,b.id limit 1;
  if not found then raise exception 'no active permitted branch can consume this package' using errcode='42501'; end if;

  update public.client_packages
     set remaining = remaining - 1,
         status = case when remaining - 1 = 0 then 'used_up' else 'active' end
   where id = v_cp.id and business_id = p_business and remaining > 0;
  if not found then raise exception 'package session was consumed concurrently' using errcode = '40001'; end if;

  -- This is the retention-visit record: amount_cents = 0 and no payment is created.
  insert into public.sales
    (id, business_id, client_id, kind, amount_cents, note, branch_id, staff_id)
  values (v_sale_id, p_business, v_cp.client_id, 'service', 0,
          'package session used: ' || v_plan.name, v_branch, v_staff);

  insert into public.package_session_consumptions
    (business_id, client_package_id, client_id, sale_id, actor, idempotency_key,
     request_payload, request_hash, remaining_before, remaining_after)
  values
    (p_business, v_cp.id, v_cp.client_id, v_sale_id, v_actor, p_idempotency_key,
     v_payload, v_request_hash, v_cp.remaining, v_cp.remaining - 1);
  return v_cp.remaining - 1;
end $$;

--
-- Name: use_package_session_v102(uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.use_package_session_v102(p_business uuid, p_client_package uuid, p_branch uuid, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare
  v_actor uuid:=auth.uid();
  v_staff uuid;
  v_package public.client_packages%rowtype;
  v_existing public.package_session_consumptions%rowtype;
  v_consumption_id uuid:=gen_random_uuid();
  v_sale_id uuid:=gen_random_uuid();
  v_payload jsonb;
  v_hash text;
  v_points_total bigint;
  v_result jsonb;
begin
  p_idempotency_key:=btrim(p_idempotency_key);
  if v_actor is null or p_idempotency_key is null
     or length(p_idempotency_key)<8 then
    raise exception 'authenticated staff and valid idempotency key required'
      using errcode='22023';
  end if;
  if not app.has_perm(p_business,'create_sales')
     or not (
       app.can_module_write(p_business,'till')
       or app.can_module_write(p_business,'sales')
       or app.can_module_write(p_business,'packages')
     ) then
    raise exception 'package session authorization required' using errcode='42501';
  end if;
  select staff_row.id into v_staff
  from public.staff staff_row
  where staff_row.business_id=p_business
    and staff_row.user_id=v_actor
    and staff_row.active
    and 'create_sales'=any(app.role_perms(staff_row.role))
  order by case staff_row.role when 'owner' then 0 when 'manager' then 1 else 2 end,
           staff_row.created_at,staff_row.id
  limit 1
  for update;
  if not found then
    raise exception 'active staff authorization required' using errcode='42501';
  end if;

  v_payload:=jsonb_build_object(
    'branch_id',p_branch,
    'business_id',p_business,
    'client_package_id',p_client_package
  );
  v_hash:=md5(v_payload::text);
  perform pg_advisory_xact_lock(hashtextextended(
    'v102:package-session:'||p_business::text||':'||p_idempotency_key,0
  ));
  select * into v_existing
  from public.package_session_consumptions consumption
  where consumption.business_id=p_business
    and consumption.idempotency_key=p_idempotency_key;
  if found then
    if v_existing.actor is distinct from v_actor
       or v_existing.request_hash<>v_hash
       or v_existing.result is null then
      raise exception 'package session idempotency key conflict' using errcode='23505';
    end if;
    return v_existing.result;
  end if;

  select * into v_package
  from public.client_packages customer_package
  where customer_package.id=p_client_package
    and customer_package.business_id=p_business
  for update;
  if not found then
    raise exception 'client_package_not_found' using errcode='22023';
  end if;
  if v_package.status<>'active' or v_package.remaining<=0 then
    raise exception 'package_has_no_sessions' using errcode='22023';
  end if;
  perform 1
  from public.branches branch
  where branch.id=p_branch and branch.business_id=p_business and branch.active
    and app.can_see_branch(p_business,branch.id)
    and (
      v_package.service_id_snapshot is null
      or not exists(
        select 1 from public.service_branches any_branch
        where any_branch.business_id=p_business
          and any_branch.service_id=v_package.service_id_snapshot
      )
      or exists(
        select 1 from public.service_branches allowed
        where allowed.business_id=p_business
          and allowed.service_id=v_package.service_id_snapshot
          and allowed.branch_id=branch.id
      )
    )
  for share;
  if not found then
    raise exception 'package_branch_not_permitted' using errcode='42501';
  end if;

  update public.client_packages
  set remaining=remaining-1,
      status=case when remaining-1=0 then 'used_up' else 'active' end
  where id=v_package.id and business_id=p_business and remaining>0;
  if not found then
    raise exception 'package_session_concurrent_use' using errcode='40001';
  end if;
  insert into public.sales(
    id,business_id,client_id,kind,amount_cents,note,branch_id,staff_id
  ) values(
    v_sale_id,p_business,v_package.client_id,'service',0,
    'package session used: '||v_package.plan_name_snapshot,p_branch,v_staff
  );
  v_points_total := app.client_points_balance_v409(p_business, v_package.client_id)::bigint;
  v_result:=jsonb_build_object(
    'status','completed',
    'replayed',false,
    'consumption_id',v_consumption_id,
    'sale_id',v_sale_id,
    'client_package_id',v_package.id,
    'client_id',v_package.client_id,
    'branch_id',p_branch,
    'remaining_before',v_package.remaining,
    'remaining_after',v_package.remaining-1,
    'points_earned',0,
    'points_total',v_points_total
  );
  insert into public.package_session_consumptions(
    id,business_id,client_package_id,client_id,sale_id,actor,
    idempotency_key,request_payload,request_hash,
    remaining_before,remaining_after,result
  ) values(
    v_consumption_id,p_business,v_package.id,v_package.client_id,v_sale_id,v_actor,
    p_idempotency_key,v_payload,v_hash,
    v_package.remaining,v_package.remaining-1,v_result
  );
  return v_result;
end
$$;

--
-- Name: v156_service_claim_dispatch(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.v156_service_claim_dispatch(p_limit integer DEFAULT 10) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_rows jsonb;
begin
  -- A crashed worker's lease expires after fifteen minutes.  Retryable rows
  -- become claimable only at next_attempt_at, preserving exponential backoff.
  with claimed as (select id from public.platform_subscription_deliveries_v156 where
      ((status in ('queued','retryable_failed') and next_attempt_at<=clock_timestamp())
       or (status='processing' and last_attempt_at<clock_timestamp()-interval '15 minutes'))
      order by next_attempt_at,id for update skip locked limit least(greatest(p_limit,1),25)),
  updated as (update public.platform_subscription_deliveries_v156 d set status='processing',attempt_count=attempt_count+1,last_attempt_at=clock_timestamp(),updated_at=clock_timestamp() from claimed where d.id=claimed.id returning d.*)
  select coalesce(jsonb_agg(jsonb_build_object('delivery',to_jsonb(updated),'documents',(select jsonb_agg(jsonb_build_object('id',doc.id,'business_id',doc.business_id,'prospect_id',doc.prospect_id,'number',doc.document_number,'type',doc.document_type,'snapshot',doc.snapshot,'snapshot_sha256',doc.snapshot_sha256,'template_version',doc.template_version,'file',(select to_jsonb(file) from public.platform_subscription_document_files_v156 file where file.document_id=doc.id order by revision desc limit 1)) order by doc.document_type) from public.platform_subscription_documents_v156 doc where doc.id=any(updated.document_ids)))),'[]'::jsonb) into v_rows from updated;
  return v_rows;
end $$;

--
-- Name: v156_service_finish_delivery(uuid, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.v156_service_finish_delivery(p_delivery uuid, p_status text, p_provider_message_id text, p_failure_code text, p_failure_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_row public.platform_subscription_deliveries_v156%rowtype;
begin
  if p_status not in ('provider_accepted','delivered','retryable_failed','permanent_failed','provider_unconfigured') then raise exception 'delivery status is invalid' using errcode='22023';end if;
  update public.platform_subscription_deliveries_v156 set status=p_status,provider_message_id=nullif(btrim(p_provider_message_id),''),failure_code=nullif(btrim(p_failure_code),''),failure_reason=left(nullif(btrim(p_failure_reason),''),1000),
    delivered_at=case when p_status='delivered' then clock_timestamp() end,next_attempt_at=case when p_status='retryable_failed' then clock_timestamp()+make_interval(mins=>least(1440,5*(2^least(attempt_count,8)))) else next_attempt_at end,updated_at=clock_timestamp()
  where id=p_delivery and status='processing' returning * into v_row;if not found then raise exception 'processing delivery was not found' using errcode='22023';end if;
  if p_status in ('permanent_failed','provider_unconfigured') then perform app.v156_upsert_task('delivery-failed:'||p_delivery,'invoice_delivery_failed',v_row.business_id,null,null,v_row.provider_invoice_id,'high',clock_timestamp(),'Resolve failed billing document delivery',null);end if;
  if p_status in ('provider_accepted','delivered') and v_row.delivery_type='quotation' and v_row.prospect_id is not null then
    update public.platform_crm_commercial_v156 set quotation_status='sent',updated_at=clock_timestamp() where prospect_id=v_row.prospect_id;
    insert into public.platform_subscription_document_events_v156(document_id,status,source_type,source_id)
    select document_id,'sent','delivery',p_delivery::text from unnest(v_row.document_ids) document_id on conflict do nothing;
    insert into public.sme_prospect_activities(prospect_id,consultant_id,activity_type,summary,detail)
    select v_row.prospect_id,p.assigned_consultant_id,'document_sent','Quotation sent','delivery:'||p_delivery from public.sme_prospects p
    where p.id=v_row.prospect_id and not exists(select 1 from public.sme_prospect_activities a where a.prospect_id=v_row.prospect_id and a.activity_type='document_sent' and a.detail='delivery:'||p_delivery);
  end if;
  insert into public.platform_subscription_dispatch_audit_v156(action,entity_type,entity_id,detail) values('delivery_'||p_status,'delivery',p_delivery,jsonb_build_object('failure_code',p_failure_code,'provider_message_id',p_provider_message_id));
  return to_jsonb(v_row);
end $$;

--
-- Name: v156_service_record_document_file(uuid, text, bigint, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.v156_service_record_document_file(p_document uuid, p_path text, p_size bigint, p_sha256 text, p_template text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_row public.platform_subscription_document_files_v156%rowtype;v_business uuid;v_prospect uuid;v_revision integer;v_expected text;
begin
  select business_id,prospect_id into v_business,v_prospect from public.platform_subscription_documents_v156 where id=p_document and finalized_at is not null;if not found then raise exception 'finalized document was not found' using errcode='22023';end if;
  select coalesce(max(revision),0)+1 into v_revision from public.platform_subscription_document_files_v156 where document_id=p_document;
  v_expected:='platform-subscriptions/'||case when v_business is not null then 'businesses/'||v_business else 'prospects/'||v_prospect end||'/'||p_document||'/r'||v_revision||'.pdf';
  if p_path<>v_expected then raise exception 'document path is invalid' using errcode='22023';end if;
  insert into public.platform_subscription_document_files_v156(document_id,revision,object_path,size_bytes,sha256,template_version)
  values(p_document,v_revision,p_path,p_size,p_sha256,p_template) on conflict(document_id,revision) do update set document_id=excluded.document_id returning * into v_row;
  return to_jsonb(v_row);
end $$;

--
-- Name: validate_program_rule(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_program_rule(p_business uuid, p_rule jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_err text[];
begin
  if not (app.is_salon_owner(p_business) or app.is_super_admin()) then
    raise exception 'owner only' using errcode = '42501';
  end if;
  v_err := app.program_rule_errors(p_business, p_rule);
  return jsonb_build_object(
    'valid',     coalesce(array_length(v_err, 1), 0) = 0,
    'errors',    to_jsonb(coalesce(v_err, array[]::text[])),
    'canonical', app.program_rule_canonical(p_rule),
    'rule_hash', app.program_rule_hash(p_rule)
  );
end $$;

--
-- Name: waive_onboarding_item_v79(uuid, text, text, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.waive_onboarding_item_v79(p_business uuid, p_item_key text, p_reason text, p_expected_version bigint, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'app', 'pg_temp'
    AS $$
declare v_actor uuid:=auth.uid();v_hash text;v_replay jsonb;v_check public.business_onboarding_checklists%rowtype;v_item public.business_onboarding_items%rowtype;v_response jsonb;
begin
  if not app.is_super_admin() then raise exception 'super admin access is required' using errcode='42501';end if;
  perform app.require_idempotency_key_v79(p_idempotency_key);
  if length(btrim(coalesce(p_reason,'')))<3 then raise exception 'waiver reason is required' using errcode='22023';end if;
  v_hash:=app.v76_sha256_hex(jsonb_build_object('business',p_business,'item',p_item_key,'reason',p_reason,'version',p_expected_version)::text);
  v_replay:=app.v76_replay(v_actor,'waive_onboarding_item_v79',p_idempotency_key,v_hash);if v_replay is not null then return v_replay;end if;
  select * into v_check from public.business_onboarding_checklists where business_id=p_business and version=p_expected_version for update;
  if not found then raise exception 'onboarding version conflict' using errcode='40001';end if;
  select * into v_item from public.business_onboarding_items where business_id=p_business and item_key=p_item_key for update;
  if not found or not v_item.waivable or v_item.item_key='go_live_approved' then
    raise exception 'this onboarding item is nonwaivable' using errcode='22023';end if;
  update public.business_onboarding_items set status='waived',waived_by=v_actor,waived_at=now(),
    waiver_reason=btrim(p_reason),satisfied_by=null,satisfied_at=null,updated_at=now() where id=v_item.id;
  insert into public.business_onboarding_events(checklist_id,business_id,item_id,event_type,from_status,to_status,evidence,actor)
  values(v_check.id,p_business,v_item.id,'item_waived',v_item.status,'waived',jsonb_build_object('reason',btrim(p_reason)),v_actor);
  perform app.recompute_onboarding_status_v79(p_business,v_actor);
  v_response:=jsonb_build_object('replayed',false,'onboarding',app.get_onboarding_core_v79(p_business));
  perform app.v76_store_receipt(v_actor,'waive_onboarding_item_v79',p_idempotency_key,v_hash,v_response);return v_response;
end
$$;

