    idempotency_key text NOT NULL,
    request_fingerprint text NOT NULL,
    result_snapshot jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT account_deletion_request_events_action_check CHECK ((action = ANY (ARRAY['claim'::text, 'resolve'::text, 'retention_review'::text]))),
    CONSTRAINT account_deletion_request_events_disposition_check CHECK (((disposition IS NULL) OR (disposition = ANY (ARRAY['deleted_where_permitted'::text, 'anonymised_where_permitted'::text, 'retained_legal'::text, 'request_invalid'::text])))),
    CONSTRAINT account_deletion_request_events_evidence_reference_check CHECK (((evidence_reference IS NULL) OR ((length(evidence_reference) >= 8) AND (length(evidence_reference) <= 200)))),
    CONSTRAINT account_deletion_request_events_idempotency_key_check CHECK (((length(idempotency_key) >= 8) AND (length(idempotency_key) <= 200))),
    CONSTRAINT account_deletion_request_events_reason_check CHECK (((length(reason) >= 8) AND (length(reason) <= 1000))),
    CONSTRAINT account_deletion_request_events_request_fingerprint_check CHECK ((request_fingerprint ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT account_deletion_request_events_result_snapshot_check CHECK ((jsonb_typeof(result_snapshot) = 'object'::text)),
    CONSTRAINT account_deletion_request_events_shape_check CHECK ((((action = 'claim'::text) AND (disposition IS NULL) AND (evidence_reference IS NULL) AND (retention_until IS NULL)) OR ((action = ANY (ARRAY['resolve'::text, 'retention_review'::text])) AND (disposition IS NOT NULL) AND (evidence_reference IS NOT NULL) AND (((disposition = 'retained_legal'::text) AND (retention_until IS NOT NULL)) OR ((disposition <> 'retained_legal'::text) AND (retention_until IS NULL))))))
);

