    idempotency_key text NOT NULL,
    request_fingerprint text DEFAULT 'DELETE:v131'::text NOT NULL,
    requested_at timestamp with time zone DEFAULT now() NOT NULL,
    response_due_at timestamp with time zone DEFAULT (now() + '30 days'::interval) NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    completed_at timestamp with time zone,
    operator_note text,
    claimed_at timestamp with time zone,
    claimed_by uuid,
    resolution_code text,
    retention_until timestamp with time zone,
    resolution_reference text,
    CONSTRAINT account_deletion_requests_completion_check CHECK ((((status = 'completed'::text) AND (completed_at IS NOT NULL)) OR ((status <> 'completed'::text) AND (completed_at IS NULL)))),
    CONSTRAINT account_deletion_requests_due_check CHECK ((response_due_at = (requested_at + '30 days'::interval))),
    CONSTRAINT account_deletion_requests_idempotency_key_check CHECK (((length(idempotency_key) >= 8) AND (length(idempotency_key) <= 200))),
    CONSTRAINT account_deletion_requests_resolution_code_check CHECK (((resolution_code IS NULL) OR (resolution_code = ANY (ARRAY['deleted_where_permitted'::text, 'anonymised_where_permitted'::text, 'retained_legal'::text, 'request_invalid'::text])))),
    CONSTRAINT account_deletion_requests_resolution_reference_check CHECK (((resolution_reference IS NULL) OR ((length(resolution_reference) >= 8) AND (length(resolution_reference) <= 200)))),
    CONSTRAINT account_deletion_requests_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'processing'::text, 'completed'::text, 'rejected'::text, 'cancelled'::text]))),
    CONSTRAINT account_deletion_requests_v133_lifecycle_check CHECK ((((status = 'pending'::text) AND (claimed_at IS NULL) AND (claimed_by IS NULL) AND (resolution_code IS NULL) AND (retention_until IS NULL) AND (resolution_reference IS NULL)) OR ((status = 'processing'::text) AND (claimed_at IS NOT NULL) AND (claimed_by IS NOT NULL) AND (resolution_code IS NULL) AND (retention_until IS NULL) AND (resolution_reference IS NULL)) OR ((status = 'completed'::text) AND (completed_at IS NOT NULL) AND (claimed_at IS NOT NULL) AND (claimed_by IS NOT NULL) AND (resolution_code IS NOT NULL) AND (resolution_reference IS NOT NULL) AND (((resolution_code = 'retained_legal'::text) AND (retention_until IS NOT NULL)) OR ((resolution_code <> 'retained_legal'::text) AND (retention_until IS NULL)))) OR (status = ANY (ARRAY['rejected'::text, 'cancelled'::text]))))
);

ALTER TABLE ONLY public.account_deletion_requests FORCE ROW LEVEL SECURITY;

