    generation integer DEFAULT 1 NOT NULL,
    requested_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    claimed_at timestamp with time zone,
    completed_at timestamp with time zone,
    CONSTRAINT ai_firm_reports_v176_generation_check CHECK ((generation > 0)),
    CONSTRAINT ai_firm_reports_v176_period_kind_check CHECK ((period_kind = ANY (ARRAY['monthly'::text, 'quarterly'::text, 'yearly'::text]))),
    CONSTRAINT ai_firm_reports_v176_period_order CHECK ((period_end >= period_start)),
    CONSTRAINT ai_firm_reports_v176_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'generating'::text, 'succeeded'::text, 'failed'::text]))),
    CONSTRAINT ai_firm_reports_v176_terminal_shape CHECK ((((status = 'succeeded'::text) AND (narrative_md IS NOT NULL) AND (btrim(narrative_md) <> ''::text) AND (completed_at IS NOT NULL)) OR ((status = 'failed'::text) AND (error IS NOT NULL) AND (btrim(error) <> ''::text) AND (completed_at IS NOT NULL)) OR ((status = ANY (ARRAY['pending'::text, 'generating'::text])) AND (narrative_md IS NULL) AND (completed_at IS NULL))))
);

