    legal_name text,
    registration_number text,
    onboarding_started_at timestamp with time zone,
    activated_at timestamp with time zone,
    source_prospect_id uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    quick_earn_catalogue_enabled boolean DEFAULT true NOT NULL,
    gift_card_sales_enabled boolean DEFAULT false NOT NULL,
    is_demo boolean DEFAULT false NOT NULL,
    booking_staff_choice boolean DEFAULT false NOT NULL,
    takes_table_reservations boolean DEFAULT false NOT NULL,
    points_mode text,
    place_id text,
    postal_code text,
    bio text,
    booking_confirmation_template text,
    industry_label text,
    CONSTRAINT businesses_booking_hold_minutes_check CHECK ((booking_hold_minutes >= 0)),
    CONSTRAINT businesses_booking_overflow_check CHECK ((booking_overflow = ANY (ARRAY['waitlist'::text, 'reject'::text]))),
    CONSTRAINT businesses_custom_line_limit_cents_check CHECK ((custom_line_limit_cents >= 0)),
    CONSTRAINT businesses_gst_rate_bps_check CHECK (((gst_rate_bps >= 0) AND (gst_rate_bps <= 2000))),
    CONSTRAINT businesses_industry_label_len CHECK (((industry_label IS NULL) OR ((char_length(btrim(industry_label)) >= 1) AND (char_length(btrim(industry_label)) <= 60)))),
    CONSTRAINT businesses_points_mode_check CHECK (((points_mode IS NULL) OR (points_mode = ANY (ARRAY['redeem'::text, 'tiers'::text, 'both'::text])))),
    CONSTRAINT businesses_review_url_check CHECK (((review_url IS NULL) OR ((length(review_url) <= 500) AND (review_url ~ '^https://'::text)))),
    CONSTRAINT businesses_tax_rate_bps_check CHECK (((tax_rate_bps >= 0) AND (tax_rate_bps <= 10000)))
);

--
-- Name: COLUMN businesses.updated_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.businesses.updated_at IS 'Last workspace lifecycle update; maintained by guarded business mutation RPCs.';

--
-- Name: COLUMN businesses.booking_staff_choice; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.businesses.booking_staff_choice IS 'v183: when true the public booking page lets a customer choose a specific team member.';

--
-- Name: COLUMN businesses.takes_table_reservations; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.businesses.takes_table_reservations IS 'v223: this business seats guests at tables, so Tables/capacity and the when-full overflow rule apply. Off for appointment-only businesses (spa, salon, clinic), which still take booking requests through the public page.';

--
-- Name: COLUMN businesses.points_mode; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.businesses.points_mode IS 'FROZEN at v314 — historical record of the pre-switchboard choice. Read by nothing (the customer capability derives its points_mode key from the spine) and written by nothing (the v314 tripwire pins it and audits any attempt). The column survives so a firm''s pre-inversion choice remains recoverable and so the rollback has something to restore.';

--
-- Name: COLUMN businesses.place_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.businesses.place_id IS 'Google Place ID of this merchant''s premises. Permanently storable (GMP Service Specific Terms §3) and the strongest key for "is this discovered business already ours?".';

--
-- Name: COLUMN businesses.bio; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.businesses.bio IS 'v325: short company description shown to customers on the public booking portal. Nullable — blank means nothing is rendered. Edited from Customer Interface > Business Profile.';

--
-- Name: COLUMN businesses.industry_label; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.businesses.industry_label IS 'v385: the firm''s own wording for what it does, shown under its name in the customer app.
   NULL = fall back to the industry sector label.';

--
-- Name: campaign_send_records_v255; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.campaign_send_records_v255 (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
