    client_id uuid NOT NULL,
    recipient_key uuid GENERATED ALWAYS AS (COALESCE(identity_id, client_id)) STORED NOT NULL,
    occurred_at timestamp with time zone DEFAULT now() NOT NULL,
    retention_until timestamp with time zone DEFAULT (now() + '400 days'::interval) NOT NULL,
    CONSTRAINT campaign_send_records_v255_campaign_kind_check CHECK ((campaign_kind = ANY (ARRAY['promotion'::text, 'retention'::text, 'growth'::text]))),
    CONSTRAINT campaign_send_records_v255_campaign_label_check CHECK (((char_length(campaign_label) >= 1) AND (char_length(campaign_label) <= 200))),
    CONSTRAINT campaign_send_records_v255_channel_check CHECK ((channel = ANY (ARRAY['in_app'::text, 'web_push'::text, 'none'::text]))),
    CONSTRAINT campaign_send_records_v255_in_app_shape_check CHECK (((channel <> 'in_app'::text) OR ((identity_id IS NOT NULL) AND (link_id IS NOT NULL) AND (inbox_event_id IS NOT NULL)))),
    CONSTRAINT campaign_send_records_v255_retention_check CHECK (((retention_until >= (occurred_at + '399 days'::interval)) AND (retention_until <= (occurred_at + '401 days'::interval)))),
    CONSTRAINT campaign_send_records_v255_send_kind_check CHECK (((char_length(send_kind) >= 1) AND (char_length(send_kind) <= 60)))
);

--
-- Name: TABLE campaign_send_records_v255; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.campaign_send_records_v255 IS 'Append-only marketing send evidence. campaign_ref_id is intentionally not a foreign key and campaign_label is a snapshot so a record survives campaign deletion.';

