    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid DEFAULT auth.uid(),
    CONSTRAINT cash_drawer_movements_check CHECK (((kind <> 'pay_out'::text) OR (amount_cents < 0))),
    CONSTRAINT cash_drawer_movements_check1 CHECK (((kind <> ALL (ARRAY['open_float'::text, 'pay_in'::text, 'sale_cash'::text])) OR (amount_cents <> 0))),
    CONSTRAINT cash_drawer_movements_kind_check CHECK ((kind = ANY (ARRAY['open_float'::text, 'sale_cash'::text, 'pay_in'::text, 'pay_out'::text, 'close_variance'::text])))
);

