    opened_by uuid DEFAULT auth.uid(),
    opening_float_cents integer DEFAULT 0 NOT NULL,
    closed_at timestamp with time zone,
    closed_by uuid,
    expected_cents integer,
    counted_cents integer,
    note text,
    CONSTRAINT cash_drawer_sessions_check CHECK ((((closed_at IS NULL) AND (counted_cents IS NULL) AND (expected_cents IS NULL)) OR ((closed_at IS NOT NULL) AND (counted_cents IS NOT NULL) AND (expected_cents IS NOT NULL)))),
    CONSTRAINT cash_drawer_sessions_opening_float_cents_check CHECK ((opening_float_cents >= 0))
);

--
-- Name: cash_drawer_balance; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.cash_drawer_balance WITH (security_invoker='on') AS
 SELECT b.id AS branch_id,
    b.business_id,
    b.name AS branch_name,
    (COALESCE(sum(m.amount_cents), (0)::bigint))::integer AS expected_cents,
    ( SELECT ds.id
           FROM public.cash_drawer_sessions ds
          WHERE ((ds.branch_id = b.id) AND (ds.closed_at IS NULL))
         LIMIT 1) AS open_session_id,
    max(m.occurred_at) AS last_movement_at
   FROM (public.branches b
     LEFT JOIN public.cash_drawer_movements m ON ((m.branch_id = b.id)))
  WHERE app.has_perm(b.business_id, 'view_finance'::text)
  GROUP BY b.id, b.business_id, b.name;

--
-- Name: cash_drawer_session_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.cash_drawer_session_summary AS
SELECT
    NULL::uuid AS session_id,
    NULL::uuid AS business_id,
    NULL::uuid AS branch_id,
    NULL::timestamp with time zone AS opened_at,
    NULL::timestamp with time zone AS closed_at,
    NULL::integer AS opening_float_cents,
    NULL::integer AS expected_cents,
    NULL::integer AS counted_cents,
    NULL::integer AS variance_cents,
    NULL::integer AS cash_sales_cents,
    NULL::integer AS pay_in_cents,
    NULL::integer AS pay_out_cents,
    NULL::integer AS session_net_cents;

