-- Name: COLUMN points_ledger.programme_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.points_ledger.programme_id IS 'v309 W3 / v311 W5a: which programme this row belongs to (public.business_programmes). NOT NULL since v311. Supplied explicitly by app.on_sale_recorded''s earn loop and by every scoped write path; app.tag_ledger_programme_v309 remains as the BEFORE INSERT default for a writer nobody enumerated — it only ever fills a NULL and never overrides.';

--
-- Name: client_points_balance; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.client_points_balance WITH (security_invoker='true') AS
 SELECT business_id,
    client_id,
    COALESCE(sum(points), (0)::bigint) AS points
   FROM public.points_ledger
  GROUP BY business_id, client_id;

