--
-- Name: commerce_events_v106; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.commerce_events_v106 (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    business_id uuid NOT NULL,
    branch_id uuid,
    event_type text NOT NULL,
    schema_version integer DEFAULT 1 NOT NULL,
    source_system text NOT NULL,
    source_event_id text NOT NULL,
    idempotency_key text NOT NULL,
    occurred_at timestamp with time zone NOT NULL,
    received_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    recorded_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    business_date date NOT NULL,
    reporting_contract_id uuid NOT NULL,
    timezone text NOT NULL,
    currency text NOT NULL,
    amount_minor bigint NOT NULL,
    actor_type text DEFAULT 'integration'::text NOT NULL,
    actor_id uuid,
    causation_id text,
    correlation_id text,
    supersedes_event_id uuid,
    payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    payload_hash text NOT NULL,
    created_by uuid DEFAULT auth.uid(),
    CONSTRAINT commerce_events_v106_actor_type_check CHECK ((actor_type = ANY (ARRAY['integration'::text, 'owner'::text, 'admin'::text, 'staff'::text, 'system'::text]))),
    CONSTRAINT commerce_events_v106_amount_sign_check CHECK ((((event_type = 'transaction_completed'::text) AND (amount_minor > 0)) OR ((event_type = ANY (ARRAY['transaction_voided'::text, 'refund_completed'::text, 'chargeback_opened'::text])) AND (amount_minor < 0)) OR ((event_type = 'chargeback_reversed'::text) AND (amount_minor > 0)))),
    CONSTRAINT commerce_events_v106_clock_check CHECK ((recorded_at >= received_at)),
    CONSTRAINT commerce_events_v106_currency_check CHECK ((currency ~ '^[A-Z]{3}$'::text)),
    CONSTRAINT commerce_events_v106_event_type_check CHECK ((event_type = ANY (ARRAY['transaction_completed'::text, 'transaction_voided'::text, 'refund_completed'::text, 'chargeback_opened'::text, 'chargeback_reversed'::text]))),
    CONSTRAINT commerce_events_v106_idempotency_key_check CHECK (((length(btrim(idempotency_key)) >= 1) AND (length(btrim(idempotency_key)) <= 200))),
    CONSTRAINT commerce_events_v106_payload_check CHECK ((jsonb_typeof(payload) = 'object'::text)),
    CONSTRAINT commerce_events_v106_payload_hash_check CHECK ((payload_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT commerce_events_v106_schema_version_check CHECK ((schema_version = 1)),
    CONSTRAINT commerce_events_v106_source_event_id_check CHECK (((length(btrim(source_event_id)) >= 1) AND (length(btrim(source_event_id)) <= 200))),
    CONSTRAINT commerce_events_v106_source_system_check CHECK ((source_system ~ '^[a-z0-9][a-z0-9._-]{1,62}$'::text))
);

