--
-- Name: consultant_commission_accruals; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.consultant_commission_accruals (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    attribution_id uuid NOT NULL,
    consultant_id uuid NOT NULL,
    business_id uuid NOT NULL,
    invoice_id uuid NOT NULL,
    provider_invoice_id text NOT NULL,
    policy_id uuid NOT NULL,
    tier_snapshot text NOT NULL,
    commission_phase text NOT NULL,
    onboarding_started_at timestamp with time zone NOT NULL,
    invoice_paid_at timestamp with time zone NOT NULL,
    eligible_at timestamp with time zone NOT NULL,
    basis_cents integer NOT NULL,
    rate_bps integer NOT NULL,
    commission_cents integer NOT NULL,
    currency text NOT NULL,
    status text NOT NULL,
    approved_by uuid,
    approved_at timestamp with time zone,
    forfeited_at timestamp with time zone,
    forfeiture_reason text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT consultant_commission_accruals_basis_cents_check CHECK ((basis_cents > 0)),
    CONSTRAINT consultant_commission_accruals_commission_cents_check CHECK ((commission_cents >= 0)),
    CONSTRAINT consultant_commission_accruals_commission_phase_check CHECK ((commission_phase = ANY (ARRAY['first_year_base'::text, 'anniversary_bonus'::text, 'renewal'::text]))),
    CONSTRAINT consultant_commission_accruals_currency_check CHECK ((currency ~ '^[A-Z]{3}$'::text)),
    CONSTRAINT consultant_commission_accruals_eligibility_check CHECK ((eligible_at >= invoice_paid_at)),
    CONSTRAINT consultant_commission_accruals_rate_bps_check CHECK (((rate_bps >= 0) AND (rate_bps <= 10000))),
    CONSTRAINT consultant_commission_accruals_status_check CHECK ((status = ANY (ARRAY['accrued'::text, 'approved'::text, 'paid'::text, 'forfeited'::text]))),
    CONSTRAINT consultant_commission_accruals_status_shape CHECK ((((status = 'accrued'::text) AND (approved_at IS NULL) AND (forfeited_at IS NULL)) OR ((status = ANY (ARRAY['approved'::text, 'paid'::text])) AND (approved_at IS NOT NULL) AND (forfeited_at IS NULL)) OR ((status = 'forfeited'::text) AND (forfeited_at IS NOT NULL) AND (length(btrim(COALESCE(forfeiture_reason, ''::text))) >= 3)))),
    CONSTRAINT consultant_commission_accruals_tier_snapshot_check CHECK ((tier_snapshot = ANY (ARRAY['senior'::text, 'junior'::text])))
);

