    CONSTRAINT consultant_commission_adjustments_adjustment_type_check CHECK ((adjustment_type = ANY (ARRAY['refund'::text, 'chargeback'::text, 'reversal'::text]))),
    CONSTRAINT consultant_commission_adjustments_rate_bps_check CHECK (((rate_bps >= 0) AND (rate_bps <= 10000))),
    CONSTRAINT consultant_commission_adjustments_settlement_status_check CHECK ((settlement_status = ANY (ARRAY['payable'::text, 'forfeited_to_nestly'::text]))),
    CONSTRAINT consultant_commission_adjustments_shape_check CHECK ((((adjustment_type = ANY (ARRAY['refund'::text, 'chargeback'::text])) AND (reversal_of IS NULL) AND (basis_adjustment_cents < 0) AND (commission_adjustment_cents <= 0)) OR ((adjustment_type = 'reversal'::text) AND (reversal_of IS NOT NULL) AND (basis_adjustment_cents > 0) AND (commission_adjustment_cents >= 0))))
);

