    CONSTRAINT consultant_commission_policies_basis_rule_check CHECK ((basis_rule = 'net_cash_collected_ex_gst_refunds_chargebacks'::text)),
    CONSTRAINT consultant_commission_policies_first_year_bps_check CHECK (((first_year_bps >= 0) AND (first_year_bps <= 10000))),
    CONSTRAINT consultant_commission_policies_reason_check CHECK (((length(btrim(reason)) >= 3) AND (length(btrim(reason)) <= 1000))),
    CONSTRAINT consultant_commission_policies_renewal_bps_check CHECK (((renewal_bps >= 0) AND (renewal_bps <= 10000))),
    CONSTRAINT consultant_commission_policies_setup_fee_included_check CHECK (setup_fee_included),
    CONSTRAINT consultant_commission_policies_tier_check CHECK ((tier = ANY (ARRAY['senior'::text, 'junior'::text]))),
    CONSTRAINT consultant_commission_policies_total_rate_check CHECK (((first_year_bps + anniversary_bonus_bps) <= 10000)),
    CONSTRAINT consultant_commission_policies_version_check CHECK ((version > 0)),
    CONSTRAINT consultant_commission_policies_window_check CHECK (((effective_to IS NULL) OR (effective_to > effective_from)))
);

