    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT customer_contact_proofs_contact_type_check CHECK ((contact_type = ANY (ARRAY['email'::text, 'phone'::text]))),
    CONSTRAINT customer_contact_proofs_expiry_check CHECK ((expires_at > issued_at)),
    CONSTRAINT customer_contact_proofs_method_type_check CHECK ((((contact_type = 'email'::text) AND (proof_method = ANY (ARRAY['auth_email_confirmation'::text, 'email_otp'::text, 'firm_invitation'::text, 'support_recovery'::text]))) OR ((contact_type = 'phone'::text) AND (proof_method = 'auth_phone_otp'::text)))),
    CONSTRAINT customer_contact_proofs_state_check CHECK ((((status = 'verified'::text) AND (verified_at IS NOT NULL)) OR ((status = ANY (ARRAY['expired'::text, 'revoked'::text])) AND (verified_at IS NULL)))),
    CONSTRAINT customer_contact_proofs_status_check CHECK ((status = ANY (ARRAY['verified'::text, 'expired'::text, 'revoked'::text])))
);

--
-- Name: CONSTRAINT customer_contact_proofs_method_type_check ON customer_contact_proofs; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON CONSTRAINT customer_contact_proofs_method_type_check ON public.customer_contact_proofs IS 'Sole proof_method/contact_type allowlist. v30 declared proof_method with an inline (auto-named customer_contact_proofs_proof_method_check) email-only check alongside this named check; c42 rewrote only the named check to admit phone/auth_phone_otp, and v50b dropped the surviving stale inline check so phone registration is no longer structurally rejected.';

