CREATE VIEW public.customer_identity_current_attribution_v111 WITH (security_invoker='true') AS
 SELECT DISTINCT ON (business_id, source_client_id) business_id,
    source_client_id,
    after_client_id AS effective_client_id,
    proposal_id,
    decision_id,
    event_type,
    occurred_at
   FROM public.customer_identity_attribution_events_v111 event
  ORDER BY business_id, source_client_id, event_sequence DESC;

