    CONSTRAINT growth_executions_v108_check CHECK (((jsonb_typeof(governed_copy) = 'object'::text) AND (governed_copy ?& ARRAY['schema'::text, 'version'::text, 'title'::text, 'body'::text, 'cta_label'::text, 'cta_destination'::text, 'eligibility'::text, 'conditions'::text, 'locked_facts'::text]) AND ((governed_copy ->> 'schema'::text) = governed_copy_schema) AND (((governed_copy ->> 'version'::text))::integer = governed_copy_version) AND ((governed_copy ->> 'cta_destination'::text) = 'customer_growth_offer_qr'::text) AND ((governed_copy ->> 'cta_label'::text) = 'Redeem now'::text) AND (jsonb_typeof((governed_copy -> 'eligibility'::text)) = 'object'::text) AND (jsonb_typeof((governed_copy -> 'conditions'::text)) = 'object'::text) AND (jsonb_typeof((governed_copy -> 'locked_facts'::text)) = 'object'::text) AND ((governed_copy #>> '{locked_facts,template_id}'::text[]) = offer_label) AND (((governed_copy #>> '{locked_facts,offer_value_cents}'::text[]))::integer = offer_value_cents) AND ((governed_copy #>> '{locked_facts,currency}'::text[]) = currency) AND (((governed_copy #>> '{locked_facts,expires_at}'::text[]))::timestamp with time zone = offer_expires_at) AND ((governed_copy #>> '{locked_facts,timezone}'::text[]) = offer_timezone) AND (((governed_copy #>> '{conditions,expires_at}'::text[]))::timestamp with time zone = offer_expires_at) AND ((governed_copy #>> '{conditions,timezone}'::text[]) = offer_timezone) AND (((governed_copy #>> '{eligibility,business_id}'::text[]))::uuid = business_id) AND (NOT (((governed_copy #>> '{eligibility,branch_id}'::text[]))::uuid IS DISTINCT FROM branch_id)))),
    CONSTRAINT growth_executions_v108_currency_check CHECK ((currency ~ '^[A-Z]{3}$'::text)),
