    CONSTRAINT growth_executions_v108_status_check CHECK ((status = ANY (ARRAY['running'::text, 'cancelled'::text, 'completed'::text]))),
    CONSTRAINT growth_executions_v108_window_check CHECK (((ends_at > started_at) AND (offer_expires_at > started_at) AND (offer_expires_at <= ends_at)))
);

