    CONSTRAINT growth_recommendations_v108_recommended_offer_check CHECK ((jsonb_typeof(recommended_offer) = 'object'::text)),
    CONSTRAINT growth_recommendations_v108_status_check CHECK ((status = ANY (ARRAY['presented'::text, 'suppressed'::text, 'accepted'::text, 'dismissed'::text, 'expired'::text, 'executed'::text, 'completed'::text]))),
    CONSTRAINT growth_recommendations_v108_stop_conditions_check CHECK ((jsonb_typeof(stop_conditions) = 'object'::text)),
