    CONSTRAINT loyalty_operations_idempotency_key_check CHECK ((length(btrim(idempotency_key)) >= 8)),
    CONSTRAINT loyalty_operations_operation_type_check CHECK ((operation_type = ANY (ARRAY['redeem_points'::text, 'redeem_reward'::text]))),
    CONSTRAINT loyalty_operations_request_payload_check CHECK ((jsonb_typeof(request_payload) = 'object'::text)),
    CONSTRAINT loyalty_operations_shape_check CHECK ((((operation_type = 'redeem_points'::text) AND (reward_id IS NULL)) OR ((operation_type = 'redeem_reward'::text) AND (reward_id IS NOT NULL)))),
    CONSTRAINT loyalty_operations_status_check CHECK ((status = ANY (ARRAY['reserved'::text, 'completed'::text])))
);

