    CONSTRAINT loyalty_program_versions_earn_points_per_dollar_check CHECK ((earn_points_per_dollar >= (0)::numeric)),
    CONSTRAINT loyalty_program_versions_expiry_days_check CHECK (((expiry_days IS NULL) OR (expiry_days > 0))),
    CONSTRAINT loyalty_program_versions_expiry_mode_check CHECK ((expiry_mode = ANY (ARRAY['none'::text, 'fixed'::text, 'inactivity'::text]))),
    CONSTRAINT loyalty_program_versions_kind_check CHECK ((kind = ANY (ARRAY['points'::text, 'stamps'::text]))),
    CONSTRAINT loyalty_program_versions_loyalty_model_check CHECK ((loyalty_model = ANY (ARRAY['classic'::text, 'points_tiers'::text, 'stamps'::text]))),
    CONSTRAINT loyalty_program_versions_redeem_points_check CHECK ((redeem_points > 0)),
    CONSTRAINT loyalty_program_versions_reward_credit_cents_check CHECK ((reward_credit_cents >= 0)),
    CONSTRAINT loyalty_program_versions_stamp_per_cents_check CHECK (((stamp_per_cents IS NULL) OR (stamp_per_cents > 0))),
    CONSTRAINT loyalty_program_versions_tier_basis_check CHECK ((tier_basis = ANY (ARRAY['visits'::text, 'spend'::text, 'points_earned'::text])))
);

--
-- Name: loyalty_programs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.loyalty_programs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    business_id uuid NOT NULL,
    kind text DEFAULT 'points'::text NOT NULL,
    stamp_target integer,
    reward_credit_cents integer DEFAULT 0 NOT NULL,
    active boolean DEFAULT true NOT NULL,
    earn_points_per_dollar numeric DEFAULT 1 NOT NULL,
    redeem_points integer DEFAULT 800 NOT NULL,
    tier_basis text DEFAULT 'visits'::text NOT NULL,
    loyalty_model text DEFAULT 'classic'::text NOT NULL,
    expiry_mode text DEFAULT 'none'::text NOT NULL,
    expiry_days integer,
    stamp_per_cents integer,
    configuration_status text DEFAULT 'draft'::text NOT NULL,
    recommendation_source text,
    current_config_version_id uuid,
    CONSTRAINT loyalty_programs_configuration_status_check CHECK (((configuration_status = ANY (ARRAY['draft'::text, 'published'::text])) AND ((configuration_status <> 'draft'::text) OR (NOT active)))),
    CONSTRAINT loyalty_programs_expiry_mode_check CHECK ((expiry_mode = ANY (ARRAY['none'::text, 'fixed'::text, 'inactivity'::text]))),
    CONSTRAINT loyalty_programs_kind_check CHECK ((kind = ANY (ARRAY['points'::text, 'stamps'::text]))),
    CONSTRAINT loyalty_programs_loyalty_model_check CHECK ((loyalty_model = ANY (ARRAY['classic'::text, 'points_tiers'::text, 'stamps'::text]))),
    CONSTRAINT loyalty_programs_stamp_per_cents_check CHECK (((stamp_per_cents IS NULL) OR (stamp_per_cents > 0))),
    CONSTRAINT loyalty_programs_tier_basis_check CHECK ((tier_basis = ANY (ARRAY['visits'::text, 'spend'::text, 'points_earned'::text])))
);

--
-- Name: COLUMN loyalty_programs.active; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.loyalty_programs.active IS 'SETTINGS as of v314: "this firm has a published loyalty configuration". It no longer decides which programmes run — public.business_programmes does, and it decides it COMPLETELY: a programme whose spine row is false neither accrues (app.on_sale_recorded) nor pays out (app.redeem_reward_core, which as of v314 does not test this column at all, in its row lookup or anywhere else) nor quotes (customer_create_redemption_intent_v89, customer_get_business_actions_v89). Pausing is therefore ONE flag with ONE meaning; setting this column false pauses nothing on its own, and every publish route in the browser applies the matching switch through public.set_programmes_v314. It is still read by the customer wallet/activity capabilities as "is loyalty configured at all", which is a deliberate residual named in the v314 acceptance doc for increment 2, not an oversight.';

--
-- Name: COLUMN loyalty_programs.loyalty_model; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.loyalty_programs.loyalty_model IS 'SETTINGS as of v314, not a switch. It still selects which engine SETTINGS a version carries (earn rate vs spend-per-stamp) and it is still single-valued and CHECK-constrained, but "is the stamps programme running?" is answered by public.business_programmes, not here. Recorded risk (W6 brief §7): loyalty_program_versions.kind and .loyalty_model remain single-valued under the v26 immutability guard, so a later increment that wants per-programme settings rows must plan for that guard.';

--
-- Name: COLUMN loyalty_programs.stamp_per_cents; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.loyalty_programs.stamp_per_cents IS 'stamps model: cents of spend per stamp earned (500 = one stamp per full $5; $12 -> 2 stamps). Firm-set. Required (positive) for the model to mint stamps.';

--
-- Name: COLUMN loyalty_programs.configuration_status; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.loyalty_programs.configuration_status IS 'draft = editable recommendation that has no earn/redeem effect; published = owner accepted.';

--
-- Name: COLUMN loyalty_programs.recommendation_source; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.loyalty_programs.recommendation_source IS 'Provenance for a generated draft, for example onboarding_preset or imported_data_rules_v1.';

--
-- Name: loyalty_redemption_batch_drains; Type: TABLE; Schema: public; Owner: -
