);

--
-- Name: loyalty_redemption_provenance; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.loyalty_redemption_provenance (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    business_id uuid NOT NULL,
    client_id uuid NOT NULL,
    operation_id uuid NOT NULL,
    redemption_id uuid NOT NULL,
    points_ledger_id uuid,
    credit_ledger_id uuid,
    config_version_id uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    consumes_balance boolean DEFAULT true NOT NULL,
    CONSTRAINT loyalty_redemption_provenance_consumption_shape_check CHECK (((consumes_balance AND (points_ledger_id IS NOT NULL)) OR ((NOT consumes_balance) AND (points_ledger_id IS NULL))))
);

--
-- Name: COLUMN loyalty_redemption_provenance.consumes_balance; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.loyalty_redemption_provenance.consumes_balance IS 'v323: the same flag, denormalised so the provenance row''s own CHECK can bind it to points_ledger_id. true => a ledger row exists; false => there is none, because nothing moved. public.merchant_scan_redemption_qr_v117 reads only redemption_id and is unaffected.';

--
-- Name: loyalty_redemption_reversals; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.loyalty_redemption_reversals (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    business_id uuid NOT NULL,
    redemption_id uuid NOT NULL,
    provenance_id uuid NOT NULL,
    client_id uuid NOT NULL,
    actor uuid NOT NULL,
    idempotency_key text NOT NULL,
    request_payload jsonb NOT NULL,
    request_hash text NOT NULL,
    restored_points_ledger_id uuid NOT NULL,
    reversed_credit_ledger_id uuid,
    result jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT loyalty_redemption_reversals_check CHECK ((request_hash = md5((request_payload)::text))),
    CONSTRAINT loyalty_redemption_reversals_idempotency_key_check CHECK ((length(btrim(idempotency_key)) >= 8)),
    CONSTRAINT loyalty_redemption_reversals_request_payload_check CHECK ((jsonb_typeof(request_payload) = 'object'::text)),
    CONSTRAINT loyalty_redemption_reversals_result_check CHECK ((jsonb_typeof(result) = 'object'::text))
);

--
-- Name: loyalty_redemptions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.loyalty_redemptions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    business_id uuid NOT NULL,
    client_id uuid NOT NULL,
    reward_id uuid,
    reward_name text NOT NULL,
    points_spent integer NOT NULL,
    credit_cents integer NOT NULL,
    redeemed_at timestamp with time zone DEFAULT now() NOT NULL,
    actor uuid,
    config_version_id uuid,
    reward_version_id uuid,
    reward_snapshot jsonb,
    eligibility_snapshot jsonb,
    fulfillment_kind text,
    entitlement_expires_at timestamp with time zone,
    usage_number integer,
    consumes_balance boolean DEFAULT true NOT NULL,
    CONSTRAINT loyalty_redemptions_consumption_shape_check CHECK (((consumes_balance AND (points_spent > 0)) OR ((NOT consumes_balance) AND (points_spent = 0)))),
    CONSTRAINT loyalty_redemptions_credit_cents_check CHECK ((credit_cents >= 0)),
    CONSTRAINT loyalty_redemptions_eligibility_snapshot_shape_check CHECK (((eligibility_snapshot IS NULL) OR (jsonb_typeof(eligibility_snapshot) = 'object'::text))),
    CONSTRAINT loyalty_redemptions_fulfillment_kind_check CHECK (((fulfillment_kind IS NULL) OR (fulfillment_kind = ANY (ARRAY['credit'::text, 'manual_item'::text])))),
    CONSTRAINT loyalty_redemptions_points_spent_check CHECK ((points_spent >= 0)),
    CONSTRAINT loyalty_redemptions_snapshot_shape_check CHECK (((reward_snapshot IS NULL) OR (jsonb_typeof(reward_snapshot) = 'object'::text))),
    CONSTRAINT loyalty_redemptions_usage_number_check CHECK (((usage_number IS NULL) OR (usage_number > 0)))
);

--
-- Name: COLUMN loyalty_redemptions.consumes_balance; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.loyalty_redemptions.consumes_balance IS 'v323: did this redemption take a balance? true for every points reward — the paired CHECK then requires points_spent > 0, so an ordinary points reward is structurally unable to record a free claim. false only for a stamp-quest milestone claim, which is non-consuming by design (R5): no points_ledger row, no points_batches drain, points_spent = 0.';

