    instructions text,
    terms text,
    image_ref text,
    usage_limit integer,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    min_tier_id uuid,
    min_tier_threshold integer,
    programme_id uuid NOT NULL,
    requires_purchase boolean DEFAULT false NOT NULL,
    CONSTRAINT loyalty_reward_versions_claim_window_check CHECK (((claim_available_until IS NULL) OR (claim_available_from IS NULL) OR (claim_available_until > claim_available_from))),
    CONSTRAINT loyalty_reward_versions_cost_points_check CHECK ((cost_points > 0)),
    CONSTRAINT loyalty_reward_versions_credit_cents_check CHECK ((credit_cents >= 0)),
    CONSTRAINT loyalty_reward_versions_customer_name_check CHECK (((length(btrim(customer_name)) >= 1) AND (length(btrim(customer_name)) <= 120))),
    CONSTRAINT loyalty_reward_versions_description_check CHECK (((description IS NULL) OR (length(description) <= 2000))),
    CONSTRAINT loyalty_reward_versions_entitlement_expiry_days_check CHECK (((entitlement_expiry_days IS NULL) OR (entitlement_expiry_days > 0))),
    CONSTRAINT loyalty_reward_versions_estimated_cost_cents_check CHECK ((estimated_cost_cents >= 0)),
    CONSTRAINT loyalty_reward_versions_fulfillment_amount_check CHECK ((((fulfillment_kind = 'credit'::text) AND (credit_cents > 0)) OR ((fulfillment_kind = 'manual_item'::text) AND (credit_cents = 0)))),
    CONSTRAINT loyalty_reward_versions_fulfillment_kind_check CHECK ((fulfillment_kind = ANY (ARRAY['credit'::text, 'manual_item'::text]))),
    CONSTRAINT loyalty_reward_versions_image_ref_check CHECK (((image_ref IS NULL) OR (image_ref ~ '^[a-z0-9][a-z0-9/_-]{0,247}\.(png|jpg|jpeg|webp)$'::text) OR (image_ref ~ '^https://[A-Za-z0-9.-]+(/[A-Za-z0-9._~:/?#\[\]@!$&''()*+,;=%-]*)?$'::text))),
    CONSTRAINT loyalty_reward_versions_instructions_check CHECK (((instructions IS NULL) OR (length(instructions) <= 4000))),
    CONSTRAINT loyalty_reward_versions_internal_name_check CHECK (((length(btrim(internal_name)) >= 1) AND (length(btrim(internal_name)) <= 120))),
    CONSTRAINT loyalty_reward_versions_taxonomy_label_check CHECK (((taxonomy_label IS NULL) OR ((length(btrim(taxonomy_label)) >= 1) AND (length(btrim(taxonomy_label)) <= 80)))),
    CONSTRAINT loyalty_reward_versions_terms_check CHECK (((terms IS NULL) OR (length(terms) <= 4000))),
    CONSTRAINT loyalty_reward_versions_usage_limit_check CHECK (((usage_limit IS NULL) OR (usage_limit > 0)))
);

