-- Name: COLUMN loyalty_reward_versions.min_tier_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.loyalty_reward_versions.min_tier_id IS 'V176 draft-side tier gate; carried by app.clone_reward_versions_for_config and promoted by publish_loyalty_config.';

--
-- Name: COLUMN loyalty_reward_versions.min_tier_threshold; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.loyalty_reward_versions.min_tier_threshold IS 'V176 draft-side fallback gate value.';

--
-- Name: COLUMN loyalty_reward_versions.programme_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.loyalty_reward_versions.programme_id IS 'v313 W6i1: the programme this reward VERSION is priced in. This is the column app.redeem_reward_core and public.customer_create_redemption_intent_v89 read to decide which pot to prove and drain, so it — not the business''s model — is what stops a stamp gift being paid for out of a customer''s points.';

--
-- Name: COLUMN loyalty_reward_versions.requires_purchase; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.loyalty_reward_versions.requires_purchase IS 'V340 draft-side purchase requirement; carried by app.clone_reward_versions_for_config and promoted by public.publish_loyalty_config.';

--
-- Name: loyalty_rewards; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.loyalty_rewards (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    business_id uuid NOT NULL,
    name text NOT NULL,
    cost_points integer NOT NULL,
    credit_cents integer NOT NULL,
    active boolean DEFAULT true NOT NULL,
    sort integer DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    internal_name text NOT NULL,
    customer_name text NOT NULL,
    description text,
    fulfillment_kind text NOT NULL,
    taxonomy_label text,
    instructions text,
    terms text,
    image_ref text,
    estimated_cost_cents integer NOT NULL,
    claim_available_from timestamp with time zone,
    claim_available_until timestamp with time zone,
    entitlement_expiry_days integer,
    usage_limit integer,
    current_config_version_id uuid,
    min_tier_id uuid,
    min_tier_threshold integer,
    programme_id uuid NOT NULL,
    paused boolean DEFAULT false NOT NULL,
    requires_purchase boolean DEFAULT false NOT NULL,
    CONSTRAINT loyalty_rewards_claim_window_check CHECK (((claim_available_until IS NULL) OR (claim_available_from IS NULL) OR (claim_available_until > claim_available_from))),
    CONSTRAINT loyalty_rewards_cost_points_check CHECK ((cost_points > 0)),
    CONSTRAINT loyalty_rewards_credit_cents_check CHECK ((credit_cents >= 0)),
    CONSTRAINT loyalty_rewards_customer_name_check CHECK (((length(btrim(customer_name)) >= 1) AND (length(btrim(customer_name)) <= 120))),
    CONSTRAINT loyalty_rewards_description_check CHECK (((description IS NULL) OR (length(description) <= 2000))),
    CONSTRAINT loyalty_rewards_entitlement_expiry_check CHECK (((entitlement_expiry_days IS NULL) OR (entitlement_expiry_days > 0))),
    CONSTRAINT loyalty_rewards_estimated_cost_check CHECK ((estimated_cost_cents >= 0)),
    CONSTRAINT loyalty_rewards_fulfillment_amount_check CHECK ((((fulfillment_kind = 'credit'::text) AND (credit_cents > 0)) OR ((fulfillment_kind = 'manual_item'::text) AND (credit_cents = 0)))),
    CONSTRAINT loyalty_rewards_fulfillment_kind_check CHECK ((fulfillment_kind = ANY (ARRAY['credit'::text, 'manual_item'::text]))),
    CONSTRAINT loyalty_rewards_image_ref_check CHECK (((image_ref IS NULL) OR (image_ref ~ '^[a-z0-9][a-z0-9/_-]{0,247}\.(png|jpg|jpeg|webp)$'::text) OR (image_ref ~ '^https://[A-Za-z0-9.-]+(/[A-Za-z0-9._~:/?#\[\]@!$&''()*+,;=%-]*)?$'::text))),
    CONSTRAINT loyalty_rewards_instructions_check CHECK (((instructions IS NULL) OR (length(instructions) <= 4000))),
    CONSTRAINT loyalty_rewards_internal_name_check CHECK (((length(btrim(internal_name)) >= 1) AND (length(btrim(internal_name)) <= 120))),
    CONSTRAINT loyalty_rewards_taxonomy_label_check CHECK (((taxonomy_label IS NULL) OR ((length(btrim(taxonomy_label)) >= 1) AND (length(btrim(taxonomy_label)) <= 80)))),
    CONSTRAINT loyalty_rewards_terms_check CHECK (((terms IS NULL) OR (length(terms) <= 4000))),
    CONSTRAINT loyalty_rewards_usage_limit_check CHECK (((usage_limit IS NULL) OR (usage_limit > 0)))
);

--
-- Name: COLUMN loyalty_rewards.image_ref; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.loyalty_rewards.image_ref IS 'Validated relative Storage key or HTTPS image URL. Data URLs and executable schemes are rejected.';

--
-- Name: COLUMN loyalty_rewards.entitlement_expiry_days; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.loyalty_rewards.entitlement_expiry_days IS 'Firm-visible claim validity. Its value is snapshotted on redemption; expiry enforcement for held benefits requires a future entitlement state machine.';

--
-- Name: COLUMN loyalty_rewards.min_tier_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.loyalty_rewards.min_tier_id IS 'V176 soft reference to loyalty_tiers.tier_id gating this reward; null = available to every member.';

--
-- Name: COLUMN loyalty_rewards.min_tier_threshold; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.loyalty_rewards.min_tier_threshold IS 'V176 fallback gate value used when min_tier_id no longer resolves to a live tier.';

--
-- Name: COLUMN loyalty_rewards.programme_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.loyalty_rewards.programme_id IS 'v313 W6i1: the programme this reward is priced in (public.business_programmes). Identity, not runningness — a paused programme still owns its rewards. Backfilled once from app.resolve_ledger_programme_v309 in the last transaction in which that resolver was unambiguous; supplied explicitly by every writer since. Promoted from the version row by publish_loyalty_config.';

--
-- Name: COLUMN loyalty_rewards.paused; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.loyalty_rewards.paused IS 'V326 immediate-write pause: temporarily withheld from redemption without deleting the gift. Not part of loyalty_reward_versions or the draft/publish cycle — publish_loyalty_config must never reference this column, and no migration should ever add it to loyalty_reward_versions.';

--
-- Name: COLUMN loyalty_rewards.requires_purchase; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.loyalty_rewards.requires_purchase IS 'V340 owner assertion: true = the customer must also make a purchase to claim this reward. false (the default, and the behaviour of every redemption path in this product) = the points balance alone is enough. Not enforced by app.redeem_reward_core — it is a counter condition the owner states, and the customer surface only ever renders the false case.';

