    CONSTRAINT platform_subscription_documents_v156_check1 CHECK ((((finalized_at IS NULL) AND (document_number IS NULL) AND (snapshot_sha256 IS NULL)) OR ((finalized_at IS NOT NULL) AND (document_number IS NOT NULL) AND (issue_date IS NOT NULL) AND (snapshot_sha256 IS NOT NULL)))),
    CONSTRAINT platform_subscription_documents_v156_check2 CHECK ((total_cents = ((subtotal_cents - discount_cents) + tax_cents))),
    CONSTRAINT platform_subscription_documents_v156_check3 CHECK (((amount_paid_cents + balance_due_cents) = total_cents)),
    CONSTRAINT platform_subscription_documents_v156_currency_check CHECK ((currency = 'SGD'::text)),
    CONSTRAINT platform_subscription_documents_v156_discount_cents_check CHECK ((discount_cents >= 0)),
    CONSTRAINT platform_subscription_documents_v156_document_type_check CHECK ((document_type = ANY (ARRAY['quotation'::text, 'invoice'::text, 'receipt'::text, 'subscription_summary'::text]))),
    CONSTRAINT platform_subscription_documents_v156_request_hash_check CHECK ((request_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT platform_subscription_documents_v156_snapshot_check CHECK ((jsonb_typeof(snapshot) = 'object'::text)),
    CONSTRAINT platform_subscription_documents_v156_snapshot_sha256_check CHECK (((snapshot_sha256 IS NULL) OR (snapshot_sha256 ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT platform_subscription_documents_v156_subtotal_cents_check CHECK ((subtotal_cents >= 0)),
    CONSTRAINT platform_subscription_documents_v156_tax_cents_check CHECK ((tax_cents >= 0)),
    CONSTRAINT platform_subscription_documents_v156_total_cents_check CHECK ((total_cents >= 0))
);

