COMMENT ON COLUMN public.products.size_ml IS 'V278 bottle size in millilitres. NOT NULL means this product is a bottle the bar can park; the park dialog fills the size from here so it is never typed.';

--
-- Name: stock_batches; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.stock_batches (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    product_id uuid NOT NULL,
    qty integer NOT NULL,
    expires_on date,
    received_on date DEFAULT (timezone('Asia/Singapore'::text, now()))::date NOT NULL,
    CONSTRAINT stock_batches_qty_check CHECK ((qty >= 0))
);

--
-- Name: product_stock; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.product_stock WITH (security_invoker='true') AS
 SELECT p.id AS product_id,
    p.business_id,
    (COALESCE(sum(b.qty), (0)::bigint))::integer AS stock
   FROM (public.products p
     LEFT JOIN public.stock_batches b ON ((b.product_id = p.id)))
  GROUP BY p.id, p.business_id;

