    CONSTRAINT program_rules_sort_check CHECK (((sort >= 0) AND (sort <= 10000))),
    CONSTRAINT program_rules_source_engine_check CHECK ((source_engine = 'studio_rule'::text)),
    CONSTRAINT program_rules_then_effects_check CHECK ((jsonb_typeof(then_effects) = 'array'::text)),
    CONSTRAINT program_rules_using_stacking_check CHECK ((jsonb_typeof(using_stacking) = 'object'::text)),
