    expires_at timestamp with time zone,
    redeemed_at timestamp with time zone,
    redeemed_sale_id uuid,
    redeemed_by uuid,
    beneficiary text DEFAULT 'referrer'::text NOT NULL,
    CONSTRAINT referral_grants_v420_beneficiary_check CHECK ((beneficiary = ANY (ARRAY['referrer'::text, 'friend'::text]))),
    CONSTRAINT referral_grants_v420_status_check CHECK ((status = ANY (ARRAY['granted'::text, 'redeemed'::text, 'expired'::text])))
);

--
-- Name: TABLE referral_grants_v420; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.referral_grants_v420 IS 'v420: a free-gift referral payout owed to the REFERRER, claimed once at the counter. Written only by app.on_sale_recorded when the friend''s first qualifying visit lands; redeemed by public.staff_redeem_referral_v420 against a $0 sale.';

--
-- Name: COLUMN referral_grants_v420.beneficiary; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.referral_grants_v420.beneficiary IS 'v421: which side of the referral this gift belongs to - ''referrer'' (the customer who introduced) or ''friend'' (the customer who was introduced). Existing rows are all referrer.';

--
-- Name: referral_programs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.referral_programs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    business_id uuid NOT NULL,
    enabled boolean DEFAULT false NOT NULL,
    reward_cents integer DEFAULT 1000 NOT NULL,
    min_spend_cents integer DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    reward_points integer DEFAULT 0 NOT NULL,
    reward_kind text DEFAULT 'points'::text NOT NULL,
    reward_label text,
    friend_enabled boolean DEFAULT true NOT NULL,
    friend_reward_points integer,
    friend_reward_label text,
    CONSTRAINT referral_programs_friend_label_len CHECK (((friend_reward_label IS NULL) OR ((length(btrim(friend_reward_label)) >= 2) AND (length(btrim(friend_reward_label)) <= 80)))),
    CONSTRAINT referral_programs_friend_points_nonneg CHECK (((friend_reward_points IS NULL) OR (friend_reward_points >= 0))),
    CONSTRAINT referral_programs_min_spend_cents_check CHECK ((min_spend_cents >= 0)),
    CONSTRAINT referral_programs_reward_cents_check CHECK ((reward_cents >= 0)),
    CONSTRAINT referral_programs_reward_kind_check CHECK ((reward_kind = ANY (ARRAY['points'::text, 'voucher'::text]))),
    CONSTRAINT referral_programs_reward_label_len CHECK (((reward_label IS NULL) OR ((length(btrim(reward_label)) >= 2) AND (length(btrim(reward_label)) <= 80)))),
    CONSTRAINT referral_programs_reward_points_check CHECK ((reward_points >= 0))
);

--
-- Name: COLUMN referral_programs.reward_cents; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.referral_programs.reward_cents IS 'FROZEN at v322. The historical money amount this firm used to pay a referrer in store credit. Store credit left the product at v320 and the referral payout followed at v322; nothing on the payout path reads this column any more. Kept, not dropped, so the old value is recoverable and so the pre-v322 save_referral_program signature keeps working through its CDN window.';

--
-- Name: COLUMN referral_programs.reward_points; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.referral_programs.reward_points IS 'v322 (owner ruling R1/R4): what a qualifying referral pays the referrer, in POINTS, into the firm''s one active accruing programme. Referral no longer pays store credit. reward_cents is the frozen historical money amount and is read by nothing on the payout path.';

--
-- Name: COLUMN referral_programs.reward_kind; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.referral_programs.reward_kind IS 'v322 (owner ruling R4): ''points'' is the only payout built. ''voucher'' (a free item the customer claims at the counter) is DEFERRED; nothing writes it and app.on_sale_recorded pays only ''points'', so a voucher row cannot be paid by accident.';

--
-- Name: COLUMN referral_programs.reward_label; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.referral_programs.reward_label IS 'v420: what the referrer receives when reward_kind = ''voucher'' - the name staff read at the counter and the customer sees. Ignored when reward_kind = ''points''.';

--
-- Name: COLUMN referral_programs.friend_enabled; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.referral_programs.friend_enabled IS 'v421: whether the friend who was introduced is paid as well as the referrer. Default true (owner ruling 2026-08-21). False restores the one-sided payout referrals had until v421.';

--
-- Name: COLUMN referral_programs.friend_reward_points; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.referral_programs.friend_reward_points IS 'v421: points for the friend when reward_kind = ''points''. NULL means the same as the referrer''s reward_points; 0 means the friend is paid nothing even while friend_enabled is on.';

--
-- Name: COLUMN referral_programs.friend_reward_label; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.referral_programs.friend_reward_label IS 'v421: the gift for the friend when reward_kind = ''voucher''. NULL means the same gift the referrer receives.';

