    CONSTRAINT retention_campaigns_attribution_window_days_check CHECK (((attribution_window_days >= 1) AND (attribution_window_days <= 365))),
    CONSTRAINT retention_campaigns_audience_criteria_check CHECK ((jsonb_typeof(audience_criteria) = 'object'::text)),
    CONSTRAINT retention_campaigns_audience_size_check CHECK (((audience_size IS NULL) OR (audience_size >= 0))),
    CONSTRAINT retention_campaigns_budget_cap_cents_check CHECK ((budget_cap_cents >= 0)),
    CONSTRAINT retention_campaigns_expected_cost_cents_check CHECK (((expected_cost_cents IS NULL) OR (expected_cost_cents >= 0))),
    CONSTRAINT retention_campaigns_expected_upside_cents_check CHECK (((expected_upside_cents IS NULL) OR (expected_upside_cents >= 0))),
    CONSTRAINT retention_campaigns_explanation_check CHECK (((explanation IS NULL) OR (char_length(explanation) <= 4000))),
    CONSTRAINT retention_campaigns_holdout_percent_check CHECK (((holdout_percent >= 0) AND (holdout_percent <= 90))),
    CONSTRAINT retention_campaigns_lifecycle_check CHECK ((((status = 'draft'::text) AND (activated_at IS NULL) AND (audience_size IS NULL) AND (completed_at IS NULL) AND (cancelled_at IS NULL)) OR ((status = 'active'::text) AND (activated_at IS NOT NULL) AND (audience_size IS NOT NULL) AND (completed_at IS NULL) AND (cancelled_at IS NULL)) OR ((status = 'completed'::text) AND (activated_at IS NOT NULL) AND (audience_size IS NOT NULL) AND (completed_at IS NOT NULL) AND (cancelled_at IS NULL)) OR ((status = 'cancelled'::text) AND (completed_at IS NULL) AND (cancelled_at IS NOT NULL)))),
    CONSTRAINT retention_campaigns_name_check CHECK (((char_length(btrim(name)) >= 1) AND (char_length(btrim(name)) <= 120))),
    CONSTRAINT retention_campaigns_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'active'::text, 'completed'::text, 'cancelled'::text])))
);

