--
-- Name: sales; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.sales (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    business_id uuid NOT NULL,
    client_id uuid,
    kind text NOT NULL,
    amount_cents integer NOT NULL,
    occurred_at timestamp with time zone DEFAULT now() NOT NULL,
    note text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    appointment_id uuid,
    product_id uuid,
    qty integer,
    counts_as_revenue boolean NOT NULL,
    counts_as_visit boolean NOT NULL,
    earns_points boolean NOT NULL,
    policy_resolved_at timestamp with time zone NOT NULL,
    branch_id uuid,
    staff_id uuid,
    commission_rate_bps integer NOT NULL,
    commission_resolved_at timestamp with time zone NOT NULL,
    idem_key text,
    reversal_of uuid,
    reversal_reason text,
    reversal_actor uuid,
    reversal_idempotency_key text,
    commission_flat_cents integer,
    config_version_id uuid,
    CONSTRAINT sales_amount_cents_check CHECK ((((reversal_of IS NULL) AND (amount_cents >= 0)) OR ((reversal_of IS NOT NULL) AND (amount_cents <= 0)))),
    CONSTRAINT sales_commission_flat_cents_check CHECK (((commission_flat_cents IS NULL) OR (commission_flat_cents >= 0))),
    CONSTRAINT sales_kind_check CHECK ((kind = ANY (ARRAY['service'::text, 'retail'::text, 'membership'::text, 'quick_sale'::text, 'gift_card'::text, 'package'::text, 'bottle_keep'::text]))),
    CONSTRAINT sales_qty_check CHECK (((qty IS NULL) OR (qty > 0))),
    CONSTRAINT sales_reversal_metadata_check CHECK ((((reversal_of IS NULL) AND (reversal_reason IS NULL) AND (reversal_actor IS NULL) AND (reversal_idempotency_key IS NULL)) OR ((reversal_of IS NOT NULL) AND (amount_cents <= 0) AND (appointment_id IS NULL) AND (reversal_actor IS NOT NULL) AND (reversal_idempotency_key IS NOT NULL) AND (length(btrim(COALESCE(reversal_reason, ''::text))) >= 10)))),
    CONSTRAINT sales_reversal_not_self_check CHECK (((reversal_of IS NULL) OR (reversal_of <> id)))
);

--
-- Name: COLUMN sales.counts_as_revenue; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sales.counts_as_revenue IS 'IMMUTABLE SNAPSHOT of sale_policies as resolved when this sale was RECORDED. Historical reporting MUST read this column, never app.sale_policy(). Changed only by public.reclassify_sale_policy() (audited, owner-only).';

--
-- Name: COLUMN sales.counts_as_visit; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sales.counts_as_visit IS 'Immutable snapshot — see counts_as_revenue. NEVER changeable after insert: the loyalty ledgers (reward_grants, referrals, credit_ledger) were written against this value.';

--
-- Name: COLUMN sales.earns_points; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sales.earns_points IS 'Immutable snapshot — see counts_as_revenue. NEVER changeable after insert: points_ledger and points_batches were written against this value.';

--
-- Name: COLUMN sales.policy_resolved_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sales.policy_resolved_at IS 'When the snapshot was taken (insert time). Backfilled rows carry created_at.';

--
-- Name: COLUMN sales.commission_rate_bps; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sales.commission_rate_bps IS 'IMMUTABLE SNAPSHOT of the commission rate in basis points as resolved when this sale was RECORDED, per v11a''s order (services.commission_bps -> staff.commission_service_bps -> 0 for kind=service; staff.commission_product_bps -> 0 otherwise), with the staff.commission_starts_on gate and the no-staff case already FOLDED IN (both yield 0). Payroll MUST read this column, never staff.commission_*_bps. 0 is a REAL RATE meaning "no commission", never "unset". There is deliberately NO supported path to change this after insert — see the header.';

--
-- Name: COLUMN sales.commission_resolved_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sales.commission_resolved_at IS 'When the commission snapshot was taken (insert time). Backfilled rows carry created_at. Mirrors policy_resolved_at (v10.1).';

--
-- Name: COLUMN sales.reversal_of; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sales.reversal_of IS 'v20: points to the ORIGINAL sale this append-only negative row reverses. Full reversal only.';

--
-- Name: COLUMN sales.reversal_reason; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sales.reversal_reason IS 'v20: mandatory human reason captured by public.reverse_sale()/refund_sale().';

--
-- Name: COLUMN sales.reversal_actor; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sales.reversal_actor IS 'v20: auth.uid() that posted the reversal.';

--
-- Name: COLUMN sales.reversal_idempotency_key; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sales.reversal_idempotency_key IS 'v20: business-scoped idempotency key for the reversal RPC.';

--
-- Name: COLUMN sales.commission_flat_cents; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sales.commission_flat_cents IS 'IMMUTABLE SNAPSHOT of the resolved FLAT commission in cents at record time, or NULL if not flat-commission (then commission_rate_bps applies). When NOT NULL this WINS over the rate (0 is a real flat-zero). A reversal sale copies the original sale''s snapshot and the view nets it negative. Reinstated by frenly_v13_flat_commission and formally reconciled with the v20 financial engine by frenly_v22_flat_commission_reconciliation (supersedes the v20 tombstone).';

--
-- Name: sale_balance; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.sale_balance WITH (security_invoker='on') AS
 WITH reversal_totals AS (
         SELECT r.business_id,
            r.reversal_of AS sale_id,
            (COALESCE(sum(r.amount_cents), (0)::bigint))::integer AS reversal_cents
           FROM public.sales r
          WHERE (r.reversal_of IS NOT NULL)
          GROUP BY r.business_id, r.reversal_of
        ), payment_totals AS (
         SELECT s_1.business_id,
            s_1.id AS sale_id,
            (COALESCE(sum(p.amount_cents), (0)::bigint))::integer AS paid_cents
           FROM (public.sales s_1
             LEFT JOIN public.payments p ON (((p.business_id = s_1.business_id) AND ((p.sale_id = s_1.id) OR ((p.sale_id IS NULL) AND (s_1.appointment_id IS NOT NULL) AND (p.appointment_id = s_1.appointment_id))))))
          WHERE (s_1.reversal_of IS NULL)
          GROUP BY s_1.business_id, s_1.id
        ), sv_tender_totals AS (
         SELECT t.business_id,
            t.sale_id,
            (COALESCE(sum(t.reserved_cents), (0)::bigint))::integer AS sv_settled_cents
           FROM public.checkout_sv_tenders t
          WHERE ((t.status = 'consumed'::text) AND (t.sale_id IS NOT NULL) AND (NOT (EXISTS ( SELECT 1
                   FROM public.checkout_sv_tender_reversals rv
                  WHERE ((rv.business_id = t.business_id) AND (rv.tender_id = t.id))))))
          GROUP BY t.business_id, t.sale_id
        )
 SELECT s.id AS sale_id,
    s.business_id,
    s.branch_id,
    s.client_id,
    s.appointment_id,
    s.kind,
    s.counts_as_revenue,
    (s.amount_cents + COALESCE(rt.reversal_cents, 0)) AS amount_cents,
    s.occurred_at,
    COALESCE(pt.paid_cents, 0) AS paid_cents,
    (((s.amount_cents + COALESCE(rt.reversal_cents, 0)) - COALESCE(pt.paid_cents, 0)) - COALESCE(st.sv_settled_cents, 0)) AS balance_cents,
        CASE
            WHEN (((s.amount_cents + COALESCE(rt.reversal_cents, 0)) = 0) AND ((COALESCE(pt.paid_cents, 0) + COALESCE(st.sv_settled_cents, 0)) = 0)) THEN 'paid'::text
            WHEN ((COALESCE(pt.paid_cents, 0) + COALESCE(st.sv_settled_cents, 0)) <= 0) THEN 'unpaid'::text
            WHEN ((COALESCE(pt.paid_cents, 0) + COALESCE(st.sv_settled_cents, 0)) < (s.amount_cents + COALESCE(rt.reversal_cents, 0))) THEN 'partial'::text
            WHEN ((COALESCE(pt.paid_cents, 0) + COALESCE(st.sv_settled_cents, 0)) = (s.amount_cents + COALESCE(rt.reversal_cents, 0))) THEN 'paid'::text
            ELSE 'overpaid'::text
        END AS payment_status,
    s.amount_cents AS gross_amount_cents,
    COALESCE((- rt.reversal_cents), 0) AS reversed_cents,
    COALESCE(st.sv_settled_cents, 0) AS sv_settled_cents
   FROM (((public.sales s
     LEFT JOIN reversal_totals rt ON (((rt.business_id = s.business_id) AND (rt.sale_id = s.id))))
     LEFT JOIN payment_totals pt ON (((pt.business_id = s.business_id) AND (pt.sale_id = s.id))))
     LEFT JOIN sv_tender_totals st ON (((st.business_id = s.business_id) AND (st.sale_id = s.id))))
  WHERE ((s.reversal_of IS NULL) AND app.has_perm(s.business_id, 'view_finance'::text));

--
-- Name: sale_commission; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.sale_commission WITH (security_invoker='on') AS
 SELECT id AS sale_id,
    business_id,
    branch_id,
    staff_id,
    kind,
    occurred_at,
    amount_cents,
    commission_rate_bps AS rate_bps,
        CASE
            WHEN (commission_flat_cents IS NOT NULL) THEN
            CASE
                WHEN ((reversal_of IS NOT NULL) AND (amount_cents < 0)) THEN (- commission_flat_cents)
                ELSE commission_flat_cents
            END
            WHEN ((reversal_of IS NOT NULL) AND (amount_cents < 0)) THEN (- (floor(((((- amount_cents))::numeric * (commission_rate_bps)::numeric) / (10000)::numeric)))::integer)
            ELSE (floor((((amount_cents)::numeric * (commission_rate_bps)::numeric) / (10000)::numeric)))::integer
        END AS commission_cents,
    commission_flat_cents AS flat_cents,
    counts_as_revenue
   FROM public.sales sale
  WHERE (app.has_perm(business_id, 'view_finance'::text) AND app.can_see_branch(business_id, branch_id));

