    CONSTRAINT self_serve_business_onboarding_v130_request_hash_check CHECK ((request_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT self_serve_business_onboarding_v130_selected_cadence_check CHECK ((selected_cadence = ANY (ARRAY['monthly'::text, 'annual'::text]))),
    CONSTRAINT self_serve_business_onboarding_v130_status_check CHECK ((status = ANY (ARRAY['payment_pending'::text, 'active'::text]))),
