    role text NOT NULL,
    full_name text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    email text,
    phone text,
    title text,
    calendar_color text DEFAULT '#7C9CBF'::text NOT NULL,
    active boolean DEFAULT true NOT NULL,
    commission_service_bps integer,
    commission_product_bps integer,
    commission_starts_on date,
    modules text[],
    module_perms jsonb,
    customer_bookable boolean DEFAULT true NOT NULL,
    access_state text DEFAULT 'approved'::text NOT NULL,
    capabilities text[],
    CONSTRAINT staff_access_state_ck CHECK ((access_state = ANY (ARRAY['pending'::text, 'approved'::text, 'rejected'::text]))),
    CONSTRAINT staff_calendar_color_check CHECK ((calendar_color ~ '^#[0-9A-Fa-f]{6}$'::text)),
    CONSTRAINT staff_commission_product_bps_check CHECK (((commission_product_bps >= 0) AND (commission_product_bps <= 10000))),
    CONSTRAINT staff_commission_service_bps_check CHECK (((commission_service_bps >= 0) AND (commission_service_bps <= 10000))),
    CONSTRAINT staff_module_perms_v41_shape_check CHECK (((module_perms IS NULL) OR ((jsonb_typeof(module_perms) = 'object'::text) AND (NOT jsonb_path_exists(module_perms, '$.*?(@ != "r" && @ != "rw")'::jsonpath))))),
    CONSTRAINT staff_role_check CHECK ((role = ANY (ARRAY['owner'::text, 'manager'::text, 'staff'::text, 'frontdesk'::text, 'bookkeeper'::text])))
);

--
-- Name: COLUMN staff.modules; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.staff.modules IS 'NULL = inherit all firm-enabled modules. Non-null = explicit allowlist. Owners bypass.';

--
-- Name: COLUMN staff.module_perms; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.staff.module_perms IS 'Per-module read/write override: NULL inherits legacy modules, r is read-only, rw is read/write.';

--
-- Name: COLUMN staff.customer_bookable; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.staff.customer_bookable IS 'v183: false hides this team member from the customer-facing booking page. Rota-only and
   back-office people should be false; it has no effect while businesses.booking_staff_choice
   is false.';

--
-- Name: COLUMN staff.access_state; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.staff.access_state IS 'Workspace access for a LOGIN. pending = accepted an invite, waiting for the owner; approved = in; rejected = refused. A roster-only teammate (user_id null) is unaffected either way — they have no login to gate.';

--
-- Name: COLUMN staff.capabilities; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.staff.capabilities IS 'v404: per-staff capability grants, NULL or empty = none. Owner and manager do not need a grant for manual_reward_redemption; every other role does.';

