    CONSTRAINT staff_blocked_times_reason_v120 CHECK (((reason IS NULL) OR ((reason = btrim(reason)) AND ((char_length(reason) >= 1) AND (char_length(reason) <= 160))))),
    CONSTRAINT staff_blocked_times_window_v120 CHECK (((ends_at > starts_at) AND (ends_at <= (starts_at + '24:00:00'::interval))))
);

