);

--
-- Name: subscriptions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.subscriptions (
    business_id uuid NOT NULL,
    status text DEFAULT 'trialing'::text NOT NULL,
    currency text DEFAULT 'SGD'::text NOT NULL,
    base_price_cents integer DEFAULT 2500 NOT NULL,
    included_seats integer DEFAULT 1 NOT NULL,
    per_seat_price_cents integer DEFAULT 1000 NOT NULL,
    trial_ends_at timestamp with time zone DEFAULT (now() + '14 days'::interval) NOT NULL,
    current_period_start timestamp with time zone DEFAULT now() NOT NULL,
    current_period_end timestamp with time zone DEFAULT (now() + '1 mon'::interval) NOT NULL,
    note text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    billing_provider text DEFAULT 'manual'::text NOT NULL,
    billing_cadence text,
    cadence_months smallint,
    provider_customer_id text,
    provider_subscription_id text,
    provider_base_item_id text,
    provider_seat_item_id text,
    provider_base_price_id text,
    provider_seat_price_id text,
    provider_seat_quantity integer,
    period_subtotal_cents integer,
    period_tax_cents integer,
    period_total_cents integer,
    tax_behavior text,
    cancel_at_period_end boolean DEFAULT false NOT NULL,
    canceled_at timestamp with time zone,
    next_payment_at timestamp with time zone,
    last_paid_at timestamp with time zone,
    last_paid_invoice_id text,
    payment_status text DEFAULT 'not_collected'::text NOT NULL,
    payment_event_created_at timestamp with time zone,
    payment_event_rank smallint DEFAULT 0 NOT NULL,
    provider_event_created_at timestamp with time zone,
    provider_event_rank smallint DEFAULT 0 NOT NULL,
    plan_code text,
    product_code text,
    commercial_terms_id uuid,
    seat_limit integer,
    provider_covers_base_unit boolean DEFAULT true NOT NULL,
    CONSTRAINT subscriptions_billing_cadence_check CHECK (((billing_cadence IS NULL) OR (billing_cadence = ANY (ARRAY['monthly'::text, 'quarterly'::text, 'half_yearly'::text, 'annual'::text])))),
    CONSTRAINT subscriptions_billing_provider_check CHECK ((billing_provider = ANY (ARRAY['manual'::text, 'stripe'::text]))),
    CONSTRAINT subscriptions_cadence_months_check CHECK (((cadence_months IS NULL) OR (cadence_months = ANY (ARRAY[1, 3, 6, 12])))),
    CONSTRAINT subscriptions_cadence_pair_check CHECK ((((billing_cadence IS NULL) AND (cadence_months IS NULL)) OR ((billing_cadence = 'monthly'::text) AND (cadence_months = 1)) OR ((billing_cadence = 'quarterly'::text) AND (cadence_months = 3)) OR ((billing_cadence = 'half_yearly'::text) AND (cadence_months = 6)) OR ((billing_cadence = 'annual'::text) AND (cadence_months = 12)))),
    CONSTRAINT subscriptions_no_gst_v125_check CHECK ((COALESCE(period_tax_cents, 0) = 0)),
    CONSTRAINT subscriptions_payment_status_check CHECK ((payment_status = ANY (ARRAY['not_collected'::text, 'paid'::text, 'failed'::text, 'action_required'::text, 'past_due'::text]))),
    CONSTRAINT subscriptions_period_amounts_check CHECK (((period_total_cents IS NULL) OR ((period_subtotal_cents IS NOT NULL) AND (period_tax_cents IS NOT NULL) AND (period_total_cents = (period_subtotal_cents + period_tax_cents))))),
    CONSTRAINT subscriptions_period_subtotal_cents_check CHECK (((period_subtotal_cents IS NULL) OR (period_subtotal_cents >= 0))),
    CONSTRAINT subscriptions_period_tax_cents_check CHECK (((period_tax_cents IS NULL) OR (period_tax_cents >= 0))),
    CONSTRAINT subscriptions_period_total_cents_check CHECK (((period_total_cents IS NULL) OR (period_total_cents >= 0))),
    CONSTRAINT subscriptions_prices_sane CHECK (((base_price_cents >= 0) AND (per_seat_price_cents >= 0) AND (included_seats >= 0))),
    CONSTRAINT subscriptions_provider_seat_quantity_check CHECK (((provider_seat_quantity IS NULL) OR (provider_seat_quantity >= 0))),
    CONSTRAINT subscriptions_seat_limit_check CHECK (((seat_limit IS NULL) OR (seat_limit > 0))),
    CONSTRAINT subscriptions_status_check CHECK ((status = ANY (ARRAY['trialing'::text, 'active'::text, 'incomplete'::text, 'incomplete_expired'::text, 'past_due'::text, 'unpaid'::text, 'paused'::text, 'canceled'::text, 'cancelled'::text]))),
    CONSTRAINT subscriptions_tax_behavior_check CHECK ((tax_behavior = ANY (ARRAY['inclusive'::text, 'exclusive'::text, 'unspecified'::text])))
);

--
-- Name: COLUMN subscriptions.provider_covers_base_unit; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.subscriptions.provider_covers_base_unit IS 'true = the Stripe subscription''s base-price quantity includes this firm''s own base unit (the company and its main branch). false = the Stripe subscription exists only to pay for extra branches, because the base plan is collected elsewhere. Read by the billing command edge function to decide the quantity; never a price.';

