    CONSTRAINT sv_plan_guardrails_ordering CHECK ((hard_discount_bps >= warn_discount_bps)),
    CONSTRAINT sv_plan_guardrails_warn_discount_bps_check CHECK (((warn_discount_bps >= 0) AND (warn_discount_bps <= 10000)))
);

