--
-- Name: tier_benefits_v365; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.tier_benefits_v365 (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    business_id uuid NOT NULL,
    tier_id uuid NOT NULL,
    label text NOT NULL,
    limit_count integer,
    limit_period text DEFAULT 'month'::text NOT NULL,
    sort integer DEFAULT 0 NOT NULL,
    active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    deleted_at timestamp with time zone,
    benefit_kind text DEFAULT 'custom'::text NOT NULL,
    discount_percent numeric(5,2),
    product_id uuid,
    item_label text,
    CONSTRAINT tier_benefits_v365_kind_check CHECK ((benefit_kind = ANY (ARRAY['discount_pct'::text, 'free_item'::text, 'custom'::text]))),
    CONSTRAINT tier_benefits_v365_kind_shape_check CHECK ((((benefit_kind = 'discount_pct'::text) AND (discount_percent IS NOT NULL) AND (discount_percent > (0)::numeric) AND (discount_percent <= (100)::numeric) AND (product_id IS NULL) AND (item_label IS NULL)) OR ((benefit_kind = 'free_item'::text) AND (discount_percent IS NULL) AND ((product_id IS NOT NULL) OR ((length(btrim(COALESCE(item_label, ''::text))) >= 1) AND (length(btrim(COALESCE(item_label, ''::text))) <= 120)))) OR ((benefit_kind = 'custom'::text) AND (discount_percent IS NULL) AND (product_id IS NULL) AND (item_label IS NULL)))),
    CONSTRAINT tier_benefits_v365_label_check CHECK (((length(btrim(label)) >= 1) AND (length(btrim(label)) <= 120))),
    CONSTRAINT tier_benefits_v365_limit_count_check CHECK (((limit_count IS NULL) OR ((limit_count >= 1) AND (limit_count <= 10000)))),
    CONSTRAINT tier_benefits_v365_limit_period_check CHECK ((limit_period = ANY (ARRAY['day'::text, 'week'::text, 'month'::text, 'year'::text, 'ever'::text, 'birthday_month'::text]))),
    CONSTRAINT tier_benefits_v365_sort_check CHECK (((sort >= 0) AND (sort <= 10000)))
);

--
-- Name: v_business_billing; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_business_billing WITH (security_invoker='true') AS
 SELECT b.id AS business_id,
    b.name AS business_name,
    COALESCE(sub.status, 'trialing'::text) AS status,
    COALESCE(sub.currency, 'SGD'::text) AS currency,
    COALESCE(sub.base_price_cents, 2500) AS base_price_cents,
    COALESCE(sub.included_seats, 1) AS included_seats,
    COALESCE(sub.per_seat_price_cents, 1000) AS per_seat_price_cents,
    app.billable_seats(b.id) AS billable_seats,
    GREATEST((app.billable_seats(b.id) - COALESCE(sub.included_seats, 1)), 0) AS extra_seats,
    (COALESCE(sub.base_price_cents, 2500) + (GREATEST((app.billable_seats(b.id) - COALESCE(sub.included_seats, 1)), 0) * COALESCE(sub.per_seat_price_cents, 1000))) AS monthly_total_cents,
    sub.trial_ends_at,
    sub.current_period_start,
    sub.current_period_end
   FROM (public.businesses b
     LEFT JOIN public.subscriptions sub ON ((sub.business_id = b.id)))
  WHERE (b.is_synthetic = false);

--
-- Name: VIEW v_business_billing; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.v_business_billing IS 'Seat billing: base $25 SGD/mo covers 1 login; each extra active login +$10/mo. No payment rail wired (Stripe deferred).';

--
-- Name: v_program_rules_all; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_program_rules_all WITH (security_invoker='true') AS
 SELECT business_id,
    source_engine,
    rule_key,
    (md5(('v_program_rules_all:'::text || rule_key)))::uuid AS synthetic_rule_id,
    native_ref,
    config_version_id,
    name,
    active,
    when_event,
    if_conditions,
    then_effects,
    with_params,
    during_schedule,
    using_stacking,
    native_config,
    execution_state
   FROM ( SELECT lp.business_id,
            'points_loyalty'::text AS source_engine,
            ('points_loyalty:'::text || (lp.config_version_id)::text) AS rule_key,
            (lp.config_version_id)::text AS native_ref,
            lp.config_version_id,
            ('Earn - '::text || lp.loyalty_model) AS name,
            lp.active,
            'sale.completed'::text AS when_event,
            jsonb_build_array(jsonb_build_object('field', 'earns_points', 'op', 'eq', 'value', true)) AS if_conditions,
                CASE
                    WHEN ((lp.kind = 'stamps'::text) OR (lp.loyalty_model = 'stamps'::text)) THEN jsonb_build_array(jsonb_build_object('effect_type', 'earn_bonus_stamps', 'per_cents', lp.stamp_per_cents, 'stamp_target', lp.stamp_target))
                    ELSE jsonb_build_array(jsonb_build_object('effect_type', 'earn_bonus_points', 'points_per_dollar', lp.earn_points_per_dollar))
                END AS then_effects,
            jsonb_build_object('redeem_points', lp.redeem_points, 'reward_credit_cents', lp.reward_credit_cents, 'expiry_mode', lp.expiry_mode, 'expiry_days', lp.expiry_days) AS with_params,
            '{}'::jsonb AS during_schedule,
            '{}'::jsonb AS using_stacking,
            to_jsonb(lp.*) AS native_config,
                CASE
                    WHEN lp.active THEN 'live'::text
                    ELSE 'paused'::text
                END AS execution_state
           FROM (public.loyalty_program_versions lp
             JOIN public.businesses b ON (((b.id = lp.business_id) AND (b.active_config_version_id = lp.config_version_id))))
        UNION ALL
         SELECT tv.business_id,
            'points_loyalty'::text AS text,
            ('tier:'::text || (tv.tier_id)::text),
            (tv.tier_id)::text AS tier_id,
            tv.config_version_id,
            ('Tier - '::text || tv.name),
            tv.active,
            'sale.completed'::text AS text,
            jsonb_build_array(jsonb_build_object('field', 'points_earned', 'op', 'gte', 'value', tv.threshold)) AS jsonb_build_array,
            jsonb_build_array(jsonb_build_object('effect_type', 'tier_multiplier', 'multiplier', tv.points_multiplier, 'tier_id', tv.tier_id)) AS jsonb_build_array,
            jsonb_build_object('perk_note', tv.perk_note, 'sort', tv.sort) AS jsonb_build_object,
            '{}'::jsonb AS jsonb,
            '{}'::jsonb AS jsonb,
            to_jsonb(tv.*) AS to_jsonb,
                CASE
                    WHEN tv.active THEN 'live'::text
                    ELSE 'inactive'::text
                END AS text
           FROM (public.loyalty_tier_versions tv
             JOIN public.businesses b ON (((b.id = tv.business_id) AND (b.active_config_version_id = tv.config_version_id))))
        UNION ALL
         SELECT rv.business_id,
            'points_loyalty'::text AS text,
            ('reward:'::text || (rv.reward_id)::text),
            (rv.reward_id)::text AS reward_id,
            rv.config_version_id,
            ('Reward - '::text || rv.customer_name),
            rv.active,
            'points.redeemed'::text AS text,
            jsonb_build_array(jsonb_build_object('field', 'reward_id', 'op', 'eq', 'value', rv.reward_id)) AS jsonb_build_array,
            jsonb_build_array(jsonb_build_object('effect_type',
                CASE
                    WHEN (rv.fulfillment_kind = 'credit'::text) THEN 'grant_credit'::text
                    ELSE 'grant_free_item'::text
                END, 'amount_cents',
                CASE
                    WHEN (rv.fulfillment_kind = 'credit'::text) THEN rv.credit_cents
                    ELSE NULL::integer
                END, 'cost_points', rv.cost_points)) AS jsonb_build_array,
            jsonb_build_object('cost_points', rv.cost_points, 'estimated_cost_cents', rv.estimated_cost_cents, 'usage_limit', rv.usage_limit) AS jsonb_build_object,
            '{}'::jsonb AS jsonb,
            '{}'::jsonb AS jsonb,
            to_jsonb(rv.*) AS to_jsonb,
                CASE
                    WHEN rv.active THEN 'live'::text
                    ELSE 'inactive'::text
                END AS text
           FROM (public.loyalty_reward_versions rv
             JOIN public.businesses b ON (((b.id = rv.business_id) AND (b.active_config_version_id = rv.config_version_id))))
        UNION ALL
         SELECT r.business_id,
            'retention'::text AS text,
            ('retention:'::text || (r.program_id)::text),
            (r.program_id)::text AS program_id,
            r.config_version_id,
            ('Retention - '::text || r.name),
            r.active,
            'sale.completed'::text AS text,
            jsonb_build_array(jsonb_build_object('field', 'counts_as_visit', 'op', 'eq', 'value', true), jsonb_build_object('field', 'visits_in_period', 'op', 'gte', 'value', r.goal_visits)) AS jsonb_build_array,
            jsonb_build_array(jsonb_build_object('effect_type',
                CASE r.fulfillment_kind
                    WHEN 'credit'::text THEN 'grant_credit'::text
                    WHEN 'discount_pct'::text THEN 'apply_discount_pct'::text
                    ELSE 'grant_free_item'::text
                END, 'amount_cents', r.credit_cents, 'discount_pct', r.discount_percent, 'manual_item', r.manual_item)) AS jsonb_build_array,
            jsonb_build_object('goal_visits', r.goal_visits, 'period_days', r.period_days, 'starts_on', r.starts_on) AS jsonb_build_object,
            '{}'::jsonb AS jsonb,
            '{}'::jsonb AS jsonb,
            to_jsonb(r.*) AS to_jsonb,
                CASE
                    WHEN r.active THEN 'live'::text
                    ELSE 'paused'::text
                END AS text
           FROM (public.retention_program_versions r
             JOIN public.businesses b ON (((b.id = r.business_id) AND (b.active_config_version_id = r.config_version_id))))
        UNION ALL
         SELECT bp.business_id,
            'birthday'::text AS text,
            ('birthday:'::text || (bp.program_id)::text),
            (bp.program_id)::text AS program_id,
            bp.config_version_id,
            ('Birthday - '::text || bp.customer_label),
            bp.active,
            'birthday.activated'::text AS text,
            '[]'::jsonb AS jsonb,
            jsonb_build_array(jsonb_build_object('effect_type',
                CASE bp.fulfillment_kind
                    WHEN 'discount_pct'::text THEN 'apply_discount_pct'::text
                    ELSE 'grant_free_item'::text
                END, 'discount_pct', bp.discount_percent, 'manual_item', bp.manual_item)) AS jsonb_build_array,
            jsonb_build_object('window_days_before', bp.window_days_before, 'window_days_after', bp.window_days_after) AS jsonb_build_object,
            '{}'::jsonb AS jsonb,
            '{}'::jsonb AS jsonb,
            to_jsonb(bp.*) AS to_jsonb,
                CASE
                    WHEN bp.active THEN 'live'::text
                    ELSE 'paused'::text
                END AS text
           FROM (public.birthday_program_versions bp
             JOIN public.businesses b ON (((b.id = bp.business_id) AND (b.active_config_version_id = bp.config_version_id))))
        UNION ALL
         SELECT rp.business_id,
            'referral'::text AS text,
            ('referral:'::text || (rp.business_id)::text),
            (rp.business_id)::text AS business_id,
            b.active_config_version_id,
            'Referral program'::text AS text,
            rp.enabled,
            'referral.qualified'::text AS text,
            jsonb_build_array(jsonb_build_object('field', 'min_spend_cents', 'op', 'gte', 'value', COALESCE(rp.min_spend_cents, 0))) AS jsonb_build_array,
            jsonb_build_array(jsonb_build_object('effect_type', 'grant_credit', 'amount_cents', rp.reward_cents)) AS jsonb_build_array,
            jsonb_build_object('min_spend_cents', rp.min_spend_cents, 'reward_cents', rp.reward_cents) AS jsonb_build_object,
            '{}'::jsonb AS jsonb,
            '{}'::jsonb AS jsonb,
            to_jsonb(rp.*) AS to_jsonb,
                CASE
                    WHEN rp.enabled THEN 'live'::text
                    ELSE 'disabled'::text
                END AS text
           FROM (public.referral_programs rp
             JOIN public.businesses b ON ((b.id = rp.business_id)))) v
  WHERE (app.is_salon_owner(business_id) OR app.is_super_admin());

--
-- Name: VIEW v_program_rules_all; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.v_program_rules_all IS 'PS-1A read-only adapter: projects each LIVE engine''s active config into the WHEN/IF/THEN/WITH/DURING/USING studio shape. Zero storage. Rows are 1:1 derivable from native_config (the exact source row). Secure-barrier view (owner/super-admin predicate); does NOT execute anything.';

--
-- Name: v_table_availability; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_table_availability WITH (security_invoker='true') AS
 SELECT table_type.business_id,
    table_type.id AS table_type_id,
    table_type.name,
    table_type.pax,
    table_type.quantity,
    table_type.sort,
    holds.held,
    GREATEST((table_type.quantity - holds.held), 0) AS available
   FROM (public.booking_tables table_type
     CROSS JOIN LATERAL ( SELECT ((( SELECT count(*) AS count
                   FROM public.booking_requests held_request
                  WHERE ((held_request.table_type_id = table_type.id) AND (held_request.status = ANY (ARRAY['new'::text, 'pending'::text])) AND ((held_request.expires_at IS NULL) OR (held_request.expires_at > clock_timestamp())))) + ( SELECT count(*) AS count
                   FROM public.appointments held_appointment
                  WHERE ((held_appointment.table_type_id = table_type.id) AND (held_appointment.status = 'booked'::text)))))::integer AS held) holds)
  WHERE table_type.active;

