    CONSTRAINT waitlist_status_check CHECK ((status = ANY (ARRAY['waiting'::text, 'contacted'::text, 'booked'::text, 'removed'::text])))
);

--
-- Name: welcome_offer_grants_v215; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.welcome_offer_grants_v215 (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    business_id uuid NOT NULL,
    client_id uuid NOT NULL,
    min_spend_cents integer NOT NULL,
    reward_catalog_kind text NOT NULL,
    reward_catalog_id uuid,
    reward_label text NOT NULL,
    status text DEFAULT 'granted'::text NOT NULL,
    granted_at timestamp with time zone DEFAULT now() NOT NULL,
    expires_at timestamp with time zone,
    redeemed_at timestamp with time zone,
    redeemed_sale_id uuid,
    redeemed_by uuid,
    qualifying_sale_id uuid,
    redeem_idempotency_key text,
    CONSTRAINT welcome_offer_grants_v215_kind_check CHECK ((reward_catalog_kind = ANY (ARRAY['service'::text, 'product'::text, 'custom'::text]))),
    CONSTRAINT welcome_offer_grants_v215_min_spend_check CHECK ((min_spend_cents >= 0)),
    CONSTRAINT welcome_offer_grants_v215_redeem_shape CHECK ((((status = 'redeemed'::text) AND (redeemed_at IS NOT NULL) AND (redeemed_sale_id IS NOT NULL)) OR ((status <> 'redeemed'::text) AND (redeemed_at IS NULL) AND (redeemed_sale_id IS NULL)))),
    CONSTRAINT welcome_offer_grants_v215_status_check CHECK ((status = ANY (ARRAY['granted'::text, 'redeemed'::text, 'expired'::text])))
);

--
-- Name: workspace_locale_preferences_v97; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.workspace_locale_preferences_v97 (
    auth_user_id uuid NOT NULL,
    locale text DEFAULT 'en'::text NOT NULL,
    version bigint DEFAULT 1 NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT workspace_locale_preferences_v97_locale_check CHECK ((locale = ANY (ARRAY['en'::text, 'zh-CN'::text, 'ms'::text]))),
    CONSTRAINT workspace_locale_preferences_v97_version_check CHECK ((version > 0))
);

--
-- Name: workspace_owner_invitations; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.workspace_owner_invitations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    business_id uuid NOT NULL,
    prospect_id uuid NOT NULL,
    version integer NOT NULL,
    owner_email text NOT NULL,
    token_hash text NOT NULL,
    token_last_four text NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    issued_by uuid,
    accepted_by uuid,
    accepted_at timestamp with time zone,
    revoked_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT workspace_owner_invitation_status_shape CHECK ((((status = 'pending'::text) AND (accepted_by IS NULL) AND (accepted_at IS NULL) AND (revoked_at IS NULL)) OR ((status = 'accepted'::text) AND (accepted_by IS NOT NULL) AND (accepted_at IS NOT NULL) AND (revoked_at IS NULL)) OR ((status = ANY (ARRAY['revoked'::text, 'expired'::text])) AND (accepted_by IS NULL) AND (accepted_at IS NULL) AND (revoked_at IS NOT NULL)))),
    CONSTRAINT workspace_owner_invitations_owner_email_check CHECK ((POSITION(('@'::text) IN (owner_email)) > 1)),
    CONSTRAINT workspace_owner_invitations_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'accepted'::text, 'revoked'::text, 'expired'::text]))),
    CONSTRAINT workspace_owner_invitations_token_hash_check CHECK ((token_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT workspace_owner_invitations_token_last_four_check CHECK ((length(token_last_four) = 4)),
    CONSTRAINT workspace_owner_invitations_version_check CHECK ((version > 0))
);

