--
-- Name: cash_drawer_session_summary _RETURN; Type: RULE; Schema: public; Owner: -
--

CREATE OR REPLACE VIEW public.cash_drawer_session_summary WITH (security_invoker='on') AS
 SELECT s.id AS session_id,
    s.business_id,
    s.branch_id,
    s.opened_at,
    s.closed_at,
    s.opening_float_cents,
    s.expected_cents,
    s.counted_cents,
    (s.counted_cents - s.expected_cents) AS variance_cents,
    (COALESCE(sum(m.amount_cents) FILTER (WHERE (m.kind = 'sale_cash'::text)), (0)::bigint))::integer AS cash_sales_cents,
    (COALESCE(sum(m.amount_cents) FILTER (WHERE (m.kind = 'pay_in'::text)), (0)::bigint))::integer AS pay_in_cents,
    (COALESCE(sum(m.amount_cents) FILTER (WHERE (m.kind = 'pay_out'::text)), (0)::bigint))::integer AS pay_out_cents,
    (COALESCE(sum(m.amount_cents), (0)::bigint))::integer AS session_net_cents
   FROM (public.cash_drawer_sessions s
     LEFT JOIN public.cash_drawer_movements m ON ((m.session_id = s.id)))
  WHERE app.has_perm(s.business_id, 'view_finance'::text)
  GROUP BY s.id;

